OBSERVATION = {'row_sum': [8, 1, 8, 11, 9], 'col_sum': [14, 4, 13, 3, 10]}
from functools import lru_cache

# Puzzle model:
# Binary grid x[r][c] in {0,1} where 1 means black.
# Row constraint: sum_c (col_weight[c] * x[r][c]) == row_target[r]
# Col constraint: sum_r (row_weight[r] * x[r][c]) == col_target[c]
# In this puzzle, the weights are the 1-based indices printed around the board:
# - Column weights are 1..W left-to-right
# - Row weights are 1..H top-to-bottom
#
# We solve via aggressive constraint propagation on per-row and per-column domains:
# - Precompute all feasible bitmasks for each row (based on weighted sum with col weights).
# - Precompute all feasible bitmasks for each column (based on weighted sum with row weights).
# - Maintain current domains (sets) for each row/col, iteratively prune using arc consistency:
#   a) From row domains derive allowed bits per cell; remove column masks that disagree.
#   b) From column domains derive allowed bits per cell; remove row masks that disagree.
# - Use "hidden single" style deductions (a cell forced if all masks agree).
# - If not solved, branch on the most constrained variable (row/col with smallest domain),
#   trying a candidate mask, then propagate.

def solve(observation):
    row_targets = observation["row_sum"]
    col_targets = observation["col_sum"]
    H = len(row_targets)
    W = len(col_targets)

    row_weights = tuple(range(1, H + 1))
    col_weights = tuple(range(1, W + 1))

    # Precompute all masks by (n, target, weights) using DP to avoid brute force enumeration.
    @lru_cache(None)
    def masks_for_target(n, target, weights):
        # returns tuple of int masks length n meeting sum(weights[i] for i in bits) == target
        # DP on positions with sum; store masks.
        # For n<=10 typical, still fine; but DP avoids 2^n scans.
        dp = {0: [0]}  # sum -> list of masks
        for i in range(n):
            w = weights[i]
            new = {s: lst[:] for s, lst in dp.items()}
            for s, lst in dp.items():
                ns = s + w
                if ns <= target:
                    nlst = new.get(ns)
                    if nlst is None:
                        nlst = []
                        new[ns] = nlst
                    bit = 1 << i
                    for m in lst:
                        nlst.append(m | bit)
            dp = new
        return tuple(dp.get(target, []))

    row_dom_init = [set(masks_for_target(W, row_targets[r], col_weights)) for r in range(H)]
    col_dom_init = [set(masks_for_target(H, col_targets[c], row_weights)) for c in range(W)]

    # Quick unsat check
    if any(len(d) == 0 for d in row_dom_init) or any(len(d) == 0 for d in col_dom_init):
        return "No Solution"

    # Utility: derive allowed bits per cell from a domain of masks.
    def allowed_bits_from_domain(domain, n):
        # returns (must1_mask, must0_mask, can1_mask)
        # must1: bits that are 1 in all masks
        # must0: bits that are 0 in all masks
        # can1: bits that are 1 in at least one mask
        it = iter(domain)
        first = next(it)
        all1 = first
        any1 = first
        for m in it:
            all1 &= m
            any1 |= m
        must1 = all1
        must0 = ((1 << n) - 1) ^ any1
        return must1, must0, any1

    # Propagation (AC-like). Returns (ok, row_domains, col_domains).
    def propagate(row_dom, col_dom):
        Hn, Wn = H, W
        changed = True
        while changed:
            changed = False

            # From row constraints to prune column domains
            row_must1 = [0] * Hn
            row_must0 = [0] * Hn
            row_can1 = [0] * Hn
            for r in range(Hn):
                d = row_dom[r]
                if not d:
                    return False, row_dom, col_dom
                m1, m0, a1 = allowed_bits_from_domain(d, Wn)
                row_must1[r], row_must0[r], row_can1[r] = m1, m0, a1

            # Prune each column mask set by cell-wise consistency with row allowed bits
            for c in range(Wn):
                d = col_dom[c]
                if not d:
                    return False, row_dom, col_dom
                newd = None
                for m in d:
                    okm = True
                    # bit r of column mask indicates black at (r,c)
                    # If row r forces (r,c)=1 then column mask must have bit r=1
                    # If row r forces (r,c)=0 then column mask must have bit r=0
                    for r in range(Hn):
                        bit = (m >> r) & 1
                        if (row_must1[r] >> c) & 1:
                            if bit == 0:
                                okm = False
                                break
                        if (row_must0[r] >> c) & 1:
                            if bit == 1:
                                okm = False
                                break
                    if okm:
                        if newd is None:
                            newd = set()
                        newd.add(m)
                if newd is None:
                    return False, row_dom, col_dom
                if len(newd) != len(d):
                    col_dom[c] = newd
                    changed = True

            # From column constraints to prune row domains
            col_must1 = [0] * Wn
            col_must0 = [0] * Wn
            col_can1 = [0] * Wn
            for c in range(Wn):
                d = col_dom[c]
                if not d:
                    return False, row_dom, col_dom
                m1, m0, a1 = allowed_bits_from_domain(d, Hn)
                col_must1[c], col_must0[c], col_can1[c] = m1, m0, a1

            for r in range(Hn):
                d = row_dom[r]
                if not d:
                    return False, row_dom, col_dom
                newd = None
                for m in d:
                    okm = True
                    for c in range(Wn):
                        bit = (m >> c) & 1
                        if (col_must1[c] >> r) & 1:
                            if bit == 0:
                                okm = False
                                break
                        if (col_must0[c] >> r) & 1:
                            if bit == 1:
                                okm = False
                                break
                    if okm:
                        if newd is None:
                            newd = set()
                        newd.add(m)
                if newd is None:
                    return False, row_dom, col_dom
                if len(newd) != len(d):
                    row_dom[r] = newd
                    changed = True

        return True, row_dom, col_dom

    # Heuristic to choose next branching variable (row or column) with smallest domain > 1.
    def pick_branch(row_dom, col_dom):
        best_is_row = True
        best_idx = -1
        best_size = 10**9
        for r, d in enumerate(row_dom):
            s = len(d)
            if 1 < s < best_size:
                best_size = s
                best_is_row = True
                best_idx = r
        for c, d in enumerate(col_dom):
            s = len(d)
            if 1 < s < best_size:
                best_size = s
                best_is_row = False
                best_idx = c
        return best_is_row, best_idx, best_size

    # Convert final singleton domains to grid
    def domains_to_grid(row_dom):
        grid = [[None for _ in range(W)] for __ in range(H)]
        for r in range(H):
            m = next(iter(row_dom[r]))
            for c in range(W):
                if (m >> c) & 1:
                    grid[r][c] = 'B'
        return grid

    # Depth-first search with propagation
    def dfs(row_dom, col_dom):
        ok, row_dom, col_dom = propagate([set(d) for d in row_dom], [set(d) for d in col_dom])
        if not ok:
            return None

        # Check solved
        if all(len(d) == 1 for d in row_dom) and all(len(d) == 1 for d in col_dom):
            return domains_to_grid(row_dom)

        is_row, idx, _ = pick_branch(row_dom, col_dom)
        if idx < 0:
            return None

        if is_row:
            candidates = list(row_dom[idx])
            # Try candidates in an order that tends to constrain columns: more 1s first
            candidates.sort(key=lambda m: -m.bit_count())
            for m in candidates:
                new_row = [set(d) for d in row_dom]
                new_col = [set(d) for d in col_dom]
                new_row[idx] = {m}
                res = dfs(new_row, new_col)
                if res is not None:
                    return res
        else:
            candidates = list(col_dom[idx])
            candidates.sort(key=lambda m: -m.bit_count())
            for m in candidates:
                new_row = [set(d) for d in row_dom]
                new_col = [set(d) for d in col_dom]
                new_col[idx] = {m}
                res = dfs(new_row, new_col)
                if res is not None:
                    return res
        return None

    solution = dfs(row_dom_init, col_dom_init)
    if solution is None:
        return "No Solution"
    return repr(solution)

