# Solver for weighted black-cell selection puzzle:
# - Grid is RxC with row weights rw[i]=i+1 and column weights cw[j]=j+1 unless extended in observation (not provided).
# - Constraints:
#   For each row i: sum_{j black} cw[j] == row_sum[i]
#   For each col j: sum_{i black} rw[i] == col_sum[j]
#
# Human-like deduction implemented via:
# 1) Domain generation per row/col as subset-sum bitmasks (all feasible patterns).
# 2) Iterative constraint propagation:
#    - Row/col pattern filtering based on fixed cells and remaining targets.
#    - Cell forcing by consensus (must-be-black / must-be-white) across all remaining patterns.
# 3) Informed branching on most constrained line (fewest patterns), with fast incremental updates.
#
# This is not a naive brute force over 2^(R*C); it works on line-pattern domains with heavy pruning.

from typing import List, Tuple, Optional, Dict

def _weights(n: int) -> List[int]:
    return [i + 1 for i in range(n)]

def _gen_patterns_line(weights: List[int], target: int) -> List[int]:
    """Return all bitmask patterns (0..2^n-1) such that sum(weights[k] for k in bits)=target."""
    # DP over weights to build masks; keeps explicit masks but prunes aggressively.
    # For n<=12 typical, list of masks is manageable; for larger, still feasible with pruning.
    n = len(weights)
    dp: Dict[int, List[int]] = {0: [0]}
    for idx, w in enumerate(weights):
        new_dp = {s: masks[:] for s, masks in dp.items()}
        for s, masks in dp.items():
            ns = s + w
            if ns > target:
                continue
            bucket = new_dp.get(ns)
            if bucket is None:
                new_dp[ns] = [m | (1 << idx) for m in masks]
            else:
                bucket.extend(m | (1 << idx) for m in masks)
        dp = new_dp
    return dp.get(target, [])

def _mask_compatible(mask: int, fixed: List[int]) -> bool:
    # fixed: -1 unknown, 0 white, 1 black
    # compatible if for each fixed bit, mask has that bit set accordingly.
    for k, v in enumerate(fixed):
        if v == -1:
            continue
        bit = (mask >> k) & 1
        if bit != v:
            return False
    return True

def _force_from_patterns(patterns: List[int], nbits: int) -> Tuple[int, int]:
    """Return (must1_mask, must0_mask) among patterns."""
    if not patterns:
        return 0, 0
    all1 = (1 << nbits) - 1
    any1 = 0
    for m in patterns:
        any1 |= m
        all1 &= m
    must1 = all1
    must0 = ((1 << nbits) - 1) ^ any1
    return must1, must0

def solve(observation):
    row_targets: List[int] = list(observation["row_sum"])
    col_targets: List[int] = list(observation["col_sum"])
    R, C = len(row_targets), len(col_targets)

    rw = _weights(R)  # row weights for columns' sums
    cw = _weights(C)  # column weights for rows' sums

    # Quick feasibility checks: each target must be achievable by subset sums.
    row_all = sum(cw)
    col_all = sum(rw)
    for t in row_targets:
        if t < 0 or t > row_all:
            return "No Solution"
    for t in col_targets:
        if t < 0 or t > col_all:
            return "No Solution"

    # Precompute all feasible patterns for each row and column.
    row_patterns: List[List[int]] = [_gen_patterns_line(cw, row_targets[i]) for i in range(R)]
    col_patterns: List[List[int]] = [_gen_patterns_line(rw, col_targets[j]) for j in range(C)]

    if any(len(p) == 0 for p in row_patterns) or any(len(p) == 0 for p in col_patterns):
        return "No Solution"

    # Grid state: -1 unknown, 0 white, 1 black
    grid = [[-1] * C for _ in range(R)]

    # Fixed constraints views for rows and cols
    row_fixed = [grid[i][:] for i in range(R)]
    col_fixed = [[grid[i][j] for i in range(R)] for j in range(C)]

    # Working domains (mutable copies)
    rdom = [p[:] for p in row_patterns]
    cdom = [p[:] for p in col_patterns]

    def set_cell(i: int, j: int, val: int, queue: List[Tuple[str, int]]):
        cur = grid[i][j]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        grid[i][j] = val
        row_fixed[i][j] = val
        col_fixed[j][i] = val
        queue.append(("r", i))
        queue.append(("c", j))
        return True

    def filter_domain_line(kind: str, idx: int) -> bool:
        nonlocal rdom, cdom
        if kind == "r":
            fixed = row_fixed[idx]
            dom = rdom[idx]
            nd = [m for m in dom if _mask_compatible(m, fixed)]
            if not nd:
                return False
            rdom[idx] = nd
            return True
        else:
            fixed = col_fixed[idx]
            dom = cdom[idx]
            nd = [m for m in dom if _mask_compatible(m, fixed)]
            if not nd:
                return False
            cdom[idx] = nd
            return True

    def propagate(queue: List[Tuple[str, int]]) -> bool:
        # AC-like propagation between row and col domains via forced bits.
        inq = set(queue)
        while queue:
            kind, idx = queue.pop()
            inq.discard((kind, idx))
            if not filter_domain_line(kind, idx):
                return False

            if kind == "r":
                patterns = rdom[idx]
                must1, must0 = _force_from_patterns(patterns, C)
                for j in range(C):
                    bit = 1 << j
                    if must1 & bit:
                        if not set_cell(idx, j, 1, queue):
                            return False
                    elif must0 & bit:
                        if not set_cell(idx, j, 0, queue):
                            return False
            else:
                patterns = cdom[idx]
                must1, must0 = _force_from_patterns(patterns, R)
                for i in range(R):
                    bit = 1 << i
                    if must1 & bit:
                        if not set_cell(i, idx, 1, queue):
                            return False
                    elif must0 & bit:
                        if not set_cell(i, idx, 0, queue):
                            return False
        return True

    # Initial propagation: all lines
    initq = [("r", i) for i in range(R)] + [("c", j) for j in range(C)]
    if not propagate(initq):
        return "No Solution"

    def solved() -> bool:
        for i in range(R):
            for j in range(C):
                if grid[i][j] == -1:
                    return False
        return True

    def snapshot():
        return (
            [row[:] for row in grid],
            [rf[:] for rf in row_fixed],
            [cf[:] for cf in col_fixed],
            [d[:] for d in rdom],
            [d[:] for d in cdom],
        )

    def restore(snap):
        nonlocal grid, row_fixed, col_fixed, rdom, cdom
        grid, row_fixed, col_fixed, rdom, cdom = snap

    def choose_branch():
        # Pick most constrained line with >1 pattern, then branch by selecting a pattern.
        best = None  # (dom_size, kind, idx)
        for i in range(R):
            s = len(rdom[i])
            if s > 1:
                cand = (s, "r", i)
                if best is None or cand < best:
                    best = cand
        for j in range(C):
            s = len(cdom[j])
            if s > 1:
                cand = (s, "c", j)
                if best is None or cand < best:
                    best = cand
        return best

    def apply_pattern(kind: str, idx: int, mask: int) -> bool:
        q: List[Tuple[str, int]] = []
        if kind == "r":
            # enforce all bits of row idx according to mask
            for j in range(C):
                v = (mask >> j) & 1
                if not set_cell(idx, j, v, q):
                    return False
            rdom[idx] = [mask]
            q.append(("r", idx))
        else:
            for i in range(R):
                v = (mask >> i) & 1
                if not set_cell(i, idx, v, q):
                    return False
            cdom[idx] = [mask]
            q.append(("c", idx))
        return propagate(q)

    def dfs() -> bool:
        if solved():
            return True

        choice = choose_branch()
        if choice is None:
            # domains all singleton but still unknown cells => inconsistency in representation
            return False

        _, kind, idx = choice
        dom = rdom[idx] if kind == "r" else cdom[idx]

        # Heuristic: try patterns that set more currently-unknown cells to forced values first
        def score(mask: int) -> int:
            sc = 0
            if kind == "r":
                for j in range(C):
                    if grid[idx][j] == -1:
                        sc += 1
            else:
                for i in range(R):
                    if grid[i][idx] == -1:
                        sc += 1
            return -sc

        # Stable: iterate in existing order; optionally sort by score
        candidates = dom[:]  # could sort, but dom usually small
        # candidates.sort(key=score)

        for m in candidates:
            snap = snapshot()
            if apply_pattern(kind, idx, m):
                if dfs():
                    return True
            restore(snap)
        return False

    if not dfs():
        return "No Solution"

    # Build required output grid: 'B' for black else None
    out = [[('B' if grid[i][j] == 1 else None) for j in range(C)] for i in range(R)]
    return str(out)

