from functools import lru_cache

# Solver for weighted bipartite sum grid:
# Choose black cells x[r][c] in {0,1} s.t.
#   sum_c x[r][c]*col_w[c] == row_sum[r]
#   sum_r x[r][c]*row_w[r] == col_sum[c]
# where row_w[r] = r+1 and col_w[c] = c+1 by definition in this puzzle family.
#
# Human-like logic mimicked:
#  - Enumerate feasible patterns per row/col (like pencil-marks).
#  - Aggressive constraint propagation via domain filtering (AC-3-ish).
#  - Forced cell deductions from pattern intersections.
#  - Branching only on most constrained line/cell with smallest ambiguity.

def solve(observation):
    row_sum = list(observation["row_sum"])
    col_sum = list(observation["col_sum"])
    R, C = len(row_sum), len(col_sum)
    row_w = tuple(range(1, R + 1))
    col_w = tuple(range(1, C + 1))

    # Quick infeasibility bounds
    if any(s < 0 or s > sum(col_w) for s in row_sum):
        return "No Solution"
    if any(s < 0 or s > sum(row_w) for s in col_sum):
        return "No Solution"

    # Bit representation per line:
    # - Row pattern: bitmask over columns (C bits), sum(bit*cw) = row_sum[r]
    # - Col pattern: bitmask over rows (R bits), sum(bit*rw) = col_sum[c]
    @lru_cache(None)
    def patterns_for_sum(weights, target):
        # Generate all subsets (bitmasks) of len(weights) with weighted sum == target.
        # Uses meet-in-the-middle for speed (works well up to ~20).
        n = len(weights)
        half = n // 2
        w1 = weights[:half]
        w2 = weights[half:]

        sums1 = {}
        for m in range(1 << half):
            s = 0
            mm = m
            i = 0
            while mm:
                lb = mm & -mm
                j = (lb.bit_length() - 1)
                s += w1[j]
                mm ^= lb
                i += 1
            sums1.setdefault(s, []).append(m)

        res = []
        for m2 in range(1 << (n - half)):
            s2 = 0
            mm = m2
            while mm:
                lb = mm & -mm
                j = (lb.bit_length() - 1)
                s2 += w2[j]
                mm ^= lb
            need = target - s2
            if need in sums1:
                base = m2 << half
                for m1 in sums1[need]:
                    res.append(base | m1)
        return tuple(res)

    row_patterns = [list(patterns_for_sum(col_w, row_sum[r])) for r in range(R)]
    col_patterns = [list(patterns_for_sum(row_w, col_sum[c])) for c in range(C)]

    if any(len(p) == 0 for p in row_patterns) or any(len(p) == 0 for p in col_patterns):
        return "No Solution"

    # Cell assignment state: -1 unknown, 0 white, 1 black
    grid = [[-1] * C for _ in range(R)]

    def filter_line_patterns_by_grid(is_row, idx, pats):
        # Remove patterns inconsistent with current fixed cells.
        if is_row:
            # idx is row, pattern bits are columns
            newp = []
            row = grid[idx]
            for m in pats:
                ok = True
                for c in range(C):
                    v = row[c]
                    if v != -1:
                        bit = (m >> c) & 1
                        if bit != v:
                            ok = False
                            break
                if ok:
                    newp.append(m)
            return newp
        else:
            # idx is col, pattern bits are rows
            newp = []
            for m in pats:
                ok = True
                for r in range(R):
                    v = grid[r][idx]
                    if v != -1:
                        bit = (m >> r) & 1
                        if bit != v:
                            ok = False
                            break
                if ok:
                    newp.append(m)
            return newp

    def implied_cells_from_patterns(is_row, idx, pats):
        # For a line's remaining patterns, determine cells that are forced:
        # If all patterns have bit=1 => forced black; if all have bit=0 => forced white.
        forced = []
        if not pats:
            return forced
        if is_row:
            # columns positions
            all_ones = (1 << C) - 1
            all_zeros = 0
            # Compute intersection of ones, intersection of zeros (via OR)
            ones_and = all_ones
            ones_or = 0
            for m in pats:
                ones_and &= m
                ones_or |= m
            # forced 1 are those in ones_and; forced 0 are those not in ones_or
            forced1 = ones_and
            forced0 = (~ones_or) & all_ones
            for c in range(C):
                if (forced1 >> c) & 1:
                    forced.append((idx, c, 1))
                elif (forced0 >> c) & 1:
                    forced.append((idx, c, 0))
        else:
            all_ones = (1 << R) - 1
            ones_and = all_ones
            ones_or = 0
            for m in pats:
                ones_and &= m
                ones_or |= m
            forced1 = ones_and
            forced0 = (~ones_or) & all_ones
            for r in range(R):
                if (forced1 >> r) & 1:
                    forced.append((r, idx, 1))
                elif (forced0 >> r) & 1:
                    forced.append((r, idx, 0))
        return forced

    def propagate(row_pats, col_pats):
        # Returns (ok, row_pats, col_pats). Modifies grid in-place with forced assignments.
        # Uses a queue of lines to recheck when something changes.
        from collections import deque
        q = deque()
        inq_r = [True] * R
        inq_c = [True] * C
        for r in range(R):
            q.append(("r", r))
        for c in range(C):
            q.append(("c", c))

        changed = True
        while q:
            typ, i = q.popleft()
            if typ == "r":
                inq_r[i] = False
                newp = filter_line_patterns_by_grid(True, i, row_pats[i])
                if len(newp) == 0:
                    return False, row_pats, col_pats
                if len(newp) != len(row_pats[i]):
                    row_pats[i] = newp
                forced = implied_cells_from_patterns(True, i, row_pats[i])
                for r, c, v in forced:
                    cur = grid[r][c]
                    if cur == -1:
                        grid[r][c] = v
                        # any assignment affects both lines
                        if not inq_r[r]:
                            q.append(("r", r)); inq_r[r] = True
                        if not inq_c[c]:
                            q.append(("c", c)); inq_c[c] = True
                    elif cur != v:
                        return False, row_pats, col_pats
            else:
                inq_c[i] = False
                newp = filter_line_patterns_by_grid(False, i, col_pats[i])
                if len(newp) == 0:
                    return False, row_pats, col_pats
                if len(newp) != len(col_pats[i]):
                    col_pats[i] = newp
                forced = implied_cells_from_patterns(False, i, col_pats[i])
                for r, c, v in forced:
                    cur = grid[r][c]
                    if cur == -1:
                        grid[r][c] = v
                        if not inq_r[r]:
                            q.append(("r", r)); inq_r[r] = True
                        if not inq_c[c]:
                            q.append(("c", c)); inq_c[c] = True
                    elif cur != v:
                        return False, row_pats, col_pats
        return True, row_pats, col_pats

    def snapshot():
        return [row[:] for row in grid]

    def restore(snap):
        for r in range(R):
            grid[r][:] = snap[r]

    def is_solved():
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    return False
        return True

    def select_branch(row_pats, col_pats):
        # Prefer line with smallest domain >1, else a cell with max constraint.
        best = None  # (domain_size, type, idx)
        for r in range(R):
            d = len(row_pats[r])
            if 1 < d and (best is None or d < best[0]):
                best = (d, "r", r)
        for c in range(C):
            d = len(col_pats[c])
            if 1 < d and (best is None or d < best[0]):
                best = (d, "c", c)
        if best is not None:
            return best[1], best[2], None

        # Otherwise pick an unknown cell (should not happen unless no line has >1 but grid not full)
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    return "cell", (r, c), None
        return None, None, None

    def dfs(row_pats, col_pats):
        ok, row_pats, col_pats = propagate(row_pats, col_pats)
        if not ok:
            return False
        if is_solved():
            return True

        typ, idx, _ = select_branch(row_pats, col_pats)
        snap = snapshot()

        if typ == "r":
            r = idx
            # Try patterns in an order that tends to force more: more bits first (heuristic)
            candidates = sorted(row_pats[r], key=lambda m: -m.bit_count())
            for m in candidates:
                restore(snap)
                rp2 = [lst[:] for lst in row_pats]
                cp2 = [lst[:] for lst in col_pats]
                rp2[r] = [m]
                # Apply immediate row cell assignments from the chosen pattern (fast)
                for c in range(C):
                    v = (m >> c) & 1
                    cur = grid[r][c]
                    if cur == -1:
                        grid[r][c] = v
                    elif cur != v:
                        break
                else:
                    if dfs(rp2, cp2):
                        return True
            restore(snap)
            return False

        if typ == "c":
            c = idx
            candidates = sorted(col_pats[c], key=lambda m: -m.bit_count())
            for m in candidates:
                restore(snap)
                rp2 = [lst[:] for lst in row_pats]
                cp2 = [lst[:] for lst in col_pats]
                cp2[c] = [m]
                for r in range(R):
                    v = (m >> r) & 1
                    cur = grid[r][c]
                    if cur == -1:
                        grid[r][c] = v
                    elif cur != v:
                        break
                else:
                    if dfs(rp2, cp2):
                        return True
            restore(snap)
            return False

        # Fallback branch on a cell
        (r, c) = idx
        for v in (0, 1):
            restore(snap)
            grid[r][c] = v
            if dfs([lst[:] for lst in row_pats], [lst[:] for lst in col_pats]):
                return True
        restore(snap)
        return False

    # Initialize with propagation
    if not dfs([p[:] for p in row_patterns], [p[:] for p in col_patterns]):
        return "No Solution"

    # Build answer grid with 'B' and None
    out = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if grid[r][c] == 1 else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [9, 28, 11, 6, 16, 19, 13, 23], 'col_sum': [26, 2, 14, 9, 13, 9, 28, 21]}
from functools import lru_cache

# Puzzle:
# Choose black cells x[r][c] in {0,1}
# Row constraint: sum_c (col_weight[c] * x[r][c]) = row_sum[r]
# Col constraint: sum_r (row_weight[r] * x[r][c]) = col_sum[c]
# where row_weight[r] = r+1, col_weight[c] = c+1.

def solve(observation):
    row_sum = list(observation["row_sum"])
    col_sum = list(observation["col_sum"])
    R, C = len(row_sum), len(col_sum)
    row_w = [i + 1 for i in range(R)]
    col_w = [j + 1 for j in range(C)]

    # Precompute all feasible subsets for each row and each column
    # Row pattern is a bitmask over columns.
    @lru_cache(None)
    def row_patterns_for_sum(target):
        pats = []
        # Meet-in-the-middle for speed on wider boards; fallback to DP enumeration for small.
        # Here C typically small (<=15-ish). We'll do DP with pruning.
        def dfs(j, acc, mask):
            if acc > target:
                return
            if j == C:
                if acc == target:
                    pats.append(mask)
                return
            # Option 0
            dfs(j + 1, acc, mask)
            # Option 1
            w = col_w[j]
            if acc + w <= target:
                dfs(j + 1, acc + w, mask | (1 << j))
        dfs(0, 0, 0)
        return tuple(pats)

    @lru_cache(None)
    def col_patterns_for_sum(target):
        pats = []
        def dfs(i, acc, mask):
            if acc > target:
                return
            if i == R:
                if acc == target:
                    pats.append(mask)
                return
            # 0
            dfs(i + 1, acc, mask)
            # 1
            w = row_w[i]
            if acc + w <= target:
                dfs(i + 1, acc + w, mask | (1 << i))
        dfs(0, 0, 0)
        return tuple(pats)

    row_pats = []
    for rs in row_sum:
        pats = row_patterns_for_sum(rs)
        if not pats:
            return "No Solution"
        row_pats.append(list(pats))

    col_pats = []
    for cs in col_sum:
        pats = col_patterns_for_sum(cs)
        if not pats:
            return "No Solution"
        col_pats.append(list(pats))

    # Domains are lists of masks. We'll do human-like propagation:
    # - Cell forced by row domain (all patterns agree) or column domain.
    # - Filter domains to match forced cell decisions.
    # - Also perform bounds/compatibility checks via allowed bits per position.

    # State representation:
    # row_dom[r] list of masks
    # col_dom[c] list of masks
    # grid decisions: for each cell, -1 unknown, 0 white, 1 black
    # We'll avoid storing full grid by deriving forced bits from domains repeatedly.

    def forced_bits_from_domain(dom, length):
        # returns (must1_mask, must0_mask) over positions [0..length-1]
        # must1: bits set in all patterns, must0: bits clear in all patterns
        all1 = (1 << length) - 1
        any1 = 0
        for m in dom:
            all1 &= m
            any1 |= m
        must1 = all1
        must0 = ((1 << length) - 1) ^ any1
        return must1, must0

    def filter_row_domain_by_cell(row_dom_r, c, val):
        bit = 1 << c
        if val == 1:
            return [m for m in row_dom_r if (m & bit)]
        else:
            return [m for m in row_dom_r if not (m & bit)]

    def filter_col_domain_by_cell(col_dom_c, r, val):
        bit = 1 << r
        if val == 1:
            return [m for m in col_dom_c if (m & bit)]
        else:
            return [m for m in col_dom_c if not (m & bit)]

    def propagate(row_dom, col_dom):
        # Repeatedly apply forced cell deductions and domain filtering until fixed point.
        changed = True
        while changed:
            changed = False

            # Forced by rows -> filter columns
            for r in range(R):
                dom = row_dom[r]
                if not dom:
                    return None
                must1, must0 = forced_bits_from_domain(dom, C)
                if must1 or must0:
                    for c in range(C):
                        bit = 1 << c
                        if must1 & bit:
                            new_cd = filter_col_domain_by_cell(col_dom[c], r, 1)
                            if len(new_cd) != len(col_dom[c]):
                                col_dom[c] = new_cd
                                if not new_cd:
                                    return None
                                changed = True
                        elif must0 & bit:
                            new_cd = filter_col_domain_by_cell(col_dom[c], r, 0)
                            if len(new_cd) != len(col_dom[c]):
                                col_dom[c] = new_cd
                                if not new_cd:
                                    return None
                                changed = True

            # Forced by cols -> filter rows
            for c in range(C):
                dom = col_dom[c]
                if not dom:
                    return None
                must1, must0 = forced_bits_from_domain(dom, R)
                if must1 or must0:
                    for r in range(R):
                        bit = 1 << r
                        if must1 & bit:
                            new_rd = filter_row_domain_by_cell(row_dom[r], c, 1)
                            if len(new_rd) != len(row_dom[r]):
                                row_dom[r] = new_rd
                                if not new_rd:
                                    return None
                                changed = True
                        elif must0 & bit:
                            new_rd = filter_row_domain_by_cell(row_dom[r], c, 0)
                            if len(new_rd) != len(row_dom[r]):
                                row_dom[r] = new_rd
                                if not new_rd:
                                    return None
                                changed = True

            # Additional consistency pruning via per-cell possibility intersections:
            # For each cell, if row says it can only be 0/1 given its domain, enforce in column, and vice versa.
            # Already covered by must bits; but we can do stronger: remove patterns that require impossible in counterpart.
            # We'll compute possible values per cell from domains quickly.
            row_poss1 = [0] * R  # bitmask over columns where cell can be 1 in some row pattern
            row_poss0 = [0] * R  # bitmask over columns where cell can be 0 in some row pattern
            for r in range(R):
                any1 = 0
                any0 = 0
                for m in row_dom[r]:
                    any1 |= m
                    any0 |= (~m) & ((1 << C) - 1)
                row_poss1[r] = any1
                row_poss0[r] = any0

            col_poss1 = [0] * C  # bitmask over rows where cell can be 1 in some col pattern
            col_poss0 = [0] * C
            for c in range(C):
                any1 = 0
                any0 = 0
                for m in col_dom[c]:
                    any1 |= m
                    any0 |= (~m) & ((1 << R) - 1)
                col_poss1[c] = any1
                col_poss0[c] = any0

            # Enforce incompatibilities:
            for r in range(R):
                for c in range(C):
                    rb = 1 << c
                    cb = 1 << r
                    # If row cannot be 1 here, column must not force 1 patterns (filter col patterns with bit=1)
                    if not (row_poss1[r] & rb):
                        new_cd = [m for m in col_dom[c] if not (m & cb)]
                        if len(new_cd) != len(col_dom[c]):
                            col_dom[c] = new_cd
                            if not new_cd:
                                return None
                            changed = True
                    # If row cannot be 0 here, column must have bit=1
                    if not (row_poss0[r] & rb):
                        new_cd = [m for m in col_dom[c] if (m & cb)]
                        if len(new_cd) != len(col_dom[c]):
                            col_dom[c] = new_cd
                            if not new_cd:
                                return None
                            changed = True
                    # Symmetric: if column cannot be 1 -> row must be 0
                    if not (col_poss1[c] & cb):
                        new_rd = [m for m in row_dom[r] if not (m & rb)]
                        if len(new_rd) != len(row_dom[r]):
                            row_dom[r] = new_rd
                            if not new_rd:
                                return None
                            changed = True
                    # If column cannot be 0 -> row must be 1
                    if not (col_poss0[c] & cb):
                        new_rd = [m for m in row_dom[r] if (m & rb)]
                        if len(new_rd) != len(row_dom[r]):
                            row_dom[r] = new_rd
                            if not new_rd:
                                return None
                            changed = True

        return row_dom, col_dom

    def is_solved(row_dom, col_dom):
        return all(len(d) == 1 for d in row_dom) and all(len(d) == 1 for d in col_dom)

    def choose_branch_var(row_dom, col_dom):
        # Human-like: pick the most constrained line (row or column) with smallest domain >1.
        best = None
        best_is_row = True
        best_idx = -1
        best_size = 10**9
        for r, d in enumerate(row_dom):
            s = len(d)
            if 1 < s < best_size:
                best_size = s
                best = d
                best_is_row = True
                best_idx = r
        for c, d in enumerate(col_dom):
            s = len(d)
            if 1 < s < best_size:
                best_size = s
                best = d
                best_is_row = False
                best_idx = c
        return best_is_row, best_idx

    def deep_copy_domains(row_dom, col_dom):
        return [list(d) for d in row_dom], [list(d) for d in col_dom]

    def dfs(row_dom, col_dom):
        propagated = propagate(row_dom, col_dom)
        if propagated is None:
            return None
        row_dom, col_dom = propagated
        if is_solved(row_dom, col_dom):
            return row_dom, col_dom

        is_row, idx = choose_branch_var(row_dom, col_dom)
        if idx < 0:
            return None

        if is_row:
            # Try each remaining row pattern, but order by how constraining it is on columns (rarer bits first).
            patterns = row_dom[idx]
            # Score pattern by product of column domain reductions estimate
            def score(p):
                sc = 0
                for c in range(C):
                    bit = 1 << c
                    v = 1 if (p & bit) else 0
                    # fewer compatible patterns -> higher score
                    cnt = 0
                    cb = 1 << idx
                    for m in col_dom[c]:
                        if v == 1:
                            if m & cb:
                                cnt += 1
                        else:
                            if not (m & cb):
                                cnt += 1
                    sc += cnt
                return sc
            patterns = sorted(patterns, key=score)
            for p in patterns:
                rd2, cd2 = deep_copy_domains(row_dom, col_dom)
                rd2[idx] = [p]
                res = dfs(rd2, cd2)
                if res is not None:
                    return res
        else:
            patterns = col_dom[idx]
            def score(p):
                sc = 0
                for r in range(R):
                    bit = 1 << r
                    v = 1 if (p & bit) else 0
                    cnt = 0
                    rb = 1 << idx
                    for m in row_dom[r]:
                        if v == 1:
                            if m & rb:
                                cnt += 1
                        else:
                            if not (m & rb):
                                cnt += 1
                    sc += cnt
                return sc
            patterns = sorted(patterns, key=score)
            for p in patterns:
                rd2, cd2 = deep_copy_domains(row_dom, col_dom)
                cd2[idx] = [p]
                res = dfs(rd2, cd2)
                if res is not None:
                    return res

        return None

    res = dfs([list(d) for d in row_pats], [list(d) for d in col_pats])
    if res is None:
        return "No Solution"
    row_dom, col_dom = res

    # Build final grid from row masks (unique each row)
    grid = []
    for r in range(R):
        m = row_dom[r][0]
        row = []
        for c in range(C):
            row.append('B' if (m >> c) & 1 else None)
        grid.append(row)
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 2, 2, 3], [0, 0, 1, 2, 2, 3], [0, 4, 4, 5, 2, 3], [6, 6, 4, 5, 5, 3], [6, 7, 7, 8, 8, 8], [9, 9, 7, 8, 10, 10]], 'row_water_counts': [1, 1, 4, 2, 4, 2], 'col_water_counts': [3, 5, 2, 2, 1, 1]}
from collections import defaultdict, deque

# Solver for "Regions with water level + row/col counts":
# Each region must be either empty (level = 0) or filled up to a consistent water level:
# For each region r, choose k in [0..height_r], and mark exactly the bottom k cells (by row) in that region as water.
# Row/col clues are exact totals.

def solve(observation):
    region = observation["region"]
    R = observation["row_water_counts"]
    C = observation["col_water_counts"]
    H = len(region)
    W = len(region[0]) if H else 0
    if len(R) != H or len(C) != W:
        return "No Solution"

    # Build region cells grouped by region id and sorted by row (top->bottom).
    reg_cells = defaultdict(list)
    for r in range(H):
        for c in range(W):
            reg_cells[region[r][c]].append((r, c))
    reg_ids = sorted(reg_cells.keys())

    # For each region, build "layers" by distinct row value; a level k fills bottom k layers (not cells count),
    # but rule says "if a cell is water, all cells of that region below it are also water".
    # This implies within a region, water status is monotone with respect to row:
    # all cells at row >= threshold become water. Equivalent to choosing a cutoff row.
    # We'll model by selecting number of filled layers (unique rows) from bottom.
    reg_layers = {}
    reg_layer_cells = {}
    for rid in reg_ids:
        cells = reg_cells[rid]
        rows = sorted({r for r, _ in cells})
        layers = rows[:]  # ascending
        reg_layers[rid] = layers
        # map row->cells in that layer
        layer_map = defaultdict(list)
        for r, c in cells:
            layer_map[r].append((r, c))
        reg_layer_cells[rid] = {rr: layer_map[rr] for rr in layers}

    # Precompute for each region and each possible filled layer-count k:
    # contributions to each row and col (sparse dicts).
    reg_options = {}  # rid -> list of option dicts: {"k":k, "row":{i:cnt}, "col":{j:cnt}}
    for rid in reg_ids:
        layers = reg_layers[rid]
        m = len(layers)
        opts = []
        # k = number of bottom layers filled (0..m)
        for k in range(m + 1):
            row_cnt = defaultdict(int)
            col_cnt = defaultdict(int)
            if k > 0:
                filled_rows = layers[m - k :]  # bottom k layers
                for rr in filled_rows:
                    for r, c in reg_layer_cells[rid][rr]:
                        row_cnt[r] += 1
                        col_cnt[c] += 1
            opts.append({"k": k, "row": dict(row_cnt), "col": dict(col_cnt)})
        reg_options[rid] = opts

    # Helper: compute min/max possible additional contributions from unassigned regions for each row/col
    # given current domains.
    def compute_bounds(unassigned, domains):
        row_min = [0] * H
        row_max = [0] * H
        col_min = [0] * W
        col_max = [0] * W
        for rid in unassigned:
            dom = domains[rid]
            # For each row/col, take min/max over options in dom
            # Sparse: consider only rows/cols that appear in any option of this region.
            # We'll gather per region possible counts per row/col quickly by scanning options in dom.
            # Region sizes are small; this is fine.
            # Build local dicts row->(min,max), col->(min,max)
            rmins = {}
            rmaxs = {}
            cmins = {}
            cmaxs = {}
            for oi in dom:
                opt = reg_options[rid][oi]
                for r, v in opt["row"].items():
                    if r in rmins:
                        if v < rmins[r]:
                            rmins[r] = v
                        if v > rmaxs[r]:
                            rmaxs[r] = v
                    else:
                        rmins[r] = v
                        rmaxs[r] = v
                for c, v in opt["col"].items():
                    if c in cmins:
                        if v < cmins[c]:
                            cmins[c] = v
                        if v > cmaxs[c]:
                            cmaxs[c] = v
                    else:
                        cmins[c] = v
                        cmaxs[c] = v
            # For rows/cols not present in any option, min=max=0.
            for r, mn in rmins.items():
                row_min[r] += mn
                row_max[r] += rmaxs[r]
            for c, mn in cmins.items():
                col_min[c] += mn
                col_max[c] += cmaxs[c]
        return row_min, row_max, col_min, col_max

    # Constraint propagation: domain filtering by row/col feasibility (bounds) and local pruning.
    def propagate(assign, domains, row_sum, col_sum):
        # assign: dict rid -> option index
        # domains: dict rid -> set of option indices (for unassigned too)
        # row_sum/col_sum: current contributed totals from assigned regions
        changed = True
        unassigned = [rid for rid in reg_ids if rid not in assign]
        while changed:
            changed = False
            unassigned = [rid for rid in reg_ids if rid not in assign]
            # Quick global feasibility check with bounds
            row_min, row_max, col_min, col_max = compute_bounds(unassigned, domains)
            for i in range(H):
                lo = row_sum[i] + row_min[i]
                hi = row_sum[i] + row_max[i]
                if lo > R[i] or hi < R[i]:
                    return False
            for j in range(W):
                lo = col_sum[j] + col_min[j]
                hi = col_sum[j] + col_max[j]
                if lo > C[j] or hi < C[j]:
                    return False

            # Filter each unassigned region domain using per-option bounds reasoning
            for rid in unassigned:
                dom = domains[rid]
                if len(dom) == 1:
                    continue

                # Compute bounds from other unassigned regions (excluding rid)
                others = [x for x in unassigned if x != rid]
                orow_min, orow_max, ocol_min, ocol_max = compute_bounds(others, domains)

                to_remove = []
                for oi in dom:
                    opt = reg_options[rid][oi]
                    # For each row/col, check if choosing this option can still reach exact R/C given others.
                    ok = True
                    # Check all rows touched by this option or potentially by others
                    # We do full rows/cols for simplicity; small sizes.
                    for i in range(H):
                        v = opt["row"].get(i, 0)
                        lo = row_sum[i] + v + orow_min[i]
                        hi = row_sum[i] + v + orow_max[i]
                        if lo > R[i] or hi < R[i]:
                            ok = False
                            break
                    if ok:
                        for j in range(W):
                            v = opt["col"].get(j, 0)
                            lo = col_sum[j] + v + ocol_min[j]
                            hi = col_sum[j] + v + ocol_max[j]
                            if lo > C[j] or hi < C[j]:
                                ok = False
                                break
                    if not ok:
                        to_remove.append(oi)

                if to_remove:
                    for oi in to_remove:
                        dom.discard(oi)
                    if not dom:
                        return False
                    changed = True

                # If domain becomes singleton, assign it immediately (forced move)
                if rid not in assign and len(dom) == 1:
                    oi = next(iter(dom))
                    assign[rid] = oi
                    # update sums
                    opt = reg_options[rid][oi]
                    for i, v in opt["row"].items():
                        row_sum[i] += v
                    for j, v in opt["col"].items():
                        col_sum[j] += v
                    changed = True

        return True

    # Initialize domains for each region: all options.
    domains = {rid: set(range(len(reg_options[rid]))) for rid in reg_ids}
    assign = {}
    row_sum = [0] * H
    col_sum = [0] * W

    if not propagate(assign, domains, row_sum, col_sum):
        return "No Solution"

    # Search with MRV + fail-first on most constrained by row/col impact.
    def pick_region(assign, domains):
        best = None
        best_size = 10**9
        best_span = -1
        for rid in reg_ids:
            if rid in assign:
                continue
            dsz = len(domains[rid])
            if dsz < best_size:
                best = rid
                best_size = dsz
                # span heuristic: max cells in region (approx impact)
                span = len(reg_cells[rid])
                best_span = span
            elif dsz == best_size:
                span = len(reg_cells[rid])
                if span > best_span:
                    best = rid
                    best_span = span
        return best

    def dfs(assign, domains, row_sum, col_sum):
        # Check completion
        if len(assign) == len(reg_ids):
            if row_sum == R and col_sum == C:
                return assign
            return None

        rid = pick_region(assign, domains)
        dom_list = list(domains[rid])

        # Value ordering: try options that best match remaining needs (greedy)
        rem_row = [R[i] - row_sum[i] for i in range(H)]
        rem_col = [C[j] - col_sum[j] for j in range(W)]

        def score(oi):
            opt = reg_options[rid][oi]
            s = 0
            for i, v in opt["row"].items():
                s += abs(rem_row[i] - v)
            for j, v in opt["col"].items():
                s += abs(rem_col[j] - v)
            return s

        dom_list.sort(key=score)

        for oi in dom_list:
            # clone state
            n_assign = dict(assign)
            n_domains = {k: (set(v) if k != rid else {oi}) for k, v in domains.items()}
            n_row_sum = row_sum[:]
            n_col_sum = col_sum[:]

            n_assign[rid] = oi
            opt = reg_options[rid][oi]
            for i, v in opt["row"].items():
                n_row_sum[i] += v
                if n_row_sum[i] > R[i]:
                    break
            else:
                for j, v in opt["col"].items():
                    n_col_sum[j] += v
                    if n_col_sum[j] > C[j]:
                        break
                else:
                    if propagate(n_assign, n_domains, n_row_sum, n_col_sum):
                        res = dfs(n_assign, n_domains, n_row_sum, n_col_sum)
                        if res is not None:
                            return res
            # else prune
        return None

    sol = dfs(assign, domains, row_sum, col_sum)
    if sol is None:
        return "No Solution"

    # Build output grid: 'W' for water, None otherwise.
    out = [[None for _ in range(W)] for _ in range(H)]
    for rid, oi in sol.items():
        opt = reg_options[rid][oi]
        # Mark water cells in filled layers
        k = opt["k"]
        layers = reg_layers[rid]
        m = len(layers)
        if k == 0:
            continue
        filled_rows = set(layers[m - k :])
        for r, c in reg_cells[rid]:
            if r in filled_rows:
                out[r][c] = 'W'
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [1, 22, 12, 12, 27, 11, 34, 16, 27], 'col_sum': [43, 27, 35, 10, 10, 26, 14, 39, 9]}
# Solver for weighted black-cell grid puzzle (a.k.a. "Kakurasu"-like with given row/col target sums).
# Model:
# - Grid size: R x C (R=len(row_sum), C=len(col_sum))
# - Each cell (r,c) is either black(1) or white(0)
# - Row constraint: sum_{c black} (c+1) == row_sum[r]
# - Col constraint: sum_{r black} (r+1) == col_sum[c]
#
# Approach:
# - Precompute all feasible patterns for each row and each column (bitmasks) satisfying the weighted sum.
# - Use aggressive constraint propagation via domain filtering:
#     * Arc consistency between row domains and column domains using per-cell support checks.
#     * Deterministic cell fixing when all remaining patterns agree.
# - Use backtracking with MRV heuristic on smallest domain variable (row/col),
#   plus dynamic ordering by impact and incremental propagation.
#
# No external solvers are used.

from collections import deque

def _subset_sum_patterns(weights, target):
    """
    Return list of bitmasks over len(weights) positions such that sum(selected weights)=target.
    weights are positive ints, typically 1..n.
    Uses DP mapping sum -> list of masks. Optimized enough for n<=15-ish; here n is grid dimension.
    """
    n = len(weights)
    # dp[sum] = list of masks achieving sum
    dp = {0: [0]}
    for i, w in enumerate(weights):
        new_dp = dict(dp)
        for s, masks in dp.items():
            ns = s + w
            if ns > target:
                continue
            lst = new_dp.get(ns)
            if lst is None:
                new_dp[ns] = [m | (1 << i) for m in masks]
            else:
                # extend in-place
                lst.extend(m | (1 << i) for m in masks)
        dp = new_dp
    return dp.get(target, [])

def _bit_at(mask, idx):
    return (mask >> idx) & 1

def _domain_cell_support(dom_masks, idx, val):
    # True if there exists mask in domain with bit idx == val
    if val == 1:
        # any mask with bit set at idx
        bit = 1 << idx
        for m in dom_masks:
            if m & bit:
                return True
        return False
    else:
        bit = 1 << idx
        for m in dom_masks:
            if not (m & bit):
                return True
        return False

def _filter_domain_by_cell(dom_masks, idx, val):
    bit = 1 << idx
    if val == 1:
        return [m for m in dom_masks if (m & bit)]
    else:
        return [m for m in dom_masks if not (m & bit)]

def _compute_forced_bits(dom_masks, nbits):
    """
    Return (forced0_mask, forced1_mask) over nbits where:
    - forced1_mask has bits that are 1 in all domain masks
    - forced0_mask has bits that are 0 in all domain masks
    """
    if not dom_masks:
        return 0, 0
    all1 = (1 << nbits) - 1
    any1 = 0
    for m in dom_masks:
        all1 &= m
        any1 |= m
    forced1 = all1
    forced0 = (~any1) & ((1 << nbits) - 1)
    return forced0, forced1

def _propagate(row_dom, col_dom, R, C):
    """
    Enforce arc consistency between row and column domains.
    Returns (ok, row_dom, col_dom).
    row_dom: list[list[int]] of row masks over C cols
    col_dom: list[list[int]] of col masks over R rows
    """
    q = deque()
    inq = set()

    # Initialize with all variables
    for r in range(R):
        q.append(('r', r))
        inq.add(('r', r))
    for c in range(C):
        q.append(('c', c))
        inq.add(('c', c))

    while q:
        typ, idx = q.popleft()
        inq.discard((typ, idx))

        if typ == 'r':
            r = idx
            # For each column c, ensure row patterns have support in col domain and vice versa.
            dom = row_dom[r]
            if not dom:
                return False, row_dom, col_dom
            # Precompute for each c whether 0/1 is possible in row dom
            poss1 = [False] * C
            poss0 = [False] * C
            for m in dom:
                # iterate bits by scanning; C is small, so direct loop ok
                for c in range(C):
                    if (m >> c) & 1:
                        poss1[c] = True
                    else:
                        poss0[c] = True

            # Now for each column c, prune col_dom[c] if it requires impossible bit at row r
            for c in range(C):
                cd = col_dom[c]
                if not cd:
                    return False, row_dom, col_dom
                need_prune = False
                # If col has masks with bit r=1 but row cannot be 1 at c -> prune those masks; similarly for 0
                if not poss1[c]:
                    # remove masks with bit at r set
                    new_cd = [m for m in cd if not ((m >> r) & 1)]
                    if len(new_cd) != len(cd):
                        col_dom[c] = new_cd
                        need_prune = True
                if not poss0[c]:
                    new_cd = [m for m in col_dom[c] if ((m >> r) & 1)]
                    if len(new_cd) != len(col_dom[c]):
                        col_dom[c] = new_cd
                        need_prune = True
                if not col_dom[c]:
                    return False, row_dom, col_dom
                if need_prune and ('c', c) not in inq:
                    q.append(('c', c))
                    inq.add(('c', c))

            # Additionally, prune row_dom[r] based on updated col possibilities per cell
            # For each c, if col cannot support 1/0 at (r,c), remove row masks accordingly.
            # Compute per column supports quickly:
            for c in range(C):
                cd = col_dom[c]
                sup1 = _domain_cell_support(cd, r, 1)
                sup0 = _domain_cell_support(cd, r, 0)
                if not sup1:
                    new_dom = [m for m in row_dom[r] if not ((m >> c) & 1)]
                    if len(new_dom) != len(row_dom[r]):
                        row_dom[r] = new_dom
                        if not row_dom[r]:
                            return False, row_dom, col_dom
                        if ('r', r) not in inq:
                            q.append(('r', r))
                            inq.add(('r', r))
                        break  # restart row processing
                if not sup0:
                    new_dom = [m for m in row_dom[r] if ((m >> c) & 1)]
                    if len(new_dom) != len(row_dom[r]):
                        row_dom[r] = new_dom
                        if not row_dom[r]:
                            return False, row_dom, col_dom
                        if ('r', r) not in inq:
                            q.append(('r', r))
                            inq.add(('r', r))
                        break

        else:
            c = idx
            dom = col_dom[c]
            if not dom:
                return False, row_dom, col_dom

            poss1 = [False] * R
            poss0 = [False] * R
            for m in dom:
                for r in range(R):
                    if (m >> r) & 1:
                        poss1[r] = True
                    else:
                        poss0[r] = True

            for r in range(R):
                rd = row_dom[r]
                if not rd:
                    return False, row_dom, col_dom
                need_prune = False
                if not poss1[r]:
                    new_rd = [m for m in rd if not ((m >> c) & 1)]
                    if len(new_rd) != len(rd):
                        row_dom[r] = new_rd
                        need_prune = True
                if not poss0[r]:
                    new_rd = [m for m in row_dom[r] if ((m >> c) & 1)]
                    if len(new_rd) != len(row_dom[r]):
                        row_dom[r] = new_rd
                        need_prune = True
                if not row_dom[r]:
                    return False, row_dom, col_dom
                if need_prune and ('r', r) not in inq:
                    q.append(('r', r))
                    inq.add(('r', r))

            # Prune col_dom[c] based on updated row supports
            for r in range(R):
                rd = row_dom[r]
                sup1 = _domain_cell_support(rd, c, 1)
                sup0 = _domain_cell_support(rd, c, 0)
                if not sup1:
                    new_dom = [m for m in col_dom[c] if not ((m >> r) & 1)]
                    if len(new_dom) != len(col_dom[c]):
                        col_dom[c] = new_dom
                        if not col_dom[c]:
                            return False, row_dom, col_dom
                        if ('c', c) not in inq:
                            q.append(('c', c))
                            inq.add(('c', c))
                        break
                if not sup0:
                    new_dom = [m for m in col_dom[c] if ((m >> r) & 1)]
                    if len(new_dom) != len(col_dom[c]):
                        col_dom[c] = new_dom
                        if not col_dom[c]:
                            return False, row_dom, col_dom
                        if ('c', c) not in inq:
                            q.append(('c', c))
                            inq.add(('c', c))
                        break

    return True, row_dom, col_dom

def _choose_variable(row_dom, col_dom):
    # MRV across rows and cols; return ('r', idx) or ('c', idx)
    best = None
    best_size = 10**9
    for i, d in enumerate(row_dom):
        sz = len(d)
        if 1 < sz < best_size:
            best_size = sz
            best = ('r', i)
    for j, d in enumerate(col_dom):
        sz = len(d)
        if 1 < sz < best_size:
            best_size = sz
            best = ('c', j)
    return best

def _value_ordering(var, row_dom, col_dom, R, C):
    # Prefer masks that maximize agreement with forced bits of opposite domains.
    typ, idx = var
    if typ == 'r':
        r = idx
        # compute per column forced bits at row r from col domains
        forced1 = 0
        forced0 = 0
        for c in range(C):
            cd = col_dom[c]
            f0, f1 = _compute_forced_bits(cd, R)
            if (f1 >> r) & 1:
                forced1 |= (1 << c)
            if (f0 >> r) & 1:
                forced0 |= (1 << c)
        candidates = row_dom[r]
        def score(m):
            # higher is better
            agree1 = (m & forced1).bit_count()
            agree0 = (((~m) & ((1 << C) - 1)) & forced0).bit_count()
            return agree1 + agree0
        return sorted(candidates, key=score, reverse=True)
    else:
        c = idx
        forced1 = 0
        forced0 = 0
        for r in range(R):
            rd = row_dom[r]
            f0, f1 = _compute_forced_bits(rd, C)
            if (f1 >> c) & 1:
                forced1 |= (1 << r)
            if (f0 >> c) & 1:
                forced0 |= (1 << r)
        candidates = col_dom[c]
        def score(m):
            agree1 = (m & forced1).bit_count()
            agree0 = (((~m) & ((1 << R) - 1)) & forced0).bit_count()
            return agree1 + agree0
        return sorted(candidates, key=score, reverse=True)

def _deepcopy_domains(row_dom, col_dom):
    return [d[:] for d in row_dom], [d[:] for d in col_dom]

def _search(row_dom, col_dom, R, C):
    ok, row_dom, col_dom = _propagate(row_dom, col_dom, R, C)
    if not ok:
        return None

    var = _choose_variable(row_dom, col_dom)
    if var is None:
        # solved: all domains size 1
        row_masks = [d[0] for d in row_dom]
        return row_masks

    typ, idx = var
    ordered = _value_ordering(var, row_dom, col_dom, R, C)

    if typ == 'r':
        r = idx
        for m in ordered:
            rd2, cd2 = _deepcopy_domains(row_dom, col_dom)
            rd2[r] = [m]
            res = _search(rd2, cd2, R, C)
            if res is not None:
                return res
    else:
        c = idx
        for m in ordered:
            rd2, cd2 = _deepcopy_domains(row_dom, col_dom)
            cd2[c] = [m]
            res = _search(rd2, cd2, R, C)
            if res is not None:
                return res

    return None

def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]
    R, C = len(row_sum), len(col_sum)

    # Feasibility quick checks:
    if sum(row_sum) != sum(col_sum):
        return "No Solution"

    col_weights = list(range(1, C + 1))
    row_weights = list(range(1, R + 1))

    # Precompute domains
    row_dom = []
    for r in range(R):
        masks = _subset_sum_patterns(col_weights, row_sum[r])
        if not masks:
            return "No Solution"
        row_dom.append(masks)

    col_dom = []
    for c in range(C):
        masks = _subset_sum_patterns(row_weights, col_sum[c])
        if not masks:
            return "No Solution"
        col_dom.append(masks)

    row_masks = _search(row_dom, col_dom, R, C)
    if row_masks is None:
        return "No Solution"

    # Build answer grid: 'B' for black, None otherwise
    grid = []
    for r in range(R):
        m = row_masks[r]
        row = []
        for c in range(C):
            row.append('B' if ((m >> c) & 1) else None)
        grid.append(row)

    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 1, 1, 1, 1, 1], [0, 2, 3, 3, 3, 3], [0, 2, 4, 4, 4, 4], [0, 2, 2, 2, 4, 5], [0, 2, 6, 6, 6, 5], [0, 2, 6, 6, 6, 5]], 'row_water_counts': [1, 4, 4, 5, 5, 4], 'col_water_counts': [5, 4, 5, 5, 3, 1]}

from collections import defaultdict, deque

WATER = 1
DRY = 0
UNK = -1

def solve(observation):
    region = observation["region"]
    row_req = observation["row_water_counts"]
    col_req = observation["col_water_counts"]
    R, C = len(region), len(region[0])

    # Build region -> list of cells, and within each region, per-column stacks (by row) for monotone water-from-bottom rule.
    reg_cells = defaultdict(list)
    for r in range(R):
        for c in range(C):
            reg_cells[region[r][c]].append((r, c))
    reg_ids = sorted(reg_cells.keys())

    # For each region, group cells by column, sort by row increasing.
    reg_col_stacks = {}
    for rid in reg_ids:
        byc = defaultdict(list)
        for (r, c) in reg_cells[rid]:
            byc[c].append(r)
        for c in byc:
            byc[c].sort()
        reg_col_stacks[rid] = byc

    # Precompute for each cell within region its "below-in-same-region-same-column" list and "above" list,
    # which enables quick implications.
    below = [[None]*C for _ in range(R)]
    above = [[None]*C for _ in range(R)]
    for rid in reg_ids:
        byc = reg_col_stacks[rid]
        for c, rows in byc.items():
            for i, r in enumerate(rows):
                below[r][c] = [(rr, c) for rr in rows[i+1:]]  # strictly below
                above[r][c] = [(rr, c) for rr in rows[:i]]    # strictly above

    # State arrays
    grid = [[UNK]*C for _ in range(R)]
    row_w = [0]*R
    row_u = [C]*R
    col_w = [0]*C
    col_u = [R]*C

    # Region model:
    # Each region is either empty (all DRY) or "filled up to one consistent water level".
    # We model as choosing, for each (region, column) stack, a threshold k meaning the bottom k cells are water.
    # Consistent water level across the region means: there exists a global waterline height H such that in each column,
    # all cells with row index >= H are water if present, else dry. Equivalent to: choose H and then each column gets
    # water count = number of cells in that column with row >= H. Also allow empty = H > max_row_in_region.
    #
    # We'll represent possible waterlines as a set of candidate "H" values per region:
    # H ranges from -infty to +infty; in grid integer rows, consider H in [0..R] with convention:
    # water iff r >= H. Then H=R => empty (no r>=R). H=0 => all cells water.
    #
    # For each region rid, compute rows present per column; then for each H, the forced status of each cell.
    reg_possible_H = {}
    reg_cells_set = {}
    reg_rows = {}
    for rid in reg_ids:
        cells = reg_cells[rid]
        reg_cells_set[rid] = set(cells)
        minr = min(r for r, _ in cells)
        maxr = max(r for r, _ in cells)
        reg_rows[rid] = (minr, maxr)
        # Candidate H in [0..R]; but only those that change something for this region matter.
        # Still keep as boolean mask list for speed.
        possible = [True]*(R+1)
        reg_possible_H[rid] = possible

    # Helpers for propagation
    def assign(r, c, val, q, trail):
        cur = grid[r][c]
        if cur == val:
            return True
        if cur != UNK and cur != val:
            return False
        # push to trail for undo
        trail.append((r, c, cur))
        grid[r][c] = val
        # update counts
        if cur == UNK:
            trail.append(("row_u", r, row_u[r]))
            trail.append(("col_u", c, col_u[c]))
            row_u[r] -= 1
            col_u[c] -= 1
        if val == WATER:
            trail.append(("row_w", r, row_w[r]))
            trail.append(("col_w", c, col_w[c]))
            row_w[r] += 1
            col_w[c] += 1
        # enqueue row/col checks and region checks
        q.append(("row", r))
        q.append(("col", c))
        q.append(("reg", region[r][c]))
        # monotone rule within region/column stack
        if val == WATER:
            for (rr, cc) in below[r][c] or ():
                q.append(("force", rr, cc, WATER))
        else:  # DRY
            for (rr, cc) in above[r][c] or ():
                q.append(("force", rr, cc, DRY))
        return True

    def undo(trail):
        while trail:
            item = trail.pop()
            if isinstance(item[0], int):
                r, c, prev = item
                grid[r][c] = prev
            else:
                tag = item[0]
                if tag == "row_u":
                    _, r, prev = item
                    row_u[r] = prev
                elif tag == "col_u":
                    _, c, prev = item
                    col_u[c] = prev
                elif tag == "row_w":
                    _, r, prev = item
                    row_w[r] = prev
                elif tag == "col_w":
                    _, c, prev = item
                    col_w[c] = prev
                elif tag == "regH":
                    _, rid, idx, prev = item
                    reg_possible_H[rid][idx] = prev
                else:
                    raise RuntimeError("bad trail tag")

    def row_propagate(r, q, trail):
        # Basic line constraints
        need = row_req[r]
        if row_w[r] > need:
            return False
        if row_w[r] + row_u[r] < need:
            return False
        # If all unknown must be water
        if row_w[r] + row_u[r] == need:
            for c in range(C):
                if grid[r][c] == UNK:
                    if not assign(r, c, WATER, q, trail):
                        return False
        # If already met, rest must be dry
        if row_w[r] == need:
            for c in range(C):
                if grid[r][c] == UNK:
                    if not assign(r, c, DRY, q, trail):
                        return False
        return True

    def col_propagate(c, q, trail):
        need = col_req[c]
        if col_w[c] > need:
            return False
        if col_w[c] + col_u[c] < need:
            return False
        if col_w[c] + col_u[c] == need:
            for r in range(R):
                if grid[r][c] == UNK:
                    if not assign(r, c, WATER, q, trail):
                        return False
        if col_w[c] == need:
            for r in range(R):
                if grid[r][c] == UNK:
                    if not assign(r, c, DRY, q, trail):
                        return False
        return True

    def reg_prune(rid, q, trail):
        # Prune possible H values based on assigned cells in this region.
        poss = reg_possible_H[rid]
        cells = reg_cells[rid]

        any_poss = False
        for H in range(R+1):
            if not poss[H]:
                continue
            ok = True
            # Check consistency: for each known cell (r,c), must match (r>=H)->WATER else DRY
            for (r, c) in cells:
                v = grid[r][c]
                if v == UNK:
                    continue
                implied = WATER if r >= H else DRY
                if v != implied:
                    ok = False
                    break
            if not ok:
                trail.append(("regH", rid, H, poss[H]))
                poss[H] = False
            else:
                any_poss = True
        if not any_poss:
            return False

        # If a cell is forced same across all remaining H, assign it.
        # To reduce cost, compute for each cell whether WATER is possible and DRY is possible.
        # Early exit if fully decided.
        remHs = [H for H in range(R+1) if poss[H]]
        if len(remHs) == 1:
            H = remHs[0]
            for (r, c) in cells:
                if grid[r][c] == UNK:
                    if not assign(r, c, WATER if r >= H else DRY, q, trail):
                        return False
            return True

        # General forced check
        for (r, c) in cells:
            if grid[r][c] != UNK:
                continue
            canW = False
            canD = False
            for H in remHs:
                if r >= H:
                    canW = True
                else:
                    canD = True
                if canW and canD:
                    break
            if not canW:
                if not assign(r, c, DRY, q, trail):
                    return False
            elif not canD:
                if not assign(r, c, WATER, q, trail):
                    return False
        return True

    def propagate(q, trail):
        while q:
            item = q.pop()
            tag = item[0]
            if tag == "force":
                _, r, c, val = item
                if not assign(r, c, val, q, trail):
                    return False
            elif tag == "row":
                _, r = item
                if not row_propagate(r, q, trail):
                    return False
            elif tag == "col":
                _, c = item
                if not col_propagate(c, q, trail):
                    return False
            elif tag == "reg":
                _, rid = item
                if not reg_prune(rid, q, trail):
                    return False
            else:
                raise RuntimeError("bad queue tag")
        return True

    # Initial global propagation (regions + row/col)
    q = []
    trail = []
    for r in range(R):
        q.append(("row", r))
    for c in range(C):
        q.append(("col", c))
    for rid in reg_ids:
        q.append(("reg", rid))
    if not propagate(q, trail):
        return "No Solution"

    def is_solved():
        for r in range(R):
            if row_w[r] != row_req[r] or row_u[r] != 0:
                return False
        for c in range(C):
            if col_w[c] != col_req[c] or col_u[c] != 0:
                return False
        return True

    def choose_branch():
        # Human-like choice: pick most constrained region (fewest H) else most constrained row/col or a single cell.
        best = None

        # Regions
        for rid in reg_ids:
            poss = reg_possible_H[rid]
            cnt = sum(1 for x in poss if x)
            if cnt > 1:
                if best is None or cnt < best[0]:
                    best = (cnt, ("regH", rid))
        if best is not None and best[0] <= 3:
            return best[1]

        # Rows / cols: choose one with smallest slack and unknowns
        best_line = None
        for r in range(R):
            if row_u[r] == 0:
                continue
            need = row_req[r] - row_w[r]
            if need < 0 or need > row_u[r]:
                return ("fail",)
            score = (row_u[r], abs(need - row_u[r]/2))
            if best_line is None or score < best_line[0]:
                best_line = (score, ("row", r))
        for c in range(C):
            if col_u[c] == 0:
                continue
            need = col_req[c] - col_w[c]
            if need < 0 or need > col_u[c]:
                return ("fail",)
            score = (col_u[c], abs(need - col_u[c]/2))
            if best_line is None or score < best_line[0]:
                best_line = (score, ("col", c))
        if best_line is not None and best is None:
            return best_line[1]
        if best is not None:
            return best[1]

        # Fallback: pick first unknown cell
        for r in range(R):
            for c in range(C):
                if grid[r][c] == UNK:
                    return ("cell", r, c)
        return None

    def dfs():
        if is_solved():
            return True
        branch = choose_branch()
        if branch is None:
            return False
        if branch[0] == "fail":
            return False

        if branch[0] == "regH":
            _, rid = branch
            possHs = [H for H in range(R+1) if reg_possible_H[rid][H]]
            # Try more "human" ordering: empty-ish first if rows/cols demand low water in that region? Hard to know.
            # Use heuristic: try H around median to balance.
            possHs.sort(key=lambda H: abs(H - R//2))
            for H in possHs:
                local_trail = []
                local_q = []
                # set region to exactly this H by eliminating others
                for HH in range(R+1):
                    if HH != H and reg_possible_H[rid][HH]:
                        local_trail.append(("regH", rid, HH, True))
                        reg_possible_H[rid][HH] = False
                local_q.append(("reg", rid))
                if propagate(local_q, local_trail):
                    if dfs():
                        return True
                undo(local_trail)
            return False

        if branch[0] == "row":
            _, r = branch
            # pick an unknown cell in row and try DRY/WATER guided by remaining need
            need = row_req[r] - row_w[r]
            # prefer WATER if need is high
            targets = []
            for c in range(C):
                if grid[r][c] == UNK:
                    targets.append((r, c))
            if not targets:
                return False
            rr, cc = targets[0]
            order = [WATER, DRY] if need > 0 else [DRY, WATER]
            for val in order:
                local_trail = []
                local_q = []
                if assign(rr, cc, val, local_q, local_trail) and propagate(local_q, local_trail):
                    if dfs():
                        return True
                undo(local_trail)
            return False

        if branch[0] == "col":
            _, c = branch
            need = col_req[c] - col_w[c]
            targets = []
            for r in range(R):
                if grid[r][c] == UNK:
                    targets.append((r, c))
            if not targets:
                return False
            rr, cc = targets[0]
            order = [WATER, DRY] if need > 0 else [DRY, WATER]
            for val in order:
                local_trail = []
                local_q = []
                if assign(rr, cc, val, local_q, local_trail) and propagate(local_q, local_trail):
                    if dfs():
                        return True
                undo(local_trail)
            return False

        # cell
        _, r, c = branch
        for val in (WATER, DRY):
            local_trail = []
            local_q = []
            if assign(r, c, val, local_q, local_trail) and propagate(local_q, local_trail):
                if dfs():
                    return True
            undo(local_trail)
        return False

    if not dfs():
        return "No Solution"

    out = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('W' if grid[r][c] == WATER else None)
        out.append(row)
    return str(out)

