    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 2, None, None, None, None], [None, 1, None, None, None, -1, None], [None, None, None, None, None, 0, None], [None, None, None, None, None, None, None], [0, None, None, None, None, None, None], [None, 1, None, None, 1, 2, None], [None, None, None, None, -1, None, None]]}

from collections import deque

# Akari / Light Up solver with human-like propagation + backtracking
# Board encoding in observation['data']:
#   None = white cell
#   -1   = black cell (no number)
#   0..4 = numbered black cell
#
# Output: N x N grid with 'B' on bulb cells, None elsewhere.

DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))


def solve(observation):
    data = observation["data"]
    n = len(data)
    if any(len(row) != n for row in data):
        return "No Solution"

    # Cell sets
    is_black = [[data[r][c] is not None for c in range(n)] for r in range(n)]
    is_white = [[not is_black[r][c] for c in range(n)] for r in range(n)]

    # Precompute line-of-sight segments between blacks for each white cell (for fast updates)
    # For each white cell, store visible whites in four directions up to a black (exclusive).
    vis = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if not is_white[r][c]:
                continue
            lst = []
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                line = []
                while 0 <= rr < n and 0 <= cc < n and is_white[rr][cc]:
                    line.append((rr, cc))
                    rr += dr
                    cc += dc
                lst.append(line)
            vis[r][c] = lst

    # Precompute adjacency for numbered blacks
    numbered = []
    adj_whites = {}  # (r,c)-> list of adjacent white cells
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if isinstance(v, int) and v >= 0:
                numbered.append((r, c))
                aw = []
                for dr, dc in DIRS:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n and is_white[rr][cc]:
                        aw.append((rr, cc))
                adj_whites[(r, c)] = aw

    # State:
    # 0 = undecided white, 1 = bulb, -1 = no-bulb (marked empty)
    state = [[0] * n for _ in range(n)]
    lit = [[False] * n for _ in range(n)]  # whether white is illuminated by some bulb
    # For efficient unlighting rollback, we keep illumination count
    illum_cnt = [[0] * n for _ in range(n)]
    # Bulb conflict tracking: a bulb forbids bulbs in its line-of-sight
    # We'll maintain "attacked count" per cell: number of bulbs that see this cell (excluding itself)
    attacked_cnt = [[0] * n for _ in range(n)]

    def inb(r, c):
        return 0 <= r < n and 0 <= c < n

    # Helpers to apply and rollback moves using a trail stack
    trail = []

    def trail_set(mat, r, c, newv):
        oldv = mat[r][c]
        if oldv == newv:
            return
        trail.append((mat, r, c, oldv))
        mat[r][c] = newv

    def trail_inc(mat, r, c, delta):
        oldv = mat[r][c]
        newv = oldv + delta
        if delta == 0:
            return
        trail.append((mat, r, c, oldv))
        mat[r][c] = newv

    def undo(trail_mark):
        while len(trail) > trail_mark:
            mat, r, c, oldv = trail.pop()
            mat[r][c] = oldv

    def is_number_cell(r, c):
        v = data[r][c]
        return isinstance(v, int) and v >= 0

    # Check numbered cell feasibility quickly
    def num_counts_ok(r, c):
        req = data[r][c]
        aw = adj_whites[(r, c)]
        bulbs = 0
        unknown = 0
        for (rr, cc) in aw:
            if state[rr][cc] == 1:
                bulbs += 1
            elif state[rr][cc] == 0:
                unknown += 1
        if bulbs > req:
            return False
        if bulbs + unknown < req:
            return False
        return True

    def all_numbers_ok():
        for (r, c) in numbered:
            if not num_counts_ok(r, c):
                return False
        return True

    def apply_light_from_bulb(r, c, delta):
        # delta = +1 for placing bulb, -1 for removing bulb
        # A bulb illuminates itself and along lines until black.
        trail_inc(illum_cnt, r, c, delta)
        trail_set(lit, r, c, illum_cnt[r][c] + (0 if delta < 0 else 0) > 0)  # will be corrected below
        # Update lit based on illum_cnt after increment (handled by dedicated set below)
        # To avoid recompute, set lit by checking illum_cnt>0 when changed.
        # We'll do for each affected cell after inc.
        def update_lit_cell(rr, cc):
            trail_set(lit, rr, cc, illum_cnt[rr][cc] > 0)

        update_lit_cell(r, c)
        for k in range(4):
            for (rr, cc) in vis[r][c][k]:
                trail_inc(illum_cnt, rr, cc, delta)
                update_lit_cell(rr, cc)

    def apply_attack_from_bulb(r, c, delta):
        # attacked_cnt for other whites seen by bulb (not including itself)
        for k in range(4):
            for (rr, cc) in vis[r][c][k]:
                trail_inc(attacked_cnt, rr, cc, delta)

    def can_place_bulb(r, c):
        if not is_white[r][c]:
            return False
        if state[r][c] == -1:
            return False
        if state[r][c] == 1:
            return True
        # No other bulb can see it
        if attacked_cnt[r][c] > 0:
            return False
        # Adjacent numbered constraints: placing bulb must not exceed required
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            if inb(rr, cc) and is_number_cell(rr, cc):
                req = data[rr][cc]
                aw = adj_whites[(rr, cc)]
                bulbs = 0
                unknown = 0
                for (ar, ac) in aw:
                    if (ar, ac) == (r, c):
                        continue
                    if state[ar][ac] == 1:
                        bulbs += 1
                    elif state[ar][ac] == 0:
                        unknown += 1
                # if place bulb at (r,c)
                bulbs += 1
                if bulbs > req:
                    return False
                # remaining could still reach req: bulbs + unknown >= req always, since unknown excludes (r,c)
                if bulbs + unknown < req:
                    return False
        return True

    def forbid_cell(r, c):
        # mark as no-bulb
        if state[r][c] == -1:
            return True
        if state[r][c] == 1:
            return False
        trail_set(state, r, c, -1)
        return True

    def place_bulb(r, c):
        if state[r][c] == 1:
            return True
        if not can_place_bulb(r, c):
            return False
        trail_set(state, r, c, 1)
        apply_attack_from_bulb(r, c, +1)
        apply_light_from_bulb(r, c, +1)
        return True

    def remove_bulb(r, c):
        # only used in rollback by undo; no direct call
        pass

    # Propagation rules queue
    q = deque()

    def enqueue_number_cells_around(r, c):
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            if inb(rr, cc) and is_number_cell(rr, cc):
                q.append(("num", rr, cc))

    def enqueue_cell(r, c):
        q.append(("cell", r, c))

    def initial_queue():
        # All numbered cells
        for (r, c) in numbered:
            q.append(("num", r, c))
        # All whites for illumination rules
        for r in range(n):
            for c in range(n):
                if is_white[r][c]:
                    q.append(("cell", r, c))

    def visible_undecided_positions(r, c):
        # possible bulb placements that could illuminate (r,c): itself or any visible in row/col without black
        # But bulb placements must also satisfy attacked constraints etc; here we return candidates positions
        res = [(r, c)]
        for k in range(4):
            res.extend(vis[r][c][k])
        # filter to whites only (already) and not forbidden
        out = []
        for (rr, cc) in res:
            if state[rr][cc] != -1:
                out.append((rr, cc))
        return out

    def propagate():
        # Returns False on contradiction
        while q:
            typ, r, c = q.popleft()
            if typ == "num":
                if not num_counts_ok(r, c):
                    return False
                req = data[r][c]
                aw = adj_whites[(r, c)]
                bulbs = 0
                unknowns = []
                for (rr, cc) in aw:
                    if state[rr][cc] == 1:
                        bulbs += 1
                    elif state[rr][cc] == 0:
                        unknowns.append((rr, cc))
                if bulbs == req:
                    # all remaining adjacent must be empty
                    for (rr, cc) in unknowns:
                        if not forbid_cell(rr, cc):
                            return False
                        enqueue_cell(rr, cc)
                        enqueue_number_cells_around(rr, cc)
                elif bulbs + len(unknowns) == req:
                    # all unknown adjacent must be bulbs
                    for (rr, cc) in unknowns:
                        if not place_bulb(rr, cc):
                            return False
                        enqueue_cell(rr, cc)
                        enqueue_number_cells_around(rr, cc)
                continue

            # cell propagation: illumination & bulb feasibility
            if not is_white[r][c]:
                continue
            if lit[r][c]:
                continue
            if state[r][c] == 1:
                continue

            # If cell unlit, at least one candidate position in its sight must be a bulb.
            # Candidate positions are those that can still host a bulb (not forbidden, not attacked, etc).
            candidates = visible_undecided_positions(r, c)
            feasible = []
            for (rr, cc) in candidates:
                if state[rr][cc] == 1:
                    feasible = [(rr, cc)]
                    break
                if state[rr][cc] == 0 and can_place_bulb(rr, cc):
                    feasible.append((rr, cc))

            if not feasible:
                return False

            if len(feasible) == 1:
                rr, cc = feasible[0]
                if not place_bulb(rr, cc):
                    return False
                enqueue_cell(rr, cc)
                enqueue_number_cells_around(rr, cc)
                # placing a bulb affects lit status of many cells; re-enqueue line
                for k in range(4):
                    for (ar, ac) in vis[rr][cc][k]:
                        enqueue_cell(ar, ac)
                enqueue_cell(rr, cc)

        return True

    def all_lit():
        for r in range(n):
            for c in range(n):
                if is_white[r][c] and not lit[r][c]:
                    return False
        return True

    def choose_branch_cell():
        # Heuristic: pick an unlit cell, then among its feasible candidates pick the most constrained
        best = None
        best_domain = None
        for r in range(n):
            for c in range(n):
                if is_white[r][c] and not lit[r][c]:
                    candidates = visible_undecided_positions(r, c)
                    dom = []
                    for (rr, cc) in candidates:
                        if state[rr][cc] == 1:
                            dom = [(rr, cc)]
                            break
                        if state[rr][cc] == 0 and can_place_bulb(rr, cc):
                            dom.append((rr, cc))
                    if not dom:
                        return None, None
                    # prefer smallest domain
                    if best is None or len(dom) < len(best_domain):
                        best = (r, c)
                        best_domain = dom
                        if len(best_domain) == 1:
                            return best, best_domain
        return best, best_domain

    def dfs():
        mark = len(trail)
        # Ensure queue is not stale: run propagation from scratch queue of affected constraints is expensive.
        # We instead rely on incremental enqueues; still, for branching, ensure all constraints consistent:
        if not all_numbers_ok():
            undo(mark)
            return False
        if not propagate():
            undo(mark)
            return False
        if all_lit():
            return True

        cell, dom = choose_branch_cell()
        if cell is None:
            undo(mark)
            return False

        # Branch order: try placing bulb where it also satisfies nearby numbered tightness
        # Sort dom by (attacked_cnt, adjacency tightness, lighting gain)
        def score(pos):
            rr, cc = pos
            tight = 0
            for dr, dc in DIRS:
                ar, ac = rr + dr, cc + dc
                if inb(ar, ac) and is_number_cell(ar, ac):
                    req = data[ar][ac]
                    aw = adj_whites[(ar, ac)]
                    bulbs = sum(1 for (x, y) in aw if state[x][y] == 1)
                    unk = sum(1 for (x, y) in aw if state[x][y] == 0)
                    # lower slack => more constrained
                    slack = (bulbs + unk) - req
                    tight += max(0, 10 - slack)
            gain = 1
            for k in range(4):
                for (x, y) in vis[rr][cc][k]:
                    if is_white[x][y] and not lit[x][y]:
                        gain += 1
            if not lit[rr][cc]:
                gain += 1
            return (-tight, -gain, attacked_cnt[rr][cc])

        dom_sorted = sorted(dom, key=score)

        # Try bulb placement options first (strongly constrained by no-two-bulbs rule)
        for (rr, cc) in dom_sorted:
            mark2 = len(trail)
            if place_bulb(rr, cc):
                enqueue_cell(rr, cc)
                enqueue_number_cells_around(rr, cc)
                for k in range(4):
                    for (x, y) in vis[rr][cc][k]:
                        enqueue_cell(x, y)
                if dfs():
                    return True
            undo(mark2)

        # If none works, force that the chosen cell's candidates are not bulbs is impossible because it must be lit.
        # But we can branch by forbidding a particular candidate to reduce domain (nogood style).
        # Pick first candidate and forbid it, recurse.
        # This is still human-like: "that spot can't be a bulb, so try other possibilities."
        rr, cc = dom_sorted[0]
        mark3 = len(trail)
        if forbid_cell(rr, cc):
            enqueue_cell(rr, cc)
            enqueue_number_cells_around(rr, cc)
            # forbidding affects illumination possibility for all cells that rely on it
            # enqueue along its lines
            enqueue_cell(rr, cc)
            for k in range(4):
                for (x, y) in vis[rr][cc][k]:
                    enqueue_cell(x, y)
            if dfs():
                return True
        undo(mark3)

        undo(mark)
        return False

    # Initial: numbered zeros -> forbid adjacent immediately
    for (r, c) in numbered:
        if data[r][c] == 0:
            for (rr, cc) in adj_whites[(r, c)]:
                if not forbid_cell(rr, cc):
                    return "No Solution"
                enqueue_cell(rr, cc)

    initial_queue()
    if not propagate():
        return "No Solution"

    if not dfs():
        return "No Solution"

    # Build answer grid
    ans = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if is_white[r][c] and state[r][c] == 1:
                ans[r][c] = "B"
            else:
                ans[r][c] = None
    return ans


if __name__ == "__main__":
    print(solve(OBSERVATION))

