# Akari / Light Up solver with human-like deduction + backtracking.
# Board encoding in observation['data']:
#   None = white cell
#   -1   = black cell (unnumbered)
#   0..4 = black cell with number constraint (exact adjacent bulbs)


DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = len(data[0]) if n else 0

    def inb(r, c):
        return 0 <= r < n and 0 <= c < m

    # Precompute white cells and segments (maximal contiguous whites in row/col)
    is_white = [[data[r][c] is None for c in range(m)] for r in range(n)]
    is_black = [[not is_white[r][c] for c in range(m)] for r in range(n)]

    whites = [(r, c) for r in range(n) for c in range(m) if is_white[r][c]]

    # Adjacency for numbered blacks
    numbered = []
    adj_whites_of_num = {}
    for r in range(n):
        for c in range(m):
            v = data[r][c]
            if isinstance(v, int) and v >= 0:
                numbered.append((r, c))
                adj = []
                for dr, dc in DIRS:
                    rr, cc = r + dr, c + dc
                    if inb(rr, cc) and is_white[rr][cc]:
                        adj.append((rr, cc))
                adj_whites_of_num[(r, c)] = adj

    # Build row segments
    row_seg_id = [[-1] * m for _ in range(n)]
    row_segments = []  # list of list of cells
    for r in range(n):
        c = 0
        while c < m:
            if not is_white[r][c]:
                c += 1
                continue
            start = c
            cells = []
            while c < m and is_white[r][c]:
                row_seg_id[r][c] = len(row_segments)
                cells.append((r, c))
                c += 1
            row_segments.append(cells)
            # continue; c already at first non-white
    # Build col segments
    col_seg_id = [[-1] * m for _ in range(n)]
    col_segments = []
    for c in range(m):
        r = 0
        while r < n:
            if not is_white[r][c]:
                r += 1
                continue
            cells = []
            while r < n and is_white[r][c]:
                col_seg_id[r][c] = len(col_segments)
                cells.append((r, c))
                r += 1
            col_segments.append(cells)

    # For each white cell, its two segments and "line-of-sight" cells are simply union of its segs.
    # Bulb conflict constraint: at most one bulb per segment (row segment and col segment).
    # Illumination constraint: every white must be illuminated => in its row segment or col segment there must be a bulb.

    # Build candidate bulb positions for each illumination requirement (cell)
    cell_watchers = {}
    for r, c in whites:
        rs = row_seg_id[r][c]
        cs = col_seg_id[r][c]
        # All cells in the row segment and col segment can illuminate (r,c)
        watchers = set(row_segments[rs]) | set(col_segments[cs])
        cell_watchers[(r, c)] = tuple(watchers)

    # For each segment, list of cells
    seg_cells = {
        ("r", i): tuple(row_segments[i]) for i in range(len(row_segments))
    }
    seg_cells.update({
        ("c", i): tuple(col_segments[i]) for i in range(len(col_segments))
    })

    # For each white cell, which two segments it belongs to
    cell_segs = {(r, c): (("r", row_seg_id[r][c]), ("c", col_seg_id[r][c])) for r, c in whites}

    # State representation:
    #   assign[(r,c)] in {0,1} for white cells only, absent = unassigned.
    #   seg_bulb[("r",i)] = (r,c) if bulb placed in that segment else None
    #   seg_forbidden[seg] = set of cells forbidden as bulbs due to already placed bulb in crossing segment? (maintained via simple checks)
    # We'll perform fast consistency checks on placement.

    # For numbered blacks, maintain counts:
    #   nb_count[(br,bc)] = bulbs already placed adjacent
    #   nb_unassigned[(br,bc)] = number of adjacent whites not yet assigned to 0/1
