from __future__ import annotations

# Solver for "Masyu-like with segment length sums" loop puzzle on dot grid.
# Input observation['data'] is (N+1)x(N+1) tokens or None located on dots.
# Output is ordered closed loop path as list of (row,col) dots ending with start repeated.

from collections import defaultdict, deque
import math
import time

DIRS = [(0, 1), (1, 0), (0, -1), (-1, 0)]
DIR_BIT = {(0, 1): 0, (1, 0): 1, (0, -1): 2, (-1, 0): 3}
BIT_DIR = {v: k for k, v in DIR_BIT.items()}


def solve(observation):
    data = observation["data"]
    H = len(data)           # dots rows = N+1
    W = len(data[0])        # dots cols = N+1
    N = H - 1
    M = W - 1
    if N < 1 or M < 1:
        return "No Solution"

    # Edge indexing: horizontal edges (r,c)-(r,c+1): r in [0..N], c in [0..M-1]
    # vertical edges (r,c)-(r+1,c): r in [0..N-1], c in [0..M]
    # We'll store as two 2D arrays: -1 unknown, 0 off, 1 on.
    eh = [[-1] * M for _ in range(H)]   # H x M
    ev = [[-1] * W for _ in range(N)]   # N x W

    def inb_dot(r, c):
        return 0 <= r < H and 0 <= c < W

    def get_edge(u, v):
        (r1, c1), (r2, c2) = u, v
        dr, dc = r2 - r1, c2 - c1
        if abs(dr) + abs(dc) != 1:
            raise ValueError("Non-adjacent dots")
        if dr == 0:
            r = r1
            c = min(c1, c2)
            return ("h", r, c)
        else:
            r = min(r1, r2)
            c = c1
            return ("v", r, c)

    def edge_value(e):
        t, r, c = e
        return eh[r][c] if t == "h" else ev[r][c]

    def set_edge(e, val, reason=""):
        nonlocal changed
        t, r, c = e
        arr = eh if t == "h" else ev
        cur = arr[r][c]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        arr[r][c] = val
        changed = True
        return True

    def incident_edges(r, c):
        res = []
        if c > 0:
            res.append(("h", r, c - 1))
        if c < M:
            res.append(("h", r, c))
        if r > 0:
            res.append(("v", r - 1, c))
        if r < N:
            res.append(("v", r, c))
        return res

    def neighbor_dot_from_edge(e, r, c):
        t, er, ec = e
        if t == "h":
            if (r, c) == (er, ec):
                return (r, c + 1)
            elif (r, c) == (er, ec + 1):
                return (r, c - 1)
        else:
            if (r, c) == (er, ec):
                return (r + 1, c)
            elif (r, c) == (er + 1, ec):
                return (r - 1, c)
        raise ValueError("Dot not incident to edge")

    def dot_deg_status(r, c):
        inc = incident_edges(r, c)
        on = 0
        unk = 0
        for e in inc:
            v = edge_value(e)
            if v == 1:
                on += 1
            elif v == -1:
                unk += 1
        return on, unk, len(inc)

    # Clues
    clues = {}
    for r in range(H):
        for c in range(W):
            tok = data[r][c]
            if tok:
                typ = tok[0]
                k = int(tok[1:])
                clues[(r, c)] = (typ, k)

    # Human-like deduction helpers for clue constraints
    def line_dir_state_at_dot(r, c):
        # returns possible dirs that are ON among 4 directions, computed from edge states
        st = {}
        if c < M:
            st[(0, 1)] = edge_value(("h", r, c))
        if c > 0:
            st[(0, -1)] = edge_value(("h", r, c - 1))
        if r < N:
            st[(1, 0)] = edge_value(("v", r, c))
        if r > 0:
            st[(-1, 0)] = edge_value(("v", r - 1, c))
        return st  # dir -> -1/0/1

    def force_dot_degree_rules(r, c):
        # Standard single-loop degree constraints: each dot has degree 0 or 2.
        on, unk, tot = dot_deg_status(r, c)
        if on > 2:
            return False
        if on + unk < 2 and on != 0:
            # can't reach degree 2
            return False
        # If already 2, all other incident must be off
        if on == 2:
            for e in incident_edges(r, c):
                if edge_value(e) == -1:
                    if not set_edge(e, 0, "deg=2"):
                        return False
        # If on==1 and only one unknown left, it must turn on (to reach 2)
        if on == 1 and unk == 1:
            for e in incident_edges(r, c):
                if edge_value(e) == -1:
                    if not set_edge(e, 1, "deg complete"):
                        return False
        # If on==0 and unk==1: to avoid degree 1, that last unknown must be off
        if on == 0 and unk == 1:
            for e in incident_edges(r, c):
                if edge_value(e) == -1:
                    if not set_edge(e, 0, "avoid deg=1"):
                        return False
        return True

    def get_two_on_dirs_at_dot(r, c):
        st = line_dir_state_at_dot(r, c)
        on_dirs = [d for d, v in st.items() if v == 1]
        if len(on_dirs) != 2:
            return None
        return tuple(on_dirs)

    def axis(d):
        return 0 if d[0] == 0 else 1  # 0 horizontal, 1 vertical

    def opp(d):
        return (-d[0], -d[1])

    def clue_local_turn_straight_constraints(pos):
        # Apply W: straight if degree 2 established; B: turn if degree 2 established.
        r, c = pos
        typ, k = clues[pos]
        st = line_dir_state_at_dot(r, c)

        on_dirs = [d for d, v in st.items() if v == 1]
        off_dirs = [d for d, v in st.items() if v == 0]
        unk_dirs = [d for d, v in st.items() if v == -1]

        # Hard constraints when two ON are known
        if len(on_dirs) == 2:
            if typ == "W":
                if axis(on_dirs[0]) != axis(on_dirs[1]):
                    return False
            else:
                if axis(on_dirs[0]) == axis(on_dirs[1]):
                    return False

        # If one ON known, some deductions:
        if len(on_dirs) == 1:
            d = on_dirs[0]
            if typ == "W":
                # must go straight: opposite direction must be ON if exists, perpendiculars OFF.
                if opp(d) in st:
                    if st[opp(d)] == 0:
                        return False
                    if st[opp(d)] == -1:
                        e = get_edge((r, c), (r + opp(d)[0], c + opp(d)[1]))
                        if not set_edge(e, 1, "W straight opposite"):
                            return False
                for pd in [(d[1], d[0]), (-d[1], -d[0])]:  # perpendiculars
                    if pd in st:
                        if st[pd] == 1:
                            return False
                        if st[pd] == -1:
                            e = get_edge((r, c), (r + pd[0], c + pd[1]))
                            if not set_edge(e, 0, "W straight perp off"):
                                return False
            else:
                # must turn: opposite must be OFF (if exists); at least one perpendicular must be ON eventually.
                if opp(d) in st:
                    if st[opp(d)] == 1:
                        return False
                    if st[opp(d)] == -1:
                        e = get_edge((r, c), (r + opp(d)[0], c + opp(d)[1]))
                        if not set_edge(e, 0, "B turn opposite off"):
                            return False
                # If one perpendicular is off and other unknown, force other on (if exists)
                perps = []
                for pd in [(d[1], d[0]), (-d[1], -d[0])]:
                    if pd in st:
                        perps.append(pd)
                if len(perps) == 2:
                    v1, v2 = st[perps[0]], st[perps[1]]
                    if v1 == 0 and v2 == 0:
                        return False
                    if v1 == 0 and v2 == -1:
                        e = get_edge((r, c), (r + perps[1][0], c + perps[1][1]))
                        if not set_edge(e, 1, "B turn force perp"):
                            return False
                    if v2 == 0 and v1 == -1:
                        e = get_edge((r, c), (r + perps[0][0], c + perps[0][1]))
                        if not set_edge(e, 1, "B turn force perp"):
                            return False

        # If degree completed (2), enforce remaining are off (handled by degree rule), plus typ consistency above.
        return True

    def trace_straight_length_from(pos, d):
        # If from pos there is an ON edge in direction d, count consecutive ON edges in that direction
        # until a turn/end/unknown/off encountered. Returns (min_len, max_len, determined?)
        r, c = pos
        st = line_dir_state_at_dot(r, c)
        if d not in st:
            return (0, 0, True)
        if st[d] == 0:
            return (0, 0, True)
        # walk
        min_len = 0
        max_len = 0
        cr, cc = r, c
        cd = d
        # if first edge unknown, min=0 max can extend until forced stop
        first_val = st[d]
        if first_val == 1:
            min_len = 1
            max_len = 1
            cr, cc = r + d[0], c + d[1]
        else:
            # unknown
            min_len = 0
            max_len = 1
            cr, cc = r + d[0], c + d[1]
        # Now extend while we can go straight: i.e., at intermediate dot, the edge continuing straight is ON/UNK,
        # and perpendicular edges must be OFF for it to be a straight segment; but we don't know yet.
        # We'll compute bounds based on edge states only, conservative but useful.
        steps = max(N, M) + 2
        for _ in range(steps):
            if not inb_dot(cr, cc):
                break
            # next edge continuing in same direction from (cr,cc)
            st2 = line_dir_state_at_dot(cr, cc)
            if cd not in st2:
                break
            v = st2[cd]
            if v == 0:
                break
            if v == 1:
                min_len += 1
                max_len += 1
            else:
                max_len += 1
            cr, cc = cr + cd[0], cc + cd[1]
        determined = (min_len == max_len)
        return (min_len, max_len, determined)

    def clue_length_sum_constraints(pos):
        # Use bounds to prune impossible k early; if turn/straight directions known, can derive more.
        r, c = pos
        typ, k = clues[pos]
        st = line_dir_state_at_dot(r, c)

        # Determine which two directions will be used if partially known:
        on_dirs = [d for d, v in st.items() if v == 1]
        unk_dirs = [d for d, v in st.items() if v == -1]
        # Only apply meaningful checks if at least one incident edge is on/forced by typ.
        # We'll compute possible pairs of directions consistent with typ and current on/off.
        dirs = list(st.keys())

        def ok_pair(a, b):
            if a == b or opp(a) == b:
                # Straight uses opposite directions; turn uses perpendicular.
                pass
            if typ == "W":
                return axis(a) == axis(b) and opp(a) == b
            else:
                return axis(a) != axis(b)

        pairs = []
        for i in range(len(dirs)):
            for j in range(i + 1, len(dirs)):
                a, b = dirs[i], dirs[j]
                if not ok_pair(a, b):
                    continue
                # respect off constraints
                if st[a] == 0 or st[b] == 0:
                    continue
                # if some other dir is on that is not in pair, impossible
                bad = False
                for d in on_dirs:
                    if d != a and d != b:
                        bad = True
                        break
                if bad:
                    continue
                pairs.append((a, b))

        if not pairs:
            # may still be early with no edges yet and typ imposes possibility; but if all dirs exist and some forced off can empty.
            return False

        # For each feasible pair, compute bounds for lengths on each ray.
        feasible = False
        global_min = math.inf
        global_max = -math.inf
        for a, b in pairs:
            mina, maxa, _ = trace_straight_length_from(pos, a)
            minb, maxb, _ = trace_straight_length_from(pos, b)
            # If first edge must be on due to degree or typ? not guaranteed yet.
            # But if st[a]==1 then length at least 1 etc already in bounds.
            minsum = mina + minb
            maxsum = maxa + maxb
            global_min = min(global_min, minsum)
            global_max = max(global_max, maxsum)
            if minsum <= k <= maxsum:
                feasible = True
        if not feasible:
            return False

        # Stronger: if k is outside bounds for all pairs already handled.
        return True

    # Single loop global constraints via DSU, forbidding premature cycles
    parent = {}
    size = {}
    deg_on = [[0] * W for _ in range(H)]

    def dsu_find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def dsu_union(a, b):
        ra, rb = dsu_find(a), dsu_find(b)
        if ra == rb:
            return ra
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return ra

    def dsu_init_all():
        for r in range(H):
            for c in range(W):
                parent[(r, c)] = (r, c)
                size[(r, c)] = 1

    dsu_init_all()

    def rebuild_dsu_and_degrees():
        for r in range(H):
            for c in range(W):
                parent[(r, c)] = (r, c)
                size[(r, c)] = 1
                deg_on[r][c] = 0
        # Add ON edges
        for r in range(H):
            for c in range(M):
                if eh[r][c] == 1:
                    a = (r, c)
                    b = (r, c + 1)
                    dsu_union(a, b)
                    deg_on[r][c] += 1
                    deg_on[r][c + 1] += 1
        for r in range(N):
            for c in range(W):
                if ev[r][c] == 1:
                    a = (r, c)
                    b = (r + 1, c)
                    dsu_union(a, b)
                    deg_on[r][c] += 1
                    deg_on[r + 1][c] += 1

    def would_create_small_cycle(u, v):
        # If adding edge connects two nodes already connected, it creates a cycle.
        # It's allowed only if it completes the final loop (i.e., all used vertices have degree 2 and no other edges unknown needed).
        if dsu_find(u) != dsu_find(v):
            return False
        return True

    def count_on_edges():
        s = 0
        for r in range(H):
            for c in range(M):
                if eh[r][c] == 1:
                    s += 1
        for r in range(N):
            for c in range(W):
                if ev[r][c] == 1:
                    s += 1
        return s

    def all_constraints_ok():
        # Degree feasibility
        for r in range(H):
            for c in range(W):
                on, unk, tot = dot_deg_status(r, c)
                if on > 2:
                    return False
                if on == 1 and unk == 0:
                    return False
        # Clue local and length
        for pos in clues:
            if not clue_local_turn_straight_constraints(pos):
                return False
            if not clue_length_sum_constraints(pos):
                return False
        return True

    def propagate():
        nonlocal changed
        # Iterative constraint propagation
        for _ in range(10000):
            changed = False
            # Dot degree rules everywhere
            for r in range(H):
                for c in range(W):
                    if not force_dot_degree_rules(r, c):
                        return False
            # Clue rules
            for pos in clues:
                if not clue_local_turn_straight_constraints(pos):
                    return False
            # Rebuild DSU and degrees and add anti-small-cycle where forced edge would close early
            rebuild_dsu_and_degrees()
            # If an unknown edge would create a cycle while there exist other vertices that could still be used,
            # we don't always forbid it, but we can if both endpoints currently have deg_on==1 (would close component into cycle).
            # We'll add a safe pruning: if adding edge creates a cycle and there exists any dot with deg_on==1 or unknown edges,
            # then it's premature unless it would also ensure all used dots degree 2 and no other ON components exist.
            # We'll instead use as branching heuristic rather than hard forbid in propagation.
            # Length sum feasibility check
            for pos in clues:
                if not clue_length_sum_constraints(pos):
                    return False
            if not changed:
                break
        return True

    def is_solved():
        # All edges decided and form single loop through all clues with correct degree 2 at clue dots?
        for r in range(H):
            for c in range(M):
                if eh[r][c] == -1:
                    return False
        for r in range(N):
            for c in range(W):
                if ev[r][c] == -1:
                    return False
        # degrees must be 0 or 2, and at least one edge on
        total_on = count_on_edges()
        if total_on == 0:
            return False
        used = []
        for r in range(H):
            for c in range(W):
                on, _, _ = dot_deg_status(r, c)
                if on not in (0, 2):
                    return False
                if on == 2:
                    used.append((r, c))
        # single connected component among used vertices
        rebuild_dsu_and_degrees()
        roots = {dsu_find(v) for v in used}
        if len(roots) != 1:
            return False
        # all clues must be on loop (degree 2)
        for (r, c) in clues:
            if dot_deg_status(r, c)[0] != 2:
                return False
        # clue length sums exactly satisfied
        if not check_all_clue_lengths_exact():
            return False
        return True

    def check_all_clue_lengths_exact():
        # With fully decided edges, compute exact lengths from each clue along its two required straight directions.
        for (r, c), (typ, k) in clues.items():
            st = line_dir_state_at_dot(r, c)
            on_dirs = [d for d, v in st.items() if v == 1]
            if len(on_dirs) != 2:
                return False
            if typ == "W":
                if axis(on_dirs[0]) != axis(on_dirs[1]):
                    return False
            else:
                if axis(on_dirs[0]) == axis(on_dirs[1]):
                    return False
            # compute exact lengths along each on direction until turn (i.e., next dot doesn't continue straight)
            lens = []
            for d in on_dirs:
                length = 0
                cr, cc = r, c
                while True:
                    nr, nc = cr + d[0], cc + d[1]
                    if not inb_dot(nr, nc):
                        break
                    e = get_edge((cr, cc), (nr, nc))
                    if edge_value(e) != 1:
                        break
                    length += 1
                    # at new dot, must continue straight along same axis for segment length
                    cr, cc = nr, nc
                    st2 = line_dir_state_at_dot(cr, cc)
                    if d not in st2 or st2[d] != 1:
                        break
                    # if dot is a turning point (its two on dirs are perpendicular), stop segment here
                    two = get_two_on_dirs_at_dot(cr, cc)
                    if two is None:
                        # should not happen if solved
                        break
                    if axis(two[0]) != axis(two[1]):
                        break
                    # still straight; continue
                lens.append(length)
            if sum(lens) != k:
                return False
        return True

    def snapshot():
        return (
            [row[:] for row in eh],
            [row[:] for row in ev],
        )

    def restore(snap):
        nonlocal eh, ev
        eh, ev = snap[0], snap[1]

    def list_unknown_edges():
        unk = []
        for r in range(H):
            for c in range(M):
                if eh[r][c] == -1:
                    unk.append(("h", r, c))
        for r in range(N):
            for c in range(W):
                if ev[r][c] == -1:
                    unk.append(("v", r, c))
        return unk

    def edge_endpoints(e):
        t, r, c = e
        if t == "h":
            return (r, c), (r, c + 1)
        else:
            return (r, c), (r + 1, c)

    def heuristic_pick_edge():
        # Choose edge with highest constraint impact:
        # - incident to clue
        # - incident to dot with on degree 1 (forced completion)
        # - would create cycle (risky)
        best = None
        best_score = -1
        rebuild_dsu_and_degrees()
        for e in list_unknown_edges():
            (a, b) = edge_endpoints(e)
            score = 0
            for (r, c) in (a, b):
                if (r, c) in clues:
                    score += 50
                on, unk, _ = dot_deg_status(r, c)
                if on == 1:
                    score += 20
                if on == 2:
                    score -= 100
                if unk == 1:
                    score += 10
            if would_create_small_cycle(a, b):
                score += 5
            # slight preference for edges adjacent to many clues by proximity
            if score > best_score:
                best_score = score
                best = e
        return best

    def dfs(limit_nodes=200000):
        nonlocal nodes
        if nodes > limit_nodes:
            return None
        nodes += 1
        if not propagate():
            return None
        if not all_constraints_ok():
            return None
        if is_solved():
            return build_loop_path()
        e = heuristic_pick_edge()
        if e is None:
            return None
        a, b = edge_endpoints(e)
        # Branch ordering: try ON first if it helps degrees/clues, but avoid premature cycles.
        order = [1, 0]
        rebuild_dsu_and_degrees()
        if would_create_small_cycle(a, b):
            # prefer OFF to avoid premature cycle unless forced by degrees/clues
            order = [0, 1]
        for val in order:
            snap = snapshot()
            ok = set_edge(e, val, "branch")
            if ok:
                res = dfs(limit_nodes)
                if res is not None:
                    return res
            restore(snap)
        return None

    def build_loop_path():
        # Extract the unique loop as ordered dots.
        # Build adjacency of ON edges
        adj = defaultdict(list)
        for r in range(H):
            for c in range(M):
                if eh[r][c] == 1:
                    a = (r, c)
                    b = (r, c + 1)
                    adj[a].append(b)
                    adj[b].append(a)
        for r in range(N):
            for c in range(W):
                if ev[r][c] == 1:
                    a = (r, c)
                    b = (r + 1, c)
                    adj[a].append(b)
                    adj[b].append(a)
        # pick start: any clue dot if possible, else any used dot
        start = next(iter(clues.keys()), None)
        if start is None or len(adj[start]) == 0:
            start = None
            for k, v in adj.items():
                if v:
                    start = k
                    break
        if start is None:
            return "No Solution"
        # traverse
        path = [start]
        prev = None
        cur = start
        for _ in range((H * W) * 4 + 10):
            nbrs = adj[cur]
            if len(nbrs) != 2:
                return "No Solution"
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
        if path[-1] != start:
            return "No Solution"
        return path

    # Initial quick pruning: boundary dots cannot have degree 2 if only 2 incident edges, still ok.
    # Run search
    nodes = 0
    res = dfs()
    return res if res is not None else "No Solution"


