# Solver for "Dot loop with length clues" as described:
# - Single closed loop on edges of (N+1)x(N+1) dot grid, no crossings, no branches (degree 0 or 2 at each dot).
# - Clues are placed at grid vertices (dots): token 'Wk' or 'Bk'
#   * W: loop goes straight through the vertex (degree 2 with opposite edges)
#   * B: loop turns at the vertex (degree 2 with perpendicular edges)
#   * k equals sum of lengths of the two straight segments extending from that vertex along the loop
#     (each segment extends from the vertex in each of the two incident directions until the next turn
#      or endpoint; but since it's a loop, endpoints are turns/straight changes).
#
# This implementation is a constraint propagation + backtracking solver:
# - Edge variables: each undirected unit edge between neighboring dots is {0,1}.
# - Vertex degree constraints: degree in {0,2} globally; at clue vertices degree must be 2 with shape (W or B).
# - Segment-length constraints for clue vertices: computed based on turns/straight vertices along each direction.
#   Enforced by incremental "ray reasoning": for each clue, for each of its two incident directions, the next
#   "event" vertex must be a turn (for W) or straight (for B) as appropriate; length is distance to that event.
#
# Human-like deductions implemented:
# 1) Local vertex shape forcing for W/B clues and for degree saturation.
# 2) No premature small cycles: union-find with cycle check unless it's the final loop using all used vertices.
# 3) Segment length feasibility bounds for each clue using min/max possible extension given current undecided edges.
# 4) Propagation of forced edges from degree constraints (if a vertex already has 2 ON, rest OFF; if has 1 ON and only
#    one candidate left to reach degree 2 when required, force it; etc.)
# 5) Ray-based pruning: given a clue and a chosen outgoing direction, we can bound where the next turn/straight can occur.
#
# Note: Clues on vertices implies the loop must pass through all clue dots.

from __future__ import annotations
from dataclasses import dataclass
from typing import List, Tuple, Dict, Optional, Set

Coord = Tuple[int, int]

# Directions: U,D,L,R
DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]
DIR_IDX = {(-1,0):0, (1,0):1, (0,-1):2, (0,1):3}
OPP = {0:1, 1:0, 2:3, 3:2}

def addc(a: Coord, d: int) -> Coord:
    dr, dc = DIRS[d]
    return (a[0] + dr, a[1] + dc)

def inb(r: int, c: int, n: int) -> bool:
    return 0 <= r <= n and 0 <= c <= n

def edge_key(a: Coord, b: Coord) -> Tuple[Coord, Coord]:
    return (a, b) if a <= b else (b, a)

def is_adj(a: Coord, b: Coord) -> bool:
    return abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1

@dataclass
class Clue:
    kind: str  # 'W' or 'B'
    k: int

class UnionFind:
    __slots__ = ("p","r","sz","edges")
    def __init__(self, n: int):
        self.p = list(range(n))
        self.r = [0]*n
        self.sz = [1]*n
        self.edges = [0]*n  # number of ON edges within component (counts edges, not half-edges)

    def find(self, x: int) -> int:
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x

    def union_edge(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            self.edges[ra] += 1
            return False
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        self.sz[ra] += self.sz[rb]
        self.edges[ra] += self.edges[rb] + 1
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1
        return True

    def comp_size(self, x: int) -> int:
        return self.sz[self.find(x)]

    def comp_edges(self, x: int) -> int:
        return self.edges[self.find(x)]

class State:
    __slots__ = (
        "n","clues","E","adj_edges","deg_on","deg_off","uf",
        "used_vertices","must_degree2","trail","edge_list","edge_index"
    )
    def __init__(self, n: int, clues: Dict[Coord, Clue]):
        self.n = n
        self.clues = clues
        # Edge variables: map edge_key -> -1 unknown, 0 off, 1 on
        self.E: Dict[Tuple[Coord,Coord], int] = {}
        self.adj_edges: Dict[Coord, List[Tuple[Coord,Coord, int]]] = {}
        # degree counts for each vertex
        self.deg_on: Dict[Coord, int] = {}
        self.deg_off: Dict[Coord, int] = {}
        # UF over vertices indices 0..(n+1)^2-1
        self.uf = UnionFind((n+1)*(n+1))
        self.used_vertices: Set[Coord] = set()
        # vertices that must be in loop (all clues)
        self.must_degree2: Set[Coord] = set(clues.keys())
        # assignment trail for backtracking: list of (edge, old_value, uf_snapshot?, deg changes)
        self.trail: List[Tuple[Tuple[Coord,Coord], int, Tuple[int,int,int,int,int,int]]] = []
        # Prebuild all edges and adjacency
        self.edge_list: List[Tuple[Coord,Coord]] = []
        self.edge_index: Dict[Tuple[Coord,Coord], int] = {}
        self._init_graph()

    def _init_graph(self):
        n = self.n
        for r in range(n+1):
            for c in range(n+1):
                v = (r,c)
                self.deg_on[v] = 0
                self.deg_off[v] = 0
                self.adj_edges[v] = []
        # create undirected unit edges (right and down)
        for r in range(n+1):
            for c in range(n+1):
                a = (r,c)
                if c < n:
                    b = (r,c+1)
                    ek = edge_key(a,b)
                    self.E[ek] = -1
                    self.edge_index[ek] = len(self.edge_list)
                    self.edge_list.append(ek)
                    self.adj_edges[a].append((ek[0], ek[1], self._dir_from_to(a,b)))
                    self.adj_edges[b].append((ek[0], ek[1], self._dir_from_to(b,a)))
                if r < n:
                    b = (r+1,c)
                    ek = edge_key(a,b)
                    self.E[ek] = -1
                    self.edge_index[ek] = len(self.edge_list)
                    self.edge_list.append(ek)
                    self.adj_edges[a].append((ek[0], ek[1], self._dir_from_to(a,b)))
                    self.adj_edges[b].append((ek[0], ek[1], self._dir_from_to(b,a)))

    def _dir_from_to(self, a: Coord, b: Coord) -> int:
        dr = b[0]-a[0]
        dc = b[1]-a[1]
        return DIR_IDX[(dr,dc)]

    def v_id(self, v: Coord) -> int:
        return v[0]*(self.n+1) + v[1]

    def edge_val(self, ek: Tuple[Coord,Coord]) -> int:
        return self.E[ek]

    def other(self, ek: Tuple[Coord,Coord], v: Coord) -> Coord:
        a,b = ek
        return b if v==a else a

    def set_edge(self, ek: Tuple[Coord,Coord], val: int) -> bool:
        # returns False if contradiction
        cur = self.E[ek]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        a,b = ek
        # snapshot UF roots and ranks? We'll do reversible UF by saving parent/rank/size/edges for involved roots.
        # Since UF is not natively reversible, we will implement "poor man's" snapshots by storing changed fields for roots.
        # We only union on ON edges; OFF edges don't touch UF.
        # We'll store: (a_root, a_parent, a_rank, a_sz, a_edges, b_root, b_parent, b_rank, b_sz, b_edges, did_union_flag)
        # but in cycle case, only edges increment, root same.
        uf = self.uf
        snap = (-1,-1,-1,-1,-1,-1)  # compact later
        # record old degree counts for endpoints to restore
        old_deg_on_a = self.deg_on[a]
        old_deg_on_b = self.deg_on[b]
        old_deg_off_a = self.deg_off[a]
        old_deg_off_b = self.deg_off[b]

        # store UF snapshot for both roots (and possibly parent changes) in a fixed tuple of 6 ints referencing packed index into arrays?
        # We'll just store a custom packed snapshot of arrays at roots and also parent of rootB if union.
        uf_before = None
        if val == 1:
            ra, rb = uf.find(self.v_id(a)), uf.find(self.v_id(b))
            # capture root states
            uf_before = (ra, uf.p[ra], uf.r[ra], uf.sz[ra], uf.edges[ra],
                         rb, uf.p[rb], uf.r[rb], uf.sz[rb], uf.edges[rb])
            # apply union_edge which can modify p/r/sz/edges
            uf.union_edge(self.v_id(a), self.v_id(b))
        # set edge
        self.E[ek] = val
        # update degree counts
        if val == 1:
            self.deg_on[a] += 1
            self.deg_on[b] += 1
            self.used_vertices.add(a); self.used_vertices.add(b)
        else:
            self.deg_off[a] += 1
            self.deg_off[b] += 1

        # push trail entry
        self.trail.append((ek, cur, (old_deg_on_a, old_deg_on_b, old_deg_off_a, old_deg_off_b, 1 if uf_before else 0, 0)))
        # store uf_before in a side dict keyed by trail index using negative trick: keep in attribute dict? not allowed.
        # We'll encode uf_before by appending to trail as a special entry when needed.
        if uf_before is not None:
            self.trail.append((ek, -2, uf_before))  # -2 marks UF snapshot record

        # check immediate local contradictions
        if not self._check_vertex(a) or not self._check_vertex(b):
            return False
        return True

    def undo(self, trail_len: int):
        uf = self.uf
        while len(self.trail) > trail_len:
            ek, old, info = self.trail.pop()
            if old == -2:
                # restore UF snapshot
                ra, pa, rka, sza, ea, rb, pb, rkb, szb, eb = info
                uf.p[ra] = pa; uf.r[ra] = rka; uf.sz[ra] = sza; uf.edges[ra] = ea
                uf.p[rb] = pb; uf.r[rb] = rkb; uf.sz[rb] = szb; uf.edges[rb] = eb
                continue
            # restore edge value and degrees (for its endpoints)
            a,b = ek
            self.E[ek] = old
            old_deg_on_a, old_deg_on_b, old_deg_off_a, old_deg_off_b, _, _ = info
            self.deg_on[a] = old_deg_on_a
            self.deg_on[b] = old_deg_on_b
            self.deg_off[a] = old_deg_off_a
            self.deg_off[b] = old_deg_off_b
            # used_vertices set is not reverted precisely; rebuild lazily when needed
        # Rebuild used_vertices accurately (cheap enough)
        self.used_vertices = set()
        for ek2,v in self.E.items():
            if v == 1:
                self.used_vertices.add(ek2[0]); self.used_vertices.add(ek2[1])

    def _check_vertex(self, v: Coord) -> bool:
        on = self.deg_on[v]
        # max degree is 4
        if on > 2:
            return False
        # if clue, must be degree 2 eventually
        unk = 4 - on - self.deg_off[v]
        if v in self.must_degree2:
            if on + unk < 2:
                return False
            if on > 2:
                return False
        else:
            # non-clue: degree can be 0 or 2
            if on == 1 and unk == 0:
                return False
        return True

    def incident_edges(self, v: Coord) -> List[Tuple[Tuple[Coord,Coord], int]]:
        res = []
        for a,b,d in self.adj_edges[v]:
            ek = (a,b)
            res.append((ek,d))
        return res

    def shape_status(self, v: Coord) -> Optional[Tuple[int,int]]:
        # If degree 2 fixed, return the two direction indices used by ON edges; else None
        if self.deg_on[v] != 2:
            return None
        dirs = []
        for ek,d in self.incident_edges(v):
            if self.E[ek] == 1:
                dirs.append(d)
        if len(dirs) != 2:
            return None
        return (dirs[0], dirs[1])

def parse_observation(observation) -> Tuple[int, Dict[Coord, Clue]]:
    data = observation["data"]
    n = len(data)-1
    clues: Dict[Coord, Clue] = {}
    for r,row in enumerate(data):
        for c,tok in enumerate(row):
            if tok is None:
                continue
            kind = tok[0].upper()
            k = int(tok[1:])
            clues[(r,c)] = Clue(kind, k)
    return n, clues

def solve(observation):
    n, clues = parse_observation(observation)
    st = State(n, clues)

    # Pre-force: all clue vertices must have degree 2 => disallow degree 0; handled by propagation
    # Also apply immediate impossibility bounds for k: must be >=2 (since two segments at least length 1 each)
    for v,cl in clues.items():
        if cl.k < 2:
            return "No Solution"

    def propagate() -> bool:
        # Repeat until fixpoint
        changed = True
        while changed:
            changed = False

            # Degree/shape propagation at each vertex
            for r in range(n+1):
                for c in range(n+1):
                    v = (r,c)
                    on = st.deg_on[v]
                    off = st.deg_off[v]
                    unk_edges = []
                    on_dirs = []
                    for ek,d in st.incident_edges(v):
                        val = st.edge_val(ek)
                        if val == -1:
                            unk_edges.append((ek,d))
                        elif val == 1:
                            on_dirs.append(d)
                    unk = len(unk_edges)

                    if on > 2:
                        return False
                    if on + unk < 2 and v in st.must_degree2:
                        return False
                    if unk == 0:
                        # if non-clue, degree must be 0 or 2
                        if v not in st.must_degree2 and on == 1:
                            return False
                    # If on==2: remaining unknown must be OFF
                    if on == 2 and unk > 0:
                        for ek,_ in unk_edges:
                            if st.edge_val(ek) == -1:
                                if not st.set_edge(ek, 0):
                                    return False
                                changed = True
                        continue

                    # If clue vertex and only enough unknown to reach degree 2: force ONs
                    if v in st.must_degree2:
                        if on < 2 and on + unk == 2:
                            for ek,_ in unk_edges:
                                if st.edge_val(ek) == -1:
                                    if not st.set_edge(ek, 1):
                                        return False
                                    changed = True
                            continue

                    # If non-clue and on==1, must become degree 2 (can't end) => if only 1 unknown, force it ON
                    if v not in st.must_degree2 and on == 1:
                        if unk == 0:
                            return False
                        if unk == 1:
                            ek,_ = unk_edges[0]
                            if not st.set_edge(ek, 1):
                                return False
                            changed = True
                            continue

                    # Shape constraints for clue vertices when degree 2 is decided or partially decided
                    if v in clues:
                        cl = clues[v]
                        # if degree 2 known, enforce straight/turn
                        if on == 2:
                            if len(on_dirs) != 2:
                                return False
                            d1,d2 = on_dirs[0], on_dirs[1]
                            straight = (OPP[d1] == d2)
                            if cl.kind == 'W' and not straight:
                                return False
                            if cl.kind == 'B' and straight:
                                return False
                        # if one ON edge known, we can sometimes force second edge set based on kind:
                        # - For W: second edge must be opposite direction (if available)
                        # - For B: second edge must be perpendicular (cannot be opposite)
                        if on == 1 and unk > 0:
                            d_on = on_dirs[0]
                            if cl.kind == 'W':
                                need = OPP[d_on]
                                # all other directions must be OFF; need must be ON if possible
                                for ek,d in unk_edges:
                                    if d == need:
                                        # if this edge cannot exist (border), it won't be in unk_edges
                                        if not st.set_edge(ek, 1):
                                            return False
                                        changed = True
                                    else:
                                        if not st.set_edge(ek, 0):
                                            return False
                                        changed = True
                            else:  # 'B'
                                # opposite must be OFF if unknown
                                opp = OPP[d_on]
                                for ek,d in unk_edges:
                                    if d == opp:
                                        if not st.set_edge(ek, 0):
                                            return False
                                        changed = True

            # Segment-length feasibility checks for each clue (bounds + some forcing)
            for v,cl in clues.items():
                if not segment_feasible(v, cl):
                    return False

        return True

    def next_event_bound(start: Coord, d: int, expect_event: str) -> Tuple[int,int]:
        # Walk along direction d; each step crosses an edge; vertices encountered decide when the "event" happens.
        # expect_event: 'TURN' meaning next vertex where path turns (degree2 with perpendicular), or where it MUST turn.
        #              'STRAIGHT' meaning next vertex where path goes straight (degree2 with opposite)
        # Return (min_len, max_len) possible until the event, given partial assignments.
        # Conservative bounds: use edge unknown/on and vertex constraints.
        cur = start
        length = 0
        min_len = None
        max_len = 0
        # maximum possible steps until border
        while True:
            nxt = addc(cur, d)
            if not inb(nxt[0], nxt[1], n):
                break
            ek = edge_key(cur, nxt)
            val = st.edge_val(ek)
            if val == 0:
                break  # cannot proceed
            length += 1
            cur = nxt
            # At vertex cur, if the loop passes through (degree2), it either continues straight or turns.
            # Event depends on shape.
            sh = st.shape_status(cur)
            if sh is not None:
                d1,d2 = sh
                is_straight = (OPP[d1]==d2)
                is_turn = not is_straight
                if expect_event == 'TURN' and is_turn:
                    min_len = max_len = length
                    return (min_len, max_len)
                if expect_event == 'STRAIGHT' and is_straight:
                    min_len = max_len = length
                    return (min_len, max_len)
                # If fixed opposite of d is not among {d1,d2}, then path cannot have arrived from prev; but
                # since edges may still be inconsistent, we'll detect later. Here just continue if possible.
            # If clue at cur forces shape:
            if cur in clues:
                kind = clues[cur].kind
                if kind == 'W':
                    # straight through if degree2; if degree2 not yet, but if edge from prev is ON, forces opposite ON.
                    # For event detection, W is STRAIGHT vertex when resolved.
                    if expect_event == 'STRAIGHT':
                        # could be this if it becomes degree2; min could be length if it must be used
                        pass
                else:
                    if expect_event == 'TURN':
                        pass
            max_len = length
        # If no determined event, min_len is the earliest possible length where an event could occur; if unknown, 1
        if min_len is None:
            min_len = 1
        return (min_len, max_len)

    def segment_feasible(v: Coord, cl: Clue) -> bool:
        # If the two incident directions at v are not fully decided, we only enforce feasibility bounds.
        on_dirs = []
        unk_dirs = []
        for ek,d in st.incident_edges(v):
            val = st.edge_val(ek)
            if val == 1:
                on_dirs.append(d)
            elif val == -1:
                unk_dirs.append(d)
        on = len(on_dirs)
        if on > 2:
            return False
        if on + len(unk_dirs) < 2:
            return False

        # Determine possible pairs of directions consistent with kind and current assignments.
        dirs = [d for d in on_dirs] + [d for d in unk_dirs]
        # candidates are pairs (dA,dB)
        cand = []
        all_dirs = set(on_dirs) | set(unk_dirs)
        # if on==2 then fixed
        if on == 2:
            cand = [tuple(sorted(on_dirs))]
        else:
            ds = sorted(all_dirs)
            for i in range(len(ds)):
                for j in range(i+1,len(ds)):
                    d1,d2 = ds[i], ds[j]
                    if on == 1 and (d1 not in on_dirs and d2 not in on_dirs):
                        continue
                    straight = (OPP[d1]==d2)
                    if cl.kind == 'W' and not straight:
                        continue
                    if cl.kind == 'B' and straight:
                        continue
                    # must be compatible with border edges existence (already ensured by adjacency)
                    cand.append((d1,d2))
        if not cand:
            return False

        # For each candidate, compute possible sum length bounds based on rays.
        feasible = False
        for d1,d2 in cand:
            # segment extends from v in direction d until next event:
            # - If vertex is W (straight), event is a TURN on each side.
            # - If vertex is B (turn), event is a STRAIGHT on each side.
            expect = 'TURN' if cl.kind == 'W' else 'STRAIGHT'
            mn1,mx1 = next_event_bound(v, d1, expect)
            mn2,mx2 = next_event_bound(v, d2, expect)
            if mn1 + mn2 <= cl.k <= mx1 + mx2:
                feasible = True
                break
        return feasible

    def choose_edge() -> Optional[Tuple[Coord,Coord]]:
        # Heuristic: pick an unknown edge that is adjacent to a clue or to a vertex with degree pressure.
        best = None
        best_score = -1
        for ek in st.edge_list:
            if st.edge_val(ek) != -1:
                continue
            a,b = ek
            score = 0
            if a in clues or b in clues:
                score += 5
            # degree pressure
            for v in (a,b):
                on = st.deg_on[v]
                unk = 4 - on - st.deg_off[v]
                if v in st.must_degree2:
                    if on == 1:
                        score += 4
                    if on == 0 and unk == 2:
                        score += 3
                else:
                    if on == 1:
                        score += 2
            if score > best_score:
                best_score = score
                best = ek
        return best

    def is_solved() -> bool:
        # All edges decided and exactly one loop including all clue vertices.
        for v in st.E.values():
            if v == -1:
                return False
        # degree check and clue pass
        for r in range(n+1):
            for c in range(n+1):
                v = (r,c)
                on = st.deg_on[v]
                if v in st.must_degree2:
                    if on != 2:
                        return False
                else:
                    if on not in (0,2):
                        return False
        # must be single component for used vertices
        used = [v for v in st.used_vertices]
        if not used:
            return False
        root = st.uf.find(st.v_id(used[0]))
        for v in used[1:]:
            if st.uf.find(st.v_id(v)) != root:
                return False
        # all used vertices degree2 => edges == vertices in component
        comp_edges = st.uf.comp_edges(st.v_id(used[0]))
        comp_size = st.uf.comp_size(st.v_id(used[0]))
        if comp_edges != comp_size:
            return False
        # all clue vertices are used
        for v in st.must_degree2:
            if v not in st.used_vertices:
                return False
        return True

    def dfs() -> bool:
        if not propagate():
            return False
        if is_solved():
            return True
        ek = choose_edge()
        if ek is None:
            return False
        # Try ON then OFF (often ON is more constrained)
        for val in (1,0):
            tlen = len(st.trail)
            if st.set_edge(ek, val):
                # Prevent forming a small cycle early: if set ON creates a cycle in a component that is not complete
                # with all must vertices and no undecided edges to connect others, it can still be okay; use basic check:
                if val == 1:
                    # if component forms a cycle (edges==vertices) but there remain other used vertices outside -> invalid
                    a,b = ek
                    ra = st.uf.find(st.v_id(a))
                    comp_edges = st.uf.edges[ra]
                    comp_size = st.uf.sz[ra]
                    if comp_edges == comp_size:
                        # if there are any must vertices not in this component -> invalid
                        for mv in st.must_degree2:
                            if st.uf.find(st.v_id(mv)) != ra:
                                st.undo(tlen)
                                break
                        else:
                            # ok (could be final), but ensure no other used vertices outside
                            for uv in st.used_vertices:
                                if st.uf.find(st.v_id(uv)) != ra:
                                    st.undo(tlen)
                                    break
                            else:
                                if dfs():
                                    return True
                                st.undo(tlen)
                                continue
                        continue
                if dfs():
                    return True
            st.undo(tlen)
        return False

    if not dfs():
        return "No Solution"

    # Build ordered loop path from ON edges
    # pick any used vertex and traverse
    start = next(iter(st.used_vertices))
    # build adjacency of ON edges
    adj: Dict[Coord, List[Coord]] = {v: [] for v in st.used_vertices}
    for ek,val in st.E.items():
        if val == 1:
            a,b = ek
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
    # traverse
    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = adj[cur]
        if len(nbrs) != 2:
            return "No Solution"
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
        if len(path) > (n+1)*(n+1)*4:
            return "No Solution"
    return str(path)

