# NOTE: The image includes some numbered black cells, but this literal observation uses -1 for all black cells.
# The solver below fully supports numbered blacks (0..4) when present in OBSERVATION['data'].

from collections import deque

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"

    # Cell types:
    #   white: grid[r][c] is None
    #   black: grid[r][c] is -1 or 0..4 (numbered black)
    # We decide bulbs only on white.

    WHITE = 0
    BLACK = 1

    is_black = [[grid[r][c] is not None for c in range(n)] for r in range(n)]
    blk_num = [[grid[r][c] if isinstance(grid[r][c], int) and grid[r][c] >= 0 else None for c in range(n)] for r in range(n)]

    # Precompute segments (continuous white runs) for rows and cols.
    row_seg_id = [[-1]*n for _ in range(n)]
    col_seg_id = [[-1]*n for _ in range(n)]
    row_segs = []  # list of list of (r,c)
    col_segs = []
    for r in range(n):
        c = 0
        while c < n:
            if is_black[r][c]:
                c += 1
                continue
            start = c
            cells = []
            while c < n and not is_black[r][c]:
                cells.append((r, c))
                c += 1
            sid = len(row_segs)
            row_segs.append(cells)
            for (rr, cc) in cells:
                row_seg_id[rr][cc] = sid
    for c in range(n):
        r = 0
        while r < n:
            if is_black[r][c]:
                r += 1
                continue
            start = r
            cells = []
            while r < n and not is_black[r][c]:
                cells.append((r, c))
                r += 1
            sid = len(col_segs)
            col_segs.append(cells)
            for (rr, cc) in cells:
                col_seg_id[rr][cc] = sid

    # Map each cell to the set of cells it illuminates including itself along row/col until black.
    # Efficient: illumination set = row segment union col segment (minus self duplicate).
    # For conflict checking, bulbs cannot share row segment or col segment (same segment => see each other).
    # That is exact because segments are bounded by black cells.
    whites = [(r,c) for r in range(n) for c in range(n) if not is_black[r][c]]
    W = len(whites)
    idx_of = {rc:i for i,rc in enumerate(whites)}

    cell_row_seg = [0]*W
    cell_col_seg = [0]*W
    for i,(r,c) in enumerate(whites):
        cell_row_seg[i] = row_seg_id[r][c]
        cell_col_seg[i] = col_seg_id[r][c]

    # For coverage constraints: each white must be illuminated by at least one bulb.
    # A bulb at i illuminates all cells in its row/col segment.
    illum_list = [None]*W
    for i,(r,c) in enumerate(whites):
        rs = row_segs[cell_row_seg[i]]
        cs = col_segs[cell_col_seg[i]]
        s = set()
        for rc in rs: s.add(idx_of[rc])
        for rc in cs: s.add(idx_of[rc])
        illum_list[i] = tuple(s)

    # For each white cell v, list candidate bulb positions that can illuminate it:
    illum_by = [[] for _ in range(W)]
    for b in range(W):
        for v in illum_list[b]:
            illum_by[v].append(b)

    # Numbered black adjacency constraints.
    # Build list of numbered blacks with their adjacent white indices.
    numbered = []
    for r in range(n):
        for c in range(n):
            k = blk_num[r][c]
            if k is None:
                continue
            adj = []
            for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                rr,cc = r+dr, c+dc
                if 0 <= rr < n and 0 <= cc < n and not is_black[rr][cc]:
                    adj.append(idx_of[(rr,cc)])
            numbered.append((r,c,k,tuple(adj)))

    # State:
    #  assign[i] in {-1 unknown, 0 no bulb, 1 bulb}
    assign = [-1]*W

    # Segment occupancy: at most one bulb per row segment and per col segment.
    row_seg_bulb = [-1]*len(row_segs)  # store bulb index placed, else -1
    col_seg_bulb = [-1]*len(col_segs)

    # Coverage tracking: lit[v] bool
    lit = [False]*W
    unlit_count = W

    # For numbered blacks tracking:
    # for each numbered constraint j: need = k; adj list; placed count; undecided count
    nb_need = []
    nb_adj = []
    nb_placed = []
    nb_undec = []
    for (_,_,k,adj) in numbered:
        nb_need.append(k)
        nb_adj.append(adj)
        nb_placed.append(0)
        nb_undec.append(len(adj))

    # For fast update of which numbered constraints a cell participates in
    cell_to_nbs = [[] for _ in range(W)]
    for j,adj in enumerate(nb_adj):
        for i in adj:
            cell_to_nbs[i].append(j)

    # Trail for backtracking
    trail = []

    def mark_lit_from_bulb(bi, newval=True):
        # add lighting for bulb bi; return list of cells newly lit for undo
        newly = []
        nonlocal unlit_count
        for v in illum_list[bi]:
            if not lit[v]:
                lit[v] = True
                newly.append(v)
                unlit_count -= 1
        return newly

    def unmark_lit(newly):
        nonlocal unlit_count
        for v in newly:
            lit[v] = False
            unlit_count += 1

    def set_assign(i, val):
        # returns False if contradiction
        if assign[i] == val:
            return True
        if assign[i] != -1 and assign[i] != val:
            return False
        # record previous
        trail.append(("a", i, -1))
        assign[i] = val

        # Update numbered black counts
        for j in cell_to_nbs[i]:
            # record before
            trail.append(("nb", j, nb_placed[j], nb_undec[j]))
            if val == 1:
                nb_placed[j] += 1
            nb_undec[j] -= 1

        if val == 1:
            # segment constraints: no other bulb in same row/col segment
            rs = cell_row_seg[i]
            cs = cell_col_seg[i]
            if row_seg_bulb[rs] != -1 and row_seg_bulb[rs] != i:
                return False
            if col_seg_bulb[cs] != -1 and col_seg_bulb[cs] != i:
                return False
            trail.append(("rs", rs, row_seg_bulb[rs]))
            trail.append(("cs", cs, col_seg_bulb[cs]))
            row_seg_bulb[rs] = i
            col_seg_bulb[cs] = i

            # light updates
            newly = mark_lit_from_bulb(i)
            trail.append(("lit", newly))
        return True

    def undo(to_size):
        while len(trail) > to_size:
            typ, *rest = trail.pop()
            if typ == "a":
                i, prev = rest
                assign[i] = prev
            elif typ == "nb":
                j, p, u = rest
                nb_placed[j] = p
                nb_undec[j] = u
            elif typ == "rs":
                rs, prev = rest
                row_seg_bulb[rs] = prev
            elif typ == "cs":
                cs, prev = rest
                col_seg_bulb[cs] = prev
            elif typ == "lit":
                newly = rest[0]
                unmark_lit(newly)
            else:
                raise RuntimeError("bad trail")

    # Deduction rules (human-like):
    # 1) Numbered black: if placed == need => all remaining adj must be 0
    # 2) Numbered black: if placed + undec == need => all remaining adj must be 1
    # 3) For any unlit cell v: if only one possible bulb remains (considering forbidden/assigned) => force it
    # 4) Segment: if a bulb is placed in a segment, all other cells in that row/col segment cannot be bulbs (implicit via rs/cs occupancy checks on placement; we can also proactively set them 0 for stronger propagation)
    #    We'll do proactive forbidding: when bulb placed, set all other cells sharing row seg or col seg to 0.

    # Precompute cells per segment as indices
    row_seg_cells = []
    for seg in row_segs:
        row_seg_cells.append([idx_of[rc] for rc in seg])
    col_seg_cells = []
    for seg in col_segs:
        col_seg_cells.append([idx_of[rc] for rc in seg])

    def propagate():
        q = deque()
        # Seed with all numbered constraints and all unlit cells
        for j in range(len(nb_need)):
            q.append(("nb", j))
        for v in range(W):
            if not lit[v]:
                q.append(("ul", v))

        while q:
            typ, x = q.popleft()
            if typ == "nb":
                j = x
                need = nb_need[j]
                placed = nb_placed[j]
                undec = nb_undec[j]
                if placed > need:
                    return False
                if placed + undec < need:
                    return False
                if undec == 0:
                    continue
                if placed == need:
                    # force remaining undecided adj to 0
                    for i in nb_adj[j]:
                        if assign[i] == -1:
                            t0 = len(trail)
                            if not set_assign(i, 0):
                                return False
                            # new assignment impacts related constraints and might create new unlit singleton
                            for jj in cell_to_nbs[i]:
                                q.append(("nb", jj))
                            # for any unlit cell that could be illuminated by i (if i was only candidate, etc.) - handled by ul checks
                            # we enqueue the cell itself if still unlit
                            if not lit[i]:
                                q.append(("ul", i))
                elif placed + undec == need:
                    # force remaining undecided adj to 1
                    for i in nb_adj[j]:
                        if assign[i] == -1:
                            if not set_assign(i, 1):
                                return False
                            # proactive forbidding on segments due to bulb
                            rs = cell_row_seg[i]
                            cs = cell_col_seg[i]
                            for k in row_seg_cells[rs]:
                                if k != i and assign[k] == -1:
                                    if not set_assign(k, 0):
                                        return False
                                    for jj in cell_to_nbs[k]:
                                        q.append(("nb", jj))
                                    if not lit[k]:
                                        q.append(("ul", k))
                            for k in col_seg_cells[cs]:
                                if k != i and assign[k] == -1:
                                    if not set_assign(k, 0):
                                        return False
                                    for jj in cell_to_nbs[k]:
                                        q.append(("nb", jj))
                                    if not lit[k]:
                                        q.append(("ul", k))
                            # updates
                            for jj in cell_to_nbs[i]:
                                q.append(("nb", jj))
                            # cells newly lit might remove ul pressure; we'll just allow redundant checks
                            for v in illum_list[i]:
                                if not lit[v]:
                                    q.append(("ul", v))
            else:  # "ul"
                v = x
                if lit[v]:
                    continue
                # Determine feasible bulbs that could illuminate v
                feas = []
                for b in illum_by[v]:
                    if assign[b] == 0:
                        continue
                    # If assign[b]==1 it's already a bulb: then v would be lit; but it's not, so cannot happen
                    if assign[b] == 1:
                        return False
                    # Check segment availability if b were placed:
                    rs = cell_row_seg[b]
                    cs = cell_col_seg[b]
                    if row_seg_bulb[rs] != -1:
                        continue
                    if col_seg_bulb[cs] != -1:
                        continue
                    # Check numbered blacks feasibility if set to 1
                    ok = True
                    for j in cell_to_nbs[b]:
                        need = nb_need[j]
                        placed = nb_placed[j]
                        undec = nb_undec[j]
                        # if we place b, placed+1 must <= need; and (placed+1)+(undec-1) >= need
                        if placed + 1 > need:
                            ok = False
                            break
                        if placed + 1 + (undec - 1) < need:
                            ok = False
                            break
                    if ok:
                        feas.append(b)
                if not feas:
                    return False
                if len(feas) == 1:
                    b = feas[0]
                    if not set_assign(b, 1):
                        return False
                    # proactive forbidding on segments due to bulb
                    rs = cell_row_seg[b]
                    cs = cell_col_seg[b]
                    for k in row_seg_cells[rs]:
                        if k != b and assign[k] == -1:
                            if not set_assign(k, 0):
                                return False
                            for jj in cell_to_nbs[k]:
                                q.append(("nb", jj))
                            if not lit[k]:
                                q.append(("ul", k))
                    for k in col_seg_cells[cs]:
                        if k != b and assign[k] == -1:
                            if not set_assign(k, 0):
                                return False
                            for jj in cell_to_nbs[k]:
                                q.append(("nb", jj))
                            if not lit[k]:
                                q.append(("ul", k))
                    for jj in cell_to_nbs[b]:
                        q.append(("nb", jj))
                    # enqueue all cells lit by b (they are now lit; no need) but their neighbors' ul constraints might resolve; allow redundancy
                    for u in illum_list[b]:
                        q.append(("ul", u))
        return True

    def is_solved():
        if unlit_count != 0:
            return False
        # all numbered constraints satisfied
        for j in range(len(nb_need)):
            if nb_placed[j] != nb_need[j]:
                return False
        return True

    def pick_branch_var():
        # Heuristic: choose an unlit cell with smallest number of feasible bulb candidates (MRV on coverage),
        # then branch on placing a bulb among its candidates.
        best_v = -1
        best_cands = None

        for v in range(W):
            if lit[v]:
                continue
            feas = []
            for b in illum_by[v]:
                if assign[b] == 0:
                    continue
                if assign[b] == 1:
                    # would be lit, but v unlit => inconsistent; handled in propagate
                    continue
                rs = cell_row_seg[b]
                cs = cell_col_seg[b]
                if row_seg_bulb[rs] != -1 or col_seg_bulb[cs] != -1:
                    continue
                ok = True
                for j in cell_to_nbs[b]:
                    need = nb_need[j]
                    placed = nb_placed[j]
                    undec = nb_undec[j]
                    if placed + 1 > need or placed + 1 + (undec - 1) < need:
                        ok = False
                        break
                if ok:
                    feas.append(b)
            if not feas:
                return None, None
            if best_cands is None or len(feas) < len(best_cands):
                best_v = v
                best_cands = feas
                if len(best_cands) == 1:
                    break

        if best_cands is None:
            # all lit; but may still need to satisfy numbered blacks with extra bulbs.
            # Choose a cell adjacent to a numbered black that still needs bulbs.
            best_i = None
            best_score = -1
            for j in range(len(nb_need)):
                deficit = nb_need[j] - nb_placed[j]
                if deficit <= 0:
                    continue
                # pick undec adjacent cell
                for i in nb_adj[j]:
                    if assign[i] != -1:
                        continue
                    rs = cell_row_seg[i]; cs = cell_col_seg[i]
                    if row_seg_bulb[rs] != -1 or col_seg_bulb[cs] != -1:
                        continue
                    score = deficit
                    if score > best_score:
                        best_score = score
                        best_i = i
            if best_i is None:
                return -1, []
            return -2, [best_i]
        return best_v, best_cands

    def dfs():
        tsize = len(trail)
        if not propagate():
            undo(tsize)
            return False
        if is_solved():
            return True

        v, cands = pick_branch_var()
        if v is None:
            undo(tsize)
            return False
        if v == -1 and not cands:
            # all lit and no numbered deficits; should be solved but isn't => contradiction
            undo(tsize)
            return False

        # Branch ordering: try placing bulb (1) for a promising candidate, otherwise forbid it (0).
        # If branching on multiple candidates for unlit cell, try candidates with maximal additional coverage first.
        if v >= 0:
            cands.sort(key=lambda b: -sum(1 for u in illum_list[b] if not lit[u]))
            for b in cands:
                t2 = len(trail)
                if set_assign(b, 1):
                    # proactive forbidding in its segments
                    rs = cell_row_seg[b]; cs = cell_col_seg[b]
                    ok = True
                    for k in row_seg_cells[rs]:
                        if k != b and assign[k] == -1:
                            if not set_assign(k, 0):
                                ok = False
                                break
                    if ok:
                        for k in col_seg_cells[cs]:
                            if k != b and assign[k] == -1:
                                if not set_assign(k, 0):
                                    ok = False
                                    break
                    if ok and dfs():
                        return True
                undo(t2)
                # Also try forbidding this bulb if needed (only if multiple candidates)
                # But to avoid blow-up, forbid only if it doesn't immediately break coverage by making v impossible.
            # If none worked, fail.
            undo(tsize)
            return False
        else:
            # v == -2: pick specific cell to satisfy numbered deficit: branch bulb then no-bulb
            i = cands[0]
            # try bulb
            t2 = len(trail)
            if set_assign(i, 1):
                rs = cell_row_seg[i]; cs = cell_col_seg[i]
                ok = True
                for k in row_seg_cells[rs]:
                    if k != i and assign[k] == -1:
                        if not set_assign(k, 0):
                            ok = False
                            break
                if ok:
                    for k in col_seg_cells[cs]:
                        if k != i and assign[k] == -1:
                            if not set_assign(k, 0):
                                ok = False
                                break
                if ok and dfs():
                    return True
            undo(t2)
            # try no bulb
            t3 = len(trail)
            if set_assign(i, 0) and dfs():
                return True
            undo(t3)
            undo(tsize)
            return False

    if not dfs():
        return "No Solution"

    # Build answer grid: 'B' for bulbs, None otherwise (including black cells and empty whites)
    out = [[None]*n for _ in range(n)]
    for i,(r,c) in enumerate(whites):
        if assign[i] == 1:
            out[r][c] = 'B'
    return str(out)

