from collections import deque

# Takuzu / Binary Puzzle solver with strong human-like propagation + shallow backtracking.
# Symbols: 0 = B, 1 = W, -1 = unknown

B, W, U = 0, 1, -1

def solve(observation):
    grid0 = observation["data"]
    n = len(grid0)
    if n == 0 or any(len(r) != n for r in grid0) or (n % 2 != 0):
        return "No Solution"
    half = n // 2

    # Parse
    g = [[U]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = grid0[r][c]
            if v is None:
                continue
            if v == 'B':
                g[r][c] = B
            elif v == 'W':
                g[r][c] = W
            else:
                return "No Solution"

    # Precompute all valid full lines (rows/cols) for length n
    # Valid = exactly half B and half W, no 3 consecutive equal.
    valid_lines = []
    for mask in range(1 << n):
        if mask.bit_count() != half:
            continue
        ok = True
        prev2 = prev1 = None
        for i in range(n):
            bit = (mask >> i) & 1
            if prev2 is not None and prev2 == prev1 == bit:
                ok = False
                break
            prev2, prev1 = prev1, bit
        if ok:
            # represent as tuple of 0/1 with index 0..n-1
            line = tuple((mask >> i) & 1 for i in range(n))
            valid_lines.append(line)

    # For faster filtering, keep for each line pattern constraints -> possible lines computed on the fly.

    def row_tuple(r):
        return tuple(g[r])

    def col_tuple(c):
        return tuple(g[r][c] for r in range(n))

    def compatible(line_full, line_partial):
        # line_partial values in {0,1,-1}
        for i, v in enumerate(line_partial):
            if v != U and line_full[i] != v:
                return False
        return True

    def line_no_three_possible(partial):
        # quick local contradiction check: if any three consecutive are set and equal => impossible
        for i in range(n-2):
            a,b,c = partial[i], partial[i+1], partial[i+2]
            if a != U and a == b == c:
                return False
        return True

    def line_balance_possible(partial):
        # counts cannot exceed half; also remaining must be able to reach half
        cb = sum(1 for v in partial if v == B)
        cw = sum(1 for v in partial if v == W)
        if cb > half or cw > half:
            return False
        unk = partial.count(U)
        if cb + unk < half or cw + unk < half:
            return False
        return True

    def local_patterns_infer_line(partial):
        # Apply classic human rules:
        # 1) X X _ => X X must be followed by opposite
        # 2) _ X X => opposite before
        # 3) X _ X => middle opposite
        # plus balance fill if counts reached half.
        changed = []
        # patterns
        for i in range(n-2):
            a,b,c = partial[i], partial[i+1], partial[i+2]
            if a != U and a == b and c == U:
                changed.append((i+2, 1-a))
            if b != U and b == c and a == U:
                changed.append((i, 1-b))
            if a != U and c != U and a == c and b == U:
                changed.append((i+1, 1-a))
        # balance
        cb = sum(1 for v in partial if v == B)
        cw = sum(1 for v in partial if v == W)
        if cb == half:
            for i,v in enumerate(partial):
                if v == U:
                    changed.append((i, W))
        if cw == half:
            for i,v in enumerate(partial):
                if v == U:
                    changed.append((i, B))
        # Consolidate; if conflicts appear, signal with None
        if not changed:
            return {}
        out = {}
        for idx,val in changed:
            if idx in out and out[idx] != val:
                return None
            out[idx] = val
        return out

    def filter_candidates(partial):
        # Return list of valid full lines compatible with partial
        # Early pruning with basic checks.
        if not line_no_three_possible(partial) or not line_balance_possible(partial):
            return []
        # use local patterns to narrow partial further? not here
        return [ln for ln in valid_lines if compatible(ln, partial)]

    def derive_forced_from_candidates(partial, candidates):
        # For each position, if all candidates have same bit, force it
        forced = {}
        if not candidates:
            return forced
        for i in range(n):
            if partial[i] != U:
                continue
            v0 = candidates[0][i]
            for k in range(1, len(candidates)):
                if candidates[k][i] != v0:
                    v0 = None
                    break
            if v0 is not None:
                forced[i] = v0
        return forced

    def assign_cell(r, c, val, queue):
        cur = g[r][c]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        g[r][c] = val
        queue.append(('row', r))
        queue.append(('col', c))
        return True

    def propagate():
        # constraint propagation loop
        queue = deque()
        for i in range(n):
            queue.append(('row', i))
            queue.append(('col', i))

        while queue:
            typ, idx = queue.popleft()
            if typ == 'row':
                partial = list(row_tuple(idx))
                # apply local pattern inference
                inf = local_patterns_infer_line(partial)
                if inf is None:
                    return False
                for j, val in inf.items():
                    if not assign_cell(idx, j, val, queue):
                        return False

                partial = list(row_tuple(idx))
                # candidate-based inference
                cands = filter_candidates(partial)
                if not cands:
                    return False
                forced = derive_forced_from_candidates(partial, cands)
                for j, val in forced.items():
                    if not assign_cell(idx, j, val, queue):
                        return False

                # uniqueness: if row is complete, it must differ from other complete rows
                if U not in g[idx]:
                    for r2 in range(n):
                        if r2 != idx and U not in g[r2] and g[r2] == g[idx]:
                            return False

            else:
                partial = list(col_tuple(idx))
                inf = local_patterns_infer_line(partial)
                if inf is None:
                    return False
                for i, val in inf.items():
                    if not assign_cell(i, idx, val, queue):
                        return False

                partial = list(col_tuple(idx))
                cands = filter_candidates(partial)
                if not cands:
                    return False
                forced = derive_forced_from_candidates(partial, cands)
                for i, val in forced.items():
                    if not assign_cell(i, idx, val, queue):
                        return False

                if all(g[r][idx] != U for r in range(n)):
                    col = [g[r][idx] for r in range(n)]
                    for c2 in range(n):
                        if c2 != idx and all(g[r][c2] != U for r in range(n)):
                            col2 = [g[r][c2] for r in range(n)]
                            if col2 == col:
                                return False

        # Global uniqueness feasibility pruning (partial):
        # If two partial rows (or cols) are identical and have no unknowns difference potential -> impossible.
        # More precisely: if two rows are equal on all known positions and the unknown positions are also equal (same U pattern),
        # they could still be completed differently; allow. But if both are complete, already checked.
        return True

    def is_solved():
        for r in range(n):
            if U in g[r]:
                return False
        # validate all constraints fully
        # balance + no three
        for r in range(n):
            row = g[r]
            if row.count(B) != half or row.count(W) != half:
                return False
            if not line_no_three_possible(row):
                return False
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            if col.count(B) != half or col.count(W) != half:
                return False
            if not line_no_three_possible(col):
                return False
        # uniqueness
        rows = [tuple(g[r]) for r in range(n)]
        if len(set(rows)) != n:
            return False
        cols = [tuple(g[r][c] for r in range(n)) for c in range(n)]
        if len(set(cols)) != n:
            return False
        return True

    def pick_branch_cell():
        # Choose the most constrained row/col with unknowns by candidate count, then pick a cell within it.
        best = None  # (cand_count, typ, idx, candidates)
        for r in range(n):
            if U in g[r]:
                partial = list(row_tuple(r))
                cands = filter_candidates(partial)
                if not cands:
                    return None
                score = len(cands)
                if best is None or score < best[0]:
                    best = (score, 'row', r, cands)
                    if score == 1:
                        break
        for c in range(n):
            if any(g[r][c] == U for r in range(n)):
                partial = list(col_tuple(c))
                cands = filter_candidates(partial)
                if not cands:
                    return None
                score = len(cands)
                if best is None or score < best[0]:
                    best = (score, 'col', c, cands)
                    if score == 1:
                        break
        if best is None:
            return None

        _, typ, idx, cands = best
        # pick an unknown position with maximum split among candidates (closest to half).
        if typ == 'row':
            partial = list(row_tuple(idx))
            positions = [i for i,v in enumerate(partial) if v == U]
            # compute frequency of W among candidates
            best_pos = None
            best_bal = None
            for p in positions:
                ones = sum(ln[p] for ln in cands)
                # want near half to maximize information
                bal = abs(ones*2 - len(cands))
                if best_bal is None or bal < best_bal:
                    best_bal = bal
                    best_pos = p
            return ('cell', idx, best_pos)
        else:
            partial = list(col_tuple(idx))
            positions = [i for i,v in enumerate(partial) if v == U]
            best_pos = None
            best_bal = None
            for p in positions:
                ones = sum(ln[p] for ln in cands)
                bal = abs(ones*2 - len(cands))
                if best_bal is None or bal < best_bal:
                    best_bal = bal
                    best_pos = p
            return ('cell', best_pos, idx)

    def snapshot():
        return [row[:] for row in g]

    def restore(snap):
        for r in range(n):
            g[r][:] = snap[r]

    def dfs():
        if not propagate():
            return False
        if is_solved():
            return True
        choice = pick_branch_cell()
        if choice is None:
            return False
        _, r, c = choice
        # try values with heuristic: prefer value that satisfies balance needs in row/col
        def need_pref(val):
            row = g[r]
            col = [g[i][c] for i in range(n)]
            rb = row.count(B); rw = row.count(W)
            cb = col.count(B); cw = col.count(W)
            # higher is better
            score = 0
            if val == B:
                score += (half - rb)
                score += (half - cb)
            else:
                score += (half - rw)
                score += (half - cw)
            return score
        vals = [B, W]
        vals.sort(key=need_pref, reverse=True)

        snap = snapshot()
        for v in vals:
            restore(snap)
            q = deque()
            if assign_cell(r, c, v, q):
                # process immediate queued constraints quickly
                if dfs():
                    return True
        restore(snap)
        return False

    if not dfs():
        return "No Solution"

    out = [['B' if g[r][c] == B else 'W' for c in range(n)] for r in range(n)]
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 0, None, 1, None, None], [None, None, None, None, None, None, None], [2, None, None, None, None, None, 1], [None, None, None, None, None, None, None], [2, None, None, None, None, None, 0], [None, None, None, None, None, None, None], [None, None, 0, None, 0, None, None]]}
from __future__ import annotations

# Akari / Light Up solver with human-like deduction + constraint propagation + guided backtracking.
# Board encoding in observation['data']:
#   None -> white
#   -1   -> black (unnumbered)
#   0..4 -> black numbered
#
# Output: N x N grid with 'B' for bulbs, None otherwise.

from collections import deque
from dataclasses import dataclass
from typing import List, Tuple, Optional, Dict, Set

WHITE = 0
BLACK = 1

UNKNOWN = 0
BULB = 1
NOBULB = 2  # explicitly forbidden bulb (still must be lit by others)

DIRS = [(-1,0),(1,0),(0,-1),(0,1)]

@dataclass
class Precomp:
    n: int
    is_white: List[bool]                 # len = n*n
    numbered: Dict[int, int]             # cell -> number (for numbered black only)
    adj_whites: List[List[int]]          # for each black cell index -> list of adjacent white indices
    vis_lines: List[List[int]]           # for each white index -> list of white indices visible (excluding itself)
    segments: List[List[int]]            # list of maximal segments (white cells along row/col between blacks)
    seg_of_cell: List[List[int]]         # for each white cell -> [seg_row_id, seg_col_id]
    row_segs: List[int]                  # segment ids that are row segments (first part of segments)
    col_segs: List[int]                  # segment ids that are col segments

def idx(n: int, r: int, c: int) -> int:
    return r*n + c

def rc(n: int, i: int) -> Tuple[int,int]:
    return divmod(i, n)

def parse_observation(obs) -> Tuple[int, List[Optional[int]]]:
    data = obs["data"]
    n = len(data)
    flat: List[Optional[int]] = []
    for r in range(n):
        if len(data[r]) != n:
            raise ValueError("Non-square grid")
        for c in range(n):
            v = data[r][c]
            if v is None:
                flat.append(None)
            else:
                flat.append(int(v))
    return n, flat

def precompute(n: int, flat: List[Optional[int]]) -> Precomp:
    is_white = [v is None for v in flat]
    numbered: Dict[int,int] = {}
    black_cells: List[int] = []
    for i,v in enumerate(flat):
        if v is None:
            continue
        black_cells.append(i)
        if v >= 0:
            numbered[i] = v

    # Adjacent whites for each black cell
    adj_whites = [[] for _ in range(n*n)]
    for b in black_cells:
        br, bc = rc(n, b)
        lst = []
        for dr,dc in DIRS:
            rr, cc = br+dr, bc+dc
            if 0 <= rr < n and 0 <= cc < n:
                j = idx(n, rr, cc)
                if is_white[j]:
                    lst.append(j)
        adj_whites[b] = lst

    # Visible lines: for each white, all other whites along row/col until a black blocks
    def blocked(j: int) -> bool:
        return not is_white[j]

    vis_lines = [[] for _ in range(n*n)]
    for i in range(n*n):
        if not is_white[i]:
            continue
        r,c = rc(n, i)
        acc = []
        # up
        rr = r-1
        while rr >= 0:
            j = idx(n, rr, c)
            if blocked(j): break
            acc.append(j)
            rr -= 1
        # down
        rr = r+1
        while rr < n:
            j = idx(n, rr, c)
            if blocked(j): break
            acc.append(j)
            rr += 1
        # left
        cc = c-1
        while cc >= 0:
            j = idx(n, r, cc)
            if blocked(j): break
            acc.append(j)
            cc -= 1
        # right
        cc = c+1
        while cc < n:
            j = idx(n, r, cc)
            if blocked(j): break
            acc.append(j)
            cc += 1
        vis_lines[i] = acc

    # Build row/col segments (max contiguous whites separated by blacks)
    segments: List[List[int]] = []
    seg_of_cell = [[-1,-1] for _ in range(n*n)]
    row_segs: List[int] = []
    col_segs: List[int] = []

    # row segments
    for r in range(n):
        c = 0
        while c < n:
            j = idx(n, r, c)
            if not is_white[j]:
                c += 1
                continue
            seg = []
            while c < n and is_white[idx(n, r, c)]:
                seg.append(idx(n, r, c))
                c += 1
            sid = len(segments)
            segments.append(seg)
            row_segs.append(sid)
            for cell in seg:
                seg_of_cell[cell][0] = sid
    # col segments
    for c in range(n):
        r = 0
        while r < n:
            j = idx(n, r, c)
            if not is_white[j]:
                r += 1
                continue
            seg = []
            while r < n and is_white[idx(n, r, c)]:
                seg.append(idx(n, r, c))
                r += 1
            sid = len(segments)
            segments.append(seg)
            col_segs.append(sid)
            for cell in seg:
                seg_of_cell[cell][1] = sid

    return Precomp(n, is_white, numbered, adj_whites, vis_lines, segments, seg_of_cell, row_segs, col_segs)

@dataclass
class State:
    # cell_state only meaningful for white cells: UNKNOWN/BULB/NOBULB
    cell_state: List[int]
    # illumination count for white cells (>=1 means lit)
    lit: List[int]
    # segment bulb counts (for each segment id)
    seg_bulbs: List[int]
    # numbered black constraints bookkeeping
    num_adj_bulbs: Dict[int,int]
    num_adj_unknown: Dict[int,int]

    def clone(self) -> "State":
        return State(
            self.cell_state[:],
            self.lit[:],
            self.seg_bulbs[:],
            dict(self.num_adj_bulbs),
            dict(self.num_adj_unknown),
        )

class Contradiction(Exception):
    pass

def solve(observation):
    n, flat = parse_observation(observation)
    P = precompute(n, flat)

    # Initialize state
    cell_state = [UNKNOWN]*(n*n)
    lit = [0]*(n*n)
    seg_bulbs = [0]*len(P.segments)

    num_adj_bulbs: Dict[int,int] = {}
    num_adj_unknown: Dict[int,int] = {}
    for b, k in P.numbered.items():
        num_adj_bulbs[b] = 0
        num_adj_unknown[b] = len(P.adj_whites[b])

    st = State(cell_state, lit, seg_bulbs, num_adj_bulbs, num_adj_unknown)

    # Helper operations with propagation
    def set_cell(st: State, i: int, val: int, q: deque):
        if not P.is_white[i]:
            raise Contradiction()
        cur = st.cell_state[i]
        if cur == val:
            return
        if cur != UNKNOWN and cur != val:
            raise Contradiction()
        st.cell_state[i] = val
        q.append(("cell", i))

        # Update numbered black neighbor unknown counts
        r,c = rc(n, i)
        for dr,dc in DIRS:
            rr,cc = r+dr, c+dc
            if 0 <= rr < n and 0 <= cc < n:
                b = idx(n, rr, cc)
                if b in P.numbered:
                    st.num_adj_unknown[b] -= 1
                    if val == BULB:
                        st.num_adj_bulbs[b] += 1
                    q.append(("num", b))

    def add_light(st: State, i: int):
        st.lit[i] += 1

    def remove_light(st: State, i: int):
        st.lit[i] -= 1
        if st.lit[i] < 0:
            raise Contradiction()

    # We apply changes with a trail-like local undo via cloning in recursion; so we can directly mutate.
    def place_bulb(st: State, i: int, q: deque):
        # Preconditions: i white, not forbidden, and no other bulb visible
        if not P.is_white[i]:
            raise Contradiction()
        if st.cell_state[i] == NOBULB:
            raise Contradiction()
        if st.cell_state[i] == BULB:
            return
        # Check visibility conflict with existing bulbs quickly using segments
        row_sid, col_sid = P.seg_of_cell[i]
        if st.seg_bulbs[row_sid] >= 1 or st.seg_bulbs[col_sid] >= 1:
            # If already contains bulb, placing another in same segment would see it
            # (segments are maximal contiguous whites along row/col).
            # However, a bulb in same row segment definitely sees unless blocked; by definition it's unblocked.
            raise Contradiction()

        set_cell(st, i, BULB, q)

        # update segment bulb counts
        st.seg_bulbs[row_sid] += 1
        st.seg_bulbs[col_sid] += 1
        if st.seg_bulbs[row_sid] > 1 or st.seg_bulbs[col_sid] > 1:
            raise Contradiction()

        # illuminate itself and all visible cells
        add_light(st, i)
        for j in P.vis_lines[i]:
            add_light(st, j)

        # all other cells visible to this bulb cannot be bulbs
        for j in P.vis_lines[i]:
            if P.is_white[j] and st.cell_state[j] == UNKNOWN:
                set_cell(st, j, NOBULB, q)
            elif P.is_white[j] and st.cell_state[j] == BULB:
                raise Contradiction()

        # also, in same row/col segment, all cells are visible; already handled by vis_lines
        q.append(("illum", i))

    def forbid_bulb(st: State, i: int, q: deque):
        if not P.is_white[i]:
            raise Contradiction()
        if st.cell_state[i] == BULB:
            raise Contradiction()
        if st.cell_state[i] == NOBULB:
            return
        set_cell(st, i, NOBULB, q)

    def propagate(st: State):
        q = deque()
        # Seed queue with numbered blacks to enforce constraints and trivial rules, and with any known bulbs.
        for b in P.numbered:
            q.append(("num", b))
        # Also enforce immediate 0-rule and 4-rule etc via num propagation.
        while q:
            typ, x = q.popleft()

            if typ == "num":
                b = x
                if b not in P.numbered:
                    continue
                k = P.numbered[b]
                adj = P.adj_whites[b]
                bulbs = st.num_adj_bulbs[b]
                unk = st.num_adj_unknown[b]
                if bulbs > k:
                    raise Contradiction()
                if bulbs + unk < k:
                    raise Contradiction()

                # If satisfied, all remaining adjacent unknowns cannot be bulbs
                if bulbs == k:
                    for w in adj:
                        if st.cell_state[w] == UNKNOWN:
                            forbid_bulb(st, w, q)
                # If must fill all unknowns with bulbs
                if bulbs + unk == k:
                    for w in adj:
                        if st.cell_state[w] == UNKNOWN:
                            place_bulb(st, w, q)

            elif typ == "cell":
                # Local inferences around recently fixed cell for numbered blacks handled above already by q("num", b)
                pass

            elif typ == "illum":
                # no-op placeholder
                pass

        # Additional propagation: enforce "at most one bulb per segment" already enforced via seg_bulbs.
        # Enforce coverage: if a white cell is unlit and all candidates to light it are forbidden, contradiction;
        # if it has exactly one candidate position for a bulb (including itself if possible), force it.
        # We'll do a tight pass (repeat until no new) using a worklist of currently unlit cells.
        changed = True
        while changed:
            changed = False

            # Numbered constraints already stable; now coverage-based forcing
            for i in range(n*n):
                if not P.is_white[i]:
                    continue
                if st.lit[i] > 0:
                    continue
                if st.cell_state[i] == BULB:
                    continue
                # Candidates are any position that could host a bulb and would illuminate i.
                # That's i itself plus all visible whites.
                cand = []
                # i itself candidate if not NOBULB and segment counts allow and doesn't violate numbered local constraints.
                positions = [i] + P.vis_lines[i]
                for p in positions:
                    if not P.is_white[p]:
                        continue
                    if st.cell_state[p] == NOBULB:
                        continue
                    if st.cell_state[p] == BULB:
                        cand = [p]
                        break
                    # segment "at most 1" feasibility
                    row_sid, col_sid = P.seg_of_cell[p]
                    if st.seg_bulbs[row_sid] >= 1 or st.seg_bulbs[col_sid] >= 1:
                        continue
                    # numbered feasibility quick check for adjacent numbered blacks
                    pr, pc = rc(n, p)
                    ok = True
                    for dr,dc in DIRS:
                        rr,cc = pr+dr, pc+dc
                        if 0 <= rr < n and 0 <= cc < n:
                            b = idx(n, rr, cc)
                            if b in P.numbered:
                                k = P.numbered[b]
                                bulbs = st.num_adj_bulbs[b]
                                unk = st.num_adj_unknown[b]
                                # If we place bulb here, bulbs+1 must be <= k and (bulbs+1)+ (unk-1) >= k
                                if bulbs + 1 > k:
                                    ok = False
                                    break
                                if bulbs + 1 + (unk - 1) < k:
                                    ok = False
                                    break
                    if not ok:
                        continue
                    cand.append(p)

                if not cand:
                    raise Contradiction()
                if len(cand) == 1 and st.cell_state[cand[0]] != BULB:
                    # Force bulb at only candidate
                    q = deque()
                    place_bulb(st, cand[0], q)
                    # propagate numbered constraints triggered by placement
                    while q:
                        typ, x = q.popleft()
                        if typ == "num":
                            b = x
                            if b in P.numbered:
                                k = P.numbered[b]
                                adj = P.adj_whites[b]
                                bulbs = st.num_adj_bulbs[b]
                                unk = st.num_adj_unknown[b]
                                if bulbs > k or bulbs + unk < k:
                                    raise Contradiction()
                                if bulbs == k:
                                    for w in adj:
                                        if st.cell_state[w] == UNKNOWN:
                                            forbid_bulb(st, w, q)
                                if bulbs + unk == k:
                                    for w in adj:
                                        if st.cell_state[w] == UNKNOWN:
                                            place_bulb(st, w, q)
                    changed = True

    def is_solved(st: State) -> bool:
        # all whites lit and numbered constraints met
        for i in range(n*n):
            if P.is_white[i] and st.lit[i] <= 0:
                return False
        for b,k in P.numbered.items():
            if st.num_adj_bulbs[b] != k:
                return False
        return True

    def select_branch_cell(st: State) -> Optional[int]:
        # Choose an unlit white cell with minimal candidate bulb positions (MRV), then branch on placing bulb at a candidate.
        best_cell = None
        best_cands = None

        for i in range(n*n):
            if not P.is_white[i]:
                continue
            if st.lit[i] > 0:
                continue
            # compute candidates similarly to propagate
            cand = []
            positions = [i] + P.vis_lines[i]
            for p in positions:
                if st.cell_state[p] == NOBULB:
                    continue
                if st.cell_state[p] == BULB:
                    cand = [p]
                    break
                row_sid, col_sid = P.seg_of_cell[p]
                if st.seg_bulbs[row_sid] >= 1 or st.seg_bulbs[col_sid] >= 1:
                    continue
                # numbered quick feasibility
                pr, pc = rc(n, p)
                ok = True
                for dr,dc in DIRS:
                    rr,cc = pr+dr, pc+dc
                    if 0 <= rr < n and 0 <= cc < n:
                        b = idx(n, rr, cc)
                        if b in P.numbered:
                            k = P.numbered[b]
                            bulbs = st.num_adj_bulbs[b]
                            unk = st.num_adj_unknown[b]
                            if bulbs + 1 > k or bulbs + 1 + (unk - 1) < k:
                                ok = False
                                break
                if ok:
                    cand.append(p)
            if not cand:
                return i  # dead end indicator
            if best_cands is None or len(cand) < len(best_cands):
                best_cell = i
                best_cands = cand
                if len(best_cands) == 1:
                    break
        if best_cell is None:
            return None
        return best_cell

    def candidates_for_unlit(st: State, i: int) -> List[int]:
        cand = []
        positions = [i] + P.vis_lines[i]
        for p in positions:
            if st.cell_state[p] == NOBULB:
                continue
            if st.cell_state[p] == BULB:
                return [p]
            row_sid, col_sid = P.seg_of_cell[p]
            if st.seg_bulbs[row_sid] >= 1 or st.seg_bulbs[col_sid] >= 1:
                continue
            pr, pc = rc(n, p)
            ok = True
            for dr,dc in DIRS:
                rr,cc = pr+dr, pc+dc
                if 0 <= rr < n and 0 <= cc < n:
                    b = idx(n, rr, cc)
                    if b in P.numbered:
                        k = P.numbered[b]
                        bulbs = st.num_adj_bulbs[b]
                        unk = st.num_adj_unknown[b]
                        if bulbs + 1 > k or bulbs + 1 + (unk - 1) < k:
                            ok = False
                            break
            if ok:
                cand.append(p)
        return cand

    def dfs(st: State) -> Optional[State]:
        try:
            propagate(st)
        except Contradiction:
            return None
        if is_solved(st):
            return st

        pick = select_branch_cell(st)
        if pick is None:
            return None
        if P.is_white[pick] and st.lit[pick] <= 0:
            cands = candidates_for_unlit(st, pick)
            if not cands:
                return None
            # Try candidates in an order: prefer those that satisfy numbered blacks tightly (heuristic)
            def score(p: int) -> int:
                pr, pc = rc(n, p)
                s = 0
                for dr,dc in DIRS:
                    rr,cc = pr+dr, pc+dc
                    if 0 <= rr < n and 0 <= cc < n:
                        b = idx(n, rr, cc)
                        if b in P.numbered:
                            k = P.numbered[b]
                            bulbs = st.num_adj_bulbs[b]
                            unk = st.num_adj_unknown[b]
                            # higher score if placing moves closer to k
                            s += (k - bulbs)
                            # and if it would force remaining
                            if bulbs + 1 == k or bulbs + 1 + (unk - 1) == k:
                                s += 3
                return -s
            cands.sort(key=score)

            for p in cands:
                st2 = st.clone()
                q = deque()
                try:
                    place_bulb(st2, p, q)
                    res = dfs(st2)
                    if res is not None:
                        return res
                except Contradiction:
                    continue
            return None

        # fallback: pick an unknown cell and branch (bulb vs no-bulb), but avoid pure brute force by choosing constrained cell
        # Choose unknown cell that is adjacent to a numbered black or in a segment with no bulb yet and contributes to unlit.
        best = None
        best_score = -10**9
        for i in range(n*n):
            if not P.is_white[i] or st.cell_state[i] != UNKNOWN:
                continue
            sc = 0
            if st.lit[i] <= 0:
                sc += 5
            r,c = rc(n, i)
            for dr,dc in DIRS:
                rr,cc = r+dr, c+dc
                if 0 <= rr < n and 0 <= cc < n:
                    b = idx(n, rr, cc)
                    if b in P.numbered:
                        k = P.numbered[b]
                        sc += 2*(k - st.num_adj_bulbs[b])
            row_sid, col_sid = P.seg_of_cell[i]
            sc += 1 if st.seg_bulbs[row_sid] == 0 else 0
            sc += 1 if st.seg_bulbs[col_sid] == 0 else 0
            if sc > best_score:
                best_score = sc
                best = i
        if best is None:
            return None

        # Branch: try BULB then NOBULB
        for val in (BULB, NOBULB):
            st2 = st.clone()
            q = deque()
            try:
                if val == BULB:
                    place_bulb(st2, best, q)
                else:
                    forbid_bulb(st2, best, q)
                res = dfs(st2)
                if res is not None:
                    return res
            except Contradiction:
                continue
        return None

    # Initial obvious deductions for numbered blacks:
    # - For '0' => all adjacent whites are NOBULB (handled by propagate).
    # - For '4' => all adjacent whites are BULB (handled by propagate).
    sol = dfs(st)
    if sol is None:
        return "No Solution"

    # Build output grid
    out: List[List[Optional[str]]] = [[None]*n for _ in range(n)]
    for i in range(n*n):
        if P.is_white[i] and sol.cell_state[i] == BULB:
            r,c = rc(n, i)
            out[r][c] = "B"
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, None, None, None, 'W', None], [None, None, 'B', None, None, None], [None, None, None, 'W', None, 'W'], [None, None, None, None, None, None], ['B', None, None, 'W', None, 'B']]}
from typing import List, Optional, Tuple, Dict

# Binary Puzzle / Takuzu solver
# Human-like deduction + aggressive propagation + minimal branching with strong pruning.
# Generalized for even-sized NxN grids (classic Takuzu). Returns solved grid or "No Solution".

B, W = 1, 0

def solve(observation):
    grid0 = observation["data"]
    n = len(grid0)
    if n == 0 or any(len(r) != n for r in grid0) or (n % 2 != 0):
        return "No Solution"

    # Represent grid as ints {B,W} or -1 unknown for speed.
    g = [[-1]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = grid0[r][c]
            if v == 'B':
                g[r][c] = B
            elif v == 'W':
                g[r][c] = W

    half = n // 2

    # Precompute all valid full line patterns for size n.
    # Constraints: exactly half of each color and no three consecutive same.
    valid_lines = []
    for mask in range(1 << n):
        # quick popcount check for number of 1s = half (treat 1 as B)
        if mask.bit_count() != half:
            continue
        ok = True
        # No three consecutive equal
        # Extract bits; 1->B, 0->W
        for i in range(n - 2):
            b0 = (mask >> i) & 1
            b1 = (mask >> (i + 1)) & 1
            b2 = (mask >> (i + 2)) & 1
            if b0 == b1 == b2:
                ok = False
                break
        if ok:
            valid_lines.append(mask)
    if not valid_lines:
        return "No Solution"

    # Build compatibility: for any partial line (with -1) we can filter valid masks on demand.
    # Use cache by encoding partial assignment into (known_mask, value_mask).
    # known_mask bits=1 where fixed; value_mask bits contain values where known (1 for B, 0 for W)
    line_cache: Dict[Tuple[int, int], List[int]] = {}

    def encode_line(vals: List[int]) -> Tuple[int, int]:
        km = 0
        vm = 0
        for i, v in enumerate(vals):
            if v != -1:
                km |= (1 << i)
                if v == B:
                    vm |= (1 << i)
        return km, vm

    def candidates_for_line(vals: List[int]) -> List[int]:
        key = encode_line(vals)
        if key in line_cache:
            return line_cache[key]
        km, vm = key
        res = []
        # Filter valid_lines by matching known bits
        for m in valid_lines:
            if (m & km) == vm:
                res.append(m)
        line_cache[key] = res
        return res

    def line_from_mask(mask: int) -> List[int]:
        return [(mask >> i) & 1 for i in range(n)]

    def get_row(r: int) -> List[int]:
        return g[r]

    def get_col(c: int) -> List[int]:
        return [g[r][c] for r in range(n)]

    def apply_line_forced(vals: List[int], cands: List[int]) -> List[Tuple[int, int, int]]:
        # Returns list of (idx, value) forced positions for this line.
        # Use bitwise consensus: if all candidates have same bit at position, it's forced.
        forced = []
        if not cands:
            return forced
        # Compute intersection consensus via counts
        # For each position, if all candidates have bit 1 -> forced B; if all 0 -> forced W.
        all_ones = (1 << n) - 1
        any_ones = 0
        for m in cands:
            any_ones |= m
            all_ones &= m
        # all_zeros positions are where no candidate has 1
        all_zeros = (~any_ones) & ((1 << n) - 1)

        for i, v in enumerate(vals):
            if v == -1:
                bit = 1 << i
                if all_ones & bit:
                    forced.append((i, B))
                elif all_zeros & bit:
                    forced.append((i, W))
        return forced

    def set_cell(r: int, c: int, val: int, trail: List[Tuple[int, int]]):
        if g[r][c] == val:
            return True
        if g[r][c] != -1 and g[r][c] != val:
            return False
        g[r][c] = val
        trail.append((r, c))
        return True

    def undo(trail: List[Tuple[int, int]]):
        for r, c in reversed(trail):
            g[r][c] = -1

    def check_no_three_local_line(vals: List[int]) -> bool:
        # Check partial line doesn't already violate no-3 rule (e.g. fixed trio equal).
        for i in range(n - 2):
            a, b, c = vals[i], vals[i+1], vals[i+2]
            if a != -1 and a == b == c:
                return False
        return True

    def check_counts_possible(vals: List[int]) -> bool:
        # partial count constraints
        bcnt = sum(1 for v in vals if v == B)
        wcnt = sum(1 for v in vals if v == W)
        unk = vals.count(-1)
        if bcnt > half or wcnt > half:
            return False
        # must be able to reach half
        if bcnt + unk < half or wcnt + unk < half:
            return False
        return True

    def line_complete(vals: List[int]) -> bool:
        return all(v != -1 for v in vals)

    def row_mask(r: int) -> int:
        m = 0
        for i, v in enumerate(g[r]):
            if v == B:
                m |= (1 << i)
        return m

    def col_mask(c: int) -> int:
        m = 0
        for i in range(n):
            if g[i][c] == B:
                m |= (1 << i)
        return m

    def propagate(trail: List[Tuple[int, int]]) -> bool:
        # Constraint propagation loop: apply classic Takuzu rules via candidate-line filtering.
        # Also enforce uniqueness for fully solved lines.
        # Return False if contradiction.
        changed = True
        while changed:
            changed = False

            # Early local checks + candidate filtering to force cells
            for r in range(n):
                row = get_row(r)
                if not check_no_three_local_line(row) or not check_counts_possible(row):
                    return False
                cands = candidates_for_line(row)
                if not cands:
                    return False
                for idx, val in apply_line_forced(row, cands):
                    if not set_cell(r, idx, val, trail):
                        return False
                    changed = True

            for c in range(n):
                col = get_col(c)
                if not check_no_three_local_line(col) or not check_counts_possible(col):
                    return False
                cands = candidates_for_line(col)
                if not cands:
                    return False
                for idx, val in apply_line_forced(col, cands):
                    if not set_cell(idx, c, val, trail):
                        return False
                    changed = True

            # Explicit "no three consecutive" implication rules (human style):
            # 1) If XX? -> XX must be followed by opposite: BB? -> B B W ; WW? -> W W B
            # 2) If ?XX -> opposite preceding
            # 3) If X?X -> middle must be opposite
            for r in range(n):
                row = get_row(r)
                for i in range(n - 2):
                    a, b, c = row[i], row[i+1], row[i+2]
                    if a != -1 and a == b and c == -1:
                        if not set_cell(r, i+2, 1-a, trail):
                            return False
                        changed = True
                    if b != -1 and b == c and a == -1:
                        if not set_cell(r, i, 1-b, trail):
                            return False
                        changed = True
                    if a != -1 and c != -1 and a == c and b == -1:
                        if not set_cell(r, i+1, 1-a, trail):
                            return False
                        changed = True

            for c in range(n):
                col = get_col(c)
                for i in range(n - 2):
                    a, b, cc = col[i], col[i+1], col[i+2]
                    if a != -1 and a == b and cc == -1:
                        if not set_cell(i+2, c, 1-a, trail):
                            return False
                        changed = True
                    if b != -1 and b == cc and a == -1:
                        if not set_cell(i, c, 1-b, trail):
                            return False
                        changed = True
                    if a != -1 and cc != -1 and a == cc and b == -1:
                        if not set_cell(i+1, c, 1-a, trail):
                            return False
                        changed = True

            # Count completion rule (human style):
            # If a line already has half of one color, fill rest with the other.
            for r in range(n):
                row = get_row(r)
                bcnt = sum(1 for v in row if v == B)
                wcnt = sum(1 for v in row if v == W)
                if bcnt == half:
                    for c in range(n):
                        if row[c] == -1:
                            if not set_cell(r, c, W, trail):
                                return False
                            changed = True
                elif wcnt == half:
                    for c in range(n):
                        if row[c] == -1:
                            if not set_cell(r, c, B, trail):
                                return False
                            changed = True

            for c in range(n):
                col = get_col(c)
                bcnt = sum(1 for v in col if v == B)
                wcnt = sum(1 for v in col if v == W)
                if bcnt == half:
                    for r in range(n):
                        if g[r][c] == -1:
                            if not set_cell(r, c, W, trail):
                                return False
                            changed = True
                elif wcnt == half:
                    for r in range(n):
                        if g[r][c] == -1:
                            if not set_cell(r, c, B, trail):
                                return False
                            changed = True

            # Uniqueness: no two identical completed rows/cols.
            # Also: if a row is one cell away from matching a completed row, force difference.
            completed_rows = {}
            for r in range(n):
                row = get_row(r)
                if line_complete(row):
                    m = row_mask(r)
                    if m in completed_rows:
                        return False
                    completed_rows[m] = r

            completed_cols = {}
            for c in range(n):
                col = get_col(c)
                if line_complete(col):
                    m = col_mask(c)
                    if m in completed_cols:
                        return False
                    completed_cols[m] = c

            # Near-duplicate pruning (strong and still "human-like"):
            # For each incomplete row, if it could become equal to a completed row, forbid that by forcing at least one differing cell.
            # If only one position can differ, force it to differ.
            for r in range(n):
                row = get_row(r)
                if line_complete(row):
                    continue
                km, vm = encode_line(row)
                # Compare to each completed row mask; if all known bits match, then remaining unknowns would have to avoid becoming identical.
                for m, rr in completed_rows.items():
                    if (m & km) == vm:
                        # Positions where row is unknown are free; to avoid equality, must set at least one unknown to opposite of m.
                        unknown_positions = [i for i, v in enumerate(row) if v == -1]
                        if not unknown_positions:
                            return False
                        # If only one unknown, must differ there.
                        if len(unknown_positions) == 1:
                            i = unknown_positions[0]
                            forced = 1 - ((m >> i) & 1)
                            if not set_cell(r, i, forced, trail):
                                return False
                            changed = True

            for c in range(n):
                col = get_col(c)
                if line_complete(col):
                    continue
                km, vm = encode_line(col)
                for m, cc in completed_cols.items():
                    if (m & km) == vm:
                        unknown_positions = [i for i, v in enumerate(col) if v == -1]
                        if not unknown_positions:
                            return False
                        if len(unknown_positions) == 1:
                            i = unknown_positions[0]
                            forced = 1 - ((m >> i) & 1)
                            if not set_cell(i, c, forced, trail):
                                return False
                            changed = True

        return True

    def is_solved() -> bool:
        return all(all(v != -1 for v in row) for row in g)

    def pick_branch() -> Optional[Tuple[str, int, List[int]]]:
        # Choose most constrained line (row or col) with smallest candidate count >1
        best = None
        best_cands = None
        for r in range(n):
            row = get_row(r)
            if line_complete(row):
                continue
            cands = candidates_for_line(row)
            if not cands:
                return None
            if len(cands) > 1 and (best is None or len(cands) < len(best_cands)):
                best = ("R", r, [])
                best_cands = cands
                if len(cands) == 2:
                    break
        for c in range(n):
            col = get_col(c)
            if line_complete(col):
                continue
            cands = candidates_for_line(col)
            if not cands:
                return None
            if len(cands) > 1 and (best is None or len(cands) < len(best_cands)):
                best = ("C", c, [])
                best_cands = cands
                if len(cands) == 2:
                    break
        if best is None:
            return None
        return (best[0], best[1], best_cands)

    def dfs() -> bool:
        trail: List[Tuple[int, int]] = []
        if not propagate(trail):
            undo(trail)
            return False
        if is_solved():
            return True

        choice = pick_branch()
        if choice is None:
            undo(trail)
            return False
        kind, idx, cands = choice

        # Try candidates in an order that may reduce symmetry: prefer those that diversify from existing completed lines.
        # Simple heuristic: count similarity to completed lines; try less-similar first.
        if kind == "R":
            completed = {row_mask(r) for r in range(n) if line_complete(get_row(r))}
        else:
            completed = {col_mask(c) for c in range(n) if line_complete(get_col(c))}

        def score(mask: int) -> int:
            # lower is better: minimal max similarity
            if not completed:
                return 0
            # similarity = number of equal bits
            best_sim = 0
            for m in completed:
                eq = n - (mask ^ m).bit_count()
                if eq > best_sim:
                    best_sim = eq
            return best_sim

        cands_sorted = sorted(cands, key=score)

        # branch by setting whole line to a candidate mask (stronger than single-cell guess)
        base_trail = list(trail)
        for m in cands_sorted:
            local_trail = []
            ok = True
            if kind == "R":
                for c in range(n):
                    v = (m >> c) & 1
                    if g[idx][c] != -1 and g[idx][c] != v:
                        ok = False
                        break
                    if g[idx][c] == -1:
                        if not set_cell(idx, c, v, local_trail):
                            ok = False
                            break
            else:
                for r in range(n):
                    v = (m >> r) & 1
                    if g[r][idx] != -1 and g[r][idx] != v:
                        ok = False
                        break
                    if g[r][idx] == -1:
                        if not set_cell(r, idx, v, local_trail):
                            ok = False
                            break

            if ok and dfs():
                return True
            undo(local_trail)

        undo(base_trail)
        return False

    if not dfs():
        return "No Solution"

    out = [['B' if g[r][c] == B else 'W' for c in range(n)] for r in range(n)]
    return str(out)

