    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 2, None, 2, None], [1, 2, 1, 3, 2], [2, 3, None, None, None], [None, 2, 3, 3, None], [None, None, None, None, None]]}
# Slitherlink solver: human-style deductions + limited backtracking.
# Input: observation['data'] is N x N with ints or None (cells).
# Output: ordered list of loop dot coordinates [(r,c), ..., (r,c)] or "No Solution".

from collections import deque, defaultdict
import math
import sys

def solve(observation):
    grid = observation["data"]
    N = len(grid)
    if any(len(row) != N for row in grid):
        return "No Solution"

    # Edge indexing:
    # Horizontal edges h[r][c] between dots (r,c) - (r,c+1), r in [0..N], c in [0..N-1]
    # Vertical edges v[r][c] between dots (r,c) - (r+1,c), r in [0..N-1], c in [0..N]
    # State: -1 unknown, 0 off, 1 on
    h = [[-1] * N for _ in range(N + 1)]
    v = [[-1] * (N + 1) for _ in range(N)]

    def iter_cell_edges(r, c):
        # returns list of (kind, rr, cc)
        return [("h", r, c), ("v", r, c + 1), ("h", r + 1, c), ("v", r, c)]

    def edge_get(e):
        kind, r, c = e
        return h[r][c] if kind == "h" else v[r][c]

    def edge_set(e, val, trail):
        kind, r, c = e
        arr = h if kind == "h" else v
        if arr[r][c] == val:
            return True
        if arr[r][c] != -1 and arr[r][c] != val:
            return False
        trail.append((kind, r, c, arr[r][c]))
        arr[r][c] = val
        return True

    def undo(trail, upto):
        for i in range(len(trail) - 1, upto - 1, -1):
            kind, r, c, prev = trail[i]
            (h if kind == "h" else v)[r][c] = prev
        del trail[upto:]

    def dot_edges(dr, dc):
        # All incident edges to dot (dr,dc)
        res = []
        if dc > 0:
            res.append(("h", dr, dc - 1))
        if dc < N:
            res.append(("h", dr, dc))
        if dr > 0:
            res.append(("v", dr - 1, dc))
        if dr < N:
            res.append(("v", dr, dc))
        return res

    def cell_count(r, c):
        edges = iter_cell_edges(r, c)
        on = sum(1 for e in edges if edge_get(e) == 1)
        off = sum(1 for e in edges if edge_get(e) == 0)
        unk = 4 - on - off
        return on, off, unk

    def dot_count(r, c):
        edges = dot_edges(r, c)
        on = sum(1 for e in edges if edge_get(e) == 1)
        off = sum(1 for e in edges if edge_get(e) == 0)
        unk = len(edges) - on - off
        return on, off, unk, edges

    # Disjoint set for "on" edges to prevent premature small cycles.
    parent = {}
    size = {}

    def dsu_init():
        parent.clear()
        size.clear()

    def dsu_find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def dsu_union(a, b):
        ra = dsu_find(a)
        rb = dsu_find(b)
        if ra == rb:
            return ra
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return ra

    def ensure_node(n):
        if n not in parent:
            parent[n] = n
            size[n] = 1

    def edge_endpoints(e):
        kind, r, c = e
        if kind == "h":
            return (r, c), (r, c + 1)
        else:
            return (r, c), (r + 1, c)

    def rebuild_dsu_and_degrees():
        dsu_init()
        deg = [[0] * (N + 1) for _ in range(N + 1)]
        on_edges = []
        for r in range(N + 1):
            for c in range(N):
                if h[r][c] == 1:
                    a, b = (r, c), (r, c + 1)
                    ensure_node(a); ensure_node(b)
                    dsu_union(a, b)
                    deg[a[0]][a[1]] += 1
                    deg[b[0]][b[1]] += 1
                    on_edges.append(("h", r, c))
        for r in range(N):
            for c in range(N + 1):
                if v[r][c] == 1:
                    a, b = (r, c), (r + 1, c)
                    ensure_node(a); ensure_node(b)
                    dsu_union(a, b)
                    deg[a[0]][a[1]] += 1
                    deg[b[0]][b[1]] += 1
                    on_edges.append(("v", r, c))
        return deg, on_edges

    def all_edges():
        for r in range(N + 1):
            for c in range(N):
                yield ("h", r, c)
        for r in range(N):
            for c in range(N + 1):
                yield ("v", r, c)

    # Queue-driven propagation: cell constraints + dot degree constraints + no-small-cycle constraint.
    def propagate(trail):
        # returns False on contradiction
        q_cells = deque()
        q_dots = deque()

        inq_cell = [[False] * N for _ in range(N)]
        inq_dot = [[False] * (N + 1) for _ in range(N + 1)]

        def push_cell(r, c):
            if 0 <= r < N and 0 <= c < N and not inq_cell[r][c] and grid[r][c] is not None:
                inq_cell[r][c] = True
                q_cells.append((r, c))

        def push_dot(r, c):
            if 0 <= r <= N and 0 <= c <= N and not inq_dot[r][c]:
                inq_dot[r][c] = True
                q_dots.append((r, c))

        # initial
        for r in range(N):
            for c in range(N):
                if grid[r][c] is not None:
                    push_cell(r, c)
        for r in range(N + 1):
            for c in range(N + 1):
                push_dot(r, c)

        # helper to enqueue affected constraints when an edge changes
        def on_edge_change(e):
            kind, r, c = e
            if kind == "h":
                # affects cells above/below
                if r > 0:
                    push_cell(r - 1, c)
                if r < N:
                    push_cell(r, c)
                # affects dots endpoints
                push_dot(r, c)
                push_dot(r, c + 1)
            else:
                if c > 0:
                    push_cell(r, c - 1)
                if c < N:
                    push_cell(r, c)
                push_dot(r, c)
                push_dot(r + 1, c)

        # Because we modify edges inside propagation, we need to track newly set edges.
        def set_edge(e, val):
            before_len = len(trail)
            if not edge_set(e, val, trail):
                return False
            if len(trail) != before_len:
                on_edge_change(e)
            return True

        # A few standard Slitherlink cell rules:
        # - If clue k: on + unk must be >= k and on <= k.
        # - If on == k -> all remaining unk are off.
        # - If on + unk == k -> all remaining unk are on.
        #
        # Dot rules:
        # - Degree at dot must be 0 or 2.
        # - If deg_on == 2 -> all remaining unk are off.
        # - If deg_on == 1 and unk == 0 -> contradiction.
        # - If deg_on == 1 and unk == 1 -> last unk must be on (to reach 2).
        # - If deg_on == 0 and unk == 1 -> last unk must be off (can't reach 2).
        #
        # No-small-cycle rule:
        # - If setting an edge ON would close a cycle while there exist other ON edges not in that component
        #   or there exist any unknown edges incident to the cycle that could connect? Implement conservatively:
        #   disallow forming a cycle unless it would include all ON edges and all dots in that component have degree 2.
        # We'll enforce this during guessing (and also opportunistically after dot propagation).

        while q_cells or q_dots:
            while q_cells:
                r, c = q_cells.popleft()
                inq_cell[r][c] = False
                k = grid[r][c]
                if k is None:
                    continue
                edges = iter_cell_edges(r, c)
                on = off = 0
                unk_edges = []
                for e in edges:
                    st = edge_get(e)
                    if st == 1:
                        on += 1
                    elif st == 0:
                        off += 1
                    else:
                        unk_edges.append(e)
                unk = len(unk_edges)
                if on > k:
                    return False
                if on + unk < k:
                    return False
                if unk == 0:
                    continue
                if on == k:
                    for e in unk_edges:
                        if not set_edge(e, 0):
                            return False
                elif on + unk == k:
                    for e in unk_edges:
                        if not set_edge(e, 1):
                            return False

            while q_dots:
                r, c = q_dots.popleft()
                inq_dot[r][c] = False
                on, off, unk, edges = dot_count(r, c)
                if on > 2:
                    return False
                if on == 2:
                    for e in edges:
                        if edge_get(e) == -1:
                            if not set_edge(e, 0):
                                return False
                if unk == 0:
                    if on == 1:
                        return False
                elif unk == 1:
                    # If on==1 => must be 2: last unk on
                    if on == 1:
                        e = next(e for e in edges if edge_get(e) == -1)
                        if not set_edge(e, 1):
                            return False
                    # If on==0 => can't reach 2 with only one edge; so last unk off.
                    elif on == 0:
                        e = next(e for e in edges if edge_get(e) == -1)
                        if not set_edge(e, 0):
                            return False

        # Basic global feasibility check: for each dot, on <=2 and on+unk !=1 (can't finish with degree 1).
        for r in range(N + 1):
            for c in range(N + 1):
                on, off, unk, edges = dot_count(r, c)
                if on > 2:
                    return False
                if on == 1 and unk == 0:
                    return False
        # For each clue cell, verify not impossible
        for r in range(N):
            for c in range(N):
                k = grid[r][c]
                if k is None:
                    continue
                on, off, unk = cell_count(r, c)
                if on > k or on + unk < k:
                    return False
        return True

    def is_complete():
        for e in all_edges():
            if edge_get(e) == -1:
                return False
        return True

    def validate_single_loop():
        deg, on_edges = rebuild_dsu_and_degrees()
        if not on_edges:
            return False
        # all degrees must be 0 or 2; and all used dots degree 2
        used = []
        for r in range(N + 1):
            for c in range(N + 1):
                d = deg[r][c]
                if d not in (0, 2):
                    return False
                if d == 2:
                    used.append((r, c))
        if not used:
            return False
        # single component among used dots
        roots = {dsu_find(u) for u in used}
        if len(roots) != 1:
            return False
        # clue satisfaction
        for r in range(N):
            for c in range(N):
                k = grid[r][c]
                if k is None:
                    continue
                on, off, unk = cell_count(r, c)
                if unk != 0 or on != k:
                    return False
        return True

    def would_create_illegal_small_cycle(e):
        # Check if turning e ON closes a cycle prematurely.
        a, b = edge_endpoints(e)
        deg, on_edges = rebuild_dsu_and_degrees()
        # If a and b already connected, adding e creates a cycle.
        if a not in parent or b not in parent:
            return False
        if dsu_find(a) != dsu_find(b):
            return False
        # It forms a cycle within that component. Allow only if it would finalize the whole loop:
        # - all dots in that component would have degree 2 after adding
        # - and there are no other ON edges outside that component
        root = dsu_find(a)
        # check other components
        for n in parent:
            if dsu_find(n) != root:
                return True
        # compute degrees after adding e
        deg_a = deg[a[0]][a[1]] + 1
        deg_b = deg[b[0]][b[1]] + 1
        if deg_a > 2 or deg_b > 2:
            return True
        # every node in component must reach degree 2 and have no incident unknown edges that would force mismatch
        nodes = [n for n in parent if dsu_find(n) == root]
        for n in nodes:
            d = deg[n[0]][n[1]] + (1 if n == a else 0) + (1 if n == b else 0)
            if d != 2:
                return True
        return False

    def choose_branch_edge():
        # Most constrained unknown edge: based on adjacent clue tightness and dot degrees.
        best = None
        best_score = -1
        for e in all_edges():
            if edge_get(e) != -1:
                continue
            kind, r, c = e
            score = 0
            # dot pressure
            a, b = edge_endpoints(e)
            for (dr, dc) in (a, b):
                on, off, unk, edges = dot_count(dr, dc)
                if on == 1:
                    score += 5
                if unk == 1:
                    score += 4
                if on == 2:
                    score -= 10
            # clue pressure
            adj = []
            if kind == "h":
                if r > 0:
                    adj.append((r - 1, c))
                if r < N:
                    adj.append((r, c))
            else:
                if c > 0:
                    adj.append((r, c - 1))
                if c < N:
                    adj.append((r, c))
            for (cr, cc) in adj:
                k = grid[cr][cc]
                if k is None:
                    continue
                on, off, unk = cell_count(cr, cc)
                # closer to forcing
                score += 3 - unk
                if on == k or on + unk == k:
                    score += 3
            if score > best_score:
                best_score = score
                best = e
        return best

    trail = []
    if not propagate(trail):
        return "No Solution"

    sys.setrecursionlimit(10000)

    def dfs():
        if is_complete():
            return validate_single_loop()
        e = choose_branch_edge()
        if e is None:
            return False

        # Try ON then OFF, but avoid premature cycle when ON.
        for val in (1, 0):
            if val == 1 and would_create_illegal_small_cycle(e):
                continue
            mark = len(trail)
            if edge_set(e, val, trail) and propagate(trail):
                if dfs():
                    return True
            undo(trail, mark)
        return False

    if not dfs():
        return "No Solution"

    # Build ordered loop coordinates from ON edges
    deg, on_edges = rebuild_dsu_and_degrees()
    # adjacency map
    adj = defaultdict(list)
    for e in on_edges:
        a, b = edge_endpoints(e)
        adj[a].append(b)
        adj[b].append(a)
    # find a start
    start = next((node for node, ns in adj.items() if len(ns) == 2), None)
    if start is None:
        return "No Solution"
    # traverse
    path = [start]
    prev = None
    cur = start
    while True:
        ns = adj[cur]
        nxt = ns[0] if ns[0] != prev else ns[1]
        prev, cur = cur, nxt
        path.append(cur)
        if cur == start:
            break
        if len(path) > (N + 1) * (N + 1) * 4 + 5:
            return "No Solution"

    return str(path)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 'W', None, 'W', 'B', None, None, 'W', None], ['B', None, 'W', None, None, None, None, 'B', None, None], [None, None, None, 'B', None, None, 'W', None, None, None], ['B', 'B', None, None, None, 'B', None, None, None, None], [None, None, None, 'B', None, None, None, None, None, None], [None, None, None, None, None, None, None, 'W', None, 'W'], [None, 'B', None, 'B', None, 'B', None, None, None, None], [None, None, 'W', None, None, None, 'B', None, 'W', None], ['B', None, None, None, None, None, None, 'B', None, None], ['B', None, None, 'B', None, 'W', None, None, None, None]]}
from __future__ import annotations

from dataclasses import dataclass
from typing import List, Optional, Tuple, Iterable

B, W = 'B', 'W'
OPP = {B: W, W: B}

# ----------------------------
# Core deduction utilities
# ----------------------------

def _count_vals(line: List[Optional[str]]) -> Tuple[int, int, int]:
    b = sum(1 for v in line if v == B)
    w = sum(1 for v in line if v == W)
    u = len(line) - b - w
    return b, w, u

def _no_three_possible(line: List[Optional[str]]) -> bool:
    n = len(line)
    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and a == b == c:
            return False
    return True

def _apply_no_three_forced(line: List[Optional[str]]) -> List[Tuple[int, str]]:
    # Human rule: BB_ -> BBW, _BB -> WBB, B_B -> BWB (and same for W)
    n = len(line)
    changes = []
    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and b is not None and a == b and c is None:
            changes.append((i + 2, OPP[a]))
        if b is not None and c is not None and b == c and a is None:
            changes.append((i, OPP[b]))
        if a is not None and c is not None and a == c and b is None:
            changes.append((i + 1, OPP[a]))
    return changes

def _apply_balance_forced(line: List[Optional[str]]) -> Optional[List[Tuple[int, str]]]:
    # Human rule: if already have n/2 of one color, remaining must be the other.
    n = len(line)
    half = n // 2
    cb, cw, cu = _count_vals(line)
    if cb > half or cw > half:
        return None
    changes = []
    if cu == 0:
        return changes
    if cb == half:
        for i, v in enumerate(line):
            if v is None:
                changes.append((i, W))
    elif cw == half:
        for i, v in enumerate(line):
            if v is None:
                changes.append((i, B))
    return changes

def _line_to_bits(line: List[Optional[str]]) -> Optional[Tuple[int, int]]:
    # returns (mask_known, bits_black) for known cells; None if any unknown? No, keeps mask.
    n = len(line)
    mask = 0
    bits = 0
    for i, v in enumerate(line):
        if v is not None:
            mask |= (1 << i)
            if v == B:
                bits |= (1 << i)
    return mask, bits

def _compatible(mask_a: int, bits_a: int, mask_b: int, bits_b: int) -> bool:
    both = mask_a & mask_b
    return ((bits_a ^ bits_b) & both) == 0

def _equal_if_complete(line1: List[Optional[str]], line2: List[Optional[str]]) -> bool:
    return all(a is not None and b is not None and a == b for a, b in zip(line1, line2))

def _has_duplicate_complete(lines: List[List[Optional[str]]]) -> bool:
    seen = set()
    for ln in lines:
        if any(v is None for v in ln):
            continue
        t = tuple(ln)
        if t in seen:
            return True
        seen.add(t)
    return False

# ----------------------------
# State representation
# ----------------------------

@dataclass
class State:
    g: List[List[Optional[str]]]
    n: int
    row_known_mask: List[int]
    row_bits_b: List[int]
    col_known_mask: List[int]
    col_bits_b: List[int]

    @staticmethod
    def from_grid(grid: List[List[Optional[str]]]) -> "State":
        n = len(grid)
        row_known_mask = [0] * n
        row_bits_b = [0] * n
        col_known_mask = [0] * n
        col_bits_b = [0] * n
        for r in range(n):
            mk, bb = _line_to_bits(grid[r])
            row_known_mask[r] = mk
            row_bits_b[r] = bb
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            mk, bb = _line_to_bits(col)
            col_known_mask[c] = mk
            col_bits_b[c] = bb
        return State(grid, n, row_known_mask, row_bits_b, col_known_mask, col_bits_b)

    def clone(self) -> "State":
        n = self.n
        ng = [row[:] for row in self.g]
        return State(
            ng, n,
            self.row_known_mask[:], self.row_bits_b[:],
            self.col_known_mask[:], self.col_bits_b[:]
        )

    def set_cell(self, r: int, c: int, v: str) -> bool:
        cur = self.g[r][c]
        if cur is not None:
            return cur == v
        self.g[r][c] = v
        # update row masks
        bit = 1 << c
        self.row_known_mask[r] |= bit
        if v == B:
            self.row_bits_b[r] |= bit
        else:
            self.row_bits_b[r] &= ~bit
        # update col masks
        bitc = 1 << r
        self.col_known_mask[c] |= bitc
        if v == B:
            self.col_bits_b[c] |= bitc
        else:
            self.col_bits_b[c] &= ~bitc
        return True

    def row(self, r: int) -> List[Optional[str]]:
        return self.g[r]

    def col(self, c: int) -> List[Optional[str]]:
        return [self.g[r][c] for r in range(self.n)]

# ----------------------------
# Constraint checking & propagation
# ----------------------------

def _check_line_basic(line: List[Optional[str]]) -> bool:
    n = len(line)
    half = n // 2
    cb, cw, _ = _count_vals(line)
    if cb > half or cw > half:
        return False
    if not _no_three_possible(line):
        return False
    return True

def _check_state_basic(st: State) -> bool:
    n = st.n
    for r in range(n):
        if not _check_line_basic(st.row(r)):
            return False
    for c in range(n):
        if not _check_line_basic(st.col(c)):
            return False
    # completed uniqueness
    if _has_duplicate_complete([st.row(r) for r in range(n)]):
        return False
    if _has_duplicate_complete([st.col(c) for c in range(n)]):
        return False
    return True

def _uniqueness_prune(st: State) -> bool:
    # Fast prune: if two rows are already identical on all known positions AND both could still become identical fully,
    # we must ensure they can diverge. We prune only when they are complete and equal (handled elsewhere),
    # or when they are fully known on union of masks AND equal and union is complete (i.e., both complete).
    # Additionally: if two rows have same known mask == full and same bits => duplicate (already checked).
    # Here we add a stronger safe prune:
    # If two rows are compatible and one is complete, then the other cannot be completed to exactly that row.
    n = st.n
    full = (1 << n) - 1

    # rows
    for i in range(n):
        mi, bi = st.row_known_mask[i], st.row_bits_b[i]
        if mi == full:
            for j in range(n):
                if i == j:
                    continue
                mj, bj = st.row_known_mask[j], st.row_bits_b[j]
                if _compatible(mi, bi, mj, bj):
                    # if row j can still become equal to row i, forbid that:
                    # If all unknown cells in j are free, it might equal; but can we detect it's forced to equal?
                    # Safe prune only when mj|mi == full and they match on mj (compatibility already), but j has no way to differ
                    # would require all remaining cells in j are forced to match i. Hard to prove quickly; skip.
                    pass

    # columns analogous skipped for safety.
    return True

def propagate(st: State) -> bool:
    n = st.n
    changed = True
    while changed:
        changed = False

        # Balance + no-three on rows
        for r in range(n):
            line = st.row(r)
            # forced by no-three
            for idx, v in _apply_no_three_forced(line):
                if st.g[r][idx] is None:
                    if not st.set_cell(r, idx, v):
                        return False
                    changed = True
            # forced by balance
            bal = _apply_balance_forced(st.row(r))
            if bal is None:
                return False
            for idx, v in bal:
                if st.g[r][idx] is None:
                    if not st.set_cell(r, idx, v):
                        return False
                    changed = True

        # Balance + no-three on cols
        for c in range(n):
            col = st.col(c)
            for idx, v in _apply_no_three_forced(col):
                if st.g[idx][c] is None:
                    if not st.set_cell(idx, c, v):
                        return False
                    changed = True
            bal = _apply_balance_forced(st.col(c))
            if bal is None:
                return False
            for idx, v in bal:
                if st.g[idx][c] is None:
                    if not st.set_cell(idx, c, v):
                        return False
                    changed = True

        if not _check_state_basic(st):
            return False
        if not _uniqueness_prune(st):
            return False

    return True

# ----------------------------
# Smart branching
# ----------------------------

def _cell_score(st: State, r: int, c: int) -> int:
    # Heuristic: prioritize cells in most constrained row/col (more known, close to half, near creating triples)
    n = st.n
    row = st.row(r)
    col = st.col(c)
    rb, rw, ru = _count_vals(row)
    cb, cw, cu = _count_vals(col)
    known_row = n - ru
    known_col = n - cu
    # risk of triple locally
    risk = 0
    for dr, dc in ((0, -2), (0, -1), (0, 0)):
        pass
    # lightweight: adjacency known
    for rr, cc in ((r, c - 1), (r, c + 1), (r - 1, c), (r + 1, c)):
        if 0 <= rr < n and 0 <= cc < n and st.g[rr][cc] is not None:
            risk += 1
    # closeness to balance
    half = n // 2
    bal_tight = (half - max(rb, rw)) + (half - max(cb, cw))
    return known_row * 3 + known_col * 3 + risk * 2 - bal_tight

def choose_branch_cell(st: State) -> Optional[Tuple[int, int]]:
    n = st.n
    best = None
    best_score = -10**9
    for r in range(n):
        for c in range(n):
            if st.g[r][c] is None:
                sc = _cell_score(st, r, c)
                if sc > best_score:
                    best_score = sc
                    best = (r, c)
    return best

def is_solved(st: State) -> bool:
    n = st.n
    for r in range(n):
        if any(v is None for v in st.row(r)):
            return False
    # all constraints already ensured by propagate/check
    return True

def _finalize_and_check(st: State) -> bool:
    # Ensure uniqueness for all rows/cols at the end and balance.
    n = st.n
    rows = [tuple(st.row(r)) for r in range(n)]
    cols = [tuple(st.col(c)) for c in range(n)]
    if len(set(rows)) != n:
        return False
    if len(set(cols)) != n:
        return False
    half = n // 2
    for r in range(n):
        if rows[r].count(B) != half or rows[r].count(W) != half:
            return False
        for i in range(n - 2):
            if rows[r][i] == rows[r][i + 1] == rows[r][i + 2]:
                return False
    for c in range(n):
        if cols[c].count(B) != half or cols[c].count(W) != half:
            return False
        for i in range(n - 2):
            if cols[c][i] == cols[c][i + 1] == cols[c][i + 2]:
                return False
    return True

def search(st: State, depth: int = 0, limit_depth: int = 10_000) -> Optional[State]:
    if depth > limit_depth:
        return None
    if not propagate(st):
        return None
    if is_solved(st):
        return st if _finalize_and_check(st) else None

    rc = choose_branch_cell(st)
    if rc is None:
        return None
    r, c = rc

    # Value ordering: try the color that helps balance first.
    n = st.n
    half = n // 2
    rb, rw, _ = _count_vals(st.row(r))
    cb, cw, _ = _count_vals(st.col(c))

    prefs: List[str] = []
    if rb < half and cb < half:
        prefs.append(B)
    if rw < half and cw < half:
        prefs.append(W)
    if B not in prefs:
        prefs.append(B)
    if W not in prefs:
        prefs.append(W)

    for v in prefs:
        st2 = st.clone()
        if not st2.set_cell(r, c, v):
            continue
        res = search(st2, depth + 1, limit_depth)
        if res is not None:
            return res
    return None

# ----------------------------
# Public API
# ----------------------------

def solve(observation):
    grid = observation.get('data')
    if not grid or not isinstance(grid, list):
        return "No Solution"
    n = len(grid)
    if any(len(row) != n for row in grid):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"

    st = State.from_grid([row[:] for row in grid])
    if not _check_state_basic(st):
        return "No Solution"

    res = search(st)
    if res is None:
        return "No Solution"
    return [[v for v in row] for row in res.g]

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[-1, None, None, None, None, -1, -1, None, None, -1], [None, -1, None, None, None, None, None, None, -1, None], [None, None, None, None, None, None, 0, None, None, None], [0, None, -1, None, None, None, None, None, None, None], [-1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, -1], [None, None, None, None, None, None, None, -1, None, -1], [None, None, None, -1, None, None, None, None, None, None], [None, -1, None, None, None, None, None, None, -1, None], [-1, None, None, -1, -1, None, None, None, None, -1]]}
from collections import deque

# Akari / Light Up solver with strong human-like propagation + guided search.
# Board encoding:
# observation['data'][r][c] == None => white cell
# == -1 => black cell (unnumbered)
# == 0..4 => black numbered cell

DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if any(len(row) != n for row in grid):
        return "No Solution"

    # Index white cells
    white = []
    widx = [[-1] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                widx[r][c] = len(white)
                white.append((r, c))
    W = len(white)

    # Precompute visibility: for each white cell, all white cells in its line of sight (excluding itself)
    # plus segments for fast "unlit" accounting.
    visible = [[] for _ in range(W)]
    # Also precompute row/col segments separated by black cells: list of lists of white indices
    segments = []
    seg_of = [-1] * W

    def inb(r, c):
        return 0 <= r < n and 0 <= c < n

    # Build segments by scanning rows and cols, to later use "must place bulb if cell is only one that can light itself"
    # But in Akari, a cell can be lit by any bulb in same segment (row) or (col) segment.
    # We'll create "line groups": maximal contiguous whites in each row and col.
    line_groups = []  # each is list of white indices
    cell_to_groups = [[] for _ in range(W)]

    # Row groups
    for r in range(n):
        c = 0
        while c < n:
            while c < n and grid[r][c] is not None:
                c += 1
            start = c
            while c < n and grid[r][c] is None:
                c += 1
            if c > start:
                g = []
                for cc in range(start, c):
                    g.append(widx[r][cc])
                gid = len(line_groups)
                line_groups.append(g)
                for wi in g:
                    cell_to_groups[wi].append(gid)
            c += 0

    # Col groups
    for c in range(n):
        r = 0
        while r < n:
            while r < n and grid[r][c] is not None:
                r += 1
            start = r
            while r < n and grid[r][c] is None:
                r += 1
            if r > start:
                g = []
                for rr in range(start, r):
                    g.append(widx[rr][c])
                gid = len(line_groups)
                line_groups.append(g)
                for wi in g:
                    cell_to_groups[wi].append(gid)
            r += 0

    # Visibility lists
    for i, (r, c) in enumerate(white):
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            while inb(rr, cc) and grid[rr][cc] is None:
                visible[i].append(widx[rr][cc])
                rr += dr
                cc += dc

    # For numbered blacks: adjacency lists of white indices orthogonally adjacent
    numbered = []
    nb_adj = []
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if isinstance(v, int) and v >= 0:
                adj = []
                for dr, dc in DIRS:
                    rr, cc = r + dr, c + dc
                    if inb(rr, cc) and grid[rr][cc] is None:
                        adj.append(widx[rr][cc])
                numbered.append((r, c, v))
                nb_adj.append(adj)

    # State arrays for each white cell:
    # val: -1 unknown, 0 forced no-bulb, 1 bulb
    val = [-1] * W

    # Track bulbs and illumination counts
    lit = [0] * W  # number of bulbs lighting this cell (including itself if bulb)
    # For fast conflict checking between bulbs:
    # We'll maintain for each cell whether it is "attacked" by an existing bulb (lit>0 via others) but that's same as lit>0.
    # For "no bulb may illuminate another bulb", ensure any bulb cell has no other bulb visible.

    # For numbered constraint tracking:
    nb_need = [num for (_, _, num) in numbered]
    nb_have = [0] * len(numbered)
    nb_unknown = [0] * len(numbered)
    # initialize unknown counts
    for k, adj in enumerate(nb_adj):
        nb_unknown[k] = len(adj)

    # For each cell, which numbered blacks it touches (0-4)
    cell_to_numbered = [[] for _ in range(W)]
    for k, adj in enumerate(nb_adj):
        for wi in adj:
            cell_to_numbered[wi].append(k)

    # For each line group, track how many bulbs in group and unknowns; group is "lighting domain":
    # A cell is lit if there is a bulb in any of its two groups (row and col) that sees it, but group bulbs may be blocked by black within group no.
    # In a group, any bulb lights all cells in that group (since group is contiguous with no black), yes.
    # So to ensure every cell lit, for each cell, at least one bulb in its row-group OR col-group.
    g_bulbs = [0] * len(line_groups)
    g_unknown = [len(g) for g in line_groups]

    # Additionally, classic Akari rule: if a cell has a bulb then all visible cells cannot be bulbs.
    # We'll use propagation queue of assignments.

    trail = []  # stack for undo: list of (kind, idx, old)
    # kind: 'val','lit','nb_have','nb_unknown','g_bulbs','g_unknown'

    def set_val(i, newv):
        old = val[i]
        if old == newv:
            return True
        if old != -1 and old != newv:
            return False
        trail.append(("val", i, old))
        val[i] = newv
        # update group unknown counts
        if old == -1:
            for gid in cell_to_groups[i]:
                trail.append(("g_unknown", gid, g_unknown[gid]))
                g_unknown[gid] -= 1
        return True

    def add_lit(i, delta):
        if delta == 0:
            return
        trail.append(("lit", i, lit[i]))
        lit[i] += delta

    def inc_nb_have(k, delta):
        if delta == 0:
            return
        trail.append(("nb_have", k, nb_have[k]))
        nb_have[k] += delta

    def inc_nb_unknown(k, delta):
        if delta == 0:
            return
        trail.append(("nb_unknown", k, nb_unknown[k]))
        nb_unknown[k] += delta

    def inc_g_bulbs(gid, delta):
        if delta == 0:
            return
        trail.append(("g_bulbs", gid, g_bulbs[gid]))
        g_bulbs[gid] += delta

    def undo(to_len):
        while len(trail) > to_len:
            kind, idx, old = trail.pop()
            if kind == "val":
                val[idx] = old
            elif kind == "lit":
                lit[idx] = old
            elif kind == "nb_have":
                nb_have[idx] = old
            elif kind == "nb_unknown":
                nb_unknown[idx] = old
            elif kind == "g_bulbs":
                g_bulbs[idx] = old
            elif kind == "g_unknown":
                g_unknown[idx] = old
            else:
                raise RuntimeError("bad trail kind")

    def place_bulb(i):
        # assign bulb and enforce constraints
        if not set_val(i, 1):
            return False

        # cannot place bulb if any visible cell already has bulb
        for j in visible[i]:
            if val[j] == 1:
                return False

        # update group bulbs
        for gid in cell_to_groups[i]:
            inc_g_bulbs(gid, 1)

        # bulb lights itself and all visible cells; also lights along to group cells but visible captures all in lines.
        add_lit(i, 1)
        for j in visible[i]:
            add_lit(j, 1)

        # all visible cells cannot be bulbs
        for j in visible[i]:
            if val[j] == -1:
                if not set_val(j, 0):
                    return False

        # numbered adjacency updates
        for k in cell_to_numbered[i]:
            inc_nb_have(k, 1)
            inc_nb_unknown(k, -1)
        return True

    def forbid_bulb(i):
        if not set_val(i, 0):
            return False
        for k in cell_to_numbered[i]:
            inc_nb_unknown(k, -1)
        return True

    # Initialize nb_unknown already counted; but if we later set values, we update.
    # Need to subtract unknown counts for any preset? none.

    # Propagation rules (human-like):
    # - Numbered cell: if have > need or have + unknown < need => contradiction
    # - Numbered: if have == need => all adjacent unknown are no-bulb
    # - Numbered: if have + unknown == need => all adjacent unknown are bulbs
    # - If a white cell is unlit and all potential bulb positions that could light it are forbidden => contradiction
    # - If an unlit white cell has exactly one possible bulb position that can light it => that position must be bulb
    # We approximate "possible bulb positions to light cell" as itself and all visible cells (because any bulb in line lights it).
    # But bulbs can't be on already-forbidden cells.
    could_light = [[] for _ in range(W)]
    for i in range(W):
        lst = [i] + visible[i]
        # also reverse visibility: cells in same row/col segment; visible list already both directions, but includes cells further.
        # Actually "bulb at j lights i" iff j in [i]+visible[i] (since visibility is symmetric in empty segment).
        could_light[i] = lst

    # For fast checking "domain size", we'll compute on the fly.

    def check_numbered():
        for k in range(len(numbered)):
            need = nb_need[k]
            have = nb_have[k]
            unk = nb_unknown[k]
            if have > need:
                return False
            if have + unk < need:
                return False
        return True

    def propagate():
        q = deque()
        # seed with all numbered constraints and all cells
        for k in range(len(numbered)):
            q.append(("nb", k))
        for i in range(W):
            q.append(("cell", i))

        inq_nb = [True] * len(numbered)
        inq_cell = [True] * W

        while q:
            typ, idx = q.popleft()
            if typ == "nb":
                inq_nb[idx] = False
                need = nb_need[idx]
                have = nb_have[idx]
                unk = nb_unknown[idx]
                if have > need or have + unk < need:
                    return False
                adj = nb_adj[idx]
                if unk == 0:
                    continue
                if have == need:
                    # all adjacent unknown -> no-bulb
                    for wi in adj:
                        if val[wi] == -1:
                            tlen = len(trail)
                            if not forbid_bulb(wi):
                                undo(tlen)
                                return False
                            # enqueue affected
                            for k2 in cell_to_numbered[wi]:
                                if not inq_nb[k2]:
                                    inq_nb[k2] = True
                                    q.append(("nb", k2))
                            for ci in [wi] + visible[wi]:
                                if not inq_cell[ci]:
                                    inq_cell[ci] = True
                                    q.append(("cell", ci))
                elif have + unk == need:
                    # all adjacent unknown -> bulbs
                    for wi in adj:
                        if val[wi] == -1:
                            tlen = len(trail)
                            if not place_bulb(wi):
                                undo(tlen)
                                return False
                            for k2 in cell_to_numbered[wi]:
                                if not inq_nb[k2]:
                                    inq_nb[k2] = True
                                    q.append(("nb", k2))
                            # bulb affects many cells
                            for ci in [wi] + visible[wi]:
                                if not inq_cell[ci]:
                                    inq_cell[ci] = True
                                    q.append(("cell", ci))
                            # also cells that can see wi might have their singleton-light options changed
                            for vci in visible[wi]:
                                if not inq_cell[vci]:
                                    inq_cell[vci] = True
                                    q.append(("cell", vci))
            else:
                inq_cell[idx] = False
                i = idx
                # If already bulb and lit by others -> conflict (another bulb sees it)
                if val[i] == 1 and lit[i] > 1:
                    return False
                # Illumination feasibility / singleton-light rule
                if lit[i] == 0:
                    # compute possible bulb positions that could light i
                    opts = []
                    for j in could_light[i]:
                        if val[j] == 1:
                            opts = [j]
                            break
                        if val[j] == -1:
                            # candidate must not see an existing bulb
                            ok = True
                            for v in visible[j]:
                                if val[v] == 1:
                                    ok = False
                                    break
                            if ok:
                                opts.append(j)
                    if not opts:
                        return False
                    if len(opts) == 1:
                        j = opts[0]
                        if val[j] != 1:
                            tlen = len(trail)
                            if not place_bulb(j):
                                undo(tlen)
                                return False
                            # enqueue impacted
                            for k2 in cell_to_numbered[j]:
                                if not inq_nb[k2]:
                                    inq_nb[k2] = True
                                    q.append(("nb", k2))
                            for ci in [j] + visible[j]:
                                if not inq_cell[ci]:
                                    inq_cell[ci] = True
                                    q.append(("cell", ci))
                            for vci in visible[j]:
                                if not inq_cell[vci]:
                                    inq_cell[vci] = True
                                    q.append(("cell", vci))
                # Additional: if cell is unknown but cannot be bulb due to seeing bulb, force no-bulb.
                if val[i] == -1:
                    for v in visible[i]:
                        if val[v] == 1:
                            tlen = len(trail)
                            if not forbid_bulb(i):
                                undo(tlen)
                                return False
                            for k2 in cell_to_numbered[i]:
                                if not inq_nb[k2]:
                                    inq_nb[k2] = True
                                    q.append(("nb", k2))
                            break
        return check_numbered()

    # Initial propagation
    if not propagate():
        return "No Solution"

    def is_solved():
        if any(l == 0 for l in lit):
            return False
        if any(v == -1 for v in val):
            # can be solved even with unknowns if all lit and numbered satisfied, but bulbs/no-bulb must be decided to avoid future conflicts.
            return False
        # numbered already checked
        return True

    # Choose branching variable with strong heuristic:
    # prefer unlit cell with smallest lighting options; else prefer cell involved in tight numbered constraint.
    def choose_var():
        best = None
        best_dom = 10 ** 9
        # prioritize unlit cells
        for i in range(W):
            if lit[i] == 0:
                dom = 0
                for j in could_light[i]:
                    if val[j] == 1:
                        dom = 1
                        break
                    if val[j] == -1:
                        ok = True
                        for v in visible[j]:
                            if val[v] == 1:
                                ok = False
                                break
                        if ok:
                            dom += 1
                if dom < best_dom:
                    best_dom = dom
                    best = ("lightcell", i)
                    if dom <= 2:
                        break
        if best is not None:
            return best

        # then numbered constraints with smallest slack
        bestk = -1
        bestslack = 10 ** 9
        for k in range(len(numbered)):
            need = nb_need[k]
            have = nb_have[k]
            unk = nb_unknown[k]
            if unk == 0:
                continue
            slack = (have + unk) - need  # how many can still be zero
            if slack < bestslack:
                bestslack = slack
                bestk = k
        if bestk != -1:
            # pick an adjacent unknown cell
            for wi in nb_adj[bestk]:
                if val[wi] == -1:
                    return ("cell", wi)

        # fallback: any unknown cell with most constraints (visibility + numbered)
        besti = -1
        bestscore = -1
        for i in range(W):
            if val[i] == -1:
                score = len(visible[i]) + 3 * len(cell_to_numbered[i])
                if score > bestscore:
                    bestscore = score
                    besti = i
        if besti != -1:
            return ("cell", besti)
        return None

    def dfs():
        if is_solved():
            return True
        var = choose_var()
        if var is None:
            # all decided but maybe some unlit? (shouldn't happen)
            return False

        kind, x = var
        # Branch ordering: try placing bulb first when it helps lighting or satisfies numbered need.
        # If chosen by unlit cell, try bulb positions that light it in sorted order (prefer itself).
        branches = []

        if kind == "lightcell":
            i = x
            cand = []
            for j in could_light[i]:
                if val[j] == -1:
                    ok = True
                    for v in visible[j]:
                        if val[v] == 1:
                            ok = False
                            break
                    if ok:
                        cand.append(j)
                elif val[j] == 1:
                    cand = [j]
                    break
            # if already lit by bulb, shouldn't be here
            if not cand:
                return False
            # try each candidate as bulb (forced-choice search)
            for j in cand:
                branches.append(("bulb", j))
        else:
            i = x
            branches = [("bulb", i), ("nobulb", i)]

        for bkind, i in branches:
            tlen = len(trail)
            ok = True
            if bkind == "bulb":
                ok = place_bulb(i)
            else:
                ok = forbid_bulb(i)
            if ok and propagate():
                if dfs():
                    return True
            undo(tlen)
        return False

    if not dfs():
        return "No Solution"

    # Build answer grid: 'B' for bulbs else None
    ans = [[None] * n for _ in range(n)]
    for i, (r, c) in enumerate(white):
        if val[i] == 1:
            ans[r][c] = "B"
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 1, 1, 1, 1], [0, 0, 1, 2, 2, 1], [3, 0, 0, 0, 2, 1], [3, 3, 4, 0, 2, 2], [3, 4, 4, 4, 4, 2], [3, 3, 3, 4, 2, 2]]}

from collections import defaultdict, deque
from itertools import product

# Tetromino types: L, I, T, S (S includes Z by reflection)
# We'll treat "type" as one of {'L','I','T','S'} regardless of orientation/reflection.
# Shapes are encoded as 4 offsets including (0,0); all orientations precomputed.

def _norm(cells):
    rmin = min(r for r, c in cells)
    cmin = min(c for r, c in cells)
    return tuple(sorted((r - rmin, c - cmin) for r, c in cells))

def _rot90(cells):
    # (r,c) -> (c, -r)
    return [(c, -r) for r, c in cells]

def _refx(cells):
    # reflect across vertical axis: (r,c)->(r,-c)
    return [(r, -c) for r, c in cells]

def _all_orients(base):
    seen = set()
    out = []
    cur = base
    for _ in range(4):
        cur = _rot90(cur)
        for rf in (False, True):
            cc = _refx(cur) if rf else cur
            nm = _norm(cc)
            if nm not in seen:
                seen.add(nm)
                out.append(nm)
    return out

def _build_shapes():
    bases = {
        'I': [(0,0),(1,0),(2,0),(3,0)],
        'L': [(0,0),(1,0),(2,0),(2,1)],
        'T': [(0,0),(0,1),(0,2),(1,1)],
        'S': [(0,1),(0,2),(1,0),(1,1)],  # S; reflection gives Z
    }
    shapes = {t: _all_orients(cells) for t, cells in bases.items()}
    # Deduplicate orientations further (some shapes like I have 2 unique)
    for t in shapes:
        shapes[t] = sorted(set(shapes[t]))
    return shapes

SHAPES = _build_shapes()

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if any(len(row) != n for row in grid):
        return "No Solution"

    # Regions
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            region_cells[grid[r][c]].append((r,c))
    region_ids = sorted(region_cells.keys())
    R = len(region_ids)

    # Region adjacency (orthogonally)
    reg_adj = {rid: set() for rid in region_ids}
    for r in range(n):
        for c in range(n):
            rid = grid[r][c]
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                rr, cc = r+dr, c+dc
                if 0 <= rr < n and 0 <= cc < n:
                    rid2 = grid[rr][cc]
                    if rid2 != rid:
                        reg_adj[rid].add(rid2)

    # Each region must place exactly one tetromino of size 4.
    # Precompute for each region: all placements (as frozenset of cells) with type.
    # Placement must be subset of region cells; and does not create a 2x2 fully shaded by itself? (check later globally)
    region_set = {rid: set(region_cells[rid]) for rid in region_ids}

    def in_bounds(cell):
        r,c = cell
        return 0 <= r < n and 0 <= c < n

    # List all tetromino placements in a region by anchoring each orientation at each cell.
    region_placements = {rid: [] for rid in region_ids}  # list of (type, frozenset(cells))
    for rid in region_ids:
        cells = region_set[rid]
        for t, orients in SHAPES.items():
            for shape in orients:
                # shape is normalized offsets; anchor at every region cell
                for ar, ac in cells:
                    placed = [(ar + dr, ac + dc) for dr, dc in shape]
                    if all(in_bounds(p) and p in cells for p in placed):
                        fs = frozenset(placed)
                        region_placements[rid].append((t, fs))
        # Deduplicate identical placements that could arise from different anchor/orient combos
        uniq = {}
        for t, fs in region_placements[rid]:
            # a placement has a unique cell set; type is unique for that placement
            # if same fs appears with same type keep one; if appears with different type, keep both (rare/impossible)
            uniq.setdefault((t, fs), 1)
        region_placements[rid] = [(t, fs) for (t, fs) in uniq.keys()]

        # Immediate infeasible
        if not region_placements[rid]:
            return "No Solution"

    # Global constraints:
    # - Adjacent regions cannot have same type.
    # - All shaded cells connected globally.
    # - No 2x2 fully shaded.

    # Data structures for fast propagation
    all_cells = [(r,c) for r in range(n) for c in range(n)]
    cell_to_regions = defaultdict(set)
    for rid in region_ids:
        for cell in region_cells[rid]:
            cell_to_regions[cell].add(rid)

    # For 2x2 blocks, precompute blocks as tuples of 4 cells
    blocks2 = []
    for r in range(n-1):
        for c in range(n-1):
            blocks2.append(((r,c),(r+1,c),(r,c+1),(r+1,c+1)))

    # Build for each region and each type: placements list
    region_type_placements = {rid: defaultdict(list) for rid in region_ids}
    for rid in region_ids:
        for t, fs in region_placements[rid]:
            region_type_placements[rid][t].append(fs)

    # Domain: possible placements indices per region
    # We'll keep as list of (t, fs) and a bitmask-like "active" boolean list for speed.
    # Also maintain mapping from placement to its type and cells.
    placements = {rid: region_placements[rid] for rid in region_ids}

    # Ordering heuristic: smallest domain first; tie-break by region degree
    def region_order(domains):
        return sorted(region_ids, key=lambda rid: (len(domains[rid]), -len(reg_adj[rid])))

    # Utility: compute forced shaded / forced unshaded for a region from its domain
    def forced_cells(dom):
        # dom: list of (t, fs)
        it = iter(dom)
        try:
            _, first = next(it)
        except StopIteration:
            return set(), set()
        inter = set(first)
        union = set(first)
        for _, fs in it:
            inter &= fs
            union |= fs
        # forced shaded = inter; forced unshaded within region = region_set - union (never shaded)
        return inter, (None, None), union  # keep union for convenience

    # Fast check: type adjacency
    def compatible_type(rid, t, assign_type):
        for nb in reg_adj[rid]:
            tt = assign_type.get(nb)
            if tt is not None and tt == t:
                return False
        return True

    # Connectivity pruning:
    # We can only fully check connectivity when all regions assigned.
    # But we can also prune early using "possible connectivity": shaded cells chosen so far must be in one component,
    # and unassigned regions must have at least one cell adjacent to current component or could bridge.
    # We'll implement a lightweight necessary condition:
    # - If there are already shaded cells, every unassigned region must have at least one cell adjacent (4-neigh)
    #   to either an already-shaded cell OR to a cell in some other unassigned region that could connect later via adjacency chains.
    # We'll approximate by building a graph of regions by whether any of their cells are adjacent (region adjacency itself),
    # and require that all regions are in the same connected component as some region that already has shaded cells (if any),
    # which is always true because region adjacency graph for puzzle may be connected; not strong enough.
    # Instead, use cell-level adjacency between "possible shaded cells": each region has a union of cells that could be shaded.
    # We ensure that the union graph is connected and that already-shaded cells are not split into multiple components.
    def connectivity_necessary(domains, assigned_cells):
        if not assigned_cells:
            return True
        # assigned_cells must be connected themselves (as we never assign per-cell, but placement; still check)
        comp = set()
        start = next(iter(assigned_cells))
        dq = deque([start])
        comp.add(start)
        while dq:
            r,c = dq.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nb = (r+dr,c+dc)
                if nb in assigned_cells and nb not in comp:
                    comp.add(nb); dq.append(nb)
        if comp != assigned_cells:
            return False

        # Build possible shaded set = assigned_cells U union of remaining domains
        possible = set(assigned_cells)
        for rid in region_ids:
            if rid in domains:
                # if unassigned: add union of all placement cells
                # but if already assigned, its domain might be singleton and already included via assigned_cells
                dom = domains[rid]
                if len(dom) == 0:
                    return False
                # union quickly
                u = set()
                for _, fs in dom:
                    u |= fs
                possible |= u

        # Necessary: every cell in possible that's chosen later can connect; but too hard.
        # Use weaker: the possible set should be connected (otherwise impossible to have final connected).
        start2 = next(iter(possible))
        comp2 = set([start2])
        dq = deque([start2])
        while dq:
            r,c = dq.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nb = (r+dr,c+dc)
                if nb in possible and nb not in comp2:
                    comp2.add(nb); dq.append(nb)
        return comp2 == possible

    # 2x2 pruning:
    # Maintain assigned shaded cells; ensure no 2x2 already full; also ensure no 2x2 is forced full by domains.
    def blocks_ok(domains, assigned_cells):
        asg = assigned_cells
        # quick already full
        for b in blocks2:
            if all(cell in asg for cell in b):
                return False
        # forced full: if for some block, each of its 4 cells is either already shaded or is forced shaded by its region's domain
        # compute forced shaded per region lazily cached
        forced = {}
        def forced_for_region(rid):
            if rid in forced:
                return forced[rid]
            dom = domains[rid]
            if len(dom) == 0:
                forced[rid] = set()
                return forced[rid]
            it = iter(dom)
            _, first = next(it)
            inter = set(first)
            for _, fs in it:
                inter &= fs
            forced[rid] = inter
            return inter

        for b in blocks2:
            ok = False
            for cell in b:
                if cell in asg:
                    continue
                rid = grid[cell[0]][cell[1]]
                inter = forced_for_region(rid)
                if cell not in inter:
                    ok = True
                    break
            if not ok:
                # all cells are either already shaded or forced shaded => block will be full
                return False
        return True

    # Domain filtering based on already assigned shaded cells, 2x2 partial, and type adjacency.
    # Since each cell belongs to exactly one region, overlaps between regions cannot happen; no conflict.
    # But we still use filtering for type adjacency.
    def filter_domain_for_assignment(dom, rid, assign_type):
        # rid is being assigned later; filter by neighboring assigned types
        if not assign_type:
            return dom
        out = []
        for t, fs in dom:
            if compatible_type(rid, t, assign_type):
                out.append((t, fs))
        return out

    # Main propagation: AC-like between regions via type adjacency
    def propagate(domains, assign_type, assigned_cells):
        changed = True
        while changed:
            changed = False

            # Filter each unassigned region domain by type adjacency to assigned neighbors.
            for rid in region_ids:
                dom = domains[rid]
                if len(dom) == 0:
                    return False
                if len(dom) == 1:
                    continue
                nd = filter_domain_for_assignment(dom, rid, assign_type)
                if len(nd) != len(dom):
                    domains[rid] = nd
                    dom = nd
                    changed = True
                    if len(dom) == 0:
                        return False

            # If a region is singleton, record its type and shaded cells (idempotent)
            for rid in region_ids:
                dom = domains[rid]
                if len(dom) == 1:
                    t, fs = dom[0]
                    if assign_type.get(rid) is None:
                        # check type compatibility
                        if not compatible_type(rid, t, assign_type):
                            return False
                        assign_type[rid] = t
                        # add shaded
                        before = len(assigned_cells)
                        assigned_cells |= set(fs)
                        if len(assigned_cells) != before:
                            changed = True

            # Pairwise region adjacency: if two adjacent regions only have same single possible type, eliminate.
            # More generally, enforce arc consistency on "types differ" constraint:
            # For each edge (a,b), remove placements of a with type t if b has no placement with type != t.
            for a in region_ids:
                for b in reg_adj[a]:
                    if a > b:
                        continue
                    da = domains[a]
                    db = domains[b]
                    if not da or not db:
                        return False
                    # possible types in b
                    types_b = set(t for t, _ in db)
                    types_a = set(t for t, _ in da)
                    # prune a
                    if len(types_b) == 1:
                        tb = next(iter(types_b))
                        nda = [p for p in da if p[0] != tb]
                        if len(nda) != len(da):
                            domains[a] = nda
                            changed = True
                            if not nda:
                                return False
                    # prune b
                    if len(types_a) == 1:
                        ta = next(iter(types_a))
                        ndb = [p for p in db if p[0] != ta]
                        if len(ndb) != len(db):
                            domains[b] = ndb
                            changed = True
                            if not ndb:
                                return False

            # Global prunes
            if not blocks_ok(domains, assigned_cells):
                return False
            if not connectivity_necessary(domains, assigned_cells):
                return False

        return True

    # Initialize domains
    domains0 = {rid: placements[rid][:] for rid in region_ids}
    assign_type0 = {rid: None for rid in region_ids}
    assigned_cells0 = set()

    if not propagate(domains0, assign_type0, assigned_cells0):
        return "No Solution"

    # DFS with strong heuristics: choose region with smallest domain; value ordering by connectivity (prefer placements that touch existing component)
    def placement_score(fs, assigned_cells):
        if not assigned_cells:
            return 0
        # count adjacency edges to assigned cells
        sc = 0
        for r,c in fs:
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                if (r+dr, c+dc) in assigned_cells:
                    sc += 1
        return -sc  # more adjacency first

    def dfs(domains, assign_type, assigned_cells):
        # Check completion
        done = all(len(domains[rid]) == 1 for rid in region_ids)
        if done:
            # Final connectivity check and 2x2 check (already enforced), but ensure all shaded connected
            # assigned_cells already full set
            # connectivity:
            start = next(iter(assigned_cells))
            dq = deque([start])
            seen = {start}
            while dq:
                r,c = dq.popleft()
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nb = (r+dr,c+dc)
                    if nb in assigned_cells and nb not in seen:
                        seen.add(nb); dq.append(nb)
            if seen != assigned_cells:
                return None
            # Build output grid: shade cells with region's tetromino type letter, others None
            out = [[None for _ in range(n)] for _ in range(n)]
            for rid in region_ids:
                t, fs = domains[rid][0]
                for (r,c) in fs:
                    out[r][c] = t
            return out

        # Select region with MRV
        rid = min((r for r in region_ids if len(domains[r]) > 1), key=lambda r: (len(domains[r]), -len(reg_adj[r])))
        dom = domains[rid]

        # Value ordering
        ordered = sorted(dom, key=lambda p: (placement_score(p[1], assigned_cells), p[0]))
        for t, fs in ordered:
            if not compatible_type(rid, t, assign_type):
                continue
            # Copy state (optimized shallow copies)
            ndomains = {r: domains[r] for r in region_ids}
            # Set singleton
            ndomains = ndomains.copy()
            ndomains[rid] = [(t, fs)]

            nassign_type = assign_type.copy()
            nassigned_cells = set(assigned_cells)
            # Propagate with singleton assignment
            if not propagate(ndomains, nassign_type, nassigned_cells):
                continue
            res = dfs(ndomains, nassign_type, nassigned_cells)
            if res is not None:
                return res
        return None

    sol = dfs(domains0, assign_type0, assigned_cells0)
    return sol if sol is not None else "No Solution"


