from collections import deque, defaultdict

# Slitherlink solver:
# - Variables are edges between adjacent dots.
# - Constraints:
#   (1) Each clue cell: number of surrounding edges equals clue.
#   (2) Each dot: degree is 0 or 2 (single loop, no branches).
# - We enforce "single loop" at end, but prune early using:
#   - degree upper bounds, forced degree satisfaction
#   - subtour prevention: avoid creating a smaller closed loop before all edges decided
# - Human-like deductions implemented as local propagation rules:
#   - Cell sum bounds (if remaining edges count equals remaining needed => force ON; if needed==0 => force OFF)
#   - Dot degree bounds (if deg==2 force remaining incident OFF; if deg==1 and only one undecided => force ON; if deg==0 and only two undecided and must reach 2? no, since 0 is allowed; but we can use "can't strand" checks)
#   - Pattern rules for 0 and 3/4 equivalents are encompassed by cell sum forcing.
# - Search uses MRV (most constrained variable): pick undecided edge involved in tightest constraints.

EDGE_OFF = 0
EDGE_ON = 1
EDGE_UNK = -1

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    # dots are (r,c) with r,c in [0..n]
    # edges:
    # horizontal edges between (r,c)-(r,c+1): r in [0..n], c in [0..n-1]
    # vertical edges between (r,c)-(r+1,c): r in [0..n-1], c in [0..n]
    #
    # We'll index all edges in a flat list for speed.
    # Map edge -> endpoints, and incidence lists.
    e_endpoints = []
    e_cells = []  # adjacent cells for each edge (0..2 cells)
    e_is_h = []
    e_index_h = [[None]*(n) for _ in range(n+1)]  # (r,c) for segment to (r,c+1)
    e_index_v = [[None]*(n+1) for _ in range(n)]  # (r,c) for segment to (r+1,c)

    def add_edge(p, q, is_h, cells):
        idx = len(e_endpoints)
        e_endpoints.append((p, q))
        e_is_h.append(is_h)
        e_cells.append(cells)
        return idx

    # Build edges and adjacency to cells
    # Cell (r,c) has corners (r,c),(r,c+1),(r+1,c+1),(r+1,c)
    # Surrounding edges:
    # top: h(r,c), right: v(r,c+1), bottom: h(r+1,c), left: v(r,c)
    for r in range(n+1):
        for c in range(n):
            # horizontal edge
            cells = []
            if r > 0:
                cells.append((r-1, c))
            if r < n:
                cells.append((r, c))
            idx = add_edge((r, c), (r, c+1), True, cells)
            e_index_h[r][c] = idx
    for r in range(n):
        for c in range(n+1):
            cells = []
            if c > 0:
                cells.append((r, c-1))
            if c < n:
                cells.append((r, c))
            idx = add_edge((r, c), (r+1, c), False, cells)
            e_index_v[r][c] = idx

    m = len(e_endpoints)

    # Precompute cell -> 4 edge indices
    cell_edges = [[None]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            top = e_index_h[r][c]
            bottom = e_index_h[r+1][c]
            left = e_index_v[r][c]
            right = e_index_v[r][c+1]
            cell_edges[r][c] = (top, right, bottom, left)

    # Precompute dot -> incident edge indices
    dot_inc = [[[] for _ in range(n+1)] for __ in range(n+1)]
    for ei, (p, q) in enumerate(e_endpoints):
        (r1, c1) = p
        (r2, c2) = q
        dot_inc[r1][c1].append(ei)
        dot_inc[r2][c2].append(ei)

    # Utility: DSU for current ON edges, to detect premature cycles (subtours)
    class DSU:
        __slots__ = ("p", "r", "size")
        def __init__(self, N):
            self.p = list(range(N))
            self.r = [0]*N
            self.size = [1]*N
        def find(self, a):
            p = self.p
            while p[a] != a:
                p[a] = p[p[a]]
                a = p[a]
            return a
        def union(self, a, b):
            a = self.find(a); b = self.find(b)
            if a == b:
                return False
            ra = self.r[a]; rb = self.r[b]
            if ra < rb:
                a, b = b, a
            self.p[b] = a
            self.size[a] += self.size[b]
            if ra == rb:
                self.r[a] += 1
            return True
        def comp_size(self, a):
            return self.size[self.find(a)]

    # Dot id for DSU
    def dot_id(r, c):
        return r*(n+1) + c
    num_dots = (n+1)*(n+1)

    # State
    edges = [EDGE_UNK]*m
    # degree at dots from ON edges
    deg = [[0]*(n+1) for _ in range(n+1)]
    on_count = 0

    # For fast constraint checks, maintain per cell counts
    cell_on = [[0]*n for _ in range(n)]
    cell_unk = [[4]*n for _ in range(n)]

    # Trail stack for backtracking
    trail = []

    # enqueue propagation items
    q = deque()

    def push_change(kind, *data):
        trail.append((kind, data))

    def set_edge(ei, val):
        nonlocal on_count
        cur = edges[ei]
        if cur == val:
            return True
        if cur != EDGE_UNK and cur != val:
            return False
        # record
        push_change("edge", ei, cur)
        edges[ei] = val
        (p, qd) = e_endpoints[ei]
        r1, c1 = p; r2, c2 = qd

        if val == EDGE_ON:
            on_count += 1
            push_change("deg", (r1, c1), deg[r1][c1])
            push_change("deg", (r2, c2), deg[r2][c2])
            deg[r1][c1] += 1
            deg[r2][c2] += 1
        # update cells counts
        for (cr, cc) in e_cells[ei]:
            push_change("cell", (cr, cc), (cell_on[cr][cc], cell_unk[cr][cc]))
            if val == EDGE_ON:
                cell_on[cr][cc] += 1
            cell_unk[cr][cc] -= 1

        # schedule affected constraints propagation
        q.append(("edge_set", ei))
        for (cr, cc) in e_cells[ei]:
            q.append(("cell", cr, cc))
        q.append(("dot", r1, c1))
        q.append(("dot", r2, c2))
        return True

    def undo(to_len):
        nonlocal on_count
        while len(trail) > to_len:
            kind, data = trail.pop()
            if kind == "edge":
                (ei, prev) = data
                # adjust on_count? handled by deg/cell restores; but do explicitly for speed/robustness
                if edges[ei] == EDGE_ON and prev != EDGE_ON:
                    on_count -= 1
                elif edges[ei] != EDGE_ON and prev == EDGE_ON:
                    on_count += 1
                edges[ei] = prev
            elif kind == "deg":
                (pos, prev) = data
                r, c = pos
                deg[r][c] = prev
            elif kind == "cell":
                (pos, prevpair) = data
                r, c = pos
                cell_on[r][c], cell_unk[r][c] = prevpair
            else:
                raise RuntimeError("bad trail kind")

    def cell_possible(cr, cc):
        clue = grid[cr][cc]
        if clue is None:
            return True
        on = cell_on[cr][cc]
        unk = cell_unk[cr][cc]
        # on <= clue <= on+unk
        return (on <= clue <= on + unk)

    def dot_possible(r, c):
        d = deg[r][c]
        if d > 2:
            return False
        # If all incident edges decided and d == 1 => impossible (cannot have open end)
        inc = dot_inc[r][c]
        unk = 0
        for ei in inc:
            if edges[ei] == EDGE_UNK:
                unk += 1
        if unk == 0 and d == 1:
            return False
        # If d == 2, remaining must be OFF (prop handles)
        # If d == 1 and unk == 0 already covered
        # If d == 0, ok (can be unused)
        # If d == 1 and unk >= 1, must be possible to reach degree 2: always if unk>=1.
        # If d == 0 and unk == 1, setting it ON would create d==1 and then impossible since no more edges -> but dot_possible above catches once decided.
        return True

    def propagate_cell(cr, cc):
        clue = grid[cr][cc]
        if clue is None:
            return True
        if not cell_possible(cr, cc):
            return False
        on = cell_on[cr][cc]
        unk = cell_unk[cr][cc]
        if unk == 0:
            return True
        need = clue - on
        # If need == 0 -> all remaining OFF
        if need == 0:
            for ei in cell_edges[cr][cc]:
                if edges[ei] == EDGE_UNK:
                    if not set_edge(ei, EDGE_OFF):
                        return False
        # If need == unk -> all remaining ON
        elif need == unk:
            for ei in cell_edges[cr][cc]:
                if edges[ei] == EDGE_UNK:
                    if not set_edge(ei, EDGE_ON):
                        return False
        return True

    def propagate_dot(r, c):
        if not dot_possible(r, c):
            return False
        d = deg[r][c]
        inc = dot_inc[r][c]
        unk_edges = [ei for ei in inc if edges[ei] == EDGE_UNK]
        if d == 2:
            # force all remaining OFF
            for ei in unk_edges:
                if not set_edge(ei, EDGE_OFF):
                    return False
        elif d == 1:
            # if only one remaining can satisfy degree==2, force it ON when it's the last undecided
            if len(unk_edges) == 1:
                if not set_edge(unk_edges[0], EDGE_ON):
                    return False
            # also if no remaining, dot_possible already handled
        else:  # d == 0
            # if three incident are OFF, last must be OFF too? not necessary; degree 0 allowed.
            # But if only one incident edge remains UNK and all others OFF,
            # setting it ON would create dangling end => thus it must be OFF.
            if len(unk_edges) == 1:
                # if all decided others are OFF (since d==0)
                if not set_edge(unk_edges[0], EDGE_OFF):
                    return False
        return True

    def propagate():
        while q:
            kind, *rest = q.popleft()
            if kind == "cell":
                cr, cc = rest
                if not propagate_cell(cr, cc):
                    return False
            elif kind == "dot":
                r, c = rest
                if not propagate_dot(r, c):
                    return False
            elif kind == "edge_set":
                ei = rest[0]
                # fast sanity checks on adjacent constraints
                for (cr, cc) in e_cells[ei]:
                    if not cell_possible(cr, cc):
                        return False
                (p, qd) = e_endpoints[ei]
                if not dot_possible(*p) or not dot_possible(*qd):
                    return False
            else:
                raise RuntimeError("bad queue item")
        return True

    # Initialize propagation from all cells/dots
    for r in range(n):
        for c in range(n):
            q.append(("cell", r, c))
    for r in range(n+1):
        for c in range(n+1):
            q.append(("dot", r, c))
    if not propagate():
        return "No Solution"

    # Helper to detect premature small loops (subtours)
    def has_premature_cycle_if_add(ei, dsu):
        (p, qd) = e_endpoints[ei]
        a = dot_id(*p)
        b = dot_id(*qd)
        # if already connected and adding edge will close a cycle
        if dsu.find(a) == dsu.find(b):
            # This would form a cycle. Allow only if it would include all ON edges and all undecided edges are OFF? Too strict.
            # Human rule: avoid closing a loop unless all vertices in that component are degree 2
            # and no other ON edges exist outside the component.
            return True
        return False

    def build_dsu_from_on():
        dsu = DSU(num_dots)
        for ei, v in enumerate(edges):
            if v == EDGE_ON:
                (p, qd) = e_endpoints[ei]
                dsu.union(dot_id(*p), dot_id(*qd))
        return dsu

    def all_clues_satisfied():
        for r in range(n):
            for c in range(n):
                clue = grid[r][c]
                if clue is None:
                    continue
                if cell_on[r][c] != clue:
                    return False
        return True

    def all_dots_valid_final():
        for r in range(n+1):
            for c in range(n+1):
                d = deg[r][c]
                if d not in (0, 2):
                    return False
        return True

    def extract_loop():
        # Build adjacency from ON edges, then traverse loop
        adj = defaultdict(list)
        for ei, v in enumerate(edges):
            if v == EDGE_ON:
                p, qd = e_endpoints[ei]
                adj[p].append(qd)
                adj[qd].append(p)
        # find a start dot with degree 2
        start = None
        for p, neigh in adj.items():
            if len(neigh) == 2:
                start = p
                break
        if start is None:
            return None
        # traverse
        loop = [start]
        prev = None
        cur = start
        while True:
            neigh = adj[cur]
            if len(neigh) != 2:
                return None
            nxt = neigh[0] if neigh[0] != prev else neigh[1]
            prev, cur = cur, nxt
            loop.append(cur)
            if cur == start:
                break
            if len(loop) > on_count + 2:
                return None
        # verify uses all ON edges (single cycle)
        if len(loop) - 1 != on_count:
            return None
        return loop

    # Variable ordering heuristic: choose undecided edge with tightest constraints
    def pick_edge():
        best = None
        best_score = -1
        for ei, v in enumerate(edges):
            if v != EDGE_UNK:
                continue
            score = 0
            # clues adjacent
            for (cr, cc) in e_cells[ei]:
                clue = grid[cr][cc]
                if clue is not None:
                    # tighter when close to bound
                    on = cell_on[cr][cc]
                    unk = cell_unk[cr][cc]
                    need = clue - on
                    score += 10
                    score += 5 if need in (0, unk) else 0
                    score += 3 if need in (1, unk-1) else 0
            # dots adjacent
            p, qd = e_endpoints[ei]
            for (r, c) in (p, qd):
                d = deg[r][c]
                score += 6
                if d == 1:
                    score += 6
                elif d == 2:
                    score += 100  # should have been forced OFF already; but keep high
            if score > best_score:
                best_score = score
                best = ei
        return best

    def search():
        # Check completion
        if all(v != EDGE_UNK for v in edges):
            if not all_clues_satisfied():
                return None
            if not all_dots_valid_final():
                return None
            loop = extract_loop()
            return loop

        ei = pick_edge()
        if ei is None:
            return None

        # Try ON then OFF, but use quick subtour check when trying ON
        # Build DSU once per node for speed
        dsu = build_dsu_from_on()

        for val in (EDGE_ON, EDGE_OFF):
            tlen = len(trail)
            q.clear()
            ok = True
            if val == EDGE_ON:
                # prune: cannot exceed dot degree 2, and avoid closing a small cycle
                p, qd = e_endpoints[ei]
                if deg[p[0]][p[1]] >= 2 or deg[qd[0]][qd[1]] >= 2:
                    ok = False
                else:
                    if has_premature_cycle_if_add(ei, dsu):
                        ok = False
            if ok and set_edge(ei, val) and propagate():
                # Additional prune: if any clue impossible already checked; also ensure no dot stranded (handled)
                res = search()
                if res is not None:
                    return res
            undo(tlen)
        return None

    loop = search()
    if loop is None:
        return "No Solution"
    return str(loop)

