    idx_cells = {rid: [cand_blocks[rid][i][1] for i in range(len(cand_blocks[rid]))] for rid in region_ids}
    idx_blocks = {rid: [cand_blocks[rid][i][2] for i in range(len(cand_blocks[rid]))] for rid in region_ids}

