    # Forward checking / propagation (human-like):
    # - Enforce neighbor type constraints by filtering domains after assignment.
    # - Enforce mandatory connectivity potential: if shaded exists, keep only candidates touching shaded or that
    #   can become connected via other unassigned regions? We keep only immediate touching as strong prune
    #   (works well for these puzzles).
    def propagate(queue):
        # queue: list of region ids whose assignment/type affects neighbors
        pruned_stack = []  # list of (rid, removed_indices)
        while queue:
            rid = queue.pop()
            if rid not in region_type:
