OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, None, None, 'W', 'W', None, None, 'B'], ['W', None, 'B', None, None, 'W', 'W', None], ['W', None, None, None, None, 'W', None, None], [None, None, None, 'B', None, None, None, None], [None, None, 'W', None, None, None, 'B', None], [None, None, None, None, None, None, None, 'B'], [None, None, 'W', None, 'W', 'W', None, None]]}
from __future__ import annotations

# Binary Puzzle / Takuzu solver:
# - Equal number of B/W per row/col
# - No three consecutive same in any row/col
# - All rows pairwise distinct; all cols pairwise distinct
# - Given cells fixed
#
# Approach: human-like deduction + aggressive propagation + limited backtracking (MRV).
# Key techniques:
# 1) Local "no-3" rules (XX_ and X_X imply opposite).
# 2) Count completion rules (if B or W hits n/2, fill rest with opposite).
# 3) Pattern-based forced moves via line feasibility: enumerate completions of a line (row/col)
#    consistent with local and count constraints; intersect to derive forced cells.
# 4) Uniqueness pruning: if a line becomes complete, forbid any other line from matching it.
#    If a line is one cell away from matching an existing complete line, force it to differ.
# 5) Backtracking only after propagation reaches fixpoint; choose cell with smallest domain (MRV).

B, W, U = 'B', 'W', None

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    if n == 0 or any(len(r) != n for r in grid) or (n % 2 != 0):
        return "No Solution"
    half = n // 2

    # Validate initial fixed cells quickly
    if not _validate_grid(grid):
        return "No Solution"

    # Propagate + search
    res = _search(grid, n, half)
    if res is None:
        return "No Solution"
    return res

def _search(grid, n, half):
    st = _State(grid, n, half)
    if not st.propagate():
        return None
    if st.is_solved():
        return st.grid

    r, c, dom = st.pick_mrv_cell()
    if r is None:
        return None

    # Try values with a light heuristic: prefer value that helps balance counts
    for v in st.order_domain(r, c, dom):
        child = st.copy()
        if not child.assign(r, c, v):
            continue
        out = _search(child.grid, n, half)
        if out is not None:
            return out
    return None

class _State:
    __slots__ = ("grid", "n", "half", "rowB", "rowW", "colB", "colW",
                 "rowU", "colU", "dirty_rows", "dirty_cols")

    def __init__(self, grid, n, half):
        self.grid = [r[:] for r in grid]
        self.n = n
        self.half = half
        self.rowB = [0]*n
        self.rowW = [0]*n
        self.colB = [0]*n
        self.colW = [0]*n
        self.rowU = [0]*n
        self.colU = [0]*n
        for r in range(n):
            for c in range(n):
                v = self.grid[r][c]
                if v is U:
                    self.rowU[r] += 1
                    self.colU[c] += 1
                elif v == B:
                    self.rowB[r] += 1
                    self.colB[c] += 1
                else:
                    self.rowW[r] += 1
                    self.colW[c] += 1
        self.dirty_rows = set(range(n))
        self.dirty_cols = set(range(n))

    def copy(self):
        cp = _State(self.grid, self.n, self.half)
        cp.dirty_rows = set(self.dirty_rows)
        cp.dirty_cols = set(self.dirty_cols)
        return cp

    def is_solved(self):
        n = self.n
        for r in range(n):
            if self.rowU[r] != 0:
                return False
        return _validate_complete(self.grid)

    def assign(self, r, c, v):
        cur = self.grid[r][c]
        if cur is not U:
            return cur == v
        # update counts
        self.grid[r][c] = v
        self.rowU[r] -= 1
        self.colU[c] -= 1
        if v == B:
            self.rowB[r] += 1
            self.colB[c] += 1
        else:
            self.rowW[r] += 1
            self.colW[c] += 1
        # basic early count infeasibility
        if self.rowB[r] > self.half or self.rowW[r] > self.half:
            return False
        if self.colB[c] > self.half or self.colW[c] > self.half:
            return False
        # mark affected lines dirty
        self.dirty_rows.add(r)
        self.dirty_cols.add(c)
        return True

    def propagate(self):
        # Iterate until fixpoint
        while self.dirty_rows or self.dirty_cols:
            if self.dirty_rows:
                r = self.dirty_rows.pop()
                if not self._process_row(r):
                    return False
            else:
                c = self.dirty_cols.pop()
                if not self._process_col(c):
                    return False
        return True

    def _process_row(self, r):
        n = self.n
        # 1) Local no-three in row
        if not self._apply_no3_line(r, is_row=True):
            return False

        # 2) Count completion in row
        if not self._apply_count_fill_line(r, is_row=True):
            return False

        # 3) Feasibility-based forced moves (line completion intersection)
        if not self._apply_line_feasibility_forces(r, is_row=True):
            return False

        # 4) Uniqueness pruning against completed rows
        if not self._apply_uniqueness_forces_line(r, is_row=True):
            return False

        # Also ensure partial row doesn't already violate uniqueness possibility when all rows complete later:
        # done via feasibility/uniqueness checks above.
        return True

    def _process_col(self, c):
        # 1) Local no-three in col
        if not self._apply_no3_line(c, is_row=False):
            return False

        # 2) Count completion in col
        if not self._apply_count_fill_line(c, is_row=False):
            return False

        # 3) Feasibility-based forced moves
        if not self._apply_line_feasibility_forces(c, is_row=False):
            return False

        # 4) Uniqueness pruning against completed cols
        if not self._apply_uniqueness_forces_line(c, is_row=False):
            return False
        return True

    def _get_line(self, idx, is_row):
        if is_row:
            return self.grid[idx]
        return [self.grid[r][idx] for r in range(self.n)]

    def _set_cell_in_line(self, idx, pos, is_row, v):
        if is_row:
            return self.assign(idx, pos, v)
        else:
            return self.assign(pos, idx, v)

    def _apply_no3_line(self, idx, is_row):
        line = self._get_line(idx, is_row)
        n = self.n
        for i in range(n-2):
            a, b, c = line[i], line[i+1], line[i+2]
            # XX_ => _ is opposite
            if a is not U and a == b and c is U:
                if not self._set_cell_in_line(idx, i+2, is_row, _opp(a)):
                    return False
            if b is not U and b == c and a is U:
                if not self._set_cell_in_line(idx, i, is_row, _opp(b)):
                    return False
            # X_X => middle is opposite
            if a is not U and c is not U and a == c and b is U:
                if not self._set_cell_in_line(idx, i+1, is_row, _opp(a)):
                    return False
        return True

    def _apply_count_fill_line(self, idx, is_row):
        if is_row:
            b = self.rowB[idx]; w = self.rowW[idx]; u = self.rowU[idx]
        else:
            b = self.colB[idx]; w = self.colW[idx]; u = self.colU[idx]
        if b > self.half or w > self.half:
            return False
        if u == 0:
            return True
        if b == self.half:
            # rest must be W
            line = self._get_line(idx, is_row)
            for j, v in enumerate(line):
                if v is U:
                    if not self._set_cell_in_line(idx, j, is_row, W):
                        return False
        elif w == self.half:
            # rest must be B
            line = self._get_line(idx, is_row)
            for j, v in enumerate(line):
                if v is U:
                    if not self._set_cell_in_line(idx, j, is_row, B):
                        return False
        return True

    def _apply_line_feasibility_forces(self, idx, is_row):
        line = self._get_line(idx, is_row)
        if all(v is not U for v in line):
            return True

        # Enumerate all completions consistent with:
        # - no-three locally
        # - exact half counts
        # Keep small via recursion with pruning; n is typically <= 14-16.
        completions = []
        max_keep = 512  # cap to avoid blowup; still sufficient for inference
        targetB = self.half
        targetW = self.half

        fixedB = sum(1 for v in line if v == B)
        fixedW = sum(1 for v in line if v == W)
        if fixedB > targetB or fixedW > targetW:
            return False

        # Precompute to speed recursion
        line0 = line[:]
        def ok_no3_at(pos, arr):
            # check triples involving pos
            for i in (pos-2, pos-1, pos):
                if 0 <= i <= self.n-3:
                    x, y, z = arr[i], arr[i+1], arr[i+2]
                    if x is not U and x == y == z:
                        return False
            return True

        arr = line0[:]
        unknown_positions = [i for i, v in enumerate(arr) if v is U]

        def rec(k, bcnt, wcnt):
            if len(completions) >= max_keep:
                return
            if bcnt > targetB or wcnt > targetW:
                return
            remaining = len(unknown_positions) - k
            if bcnt + remaining < targetB or wcnt + remaining < targetW:
                return
            if k == len(unknown_positions):
                if bcnt == targetB and wcnt == targetW:
                    # final no3 check already enforced incrementally
                    completions.append(arr[:])
                return
            pos = unknown_positions[k]

            # Try B then W with quick pruning against neighboring fixed pattern constraints
            for val in (B, W):
                if val == B and bcnt == targetB:
                    continue
                if val == W and wcnt == targetW:
                    continue
                arr[pos] = val
                if ok_no3_at(pos, arr):
                    rec(k+1, bcnt + (val == B), wcnt + (val == W))
                arr[pos] = U

        rec(0, fixedB, fixedW)
        if not completions:
            return False

        # Intersect: any position that is same across all completions is forced
        for j, v in enumerate(line):
            if v is not U:
                continue
            forced = completions[0][j]
            if all(comp[j] == forced for comp in completions[1:]):
                if not self._set_cell_in_line(idx, j, is_row, forced):
                    return False
        return True

    def _apply_uniqueness_forces_line(self, idx, is_row):
        n = self.n
        line = self._get_line(idx, is_row)

        # Collect completed lines (rows or cols)
        completed = []
        if is_row:
            for r in range(n):
                if r != idx and self.rowU[r] == 0:
                    completed.append((r, tuple(self.grid[r])))
        else:
            for c in range(n):
                if c != idx and self.colU[c] == 0:
                    completed.append((c, tuple(self.grid[r][c] for r in range(n))))

        # If this line is complete, it must be unique
        if all(v is not U for v in line):
            t = tuple(line)
            for j, tt in completed:
                if t == tt:
                    return False
            return True

        # If this line could still become identical to a completed line, force a difference.
        # Human-like: if for some completed line, all fixed cells already match and only one
        # unknown remains, that unknown must be opposite of that completed value.
        for _, comp in completed:
            # Check compatibility with current partial line
            compatible = True
            mismatches = 0
            unknowns = []
            for k in range(n):
                v = line[k]
                if v is U:
                    unknowns.append(k)
                else:
                    if v != comp[k]:
                        compatible = False
                        break
            if not compatible:
                continue
            # If no unknowns, would be equal (handled above, but keep safe)
            if not unknowns:
                return False
            if len(unknowns) == 1:
                k = unknowns[0]
                if not self._set_cell_in_line(idx, k, is_row, _opp(comp[k])):
                    return False
        return True

    def pick_mrv_cell(self):
        n = self.n
        best = None
        best_dom = None

        # Quick scans; compute domain via local constraints + counts.
        for r in range(n):
            if self.rowU[r] == 0:
                continue
            for c in range(n):
                if self.grid[r][c] is not U:
                    continue
                dom = self.domain(r, c)
                if not dom:
                    return (None, None, None)
                if best is None or len(dom) < len(best_dom):
                    best = (r, c)
                    best_dom = dom
                    if len(dom) == 1:
                        return (r, c, dom)
        if best is None:
            return (None, None, None)
        return (best[0], best[1], best_dom)

    def domain(self, r, c):
        # Domain based on counts + no-three immediate constraints.
        if self.grid[r][c] is not U:
            return {self.grid[r][c]}
        dom = {B, W}
        # counts
        if self.rowB[r] >= self.half:
            dom.discard(B)
        if self.rowW[r] >= self.half:
            dom.discard(W)
        if self.colB[c] >= self.half:
            dom.discard(B)
        if self.colW[c] >= self.half:
            dom.discard(W)
        if not dom:
            return set()

        # no-three check if assign each candidate
        out = set()
        for v in dom:
            if _no3_ok_if_set(self.grid, r, c, v):
                out.add(v)
        return out

    def order_domain(self, r, c, dom):
        # Prefer value that balances row/col towards half
        if len(dom) == 1:
            return tuple(dom)
        score = []
        for v in dom:
            rb = self.rowB[r] + (v == B)
            rw = self.rowW[r] + (v == W)
            cb = self.colB[c] + (v == B)
            cw = self.colW[c] + (v == W)
            # smaller imbalance is better
            s = abs(rb - self.half) + abs(rw - self.half) + abs(cb - self.half) + abs(cw - self.half)
            score.append((s, v))
        score.sort()
        return [v for _, v in score]

def _opp(x):
    return W if x == B else B

def _no3_ok_if_set(grid, r, c, v):
    n = len(grid)
    # check row triples involving c
    for j in (c-2, c-1, c):
        if 0 <= j <= n-3:
            a = v if j == c else grid[r][j]
            b = v if j+1 == c else grid[r][j+1]
            d = v if j+2 == c else grid[r][j+2]
            if a is not U and a == b == d:
                return False
    # check col triples involving r
    for i in (r-2, r-1, r):
        if 0 <= i <= n-3:
            a = v if i == r else grid[i][c]
            b = v if i+1 == r else grid[i+1][c]
            d = v if i+2 == r else grid[i+2][c]
            if a is not U and a == b == d:
                return False
    return True

def _validate_grid(grid):
    n = len(grid)
    if n % 2 != 0:
        return False
    half = n // 2
    # no-three for already fixed triples
    for r in range(n):
        for c in range(n-2):
            a, b, d = grid[r][c], grid[r][c+1], grid[r][c+2]
            if a is not U and a == b == d:
                return False
    for c in range(n):
        for r in range(n-2):
            a, b, d = grid[r][c], grid[r+1][c], grid[r+2][c]
            if a is not U and a == b == d:
                return False
    # count feasibility
    for r in range(n):
        b = sum(1 for v in grid[r] if v == B)
        w = sum(1 for v in grid[r] if v == W)
        if b > half or w > half:
            return False
    for c in range(n):
        b = sum(1 for r in range(n) if grid[r][c] == B)
        w = sum(1 for r in range(n) if grid[r][c] == W)
        if b > half or w > half:
            return False
    return True

def _validate_complete(grid):
    n = len(grid)
    half = n // 2
    # counts, no3, uniqueness
    rows = []
    for r in range(n):
        row = grid[r]
        if any(v is U for v in row):
            return False
        if row.count(B) != half or row.count(W) != half:
            return False
        for c in range(n-2):
            if row[c] == row[c+1] == row[c+2]:
                return False
        rows.append(tuple(row))
    if len(set(rows)) != n:
        return False

    cols = []
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if col.count(B) != half or col.count(W) != half:
            return False
        for r in range(n-2):
            if col[r] == col[r+1] == col[r+2]:
                return False
        cols.append(tuple(col))
    if len(set(cols)) != n:
        return False
    return True

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None, None, 3], [3, None, None, 2, 2, None, None, None, 1, None], [None, None, None, 2, 3, 2, 0, None, 3, 2], [None, None, 1, None, None, None, 1, None, 2, 3], [None, 1, None, None, 3, 3, 3, 3, 2, None], [None, None, 3, None, 2, None, None, 2, 2, None], [None, None, 1, None, 2, None, None, 1, 1, 2], [None, 3, None, 2, None, None, None, 2, None, None], [None, None, None, 2, 3, None, None, 2, 1, None], [None, 3, None, 2, 3, None, 1, 2, None, 3]]}
# Slitherlink solver (single closed loop) with human-like deductions + backtracking.
# Grid: clues are N x N cells, dots are (N+1) x (N+1).
# We model each possible edge between adjacent dots as variable in {0(off),1(on)}.
# Constraints:
# 1) Each clue cell requires sum of its 4 surrounding edges == clue.
# 2) Each dot must have degree in {0,2}; in final solution, all used edges form exactly one cycle.
# Deductions:
# - For each clue, force edges when remaining needed equals remaining undecided etc.
# - For each dot, enforce degree cannot exceed 2; if degree==2, other incident edges off; if remaining possible edges == needed, force on.
# - Connectivity / subtour prevention: detect multiple disjoint cycles early; avoid closing a smaller cycle unless all edges decided.
# Search: choose variable with highest impact (edge in most constraints) and branch 1 then 0.

from collections import deque, defaultdict

def solve(observation):
    grid = observation["data"]
    N = len(grid)
    if any(len(r) != N for r in grid):
        return "No Solution"

    # Enumerate edges
    # Horizontal edges: (r,c)-(r,c+1) for r in [0..N], c in [0..N-1]
    # Vertical edges: (r,c)-(r+1,c) for r in [0..N-1], c in [0..N]
    # Represent edge by integer id, store endpoints (u,v) as dot indices.
    # Dot index = r*(N+1)+c
    D = N + 1
    def dot_id(r, c): return r * D + c
    def dot_rc(i): return divmod(i, D)

    edges_u = []
    edges_v = []
    edge_of = {}  # (u,v)->eid, u<v
    incident = [[] for _ in range(D * D)]
    cell_edges = [[None]*N for _ in range(N)]  # list of 4 eids per cell
    edge_cells = defaultdict(list)  # eid -> list of (r,c)

    def add_edge(u, v):
        if u > v: u, v = v, u
        eid = len(edges_u)
        edges_u.append(u); edges_v.append(v)
        edge_of[(u, v)] = eid
        incident[u].append(eid)
        incident[v].append(eid)
        return eid

    # Build edges
    # horizontals
    for r in range(D):
        for c in range(N):
            u = dot_id(r, c)
            v = dot_id(r, c+1)
            add_edge(u, v)
    # verticals
    for r in range(N):
        for c in range(D):
            u = dot_id(r, c)
            v = dot_id(r+1, c)
            add_edge(u, v)

    E = len(edges_u)

    def get_edge_between(r1, c1, r2, c2):
        u = dot_id(r1, c1)
        v = dot_id(r2, c2)
        if u > v: u, v = v, u
        return edge_of[(u, v)]

    # Map cell to its 4 edges: top, right, bottom, left
    for r in range(N):
        for c in range(N):
            top = get_edge_between(r, c, r, c+1)
            right = get_edge_between(r, c+1, r+1, c+1)
            bottom = get_edge_between(r+1, c, r+1, c+1)
            left = get_edge_between(r, c, r+1, c)
            cell_edges[r][c] = (top, right, bottom, left)
            for eid in (top, right, bottom, left):
                edge_cells[eid].append((r, c))

    # Precompute edge->dots
    eu, ev = edges_u, edges_v

    # State arrays
    # -1 unknown, 0 off, 1 on
    val = [-1] * E
    deg = [0] * (D * D)              # current degree (on edges)
    unk_inc = [len(incident[i]) for i in range(D*D)]  # unknown incident edges count
    # For each cell: clue, on_count, unk_count
    clue = [[grid[r][c] for c in range(N)] for r in range(N)]
    cell_on = [[0]*N for _ in range(N)]
    cell_unk = [[4]*N for _ in range(N)]

    # Frontier for propagation
    q = deque()

    # Helper: set edge with consistency checks, enqueue affected constraints
    def set_edge(eid, x):
        if val[eid] == x:
            return True
        if val[eid] != -1 and val[eid] != x:
            return False
        val[eid] = x
        u, v = eu[eid], ev[eid]
        # Update dot degrees / unknown counts
        if x == 1:
            deg[u] += 1
            deg[v] += 1
            if deg[u] > 2 or deg[v] > 2:
                return False
        # unknown count decreases at both ends always
        unk_inc[u] -= 1
        unk_inc[v] -= 1
        # enqueue dots and adjacent cells
        q.append(("dot", u))
        q.append(("dot", v))
        for (r, c) in edge_cells.get(eid, []):
            if clue[r][c] is not None:
                if x == 1:
                    cell_on[r][c] += 1
                cell_unk[r][c] -= 1
                q.append(("cell", r, c))
        return True

    # Initial enqueue all clue cells
    for r in range(N):
        for c in range(N):
            if clue[r][c] is not None:
                q.append(("cell", r, c))

    # Deduction rules
    def propagate():
        while q:
            item = q.popleft()
            if item[0] == "cell":
                r, c = item[1], item[2]
                k = clue[r][c]
                if k is None:
                    continue
                on = cell_on[r][c]
                unk = cell_unk[r][c]
                if on > k or on + unk < k:
                    return False
                if unk == 0:
                    continue
                # If need all remaining unknown edges
                if on + unk == k:
                    for eid in cell_edges[r][c]:
                        if val[eid] == -1:
                            if not set_edge(eid, 1):
                                return False
                # If already satisfied, all remaining unknown off
                if on == k:
                    for eid in cell_edges[r][c]:
                        if val[eid] == -1:
                            if not set_edge(eid, 0):
                                return False

            else:  # dot
                d = item[1]
                # Degree constraints: allowed {0,2} final; during solving, degree<=2.
                if deg[d] > 2:
                    return False
                # If degree==2, all other incident unknown edges must be off
                if deg[d] == 2:
                    for eid in incident[d]:
                        if val[eid] == -1:
                            if not set_edge(eid, 0):
                                return False
                # If degree==1 and only one unknown remains, it must be on to reach 2 (unless dot ends up 0, but that would require degree 0)
                # More generally: degree can be 0 or 2, so remaining_on_needed is either (0 - deg) impossible unless deg==0,
                # or (2 - deg). If deg>0, must reach 2.
                unk = 0
                unknown_eids = []
                for eid in incident[d]:
                    if val[eid] == -1:
                        unk += 1
                        unknown_eids.append(eid)
                if deg[d] == 1:
                    if unk == 0:
                        return False
                    if unk == 1:
                        if not set_edge(unknown_eids[0], 1):
                            return False
                elif deg[d] == 0:
                    # If only 1 unknown left, it must be off (can't reach degree 2 with one edge)
                    if unk == 1:
                        if not set_edge(unknown_eids[0], 0):
                            return False
                # If deg==0 and unk==2 and we already know at least one incident is on? not possible; skip.
        return True

    # Connectivity / cycle checks
    def components_and_cycles():
        # Build adjacency from ON edges
        adj = [[] for _ in range(D*D)]
        used_nodes = set()
        on_edges = []
        for eid in range(E):
            if val[eid] == 1:
                u, v = eu[eid], ev[eid]
                adj[u].append(v)
                adj[v].append(u)
                used_nodes.add(u); used_nodes.add(v)
                on_edges.append(eid)
        # Detect any node with degree 1 (in terms of on-edges) is allowed during partial, but in final must be none.
        # Detect closed cycles: connected component where every node has degree 2.
        seen = set()
        cycles = 0
        comps = 0
        for s in used_nodes:
            if s in seen:
                continue
            comps += 1
            stack = [s]
            seen.add(s)
            all_deg2 = True
            nodes = 0
            edges_count2 = 0
            while stack:
                x = stack.pop()
                nodes += 1
                dx = len(adj[x])
                if dx != 2:
                    all_deg2 = False
                edges_count2 += dx
                for y in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            # edges_count2 is 2*edges in comp
            if all_deg2 and nodes > 0:
                cycles += 1
        return comps, cycles

    def premature_small_cycle_check():
        # If there's a cycle while there still exist unknown edges that could connect elsewhere,
        # then it's only allowed if it's the final single loop and no other on edges elsewhere.
        comps, cycles = components_and_cycles()
        if cycles == 0:
            return True
        # If more than 1 cycle -> impossible
        if cycles > 1:
            return False
        # If one cycle exists and there are other ON edges outside it, that's covered by cycles>1? not necessarily.
        # But if there is a cycle and also some node in used set not in that cycle would imply another component; allow only if no other components.
        if comps > 1:
            return False
        # If cycle is formed but there are still undecided edges that are ON in future? That would create branches; but could still extend by breaking cycle impossible.
        # Hence if a complete cycle exists before all edges decided, it must already satisfy all clues and all remaining edges must be OFF.
        # We approximate: if a cycle exists and there is any unknown edge that touches any node in used loop, it must be OFF already due to deg=2 propagation.
        # Remaining unknown edges elsewhere must be OFF too, otherwise they'd be unused dots deg 0 ok but would not violate; however clues might force them on.
        # To stay safe and strong: require that all clue constraints are already satisfied with current assignments (i.e., each clue's remaining feasible includes possibility with all remaining unknown edges off).
        for r in range(N):
            for c in range(N):
                k = clue[r][c]
                if k is None:
                    continue
                on = cell_on[r][c]
                unk = cell_unk[r][c]
                # If any clue still needs additional ON edges, cycle cannot be final.
                if on < k:
                    return False
        return True

    # Variable selection heuristic
    edge_score = [0]*E
    for eid in range(E):
        score = 0
        score += len(edge_cells.get(eid, [])) * 3
        u, v = eu[eid], ev[eid]
        score += 1 if len(incident[u]) <= 3 else 0
        score += 1 if len(incident[v]) <= 3 else 0
        edge_score[eid] = score

    def pick_edge():
        best = -1
        best_key = None
        for eid in range(E):
            if val[eid] != -1:
                continue
            # prioritize edges adjacent to clues and constrained dots
            u, v = eu[eid], ev[eid]
            key = (edge_score[eid],
                   -min(unk_inc[u], unk_inc[v]),
                   -(deg[u] + deg[v]))
            if best_key is None or key > best_key:
                best_key = key
                best = eid
        return best

    # Snapshot/restore (fast enough for typical sizes)
    def snapshot():
        return (val[:], deg[:], unk_inc[:], [row[:] for row in cell_on], [row[:] for row in cell_unk], list(q))

    def restore(snap):
        nonlocal val, deg, unk_inc, cell_on, cell_unk, q
        val, deg, unk_inc, cell_on, cell_unk, qlist = snap
        q = deque(qlist)

    def all_assigned():
        return all(x != -1 for x in val)

    def final_check():
        # all clues exact
        for r in range(N):
            for c in range(N):
                k = clue[r][c]
                if k is None:
                    continue
                if cell_on[r][c] != k:
                    return False
        # dot degrees must be 0 or 2; and used edges must form single loop
        used = [i for i in range(D*D) if deg[i] > 0]
        if not used:
            return False
        for i in range(D*D):
            if deg[i] not in (0, 2):
                return False
        comps, cycles = components_and_cycles()
        return cycles == 1 and comps == 1

    def build_loop_path():
        # Extract loop as ordered list of dot (row,col). Start at smallest dot id used.
        adj = [[] for _ in range(D*D)]
        used_nodes = []
        for eid in range(E):
            if val[eid] == 1:
                u, v = eu[eid], ev[eid]
                adj[u].append(v); adj[v].append(u)
        for i in range(D*D):
            if adj[i]:
                used_nodes.append(i)
        if not used_nodes:
            return None
        start = min(used_nodes)
        path = [start]
        prev = -1
        cur = start
        while True:
            nxts = adj[cur]
            if len(nxts) != 2:
                return None
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            prev, cur = cur, nxt
            path.append(cur)
            if cur == start:
                break
            if len(path) > len(used_nodes) + 2:
                return None
        # Convert to (row,col)
        out = [dot_rc(i) for i in path]
        return out

    def dfs():
        if not propagate():
            return None
        if not premature_small_cycle_check():
            return None
        if all_assigned():
            if final_check():
                return build_loop_path()
            return None
        eid = pick_edge()
        if eid == -1:
            return None
        # Branching order: try ON first typically beneficial for loop puzzles with clues
        for x in (1, 0):
            snap = snapshot()
            if set_edge(eid, x):
                res = dfs()
                if res is not None:
                    return res
            restore(snap)
        return None

    res = dfs()
    if res is None:
        return "No Solution"
    return str(res)

