    # Initial propagation
    if not propagate():
        return "No Solution"

    def solved():
        return all(x == 0 for x in need_row) and all(x == 0 for x in need_col) and all(x == 0 for x in need_reg)

    def select_branch():
        # Choose the most constrained unmet unit among rows/cols/regions.
