from collections import defaultdict

# Star Battle (1-star) solver with human-like constraint propagation:
# - Model as exact-one constraints for rows/cols/regions
# - Non-touching (incl. diagonal) adjacency constraints
# - Aggressive propagation: singles, hidden singles, and forced exclusions
# - Backtracking only when necessary with MRV + degree heuristics

def solve(observation):
    R = observation["data"]
    n = len(R)
    if any(len(row) != n for row in R):
        return "No Solution"

    # Regions
    reg_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            reg_cells[R[r][c]].append((r, c))
    region_ids = list(reg_cells.keys())
    m = len(region_ids)

    # Basic sanity: every region must have at least 1 cell
    if any(len(reg_cells[k]) == 0 for k in region_ids):
        return "No Solution"

    # Adjacency (including diagonals)
    neigh = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            ns = []
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n:
                        ns.append((rr, cc))
            neigh[r][c] = ns

    # Units
    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]
    reg_list = [reg_cells[k] for k in region_ids]

    # Map each cell -> unit indices
    cell_region = [[None] * n for _ in range(n)]
    reg_index = {rid: i for i, rid in enumerate(region_ids)}
    for rid, cells in reg_cells.items():
        idx = reg_index[rid]
        for (r, c) in cells:
            cell_region[r][c] = idx

    # Candidate sets for each unit (initially all cells in the unit)
    # We'll maintain forbidden cells via placement and propagate.
    # State:
    #   star[r][c] = True/False/None (None undecided)
    #   row_need[r], col_need[c], reg_need[k] each 0/1
    #   alive[r][c] = whether cell can still be a star candidate
    #
    # Invariant: if a unit need==1, at least one alive cell remains there.

    # Precompute unit membership to speed up hidden-single detection
    cell_in_row = [(r, c, r) for r in range(n) for c in range(n)]
    cell_in_col = [(r, c, c) for r in range(n) for c in range(n)]
    cell_in_reg = [(r, c, cell_region[r][c]) for r in range(n) for c in range(n)]

    # Helper: build list of cells for each region index
    reg_cells_by_index = [None] * m
    for rid, idx in reg_index.items():
        reg_cells_by_index[idx] = reg_cells[rid]

    # Bitset acceleration for alive candidates per unit (Python int bitmask)
    # index cell -> bit position
    cell_id = [[r * n + c for c in range(n)] for r in range(n)]
    id_to_rc = [(i // n, i % n) for i in range(n * n)]
    full_mask = (1 << (n * n)) - 1

    row_mask = [0] * n
    col_mask = [0] * n
    reg_mask = [0] * m
    for r in range(n):
        mask = 0
        for c in range(n):
            mask |= 1 << cell_id[r][c]
        row_mask[r] = mask
    for c in range(n):
        mask = 0
        for r in range(n):
            mask |= 1 << cell_id[r][c]
        col_mask[c] = mask
    for k in range(m):
        mask = 0
        for (r, c) in reg_cells_by_index[k]:
            mask |= 1 << cell_id[r][c]
        reg_mask[k] = mask

    # Neighbor mask per cell for fast exclusion
    neigh_mask = [0] * (n * n)
    for r in range(n):
        for c in range(n):
            cm = 0
            for (rr, cc) in neigh[r][c]:
                cm |= 1 << cell_id[rr][cc]
            neigh_mask[cell_id[r][c]] = cm

    def popcount(x: int) -> int:
        return x.bit_count()

    def lsb_index(x: int) -> int:
        # assumes x != 0
        return (x & -x).bit_length() - 1

    # Initial state
    star = [[None] * n for _ in range(n)]
    row_need = [1] * n
    col_need = [1] * n
    reg_need = [1] * m
    alive_mask = full_mask  # 1 means cell can be a star
    # If we set a star, we must exclude its neighbors + same row/col/region (since unit is exactly one)
    # However, excluding entire row/col/region is equivalent to setting need=0 and keeping the star cell.

    # Trail for backtracking
    # Each action pushes reversible changes: (type, args...)
    # Types:
    #   'alive': prev_alive_mask
    #   'need': ('r'/'c'/'g', idx, prev)
    #   'star': (r,c, prev)
    def assign_star(r, c, trail):
        nonlocal alive_mask
        if star[r][c] is False:
            return False
        if star[r][c] is True:
            return True

        # Check unit needs
        g = cell_region[r][c]
        if row_need[r] == 0 or col_need[c] == 0 or reg_need[g] == 0:
            return False

        # Check not adjacent to existing stars by ensuring no neighbor already True
        # We'll verify by scanning neighbors (few).
        for (rr, cc) in neigh[r][c]:
            if star[rr][cc] is True:
                return False

        # Place star
        trail.append(('star', r, c, star[r][c]))
        star[r][c] = True

        # Update needs
        trail.append(('need', 'r', r, row_need[r]))
        row_need[r] = 0
        trail.append(('need', 'c', c, col_need[c]))
        col_need[c] = 0
        trail.append(('need', 'g', g, reg_need[g]))
        reg_need[g] = 0

        # Exclude all other candidates in same row/col/region and neighbors
        # Keep the star cell itself alive doesn't matter, but simpler: just clear everything forbidden.
        prev_alive = alive_mask
        forbid = (row_mask[r] | col_mask[c] | reg_mask[g] | neigh_mask[cell_id[r][c]])
        # but do not forbid the star cell itself
        forbid &= ~(1 << cell_id[r][c])
        alive_mask = alive_mask & ~forbid
        trail.append(('alive', prev_alive))
        return True

    def forbid_cell(r, c, trail):
        nonlocal alive_mask
        cid = cell_id[r][c]
        if (alive_mask >> cid) & 1 == 0:
            return True
        # Cannot forbid a cell already starred
        if star[r][c] is True:
            return False
        prev_alive = alive_mask
        alive_mask = alive_mask & ~(1 << cid)
        trail.append(('alive', prev_alive))
        return True

    def unit_candidates_mask(unit_type, idx):
        if unit_type == 'r':
            return alive_mask & row_mask[idx]
        if unit_type == 'c':
            return alive_mask & col_mask[idx]
        # 'g'
        return alive_mask & reg_mask[idx]

    def check_feasible():
        # For each unit that still needs a star, it must have >=1 candidate
        for r in range(n):
            if row_need[r] and unit_candidates_mask('r', r) == 0:
                return False
        for c in range(n):
            if col_need[c] and unit_candidates_mask('c', c) == 0:
                return False
        for g in range(m):
            if reg_need[g] and unit_candidates_mask('g', g) == 0:
                return False
        return True

    def propagate(trail):
        # Repeatedly apply:
        # 1) Naked singles: if a unit needs 1 and has only one candidate -> assign it.
        # 2) Forced exclusions: if a cell is the only remaining candidate in some unit -> assign.
        # 3) Adjacency-based elimination from existing stars already handled in assign_star.
        #
        # Also mark explicitly False for cells that become non-alive (optional); keep implicit via alive_mask.
        changed = True
        while changed:
            changed = False

            if not check_feasible():
                return False

            # Naked singles in units
            for r in range(n):
                if row_need[r]:
                    cm = unit_candidates_mask('r', r)
                    if cm and (cm & (cm - 1)) == 0:
                        i = lsb_index(cm)
                        rr, cc = id_to_rc[i]
                        if not assign_star(rr, cc, trail):
                            return False
                        changed = True
            for c in range(n):
                if col_need[c]:
                    cm = unit_candidates_mask('c', c)
                    if cm and (cm & (cm - 1)) == 0:
                        i = lsb_index(cm)
                        rr, cc = id_to_rc[i]
                        if not assign_star(rr, cc, trail):
                            return False
                        changed = True
            for g in range(m):
                if reg_need[g]:
                    cm = unit_candidates_mask('g', g)
                    if cm and (cm & (cm - 1)) == 0:
                        i = lsb_index(cm)
                        rr, cc = id_to_rc[i]
                        if not assign_star(rr, cc, trail):
                            return False
                        changed = True

            if changed:
                continue

            # Hidden singles via scanning candidates and counting per unit using masks quickly:
            # Since unit sizes are small, compute popcount. If exactly 1 -> assign.
            for r in range(n):
                if row_need[r]:
                    cm = unit_candidates_mask('r', r)
                    if popcount(cm) == 1:
                        i = lsb_index(cm)
                        rr, cc = id_to_rc[i]
                        if not assign_star(rr, cc, trail):
                            return False
                        changed = True
            for c in range(n):
                if col_need[c]:
                    cm = unit_candidates_mask('c', c)
                    if popcount(cm) == 1:
                        i = lsb_index(cm)
                        rr, cc = id_to_rc[i]
                        if not assign_star(rr, cc, trail):
                            return False
                        changed = True
            for g in range(m):
                if reg_need[g]:
                    cm = unit_candidates_mask('g', g)
                    if popcount(cm) == 1:
                        i = lsb_index(cm)
                        rr, cc = id_to_rc[i]
                        if not assign_star(rr, cc, trail):
                            return False
                        changed = True

        return True

    def is_solved():
        return all(v == 0 for v in row_need) and all(v == 0 for v in col_need) and all(v == 0 for v in reg_need)

    def pick_branch_cell():
        # MRV over units needing a star: choose unit with fewest candidates, then pick a candidate cell
        best_unit = None
        best_mask = 0
        best_cnt = 10**9

        for r in range(n):
            if row_need[r]:
                cm = unit_candidates_mask('r', r)
                cnt = popcount(cm)
                if cnt < best_cnt:
                    best_cnt, best_unit, best_mask = cnt, ('r', r), cm
                    if cnt <= 2:
                        break
        if best_cnt > 2:
            for c in range(n):
                if col_need[c]:
                    cm = unit_candidates_mask('c', c)
                    cnt = popcount(cm)
                    if cnt < best_cnt:
                        best_cnt, best_unit, best_mask = cnt, ('c', c), cm
                        if cnt <= 2:
                            break
        if best_cnt > 2:
            for g in range(m):
                if reg_need[g]:
                    cm = unit_candidates_mask('g', g)
                    cnt = popcount(cm)
                    if cnt < best_cnt:
                        best_cnt, best_unit, best_mask = cnt, ('g', g), cm
                        if cnt <= 2:
                            break

        if best_unit is None or best_mask == 0:
            return None, None

        # Choose candidate cell with highest "impact": excludes many alive cells
        # impact approx = candidates in its row/col/region + neighbors
        chosen = None
        chosen_score = -1
        cm = best_mask
        while cm:
            b = cm & -cm
            i = b.bit_length() - 1
            rr, cc = id_to_rc[i]
            g = cell_region[rr][cc]
            impact = popcount((row_mask[rr] | col_mask[cc] | reg_mask[g] | neigh_mask[i]) & alive_mask)
            if impact > chosen_score:
                chosen_score = impact
                chosen = (rr, cc)
            cm ^= b
        return best_unit, chosen

    def undo(trail, checkpoint):
        nonlocal alive_mask
        for k in range(len(trail) - 1, checkpoint - 1, -1):
            item = trail[k]
            t = item[0]
            if t == 'alive':
                alive_mask = item[1]
            elif t == 'need':
                _, which, idx, prev = item
                if which == 'r':
                    row_need[idx] = prev
                elif which == 'c':
                    col_need[idx] = prev
                else:
                    reg_need[idx] = prev
            elif t == 'star':
                _, r, c, prev = item
                star[r][c] = prev
        del trail[checkpoint:]

    def dfs(trail):
        if not propagate(trail):
            return False
        if is_solved():
            return True

        unit, cell = pick_branch_cell()
        if cell is None:
            return False
        r, c = cell

        # Branch 1: place star here
        cp = len(trail)
        if assign_star(r, c, trail) and dfs(trail):
            return True
        undo(trail, cp)

        # Branch 2: forbid this cell
        cp = len(trail)
        if forbid_cell(r, c, trail) and dfs(trail):
            return True
        undo(trail, cp)

        return False

    trail = []
    if not dfs(trail):
        return "No Solution"

    ans = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if star[r][c] is True:
                ans[r][c] = 'S'
    return str(ans)

