from __future__ import annotations

# Star Battle (Shapeless, 1-star): N stars total, exactly 1 per row/col, no adjacency incl. diagonals, avoid obstacles.

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if n == 0 or any(len(r) != n for r in grid):
        return "No Solution"

    # Precompute legal cells per row/col (obstacles removed)
    row_cells = [set(c for c in range(n) if grid[r][c] != 'B') for r in range(n)]
    col_cells = [set(r for r in range(n) if grid[r][c] != 'B') for c in range(n)]
    if any(len(row_cells[r]) == 0 for r in range(n)) or any(len(col_cells[c]) == 0 for c in range(n)):
        return "No Solution"

    # Neighbor mask for adjacency (including diagonals)
    nbr = [[set() for _ in range(n)] for __ in range(n)]
    for r in range(n):
        for c in range(n):
            s = set()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n:
                        s.add((rr, cc))
            nbr[r][c] = s

    # Domains: for each row r, possible columns for its star
    domains = [set(row_cells[r]) for r in range(n)]

    # State: assigned_col[r] or -1; used columns; forbidden cells due to adjacency/obstacles/used row handling
    assigned_col = [-1] * n
    col_used = [False] * n
    forbidden = [[False] * n for _ in range(n)]  # dynamic forbiddance due to adjacency of placed stars

    # Initialize forbidden with obstacles (treated as never-allowed)
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 'B':
                forbidden[r][c] = True

    # Fast check helpers
    def cell_allowed(r, c):
        return (not forbidden[r][c]) and (not col_used[c])

    def recompute_domain(r):
        # filter by current forbidden/col_used
        d = domains[r]
        # remove disallowed
        rem = [c for c in d if not cell_allowed(r, c)]
        for c in rem:
            d.remove(c)
        return len(d)

    # Forward-check / propagation queue
    def propagate(queue, trail):
        # queue contains rows whose domain might need filtering / forced assignment
        while queue:
            r = queue.pop()
            if assigned_col[r] != -1:
                continue
            if recompute_domain(r) == 0:
                return False
            if len(domains[r]) == 1:
                c = next(iter(domains[r]))
                if not place_star(r, c, trail, queue):
                    return False

        # Additional human-like deduction: column singleton (only one row can take a column)
        # and Hall-like feasibility bounds (cheap)
        changed = True
        while changed:
            changed = False

            # Column singleton: for each free column, count candidate rows
            for c in range(n):
                if col_used[c]:
                    continue
                candidates = []
                for r in range(n):
                    if assigned_col[r] == -1 and c in domains[r] and cell_allowed(r, c):
                        candidates.append(r)
                        if len(candidates) > 1:
                            break
                if len(candidates) == 0:
                    return False
                if len(candidates) == 1:
                    r0 = candidates[0]
                    if assigned_col[r0] == -1:
                        if not place_star(r0, c, trail, queue):
                            return False
                        changed = True

            # Feasibility lower-bound: for each subset of rows? too expensive.
            # Instead: for each row count and each column count already handled.
            # And quick bipartite matching bound via greedy (fast and strong enough for N<=~12 typical)
            if not greedy_feasible():
                return False

        return True

    def greedy_feasible():
        # Quick feasibility check: can we injectively assign remaining rows to remaining columns from domains?
        # Greedy by smallest domain (after filtering) is a strong early-prune proxy for matching.
        rows = [r for r in range(n) if assigned_col[r] == -1]
        # build available columns per row considering current col_used/forbidden
        cand = []
        for r in rows:
            d = [c for c in domains[r] if cell_allowed(r, c)]
            if not d:
                return False
            cand.append((len(d), r, d))
        cand.sort()
        used = set(c for c in range(n) if col_used[c])
        for _, r, d in cand:
            # choose first available
            pick = None
            for c in d:
                if c not in used:
                    pick = c
                    break
            if pick is None:
                return False
            used.add(pick)
        return True

    def place_star(r, c, trail, queue):
        if assigned_col[r] != -1:
            return assigned_col[r] == c
        if forbidden[r][c] or col_used[c]:
            return False

        # Assign
        assigned_col[r] = c
        trail.append(("assign", r))
        col_used[c] = True
        trail.append(("col", c))

        # Forbid adjacency cells
        affected = []
        for (rr, cc) in nbr[r][c]:
            if not forbidden[rr][cc]:
                forbidden[rr][cc] = True
                affected.append((rr, cc))
        if affected:
            trail.append(("forbid", affected))

        # After placing, other columns in row are irrelevant; but keep domain as singleton for consistency
        # Remove other candidates in this row to prevent reconsideration
        old_dom = domains[r].copy()
        domains[r].clear()
        domains[r].add(c)
        trail.append(("dom", r, old_dom))

        # Enqueue impacted rows: all rows potentially affected by forbidden changes and column use
        # Rows: neighbors rows and all unassigned rows that had this column as candidate.
        for rr in range(max(0, r - 1), min(n, r + 2)):
            if assigned_col[rr] == -1:
                queue.append(rr)
        for rr in range(n):
            if assigned_col[rr] == -1 and c in domains[rr]:
                queue.append(rr)
        return True

    def undo(trail):
        while trail:
            tag = trail.pop()
            kind = tag[0]
            if kind == "dom":
                _, r, old_dom = tag
                domains[r] = old_dom
            elif kind == "forbid":
                _, cells = tag
                for rr, cc in cells:
                    # obstacles remain forbidden; but we never un-forbid obstacles as they were set initially.
                    # Ensure not to unset obstacle cells
                    if grid[rr][cc] != 'B':
                        forbidden[rr][cc] = False
            elif kind == "col":
                _, c = tag
                col_used[c] = False
            elif kind == "assign":
                _, r = tag
                assigned_col[r] = -1
            else:
                raise RuntimeError("bad trail tag")

    def select_unassigned_row():
        best_r = -1
        best_sz = 10**9
        for r in range(n):
            if assigned_col[r] == -1:
                # ensure filtered
                recompute_domain(r)
                sz = len(domains[r])
                if sz < best_sz:
                    best_sz = sz
                    best_r = r
                    if sz <= 2:
                        break
        return best_r

    # Initial propagation (simple filtering)
    init_trail = []
    init_queue = list(range(n))
    if not propagate(init_queue, init_trail):
        return "No Solution"

    def dfs():
        # All assigned?
        if all(a != -1 for a in assigned_col):
            return True

        r = select_unassigned_row()
        if r == -1:
            return False

        # Human-like branching: try candidates that constrain most (least-constraining / most-constraining heuristic)
        candidates = [c for c in domains[r] if cell_allowed(r, c)]
        if not candidates:
            return False

        # Sort by how many future cells would be forbidden in other rows (more forbiddance first to prune)
        def impact(c):
            cnt = 0
            # column conflicts: how many other rows could use this column
            for rr in range(n):
                if rr != r and assigned_col[rr] == -1 and c in domains[rr] and cell_allowed(rr, c):
                    cnt += 1
            # adjacency forbiddance: count currently allowed cells that would be forbidden
            for (rr, cc) in nbr[r][c]:
                if assigned_col[rr] == -1 and not forbidden[rr][cc] and grid[rr][cc] != 'B':
                    if cc in domains[rr] and (not col_used[cc]):
                        cnt += 1
            return -cnt

        candidates.sort(key=impact)

        for c in candidates:
            trail = []
            queue = []
            if place_star(r, c, trail, queue) and propagate(queue, trail):
                if dfs():
                    return True
            undo(trail)
        return False

    if not dfs():
        # undo init trail (not necessary but keeps clean)
        undo(init_trail)
        return "No Solution"

    # Build output grid
    out = [[None for _ in range(n)] for __ in range(n)]
    for r in range(n):
        c = assigned_col[r]
        if c == -1:
            return "No Solution"
        out[r][c] = 'S'
    return str(out)

