from collections import deque
from functools import lru_cache

# Solver for "Numbered Masyu" / loop with white/black numbered circles.
# - Grid: N x N cells, (N+1)x(N+1) dots.
# - Variables: undirected edges between adjacent dots (horizontal/vertical). Value in {0,1}.
# - Constraints:
#   * At each dot: degree is 0 or 2 (single loop; intermediates can be unused but final must be one loop).
#   * At each clue circle (located at a dot in the provided observation):
#       - Wk: used and straight (two opposite edges).
#       - Bk: used and turn (two perpendicular edges).
#       - Number k: sum of lengths (in edges) of the straight segments extending from the circle along the loop.
#         For Wk: those are the two straight arms passing through the circle.
#         For Bk: those are the straight runs leaving the circle on both sides of the corner.
#
# NOTE:
# The image-to-grid parsing is not implemented here; OBSERVATION must contain clue tokens.
# This engine is general and expects clues to be on dot coordinates: observation['data'][r][c] = 'W3'/'B5'.
#
# Because the provided OBSERVATION is empty (all None), the solver will return "No Solution"
# under the "must pass through all clue circles" requirement (vacuously true), but still needs
# a single closed loop; there are infinitely many. We therefore require at least one clue.
# If no clues exist, return "No Solution" (ambiguous).

DIRS = [(0, 1), (1, 0), (0, -1), (-1, 0)]
DIR_IDX = {(0, 1): 0, (1, 0): 1, (0, -1): 2, (-1, 0): 3}
OPP = {0: 2, 1: 3, 2: 0, 3: 1}

def solve(observation):
    data = observation["data"]
    R = len(data)
    C = len(data[0]) if R else 0
    if R != C:
        return "No Solution"
    N = R - 1
    if N < 1:
        return "No Solution"

    clues = {}
    for r in range(R):
        for c in range(C):
            tok = data[r][c]
            if tok:
                t = tok[0].upper()
                k = int(tok[1:])
                if t not in ("W", "B"):
                    return "No Solution"
                clues[(r, c)] = (t, k)

    if not clues:
        return "No Solution"

    # Edge indexing:
    # Horizontal edges: (r,c)-(r,c+1) for r in [0..N], c in [0..N-1]
    # Vertical edges:   (r,c)-(r+1,c) for r in [0..N-1], c in [0..N]
    # We'll encode each undirected edge as (r,c,dir) where dir in {0:right,1:down} only.
    # Helper to normalize.
    def norm_edge(a, b):
        (r1, c1), (r2, c2) = a, b
        dr, dc = r2 - r1, c2 - c1
        if abs(dr) + abs(dc) != 1:
            raise ValueError("non-adjacent")
        if dr == 0 and dc == 1:
            return (r1, c1, 0)
        if dr == 0 and dc == -1:
            return (r2, c2, 0)
        if dr == 1 and dc == 0:
            return (r1, c1, 1)
        if dr == -1 and dc == 0:
            return (r2, c2, 1)
        raise ValueError("bad")

    # Enumerate all edges
    edges = []
    edge_id = {}
    # horizontal
    for r in range(N + 1):
        for c in range(N):
            e = (r, c, 0)
            edge_id[e] = len(edges)
            edges.append(e)
    # vertical
    for r in range(N):
        for c in range(N + 1):
            e = (r, c, 1)
            edge_id[e] = len(edges)
            edges.append(e)

    M = len(edges)

    # For each dot, list incident edges (by id) and direction at dot (0..3).
    dot_inc = [[[] for _ in range(C)] for __ in range(R)]
    # Map edge id to its endpoints
    endpts = [None] * M
    for eid, (r, c, d) in enumerate(edges):
        if d == 0:
            a = (r, c)
            b = (r, c + 1)
            endpts[eid] = (a, b)
            dot_inc[r][c].append((eid, 0))      # right
            dot_inc[r][c + 1].append((eid, 2))  # left
        else:
            a = (r, c)
            b = (r + 1, c)
            endpts[eid] = (a, b)
            dot_inc[r][c].append((eid, 1))      # down
            dot_inc[r + 1][c].append((eid, 3))  # up

    # Domain for each edge: -1 unknown, 0 off, 1 on
    state = [-1] * M
    # Degree per dot with known edges
    deg = [[0] * C for _ in range(R)]
    unk = [[0] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            unk[r][c] = len(dot_inc[r][c])

    # Fast queue-based propagation
    q = deque()

    def set_edge(eid, val):
        cur = state[eid]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        state[eid] = val
        (a, b) = endpts[eid]
        for (r, c) in (a, b):
            unk[r][c] -= 1
            if val == 1:
                deg[r][c] += 1
            q.append(("dot", r, c))
        # endpoints involved in clue constraints
        q.append(("edge", eid))
        return True

    # Precompute clue-local incident edges by direction index for quick pattern forcing
    clue_inc_by_dir = {}
    for (r, c), (t, k) in clues.items():
        bydir = [None, None, None, None]  # edge id or None if boundary
        for (eid, ddir) in dot_inc[r][c]:
            bydir[ddir] = eid
        clue_inc_by_dir[(r, c)] = bydir

    def dot_propagate(r, c):
        # degree must be 0 or 2; but if dot is a clue then it must be 2.
        must2 = (r, c) in clues
        d = deg[r][c]
        u = unk[r][c]
        if d > 2:
            return False
        if must2:
            if d + u < 2:
                return False
            if d == 2:
                # all remaining incident edges off
                for (eid, _) in dot_inc[r][c]:
                    if state[eid] == -1:
                        if not set_edge(eid, 0):
                            return False
            elif d + u == 2:
                # all remaining incident edges on
                for (eid, _) in dot_inc[r][c]:
                    if state[eid] == -1:
                        if not set_edge(eid, 1):
                            return False
        else:
            # optional dot: degree can be 0 or 2
            if d == 1:
                # cannot end here; must reach 2 unless we can still reach 2
                if u == 0:
                    return False
                if d + u == 2:
                    for (eid, _) in dot_inc[r][c]:
                        if state[eid] == -1:
                            if not set_edge(eid, 1):
                                return False
            elif d == 2:
                for (eid, _) in dot_inc[r][c]:
                    if state[eid] == -1:
                        if not set_edge(eid, 0):
                            return False
            elif d == 0:
                # if u==0 ok (isolated)
                pass
            else:  # d>2 handled
                return False
            # If d+u<0 none
            if d + u < 0:
                return False
        return True

    def clue_shape_propagate(r, c):
        t, k = clues[(r, c)]
        bydir = clue_inc_by_dir[(r, c)]
        # A clue dot must have degree 2, enforced by dot_propagate.
        # Here enforce straight/turn pattern if degree known or partially known.
        # Determine fixed on/off edges among the four.
        on_dirs = []
        off_dirs = []
        unk_dirs = []
        for ddir in range(4):
            eid = bydir[ddir]
            if eid is None:
                off_dirs.append(ddir)
                continue
            v = state[eid]
            if v == 1:
                on_dirs.append(ddir)
            elif v == 0:
                off_dirs.append(ddir)
            else:
                unk_dirs.append(ddir)

        # boundary: if clue at boundary, still possible but must have 2 incident edges among existing.
        # Enforce straight/turn when possible.
        def force_pair(d1, d2):
            # set those directions on; others off (where exist)
            for ddir in range(4):
                eid = bydir[ddir]
                if eid is None:
                    continue
                if ddir in (d1, d2):
                    if not set_edge(eid, 1):
                        return False
                else:
                    if not set_edge(eid, 0):
                        return False
            return True

        if t == "W":
            # must be opposite pair
            opp_pairs = [(0, 2), (1, 3)]
            # prune impossible based on existing on edges
            possible = []
            for (a, b) in opp_pairs:
                ok = True
                for ddir in range(4):
                    eid = bydir[ddir]
                    if eid is None:
                        # if required dir missing => impossible
                        if ddir in (a, b):
                            ok = False
                            break
                        continue
                    v = state[eid]
                    if ddir in (a, b):
                        if v == 0:
                            ok = False
                            break
                    else:
                        if v == 1:
                            ok = False
                            break
                if ok:
                    possible.append((a, b))
            if not possible:
                return False
            if len(possible) == 1:
                if not force_pair(*possible[0]):
                    return False
        else:
            # B: must be perpendicular pair
            turn_pairs = [(0, 1), (1, 2), (2, 3), (3, 0)]
            possible = []
            for (a, b) in turn_pairs:
                ok = True
                for ddir in range(4):
                    eid = bydir[ddir]
                    if eid is None:
                        if ddir in (a, b):
                            ok = False
                            break
                        continue
                    v = state[eid]
                    if ddir in (a, b):
                        if v == 0:
                            ok = False
                            break
                    else:
                        if v == 1:
                            ok = False
                            break
                if ok:
                    possible.append((a, b))
            if not possible:
                return False
            if len(possible) == 1:
                if not force_pair(*possible[0]):
                    return False

        # Number constraint propagation (k = sum of straight run lengths from the circle).
        # We compute lower/upper bounds for each of the two arms (given current partial assignments).
        # If we can force edges to satisfy exact k within bounds, we do limited lookahead:
        # For each candidate shape pair still possible, compute feasible range of total and prune shape if impossible.
        #
        # We do NOT do heavy global search here; just compute bounds and force when tight.

        def arm_bounds(start_rc, dir_out):
            # Starting at clue dot, move stepwise along dir_out following straight line.
            # Run length counts consecutive ON edges until first OFF; if unknown we have range.
            r0, c0 = start_rc
            dr, dc = DIRS[dir_out]
            length_min = 0
            length_max = 0
            r, c = r0, c0
            while True:
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < R and 0 <= c2 < C):
                    break
                eid = edge_id[norm_edge((r, c), (r2, c2))]
                v = state[eid]
                if v == 0:
                    break
                if v == 1:
                    length_min += 1
                    length_max += 1
                    r, c = r2, c2
                    continue
                # unknown: could be off here, or on and continue until boundary or forced off
                length_max += 1
                # for max, continue scanning but treat further unknowns as potentially on
                r, c = r2, c2
                while True:
                    r3, c3 = r + dr, c + dc
                    if not (0 <= r3 < R and 0 <= c3 < C):
                        break
                    eid2 = edge_id[norm_edge((r, c), (r3, c3))]
                    v2 = state[eid2]
                    if v2 == 0:
                        break
                    length_max += 1
                    if v2 == -1:
                        # still could be on, continue
                        r, c = r3, c3
                        continue
                    else:
                        r, c = r3, c3
                        continue
                break
            return length_min, length_max

        # Evaluate feasible shapes, and if unique feasible shape enforce it.
        t, k = clues[(r, c)]
        bydir = clue_inc_by_dir[(r, c)]
        if t == "W":
            shape_candidates = [(0, 2), (1, 3)]
        else:
            shape_candidates = [(0, 1), (1, 2), (2, 3), (3, 0)]

        feasible_shapes = []
        for a, b in shape_candidates:
            # must have those dirs available (not boundary) and not contradict assigned states
            ok = True
            for ddir in range(4):
                eid = bydir[ddir]
                if eid is None:
                    if ddir in (a, b):
                        ok = False
                        break
                    continue
                v = state[eid]
                if ddir in (a, b):
                    if v == 0:
                        ok = False
                        break
                else:
                    if v == 1:
                        ok = False
                        break
            if not ok:
                continue
            amin, amax = arm_bounds((r, c), a)
            bmin, bmax = arm_bounds((r, c), b)
            if amin + bmin <= k <= amax + bmax:
                feasible_shapes.append((a, b, amin, amax, bmin, bmax))

        if not feasible_shapes:
            return False

        if len(feasible_shapes) == 1:
            a, b, amin, amax, bmin, bmax = feasible_shapes[0]
            if not force_pair(a, b):
                return False
            # After forcing shape, we can sometimes force extension lengths:
            # If we need at least L along an arm, set first L edges ON.
            # If we need at most U, and U==current min, set next edge OFF.
            # Use bounds to derive per-arm required min/max given exact k.
            # Required min for arm a is max(amin, k - bmax); required max is min(amax, k - bmin)
            req_a_min = max(amin, k - bmax)
            req_a_max = min(amax, k - bmin)
            req_b_min = max(bmin, k - amax)
            req_b_max = min(bmax, k - amin)
            if req_a_min > req_a_max or req_b_min > req_b_max:
                return False

            def force_arm(dir_out, need_min, need_max):
                r0, c0 = r, c
                dr, dc = DIRS[dir_out]
                # force first need_min edges ON
                rr, cc = r0, c0
                for _ in range(need_min):
                    r2, c2 = rr + dr, cc + dc
                    if not (0 <= r2 < R and 0 <= c2 < C):
                        return False
                    eid = edge_id[norm_edge((rr, cc), (r2, c2))]
                    if not set_edge(eid, 1):
                        return False
                    rr, cc = r2, c2
                # if need_max == need_min, next edge must be OFF (if exists and undecided)
                if need_max == need_min:
                    r2, c2 = rr + dr, cc + dc
                    if 0 <= r2 < R and 0 <= c2 < C:
                        eid = edge_id[norm_edge((rr, cc), (r2, c2))]
                        if state[eid] == -1:
                            if not set_edge(eid, 0):
                                return False
                return True

            if not force_arm(a, req_a_min, req_a_max):
                return False
            if not force_arm(b, req_b_min, req_b_max):
                return False

        return True

    def propagate():
        # seed all dots and all clues
        for (r, c) in clues:
            q.append(("dot", r, c))
            q.append(("clue", r, c))
        while q:
            typ, *rest = q.popleft()
            if typ == "dot":
                r, c = rest
                if not dot_propagate(r, c):
                    return False
                if (r, c) in clues:
                    q.append(("clue", r, c))
            elif typ == "clue":
                r, c = rest
                if not clue_shape_propagate(r, c):
                    return False
            elif typ == "edge":
                # currently unused
                pass
        return True

    # Connectivity / single-loop checks using union-find with deferred subtour elimination:
    # Disallow forming a closed cycle before all clue-dots are included (and before all used dots resolved).
    parent = list(range(R * C))
    size = [1] * (R * C)
    comp_deg2 = [0] * (R * C)  # count of degree-2 vertices in component (used vertices)

    def idx(rc):
        r, c = rc
        return r * C + c

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return ra
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        comp_deg2[ra] += comp_deg2[rb]
        return ra

    def rebuild_unionfind():
        for i in range(R * C):
            parent[i] = i
            size[i] = 1
            comp_deg2[i] = 0
        for r in range(R):
            for c in range(C):
                if deg[r][c] == 2:
                    comp_deg2[idx((r, c))] = 1
        for eid, v in enumerate(state):
            if v != 1:
                continue
            a, b = endpts[eid]
            union(idx(a), idx(b))

    def any_small_cycle_formed():
        # A component is a cycle if all its vertices have deg 2 and it's closed.
        # In this grid representation, if a component has vertices with deg2 count == number of vertices in comp
        # and it is not the final single loop (i.e., not all clue vertices included), it's a forbidden subtour.
        rebuild_unionfind()
        total_deg2 = sum(1 for r in range(R) for c in range(C) if deg[r][c] == 2)
        # required used vertices at least all clues (each clue has deg 2)
        clue_vertices = len(clues)
        for i in range(R * C):
            if parent[i] != i:
                continue
            if comp_deg2[i] == 0:
                continue
            if comp_deg2[i] == size[i]:
                # closed component (a cycle)
                if comp_deg2[i] < total_deg2:
                    return True
                # if it's the only cycle but doesn't include all clues yet, also forbidden
                if comp_deg2[i] < clue_vertices:
                    return True
        return False

    # Variable ordering heuristic: pick most constrained edge (touching clues / near forced degrees)
    edge_score = [0] * M
    for eid, (a, b) in enumerate(endpts):
        (r1, c1), (r2, c2) = a, b
        s = 0
        if (r1, c1) in clues:
            s += 10
        if (r2, c2) in clues:
            s += 10
        s += 2 * (len(dot_inc[r1][c1]) - 2 != 0)
        s += 2 * (len(dot_inc[r2][c2]) - 2 != 0)
        edge_score[eid] = s

    def choose_edge():
        best = -1
        best_s = -1
        for eid in range(M):
            if state[eid] != -1:
                continue
            s = edge_score[eid]
            (a, b) = endpts[eid]
            # prioritize edges adjacent to degree pressure
            da = deg[a[0]][a[1]]
            db = deg[b[0]][b[1]]
            ua = unk[a[0]][a[1]]
            ub = unk[b[0]][b[1]]
            if (a in clues) or (b in clues):
                s += 5
            if da == 1 and ua == 1:
                s += 4
            if db == 1 and ub == 1:
                s += 4
            if s > best_s:
                best_s = s
                best = eid
        return best

    # Trail extraction when solved
    def extract_loop():
        # find a starting used dot
        start = None
        for r in range(R):
            for c in range(C):
                if deg[r][c] == 2:
                    start = (r, c)
                    break
            if start:
                break
        if not start:
            return None
        # follow edges
        path = [start]
        prev = None
        cur = start
        while True:
            r, c = cur
            nbrs = []
            for eid, ddir in dot_inc[r][c]:
                if state[eid] == 1:
                    a, b = endpts[eid]
                    nxt = b if a == cur else a
                    nbrs.append(nxt)
            if len(nbrs) != 2:
                return None
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            prev, cur = cur, nxt
            path.append(cur)
            if cur == start:
                break
            if len(path) > (R * C + 5) * 2:
                return None
        return path

    def is_complete_valid():
        # all clues deg 2 already enforced; ensure all dots have deg 0 or 2 and no unknown edges
        if any(v == -1 for v in state):
            return False
        for r in range(R):
            for c in range(C):
                if deg[r][c] not in (0, 2):
                    return False
        # must be a single cycle including all clue vertices
        rebuild_unionfind()
        roots = set()
        clue_root = None
        for (r, c) in clues:
            cr = find(idx((r, c)))
            if clue_root is None:
                clue_root = cr
            elif cr != clue_root:
                return False
        # ensure every deg2 vertex is in same component (single loop)
        for r in range(R):
            for c in range(C):
                if deg[r][c] == 2:
                    if find(idx((r, c))) != clue_root:
                        return False
        # ensure it's actually a cycle path
        loop = extract_loop()
        return loop is not None

    # Backtracking with strong propagation
    def dfs():
        if not propagate():
            return None
        if any_small_cycle_formed():
            return None
        if is_complete_valid():
            return extract_loop()

        eid = choose_edge()
        if eid == -1:
            return None

        # Save snapshot (compact)
        snap_state = state[:]
        snap_deg = [row[:] for row in deg]
        snap_unk = [row[:] for row in unk]

        # Try ON then OFF (often loop edges needed)
        for val in (1, 0):
            # restore
            for i in range(M):
                state[i] = snap_state[i]
            for r in range(R):
                deg[r][:] = snap_deg[r][:]
                unk[r][:] = snap_unk[r][:]
            q.clear()

            if set_edge(eid, val):
                res = dfs()
                if res is not None:
                    return res
        return None

    res = dfs()
    if res is None:
        return "No Solution"
    return str(res)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 'W', None, None, None, 'W', None], ['W', None, None, None, 'W', None, None, 'W'], ['B', None, None, None, None, None, None, None], [None, None, None, None, 'W', None, None, 'B'], [None, 'W', None, 'B', None, None, None, None], [None, None, None, None, 'W', 'W', None, None], [None, None, None, 'B', 'W', None, None, 'W'], ['B', None, None, None, None, None, 'W', None]]}
# Masyu solver (dots-as-nodes, edges between orthogonal adjacent dots).
# This implementation emphasizes human-like deduction + aggressive propagation:
# - Enforce degree constraints at every dot (0..2).
# - Enforce clue constraints at circled dots:
#   * White: must go straight; and at least one of the two adjacent nodes along straight must be a turn.
#   * Black: must turn; and both adjacent nodes along the entering/leaving directions must be straight.
# - Prevent premature small cycles (single-loop requirement) via DSU with "cycle only when final".
# - Use deterministic propagation + prioritized branching on most constrained edge.

from collections import deque

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]  # U R D L
U, R, D, L = 0, 1, 2, 3

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if any(len(row) != n for row in grid):
        return "No Solution"

    # Node indexing: (r,c) with 0..n-1, edges between adjacent dots => same coords.
    # Clues are located on dots (as per prompt). If your variant has clues in cells,
    # adapt mapping accordingly.
    def inb(r, c):
        return 0 <= r < n and 0 <= c < n

    def nid(r, c):
        return r * n + c

    N = n * n

    # Edge representation: undirected between two nodes (u < v).
    edges = []
    edge_id = {}
    adj = [[] for _ in range(N)]  # list of (eid, neighbor, dir_from_node)
    for r in range(n):
        for c in range(n):
            u = nid(r, c)
            for d, (dr, dc) in enumerate(DIRS):
                r2, c2 = r + dr, c + dc
                if inb(r2, c2):
                    v = nid(r2, c2)
                    if u < v:
                        eid = len(edges)
                        edges.append((u, v))
                        edge_id[(u, v)] = eid
                        edge_id[(v, u)] = eid
                    else:
                        eid = edge_id[(u, v)]
                    adj[u].append((eid, v, d))

    M = len(edges)

    # State of each edge: -1 unknown, 0 off, 1 on
    E = [-1] * M
    deg = [0] * N
    offcnt = [0] * N
    # For each node, number of incident edges = len(adj[u]) (2 to 4 depending border)

    # DSU for preventing premature cycles among ON edges
    parent = list(range(N))
    size = [1] * N
    comp_edges = [0] * N  # number of ON edges inside component

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return ra
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        comp_edges[ra] += comp_edges[rb]
        return ra

    # Helpers to get edge id for node and direction
    def neigh(u, d):
        r, c = divmod(u, n)
        dr, dc = DIRS[d]
        r2, c2 = r + dr, c + dc
        if not inb(r2, c2):
            return None
        return nid(r2, c2)

    def get_eid(u, v):
        return edge_id.get((u, v), None)

    # Contradiction flag
    CONTRA = [False]

    # Queue of nodes/clues to recheck when incident edges change
    q = deque()

    # Pre-load all nodes in queue
    for u in range(N):
        q.append(("node", u))
    # and all clue nodes
    clue_nodes = []
    for r in range(n):
        for c in range(n):
            if grid[r][c] in ("W", "B"):
                clue_nodes.append(nid(r, c))
                q.append(("clue", nid(r, c)))

    def set_edge(eid, val):
        if CONTRA[0]:
            return
        cur = E[eid]
        if cur == val:
            return
        if cur != -1 and cur != val:
            CONTRA[0] = True
            return
        E[eid] = val
        u, v = edges[eid]
        # update degrees / off counts
        if val == 1:
            deg[u] += 1
            deg[v] += 1
        else:
            offcnt[u] += 1
            offcnt[v] += 1
        # enqueue endpoints + any clue checks
        q.append(("node", u))
        q.append(("node", v))
        q.append(("clue", u))
        q.append(("clue", v))

        # DSU update/prune on ON edges:
        if val == 1:
            ru, rv = find(u), find(v)
            if ru == rv:
                # This would create a cycle within component.
                # Only allowed if it's the final single loop: all required degrees satisfied and all clues satisfied.
                # We'll disallow during propagation; final validation will allow only at the end.
                CONTRA[0] = True
                return
            newr = union(ru, rv)
            comp_edges[newr] += 1  # added this edge

    def force_node_degree(u):
        # Degree constraints for loop:
        # - final should be 0 or 2 everywhere, but single loop implies no isolated leftovers;
        # During solve we enforce: deg <=2; if deg==2 => all other incident edges OFF.
        # If remaining possible edges count equals (2-deg) => those must be ON.
        if CONTRA[0]:
            return
        if deg[u] > 2:
            CONTRA[0] = True
            return
        inc = adj[u]
        tot = len(inc)
        unknown = []
        for eid, v, d in inc:
            if E[eid] == -1:
                unknown.append(eid)
        remaining_possible = tot - offcnt[u]  # unknown + on
        if deg[u] == 2:
            # turn off all unknown incident edges
            for eid in unknown:
                set_edge(eid, 0)
            return
        # If even with all unknown ON we can't reach 2, then node must be degree 0 (unused) OR contradiction.
        # But in a single-loop puzzle on dot grid with clues on dots, typically many nodes unused.
        # However, clue nodes must have degree 2.
        # We'll enforce: if node is a clue -> degree must become 2.
        # For non-clue: allow 0 or 2; so if deg==1 must later become 2 (can't end at 1).
        # We can still propagate:
        if grid[u // n][u % n] in ("W", "B"):
            # must end degree 2
            if deg[u] + len(unknown) < 2:
                CONTRA[0] = True
                return
            if deg[u] + len(unknown) == 2:
                for eid in unknown:
                    set_edge(eid, 1)
                return
        # For non-clue:
        # If deg==1 and only one unknown remains, must be ON to avoid dead-end.
        if deg[u] == 1 and len(unknown) == 1:
            set_edge(unknown[0], 1)
        # If deg==0 and remaining_possible == 1 => can't have degree 2; so must be degree 0 -> all incident edges OFF.
        if deg[u] == 0 and remaining_possible == 1:
            for eid in unknown:
                set_edge(eid, 0)
        # If deg==1 and no unknown => contradiction (dead end)
        if deg[u] == 1 and len(unknown) == 0:
            CONTRA[0] = True

    def pattern_at_node(u):
        # If degree is already 2, classify straight vs turn if possible
        # Returns: None if not decided, else tuple of two directions used (d1,d2) sorted.
        dirs_on = []
        for eid, v, d in adj[u]:
            if E[eid] == 1:
                dirs_on.append(d)
        if len(dirs_on) != 2:
            return None
        d1, d2 = sorted(dirs_on)
        return (d1, d2)

    def enforce_black(u):
        # Black: must turn at u; and both adjacent nodes along the entering/leaving directions must be straight.
        # i.e., if the two used dirs are orthogonal. Additionally, on the neighbor node in each used dir,
        # the edge continues straight (so neighbor must use the opposite direction too).
        if CONTRA[0]:
            return
        # u must have degree 2 eventually
        force_node_degree(u)
        # If we already have two ON edges at u, enforce they are a turn
        pat = pattern_at_node(u)
        if pat is not None:
            d1, d2 = pat
            # check turn (not opposite)
            if (d1 + 2) % 4 == d2:
                CONTRA[0] = True
                return
            # enforce neighbor straightness along each direction
            for d in (d1, d2):
                v = neigh(u, d)
                if v is None:
                    CONTRA[0] = True
                    return
                # At v, edge (u-v) is ON, so v must also take opposite direction (continue straight)
                opp = (d + 2) % 4
                vv = neigh(v, opp)
                if vv is None:
                    CONTRA[0] = True
                    return
                eid2 = get_eid(v, vv)
                if eid2 is None:
                    CONTRA[0] = True
                    return
                set_edge(eid2, 1)
                # also v cannot turn on that edge: so other two orthogonal edges at v must be OFF if degree reaches 2 straight.
                # If v already has another ON edge not equal to eid2, must be consistent.
        else:
            # If one ON edge at u, we can prune: opposite direction cannot be ON simultaneously (would force straight)
            dirs_on = [d for eid, v, d in adj[u] if E[eid] == 1]
            if len(dirs_on) == 1:
                d = dirs_on[0]
                opp = (d + 2) % 4
                vopp = neigh(u, opp)
                if vopp is not None:
                    eid_opp = get_eid(u, vopp)
                    if eid_opp is not None:
                        set_edge(eid_opp, 0)

    def enforce_white(u):
        # White: must go straight through u; and must turn at least once in previous or next step.
        # So u uses opposite directions. Additionally, at least one adjacent node along those directions is a turn.
        if CONTRA[0]:
            return
        force_node_degree(u)
        pat = pattern_at_node(u)
        if pat is not None:
            d1, d2 = pat
            # must be straight (opposite)
            if (d1 + 2) % 4 != d2:
                CONTRA[0] = True
                return
            # "must turn at least once in previous or next step":
            # Let v1 = neighbor in d1, v2 = neighbor in d2. At least one of v1, v2 is a turn node.
            # A node is a turn if its two used dirs are orthogonal.
            v1 = neigh(u, d1)
            v2 = neigh(u, d2)
            if v1 is None or v2 is None:
                CONTRA[0] = True
                return
            # If v1 already decided straight, then v2 must be turn, and vice versa.
            # If v1 has both ON edges and is straight, then force v2 to be a turn by forbidding straight continuation at v2.
            def is_decided(u2):
                pat2 = pattern_at_node(u2)
                if pat2 is None:
                    return None
                a, b = pat2
                return "straight" if (a + 2) % 4 == b else "turn"

            s1 = is_decided(v1)
            s2 = is_decided(v2)
            if s1 == "straight" and s2 == "straight":
                CONTRA[0] = True
                return
            if s1 == "straight":
                # v2 must be turn: since edge (u-v2) is ON, v2's other ON edge cannot be opposite of that direction.
                d_to_u = (d2 + 2) % 4  # direction from v2 to u
                opp = (d_to_u + 2) % 4
                vv = neigh(v2, opp)
                if vv is not None:
                    eid_forbid = get_eid(v2, vv)
                    if eid_forbid is not None:
                        set_edge(eid_forbid, 0)
            if s2 == "straight":
                d_to_u = (d1 + 2) % 4
                opp = (d_to_u + 2) % 4
                vv = neigh(v1, opp)
                if vv is not None:
                    eid_forbid = get_eid(v1, vv)
                    if eid_forbid is not None:
                        set_edge(eid_forbid, 0)
        else:
            # If one ON edge at a white, the opposite must be ON and orthogonals OFF once degree fixed.
            dirs_on = [d for eid, v, d in adj[u] if E[eid] == 1]
            if len(dirs_on) == 1:
                d = dirs_on[0]
                opp = (d + 2) % 4
                vopp = neigh(u, opp)
                if vopp is None:
                    CONTRA[0] = True
                    return
                eid_opp = get_eid(u, vopp)
                set_edge(eid_opp, 1)
            # If one OFF edge at white and it's one of a pair, not much. If two orthogonals OFF, forces straight.
            # If for both opposite pair one is OFF, that opposite pair can't be used.

    def propagate():
        while q and not CONTRA[0]:
            typ, u = q.popleft()
            if typ == "node":
                force_node_degree(u)
            else:
                clue = grid[u // n][u % n]
                if clue == "B":
                    enforce_black(u)
                elif clue == "W":
                    enforce_white(u)

    # Initial propagation
    propagate()
    if CONTRA[0]:
        return "No Solution"

    # Branching with backtracking
    def snapshot():
        return (E[:], deg[:], offcnt[:], parent[:], size[:], comp_edges[:], deque(q), CONTRA[0])

    def restore(snap):
        nonlocal E, deg, offcnt, parent, size, comp_edges, q
        E, deg, offcnt, parent, size, comp_edges, q, CONTRA[0] = snap

    def choose_edge():
        # Pick unknown edge adjacent to most constrained node (near degree limit / clue)
        best = None
        best_score = -1
        for eid, (u, v) in enumerate(edges):
            if E[eid] != -1:
                continue
            def node_score(x):
                s = 0
                if grid[x // n][x % n] in ("W", "B"):
                    s += 10
                s += deg[x] * 3
                # fewer unknown incident edges => more constrained
                unk = sum(1 for ee, _, _ in adj[x] if E[ee] == -1)
                s += (4 - unk)
                return s
            score = node_score(u) + node_score(v)
            if score > best_score:
                best_score = score
                best = eid
        return best

    def all_clues_satisfied():
        for u in clue_nodes:
            if deg[u] != 2:
                return False
            pat = pattern_at_node(u)
            if pat is None:
                return False
            a, b = pat
            t = grid[u // n][u % n]
            if t == "B":
                if (a + 2) % 4 == b:
                    return False
            else:
                if (a + 2) % 4 != b:
                    return False
                # neighbor turn condition
                d1, d2 = a, b
                v1 = neigh(u, d1)
                v2 = neigh(u, d2)
                if v1 is None or v2 is None:
                    return False
                def is_turn(x):
                    pat2 = pattern_at_node(x)
                    if pat2 is None:
                        return False
                    p, q2 = pat2
                    return (p + 2) % 4 != q2
                if not (is_turn(v1) or is_turn(v2)):
                    return False
        return True

    def build_loop_path():
        # Extract the single loop from ON edges.
        # Find any node with deg 2; follow until returns.
        start = next((u for u in range(N) if deg[u] == 2), None)
        if start is None:
            return None
        path = [divmod(start, n)]
        prev = None
        cur = start
        while True:
            nxt = None
            for eid, v, d in adj[cur]:
                if E[eid] == 1 and v != prev:
                    nxt = v
                    break
            if nxt is None:
                return None
            if nxt == start:
                path.append(divmod(start, n))
                return path
            path.append(divmod(nxt, n))
            prev, cur = cur, nxt
            if len(path) > N + 2:
                return None

    def validate_single_loop():
        # All nodes must have degree 0 or 2; no multiple components among ON edges; all clue constraints satisfied.
        if not all_clues_satisfied():
            return False
        used = [u for u in range(N) if deg[u] == 2]
        if not used:
            return False
        # Connectedness: all used nodes in one component
        root = find(used[0])
        for u in used[1:]:
            if find(u) != root:
                return False
        # Every node degree must be 0 or 2
        for u in range(N):
            if deg[u] not in (0, 2):
                return False
        # Edge count in component should equal node count in component (single cycle)
        # For a single cycle graph: edges == nodes (in used subgraph)
        edge_count = sum(1 for e in E if e == 1)
        node_count = len(used)
        if edge_count != node_count:
            return False
        return True

    def dfs():
        propagate()
        if CONTRA[0]:
            return None
        eid = choose_edge()
        if eid is None:
            if validate_single_loop():
                return build_loop_path()
            return None

        # Try ON then OFF (often ON is more informative)
        for val in (1, 0):
            snap = snapshot()
            set_edge(eid, val)
            if not CONTRA[0]:
                res = dfs()
                if res is not None:
                    return res
            restore(snap)
        return None

    res = dfs()
    if res is None:
        return "No Solution"
    return str(res)

