from typing import List, Tuple, Optional, Dict

# Solver for "Shapeless, 1-Star" (a.k.a. 1-queen-per-row/col with adjacency forbidden and obstacles).
# Human-like logic: build candidates, propagate row/col singles, "forced by attack" exclusions,
# maintain exact-one constraints, and only then do minimal branching with strong heuristics.

Coord = Tuple[int, int]

def solve(observation: Dict) -> str:
    grid = observation["data"]
    n = len(grid)
    if any(len(row) != n for row in grid):
        return "No Solution"

    # Precompute allowed cells (not obstacles)
    allowed = [[grid[r][c] != 'B' for c in range(n)] for r in range(n)]

    # Neighbors (touching including diagonals)
    neigh = {}
    for r in range(n):
        for c in range(n):
            ns = []
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n:
                        ns.append((rr, cc))
            neigh[(r, c)] = ns

    all_cells = [(r, c) for r in range(n) for c in range(n)]

    # Bitset utilities
    # We'll represent candidate sets per row as bitmask over columns.
    FULL = (1 << n) - 1

    row_cand = [0] * n
    col_cand = [0] * n
    for r in range(n):
        m = 0
        for c in range(n):
            if allowed[r][c]:
                m |= (1 << c)
        row_cand[r] = m
    for c in range(n):
        m = 0
        for r in range(n):
            if allowed[r][c]:
                m |= (1 << r)
        col_cand[c] = m

    # State
    # star_row[r] = c or -1
    star_row = [-1] * n
    star_col = [-1] * n

    # Forbidden-by-adjacency mask per row over columns (cells that cannot be used due to placed stars)
    forbid_row = [0] * n

    # Fast count bits
    def popcount(x: int) -> int:
        return x.bit_count()

    def lowbit_index(x: int) -> int:
        return (x & -x).bit_length() - 1

    # Domain per row: allowed & not forbidden & if col already taken then excluded
    def row_domain(r: int) -> int:
        dom = row_cand[r] & ~forbid_row[r]
        # remove cols already assigned
        taken = 0
        for c in range(n):
            if star_col[c] != -1:
                taken |= (1 << c)
        return dom & ~taken

    # Symmetric domain per col: rows available for that col
    def col_domain(c: int) -> int:
        dom_rows = col_cand[c]
        # remove rows already assigned
        taken = 0
        for r in range(n):
            if star_row[r] != -1:
                taken |= (1 << r)
        dom_rows &= ~taken
        # remove rows where the (r,c) is forbidden by adjacency
        # (if forbid_row[r] has bit c)
        m = 0
        x = dom_rows
        while x:
            r = lowbit_index(x)
            x &= x - 1
            if (forbid_row[r] >> c) & 1:
                continue
            m |= (1 << r)
        return m

    # Place a star at (r,c), recording changes for undo.
    # Changes list stores tuples describing reversible edits.
    # ('sr', r, oldc), ('sc', c, oldr), ('fr', rr, oldmask)
    def place_star(r: int, c: int, changes: List[Tuple]) -> bool:
        if not allowed[r][c]:
            return False
        if star_row[r] != -1 or star_col[c] != -1:
            return False
        if (forbid_row[r] >> c) & 1:
            return False

        changes.append(('sr', r, -1))
        changes.append(('sc', c, -1))
        star_row[r] = c
        star_col[c] = r

        # Update forbid_row for all neighbor cells + same cell? only adjacency, but same cell now irrelevant.
        # Also, adjacency affects 8 neighbors, and forbids them.
        affected = neigh[(r, c)]
        for rr, cc in affected:
            old = forbid_row[rr]
            new = old | (1 << cc)
            if new != old:
                changes.append(('fr', rr, old))
                forbid_row[rr] = new

        # Additionally, since each row and col must have exactly 1, other cells in same row/col become irrelevant;
        # but we enforce via star_row/star_col, so no need to explicitly forbid.
        return True

    def undo(changes: List[Tuple]) -> None:
        for typ, a, old in reversed(changes):
            if typ == 'sr':
                star_row[a] = old
            elif typ == 'sc':
                star_col[a] = old
            else:  # 'fr'
                forbid_row[a] = old

    # Deduction loop:
    # 1) If a row unassigned has domain size 0 -> fail; size 1 -> force.
    # 2) If a col unassigned has domain size 0 -> fail; size 1 -> force.
    # 3) Hidden singles: in a row-domain, a column that appears only once among remaining rows must be forced there;
    #    similarly for rows in columns. (Exact cover style)
    def propagate(changes: List[Tuple]) -> bool:
        # Queue rows/cols to re-check
        # We'll iterate to fixpoint with efficient checks.
        while True:
            progress = False

            # Row singles
            for r in range(n):
                if star_row[r] != -1:
                    continue
                dom = row_domain(r)
                cnt = popcount(dom)
                if cnt == 0:
                    return False
                if cnt == 1:
                    c = lowbit_index(dom)
                    if not place_star(r, c, changes):
                        return False
                    progress = True

            # Col singles
            for c in range(n):
                if star_col[c] != -1:
                    continue
                domr = col_domain(c)
                cnt = popcount(domr)
                if cnt == 0:
                    return False
                if cnt == 1:
                    r = lowbit_index(domr)
                    if not place_star(r, c, changes):
                        return False
                    progress = True

            # Hidden singles by columns across remaining rows (each column exactly 1)
            # For each column not assigned, count candidate rows.
            # If only one row can take column -> force it.
            for c in range(n):
                if star_col[c] != -1:
                    continue
                domr = col_domain(c)
                cnt = popcount(domr)
                if cnt == 0:
                    return False
                if cnt == 1:
                    r = lowbit_index(domr)
                    if not place_star(r, c, changes):
                        return False
                    progress = True

            # Hidden singles by rows across remaining columns (each row exactly 1)
            for r in range(n):
                if star_row[r] != -1:
                    continue
                dom = row_domain(r)
                cnt = popcount(dom)
                if cnt == 0:
                    return False
                if cnt == 1:
                    c = lowbit_index(dom)
                    if not place_star(r, c, changes):
                        return False
                    progress = True

            if progress:
                continue

            # Global exact-one pruning: if a column is only present in k rows and those rows have to fill,
            # not much else to do without deeper techniques. We'll add a lightweight "availability check":
            # For any unassigned subset? too expensive. Skip.

            return True

    def is_solved() -> bool:
        return all(x != -1 for x in star_row)

    # Branching heuristic:
    # choose unassigned row with minimum remaining values; break ties by rows that constrain many (center).
    def choose_row_mrv() -> int:
        best_r = -1
        best_cnt = 10**9
        best_tie = -1
        for r in range(n):
            if star_row[r] != -1:
                continue
            dom = row_domain(r)
            cnt = popcount(dom)
            # cnt can't be 0 due to propagation before calling
            tie = -abs(r - (n - 1) / 2.0)  # favor central slightly
            if cnt < best_cnt or (cnt == best_cnt and tie > best_tie):
                best_cnt = cnt
                best_tie = tie
                best_r = r
        return best_r

    # Value ordering: try columns with least remaining rows (most constrained)
    def ordered_cols_for_row(r: int) -> List[int]:
        dom = row_domain(r)
        cols = []
        x = dom
        while x:
            c = lowbit_index(x)
            x &= x - 1
            cols.append(c)
        cols.sort(key=lambda c: popcount(col_domain(c)))
        return cols

    # Depth-first search with strong propagation
    def dfs() -> bool:
        changes: List[Tuple] = []
        if not propagate(changes):
            undo(changes)
            return False
        if is_solved():
            # keep changes (solution)
            return True

        r = choose_row_mrv()
        if r == -1:
            undo(changes)
            return False

        cols = ordered_cols_for_row(r)
        # Save state changes to undo after exploring all branches from this node
        base_changes = changes

        for c in cols:
            local_changes: List[Tuple] = []
            if place_star(r, c, local_changes):
                if dfs():
                    # keep solution; do not undo
                    return True
            undo(local_changes)

        undo(base_changes)
        return False

    if not dfs():
        return "No Solution"

    # Build answer grid
    ans = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        c = star_row[r]
        if c == -1:
            return "No Solution"
        ans[r][c] = 'S'
    return str(ans)

