OBSERVATION = {'data': [[None, None, None, 'W', None, None], [None, 'B', None, None, 'W', None], [None, 'W', None, None, None, None], [None, None, None, None, 'W', 'B'], ['W', 'B', 'W', None, None, 'W'], [None, None, None, None, None, None]]}
# Masyu (Loop the Loop) solver: aggressive human-like deductions + small guided backtracking.
# Generalized for N x N dot grid with clues on cells between dots (also N x N in observation).
# Output: ordered closed loop path as list of dot coordinates [(r,c),...,(r0,c0)] or "No Solution".

from collections import deque, defaultdict

# --- Utilities: edge indexing on (N+1)x(N+1) dots grid ---
# Horizontal edge: between (r,c)-(r,c+1) where r in [0..N], c in [0..N-1]
# Vertical edge: between (r,c)-(r+1,c) where r in [0..N-1], c in [0..N]

def solve(observation):
    data = observation["data"]
    N = len(data)
    if any(len(row) != N for row in data):
        return "No Solution"

    # Edge states: 0 unknown, 1 on (in loop), -1 off
    H = [[0] * N for _ in range(N + 1)]      # (N+1) x N
    V = [[0] * (N + 1) for _ in range(N)]    # N x (N+1)

    # Degree at each dot must be 0 or 2, and finally all used dots degree=2 in one component.
    deg = [[0] * (N + 1) for _ in range(N + 1)]

    # For fast propagation: track unknown counts per dot
    # neighbors edges list for each dot
    dot_edges = [[[] for _ in range(N + 1)] for __ in range(N + 1)]
    # Each edge encoded as (isH, r, c) => H[r][c] or V[r][c]
    for r in range(N + 1):
        for c in range(N):
            # H edge at (r,c) connects (r,c) and (r,c+1)
            dot_edges[r][c].append((True, r, c))
            dot_edges[r][c + 1].append((True, r, c))
    for r in range(N):
        for c in range(N + 1):
            # V edge at (r,c) connects (r,c) and (r+1,c)
            dot_edges[r][c].append((False, r, c))
            dot_edges[r + 1][c].append((False, r, c))

    def get_edge(e):
        isH, r, c = e
        return H[r][c] if isH else V[r][c]

    def set_edge(e, val, q):
        """Set edge to val (1 or -1). Enqueue affected constraints. Return False if contradiction."""
        isH, r, c = e
        cur = H[r][c] if isH else V[r][c]
        if cur == val:
            return True
        if cur != 0 and cur != val:
            return False
        if isH:
            H[r][c] = val
            a = (r, c)
            b = (r, c + 1)
        else:
            V[r][c] = val
            a = (r, c)
            b = (r + 1, c)
        if val == 1:
            deg[a[0]][a[1]] += 1
            deg[b[0]][b[1]] += 1
        # enqueue endpoints for degree propagation
        q.append(("dot", a[0], a[1]))
        q.append(("dot", b[0], b[1]))
        # enqueue adjacent cell constraints around this edge
        # cells are between dots: (cr,cc) where 0<=cr<N,0<=cc<N
        # H edge at row r separates cell above (r-1, c) and below (r, c)
        # V edge at col c separates cell left (r, c-1) and right (r, c)
        if isH:
            if 0 <= r - 1 < N and 0 <= c < N:
                q.append(("cell", r - 1, c))
            if 0 <= r < N and 0 <= c < N:
                q.append(("cell", r, c))
        else:
            if 0 <= r < N and 0 <= c - 1 < N:
                q.append(("cell", r, c - 1))
            if 0 <= r < N and 0 <= c < N:
                q.append(("cell", r, c))
        return True

    def edge_endpoints(e):
        isH, r, c = e
        if isH:
            return (r, c), (r, c + 1)
        else:
            return (r, c), (r + 1, c)

    def cell_edges(cr, cc):
        # cell at (cr,cc) bounded by:
        # top H[cr][cc], bottom H[cr+1][cc], left V[cr][cc], right V[cr][cc+1]
        return [
            (True, cr, cc),       # top
            (True, cr + 1, cc),   # bottom
            (False, cr, cc),      # left
            (False, cr, cc + 1)   # right
        ]

    def dot_unknown_on_off(r, c):
        on = off = unk = 0
        for e in dot_edges[r][c]:
            v = get_edge(e)
            if v == 1:
                on += 1
            elif v == -1:
                off += 1
            else:
                unk += 1
        return on, off, unk

    # ---- Masyu constraints (human rules) ----
    # Each clue is at cell (r,c). The loop travels along cell borders, so at a cell:
    # - W: must go straight through: either (top+bottom ON and left+right OFF) OR (left+right ON and top+bottom OFF)
    #      and additionally: at least one of adjacent cells along the straight direction must be a turn.
    #      Equivalent: If W is horizontal pass (left+right ON), then at least one of (top-left corner turn)?? Actually turn refers to next step at the vertices adjacent along the path.
    #      Standard Masyu rule: If the line goes straight through a white circle, it must turn in at least one of the adjacent cells (in the next or previous cell along the path).
    #      Operationally: If W is horizontal through cell, then at least one of the two vertices left and right of the cell is a turn (i.e., path turns at that dot).
    #      Similarly for vertical.
    # - B: must turn at this cell: exactly one of {top,bottom} and one of {left,right} are ON, and the line must go straight through the adjacent cells in both directions after the turn.
    #      Standard: After turning in black cell, the line must continue straight for at least one more cell in both directions.
    #
    # We implement these as local implications and when enough decided, force neighbors.

    def is_turn_at_dot(r, c):
        # if degree at dot is 2 and the two ON edges are not collinear => turn
        if deg[r][c] != 2:
            return None  # unknown
        ons = [e for e in dot_edges[r][c] if get_edge(e) == 1]
        if len(ons) != 2:
            return None
        # Determine orientations
        def ori(e):
            return "H" if e[0] else "V"
        return ori(ons[0]) != ori(ons[1])

    def force_dot_degree_rules(r, c, q):
        on, off, unk = dot_unknown_on_off(r, c)
        if on > 2:
            return False
        if on == 2:
            # all other incident edges must be OFF
            for e in dot_edges[r][c]:
                if get_edge(e) == 0:
                    if not set_edge(e, -1, q):
                        return False
        # if on + unk < 2 and on != 0 => impossible to reach degree 2
        if on == 1 and unk == 0:
            return False
        if on == 0:
            # allow degree 0 or 2; but if some edges forced ON later, ok.
            pass
        if on == 1 and unk == 1:
            # must take the remaining unknown as ON to reach degree 2 (cannot end with degree 1)
            for e in dot_edges[r][c]:
                if get_edge(e) == 0:
                    if not set_edge(e, 1, q):
                        return False
        if on == 0 and unk == 1:
            # cannot end with degree 1; so last unknown must be OFF
            for e in dot_edges[r][c]:
                if get_edge(e) == 0:
                    if not set_edge(e, -1, q):
                        return False
        return True

    def cell_pattern_possibilities(cr, cc):
        clue = data[cr][cc]
        edges = cell_edges(cr, cc)
        vals = [get_edge(e) for e in edges]  # [top,bottom,left,right]
        # Return list of possible assignments dict {edge: val} consistent with clue and current vals.
        # Note: values can remain 0 in assignment (leave unspecified) in returned possibilities, but we prefer full.
        possible = []

        def consistent(assign):
            for i, e in enumerate(edges):
                v = vals[i]
                if v != 0 and assign[i] != v:
                    return False
            return True

        if clue is None:
            # unconstrained locally (still must form loop globally)
            return None

        if clue == "W":
            # straight: vertical or horizontal, exactly two opposite ON and other two OFF
            for mode in (0, 1):  # 0 vertical, 1 horizontal
                if mode == 0:
                    assign = [1, 1, -1, -1]
                else:
                    assign = [-1, -1, 1, 1]
                if consistent(assign):
                    possible.append(assign)

        elif clue == "B":
            # turn: one from (top,bottom) and one from (left,right) ON; the other two OFF
            for t in (0, 1):  # which vertical edge ON: 0 top,1 bottom
                for s in (2, 3):  # which horizontal edge ON: 2 left,3 right
                    assign = [-1, -1, -1, -1]
                    assign[t] = 1
                    assign[s] = 1
                    if consistent(assign):
                        possible.append(assign)
        else:
            return None

        return possible

    def apply_cell_constraints(cr, cc, q):
        clue = data[cr][cc]
        if clue is None:
            return True
        poss = cell_pattern_possibilities(cr, cc)
        if not poss:
            return False
        edges = cell_edges(cr, cc)

        # If only one possible pattern, enforce it
        if len(poss) == 1:
            pat = poss[0]
            for i, e in enumerate(edges):
                if pat[i] != 0 and get_edge(e) == 0:
                    if not set_edge(e, pat[i], q):
                        return False

        # Also do common-value propagation across possibilities
        for i, e in enumerate(edges):
            if get_edge(e) != 0:
                continue
            vals = {p[i] for p in poss}
            if len(vals) == 1:
                v = vals.pop()
                if not set_edge(e, v, q):
                    return False

        # Additional Masyu forward rules for W/B when orientation determined:
        # For W: if straight orientation fixed, enforce "turn on at least one adjacent dot"
        # We'll implement as: at each of the two dots along travel direction, forbid both being straight-through.
        # We model it via requiring at least one of those dots to be a turn, which can be propagated when one dot is known straight.
        if clue == "W":
            top, bottom, left, right = edges
            tv = get_edge(top); bv = get_edge(bottom); lv = get_edge(left); rv = get_edge(right)
            orient = None
            if lv == 1 and rv == 1:
                orient = "H"
            elif tv == 1 and bv == 1:
                orient = "V"
            if orient == "H":
                # travel passes through left and right sides: adjacent dots are (cr,cc)?? Actually corners:
                # The path enters/leaves through left/right edges, so it uses the midpoints; turns occur at dots on left/right of cell:
                # Those dots are (cr,cc) and (cr+1,cc) for left edge; (cr,cc+1) and (cr+1,cc+1) for right edge.
                # But "turn in previous/next step" refers to vertices immediately before/after traversing the cell, i.e.,
                # at one of the two dots on left side AND at one of the two dots on right side, at least one of the sides must contain a turn.
                # Standard simplification: if W is horizontal, then at least one of the two vertices to the left of the circle must be a turn
                # OR at least one of the two vertices to the right must be a turn. Equivalent to: cannot go straight through both neighboring cells.
                # We implement a stronger common human rule:
                # If W horizontal, then the edges continuing left and right from the cell must not both be horizontal straight through at both adjacent dots.
                # Concretely: for left side, the path uses left edge => either top-left corner or bottom-left corner is used.
                # Hard to encode without segment-level vars. We'll use vertex-turn enforcement:
                left_dots = [(cr, cc), (cr + 1, cc)]
                right_dots = [(cr, cc + 1), (cr + 1, cc + 1)]
                if not enforce_at_least_one_turn_among_sides(left_dots, right_dots, q):
                    return False
            elif orient == "V":
                top_dots = [(cr, cc), (cr, cc + 1)]
                bot_dots = [(cr + 1, cc), (cr + 1, cc + 1)]
                if not enforce_at_least_one_turn_among_sides(top_dots, bot_dots, q):
                    return False

        if clue == "B":
            # For B, after the turn, it must go straight in both directions for one cell.
            # This translates to: if top edge ON, then the segment must continue upward (H[cr][cc] ON implies at dot (cr,cc)-> vertical),
            # but easiest local: determine which two edges are ON; then force the opposite edges in adjacent cells to be ON (straight continuation).
            edges = cell_edges(cr, cc)
            vals = [get_edge(e) for e in edges]  # top,bottom,left,right
            if vals.count(1) == 2:
                # Identify ON edges
                on_idx = [i for i,v in enumerate(vals) if v==1]
                # Must be one vertical and one horizontal
                if (0 in on_idx or 1 in on_idx) and (2 in on_idx or 3 in on_idx):
                    # For each ON edge, force continuation straight in the neighboring cell beyond that edge:
                    # If top ON => above cell's bottom edge ON i.e., H[cr][cc] is top; continuation means in cell above, top edge also ON? Wait:
                    # The path comes into black cell via that edge and must go straight in adjacent cell next to it, meaning it must exit the adjacent cell through the opposite edge.
                    # Practically: if top edge of black cell is ON, then in the cell above (cr-1,cc), the top edge H[cr-1][cc] must also be ON (vertical straight through that cell),
                    # and in that above cell, the line must be vertical (left/right OFF). We can only force the shared edge and the next edge:
                    # The "one more cell straight" implies the edge continuing beyond the vertex at the far side is ON:
                    # Top ON uses vertex pair (cr,cc)-(cr,cc+1). Going straight upward means the vertical edges above those vertices (V[cr-1][cc], V[cr-1][cc+1])? Not right.
                    # In Masyu, path runs on grid lines; entering from top means it used the top border segment, so it connects to one of the two vertical borders (left/right) inside cell via a corner (turn).
                    # After turning, the outgoing direction (say left) must continue straight for one cell: i.e., the cell adjacent in that direction must have the line go straight through (no turn at the shared vertex).
                    # Exact encoding needs corner-choice; we'll enforce standard strong deductions via "forced straight in adjacent cell" using edge patterns:
                    # Use known ON edges to infer which corners are used? Not unique. We'll instead use safe implications:
                    # If black cell has top ON and left ON, then the turn is at top-left corner dot (cr,cc). Then continuation requires:
                    # - Above cell (cr-1,cc) must have vertical straight at that corner => its left or right? Actually continuation from top means segment before entering must be straight, so at dot (cr,cc) it comes from above via V[cr-1][cc] or V[cr-1][cc]? ambiguous.
                    # Therefore, only apply when corner is forced by surrounding OFF edges:
                    pass
        return True

    def enforce_at_least_one_turn_among_sides(sideA_dots, sideB_dots, q):
        # sideA are two dots on one side of a straight-through white circle, sideB other side.
        # Constraint: at least one of the four dots must be a turn, but more precisely:
        # at least one dot on sideA OR at least one dot on sideB must be a turn.
        # We'll apply conservative propagation:
        # If both dots on sideA are already confirmed "straight" (deg=2 and not turn), then force at least one dot on sideB to be a turn if possible.
        def confirmed_straight(dot):
            r,c = dot
            t = is_turn_at_dot(r,c)
            return (t is False)
        def confirmed_turn(dot):
            r,c = dot
            t = is_turn_at_dot(r,c)
            return (t is True)

        A_all_straight = all(is_turn_at_dot(r,c) is False for r,c in sideA_dots if deg[r][c]==2) and all(deg[r][c]==2 for r,c in sideA_dots)
        B_all_straight = all(is_turn_at_dot(r,c) is False for r,c in sideB_dots if deg[r][c]==2) and all(deg[r][c]==2 for r,c in sideB_dots)

        if any(confirmed_turn(d) for d in sideA_dots) or any(confirmed_turn(d) for d in sideB_dots):
            return True
        if A_all_straight and B_all_straight:
            return False

        # If A_all_straight, then B must contain a turn; enforce by forbidding both B dots to be straight when they get completed.
        # We can't force turn without more info; defer.
        # Similarly for B_all_straight.
        return True

    # --- Connectivity / premature cycle prevention (human rule: avoid small loops) ---
    parent = {}
    size = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return True

    def init_dsu():
        parent.clear()
        size.clear()
        for r in range(N + 1):
            for c in range(N + 1):
                parent[(r,c)] = (r,c)
                size[(r,c)] = 1

    def rebuild_dsu_from_on_edges():
        init_dsu()
        for r in range(N + 1):
            for c in range(N):
                if H[r][c] == 1:
                    union((r,c), (r,c+1))
        for r in range(N):
            for c in range(N + 1):
                if V[r][c] == 1:
                    union((r,c), (r+1,c))

    def would_create_premature_cycle(e):
        # If adding this ON edge connects two vertices already connected, it forms a cycle.
        # Allow only if it would complete the single final loop (i.e., all vertices with deg>0 are in that component and all degrees 2).
        a,b = edge_endpoints(e)
        if find(a) != find(b):
            return False
        # it would create a cycle; check if all constraints already force completion
        # If any dot has deg 1 or unknown incident edges for used dots, it's premature.
        for r in range(N + 1):
            for c in range(N + 1):
                if deg[r][c] == 1:
                    return True
        # Also if there exists any clue cell not yet fully satisfied (some required ON not set), it's premature
        # We'll allow only when no unknown edges remain among used component and loop can be closed.
        return True

    # --- Propagation engine ---
    def propagate(queue):
        while queue:
            typ, r, c = queue.popleft()
            if typ == "dot":
                if not force_dot_degree_rules(r, c, queue):
                    return False
            else:
                if not apply_cell_constraints(r, c, queue):
                    return False
        return True

    # Initial queue: all cells and dots
    q = deque()
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                q.append(("cell", r, c))
    for r in range(N + 1):
        for c in range(N + 1):
            q.append(("dot", r, c))

    # --- Search with strong branching ---
    def snapshot():
        return (
            [row[:] for row in H],
            [row[:] for row in V],
            [row[:] for row in deg],
        )

    def restore(snap):
        nonlocal H, V, deg
        H, V, deg = ([row[:] for row in snap[0]], [row[:] for row in snap[1]], [row[:] for row in snap[2]])

    def all_edges():
        for r in range(N + 1):
            for c in range(N):
                yield (True, r, c)
        for r in range(N):
            for c in range(N + 1):
                yield (False, r, c)

    def choose_branch_edge():
        # Heuristic: pick unknown edge adjacent to a clue, else any unknown with endpoint having deg=1.
        best = None
        best_score = -1
        for e in all_edges():
            if get_edge(e) != 0:
                continue
            (a,b) = edge_endpoints(e)
            score = 0
            # endpoints deg
            da = deg[a[0]][a[1]]
            db = deg[b[0]][b[1]]
            if da == 1: score += 5
            if db == 1: score += 5
            if da == 2 or db == 2: score += 2
            # adjacent clue cells
            isH, r, c = e
            adj = 0
            if isH:
                if 0 <= r-1 < N and data[r-1][c] is not None: adj += 1
                if 0 <= r < N and data[r][c] is not None: adj += 1
            else:
                if 0 <= c-1 < N and data[r][c-1] is not None: adj += 1
                if 0 <= c < N and data[r][c] is not None: adj += 1
            score += 3*adj
            if score > best_score:
                best_score = score
                best = e
        return best

    def check_final():
        # All dots must have degree 0 or 2, and all clue constraints satisfied, and single loop.
        for r in range(N + 1):
            for c in range(N + 1):
                if deg[r][c] not in (0,2):
                    return False
        # clue patterns must be exactly satisfied (no unknown around them)
        for r in range(N):
            for c in range(N):
                clue = data[r][c]
                if clue is None:
                    continue
                edges = cell_edges(r,c)
                vals = [get_edge(e) for e in edges]
                if 0 in vals:
                    return False
                if clue == "W":
                    ok = (vals[0]==1 and vals[1]==1 and vals[2]==-1 and vals[3]==-1) or (vals[0]==-1 and vals[1]==-1 and vals[2]==1 and vals[3]==1)
                    if not ok:
                        return False
                elif clue == "B":
                    if vals.count(1) != 2:
                        return False
                    if not ((vals[0]==1 or vals[1]==1) and (vals[2]==1 or vals[3]==1)):
                        return False
        # single component among used dots
        rebuild_dsu_from_on_edges()
        used = [(r,c) for r in range(N+1) for c in range(N+1) if deg[r][c]==2]
        if not used:
            return False
        root = find(used[0])
        if any(find(x)!=root for x in used):
            return False
        return True

    def dfs():
        # propagate deterministic
        qq = deque()
        if not propagate(qq):
            return False

        # quick contradiction: any clue cell has no possible patterns
        for r in range(N):
            for c in range(N):
                if data[r][c] is not None:
                    poss = cell_pattern_possibilities(r,c)
                    if poss is not None and not poss:
                        return False

        if all(get_edge(e) != 0 for e in all_edges()):
            return check_final()

        e = choose_branch_edge()
        if e is None:
            return False

        # rebuild DSU for cycle check
        rebuild_dsu_from_on_edges()

        # try ON first if it doesn't create premature cycle
        for val in (1, -1):
            if val == 1 and would_create_premature_cycle(e):
                continue
            snap = snapshot()
            qloc = deque()
            if not set_edge(e, val, qloc):
                continue
            if not propagate(qloc):
                restore(snap)
                continue
            if dfs():
                return True
            restore(snap)
        return False

    # Start with initial propagation
    if not propagate(q):
        return "No Solution"

    if not dfs():
        return "No Solution"

    # Build loop path from ON edges
    # Create adjacency of dots with ON edges
    adj = defaultdict(list)
    for r in range(N + 1):
        for c in range(N):
            if H[r][c] == 1:
                a=(r,c); b=(r,c+1)
                adj[a].append(b); adj[b].append(a)
    for r in range(N):
        for c in range(N + 1):
            if V[r][c] == 1:
                a=(r,c); b=(r+1,c)
                adj[a].append(b); adj[b].append(a)

    # pick a starting used dot
    start = None
    for k,v in adj.items():
        if len(v) == 2:
            start = k
            break
    if start is None:
        return "No Solution"

    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = adj[cur]
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
        if len(path) > (N+1)*(N+1)*4:
            return "No Solution"

    return str(path)

