from collections import deque

# Solver for "3x3 neighborhood black count" puzzle (Minesweeper-like with center included)
# Grid variables: each cell is black (1) or white (0). Given number at (r,c) constrains sum of 3x3 vars around it.
# Human-like techniques implemented:
#  - Local bounds propagation: for each clue, maintain (min,max) possible sum given current assignments.
#  - Forced assignments: if clue needs k more blacks and exactly k undecided -> all black; if needs 0 -> all white.
#  - Arc-consistency style queue: whenever a variable changes, only neighboring clues are revisited.
#  - Contradiction checks early.
#  - Heuristic branching: choose variable that appears in most tight constraints (smallest slack / highest impact).

def solve(observation):
    data = observation["data"]
    H = len(data)
    W = len(data[0]) if H else 0

    # Map each clue cell to list of variable indices in its 3x3 neighborhood.
    def inb(r, c):
        return 0 <= r < H and 0 <= c < W

    # Indexing variables
    N = H * W
    def vid(r, c): return r * W + c
    def rc(i): return divmod(i, W)

    # Collect clues
    clues = []
    clue_at = {}  # (r,c)->clue_id
    for r in range(H):
        for c in range(W):
            v = data[r][c]
            if v is None:
                continue
            cid = len(clues)
            clue_at[(r, c)] = cid
            nbrs = []
            for rr in range(r - 1, r + 2):
                for cc in range(c - 1, c + 2):
                    if inb(rr, cc):
                        nbrs.append(vid(rr, cc))
            clues.append((v, nbrs))

    # For each variable, which clues it participates in
    var_to_clues = [[] for _ in range(N)]
    for cid, (_, nbrs) in enumerate(clues):
        for x in nbrs:
            var_to_clues[x].append(cid)

    # State arrays
    # val[i] in {-1,0,1}
    val = [-1] * N

    # Precompute for clues: neighbor list and quick access
    clue_target = [t for t, _ in clues]
    clue_nbrs = [nbrs for _, nbrs in clues]

    # Helper: compute current sums and undecided counts for a clue
    def clue_stats(cid):
        s = 0
        u = 0
        for x in clue_nbrs[cid]:
            vx = val[x]
            if vx == -1:
                u += 1
            else:
                s += vx
        return s, u

    # Apply assignment with propagation using queue of impacted clues
    def propagate(initial_queue, val_local):
        # val_local is list; we mutate it.
        q = deque(initial_queue)
        inq = [False] * len(clues)
        for cid in initial_queue:
            if 0 <= cid < len(clues):
                inq[cid] = True

        # Also allow variable assignment queue as (var, value)
        assign_q = deque()

        def enqueue_clue(cid):
            if not inq[cid]:
                inq[cid] = True
                q.append(cid)

        def set_var(i, v):
            cur = val_local[i]
            if cur == v:
                return True
            if cur != -1 and cur != v:
                return False
            val_local[i] = v
            for cid in var_to_clues[i]:
                enqueue_clue(cid)
            return True

        while q or assign_q:
            while assign_q:
                i, v = assign_q.popleft()
                if not set_var(i, v):
                    return False

            if not q:
                continue
            cid = q.popleft()
            inq[cid] = False
            target = clue_target[cid]
            s, u = 0, 0
            undec = []
            for x in clue_nbrs[cid]:
                vx = val_local[x]
                if vx == -1:
                    u += 1
                    undec.append(x)
                else:
                    s += vx

            # Bounds check
            if s > target or s + u < target:
                return False

            need = target - s
            if need == 0 and u > 0:
                # all undecided are white
                for x in undec:
                    assign_q.append((x, 0))
            elif need == u and u > 0:
                # all undecided are black
                for x in undec:
                    assign_q.append((x, 1))

        return True

    # Initialize propagation from all clues (some immediate forced moves possible)
    if not propagate(list(range(len(clues))), val):
        return "No Solution"

    # Heuristic: choose next var to branch on
    def pick_var(val_local):
        best = -1
        best_score = None
        for i in range(N):
            if val_local[i] != -1:
                continue
            # Score variable by how tight its participating clues are: sum of (1/(slack+1))
            # slack = u - need or need? We compute minimal slack around.
            score = 0.0
            for cid in var_to_clues[i]:
                target = clue_target[cid]
                s = 0
                u = 0
                for x in clue_nbrs[cid]:
                    vx = val_local[x]
                    if vx == -1:
                        u += 1
                    else:
                        s += vx
                need = target - s
                # slack measures how many free choices remain
                slack_low = need  # blacks to place among u vars
                slack_high = u - need
                slack = min(slack_low, slack_high)
                if slack < 0:
                    return i  # will be caught, but prioritize
                score += 1.0 / (slack + 1.0)
            # Prefer variables in more constraints and higher score
            key = (-len(var_to_clues[i]), -score)
            if best_score is None or key < best_score:
                best_score = key
                best = i
        return best

    # Determine a good branching order (try value that seems more plausible from neighbors)
    def branch_values(i, val_local):
        # Estimate probability of black from clue needs
        p = 0.5
        weights = 0.0
        for cid in var_to_clues[i]:
            target = clue_target[cid]
            s = 0
            u = 0
            for x in clue_nbrs[cid]:
                vx = val_local[x]
                if vx == -1:
                    u += 1
                else:
                    s += vx
            need = target - s
            if u <= 0:
                continue
            # expected density
            dens = need / u
            w = 1.0
            p = (p * weights + dens * w) / (weights + w)
            weights += w
        # Try closer to p first
        if p >= 0.5:
            return (1, 0)
        return (0, 1)

    # Depth-first with propagation; not naive due to strong pruning + focused branching
    def dfs(val_local):
        i = pick_var(val_local)
        if i == -1:
            return val_local  # solved

        # If any clue already inconsistent, fail quickly
        for cid in var_to_clues[i]:
            target = clue_target[cid]
            s = 0
            u = 0
            for x in clue_nbrs[cid]:
                vx = val_local[x]
                if vx == -1:
                    u += 1
                else:
                    s += vx
            if s > target or s + u < target:
                return None

        for v in branch_values(i, val_local):
            nxt = val_local[:]  # copy
            nxt[i] = v
            # propagate from affected clues
            if propagate(var_to_clues[i], nxt):
                res = dfs(nxt)
                if res is not None:
                    return res
        return None

    sol = dfs(val)
    if sol is None:
        return "No Solution"

    # Build output grid: 'B' for black, None for white
    out = []
    for r in range(H):
        row = []
        for c in range(W):
            v = sol[vid(r, c)]
            row.append('B' if v == 1 else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

