from collections import deque

# Masu (Masyu) loop solver on N x N DOT grid with clues on cell centers:
# Dots: (r,c) 0..N-1, 0..N-1
# Edges between orthogonally adjacent dots.
# Clue at cell (r,c) affects the vertex/dot (r,c) in this problem statement's coordinate system.
#
# Representation:
# For each dot v, incident edges to N/E/S/W in that order; each edge can be ON, OFF, or UNK.
# Constraints:
# - Each dot degree is 0 or 2; final solution must be single cycle (no multiple cycles; no degree-0 nodes used by loop).
# - White clue at v: loop goes straight through v (deg=2, opposite edges ON), and at least one of adjacent vertices
#   along the straight direction must be a turn (i.e., not straight).
# - Black clue at v: loop turns at v (deg=2, adjacent edges ON), and in both directions of the turn, the next vertex
#   must be straight (deg=2 with opposite edges ON along that travel direction).
#
# We enforce strong propagation with local deductions + global subcycle prevention using DSU with "cycle closure" checks.

UNK, ON, OFF = 0, 1, -1
DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]  # N,E,S,W
OPP = [2, 3, 0, 1]

def solve(observation):
    data = observation["data"]
    N = len(data)
    # quick validation
    if any(len(row) != N for row in data):
        return "No Solution"

    # Edge indexing helpers: store only E and S edges per dot to avoid duplicates
    # Edge key: (r,c,dir) where dir in {1(E),2(S)} for canonical storage
    def edge_key(r, c, d):
        if d == 1:  # E
            return (r, c, 1)
        if d == 2:  # S
            return (r, c, 2)
        if d == 3:  # W -> E of (r,c-1)
            return (r, c - 1, 1)
        if d == 0:  # N -> S of (r-1,c)
            return (r - 1, c, 2)
        raise ValueError

    def edge_endpoints(k):
        r, c, d = k
        if d == 1:
            return (r, c), (r, c + 1)
        else:
            return (r, c), (r + 1, c)

    def in_bounds_dot(r, c):
        return 0 <= r < N and 0 <= c < N

    # Build all edges
    edges = {}
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                edges[(r, c, 1)] = UNK
            if r + 1 < N:
                edges[(r, c, 2)] = UNK

    # Incidence lists per dot: list of (dir, edge_key)
    inc = [[[] for _ in range(N)] for __ in range(N)]
    for (r, c, d) in edges.keys():
        a, b = edge_endpoints((r, c, d))
        ra, ca = a
        rb, cb = b
        if d == 1:
            inc[ra][ca].append((1, (r, c, 1)))
            inc[rb][cb].append((3, (r, c, 1)))
        else:
            inc[ra][ca].append((2, (r, c, 2)))
            inc[rb][cb].append((0, (r, c, 2)))

    # DSU to track connectivity of ON edges; prevent premature small cycles.
    # We'll also maintain size of each component and whether it already has a cycle.
    parent = {}
    comp_size = {}
    comp_has_cycle = {}

    def vid(r, c):
        return r * N + c

    for r in range(N):
        for c in range(N):
            v = vid(r, c)
            parent[v] = v
            comp_size[v] = 1
            comp_has_cycle[v] = False

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            comp_has_cycle[ra] = True
            return ra
        if comp_size[ra] < comp_size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        comp_size[ra] += comp_size[rb]
        comp_has_cycle[ra] = comp_has_cycle[ra] or comp_has_cycle[rb]
        return ra

    # Degree tracking and quick counts
    deg_on = [[0] * N for _ in range(N)]
    deg_off = [[0] * N for _ in range(N)]  # count forced OFF among incident edges
    # total incident edges count per dot varies at borders
    deg_total = [[len(inc[r][c]) for c in range(N)] for r in range(N)]

    # For clue reasoning: determine "straight" vs "turn" at a vertex given edge states
    def is_forced_straight(r, c):
        # returns True if dot degree must be 2 with opposite edges ON based on assignments (not necessarily complete)
        ons = []
        unks = []
        for d, k in inc[r][c]:
            st = edges[k]
            if st == ON:
                ons.append(d)
            elif st == UNK:
                unks.append(d)
        if len(ons) == 2:
            return (ons[0] + 2) % 4 == ons[1]
        if len(ons) > 2:
            return False
        # If exactly one ON and all remaining possible to reach degree2 only with opposite?
        # Not fully forced; return False to avoid incorrect inferences.
        return False

    def is_forced_turn(r, c):
        ons = []
        for d, k in inc[r][c]:
            if edges[k] == ON:
                ons.append(d)
        if len(ons) == 2:
            return (ons[0] + 2) % 4 != ons[1]
        if len(ons) > 2:
            return False
        return False

    # Assignment with propagation queue
    q = deque()
    contradiction = False

    def set_edge(k, val):
        nonlocal contradiction
        cur = edges[k]
        if cur == val:
            return
        if cur != UNK and cur != val:
            contradiction = True
            return
        edges[k] = val
        a, b = edge_endpoints(k)
        ra, ca = a
        rb, cb = b
        if val == ON:
            deg_on[ra][ca] += 1
            deg_on[rb][cb] += 1
            # union with cycle detection; forbid forming a cycle before all clues satisfied and all used vertices in component are closed
            va, vb = vid(ra, ca), vid(rb, cb)
            rpa, rpb = find(va), find(vb)
            if rpa == rpb:
                # closing a cycle; only allowed if it will be the final single loop and no other ON edges remain to add.
                # We'll conservatively forbid unless all vertices in this component already have deg==2 and no other ON elsewhere can connect.
                # Check "premature" closure: if any vertex in component has deg_on < 2 and can still connect outside, it's premature.
                comp_root = rpa
                # Since DSU doesn't track member list, use a conservative rule:
                # disallow cycle closure unless all incident UNK edges on all vertices already OFF/ON leading to finality.
                # We'll instead mark cycle and later ensure single cycle; for pruning, require that both endpoints already had deg_on==1 before adding,
                # so closure only occurs when all degrees in component likely satisfied.
                pass
            union(va, vb)
        else:
            deg_off[ra][ca] += 1
            deg_off[rb][cb] += 1
        # enqueue endpoints for local propagation
        q.append(("dot", ra, ca))
        q.append(("dot", rb, cb))
        # enqueue any clue constraints at these dots and neighbors (for W/B lookahead)
        q.append(("clue", ra, ca))
        q.append(("clue", rb, cb))
        for dr, dc in DIRS:
            nr, nc = ra + dr, ca + dc
            if in_bounds_dot(nr, nc):
                q.append(("clue", nr, nc))
            nr, nc = rb + dr, cb + dc
            if in_bounds_dot(nr, nc):
                q.append(("clue", nr, nc))

    def force_degree_rules(r, c):
        nonlocal contradiction
        if contradiction:
            return
        on = deg_on[r][c]
        off = deg_off[r][c]
        total = deg_total[r][c]
        unk = total - on - off
        # degree cannot exceed 2
        if on > 2:
            contradiction = True
            return
        # if on == 2 => rest must be OFF
        if on == 2 and unk:
            for d, k in inc[r][c]:
                if edges[k] == UNK:
                    set_edge(k, OFF)
                    if contradiction:
                        return
        # if on == 1 and total-off == 1 => must turn on the remaining possible to reach degree2? Actually need degree 0 or 2.
        # If any edge is ON, degree cannot be 0; so must reach degree 2.
        if on == 1:
            # Need exactly one more ON among remaining UNK
            if unk == 0:
                contradiction = True  # stuck at degree 1
                return
            if unk == 1:
                for d, k in inc[r][c]:
                    if edges[k] == UNK:
                        set_edge(k, ON)
                        return
        # if on == 0:
        # if total-off == 1 => cannot have degree 2, so must be degree 0 => force remaining to OFF
        if on == 0 and (total - off) == 1:
            for d, k in inc[r][c]:
                if edges[k] == UNK:
                    set_edge(k, OFF)
                    return

    def apply_white(r, c):
        nonlocal contradiction
        if data[r][c] != "W" or contradiction:
            return
        # White: straight through (if used) and at least one adjacent vertex along path must be a turn.
        # We enforce: degree at this dot cannot be 0; thus must be 2 straight.
        # Straight means either (N,S) ON and (E,W) OFF, or (E,W) ON and (N,S) OFF, respecting borders.
        # Determine feasibility sets.
        dirs_present = {d for d, _ in inc[r][c]}
        vert_possible = (0 in dirs_present and 2 in dirs_present)
        hori_possible = (1 in dirs_present and 3 in dirs_present)
        if not (vert_possible or hori_possible):
            contradiction = True
            return
        # Based on existing ON edges, restrict orientation.
        on_dirs = [d for d, k in inc[r][c] if edges[k] == ON]
        if len(on_dirs) == 1:
            d = on_dirs[0]
            # must be straight so opposite must be ON
            od = OPP[d]
            if od not in dirs_present:
                contradiction = True
                return
            set_edge(edge_key(r, c, od), ON)
            # and the perpendiculars must be OFF (if present)
            for pd in [(d + 1) % 4, (d + 3) % 4]:
                if pd in dirs_present:
                    set_edge(edge_key(r, c, pd), OFF)
            return
        if len(on_dirs) == 2:
            # must be opposite
            if (on_dirs[0] + 2) % 4 != on_dirs[1]:
                contradiction = True
            return
        if len(on_dirs) == 0:
            # if any perpendicular edge is forced OFF, may force orientation
            # Check if vertical or horizontal becomes impossible due to OFF.
            def orientation_ok(pair):
                a, b = pair
                if a not in dirs_present or b not in dirs_present:
                    return False
                ka, kb = edge_key(r, c, a), edge_key(r, c, b)
                if edges[ka] == OFF or edges[kb] == OFF:
                    return False
                return True

            can_vert = orientation_ok((0, 2))
            can_hori = orientation_ok((1, 3))
            if not can_vert and not can_hori:
                contradiction = True
                return
            if can_vert and not can_hori:
                set_edge(edge_key(r, c, 0), ON)
                set_edge(edge_key(r, c, 2), ON)
                if 1 in dirs_present:
                    set_edge(edge_key(r, c, 1), OFF)
                if 3 in dirs_present:
                    set_edge(edge_key(r, c, 3), OFF)
            elif can_hori and not can_vert:
                set_edge(edge_key(r, c, 1), ON)
                set_edge(edge_key(r, c, 3), ON)
                if 0 in dirs_present:
                    set_edge(edge_key(r, c, 0), OFF)
                if 2 in dirs_present:
                    set_edge(edge_key(r, c, 2), OFF)

    def apply_black(r, c):
        nonlocal contradiction
        if data[r][c] != "B" or contradiction:
            return
        # Black: must turn at this dot => choose one of two adjacent pairs (N,E),(E,S),(S,W),(W,N) depending on borders.
        dirs_present = {d for d, _ in inc[r][c]}
        # Determine allowed turn pairs
        turn_pairs = []
        for d in range(4):
            d2 = (d + 1) % 4
            if d in dirs_present and d2 in dirs_present:
                turn_pairs.append((d, d2))
        if not turn_pairs:
            contradiction = True
            return
        on_dirs = [d for d, k in inc[r][c] if edges[k] == ON]
        if len(on_dirs) == 1:
            d = on_dirs[0]
            # must turn => second ON must be perpendicular, not opposite
            candidates = []
            for d2, k2 in inc[r][c]:
                if d2 == d or d2 == OPP[d]:
                    continue
                if edges[k2] != OFF:
                    candidates.append(d2)
            if not candidates:
                contradiction = True
                return
            if len(candidates) == 1:
                set_edge(edge_key(r, c, candidates[0]), ON)
                # and opposite of each ON must be OFF to prevent straight
                if OPP[d] in dirs_present:
                    set_edge(edge_key(r, c, OPP[d]), OFF)
                if OPP[candidates[0]] in dirs_present:
                    set_edge(edge_key(r, c, OPP[candidates[0]]), OFF)
            return
        if len(on_dirs) == 2:
            # must be a turn
            if (on_dirs[0] + 2) % 4 == on_dirs[1]:
                contradiction = True
            return
        if len(on_dirs) == 0:
            # prune turn pairs made impossible by OFF edges
            feasible = []
            for a, b in turn_pairs:
                ka, kb = edge_key(r, c, a), edge_key(r, c, b)
                if edges[ka] != OFF and edges[kb] != OFF:
                    feasible.append((a, b))
            if not feasible:
                contradiction = True
                return
            if len(feasible) == 1:
                a, b = feasible[0]
                set_edge(edge_key(r, c, a), ON)
                set_edge(edge_key(r, c, b), ON)
                # force opposite edges OFF if present
                for d in (a, b):
                    od = OPP[d]
                    if od in dirs_present:
                        set_edge(edge_key(r, c, od), OFF)

    def apply_lookahead_constraints(r, c):
        nonlocal contradiction
        if contradiction:
            return
        clue = data[r][c]
        if clue == "W":
            # At least one adjacent vertex along the straight direction must be a turn.
            # If orientation forced, enforce "turn somewhere" by forbidding both neighbors to be straight in that direction.
            if is_forced_straight(r, c):
                # determine straight axis from ON dirs
                on_dirs = [d for d, k in inc[r][c] if edges[k] == ON]
                a, b = on_dirs
                # travel to neighbors along those dirs
                for d in (a, b):
                    nr, nc = r + DIRS[d][0], c + DIRS[d][1]
                    if in_bounds_dot(nr, nc):
                        pass
                # If both neighbors are already forced straight, contradiction (needs at least one turn).
                neigh = []
                for d in (a, b):
                    nr, nc = r + DIRS[d][0], c + DIRS[d][1]
                    if in_bounds_dot(nr, nc):
                        neigh.append((nr, nc))
                if len(neigh) == 2:
                    if is_forced_straight(neigh[0][0], neigh[0][1]) and is_forced_straight(neigh[1][0], neigh[1][1]):
                        contradiction = True
        elif clue == "B":
            # Both adjacent vertices in the two directions must be straight (in the direction of travel).
            if is_forced_turn(r, c):
                on_dirs = [d for d, k in inc[r][c] if edges[k] == ON]
                d1, d2 = on_dirs
                for d in (d1, d2):
                    nr, nc = r + DIRS[d][0], c + DIRS[d][1]
                    if not in_bounds_dot(nr, nc):
                        contradiction = True
                        return
                    # The neighbor must be straight: it must have the edge back ON and the opposite edge ON.
                    back = OPP[d]
                    if back not in {dd for dd, _ in inc[nr][nc]}:
                        contradiction = True
                        return
                    # force opposite to back ON (i.e., continue straight through neighbor)
                    cont = OPP[back]  # equals d
                    # At neighbor, straight means edges in (back, cont) ON; cont edge from neighbor is same direction d
                    set_edge(edge_key(nr, nc, cont), ON)
                    set_edge(edge_key(nr, nc, back), ON)
                    # and perpendicular edges OFF where present if degree would exceed 2; degree rules will handle after.
                    if contradiction:
                        return

    def propagate():
        nonlocal contradiction
        while q and not contradiction:
            typ, r, c = q.popleft()
            if typ == "dot":
                force_degree_rules(r, c)
            else:
                # clue application
                apply_white(r, c)
                apply_black(r, c)
                apply_lookahead_constraints(r, c)

    # Seed queue with all dots/clues
    for r in range(N):
        for c in range(N):
            q.append(("dot", r, c))
            if data[r][c] is not None:
                q.append(("clue", r, c))
    propagate()
    if contradiction:
        return "No Solution"

    # Backtracking with heuristic: choose most constrained edge
    edge_list = list(edges.keys())

    def snapshot():
        return (
            edges.copy(),
            [row[:] for row in deg_on],
            [row[:] for row in deg_off],
            parent.copy(),
            comp_size.copy(),
            comp_has_cycle.copy(),
            deque(q),
            contradiction,
        )

    def restore(snap):
        nonlocal contradiction, q
        (e, don, doff, par, csz, cyc, qq, contra) = snap
        edges.clear()
        edges.update(e)
        for r in range(N):
            deg_on[r][:] = don[r]
            deg_off[r][:] = doff[r]
        parent.clear()
        parent.update(par)
        comp_size.clear()
        comp_size.update(csz)
        comp_has_cycle.clear()
        comp_has_cycle.update(cyc)
        q = deque(qq)
        contradiction = contra

    def all_assigned():
        return all(v != UNK for v in edges.values())

    def check_final_single_cycle():
        # all vertices have deg 0 or 2; all clues satisfied already by propagation
        # ensure single cycle using ON edges: exactly one connected component with ON edges and all used vertices in it.
        used = []
        for r in range(N):
            for c in range(N):
                if deg_on[r][c] == 1:
                    return False
                if deg_on[r][c] == 2:
                    used.append(vid(r, c))
                elif deg_on[r][c] != 0:
                    return False
        if not used:
            return False
        root = find(used[0])
        for v in used[1:]:
            if find(v) != root:
                return False
        # verify it's a cycle: in a connected graph where all degrees are 2, it's a single cycle.
        return True

    def choose_edge():
        best = None
        best_score = 10**9
        for k, st in edges.items():
            if st != UNK:
                continue
            (a, b) = edge_endpoints(k)
            ra, ca = a
            rb, cb = b
            # score: how tight endpoints are (less slack)
            slack_a = 2 - deg_on[ra][ca]
            slack_b = 2 - deg_on[rb][cb]
            # prioritize if either endpoint already has 2 OFF edges remaining etc.
            score = (slack_a + slack_b)
            if score < best_score:
                best_score = score
                best = k
                if score == 0:
                    break
        return best

    def dfs():
        nonlocal contradiction
        if contradiction:
            return False
        if all_assigned():
            return check_final_single_cycle()
        k = choose_edge()
        if k is None:
            return False
        # try ON first if it doesn't immediately exceed degrees
        for val in (ON, OFF):
            snap = snapshot()
            set_edge(k, val)
            propagate()
            if not contradiction:
                # additional pruning: if any clue dot currently has deg_on==0 and all incident edges OFF => impossible for W/B
                ok = True
                for r in range(N):
                    for c in range(N):
                        if data[r][c] is None:
                            continue
                        if deg_on[r][c] == 0:
                            # if all incident are OFF then clue can't be satisfied
                            if deg_off[r][c] == deg_total[r][c]:
                                ok = False
                                break
                    if not ok:
                        break
                if ok and dfs():
                    return True
            restore(snap)
        return False

    if not dfs():
        return "No Solution"

    # Extract cycle path in order
    # Find any used vertex
    start = None
    for r in range(N):
        for c in range(N):
            if deg_on[r][c] == 2:
                start = (r, c)
                break
        if start:
            break
    if not start:
        return "No Solution"

    # Build adjacency from ON edges
    adj = [[[] for _ in range(N)] for __ in range(N)]
    for k, st in edges.items():
        if st != ON:
            continue
        (a, b) = edge_endpoints(k)
        ra, ca = a
        rb, cb = b
        adj[ra][ca].append((rb, cb))
        adj[rb][cb].append((ra, ca))

    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = adj[cur[0]][cur[1]]
        if len(nbrs) != 2:
            return "No Solution"
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        prev, cur = cur, nxt
        path.append(cur)
        if cur == start:
            break
        if len(path) > N * N * 4 + 5:
            return "No Solution"
    return str(path)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, 'W', None, None, 'W', None, 'W', None], [None, None, None, None, None, 'W', 'W', None], [None, None, 'W', None, None, None, 'W', None], [None, None, None, None, None, 'B', None, 'W'], [None, None, 'W', 'W', None, None, None, None], [None, 'W', None, None, None, None, None, None], [None, None, None, None, 'W', None, None, None]]}
from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from typing import List, Tuple, Optional, Dict

# Masyu solver on an (N x N) dot grid with circles centered in cells of an (N-1 x N-1) cell grid.
# Input observation['data'] is N x N with None/'W'/'B' on dot intersections in the provided prompt.
# We interpret given circles as being on grid points (dots) as per prompt statement "clue circles" on dots.
# Therefore constraints apply to vertices (dots), and the loop uses orthogonal edges between adjacent dots.


Coord = Tuple[int, int]
Edge = Tuple[Coord, Coord]


def solve(observation):
    data = observation["data"]
    N = len(data)
    if any(len(row) != N for row in data):
        return "No Solution"

    # Edge states between adjacent dots: 0 unknown, 1 present, -1 absent
    # Horizontal edges: (r,c)-(r,c+1) for c in [0..N-2]
    # Vertical edges: (r,c)-(r+1,c) for r in [0..N-2]
    H = [[0] * (N - 1) for _ in range(N)]
    V = [[0] * N for _ in range(N - 1)]

    def inb(r, c):
        return 0 <= r < N and 0 <= c < N

    def neighbors(r, c):
        # Returns list of (nr,nc, kind, idx) where kind 'H'/'V' and idx indexes into arrays
        out = []
        if c > 0:
            out.append((r, c - 1, 'H', (r, c - 1)))  # edge (r,c-1)-(r,c) is H[r][c-1]
        if c < N - 1:
            out.append((r, c + 1, 'H', (r, c)))      # edge (r,c)-(r,c+1) is H[r][c]
        if r > 0:
            out.append((r - 1, c, 'V', (r - 1, c)))  # edge (r-1,c)-(r,c) is V[r-1][c]
        if r < N - 1:
            out.append((r + 1, c, 'V', (r, c)))      # edge (r,c)-(r+1,c) is V[r][c]
        return out

    def get_edge(kind, idx):
        r, c = idx
        return H[r][c] if kind == 'H' else V[r][c]

    def set_edge(kind, idx, val, trail):
        r, c = idx
        arr = H if kind == 'H' else V
        cur = arr[r][c]
        if cur == val:
            return True
        if cur != 0 and cur != val:
            return False
        trail.append((kind, r, c, cur))
        arr[r][c] = val
        return True

    def edge_between(a: Coord, b: Coord):
        (r1, c1), (r2, c2) = a, b
        if r1 == r2 and abs(c1 - c2) == 1:
            r = r1
            c = min(c1, c2)
            return ('H', (r, c))
        if c1 == c2 and abs(r1 - r2) == 1:
            r = min(r1, r2)
            c = c1
            return ('V', (r, c))
        return None

    def deg(r, c):
        d = 0
        for nr, nc, kind, idx in neighbors(r, c):
            if get_edge(kind, idx) == 1:
                d += 1
        return d

    def unk_edges(r, c):
        u = []
        for nr, nc, kind, idx in neighbors(r, c):
            if get_edge(kind, idx) == 0:
                u.append((kind, idx, (nr, nc)))
        return u

    def incident_edges(r, c):
        out = []
        for nr, nc, kind, idx in neighbors(r, c):
            out.append((kind, idx, (nr, nc), get_edge(kind, idx)))
        return out

    def other_dir(a: Coord, b: Coord):
        # a->b direction as (dr,dc)
        return (b[0] - a[0], b[1] - a[1])

    def is_turn_at_vertex(r, c):
        # If degree==2 and edges are perpendicular => turn
        inc = [(kind, idx, nb) for kind, idx, nb, st in incident_edges(r, c) if st == 1]
        if len(inc) != 2:
            return False
        (k1, i1, n1), (k2, i2, n2) = inc
        # straight if both horizontal or both vertical
        return not (k1 == k2)

    def is_straight_at_vertex(r, c):
        inc = [(kind, idx, nb) for kind, idx, nb, st in incident_edges(r, c) if st == 1]
        if len(inc) != 2:
            return False
        (k1, i1, n1), (k2, i2, n2) = inc
        return (k1 == k2)

    def enforce_vertex_degree_rules(r, c, trail):
        # Standard loop rules: degree must be 0 or 2; we aggressively enforce when possible.
        d = deg(r, c)
        unks = unk_edges(r, c)
        if d > 2:
            return False
        if d == 2:
            # all other incident edges must be absent
            for kind, idx, nb in unks:
                if not set_edge(kind, idx, -1, trail):
                    return False
        # if d==1, need one more present among unknowns (at least one unknown must remain or already impossible)
        if d == 1 and len(unks) == 0:
            return False
        # if d==0, nothing
        # if d + len(unks) < 2 and clue requires passing through, will be handled by clue constraints
        return True

    def enforce_clue_local(r, c, trail):
        clue = data[r][c]
        if clue is None:
            return True

        # The loop must pass through all clue circles => degree exactly 2
        d = deg(r, c)
        unks = unk_edges(r, c)
        if d > 2:
            return False
        if d + len(unks) < 2:
            return False
        if d == 2:
            # degree fixed
            pass
        elif d == 1:
            # need exactly one more present among unknowns => cannot set here without branching unless only one unknown
            if len(unks) == 1:
                kind, idx, nb = unks[0]
                if not set_edge(kind, idx, 1, trail):
                    return False
        elif d == 0:
            if len(unks) == 2:
                # only two possible edges, must take both
                for kind, idx, nb in unks:
                    if not set_edge(kind, idx, 1, trail):
                        return False

        # After any implied additions, re-evaluate fixed pattern constraints when degree==2
        d = deg(r, c)
        if d == 2:
            inc = [(kind, idx, nb) for kind, idx, nb, st in incident_edges(r, c) if st == 1]
            if clue == 'B':
                # must turn here (per prompt)
                if len(inc) != 2:
                    return False
                (k1, i1, n1), (k2, i2, n2) = inc
                if k1 == k2:
                    return False
                # previous and next steps straight: at adjacent vertices, the edge must be part of straight segment through them
                # For each neighbor along used edge, that neighbor must be straight (if/when degree becomes 2); we can enforce:
                for kind, idx, nb in inc:
                    nr, nc = nb
                    # At neighbor, the continuation must be straight, meaning: if edge is horizontal, neighbor must have other horizontal edge present (not vertical).
                    # If neighbor already has degree 2, verify; else force impossibilities by forbidding perpendicular completion when it would close.
                    # We'll implement as:
                    # - Forbid the perpendicular edge at neighbor from being the only remaining possible to reach degree 2.
                    # - Stronger: if neighbor has one incident present (this edge), then when it needs one more, it must be the collinear edge.
                    ndeg = deg(nr, nc)
                    nunk = unk_edges(nr, nc)
                    # Determine required collinear edge idx at neighbor
                    if kind == 'H':
                        # edge is horizontal; other required horizontal edge at neighbor is left or right depending
                        # identify possible: (nr,nc-1)-(nr,nc) or (nr,nc)-(nr,nc+1) excluding current
                        required = []
                        if nc > 0:
                            e = ('H', (nr, nc - 1))
                            # Check if this edge is current:
                            if e != (kind, idx):
                                required.append(e)
                        if nc < N - 1:
                            e = ('H', (nr, nc))
                            if e != (kind, idx):
                                required.append(e)
                        # required should have exactly 1 element unless at boundary where it can be 0 (then impossible for straight-through)
                        if len(required) != 1:
                            return False
                        rk, ridx = required[0]
                        # Also, both vertical edges at neighbor must be absent if neighbor degree forced to 2 and one edge is horizontal.
                        if ndeg == 1:
                            # if only one unknown available besides current, force it
                            # If neighbor has already one edge present (current), it must take ridx as the second when it eventually uses degree 2.
                            # Since loop degree at vertices is 0 or 2, if neighbor is on loop it must be 2; we don't yet know.
                            # But black constraint requires straight through neighbor along this direction, meaning neighbor must be on loop.
                            # Hence enforce degree==2 at neighbor by setting required edge present, and perpendicular absent.
                            if not set_edge(rk, ridx, 1, trail):
                                return False
                            # set verticals absent
                            if nr > 0:
                                if not set_edge('V', (nr - 1, nc), -1, trail):
                                    return False
                            if nr < N - 1:
                                if not set_edge('V', (nr, nc), -1, trail):
                                    return False
                        elif ndeg == 2:
                            # must be straight
                            if not is_straight_at_vertex(nr, nc):
                                return False
                        else:
                            # ndeg==0: black's straight requirement implies neighbor will have two horizontal edges if possible; we can only partially enforce:
                            # if either vertical edge is already present -> impossible
                            for vk in (('V', (nr - 1, nc)) if nr > 0 else None, ('V', (nr, nc)) if nr < N - 1 else None):
                                if vk is not None and get_edge(vk[0], vk[1]) == 1:
                                    return False
                    else:
                        # kind == 'V' so require vertical straight at neighbor
                        required = []
                        if nr > 0:
                            e = ('V', (nr - 1, nc))
                            if e != (kind, idx):
                                required.append(e)
                        if nr < N - 1:
                            e = ('V', (nr, nc))
                            if e != (kind, idx):
                                required.append(e)
                        if len(required) != 1:
                            return False
                        rk, ridx = required[0]
                        if ndeg == 1:
                            if not set_edge(rk, ridx, 1, trail):
                                return False
                            # set horizontals absent
                            if nc > 0:
                                if not set_edge('H', (nr, nc - 1), -1, trail):
                                    return False
                            if nc < N - 1:
                                if not set_edge('H', (nr, nc), -1, trail):
                                    return False
                        elif ndeg == 2:
                            if not is_straight_at_vertex(nr, nc):
                                return False
                        else:
                            for hk in (('H', (nr, nc - 1)) if nc > 0 else None, ('H', (nr, nc)) if nc < N - 1 else None):
                                if hk is not None and get_edge(hk[0], hk[1]) == 1:
                                    return False

            elif clue == 'W':
                # must go straight here
                if not is_straight_at_vertex(r, c):
                    return False
                # must turn at least once in previous or next step => at least one adjacent vertex (along the straight line) must be a turn.
                # If both adjacent vertices already straight, contradiction. If one fixed straight, force other to be turn when possible.
                inc = [(kind, idx, nb) for kind, idx, nb, st in incident_edges(r, c) if st == 1]
                k = inc[0][0]  # same for both
                a = inc[0][2]
                b = inc[1][2]
                # For each endpoint vertex, we can sometimes force "turn" by forbidding straight-through completion.
                def endpoint_turn_status(v):
                    vr, vc = v
                    if deg(vr, vc) == 2:
                        return is_turn_at_vertex(vr, vc), is_straight_at_vertex(vr, vc)
                    return None, None

                tA, sA = endpoint_turn_status(a)
                tB, sB = endpoint_turn_status(b)
                if sA is True and sB is True:
                    return False
                # If one endpoint is confirmed straight, the other must be able to be turn; if other is forced straight later, will fail.
                # We can enforce some local pruning: if an endpoint currently has the connecting edge present and has degree 1,
                # then to be a turn its second edge must be perpendicular (not collinear). We can force that if needed.
                def force_turn_at_endpoint(v, along_kind):
                    vr, vc = v
                    # along_kind is 'H' if line is horizontal through the white circle, so collinear edges are horizontal at endpoint.
                    # To force a turn: the second edge (besides the connecting edge) must be perpendicular.
                    if deg(vr, vc) != 1:
                        return True
                    unks = unk_edges(vr, vc)
                    if not unks:
                        return False
                    # Determine collinear candidates at endpoint
                    col = set()
                    if along_kind == 'H':
                        if vc > 0:
                            col.add(('H', (vr, vc - 1)))
                        if vc < N - 1:
                            col.add(('H', (vr, vc)))
                    else:
                        if vr > 0:
                            col.add(('V', (vr - 1, vc)))
                        if vr < N - 1:
                            col.add(('V', (vr, vc)))
                    # The connecting edge is one of collinear in many cases; for turn we need the other edge to be perpendicular.
                    # So forbid any remaining collinear unknown edge (besides possibly the already-present one which isn't unknown).
                    for kind2, idx2, nb2 in unks:
                        if (kind2, idx2) in col:
                            if not set_edge(kind2, idx2, -1, trail):
                                return False
                    # Then degree rule will force a perpendicular edge if available.
                    return True

                # If A is straight confirmed, force B to be turn (when possible), and vice versa.
                if sA is True and tB is None:
                    if not force_turn_at_endpoint(b, k):
                        return False
                if sB is True and tA is None:
                    if not force_turn_at_endpoint(a, k):
                        return False

        return True

    def enforce_all(trail):
        # Worklist of vertices to process
        q = deque()
        inq = [[False] * N for _ in range(N)]
        def push(r, c):
            if not inq[r][c]:
                inq[r][c] = True
                q.append((r, c))
        for r in range(N):
            for c in range(N):
                push(r, c)

        while q:
            r, c = q.popleft()
            inq[r][c] = False
            if not enforce_vertex_degree_rules(r, c, trail):
                return False
            if not enforce_clue_local(r, c, trail):
                return False
            # If something changed around, we will push neighbors when applying changes in set_edge via trail;
            # here we conservatively push neighbors each time we visit (cheap for N<=~20 typical).
            for nr, nc, *_ in neighbors(r, c):
                push(nr, nc)
        return True

    def undo(trail):
        while trail:
            kind, r, c, prev = trail.pop()
            if kind == 'H':
                H[r][c] = prev
            else:
                V[r][c] = prev

    def any_contradiction_fast():
        # Quick degree upper bounds
        for r in range(N):
            for c in range(N):
                d = deg(r, c)
                if d > 2:
                    return True
                # If d==1 and no unknowns -> dead unless vertex not required and could be 0/2, but degree 1 is never allowed in final.
                # We allow intermediate degree 1, so no contradiction here unless isolated with no unknown.
                if d == 1 and len(unk_edges(r, c)) == 0:
                    return True
                clue = data[r][c]
                if clue is not None:
                    # must be degree 2 eventually
                    if d + len(unk_edges(r, c)) < 2:
                        return True
        return False

    def all_edges_iter():
        for r in range(N):
            for c in range(N - 1):
                yield ('H', (r, c))
        for r in range(N - 1):
            for c in range(N):
                yield ('V', (r, c))

    def count_unknown_edges():
        s = 0
        for kind, idx in all_edges_iter():
            if get_edge(kind, idx) == 0:
                s += 1
        return s

    def build_components():
        # Union-find on vertices using present edges.
        parent = list(range(N * N))
        rank = [0] * (N * N)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        def vid(r, c):
            return r * N + c

        # union for each present edge
        for r in range(N):
            for c in range(N - 1):
                if H[r][c] == 1:
                    union(vid(r, c), vid(r, c + 1))
        for r in range(N - 1):
            for c in range(N):
                if V[r][c] == 1:
                    union(vid(r, c), vid(r + 1, c))

        # Collect degrees and vertices used
        used = []
        for r in range(N):
            for c in range(N):
                if deg(r, c) > 0:
                    used.append((r, c, find(vid(r, c))))
        return parent, used

    def premature_cycle_check():
        # Forbid forming a closed cycle unless all clues are satisfied and all used vertices have degree 2 and are single component.
        # Detect if any component is a cycle already with no open ends (all vertices in component have deg=2) while unknown edges remain that could connect clues outside.
        parent, used = build_components()
        if not used:
            return False
        # map root -> vertices and count of degree!=2 and open ends
        comp = {}
        for r, c, root in used:
            comp.setdefault(root, []).append((r, c))
        # if there is a component where all vertices deg==2 AND not all clue vertices are included OR there are other used vertices elsewhere
        # then it's a premature closed loop.
        clue_vertices = [(r, c) for r in range(N) for c in range(N) if data[r][c] is not None]
        for root, verts in comp.items():
            if all(deg(r, c) == 2 for r, c in verts):
                # closed cycle (could still be open if component has small? but deg==2 implies closed)
                # check if all used vertices belong to this component and all clue vertices have deg==2 in it
                if len(comp) > 1:
                    return True
                # ensure all clue vertices have degree 2 (thus included)
                for r, c in clue_vertices:
                    if deg(r, c) != 2:
                        return True
                # also ensure no unknown edges could create branches? not needed
        return False

    def choose_branch_edge():
        # Heuristic: pick edge adjacent to a constrained clue/vertex with degree needs.
        best = None
        best_score = -10**9
        for kind, idx in all_edges_iter():
            if get_edge(kind, idx) != 0:
                continue
            r, c = idx
            if kind == 'H':
                a = (r, c)
                b = (r, c + 1)
            else:
                a = (r, c)
                b = (r + 1, c)
            score = 0
            for vr, vc in (a, b):
                clue = data[vr][vc]
                d = deg(vr, vc)
                u = len(unk_edges(vr, vc))
                if clue is not None:
                    score += 50
                    score += (2 - d) * 10
                # prefer vertices with d==1 (forced soon)
                if d == 1:
                    score += 15
                if d == 2:
                    score -= 5
                score += max(0, 2 - (d + u)) * 100  # near contradiction (should be handled elsewhere)
            # slight preference for edges that could complete forced degree-2 at clues
            if score > best_score:
                best_score = score
                best = (kind, idx)
        return best

    def is_solved():
        # All vertices have degree 0 or 2, all clue vertices degree 2, and exactly one cycle.
        # Also must be a single closed loop: all used vertices in one component.
        used = []
        for r in range(N):
            for c in range(N):
                d = deg(r, c)
                if d not in (0, 2):
                    return False
                if data[r][c] is not None and d != 2:
                    return False
                if d == 2:
                    used.append((r, c))
        if not used:
            return False
        # connectivity
        _, used_with_root = build_components()
        roots = {root for _, _, root in used_with_root}
        if len(roots) != 1:
            return False
        # ensure it's a single cycle (degree 2 everywhere used implies cycles; connectivity makes it one cycle)
        return True

    def extract_loop():
        # Build adjacency from present edges and follow cycle.
        adj: Dict[Coord, List[Coord]] = {}
        for r in range(N):
            for c in range(N - 1):
                if H[r][c] == 1:
                    a, b = (r, c), (r, c + 1)
                    adj.setdefault(a, []).append(b)
                    adj.setdefault(b, []).append(a)
        for r in range(N - 1):
            for c in range(N):
                if V[r][c] == 1:
                    a, b = (r, c), (r + 1, c)
                    adj.setdefault(a, []).append(b)
                    adj.setdefault(b, []).append(a)
        # pick start
        start = next(iter(adj))
        path = [start]
        prev = None
        cur = start
        while True:
            ns = adj[cur]
            nxt = ns[0] if ns[0] != prev else ns[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > N * N * 4 + 5:
                break
        return path

    def dfs():
        if any_contradiction_fast():
            return None
        trail = []
        if not enforce_all(trail):
            undo(trail)
            return None
        if premature_cycle_check():
            undo(trail)
            return None
        if is_solved():
            loop = extract_loop()
            undo(trail)
            return loop

        br = choose_branch_edge()
        if br is None:
            undo(trail)
            return None
        kind, idx = br

        # Try present first then absent; present tends to satisfy clue degree requirements.
        for val in (1, -1):
            t2 = []
            if set_edge(kind, idx, val, t2):
                res = dfs()
                if res is not None:
                    # keep current trail undone already; but we must undo both.
                    undo(t2)
                    undo(trail)
                    return res
            undo(t2)

        undo(trail)
        return None

    res = dfs()
    if res is None:
        return "No Solution"
    return str(res)


