OBSERVATION = {'data': [[None, 4, None, None, 1], [None, None, 8, None, None], [None, 6, 9, None, 5], [None, None, 6, None, None], [1, None, None, None, 3]]}

from collections import deque

# Solver for "3x3 neighborhood black count" puzzles (Minesweeper-like with radius 1)
# Cell domain: -1 unknown, 0 white, 1 black
# For each clue at (r,c) with value k: sum of blacks in its 3x3 neighborhood == k

def solve(observation):
    grid = observation["data"]
    R = len(grid)
    C = len(grid[0]) if R else 0

    # Precompute neighborhoods for each clue and reverse mapping (cell -> constraints)
    clues = []
    clue_id = {}
    neigh = []  # list of list of cell indices
    cells_of = [[] for _ in range(R * C)]  # constraints involving each cell

    def idx(r, c): return r * C + c
    def rc(i): return divmod(i, C)

    for r in range(R):
        for c in range(C):
            v = grid[r][c]
            if v is not None:
                clue_id[(r, c)] = len(clues)
                clues.append((r, c, int(v)))

    for (r, c, k) in clues:
        n = []
        for rr in range(max(0, r - 1), min(R, r + 2)):
            for cc in range(max(0, c - 1), min(C, c + 2)):
                n.append(idx(rr, cc))
        neigh.append(n)
        cid = clue_id[(r, c)]
        for i in n:
            cells_of[i].append(cid)

    # State
    val = [-1] * (R * C)

    # For each constraint, maintain: assigned_black, assigned_count, unknown_count, target
    target = [k for (_, _, k) in clues]
    assigned_black = [0] * len(clues)
    assigned_count = [0] * len(clues)
    unknown_count = [len(neigh[cid]) for cid in range(len(clues))]

    # Queue for propagation
    q = deque()
    inq = [False] * len(clues)

    def enqueue(cid):
        if not inq[cid]:
            inq[cid] = True
            q.append(cid)

    # Initialize queue with all constraints
    for cid in range(len(clues)):
        enqueue(cid)

    # Assignment stack for backtracking
    trail = []
    # Each trail record: ("cell", i, old_val) or ("cons", cid, ab_old, ac_old, uc_old) or ("mark",)
    def push_mark():
        trail.append(("mark",))

    def undo():
        while trail:
            rec = trail.pop()
            if rec[0] == "mark":
                break
            if rec[0] == "cell":
                _, i, oldv = rec
                val[i] = oldv
            else:
                _, cid, ab, ac, uc = rec
                assigned_black[cid] = ab
                assigned_count[cid] = ac
                unknown_count[cid] = uc

    def apply_cell(i, v):
        """Assign cell i to v (0/1). Returns False if contradiction."""
        if val[i] != -1:
            return val[i] == v
        # record cell change
        trail.append(("cell", i, -1))
        val[i] = v
        # Update all involved constraints
        for cid in cells_of[i]:
            trail.append(("cons", cid, assigned_black[cid], assigned_count[cid], unknown_count[cid]))
            assigned_count[cid] += 1
            unknown_count[cid] -= 1
            if v == 1:
                assigned_black[cid] += 1
            enqueue(cid)
        return True

    def constraint_check(cid):
        """Basic range pruning and forced assignments for a single constraint."""
        k = target[cid]
        ab = assigned_black[cid]
        uc = unknown_count[cid]
        # Range check
        if ab > k:
            return False
        if ab + uc < k:
            return False

        # Forced: if need all unknown to be black
        if uc > 0:
            need = k - ab
            if need == 0:
                # all remaining are white
                for i in neigh[cid]:
                    if val[i] == -1:
                        if not apply_cell(i, 0):
                            return False
            elif need == uc:
                # all remaining are black
                for i in neigh[cid]:
                    if val[i] == -1:
                        if not apply_cell(i, 1):
                            return False
        return True

    def propagate():
        """Run propagation until fixpoint; returns False if contradiction."""
        while q:
            cid = q.popleft()
            inq[cid] = False
            if not constraint_check(cid):
                return False
        return True

    def choose_var():
        """Heuristic: pick an unassigned cell that appears in the tightest constraints."""
        best = None
        best_score = None
        for i in range(R * C):
            if val[i] != -1:
                continue
            # score: min remaining slack over constraints containing i
            # lower slack => more constrained
            score = (10**9, 10**9, -1)  # (min_slack, min_uc, degree)
            deg = len(cells_of[i])
            min_slack = 10**9
            min_uc = 10**9
            for cid in cells_of[i]:
                k = target[cid]
                ab = assigned_black[cid]
                uc = unknown_count[cid]
                slack_low = k - ab  # blacks still needed
                slack_high = (ab + uc) - k  # extra blacks possible
                # closer to 0 means tighter; we use min of both sides
                tight = min(slack_low, slack_high)
                if tight < min_slack:
                    min_slack = tight
                if uc < min_uc:
                    min_uc = uc
            score = (min_slack, min_uc, -deg)
            if best is None or score < best_score:
                best = i
                best_score = score
        return best

    def is_solved():
        # all constraints satisfied and all cells assigned not necessary, but check constraints
        for cid in range(len(clues)):
            if unknown_count[cid] != 0:
                return False
            if assigned_black[cid] != target[cid]:
                return False
        return True

    # Initial propagation
    push_mark()
    if not propagate():
        return "No Solution"
    trail.pop()  # remove mark to keep trail clean at root

    # Advanced technique: constraint intersection forcing (subset reasoning)
    # For two constraints A and B: let IA = unknown cells in A, IB in B
    # From sums: blacks_in(IA) in [needA, needA+...], similarly.
    # We can deduce bounds on overlap and differences.
    # Implement lightweight pass occasionally to avoid O(m^2) always.
    clue_cells = [set(n) for n in neigh]

    def subset_reasoning():
        # Build current unknown sets per clue
        unknown_sets = []
        need = []
        for cid in range(len(clues)):
            if unknown_count[cid] == 0:
                unknown_sets.append(None)
                need.append(0)
                continue
            us = set(i for i in neigh[cid] if val[i] == -1)
            unknown_sets.append(us)
            need.append(target[cid] - assigned_black[cid])
        # Compare only potentially related constraints: share at least one cell.
        # Build adjacency via cells_of.
        affected_pairs = set()
        for i in range(R * C):
            if val[i] == -1 and len(cells_of[i]) > 1:
                cids = cells_of[i]
                for a in range(len(cids)):
                    for b in range(a + 1, len(cids)):
                        x, y = cids[a], cids[b]
                        if x > y:
                            x, y = y, x
                        affected_pairs.add((x, y))

        for a, b in affected_pairs:
            Ua = unknown_sets[a]
            Ub = unknown_sets[b]
            if not Ua or not Ub:
                continue
            na = need[a]
            nb = need[b]
            # If Ua subset Ub then we can bound blacks in (Ub\Ua)
            if Ua.issubset(Ub):
                diff = Ub - Ua
                if not diff:
                    # then needs must match
                    if na != nb:
                        return False
                else:
                    # blacks in diff = nb - blacks_in_Ua, but blacks_in_Ua in [na_min, na_max]
                    # Here exact for Ua: sum over Ua equals na (since it's the remaining needed in that clue)
                    # Actually clue a: blacks in Ua must equal na, because other cells fixed; yes.
                    # So blacks in diff must equal nb - na within bounds [0, |diff|]
                    req = nb - na
                    if req < 0 or req > len(diff):
                        return False
                    if req == 0:
                        for i in diff:
                            if val[i] == -1 and not apply_cell(i, 0):
                                return False
                    elif req == len(diff):
                        for i in diff:
                            if val[i] == -1 and not apply_cell(i, 1):
                                return False
            # symmetric
            if Ub.issubset(Ua):
                diff = Ua - Ub
                if not diff:
                    if nb != na:
                        return False
                else:
                    req = na - nb
                    if req < 0 or req > len(diff):
                        return False
                    if req == 0:
                        for i in diff:
                            if val[i] == -1 and not apply_cell(i, 0):
                                return False
                    elif req == len(diff):
                        for i in diff:
                            if val[i] == -1 and not apply_cell(i, 1):
                                return False
        return True

    def search():
        # Run propagation and subset reasoning to a fixpoint
        while True:
            push_mark()
            ok = propagate()
            if ok:
                ok = subset_reasoning()
            if ok:
                ok = propagate()
            if not ok:
                undo()
                return False
            # if no new info since mark, break
            # detect by checking whether mark is at end (no changes after mark)
            changed = (trail and trail[-1][0] != "mark")
            undo()  # revert mark only; keep changes? We reverted everything, so we can't do that.
            # To avoid complex diffing, we instead apply in-place without undo by not using mark here.
            break

        # Re-apply reasoning without mark/undo (actual)
        if not propagate():
            return False
        if not subset_reasoning():
            return False
        if not propagate():
            return False

        if is_solved():
            return True

        i = choose_var()
        if i is None:
            return False

        # Branching order: try value that seems more plausible by local needs
        # Compute preference: sum needs over constraints containing i; higher need -> black
        s_need = 0
        s_uc = 0
        for cid in cells_of[i]:
            s_need += (target[cid] - assigned_black[cid])
            s_uc += unknown_count[cid]
        prefer_black = (s_need * 2 >= s_uc)  # rough

        for v in ([1, 0] if prefer_black else [0, 1]):
            push_mark()
            if apply_cell(i, v) and propagate() and subset_reasoning() and propagate() and search():
                return True
            undo()
        return False

    # Replace the earlier fixpoint attempt with a clean recursive approach
    def dfs():
        if not propagate():
            return False
        if not subset_reasoning():
            return False
        if not propagate():
            return False
        if is_solved():
            return True
        i = choose_var()
        if i is None:
            return False
        s_need = 0
        s_uc = 0
        for cid in cells_of[i]:
            s_need += (target[cid] - assigned_black[cid])
            s_uc += unknown_count[cid]
        prefer_black = (s_need * 2 >= s_uc)
        for v in ([1, 0] if prefer_black else [0, 1]):
            push_mark()
            if apply_cell(i, v) and dfs():
                return True
            undo()
        return False

    if not dfs():
        return "No Solution"

    # Build output grid: 'B' for black, None for white
    out = []
    for r in range(R):
        row = []
        for c in range(C):
            v = val[idx(r, c)]
            row.append('B' if v == 1 else None)
        out.append(row)
    return str(out)


