from collections import deque

# Solver for: Each numbered cell equals the count of black cells in its 3x3 neighborhood (including itself).
# Output: grid of 'B' for black and None for white.

UNKNOWN = -1
WHITE = 0
BLACK = 1

def solve(observation):
    grid = observation["data"]
    R = len(grid)
    C = len(grid[0]) if R else 0

    # Precompute neighborhoods
    neigh = [[] for _ in range(R * C)]
    num_cells = []
    for r in range(R):
        for c in range(C):
            idx = r * C + c
            for rr in range(max(0, r - 1), min(R, r + 2)):
                base = rr * C
                for cc in range(max(0, c - 1), min(C, c + 2)):
                    neigh[idx].append(base + cc)
            if grid[r][c] is not None:
                num_cells.append(idx)

    # For each variable cell, list of constraints (numbered cells) it affects.
    affects = [[] for _ in range(R * C)]
    for nidx in num_cells:
        for vidx in neigh[nidx]:
            affects[vidx].append(nidx)

    # State arrays
    state = [UNKNOWN] * (R * C)

    # Constraint bookkeeping for numbered cells
    # need[nidx] = target count
    # black_ct[nidx] = assigned black in neighborhood
    # unk_ct[nidx] = unassigned in neighborhood
    need = {}
    black_ct = {}
    unk_ct = {}

    for nidx in num_cells:
        r, c = divmod(nidx, C)
        t = grid[r][c]
        need[nidx] = t
        b = 0
        u = 0
        for vidx in neigh[nidx]:
            if state[vidx] == BLACK:
                b += 1
            elif state[vidx] == UNKNOWN:
                u += 1
        black_ct[nidx] = b
        unk_ct[nidx] = u

    # Fast contradiction check for a constraint
    def constraint_ok(nidx):
        b = black_ct[nidx]
        u = unk_ct[nidx]
        t = need[nidx]
        # b <= t <= b+u
        return (b <= t) and (t <= b + u)

    # Queue-based propagation with forced moves:
    # If in a numbered cell's neighborhood:
    # - if b == t => all unknowns must be WHITE
    # - if b + u == t => all unknowns must be BLACK
    def propagate(assignments_stack):
        q = deque(num_cells)  # start with all constraints; cheap for small boards
        inq = [False] * (R * C)
        for nidx in num_cells:
            inq[nidx] = True

        while q:
            nidx = q.popleft()
            inq[nidx] = False

            if not constraint_ok(nidx):
                return False

            b = black_ct[nidx]
            u = unk_ct[nidx]
            t = need[nidx]
            if u == 0:
                continue

            # Determine forced value for all unknowns in this neighborhood if any.
            force_val = None
            if b == t:
                force_val = WHITE
            elif b + u == t:
                force_val = BLACK

            if force_val is None:
                continue

            # Assign all unknown vars in neighborhood
            for vidx in neigh[nidx]:
                if state[vidx] == UNKNOWN:
                    if not assign(vidx, force_val, assignments_stack, q, inq):
                        return False
        return True

    # Assign a variable, update affected constraints counts, enqueue affected constraints.
    def assign(vidx, val, assignments_stack, q, inq):
        cur = state[vidx]
        if cur != UNKNOWN:
            return cur == val
        state[vidx] = val
        assignments_stack.append(vidx)

        # Update all constraints affected by this variable
        for nidx in affects[vidx]:
            unk_ct[nidx] -= 1
            if val == BLACK:
                black_ct[nidx] += 1
            if not constraint_ok(nidx):
                return False
            if not inq[nidx]:
                q.append(nidx)
                inq[nidx] = True
        return True

    # Heuristics: choose variable with strongest implications.
    # Score by sum of "tightness" across affected constraints: min(slack_low, slack_high)
    def pick_var():
        best = -1
        best_score = None

        for vidx in range(R * C):
            if state[vidx] != UNKNOWN:
                continue
            # If variable is irrelevant to any constraint, we can leave it WHITE (canonical) without branching.
            if not affects[vidx]:
                return vidx, "irrelevant"

            score = 0
            # Prefer variables in many tight constraints
            for nidx in affects[vidx]:
                b = black_ct[nidx]
                u = unk_ct[nidx]
                t = need[nidx]
                # slack if set to WHITE or BLACK impacts feasibility.
                # Use current interval width and proximity to bounds.
                lo = t - b
                hi = (b + u) - t
                tight = min(lo, hi)
                score += (10 - tight)  # tighter => larger
            if best_score is None or score > best_score:
                best_score = score
                best = vidx
        return best, None

    # Canonicalize output: assign all unconstrained cells to WHITE at the end.
    def finalize():
        for vidx in range(R * C):
            if state[vidx] == UNKNOWN:
                state[vidx] = WHITE

    # Initial feasibility: quick bound checks
    for nidx in num_cells:
        if not constraint_ok(nidx):
            return "No Solution"

    # Initial propagation
    init_stack = []
    if not propagate(init_stack):
        return "No Solution"

    # Backtracking with aggressive propagation and heuristic branching
    def dfs():
        vidx, tag = pick_var()
        if vidx == -1:
            return True

        if tag == "irrelevant":
            # Deterministically set to WHITE (canonical) without branching
            stack = []
            q = deque()
            inq = [False] * (R * C)
            if not assign(vidx, WHITE, stack, q, inq):
                undo(stack)
                return False
            # Need propagate from affected constraints only
            for nidx in affects[vidx]:
                if not inq[nidx]:
                    q.append(nidx)
                    inq[nidx] = True
            if not propagate_with_queue(q, inq, stack):
                undo(stack)
                return False
            if dfs():
                return True
            undo(stack)
            return False

        # Try BLACK then WHITE (often tighter for count constraints)
        for val in (BLACK, WHITE):
            stack = []
            q = deque()
            inq = [False] * (R * C)
            if not assign(vidx, val, stack, q, inq):
                undo(stack)
                continue
            # Propagate only from constraints affected by this assignment
            if not propagate_with_queue(q, inq, stack):
                undo(stack)
                continue
            if dfs():
                return True
            undo(stack)
        return False

    # A propagate variant that continues from existing queue and inq arrays.
    def propagate_with_queue(q, inq, assignments_stack):
        # If queue is empty, seed with affected constraints of recent assignments.
        if not q:
            for vidx in assignments_stack[-1:]:
                for nidx in affects[vidx]:
                    if not inq[nidx]:
                        q.append(nidx)
                        inq[nidx] = True
        while q:
            nidx = q.popleft()
            inq[nidx] = False

            if not constraint_ok(nidx):
                return False

            b = black_ct[nidx]
            u = unk_ct[nidx]
            t = need[nidx]
            if u == 0:
                continue

            force_val = None
            if b == t:
                force_val = WHITE
            elif b + u == t:
                force_val = BLACK
            if force_val is None:
                continue

            for vidx in neigh[nidx]:
                if state[vidx] == UNKNOWN:
                    if not assign(vidx, force_val, assignments_stack, q, inq):
                        return False
        return True

    def undo(assignments_stack):
        # Undo in reverse; restore counts.
        for vidx in reversed(assignments_stack):
            val = state[vidx]
            state[vidx] = UNKNOWN
            for nidx in affects[vidx]:
                unk_ct[nidx] += 1
                if val == BLACK:
                    black_ct[nidx] -= 1

    if not dfs():
        return "No Solution"

    finalize()

    # Build output grid with 'B' and None
    out = []
    for r in range(R):
        row = []
        for c in range(C):
            v = state[r * C + c]
            row.append('B' if v == BLACK else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

