from collections import deque

# Masyu (Loop the Loop) solver on an N x N dot grid with clues on cells between dots.
# Model: edges between adjacent dots (orthogonal). Each dot degree is 0 or 2 (single loop).
# Clue interpretation (cell at (r,c)):
#  - 'W' (white): path goes straight through cell; and at least one of the adjacent cells
#    before or after (in travel direction) must be a turn.
#  - 'B' (black): path turns in cell; and the cells immediately before and after must be straight.

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]  # U,R,D,L
OPP = {0: 2, 1: 3, 2: 0, 3: 1}

def solve(observation):
    data = observation["data"]
    N = len(data)
    # Dots are (0..N) x (0..N)
    H = N + 1
    W = N + 1

    # Map each undirected edge between adjacent dots to an id
    # Horizontal edges: between (r,c) and (r,c+1) for r in 0..N, c in 0..N-1 => (N+1)*N
    # Vertical edges: between (r,c) and (r+1,c) for r in 0..N-1, c in 0..N => N*(N+1)
    # Total edges: 2*N*(N+1)
    def hid(r, c):  # horizontal edge at dot-row r, dot-col c -> between (r,c) and (r,c+1)
        return r * N + c

    def vid(r, c):  # vertical edge at dot-row r, dot-col c -> between (r,c) and (r+1,c)
        return (H * N) + r * (N + 1) + c

    E = 2 * N * (N + 1)

    # Edge endpoints and adjacency by dot
    e_u = [None] * E
    e_v = [None] * E
    dot_edges = [[] for _ in range(H * W)]

    def d_id(r, c):
        return r * W + c

    # fill horizontal edges
    for r in range(H):
        for c in range(N):
            eid = hid(r, c)
            u = d_id(r, c)
            v = d_id(r, c + 1)
            e_u[eid] = u
            e_v[eid] = v
            dot_edges[u].append(eid)
            dot_edges[v].append(eid)
    # fill vertical edges
    for r in range(N):
        for c in range(W):
            eid = vid(r, c)
            u = d_id(r, c)
            v = d_id(r + 1, c)
            e_u[eid] = u
            e_v[eid] = v
            dot_edges[u].append(eid)
            dot_edges[v].append(eid)

    # Edge states: -1 unknown, 0 off, 1 on
    st = [-1] * E
    deg = [0] * (H * W)

    # Helper: enumerate edges bordering a cell (r,c) in dot coordinates:
    # top: h(r, c), bottom: h(r+1, c), left: v(r, c), right: v(r, c+1)
    def cell_edges(r, c):
        return (hid(r, c), hid(r + 1, c), vid(r, c), vid(r, c + 1))

    # Determine if an edge is horizontal/vertical, and which direction it represents around a cell
    def is_h(eid):
        return eid < H * N

    # For a given cell and an "on" pattern, determine straight vs turn:
    # straight means both horizontals on (and verticals off) OR both verticals on (and horizontals off)
    # turn means one horizontal and one vertical on, other two off
    def classify_cell(r, c):
        top, bot, left, right = cell_edges(r, c)
        vals = [st[top], st[bot], st[left], st[right]]
        if -1 in vals:
            return None
        on = [i for i, v in enumerate(vals) if v == 1]
        if len(on) != 2:
            return "invalid"
        if set(on) == {0, 1}:
            return "straight_h"
        if set(on) == {2, 3}:
            return "straight_v"
        if (0 in on or 1 in on) and (2 in on or 3 in on):
            return "turn"
        return "invalid"

    # Propagation queue of constraints to re-check
    q = deque()

    def push_dot(d):
        q.append(("dot", d))

    def push_cell(r, c):
        q.append(("cell", (r, c)))

    # Initialize all dots/cells to be checked
    for d in range(H * W):
        push_dot(d)
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                push_cell(r, c)

    # DSU for preventing premature small cycles: we allow cycle only when it includes all "on" edges
    parent = list(range(H * W))
    size = [1] * (H * W)

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return ra
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return ra

    # Track "on" edges count per component endpoints to detect forming a closed cycle early:
    # We'll use union-find only for forced-on edges during propagation, and for decision branches we rebuild DSU cheaply.
    # For speed we maintain DSU incrementally and check for cycle creation when adding an edge.

    # Trail for backtracking: list of (kind, idx, old)
    trail = []
    qtrail = []  # queue length markers

    def snapshot():
        trail.append(("MARK", None, None))
        qtrail.append(len(q))

    def rollback():
        # restore queue
        target_q_len = qtrail.pop()
        while len(q) > target_q_len:
            q.pop()
        # undo changes
        while trail:
            k, a, old = trail.pop()
            if k == "MARK":
                break
            if k == "E":
                eid = a
                st[eid] = old
            elif k == "D":
                d = a
                deg[d] = old
            elif k == "P":
                i = a
                parent[i] = old
            elif k == "S":
                i = a
                size[i] = old

    def set_parent(i, val):
        if parent[i] != val:
            trail.append(("P", i, parent[i]))
            parent[i] = val

    def set_size(i, val):
        if size[i] != val:
            trail.append(("S", i, size[i]))
            size[i] = val

    def dsu_union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return ra, True
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        set_parent(rb, ra)
        set_size(ra, size[ra] + size[rb])
        return ra, False

    def set_edge(eid, val):
        cur = st[eid]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        trail.append(("E", eid, cur))
        st[eid] = val
        u, v = e_u[eid], e_v[eid]
        if val == 1:
            # update degrees
            trail.append(("D", u, deg[u]))
            trail.append(("D", v, deg[v]))
            deg[u] += 1
            deg[v] += 1
            # union
            _, formed_cycle = dsu_union(u, v)
            if formed_cycle:
                # If this creates a cycle, it must be the final single loop.
                # So all dots with degree>0 must be in this component and no dot may exceed degree 2.
                # We'll check degree constraints immediately; full check later in validation.
                pass
            push_dot(u)
            push_dot(v)
        else:
            # edge off affects dot constraints too
            push_dot(u)
            push_dot(v)
        # edge affects adjacent cells (at most 2)
        # Determine adjacent cell coordinates:
        if is_h(eid):
            # horizontal edge at dot-row r, col c
            r = eid // N
            c = eid % N
            # adjacent cells: above at (r-1,c) if r>0 ; below at (r,c) if r<N
            if 0 < r <= N - 1:
                if data[r - 1][c] is not None:
                    push_cell(r - 1, c)
            if 0 <= r < N and data[r][c] is not None:
                push_cell(r, c)
        else:
            x = eid - (H * N)
            r = x // (N + 1)
            c = x % (N + 1)
            # adjacent cells: left at (r,c-1) if c>0 ; right at (r,c) if c<N
            if 0 <= r < N:
                if 0 < c <= N - 1 and data[r][c - 1] is not None:
                    push_cell(r, c - 1)
                if c < N and data[r][c] is not None:
                    push_cell(r, c)
        return True

    # Dot constraints: degree must be 0 or 2. If degree==2 => all other incident edges off.
    # If degree==1 => at least one more incident edge on (unless impossible); if only one unknown remains, force it on.
    # If degree==0 and exactly 2 possible edges must remain? We do mild propagation: if exactly 2 incident edges can still be on and others off forced? not needed.
    def propagate_dot(d):
        inc = dot_edges[d]
        on = sum(1 for e in inc if st[e] == 1)
        off = sum(1 for e in inc if st[e] == 0)
        unk = [e for e in inc if st[e] == -1]
        if on != deg[d]:
            # deg array should match
            return False
        if on > 2:
            return False
        if on == 2:
            # remaining must be off
            for e in unk:
                if not set_edge(e, 0):
                    return False
        # If on==1, and all but one are off -> last must be on
        if on == 1:
            # Need one more on eventually; if no unknowns -> dead
            if not unk:
                return False
            if len(unk) == 1:
                if not set_edge(unk[0], 1):
                    return False
        if on == 0:
            # If exactly one unknown and others off, cannot reach degree 2 (would end at 1)
            if len(unk) == 1:
                return False
        return True

    # Cell constraint propagation for Masyu.
    # We encode local possibilities for each clue cell in terms of its 4 bordering edges.
    # Additionally, impose neighbor straight/turn requirements by pushing implications on adjacent cells.
    def propagate_cell(r, c):
        clue = data[r][c]
        if clue is None:
            return True
        top, bot, left, right = cell_edges(r, c)
        edges = [top, bot, left, right]
        vals = [st[e] for e in edges]

        # Helper: force exact pattern
        def force_pattern(on_set):
            for i, e in enumerate(edges):
                v = 1 if i in on_set else 0
                if not set_edge(e, v):
                    return False
            return True

        # Generate feasible patterns consistent with clue + current assignments + neighbor straight requirements (as far as known).
        feasible = []
        # Patterns are sets of indices among {0:top,1:bot,2:left,3:right} that are ON.
        # For any valid loop through cell: exactly 2 edges on, and they must connect.
        base_patterns = [{0, 1}, {2, 3}, {0, 2}, {0, 3}, {1, 2}, {1, 3}]
        for on_set in base_patterns:
            ok = True
            # must match clue geometry
            if clue == "W":
                if on_set not in ({0, 1}, {2, 3}):
                    ok = False
            else:  # 'B'
                if on_set in ({0, 1}, {2, 3}):
                    ok = False
            if not ok:
                continue
            # must be consistent with assigned edges
            for i, e in enumerate(edges):
                if st[e] != -1:
                    if (st[e] == 1) != (i in on_set):
                        ok = False
                        break
            if not ok:
                continue
            feasible.append(on_set)

        if not feasible:
            return False

        # Neighbor requirements:
        # For 'B': the adjacent cell in the direction of each used edge must be straight in that cell (if that cell exists and is a clue or can be influenced).
        # More directly: black turn implies entering/leaving straight segments extend one more cell.
        # Classic Masyu edge implications:
        #  - Black: the edges adjacent to the turn must continue straight across the neighboring cells:
        #    If turn uses top and left, then in cell above (r-1,c) must use its bottom edge AND the opposite of bottom (i.e., vertical straight),
        #    and in cell left (r,c-1) must use its right edge and horizontal straight.
        #  - White: straight through, and at least one of the neighboring cells along the straight direction is a turn.
        #
        # We'll do strong deterministic implications when a cell's orientation is forced (single feasible pattern).
        if len(feasible) == 1:
            on_set = next(iter(feasible))
            if not force_pattern(on_set):
                return False

            if clue == "B":
                # Determine which two directions are used and enforce straight extension one cell further.
                used = list(on_set)
                # used are indices among edges: 0 top,1 bot,2 left,3 right
                for idx in used:
                    if idx == 0 and r - 1 >= 0:
                        # cell above must have bottom edge ON and be vertical straight => its top also ON
                        if not set_edge(hid(r - 1, c), 1):  # top edge of above cell
                            return False
                        if not set_edge(hid(r, c), 1):  # bottom edge of above cell == this top edge already on
                            return False
                    elif idx == 1 and r + 1 < N:
                        if not set_edge(hid(r + 2, c), 1):  # bottom edge of below cell
                            return False
                        if not set_edge(hid(r + 1, c), 1):  # top edge of below cell == this bottom edge already on
                            return False
                    elif idx == 2 and c - 1 >= 0:
                        if not set_edge(vid(r, c - 1), 1):  # left edge of left cell
                            return False
                        if not set_edge(vid(r, c), 1):      # right edge of left cell == this left edge already on
                            return False
                    elif idx == 3 and c + 1 < N:
                        if not set_edge(vid(r, c + 2), 1):  # right edge of right cell
                            return False
                        if not set_edge(vid(r, c + 1), 1):  # left edge of right cell == this right edge already on
                            return False
                # Also, in the black cell itself, the two unused edges must be off (already by force_pattern)
                return True

            if clue == "W":
                # White: straight through; require at least one adjacent cell along travel direction is a turn.
                # We'll encode as: if straight is vertical, then either cell above or below must be a turn.
                # If straight is horizontal, either left or right must be a turn.
                # Deterministically, if one side is missing (border) then the other must be a turn.
                # Also, if a neighbor cell is already forced straight, then the other must be a turn.
                classification = "vertical" if on_set == {2, 3} else "horizontal"
                if classification == "vertical":
                    candidates = []
                    if r - 1 >= 0:
                        candidates.append((r - 1, c))
                    if r + 1 < N:
                        candidates.append((r + 1, c))
                else:
                    candidates = []
                    if c - 1 >= 0:
                        candidates.append((r, c - 1))
                    if c + 1 < N:
                        candidates.append((r, c + 1))

                # If only one candidate exists, force it to be a turn (if it's a clue, must be compatible; if empty, we can still force via edge pattern)
                if len(candidates) == 1:
                    rr, cc = candidates[0]
                    if not force_cell_turn(rr, cc):
                        return False
                elif len(candidates) == 2:
                    # If one neighbor cannot be a turn due to existing edge assignments, force the other.
                    a, b = candidates
                    a_can = cell_can_be_turn(*a)
                    b_can = cell_can_be_turn(*b)
                    if not a_can and not b_can:
                        return False
                    if not a_can and b_can:
                        if not force_cell_turn(*b):
                            return False
                    if not b_can and a_can:
                        if not force_cell_turn(*a):
                            return False
                return True

        # If multiple feasible patterns, do edge-wise consensus propagation:
        must_on = set.intersection(*feasible)
        must_off = set(range(4)) - set.union(*feasible)
        for i in must_on:
            if not set_edge(edges[i], 1):
                return False
        for i in must_off:
            if not set_edge(edges[i], 0):
                return False
        return True

    def cell_can_be_turn(r, c):
        if not (0 <= r < N and 0 <= c < N):
            return False
        top, bot, left, right = cell_edges(r, c)
        edges = [top, bot, left, right]
        vals = [st[e] for e in edges]
        # turn patterns:
        patterns = [{0, 2}, {0, 3}, {1, 2}, {1, 3}]
        clue = data[r][c]
        for on_set in patterns:
            ok = True
            if clue == "W":
                ok = False
            if clue == "B":
                ok = True
            if clue is None:
                ok = True
            if not ok:
                continue
            for i, e in enumerate(edges):
                if vals[i] != -1 and ((vals[i] == 1) != (i in on_set)):
                    ok = False
                    break
            if ok:
                return True
        return False

    def force_cell_turn(r, c):
        if not (0 <= r < N and 0 <= c < N):
            return False
        top, bot, left, right = cell_edges(r, c)
        edges = [top, bot, left, right]
        vals = [st[e] for e in edges]
        patterns = [{0, 2}, {0, 3}, {1, 2}, {1, 3}]
        clue = data[r][c]
        feasible = []
        for on_set in patterns:
            if clue == "W":
                continue
            if clue == "B":
                pass
            for i, e in enumerate(edges):
                if vals[i] != -1 and ((vals[i] == 1) != (i in on_set)):
                    break
            else:
                feasible.append(on_set)
        if not feasible:
            return False
        if len(feasible) == 1:
            on_set = feasible[0]
            for i, e in enumerate(edges):
                if not set_edge(e, 1 if i in on_set else 0):
                    return False
        # else can't force uniquely; just leave
        return True

    def propagate():
        while q:
            typ, obj = q.popleft()
            if typ == "dot":
                if not propagate_dot(obj):
                    return False
            else:
                r, c = obj
                if not propagate_cell(r, c):
                    return False
        return True

    def all_clues_satisfied():
        for r in range(N):
            for c in range(N):
                clue = data[r][c]
                if clue is None:
                    continue
                cls = classify_cell(r, c)
                if cls is None:
                    return False
                if clue == "W":
                    if cls not in ("straight_h", "straight_v"):
                        return False
                else:
                    if cls != "turn":
                        return False
        # Additional white/black neighbor conditions fully:
        for r in range(N):
            for c in range(N):
                clue = data[r][c]
                if clue is None:
                    continue
                top, bot, left, right = cell_edges(r, c)
                on_set = set()
                if st[top] == 1: on_set.add(0)
                if st[bot] == 1: on_set.add(1)
                if st[left] == 1: on_set.add(2)
                if st[right] == 1: on_set.add(3)
                if clue == "B":
                    # turn, and adjacent cells along both arms must be straight
                    # For each used edge, the neighboring cell must be straight in that direction.
                    for idx in on_set:
                        if idx == 0:
                            if r - 1 < 0:
                                return False
                            ncls = classify_cell(r - 1, c)
                            if ncls != "straight_v":
                                return False
                        elif idx == 1:
                            if r + 1 >= N:
                                return False
                            ncls = classify_cell(r + 1, c)
                            if ncls != "straight_v":
                                return False
                        elif idx == 2:
                            if c - 1 < 0:
                                return False
                            ncls = classify_cell(r, c - 1)
                            if ncls != "straight_h":
                                return False
                        else:
                            if c + 1 >= N:
                                return False
                            ncls = classify_cell(r, c + 1)
                            if ncls != "straight_h":
                                return False
                else:
                    # straight, and at least one adjacent along direction is a turn
                    if on_set == {0, 1}:  # horizontal straight through cell
                        # neighbors left/right are cells (r,c-1) and (r,c+1)?? Actually travel direction is horizontal,
                        # so adjacent cells are left and right.
                        left_ok = (c - 1 >= 0 and classify_cell(r, c - 1) == "turn")
                        right_ok = (c + 1 < N and classify_cell(r, c + 1) == "turn")
                        if not (left_ok or right_ok):
                            return False
                    elif on_set == {2, 3}:  # vertical
                        up_ok = (r - 1 >= 0 and classify_cell(r - 1, c) == "turn")
                        down_ok = (r + 1 < N and classify_cell(r + 1, c) == "turn")
                        if not (up_ok or down_ok):
                            return False
                    else:
                        return False
        return True

    def single_loop_check():
        # All dots have degree 0 or 2, and all degree-2 dots are in one connected component.
        active = [d for d in range(H * W) if deg[d] > 0]
        if not active:
            return False
        for d in active:
            if deg[d] != 2:
                return False
        root = find(active[0])
        for d in active[1:]:
            if find(d) != root:
                return False
        # Ensure number of on edges equals number of active dots (cycle)
        on_edges = sum(1 for e in range(E) if st[e] == 1)
        if on_edges != len(active):
            return False
        return True

    def choose_branch_edge():
        # Prefer unknown edges touching clue cells, especially ones with high constraint.
        best = None
        best_score = -1
        for e in range(E):
            if st[e] != -1:
                continue
            score = 0
            u, v = e_u[e], e_v[e]
            # endpoints degrees
            score += (deg[u] + deg[v])
            # adjacency to clues
            if is_h(e):
                r = e // N
                c = e % N
                if 0 < r <= N - 1 and data[r - 1][c] is not None:
                    score += 5
                if 0 <= r < N and data[r][c] is not None:
                    score += 5
            else:
                x = e - (H * N)
                r = x // (N + 1)
                c = x % (N + 1)
                if 0 <= r < N:
                    if 0 < c <= N - 1 and data[r][c - 1] is not None:
                        score += 5
                    if c < N and data[r][c] is not None:
                        score += 5
            if score > best_score:
                best_score = score
                best = e
        return best

    def rebuild_dsu():
        # Rebuild DSU from current on edges (needed because our incremental DSU with rollback covers all, but find path compression
        # can complicate rollback safety. We avoided compression in find except partial; still can be problematic.
        # We'll instead rebuild DSU at each node for correctness with small overhead.
        for i in range(H * W):
            parent[i] = i
            size[i] = 1
        for e in range(E):
            if st[e] == 1:
                a, b = e_u[e], e_v[e]
                ra, rb = find(a), find(b)
                if ra != rb:
                    if size[ra] < size[rb]:
                        ra, rb = rb, ra
                    parent[rb] = ra
                    size[ra] += size[rb]

    def dfs():
        if not propagate():
            return None
        # quick impossibility: any dot degree >2 already caught; also prevent isolated 1-degree endpoints due to no unknowns in propagate_dot.
        # if all edges decided, validate
        if all(v != -1 for v in st):
            rebuild_dsu()
            if all_clues_satisfied() and single_loop_check():
                return extract_loop()
            return None

        # additional partial check: clue cells must remain feasible
        # (lightweight) - skip for speed; propagate_cell already checks.

        e = choose_branch_edge()
        if e is None:
            return None

        # Try ON then OFF (often ON is more constrained)
        for val in (1, 0):
            snapshot()
            rebuild_dsu()  # keep DSU consistent before applying edge (since propagate uses it)
            if set_edge(e, val):
                res = dfs()
                if res is not None:
                    return res
            rollback()
        return None

    def extract_loop():
        # Build adjacency from ON edges
        adj = [[] for _ in range(H * W)]
        for e in range(E):
            if st[e] == 1:
                u, v = e_u[e], e_v[e]
                adj[u].append(v)
                adj[v].append(u)
        # find start
        start = next(i for i in range(H * W) if len(adj[i]) == 2)
        # walk cycle
        path = []
        prev = None
        cur = start
        while True:
            r, c = divmod(cur, W)
            path.append((r, c))
            nxts = adj[cur]
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            prev, cur = cur, nxt
            if cur == start:
                break
        path.append(path[0])
        return path

    # Ensure initial DSU is clean (will rebuild during search)
    rebuild_dsu()
    sol = dfs()
    if sol is None:
        return "No Solution"
    return str(sol)

if __name__ == "__main__":
    print(solve(OBSERVATION))

