from collections import deque, defaultdict
import itertools
import math
import sys

# Minesweeper-style solver for "given-number" constraints with unknown mines everywhere else.
# Goal: flag a set of mines such that each numbered cell equals the count of adjacent mines.
# Output: grid of same size with 'F' for mines and None otherwise.


def solve(observation):
    grid = observation["data"]
    R = len(grid)
    C = len(grid[0]) if R else 0

    # Precompute neighbors
    neigh = [[] for _ in range(R * C)]
    for r in range(R):
        for c in range(C):
            i = r * C + c
            for dr in (-1, 0, 1):
                rr = r + dr
                if 0 <= rr < R:
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        cc = c + dc
                        if 0 <= cc < C:
                            neigh[i].append(rr * C + cc)

    # Identify constraint cells (numbers)
    clue_cells = []
    clue_val = {}
    for r in range(R):
        for c in range(C):
            v = grid[r][c]
            if v is not None:
                i = r * C + c
                clue_cells.append(i)
                clue_val[i] = int(v)

    # Variables are all cells (including numbered ones) that may be mines.
    # But in classic minesweeper, numbered cells are never mines. Here, the statement doesn't explicitly say,
    # yet it's strongly implied by "numbered cell equals adjacent mines", not including itself.
    # We'll enforce: numbered cells are non-mines.
    is_numbered = [False] * (R * C)
    for i in clue_cells:
        is_numbered[i] = True

    # Variable domain: unknown mine status for non-numbered cells only.
    var_cells = [i for i in range(R * C) if not is_numbered[i]]
    var_index = {cell: idx for idx, cell in enumerate(var_cells)}
    N = len(var_cells)

    # Build constraints: for each clue cell i, sum_{j in neigh(i) & var_cells} x_j == clue
    # plus already-fixed mines among neighbors (none initially).
    constraints = []
    cell_to_constraints = [[] for _ in range(R * C)]

    for ci in clue_cells:
        vars_in = [v for v in neigh[ci] if v in var_index]
        rhs = clue_val[ci]
        # If clue counts mines only in neighbors; numbered cells cannot be mines so fine.
        con = {"cell": ci, "vars": vars_in, "rhs": rhs}
        idx = len(constraints)
        constraints.append(con)
        for v in vars_in:
            cell_to_constraints[v].append(idx)

        # Early infeasibility check
        if rhs < 0 or rhs > len(vars_in):
            return "No Solution"

    # Assignment array for variables: -1 unknown, 0 safe, 1 mine
    assign = [-1] * N

    # For each constraint, maintain:
    # remaining RHS after accounting for assigned mines; and remaining unknown count
    con_rhs = [con["rhs"] for con in constraints]
    con_unk = [len(con["vars"]) for con in constraints]

    # For fast updates: store vars lists as var indices
    con_var_idxs = []
    for con in constraints:
        con_var_idxs.append([var_index[v] for v in con["vars"]])

    # Initialize degrees for heuristic
    var_deg = [0] * N
    for k, var_list in enumerate(con_var_idxs):
        for vi in var_list:
            var_deg[vi] += 1

    # Queue-based propagation with human-like rules and subset reasoning
    in_queue = [False] * len(constraints)
    q = deque(range(len(constraints)))
    for i in range(len(constraints)):
        in_queue[i] = True

    # For subset reasoning, we group constraints by clue cell neighborhood intersection.
    # We'll do dynamic local subset checks only within affected area for efficiency.

    # Track for each constraint: current unknown vars list not stored; compute on demand with filtering.
    def con_counts(k):
        # returns (min_possible, max_possible) and (unk_vars list)
        rhs = con_rhs[k]
        vars_k = con_var_idxs[k]
        unk = [vi for vi in vars_k if assign[vi] < 0]
        mines_assigned = sum(1 for vi in vars_k if assign[vi] == 1)
        # con_rhs already represents original rhs; we keep separate? We'll maintain con_rhs as remaining rhs.
        # So mines_assigned won't match. We'll avoid mines_assigned and use remaining rhs + unknown only.
        # We'll compute remaining mines required = rem_rhs and rem_unk = len(unk).
        rem_rhs = remaining_rhs(k)
        rem_unk = len(unk)
        return rem_rhs, rem_unk, unk

    # We'll maintain rem_rhs and rem_unk incrementally:
    rem_rhs = con_rhs[:]  # remaining mines needed in constraint
    rem_unk = con_unk[:]  # remaining unassigned vars in constraint

    # Need a way to update per assignment:
    # When variable set to mine: for each constraint containing it: rem_rhs -=1, rem_unk -=1
    # When safe: rem_unk -=1
    def remaining_rhs(k):  # tiny wrapper for readability
        return rem_rhs[k]

    def enqueue_constraint(k):
        if not in_queue[k]:
            in_queue[k] = True
            q.append(k)

    # Assign variable with propagation bookkeeping
    def set_var(vi, val, trail):
        if assign[vi] == val:
            return True
        if assign[vi] != -1 and assign[vi] != val:
            return False
        assign[vi] = val
        trail.append(vi)
        # update all constraints containing this var
        cell = var_cells[vi]
        for ck in cell_to_constraints[cell]:
            rem_unk[ck] -= 1
            if val == 1:
                rem_rhs[ck] -= 1
            # enqueue for propagation
            enqueue_constraint(ck)
        return True

    # Basic human rules per constraint:
    # If rem_rhs == 0 => all unknown vars are safe.
    # If rem_rhs == rem_unk => all unknown vars are mines.
    # If rem_rhs < 0 or rem_rhs > rem_unk => contradiction.
    def propagate_basic(trail):
        while q:
            ck = q.popleft()
            in_queue[ck] = False
            rr = rem_rhs[ck]
            uu = rem_unk[ck]
            if rr < 0 or rr > uu:
                return False
            if uu == 0:
                if rr != 0:
                    return False
                continue
            if rr == 0 or rr == uu:
                # Determine assignment for all unknown vars in this constraint
                target = 1 if rr == uu else 0
                for vi in con_var_idxs[ck]:
                    if assign[vi] < 0:
                        if not set_var(vi, target, trail):
                            return False
        return True

    # Subset reasoning:
    # For constraints A and B, with variable sets SA, SB.
    # If SA subset SB, then mines in (SB\SA) = rhsB - rhsA, and unknowns count = |SB\SA|.
    # When rhsB - rhsA == 0 => (SB\SA) all safe; when equals |SB\SA| => all mines.
    #
    # We'll apply locally: whenever constraints in a local neighborhood changed, check pairs among them.
    # We'll restrict to constraints sharing at least one variable cell for efficiency using adjacency sets.
    con_vars_set = [set(lst) for lst in con_var_idxs]

    # Build constraint adjacency via shared variables
    con_adj = [set() for _ in range(len(constraints))]
    var_to_cons = [[] for _ in range(N)]
    for ck, lst in enumerate(con_var_idxs):
        for vi in lst:
            var_to_cons[vi].append(ck)
    for vi, cons in enumerate(var_to_cons):
        for a in cons:
            for b in cons:
                if a != b:
                    con_adj[a].add(b)

    def subset_step(trail):
        # We'll do a bounded iterative pass; if anything assigned, re-run basic propagation.
        changed = True
        while changed:
            changed = False
            # Collect constraints that are "active": rem_unk>0 and 0<=rem_rhs<=rem_unk
            active = [k for k in range(len(constraints)) if rem_unk[k] > 0]
            # For efficiency, iterate by adjacency
            for a in active:
                SA = con_vars_set[a]
                if not SA:
                    continue
                rrA = rem_rhs[a]
                # If contradiction already
                if rrA < 0 or rrA > rem_unk[a]:
                    return False
                for b in con_adj[a]:
                    SB = con_vars_set[b]
                    if not SB or len(SA) > len(SB):
                        continue
                    # Need to consider only unassigned vars in sets. We'll construct filtered sets.
                    # To keep fast, build using current assignment check.
                    # We'll treat SAu, SBu as sets of unknown vars in each constraint.
                    SAu = None
                    SBu = None
                    # Quick skip if A can't be subset by size bound on unknowns
                    if rem_unk[a] > rem_unk[b]:
                        continue
                    # Compute SAu, SBu
                    SAu = {vi for vi in SA if assign[vi] < 0}
                    if not SAu:
                        continue
                    SBu = {vi for vi in SB if assign[vi] < 0}
                    if not SBu:
                        continue
                    if not SAu.issubset(SBu):
                        continue
                    diff = SBu - SAu
                    if not diff:
                        continue
                    rrB = rem_rhs[b]
                    # Remaining rhs already accounts for assigned mines
                    d = rrB - rrA
                    if d < 0 or d > len(diff):
                        return False
                    if d == 0 or d == len(diff):
                        target = 1 if d == len(diff) else 0
                        for vi in diff:
                            if assign[vi] < 0:
                                if not set_var(vi, target, trail):
                                    return False
                                changed = True
                        if changed:
                            if not propagate_basic(trail):
                                return False
        return True

    def full_propagate(trail):
        if not propagate_basic(trail):
            return False
        if not subset_step(trail):
            return False
        # One more basic sweep (subset may have enqueued)
        if not propagate_basic(trail):
            return False
        return True

    # Initial propagation
    trail0 = []
    if not full_propagate(trail0):
        return "No Solution"

    # Connected components on remaining unknown variables via constraints for component-wise search
    def build_components():
        unseen = set(i for i in range(N) if assign[i] < 0 and var_deg[i] > 0)
        comps = []
        while unseen:
            start = next(iter(unseen))
            stack = [start]
            unseen.remove(start)
            vars_comp = []
            cons_comp = set()
            while stack:
                vi = stack.pop()
                vars_comp.append(vi)
                for ck in var_to_cons[vi]:
                    cons_comp.add(ck)
                    for vj in con_var_idxs[ck]:
                        if assign[vj] < 0 and vj in unseen:
                            unseen.remove(vj)
                            stack.append(vj)
            comps.append((vars_comp, sorted(cons_comp)))
        # Variables with degree 0 are unconstrained; must be safe (otherwise would violate nothing, but allowed).
        # We choose to set them safe to find a minimal-mine solution; any mine there would be unconstrained.
        for vi in range(N):
            if assign[vi] < 0 and var_deg[vi] == 0:
                # choose safe deterministically
                trail = []
                if not set_var(vi, 0, trail):
                    return None
                if not full_propagate(trail):
                    return None
        return comps

    comps = build_components()
    if comps is None:
        return "No Solution"

    # Backtracking with strong propagation. Choose next variable by:
    # - highest degree, then participate in tight constraints (small rem_unk), then arbitrary.
    def pick_var(vars_subset=None):
        best = -1
        best_key = None
        candidates = vars_subset if vars_subset is not None else range(N)
        for vi in candidates:
            if assign[vi] >= 0:
                continue
            deg = var_deg[vi]
            # compute tightness: min rem_unk among constraints it appears in
            tight = 999999
            for ck in var_to_cons[vi]:
                tight = min(tight, rem_unk[ck])
            key = (deg, -tight)  # maximize deg, minimize tight => maximize -tight
            if best_key is None or key > best_key:
                best_key = key
                best = vi
        return best

    def snapshot_constraints(cons_list):
        # snapshot rem_rhs/rem_unk and var sets for constraints in cons_list
        return [(k, rem_rhs[k], rem_unk[k], con_vars_set[k].copy()) for k in cons_list]

    def restore_constraints(snap):
        for k, rr, uu, s in snap:
            rem_rhs[k] = rr
            rem_unk[k] = uu
            con_vars_set[k].clear()
            con_vars_set[k].update(s)
            # queue state cleared by recomputation; we'll just enqueue for safety
            enqueue_constraint(k)

    def apply_varset_updates(vi):
        # When a var is assigned, remove it from each constraint's set used for subset reasoning
        for ck in var_to_cons[vi]:
            if vi in con_vars_set[ck]:
                con_vars_set[ck].remove(vi)

    def undo_varset_updates(trail_vars, cons_snap):
        # cons_snap restore covers varset; nothing else needed.
        pass

    # Modify set_var to also update con_vars_set quickly via apply_varset_updates;
    # We'll wrap it here to avoid rewriting above.
    def set_var2(vi, val, trail, touched_cons):
        if assign[vi] == val:
            return True
        if assign[vi] != -1 and assign[vi] != val:
            return False
        # record constraints touched for snapshot
        for ck in var_to_cons[vi]:
            touched_cons.add(ck)
        ok = set_var(vi, val, trail)
        if not ok:
            return False
        apply_varset_updates(vi)
        return True

    def dfs(vars_scope=None):
        vi = pick_var(vars_scope)
        if vi == -1:
            return True
        # Determine preferred value using constraints: if a var appears in constraints where rem_rhs is close to rem_unk, mine more likely.
        mine_score = 0
        safe_score = 0
        for ck in var_to_cons[vi]:
            if rem_unk[ck] > 0:
                mine_score += rem_rhs[ck] / rem_unk[ck]
                safe_score += (rem_unk[ck] - rem_rhs[ck]) / rem_unk[ck]
        order = [1, 0] if mine_score > safe_score else [0, 1]

        for val in order:
            trail = []
            touched_cons = set()
            cons_snap = None
            # snapshot touched constraints before assignment to restore rem_* and sets
            for ck in var_to_cons[vi]:
                touched_cons.add(ck)
            cons_snap = snapshot_constraints(touched_cons)
            # Also snapshot queue state minimally by clearing and rebuilding affected constraints enqueue
            saved_queue = list(q)
            saved_inq = in_queue[:]

            ok = set_var2(vi, val, trail, touched_cons)
            if ok:
                # propagate
                ok = full_propagate(trail)
            if ok:
                if dfs(vars_scope):
                    return True

            # undo assignments
            for vj in reversed(trail):
                # restore rem updates by replaying inverse effects:
                valj = assign[vj]
                assign[vj] = -1
                cell = var_cells[vj]
                for ck in cell_to_constraints[cell]:
                    rem_unk[ck] += 1
                    if valj == 1:
                        rem_rhs[ck] += 1
            # restore constraints sets and queue
            restore_constraints(cons_snap)
            q.clear()
            q.extend(saved_queue)
            in_queue[:] = saved_inq
        return False

    # Solve component-wise: but constraints can connect components; our comps built accordingly.
    # We'll just do global dfs; it's typically fine given propagation. Still, prefer solving by components sequentially.
    for vars_comp, cons_comp in comps:
        # Ensure queue is empty before component search
        # run dfs restricted to vars_comp; other vars are already assigned or in other components
        if not dfs(vars_comp):
            return "No Solution"
        # After finishing a component, propagate globally in case of cross effects (shouldn't happen)
        trail = []
        if not full_propagate(trail):
            return "No Solution"

    # Final check
    for ck in range(len(constraints)):
        if rem_unk[ck] != 0 or rem_rhs[ck] != 0:
            # Assign remaining vars if any (shouldn't)
            return "No Solution"

    # Build answer grid
    out = [[None for _ in range(C)] for _ in range(R)]
    for vi, cell in enumerate(var_cells):
        r, c = divmod(cell, C)
        if assign[vi] == 1:
            out[r][c] = "F"

    return str(out)


