OBSERVATION = {'data': [[None, 1, None, None, 3, None, None], [None, None, 1, None, 4, None, 2], [None, 3, 2, 2, None, None, None], [2, None, 1, None, None, None, None], [None, None, None, None, 1, None, 0], [None, None, None, 1, None, None, None], [2, None, 2, None, None, None, 1]]}
from __future__ import annotations

from dataclasses import dataclass
from typing import List, Optional, Tuple, Dict, Set
from collections import deque, defaultdict
import itertools


# Minesweeper solver:
# - Builds local constraints around each clue cell.
# - Applies human-like propagation (forced mines/safes, subset rule).
# - Uses component-based exact enumeration on small frontiers (not global brute force).
# - Falls back to branch & bound on the most constrained cell only if necessary.


Coord = Tuple[int, int]


def solve(observation):
    grid = observation["data"]
    R = len(grid)
    C = len(grid[0]) if R else 0

    def inb(r, c): return 0 <= r < R and 0 <= c < C

    neigh = {}
    for r in range(R):
        for c in range(C):
            ns = []
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if inb(rr, cc):
                        ns.append((rr, cc))
            neigh[(r, c)] = tuple(ns)

    clues: Dict[Coord, int] = {}
    for r in range(R):
        for c in range(C):
            v = grid[r][c]
            if v is not None:
                clues[(r, c)] = int(v)

    # State per cell: -1 unknown, 0 safe, 1 mine
    state = [[-1] * C for _ in range(R)]
    # Clue cells are always safe (not mines)
    for (r, c) in clues:
        state[r][c] = 0

    # Constraint representation: for each clue cell, list of adjacent unknown variables and required mines count.
    # We'll update dynamically with state.
    clue_adj = {p: [q for q in neigh[p] if q not in clues] for p in clues}

    def current_constraint(p: Coord):
        """Return (unknown_neighbors_list, needed_mines) for clue p under current state."""
        need = clues[p]
        unk = []
        for q in clue_adj[p]:
            sr, sc = q
            if state[sr][sc] == 1:
                need -= 1
            elif state[sr][sc] == -1:
                unk.append(q)
        return unk, need

    # Fast invalidity checks on constraints
    def any_contradiction(affected_clues: Set[Coord] | None = None) -> bool:
        targets = affected_clues if affected_clues is not None else clues.keys()
        for p in targets:
            unk, need = current_constraint(p)
            if need < 0 or need > len(unk):
                return True
        return False

    # Mapping from variable cell -> adjacent clues for incremental updates
    var_to_clues: Dict[Coord, List[Coord]] = defaultdict(list)
    for p in clues:
        for q in clue_adj[p]:
            var_to_clues[q].append(p)

    def set_cell(cell: Coord, val: int, queue: deque, changed_vars: Set[Coord], changed_clues: Set[Coord]):
        r, c = cell
        cur = state[r][c]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        state[r][c] = val
        changed_vars.add(cell)
        for cp in var_to_clues.get(cell, ()):
            changed_clues.add(cp)
            queue.append(cp)
        return True

    # Human-like propagation rules:
    # 1) If need==0 => all adjacent unknowns are safe.
    # 2) If need==len(unk) => all adjacent unknowns are mines.
    # 3) Subset rule: If A's unknown set subset of B's, derive constraints on B\A.
    # 4) Generalized pairwise difference for small sets (still subset-based).
    def propagate() -> bool:
        queue = deque(clues.keys())
        inq = set(queue)
        changed = True
        while changed:
            changed = False
            # Basic forced deductions with a queue over clues
            while queue:
                p = queue.popleft()
                inq.discard(p)
                unk, need = current_constraint(p)
                if need < 0 or need > len(unk):
                    return False
                if need == 0 and unk:
                    for q in unk:
                        if state[q[0]][q[1]] == -1:
                            if not set_cell(q, 0, queue, set(), set()):
                                return False
                            changed = True
                elif need == len(unk) and unk:
                    for q in unk:
                        if state[q[0]][q[1]] == -1:
                            if not set_cell(q, 1, queue, set(), set()):
                                return False
                            changed = True

            if any_contradiction():
                return False

            # Subset reasoning: build active constraints list
            active = []
            for p in clues:
                unk, need = current_constraint(p)
                if unk:
                    active.append((p, frozenset(unk), need))
            if not active:
                break

            # Group by region to reduce comparisons (by variable set hash buckets)
            # We'll compare only constraints that share at least one variable: index variables to constraints
            var_index = defaultdict(list)
            for i, (_, s, _) in enumerate(active):
                for v in s:
                    var_index[v].append(i)

            candidate_pairs = set()
            for idxs in var_index.values():
                if len(idxs) > 1:
                    for a in idxs:
                        for b in idxs:
                            if a < b:
                                candidate_pairs.add((a, b))

            if not candidate_pairs:
                break

            # Apply subset rule on these pairs
            queue = deque()
            inq = set()
            for i, j in candidate_pairs:
                p1, s1, n1 = active[i]
                p2, s2, n2 = active[j]
                # Ensure s1 is smaller for subset check
                if len(s1) > len(s2):
                    (p1, s1, n1), (p2, s2, n2) = (p2, s2, n2), (p1, s1, n1)
                if s1.issubset(s2):
                    diff = list(s2 - s1)
                    dn = n2 - n1
                    if dn < 0 or dn > len(diff):
                        return False
                    if dn == 0 and diff:
                        for v in diff:
                            if state[v[0]][v[1]] == -1:
                                if not set_cell(v, 0, queue, set(), set()):
                                    return False
                                changed = True
                    elif dn == len(diff) and diff:
                        for v in diff:
                            if state[v[0]][v[1]] == -1:
                                if not set_cell(v, 1, queue, set(), set()):
                                    return False
                                changed = True

            # continue loop if we made changes; else exit
        return not any_contradiction()

    # Component-based exact solving for remaining frontier variables:
    # Build bipartite graph of variables and clues (only constraints with unknowns).
    def build_frontier():
        var_set = set()
        active_clues = []
        for p in clues:
            unk, need = current_constraint(p)
            if unk:
                active_clues.append(p)
                var_set.update(unk)
        return var_set, active_clues

    def connected_components(vars_set: Set[Coord], active_clues: List[Coord]):
        # Build adjacency among variables via clues
        clue_to_vars = {}
        for p in active_clues:
            unk, need = current_constraint(p)
            clue_to_vars[p] = unk

        # Build graph on vars: adjacency by sharing a clue
        var_graph = defaultdict(set)
        for p, vs in clue_to_vars.items():
            for a in vs:
                for b in vs:
                    if a != b:
                        var_graph[a].add(b)
        # Some variables may only appear alone; ensure present
        for v in vars_set:
            var_graph.setdefault(v, set())

        seen = set()
        comps = []
        for v in vars_set:
            if v in seen:
                continue
            stack = [v]
            seen.add(v)
            comp_vars = set()
            while stack:
                x = stack.pop()
                comp_vars.add(x)
                for y in var_graph[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            # collect relevant clues touching these vars
            comp_clues = set()
            for vv in comp_vars:
                for cp in var_to_clues.get(vv, ()):
                    unk, need = current_constraint(cp)
                    if unk:  # active
                        comp_clues.add(cp)
            comps.append((comp_vars, comp_clues))
        return comps

    def enumerate_component(comp_vars: List[Coord], comp_clues: List[Coord], limit_states: int = 200000):
        # Backtracking with strong pruning per clue:
        # Maintain for each clue: remaining need and remaining unknown count under partial assignment.
        idx = {v: i for i, v in enumerate(comp_vars)}
        m = len(comp_vars)

        clue_data = []
        for p in comp_clues:
            unk, need = current_constraint(p)
            # only consider vars within this component
            uv = [idx[v] for v in unk if v in idx]
            if uv:
                clue_data.append((p, uv, need))
        # For each variable index, list constraints it appears in
        var_to_constraints = [[] for _ in range(m)]
        for ci, (_, uv, _) in enumerate(clue_data):
            for vi in uv:
                var_to_constraints[vi].append(ci)

        rem_need = [need for (_, _, need) in clue_data]
        rem_unk = [len(uv) for (_, uv, _) in clue_data]

        assign = [-1] * m  # -1 unknown, 0 safe, 1 mine
        mine_count_per_var = [0] * m
        total_models = 0

        # Choose next variable heuristic: max constraints, then smallest domain (implicitly binary)
        order = sorted(range(m), key=lambda i: (-len(var_to_constraints[i]), i))

        # Better dynamic choice: pick unassigned var that appears in a most "tight" clue
        def pick_var():
            best = None
            best_key = None
            for i in range(m):
                if assign[i] != -1:
                    continue
                # tightness: min slack across its constraints
                tight = 10**9
                deg = len(var_to_constraints[i])
                for ci in var_to_constraints[i]:
                    # slack relative to remaining
                    # constraints must satisfy 0<=rem_need<=rem_unk
                    slack = rem_unk[ci] - rem_need[ci]
                    tight = min(tight, slack, rem_need[ci])
                key = (tight, -deg)
                if best is None or key < best_key:
                    best = i
                    best_key = key
            return best

        def apply(vi: int, val: int):
            assign[vi] = val
            for ci in var_to_constraints[vi]:
                rem_unk[ci] -= 1
                if val == 1:
                    rem_need[ci] -= 1

        def undo(vi: int, val: int):
            for ci in var_to_constraints[vi]:
                if val == 1:
                    rem_need[ci] += 1
                rem_unk[ci] += 1
            assign[vi] = -1

        def consistent_after_updates(affected_constraints: List[int]) -> bool:
            for ci in affected_constraints:
                if rem_need[ci] < 0 or rem_need[ci] > rem_unk[ci]:
                    return False
            return True

        def dfs():
            nonlocal total_models
            if total_models >= limit_states:
                return
            vi = pick_var()
            if vi is None:
                # All assigned: must satisfy all constraints exactly => rem_need must be 0
                for rn in rem_need:
                    if rn != 0:
                        return
                total_models += 1
                for i, a in enumerate(assign):
                    if a == 1:
                        mine_count_per_var[i] += 1
                return

            affected = var_to_constraints[vi]
            # Try values in an order that seems more likely: if any constraint needs mines, try mine first
            try_mine_first = any(rem_need[ci] > 0 for ci in affected)
            vals = (1, 0) if try_mine_first else (0, 1)
            for val in vals:
                apply(vi, val)
                if consistent_after_updates(affected):
                    dfs()
                undo(vi, val)

        # Early pruning: constraints with 0 remaining unk must have 0 need
        for ci in range(len(rem_need)):
            if rem_unk[ci] == 0 and rem_need[ci] != 0:
                return 0, mine_count_per_var, idx

        dfs()
        return total_models, mine_count_per_var, idx

    # Overall solving loop: propagate, then analyze components; if still ambiguous, branch on best cell.
    def snapshot():
        return [row[:] for row in state]

    def restore(snap):
        for r in range(R):
            state[r] = snap[r][:]

    def all_satisfied():
        for p in clues:
            unk, need = current_constraint(p)
            if unk:
                return False
            if need != 0:
                return False
        return True

    if not propagate():
        return "No Solution"

    # Main refinement loop: use exact component enumeration to force cells that are always mine/safe.
    progressed = True
    while progressed:
        progressed = False
        vars_set, active_clues = build_frontier()
        if not vars_set:
            break
        comps = connected_components(vars_set, active_clues)

        forced_assignments = []
        for comp_vars, comp_clues in comps:
            comp_vars_list = list(comp_vars)
            comp_clues_list = list(comp_clues)
            # Enumerate if component is moderate size; else skip (will handle by branching)
            if len(comp_vars_list) <= 22:
                total, mine_counts, idx = enumerate_component(comp_vars_list, comp_clues_list)
                if total == 0:
                    return "No Solution"
                for v in comp_vars_list:
                    i = idx[v]
                    if mine_counts[i] == 0:
                        forced_assignments.append((v, 0))
                    elif mine_counts[i] == total:
                        forced_assignments.append((v, 1))

        if forced_assignments:
            q = deque()
            for v, val in forced_assignments:
                if state[v[0]][v[1]] == -1:
                    if not set_cell(v, val, q, set(), set()):
                        return "No Solution"
                    progressed = True
            if not propagate():
                return "No Solution"

    if all_satisfied():
        # Output mines as 'F' in grid, others None
        out = [[None] * C for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if state[r][c] == 1:
                    out[r][c] = 'F'
        return str(out)

    # Controlled branching: pick an unknown variable that is in the frontier with maximum constraint degree.
    def pick_branch_cell():
        best = None
        best_deg = -1
        for r in range(R):
            for c in range(C):
                if state[r][c] == -1:
                    cell = (r, c)
                    deg = len(var_to_clues.get(cell, ()))
                    if deg > best_deg:
                        best = cell
                        best_deg = deg
        return best

    def search():
        if not propagate():
            return None
        if all_satisfied():
            return snapshot()

        # Try exact forcing again before branching
        vars_set, active_clues = build_frontier()
        if vars_set:
            comps = connected_components(vars_set, active_clues)
            for comp_vars, comp_clues in comps:
                if len(comp_vars) <= 22:
                    comp_vars_list = list(comp_vars)
                    comp_clues_list = list(comp_clues)
                    total, mine_counts, idx = enumerate_component(comp_vars_list, comp_clues_list)
                    if total == 0:
                        return None
                    forced = []
                    for v in comp_vars_list:
                        i = idx[v]
                        if mine_counts[i] == 0:
                            forced.append((v, 0))
                        elif mine_counts[i] == total:
                            forced.append((v, 1))
                    if forced:
                        snap = snapshot()
                        ok = True
                        q = deque()
                        for v, val in forced:
                            if state[v[0]][v[1]] == -1:
                                if not set_cell(v, val, q, set(), set()):
                                    ok = False
                                    break
                        if ok:
                            res = search()
                            if res is not None:
                                return res
                        restore(snap)
                        return None  # if forced led nowhere, no solution in this branch

        cell = pick_branch_cell()
        if cell is None:
            return None
        # Branch order: prefer mine if any adjacent clue still needs mines
        adj_clues = var_to_clues.get(cell, ())
        prefer_mine = False
        for p in adj_clues:
            unk, need = current_constraint(p)
            if need > 0:
                prefer_mine = True
                break
        vals = (1, 0) if prefer_mine else (0, 1)

        for val in vals:
            snap = snapshot()
            q = deque()
            if set_cell(cell, val, q, set(), set()) and not any_contradiction(set(adj_clues)):
                res = search()
                if res is not None:
                    return res
            restore(snap)
        return None

    final_state = search()
    if final_state is None:
        return "No Solution"

    # Build output
    out = [[None] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if final_state[r][c] == 1:
                out[r][c] = 'F'
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 1, None, 1, None, 3, None, 3, None], [2, 3, None, None, None, 4, None, None, 3, None], [1, None, None, None, None, None, None, 3, 3, None], [None, None, None, 2, None, 4, None, None, None, None], [None, None, None, None, None, 1, 0, None, 2, None], [None, 2, None, None, None, 4, 2, 3, None, None], [None, 0, None, 2, None, None, None, None, None, None], [None, 1, None, None, None, None, None, None, None, 2], [1, None, 1, None, None, 4, None, 2, None, 2], [None, None, None, None, None, 2, None, None, None, 1]]}
from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass
from typing import Dict, List, Optional, Set, Tuple, Iterable


# Minesweeper-style CSP solver with human-like deduction:
# - Local single-clue rules (all mines / all safe)
# - Subset rule between clue frontiers
# - Region decomposition into independent components
# - Exact cover-style enumeration within components (bounded) + propagation back
# No external solvers.


Coord = Tuple[int, int]


def solve(observation):
    grid = observation["data"]
    R, C = len(grid), len(grid[0]) if grid else 0

    def inb(r, c): return 0 <= r < R and 0 <= c < C

    # Precompute neighbors
    neigh = {}
    for r in range(R):
        for c in range(C):
            ns = []
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if inb(rr, cc):
                        ns.append((rr, cc))
            neigh[(r, c)] = tuple(ns)

    # Variables are all cells (including numbered), but mines can exist anywhere.
    # Constraints only arise from numbered cells: sum(mines in neighbors) == number.
    clues: Dict[Coord, int] = {}
    for r in range(R):
        for c in range(C):
            v = grid[r][c]
            if v is not None:
                clues[(r, c)] = int(v)

    all_cells = [(r, c) for r in range(R) for c in range(C)]

    # Domain for each cell: -1 unknown, 0 safe, 1 mine
    state = {cell: -1 for cell in all_cells}

    # Constraint representation: for each clue cell, track its neighbor variable set.
    clue_vars: Dict[Coord, Tuple[Coord, ...]] = {p: neigh[p] for p in clues}

    # For fast adjacency: which clues mention a cell
    cell_to_clues: Dict[Coord, List[Coord]] = defaultdict(list)
    for cp, vs in clue_vars.items():
        for v in vs:
            cell_to_clues[v].append(cp)

    def apply_assignment(cell: Coord, val: int, q: deque) -> bool:
        """Assign cell to 0/1; enqueue affected clues; return False if conflict."""
        cur = state[cell]
        if cur != -1:
            return cur == val
        state[cell] = val
        for cp in cell_to_clues.get(cell, ()):
            q.append(cp)
        return True

    def eval_clue(cp: Coord):
        """Return (mines_known, unknowns_list) for clue."""
        target = clues[cp]
        mines = 0
        unknowns = []
        for v in clue_vars[cp]:
            st = state[v]
            if st == 1:
                mines += 1
            elif st == -1:
                unknowns.append(v)
        return target, mines, unknowns

    def propagate_basic(q: deque) -> bool:
        """Local single-clue propagation."""
        while q:
            cp = q.popleft()
            target, mines, unknowns = eval_clue(cp)
            rem = target - mines
            if rem < 0 or rem > len(unknowns):
                return False
            if rem == 0 and unknowns:
                for v in unknowns:
                    if not apply_assignment(v, 0, q):
                        return False
            elif rem == len(unknowns) and unknowns:
                for v in unknowns:
                    if not apply_assignment(v, 1, q):
                        return False
        return True

    def frontier_constraints():
        """Build current constraint sets over unknown frontier vars."""
        cons = []
        for cp in clues:
            target, mines, unknowns = eval_clue(cp)
            rem = target - mines
            if unknowns:
                cons.append((cp, frozenset(unknowns), rem))
            else:
                if rem != 0:
                    return None  # conflict
        return cons

    def propagate_subsets() -> bool:
        """Subset rule between constraints A,B: if vars(A) subset vars(B) -> derive constraint on difference."""
        # We'll iteratively apply until no change.
        changed = True
        while changed:
            changed = False
            cons = frontier_constraints()
            if cons is None:
                return False
            # Group by variable set size to speed subset checks
            by_size = defaultdict(list)
            for cp, s, rem in cons:
                by_size[len(s)].append((cp, s, rem))

            # Build list sorted by size
            sizes = sorted(by_size)
            # Quick mapping for exact duplicates: rem consistency check
            seen = {}
            for cp, s, rem in cons:
                if s in seen and seen[s] != rem:
                    return False
                seen[s] = rem

            # Compare smaller sets against larger sets (bounded by frontier)
            cons_sorted = sorted(cons, key=lambda x: len(x[1]))
            for i, (cpA, sA, rA) in enumerate(cons_sorted):
                if len(sA) == 0:
                    continue
                for cpB, sB, rB in cons_sorted[i + 1:]:
                    if len(sA) > len(sB):
                        continue
                    if sA.issubset(sB):
                        diff = sB - sA
                        rD = rB - rA
                        if rD < 0 or rD > len(diff):
                            return False
                        # If derived constraint is tight, assign
                        if len(diff) == 0:
                            if rD != 0:
                                return False
                            continue
                        if rD == 0 or rD == len(diff):
                            q = deque()
                            val = 1 if rD == len(diff) else 0
                            for v in diff:
                                if state[v] == -1:
                                    if not apply_assignment(v, val, q):
                                        return False
                            if q:
                                if not propagate_basic(q):
                                    return False
                                changed = True
        return True

    def global_propagate() -> bool:
        """Run chained propagation until fixpoint."""
        q = deque(clues.keys())
        if not propagate_basic(q):
            return False
        if not propagate_subsets():
            return False
        # Another basic pass after subset may have added info
        q = deque(clues.keys())
        if not propagate_basic(q):
            return False
        return True

    # Initial propagation
    if not global_propagate():
        return "No Solution"

    def unknown_frontier_vars() -> Set[Coord]:
        """Unknown vars that appear in any active constraint."""
        s = set()
        for cp in clues:
            _, _, unk = eval_clue(cp)
            for v in unk:
                s.add(v)
        return s

    def build_components(frontier_vars: Set[Coord]):
        """Build independent components of frontier vars connected by shared clues."""
        # Build bipartite adjacency: var <-> clue if var in clue unknown set
        var_to_clues = defaultdict(set)
        clue_to_vars = {}
        active_clues = []
        for cp in clues:
            target, mines, unk = eval_clue(cp)
            rem = target - mines
            if unk:
                active_clues.append(cp)
                clue_to_vars[cp] = set(unk)
                for v in unk:
                    var_to_clues[v].add(cp)

        seen_vars = set()
        components = []
        for v in frontier_vars:
            if v in seen_vars:
                continue
            # BFS over vars/clues
            q = deque([v])
            comp_vars = set()
            comp_clues = set()
            seen_vars.add(v)
            while q:
                x = q.popleft()
                comp_vars.add(x)
                for cp in var_to_clues.get(x, ()):
                    if cp not in comp_clues:
                        comp_clues.add(cp)
                        for vv in clue_to_vars[cp]:
                            if vv not in seen_vars:
                                seen_vars.add(vv)
                                q.append(vv)
            components.append((comp_vars, comp_clues))
        return components

    @dataclass
    class CompModel:
        vars: List[Coord]
        clues: List[Coord]
        # For each clue, indices of vars in its neighborhood
        c2vidx: List[List[int]]
        # required mines remaining per clue
        req: List[int]

    def make_comp_model(comp_vars: Set[Coord], comp_clues: Set[Coord]) -> Optional[CompModel]:
        vars_list = list(comp_vars)
        vidx = {v: i for i, v in enumerate(vars_list)}
        clues_list = list(comp_clues)
        c2vidx = []
        req = []
        for cp in clues_list:
            target, mines, unk = eval_clue(cp)
            rem = target - mines
            if rem < 0 or rem > len(unk):
                return None
            idxs = [vidx[v] for v in unk]
            c2vidx.append(idxs)
            req.append(rem)
        return CompModel(vars_list, clues_list, c2vidx, req)

    def enumerate_component(model: CompModel, cap_solutions: int = 200000):
        """
        Enumerate all satisfying assignments for a component using backtracking with pruning.
        Returns:
          sol_count, must_mine(set of var idx), must_safe(set of var idx)
        """
        n = len(model.vars)
        m = len(model.clues)

        # For each var, which clues contain it
        v2c = [[] for _ in range(n)]
        for ci, idxs in enumerate(model.c2vidx):
            for vi in idxs:
                v2c[vi].append(ci)

        # Track for each clue: remaining required mines, remaining unassigned vars count
        req = model.req[:]
        remU = [len(idxs) for idxs in model.c2vidx]

        assign = [-1] * n
        order = list(range(n))
        # Heuristic: variables with high constraint degree first
        order.sort(key=lambda vi: -len(v2c[vi]))

        # For fast "must" derivation
        sol_count = 0
        mine_count = [0] * n  # across solutions

        def feasible_for_clue(ci: int) -> bool:
            r = req[ci]
            u = remU[ci]
            return 0 <= r <= u

        def dfs(k: int) -> bool:
            nonlocal sol_count
            if sol_count >= cap_solutions:
                return True  # stop early
            if k == n:
                # All assigned; all req must be 0
                for ci in range(m):
                    if req[ci] != 0:
                        return False
                sol_count += 1
                for i in range(n):
                    if assign[i] == 1:
                        mine_count[i] += 1
                return False

            vi = order[k]

            # Try safe then mine; value ordering: pick one that is forced-ish by constraints
            # Compute quick bounds: if any clue requires all remaining to be mines/safe for this variable
            # We'll just branch 0 then 1.
            for val in (0, 1):
                assign[vi] = val
                touched = []
                ok = True
                if v2c[vi]:
                    for ci in v2c[vi]:
                        # Update remU and req
                        touched.append(ci)
                        remU[ci] -= 1
                        if val == 1:
                            req[ci] -= 1
                        if not feasible_for_clue(ci):
                            ok = False
                            break
                if ok:
                    # Additional pruning: if any clue now has req==0 -> remaining vars in it must be safe,
                    # but handled later by propagation? Here, bound check sufficient.
                    stop = dfs(k + 1)
                    if stop:
                        # rollback before stopping
                        for ci in reversed(touched):
                            if val == 1:
                                req[ci] += 1
                            remU[ci] += 1
                        assign[vi] = -1
                        return True
                # rollback
                for ci in reversed(touched):
                    if val == 1:
                        req[ci] += 1
                    remU[ci] += 1
                assign[vi] = -1
            return False

        dfs(0)

        if sol_count == 0:
            return 0, set(), set()

        must_mine = {i for i in range(n) if mine_count[i] == sol_count}
        must_safe = {i for i in range(n) if mine_count[i] == 0}
        return sol_count, must_mine, must_safe

    def apply_component_inference() -> bool:
        """Decompose into components, enumerate each, and apply forced cells."""
        frontier = unknown_frontier_vars()
        if not frontier:
            # All constraints satisfied already
            return True

        comps = build_components(frontier)
        progress = False
        for comp_vars, comp_clues in comps:
            model = make_comp_model(comp_vars, comp_clues)
            if model is None:
                return False
            # If component too large, fall back to guided branching later.
            if len(model.vars) > 24:
                continue
            sol_count, must_mine_idx, must_safe_idx = enumerate_component(model)
            if sol_count == 0:
                return False
            if must_mine_idx or must_safe_idx:
                q = deque()
                for i in must_mine_idx:
                    v = model.vars[i]
                    if state[v] == -1:
                        if not apply_assignment(v, 1, q):
                            return False
                for i in must_safe_idx:
                    v = model.vars[i]
                    if state[v] == -1:
                        if not apply_assignment(v, 0, q):
                            return False
                if q:
                    if not propagate_basic(q):
                        return False
                    if not propagate_subsets():
                        return False
                    progress = True
        return True if progress else True

    if not apply_component_inference():
        return "No Solution"
    if not global_propagate():
        return "No Solution"

    def is_solved() -> bool:
        # All clues satisfied exactly
        for cp in clues:
            target, mines, unk = eval_clue(cp)
            if unk:
                return False
            if mines != target:
                return False
        return True

    def snapshot():
        return state.copy()

    def restore(snap):
        state.clear()
        state.update(snap)

    def choose_branch_var() -> Optional[Coord]:
        # Choose an unknown frontier variable with maximum constraint degree
        frontier = list(unknown_frontier_vars())
        if not frontier:
            # Any remaining unknowns not constrained can be safe (arbitrary) as long as clues satisfied
            for cell, st in state.items():
                if st == -1:
                    return cell
            return None
        frontier.sort(key=lambda v: -len(cell_to_clues.get(v, ())))
        return frontier[0]

    def search() -> bool:
        if not global_propagate():
            return False
        if not apply_component_inference():
            return False
        if not global_propagate():
            return False
        if is_solved():
            # Any unconstrained unknowns can be set safe
            for cell in all_cells:
                if state[cell] == -1:
                    state[cell] = 0
            return True

        v = choose_branch_var()
        if v is None:
            return is_solved()

        # Branching with immediate contradiction check
        for val in (0, 1):
            snap = snapshot()
            q = deque()
            if apply_assignment(v, val, q) and propagate_basic(q):
                if search():
                    return True
            restore(snap)
        return False

    if not search():
        return "No Solution"

    # Build answer grid with 'F' for mines else None
    ans = [[None for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if state[(r, c)] == 1:
                ans[r][c] = "F"
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

