from functools import lru_cache

# Cell states
UNK = -1
WHT = 0
BLK = 1


def solve(observation):
    row_clues = observation["row_black_runs"]
    col_clues = observation["col_black_runs"]
    R = len(row_clues)
    C = len(col_clues)

    # Quick feasibility checks
    def min_len(clue):
        if not clue:
            return 0
        return sum(clue) + (len(clue) - 1)

    for r in range(R):
        if min_len(row_clues[r]) > C:
            return "No Solution"
    for c in range(C):
        if min_len(col_clues[c]) > R:
            return "No Solution"

    # Grid
    grid = [[UNK] * C for _ in range(R)]

    # Incremental column/row assignment bookkeeping
    row_assigned = [0] * R
    col_assigned = [0] * C

    # For quick rollback, store stack of (r,c,old)
    trail = []

    def set_cell(r, c, val):
        old = grid[r][c]
        if old == val:
            return True
        if old != UNK and old != val:
            return False
        trail.append((r, c, old))
        grid[r][c] = val
        row_assigned[r] += 1
        col_assigned[c] += 1
        return True

    def undo(to_len):
        while len(trail) > to_len:
            r, c, old = trail.pop()
            row_assigned[r] -= 1
            col_assigned[c] -= 1
            grid[r][c] = old

    # Line pattern generation with caching based on (length, clues, mask_known, mask_vals)
    # Represent known cells as bitmasks: known_mask bits set where known, val_mask bits set where known BLK
    @lru_cache(maxsize=None)
    def gen_patterns(length, clues_tup, known_mask, val_mask):
        clues = list(clues_tup)

        # Build list of patterns as bitmasks of black cells
        res = []

        # Special: no clues => all white
        if not clues:
            # must be compatible with known blacks
            if val_mask & known_mask:
                return tuple()
            return (0,)

        # Precompute suffix minimal lengths for pruning
        k = len(clues)
        suffix_min = [0] * (k + 1)
        suffix_min[k] = 0
        for i in range(k - 1, -1, -1):
            suffix_min[i] = suffix_min[i + 1] + clues[i] + (1 if i < k - 1 else 0)

        def compatible_run(pos, run_len):
            # Ensure that known whites in [pos, pos+run_len) don't conflict with black
            # and if known black outside allowed, handled elsewhere by final compatibility.
            segment_mask = ((1 << run_len) - 1) << pos
            known_in_seg = known_mask & segment_mask
            known_black_in_seg = val_mask & segment_mask
            # If any known cell in seg is white => conflict means known but not black
            if known_in_seg != known_black_in_seg:
                return False
            return True

        def compatible_white(pos):
            # if cell known black but we want white
            bit = 1 << pos
            if (known_mask & bit) and (val_mask & bit):
                return False
            return True

        def dfs(i, pos, black_mask):
            # i: clue index, pos: next position to consider (start for this run or whites)
            if i == k:
                # remaining must be white-compatible
                # Check known blacks in remaining segment (pos..length-1) would violate
                rem_mask = ((1 << (length - pos)) - 1) << pos if pos < length else 0
                if (val_mask & known_mask & rem_mask) != 0:
                    return
                # Also ensure black_mask includes all known blacks in earlier part automatically via compat checks.
                res.append(black_mask)
                return

            # Latest start for this run considering remaining minimal
            run = clues[i]
            min_after = suffix_min[i + 1]
            latest_start = length - (run + min_after)
            # Try all starts from pos to latest_start
            for s in range(pos, latest_start + 1):
                # cells pos..s-1 are whites
                ok = True
                for w in range(pos, s):
                    if not compatible_white(w):
                        ok = False
                        break
                if not ok:
                    continue
                # run cells must be black-compatible
                if not compatible_run(s, run):
                    continue
                new_mask = black_mask | (((1 << run) - 1) << s)
                next_pos = s + run
                if i < k - 1:
                    # separator white required at next_pos
                    if next_pos >= length:
                        continue
                    if not compatible_white(next_pos):
                        continue
                    next_pos += 1
                dfs(i + 1, next_pos, new_mask)

        dfs(0, 0, 0)

        # Final compatibility: ensure all known blacks are included
        # (This is already enforced for black segments; but include global check.)
        km = known_mask
        vb = val_mask & km
        out = []
        for m in res:
            if (m & vb) == vb:
                # ensure known whites aren't black
                if (m & (km ^ vb)) == 0:
                    out.append(m)
        return tuple(out)

    def line_known_masks(cells):
        known_mask = 0
        val_mask = 0
        for i, v in enumerate(cells):
            if v != UNK:
                known_mask |= (1 << i)
                if v == BLK:
                    val_mask |= (1 << i)
        return known_mask, val_mask

    def intersect_forced(patterns, length):
        # Returns forced_black_mask, forced_white_mask (over length bits)
        if not patterns:
            return None
        all_ones = (1 << length) - 1
        and_black = all_ones
        or_black = 0
        for p in patterns:
            and_black &= p
            or_black |= p
        forced_black = and_black
        forced_white = (~or_black) & all_ones
        return forced_black, forced_white

    # Constraint propagation: iterate rows/cols, derive forced cells from all compatible patterns
    def propagate(queue=None):
        # queue elements: ("r", idx) or ("c", idx)
        if queue is None:
            queue = [("r", i) for i in range(R)] + [("c", j) for j in range(C)]
        inq = set(queue)

        while queue:
            kind, idx = queue.pop()
            inq.discard((kind, idx))

            if kind == "r":
                cells = grid[idx]
                length = C
                clues = tuple(row_clues[idx])
                known_mask, val_mask = line_known_masks(cells)
                patterns = gen_patterns(length, clues, known_mask, val_mask)
                if not patterns:
                    return False
                forced = intersect_forced(patterns, length)
                if forced is None:
                    return False
                fblack, fwhite = forced
                for c in range(C):
                    bit = 1 << c
                    if fblack & bit:
                        if not set_cell(idx, c, BLK):
                            return False
                        # affected column
                        key = ("c", c)
                        if key not in inq:
                            queue.append(key); inq.add(key)
                    elif fwhite & bit:
                        if not set_cell(idx, c, WHT):
                            return False
                        key = ("c", c)
                        if key not in inq:
                            queue.append(key); inq.add(key)

            else:
                # column
                cells = [grid[r][idx] for r in range(R)]
                length = R
                clues = tuple(col_clues[idx])
                known_mask, val_mask = line_known_masks(cells)
                patterns = gen_patterns(length, clues, known_mask, val_mask)
                if not patterns:
                    return False
                forced = intersect_forced(patterns, length)
                if forced is None:
                    return False
                fblack, fwhite = forced
                for r in range(R):
                    bit = 1 << r
                    if fblack & bit:
                        if not set_cell(r, idx, BLK):
                            return False
                        key = ("r", r)
                        if key not in inq:
                            queue.append(key); inq.add(key)
                    elif fwhite & bit:
                        if not set_cell(r, idx, WHT):
                            return False
                        key = ("r", r)
                        if key not in inq:
                            queue.append(key); inq.add(key)

        return True

    def solved():
        for r in range(R):
            for c in range(C):
                if grid[r][c] == UNK:
                    return False
        return True

    def choose_branch():
        # Human-like: pick the most constrained line (fewest patterns) among those with unknowns.
        best = None  # (num_patterns, kind, idx, patterns, length)
        for r in range(R):
            if row_assigned[r] == C:
                continue
            known_mask, val_mask = line_known_masks(grid[r])
            pats = gen_patterns(C, tuple(row_clues[r]), known_mask, val_mask)
            if not pats:
                return None
            if best is None or len(pats) < best[0]:
                best = (len(pats), "r", r, pats, C)
                if len(pats) == 1:
                    break
        for c in range(C):
            if col_assigned[c] == R:
                continue
            cells = [grid[r][c] for r in range(R)]
            known_mask, val_mask = line_known_masks(cells)
            pats = gen_patterns(R, tuple(col_clues[c]), known_mask, val_mask)
            if not pats:
                return None
            if best is None or len(pats) < best[0]:
                best = (len(pats), "c", c, pats, R)
                if len(pats) == 1:
                    break
        return best

    def apply_pattern(kind, idx, pat_mask, length):
        # Assign all cells in line according to mask (black=1 else white)
        if kind == "r":
            for c in range(C):
                v = BLK if (pat_mask >> c) & 1 else WHT
                if not set_cell(idx, c, v):
                    return False
        else:
            for r in range(R):
                v = BLK if (pat_mask >> r) & 1 else WHT
                if not set_cell(r, idx, v):
                    return False
        return True

    def dfs():
        t0 = len(trail)
        if not propagate():
            undo(t0)
            return False
        if solved():
            return True

        choice = choose_branch()
        if choice is None:
            undo(t0)
            return False
        _, kind, idx, patterns, length = choice

        # Try patterns in an order that tends to propagate faster:
        # prefer patterns that match more knowns (already ensured), then higher black count mid (heuristic)
        def score(p):
            return -p.bit_count()

        ordered = sorted(patterns, key=score)
        for pat in ordered:
            t1 = len(trail)
            if apply_pattern(kind, idx, pat, length):
                # enqueue affected opposite lines by full line assignment via propagate() call in recursion
                if dfs():
                    return True
            undo(t1)

        undo(t0)
        return False

    if not dfs():
        return "No Solution"

    # Return grid of 'B' and None as a Python literal string
    out = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if grid[r][c] == BLK else None)
        out.append(row)
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

