from functools import lru_cache
from collections import deque

# Cell states
UNK = -1
WHT = 0
BLK = 1

def solve(observation):
    rows = observation["row_black_runs"]
    cols = observation["col_black_runs"]
    H, W = len(rows), len(cols)

    # Basic feasibility checks
    for i, clues in enumerate(rows):
        if sum(clues) + max(0, len(clues) - 1) > W:
            return "No Solution"
    for j, clues in enumerate(cols):
        if sum(clues) + max(0, len(clues) - 1) > H:
            return "No Solution"

    grid = [[UNK] * W for _ in range(H)]

    # Precompute all possible line patterns for each row/col (as bitmasks and also as int tuple of 0/1)
    @lru_cache(None)
    def gen_patterns(L, clues):
        clues = tuple(clues)
        if not clues:
            return (0,),  # single mask: all white
        k = len(clues)
        total_black = sum(clues)
        min_len = total_black + (k - 1)
        extra = L - min_len
        if extra < 0:
            return tuple(),  # no patterns

        # Distribute extra whites into (k+1) gaps: before first, between runs (k-1), after last
        # Between gaps have at least 1 already included in min_len; we add extra to any gap.
        masks = []

        # Generate compositions of 'extra' into (k+1) parts efficiently via recursion (small sizes typical)
        parts = [0] * (k + 1)

        def rec(idx, remaining):
            if idx == k:
                parts[idx] = remaining
                # Build pattern
                pos = 0
                pos += parts[0]  # leading whites
                mask = 0
                for r in range(k):
                    run = clues[r]
                    # set run blacks
                    for t in range(run):
                        mask |= 1 << (pos + t)
                    pos += run
                    if r != k - 1:
                        pos += 1  # mandatory white between runs
                        pos += parts[r + 1]  # extra whites in between gap
                pos += parts[k]  # trailing whites
                # pos should be L
                masks.append(mask)
                return
            for x in range(remaining + 1):
                parts[idx] = x
                rec(idx + 1, remaining - x)

        rec(0, extra)
        return tuple(masks),

    # Wrapper to get just masks
    @lru_cache(None)
    def patterns_for(L, clues):
        return gen_patterns(L, tuple(clues))[0]

    row_patterns = [patterns_for(W, tuple(rows[i])) for i in range(H)]
    col_patterns = [patterns_for(H, tuple(cols[j])) for j in range(W)]

    if any(len(pats) == 0 for pats in row_patterns) or any(len(pats) == 0 for pats in col_patterns):
        return "No Solution"

    # For faster filtering, precompute per line: for each position, bitset of patterns that have black/white at pos
    # We'll represent pattern sets as list of masks, and maintain an active boolean list via indices set.
    def build_index(pats, L):
        # returns black_at[pos] = bitset int of pattern indices where cell is black, similarly white_at
        n = len(pats)
        black_at = [0] * L
        white_at = [0] * L
        for idx, m in enumerate(pats):
            bit = 1 << idx
            for pos in range(L):
                if (m >> pos) & 1:
                    black_at[pos] |= bit
                else:
                    white_at[pos] |= bit
        allset = (1 << n) - 1
        return black_at, white_at, allset

    row_idx = [build_index(row_patterns[i], W) for i in range(H)]
    col_idx = [build_index(col_patterns[j], H) for j in range(W)]

    # Active pattern sets as bitsets
    row_active = [row_idx[i][2] for i in range(H)]
    col_active = [col_idx[j][2] for j in range(W)]

    # Utility: assign a cell and enqueue affected lines
    q = deque()

    def enqueue_cell(r, c):
        q.append(("cell", r, c))

    def set_cell(r, c, val):
        cur = grid[r][c]
        if cur == val:
            return True
        if cur != UNK and cur != val:
            return False
        grid[r][c] = val
        q.append(("row", r))
        q.append(("col", c))
        return True

    # Filter line patterns based on current grid assignments
    def filter_row(r):
        pats = row_patterns[r]
        black_at, white_at, _ = row_idx[r]
        active = row_active[r]
        if active == 0:
            return False
        # Apply constraints from grid
        for c in range(W):
            v = grid[r][c]
            if v == UNK:
                continue
            if v == BLK:
                active &= black_at[c]
            else:
                active &= white_at[c]
            if active == 0:
                return False
        if active != row_active[r]:
            row_active[r] = active
            # affected cells in this row may now be forced
            for c in range(W):
                if grid[r][c] == UNK:
                    q.append(("cell", r, c))
        return True

    def filter_col(c):
        pats = col_patterns[c]
        black_at, white_at, _ = col_idx[c]
        active = col_active[c]
        if active == 0:
            return False
        for r in range(H):
            v = grid[r][c]
            if v == UNK:
                continue
            if v == BLK:
                active &= black_at[r]
            else:
                active &= white_at[r]
            if active == 0:
                return False
        if active != col_active[c]:
            col_active[c] = active
            for r in range(H):
                if grid[r][c] == UNK:
                    q.append(("cell", r, c))
        return True

    # Deduce forced cells from line active patterns (intersection logic)
    def deduce_cell(r, c):
        if grid[r][c] != UNK:
            return True
        # From row active: if all patterns have black => black; if all have white => white
        ra = row_active[r]
        ca = col_active[c]
        if ra == 0 or ca == 0:
            return False

        # Compute row possibility at (r,c)
        rb = row_idx[r][0][c]  # bitset where black
        rw = row_idx[r][1][c]
        row_can_black = (ra & rb) != 0
        row_can_white = (ra & rw) != 0

        cb = col_idx[c][0][r]
        cw = col_idx[c][1][r]
        col_can_black = (ca & cb) != 0
        col_can_white = (ca & cw) != 0

        can_black = row_can_black and col_can_black
        can_white = row_can_white and col_can_white

        if not can_black and not can_white:
            return False
        if can_black and not can_white:
            return set_cell(r, c, BLK)
        if can_white and not can_black:
            return set_cell(r, c, WHT)
        return True

    # More powerful: after filtering, if a line's active patterns all agree on a cell value, assign it.
    # Implemented implicitly by deduce_cell + cell events, but we also can batch from a line for speed.
    def deduce_from_row(r):
        ra = row_active[r]
        if ra == 0:
            return False
        rb_list, rw_list, _ = row_idx[r]
        # Determine consensus by checking if (ra & rb)==0 or (ra & rw)==0
        for c in range(W):
            if grid[r][c] != UNK:
                continue
            if (ra & rb_list[c]) == 0:
                if not set_cell(r, c, WHT):
                    return False
            elif (ra & rw_list[c]) == 0:
                if not set_cell(r, c, BLK):
                    return False
        return True

    def deduce_from_col(c):
        ca = col_active[c]
        if ca == 0:
            return False
        cb_list, cw_list, _ = col_idx[c]
        for r in range(H):
            if grid[r][c] != UNK:
                continue
            if (ca & cb_list[r]) == 0:
                if not set_cell(r, c, WHT):
                    return False
            elif (ca & cw_list[r]) == 0:
                if not set_cell(r, c, BLK):
                    return False
        return True

    # Propagation loop
    def propagate():
        # Seed queues with all lines once
        for r in range(H):
            q.append(("row", r))
        for c in range(W):
            q.append(("col", c))
        while q:
            typ, idx, *rest = q.popleft()
            if typ == "row":
                r = idx
                if not filter_row(r):
                    return False
                if not deduce_from_row(r):
                    return False
            elif typ == "col":
                c = idx
                if not filter_col(c):
                    return False
                if not deduce_from_col(c):
                    return False
            else:
                r = idx
                c = rest[0]
                if not deduce_cell(r, c):
                    return False
        return True

    # Choose next branching cell using MRV: smallest (row_can_black/white & col_can_black/white) options.
    def pick_cell():
        best = None
        best_score = 3
        for r in range(H):
            ra = row_active[r]
            if ra == 0:
                return None
            rb_list, rw_list, _ = row_idx[r]
            for c in range(W):
                if grid[r][c] != UNK:
                    continue
                ca = col_active[c]
                if ca == 0:
                    return None
                cb_list, cw_list, _ = col_idx[c]

                can_black = (ra & rb_list[c]) != 0 and (ca & cb_list[r]) != 0
                can_white = (ra & rw_list[c]) != 0 and (ca & cw_list[r]) != 0
                opts = (1 if can_white else 0) + (1 if can_black else 0)
                if opts == 0:
                    return None
                if opts < best_score:
                    best_score = opts
                    best = (r, c, can_black, can_white)
                    if best_score == 1:
                        return best
        return best

    def snapshot():
        return (
            [row_active[i] for i in range(H)],
            [col_active[j] for j in range(W)],
            [grid[r][:] for r in range(H)],
        )

    def restore(snap):
        ra, ca, g = snap
        for i in range(H):
            row_active[i] = ra[i]
        for j in range(W):
            col_active[j] = ca[j]
        for r in range(H):
            grid[r] = g[r]
        q.clear()

    def is_solved():
        for r in range(H):
            for c in range(W):
                if grid[r][c] == UNK:
                    return False
        return True

    # Depth-first with strong propagation; not naive due to pattern-domain pruning.
    def dfs():
        if not propagate():
            return False
        if is_solved():
            return True
        choice = pick_cell()
        if choice is None:
            return False
        r, c, can_black, can_white = choice
        # Value ordering: try the value that is more constrained (reduces patterns more)
        # Estimate by counting compatible patterns in row/col.
        def compat_count(val):
            if val == BLK:
                rr = row_active[r] & row_idx[r][0][c]
                cc = col_active[c] & col_idx[c][0][r]
            else:
                rr = row_active[r] & row_idx[r][1][c]
                cc = col_active[c] & col_idx[c][1][r]
            # popcount on intersection sizes
            return (rr.bit_count(), cc.bit_count())

        candidates = []
        if can_black:
            candidates.append(BLK)
        if can_white:
            candidates.append(WHT)
        if len(candidates) == 2:
            b = compat_count(BLK)
            w = compat_count(WHT)
            # Prefer smaller product of remaining counts
            if b[0] * b[1] > w[0] * w[1]:
                candidates = [WHT, BLK]

        snap = snapshot()
        for val in candidates:
            restore(snap)
            if set_cell(r, c, val) and dfs():
                return True
        restore(snap)
        return False

    if not dfs():
        return "No Solution"

    # Build output grid with 'B' and None
    out = [[('B' if grid[r][c] == BLK else None) for c in range(W)] for r in range(H)]
    return repr(out)

