from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple, Set

# Hashiwokakero (Bridges) solver with human-like deduction + aggressive propagation + limited branching.
# No external solvers used.

Coord = Tuple[int, int]
EdgeKey = Tuple[int, int]  # (edge_id, count) internal
BridgeDict = Dict[Tuple[Coord, Coord], int]


@dataclass(frozen=True)
class Island:
    id: int
    r: int
    c: int
    demand: int


@dataclass(frozen=True)
class Edge:
    id: int
    a: int  # island id
    b: int  # island id
    # geometric segment endpoints (cells on grid): from island cell center to island cell center, orthogonal
    r1: int
    c1: int
    r2: int
    c2: int
    # open cells between islands (exclusive)
    cells: Tuple[Coord, ...]
    # crossing edges ids (precomputed)
    crosses: Tuple[int, ...]


class Contradiction(Exception):
    pass


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    islands: List[Island] = []
    id_at: Dict[Coord, int] = {}
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if v is not None and v != 0:
                iid = len(islands)
                islands.append(Island(iid, r, c, int(v)))
                id_at[(r, c)] = iid

    if not islands:
        return "No Solution"

    # Build candidate edges between visible islands in four directions (orthogonal line of sight).
    edges: List[Edge] = []
    edge_of_pair: Dict[Tuple[int, int], int] = {}

    # Precompute island positions per row/col for fast neighbor scan
    row_islands = defaultdict(list)
    col_islands = defaultdict(list)
    for isl in islands:
        row_islands[isl.r].append(isl)
        col_islands[isl.c].append(isl)
    for r in row_islands:
        row_islands[r].sort(key=lambda x: x.c)
    for c in col_islands:
        col_islands[c].sort(key=lambda x: x.r)

    def add_edge(a: Island, b: Island, cells: List[Coord]):
        eid = len(edges)
        key = (min(a.id, b.id), max(a.id, b.id))
        edge_of_pair[key] = eid
        edges.append(
            Edge(
                id=eid,
                a=a.id,
                b=b.id,
                r1=a.r,
                c1=a.c,
                r2=b.r,
                c2=b.c,
                cells=tuple(cells),
                crosses=tuple(),  # fill later
            )
        )

    # Horizontal neighbors
    for r, lst in row_islands.items():
        for i in range(len(lst) - 1):
            a, b = lst[i], lst[i + 1]
            cells = [(r, c) for c in range(a.c + 1, b.c)]
            add_edge(a, b, cells)

    # Vertical neighbors
    for c, lst in col_islands.items():
        for i in range(len(lst) - 1):
            a, b = lst[i], lst[i + 1]
            cells = [(r, c) for r in range(a.r + 1, b.r)]
            add_edge(a, b, cells)

    m = len(edges)
    if m == 0:
        return "No Solution"

    # Build crossings map: two edges cross if one horizontal and one vertical intersect at a grid cell,
    # not at an island cell, and intersection point lies within both edges' open cells.
    # We use occupied cell sets for each edge for quick intersection.
    edge_cells_sets = [set(e.cells) for e in edges]
    crosses = [[] for _ in range(m)]
    for i in range(m):
        ei = edges[i]
        hi = (ei.r1 == ei.r2)
        for j in range(i + 1, m):
            ej = edges[j]
            hj = (ej.r1 == ej.r2)
            if hi == hj:
                continue
            # Intersect if open-cell sets intersect
            inter = edge_cells_sets[i] & edge_cells_sets[j]
            if inter:
                crosses[i].append(j)
                crosses[j].append(i)
    # Recreate edges with crosses filled
    edges = [
        Edge(
            id=e.id,
            a=e.a,
            b=e.b,
            r1=e.r1,
            c1=e.c1,
            r2=e.r2,
            c2=e.c2,
            cells=e.cells,
            crosses=tuple(crosses[e.id]),
        )
        for e in edges
    ]

    # adjacency
    inc_edges: List[List[int]] = [[] for _ in range(len(islands))]
    for e in edges:
        inc_edges[e.a].append(e.id)
        inc_edges[e.b].append(e.id)

    # Domains: each edge count in {0,1,2}
    dom_lo = [0] * m
    dom_hi = [2] * m

    # State of decided edges: -1 undecided else fixed 0/1/2
    fixed = [-1] * m

    # Remaining demand per island
    rem = [isl.demand for isl in islands]

    # For connectivity: DSU with potentials (we use incremental DSU rebuild on demand for simplicity + pruning)
    # We'll check feasibility of connectivity late and during propagation via articulation-like pruning:
    # - If some island has rem>0 but has no available capacity to connect, contradiction.
    # - If even with max bridges graph could be disconnected into components with no possible connecting edges, contradiction.
    #
    # We'll compute component graph using "possible edges" where dom_hi>0 and not forced 0 by crossings.

    def other_end(eid: int, vid: int) -> int:
        e = edges[eid]
        return e.b if e.a == vid else e.a

    # Crossing constraints: if an edge is fixed to >0, all crossing edges must be fixed to 0.
    def assign(eid: int, val: int, queue: deque):
        nonlocal fixed, dom_lo, dom_hi
        if val < dom_lo[eid] or val > dom_hi[eid]:
            raise Contradiction()
        if fixed[eid] != -1:
            if fixed[eid] != val:
                raise Contradiction()
            return
        fixed[eid] = val
        dom_lo[eid] = dom_hi[eid] = val
        queue.append(("edge_fixed", eid))

    def tighten(eid: int, lo: int, hi: int, queue: deque):
        nonlocal dom_lo, dom_hi, fixed
        if lo > dom_lo[eid]:
            dom_lo[eid] = lo
            queue.append(("dom", eid))
        if hi < dom_hi[eid]:
            dom_hi[eid] = hi
            queue.append(("dom", eid))
        if dom_lo[eid] > dom_hi[eid]:
            raise Contradiction()
        if dom_lo[eid] == dom_hi[eid] and fixed[eid] == -1:
            fixed[eid] = dom_lo[eid]
            queue.append(("edge_fixed", eid))

    def compute_island_bounds(vid: int):
        # sum of min/max possible incident bridges at island
        lo = 0
        hi = 0
        for eid in inc_edges[vid]:
            lo += dom_lo[eid]
            hi += dom_hi[eid]
        return lo, hi

    def build_possible_graph() -> List[List[int]]:
        g = [[] for _ in range(len(islands))]
        for e in edges:
            if dom_hi[e.id] <= 0:
                continue
            # If either endpoint already satisfied (rem=0) we still may need connections for global connectivity,
            # so keep edge if it could carry >0 (dom_hi>0).
            g[e.a].append(e.b)
            g[e.b].append(e.a)
        return g

    def connectivity_feasible():
        # Must be possible to connect all islands in one component using edges with dom_hi>0.
        g = build_possible_graph()
        seen = [False] * len(islands)
        q = deque([0])
        seen[0] = True
        while q:
            v = q.popleft()
            for w in g[v]:
                if not seen[w]:
                    seen[w] = True
                    q.append(w)
        return all(seen)

    def apply_basic_deductions(queue: deque):
        # Keep applying local constraints akin to human techniques.
        changed = True
        while changed:
            changed = False

            # 1) Crossing eliminations from fixed edges
            for eid in range(m):
                if fixed[eid] > 0:
                    for cid in edges[eid].crosses:
                        if dom_hi[cid] != 0:
                            tighten(cid, 0, 0, queue)
                            changed = True

            # 2) Island demand bounds: for each island, enforce sum(dom_lo)<=demand<=sum(dom_hi)
            for v in range(len(islands)):
                lo, hi = compute_island_bounds(v)
                d = islands[v].demand
                if lo > d or hi < d:
                    raise Contradiction()

                # If sum max equals demand -> all incident edges set to max
                if hi == d:
                    for eid in inc_edges[v]:
                        if dom_hi[eid] != dom_lo[eid]:
                            tighten(eid, dom_hi[eid], dom_hi[eid], queue)
                            changed = True

                # If sum min equals demand -> all incident edges set to min
                if lo == d:
                    for eid in inc_edges[v]:
                        if dom_hi[eid] != dom_lo[eid]:
                            tighten(eid, dom_lo[eid], dom_lo[eid], queue)
                            changed = True

                # For each incident edge: enforce tighter bounds:
                # edge <= demand - (sum others' min)
                # edge >= demand - (sum others' max)
                sum_min = lo
                sum_max = hi
                for eid in inc_edges[v]:
                    emin, emax = dom_lo[eid], dom_hi[eid]
                    other_min = sum_min - emin
                    other_max = sum_max - emax
                    new_hi = min(emax, d - other_min)
                    new_lo = max(emin, d - other_max)
                    if new_lo != emin or new_hi != emax:
                        tighten(eid, new_lo, new_hi, queue)
                        changed = True

            # 3) Degree-1 forced: if island has k available edges and demand equals 2*k, force all to 2
            # and if demand equals k, force all to 1 with max=1? (not always, because could be 0/2 mix)
            # We'll do stronger safe rules:
            for v in range(len(islands)):
                avail = [eid for eid in inc_edges[v] if dom_hi[eid] > 0]
                if not avail:
                    continue
                d = islands[v].demand
                # count edges that can still be nonzero, and their max sum
                maxsum = sum(dom_hi[eid] for eid in avail)
                if maxsum == d:
                    for eid in avail:
                        tighten(eid, dom_hi[eid], dom_hi[eid], queue)
                        changed = True
                # If only one available edge, force it to exactly d (bounded by [0,2])
                if len(avail) == 1:
                    eid = avail[0]
                    tighten(eid, d, d, queue)
                    changed = True

            # 4) Connectivity feasibility pruning
            if not connectivity_feasible():
                raise Contradiction()

    # Propagation using a queue; since our deductions do full scans, queue is mostly for future extension.
    def propagate():
        queue = deque()
        apply_basic_deductions(queue)

    def is_complete():
        return all(fixed[eid] != -1 for eid in range(m)) and all(
            sum(fixed[eid] for eid in inc_edges[v]) == islands[v].demand for v in range(len(islands))
        )

    def final_connected():
        # Using edges with fixed>0
        g = [[] for _ in range(len(islands))]
        for e in edges:
            if fixed[e.id] > 0:
                g[e.a].append(e.b)
                g[e.b].append(e.a)
        seen = [False] * len(islands)
        q = deque([0])
        seen[0] = True
        while q:
            v = q.popleft()
            for w in g[v]:
                if not seen[w]:
                    seen[w] = True
                    q.append(w)
        return all(seen)

    def choose_edge():
        # MRV + impact heuristic:
        # pick undecided edge with smallest domain size; tie-break by higher "pressure" from endpoints.
        best = None
        best_key = None
        for eid in range(m):
            if fixed[eid] != -1:
                continue
            lo, hi = dom_lo[eid], dom_hi[eid]
            size = hi - lo + 1
            if size <= 1:
                continue
            e = edges[eid]
            # pressure: remaining needed around endpoints (d - sum(min)) etc approximate by demand
            pres = islands[e.a].demand + islands[e.b].demand
            key = (size, -pres)
            if best is None or key < best_key:
                best, best_key = eid, key
        return best

    def snapshot():
        return (fixed[:], dom_lo[:], dom_hi[:])

    def restore(snap):
        nonlocal fixed, dom_lo, dom_hi
        fixed, dom_lo, dom_hi = (snap[0][:], snap[1][:], snap[2][:])

    def dfs():
        try:
            propagate()
        except Contradiction:
            return False

        if is_complete():
            return final_connected()

        eid = choose_edge()
        if eid is None:
            return False

        # Value ordering: try higher first if endpoints have high demand pressure.
        vals = list(range(dom_lo[eid], dom_hi[eid] + 1))
        e = edges[eid]
        # prefer 2, then 1, then 0 generally (connectivity), but respect domain
        pref = [2, 1, 0]
        vals = [v for v in pref if v in vals] + [v for v in vals if v not in pref]

        snap = snapshot()
        for v in vals:
            try:
                q = deque()
                assign(eid, v, q)
                # Immediate crossing propagation
                if v > 0:
                    for cid in edges[eid].crosses:
                        tighten(cid, 0, 0, q)
                if dfs():
                    return True
            except Contradiction:
                pass
            restore(snap)
        return False

    ok = dfs()
    if not ok:
        return "No Solution"

    # Build answer dict in required format {((r1,c1),(r2,c2)): count} with endpoints ordered as given
    ans: BridgeDict = {}
    for e in edges:
        v = fixed[e.id]
        if v and v > 0:
            a = (islands[e.a].r, islands[e.a].c)
            b = (islands[e.b].r, islands[e.b].c)
            if a > b:
                a, b = b, a
            ans[(a, b)] = v
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[4, None, 3, None, None, 8, 9, None, 7], [2, None, None, None, None, 9, 3, 8, None], [None, None, None, None, 3, None, 1, None, None], [None, 5, 2, 1, None, 6, None, None, None], [None, None, None, None, None, None, None, None, None], [None, None, None, 5, None, 4, 6, 7, None], [None, None, 6, None, 4, None, None, None, None], [None, 1, 7, 3, None, None, None, None, 9], [3, None, 4, 7, None, None, 2, None, 6]], 'unit': '3x3'}
# Generalized Sudoku solver (supports RxC subgrids like 3x3, 3x4, 4x4 -> N = R*C)
# Human-like deduction: singles, hidden singles, locked candidates, naked pairs, pointing pairs/triples,
# plus efficient propagation with bitmasks and MRV branching as a last resort.

from collections import defaultdict

def solve(observation):
    grid = observation["data"]
    unit = observation["unit"]
    try:
        r, c = unit.lower().split("x")
        R, C = int(r), int(c)
    except Exception:
        return "No Solution"
    N = R * C
    if len(grid) != N or any(len(row) != N for row in grid):
        return "No Solution"

    ALL = (1 << N) - 1

    # Precompute units (rows, cols, boxes) and peers
    rows = [list(range(i * N, (i + 1) * N)) for i in range(N)]
    cols = [list(range(i, N * N, N)) for i in range(N)]
    boxes = []
    for br in range(0, N, R):
        for bc in range(0, N, C):
            b = []
            for rr in range(br, br + R):
                base = rr * N
                for cc in range(bc, bc + C):
                    b.append(base + cc)
            boxes.append(b)

    units_of = [[] for _ in range(N * N)]
    for u in rows + cols + boxes:
        for cell in u:
            units_of[cell].append(u)

    peers = [set() for _ in range(N * N)]
    for i in range(N * N):
        s = set()
        for u in units_of[i]:
            s.update(u)
        s.discard(i)
        peers[i] = s

    # Helpers
    def bit(n):  # n in 1..N
        return 1 << (n - 1)

    def popcount(x):
        return x.bit_count()

    def lsb_index(x):  # x has exactly 1 bit set
        return (x & -x).bit_length() - 1

    def mask_to_vals(m):
        while m:
            b = m & -m
            yield b.bit_length()
            m -= b

    # State: candidates bitmask for each cell
    cand = [ALL] * (N * N)
    fixed = [0] * (N * N)

    # Initialize fixed from grid
    for r in range(N):
        for c_ in range(N):
            v = grid[r][c_]
            idx = r * N + c_
            if v is None:
                continue
            if not (1 <= v <= N):
                return "No Solution"
            fixed[idx] = v

    # Validate and apply initial assignments
    def assign(idx, v, trail):
        """Set cell idx to value v (1..N). Returns False if contradiction."""
        m = bit(v)
        if cand[idx] == m:
            return True
        if (cand[idx] & m) == 0:
            return False
        # record changes for backtracking
        trail.append((idx, cand[idx]))
        cand[idx] = m
        # eliminate v from peers
        for p in peers[idx]:
            if cand[p] & m:
                trail.append((p, cand[p]))
                cand[p] &= ~m
                if cand[p] == 0:
                    return False
        return True

    def is_solved():
        return all(popcount(cand[i]) == 1 for i in range(N * N))

    def contradiction_check():
        # Any unit missing a required digit due to eliminations?
        for u in rows + cols + boxes:
            # for each digit, ensure at least one place
            union = 0
            for cell in u:
                union |= cand[cell]
            if union != ALL:
                # some digits missing -> contradiction
                return False
        return True

    trail0 = []
    # Apply initial fixed assignments with propagation
    for i, v in enumerate(fixed):
        if v:
            if not assign(i, v, trail0):
                return "No Solution"
    if not contradiction_check():
        return "No Solution"

    # Deduction techniques
    def naked_single(trail):
        progress = False
        for i in range(N * N):
            if popcount(cand[i]) == 1:
                continue
            if cand[i] == 0:
                return None
            if popcount(cand[i]) == 1:
                continue
            if popcount(cand[i]) == 1:
                progress = True
        # Actually, naked single means popcount==1 already; we rely on assign propagation.
        # Here we instead detect cells reduced to one and ensure peers elimination already done.
        return progress

    def enforce_all_singles(trail):
        """If any cell has single candidate but not yet propagated (assign ensures), nothing to do."""
        return False

    def hidden_singles(trail):
        progress = False
        for u in rows + cols + boxes:
            # map digit mask -> locations
            locs = [0] * N  # bitset of positions within unit (up to N<=16 typical; but store int)
            # We'll store count and last cell
            counts = [0] * N
            last = [-1] * N
            for cell in u:
                m = cand[cell]
                # iterate candidates bits
                while m:
                    b = m & -m
                    d = b.bit_length() - 1
                    counts[d] += 1
                    last[d] = cell
                    m -= b
            for d in range(N):
                if counts[d] == 0:
                    return None  # contradiction
                if counts[d] == 1:
                    cell = last[d]
                    if popcount(cand[cell]) != 1:
                        if not assign(cell, d + 1, trail):
                            return None
                        progress = True
        return progress

    def locked_candidates(trail):
        # Also called pointing/claiming
        progress = False
        # For each box, if a digit appears only in one row within the box => eliminate from that row outside box.
        # Similarly for one column.
        for b in boxes:
            # group cells by row/col index
            row_groups = defaultdict(list)
            col_groups = defaultdict(list)
            for cell in b:
                rr, cc = divmod(cell, N)
                row_groups[rr].append(cell)
                col_groups[cc].append(cell)
            # digit -> cells in box
            digit_cells = [0] * N
            for cell in b:
                m = cand[cell]
                while m:
                    bitm = m & -m
                    d = bitm.bit_length() - 1
                    digit_cells[d] |= 1 << (b.index(cell) if N <= 64 else 0)  # not used directly
                    m -= bitm
            # Efficient: compute sets directly
            for d in range(1, N + 1):
                m = bit(d)
                cells = [cell for cell in b if cand[cell] & m]
                if len(cells) <= 1:
                    continue
                rows_in = {cell // N for cell in cells}
                if len(rows_in) == 1:
                    rr = next(iter(rows_in))
                    for cell in rows[rr]:
                        if cell not in b and (cand[cell] & m):
                            trail.append((cell, cand[cell]))
                            cand[cell] &= ~m
                            if cand[cell] == 0:
                                return None
                            progress = True
                cols_in = {cell % N for cell in cells}
                if len(cols_in) == 1:
                    cc = next(iter(cols_in))
                    for cell in cols[cc]:
                        if cell not in b and (cand[cell] & m):
                            trail.append((cell, cand[cell]))
                            cand[cell] &= ~m
                            if cand[cell] == 0:
                                return None
                            progress = True
        # Claiming: if in a row digit candidates all within one box => eliminate from box outside row
        for rr in range(N):
            u = rows[rr]
            for d in range(1, N + 1):
                m = bit(d)
                cells = [cell for cell in u if cand[cell] & m]
                if len(cells) <= 1:
                    continue
                box_id = (rr // R) * (N // C) + (cells[0] % N) // C
                if all(((cell // N) // R) * (N // C) + ((cell % N) // C) == box_id for cell in cells):
                    b = boxes[box_id]
                    for cell in b:
                        if cell // N != rr and (cand[cell] & m):
                            trail.append((cell, cand[cell]))
                            cand[cell] &= ~m
                            if cand[cell] == 0:
                                return None
                            progress = True
        for cc in range(N):
            u = cols[cc]
            for d in range(1, N + 1):
                m = bit(d)
                cells = [cell for cell in u if cand[cell] & m]
                if len(cells) <= 1:
                    continue
                box_id = ((cells[0] // N) // R) * (N // C) + (cc // C)
                if all(((cell // N) // R) * (N // C) + ((cell % N) // C) == box_id for cell in cells):
                    b = boxes[box_id]
                    for cell in b:
                        if cell % N != cc and (cand[cell] & m):
                            trail.append((cell, cand[cell]))
                            cand[cell] &= ~m
                            if cand[cell] == 0:
                                return None
                            progress = True
        return progress

    def naked_pairs(trail):
        progress = False
        for u in rows + cols + boxes:
            # Find all cells with exactly 2 candidates
            pairs = defaultdict(list)
            for cell in u:
                m = cand[cell]
                if popcount(m) == 2:
                    pairs[m].append(cell)
            for pm, cells in pairs.items():
                if len(cells) == 2:
                    # eliminate pm from other cells
                    for cell in u:
                        if cell not in cells and (cand[cell] & pm):
                            trail.append((cell, cand[cell]))
                            cand[cell] &= ~pm
                            if cand[cell] == 0:
                                return None
                            progress = True
        return progress

    def naked_triples(trail):
        progress = False
        for u in rows + cols + boxes:
            # Consider cells with 2 or 3 candidates; find combos of 3 cells whose union is size 3
            small = [cell for cell in u if 2 <= popcount(cand[cell]) <= 3]
            L = len(small)
            for i in range(L):
                mi = cand[small[i]]
                for j in range(i + 1, L):
                    mj = mi | cand[small[j]]
                    if popcount(mj) > 3:
                        continue
                    for k in range(j + 1, L):
                        mk = mj | cand[small[k]]
                        if popcount(mk) == 3:
                            trio = {small[i], small[j], small[k]}
                            for cell in u:
                                if cell not in trio and (cand[cell] & mk):
                                    trail.append((cell, cand[cell]))
                                    cand[cell] &= ~mk
                                    if cand[cell] == 0:
                                        return None
                                    progress = True
        return progress

    def reduce_loop(trail):
        # Apply deduction rules until stuck
        while True:
            if not contradiction_check():
                return None
            progressed = False
            hs = hidden_singles(trail)
            if hs is None:
                return None
            progressed |= hs
            lc = locked_candidates(trail)
            if lc is None:
                return None
            progressed |= lc
            np = naked_pairs(trail)
            if np is None:
                return None
            progressed |= np
            nt = naked_triples(trail)
            if nt is None:
                return None
            progressed |= nt
            if not progressed:
                return True

    def choose_cell_mrv():
        best_i = -1
        best_k = 999
        for i in range(N * N):
            k = popcount(cand[i])
            if k > 1 and k < best_k:
                best_k = k
                best_i = i
                if k == 2:
                    break
        return best_i

    def snapshot_restore(trail):
        for idx, old in reversed(trail):
            cand[idx] = old

    def dfs():
        trail = []
        if reduce_loop(trail) is None:
            snapshot_restore(trail)
            return False
        if is_solved():
            return True
        i = choose_cell_mrv()
        if i < 0:
            snapshot_restore(trail)
            return False

        # Value ordering: try candidates that least constrain peers (LCV heuristic)
        opts = list(mask_to_vals(cand[i]))
        def score(v):
            m = bit(v)
            s = 0
            for p in peers[i]:
                if cand[p] & m:
                    s += 1
            return s
        opts.sort(key=score)

        base_trail = trail
        base_len = len(base_trail)
        saved = base_trail[:]  # not used, but keep reference stable

        for v in opts:
            branch_trail = []
            if assign(i, v, branch_trail):
                if dfs():
                    return True
            snapshot_restore(branch_trail)
            # continue with next v
        snapshot_restore(base_trail)
        return False

    if not dfs():
        return "No Solution"

    # Build solved grid
    out = [[0] * N for _ in range(N)]
    for i in range(N * N):
        if popcount(cand[i]) != 1:
            return "No Solution"
        v = lsb_index(cand[i]) + 1
        r, c_ = divmod(i, N)
        out[r][c_] = v
    return str(out)

