    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 2, None, 3, None, 1, None], [2, None, None, None, None, None, None], [None, None, None, None, 4, None, 4], [None, None, None, None, None, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, 2, None, None], [3, None, None, 3, None, None, 3]]}
from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple, Set

Coord = Tuple[int, int]
EdgeKey = Tuple[Coord, Coord]  # ordered (min,max)


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    islands: Dict[Coord, int] = {}
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if isinstance(v, int):
                islands[(r, c)] = v

    if not islands:
        return "No Solution"

    # Build visibility edges between nearest islands in each orthogonal direction.
    # Only nearest in a line is connectable (standard Hashiwokakero rule).
    neighbors: Dict[Coord, List[Coord]] = {p: [] for p in islands}
    edges: List[Tuple[Coord, Coord]] = []
    edge_index: Dict[EdgeKey, int] = {}

    # Row scan: for each row, connect consecutive islands.
    for r in range(n):
        last = None
        for c in range(n):
            if (r, c) in islands:
                if last is not None:
                    a, b = last, (r, c)
                    neighbors[a].append(b)
                    neighbors[b].append(a)
                    key = (a, b) if a < b else (b, a)
                    edge_index[key] = len(edges)
                    edges.append(key)
                last = (r, c)

    # Col scan: for each col, connect consecutive islands.
    for c in range(n):
        last = None
        for r in range(n):
            if (r, c) in islands:
                if last is not None:
                    a, b = last, (r, c)
                    neighbors[a].append(b)
                    neighbors[b].append(a)
                    key = (a, b) if a < b else (b, a)
                    if key not in edge_index:
                        edge_index[key] = len(edges)
                        edges.append(key)
                last = (r, c)

    m = len(edges)
    if m == 0:
        return "No Solution"

    # Precompute crossings between candidate edges (only horizontal vs vertical can cross).
    def is_horizontal(e):
        (r1, c1), (r2, c2) = e
        return r1 == r2

    def segments_cross(eh, ev):
        # eh horizontal, ev vertical; crossings at interior points only (not at endpoints).
        (r, c1), (_, c2) = eh
        (r1, c), (r2, _) = ev
        if not (min(c1, c2) < c < max(c1, c2)):
            return False
        if not (min(r1, r2) < r < max(r1, r2)):
            return False
        return True

    edge_cross: List[Set[int]] = [set() for _ in range(m)]
    horizontals = [i for i, e in enumerate(edges) if is_horizontal(e)]
    verticals = [i for i, e in enumerate(edges) if not is_horizontal(e)]
    for ih in horizontals:
        eh = edges[ih]
        for iv in verticals:
            ev = edges[iv]
            if segments_cross(eh, ev):
                edge_cross[ih].add(iv)
                edge_cross[iv].add(ih)

    # Incident edges per island
    incident: Dict[Coord, List[int]] = {p: [] for p in islands}
    for i, (a, b) in enumerate(edges):
        incident[a].append(i)
        incident[b].append(i)

    # Fast degree tracking and union-find with backtracking
    @dataclass
    class UF:
        parent: List[int]
        rank: List[int]
        comps: int

        @staticmethod
        def create(k: int) -> "UF":
            return UF(parent=list(range(k)), rank=[0] * k, comps=k)

        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, a: int, b: int):
            ra, rb = self.find(a), self.find(b)
            if ra == rb:
                return None
            # union by rank
            if self.rank[ra] < self.rank[rb]:
                ra, rb = rb, ra
            # save state for rollback
            changed = (rb, self.parent[rb], ra, self.rank[ra], self.comps)
            self.parent[rb] = ra
            if self.rank[ra] == self.rank[rb]:
                self.rank[ra] += 1
            self.comps -= 1
            return changed

        def rollback(self, changed):
            if changed is None:
                return
            rb, old_parent_rb, ra, old_rank_ra, old_comps = changed
            self.parent[rb] = old_parent_rb
            self.rank[ra] = old_rank_ra
            self.comps = old_comps

    island_list = list(islands.keys())
    island_id: Dict[Coord, int] = {p: i for i, p in enumerate(island_list)}

    # State arrays
    # edge_val: -1 unassigned, 0..2 assigned
    edge_val = [-1] * m
    # remaining degree per island
    rem = {p: islands[p] for p in islands}
    # For each edge, domains bitmask for {0,1,2} possible (bit 0->0, bit1->1, bit2->2)
    dom = [0b111] * m

    # Crossing constraints: if edge>0 then crossing edges must be 0. If edge forced >0, prune.
    # Precompute for each edge a list of crossing indices.
    cross_list = [list(s) for s in edge_cross]

    # Utility for domain operations
    def dom_has(d, v):
        return (d >> v) & 1

    def dom_remove(d, v):
        return d & ~(1 << v)

    def dom_only_value(d):
        if d == 0:
            return None
        if d & (d - 1) == 0:
            # single bit
            if d == 1:
                return 0
            if d == 2:
                return 1
            if d == 4:
                return 2
        return None

    # Trail for backtracking: list of (kind, idx/key, old_value)
    trail: List[Tuple[str, object, object]] = []
    uf = UF.create(len(islands))
    uf_trail: List[object] = []

    def save(kind, key, old):
        trail.append((kind, key, old))

    def set_dom(i: int, newd: int) -> bool:
        if dom[i] == newd:
            return True
        if newd == 0:
            return False
        save("dom", i, dom[i])
        dom[i] = newd
        # If becomes singleton, enforce assignment later by queue
        return True

    def set_edge(i: int, v: int, q: deque) -> bool:
        # assign edge i to v, update rem, crossing, union-find for connectivity of positive edges
        if edge_val[i] != -1:
            return edge_val[i] == v
        if not dom_has(dom[i], v):
            return False
        save("edge", i, edge_val[i])
        edge_val[i] = v
        # domain becomes singleton
        if not set_dom(i, 1 << v):
            return False

        a, b = edges[i]
        if v > 0:
            # update degrees
            for p in (a, b):
                old = rem[p]
                new = old - v
                save("rem", p, old)
                rem[p] = new
                if new < 0:
                    return False
            # union components
            ch = uf.union(island_id[a], island_id[b])
            uf_trail.append(ch)
            # enforce crossing edges to 0
            for j in cross_list[i]:
                if edge_val[j] == -1:
                    if not set_dom(j, dom_remove(dom[j], 1) if dom_has(dom[j], 1) else dom[j]):
                        return False
                    if not set_dom(j, dom_remove(dom[j], 2) if dom_has(dom[j], 2) else dom[j]):
                        return False
                    # if forced singleton, enqueue
                    ov = dom_only_value(dom[j])
                    if ov is not None:
                        q.append(("assign", j, ov))
                else:
                    if edge_val[j] > 0:
                        return False
        else:
            # v == 0 doesn't change rem or UF
            pass

        # After assignment, trigger local island constraints
        q.append(("island", a, None))
        q.append(("island", b, None))
        return True

    def rollback(to_len: int, uf_to_len: int):
        while len(uf_trail) > uf_to_len:
            ch = uf_trail.pop()
            uf.rollback(ch)
        while len(trail) > to_len:
            kind, key, old = trail.pop()
            if kind == "dom":
                dom[key] = old
            elif kind == "edge":
                edge_val[key] = old
            elif kind == "rem":
                rem[key] = old
            else:
                raise RuntimeError("bad trail kind")

    # Human-like deduction rules for island degrees:
    # For an island p:
    # - Let incident edges E, each has max possible contrib maxv (<=2) from domain.
    # - If sum(maxv) == rem[p], then all incident edges must take their max.
    # - If sum(minv) == rem[p], then all incident edges must take their min.
    # - For each edge, if rem[p] - (sum_max - maxv) > 0 then edge min must be raised (at least that delta capped).
    # - For each edge, if rem[p] - (sum_min - minv) < maxv then edge max must be lowered.
    def island_propagate(p: Coord, q: deque) -> bool:
        E = incident[p]
        if not E:
            return rem[p] == 0
        rp = rem[p]
        if rp < 0:
            return False

        minv = []
        maxv = []
        for i in E:
            d = dom[i]
            # min is smallest allowed value, max is largest allowed value
            mn = 0 if dom_has(d, 0) else (1 if dom_has(d, 1) else (2 if dom_has(d, 2) else 99))
            mx = 2 if dom_has(d, 2) else (1 if dom_has(d, 1) else (0 if dom_has(d, 0) else -99))
            if mn == 99 or mx == -99:
                return False
            minv.append(mn)
            maxv.append(mx)

        smin = sum(minv)
        smax = sum(maxv)
        if rp < smin or rp > smax:
            return False

        # If rp equals extremes, force all to extreme
        if rp == smin:
            for idx, i in enumerate(E):
                v = minv[idx]
                if edge_val[i] == -1:
                    q.append(("assign", i, v))
                elif edge_val[i] != v:
                    return False
            return True
        if rp == smax:
            for idx, i in enumerate(E):
                v = maxv[idx]
                if edge_val[i] == -1:
                    q.append(("assign", i, v))
                elif edge_val[i] != v:
                    return False
            return True

        # General bounds tightening per edge
        for idx, i in enumerate(E):
            mn, mx = minv[idx], maxv[idx]
            # minimal required on this edge to still reach rp
            req = rp - (smax - mx)
            if req > mn:
                # raise min to req
                nd = dom[i]
                for v in range(0, min(req, 3)):
                    if dom_has(nd, v):
                        nd = dom_remove(nd, v)
                if not set_dom(i, nd):
                    return False
                ov = dom_only_value(dom[i])
                if ov is not None and edge_val[i] == -1:
                    q.append(("assign", i, ov))

            # maximal allowed on this edge to not exceed rp
            allow = rp - (smin - mn)
            if allow < mx:
                nd = dom[i]
                for v in range(allow + 1, 3):
                    if dom_has(nd, v):
                        nd = dom_remove(nd, v)
                if not set_dom(i, nd):
                    return False
                ov = dom_only_value(dom[i])
                if ov is not None and edge_val[i] == -1:
                    q.append(("assign", i, ov))
        return True

    # Connectivity pruning: prevent closing off disconnected components when degrees remaining require connectivity.
    # Use a necessary condition: consider graph of islands with potential positive edges (domain includes 1 or 2).
    # Any UF component must have at least one potential connection to another component unless it is the only component.
    def connectivity_necessary() -> bool:
        if uf.comps == 1:
            return True
        # For each UF root, whether it has an outgoing potential-positive edge.
        has_out = [False] * len(islands)
        for i, (a, b) in enumerate(edges):
            if edge_val[i] == 0:
                continue
            if edge_val[i] == -1 and not (dom_has(dom[i], 1) or dom_has(dom[i], 2)):
                continue
            ra, rb = uf.find(island_id[a]), uf.find(island_id[b])
            if ra != rb:
                has_out[ra] = True
                has_out[rb] = True
        roots = {uf.find(i) for i in range(len(islands))}
        for r in roots:
            if not has_out[r]:
                return False
        return True

    def propagate(q: deque) -> bool:
        while q:
            typ, x, v = q.popleft()
            if typ == "assign":
                if not set_edge(x, v, q):
                    return False
            elif typ == "island":
                if not island_propagate(x, q):
                    return False
            else:
                raise RuntimeError("bad queue item")
        return True

    # Initialize propagation with all islands
    q = deque()
    for p in islands:
        q.append(("island", p, None))
    if not propagate(q):
        return "No Solution"
    if not connectivity_necessary():
        return "No Solution"

    # Branching heuristic: pick unassigned edge with smallest domain size (>1) and strong impact.
    def pick_edge() -> Optional[int]:
        best = None
        best_size = 4
        best_score = -1
        for i in range(m):
            if edge_val[i] != -1:
                continue
            d = dom[i]
            # count bits
            sz = (d & 1) + ((d >> 1) & 1) + ((d >> 2) & 1)
            if sz <= 1:
                continue
            # score: prefer edges touching tight islands (small rem) and with crossings
            a, b = edges[i]
            score = (len(cross_list[i]) * 2) + (10 - min(rem[a], 9)) + (10 - min(rem[b], 9))
            if sz < best_size or (sz == best_size and score > best_score):
                best = i
                best_size = sz
                best_score = score
        return best

    def is_solved() -> bool:
        if any(edge_val[i] == -1 for i in range(m)):
            return False
        if any(rem[p] != 0 for p in rem):
            return False
        return uf.comps == 1

    # Depth-first search with heavy propagation
    def dfs() -> bool:
        if is_solved():
            return True
        if not connectivity_necessary():
            return False

        i = pick_edge()
        if i is None:
            return False

        # Value ordering: try larger first when islands have higher remaining, else 0 first.
        a, b = edges[i]
        candidates = []
        for v in (2, 1, 0):
            if dom_has(dom[i], v):
                candidates.append(v)
        candidates.sort(key=lambda vv: (vv == 0, -vv))  # prefer 2/1 over 0

        base_trail = len(trail)
        base_uf = len(uf_trail)
        for v in candidates:
            rollback(base_trail, base_uf)
            qq = deque()
            if not set_edge(i, v, qq):
                continue
            if not propagate(qq):
                continue
            if dfs():
                return True
        rollback(base_trail, base_uf)
        return False

    if not dfs():
        return "No Solution"

    # Build answer dict with only positive bridges
    ans: Dict[Tuple[Coord, Coord], int] = {}
    for i, (a, b) in enumerate(edges):
        v = edge_val[i]
        if v and v > 0:
            ans[(a, b)] = v
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, None, None, None, None, None, 4, None, None], [None, 4, 5, None, 2, 1, None, None, None], [1, None, None, None, 7, None, None, 2, 5], [None, None, None, None, None, 6, 3, 1, None], [None, None, None, 7, None, 9, None, None, None], [None, 1, 2, 3, None, None, None, None, None], [2, 5, None, None, 3, None, None, None, 9], [None, None, None, 9, 5, None, 2, 7, None], [None, None, 4, None, None, None, None, None, 8]], 'unit': '3x3'}

# Human-style Sudoku solver with aggressive constraint propagation:
# - Candidate bitmasks per cell
# - Singles (naked/hidden)
# - Locked candidates (pointing/claiming)
# - Subset elimination (naked/hidden pairs/triples/quads) in rows/cols/boxes
# - MRV + least-constraining value branching only as a last resort

from __future__ import annotations

def solve(observation):
    grid = observation["data"]
    unit = observation["unit"]
    try:
        br, bc = _parse_unit(unit)
    except Exception:
        return "No Solution"
    n = br * bc
    if len(grid) != n or any(len(r) != n for r in grid):
        return "No Solution"

    # Validate symbols: ints 1..n or None
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if v is not None and (not isinstance(v, int) or v < 1 or v > n):
                return "No Solution"

    solver = _Solver(grid, br, bc)
    sol = solver.run()
    if sol is None:
        return "No Solution"
    return repr(sol)


def _parse_unit(s: str):
    s = str(s).lower().strip()
    if "x" in s:
        a, b = s.split("x", 1)
        return int(a), int(b)
    k = int(s)
    return k, k


class _Solver:
    __slots__ = (
        "n", "br", "bc", "Nmask",
        "cells", "rows", "cols", "boxes",
        "units", "peers",
        "row_mask", "col_mask", "box_mask",
        "cand", "trail",
    )

    def __init__(self, grid, br, bc):
        self.br, self.bc = br, bc
        self.n = br * bc
        self.Nmask = (1 << self.n) - 1

        n = self.n
        self.cells = [(r, c) for r in range(n) for c in range(n)]
        self.rows = [[(r, c) for c in range(n)] for r in range(n)]
        self.cols = [[(r, c) for r in range(n)] for c in range(n)]
        self.boxes = []
        for br0 in range(0, n, br):
            for bc0 in range(0, n, bc):
                box = []
                for r in range(br0, br0 + br):
                    for c in range(bc0, bc0 + bc):
                        box.append((r, c))
                self.boxes.append(box)

        self.units = []  # list of lists of cells
        self.units.extend(self.rows)
        self.units.extend(self.cols)
        self.units.extend(self.boxes)

        # Peers for each cell
        self.peers = [[None] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                p = set(self.rows[r]) | set(self.cols[c]) | set(self.boxes[self._box_index(r, c)])
                p.discard((r, c))
                self.peers[r][c] = tuple(p)

        # Masks of used digits in row/col/box
        self.row_mask = [0] * n
        self.col_mask = [0] * n
        self.box_mask = [0] * n

        # Candidates bitmask per cell
        self.cand = [[self.Nmask] * n for _ in range(n)]
        self.trail = []

        # Initialize with givens
        for r in range(n):
            for c in range(n):
                v = grid[r][c]
                if v is not None:
                    if not self._assign(r, c, v):
                        # Mark impossible state
                        self.cand = None

    def run(self):
        if self.cand is None:
            return None
        if not self._propagate():
            return None
        if self._is_solved():
            return self._export_solution()
        if self._search():
            return self._export_solution()
        return None

    def _export_solution(self):
        n = self.n
        out = [[None] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                m = self.cand[r][c]
                if m == 0:
                    return None
                if m & (m - 1):
                    # not fully assigned (should not happen on success)
                    return None
                out[r][c] = (m.bit_length())
        return out

    def _box_index(self, r, c):
        return (r // self.br) * (self.n // self.bc) + (c // self.bc)

    def _digit_bit(self, d):
        return 1 << (d - 1)

    def _is_solved(self):
        n = self.n
        for r in range(n):
            for c in range(n):
                m = self.cand[r][c]
                if m == 0 or (m & (m - 1)):
                    return False
        return True

    # Trail-based reversible operations
    def _push(self, kind, *args):
        self.trail.append((kind, args))

    def _mark_and_set(self, r, c, newmask):
        old = self.cand[r][c]
        if old == newmask:
            return True
        self._push("cand", r, c, old)
        self.cand[r][c] = newmask
        return True

    def _mark_mask(self, arrname, idx, old):
        self._push(arrname, idx, old)

    def _undo(self, checkpoint):
        while len(self.trail) > checkpoint:
            kind, args = self.trail.pop()
            if kind == "cand":
                r, c, old = args
                self.cand[r][c] = old
            elif kind == "row":
                idx, old = args
                self.row_mask[idx] = old
            elif kind == "col":
                idx, old = args
                self.col_mask[idx] = old
            elif kind == "box":
                idx, old = args
                self.box_mask[idx] = old
            else:
                raise RuntimeError("Unknown trail op")

    def _assign(self, r, c, v):
        # Set cell (r,c) to value v; update unit masks; eliminate from peers.
        bit = self._digit_bit(v)
        m = self.cand[r][c]
        if not (m & bit):
            return False
        if m == bit:
            return True

        # Check conflicts with existing placed digits via masks
        b = self._box_index(r, c)
        if (self.row_mask[r] & bit) or (self.col_mask[c] & bit) or (self.box_mask[b] & bit):
            return False

        # Record and set masks
        if self.row_mask[r] != (self.row_mask[r] | bit):
            self._mark_mask("row", r, self.row_mask[r])
            self.row_mask[r] |= bit
        if self.col_mask[c] != (self.col_mask[c] | bit):
            self._mark_mask("col", c, self.col_mask[c])
            self.col_mask[c] |= bit
        if self.box_mask[b] != (self.box_mask[b] | bit):
            self._mark_mask("box", b, self.box_mask[b])
            self.box_mask[b] |= bit

        self._mark_and_set(r, c, bit)
        return True

    def _eliminate(self, r, c, bit):
        m = self.cand[r][c]
        if not (m & bit):
            return True
        newm = m & ~bit
        if newm == 0:
            return False
        self._mark_and_set(r, c, newm)
        return True

    def _propagate(self):
        # Repeat deductions until fixed point
        while True:
            checkpoint = len(self.trail)
            if not self._deduce_naked_singles():
                return False
            if not self._deduce_hidden_singles():
                return False
            if not self._locked_candidates():
                return False
            if not self._subset_elimination(max_k=4):
                return False
            if len(self.trail) == checkpoint:
                break
        return True

    def _deduce_naked_singles(self):
        n = self.n
        progress = True
        while progress:
            progress = False
            for r in range(n):
                for c in range(n):
                    m = self.cand[r][c]
                    if m == 0:
                        return False
                    if m & (m - 1):
                        continue
                    # single -> ensure masks consistent and peers eliminate
                    v = m.bit_length()
                    bit = m
                    b = self._box_index(r, c)
                    # If already in masks, fine; else set
                    if not (self.row_mask[r] & bit):
                        self._mark_mask("row", r, self.row_mask[r])
                        self.row_mask[r] |= bit
                    if not (self.col_mask[c] & bit):
                        self._mark_mask("col", c, self.col_mask[c])
                        self.col_mask[c] |= bit
                    if not (self.box_mask[b] & bit):
                        self._mark_mask("box", b, self.box_mask[b])
                        self.box_mask[b] |= bit
                    # eliminate from peers
                    for pr, pc in self.peers[r][c]:
                        if not self._eliminate(pr, pc, bit):
                            return False
                    # update candidates by used masks in row/col/box for unfilled cells
                    progress = True
            # also prune candidates using masks
            for r in range(n):
                used = self.row_mask[r]
                if used:
                    for c in range(n):
                        m = self.cand[r][c]
                        if m & (m - 1):  # not assigned
                            if not self._mark_and_set(r, c, m & ~used):
                                return False
                            if self.cand[r][c] == 0:
                                return False
            for c in range(n):
                used = self.col_mask[c]
                if used:
                    for r in range(n):
                        m = self.cand[r][c]
                        if m & (m - 1):
                            if not self._mark_and_set(r, c, m & ~used):
                                return False
                            if self.cand[r][c] == 0:
                                return False
            # boxes
            per_row_boxes = self.n // self.bc
            for bi, box in enumerate(self.boxes):
                used = self.box_mask[bi]
                if used:
                    for r, c in box:
                        m = self.cand[r][c]
                        if m & (m - 1):
                            if not self._mark_and_set(r, c, m & ~used):
                                return False
                            if self.cand[r][c] == 0:
                                return False
        return True

    def _deduce_hidden_singles(self):
        # For each unit, if a digit fits only one place -> assign it
        for unit in self.units:
            # map digit bit -> last position and count
            count = {}
            pos = {}
            for (r, c) in unit:
                m = self.cand[r][c]
                if m == 0:
                    return False
                x = m
                while x:
                    b = x & -x
                    count[b] = count.get(b, 0) + 1
                    pos[b] = (r, c)
                    x -= b
            for b, k in count.items():
                if k == 1:
                    r, c = pos[b]
                    if self.cand[r][c] != b:
                        v = b.bit_length()
                        if not self._assign(r, c, v):
                            return False
        return True

    def _locked_candidates(self):
        # Pointing/Claiming:
        # In a box, if candidates for a digit confined to one row/col -> eliminate from that row/col outside box
        n = self.n
        for bi, box in enumerate(self.boxes):
            # digit -> set of rows/cols where it appears
            rows = {}
            cols = {}
            cells_for = {}
            for r, c in box:
                m = self.cand[r][c]
                x = m
                while x:
                    b = x & -x
                    rows.setdefault(b, set()).add(r)
                    cols.setdefault(b, set()).add(c)
                    cells_for.setdefault(b, []).append((r, c))
                    x -= b
            for b, rs in rows.items():
                if len(rs) == 1:
                    r = next(iter(rs))
                    # eliminate b from row r outside this box
                    for cc in range(n):
                        if (r, cc) not in box:
                            if not self._eliminate(r, cc, b):
                                return False
            for b, cs in cols.items():
                if len(cs) == 1:
                    c = next(iter(cs))
                    for rr in range(n):
                        if (rr, c) not in box:
                            if not self._eliminate(rr, c, b):
                                return False

        # Claiming: In a row/col, if candidates for digit confined to one box -> eliminate from box outside row/col
        # Rows
        for r in range(n):
            where = {}
            for c in range(n):
                m = self.cand[r][c]
                x = m
                while x:
                    b = x & -x
                    where.setdefault(b, []).append(c)
                    x -= b
            for b, cols_list in where.items():
                if len(cols_list) >= 2:
                    box_ids = {self._box_index(r, c) for c in cols_list}
                    if len(box_ids) == 1:
                        bi = next(iter(box_ids))
                        for rr, cc in self.boxes[bi]:
                            if rr != r:
                                if not self._eliminate(rr, cc, b):
                                    return False
        # Cols
        for c in range(n):
            where = {}
            for r in range(n):
                m = self.cand[r][c]
                x = m
                while x:
                    b = x & -x
                    where.setdefault(b, []).append(r)
                    x -= b
            for b, rows_list in where.items():
                if len(rows_list) >= 2:
                    box_ids = {self._box_index(r, c) for r in rows_list}
                    if len(box_ids) == 1:
                        bi = next(iter(box_ids))
                        for rr, cc in self.boxes[bi]:
                            if cc != c:
                                if not self._eliminate(rr, cc, b):
                                    return False
        return True

    def _subset_elimination(self, max_k=4):
        # Apply naked/hidden subsets up to size max_k in each unit
        for unit in self.units:
            if not self._naked_subsets(unit, max_k):
                return False
            if not self._hidden_subsets(unit, max_k):
                return False
        return True

    def _naked_subsets(self, unit, max_k):
        # If k cells have union of candidates size k, remove those candidates from other cells
        # Use pattern hashing of candidate masks
        buckets = {}
        for r, c in unit:
            m = self.cand[r][c]
            if m & (m - 1):  # not single
                bits = m.bit_count()
                if 2 <= bits <= max_k:
                    buckets.setdefault(m, []).append((r, c))
        for m, cells in buckets.items():
            k = len(cells)
            if k >= 2 and k == m.bit_count() and k <= max_k:
                # eliminate mask m from other cells in unit
                for r, c in unit:
                    if (r, c) not in cells:
                        if self.cand[r][c] & m:
                            if not self._mark_and_set(r, c, self.cand[r][c] & ~m):
                                return False
                            if self.cand[r][c] == 0:
                                return False
        return True

    def _hidden_subsets(self, unit, max_k):
        # If a set of k digits appear only in same k cells -> restrict those cells to these digits
        # Build digit->cells map
        digit_cells = {}
        for r, c in unit:
            m = self.cand[r][c]
            x = m
            while x:
                b = x & -x
                digit_cells.setdefault(b, []).append((r, c))
                x -= b
        # Invert by cell-set signature; search small sets
        # Only consider digits with occurrence 2..max_k
        sig_to_bits = {}
        for b, cells in digit_cells.items():
            if 2 <= len(cells) <= max_k:
                sig = tuple(sorted(cells))
                sig_to_bits[sig] = sig_to_bits.get(sig, 0) | b
        for sig, bitsmask in sig_to_bits.items():
            k = len(sig)
            if bitsmask.bit_count() == k and 2 <= k <= max_k:
                # restrict those k cells to bitsmask
                for r, c in sig:
                    m = self.cand[r][c]
                    newm = m & bitsmask
                    if newm != m:
                        if newm == 0:
                            return False
                        self._mark_and_set(r, c, newm)
        return True

    def _choose_cell_mrv(self):
        # Choose unfilled cell with fewest candidates
        n = self.n
        best = None
        best_count = 10**9
        for r in range(n):
            for c in range(n):
                m = self.cand[r][c]
                if m == 0:
                    return None
                if m & (m - 1):
                    cnt = m.bit_count()
                    if cnt < best_count:
                        best_count = cnt
                        best = (r, c, m)
                        if cnt == 2:
                            return best
        return best

    def _search(self):
        if self._is_solved():
            return True
        pick = self._choose_cell_mrv()
        if pick is None:
            return False
        r, c, m = pick

        # Least-constraining value: try values that eliminate fewer options in peers
        options = []
        x = m
        while x:
            b = x & -x
            score = 0
            for pr, pc in self.peers[r][c]:
                if self.cand[pr][pc] & b:
                    score += 1
            options.append((score, b))
            x -= b
        options.sort()

        for _, b in options:
            checkpoint = len(self.trail)
            v = b.bit_length()
            if self._assign(r, c, v) and self._propagate():
                if self._search():
                    return True
            self._undo(checkpoint)
        return False


