from __future__ import annotations

# Human-like Sudoku solver with strong constraint propagation:
# - Candidates via bitmasks
# - Singles (naked/hidden)
# - Locked candidates (pointing/claiming)
# - Naked pairs
# - X-Wing (rows/cols)
# - MRV branching with forward checking (only when needed)

ALL_DIGITS_CACHE = {}


def _parse_unit(unit: str) -> tuple[int, int]:
    if isinstance(unit, str) and "x" in unit:
        a, b = unit.lower().split("x")
        return int(a), int(b)
    u = int(unit)
    return u, u


def _bit(n: int) -> int:
    return 1 << (n - 1)


def _popcount(x: int) -> int:
    return x.bit_count()


def _lsb_index(x: int) -> int:
    # returns 0-based index of least significant set bit
    return (x & -x).bit_length() - 1


def _iter_bits(mask: int):
    while mask:
        b = mask & -mask
        yield b
        mask ^= b


def _mask_to_vals(mask: int) -> list[int]:
    res = []
    while mask:
        b = mask & -mask
        res.append(b.bit_length())
        mask ^= b
    return res


def _val_from_singleton(mask: int) -> int:
    # mask is power of two
    return mask.bit_length()


def _build_structures(N: int, br: int, bc: int):
    # Caches based on (N, br, bc)
    key = (N, br, bc)
    if key in ALL_DIGITS_CACHE:
        return ALL_DIGITS_CACHE[key]

    all_mask = (1 << N) - 1

    rows = [[r * N + c for c in range(N)] for r in range(N)]
    cols = [[r * N + c for r in range(N)] for c in range(N)]
    boxes = []
    for r0 in range(0, N, br):
        for c0 in range(0, N, bc):
            box = []
            for dr in range(br):
                for dc in range(bc):
                    box.append((r0 + dr) * N + (c0 + dc))
            boxes.append(box)

    units = rows + cols + boxes

    peers = [set() for _ in range(N * N)]
    for unit in units:
        us = set(unit)
        for idx in unit:
            peers[idx] |= (us - {idx})

    cell_to_box = [0] * (N * N)
    b = 0
    for r0 in range(0, N, br):
        for c0 in range(0, N, bc):
            for dr in range(br):
                for dc in range(bc):
                    cell_to_box[(r0 + dr) * N + (c0 + dc)] = b
            b += 1

    ALL_DIGITS_CACHE[key] = (all_mask, rows, cols, boxes, units, peers, cell_to_box)
    return ALL_DIGITS_CACHE[key]


class State:
    __slots__ = ("N", "br", "bc", "all_mask", "cand", "rows", "cols", "boxes", "units", "peers", "cell_to_box")

    def __init__(self, data, unit):
        self.br, self.bc = _parse_unit(unit)
        self.N = len(data)
        if self.N % self.br != 0 or self.N % self.bc != 0:
            raise ValueError("Grid size not divisible by box dimensions")
        self.all_mask, self.rows, self.cols, self.boxes, self.units, self.peers, self.cell_to_box = _build_structures(
            self.N, self.br, self.bc
        )
        self.cand = [self.all_mask] * (self.N * self.N)

        # initialize with givens using assign propagation
        for r in range(self.N):
            if len(data[r]) != self.N:
                raise ValueError("Non-square grid")
            for c in range(self.N):
                v = data[r][c]
                if v is None:
                    continue
                if not (1 <= int(v) <= self.N):
                    raise ValueError("Value out of range")
                if not self.assign(r * self.N + c, int(v)):
                    raise ValueError("Invalid puzzle (contradiction in givens)")

    def copy(self) -> "State":
        s = object.__new__(State)
        s.N = self.N
        s.br = self.br
        s.bc = self.bc
        s.all_mask = self.all_mask
        s.rows = self.rows
        s.cols = self.cols
        s.boxes = self.boxes
        s.units = self.units
        s.peers = self.peers
        s.cell_to_box = self.cell_to_box
        s.cand = self.cand[:]  # shallow copy list of ints
        return s

    def is_solved(self) -> bool:
        for m in self.cand:
            if m & (m - 1):
                return False
        return True

    def grid(self):
        N = self.N
        out = [[None] * N for _ in range(N)]
        for i, m in enumerate(self.cand):
            if m and not (m & (m - 1)):
                out[i // N][i % N] = _val_from_singleton(m)
            else:
                out[i // N][i % N] = None
        return out

    def assign(self, idx: int, val: int) -> bool:
        # Set idx to val, remove other candidates; propagate eliminations.
        m = self.cand[idx]
        target = _bit(val)
        if not (m & target):
            return False
        if m == target:
            return True
        # eliminate all other values
        other = m ^ target
        self.cand[idx] = target
        # propagate elimination of other values from this cell (for unit constraints)
        for b in _iter_bits(other):
            if not self.eliminate_bit(idx, b):
                return False
        return True

    def eliminate_bit(self, idx: int, bit: int) -> bool:
        m = self.cand[idx]
        if not (m & bit):
            return True
        m2 = m ^ bit
        if m2 == 0:
            return False
        self.cand[idx] = m2

        # If cell becomes singleton, eliminate that value from peers
        if not (m2 & (m2 - 1)):
            vbit = m2
            for p in self.peers[idx]:
                if not self.eliminate_bit(p, vbit):
                    return False

        # If a unit has only one place for a value -> assign it (hidden single)
        # Only need to check units that contain idx: row, col, box
        N = self.N
        r = idx // N
        c = idx % N
        b = self.cell_to_box[idx]
        # Check for each value bit removed? Efficient: check for all bits still possible in unit may be heavy.
        # We instead check for the specific removed bit: if a value disappears from a cell, it might reduce the places count for that value.
        # We'll run unit scans in the main propagation loop; keep this elimination local minimal.

        return True

    def _unit_hidden_singles(self) -> bool:
        # For each unit, for each digit, if appears in only one cell -> assign
        for unit in self.units:
            # Build counts by scanning candidates (bitwise)
            # Use arrays length N (small: 9/16)
            counts = [0] * self.N
            last_pos = [-1] * self.N
            for idx in unit:
                m = self.cand[idx]
                while m:
                    b = m & -m
                    d = b.bit_length() - 1
                    counts[d] += 1
                    last_pos[d] = idx
                    m ^= b
            for d, cnt in enumerate(counts):
                if cnt == 0:
                    return False
                if cnt == 1:
                    idx = last_pos[d]
                    if idx >= 0:
                        if not self.assign(idx, d + 1):
                            return False
        return True

    def _naked_singles_queue(self) -> bool:
        # Repeatedly propagate singletons until stable
        changed = True
        while changed:
            changed = False
            for i, m in enumerate(self.cand):
                if m and not (m & (m - 1)):
                    # singleton, ensure peers don't have it
                    vbit = m
                    for p in self.peers[i]:
                        if self.cand[p] & vbit:
                            if not self.eliminate_bit(p, vbit):
                                return False
                            changed = True
        return True

    def _locked_candidates(self) -> bool:
        # Pointing/claiming: within a box, if digit candidates all in one row/col -> eliminate from that row/col outside box.
        N = self.N
        for b_idx, box in enumerate(self.boxes):
            # For each digit, track row/col mask and positions
            row_mask = [0] * N
            col_mask = [0] * N
            pos = [[] for _ in range(N)]
            for idx in box:
                m = self.cand[idx]
                r = idx // N
                c = idx % N
                while m:
                    b = m & -m
                    d = b.bit_length() - 1
                    row_mask[d] |= (1 << r)
                    col_mask[d] |= (1 << c)
                    pos[d].append(idx)
                    m ^= b
            for d in range(N):
                if len(pos[d]) <= 1:
                    continue
                if row_mask[d] and (row_mask[d] & (row_mask[d] - 1)) == 0:
                    r = (row_mask[d].bit_length() - 1)
                    vbit = 1 << d
                    for idx2 in self.rows[r]:
                        if self.cell_to_box[idx2] != b_idx and (self.cand[idx2] & vbit):
                            if not self.eliminate_bit(idx2, vbit):
                                return False
                if col_mask[d] and (col_mask[d] & (col_mask[d] - 1)) == 0:
                    c = (col_mask[d].bit_length() - 1)
                    vbit = 1 << d
                    for idx2 in self.cols[c]:
                        if self.cell_to_box[idx2] != b_idx and (self.cand[idx2] & vbit):
                            if not self.eliminate_bit(idx2, vbit):
                                return False
        return True

    def _naked_pairs(self) -> bool:
        # In each unit, if two cells share same two candidates, remove them from others
        for unit in self.units:
            seen = {}
            for idx in unit:
                m = self.cand[idx]
                if _popcount(m) == 2:
                    seen.setdefault(m, []).append(idx)
            for m, cells in seen.items():
                if len(cells) == 2:
                    for idx in unit:
                        if idx not in cells and (self.cand[idx] & m):
                            # eliminate both bits
                            for b in _iter_bits(m):
                                if not self.eliminate_bit(idx, b):
                                    return False
        return True

    def _xwing(self) -> bool:
        # X-Wing on rows and columns for each digit (N up to 16 ok)
        N = self.N
        for d in range(N):
            vbit = 1 << d
            # rows: for each row, get columns where digit possible (bitmask of cols)
            row_pos = []
            for r in range(N):
                cm = 0
                for c, idx in enumerate(self.rows[r]):
                    if self.cand[idx] & vbit:
                        cm |= (1 << c)
                if _popcount(cm) == 2:
                    row_pos.append((cm, r))
            # find pairs of rows with same two columns
            mp = {}
            for cm, r in row_pos:
                mp.setdefault(cm, []).append(r)
            for cm, rs in mp.items():
                if len(rs) >= 2:
                    cols2 = [i for i in range(N) if (cm >> i) & 1]
                    for c in cols2:
                        for r in range(N):
                            if r not in rs:
                                idx = r * N + c
                                if self.cand[idx] & vbit:
                                    if not self.eliminate_bit(idx, vbit):
                                        return False

            # cols: for each col, get rows where digit possible
            col_pos = []
            for c in range(N):
                rm = 0
                for r, idx in enumerate(self.cols[c]):
                    if self.cand[idx] & vbit:
                        rm |= (1 << r)
                if _popcount(rm) == 2:
                    col_pos.append((rm, c))
            mp = {}
            for rm, c in col_pos:
                mp.setdefault(rm, []).append(c)
            for rm, cs in mp.items():
                if len(cs) >= 2:
                    rows2 = [i for i in range(N) if (rm >> i) & 1]
                    for r in rows2:
                        for c in range(N):
                            if c not in cs:
                                idx = r * N + c
                                if self.cand[idx] & vbit:
                                    if not self.eliminate_bit(idx, vbit):
                                        return False
        return True

    def propagate(self) -> bool:
        # Iterate techniques until no change
        while True:
            snapshot = self.cand[:]
            if not self._naked_singles_queue():
                return False
            if not self._unit_hidden_singles():
                return False
            if not self._locked_candidates():
                return False
            if not self._naked_pairs():
                return False
            if not self._xwing():
                return False
            if self.cand == snapshot:
                return True

    def select_mrv_cell(self) -> int:
        # Minimum remaining values among unsolved
        best_i = -1
        best_k = 10**9
        for i, m in enumerate(self.cand):
            k = _popcount(m)
            if k > 1 and k < best_k:
                best_k = k
                best_i = i
                if k == 2:
                    break
        return best_i


def _search(state: State) -> State | None:
    if not state.propagate():
        return None
    if state.is_solved():
        return state
    idx = state.select_mrv_cell()
    if idx < 0:
        return None
    m = state.cand[idx]

    # Value ordering: try values that constrain peers most (least frequent in its units)
    N = state.N
    r = idx // N
    c = idx % N
    b = state.cell_to_box[idx]
    unit_cells = (state.rows[r], state.cols[c], state.boxes[b])

    freq = {}
    for bit in _iter_bits(m):
        f = 0
        for unit in unit_cells:
            for j in unit:
                if state.cand[j] & bit:
                    f += 1
        freq[bit] = f
    bits = sorted(freq, key=lambda x: freq[x])  # rarer first

    for bit in bits:
        v = bit.bit_length()
        s2 = state.copy()
        if s2.assign(idx, v):
            res = _search(s2)
            if res is not None:
                return res
    return None


def solve(observation):
    try:
        st = State(observation["data"], observation["unit"])
    except Exception:
        return "No Solution"
    res = _search(st)
    if res is None:
        return "No Solution"
    return str(res.grid())


