# Generalized Sudoku solver with strong human-like deduction + very limited branching.
# Supports NxN with subgrid of shape RxC (given by observation["unit"] like "3x3", "3x4", "4x4").
#
# Implemented techniques:
# - Basic constraint propagation with bitmasks
# - Naked singles
# - Hidden singles (row/col/box)
# - Naked pairs (row/col/box)
# - Pointing pairs/triples (box -> row/col)
# - Claiming (row/col -> box)
# - MRV branching with forward-checking, with "least constraining value" ordering
#
# No external libraries.

from __future__ import annotations

def solve(observation):
    data = observation["data"]
    unit = observation["unit"]
    br, bc = _parse_unit(unit)
    n = len(data)
    if n == 0 or any(len(r) != n for r in data):
        return "No Solution"
    if br * bc != n:
        return "No Solution"

    # Values are 1..n mapped to bits 0..n-1
    ALL = (1 << n) - 1

    # Precompute peers and units
    rows = [list(range(n)) for _ in range(n)]
    cols = [list(range(n)) for _ in range(n)]
    boxes = []
    box_index = [[0] * n for _ in range(n)]
    b = 0
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            cells = []
            for r in range(r0, r0 + br):
                for c in range(c0, c0 + bc):
                    cells.append((r, c))
                    box_index[r][c] = b
            boxes.append(cells)
            b += 1

    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]

    # Peers list for each cell
    peers = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            ps = set(row_cells[r] + col_cells[c] + boxes[box_index[r][c]])
            ps.discard((r, c))
            peers[r][c] = tuple(ps)

    # State: grid values (0 for empty), candidates bitmask for each cell
    grid = [[0] * n for _ in range(n)]
    cand = [[ALL] * n for _ in range(n)]

    # Initialize from givens with immediate propagation
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            if not _assign(grid, cand, peers, r, c, v, n):
                return "No Solution"

    # Solve with deduction + limited search
    ok = _search(grid, cand, peers, row_cells, col_cells, boxes, box_index, n, ALL)
    if not ok:
        return "No Solution"

    # Convert back to list-of-lists of ints
    out = [[grid[r][c] for c in range(n)] for r in range(n)]
    return str(out)


def _parse_unit(unit: str):
    if isinstance(unit, int):
        return unit, unit
    if "x" in unit:
        a, b = unit.lower().split("x", 1)
        return int(a), int(b)
    u = int(unit)
    return u, u


def _bit(v: int) -> int:
    return 1 << (v - 1)


def _popcount(x: int) -> int:
    return x.bit_count()


def _lsb_index(x: int) -> int:
    # x != 0
    return (x & -x).bit_length() - 1


def _mask_to_values(mask: int):
    # yields values 1..n corresponding to bits set; n not needed
    while mask:
        b = mask & -mask
        yield b.bit_length()
        mask ^= b


def _assign(grid, cand, peers, r, c, v, n):
    # Assign value v to (r,c) by eliminating all other candidates then propagate.
    if grid[r][c] == v:
        return True
    if grid[r][c] != 0 and grid[r][c] != v:
        return False
    m = cand[r][c]
    vb = _bit(v)
    if (m & vb) == 0:
        return False
    # eliminate others
    other = m & ~vb
    if other:
        if not _eliminate_mask(grid, cand, peers, r, c, other, n):
            return False
    return True


def _eliminate_mask(grid, cand, peers, r, c, elim_mask, n):
    # Remove bits in elim_mask from candidates at (r,c) and propagate singles.
    m = cand[r][c]
    if (m & elim_mask) == 0:
        return True
    m2 = m & ~elim_mask
    if m2 == 0:
        return False
    cand[r][c] = m2
    if grid[r][c] != 0:
        # already fixed, keep consistent
        if m2 != _bit(grid[r][c]):
            return False
        return True
    if (m2 & (m2 - 1)) == 0:
        # Naked single found
        v = m2.bit_length()
        grid[r][c] = v
        # propagate elimination to peers
        vb = m2
        for (pr, pc) in peers[r][c]:
            if not _eliminate_mask(grid, cand, peers, pr, pc, vb, n):
                return False
    return True


def _propagate(grid, cand, peers, row_cells, col_cells, boxes, box_index, n, ALL):
    # Repeat applying deduction rules until no progress.
    while True:
        progress = 0

        # 1) Ensure fixed cells have singleton candidates
        for r in range(n):
            for c in range(n):
                v = grid[r][c]
                if v:
                    vb = _bit(v)
                    if cand[r][c] != vb:
                        # force match
                        if not _assign(grid, cand, peers, r, c, v, n):
                            return False
                        progress += 1

        # 2) Hidden singles in rows/cols/boxes
        if _hidden_singles(grid, cand, peers, row_cells, n):
            progress += 1
        if _hidden_singles(grid, cand, peers, col_cells, n):
            progress += 1
        if _hidden_singles_boxes(grid, cand, peers, boxes, n):
            progress += 1

        # 3) Naked pairs in rows/cols/boxes
        if _naked_pairs_units(grid, cand, peers, row_cells, n):
            progress += 1
        if _naked_pairs_units(grid, cand, peers, col_cells, n):
            progress += 1
        if _naked_pairs_units(grid, cand, peers, boxes, n):
            progress += 1

        # 4) Pointing pairs/triples (box -> row/col)
        if _pointing(grid, cand, peers, boxes, box_index, n):
            progress += 1

        # 5) Claiming (row/col -> box)
        if _claiming(grid, cand, peers, row_cells, box_index, n):
            progress += 1
        if _claiming(grid, cand, peers, col_cells, box_index, n):
            progress += 1

        # Basic consistency checks: any unit has duplicate fixed values
        if not _check_consistency(grid, n, boxes, box_index):
            return False

        if progress == 0:
            break
    return True


def _check_consistency(grid, n, boxes, box_index):
    # duplicates in row/col/box among fixed numbers => invalid
    for r in range(n):
        seen = 0
        for c in range(n):
            v = grid[r][c]
            if v:
                b = 1 << (v - 1)
                if seen & b:
                    return False
                seen |= b
    for c in range(n):
        seen = 0
        for r in range(n):
            v = grid[r][c]
            if v:
                b = 1 << (v - 1)
                if seen & b:
                    return False
                seen |= b
    for cells in boxes:
        seen = 0
        for (r, c) in cells:
            v = grid[r][c]
            if v:
                b = 1 << (v - 1)
                if seen & b:
                    return False
                seen |= b
    return True


def _hidden_singles(grid, cand, peers, units, n):
    changed = False
    for unit_cells in units:
        # For each digit, count occurrences in candidates among unsolved cells
        # Use bit-aggregation approach: for each cell, for each candidate bit, add to counts.
        # Since n small (<=16 typical), iterate digits.
        present = 0
        for (r, c) in unit_cells:
            v = grid[r][c]
            if v:
                present |= _bit(v)

        for d in range(1, n + 1):
            db = _bit(d)
            if present & db:
                continue
            loc = None
            cnt = 0
            for (r, c) in unit_cells:
                if grid[r][c] == 0 and (cand[r][c] & db):
                    cnt += 1
                    loc = (r, c)
                    if cnt > 1:
                        break
            if cnt == 0:
                return False
            if cnt == 1:
                r, c = loc
                if not _assign(grid, cand, peers, r, c, d, n):
                    return False
                changed = True
    return changed


def _hidden_singles_boxes(grid, cand, peers, boxes, n):
    # Same as above but boxes list is already cell tuples
    changed = False
    for unit_cells in boxes:
        present = 0
        for (r, c) in unit_cells:
            v = grid[r][c]
            if v:
                present |= _bit(v)
        for d in range(1, n + 1):
            db = _bit(d)
            if present & db:
                continue
            loc = None
            cnt = 0
            for (r, c) in unit_cells:
                if grid[r][c] == 0 and (cand[r][c] & db):
                    cnt += 1
                    loc = (r, c)
                    if cnt > 1:
                        break
            if cnt == 0:
                return False
            if cnt == 1:
                r, c = loc
                if not _assign(grid, cand, peers, r, c, d, n):
                    return False
                changed = True
    return changed


def _naked_pairs_units(grid, cand, peers, units, n):
    changed = False
    for unit_cells in units:
        # Map candidate mask -> list of cells with exactly 2 candidates
        pairs = {}
        for (r, c) in unit_cells:
            if grid[r][c] != 0:
                continue
            m = cand[r][c]
            if _popcount(m) == 2:
                pairs.setdefault(m, []).append((r, c))
        for m, cells in pairs.items():
            if len(cells) == 2:
                # eliminate these two digits from other cells in unit
                for (r, c) in unit_cells:
                    if (r, c) in cells or grid[r][c] != 0:
                        continue
                    if cand[r][c] & m:
                        if not _eliminate_mask(grid, cand, peers, r, c, m, n):
                            return False
                        changed = True
    return changed


def _pointing(grid, cand, peers, boxes, box_index, n):
    # If in a box, a digit's candidates all lie in one row/col, eliminate from that row/col outside box.
    changed = False
    for b, cells in enumerate(boxes):
        # For each digit, collect rows/cols in which it appears as candidate
        rowmask = [0] * (n + 1)
        colmask = [0] * (n + 1)
        count = [0] * (n + 1)
        for (r, c) in cells:
            if grid[r][c] != 0:
                continue
            m = cand[r][c]
            while m:
                bb = m & -m
                d = bb.bit_length()
                count[d] += 1
                rowmask[d] |= (1 << r)
                colmask[d] |= (1 << c)
                m ^= bb
        for d in range(1, n + 1):
            if count[d] <= 1:
                continue
            rb = rowmask[d]
            cb = colmask[d]
            db = _bit(d)
            if rb and (rb & (rb - 1)) == 0:
                r = _lsb_index(rb)
                # eliminate in row r outside this box
                for c in range(n):
                    if box_index[r][c] == b or grid[r][c] != 0:
                        continue
                    if cand[r][c] & db:
                        if not _eliminate_mask(grid, cand, peers, r, c, db, n):
                            return False
                        changed = True
            if cb and (cb & (cb - 1)) == 0:
                c = _lsb_index(cb)
                # eliminate in col c outside this box
                for r in range(n):
                    if box_index[r][c] == b or grid[r][c] != 0:
                        continue
                    if cand[r][c] & db:
                        if not _eliminate_mask(grid, cand, peers, r, c, db, n):
                            return False
                        changed = True
    return changed


def _claiming(grid, cand, peers, line_units, box_index, n):
    # If in a row/col, a digit's candidates all lie within one box, eliminate from that box outside the row/col.
    changed = False
    for unit_cells in line_units:
        # Determine if row or col by checking coordinate variation
        is_row = all(unit_cells[i][0] == unit_cells[0][0] for i in range(len(unit_cells)))
        fixed_idx = unit_cells[0][0] if is_row else unit_cells[0][1]

        # For each digit collect boxes
        boxmask = [0] * (n + 1)
        count = [0] * (n + 1)
        for (r, c) in unit_cells:
            if grid[r][c] != 0:
                continue
            m = cand[r][c]
            b = box_index[r][c]
            while m:
                bb = m & -m
                d = bb.bit_length()
                count[d] += 1
                boxmask[d] |= (1 << b)
                m ^= bb

        for d in range(1, n + 1):
            if count[d] <= 1:
                continue
            bm = boxmask[d]
            if bm and (bm & (bm - 1)) == 0:
                b = _lsb_index(bm)
                db = _bit(d)
                # eliminate from box b outside this row/col
                # We don't have boxes list here; reconstruct by scanning grid
                for r in range(n):
                    for c in range(n):
                        if box_index[r][c] != b or grid[r][c] != 0:
                            continue
                        if is_row and r == fixed_idx:
                            continue
                        if (not is_row) and c == fixed_idx:
                            continue
                        if cand[r][c] & db:
                            if not _eliminate_mask(grid, cand, peers, r, c, db, n):
                                return False
                            changed = True
    return changed


def _is_solved(grid):
    for row in grid:
        for v in row:
            if v == 0:
                return False
    return True


def _select_unassigned_cell(grid, cand, n):
    # MRV: choose cell with smallest candidate count >1
    best = None
    best_cnt = 10**9
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                cnt = _popcount(cand[r][c])
                if cnt < best_cnt:
                    best_cnt = cnt
                    best = (r, c)
                    if cnt == 2:
                        return best
    return best


def _lcv_order(grid, cand, peers, r, c, n):
    # Least Constraining Value: sort candidates by how many eliminations they'd cause in peers.
    options = list(_mask_to_values(cand[r][c]))
    if len(options) <= 1:
        return options
    impacts = []
    for v in options:
        vb = _bit(v)
        impact = 0
        for (pr, pc) in peers[r][c]:
            if grid[pr][pc] == 0 and (cand[pr][pc] & vb):
                impact += 1
        impacts.append((impact, v))
    impacts.sort()
    return [v for _, v in impacts]


def _clone_state(grid, cand):
    return [row[:] for row in grid], [row[:] for row in cand]


def _search(grid, cand, peers, row_cells, col_cells, boxes, box_index, n, ALL):
    if not _propagate(grid, cand, peers, row_cells, col_cells, boxes, box_index, n, ALL):
        return False
    if _is_solved(grid):
        return True

    rc = _select_unassigned_cell(grid, cand, n)
    if rc is None:
        return False
    r, c = rc

    # Branch with LCV ordering; keep search shallow due to strong propagation.
    for v in _lcv_order(grid, cand, peers, r, c, n):
        g2, c2 = _clone_state(grid, cand)
        if _assign(g2, c2, peers, r, c, v, n):
            if _search(g2, c2, peers, row_cells, col_cells, boxes, box_index, n, ALL):
                # copy back
                for i in range(n):
                    grid[i] = g2[i]
                    cand[i] = c2[i]
                return True
    return False


if __name__ == "__main__":
    print(solve(OBSERVATION))

