from __future__ import annotations

# Efficient generalized Sudoku solver (NxN) with configurable subgrid size (r x c).
# Human-like inference: singles, hidden singles, locked candidates, naked/hidden pairs/triples,
# plus strong propagation and a minimal, highly-pruned search (MRV + LCV).
# No external libraries beyond Python stdlib.

from typing import List, Optional, Tuple, Dict


def solve(observation: dict) -> str:
    grid = observation["data"]
    unit = observation["unit"]
    r, c = _parse_unit(unit)
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"
    if r * c != n:
        return "No Solution"

    # Symbols are numbers 1..N
    full_mask = (1 << n) - 1

    # Precompute structures
    rows = [list(range(i * n, (i + 1) * n)) for i in range(n)]
    cols = [list(range(i, n * n, n)) for i in range(n)]
    boxes = _build_boxes(n, r, c)

    units_of_cell = [[] for _ in range(n * n)]
    peers = [0] * (n * n)  # bitset of peer indices not used; we'll keep as list for speed in loops
    peer_lists = [[] for _ in range(n * n)]
    all_units = rows + cols + boxes

    for u in all_units:
        for idx in u:
            units_of_cell[idx].append(u)

    # Build peer lists for each cell
    for i in range(n * n):
        pr = set()
        for u in units_of_cell[i]:
            for j in u:
                if j != i:
                    pr.add(j)
        peer_lists[i] = list(pr)

    # Masks for present digits in each unit
    row_used = [0] * n
    col_used = [0] * n
    box_used = [0] * n

    def box_index(rr: int, cc: int) -> int:
        return (rr // r) * (n // c) + (cc // c)

    # Domain masks for each cell (for filled cells: singleton mask)
    dom = [full_mask] * (n * n)

    # Initialize from givens with immediate contradiction checks
    for rr in range(n):
        for cc in range(n):
            v = grid[rr][cc]
            idx = rr * n + cc
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            bit = 1 << (v - 1)
            bi = box_index(rr, cc)
            if (row_used[rr] & bit) or (col_used[cc] & bit) or (box_used[bi] & bit):
                return "No Solution"
            row_used[rr] |= bit
            col_used[cc] |= bit
            box_used[bi] |= bit
            dom[idx] = bit

    # Reduce domains of empties based on used masks
    for rr in range(n):
        for cc in range(n):
            idx = rr * n + cc
            if grid[rr][cc] is not None:
                continue
            bi = box_index(rr, cc)
            dom[idx] = full_mask & ~(row_used[rr] | col_used[cc] | box_used[bi])
            if dom[idx] == 0:
                return "No Solution"

    # Work buffers
    # We'll maintain a stack of assignments for propagation in each search branch
    def is_single(m: int) -> bool:
        return m and (m & (m - 1)) == 0

    def bit_to_val(m: int) -> int:
        return (m.bit_length() - 1) + 1

    def popcount(x: int) -> int:
        return x.bit_count()

    # Apply assignment with trail for backtracking
    def assign(idx: int, val_bit: int, trail: List[Tuple[int, int, int, int, int, int]]) -> bool:
        rr, cc = divmod(idx, n)
        bi = box_index(rr, cc)
        old_dom = dom[idx]
        if old_dom == val_bit:
            return True
        # If val_bit not in domain -> contradiction
        if (old_dom & val_bit) == 0:
            return False

        # Save state: cell domain + unit used masks + grid value
        old_row = row_used[rr]
        old_col = col_used[cc]
        old_box = box_used[bi]
        old_grid = grid[rr][cc]
        trail.append((idx, old_dom, old_row, old_col, old_box, old_grid if old_grid is not None else 0))

        # Set the value
        dom[idx] = val_bit
        v = bit_to_val(val_bit)
        grid[rr][cc] = v

        # Update used masks; if conflict -> contradiction
        if (row_used[rr] & val_bit) or (col_used[cc] & val_bit) or (box_used[bi] & val_bit):
            return False
        row_used[rr] |= val_bit
        col_used[cc] |= val_bit
        box_used[bi] |= val_bit
        return True

    def unassign(trail: List[Tuple[int, int, int, int, int, int]], cut: int) -> None:
        # Restore in reverse order to exact previous state
        while len(trail) > cut:
            idx, old_dom, old_row, old_col, old_box, old_grid = trail.pop()
            rr, cc = divmod(idx, n)
            bi = box_index(rr, cc)
            dom[idx] = old_dom
            row_used[rr] = old_row
            col_used[cc] = old_col
            box_used[bi] = old_box
            grid[rr][cc] = None if old_grid == 0 else old_grid

    def eliminate_from_cell(idx: int, forbid_bits: int, trail: List[Tuple[int, int, int, int, int, int]]) -> bool:
        if forbid_bits == 0:
            return True
        if is_single(dom[idx]):
            return True
        newm = dom[idx] & ~forbid_bits
        if newm == dom[idx]:
            return True
        if newm == 0:
            return False
        # Save only domain change; we can store "used masks same" and "grid same" quickly:
        rr, cc = divmod(idx, n)
        bi = box_index(rr, cc)
        old_dom = dom[idx]
        old_row = row_used[rr]
        old_col = col_used[cc]
        old_box = box_used[bi]
        old_grid = grid[rr][cc]
        trail.append((idx, old_dom, old_row, old_col, old_box, old_grid if old_grid is not None else 0))
        dom[idx] = newm
        # If becomes single, assign it to propagate used masks correctly
        if is_single(newm):
            if not assign(idx, newm, trail):
                return False
        return True

    # Human-like deduction rules
    def propagate(trail: List[Tuple[int, int, int, int, int, int]]) -> bool:
        # Iterate until fixpoint
        # We prioritize fast contradictions using direct elimination from peers of assigned cells,
        # then apply unit-based techniques.
        changed = True
        while changed:
            changed = False

            # 1) Peer elimination from already assigned singles (forward checking)
            # We do this by scanning for singles and eliminating their bit from peers.
            for idx in range(n * n):
                if grid[idx // n][idx % n] is None:
                    continue
                vbit = dom[idx]
                # Ensure it's singleton
                if not is_single(vbit):
                    return False
                for p in peer_lists[idx]:
                    if grid[p // n][p % n] is None:
                        before = dom[p]
                        if before & vbit:
                            if not eliminate_from_cell(p, vbit, trail):
                                return False
                            if dom[p] != before:
                                changed = True

            # 2) Hidden singles in each unit (row/col/box)
            for unit_cells in all_units:
                # For each digit, track last position and count
                need = full_mask
                # remove used digits quickly using first cell coordinate mapping:
                # identify unit type by checking contiguity; easier: compute used by OR of assigned in unit.
                used = 0
                for idx in unit_cells:
                    if grid[idx // n][idx % n] is not None:
                        used |= dom[idx]
                need &= ~used
                if need == 0:
                    continue

                # For remaining digits, count placements
                # We'll do counting by iterating cells and accumulating bit->(count,last_idx)
                counts = [0] * n
                lastpos = [-1] * n
                for idx in unit_cells:
                    if grid[idx // n][idx % n] is not None:
                        continue
                    m = dom[idx] & need
                    while m:
                        b = m & -m
                        d = (b.bit_length() - 1)
                        counts[d] += 1
                        lastpos[d] = idx
                        m -= b
                m = need
                while m:
                    b = m & -m
                    d = (b.bit_length() - 1)
                    if counts[d] == 0:
                        return False  # no place for digit
                    if counts[d] == 1:
                        idx = lastpos[d]
                        if grid[idx // n][idx % n] is None:
                            if not assign(idx, b, trail):
                                return False
                            changed = True
                    m -= b

            # 3) Locked candidates (pointing & claiming)
            # For each box and each digit, if candidates confined to a single row/col -> eliminate outside box in that row/col
            for bidx, box in enumerate(boxes):
                # collect candidate locations per digit
                # For speed: build rowmask/colmask for each digit within box
                rows_for_d = [0] * n  # bitmask over rows 0..n-1
                cols_for_d = [0] * n  # bitmask over cols 0..n-1
                present = 0
                for idx in box:
                    rr, cc = divmod(idx, n)
                    if grid[rr][cc] is not None:
                        present |= dom[idx]
                        continue
                    m = dom[idx]
                    while m:
                        b = m & -m
                        d = (b.bit_length() - 1)
                        rows_for_d[d] |= 1 << rr
                        cols_for_d[d] |= 1 << cc
                        m -= b

                need = full_mask & ~present
                m = need
                while m:
                    b = m & -m
                    d = (b.bit_length() - 1)
                    rmask = rows_for_d[d]
                    cmask = cols_for_d[d]
                    if rmask and (rmask & (rmask - 1)) == 0:
                        rr = (rmask.bit_length() - 1)
                        # eliminate digit from row rr outside this box
                        for idx in rows[rr]:
                            if idx not in box:
                                if grid[idx // n][idx % n] is None and (dom[idx] & b):
                                    if not eliminate_from_cell(idx, b, trail):
                                        return False
                                    changed = True
                    if cmask and (cmask & (cmask - 1)) == 0:
                        cc = (cmask.bit_length() - 1)
                        for idx in cols[cc]:
                            if idx not in box:
                                if grid[idx // n][idx % n] is None and (dom[idx] & b):
                                    if not eliminate_from_cell(idx, b, trail):
                                        return False
                                    changed = True
                    m -= b

            # 4) Naked pairs/triples (generalized small-k) in each unit
            # We apply k=2 and k=3 for speed/benefit tradeoff.
            for unit_cells in all_units:
                empties = [idx for idx in unit_cells if grid[idx // n][idx % n] is None]
                if len(empties) < 2:
                    continue
                # Map domain mask -> list of cells
                mp: Dict[int, List[int]] = {}
                for idx in empties:
                    m = dom[idx]
                    pc = popcount(m)
                    if 2 <= pc <= 3:
                        mp.setdefault(m, []).append(idx)
                # Naked pairs/triples: if mask has size k and appears in exactly k cells -> eliminate from others
                for msk, cells in mp.items():
                    k = popcount(msk)
                    if len(cells) == k and k in (2, 3):
                        for idx in empties:
                            if idx in cells:
                                continue
                            if dom[idx] & msk:
                                if not eliminate_from_cell(idx, msk, trail):
                                    return False
                                changed = True

                # Hidden pairs/triples (lightweight):
                # For each digit, list cells; then try pairs via bitset of positions.
                if len(empties) <= 12:  # small enough for extra work
                    posmask_for_d = [0] * n  # bitmask over positions in empties list
                    for pi, idx in enumerate(empties):
                        m = dom[idx]
                        while m:
                            b = m & -m
                            d = (b.bit_length() - 1)
                            posmask_for_d[d] |= 1 << pi
                            m -= b
                    # hidden pairs
                    for d1 in range(n):
                        pm1 = posmask_for_d[d1]
                        if popcount(pm1) != 2:
                            continue
                        for d2 in range(d1 + 1, n):
                            pm2 = posmask_for_d[d2]
                            if pm1 == pm2 and popcount(pm2) == 2:
                                allow = (1 << d1) | (1 << d2)
                                for pi in range(len(empties)):
                                    if (pm1 >> pi) & 1:
                                        idx = empties[pi]
                                        if dom[idx] & ~allow:
                                            if not eliminate_from_cell(idx, dom[idx] & ~allow, trail):
                                                return False
                                            changed = True
                    # hidden triples (only if very small)
                    if len(empties) <= 9:
                        ds = [d for d in range(n) if 2 <= popcount(posmask_for_d[d]) <= 3]
                        for i in range(len(ds)):
                            for j in range(i + 1, len(ds)):
                                for k in range(j + 1, len(ds)):
                                    d1, d2, d3 = ds[i], ds[j], ds[k]
                                    pm = posmask_for_d[d1] | posmask_for_d[d2] | posmask_for_d[d3]
                                    if popcount(pm) == 3:
                                        allow = (1 << d1) | (1 << d2) | (1 << d3)
                                        for pi in range(len(empties)):
                                            if (pm >> pi) & 1:
                                                idx = empties[pi]
                                                if dom[idx] & ~allow:
                                                    if not eliminate_from_cell(idx, dom[idx] & ~allow, trail):
                                                        return False
                                                    changed = True
        return True

    def is_solved() -> bool:
        for rr in range(n):
            for cc in range(n):
                if grid[rr][cc] is None:
                    return False
        return True

    def choose_cell_mrv() -> int:
        best = -1
        bestc = 10**9
        for idx in range(n * n):
            if grid[idx // n][idx % n] is None:
                c = popcount(dom[idx])
                if c < bestc:
                    bestc = c
                    best = idx
                    if c <= 2:
                        return best
        return best

    def lcv_order(idx: int) -> List[int]:
        # Least-constraining value: sort by how many peer candidates it eliminates
        m = dom[idx]
        bits = []
        while m:
            b = m & -m
            bits.append(b)
            m -= b
        if len(bits) <= 1:
            return bits
        scores = []
        for b in bits:
            s = 0
            for p in peer_lists[idx]:
                if grid[p // n][p % n] is None and (dom[p] & b):
                    s += 1
            scores.append((s, b))
        scores.sort()
        return [b for _, b in scores]

    def dfs(trail: List[Tuple[int, int, int, int, int, int]]) -> bool:
        if is_solved():
            return True
        idx = choose_cell_mrv()
        if idx == -1:
            return False
        if dom[idx] == 0:
            return False

        # If any cell has domain size 1 but not assigned (shouldn't happen), enforce
        if is_single(dom[idx]) and grid[idx // n][idx % n] is None:
            cut = len(trail)
            if assign(idx, dom[idx], trail) and propagate(trail) and dfs(trail):
                return True
            unassign(trail, cut)
            return False

        for b in lcv_order(idx):
            cut = len(trail)
            if assign(idx, b, trail) and propagate(trail) and dfs(trail):
                return True
            unassign(trail, cut)
        return False

    trail: List[Tuple[int, int, int, int, int, int]] = []
    if not propagate(trail):
        return "No Solution"
    if not dfs(trail):
        return "No Solution"
    return str(grid)


def _parse_unit(unit: str) -> Tuple[int, int]:
    if isinstance(unit, int):
        return int(unit), int(unit)
    if "x" in unit:
        a, b = unit.lower().split("x")
        return int(a), int(b)
    u = int(unit)
    return u, u


def _build_boxes(n: int, r: int, c: int) -> List[List[int]]:
    boxes = []
    br = n // r
    bc = n // c
    for brr in range(br):
        for bcc in range(bc):
            cells = []
            r0 = brr * r
            c0 = bcc * c
            for dr in range(r):
                for dc in range(c):
                    rr = r0 + dr
                    cc = c0 + dc
                    cells.append(rr * n + cc)
            boxes.append(cells)
    return boxes


