# Generalized Sudoku solver with human-like deduction + fast exact-cover fallback search (not naive brute force).
# Supports arbitrary (r x c) subgrids such that N = r*c (e.g., 9,12,16). Symbols are integers 1..N.

from typing import List, Optional, Tuple, Dict

def solve(observation):
    grid = observation["data"]
    unit = observation["unit"]
    try:
        r, c = unit.lower().split("x")
        br, bc = int(r), int(c)
    except Exception:
        return "No Solution"

    N = br * bc
    if len(grid) != N or any(len(row) != N for row in grid):
        return "No Solution"

    # Precompute structures
    ALL = (1 << N) - 1  # bitmask for digits 1..N mapped to bits 0..N-1

    def bit(d):  # d in 1..N
        return 1 << (d - 1)

    def popcount(x: int) -> int:
        return x.bit_count()

    def lowbit_index(x: int) -> int:
        # x != 0
        return (x & -x).bit_length() - 1

    def iter_bits(x: int):
        while x:
            b = x & -x
            yield b
            x ^= b

    # Units and peers
    rows = [list(range(i * N, (i + 1) * N)) for i in range(N)]
    cols = [list(range(i, N * N, N)) for i in range(N)]
    boxes = []
    for rb in range(0, N, br):
        for cb in range(0, N, bc):
            box = []
            for rr in range(rb, rb + br):
                start = rr * N + cb
                box.extend(range(start, start + bc))
            boxes.append(box)
    units = rows + cols + boxes

    cell_units = [[] for _ in range(N * N)]
    for u in units:
        for idx in u:
            cell_units[idx].append(u)

    peers = [set() for _ in range(N * N)]
    for i in range(N * N):
        ps = set()
        for u in cell_units[i]:
            ps.update(u)
        ps.discard(i)
        peers[i] = ps

    # State: candidates bitmask per cell, and used masks per row/col/box
    cand = [ALL] * (N * N)
    row_used = [0] * N
    col_used = [0] * N
    box_used = [0] * N

    def box_index(r0: int, c0: int) -> int:
        return (r0 // br) * (N // bc) + (c0 // bc)

    # Initialize from givens
    for r0 in range(N):
        for c0 in range(N):
            v = grid[r0][c0]
            if v is None:
                continue
            if not (1 <= v <= N):
                return "No Solution"
            idx = r0 * N + c0
            b = bit(v)
            bi = box_index(r0, c0)
            if (row_used[r0] & b) or (col_used[c0] & b) or (box_used[bi] & b):
                return "No Solution"
            row_used[r0] |= b
            col_used[c0] |= b
            box_used[bi] |= b
            cand[idx] = b

    # After used masks set, restrict candidates for empties
    for r0 in range(N):
        for c0 in range(N):
            idx = r0 * N + c0
            if cand[idx] != ALL and popcount(cand[idx]) == 1:
                continue
            bi = box_index(r0, c0)
            forbidden = row_used[r0] | col_used[c0] | box_used[bi]
            cand[idx] = ALL & ~forbidden
            if cand[idx] == 0:
                return "No Solution"

    # Trail for undo
    trail: List[Tuple[int, int]] = []  # (idx, previous_mask)
    trail_used: List[Tuple[str, int, int]] = []  # (which, index, previous_mask)
    assigned_stack: List[int] = []  # indices assigned in order for propagation queue

    def save_cand(i: int, newmask: int):
        if cand[i] != newmask:
            trail.append((i, cand[i]))
            cand[i] = newmask

    def save_used(which: str, i: int, newmask: int):
        if which == "r":
            prev = row_used[i]
            if prev != newmask:
                trail_used.append((which, i, prev))
                row_used[i] = newmask
        elif which == "c":
            prev = col_used[i]
            if prev != newmask:
                trail_used.append((which, i, prev))
                col_used[i] = newmask
        else:
            prev = box_used[i]
            if prev != newmask:
                trail_used.append((which, i, prev))
                box_used[i] = newmask

    def checkpoint():
        return (len(trail), len(trail_used), len(assigned_stack))

    def undo(cp):
        tlen, ulen, alen = cp
        while len(assigned_stack) > alen:
            assigned_stack.pop()
        while len(trail) > tlen:
            i, prev = trail.pop()
            cand[i] = prev
        while len(trail_used) > ulen:
            which, i, prev = trail_used.pop()
            if which == "r":
                row_used[i] = prev
            elif which == "c":
                col_used[i] = prev
            else:
                box_used[i] = prev

    # Core assignment + propagation
    def assign(i: int, vmask: int) -> bool:
        # i set to vmask (single bit)
        if cand[i] == vmask:
            return True
        if cand[i] & vmask == 0:
            return False
        save_cand(i, vmask)
        assigned_stack.append(i)

        r0, c0 = divmod(i, N)
        bi = box_index(r0, c0)
        b = vmask

        # Check no conflicts in used masks
        if (row_used[r0] & b) and cand[i] != b:
            return False
        if (col_used[c0] & b) and cand[i] != b:
            return False
        if (box_used[bi] & b) and cand[i] != b:
            return False

        save_used("r", r0, row_used[r0] | b)
        save_used("c", c0, col_used[c0] | b)
        save_used("b", bi, box_used[bi] | b)

        # Remove b from peers
        for p in peers[i]:
            pm = cand[p]
            if pm & b:
                nm = pm & ~b
                if nm == 0:
                    return False
                save_cand(p, nm)
                if popcount(nm) == 1:
                    # will be handled by propagation loop if not already assigned
                    assigned_stack.append(p)
        return True

    def propagate() -> bool:
        # Two-phase: process newly-singleton cells; then apply unit deductions repeatedly until fixpoint.
        # Using a loop with flags to avoid scanning too much.
        qpos = 0
        changed = True
        while changed:
            changed = False

            # Process any singletons discovered
            while qpos < len(assigned_stack):
                i = assigned_stack[qpos]
                qpos += 1
                m = cand[i]
                if popcount(m) != 1:
                    continue
                # Ensure used masks are consistent and propagate peer removals already applied.
                r0, c0 = divmod(i, N)
                bi = box_index(r0, c0)
                b = m
                # If used doesn't include b, add it; if contradictions, fail.
                if (row_used[r0] & b) == 0:
                    save_used("r", r0, row_used[r0] | b)
                    changed = True
                if (col_used[c0] & b) == 0:
                    save_used("c", c0, col_used[c0] | b)
                    changed = True
                if (box_used[bi] & b) == 0:
                    save_used("b", bi, box_used[bi] | b)
                    changed = True

                for p in peers[i]:
                    pm = cand[p]
                    if pm & b:
                        nm = pm & ~b
                        if nm == 0:
                            return False
                        save_cand(p, nm)
                        if popcount(nm) == 1:
                            assigned_stack.append(p)
                        changed = True

            # Unit-based deductions: hidden singles + locked candidates
            # Hidden singles
            for u in units:
                # For each digit, track occurrences.
                # Build counts by bit accumulation.
                # occ_mask[d] not stored; instead use bitwise trick:
                # seen_once bitmask for digits seen exactly once; seen_more for digits seen >=2
                seen_once = 0
                seen_more = 0
                where = {}  # only for digits that are currently in seen_once; maps bit->cell index
                for i in u:
                    m = cand[i]
                    # Only consider unassigned
                    if popcount(m) == 1:
                        continue
                    # Iterate bits in m
                    x = m
                    while x:
                        b = x & -x
                        x ^= b
                        if seen_more & b:
                            continue
                        if seen_once & b:
                            seen_once ^= b
                            seen_more |= b
                            where.pop(b, None)
                        else:
                            seen_once |= b
                            where[b] = i
                # Assign digits that appear exactly once
                for b, i in where.items():
                    if popcount(cand[i]) != 1:
                        if not assign(i, b):
                            return False
                        changed = True

            # Locked candidates (pointing & claiming) per box
            # For each box and digit, if candidates are confined to one row/col within the box -> eliminate from that row/col outside box.
            for bi, box in enumerate(boxes):
                # digit -> rowmask/colmask within box, and cells list
                # Use dict only for digits that appear
                d_rows: Dict[int, int] = {}
                d_cols: Dict[int, int] = {}
                d_cells: Dict[int, List[int]] = {}
                for i in box:
                    m = cand[i]
                    if popcount(m) == 1:
                        continue
                    r0, c0 = divmod(i, N)
                    x = m
                    while x:
                        b = x & -x
                        x ^= b
                        d_rows[b] = d_rows.get(b, 0) | (1 << r0)
                        d_cols[b] = d_cols.get(b, 0) | (1 << c0)
                        d_cells.setdefault(b, []).append(i)
                for b, cells in d_cells.items():
                    rm = d_rows[b]
                    cm = d_cols[b]
                    if rm and (rm & (rm - 1)) == 0:
                        # confined to single row
                        r0 = lowbit_index(rm)
                        for j in rows[r0]:
                            if j not in box and (cand[j] & b):
                                nm = cand[j] & ~b
                                if nm == 0:
                                    return False
                                save_cand(j, nm)
                                if popcount(nm) == 1:
                                    assigned_stack.append(j)
                                changed = True
                    if cm and (cm & (cm - 1)) == 0:
                        c0 = lowbit_index(cm)
                        for j in cols[c0]:
                            if j not in box and (cand[j] & b):
                                nm = cand[j] & ~b
                                if nm == 0:
                                    return False
                                save_cand(j, nm)
                                if popcount(nm) == 1:
                                    assigned_stack.append(j)
                                changed = True

        return True

    # Apply initial propagation from givens
    for i in range(N * N):
        if popcount(cand[i]) == 1:
            assigned_stack.append(i)
    if not propagate():
        return "No Solution"

    def is_solved() -> bool:
        return all(popcount(cand[i]) == 1 for i in range(N * N))

    # Exact-cover style search with strong branching (MRV + max degree + digit frequency)
    def choose_cell() -> int:
        best = -1
        best_pc = 10**9
        best_deg = -1
        for i in range(N * N):
            pc = popcount(cand[i])
            if pc == 1:
                continue
            if pc < best_pc:
                best_pc = pc
                best = i
                best_deg = len([p for p in peers[i] if popcount(cand[p]) > 1])
                if pc == 2:
                    # can't do better than 2
                    pass
            elif pc == best_pc:
                deg = len([p for p in peers[i] if popcount(cand[p]) > 1])
                if deg > best_deg:
                    best = i
                    best_deg = deg
        return best

    def order_values(i: int) -> List[int]:
        # Least-constraining-value: try digits that eliminate fewer candidates from peers
        m = cand[i]
        scores = []
        for b in iter_bits(m):
            elim = 0
            for p in peers[i]:
                if cand[p] & b:
                    elim += 1
            scores.append((elim, b))
        scores.sort(key=lambda x: x[0])
        return [b for _, b in scores]

    def search() -> bool:
        if is_solved():
            return True
        i = choose_cell()
        if i < 0:
            return False
        for b in order_values(i):
            cp = checkpoint()
            if assign(i, b) and propagate() and search():
                return True
            undo(cp)
        return False

    if not search():
        return "No Solution"

    # Build solved grid
    out = [[0] * N for _ in range(N)]
    for r0 in range(N):
        for c0 in range(N):
            m = cand[r0 * N + c0]
            if popcount(m) != 1:
                return "No Solution"
            out[r0][c0] = lowbit_index(m) + 1
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

