# Solver for: shade cells so that
# - each region has exactly 2 shaded cells
# - shaded cells form dominoes (adjacent orthogonally, pairwise)
# - distinct dominoes cannot touch orthogonally (diagonal ok)
# - dominoes may cross regions
#
# Approach:
# Represent solution as a set of domino placements (unordered adjacent cell pairs).
# Each cell is either unused or used by exactly one domino.
# Constraints become:
# 1) Region counts: sum of used cells in region == 2.
# 2) Non-touching: if a domino uses cells a,b then any other domino cannot use any orth-neighbor of a or b,
#    except the partner cell inside same domino.
# We perform aggressive constraint propagation:
# - Maintain per-cell domain: available (can still be used) vs forbidden.
# - Maintain per-region remaining required used cells.
# - Maintain per-region remaining available capacity (how many cells could still be used).
# - Enforce forced usage/forbiddance when region must take all remaining cells, or cannot take any more.
# - Enforce forced domino when a cell must be used and has only one compatible partner.
# Search:
# - Choose next branching via most constrained region/cell (MRV): region with smallest number of feasible 2-cell selections,
#   or required cell with smallest partner options.
# - Branch by placing a feasible domino, with forward checking.
#
# Note: No external solvers used.

from collections import defaultdict, deque

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"

    # Indexing helpers
    def idx(r, c): return r * n + c
    def rc(i): return divmod(i, n)

    # Neighbors
    nbr4 = [[] for _ in range(n*n)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r: nbr4[i].append(idx(r-1, c))
            if r+1 < n: nbr4[i].append(idx(r+1, c))
            if c: nbr4[i].append(idx(r, c-1))
            if c+1 < n: nbr4[i].append(idx(r, c+1))

    # Regions
    region_of = [0]*(n*n)
    regions = defaultdict(list)
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            rid = grid[r][c]
            region_of[i] = rid
            regions[rid].append(i)
    region_ids = list(regions.keys())
    R = len(region_ids)

    # Each region must have exactly 2 shaded cells
    target = {rid: 2 for rid in region_ids}

    # Quick infeasibility check: region size must be >=2
    for rid, cells in regions.items():
        if len(cells) < 2:
            return "No Solution"

    # Precompute all adjacent pairs (domino candidates)
    # Represent domino as ordered tuple (min, max)
    dom_partners = [[] for _ in range(n*n)]
    dominos = []
    domino_index = {}
    for i in range(n*n):
        for j in nbr4[i]:
            if i < j:
                d = (i, j)
                domino_index[d] = len(dominos)
                dominos.append(d)
                dom_partners[i].append(j)
                dom_partners[j].append(i)

    # For non-touching constraint: if cell x is used, then all its orth neighbors (except its domino mate) are blocked for use.
    # We'll enforce by forbidding cells in a "blocked" set when placing a domino: block neighbors of both cells, excluding each other.
    # A cell can be in three states: 0=unknown, 1=forbidden (must be unshaded), 2=used (shaded, belongs to a domino).
    UNKNOWN, FORBID, USED = 0, 1, 2

    # State object with reversible trail
    class State:
        __slots__ = (
            "cell_state", "mate", "region_used", "region_forbid", "region_unknown",
            "trail", "queue"
        )
        def __init__(self):
            self.cell_state = [UNKNOWN]*(n*n)
            self.mate = [-1]*(n*n)  # if USED, mate index else -1
            self.region_used = {rid: 0 for rid in region_ids}
            self.region_forbid = {rid: 0 for rid in region_ids}
            self.region_unknown = {rid: len(regions[rid]) for rid in region_ids}
            self.trail = []
            self.queue = deque()

        def snapshot(self):
            return len(self.trail)

        def rollback(self, snap):
            while len(self.trail) > snap:
                typ, a, b = self.trail.pop()
                if typ == "cell":
                    i, prev_state, prev_mate = a, b[0], b[1]
                    cur_state = self.cell_state[i]
                    if cur_state != prev_state:
                        # update region counts
                        rid = region_of[i]
                        if cur_state == UNKNOWN:
                            pass
                        elif cur_state == FORBID:
                            self.region_forbid[rid] -= 1
                            self.region_unknown[rid] += 1
                        elif cur_state == USED:
                            self.region_used[rid] -= 1
                            self.region_unknown[rid] += 1
                        if prev_state == UNKNOWN:
                            pass
                        elif prev_state == FORBID:
                            self.region_forbid[rid] += 1
                            self.region_unknown[rid] -= 1
                        elif prev_state == USED:
                            self.region_used[rid] += 1
                            self.region_unknown[rid] -= 1
                    self.cell_state[i] = prev_state
                    self.mate[i] = prev_mate
                elif typ == "noop":
                    continue

        def set_cell(self, i, new_state, new_mate=-1):
            old_state = self.cell_state[i]
            old_mate = self.mate[i]
            if old_state == new_state and old_mate == new_mate:
                return True
            # Contradictions
            if old_state == USED and new_state != USED:
                return False
            if old_state == FORBID and new_state == USED:
                return False
            if old_state == USED and new_state == USED and old_mate != -1 and new_mate != -1 and old_mate != new_mate:
                return False

            # Record trail
            self.trail.append(("cell", i, (old_state, old_mate)))

            # Update region counts if state changes between UNKNOWN/FORBID/USED
            rid = region_of[i]
            if old_state != new_state:
                if old_state == UNKNOWN:
                    self.region_unknown[rid] -= 1
                elif old_state == FORBID:
                    self.region_forbid[rid] -= 1
                    self.region_unknown[rid] += 1
                elif old_state == USED:
                    self.region_used[rid] -= 1
                    self.region_unknown[rid] += 1

                if new_state == UNKNOWN:
                    self.region_unknown[rid] += 1
                elif new_state == FORBID:
                    self.region_forbid[rid] += 1
                elif new_state == USED:
                    self.region_used[rid] += 1

            self.cell_state[i] = new_state
            self.mate[i] = new_mate
            # Enqueue affected region for propagation
            self.queue.append(("region", rid))
            # Enqueue cell if it becomes USED or FORBID to trigger local propagation
            self.queue.append(("cell", i))
            return True

        def place_domino(self, a, b):
            # a,b adjacent
            if self.cell_state[a] == FORBID or self.cell_state[b] == FORBID:
                return False
            if self.cell_state[a] == USED and self.mate[a] not in (-1, b):
                return False
            if self.cell_state[b] == USED and self.mate[b] not in (-1, a):
                return False
            if not self.set_cell(a, USED, b): return False
            if not self.set_cell(b, USED, a): return False

            # Non-touching: forbid orth neighbors of a (except b), and of b (except a), unless already USED by this domino
            for x, y in ((a, b), (b, a)):
                for nb in nbr4[x]:
                    if nb == y:
                        continue
                    # If neighbor is USED, that's a conflict (dominoes would touch orthogonally)
                    if self.cell_state[nb] == USED:
                        return False
                    if self.cell_state[nb] == UNKNOWN:
                        if not self.set_cell(nb, FORBID, -1):
                            return False
            return True

        def feasible_partner_count(self, i):
            # if i must/should be used, count partners j such that domino (i,j) can be placed given current forbiddances
            if self.cell_state[i] == FORBID:
                return 0
            if self.cell_state[i] == USED:
                m = self.mate[i]
                return 1 if m != -1 else 0
            cnt = 0
            for j in dom_partners[i]:
                if self.cell_state[j] != UNKNOWN:
                    if self.cell_state[j] == USED:
                        continue
                    if self.cell_state[j] == FORBID:
                        continue
                # Check touch constraint quickly: if j is adjacent, placing domino would forbid neighbors;
                # conflict if any neighbor of i (except j) is USED, or neighbor of j (except i) is USED.
                ok = True
                for nb in nbr4[i]:
                    if nb != j and self.cell_state[nb] == USED:
                        ok = False; break
                if ok:
                    for nb in nbr4[j]:
                        if nb != i and self.cell_state[nb] == USED:
                            ok = False; break
                if ok:
                    cnt += 1
            return cnt

        def propagate(self):
            # Returns False on contradiction
            while self.queue:
                kind, x = self.queue.popleft()
                if kind == "region":
                    rid = x
                    used = self.region_used[rid]
                    unknown = self.region_unknown[rid]
                    # remaining needed
                    need = target[rid] - used
                    if need < 0:
                        return False
                    if need > unknown:
                        return False
                    if need == 0:
                        # forbid all remaining unknown in region
                        for i in regions[rid]:
                            if self.cell_state[i] == UNKNOWN:
                                if not self.set_cell(i, FORBID, -1):
                                    return False
                    elif need == unknown:
                        # all remaining unknown must be used (but as part of dominoes)
                        # mark as "must be used" by not setting USED directly; instead enforce later via cell propagation:
                        # Here we enqueue each such cell with a special check by setting a noop and pushing to cell queue.
                        for i in regions[rid]:
                            if self.cell_state[i] == UNKNOWN:
                                # Can't directly set USED because mate unknown; just ensure it cannot become FORBID later by forcing decision.
                                # We'll implement must-use by checking in cell handler when region forces it.
                                self.queue.append(("mustuse", i))
                elif kind == "mustuse":
                    i = x
                    if self.cell_state[i] != UNKNOWN:
                        continue
                    # If a cell is forced to be used, it must have at least one possible partner
                    if self.feasible_partner_count(i) == 0:
                        return False
                    # If only one partner possible, force that domino
                    # Enumerate partners and if unique, place
                    choices = []
                    for j in dom_partners[i]:
                        if self.cell_state[j] == FORBID or self.cell_state[j] == USED:
                            continue
                        ok = True
                        for nb in nbr4[i]:
                            if nb != j and self.cell_state[nb] == USED:
                                ok = False; break
                        if ok:
                            for nb in nbr4[j]:
                                if nb != i and self.cell_state[nb] == USED:
                                    ok = False; break
                        if ok:
                            choices.append(j)
                            if len(choices) > 1:
                                break
                    if len(choices) == 1:
                        if not self.place_domino(i, choices[0]):
                            return False
                elif kind == "cell":
                    i = x
                    st = self.cell_state[i]
                    if st == USED:
                        # If used, mate must be consistent; nothing more
                        continue
                    if st == FORBID:
                        continue
                    # UNKNOWN: check if it has become impossible to be used due to no partners;
                    # but we cannot forbid it unless region doesn't need it. Still, we can detect contradictions
                    # when region requires too many and this cell is unusable (handled via mustuse).
                    pass

            # Additional global pruning: for each region, ensure there exist enough "potentially usable" cells to meet need
            for rid in region_ids:
                need = target[rid] - self.region_used[rid]
                if need < 0:
                    return False
                if need == 0:
                    continue
                # count cells in region that are not FORBID and could still be used (have a partner) if UNKNOWN
                pot = 0
                for i in regions[rid]:
                    if self.cell_state[i] == USED:
                        continue
                    if self.cell_state[i] == FORBID:
                        continue
                    # UNKNOWN: must be able to have some partner
                    if self.feasible_partner_count(i) > 0:
                        pot += 1
                if pot < need:
                    return False
            return True

    def is_complete(st: State):
        for rid in region_ids:
            if st.region_used[rid] != 2:
                return False
        # also ensure all USED cells are paired (mate set)
        for i in range(n*n):
            if st.cell_state[i] == USED and st.mate[i] == -1:
                return False
        return True

    def pick_branch(st: State):
        # Prefer a region that still needs cells, choose a "must-be-used soon" cell with minimal partner options
        best_cell = None
        best_opts = 10**9

        # Try cells in regions with need>0
        for rid in region_ids:
            need = target[rid] - st.region_used[rid]
            if need <= 0:
                continue
            for i in regions[rid]:
                if st.cell_state[i] != UNKNOWN:
                    continue
                opts = st.feasible_partner_count(i)
                if opts == 0:
                    continue
                if opts < best_opts:
                    best_opts = opts
                    best_cell = i
                    if opts == 1:
                        return best_cell, best_opts
        return best_cell, best_opts if best_cell is not None else (None, None)

    def dfs(st: State):
        if not st.propagate():
            return None
        if is_complete(st):
            return st

        cell, _ = pick_branch(st)
        if cell is None:
            return None

        # Enumerate possible partner placements for this cell, prefer partners that satisfy region needs
        partners = []
        for j in dom_partners[cell]:
            if st.cell_state[j] == FORBID or st.cell_state[j] == USED:
                continue
            ok = True
            for nb in nbr4[cell]:
                if nb != j and st.cell_state[nb] == USED:
                    ok = False; break
            if ok:
                for nb in nbr4[j]:
                    if nb != cell and st.cell_state[nb] == USED:
                        ok = False; break
            if not ok:
                continue
            partners.append(j)

        # Heuristic ordering: prefer partner whose regions still need cells
        def score(j):
            return (target[region_of[j]] - st.region_used[region_of[j]]) + (target[region_of[cell]] - st.region_used[region_of[cell]])
        partners.sort(key=score, reverse=True)

        snap = st.snapshot()
        for j in partners:
            st.rollback(snap)
            if st.place_domino(cell, j):
                res = dfs(st)
                if res is not None:
                    return res
        st.rollback(snap)
        return None

    st = State()
    res = dfs(st)
    if res is None:
        return "No Solution"

    out = [[None]*n for _ in range(n)]
    for i in range(n*n):
        if res.cell_state[i] == USED:
            r, c = rc(i)
            out[r][c] = "S"
    return str(out)

