from __future__ import annotations
from dataclasses import dataclass
from typing import Dict, Tuple, List, Optional, Set
from collections import deque, defaultdict

Pos = Tuple[int, int]
EdgeKey = Tuple[Pos, Pos]  # canonical ordered endpoints


def canon(a: Pos, b: Pos) -> EdgeKey:
    return (a, b) if a <= b else (b, a)


@dataclass(frozen=True)
class Edge:
    a: int
    b: int
    # path cells strictly between endpoints (used for crossing checks)
    cells: Tuple[Pos, ...]
    # orientation: 0 horiz, 1 vert
    orient: int


class DSU:
    __slots__ = ("p", "r", "cnt")

    def __init__(self, n: int):
        self.p = list(range(n))
        self.r = [0] * n
        self.cnt = n

    def find(self, x: int) -> int:
        p = self.p
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1
        self.cnt -= 1
        return True

    def copy(self) -> "DSU":
        d = DSU(0)
        d.p = self.p[:]
        d.r = self.r[:]
        d.cnt = self.cnt
        return d


class HashiSolver:
    def __init__(self, grid: List[List[Optional[int]]]):
        self.grid = grid
        self.H = len(grid)
        self.W = len(grid[0]) if self.H else 0

        # islands
        self.islands: List[Pos] = []
        self.req: List[int] = []
        self.idx: Dict[Pos, int] = {}

        for r in range(self.H):
            for c in range(self.W):
                v = grid[r][c]
                if isinstance(v, int):
                    i = len(self.islands)
                    self.islands.append((r, c))
                    self.req.append(v)
                    self.idx[(r, c)] = i

        self.n = len(self.islands)
        if self.n == 0:
            raise ValueError("No islands found.")

        # possible edges between visible islands
        self.edges: List[Edge] = []
        self.adj_edges: List[List[int]] = [[] for _ in range(self.n)]
        self.edge_index_by_key: Dict[EdgeKey, int] = {}

        self._build_edges()

        # crossing constraints: edges that share any intermediate cell (they "block" each other)
        self.blockers: List[Set[int]] = [set() for _ in range(len(self.edges))]
        self._build_blockers()

        # mapping from cell to edges that use it
        self.cell_to_edges: Dict[Pos, List[int]] = defaultdict(list)
        for ei, e in enumerate(self.edges):
            for cell in e.cells:
                self.cell_to_edges[cell].append(ei)

        # state
        self.assigned = [0] * len(self.edges)  # 0,1,2
        self.rem = self.req[:]                 # remaining degree per island
        self.dsu = DSU(self.n)
        self.used_edges = 0

    def _build_edges(self):
        # For each island, scan right and down to find nearest island in that direction.
        for i, (r, c) in enumerate(self.islands):
            # right
            cc = c + 1
            while cc < self.W and self.grid[r][cc] is None:
                cc += 1
            if cc < self.W and isinstance(self.grid[r][cc], int):
                j = self.idx[(r, cc)]
                cells = tuple((r, x) for x in range(c + 1, cc))
                e = Edge(a=i, b=j, cells=cells, orient=0)
                ek = canon(self.islands[i], self.islands[j])
                self.edge_index_by_key[ek] = len(self.edges)
                self.edges.append(e)

            # down
            rr = r + 1
            while rr < self.H and self.grid[rr][c] is None:
                rr += 1
            if rr < self.H and isinstance(self.grid[rr][c], int):
                j = self.idx[(rr, c)]
                cells = tuple((x, c) for x in range(r + 1, rr))
                e = Edge(a=i, b=j, cells=cells, orient=1)
                ek = canon(self.islands[i], self.islands[j])
                self.edge_index_by_key[ek] = len(self.edges)
                self.edges.append(e)

        # build adjacency lists
        for ei, e in enumerate(self.edges):
            self.adj_edges[e.a].append(ei)
            self.adj_edges[e.b].append(ei)

    def _build_blockers(self):
        # Two edges block each other if any intermediate cell is shared (cannot cross or overlap).
        # Overlap cannot occur in standard Hashi (since edges are between nearest islands), but crossing can.
        cell_map: Dict[Pos, List[int]] = defaultdict(list)
        for ei, e in enumerate(self.edges):
            for cell in e.cells:
                cell_map[cell].append(ei)
        for cell, lst in cell_map.items():
            if len(lst) > 1:
                # all edges through this cell block each other
                for i in range(len(lst)):
                    a = lst[i]
                    for j in range(i + 1, len(lst)):
                        b = lst[j]
                        if a != b:
                            self.blockers[a].add(b)
                            self.blockers[b].add(a)

    # ---------- Core constraint helpers ----------

    def max_cap_edge(self, ei: int) -> int:
        """Maximum still possible value for this edge given island remaining and blockers."""
        cur = self.assigned[ei]
        if cur == 2:
            return 2
        e = self.edges[ei]
        if self.rem[e.a] == 0 or self.rem[e.b] == 0:
            return cur  # cannot add more
        # if any blocker already has >0, this edge cannot be >0 unless it already is
        if cur == 0:
            for bj in self.blockers[ei]:
                if self.assigned[bj] > 0:
                    return 0
        # remaining degree bounds
        # can raise to at most min(2, rem_a, rem_b) but not below current
        return min(2, cur + min(2 - cur, self.rem[e.a], self.rem[e.b]))

    def domain_edge(self, ei: int) -> Tuple[int, ...]:
        """Possible values consistent with immediate constraints."""
        cur = self.assigned[ei]
        e = self.edges[ei]

        # blockers: if any crossing edge already >0 and cur==0 -> only 0
        if cur == 0:
            for bj in self.blockers[ei]:
                if self.assigned[bj] > 0:
                    return (0,)
        # rem bounds: cannot exceed rem on either endpoint, and cannot decrease below cur
        hi = min(2, self.rem[e.a] + cur, self.rem[e.b] + cur)  # how many total could be incident incl current
        # Actually rem is remaining excluding current edge, but cur already counted as placed.
        # So additional possible total on this edge is [cur..min(2, cur+rem_a, cur+rem_b)]
        hi = min(2, cur + self.rem[e.a], cur + self.rem[e.b])
        lo = cur
        vals = []
        for v in range(lo, hi + 1):
            # if v==0 and cur==0 ok
            vals.append(v)
        return tuple(vals)

    def island_caps(self, i: int) -> Tuple[int, int]:
        """Return (min_possible, max_possible) additional sum from incident edges relative to current assignment."""
        rem = self.rem[i]
        # max additional is sum of per-edge remaining capacity
        max_add = 0
        for ei in self.adj_edges[i]:
            cap = self.max_cap_edge(ei) - self.assigned[ei]
            if cap > 0:
                max_add += cap
        return (0, max_add)  # min additional not computed here

    def check_feasible(self) -> bool:
        # Degree feasibility: each island rem between 0 and sum of remaining capacities
        for i in range(self.n):
            if self.rem[i] < 0:
                return False
            _, max_add = self.island_caps(i)
            if self.rem[i] > max_add:
                return False
        # Connectivity feasibility lower bound: If already have multiple components,
        # we need at least (components-1) edges with positive value possible between components.
        # Quick prune: compute potential inter-component adjacency edges that could become >0.
        comps = self._components_count()
        if comps == 1:
            return True
        need = comps - 1

        # count candidate edges that can connect different components and are not forced zero
        cand = 0
        for ei, e in enumerate(self.edges):
            if self.assigned[ei] > 0:
                continue
            # must be possible to set to at least 1
            dom = self.domain_edge(ei)
            if 1 not in dom and 2 not in dom:
                continue
            if self.dsu.find(e.a) != self.dsu.find(e.b):
                cand += 1
        return cand >= need

    def _components_count(self) -> int:
        # DSU count includes isolated islands even if some have rem==0; still must be connected.
        # Recompute actual count among all islands.
        roots = set(self.dsu.find(i) for i in range(self.n))
        return len(roots)

    # ---------- Deduction rules ----------

    def propagate(self) -> bool:
        """Aggressive constraint propagation. Returns False if contradiction found."""
        q_island = deque(range(self.n))
        q_edge = deque(range(len(self.edges)))
        in_q_is = [True] * self.n
        in_q_ed = [True] * len(self.edges)

        def enqueue_is(i: int):
            if not in_q_is[i]:
                in_q_is[i] = True
                q_island.append(i)

        def enqueue_ed(ei: int):
            if not in_q_ed[ei]:
                in_q_ed[ei] = True
                q_edge.append(ei)

        while q_island or q_edge:
            while q_edge:
                ei = q_edge.popleft()
                in_q_ed[ei] = False
                dom = self.domain_edge(ei)
                cur = self.assigned[ei]
                if cur not in dom:
                    return False
                if len(dom) == 1 and dom[0] != cur:
                    if not self._set_edge(ei, dom[0]):
                        return False
                    e = self.edges[ei]
                    enqueue_is(e.a); enqueue_is(e.b)
                    for bj in self.blockers[ei]:
                        enqueue_ed(bj)

            while q_island:
                i = q_island.popleft()
                in_q_is[i] = False
                if self.rem[i] < 0:
                    return False
                # compute per-edge available add capacity and also detect forced assignments:
                avail = []
                sum_cap = 0
                sum_min = 0
                for ei in self.adj_edges[i]:
                    cur = self.assigned[ei]
                    dom = self.domain_edge(ei)
                    mn = min(dom)
                    mx = max(dom)
                    # dom always includes cur, so mn<=cur<=mx
                    sum_min += mn
                    sum_cap += mx
                    avail.append((ei, mn, mx))

                # island needs total degree = req, and current incident sum is fixed.
                # We track rem, so required additional beyond current is rem[i].
                # The additional possible beyond current equals sum(mx-cur) etc.
                # Two human-like deductions:
                # (1) If rem == 0 -> all incident edges forced to their minimum (which is current).
                if self.rem[i] == 0:
                    for ei, mn, mx in avail:
                        # force to current (already), but if dom would allow >cur, keep; no action
                        continue

                # (2) If rem equals sum of remaining capacities -> push all incident edges to max
                # Compute sum of (max - current) and compare to rem.
                sum_add_max = 0
                sum_add_min = 0
                for ei, mn, mx in avail:
                    cur = self.assigned[ei]
                    sum_add_max += (mx - cur)
                    sum_add_min += (mn - cur)
                # sum_add_min should be 0 because mn==cur with our monotonic assignments (only increases)
                # but keep general.
                if self.rem[i] < sum_add_min or self.rem[i] > sum_add_max:
                    return False
                if self.rem[i] == sum_add_max:
                    for ei, mn, mx in avail:
                        if self.assigned[ei] != mx:
                            if not self._set_edge(ei, mx):
                                return False
                            e = self.edges[ei]
                            enqueue_is(e.a); enqueue_is(e.b)
                            enqueue_ed(ei)
                            for bj in self.blockers[ei]:
                                enqueue_ed(bj)

                # (3) If only one incident edge can still increase, force it to satisfy remaining.
                inc = []
                for ei, mn, mx in avail:
                    cur = self.assigned[ei]
                    if mx > cur:
                        inc.append((ei, mx - cur))
                if self.rem[i] > 0 and len(inc) == 1:
                    ei, cap = inc[0]
                    # must increase by exactly rem[i] (bounded by cap; already checked feasible)
                    newv = self.assigned[ei] + self.rem[i]
                    if not self._set_edge(ei, newv):
                        return False
                    e = self.edges[ei]
                    enqueue_is(e.a); enqueue_is(e.b)
                    enqueue_ed(ei)
                    for bj in self.blockers[ei]:
                        enqueue_ed(bj)

                # (4) Connectivity-aware local rule:
                # If island has rem>0 and only edges that connect to outside its DSU component are k,
                # and internal edges cannot satisfy remaining, force at least one bridge outward when necessary.
                # We implement a cheap necessary condition: if all remaining capacity edges are inside component
                # and component is not whole graph -> contradiction (since component can't connect later).
                # Conversely, if component has no possible outward edges with dom>=1, contradiction.
                root = self.dsu.find(i)
                if self._components_count() > 1:
                    out_possible = 0
                    for ei in self.adj_edges[i]:
                        e = self.edges[ei]
                        j = e.b if e.a == i else e.a
                        if self.dsu.find(j) != root:
                            dom = self.domain_edge(ei)
                            if (1 in dom) or (2 in dom):
                                out_possible += 1
                    # If i has any incident already positive to outside, ok.
                    # If component has no outward possible edges at all, prune later globally.

        return self.check_feasible()

    def _set_edge(self, ei: int, val: int) -> bool:
        """Monotonic set (only increase) edge assignment, update rem and DSU; ensure blockers if val>0."""
        cur = self.assigned[ei]
        if val < cur or val > 2:
            return False
        if val == cur:
            return True
        e = self.edges[ei]
        delta = val - cur
        if self.rem[e.a] < delta or self.rem[e.b] < delta:
            return False
        # crossing check: if setting from 0 to >0, ensure no blocker already >0
        if cur == 0 and val > 0:
            for bj in self.blockers[ei]:
                if self.assigned[bj] > 0:
                    return False
        self.assigned[ei] = val
        self.rem[e.a] -= delta
        self.rem[e.b] -= delta
        if cur == 0 and val > 0:
            self.dsu.union(e.a, e.b)
            self.used_edges += 1
        return True

    # ---------- Search ----------

    def is_solved(self) -> bool:
        if any(r != 0 for r in self.rem):
            return False
        # all edges consistent with blockers by construction
        return self._components_count() == 1

    def choose_branch_edge(self) -> Optional[int]:
        """Choose an unassigned (or partially assigned) edge with smallest domain >1, heuristic."""
        best = None
        best_dom = None
        for ei in range(len(self.edges)):
            dom = self.domain_edge(ei)
            if len(dom) <= 1:
                continue
            # prioritize edges adjacent to tight islands
            e = self.edges[ei]
            tight = (self.rem[e.a] + self.rem[e.b])
            key = (len(dom), tight)
            if best is None or key < best_dom:
                best = ei
                best_dom = key
        return best

    def snapshot(self):
        return (self.assigned[:], self.rem[:], self.dsu.copy(), self.used_edges)

    def restore(self, snap):
        self.assigned, self.rem, self.dsu, self.used_edges = snap

    def dfs(self) -> bool:
        if not self.propagate():
            return False
        if self.is_solved():
            return True

        ei = self.choose_branch_edge()
        if ei is None:
            return False

        dom = self.domain_edge(ei)
        # human-like guess order: try higher first when islands need degrees; else 0 first.
        e = self.edges[ei]
        need_bias = (self.rem[e.a] + self.rem[e.b])
        if need_bias > 0:
            order = sorted(dom, reverse=True)
        else:
            order = sorted(dom)

        snap = self.snapshot()
        for v in order:
            self.restore(snap)
            if self._set_edge(ei, v):
                if self.dfs():
                    return True
        self.restore(snap)
        return False

    def solution_dict(self) -> Dict[Tuple[Pos, Pos], int]:
        out: Dict[Tuple[Pos, Pos], int] = {}
        for ei, v in enumerate(self.assigned):
            if v > 0:
                e = self.edges[ei]
                a = self.islands[e.a]
                b = self.islands[e.b]
                out[(a, b) if a <= b else (b, a)] = v
        return out


def solve(observation):
    data = observation["data"]
    solver = HashiSolver(data)
    ok = solver.dfs()
    if not ok:
        return "No Solution"
    return str(solver.solution_dict())


if __name__ == "__main__":
    print(solve(OBSERVATION))

