from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple, Set

Coord = Tuple[int, int]
EdgeKey = Tuple[Coord, Coord]


def _norm_edge(a: Coord, b: Coord) -> EdgeKey:
    return (a, b) if a <= b else (b, a)


@dataclass(frozen=True)
class Edge:
    a: int          # node index
    b: int          # node index
    cells: Tuple[Coord, ...]  # interior cells along the segment (excluding endpoints)
    orient: int     # 0 horizontal, 1 vertical


class HashiSolver:
    def __init__(self, grid: List[List[Optional[int]]]):
        self.grid = grid
        self.R = len(grid)
        self.C = len(grid[0]) if self.R else 0

        # Nodes
        self.nodes: List[Coord] = []
        self.need: List[int] = []
        self.node_at: Dict[Coord, int] = {}

        for r in range(self.R):
            for c in range(self.C):
                v = grid[r][c]
                if v is not None and v > 0:
                    idx = len(self.nodes)
                    self.nodes.append((r, c))
                    self.need.append(int(v))
                    self.node_at[(r, c)] = idx

        self.N = len(self.nodes)

        # Candidate edges based on line of sight
        self.edges: List[Edge] = []
        self.adj_edges: List[List[int]] = [[] for _ in range(self.N)]
        self.edge_index_by_nodes: Dict[Tuple[int, int], int] = {}

        self._build_edges()

        # Conflict graph: edges that cannot both be >0 (crossing / overlapping)
        self.conflicts: List[Set[int]] = [set() for _ in range(len(self.edges))]
        self._build_conflicts()

        # For fast overlap checking, map each edge to its occupied cells set (same as cells)
        self.edge_cells: List[Tuple[Coord, ...]] = [e.cells for e in self.edges]

    def _build_edges(self) -> None:
        # For each island, look right and down to find nearest visible island.
        for i, (r, c) in enumerate(self.nodes):
            # Right
            cc = c + 1
            while cc < self.C and self.grid[r][cc] is None:
                cc += 1
            if cc < self.C and (r, cc) in self.node_at:
                j = self.node_at[(r, cc)]
                if i < j:
                    cells = tuple((r, x) for x in range(c + 1, cc))
                    e = Edge(i, j, cells, 0)
                    ei = len(self.edges)
                    self.edges.append(e)
                    self.adj_edges[i].append(ei)
                    self.adj_edges[j].append(ei)
                    self.edge_index_by_nodes[(i, j)] = ei

            # Down
            rr = r + 1
            while rr < self.R and self.grid[rr][c] is None:
                rr += 1
            if rr < self.R and (rr, c) in self.node_at:
                j = self.node_at[(rr, c)]
                if i < j:
                    cells = tuple((x, c) for x in range(r + 1, rr))
                    e = Edge(i, j, cells, 1)
                    ei = len(self.edges)
                    self.edges.append(e)
                    self.adj_edges[i].append(ei)
                    self.adj_edges[j].append(ei)
                    self.edge_index_by_nodes[(i, j)] = ei

    def _build_conflicts(self) -> None:
        # Edges conflict if they cross (perpendicular intersection), or overlap on same line,
        # or share interior cells. Sharing endpoints is allowed.
        cell_to_edges: Dict[Coord, List[int]] = {}
        for ei, e in enumerate(self.edges):
            for cell in e.cells:
                cell_to_edges.setdefault(cell, []).append(ei)

        # Any two edges sharing an interior cell conflict (covers overlaps and same-line reuse).
        for cell, eids in cell_to_edges.items():
            if len(eids) > 1:
                for i in range(len(eids)):
                    for j in range(i + 1, len(eids)):
                        a, b = eids[i], eids[j]
                        self.conflicts[a].add(b)
                        self.conflicts[b].add(a)

        # Additionally, perpendicular crossing may happen at a cell that is not in both edges' interior?
        # In grid model, a perpendicular crossing occurs at an interior cell of both segments,
        # so above already catches it. No further work needed.


@dataclass
class State:
    # edge_values: -1 unassigned, else 0/1/2
    edge_values: List[int]
    # remaining degree required for each node
    rem: List[int]
    # for each edge, current max possible due to node rem and conflicts: dynamic computed
    # occupied cells implied by chosen edges are enforced via conflicts sets


def solve(observation):
    grid = observation["data"]
    hs = HashiSolver(grid)
    if hs.N == 0:
        return "No Solution"

    # Quick infeasibility: each node needs <= 2*deg
    for i in range(hs.N):
        if hs.need[i] < 0:
            return "No Solution"
        if hs.need[i] > 2 * len(hs.adj_edges[i]):
            return "No Solution"

    M = len(hs.edges)
    st = State(edge_values=[-1] * M, rem=hs.need[:])

    # Precompute edge endpoints for speed
    ea = [e.a for e in hs.edges]
    eb = [e.b for e in hs.edges]
    econ = hs.conflicts
    adj = hs.adj_edges

    # Maintain for each edge whether it is forbidden due to a conflicting edge being >0 chosen.
    # We'll recompute incrementally via stack deltas in search rather than global recomputation.
    forbidden = [False] * M

    # For connectivity: we'll enforce at the end and also add pruning with components lower bounds.
    # We'll implement a cheap necessary condition: each partial component must have at least one
    # possible outgoing edge unless it already spans all nodes.
    # We'll compute component graph based on edges with value>0 plus potential edges (unforbidden, not forced 0).

    # --- Propagation rules (human-like) ---
    # R1: Degree bounds per node:
    #   min_possible = sum(min_assigned or 0) + sum(0) ...
    # We'll do remaining rem with per-edge values.
    # R2: If rem==0, all incident unassigned edges forced to 0.
    # R3: If rem equals sum of max_possible of incident unassigned edges, force each to its max.
    # R4: If an edge's max_possible becomes 0, force it to 0.
    # R5: Conflict propagation: if edge>0 then all conflicting edges forced 0.
    # R6: Single-neighbor necessity: if node has only one unassigned edge left, force it to rem (<=2).
    # R7: If node needs 1 and has exactly one incident edge that can be 1 (or 2) etc handle via max rule above.

    # For max_possible on an edge = min(2, rem[a], rem[b]) and not forbidden and not assigned
    def edge_max(ei, rem):
        if forbidden[ei]:
            return 0
        a = ea[ei]
        b = eb[ei]
        return min(2, rem[a], rem[b])

    # Assignment with trail for backtracking
    trail: List[Tuple[str, int, int]] = []  # ("e", ei, oldval) or ("r", ni, oldrem) or ("f", ei, oldforbidden)

    def set_forbidden(ei: int, val: bool):
        if forbidden[ei] != val:
            trail.append(("f", ei, int(forbidden[ei])))
            forbidden[ei] = val

    def assign_edge(ei: int, val: int) -> bool:
        cur = st.edge_values[ei]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        # Check feasibility
        if val < 0 or val > 2:
            return False
        if val > 0 and forbidden[ei]:
            return False
        a = ea[ei]; b = eb[ei]
        if val > st.rem[a] or val > st.rem[b]:
            return False

        # Record
        trail.append(("e", ei, cur))
        st.edge_values[ei] = val

        # Update rem
        if val != -1:
            # subtract from endpoints
            trail.append(("r", a, st.rem[a]))
            trail.append(("r", b, st.rem[b]))
            st.rem[a] -= val
            st.rem[b] -= val
            if st.rem[a] < 0 or st.rem[b] < 0:
                return False

        # Conflicts: if val>0, forbid conflicting edges and also assign them 0 if already >0 contradiction handled
        if val > 0:
            for cj in econ[ei]:
                if st.edge_values[cj] > 0:
                    return False
                set_forbidden(cj, True)
        return True

    def undo(to_len: int):
        while len(trail) > to_len:
            typ, i, old = trail.pop()
            if typ == "e":
                st.edge_values[i] = old
            elif typ == "r":
                st.rem[i] = old
            else:  # "f"
                forbidden[i] = bool(old)

    # Propagation queue: nodes and edges to reconsider
    q_nodes = deque(range(hs.N))
    q_edges = deque(range(M))

    inq_n = [True] * hs.N
    inq_e = [True] * M

    def push_node(i):
        if not inq_n[i]:
            inq_n[i] = True
            q_nodes.append(i)

    def push_edge(ei):
        if not inq_e[ei]:
            inq_e[ei] = True
            q_edges.append(ei)

    def propagate() -> bool:
        # Ensure all items eventually processed
        while q_edges or q_nodes:
            while q_edges:
                ei = q_edges.popleft()
                inq_e[ei] = False
                v = st.edge_values[ei]
                if v == -1:
                    mx = edge_max(ei, st.rem)
                    if mx == 0:
                        tlen = len(trail)
                        if not assign_edge(ei, 0):
                            undo(tlen)
                            return False
                        # endpoints changed
                        push_node(ea[ei]); push_node(eb[ei])
                        # conflicts might change for others due to forbidden? already handled
                else:
                    # If assigned 0, nothing. If assigned >0, ensure conflicts forbidden already; ok.
                    pass

            while q_nodes:
                ni = q_nodes.popleft()
                inq_n[ni] = False
                rem = st.rem[ni]
                if rem < 0:
                    return False
                incident = adj[ni]

                # Collect unassigned edges and their max
                un = []
                sum_max = 0
                for ei in incident:
                    if st.edge_values[ei] == -1:
                        mx = edge_max(ei, st.rem)
                        if mx > 0:
                            un.append((ei, mx))
                            sum_max += mx
                        else:
                            # mx==0 will be set to 0 by edge propagation; ensure scheduled
                            push_edge(ei)

                if rem == 0:
                    # force all incident unassigned to 0
                    for ei in incident:
                        if st.edge_values[ei] == -1:
                            tlen = len(trail)
                            if not assign_edge(ei, 0):
                                undo(tlen)
                                return False
                            push_edge(ei)
                            other = eb[ei] if ea[ei] == ni else ea[ei]
                            push_node(other)
                    continue

                # Feasibility check: rem cannot exceed sum_max + already assigned? already incorporated into rem.
                if rem > sum_max:
                    return False

                # If no possible edges but rem>0 -> fail
                if not un:
                    return False

                # Single option edge left: assign that edge to rem (<=2)
                if len(un) == 1:
                    ei, mx = un[0]
                    if rem > mx:
                        return False
                    tlen = len(trail)
                    if not assign_edge(ei, rem):
                        undo(tlen)
                        return False
                    push_edge(ei)
                    other = eb[ei] if ea[ei] == ni else ea[ei]
                    push_node(other)
                    continue

                # If rem equals sum of max, all must be at max
                if rem == sum_max:
                    for ei, mx in un:
                        tlen = len(trail)
                        if not assign_edge(ei, mx):
                            undo(tlen)
                            return False
                        push_edge(ei)
                        other = eb[ei] if ea[ei] == ni else ea[ei]
                        push_node(other)
                    continue

                # If rem is 1 and any edge has mx==2, cannot force, but we can cap that edge to 1?
                # Implement as: if rem==1, then at most one bridge total incident; any edge assigned 2 impossible.
                if rem == 1:
                    for ei, mx in un:
                        # If mx==2, we can't directly cap value without domain tracking.
                        # But we can add a local rule:
                        # If a node has rem==1, then any incident edge cannot be 2.
                        # We'll realize this when branching by restricting mx used in forcing rule below.
                        pass

                # Another common human rule: if rem is small, and all but one edge must be 0.
                # Use max constraints: if rem < (sum_max - mx) then that edge must take at least rem - (sum_max - mx).
                # General bound propagation:
                for ei, mx in un:
                    other_sum_max = sum_max - mx
                    lo = max(0, rem - other_sum_max)
                    hi = min(mx, rem)
                    # Apply cap for rem==1 at this node
                    if rem == 1:
                        hi = min(hi, 1)
                    # If lo==hi force assignment
                    if lo == hi:
                        tlen = len(trail)
                        if not assign_edge(ei, lo):
                            undo(tlen)
                            return False
                        push_edge(ei)
                        push_node(ea[ei]); push_node(eb[ei])
                    else:
                        # If current edge_max differs due to rem==1 cap, and hi==0, force 0
                        if hi == 0:
                            tlen = len(trail)
                            if not assign_edge(ei, 0):
                                undo(tlen)
                                return False
                            push_edge(ei)
                            push_node(ea[ei]); push_node(eb[ei])

        return True

    def all_assigned() -> bool:
        return all(v != -1 for v in st.edge_values)

    def connectivity_ok(final: bool = False) -> bool:
        # Build graph edges with value>0
        g = [[] for _ in range(hs.N)]
        used_edges = 0
        for ei, v in enumerate(st.edge_values):
            if v and v > 0:
                a = ea[ei]; b = eb[ei]
                g[a].append(b)
                g[b].append(a)
                used_edges += 1

        # If final: require all nodes connected (N==1 trivially ok)
        # If partial: require that no component is "sealed off" from others given remaining options.
        if hs.N <= 1:
            return True

        # Find components in current used graph
        comp = [-1] * hs.N
        cid = 0
        for i in range(hs.N):
            if comp[i] != -1:
                continue
            # BFS
            dq = deque([i])
            comp[i] = cid
            while dq:
                u = dq.popleft()
                for w in g[u]:
                    if comp[w] == -1:
                        comp[w] = cid
                        dq.append(w)
            cid += 1

        if final:
            return cid == 1

        if cid == 1:
            return True

        # For each component, check if there exists at least one still-possible edge leaving it.
        # A leaving edge is unassigned or assigned 0 but could be nonzero? assigned 0 can't change.
        # So only unassigned edges that are not forbidden and whose max>0.
        can_leave = [False] * cid
        for ei, v in enumerate(st.edge_values):
            if v != -1:
                continue
            if forbidden[ei]:
                continue
            a = ea[ei]; b = eb[ei]
            ca = comp[a]; cb = comp[b]
            if ca != cb:
                if edge_max(ei, st.rem) > 0:
                    can_leave[ca] = True
                    can_leave[cb] = True
        # If any component cannot leave and there is more than one component -> dead end
        return all(can_leave)

    def choose_branch_edge() -> Optional[int]:
        # Pick an unassigned edge with smallest domain (max 1/2/0), but >0 possible.
        best = None
        best_dom = 10
        for ei, v in enumerate(st.edge_values):
            if v != -1:
                continue
            mx = edge_max(ei, st.rem)
            if mx == 0:
                continue
            # domain size depends on mx and local rem==1 caps
            a = ea[ei]; b = eb[ei]
            hi = mx
            if st.rem[a] == 1:
                hi = min(hi, 1)
            if st.rem[b] == 1:
                hi = min(hi, 1)
            dom = hi + 1  # values 0..hi
            if dom < best_dom:
                best_dom = dom
                best = ei
                if best_dom <= 2:
                    # can't get smaller than 2 except 1 (forced), which would be propagated
                    pass
        return best

    def dfs() -> bool:
        # Propagate first
        # Refill queues with potentially affected nodes/edges is handled by callers;
        # but ensure at least a quick pass when called.
        if not propagate():
            return False

        if not connectivity_ok(final=False):
            return False

        if all_assigned():
            # All rem should be 0 and connected
            if any(r != 0 for r in st.rem):
                return False
            return connectivity_ok(final=True)

        ei = choose_branch_edge()
        if ei is None:
            return False

        mx = edge_max(ei, st.rem)
        a = ea[ei]; b = eb[ei]
        hi = mx
        if st.rem[a] == 1:
            hi = min(hi, 1)
        if st.rem[b] == 1:
            hi = min(hi, 1)

        # Value ordering: try higher first to satisfy degrees (common human strategy)
        options = list(range(hi, -1, -1))
        for val in options:
            tlen = len(trail)
            if assign_edge(ei, val):
                # schedule affected
                push_edge(ei)
                push_node(a); push_node(b)
                # conflicts might become forbidden when val>0; schedule those edges
                if val > 0:
                    for cj in econ[ei]:
                        push_edge(cj)
                        push_node(ea[cj]); push_node(eb[cj])
                if dfs():
                    return True
            undo(tlen)
            # clear queues (they may contain stale entries); easiest: rebuild small
            q_nodes.clear(); q_edges.clear()
            for i in range(hs.N):
                inq_n[i] = False
            for j in range(M):
                inq_e[j] = False
            # After undo, enqueue endpoints and edge again for next branch
            push_edge(ei)
            push_node(a); push_node(b)

        return False

    # Initial queue already filled
    if not dfs():
        return "No Solution"

    # Build answer dict
    ans: Dict[EdgeKey, int] = {}
    for ei, v in enumerate(st.edge_values):
        if v and v > 0:
            a = hs.nodes[ea[ei]]
            b = hs.nodes[eb[ei]]
            ans[_norm_edge(a, b)] = v
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

