OBSERVATION = {'data': [[None, 'B', None, None, None, None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None], [None, None, 'B', 'B', None, None], [None, None, None, None, 'B', None], [None, 'B', None, None, None, None]]}
from collections import deque

# Solver for "Two Connected Regions + No 2x2 monochrome" (a.k.a. Yin-Yang / Nurikabe-like variant)
# Uses aggressive constraint propagation:
# - local 2x2 forced moves
# - boundary connectivity pruning via union-find with "must-connect" and "cannot-isolate" checks
# - articulation-like pruning using BFS reachability on partial grids (fast enough for typical sizes)
# - informed branching (most constrained cell with connectivity impact)


B, W = "B", "W"
DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def solve(observation):
    data = observation["data"]
    n = len(data)
    if any(len(r) != n for r in data):
        return "No Solution"

    # Encode cell state: -1 unknown, 0 = W, 1 = B
    grid = [[-1] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] == B:
                grid[r][c] = 1
            elif data[r][c] == W:
                grid[r][c] = 0

    # Quick contradiction on given 2x2
    if not _check_no_2x2_monochrome_partial(grid):
        return "No Solution"

    # Run search with propagation
    res = _search(grid)
    if res is None:
        return "No Solution"
    # Return as 2D list of 'B'/'W'
    out = [[B if res[r][c] == 1 else W for c in range(n)] for r in range(n)]
    return str(out)


def _search(grid):
    n = len(grid)

    # Propagate until fixpoint or contradiction
    if not _propagate(grid):
        return None

    # If complete, validate connectivity
    if all(grid[r][c] != -1 for r in range(n) for c in range(n)):
        if _check_connected_complete(grid, 1) and _check_connected_complete(grid, 0) and _check_no_2x2_monochrome_partial(grid):
            return grid
        return None

    # Choose next variable (MRV + connectivity impact heuristic)
    r, c = _select_cell(grid)
    if r is None:
        return None

    # Value ordering: try the color that best preserves connectivity
    order = _value_order(grid, r, c)

    for val in order:
        ng = [row[:] for row in grid]
        ng[r][c] = val
        ans = _search(ng)
        if ans is not None:
            return ans
    return None


def _propagate(grid):
    # Apply deterministic rules to a fixpoint.
    # Returns False if contradiction.
    n = len(grid)
    q = deque()

    # Initialize queue with all cells (sufficiently small N)
    for r in range(n):
        for c in range(n):
            q.append((r, c))

    # For speed, we also loop over 2x2 blocks repeatedly; queue helps localize.
    inq = [[True] * n for _ in range(n)]

    def enqueue(rr, cc):
        if 0 <= rr < n and 0 <= cc < n and not inq[rr][cc]:
            inq[rr][cc] = True
            q.append((rr, cc))

    # Quick checks for obvious impossibilities
    if not _check_no_2x2_monochrome_partial(grid):
        return False
    if not _connectivity_possible(grid):
        return False

    # Local propagation loop
    steps = 0
    while q:
        r, c = q.popleft()
        inq[r][c] = False
        steps += 1

        # Apply forced by 2x2 constraints around (r,c)
        for br in (r - 1, r):
            for bc in (c - 1, c):
                if 0 <= br < n - 1 and 0 <= bc < n - 1:
                    forced = _forces_from_2x2(grid, br, bc)
                    if forced is False:
                        return False
                    if forced:
                        for (fr, fc, fval) in forced:
                            if grid[fr][fc] == -1:
                                grid[fr][fc] = fval
                                # enqueue neighbors and affected blocks
                                for dr, dc in DIRS:
                                    enqueue(fr + dr, fc + dc)
                                enqueue(fr, fc)

        # Connectivity pruning occasionally (amortize)
        # Trigger when we set many cells or periodically.
        if steps % 32 == 0:
            if not _connectivity_possible(grid):
                return False

    # Final connectivity check after local fixpoint
    if not _connectivity_possible(grid):
        return False

    return True


def _forces_from_2x2(grid, br, bc):
    # For a 2x2 block, if 3 cells are color X and 1 unknown, that unknown must be 1-X.
    # If 4 are X -> contradiction. If 3 are X and last is opposite already -> contradiction doesn't arise here.
    cells = [(br, bc), (br, bc + 1), (br + 1, bc), (br + 1, bc + 1)]
    vals = [grid[r][c] for r, c in cells]
    if -1 not in vals:
        if vals.count(0) == 4 or vals.count(1) == 4:
            return False
        return []
    forced = []
    for color in (0, 1):
        if vals.count(color) == 3 and vals.count(-1) == 1:
            idx = vals.index(-1)
            r, c = cells[idx]
            forced.append((r, c, 1 - color))
    # Also: if we already have 2 and 2 fixed, no direct force.
    return forced


def _check_no_2x2_monochrome_partial(grid):
    n = len(grid)
    for r in range(n - 1):
        row = grid[r]
        row2 = grid[r + 1]
        for c in range(n - 1):
            a = row[c]
            b = row[c + 1]
            d = row2[c]
            e = row2[c + 1]
            if a != -1 and a == b == d == e:
                return False
    return True


def _connectivity_possible(grid):
    # For each color, ensure:
    # - if any cells of that color exist, they can still become connected through cells not fixed to opposite.
    # - no fixed cell of that color is completely surrounded by opposite (isolation).
    # - if completed (no unknown allowed as connector), enforce full connectivity.
    n = len(grid)

    for color in (0, 1):
        opp = 1 - color

        fixed = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
        if not fixed:
            # Still must be one connected region in final; allow as long as not forced impossible.
            continue

        # Isolation check: a fixed cell cannot have all 4 neighbors fixed to opposite (or boundary treated as blocked).
        for r, c in fixed:
            blocked = 0
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if not (0 <= rr < n and 0 <= cc < n):
                    blocked += 1
                else:
                    if grid[rr][cc] == opp:
                        blocked += 1
            if blocked == 4:
                return False

        # Reachability: treat cells that are not fixed to opposite as passable for this color.
        passable = lambda rr, cc: grid[rr][cc] != opp

        # BFS from first fixed cell; must reach all fixed cells through passable
        sr, sc = fixed[0]
        seen = [[False] * n for _ in range(n)]
        dq = deque([(sr, sc)])
        seen[sr][sc] = True
        while dq:
            r, c = dq.popleft()
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n and not seen[rr][cc] and passable(rr, cc):
                    seen[rr][cc] = True
                    dq.append((rr, cc))
        for r, c in fixed:
            if not seen[r][c]:
                return False

    # If any color is fully fixed (no unknowns of that color possible?) we can't infer that; skip.

    # Also ensure that unknown space is not partitioned such that one color's fixed components would be forced separate.
    # The above reachability through non-opposite already captures that necessary condition.
    return True


def _check_connected_complete(grid, color):
    n = len(grid)
    cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
    if not cells:
        return False
    sr, sc = cells[0]
    seen = [[False] * n for _ in range(n)]
    dq = deque([(sr, sc)])
    seen[sr][sc] = True
    cnt = 1
    while dq:
        r, c = dq.popleft()
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < n and not seen[rr][cc] and grid[rr][cc] == color:
                seen[rr][cc] = True
                dq.append((rr, cc))
                cnt += 1
    return cnt == len(cells)


def _select_cell(grid):
    # MRV by evaluating immediate 2x2 contradictions and connectivity impact.
    n = len(grid)
    best = None
    best_score = None

    for r in range(n):
        for c in range(n):
            if grid[r][c] != -1:
                continue

            # Feasibility of each value
            feas = []
            for val in (0, 1):
                if _quick_feasible_assign(grid, r, c, val):
                    feas.append(val)
            if not feas:
                return (r, c)  # will fail fast

            # Score: smaller domain first; then more constraints touched (2x2 count + neighbors fixed)
            domain = len(feas)
            touch2 = _count_adj_2x2(r, c, n)
            neigh_fixed = 0
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n and grid[rr][cc] != -1:
                    neigh_fixed += 1
            score = (domain, -(touch2 * 2 + neigh_fixed))
            if best is None or score < best_score:
                best = (r, c)
                best_score = score
                if domain == 1 and score[1] <= -6:
                    return best
    return best if best is not None else (None, None)


def _count_adj_2x2(r, c, n):
    cnt = 0
    for br in (r - 1, r):
        for bc in (c - 1, c):
            if 0 <= br < n - 1 and 0 <= bc < n - 1:
                cnt += 1
    return cnt


def _quick_feasible_assign(grid, r, c, val):
    # Check local 2x2 consistency if (r,c)=val and basic isolation.
    n = len(grid)
    opp = 1 - val

    # Temporary set
    # 2x2 blocks around
    for br in (r - 1, r):
        for bc in (c - 1, c):
            if 0 <= br < n - 1 and 0 <= bc < n - 1:
                vals = []
                for (rr, cc) in ((br, bc), (br, bc + 1), (br + 1, bc), (br + 1, bc + 1)):
                    if rr == r and cc == c:
                        vals.append(val)
                    else:
                        vals.append(grid[rr][cc])
                if -1 not in vals:
                    if vals.count(0) == 4 or vals.count(1) == 4:
                        return False

    # Isolation immediate: if placing val makes this cell have 4 neighbors fixed to opp (or boundary), it would be isolated
    blocked = 0
    for dr, dc in DIRS:
        rr, cc = r + dr, c + dc
        if not (0 <= rr < n and 0 <= cc < n):
            blocked += 1
        else:
            g = grid[rr][cc]
            if g == opp:
                blocked += 1
    if blocked == 4:
        return False

    return True


def _value_order(grid, r, c):
    # Prefer value that connects to same-color neighbors or helps avoid isolating fixed cells.
    n = len(grid)

    def score(val):
        s = 0
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < n:
                if grid[rr][cc] == val:
                    s += 3
                elif grid[rr][cc] == -1:
                    s += 1
        # Prefer keeping 2x2 mixed (avoid creating 3 of same in a 2x2 unless forced)
        for br in (r - 1, r):
            for bc in (c - 1, c):
                if 0 <= br < n - 1 and 0 <= bc < n - 1:
                    vals = []
                    for (rr, cc) in ((br, bc), (br, bc + 1), (br + 1, bc), (br + 1, bc + 1)):
                        if rr == r and cc == c:
                            vals.append(val)
                        else:
                            vals.append(grid[rr][cc])
                    if vals.count(val) == 3 and vals.count(-1) == 1:
                        s -= 2
        return s

    a, b = 0, 1
    sa, sb = score(a), score(b)
    return [a, b] if sa >= sb else [b, a]


