from collections import deque

# Solver for "Yin-Yang" (aka "Black/White") puzzles:
# - All black cells connected orthogonally
# - All white cells connected orthogonally
# - No 2x2 monochromatic blocks
#
# Strategy:
# 1) Aggressive local propagation from 2x2 rule (classic human technique).
# 2) Connectivity feasibility checks using multi-source BFS through unknowns:
#    - Ensure each color can still become connected (no forced split).
#    - Detect forced cells from articulation-like separators by checking if some unknown must be a bridge.
# 3) Limited backtracking with strong heuristics:
#    - Choose cell with maximum implications (based on local 2x2 constraints + connectivity pressure).
# 4) Final connectivity enforcement only at completion; during search we prune by feasibility.

B, W, U = 1, 0, -1

def solve(observation):
    data = observation["data"]
    n = len(data)
    g = [[U] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] == "B":
                g[r][c] = B
            elif data[r][c] == "W":
                g[r][c] = W

    solver = YinYangSolver(g)
    sol = solver.run()
    if sol is None:
        return "No Solution"
    out = [["B" if sol[r][c] == B else "W" for c in range(n)] for r in range(n)]
    return str(out)

class YinYangSolver:
    __slots__ = ("n", "g", "trail", "stats")

    def __init__(self, grid):
        self.n = len(grid)
        self.g = [row[:] for row in grid]
        self.trail = []
        self.stats = {"nodes": 0, "fails": 0}

    def run(self):
        if not self.propagate():
            return None
        res = self.search()
        return res

    # ---------- Core utilities ----------
    def inb(self, r, c):
        n = self.n
        return 0 <= r < n and 0 <= c < n

    def neighbors(self, r, c):
        if r > 0: yield (r - 1, c)
        if r + 1 < self.n: yield (r + 1, c)
        if c > 0: yield (r, c - 1)
        if c + 1 < self.n: yield (r, c + 1)

    def push(self, r, c, val):
        cur = self.g[r][c]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        self.trail.append((r, c, cur))
        self.g[r][c] = val
        return True

    def undo(self, mark):
        while len(self.trail) > mark:
            r, c, prev = self.trail.pop()
            self.g[r][c] = prev

    def is_complete(self):
        for row in self.g:
            for v in row:
                if v == U:
                    return False
        return True

    # ---------- 2x2 rule propagation (human staple) ----------
    def propagate_2x2(self):
        n = self.n
        changed = False
        # For each 2x2, if three cells are same color and the fourth unknown => force opposite.
        for r in range(n - 1):
            gr = self.g[r]
            gr1 = self.g[r + 1]
            for c in range(n - 1):
                a = gr[c]
                b = gr[c + 1]
                d = gr1[c]
                e = gr1[c + 1]
                # Count colors and unknown positions
                # Pattern check
                cells = (a, b, d, e)
                if U not in cells:
                    # All four equal forbidden
                    if a == b == d == e:
                        return False, changed
                    continue
                # exactly one unknown?
                if cells.count(U) == 1:
                    idx = cells.index(U)
                    known = [x for x in cells if x != U]
                    # if three known same => force opposite
                    if known[0] == known[1] == known[2]:
                        force = 1 - known[0]
                        rr, cc = (r, c) if idx == 0 else (r, c + 1) if idx == 1 else (r + 1, c) if idx == 2 else (r + 1, c + 1)
                        if not self.push(rr, cc, force):
                            return False, changed
                        changed = True
                else:
                    # two unknowns: if the two known are equal and are adjacent in a line,
                    # it does not immediately force; but if the two known are diagonal and equal,
                    # then the other diagonal must be opposite to avoid 2x2 mono later? Not direct.
                    # However a human often uses: if two known same and two unknown,
                    # we cannot set both unknown to same; no direct propagation.
                    pass
        return True, changed

    # ---------- Connectivity feasibility pruning ----------
    def _collect(self, color):
        coords = []
        g = self.g
        for r in range(self.n):
            row = g[r]
            for c in range(self.n):
                if row[c] == color:
                    coords.append((r, c))
        return coords

    def _bfs_reachable(self, start_cells, passable_pred):
        n = self.n
        vis = [[False] * n for _ in range(n)]
        dq = deque()
        for (r, c) in start_cells:
            if not vis[r][c]:
                vis[r][c] = True
                dq.append((r, c))
        while dq:
            r, c = dq.popleft()
            for rr, cc in self.neighbors(r, c):
                if not vis[rr][cc] and passable_pred(rr, cc):
                    vis[rr][cc] = True
                    dq.append((rr, cc))
        return vis

    def connectivity_feasible(self, color):
        # Feasible if all fixed cells of that color can still be connected through
        # cells that are either that color or unknown.
        fixed = self._collect(color)
        if len(fixed) <= 1:
            return True
        g = self.g
        def passable(r, c):
            v = g[r][c]
            return v == color or v == U
        vis = self._bfs_reachable([fixed[0]], passable)
        for r, c in fixed[1:]:
            if not vis[r][c]:
                return False
        return True

    def forced_bridge_cells(self, color, limit_checks=48):
        # Human-like: if connectivity would be impossible unless some unknown becomes this color,
        # we can force it. We approximate by testing a few high-impact unknown candidates.
        # Candidate = unknown cells that lie on all paths between fixed components in the passable graph.
        # We compute components among fixed cells within passable graph and try to find cut vertices by trial.
        fixed = self._collect(color)
        if len(fixed) <= 1:
            return []
        g = self.g
        n = self.n
        def passable(r, c):
            v = g[r][c]
            return v == color or v == U

        # Build reachability from first fixed; if all fixed already connected through color-only then ok.
        # We focus only if fixed connected through passable (must be, else infeasible already).
        vis = self._bfs_reachable([fixed[0]], passable)
        for r, c in fixed[1:]:
            if not vis[r][c]:
                return []  # infeasible handled elsewhere

        # Identify unknown cells that are in the passable region and adjacent to at least two passable areas.
        # Then trial-remove them (set to opposite) to see if disconnects fixed; if yes => must be color.
        candidates = []
        for r in range(n):
            for c in range(n):
                if g[r][c] != U:
                    continue
                # only consider unknowns in passable region that could matter
                if not vis[r][c]:
                    continue
                deg = 0
                for rr, cc in self.neighbors(r, c):
                    if passable(rr, cc) and vis[rr][cc]:
                        deg += 1
                if deg >= 2:
                    candidates.append((deg, r, c))
        candidates.sort(reverse=True)
        forced = []
        checks = 0
        for _, r, c in candidates:
            if checks >= limit_checks:
                break
            checks += 1
            mark = len(self.trail)
            # temporarily forbid color here by setting opposite; if breaks feasibility => force color
            if not self.push(r, c, 1 - color):
                self.undo(mark)
                forced.append((r, c))
                continue
            ok = self.connectivity_feasible(color)
            self.undo(mark)
            if not ok:
                forced.append((r, c))
        return forced

    # ---------- Global propagation loop ----------
    def propagate(self):
        # Repeat until fixpoint:
        # - 2x2 forcing
        # - connectivity feasibility pruning
        # - force some bridge-like cells for both colors (limited)
        while True:
            any_change = False

            ok, ch = self.propagate_2x2()
            if not ok:
                return False
            any_change |= ch

            # Basic feasibility for both colors
            if not self.connectivity_feasible(B):
                return False
            if not self.connectivity_feasible(W):
                return False

            # Force bridge-like cells (lightweight, avoid heavy repeated checks)
            forcedB = self.forced_bridge_cells(B, limit_checks=24)
            forcedW = self.forced_bridge_cells(W, limit_checks=24)
            for r, c in forcedB:
                if not self.push(r, c, B):
                    return False
                any_change = True
            for r, c in forcedW:
                if not self.push(r, c, W):
                    return False
                any_change = True

            if not any_change:
                return True

    # ---------- Completion checks ----------
    def connected_exact(self, color):
        g = self.g
        fixed = self._collect(color)
        if not fixed:
            return False
        vis = self._bfs_reachable([fixed[0]], lambda r, c: g[r][c] == color)
        for r, c in fixed[1:]:
            if not vis[r][c]:
                return False
        # Ensure no other color cells exist outside visited (covered by above)
        return True

    def valid_final(self):
        # 2x2 already ensured by propagation, but re-check for safety
        n = self.n
        g = self.g
        for r in range(n - 1):
            for c in range(n - 1):
                a = g[r][c]
                b = g[r][c + 1]
                d = g[r + 1][c]
                e = g[r + 1][c + 1]
                if a == b == d == e:
                    return False
        return self.connected_exact(B) and self.connected_exact(W)

    # ---------- Branching heuristic ----------
    def choose_cell(self):
        n = self.n
        g = self.g
        best = None
        best_score = -1

        for r in range(n):
            for c in range(n):
                if g[r][c] != U:
                    continue
                score = 0
                # 2x2 involvement: each adjacent 2x2 with 2-3 decided cells increases score
                for dr in (-1, 0):
                    for dc in (-1, 0):
                        rr = r + dr
                        cc = c + dc
                        if 0 <= rr < n - 1 and 0 <= cc < n - 1:
                            cells = [g[rr][cc], g[rr][cc + 1], g[rr + 1][cc], g[rr + 1][cc + 1]]
                            decided = 4 - cells.count(U)
                            if decided >= 2:
                                score += (decided - 1)
                # connectivity pressure: adjacency to fixed regions
                adjB = adjW = 0
                for rr, cc in self.neighbors(r, c):
                    if g[rr][cc] == B:
                        adjB += 1
                    elif g[rr][cc] == W:
                        adjW += 1
                score += 2 * (adjB + adjW)
                # border slight preference (often narrows 2x2)
                if r == 0 or c == 0 or r == n - 1 or c == n - 1:
                    score += 1
                if score > best_score:
                    best_score = score
                    best = (r, c)
        return best

    def search(self):
        self.stats["nodes"] += 1
        if self.is_complete():
            return [row[:] for row in self.g] if self.valid_final() else None

        cell = self.choose_cell()
        if cell is None:
            return None
        r, c = cell

        # Try values in an order that tends to preserve both connectivity:
        # Prefer matching adjacent fixed colors; if none, try both.
        g = self.g
        pref = None
        adjB = adjW = 0
        for rr, cc in self.neighbors(r, c):
            if g[rr][cc] == B: adjB += 1
            elif g[rr][cc] == W: adjW += 1
        if adjB > adjW:
            order = (B, W)
        elif adjW > adjB:
            order = (W, B)
        else:
            order = (B, W)

        for val in order:
            mark = len(self.trail)
            if not self.push(r, c, val):
                self.undo(mark)
                continue
            if self.propagate():
                res = self.search()
                if res is not None:
                    return res
            self.undo(mark)

        self.stats["fails"] += 1
        return None

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, None, None, 3, None], [None, None, 1, None, None], [None, None, None, None, None], [None, 3, None, None, None], [None, None, None, None, None]]}
# Nurikabe solver with human-like deductions + strong constraint propagation + limited backtracking.
# Returns grid with 'B' for black, None for white.

from collections import deque, defaultdict
import itertools
import math
import time

UNKNOWN = 0
WHITE = 1
BLACK = 2

DIRS4 = [(-1,0),(1,0),(0,-1),(0,1)]

def solve(observation):
    data = observation["data"]
    R = len(data)
    C = len(data[0]) if R else 0

    # Precompute neighbors
    nbrs = [[] for _ in range(R*C)]
    for r in range(R):
        for c in range(C):
            i = r*C+c
            for dr,dc in DIRS4:
                rr,cc = r+dr, c+dc
                if 0 <= rr < R and 0 <= cc < C:
                    nbrs[i].append(rr*C+cc)

    nums = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                nums[r*C+c] = int(data[r][c])

    # Initialize state
    st = [UNKNOWN]*(R*C)
    for pos in nums:
        st[pos] = WHITE

    # Quick helpers
    def rc(i): return divmod(i, C)

    def set_cell(i, val, trail):
        cur = st[i]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        st[i] = val
        trail.append(i)
        return True

    def undo(trail):
        for i in reversed(trail):
            st[i] = UNKNOWN

    def any_2x2_all_black_forbidden():
        # check current contradictions: if any 2x2 already all black
        for r in range(R-1):
            base = r*C
            for c in range(C-1):
                a = base+c
                b = a+1
                d = a+C
                e = d+1
                if st[a]==BLACK and st[b]==BLACK and st[d]==BLACK and st[e]==BLACK:
                    return True
        return False

    def enforce_no_2x2(trail):
        # If a 2x2 has 3 black and 1 unknown -> unknown must be white
        # If a 2x2 has 4 black -> fail
        for r in range(R-1):
            for c in range(C-1):
                cells = [r*C+c, r*C+c+1, (r+1)*C+c, (r+1)*C+c+1]
                bs = sum(1 for x in cells if st[x]==BLACK)
                us = [x for x in cells if st[x]==UNKNOWN]
                if bs == 4:
                    return False
                if bs == 3 and len(us)==1:
                    if not set_cell(us[0], WHITE, trail):
                        return False
        return True

    # Island modeling: each island is a connected white region containing exactly one number.
    # We'll propagate using:
    #  - numbered cells cannot be orthogonally adjacent (otherwise islands merge) => force black between? actually adjacent means immediate merge, forbidden => contradiction unless same cell; so adjacent numbered -> no solution.
    #  - For each numbered cell n, compute reachable candidates under current black constraints and "no-other-number" constraints.
    #  - Enforce upper bound: if current connected white component containing a number exceeds its size -> fail.
    #  - Enforce completion: if a numbered component reaches its size, all adjacent unknowns become black.
    #  - Enforce uniqueness: any white component without a number is forbidden; if appears (fully determined), fail; if potential, prune by forcing connection to some number where possible.
    #  - For each number n, if a cell can only belong to a single island (exclusive reachability), set to white and connectable constraints.
    #  - For each island, if size remaining == number of frontier candidate cells forced -> set those to white (simple forced fill).
    #
    # For stronger propagation, we generate all feasible island shapes for small n (<=8 typically) given obstacles and other numbers, and apply arc-consistency-like pruning.

    # Precompute "other-number forbidden white adjacency": numbered cells separate islands, but whites can touch; only rule is each island contains exactly one number.
    # Hence if two numbered cells become connected through whites -> violation.
    # We'll treat by ensuring for any two numbers, they can't be connected via current WHITE cells; plus, we will avoid allowing a white component to contain >1 number.

    # Adjacency of numbered cells: immediately connected -> impossible
    for p in nums:
        for q in nbrs[p]:
            if q in nums:
                return "No Solution"

    # Generate feasible island shapes for each number using BFS over cell sets,
    # constrained by:
    #  - contains the numbered cell root
    #  - size == n
    #  - all cells not BLACK
    #  - does not include any other numbered cell
    #  - is orthogonally connected
    #
    # Additionally, shapes must be consistent with already WHITE cells:
    #  - any cell already WHITE that is connected to root through WHITEs must be included (component inclusion) ??? not exactly; if root has connected whites, they must belong to its island, so any shape must include the entire current white component containing root.
    #
    # We'll dynamically filter shapes based on current state.

    # Cache possible shapes by (root, frozenset(blocked), frozenset(required_component)) would be huge.
    # Instead, we enumerate all shapes based on "available area" under black + other numbers; for small n this is manageable.
    # We'll precompute a superset of candidate shapes for each root from the initial state (only respecting other numbers as forbidden cells).
    # Then at each propagation, filter by current black and required whites.
    def enumerate_shapes(root, size):
        forbidden = set(nums.keys())
        forbidden.remove(root)
        # available: any cell not in forbidden
        avail = [True]*(R*C)
        for f in forbidden:
            avail[f] = False

        # BFS over connected sets using frontier expansion; canonical to reduce duplicates using ordering.
        shapes = []
        root_idx = root
        # Represent set as sorted tuple for deterministic behavior; expand by adding neighbors >= min_new ordering.
        # Use frozenset for membership.
        start = (frozenset([root_idx]), tuple(sorted(nbrs[root_idx])))
        seen = set([frozenset([root_idx])])

        # We'll do iterative deepening expansion with pruning via bounding box? not needed for small size.
        q = deque([frozenset([root_idx])])
        # But need expand sets, not just size; use stack of sets
        stack = [frozenset([root_idx])]
        while stack:
            s = stack.pop()
            if len(s) == size:
                shapes.append(s)
                continue
            # candidate expansion cells: neighbors of set not already in it
            cand = set()
            for cell in s:
                for nb in nbrs[cell]:
                    if nb not in s and avail[nb]:
                        cand.add(nb)
            # symmetry breaking: enforce adding in increasing order to avoid permutations
            # Use max element in set as threshold
            thresh = max(s)
            for nb in sorted(cand):
                if nb < thresh:
                    continue
                ns = s | {nb}
                if ns in seen:
                    continue
                seen.add(ns)
                stack.append(ns)
        return shapes

    shapes_by_root = {}
    for root, n in nums.items():
        # For larger n, full shape enumeration can explode; fall back to reachability bounds and limited search.
        if n <= 9:
            shapes_by_root[root] = enumerate_shapes(root, n)
        else:
            shapes_by_root[root] = None  # sentinel

    def component_of_whites(start):
        # returns set of cells connected via WHITE (not including UNKNOWN)
        comp = set([start])
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in nbrs[x]:
                if st[y] == WHITE and y not in comp:
                    comp.add(y)
                    dq.append(y)
        return comp

    def components_of_color(color):
        seen = [False]*(R*C)
        comps = []
        for i in range(R*C):
            if st[i] == color and not seen[i]:
                comp = []
                dq = deque([i]); seen[i]=True
                while dq:
                    x = dq.popleft()
                    comp.append(x)
                    for y in nbrs[x]:
                        if st[y]==color and not seen[y]:
                            seen[y]=True
                            dq.append(y)
                comps.append(comp)
        return comps

    def black_connectivity_possible():
        # Black cells must form one orth-connected group in final.
        # If currently there are multiple black components, they must be connectable through UNKNOWN cells.
        comps = components_of_color(BLACK)
        if len(comps) <= 1:
            return True
        # Check if all black components lie in same connected region of (BLACK+UNKNOWN)
        allowed = [st[i] != WHITE for i in range(R*C)]  # BLACK or UNKNOWN
        # find region from first black
        start = comps[0][0]
        dq = deque([start])
        vis = set([start])
        while dq:
            x = dq.popleft()
            for y in nbrs[x]:
                if allowed[y] and y not in vis:
                    vis.add(y)
                    dq.append(y)
        for comp in comps[1:]:
            if comp[0] not in vis:
                return False
        return True

    def white_components_number_constraints():
        # Any fully-determined white component must contain exactly one number.
        # Also, if a white component contains a number, its size cannot exceed that number.
        # If it has no number, it must be expandable via UNKNOWN to reach some number? Actually islands can't be numberless.
        # We'll treat: if there is a WHITE component without a number and it is closed (no adjacent UNKNOWN) => contradiction.
        seen = [False]*(R*C)
        for i in range(R*C):
            if st[i]==WHITE and not seen[i]:
                dq = deque([i]); seen[i]=True
                comp = [i]
                nums_in = []
                border_unknown = False
                while dq:
                    x = dq.popleft()
                    if x in nums:
                        nums_in.append(x)
                    for y in nbrs[x]:
                        if st[y]==WHITE and not seen[y]:
                            seen[y]=True
                            dq.append(y)
                            comp.append(y)
                        elif st[y]==UNKNOWN:
                            border_unknown = True
                if len(nums_in) == 0:
                    if not border_unknown:
                        return False
                elif len(nums_in) >= 2:
                    return False
                else:
                    root = nums_in[0]
                    if len(comp) > nums[root]:
                        return False
        return True

    def close_completed_islands(trail):
        # If a numbered white component reaches its size, its boundary unknowns must be black.
        seen = [False]*(R*C)
        for i in range(R*C):
            if st[i]==WHITE and not seen[i]:
                dq = deque([i]); seen[i]=True
                comp = [i]
                root = None
                while dq:
                    x = dq.popleft()
                    if x in nums:
                        root = x if root is None else -1
                    for y in nbrs[x]:
                        if st[y]==WHITE and not seen[y]:
                            seen[y]=True
                            dq.append(y)
                            comp.append(y)
                if root is None or root == -1:
                    continue
                if len(comp) == nums[root]:
                    # surround with black
                    for x in comp:
                        for y in nbrs[x]:
                            if st[y]==UNKNOWN:
                                if not set_cell(y, BLACK, trail):
                                    return False
        return True

    def forced_black_between_adjacent_islands(trail):
        # If two different numbered components touch via an UNKNOWN that would connect them if white,
        # we can't directly set; but we can enforce: any UNKNOWN cell adjacent to WHITE cells from two different numbered components must be BLACK.
        # Compute label of each current white component by its number root if present, else None/ambiguous.
        comp_id = [-1]*(R*C)
        comp_root = {}
        cid = 0
        seen = [False]*(R*C)
        for i in range(R*C):
            if st[i]==WHITE and not seen[i]:
                dq=deque([i]); seen[i]=True
                comp=[]
                roots=[]
                while dq:
                    x=dq.popleft()
                    comp.append(x)
                    if x in nums:
                        roots.append(x)
                    for y in nbrs[x]:
                        if st[y]==WHITE and not seen[y]:
                            seen[y]=True
                            dq.append(y)
                for x in comp:
                    comp_id[x]=cid
                comp_root[cid] = roots[0] if len(roots)==1 else None
                cid+=1

        for u in range(R*C):
            if st[u]!=UNKNOWN:
                continue
            touching_roots=set()
            for y in nbrs[u]:
                if st[y]==WHITE:
                    r = comp_root.get(comp_id[y], None)
                    if r is not None:
                        touching_roots.add(r)
            if len(touching_roots) >= 2:
                if not set_cell(u, BLACK, trail):
                    return False
        return True

    def shape_filtering_and_forcing(trail):
        # For each island with enumerated shapes, filter by current BLACK and required WHITE component.
        # Then:
        #  - if a cell appears in all shapes => must be WHITE
        #  - if a cell appears in no shapes for a root but is in its current component => contradiction caught earlier
        #  - if a cell is WHITE and can belong to no root => contradiction
        if not nums:
            return True

        possible_for_root = {}
        possible_roots_for_cell = [set() for _ in range(R*C)]

        # Precompute current required component for each root (white component containing it)
        required_comp = {}
        for root in nums:
            required_comp[root] = component_of_whites(root)

        # Filter shapes per root
        for root, n in nums.items():
            if shapes_by_root[root] is None:
                # For large n: skip shape enumeration.
                possible_for_root[root] = None
                continue
            req = required_comp[root]
            filtered = []
            for sh in shapes_by_root[root]:
                ok = True
                # must include all required whites in component
                if not req.issubset(sh):
                    continue
                for cell in sh:
                    if st[cell] == BLACK:
                        ok = False
                        break
                if not ok:
                    continue
                filtered.append(sh)
            if not filtered:
                return False
            possible_for_root[root] = filtered
            for sh in filtered:
                for cell in sh:
                    possible_roots_for_cell[cell].add(root)

        # Any WHITE cell must be supported by exactly one root possibility (since each island has one number).
        # If a WHITE cell can belong to multiple roots, it's still ok if components not connected yet; but if cell is in a numbered component already, it must match that root.
        # We'll enforce: if a WHITE component contains a root, all its cells must be allowed by that root.
        seen = [False]*(R*C)
        for i in range(R*C):
            if st[i]==WHITE and not seen[i]:
                dq=deque([i]); seen[i]=True
                comp=[i]
                roots=[]
                while dq:
                    x=dq.popleft()
                    if x in nums:
                        roots.append(x)
                    for y in nbrs[x]:
                        if st[y]==WHITE and not seen[y]:
                            seen[y]=True
                            dq.append(y)
                            comp.append(y)
                if len(roots)==1 and shapes_by_root[roots[0]] is not None:
                    r0=roots[0]
                    for cell in comp:
                        if r0 not in possible_roots_for_cell[cell]:
                            return False

        # Force cells that are in all shapes of a root to WHITE
        for root, lst in possible_for_root.items():
            if lst is None:
                continue
            inter = set(lst[0])
            for sh in lst[1:]:
                inter.intersection_update(sh)
            for cell in inter:
                if st[cell]==UNKNOWN:
                    if not set_cell(cell, WHITE, trail):
                        return False

            # Also, if any cell is in no shape of this root but is adjacent to required component and root still needs expansion,
            # don't force; too weak.

        # Exclusive ownership: if an UNKNOWN cell can belong to exactly one root across all enumerated roots and it's needed to satisfy that root, we can sometimes force.
        # Stronger safe rule: if a cell is adjacent to required component of a root and cannot belong to any other root, and root still needs cells, set it WHITE.
        # This mirrors human "only possible expansion".
        # Compute remaining size for each root (using current component size)
        for root, n in nums.items():
            comp = required_comp[root]
            rem = n - len(comp)
            if rem <= 0:
                continue
            # frontier unknowns adjacent to component
            frontier = [u for cell in comp for u in nbrs[cell] if st[u]==UNKNOWN]
            if not frontier:
                continue
            # dedup
            frontier = sorted(set(frontier))
            # If rem equals number of frontier cells that can be used at all, force them white.
            if shapes_by_root[root] is not None:
                usable = [u for u in frontier if root in possible_roots_for_cell[u]]
                if rem == len(usable) and rem > 0:
                    for u in usable:
                        if not set_cell(u, WHITE, trail):
                            return False

            # Only-possible expansion: if a frontier cell is exclusively possible for this root and rem>0, force WHITE.
            for u in frontier:
                if st[u]!=UNKNOWN:
                    continue
                roots_set = possible_roots_for_cell[u]
                if shapes_by_root[root] is not None:
                    if roots_set == {root}:
                        if not set_cell(u, WHITE, trail):
                            return False

        return True

    def black_single_component_completion_forcing(trail):
        # If an UNKNOWN cell is the only bridge between existing black components, force it BLACK.
        comps = components_of_color(BLACK)
        if len(comps) <= 1:
            return True
        # Work in graph of cells where WHITE are blocked.
        allowed = [st[i] != WHITE for i in range(R*C)]  # BLACK or UNKNOWN
        # Identify articulation-like forced cells by testing reachability for each UNKNOWN candidate adjacent to blacks.
        # Keep it light: only consider UNKNOWN cells that touch at least one BLACK.
        unknown_touch_black = [i for i in range(R*C) if st[i]==UNKNOWN and any(st[j]==BLACK for j in nbrs[i])]
        if not unknown_touch_black:
            return True
        # For each such cell, if setting it WHITE would disconnect black components in allowed graph, then it must be BLACK.
        # Approx test: remove the cell and see if all black component reps still connected.
        reps = [comp[0] for comp in comps]
        target_set = set(reps)
        base_start = reps[0]

        def reachable_without(block):
            dq=deque([base_start])
            vis=set([base_start])
            while dq:
                x=dq.popleft()
                for y in nbrs[x]:
                    if y==block: 
                        continue
                    if allowed[y] and y not in vis:
                        vis.add(y); dq.append(y)
            return vis

        for u in unknown_touch_black:
            vis = reachable_without(u)
            ok = True
            for rep in reps[1:]:
                if rep not in vis:
                    ok = False
                    break
            if not ok:
                if not set_cell(u, BLACK, trail):
                    return False
        return True

    def propagate(trail):
        # Iterate until fixpoint
        while True:
            before = len(trail)
            if any_2x2_all_black_forbidden():
                return False
            if not enforce_no_2x2(trail):
                return False
            if not white_components_number_constraints():
                return False
            if not forced_black_between_adjacent_islands(trail):
                return False
            if not close_completed_islands(trail):
                return False
            if not black_connectivity_possible():
                return False
            if not black_single_component_completion_forcing(trail):
                return False
            if not shape_filtering_and_forcing(trail):
                return False
            if len(trail) == before:
                break
        return True

    def is_solved():
        if any(v==UNKNOWN for v in st):
            return False
        # Check black connected
        blacks = [i for i,v in enumerate(st) if v==BLACK]
        if blacks:
            dq=deque([blacks[0]])
            vis=set([blacks[0]])
            while dq:
                x=dq.popleft()
                for y in nbrs[x]:
                    if st[y]==BLACK and y not in vis:
                        vis.add(y); dq.append(y)
            if len(vis)!=len(blacks):
                return False
        # Check 2x2
        if any_2x2_all_black_forbidden():
            return False
        # Check islands: each white component has exactly one number and size matches it
        seen=[False]*(R*C)
        for i in range(R*C):
            if st[i]==WHITE and not seen[i]:
                dq=deque([i]); seen[i]=True
                comp=[]
                roots=[]
                while dq:
                    x=dq.popleft()
                    comp.append(x)
                    if x in nums:
                        roots.append(x)
                    for y in nbrs[x]:
                        if st[y]==WHITE and not seen[y]:
                            seen[y]=True; dq.append(y)
                if len(roots)!=1:
                    return False
                if len(comp)!=nums[roots[0]]:
                    return False
        return True

    def select_branch_cell():
        # Choose an UNKNOWN cell with highest impact: near blacks or near island frontiers.
        best = None
        best_score = -1
        for i,v in enumerate(st):
            if v!=UNKNOWN:
                continue
            score = 0
            # adjacency contributions
            for j in nbrs[i]:
                if st[j]==BLACK: score += 5
                elif st[j]==WHITE: score += 3
            # 2x2 risk: if in any 2x2 with two blacks, prefer
            r,c = rc(i)
            for dr in (-1,0):
                for dc in (-1,0):
                    rr,cc = r+dr, c+dc
                    if 0 <= rr < R-1 and 0 <= cc < C-1:
                        cells = [rr*C+cc, rr*C+cc+1, (rr+1)*C+cc, (rr+1)*C+cc+1]
                        bs = sum(1 for x in cells if st[x]==BLACK)
                        if bs>=2: score += bs
            if score > best_score:
                best_score = score
                best = i
        return best

    def dfs():
        trail=[]
        if not propagate(trail):
            undo(trail); return False
        if is_solved():
            return True
        cell = select_branch_cell()
        if cell is None:
            undo(trail); return False

        # Try BLACK first (often preferred in Nurikabe), then WHITE
        for val in (BLACK, WHITE):
            trail2=[]
            if set_cell(cell, val, trail2) and propagate(trail2):
                if dfs():
                    return True
            undo(trail2)
        undo(trail)
        return False

    # Initial propagation
    trail0=[]
    if not propagate(trail0):
        undo(trail0)
        return "No Solution"
    undo(trail0)  # keep state but propagation wrote to st; we shouldn't undo.
    # Above undo would revert; so re-run without undo:
    trail0=[]
    if not propagate(trail0):
        return "No Solution"

    if dfs():
        out = []
        for r in range(R):
            row=[]
            for c in range(C):
                v = st[r*C+c]
                row.append('B' if v==BLACK else None)
            out.append(row)
        return str(out)
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, 2, None], [None, None, 4, None, None, None, None], [None, 1, None, None, None, 4, None], [None, None, None, None, 4, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, None, None, None]]}
from collections import deque, defaultdict
from itertools import combinations

# Nurikabe solver: white islands with given sizes, black sea connected, no 2x2 black.
# Grid values: -1 unknown, 0 white, 1 black

DIRS = [(1,0),(-1,0),(0,1),(0,-1)]

def solve(observation):
    data = observation["data"]
    R, C = len(data), len(data[0])
    givens = []
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                givens.append((r, c, int(data[r][c])))
    if not givens:
        return "No Solution"

    # Map each cell to index for bitmasks
    idx = [[r*C+c for c in range(C)] for r in range(R)]
    N = R*C

    # Precompute neighbors as lists of indices
    neigh = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            i = idx[r][c]
            for dr, dc in DIRS:
                rr, cc = r+dr, c+dc
                if 0 <= rr < R and 0 <= cc < C:
                    neigh[i].append(idx[rr][cc])

    given_pos = [(r, c) for r, c, s in givens]
    given_set = set((r,c) for r,c,s in givens)

    # Quick impossibility: adjacent givens cannot belong to same island -> must be separated by black
    # If two givens orthogonally adjacent, puzzle impossible because islands cannot contain two numbers.
    for (r,c,s) in givens:
        for dr, dc in DIRS:
            rr, cc = r+dr, c+dc
            if (rr,cc) in given_set:
                return "No Solution"

    # State
    grid = [-1]*N
    # assign givens as white
    for r,c,s in givens:
        grid[idx[r][c]] = 0

    # Island tracking: each given has an ID
    K = len(givens)
    gid_of = {}
    for k,(r,c,s) in enumerate(givens):
        gid_of[idx[r][c]] = k

    sizes = [s for _,_,s in givens]

    # For each island id: set of currently forced white cells (indices)
    island_cells = [set([idx[r][c]]) for r,c,_ in givens]

    # Precompute 2x2 blocks indices
    blocks = []
    for r in range(R-1):
        for c in range(C-1):
            blocks.append([idx[r][c], idx[r+1][c], idx[r][c+1], idx[r+1][c+1]])

    # Utility BFS from a set within allowed predicate
    def bfs_from(starts, can_visit):
        q = deque(starts)
        seen = set(starts)
        while q:
            u = q.popleft()
            for v in neigh[u]:
                if v not in seen and can_visit(v):
                    seen.add(v)
                    q.append(v)
        return seen

    def cell_rc(i):
        return divmod(i, C)

    def compute_island_assignment(grid, island_cells):
        # Multi-source BFS among white/unknown to determine which island(s) can reach each cell without crossing black
        # We need to prevent islands connecting through existing whites of other islands: but cells are not labeled in grid.
        # We'll maintain known island cells; treat them as barriers for other islands except themselves.
        # Return for each cell: possible island IDs it could belong to (as bitmask int)
        poss = [0]*N
        # Initialize frontier per island
        frontiers = [deque() for _ in range(K)]
        dist = [dict() for _ in range(K)]  # only store visited
        for k in range(K):
            for u in island_cells[k]:
                frontiers[k].append(u)
                dist[k][u] = 0
                poss[u] |= (1<<k)

        # BFS bounded by remaining size (can't expand beyond size-1 from given if no cycles; but islands can be non-tree,
        # still max cells is size; distance bound is a safe pruning for reachability.
        maxd = [sizes[k]-1 for k in range(K)]
        for k in range(K):
            q = frontiers[k]
            while q:
                u = q.popleft()
                du = dist[k][u]
                if du >= maxd[k]:
                    continue
                for v in neigh[u]:
                    if grid[v] == 1:
                        continue
                    # If v is a known cell of another island, cannot pass / occupy
                    other_known = False
                    for kk in range(K):
                        if kk != k and v in island_cells[kk]:
                            other_known = True
                            break
                    if other_known:
                        continue
                    if v not in dist[k]:
                        dist[k][v] = du+1
                        poss[v] |= (1<<k)
                        q.append(v)
        return poss

    def island_frontier(k, grid, island_cells):
        # candidate expansion cells adjacent to island (not black, not in other islands)
        cand = set()
        for u in island_cells[k]:
            for v in neigh[u]:
                if grid[v] == 1:
                    continue
                if v in island_cells[k]:
                    continue
                if any(v in island_cells[kk] for kk in range(K) if kk != k):
                    continue
                cand.add(v)
        return cand

    def components_of_whites_and_unknowns(grid):
        # returns components of cells that are not black
        seen = set()
        comps = []
        for i in range(N):
            if grid[i] == 1 or i in seen:
                continue
            q = deque([i])
            seen.add(i)
            comp = [i]
            while q:
                u = q.popleft()
                for v in neigh[u]:
                    if grid[v] != 1 and v not in seen:
                        seen.add(v)
                        q.append(v)
                        comp.append(v)
            comps.append(comp)
        return comps

    def check_no_2x2_black(grid):
        for b in blocks:
            if all(grid[i] == 1 for i in b):
                return False
        return True

    def black_connectivity_possible(grid):
        # Ensure black cells can still become connected considering unknowns.
        black = [i for i in range(N) if grid[i] == 1]
        if not black:
            return True
        start = black[0]
        reachable = bfs_from([start], lambda v: grid[v] != 0)  # can traverse black or unknown (future black)
        for i in black:
            if i not in reachable:
                return False
        return True

    def island_size_bounds_ok(grid, island_cells):
        # For each island: current count <= size and at least can still reach enough cells within possible area.
        poss = compute_island_assignment(grid, island_cells)
        for k in range(K):
            cur = len(island_cells[k])
            if cur > sizes[k]:
                return False
            # Count cells that could belong to this island
            can = 0
            for i in range(N):
                if grid[i] == 1:
                    continue
                if any(i in island_cells[kk] for kk in range(K) if kk != k):
                    continue
                if poss[i] & (1<<k):
                    can += 1
            if can < sizes[k]:
                return False
        # Also: any forced white cell must belong to some island.
        for i in range(N):
            if grid[i] == 0:
                # if it's a given or already in some island, ok; else must have poss
                if any(i in island_cells[k] for k in range(K)):
                    continue
                if compute_island_assignment(grid, island_cells)[i] == 0:
                    return False
        return True

    def islands_disjoint_ok(grid, island_cells):
        # Ensure islands don't touch through forced white merges: if two islands have adjacent forced whites, impossible
        # because that would connect white regions (unless separated by black), but adjacent whites connect.
        cell_to_island = {}
        for k in range(K):
            for u in island_cells[k]:
                cell_to_island[u] = k
        for u,k in cell_to_island.items():
            for v in neigh[u]:
                if v in cell_to_island and cell_to_island[v] != k:
                    return False
        return True

    def forced_moves(grid, island_cells):
        # Returns (changed, contradiction)
        changed = False

        # 1) Any unknown cell not reachable by any island -> must be black.
        poss = compute_island_assignment(grid, island_cells)
        for i in range(N):
            if grid[i] != -1:
                continue
            if poss[i] == 0:
                grid[i] = 1
                changed = True

        # 2) For each island, if remaining cells needed equals number of available candidates, force them white.
        poss = compute_island_assignment(grid, island_cells)
        for k in range(K):
            need = sizes[k] - len(island_cells[k])
            if need < 0:
                return changed, True
            if need == 0:
                # all adjacent unknowns that cannot belong to other islands and would connect must be black to prevent expansion?
                # Not necessarily; they can be black or belong to other islands. But they cannot be white connected to this island,
                # so any neighbor cell with poss exactly {k} must be black.
                for u in list(island_cells[k]):
                    for v in neigh[u]:
                        if grid[v] == -1 and poss[v] == (1<<k):
                            grid[v] = 1
                            changed = True
                continue
            # available cells that could be added
            avail = []
            for i in range(N):
                if grid[i] == 1:
                    continue
                if any(i in island_cells[kk] for kk in range(K) if kk != k):
                    continue
                if (poss[i] & (1<<k)) and (i not in island_cells[k]):
                    avail.append(i)
            if len(avail) < need:
                return changed, True
            if len(avail) == need:
                for i in avail:
                    if grid[i] != 0:
                        grid[i] = 0
                        island_cells[k].add(i)
                        changed = True

        # 3) White cells must belong to exactly one island: if a white unknown-to-island cell has poss singleton, assign it.
        poss = compute_island_assignment(grid, island_cells)
        for i in range(N):
            if grid[i] != 0:
                continue
            if any(i in island_cells[k] for k in range(K)):
                continue
            m = poss[i]
            if m == 0:
                return changed, True
            if m & (m-1) == 0:
                k = (m.bit_length()-1)
                island_cells[k].add(i)
                changed = True

        # 4) Prevent 2x2 black: if in a 2x2 block three are black and one unknown, the unknown must be white.
        for b in blocks:
            blacks = sum(1 for i in b if grid[i] == 1)
            if blacks == 4:
                return changed, True
            if blacks == 3:
                for i in b:
                    if grid[i] == -1:
                        grid[i] = 0
                        changed = True

        # 5) Black connectivity: if there are two black components that can only connect via a single unknown cell (articulation-like),
        # hard to compute cheaply; instead: if any black cell becomes isolated by whites around with no unknown path, fail handled in check.

        return changed, False

    def global_checks(grid, island_cells):
        if not check_no_2x2_black(grid):
            return False
        if not islands_disjoint_ok(grid, island_cells):
            return False
        if not island_size_bounds_ok(grid, island_cells):
            return False
        if not black_connectivity_possible(grid):
            return False
        return True

    def is_solved(grid, island_cells):
        if any(v == -1 for v in grid):
            return False
        # All islands have correct size
        for k in range(K):
            if len(island_cells[k]) != sizes[k]:
                return False
        # All white cells are in exactly one island
        all_white = [i for i in range(N) if grid[i] == 0]
        assigned = set().union(*island_cells)
        if set(all_white) != assigned:
            return False
        # Black connected
        black = [i for i in range(N) if grid[i] == 1]
        if black:
            reach = bfs_from([black[0]], lambda v: grid[v] == 1)
            if len(reach) != len(black):
                return False
        # No 2x2 black
        if not check_no_2x2_black(grid):
            return False
        return True

    def choose_branch(grid, island_cells):
        # Prefer branching on island expansion with smallest remaining options, else on a cell with fewest island possibilities.
        poss = compute_island_assignment(grid, island_cells)
        best = None

        # islands with need>0
        for k in range(K):
            need = sizes[k] - len(island_cells[k])
            if need <= 0:
                continue
            cand = island_frontier(k, grid, island_cells)
            # Filter candidates that can belong to k
            cand = [c for c in cand if grid[c] != 1 and (poss[c] & (1<<k))]
            if not cand:
                return ("fail", None)
            score = len(cand)
            if best is None or score < best[0]:
                best = (score, ("island", k, cand))
        if best:
            return best[1]

        # pick unknown cell with minimal poss count (>0)
        best_cell = None
        best_count = 10**9
        best_mask = 0
        for i in range(N):
            if grid[i] != -1:
                continue
            m = poss[i]
            if m == 0:
                return ("fail", None)
            cnt = m.bit_count()
            if cnt < best_count:
                best_count = cnt
                best_cell = i
                best_mask = m
                if cnt == 1:
                    break
        if best_cell is None:
            return ("none", None)
        return ("cell", best_cell, best_mask)

    def deep_copy_state(grid, island_cells):
        return grid[:], [set(s) for s in island_cells]

    def propagate(grid, island_cells):
        while True:
            ch, contra = forced_moves(grid, island_cells)
            if contra:
                return False
            if not global_checks(grid, island_cells):
                return False
            if not ch:
                return True

    def dfs(grid, island_cells):
        if not propagate(grid, island_cells):
            return None
        if is_solved(grid, island_cells):
            return grid, island_cells

        kind = choose_branch(grid, island_cells)
        if kind[0] == "fail":
            return None
        if kind[0] == "none":
            # all decided but not solved => fail
            return None

        if kind[0] == "island":
            _, k, cand = kind
            # Try adding a candidate to island k (white), best-first: prioritize those with singleton poss or that prevent 2x2 black
            poss = compute_island_assignment(grid, island_cells)
            def keyf(c):
                # smaller poss choices and more constraints
                return (poss[c].bit_count(),)
            cand.sort(key=keyf)
            for c in cand:
                g2, isl2 = deep_copy_state(grid, island_cells)
                if g2[c] == 1:
                    continue
                g2[c] = 0
                isl2[k].add(c)
                res = dfs(g2, isl2)
                if res is not None:
                    return res
            # Also possibility: do not add any particular candidate now; but branching via exclusions:
            # pick one candidate and set it black (if allowed) to explore alternative shapes.
            # Choose the most ambiguous candidate.
            c = cand[-1]
            g2, isl2 = deep_copy_state(grid, island_cells)
            if g2[c] == -1:
                g2[c] = 1
                res = dfs(g2, isl2)
                if res is not None:
                    return res
            return None

        if kind[0] == "cell":
            _, i, mask = kind
            # Branch: assign white to one of possible islands vs black
            options = []
            # Try black first if it doesn't violate 2x2 quickly? Usually helps connectivity.
            options.append(("black", None))
            ks = [k for k in range(K) if (mask>>k)&1]
            # Try singleton islands early
            for k in ks:
                options.append(("white", k))
            for typ, k in options:
                g2, isl2 = deep_copy_state(grid, island_cells)
                if typ == "black":
                    g2[i] = 1
                else:
                    g2[i] = 0
                    isl2[k].add(i)
                res = dfs(g2, isl2)
                if res is not None:
                    return res
            return None

        return None

    result = dfs(grid, island_cells)
    if result is None:
        return "No Solution"
    sol_grid, _ = result

    out = []
    for r in range(R):
        row = []
        for c in range(C):
            v = sol_grid[idx[r][c]]
            row.append('B' if v == 1 else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, 'W', None, None], [None, None, None, None, None, None, None, None, None, None], ['B', None, 'B', None, 'W', None, None, 'W', None, None], [None, 'B', None, None, None, None, 'W', None, 'W', None], [None, None, 'B', None, 'W', None, None, None, None, None], [None, 'B', 'W', None, None, 'W', 'B', 'W', None, None], [None, None, 'B', None, None, None, 'W', None, None, None], [None, 'B', None, 'B', None, None, None, None, 'W', None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None]]}
from collections import deque
from typing import List, Optional, Tuple, Dict

# Solver for Yin-Yang / Takuzu-connectivity variant:
# - fill grid with B/W
# - all B connected orthogonally
# - all W connected orthogonally
# - no monochromatic 2x2

B, W, U = 1, 0, -1  # internal encoding: B=1, W=0, U=-1

def solve(observation):
    data = observation["data"]
    n = len(data)
    g = [[U] * n for _ in range(n)]
    for r in range(n):
        if len(data[r]) != n:
            return "No Solution"
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                g[r][c] = B
            elif v == 'W':
                g[r][c] = W
            elif v is None:
                pass
            else:
                return "No Solution"

    s = Solver(n, g)
    ans = s.run()
    if ans is None:
        return "No Solution"
    out = [[('B' if ans[r][c] == B else 'W') for c in range(n)] for r in range(n)]
    return str(out)

class Solver:
    __slots__ = ("n", "N", "grid", "trail", "head",
                 "degU", "adjU_mask",
                 "queue",
                 "dirty_2x2",
                 "unknowns",
                 "nb4",
                 "cells_2x2",
                 "inconsistency")

    def __init__(self, n: int, grid: List[List[int]]):
        self.n = n
        self.N = n * n
        self.grid = [grid[r][c] for r in range(n) for c in range(n)]
        self.trail = []  # stack of (idx, oldval)
        self.head = 0    # for rollback
        self.queue = deque()

        # Precompute neighbors (4-neighborhood)
        self.nb4 = [[] for _ in range(self.N)]
        for r in range(n):
            for c in range(n):
                i = r * n + c
                if r > 0: self.nb4[i].append((r - 1) * n + c)
                if r + 1 < n: self.nb4[i].append((r + 1) * n + c)
                if c > 0: self.nb4[i].append(r * n + (c - 1))
                if c + 1 < n: self.nb4[i].append(r * n + (c + 1))

        # Precompute list of 2x2 blocks each cell participates in
        self.cells_2x2 = [[] for _ in range(self.N)]
        for r in range(n - 1):
            for c in range(n - 1):
                block = [r * n + c, r * n + (c + 1), (r + 1) * n + c, (r + 1) * n + (c + 1)]
                for i in block:
                    self.cells_2x2[i].append(block)

        self.dirty_2x2 = deque()
        self.unknowns = sum(1 for v in self.grid if v == U)
        self.inconsistency = False

        # Seed queue with all fixed cells for local propagation
        for i, v in enumerate(self.grid):
            if v != U:
                self.queue.append(i)
                self._mark_2x2_dirty(i)

    def run(self) -> Optional[List[List[int]]]:
        if not self.propagate():
            return None
        res = self.search()
        if res is None:
            return None
        # reshape
        n = self.n
        return [res[r*n:(r+1)*n] for r in range(n)]

    # ------------------------ Assignment & trail ------------------------

    def assign(self, idx: int, val: int) -> bool:
        cur = self.grid[idx]
        if cur == val:
            return True
        if cur != U and cur != val:
            self.inconsistency = True
            return False
        # record
        self.trail.append((idx, cur))
        self.grid[idx] = val
        self.unknowns -= 1
        self.queue.append(idx)
        self._mark_2x2_dirty(idx)
        for nb in self.nb4[idx]:
            self._mark_2x2_dirty(nb)
        return True

    def snapshot(self) -> int:
        return len(self.trail)

    def rollback(self, snap: int):
        while len(self.trail) > snap:
            idx, old = self.trail.pop()
            if self.grid[idx] != old:
                if self.grid[idx] != U:
                    self.unknowns += 1
                self.grid[idx] = old
        self.queue.clear()
        self.dirty_2x2.clear()
        self.inconsistency = False
        # re-seed propagation from all fixed cells affected near trail could be complex;
        # easiest: seed from all fixed cells (still fast for 10x10).
        for i, v in enumerate(self.grid):
            if v != U:
                self.queue.append(i)
                self._mark_2x2_dirty(i)

    # ------------------------ Propagation rules ------------------------

    def _mark_2x2_dirty(self, idx: int):
        for block in self.cells_2x2[idx]:
            self.dirty_2x2.append(block)

    def propagate(self) -> bool:
        # Iteratively apply:
        # 1) 2x2 monochrome avoidance: if 3 same and 1 unknown => force opposite
        # 2) Connectivity feasibility pruning via articulation-like checks on unknowns:
        #    - For each color, ensure that all fixed cells can still connect through non-opponent cells.
        #    - Also ensure that assigning a cell cannot immediately create a "separating wall" of opponent.
        # 3) Avoid creating disconnected fixed components that cannot be bridged (component reachability)
        # 4) Forced moves from "single bridge" between fixed components (Steiner-like): if a cell is the only
        #    possible connector between two fixed components for a color, force it.
        #
        # Steps are run until queues stabilize.
        if self.inconsistency:
            return False
        n = self.n
        while True:
            progressed = False

            # Rule: resolve dirty 2x2 blocks
            while self.dirty_2x2:
                block = self.dirty_2x2.popleft()
                a, b, c, d = block
                vals = (self.grid[a], self.grid[b], self.grid[c], self.grid[d])
                if U not in vals:
                    if vals[0] == vals[1] == vals[2] == vals[3]:
                        return False
                    continue
                # if 3 filled and equal, force 4th opposite
                # count known
                known = [v for v in vals if v != U]
                if len(known) == 3 and known[0] == known[1] == known[2]:
                    opp = W if known[0] == B else B
                    # find unknown
                    if vals[0] == U:
                        if not self.assign(a, opp): return False
                        progressed = True
                    elif vals[1] == U:
                        if not self.assign(b, opp): return False
                        progressed = True
                    elif vals[2] == U:
                        if not self.assign(c, opp): return False
                        progressed = True
                    else:
                        if not self.assign(d, opp): return False
                        progressed = True

            # Connectivity feasibility check (fast BFS on allowed cells)
            if not self._connectivity_feasible(B):
                return False
            if not self._connectivity_feasible(W):
                return False

            # Forced connectors (rare but powerful)
            if self._force_unique_connectors(B):
                progressed = True
                # new assignments will have marked dirty; continue loop
                continue
            if self._force_unique_connectors(W):
                progressed = True
                continue

            # If no more local 2x2 to process, but queue still has nodes,
            # we used it only to mark dirty; nothing else to do.
            self.queue.clear()

            if not progressed:
                break

        # Final check on completed grid
        if self.unknowns == 0:
            if not self._connected_exact(B): return False
            if not self._connected_exact(W): return False
        return True

    # ------------------------ Connectivity logic ------------------------

    def _connected_exact(self, color: int) -> bool:
        # BFS over cells == color, ensure all such cells connected.
        cells = [i for i, v in enumerate(self.grid) if v == color]
        if not cells:
            return False
        start = cells[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for nb in self.nb4[x]:
                if nb not in seen and self.grid[nb] == color:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(cells)

    def _connectivity_feasible(self, color: int) -> bool:
        # Consider "passable" cells for this color: cells != opponent
        opp = W if color == B else B
        fixed = [i for i, v in enumerate(self.grid) if v == color]
        if not fixed:
            # no fixed of this color yet; still must be possible to make at least one region:
            # requires that not all cells are opponent (trivial)
            return any(v != opp for v in self.grid)
        start = fixed[0]
        # BFS in passable area (color or unknown) and check all fixed of this color reachable
        dq = deque([start])
        vis = bytearray(self.N)
        vis[start] = 1
        while dq:
            x = dq.popleft()
            for nb in self.nb4[x]:
                if not vis[nb] and self.grid[nb] != opp:
                    vis[nb] = 1
                    dq.append(nb)
        for i in fixed[1:]:
            if not vis[i]:
                return False
        return True

    def _force_unique_connectors(self, color: int) -> bool:
        # Human-like: if multiple fixed components exist (w.r.t. current fixed-only graph),
        # and there is a cell (unknown) that is the only possible bridge between components
        # in the passable graph, force it to this color.
        #
        # Approximation: compute components of fixed color in fixed-only graph.
        # For each unknown cell u, see which fixed components are adjacent via passable paths
        # that must pass through u as a cut-vertex in passable subgraph is expensive.
        # Use a cheaper necessary condition:
        # - For each pair of fixed components, compute set of unknown cells that are on all
        #   shortest paths? too hard.
        # Instead, do:
        # - Multi-source BFS from each fixed component over passable cells, record for each cell
        #   which component reaches it first/also distance. For each unknown cell, if it is the
        #   only meeting point between two components among frontier cells in a local sense,
        #   force it. This is heuristic but safe only if uniqueness is provable.
        #
        # We'll implement a SAFE rule:
        # For each unknown cell u, temporarily treat u as blocked (set to opponent) and test
        # connectivity feasibility of fixed cells for that color. If u is currently unknown and
        # blocking it makes infeasible, then u must be this color (because if u were opponent,
        # infeasible). This is a strong, safe deduction (a "must-pass" cell).
        #
        # This can be expensive if done for all unknowns; we restrict to candidate u that lie
        # in the passable region between fixed cells: those visited by BFS from fixed[0].
        opp = W if color == B else B
        fixed = [i for i, v in enumerate(self.grid) if v == color]
        if len(fixed) <= 1:
            return False

        # BFS in passable to get relevant unknowns
        start = fixed[0]
        dq = deque([start])
        vis = bytearray(self.N)
        vis[start] = 1
        while dq:
            x = dq.popleft()
            for nb in self.nb4[x]:
                if not vis[nb] and self.grid[nb] != opp:
                    vis[nb] = 1
                    dq.append(nb)

        candidates = [i for i in range(self.N) if vis[i] and self.grid[i] == U]
        changed = False

        # Further reduce by only checking candidates that have at least 2 passable neighbors
        # (more likely to be a bridge) and are in "vicinity" of fixed cells by distance <= 6
        # (compute distances from start quickly during BFS above is not stored; do small local filter)
        for u in candidates:
            # quick neighbor filter
            passable_deg = 0
            for nb in self.nb4[u]:
                if self.grid[nb] != opp:
                    passable_deg += 1
            if passable_deg <= 1:
                continue

            snap = self.snapshot()
            # Assume u is opponent; if that breaks feasibility, then u must be color.
            if not self.assign(u, opp):
                self.rollback(snap)
                continue
            feasible = self._connectivity_feasible(color)
            self.rollback(snap)
            if not feasible:
                if not self.assign(u, color):
                    return False
                changed = True
                # after forcing one, stop and let propagation re-run
                break

        return changed

    # ------------------------ Search ------------------------

    def search(self) -> Optional[List[int]]:
        if self.unknowns == 0:
            # ensure exact connectivity and no 2x2 violation already ensured
            if self._connected_exact(B) and self._connected_exact(W):
                return self.grid[:]
            return None

        # Choose variable: most constrained by 2x2 and connectivity (human-like "critical cell")
        idx = self._select_cell()
        if idx is None:
            return None

        # Value ordering: try value that better maintains connectivity (prefer joining fixed components)
        vals = self._order_values(idx)

        snap = self.snapshot()
        for v in vals:
            if self.assign(idx, v) and self.propagate():
                res = self.search()
                if res is not None:
                    return res
            self.rollback(snap)
        return None

    def _select_cell(self) -> Optional[int]:
        # Score unknown cells:
        # - higher if participates in many 2x2 blocks with 2-3 assigned cells
        # - higher if adjacent to fixed cells (either color)
        # - higher if candidate bridge: when set to opponent may break feasibility (approx via local structure)
        best = None
        best_score = -1
        for i, v in enumerate(self.grid):
            if v != U:
                continue
            score = 0
            # 2x2 pressure
            for block in self.cells_2x2[i]:
                vals = [self.grid[x] for x in block]
                k = sum(1 for t in vals if t != U)
                if k >= 2:
                    score += 3 * (k - 1)
            # adjacency pressure
            for nb in self.nb4[i]:
                if self.grid[nb] != U:
                    score += 2
            # prefer central-ish
            r, c = divmod(i, self.n)
            score += (min(r, self.n-1-r) + min(c, self.n-1-c)) // 2

            if score > best_score:
                best_score = score
                best = i
        return best

    def _order_values(self, idx: int) -> Tuple[int, int]:
        # Prefer value that connects to same-color neighbors (reduces components).
        b_adj = 0
        w_adj = 0
        for nb in self.nb4[idx]:
            if self.grid[nb] == B:
                b_adj += 1
            elif self.grid[nb] == W:
                w_adj += 1
        # If tied, try both.
        if b_adj > w_adj:
            return (B, W)
        if w_adj > b_adj:
            return (W, B)
        # If no adjacency, pick order based on which color currently has fewer fixed cells to balance
        b_ct = sum(1 for v in self.grid if v == B)
        w_ct = self.N - self.unknowns - b_ct
        return (B, W) if b_ct < w_ct else (W, B)

