    print(solve(OBSERVATION))

OBSERVATION = {'data': [[1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, 6, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, 1, None, None, 2, None, None, None, 3, None], [2, None, None, None, None, None, None, 3, None, None], [None, None, 2, None, None, None, None, None, None, 2], [None, 3, None, None, None, 3, None, None, 6, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, 2, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None]]}
from collections import deque, defaultdict
from itertools import combinations, product

# Nurikabe solver with strong human-like constraint propagation + controlled branching.
# Cell states: -1 unknown, 0 white, 1 black

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    grid = observation["data"]
    R, C = len(grid), len(grid[0])
    N = R * C

    def idx(r, c): return r * C + c
    def rc(i): return divmod(i, C)
    def inb(r, c): return 0 <= r < R and 0 <= c < C

    nums = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] is not None:
                nums[idx(r, c)] = int(grid[r][c])

    # Precompute neighbor lists
    neigh = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            i = idx(r, c)
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if inb(rr, cc):
                    neigh[i].append(idx(rr, cc))

    # Precompute 2x2 blocks (as lists of 4 indices)
    blocks2 = []
    for r in range(R - 1):
        for c in range(C - 1):
            blocks2.append([idx(r, c), idx(r + 1, c), idx(r, c + 1), idx(r + 1, c + 1)])

    # Initial state
    state0 = [-1] * N
    for i in nums:
        state0[i] = 0  # numbered cells are white

    # --------- Island modeling ---------
    # We'll maintain for each numbered cell s: a set of possible "shapes" (sets of cell indices)
    # Shapes are connected, include s, do not include other numbered cells, size == nums[s].
    # Additionally: shapes of different islands must be disjoint.
    #
    # We generate all candidate shapes up front using BFS expansion limited by size and by
    # avoiding other numbered cells. This is expensive in worst-case; we constrain it:
    # - sizes are usually small; for larger sizes, we still generate with pruning by manhattan radius.
    # - we later filter shapes using current state and forced-white/black constraints.

    numbered_list = list(nums.keys())

    # Quick distance bounds to prune shape generation
    def manhattan(a, b):
        ra, ca = rc(a)
        rb, cb = rc(b)
        return abs(ra - rb) + abs(ca - cb)

    # Avoid including other numbered cells in an island
    other_numbers = set(nums.keys())

    # Candidate generation with memo to avoid duplicates
    def gen_shapes_for_source(s, size):
        # Upper bound area: cells within distance size-1 from s can be part of connected size island.
        sr, sc = rc(s)
        cand_cells = []
        for r in range(R):
            for c in range(C):
                i = idx(r, c)
                if i != s and i in other_numbers:
                    continue
                if abs(r - sr) + abs(c - sc) <= size - 1:
                    cand_cells.append(i)
        cand_set = set(cand_cells)
        if s not in cand_set:
            cand_set.add(s)

        # Expand connected sets using frontier; canonical representation as frozenset
        shapes = set()
        start = frozenset([s])
        q = deque([start])
        seen = set([start])

        # Precompute adjacency within cand_set
        adj_cand = {}
        for i in cand_set:
            adj_cand[i] = [j for j in neigh[i] if j in cand_set]

        while q:
            S = q.popleft()
            if len(S) == size:
                shapes.add(S)
                continue
            # Potential expansion: neighbors of S not in S
            frontier = set()
            for i in S:
                for j in adj_cand[i]:
                    if j not in S:
                        frontier.add(j)
            # Prune by connectivity possibility: if not enough cells remain, skip
            if len(S) + len(frontier) < size:
                continue
            # Branch expansions; to reduce duplicates, add in increasing index order from sorted frontier
            for j in sorted(frontier):
                S2 = frozenset(set(S) | {j})
                # Quick pruning: S2 must remain potentially completable (simple bound)
                if len(S2) < size:
                    # ensure there exists at least one connected completion: approximate by checking
                    # frontier from S2; if empty and need more -> fail
                    if len(S2) == size - 1:
                        # need one more; must have some neighbor
                        ok = False
                        for i in S2:
                            for k in adj_cand[i]:
                                if k not in S2:
                                    ok = True
                                    break
                            if ok:
                                break
                        if not ok:
                            continue
                if S2 not in seen:
                    seen.add(S2)
                    q.append(S2)
        return list(shapes)

    shapes0 = {}
    for s in numbered_list:
        shapes0[s] = gen_shapes_for_source(s, nums[s])
        if not shapes0[s]:
            return "No Solution"

    # Some islands are size 1 -> all neighbors black.
    forced_black = set()
    forced_white = set(nums.keys())
    for s in numbered_list:
        if nums[s] == 1:
            for j in neigh[s]:
                forced_black.add(j)

    # Apply initial forced
    def apply_forced(state):
        for i in forced_white:
            if state[i] == 1:
                return None
            state[i] = 0
        for i in forced_black:
            if i in nums:
                return None
            if state[i] == 0:
                return None
            state[i] = 1
        return state

    state0 = apply_forced(state0[:])
    if state0 is None:
        return "No Solution"

    # --------- Propagation utilities ---------

    def comp_black_components(state):
        """Return component id per cell (only black), and list of components (list of cells)."""
        cid = [-1] * N
        comps = []
        c = 0
        for i in range(N):
            if state[i] == 1 and cid[i] == -1:
                dq = deque([i])
                cid[i] = c
                comp = [i]
                while dq:
                    v = dq.popleft()
                    for w in neigh[v]:
                        if state[w] == 1 and cid[w] == -1:
                            cid[w] = c
                            dq.append(w)
                            comp.append(w)
                comps.append(comp)
                c += 1
        return cid, comps

    def exists_black_path_with_unknowns(state, a, b):
        """Check connectivity possibility between black components via unknown/black cells."""
        if a == b:
            return True
        dq = deque()
        seen = set()
        dq.append(a)
        seen.add(a)
        while dq:
            v = dq.popleft()
            for w in neigh[v]:
                if state[w] != 0 and w not in seen:  # black or unknown
                    if w == b:
                        return True
                    seen.add(w)
                    dq.append(w)
        return False

    def forbid_2x2_black(state, queue):
        """If 3 blacks in a 2x2, force the 4th to white; if 4 blacks -> contradiction."""
        for blk in blocks2:
            bcnt = sum(1 for i in blk if state[i] == 1)
            u = [i for i in blk if state[i] == -1]
            if bcnt == 4:
                return False
            if bcnt == 3 and len(u) == 1:
                i = u[0]
                if state[i] == 1:
                    return False
                if state[i] == -1:
                    state[i] = 0
                    queue.append(i)
        return True

    def compute_white_regions(state):
        """Return list of white components (cells with state==0), and mapping cell->component index."""
        cid = [-1] * N
        comps = []
        c = 0
        for i in range(N):
            if state[i] == 0 and cid[i] == -1:
                dq = deque([i])
                cid[i] = c
                comp = [i]
                while dq:
                    v = dq.popleft()
                    for w in neigh[v]:
                        if state[w] == 0 and cid[w] == -1:
                            cid[w] = c
                            dq.append(w)
                            comp.append(w)
                comps.append(comp)
                c += 1
        return cid, comps

    # Island shape filtering and forced cell deductions from shapes
    def filter_shapes_and_force(state, shapes):
        """
        shapes: dict s -> list[frozenset]
        Returns (new_shapes, forced_assignments dict cell->0/1) or None on contradiction.
        forced_assignments only for white (0) from intersections and black (1) from impossible cells?
        We'll also detect if a cell cannot belong to any island -> potentially black (but careful: could be white sea? no, white only in islands).
        In Nurikabe, all white cells belong to some island; hence if a cell cannot be in any island shape, it must be black.
        """
        new_shapes = {}
        # Precompute forbidden cells for each island: other numbered cells are forbidden already by generation.
        # Filter by current state:
        # - shape cannot include any cell fixed black
        # - all fixed white cells that are already connected to a numbered island must be included by that island; we handle globally via assignment coverage later.
        for s, shlist in shapes.items():
            flt = []
            for sh in shlist:
                ok = True
                for i in sh:
                    if state[i] == 1:
                        ok = False
                        break
                if not ok:
                    continue
                # shape cannot touch another numbered cell (already ensured)
                flt.append(sh)
            if not flt:
                return None
            new_shapes[s] = flt

        forced = {}
        # Force island cells that are in all shapes for that island -> white
        for s, flt in new_shapes.items():
            inter = set(flt[0])
            for sh in flt[1:]:
                inter.intersection_update(sh)
                if not inter:
                    break
            for i in inter:
                if state[i] == 1:
                    return None
                if state[i] == -1:
                    forced[i] = 0

        # Force cells that cannot belong to ANY island -> black (unless already white)
        # But do not force numbered cells (already white).
        possible_white = set()
        for s, flt in new_shapes.items():
            for sh in flt:
                possible_white.update(sh)
        for i in range(N):
            if i in nums:
                continue
            if state[i] == -1 and i not in possible_white:
                forced[i] = 1

        return new_shapes, forced

    def assign_cell(state, i, val, queue):
        if state[i] == val:
            return True
        if state[i] != -1 and state[i] != val:
            return False
        if val == 0 and i in nums:
            state[i] = 0
        else:
            # numbered cells cannot be black
            if val == 1 and i in nums:
                return False
            state[i] = val
        queue.append(i)
        return True

    def sea_connectivity_prune(state):
        """
        Human rule: black cells must be potentially connectable.
        If there are >=2 black components that cannot be connected through unknown/black, contradiction.
        """
        cid, comps = comp_black_components(state)
        if len(comps) <= 1:
            return True
        # pick representative cell per component
        reps = [comp[0] for comp in comps]
        base = reps[0]
        for r in reps[1:]:
            if not exists_black_path_with_unknowns(state, base, r):
                return False
        return True

    def enforce_no_touching_islands(state):
        """
        Since islands are separated by black, two different numbered cells cannot be in same white component.
        If any white component contains >=2 numbered cells -> contradiction.
        """
        wcid, wcomps = compute_white_regions(state)
        for comp in wcomps:
            count = 0
            for i in comp:
                if i in nums:
                    count += 1
                    if count >= 2:
                        return False
        return True

    def propagate(state, shapes):
        """
        Repeatedly apply:
        - filter island shapes, force cells
        - 2x2 black rule
        - prevent merging numbered cells into same white component
        - basic island saturation: if a white component contains a numbered cell s, its size cannot exceed nums[s]
          and if it equals nums[s], all adjacent unknown become black (boundary closure).
        """
        queue = deque()
        # Seed queue with all already decided cells to allow local boundary closure computations
        for i in range(N):
            if state[i] != -1:
                queue.append(i)

        while True:
            # Filter shapes and get global forced assignments
            res = filter_shapes_and_force(state, shapes)
            if res is None:
                return None
            shapes, forced = res
            if forced:
                for i, v in forced.items():
                    if not assign_cell(state, i, v, queue):
                        return None

            # Local propagation loop for queued changes
            while queue:
                _ = queue.popleft()

                # 2x2 black forcing
                if not forbid_2x2_black(state, queue):
                    return None

                # White component rules
                if not enforce_no_touching_islands(state):
                    return None

                # Island saturation and overflow check
                wcid, wcomps = compute_white_regions(state)
                # We can process only components potentially affected, but N is small; keep it simple yet efficient.
                for comp in wcomps:
                    numcells = [i for i in comp if i in nums]
                    if len(numcells) == 1:
                        s = numcells[0]
                        target = nums[s]
                        if len(comp) > target:
                            return None
                        if len(comp) == target:
                            # boundary must be black
                            for v in comp:
                                for nb in neigh[v]:
                                    if state[nb] == -1 and nb not in comp:
                                        if not assign_cell(state, nb, 1, queue):
                                            return None
                    elif len(numcells) == 0:
                        # A white component without a number is illegal in final; during solving,
                        # it must be able to connect to some numbered cell via unknown whites.
                        # We approximate by requiring it has at least one adjacent unknown that could become white.
                        # If fully enclosed by black/edges and has no number -> contradiction.
                        enclosed = True
                        for v in comp:
                            for nb in neigh[v]:
                                if state[nb] == -1:
                                    enclosed = False
                                    break
                            if not enclosed:
                                break
                        if enclosed:
                            return None

            # Sea connectivity possibility check
            if not sea_connectivity_prune(state):
                return None

            # If no more forced changes from shape filtering, break.
            # We detect fixpoint by running filter again and checking no forced; easiest: store a snapshot key.
            key = (tuple(state), tuple(len(shapes[s]) for s in numbered_list))
            # Attempt another iteration; if it repeats, stop.
            # We'll do one more filter and see if it would force anything; since we already did, just stop here.
            return (state, shapes)

    def is_complete(state):
        return all(v != -1 for v in state)

    def validate_final(state, shapes):
        # Must satisfy black connectivity and no 2x2 black
        cid, comps = comp_black_components(state)
        if len(comps) != 1:
            return False
        for blk in blocks2:
            if all(state[i] == 1 for i in blk):
                return False
        # White components must each contain exactly one number and size matches.
        wcid, wcomps = compute_white_regions(state)
        for comp in wcomps:
            numcells = [i for i in comp if i in nums]
            if len(numcells) != 1:
                return False
            s = numcells[0]
            if len(comp) != nums[s]:
                return False
        return True

    # --------- Search with strong branching heuristics ---------

    def choose_branch(state, shapes):
        """
        Choose either:
        - an island with smallest number of shapes to pick one
        - or a cell with highest constraint (appears in many shapes) to set black/white.
        Prefer island-shape choice for strong global pruning.
        """
        # Island with smallest domain >1
        best_s = None
        best_len = 10**9
        for s in numbered_list:
            l = len(shapes[s])
            if 1 < l < best_len:
                best_len = l
                best_s = s
        if best_s is not None:
            return ("shape", best_s)

        # Otherwise pick an unknown cell with max participation in shapes
        freq = defaultdict(int)
        for s in numbered_list:
            for sh in shapes[s]:
                for i in sh:
                    if state[i] == -1:
                        freq[i] += 1
        if not freq:
            return None
        cell = max(freq.items(), key=lambda kv: kv[1])[0]
        return ("cell", cell)

    def deep_copy_shapes(shapes):
        return {s: list(lst) for s, lst in shapes.items()}

    def restrict_shapes_to_choice(shapes, s, chosen_shape):
        new_shapes = {}
        for t, lst in shapes.items():
            if t == s:
                new_shapes[t] = [chosen_shape]
            else:
                # Must be disjoint with chosen shape
                flt = [sh for sh in lst if sh.isdisjoint(chosen_shape)]
                new_shapes[t] = flt
        return new_shapes

    def apply_disjointness_filter(shapes):
        # Quick forward-checking: if any pair of islands have all shapes overlapping, hard to check.
        # We'll just ensure no domain is empty (already handled).
        return shapes

    def dfs(state, shapes):
        pr = propagate(state[:], deep_copy_shapes(shapes))
        if pr is None:
            return None
        state, shapes = pr

        # Additional disjointness pruning by removing shapes conflicting with forced whites?
        # If a cell is fixed white and belongs to some island, it must be covered by exactly one island.
        # We'll enforce: any fixed white cell must belong to at least one shape of some island; also,
        # if it's only possible in one island, remove shapes of others that contain it (still allows; islands disjoint anyway).
        fixed_white = [i for i, v in enumerate(state) if v == 0 and i not in nums]
        if fixed_white:
            cell_to_islands = defaultdict(set)
            for s in numbered_list:
                for sh in shapes[s]:
                    for i in fixed_white:
                        if i in sh:
                            cell_to_islands[i].add(s)
            for i in fixed_white:
                if not cell_to_islands[i]:
                    return None

        if is_complete(state):
            if validate_final(state, shapes):
                return state
            return None

        ch = choose_branch(state, shapes)
        if ch is None:
            return None

        if ch[0] == "shape":
            s = ch[1]
            # Try shapes with heuristic: prefer shapes that cover more currently forced/likely whites and avoid enclosing holes
            def score(sh):
                # fewer boundary unknowns (more constrained) first
                boundary_unknown = 0
                for v in sh:
                    for nb in neigh[v]:
                        if nb not in sh and state[nb] == -1:
                            boundary_unknown += 1
                return boundary_unknown

            options = sorted(shapes[s], key=score)
            for chosen in options:
                # set all cells in chosen to white; adjacent to chosen not forced here (handled by propagation)
                st2 = state[:]
                q = deque()
                ok = True
                for i in chosen:
                    if st2[i] == 1:
                        ok = False
                        break
                    st2[i] = 0
                if not ok:
                    continue
                # Enforce disjointness by filtering shapes
                sh2 = restrict_shapes_to_choice(shapes, s, chosen)
                # Also ensure other islands shapes don't include any already white cells that belong to chosen island:
                sh2 = apply_disjointness_filter(sh2)
                res = dfs(st2, sh2)
                if res is not None:
                    return res
            return None

        else:
            cell = ch[1]
            # Branch black first if cell cannot easily be white (few shape memberships), else white first.
            memberships = 0
            for s in numbered_list:
                memberships += sum(1 for sh in shapes[s] if cell in sh)
            order = [1, 0] if memberships <= 2 else [0, 1]
            for val in order:
                st2 = state[:]
                sh2 = deep_copy_shapes(shapes)
                q = deque()
                if not assign_cell(st2, cell, val, q):
                    continue
                res = dfs(st2, sh2)
                if res is not None:
                    return res
            return None

    result = dfs(state0, shapes0)
    if result is None:
        return "No Solution"

    # Build output grid: 'B' for black else None
    out = []
    for r in range(R):
        row = []
        for c in range(C):
            i = idx(r, c)
            row.append('B' if result[i] == 1 else None)
        out.append(row)
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, 2, None, None, None, 2, None], [2, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, 6], [None, 1, None, None, None, 3, None], [None, None, None, None, None, None, None]]}

from collections import deque, defaultdict
import itertools

# Nurikabe solver with human-like constraint propagation + aggressive pruning.
# Grid values: -1 unknown, 0 white, 1 black.
# Numbered cells are forced white and define islands; each island size fixed.

DIR4 = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    data = observation["data"]
    R, C = len(data), len(data[0])
    nums = {}
    seeds = []
    for r in range(R):
        for c in range(C):
            v = data[r][c]
            if v is not None:
                nums[(r, c)] = int(v)
                seeds.append((r, c))

    # Precompute neighbors
    neigh = {}
    for r in range(R):
        for c in range(C):
            ns = []
            for dr, dc in DIR4:
                rr, cc = r + dr, c + dc
                if 0 <= rr < R and 0 <= cc < C:
                    ns.append((rr, cc))
            neigh[(r, c)] = ns

    # Compute forbidden adjacency between islands: two different islands may not touch orthogonally.
    seed_index = {p: i for i, p in enumerate(seeds)}
    K = len(seeds)

    # Initial state
    grid = [[-1] * C for _ in range(R)]
    for (r, c) in seeds:
        grid[r][c] = 0

    # Island assignment: for white cells, which island (seed index) it belongs to; -1 if unassigned/unknown.
    owner = [[-1] * C for _ in range(R)]
    for p, i in seed_index.items():
        owner[p[0]][p[1]] = i

    # For each island i: set of cells assigned, and remaining size
    assigned = [set([seeds[i]]) for i in range(K)]
    target = [nums[seeds[i]] for i in range(K)]

    # Domain: for each cell, possible colors (bitmask): 1=white,2=black. Unknown => 3
    dom = [[3] * C for _ in range(R)]
    for (r, c) in seeds:
        dom[r][c] = 1  # white only

    # Utility
    def inb(p):
        r, c = p
        return 0 <= r < R and 0 <= c < C

    def cells():
        for r in range(R):
            for c in range(C):
                yield (r, c)

    # Trail for undo
    trail = []

    def trail_set_dom(r, c, newmask):
        old = dom[r][c]
        if old == newmask:
            return True
        if old & newmask == 0:
            return False
        trail.append(("dom", r, c, old))
        dom[r][c] = old & newmask
        return True

    def trail_set_cell(r, c, val):
        # val: 0 white, 1 black
        if grid[r][c] == val:
            return True
        if grid[r][c] != -1 and grid[r][c] != val:
            return False
        trail.append(("grid", r, c, grid[r][c]))
        grid[r][c] = val
        # reflect to domain
        if val == 0:
            return trail_set_dom(r, c, 1)
        else:
            return trail_set_dom(r, c, 2)

    def trail_set_owner(r, c, ow):
        if owner[r][c] == ow:
            return True
        if owner[r][c] != -1 and owner[r][c] != ow:
            return False
        trail.append(("own", r, c, owner[r][c]))
        owner[r][c] = ow
        return True

    def trail_add_assigned(i, p):
        if p in assigned[i]:
            return True
        trail.append(("asg", i, p))
        assigned[i].add(p)
        return True

    def undo(to_len):
        while len(trail) > to_len:
            t = trail.pop()
            if t[0] == "dom":
                _, r, c, old = t
                dom[r][c] = old
            elif t[0] == "grid":
                _, r, c, old = t
                grid[r][c] = old
            elif t[0] == "own":
                _, r, c, old = t
                owner[r][c] = old
            elif t[0] == "asg":
                _, i, p = t
                assigned[i].remove(p)

    def is_white_mask(m): return (m & 1) != 0
    def is_black_mask(m): return (m & 2) != 0

    # ---- Core constraints & propagation ----

    def check_no_2x2_all_black_local(r, c):
        # If any 2x2 block including (r,c) becomes all black -> fail
        for dr in (-1, 0):
            for dc in (-1, 0):
                rr, cc = r + dr, c + dc
                if 0 <= rr < R - 1 and 0 <= cc < C - 1:
                    coords = [(rr, cc), (rr + 1, cc), (rr, cc + 1), (rr + 1, cc + 1)]
                    all_black = True
                    for (a, b) in coords:
                        if grid[a][b] != 1:
                            all_black = False
                            break
                    if all_black:
                        return False
        return True

    def forbid_2x2_completion():
        # Human-like: if 3 blacks in a 2x2 then the 4th must be white.
        for r in range(R - 1):
            for c in range(C - 1):
                coords = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                blacks = [(a, b) for (a, b) in coords if grid[a][b] == 1]
                unknowns = [(a, b) for (a, b) in coords if grid[a][b] == -1]
                if len(blacks) == 4:
                    return False
                if len(blacks) == 3 and len(unknowns) == 1:
                    a, b = unknowns[0]
                    if not trail_set_cell(a, b, 0):
                        return False
        return True

    def island_adjacency_forbid():
        # If a white cell assigned to island i, then its neighbors cannot be white for another island.
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 0 and owner[r][c] != -1:
                    i = owner[r][c]
                    for (rr, cc) in neigh[(r, c)]:
                        if (rr, cc) in seed_index and seed_index[(rr, cc)] != i:
                            # already white seed but different island orthogonally adjacent -> impossible
                            return False
                        if grid[rr][cc] == 0 and owner[rr][cc] != -1 and owner[rr][cc] != i:
                            return False
                        # neighbor cannot be white if it would force different island; we handle by restricting owner when whitening
        return True

    def compute_island_frontier(i):
        # Potential expansion cells for island i: unknown cells adjacent to assigned cells,
        # not adjacent to other island's assigned/seed (orthogonally), and domain allows white.
        front = set()
        for (r, c) in assigned[i]:
            for (rr, cc) in neigh[(r, c)]:
                if grid[rr][cc] == 1:
                    continue
                if not is_white_mask(dom[rr][cc]):
                    continue
                # Cannot include a numbered cell of another island
                if (rr, cc) in seed_index and seed_index[(rr, cc)] != i:
                    continue
                # Orthogonal adjacency constraint: if neighbor cell is adjacent to a cell owned by other island, cannot be white for i
                bad = False
                for (aa, bb) in neigh[(rr, cc)]:
                    if grid[aa][bb] == 0 and owner[aa][bb] != -1 and owner[aa][bb] != i:
                        bad = True
                        break
                    if (aa, bb) in seed_index and seed_index[(aa, bb)] != i:
                        # numbered cell is white and belongs to other island; adjacency would merge islands
                        bad = True
                        break
                if bad:
                    continue
                front.add((rr, cc))
        return front

    def max_reachable_island_size(i):
        # BFS in "could-be-white" cells respecting adjacency to other islands.
        # Upper bound for island i; used for pruning.
        allowed = set(assigned[i])
        q = deque(assigned[i])
        seen = set(assigned[i])
        while q:
            r, c = q.popleft()
            for (rr, cc) in neigh[(r, c)]:
                if (rr, cc) in seen:
                    continue
                if not is_white_mask(dom[rr][cc]):
                    continue
                if grid[rr][cc] == 1:
                    continue
                if (rr, cc) in seed_index and seed_index[(rr, cc)] != i:
                    continue
                # adjacency to other island whites/seeds
                bad = False
                for (aa, bb) in neigh[(rr, cc)]:
                    if grid[aa][bb] == 0 and owner[aa][bb] != -1 and owner[aa][bb] != i:
                        bad = True
                        break
                    if (aa, bb) in seed_index and seed_index[(aa, bb)] != i:
                        bad = True
                        break
                if bad:
                    continue
                seen.add((rr, cc))
                q.append((rr, cc))
        return len(seen)

    def assign_white_to_island(r, c, i):
        # set cell white and owned by island i, add to assigned set
        if not trail_set_cell(r, c, 0):
            return False
        if not trail_set_owner(r, c, i):
            return False
        if not trail_add_assigned(i, (r, c)):
            return False
        return True

    def force_island_completion_and_separation():
        # Techniques:
        # - If island size reached target => all adjacent unknowns must be black (cannot extend).
        # - If island needs k cells but frontier size == k => all frontier forced white for this island.
        # - Prune if assigned > target or max_reachable < target.
        for i in range(K):
            a = len(assigned[i])
            t = target[i]
            if a > t:
                return False
            if max_reachable_island_size(i) < t:
                return False

            if a == t:
                # boundary must be black (or already black), except cells already white of same island (none)
                for (r, c) in list(assigned[i]):
                    for (rr, cc) in neigh[(r, c)]:
                        if grid[rr][cc] == -1:
                            # If could become white for i or any, it's forbidden now due to island fixed size:
                            if not trail_set_cell(rr, cc, 1):
                                return False
                            if not check_no_2x2_all_black_local(rr, cc):
                                return False

            else:
                frontier = compute_island_frontier(i)
                need = t - a
                if len(frontier) < need:
                    return False
                if len(frontier) == need:
                    # all must be taken
                    for (rr, cc) in frontier:
                        if owner[rr][cc] not in (-1, i):
                            return False
                        if not assign_white_to_island(rr, cc, i):
                            return False
        return True

    def enforce_unique_island_ownership():
        # If a cell is forced white by domain/grid but unowned, try to deduce possible island owners.
        # If exactly one island can own it, assign; if none -> contradiction.
        changed = True
        while changed:
            changed = False
            for r in range(R):
                for c in range(C):
                    if grid[r][c] != 0:
                        continue
                    if (r, c) in seed_index:
                        continue
                    if owner[r][c] != -1:
                        continue
                    # determine candidate islands that could legally own (r,c): must be connectable to assigned cells
                    cands = []
                    for i in range(K):
                        if len(assigned[i]) >= target[i]:
                            continue
                        # connectable if adjacent to assigned[i]
                        adj = False
                        for (rr, cc) in neigh[(r, c)]:
                            if (rr, cc) in assigned[i]:
                                adj = True
                                break
                        if not adj:
                            continue
                        # would violate adjacency to other islands?
                        bad = False
                        for (aa, bb) in neigh[(r, c)]:
                            if grid[aa][bb] == 0 and owner[aa][bb] != -1 and owner[aa][bb] != i:
                                bad = True
                                break
                            if (aa, bb) in seed_index and seed_index[(aa, bb)] != i:
                                bad = True
                                break
                        if bad:
                            continue
                        cands.append(i)
                    if not cands:
                        return False
                    if len(cands) == 1:
                        if not trail_set_owner(r, c, cands[0]):
                            return False
                        if not trail_add_assigned(cands[0], (r, c)):
                            return False
                        changed = True
        return True

    def white_connectivity_within_island_check():
        # Ensure each island's assigned whites are connected to its seed (by construction should be).
        # Also ensure no two seeds are connected via white cells.
        # We enforce via owner uniqueness and adjacency rules; still, detect accidental merge.
        # BFS each seed on white cells; if reaches another seed -> fail.
        for i, s in enumerate(seeds):
            q = deque([s])
            seen = {s}
            while q:
                r, c = q.popleft()
                for (rr, cc) in neigh[(r, c)]:
                    if (rr, cc) in seen:
                        continue
                    if grid[rr][cc] != 0:
                        continue
                    if (rr, cc) in seed_index and seed_index[(rr, cc)] != i:
                        return False
                    # if owned by different island -> also fail
                    if owner[rr][cc] != -1 and owner[rr][cc] != i:
                        return False
                    seen.add((rr, cc))
                    q.append((rr, cc))
        return True

    def black_connectivity_possible():
        # Necessary condition: all confirmed black cells must be mutually connectable through
        # cells that are not forced white (i.e., black or unknown).
        blacks = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 1]
        if not blacks:
            return True
        start = blacks[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for (rr, cc) in neigh[(r, c)]:
                if (rr, cc) in seen:
                    continue
                if grid[rr][cc] == 0:
                    continue
                if not is_black_mask(dom[rr][cc]) and grid[rr][cc] != 1:
                    continue
                seen.add((rr, cc))
                q.append((rr, cc))
        for b in blacks:
            if b not in seen:
                return False
        return True

    def forced_black_singletons():
        # If an unknown cell cannot be white for any island (including due to adjacency), force black.
        for r in range(R):
            for c in range(C):
                if grid[r][c] != -1:
                    continue
                if not is_black_mask(dom[r][c]):
                    # must be white, handled elsewhere
                    continue
                if not is_white_mask(dom[r][c]):
                    continue  # already black-only
                # can it be white for at least one island?
                possible = False
                if (r, c) in seed_index:
                    possible = True
                else:
                    for i in range(K):
                        if len(assigned[i]) >= target[i]:
                            continue
                        # would need adjacency to island i assigned or could be future connection via unknowns:
                        # Human-like conservative: require adjacency to currently assigned to be immediately plausible.
                        adj = any((rr, cc) in assigned[i] for (rr, cc) in neigh[(r, c)])
                        if not adj:
                            continue
                        bad = False
                        for (aa, bb) in neigh[(r, c)]:
                            if grid[aa][bb] == 0 and owner[aa][bb] != -1 and owner[aa][bb] != i:
                                bad = True
                                break
                            if (aa, bb) in seed_index and seed_index[(aa, bb)] != i:
                                bad = True
                                break
                        if bad:
                            continue
                        possible = True
                        break
                if not possible:
                    if not trail_set_cell(r, c, 1):
                        return False
                    if not check_no_2x2_all_black_local(r, c):
                        return False
        return True

    def propagate():
        # Repeatedly apply deductions until fixed point.
        while True:
            before = len(trail)
            # Domain-grid consistency
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == -1:
                        # if domain singleton, set
                        if dom[r][c] == 1:
                            if not trail_set_cell(r, c, 0):
                                return False
                        elif dom[r][c] == 2:
                            if not trail_set_cell(r, c, 1):
                                return False
                                # check 2x2
                            if not check_no_2x2_all_black_local(r, c):
                                return False
                    else:
                        # already fixed; ensure domain
                        if grid[r][c] == 0 and not is_white_mask(dom[r][c]):
                            return False
                        if grid[r][c] == 1 and not is_black_mask(dom[r][c]):
                            return False

            if not forbid_2x2_completion():
                return False
            if not force_island_completion_and_separation():
                return False
            if not enforce_unique_island_ownership():
                return False
            if not island_adjacency_forbid():
                return False
            if not white_connectivity_within_island_check():
                return False
            if not forced_black_singletons():
                return False
            if not black_connectivity_possible():
                return False

            if len(trail) == before:
                return True

    def all_assigned():
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    return False
        return True

    def final_black_connected_and_valid():
        # Check black connectivity and no 2x2 all black already enforced, islands exact sizes & unique.
        if not black_connectivity_possible():
            return False
        # Islands sizes exact
        for i in range(K):
            if len(assigned[i]) != target[i]:
                return False
        # No stray whites
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 0 and owner[r][c] == -1 and (r, c) not in seed_index:
                    return False
        return True

    def choose_branch_cell():
        # Heuristic: pick unknown cell with smallest domain; prefer cells in some island frontier.
        best = None
        best_score = 10**9
        front_cells = set()
        for i in range(K):
            if len(assigned[i]) < target[i]:
                front_cells |= compute_island_frontier(i)
        for r in range(R):
            for c in range(C):
                if grid[r][c] != -1:
                    continue
                m = dom[r][c]
                bits = (1 if is_white_mask(m) else 0) + (1 if is_black_mask(m) else 0)
                if bits <= 1:
                    continue
                score = bits * 100
                if (r, c) in front_cells:
                    score -= 50
                # additional: proximity to any seed to resolve islands early
                mind = min(abs(r - sr) + abs(c - sc) for (sr, sc) in seeds) if seeds else 0
                score += mind
                if score < best_score:
                    best_score = score
                    best = (r, c)
        return best

    def branch_assignments_for_cell(r, c):
        # Prefer white if it can be uniquely assigned to an island frontier, otherwise try black too.
        options = []
        if is_white_mask(dom[r][c]):
            # Candidate islands
            cands = []
            if (r, c) in seed_index:
                cands = [seed_index[(r, c)]]
            else:
                for i in range(K):
                    if len(assigned[i]) >= target[i]:
                        continue
                    if any((rr, cc) in assigned[i] for (rr, cc) in neigh[(r, c)]):
                        # adjacency ok
                        bad = False
                        for (aa, bb) in neigh[(r, c)]:
                            if grid[aa][bb] == 0 and owner[aa][bb] != -1 and owner[aa][bb] != i:
                                bad = True
                                break
                            if (aa, bb) in seed_index and seed_index[(aa, bb)] != i:
                                bad = True
                                break
                        if not bad:
                            cands.append(i)
            if len(cands) == 1:
                options.append(("W", cands[0]))
            else:
                # still can set white without deciding owner? Not allowed; must belong to exactly one island.
                # We'll branch by owner assignment when whitening.
                for i in cands:
                    options.append(("W", i))
        if is_black_mask(dom[r][c]):
            options.append(("B", None))
        # order: deterministic; white first generally helps.
        return options

    def dfs():
        tlen = len(trail)
        if not propagate():
            undo(tlen)
            return False
        if all_assigned():
            ok = final_black_connected_and_valid()
            undo(tlen)
            return ok

        cell = choose_branch_cell()
        if cell is None:
            # no branchable cell; maybe remaining unknowns have singleton domains but not set (shouldn't happen)
            ok = propagate() and all_assigned() and final_black_connected_and_valid()
            undo(tlen)
            return ok
        r, c = cell
        opts = branch_assignments_for_cell(r, c)
        if not opts:
            undo(tlen)
            return False

        for typ, info in opts:
            t2 = len(trail)
            good = True
            if typ == "B":
                if not trail_set_cell(r, c, 1):
                    good = False
                else:
                    if not check_no_2x2_all_black_local(r, c):
                        good = False
            else:
                # white owned by island info
                if not assign_white_to_island(r, c, info):
                    good = False
            if good and dfs():
                return True
            undo(t2)

        undo(tlen)
        return False

    # Initial propagation
    if not propagate():
        return "No Solution"

    # Search
    if not dfs():
        return "No Solution"

    # dfs() undoes its changes; re-run with solution capture by modifying dfs to keep state.
    # Instead, run a second dfs that stops at first solution and keeps grid via non-undo at success.
    def dfs_keep():
        if not propagate():
            return False
        if all_assigned():
            return final_black_connected_and_valid()
        cell = choose_branch_cell()
        if cell is None:
            return all_assigned() and final_black_connected_and_valid()
        r, c = cell
        opts = branch_assignments_for_cell(r, c)
        for typ, info in opts:
            t2 = len(trail)
            good = True
            if typ == "B":
                if not trail_set_cell(r, c, 1):
                    good = False
                else:
                    if not check_no_2x2_all_black_local(r, c):
                        good = False
            else:
                if not assign_white_to_island(r, c, info):
                    good = False
            if good and dfs_keep():
                return True
            undo(t2)
        return False

    trail.clear()
    # Reset state for keep-run
    grid = [[-1] * C for _ in range(R)]
    owner = [[-1] * C for _ in range(R)]
    dom = [[3] * C for _ in range(R)]
    for (r, c) in seeds:
        grid[r][c] = 0
        dom[r][c] = 1
        owner[r][c] = seed_index[(r, c)]
    assigned = [set([seeds[i]]) for i in range(K)]

    if not dfs_keep():
        return "No Solution"

    # Build answer: 'B' for black, None for white
    ans = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if grid[r][c] == 1 else None)
        ans.append(row)
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, 5, None], [None, None, None, None, 1], [None, None, None, None, None], [1, None, 3, None, None]]}
from collections import deque, defaultdict
from itertools import combinations, product

# Nurikabe solver with strong constraint propagation + small, highly-pruned search.
# Representation:
#   cell state: -1 unknown, 0 white, 1 black
# Output grid: 'B' for black else None for white.

DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def solve(observation):
    data = observation["data"]
    R, C = len(data), len(data[0])
    N = R * C

    def idx(r, c): return r * C + c
    def rc(i): return divmod(i, C)
    def inb(r, c): return 0 <= r < R and 0 <= c < C

    numbered = {}
    for r in range(R):
        for c in range(C):
            v = data[r][c]
            if v is not None:
                numbered[idx(r, c)] = int(v)

    # Precompute adjacency lists
    adj = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            i = idx(r, c)
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if inb(rr, cc):
                    adj[i].append(idx(rr, cc))

    # Precompute 2x2 blocks: each is tuple of 4 indices
    blocks2x2 = []
    cell_to_blocks = [[] for _ in range(N)]
    for r in range(R - 1):
        for c in range(C - 1):
            b = (idx(r, c), idx(r + 1, c), idx(r, c + 1), idx(r + 1, c + 1))
            bi = len(blocks2x2)
            blocks2x2.append(b)
            for x in b:
                cell_to_blocks[x].append(bi)

    # For each numbered cell, compute all connected polyomino placements of given size
    # that include the numbered cell and do NOT include other numbered cells.
    # Also compute for each placement its boundary (neighbors outside placement) to enforce separation.
    other_numbered_set = set(numbered.keys())

    def gen_island_shapes(root, size):
        # Generate connected sets containing root within size using BFS frontier expansion.
        # Use canonical frozenset of indices. Prune early via bounding potential expansion.
        if size == 1:
            return [frozenset([root])]
        res = []
        start = frozenset([root])
        q = deque([start])
        seen = set([start])
        while q:
            S = q.popleft()
            if len(S) == size:
                res.append(S)
                continue
            # Candidate expansion cells: neighbors of S not in S
            cand = set()
            for x in S:
                for y in adj[x]:
                    if y not in S:
                        cand.add(y)
            # Prune: cannot include other numbered cells
            cand = [y for y in cand if (y == root or y not in other_numbered_set)]
            # Heuristic: expand in deterministic order
            cand.sort()
            for y in cand:
                S2 = frozenset((*S, y))
                if S2 in seen:
                    continue
                # Connectivity ensured by construction (y adjacent to S)
                # Potential growth bound: ensure enough room via reachable expansion within remaining steps.
                # Quick bound by counting distinct cells within manhattan radius (loose) is not great; do a limited BFS from S2.
                remaining = size - len(S2)
                if remaining > 0:
                    # limited reachable count from S2 through cells avoiding other numbered cells
                    allowed = set(range(N)) - (other_numbered_set - {root})
                    # BFS from S2 frontier limited by remaining layers
                    front = deque([(x, 0) for x in S2])
                    dist = {x: 0 for x in S2}
                    reach = set(S2)
                    while front:
                        x, d = front.popleft()
                        if d == remaining:
                            continue
                        for z in adj[x]:
                            if z in allowed and z not in dist:
                                dist[z] = d + 1
                                reach.add(z)
                                front.append((z, d + 1))
                    if len(reach) < size:
                        continue
                seen.add(S2)
                q.append(S2)
        return res

    island_ids = list(numbered.keys())
    island_id_index = {root: k for k, root in enumerate(island_ids)}
    island_size = {root: numbered[root] for root in island_ids}

    island_shapes = {}
    # Also map cell -> list of (root, shape_index) that include cell
    cell_in_shape = [[] for _ in range(N)]
    # For each root, shape boundaries for separation constraints (white-only islands cannot touch unless separated by black)
    island_boundaries = {}
    # Precompute shapes
    for root in island_ids:
        sz = island_size[root]
        shapes = gen_island_shapes(root, sz)
        if not shapes:
            return "No Solution"
        island_shapes[root] = shapes
        bnds = []
        for si, S in enumerate(shapes):
            bound = set()
            for x in S:
                for y in adj[x]:
                    if y not in S:
                        bound.add(y)
            bnds.append(frozenset(bound))
            for x in S:
                cell_in_shape[x].append((root, si))
        island_boundaries[root] = bnds

    # State
    st = [-1] * N
    for root in island_ids:
        st[root] = 0  # numbered are white

    # For each island root, domain is set of possible shape indices
    dom = {root: set(range(len(island_shapes[root]))) for root in island_ids}

    # Utility: DSU for black connectivity check with unknowns treated carefully not as black
    def black_components_and_frontier(st_local):
        # return list of components (list of cells) among black cells
        seen = set()
        comps = []
        for i in range(N):
            if st_local[i] == 1 and i not in seen:
                q = [i]
                seen.add(i)
                comp = []
                while q:
                    x = q.pop()
                    comp.append(x)
                    for y in adj[x]:
                        if st_local[y] == 1 and y not in seen:
                            seen.add(y)
                            q.append(y)
                comps.append(comp)
        return comps

    def any_2x2_all_black(st_local):
        for b in blocks2x2:
            if st_local[b[0]] == 1 and st_local[b[1]] == 1 and st_local[b[2]] == 1 and st_local[b[3]] == 1:
                return True
        return False

    # Propagation engine
    def propagate(st_local, dom_local):
        # Returns (ok, st_local, dom_local)
        q = deque()

        # Initialize queue with all islands
        for root in island_ids:
            q.append(("island", root))
        # Also cell-based constraints
        for i in range(N):
            q.append(("cell", i))

        def assign_cell(i, val):
            cur = st_local[i]
            if cur == val:
                return True
            if cur != -1 and cur != val:
                return False
            st_local[i] = val
            q.append(("cell", i))
            # 2x2 affected
            for bi in cell_to_blocks[i]:
                q.append(("block", bi))
            # black connectivity affected
            q.append(("blackconn", None))
            # islands affected by this cell
            for root, _ in cell_in_shape[i]:
                q.append(("island", root))
            return True

        def prune_island_domain(root):
            D = dom_local[root]
            if not D:
                return False
            shapes = island_shapes[root]
            bnds = island_boundaries[root]
            changed = False
            to_remove = []
            for si in D:
                S = shapes[si]
                # Must be compatible with cell colors:
                # all cells in S must be white (or unknown)
                ok = True
                for x in S:
                    if st_local[x] == 1:
                        ok = False
                        break
                if not ok:
                    to_remove.append(si)
                    continue
                # Cells outside S are not necessarily black, but important:
                #  - Another island cannot overlap due to numbered exclusion already in generation.
                #  - Separation: If a boundary cell is forced white and belongs to other island, that's fine,
                #    but if it's forced white yet would touch this island, islands would merge unless that cell is black.
                # In Nurikabe, different white islands must be separated by black; hence any cell adjacent to S
                # that is white must be part of SAME island, impossible. So boundary cells cannot be white.
                for y in bnds[si]:
                    if st_local[y] == 0 and y not in S:
                        ok = False
                        break
                if not ok:
                    to_remove.append(si)
                    continue
            if to_remove:
                for si in to_remove:
                    D.remove(si)
                changed = True
            if not D:
                return False
            if changed:
                q.append(("island", root))
            # If singleton, we can force its cells and boundary blacks
            if len(D) == 1:
                si = next(iter(D))
                S = island_shapes[root][si]
                B = island_boundaries[root][si]
                # all S -> white
                for x in S:
                    if not assign_cell(x, 0):
                        return False
                # boundary must be black (cannot be white); if unknown => black
                for y in B:
                    if st_local[y] == -1:
                        if not assign_cell(y, 1):
                            return False
                    elif st_local[y] == 0 and y not in S:
                        return False
            else:
                # Compute forced whites: intersection of all shapes
                inter = None
                union = set()
                for si in D:
                    S = island_shapes[root][si]
                    union |= set(S)
                    inter = set(S) if inter is None else (inter & set(S))
                # forced whites
                if inter:
                    for x in inter:
                        if not assign_cell(x, 0):
                            return False
                # Cells that cannot be in island but are adjacent? handled via boundary checks per shape and via other islands.
            return True

        def cell_based_prune(i):
            # If cell is white, it must belong to exactly one island's chosen shape.
            # If cell is black, it must belong to no island.
            if st_local[i] == 1:
                # remove any shapes containing i
                for root, si in list(cell_in_shape[i]):
                    if si in dom_local[root]:
                        dom_local[root].remove(si)
                        q.append(("island", root))
                        if not dom_local[root]:
                            return False
                return True
            if st_local[i] == 0:
                # if it's a numbered root, fine.
                # else it must be covered by at least one island domain
                if i in numbered:
                    return True
                covering = []
                for root, si in cell_in_shape[i]:
                    if si in dom_local[root]:
                        covering.append((root, si))
                if not covering:
                    return False
                # also: if only one island can cover, then restrict that island to shapes covering i
                roots = set(r for r, _ in covering)
                if len(roots) == 1:
                    r = next(iter(roots))
                    allowed = set(si for rr, si in covering if rr == r)
                    if allowed != dom_local[r]:
                        dom_local[r] &= allowed
                        if not dom_local[r]:
                            return False
                        q.append(("island", r))
            return True

        def block_prune(bi):
            b = blocks2x2[bi]
            # If three are black and the last unknown -> must be white
            blacks = [x for x in b if st_local[x] == 1]
            unknowns = [x for x in b if st_local[x] == -1]
            if len(blacks) == 4:
                return False
            if len(blacks) == 3 and len(unknowns) == 1:
                if not assign_cell(unknowns[0], 0):
                    return False
            return True

        def black_connectivity_prune():
            # Necessary condition: black cells must be able to become connected through unknowns.
            # If there are k black components, we need at least (k-1) unknown cells that can connect them via paths.
            comps = black_components_and_frontier(st_local)
            if len(comps) <= 1:
                return True
            # Build graph where nodes are components, edges if there exists a path through unknown cells between comps
            # Quick check: For each component, BFS through unknowns to see which other components reachable.
            comp_id = {}
            for ci, comp in enumerate(comps):
                for x in comp:
                    comp_id[x] = ci
            # BFS from border of each comp through unknowns, detect reachable comps
            reach = [set() for _ in range(len(comps))]
            for ci, comp in enumerate(comps):
                dq = deque()
                vis = set()
                for x in comp:
                    for y in adj[x]:
                        if st_local[y] != 1 and y not in vis:  # can traverse unknown/white? In final black connectivity, whites block.
                            # Only unknowns can become black; whites are obstacles.
                            if st_local[y] == -1:
                                vis.add(y)
                                dq.append(y)
                while dq:
                    u = dq.popleft()
                    for v in adj[u]:
                        if st_local[v] == -1 and v not in vis:
                            vis.add(v)
                            dq.append(v)
                        elif st_local[v] == 1:
                            cj = comp_id[v]
                            if cj != ci:
                                reach[ci].add(cj)
                # no need to fully connect, just ensure each comp can reach some other via unknowns
            # If any component cannot reach any other, impossible
            for ci in range(len(comps)):
                if not reach[ci]:
                    return False
            return True

        # Main loop
        while q:
            typ, arg = q.popleft()
            if typ == "island":
                if not prune_island_domain(arg):
                    return False, st_local, dom_local
            elif typ == "cell":
                if not cell_based_prune(arg):
                    return False, st_local, dom_local
                # If cell unknown, sometimes forced by island coverage:
                # if unknown cell cannot be in any island shape domain -> must be black
                if st_local[arg] == -1:
                    can_be_white = False
                    for root, si in cell_in_shape[arg]:
                        if si in dom_local[root]:
                            can_be_white = True
                            break
                    if not can_be_white:
                        if not assign_cell(arg, 1):
                            return False, st_local, dom_local
            elif typ == "block":
                if not block_prune(arg):
                    return False, st_local, dom_local
            elif typ == "blackconn":
                if not black_connectivity_prune():
                    return False, st_local, dom_local
            else:
                raise RuntimeError("Unknown constraint type")

            if any_2x2_all_black(st_local):
                return False, st_local, dom_local

        return True, st_local, dom_local

    def is_solved(st_local, dom_local):
        if any(v == -1 for v in st_local):
            return False
        # Each island domain must be singleton and consistent
        for root in island_ids:
            if len(dom_local[root]) != 1:
                return False
        # White cell coverage uniqueness: every white cell belongs to exactly one island
        cover_count = [0] * N
        for root in island_ids:
            si = next(iter(dom_local[root]))
            for x in island_shapes[root][si]:
                cover_count[x] += 1
        for i in range(N):
            if st_local[i] == 0:
                if cover_count[i] != 1:
                    return False
            else:
                if cover_count[i] != 0:
                    return False
        # Black connectivity: all black connected
        comps = black_components_and_frontier(st_local)
        return len(comps) <= 1

    def choose_branch(st_local, dom_local):
        # Prefer smallest island domain > 1
        best = None
        best_root = None
        for root in island_ids:
            d = dom_local[root]
            if 1 < len(d):
                if best is None or len(d) < best:
                    best = len(d)
                    best_root = root
        if best_root is not None:
            return ("island", best_root)
        # Else choose unknown cell that is most constrained: few covering shapes
        best_cell = None
        best_cov = None
        for i in range(N):
            if st_local[i] == -1:
                cov = 0
                for root, si in cell_in_shape[i]:
                    if si in dom_local[root]:
                        cov += 1
                if best_cov is None or cov < best_cov:
                    best_cov = cov
                    best_cell = i
        if best_cell is not None:
            return ("cell", best_cell)
        return None

    def deep_copy_state(st_local, dom_local):
        return st_local[:], {k: set(v) for k, v in dom_local.items()}

    def dfs(st_local, dom_local, depth=0):
        ok, st2, dom2 = propagate(st_local, dom_local)
        if not ok:
            return None
        if is_solved(st2, dom2):
            return st2, dom2
        choice = choose_branch(st2, dom2)
        if choice is None:
            return None
        typ, arg = choice
        if typ == "island":
            root = arg
            # Try shapes ordered by heuristic: maximize forced boundary blacks already black, minimize conflicts
            candidates = list(dom2[root])
            def score(si):
                S = island_shapes[root][si]
                B = island_boundaries[root][si]
                # prefer shapes that agree with current whites and set more unknown boundary to black (reduce ambiguity)
                conflict = 0
                for x in S:
                    if st2[x] == 1:
                        conflict += 10
                for y in B:
                    if st2[y] == 0 and y not in S:
                        conflict += 10
                gain = sum(1 for y in B if st2[y] == -1)
                return (conflict, -gain)
            candidates.sort(key=score)
            for si in candidates:
                stc, domc = deep_copy_state(st2, dom2)
                domc[root] = {si}
                res = dfs(stc, domc, depth + 1)
                if res is not None:
                    return res
            return None
        else:
            i = arg
            # Branch on black first if cell cannot be white easily
            can_white = False
            for root, si in cell_in_shape[i]:
                if si in dom2[root]:
                    can_white = True
                    break
            vals = [1, 0] if can_white else [1, 0]
            for v in vals:
                stc, domc = deep_copy_state(st2, dom2)
                stc[i] = v
                res = dfs(stc, domc, depth + 1)
                if res is not None:
                    return res
            return None

    init_st, init_dom = st, dom
    result = dfs(init_st, init_dom)
    if result is None:
        return "No Solution"
    st_sol, dom_sol = result

    out = []
    for r in range(R):
        row = []
        for c in range(C):
            i = idx(r, c)
            row.append('B' if st_sol[i] == 1 else None)
        out.append(row)
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None], [2, None, None, None], [None, None, None, None], [None, None, None, None]], 'adjacent': [[0.0, 0.5], [0.0, 2.5], [0.5, 0.0], [0.5, 2.0], [1.0, 1.5], [1.5, 1.0], [1.5, 3.0], [2.0, 0.5], [2.0, 2.5], [2.5, 0.0], [2.5, 2.0], [3.0, 1.5]]}
from __future__ import annotations

from collections import deque
from typing import List, Tuple, Optional, Dict, Set

# Solver for "Consecutive Dots Latin Square" (a.k.a. Kropki-like with ONLY black dots):
# - Grid size N x N, values 1..N
# - Each row/col is a permutation (Latin square constraints)
# - Dot between orthogonally adjacent cells => values are consecutive (abs diff == 1)
# - No dot between orthogonally adjacent cells => values are NOT consecutive (abs diff != 1)
#
# Approach mirrors strong human-style deduction:
# 1) Candidate sets per cell (bitmasks).
# 2) Iterative propagation:
#    - Given numbers enforce row/col exclusion.
#    - Dot constraints: neighbor must be +/-1.
#    - No-dot constraints: forbid +/-1.
#    - Hidden singles in rows/cols.
#    - Pair/triple eliminations via subset counting (naked subsets) in rows/cols.
# 3) If stalled, branch using MRV with strong forward checking (not naive search).
#
# Representation:
# - Candidates: int bitmask of possible values.
# - Values mapped 1..N to bits 0..N-1.
#
# Designed to be general, efficient, and library-free.

def solve(observation):
    data = observation["data"]
    N = len(data)
    if any(len(r) != N for r in data):
        return "No Solution"

    # Build dot adjacency set keyed by unordered cell pairs.
    # observation["adjacent"] contains midpoints; infer endpoints.
    dot_pairs = set()
    for (rr, cc) in observation.get("adjacent", []):
        r = rr
        c = cc
        # Horizontal midpoint at (row, col+0.5)
        if abs(r - int(r)) < 1e-9 and abs(c - (int(c) + 0.5)) < 1e-9:
            row = int(r)
            col = int(c - 0.5)
            a = (row, col)
            b = (row, col + 1)
        # Vertical midpoint at (row+0.5, col)
        elif abs(c - int(c)) < 1e-9 and abs(r - (int(r) + 0.5)) < 1e-9:
            row = int(r - 0.5)
            col = int(c)
            a = (row, col)
            b = (row + 1, col)
        else:
            # Ignore malformed
            continue
        if 0 <= a[0] < N and 0 <= a[1] < N and 0 <= b[0] < N and 0 <= b[1] < N:
            if a > b:
                a, b = b, a
            dot_pairs.add((a, b))

    # Precompute neighbor relations for each edge: dotted or not
    # We'll store all orthogonal edges.
    edges = []
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                a = (r, c)
                b = (r, c + 1)
                aa, bb = (a, b) if a < b else (b, a)
                dotted = (aa, bb) in dot_pairs
                edges.append((a, b, dotted))
            if r + 1 < N:
                a = (r, c)
                b = (r + 1, c)
                aa, bb = (a, b) if a < b else (b, a)
                dotted = (aa, bb) in dot_pairs
                edges.append((a, b, dotted))

    ALL = (1 << N) - 1

    def bit(v: int) -> int:
        return 1 << (v - 1)

    def bits_to_list(mask: int) -> List[int]:
        out = []
        m = mask
        while m:
            lsb = m & -m
            idx = (lsb.bit_length() - 1)
            out.append(idx + 1)
            m -= lsb
        return out

    def popcount(x: int) -> int:
        return x.bit_count()

    def is_single(mask: int) -> bool:
        return mask and (mask & (mask - 1)) == 0

    def single_value(mask: int) -> int:
        return mask.bit_length()  # since only one bit; bit_length gives index+1

    # For each value, precompute consecutive values mask (within 1..N)
    cons_mask = [0] * (N + 1)
    for v in range(1, N + 1):
        m = 0
        if v - 1 >= 1:
            m |= bit(v - 1)
        if v + 1 <= N:
            m |= bit(v + 1)
        cons_mask[v] = m

    # For each candidate mask, precompute union of consecutive masks for any value in it.
    # This is computed on the fly with caching.
    cons_cache: Dict[int, int] = {}

    def consecutive_union(mask: int) -> int:
        # For a set of possible values in a cell, what values can a dotted neighbor take?
        if mask in cons_cache:
            return cons_cache[mask]
        res = 0
        m = mask
        while m:
            lsb = m & -m
            v = (lsb.bit_length())
            res |= cons_mask[v]
            m -= lsb
        cons_cache[mask] = res
        return res

    # Initialize candidates
    cand = [[ALL for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                cand[r][c] = bit(v)

    # Units (rows, cols) cell lists
    rows = [[(r, c) for c in range(N)] for r in range(N)]
    cols = [[(r, c) for r in range(N)] for c in range(N)]

    # Helper to eliminate a value bit from a cell, track changes
    def remove_mask(r: int, c: int, rem: int) -> bool:
        # returns False if contradiction
        old = cand[r][c]
        new = old & ~rem
        if new == old:
            return True
        if new == 0:
            return False
        cand[r][c] = new
        return True

    def assign_mask(r: int, c: int, valmask: int) -> bool:
        # restrict cell to valmask (subset); return False if contradiction
        old = cand[r][c]
        new = old & valmask
        if new == old:
            return True
        if new == 0:
            return False
        cand[r][c] = new
        return True

    # Propagation loop: returns False if contradiction
    def propagate() -> bool:
        q = deque()
        # Enqueue all cells initially to propagate row/col + edge constraints.
        for r in range(N):
            for c in range(N):
                q.append((r, c))

        # Additionally process units and edges in rounds
        # We'll do a mixed approach: cell-driven queue plus periodic unit deductions.
        steps = 0
        while True:
            changed_any = False

            # Cell-driven propagation
            while q:
                r, c = q.popleft()
                steps += 1
                cm = cand[r][c]
                if cm == 0:
                    return False

                # If single, eliminate from row/col peers
                if is_single(cm):
                    vbit = cm
                    # row peers
                    for cc in range(N):
                        if cc == c:
                            continue
                        if cand[r][cc] & vbit:
                            if not remove_mask(r, cc, vbit):
                                return False
                            q.append((r, cc))
                            changed_any = True
                    # col peers
                    for rr in range(N):
                        if rr == r:
                            continue
                        if cand[rr][c] & vbit:
                            if not remove_mask(rr, c, vbit):
                                return False
                            q.append((rr, c))
                            changed_any = True

                # Edge constraints (dot / no-dot) for this cell with its neighbors
                # Iterate neighbors via fixed directions
                for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                    r2, c2 = r + dr, c + dc
                    if not (0 <= r2 < N and 0 <= c2 < N):
                        continue
                    a = (r, c)
                    b = (r2, c2)
                    aa, bb = (a, b) if a < b else (b, a)
                    dotted = (aa, bb) in dot_pairs

                    m1 = cand[r][c]
                    m2 = cand[r2][c2]
                    if dotted:
                        # Neighbor must be consecutive to some value in m1, and vice versa.
                        allow2 = consecutive_union(m1)
                        allow1 = consecutive_union(m2)
                        if allow2 == 0 or allow1 == 0:
                            return False
                        if (m2 & allow2) != m2:
                            if not assign_mask(r2, c2, allow2):
                                return False
                            q.append((r2, c2))
                            changed_any = True
                            m2 = cand[r2][c2]
                        if (m1 & allow1) != m1:
                            if not assign_mask(r, c, allow1):
                                return False
                            q.append((r, c))
                            changed_any = True
                    else:
                        # Neighbor must NOT be consecutive.
                        # If one side is fixed v, remove v±1 from other.
                        # More generally, if one side has candidates S, then other side cannot be in cons_union(S)
                        # BUT careful: "not consecutive" means abs != 1, so remove only those values that are consecutive
                        # to ANY possible value on the other side is too strong.
                        # We'll apply safe arc-consistency:
                        # For each value x in m2, it is allowed if exists y in m1 with |x-y|!=1.
                        # Implement by removing values in m2 that are consecutive to ALL values in m1 (i.e., have no non-consecutive support).
                        # This is GAC for binary constraint.
                        m1_list = None
                        m2_list = None

                        # Prune m2 by support in m1
                        if popcount(m1) <= 6 or popcount(m2) <= 6:
                            m1_list = bits_to_list(m1)
                            m2_list = bits_to_list(m2)
                            bad2 = 0
                            for x in m2_list:
                                # x is unsupported if for all y in m1, abs(x-y)==1
                                supported = False
                                for y in m1_list:
                                    if abs(x - y) != 1:
                                        supported = True
                                        break
                                if not supported:
                                    bad2 |= bit(x)
                            if bad2:
                                if not remove_mask(r2, c2, bad2):
                                    return False
                                q.append((r2, c2))
                                changed_any = True
                                m2 = cand[r2][c2]

                            # Prune m1 by support in m2
                            bad1 = 0
                            for y in m1_list:
                                supported = False
                                for x in m2_list:
                                    if abs(x - y) != 1:
                                        supported = True
                                        break
                                if not supported:
                                    bad1 |= bit(y)
                            if bad1:
                                if not remove_mask(r, c, bad1):
                                    return False
                                q.append((r, c))
                                changed_any = True
                        else:
                            # For larger domains, apply fast safe pruning only when one is single.
                            if is_single(m1):
                                v = single_value(m1)
                                forbid = cons_mask[v]
                                if forbid and (cand[r2][c2] & forbid):
                                    if not remove_mask(r2, c2, forbid):
                                        return False
                                    q.append((r2, c2))
                                    changed_any = True
                            if is_single(m2):
                                v = single_value(m2)
                                forbid = cons_mask[v]
                                if forbid and (cand[r][c] & forbid):
                                    if not remove_mask(r, c, forbid):
                                        return False
                                    q.append((r, c))
                                    changed_any = True

            # Unit deductions: hidden singles + naked subsets (small)
            unit_changed = False

            def process_unit(cells: List[Tuple[int, int]]) -> bool:
                nonlocal unit_changed
                # Hidden singles: for each value, if it appears in only one cell
                locs = [0] * (N + 1)   # bitset of positions not used; store count and last pos
                count = [0] * (N + 1)
                last = [None] * (N + 1)
                for idx, (r, c) in enumerate(cells):
                    m = cand[r][c]
                    mm = m
                    while mm:
                        lsb = mm & -mm
                        v = lsb.bit_length()
                        count[v] += 1
                        last[v] = (r, c)
                        mm -= lsb
                for v in range(1, N + 1):
                    if count[v] == 0:
                        return False  # value cannot be placed in this unit
                    if count[v] == 1:
                        r, c = last[v]
                        if cand[r][c] != bit(v):
                            if not assign_mask(r, c, bit(v)):
                                return False
                            unit_changed = True

                # Naked subsets: consider cells with small domain up to size 4
                # Map mask -> list of cells
                buckets: Dict[int, List[Tuple[int, int]]] = {}
                for (r, c) in cells:
                    m = cand[r][c]
                    k = popcount(m)
                    if 2 <= k <= 4:
                        buckets.setdefault(m, []).append((r, c))
                # If mask appears exactly k times (k=size), eliminate those values from others
                for m, lst in buckets.items():
                    k = popcount(m)
                    if len(lst) == k:
                        for (r, c) in cells:
                            if (r, c) in lst:
                                continue
                            if cand[r][c] & m:
                                if not remove_mask(r, c, m):
                                    return False
                                unit_changed = True
                return True

            for r in range(N):
                if not process_unit(rows[r]):
                    return False
            for c in range(N):
                if not process_unit(cols[c]):
                    return False

            if unit_changed:
                changed_any = True
                # Re-enqueue all cells crudely (still small N typically)
                for r in range(N):
                    for c in range(N):
                        q.append((r, c))

            if not changed_any:
                break

        return True

    def solved() -> bool:
        for r in range(N):
            for c in range(N):
                if not is_single(cand[r][c]):
                    return False
        # Verify Latin
        for r in range(N):
            seen = 0
            for c in range(N):
                seen |= cand[r][c]
            if seen != ALL:
                return False
        for c in range(N):
            seen = 0
            for r in range(N):
                seen |= cand[r][c]
            if seen != ALL:
                return False
        # Verify adjacency constraints
        for (a, b, dotted) in edges:
            r1, c1 = a
            r2, c2 = b
            v1 = single_value(cand[r1][c1])
            v2 = single_value(cand[r2][c2])
            if dotted:
                if abs(v1 - v2) != 1:
                    return False
            else:
                if abs(v1 - v2) == 1:
                    return False
        return True

    # Snapshot/restore for search
    def snapshot():
        return [row[:] for row in cand]

    def restore(snap):
        for r in range(N):
            cand[r] = snap[r][:]

    # Choose next cell: MRV, tie-break by most constrained (degree with dots and peers)
    deg = [[0]*N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            d = 0
            for dr, dc in ((0,1),(0,-1),(1,0),(-1,0)):
                r2, c2 = r+dr, c+dc
                if 0 <= r2 < N and 0 <= c2 < N:
                    d += 1
            deg[r][c] = d

    def select_cell() -> Optional[Tuple[int,int]]:
        best = None
        best_k = 10**9
        best_deg = -1
        for r in range(N):
            for c in range(N):
                m = cand[r][c]
                k = popcount(m)
                if k > 1:
                    if k < best_k or (k == best_k and deg[r][c] > best_deg):
                        best_k = k
                        best_deg = deg[r][c]
                        best = (r, c)
        return best

    # Value ordering: least-constraining value within row/col + adjacency
    def order_values(r: int, c: int) -> List[int]:
        vals = bits_to_list(cand[r][c])
        # Score by how many eliminations it would cause to peers
        peers = set()
        for cc in range(N):
            if cc != c:
                peers.add((r, cc))
        for rr in range(N):
            if rr != r:
                peers.add((rr, c))
        neigh = []
        for dr, dc in ((0,1),(0,-1),(1,0),(-1,0)):
            r2, c2 = r+dr, c+dc
            if 0 <= r2 < N and 0 <= c2 < N:
                neigh.append((r2, c2))
        def score(v: int) -> int:
            vbit = bit(v)
            s = 0
            for (rr, cc) in peers:
                if cand[rr][cc] & vbit:
                    s += 1
            # adjacency impact: dotted neighbors become restricted to v±1, undotted forbid v±1
            for (r2, c2) in neigh:
                a = (r, c); b = (r2, c2)
                aa, bb = (a, b) if a < b else (b, a)
                dotted = (aa, bb) in dot_pairs
                if dotted:
                    allowed = cons_mask[v]
                    s += popcount(cand[r2][c2] & ~allowed)
                else:
                    forbid = cons_mask[v]
                    s += popcount(cand[r2][c2] & forbid)
            return s
        vals.sort(key=score)
        return vals

    def dfs() -> bool:
        if not propagate():
            return False
        if solved():
            return True
        cell = select_cell()
        if cell is None:
            return False
        r, c = cell
        snap = snapshot()
        for v in order_values(r, c):
            restore(snap)
            if not assign_mask(r, c, bit(v)):
                continue
            if dfs():
                return True
        restore(snap)
        return False

    if not dfs():
        return "No Solution"

    out = [[single_value(cand[r][c]) for c in range(N)] for r in range(N)]
    return str(out)

