from __future__ import annotations

# Generalized solver for "Consecutive Dots Latin Square" (N x N):
# - Values 1..N
# - Each row/col is a permutation (Latin)
# - A dot between orthogonally adjacent cells <=> values are consecutive (|a-b|=1)
# - No dot <=> values are NOT consecutive (|a-b|!=1)
#
# Design goals:
# - Human-like propagation:
#   * Row/col singles and hidden singles
#   * Dot-edge filtering: enforce consecutive/nonconsecutive adjacency
#   * Pair-consistency (AC-3 style) on adjacency constraints (very strong here)
#   * Forward-checking with MRV + degree heuristic
#   * Early contradictions via Hall-like checks on rows/cols (simple subset count)
#
# No external CSP libraries.

from collections import deque
from typing import List, Tuple, Dict, Set, Optional

ALLMASK_CACHE: Dict[int, int] = {}


def bit(n: int) -> int:
    return 1 << (n - 1)


def mask_all(N: int) -> int:
    m = ALLMASK_CACHE.get(N)
    if m is None:
        m = (1 << N) - 1
        ALLMASK_CACHE[N] = m
    return m


def popcount(x: int) -> int:
    return x.bit_count()


def lsb_index(x: int) -> int:
    # assumes x != 0, returns 0-based index of least significant set bit
    return (x & -x).bit_length() - 1


def iter_vals(mask: int) -> List[int]:
    # small N; list is fine
    out = []
    while mask:
        b = mask & -mask
        out.append(b.bit_length())
        mask ^= b
    return out


def is_single(mask: int) -> bool:
    return mask != 0 and (mask & (mask - 1)) == 0


def single_value(mask: int) -> int:
    return mask.bit_length()


def consecutive_allowed_mask(v: int, N: int) -> int:
    m = 0
    if v > 1:
        m |= bit(v - 1)
    if v < N:
        m |= bit(v + 1)
    return m


def build_adjacency(N: int, dots: List[List[float]]) -> Tuple[List[List[int]], List[List[bool]]]:
    # neighbors: list of neighbor indices for each cell
    # isdot[u][k] indicates dot between u and neighbors[u][k]
    idx = lambda r, c: r * N + c
    neighbors: List[List[int]] = [[] for _ in range(N * N)]
    isdot: List[List[bool]] = [[] for _ in range(N * N)]

    dotset = set((float(r), float(c)) for r, c in dots)

    def has_dot_between(r1, c1, r2, c2) -> bool:
        if r1 == r2 and abs(c1 - c2) == 1:
            mid = (float(r1), float(min(c1, c2)) + 0.5)
            return mid in dotset
        if c1 == c2 and abs(r1 - r2) == 1:
            mid = (float(min(r1, r2)) + 0.5, float(c1))
            return mid in dotset
        raise ValueError("Non-adjacent")
    for r in range(N):
        for c in range(N):
            u = idx(r, c)
            for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < N and 0 <= cc < N:
                    v = idx(rr, cc)
                    # only add each undirected edge once? For arc consistency, need directed arcs.
                    # We'll add all directed neighbor entries.
                    neighbors[u].append(v)
                    isdot[u].append(has_dot_between(r, c, rr, cc))
    return neighbors, isdot


def row_of(i: int, N: int) -> int:
    return i // N


def col_of(i: int, N: int) -> int:
    return i % N


def hall_prune_unit(indices: List[int], doms: List[int], N: int) -> Tuple[bool, List[Tuple[int, int]]]:
    # Simple Hall-style pruning for small N (<=9 typical): check subsets via value masks frequency.
    # We avoid full subset enumeration (2^N) by using a bounded technique:
    # - If k values appear only within exactly k cells (i.e., union size equals number of cells), prune others.
    # For N=5 this is cheap; still keep generic.
    # Returns (ok, reductions list of (cell, newmask)).
    # We'll implement: for each possible value-set mask M, compute cells whose domains are subset of M.
    # If count == popcount(M), then those values are locked to those cells => remove M from other cells.
    # Enumerating all masks up to 2^N is acceptable for N<=7; but for bigger, skip.
    if N > 8:
        return True, []
    allm = mask_all(N)
    # Precompute subset-cells counts
    cells_by_subset: Dict[int, int] = {}
    for i in indices:
        d = doms[i]
        cells_by_subset[d] = cells_by_subset.get(d, 0) + 1
    # To get counts for "domains subset of M", we can sum over subsets: zeta transform.
    # For N<=8, do zeta over array size 2^N.
    size = 1 << N
    cnt = [0] * size
    for m, k in cells_by_subset.items():
        cnt[m] += k
    # zeta transform: cnt[M] = sum_{S subset M} cnt[S]
    for b in range(N):
        step = 1 << b
        for m in range(size):
            if m & step:
                cnt[m] += cnt[m ^ step]
    reductions: List[Tuple[int, int]] = []
    for M in range(1, size):
        k = popcount(M)
        if k <= 1:
            continue
        if cnt[M] == k:
            # values in M are confined to exactly k cells whose domains subset M
            # remove M from other cells in unit
            for i in indices:
                if doms[i] & ~M:  # not subset
                    newm = doms[i] & ~M
                    if newm != doms[i]:
                        if newm == 0:
                            return False, []
                        reductions.append((i, newm))
    # Also detect impossibility: if union of all domains < number of cells
    union = 0
    for i in indices:
        union |= doms[i]
    if popcount(union) < len(indices):
        return False, []
    return True, reductions


def solve(observation) -> str:
    data = observation["data"]
    N = len(data)
    allm = mask_all(N)
    neighbors, isdot = build_adjacency(N, observation.get("adjacent", []))

    # Domains as bitmasks
    doms = [allm] * (N * N)

    # Apply givens
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                doms[r * N + c] = bit(int(v))

    # Unit indices
    rows = [[r * N + c for c in range(N)] for r in range(N)]
    cols = [[r * N + c for r in range(N)] for c in range(N)]

    # Precompute adjacency edge pairs for arc processing
    arcs = []
    for u in range(N * N):
        for k, v in enumerate(neighbors[u]):
            arcs.append((u, v, isdot[u][k]))

    def unit_propagate_queue(queue: deque[int]) -> bool:
        # queue contains cells that became singleton; propagate row/col exclusions and adjacency constraints
        while queue:
            u = queue.popleft()
            if not is_single(doms[u]):
                continue
            vu = single_value(doms[u])
            ru, cu = row_of(u, N), col_of(u, N)

            # Row exclusions
            for x in rows[ru]:
                if x != u and (doms[x] & bit(vu)):
                    nm = doms[x] & ~bit(vu)
                    if nm == 0:
                        return False
                    if nm != doms[x]:
                        doms[x] = nm
                        if is_single(nm):
                            queue.append(x)

            # Col exclusions
            for x in cols[cu]:
                if x != u and (doms[x] & bit(vu)):
                    nm = doms[x] & ~bit(vu)
                    if nm == 0:
                        return False
                    if nm != doms[x]:
                        doms[x] = nm
                        if is_single(nm):
                            queue.append(x)

            # Adjacency constraints from u to neighbors
            for k, v in enumerate(neighbors[u]):
                if isdot[u][k]:
                    allowed = consecutive_allowed_mask(vu, N)
                    nm = doms[v] & allowed
                else:
                    # forbid consecutive values
                    forbid = consecutive_allowed_mask(vu, N)
                    nm = doms[v] & ~forbid
                if nm == 0:
                    return False
                if nm != doms[v]:
                    doms[v] = nm
                    if is_single(nm):
                        queue.append(v)
        return True

    def ac3() -> bool:
        # Arc consistency on adjacency constraints only (strong). Latin constraints handled by other propagation.
        q = deque(arcs)
        while q:
            u, v, dot = q.popleft()
            du, dv = doms[u], doms[v]
            # revise u wrt v
            newdu = du & support_mask(du, dv, dot, N)
            if newdu == 0:
                return False
            if newdu != du:
                doms[u] = newdu
                # if u reduced, re-enqueue arcs affecting u
                for kk, w in enumerate(neighbors[u]):
                    if w != v:
                        q.append((w, u, isdot[w][neighbors[w].index(u)] if u in neighbors[w] else False))
                # also unit propagation if singleton
        return True

    def support_mask(du: int, dv: int, dot: bool, N: int) -> int:
        # For each value a in du, check exists b in dv satisfying adjacency dot/non-dot.
        res = 0
        # iterate a via bits
        tmp = du
        while tmp:
            b = tmp & -tmp
            a = b.bit_length()
            if dot:
                allowed = consecutive_allowed_mask(a, N)
                if dv & allowed:
                    res |= b
            else:
                forbid = consecutive_allowed_mask(a, N)
                if dv & ~forbid:
                    res |= b
            tmp ^= b
        return res

    def hidden_singles() -> bool:
        # For each unit, if a value appears in only one domain -> assign
        q = deque()
        for unit in rows + cols:
            pos = [0] * (N + 1)
            last = [-1] * (N + 1)
            for i in unit:
                m = doms[i]
                tmp = m
                while tmp:
                    b = tmp & -tmp
                    v = b.bit_length()
                    pos[v] += 1
                    last[v] = i
                    tmp ^= b
            for v in range(1, N + 1):
                if pos[v] == 0:
                    return False
                if pos[v] == 1:
                    i = last[v]
                    if doms[i] != bit(v):
                        doms[i] = bit(v)
                        q.append(i)
        return unit_propagate_queue(q)

    def hall_prune_all() -> bool:
        reductions: List[Tuple[int, int]] = []
        for unit in rows + cols:
            ok, reds = hall_prune_unit(unit, doms, N)
            if not ok:
                return False
            reductions.extend(reds)
        if reductions:
            q = deque()
            for i, nm in reductions:
                if nm != doms[i]:
                    doms[i] = nm
                    if is_single(nm):
                        q.append(i)
            if not unit_propagate_queue(q):
                return False
        return True

    def full_propagate() -> bool:
        # Initialize queue with all singles
        q = deque([i for i, m in enumerate(doms) if is_single(m)])
        if not unit_propagate_queue(q):
            return False
        # Loop stronger propagations until fixpoint
        while True:
            snapshot = doms[:]
            if not hidden_singles():
                return False
            if not hall_prune_all():
                return False
            # Lightweight adjacency revise using directed arcs around recently changed cells would be better;
            # for N small, run a bounded arc pass using local checks by scanning arcs once.
            if not adjacency_local_pass():
                return False
            if doms == snapshot:
                break
        return True

    def adjacency_local_pass() -> bool:
        # One pass of pairwise pruning on adjacency edges (both directions)
        q = deque()
        for u, v, dot in arcs:
            du, dv = doms[u], doms[v]
            ndu = du & support_mask(du, dv, dot, N)
            if ndu == 0:
                return False
            if ndu != du:
                doms[u] = ndu
                if is_single(ndu):
                    q.append(u)
        return unit_propagate_queue(q)

    def is_solved() -> bool:
        return all(is_single(m) for m in doms)

    def select_unassigned() -> int:
        # MRV with degree (more adjacency constraints) tie-break
        best = -1
        best_size = 10**9
        best_deg = -1
        for i, m in enumerate(doms):
            if not is_single(m):
                s = popcount(m)
                if s < best_size:
                    best = i
                    best_size = s
                    best_deg = len(neighbors[i])
                elif s == best_size:
                    deg = len(neighbors[i])
                    if deg > best_deg:
                        best = i
                        best_deg = deg
        return best

    def dfs() -> bool:
        if is_solved():
            return True
        i = select_unassigned()
        if i < 0:
            return False
        m = doms[i]
        # Value ordering: prefer values that satisfy dotted neighbors more easily (least constraining)
        candidates = iter_vals(m)
        scored = []
        for v in candidates:
            score = 0
            for k, nb in enumerate(neighbors[i]):
                if isdot[i][k]:
                    score += popcount(doms[nb] & consecutive_allowed_mask(v, N))
                else:
                    score += popcount(doms[nb] & ~consecutive_allowed_mask(v, N))
            scored.append((score, v))
        scored.sort(reverse=True)

        saved = doms[:]
        for _, v in scored:
            doms[i] = bit(v)
            if full_propagate():
                if dfs():
                    return True
            doms[:] = saved
        return False

    if not full_propagate():
        return "No Solution"
    if not dfs():
        return "No Solution"

    grid = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            grid[r][c] = single_value(doms[r * N + c])
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

