# Solver for "Consecutive Dots Latin Square" (a.k.a. Kropki-style consecutive constraint only)
# Rules:
# - N x N Latin square with symbols 1..N
# - Dots indicate orthogonally adjacent cells are consecutive (abs diff == 1)
# - Absence of dot indicates NOT consecutive (abs diff != 1)
#
# Design goals:
# - Strong human-like propagation:
#   * Row/col singles, hidden singles
#   * Consecutive and non-consecutive edge filtering with iterative refinement
#   * Pairwise arc-consistency on dotted/non-dotted edges (AC-3-like but specialized)
#   * MRV + degree heuristic branching with forward checking
#   * Cheap implied constraints: if cell is 1 then all non-dotted neighbors cannot be 2; etc. (covered by edge filtering)
#
# No external solvers.

from collections import deque

def solve(observation):
    data = observation["data"]
    adj = observation["adjacent"]
    N = len(data)

    # Build edge constraints for all orthogonally adjacent pairs
    # Represent each edge once as ((r1,c1),(r2,c2)) with r1,c1 < r2,c2 lexicographically
    dotted = set()
    for y, x in adj:
        # y=row coordinate, x=col coordinate, can be .5 for midpoints
        if abs(y - int(y)) < 1e-9 and abs(x - (int(x) + 0.5)) < 1e-9:
            r = int(y); c = int(x - 0.5)
            a = (r, c); b = (r, c + 1)
        elif abs(x - int(x)) < 1e-9 and abs(y - (int(y) + 0.5)) < 1e-9:
            r = int(y - 0.5); c = int(x)
            a = (r, c); b = (r + 1, c)
        else:
            return "No Solution"
        if not (0 <= a[0] < N and 0 <= a[1] < N and 0 <= b[0] < N and 0 <= b[1] < N):
            return "No Solution"
        if a > b: a, b = b, a
        dotted.add((a, b))

    # Enumerate all orthogonal edges and mark dotted or non-dotted
    edges = []
    neighbors = [[] for _ in range(N * N)]
    def idx(rc): return rc[0] * N + rc[1]
    def rc(i): return divmod(i, N)

    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                a = (r, c); b = (r, c + 1)
                e = (a, b) if a < b else (b, a)
                edges.append((idx(e[0]), idx(e[1]), e in dotted))
            if r + 1 < N:
                a = (r, c); b = (r + 1, c)
                e = (a, b) if a < b else (b, a)
                edges.append((idx(e[0]), idx(e[1]), e in dotted))

    for u, v, is_dot in edges:
        neighbors[u].append((v, is_dot))
        neighbors[v].append((u, is_dot))

    ALL = (1 << N) - 1  # bitmask for 1..N (bit k-1 represents value k)

    # Precompute consecutive compatibility bitmasks:
    # consec_mask[val] = bitmask of values consecutive to val (val-1 and val+1 within 1..N)
    consec_mask = [0] * (N + 1)
    for v in range(1, N + 1):
        m = 0
        if v - 1 >= 1: m |= 1 << (v - 2)
        if v + 1 <= N: m |= 1 << v
        consec_mask[v] = m

    # Nonconsecutive compatibility for a given value is ALL ^ consec_mask[v] ^ bit(v)?? Wait:
    # Constraint is abs diff != 1, so neighbor may equal? In Latin rules, orthogonal neighbors can equal (unless same row/col),
    # but they are different if same row/col anyway. For edge constraint, we only forbid consecutive differences.
    # So compatibility is ALL without consecutive values; value itself allowed by edge constraint.
    nonconsec_mask = [0] * (N + 1)
    for v in range(1, N + 1):
        nonconsec_mask[v] = ALL & ~consec_mask[v]

    # Domains for each cell
    dom = [ALL] * (N * N)

    # Apply givens
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                val = data[r][c]
                if not (1 <= val <= N):
                    return "No Solution"
                dom[idx((r, c))] = 1 << (val - 1)

    # Row/col used masks (for fast filtering)
    # We'll maintain them on the fly during propagation from singleton domains.
    row_used = [0] * N
    col_used = [0] * N

    def popcount(x):
        return x.bit_count()

    def lsb_index(x):
        # x != 0, return index of least significant set bit
        return (x & -x).bit_length() - 1

    def iter_bits(x):
        while x:
            b = x & -x
            yield b
            x -= b

    # Initialize used from givens; but must ensure Latin constraints not violated
    for i in range(N * N):
        if popcount(dom[i]) == 1:
            r, c = rc(i)
            bit = dom[i]
            if row_used[r] & bit: return "No Solution"
            if col_used[c] & bit: return "No Solution"
            row_used[r] |= bit
            col_used[c] |= bit

    # Constraint propagation engine
    # We'll push variables whose domain changed into a queue.
    inq = [False] * (N * N)
    q = deque()

    def enqueue(i):
        if not inq[i]:
            inq[i] = True
            q.append(i)

    for i in range(N * N):
        enqueue(i)

    # Helper: remove used values from a cell domain (Latin constraints)
    def apply_latin_filter(i):
        r, c = rc(i)
        before = dom[i]
        dom[i] &= ~(row_used[r] | col_used[c])
        return dom[i] != before

    # Edge filtering: enforce arc-consistency for one directed arc i -> j
    def revise_arc(i, j, is_dot):
        # Remove values in dom[i] that have no support in dom[j] under edge constraint
        di = dom[i]; dj = dom[j]
        if di == 0 or dj == 0:
            return False, True
        changed = False
        # Compute supported set for i given dom[j]
        # For each value v in i, need some w in j such that:
        # - if dot: |v-w|==1
        # - else: |v-w|!=1
        supported = 0
        # Iterate values in di
        for b in iter_bits(di):
            v = b.bit_length()  # value v (since bit at v-1)
            if is_dot:
                # neighbors must be consecutive to v
                if dj & consec_mask[v]:
                    supported |= b
            else:
                # neighbors must NOT be consecutive to v
                if dj & nonconsec_mask[v]:
                    supported |= b
        if supported != di:
            dom[i] = supported
            changed = True
        return changed, dom[i] == 0

    # When a cell becomes singleton, update row/col used and enqueue peers
    def assign_if_singleton(i):
        if popcount(dom[i]) != 1:
            return False, False
        r, c = rc(i)
        bit = dom[i]
        # If already accounted for, nothing
        if (row_used[r] & bit) and (col_used[c] & bit):
            return False, False
        # Check conflicts
        if row_used[r] & bit and not (col_used[c] & bit):
            # row already has this number elsewhere
            return False, True
        if col_used[c] & bit and not (row_used[r] & bit):
            return False, True
        if row_used[r] & bit or col_used[c] & bit:
            return False, True
        row_used[r] |= bit
        col_used[c] |= bit
        # enqueue all cells in row/col and all neighbors for edge constraints
        for cc in range(N):
            if cc != c: enqueue(idx((r, cc)))
        for rr in range(N):
            if rr != r: enqueue(idx((rr, c)))
        for nb, _ in neighbors[i]:
            enqueue(nb)
        return True, False

    # Hidden singles for a row/col
    def hidden_singles_unit(cells):
        # For each value, if it appears in exactly one domain, assign it there
        # Returns (changed, contradiction)
        changed = False
        # count occurrences via bitwise accumulation
        # We'll compute for each value a bitmask of candidate positions using integer as bitset over positions (<=N fits in Python int)
        posmask = [0] * N
        for pi, ci in enumerate(cells):
            d = dom[ci]
            if d == 0:
                return changed, True
            for b in iter_bits(d):
                v = b.bit_length() - 1  # 0-based value index
                posmask[v] |= (1 << pi)
        for v0 in range(N):
            pm = posmask[v0]
            if pm and (pm & (pm - 1)) == 0:
                pi = pm.bit_length() - 1
                ci = cells[pi]
                bit = 1 << v0
                if dom[ci] != bit:
                    dom[ci] = bit
                    enqueue(ci)
                    changed = True
        return changed, False

    def propagate():
        # AC-3-like propagation with Latin filtering and hidden singles loops
        while q:
            i = q.popleft()
            inq[i] = False

            # Latin filter
            if apply_latin_filter(i):
                if dom[i] == 0: return False
                # domain changed affects peers and neighbors
                r, c = rc(i)
                for cc in range(N):
                    if cc != c: enqueue(idx((r, cc)))
                for rr in range(N):
                    if rr != r: enqueue(idx((rr, c)))
                for nb, _ in neighbors[i]:
                    enqueue(nb)

            # Edge constraints revise this cell against neighbors
            for nb, is_dot in neighbors[i]:
                ch, bad = revise_arc(i, nb, is_dot)
                if bad: return False
                if ch:
                    enqueue(i)
                    # If i changed, neighbors and unit checks matter
                    r, c = rc(i)
                    for cc in range(N):
                        if cc != c: enqueue(idx((r, cc)))
                    for rr in range(N):
                        if rr != r: enqueue(idx((rr, c)))
                    for nb2, _ in neighbors[i]:
                        enqueue(nb2)
                    break  # reprocess i later for consistency

            # If singleton, record it and push effects
            _, bad = assign_if_singleton(i)
            if bad: return False

            # Opportunistically run hidden singles for impacted row/col when i is in queue processing.
            r, c = rc(i)
            row_cells = [idx((r, cc)) for cc in range(N)]
            col_cells = [idx((rr, c)) for rr in range(N)]
            ch, bad = hidden_singles_unit(row_cells)
            if bad: return False
            if ch:
                for ci in row_cells: enqueue(ci)
            ch, bad = hidden_singles_unit(col_cells)
            if bad: return False
            if ch:
                for ci in col_cells: enqueue(ci)

        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    def is_solved():
        for i in range(N * N):
            if popcount(dom[i]) != 1:
                return False
        return True

    # Choose next variable: MRV, tie-break by degree (more constraints)
    def select_var():
        best = -1
        best_sz = 10**9
        best_deg = -1
        for i in range(N * N):
            sz = popcount(dom[i])
            if sz > 1:
                if sz < best_sz:
                    best_sz = sz
                    best = i
                    best_deg = len(neighbors[i])
                elif sz == best_sz:
                    deg = len(neighbors[i])
                    if deg > best_deg:
                        best = i
                        best_deg = deg
        return best

    # Snapshot/restore for backtracking (efficient enough for N<=9 typical; here N=5)
    def snapshot():
        return (dom[:], row_used[:], col_used[:], list(q), inq[:])

    def restore(snap):
        nonlocal dom, row_used, col_used, q, inq
        dom, row_used, col_used, q_list, inq = snap
        q = deque(q_list)

    # Value ordering: try values that satisfy more dotted neighbors first
    def order_values(i):
        d = dom[i]
        vals = []
        for b in iter_bits(d):
            v = b.bit_length()
            score = 0
            for nb, is_dot in neighbors[i]:
                dj = dom[nb]
                if is_dot:
                    score += popcount(dj & consec_mask[v])
                else:
                    score += popcount(dj & nonconsec_mask[v])
            vals.append((score, b))
        vals.sort(reverse=True)
        return [b for _, b in vals]

    def dfs():
        if is_solved():
            return True
        i = select_var()
        if i < 0:
            return False

        # Try each candidate with propagation
        for bit in order_values(i):
            snap = snapshot()
            dom[i] = bit
            enqueue(i)
            if propagate() and dfs():
                return True
            restore(snap)
        return False

    if not dfs():
        return "No Solution"

    # Build solved grid
    sol = [[0] * N for _ in range(N)]
    for i in range(N * N):
        r, c = rc(i)
        sol[r][c] = lsb_index(dom[i]) + 1

    return str(sol)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 1, None, None, None, None, None, None, None], [None, None, None, 5, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, None, 1, None, None, None, None, None], [None, None, None, None, None, 9, None, None, None, 5], [6, None, None, 3, None, None, None, 8, None, None], [None, None, None, None, None, None, None, None, 3, None], [None, None, None, None, None, None, None, None, None, None], [1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, 1, None, None]]}
from collections import deque, defaultdict
from itertools import product

# Nurikabe solver (white islands with given sizes, black sea connected, no 2x2 black)
# Grid cells take states: -1 unknown, 0 white, 1 black
# This solver emphasizes aggressive human-like deduction + constraint propagation,
# with limited backtracking guided by MRV and connectivity checks.

DIRS = ((1,0),(-1,0),(0,1),(0,-1))

def solve(observation):
    data = observation["data"]
    R, C = len(data), len(data[0])
    N = R * C

    def idx(r,c): return r*C + c
    def rc(i): return divmod(i, C)
    def inb(r,c): return 0 <= r < R and 0 <= c < C

    numbers = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                numbers[idx(r,c)] = int(data[r][c])

    # Precompute neighbors
    neigh = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            i = idx(r,c)
            for dr,dc in DIRS:
                rr,cc = r+dr,c+dc
                if inb(rr,cc):
                    neigh[i].append(idx(rr,cc))

    # State arrays
    state0 = [-1]*N
    for i in numbers:
        state0[i] = 0  # numbered cells are white

    # Disallow immediate adjacency between different numbered islands (they cannot share same island, and each island has exactly one number)
    # So any cell adjacent to two different numbered cells forces black between? Actually numbered cells can't be orthogonally adjacent at all,
    # because that would create a white component with 2 numbers. Thus, if two numbered cells are adjacent, no solution.
    for i,a in numbers.items():
        for j in neigh[i]:
            if j in numbers and j != i:
                return "No Solution"

    # Also, any cell orthogonally adjacent to two different numbered cells cannot be white if that would connect them through itself?
    # A single cell between them not possible orthogonally (only direct adjacency). Diagonal doesn't matter.

    # Structures for island management
    num_list = list(numbers.keys())
    num_index = {n:k for k,n in enumerate(num_list)}
    K = len(num_list)

    # For each numbered island, maintain a current set of forced white cells (initially just the number)
    # and possibility frontier.
    # We'll avoid explicit set copies in recursion by using stack-based undo.

    # For faster component checks, we maintain union-find for whites? Hard with backtracking.
    # We'll instead do BFS for local checks selectively, with pruning.

    # 2x2 squares indices
    squares = []
    for r in range(R-1):
        for c in range(C-1):
            squares.append((idx(r,c), idx(r,c+1), idx(r+1,c), idx(r+1,c+1)))

    # Utility: BFS on given predicate
    def bfs_from(starts, allowed_pred):
        q = deque(starts)
        seen = set(starts)
        while q:
            u = q.popleft()
            for v in neigh[u]:
                if v not in seen and allowed_pred(v):
                    seen.add(v)
                    q.append(v)
        return seen

    # Determine for each cell which numbered island it currently belongs to (white connectivity),
    # but we do it lazily by assigning via BFS from each number within current white cells.
    # Also detect white components with multiple numbers.
    def analyze_white_components(state):
        owner = [-1]*N
        # mark black as -2, unknown stays -1 unless reached
        for i in range(N):
            if state[i] == 1:
                owner[i] = -2
        comps = []  # list of (cells, numbers_in_comp)
        seen = [False]*N
        for i in range(N):
            if state[i] == 0 and not seen[i]:
                # BFS component over white
                q = deque([i])
                seen[i] = True
                comp = [i]
                nums = []
                if i in numbers: nums.append(i)
                while q:
                    u = q.popleft()
                    for v in neigh[u]:
                        if state[v] == 0 and not seen[v]:
                            seen[v] = True
                            q.append(v)
                            comp.append(v)
                            if v in numbers: nums.append(v)
                comps.append((comp, nums))
                for u in comp:
                    # temp owner mark (component id)
                    owner[u] = len(comps)-1
        return comps, owner

    # Compute shortest expansion possibilities for each island (upper bound reachability through non-black cells)
    # Returns for each island: set of reachable cells without passing black, and distance layer if needed.
    def reachable_from_number(state, num_cell, limit=None):
        # Through cells that are not black (white or unknown)
        q = deque([num_cell])
        dist = {num_cell: 0}
        while q:
            u = q.popleft()
            du = dist[u]
            if limit is not None and du >= limit:
                continue
            for v in neigh[u]:
                if state[v] != 1 and v not in dist:
                    dist[v] = du+1
                    q.append(v)
        return dist  # includes num_cell

    # Check black connectivity feasibility with unknowns:
    # - All confirmed black must be connectable through cells that are black or unknown.
    def black_connectivity_possible(state):
        blacks = [i for i in range(N) if state[i] == 1]
        if not blacks:
            return True
        start = blacks[0]
        seen = bfs_from([start], lambda x: state[x] != 0)  # can traverse black+unknown
        for b in blacks:
            if b not in seen:
                return False
        return True

    # Check if confirmed black is already disconnected (must be connected in final), and no 2x2 all black.
    def basic_black_checks(state):
        # no 2x2 all black
        for a,b,c,d in squares:
            if state[a] == state[b] == state[c] == state[d] == 1:
                return False
        return black_connectivity_possible(state)

    # Island size constraints / deductions
    def island_constraints_propagate(state, changes):
        # changes: stack of (cell, oldstate)
        # returns False if contradiction, True otherwise, while applying deterministic deductions
        # We iteratively apply:
        # 1) White components must have <=1 number; if 0 numbers => contradiction (white must belong to some island).
        # 2) For each numbered component: size <= target; remaining required cells must be reachable.
        # 3) Any cell that cannot reach any number through non-black must be black.
        # 4) If a numbered component reaches target size, its boundary unknown cells must be black (to prevent growth).
        # 5) If an unknown cell is adjacent to a white cell and all possible owner islands would overflow if it stayed non-black? we do simple checks.
        # 6) Prevent connecting two numbered islands via forcing black at articulation? we ensure unknown cell adjacent to white comps with different numbers -> must be black if setting white would join comps with 2 nums.

        # Precompute number reachability regions occasionally
        # We'll run a fixpoint loop.
        while True:
            progressed = False

            # Analyze white components and detect violations
            comps, comp_id = analyze_white_components(state)
            comp_num = [None]*len(comps)  # the number cell in this comp, or None
            comp_size = [0]*len(comps)
            for cid,(cells, nums) in enumerate(comps):
                comp_size[cid] = len(cells)
                if len(nums) == 0:
                    # white region with no number -> invalid (every white island must have exactly one number)
                    return False
                if len(nums) > 1:
                    return False
                comp_num[cid] = nums[0]

            # For each numbered component, size cannot exceed target
            for cid in range(len(comps)):
                ncell = comp_num[cid]
                target = numbers[ncell]
                if comp_size[cid] > target:
                    return False

            # Rule: if a component reached its target size, all its adjacent unknowns must be black
            for cid,(cells, nums) in enumerate(comps):
                ncell = nums[0]
                target = numbers[ncell]
                if len(cells) == target:
                    for u in cells:
                        for v in neigh[u]:
                            if state[v] == -1:
                                # v cannot be white (would enlarge island), must be black
                                old = state[v]
                                state[v] = 1
                                changes.append((v, old))
                                progressed = True

            # Rule: prevent immediate connection between two numbered components by making bridging unknown black
            # If an unknown cell has two (or more) neighboring white components with different numbers, it cannot become white.
            for i in range(N):
                if state[i] == -1:
                    adj_nums = set()
                    for v in neigh[i]:
                        if state[v] == 0:
                            cid = comp_id[v]
                            if cid >= 0:
                                adj_nums.add(comp_num[cid])
                    if len(adj_nums) >= 2:
                        old = state[i]
                        state[i] = 1
                        changes.append((i, old))
                        progressed = True

            # Feasibility: for each numbered component, must have enough reachable cells (through non-black) to reach target
            # We compute reachability distances from the number through non-black cells.
            # But we must restrict: cannot pass through white cells owned by another number (would violate uniqueness).
            # We'll approximate by forbidding entering white cells in other numbered components.
            # Build a map from white cell -> its number owner
            white_owner_num = [-1]*N
            for cid,(cells,nums) in enumerate(comps):
                ncell = nums[0]
                for u in cells:
                    white_owner_num[u] = ncell

            for cid,(cells, nums) in enumerate(comps):
                ncell = nums[0]
                target = numbers[ncell]
                have = len(cells)
                need = target - have
                if need == 0:
                    continue

                # BFS over non-black, but disallow stepping into white owned by other island
                q = deque([ncell])
                seen = set([ncell])
                while q:
                    u = q.popleft()
                    for v in neigh[u]:
                        if v in seen:
                            continue
                        if state[v] == 1:
                            continue
                        if state[v] == 0 and white_owner_num[v] != ncell:
                            continue
                        seen.add(v)
                        q.append(v)
                # available cells that could be part of this island are those in seen that are not black and not fixed white of others
                # But also if state[v]==0 and owned by this island already included; okay.
                if len(seen) < target:
                    return False

                # Additionally: if exactly target cells are reachable, then all reachable non-owned unknowns must be white for this island.
                if len(seen) == target:
                    for v in seen:
                        if state[v] == -1:
                            old = state[v]
                            state[v] = 0
                            changes.append((v, old))
                            progressed = True

            # Rule: Any unknown cell that cannot reach any number via non-black cells without passing through other fixed white components
            # must be black, because it can't belong to any island.
            # Compute multi-source reachability over non-black while tracking if path crosses fixed white owned by some number.
            # We'll do per-cell check cheaply by BFS from each number? Too heavy.
            # Instead, do BFS from all numbered cells simultaneously allowing traversal through unknown and through their own white,
            # but not through white belonging to another number. We'll treat white as passable only if it is in the same component as its number.
            # We already have ownership mapping for whites: white_owner_num.
            sources = list(numbers.keys())
            # multi-source BFS where state is (cell, owner_number); but too big.
            # Alternative: for each cell, we only need existence of some owner path. We'll do BFS from each comp outward
            # but stop after covering all unknowns; still potentially heavy but acceptable at 10x10.
            can_belong = [False]*N
            for cid,(cells,nums) in enumerate(comps):
                ncell = nums[0]
                q = deque([ncell])
                seen = set([ncell])
                while q:
                    u = q.popleft()
                    for v in neigh[u]:
                        if v in seen or state[v] == 1:
                            continue
                        if state[v] == 0 and white_owner_num[v] != ncell:
                            continue
                        seen.add(v)
                        q.append(v)
                for v in seen:
                    can_belong[v] = True
            for i in range(N):
                if state[i] == -1 and not can_belong[i]:
                    old = state[i]
                    state[i] = 1
                    changes.append((i, old))
                    progressed = True

            # Basic black constraints after deductions
            if not basic_black_checks(state):
                return False

            if not progressed:
                return True

    # Forced initial deductions: if number is 1, all orthogonal neighbors must be black (island size 1)
    def apply_initial_forces(state, changes):
        for ncell, target in numbers.items():
            if target == 1:
                for v in neigh[ncell]:
                    if state[v] == -1:
                        old = state[v]
                        state[v] = 1
                        changes.append((v, old))

    # Choose branching cell with MRV-style heuristic:
    # - unknown cell adjacent to white components or affecting 2x2, etc.
    def pick_cell(state):
        best = None
        best_score = -10**9
        for i in range(N):
            if state[i] != -1:
                continue
            r,c = rc(i)
            score = 0
            # near numbers/whites
            for v in neigh[i]:
                if state[v] == 0:
                    score += 5
                elif state[v] == 1:
                    score += 2
            # part of many 2x2 squares
            if r < R-1 and c < C-1: score += 1
            if r > 0 and c < C-1: score += 1
            if r < R-1 and c > 0: score += 1
            if r > 0 and c > 0: score += 1
            # prefer cells that if black could create 2x2 (constraint tight)
            best_local = score
            if best is None or best_local > best_score:
                best = i
                best_score = best_local
        return best

    def is_solved(state):
        # all assigned
        if any(s == -1 for s in state):
            return False
        # numbered cells are white
        for i in numbers:
            if state[i] != 0:
                return False
        # check 2x2 all black
        for a,b,c,d in squares:
            if state[a] == state[b] == state[c] == state[d] == 1:
                return False
        # black connected
        if not black_connectivity_possible(state):
            return False
        # white components exactly correspond to numbered islands with correct sizes
        comps, _ = analyze_white_components(state)
        seen_nums = set()
        for cells, nums in comps:
            if len(nums) != 1:
                return False
            ncell = nums[0]
            if ncell in seen_nums:
                return False
            seen_nums.add(ncell)
            if len(cells) != numbers[ncell]:
                return False
        return seen_nums == set(numbers.keys())

    # Backtracking with propagation and strong pruning
    def dfs(state):
        changes = []
        if not island_constraints_propagate(state, changes):
            # undo
            for cell, old in reversed(changes):
                state[cell] = old
            return None

        if is_solved(state):
            sol = state[:]
            for cell, old in reversed(changes):
                state[cell] = old
            return sol

        cell = pick_cell(state)
        if cell is None:
            for cell2, old in reversed(changes):
                state[cell2] = old
            return None

        # Try white then black based on local context:
        # If adjacent to two different numbered components, it would have been forced black already.
        # If adjacent to white, often white first helps fill islands.
        order = [0, 1]
        adj_white = any(state[v] == 0 for v in neigh[cell])
        if not adj_white:
            order = [1, 0]  # try black first if isolated

        for val in order:
            local_changes = []
            old = state[cell]
            state[cell] = val
            local_changes.append((cell, old))

            # Quick checks:
            ok = True
            if val == 1:
                # immediate 2x2 violation check around cell
                r,c = rc(cell)
                for dr in (-1,0):
                    for dc in (-1,0):
                        rr,cc = r+dr,c+dc
                        if 0 <= rr < R-1 and 0 <= cc < C-1:
                            a = idx(rr,cc); b = idx(rr,cc+1); c2 = idx(rr+1,cc); d = idx(rr+1,cc+1)
                            if state[a]==state[b]==state[c2]==state[d]==1:
                                ok = False
                                break
                    if not ok:
                        break
                if ok and not black_connectivity_possible(state):
                    ok = False
            else:
                # if making white would connect two different numbered comps -> invalid; caught in propagation but can quick check
                comps, comp_id = analyze_white_components(state)
                comp_num = [nums[0] for _,nums in comps]
                adj_nums = set()
                for v in neigh[cell]:
                    if state[v] == 0:
                        cid = comp_id[v]
                        if cid >= 0:
                            adj_nums.add(comp_num[cid])
                if len(adj_nums) >= 2:
                    ok = False

            if ok:
                sol = dfs(state)
                if sol is not None:
                    # undo local then global for caller consistency
                    for cell2, old2 in reversed(local_changes):
                        state[cell2] = old2
                    for cell2, old2 in reversed(changes):
                        state[cell2] = old2
                    return sol

            for cell2, old2 in reversed(local_changes):
                state[cell2] = old2

        for cell2, old2 in reversed(changes):
            state[cell2] = old2
        return None

    st = state0[:]
    init_changes = []
    apply_initial_forces(st, init_changes)
    sol = dfs(st)
    if sol is None:
        return "No Solution"

    # Build answer grid: 'B' for black, None for white
    out = []
    for r in range(R):
        row = []
        for c in range(C):
            i = idx(r,c)
            row.append('B' if sol[i] == 1 else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

