from __future__ import annotations

# Generalized solver for "consecutive adjacency" Latin square (1..N each row/col),
# where dots enforce consecutive numbers and missing dots forbid consecutiveness.

def solve(observation):
    data = observation["data"]
    dots = {tuple(x) for x in observation["adjacent"]}
    N = len(data)
    if any(len(r) != N for r in data):
        return "No Solution"

    # --- Precompute adjacency constraints per edge ---
    # Edges are between orthogonally adjacent cells.
    # For each cell, store neighbor indices and whether consecutive required (dot) or forbidden.
    def in_bounds(r, c):
        return 0 <= r < N and 0 <= c < N

    # map (r,c)->idx
    idx = lambda r, c: r * N + c
    rc = lambda i: (i // N, i % N)

    neighbors = [[] for _ in range(N * N)]  # list of (j, req_consecutive:bool)
    for r in range(N):
        for c in range(N):
            i = idx(r, c)
            for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                rr, cc = r + dr, c + dc
                if not in_bounds(rr, cc):
                    continue
                # midpoint coordinate
                if dr == 0:  # horizontal
                    mid = (float(r), c + 0.5) if dc == 1 else (float(r), cc + 0.5)
                else:  # vertical
                    mid = (r + 0.5, float(c)) if dr == 1 else (rr + 0.5, float(c))
                req = mid in dots
                j = idx(rr, cc)
                neighbors[i].append((j, req))

    # --- Bitmask domains ---
    # Values 1..N correspond to bits 0..N-1.
    ALL = (1 << N) - 1

    def bit(v):  # v in 1..N
        return 1 << (v - 1)

    def bits_to_list(m):
        out = []
        while m:
            lsb = m & -m
            out.append((lsb.bit_length()))
            m ^= lsb
        return out

    def popcount(x):
        return x.bit_count()

    # Precompute consecutive-neighborhood masks for each value
    cons_mask_for_val = [0] * (N + 1)
    for v in range(1, N + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < N:
            m |= bit(v + 1)
        cons_mask_for_val[v] = m

    # Given a domain mask, possible values that could be consecutive to something in other domain:
    # For req consecutive between cells A and B:
    # A allowed values must have at least one consecutive in domainB.
    # We can compute support by iterating values of smaller side; N is small typically.
    def filter_req_consecutive(domA, domB):
        if domA == 0 or domB == 0:
            return 0
        res = 0
        m = domA
        while m:
            lsb = m & -m
            v = lsb.bit_length()
            if cons_mask_for_val[v] & domB:
                res |= lsb
            m ^= lsb
        return res

    # For forbid consecutive between A and B:
    # Remove values v in A that are forced to be consecutive with B (i.e., all B values are consecutive to v).
    # More generally, keep v if there exists some b in B that is NOT consecutive to v.
    # Equivalent: keep v if (domB & ~cons_mask(v)) != 0.
    def filter_forbid_consecutive(domA, domB):
        if domA == 0 or domB == 0:
            return 0
        res = 0
        m = domA
        while m:
            lsb = m & -m
            v = lsb.bit_length()
            if domB & (ALL ^ cons_mask_for_val[v]):  # there exists non-consecutive value in B
                res |= lsb
            m ^= lsb
        return res

    # --- Initialize domains with given numbers ---
    dom = [ALL] * (N * N)
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                dom[idx(r, c)] = bit(v)

    # Row/col used masks (assigned values only)
    row_used = [0] * N
    col_used = [0] * N

    def is_single(m):
        return m != 0 and (m & (m - 1)) == 0

    def single_val(m):
        return m.bit_length()  # since only one bit set

    # Apply initial singles to used masks
    for i in range(N * N):
        if is_single(dom[i]):
            r, c = rc(i)
            v = single_val(dom[i])
            b = bit(v)
            if (row_used[r] & b) or (col_used[c] & b):
                return "No Solution"
            row_used[r] |= b
            col_used[c] |= b

    # --- Constraint propagation ---
    # Techniques:
    # 1) Latin elimination: remove used numbers from domains in row/col.
    # 2) Naked singles.
    # 3) Hidden singles in each row/col.
    # 4) Consecutive-dot propagation (AC-like) for required and forbidden edges.
    # 5) Stronger pair reasoning for required consecutive: if one side fixed, restrict other to {v-1,v+1}.
    # 6) Forbid consecutive: if one fixed, remove consecutive values from other.
    # 7) Advanced: maintain supports until fixed point.

    # For efficiency, keep list of cells per row/col
    row_cells = [[idx(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[idx(r, c) for r in range(N)] for c in range(N)]

    # Precompute edge list unique i<j to process both directions once (we'll filter both ends)
    edges = []
    seen = set()
    for i in range(N * N):
        for j, req in neighbors[i]:
            a, b = (i, j) if i < j else (j, i)
            key = (a, b)
            if key in seen:
                continue
            seen.add(key)
            # Determine req from midpoint by recomputing: but easier store from i->j; since symmetric, same.
            # Find req by checking either direction list:
            # We'll just use the one from i to j if i has it.
            # If i->j not in list when i>j, locate in neighbors[j].
            if i < j:
                req2 = req
            else:
                req2 = next(xreq for (xj, xreq) in neighbors[j] if xj == i)
            edges.append((a, b, req2))

    def assign(i, new_dom):
        nonlocal dom, row_used, col_used
        if dom[i] == new_dom:
            return True
        if new_dom == 0:
            return False
        # if was single, we'd need to rollback used masks; we avoid direct mutation complexities by
        # only assigning from non-single to single in propagation and ensuring used masks consistent via rebuild.
        dom[i] = new_dom
        return True

    def rebuild_used_masks():
        nonlocal row_used, col_used
        row_used = [0] * N
        col_used = [0] * N
        for i in range(N * N):
            if is_single(dom[i]):
                r, c = rc(i)
                v = single_val(dom[i])
                b = bit(v)
                if (row_used[r] & b) or (col_used[c] & b):
                    return False
                row_used[r] |= b
                col_used[c] |= b
        return True

    def latin_elimination():
        changed = False
        for r in range(N):
            used = row_used[r]
            if used:
                inv = ALL ^ used
                for i in row_cells[r]:
                    if not is_single(dom[i]):
                        nd = dom[i] & inv
                        if nd != dom[i]:
                            if not assign(i, nd):
                                return False, False
                            changed = True
        for c in range(N):
            used = col_used[c]
            if used:
                inv = ALL ^ used
                for i in col_cells[c]:
                    if not is_single(dom[i]):
                        nd = dom[i] & inv
                        if nd != dom[i]:
                            if not assign(i, nd):
                                return False, False
                            changed = True
        return True, changed

    def hidden_singles():
        changed = False
        # Rows
        for r in range(N):
            # For each value, track possible cell count via bitwise OR of domains.
            # We'll compute occurrence counts using scan of bits (N small).
            poss = [0] * (N + 1)
            last_cell = [None] * (N + 1)
            for i in row_cells[r]:
                m = dom[i]
                mm = m
                while mm:
                    lsb = mm & -mm
                    v = lsb.bit_length()
                    poss[v] += 1
                    last_cell[v] = i
                    mm ^= lsb
            for v in range(1, N + 1):
                if poss[v] == 0:
                    return False, False
                if poss[v] == 1:
                    i = last_cell[v]
                    if not is_single(dom[i]):
                        if not assign(i, bit(v)):
                            return False, False
                        changed = True
        # Cols
        for c in range(N):
            poss = [0] * (N + 1)
            last_cell = [None] * (N + 1)
            for i in col_cells[c]:
                m = dom[i]
                mm = m
                while mm:
                    lsb = mm & -mm
                    v = lsb.bit_length()
                    poss[v] += 1
                    last_cell[v] = i
                    mm ^= lsb
            for v in range(1, N + 1):
                if poss[v] == 0:
                    return False, False
                if poss[v] == 1:
                    i = last_cell[v]
                    if not is_single(dom[i]):
                        if not assign(i, bit(v)):
                            return False, False
                        changed = True
        return True, changed

    def adjacency_propagation():
        changed = False
        for a, b, req in edges:
            da, db = dom[a], dom[b]
            if req:
                nda = filter_req_consecutive(da, db)
                ndb = filter_req_consecutive(db, da)
            else:
                nda = filter_forbid_consecutive(da, db)
                ndb = filter_forbid_consecutive(db, da)
            if nda == 0 or ndb == 0:
                return False, False
            if nda != da:
                if not assign(a, nda):
                    return False, False
                changed = True
            if ndb != db:
                if not assign(b, ndb):
                    return False, False
                changed = True
        return True, changed

    def local_fixed_point():
        # iterate until no more changes
        while True:
            if not rebuild_used_masks():
                return False
            ok, ch1 = latin_elimination()
            if not ok:
                return False
            if not rebuild_used_masks():
                return False
            ok, ch2 = adjacency_propagation()
            if not ok:
                return False
            if not rebuild_used_masks():
                return False
            ok, ch3 = hidden_singles()
            if not ok:
                return False
            if not (ch1 or ch2 or ch3):
                return True

    # --- Search with strong branching (still deduction-first) ---
    def solved():
        return all(is_single(m) for m in dom)

    def select_cell():
        # MRV with tie-breaker: most adjacency constraints degree
        best = -1
        best_sz = 10**9
        best_deg = -1
        for i, m in enumerate(dom):
            if is_single(m):
                continue
            sz = popcount(m)
            if sz < best_sz:
                best = i
                best_sz = sz
                best_deg = len(neighbors[i])
            elif sz == best_sz:
                deg = len(neighbors[i])
                if deg > best_deg:
                    best = i
                    best_deg = deg
        return best

    def order_values(i):
        # LCV heuristic: prefer values that leave more options for neighbors and row/col.
        r, c = rc(i)
        used_r = row_used[r]
        used_c = col_used[c]
        vals = bits_to_list(dom[i])
        scored = []
        for v in vals:
            b = bit(v)
            if (used_r & b) or (used_c & b):
                continue
            score = 0
            # impact on row/col: count how many domains in row/col contain v
            for j in row_cells[r]:
                if j != i and (dom[j] & b):
                    score += 1
            for j in col_cells[c]:
                if j != i and (dom[j] & b):
                    score += 1
            # impact on adjacency: for each neighbor, estimate remaining support
            for j, req in neighbors[i]:
                dj = dom[j]
                if req:
                    score += popcount(dj & cons_mask_for_val[v])
                else:
                    score += popcount(dj & (ALL ^ cons_mask_for_val[v]))
            scored.append((score, v))
        scored.sort(reverse=True)
        return [v for _, v in scored] if scored else vals

    def dfs():
        if not local_fixed_point():
            return False
        if solved():
            return True
        i = select_cell()
        if i < 0:
            return False

        snapshot_dom = dom[:]
        snapshot_row_used = row_used[:]
        snapshot_col_used = col_used[:]

        for v in order_values(i):
            dom[i] = bit(v)
            if dfs():
                return True
            # restore
            dom[:] = snapshot_dom
            row_used[:] = snapshot_row_used
            col_used[:] = snapshot_col_used
        return False

    if not dfs():
        return "No Solution"

    # Build solved grid
    out = [[0] * N for _ in range(N)]
    for i in range(N * N):
        if not is_single(dom[i]):
            return "No Solution"
        r, c = rc(i)
        out[r][c] = single_val(dom[i])
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

