from __future__ import annotations
from dataclasses import dataclass
from typing import Dict, List, Tuple, Optional, Set
from collections import deque, defaultdict
import itertools
import math

Coord = Tuple[int, int]
EdgeKey = Tuple[Coord, Coord]


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    islands: List[Coord] = [(r, c) for r in range(n) for c in range(n) if isinstance(grid[r][c], int)]
    if not islands:
        return "No Solution"
    demand = {p: grid[p[0]][p[1]] for p in islands}

    # ---- Build visibility graph (potential bridges) ----
    # Only connect nearest island in each of 4 directions.
    island_set = set(islands)
    neighbors: Dict[Coord, List[Coord]] = {p: [] for p in islands}

    def first_island_in_dir(r, c, dr, dc):
        rr, cc = r + dr, c + dc
        while 0 <= rr < n and 0 <= cc < n:
            if (rr, cc) in island_set:
                return (rr, cc)
            rr += dr
            cc += dc
        return None

    for (r, c) in islands:
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            q = first_island_in_dir(r, c, dr, dc)
            if q is not None:
                neighbors[(r, c)].append(q)

    # Create unique undirected edges between visible islands.
    edges: List[EdgeKey] = []
    edge_index: Dict[EdgeKey, int] = {}
    for a in islands:
        for b in neighbors[a]:
            if a == b:
                continue
            k = (a, b) if a < b else (b, a)
            if k not in edge_index:
                edge_index[k] = len(edges)
                edges.append(k)

    if not edges:
        return "No Solution"

    # Precompute edge geometry cells for crossing/overlap constraints.
    # In Hashiwokakero, parallel edges can share the same line between same islands (1 or 2 bridges);
    # but different edges cannot overlap (share interior cell), and cannot cross.
    def edge_cells(a: Coord, b: Coord):
        (r1, c1), (r2, c2) = a, b
        cells = []
        if r1 == r2:
            cmin, cmax = sorted((c1, c2))
            for cc in range(cmin + 1, cmax):
                cells.append((r1, cc))
        elif c1 == c2:
            rmin, rmax = sorted((r1, r2))
            for rr in range(rmin + 1, rmax):
                cells.append((rr, c1))
        else:
            raise ValueError("Non-orthogonal edge")
        return tuple(cells)

    edge_cells_map: List[Tuple[Coord, ...]] = [edge_cells(a, b) for (a, b) in edges]

    # Map each grid cell to edges that occupy it.
    cell_to_edges: Dict[Coord, List[int]] = defaultdict(list)
    for ei, cells in enumerate(edge_cells_map):
        for cell in cells:
            cell_to_edges[cell].append(ei)

    # Overlap constraint: if two edges share any interior cell, they cannot both be >0 (unless same edge).
    conflicts: List[Set[int]] = [set() for _ in edges]
    for cell, elist in cell_to_edges.items():
        if len(elist) >= 2:
            for i in elist:
                for j in elist:
                    if i != j:
                        conflicts[i].add(j)

    # For fast degree bookkeeping
    incident_edges: Dict[Coord, List[int]] = {p: [] for p in islands}
    for ei, (a, b) in enumerate(edges):
        incident_edges[a].append(ei)
        incident_edges[b].append(ei)

    # ---- State ----
    # Edge values: -1 unknown, 0 none, 1 single, 2 double
    vals = [-1] * len(edges)
    deg = {p: 0 for p in islands}

    # Domains for each edge, dynamically restricted by conflicts and endpoint demands.
    dom = [set((0, 1, 2)) for _ in edges]

    # ---- Utility functions ----
    def endpoints(ei: int) -> Tuple[Coord, Coord]:
        return edges[ei]

    def other(ep: Coord, ei: int) -> Coord:
        a, b = edges[ei]
        return b if ep == a else a

    def set_edge(ei: int, v: int, trail: list) -> bool:
        """Assign edge ei to v with propagation of immediate consequences.
        trail holds reversible modifications."""
        cur = vals[ei]
        if cur != -1:
            return cur == v
        if v not in dom[ei]:
            return False
        vals[ei] = v
        trail.append(("val", ei, -1))
        # Fix domain to singleton
        old_dom = dom[ei]
        dom[ei] = {v}
        trail.append(("dom", ei, old_dom))

        a, b = endpoints(ei)
        if v:
            # apply conflict: all conflicting edges must be 0
            for cj in conflicts[ei]:
                if vals[cj] == -1:
                    # remove 1,2 from domain; if only 0 remains, assign 0
                    if 1 in dom[cj] or 2 in dom[cj]:
                        old = dom[cj]
                        new = set(old)
                        new.discard(1)
                        new.discard(2)
                        if not new:
                            return False
                        if new != old:
                            dom[cj] = new
                            trail.append(("dom", cj, old))
                        if len(dom[cj]) == 1:
                            if not set_edge(cj, next(iter(dom[cj])), trail):
                                return False
                else:
                    if vals[cj] != 0:
                        return False

        # update degrees
        if v:
            for p in (a, b):
                oldd = deg[p]
                deg[p] = oldd + v
                trail.append(("deg", p, oldd))
                if deg[p] > demand[p]:
                    return False

        # endpoint feasibility (basic bounds)
        for p in (a, b):
            if not endpoint_bounds_ok(p):
                return False

        return True

    def endpoint_bounds_ok(p: Coord) -> bool:
        """Check min/max possible degree remaining for island p."""
        used = deg[p]
        rem = demand[p] - used
        if rem < 0:
            return False
        # Max additional degree from incident edges not fixed
        max_add = 0
        min_add = 0
        for ei in incident_edges[p]:
            if vals[ei] != -1:
                continue
            # potential contribution is value chosen on ei
            # compute possible contributions to p from domain:
            poss = dom[ei]
            # contribution equals chosen value
            if not poss:
                return False
            min_add += min(poss)
            max_add += max(poss)
        if used + min_add > demand[p]:
            return False
        if used + max_add < demand[p]:
            return False
        return True

    def undo(trail: list):
        for kind, key, old in reversed(trail):
            if kind == "val":
                vals[key] = old
            elif kind == "dom":
                dom[key] = old
            elif kind == "deg":
                deg[key] = old
            else:
                raise ValueError(kind)

    # ---- Human-like deduction rules ----
    def propagate(trail: list) -> bool:
        """Repeatedly apply local deductions until fixpoint."""
        q = deque()

        # seed with all islands
        for p in islands:
            q.append(p)

        inq = set(islands)

        def push(p):
            if p not in inq:
                q.append(p)
                inq.add(p)

        # Also seed with edges that became singleton domains
        # We'll re-check endpoint bounds anyway.

        while q:
            p = q.popleft()
            inq.remove(p)

            if not endpoint_bounds_ok(p):
                return False

            used = deg[p]
            need = demand[p] - used
            inc = incident_edges[p]
            unknown = [ei for ei in inc if vals[ei] == -1]
            if need == 0:
                # All incident unknown must be 0
                for ei in unknown:
                    if 0 not in dom[ei]:
                        return False
                    if len(dom[ei]) != 1:
                        if not set_edge(ei, 0, trail):
                            return False
                        a, b = endpoints(ei)
                        push(a)
                        push(b)
                continue

            if not unknown:
                if need != 0:
                    return False
                continue

            # Rule: forced maximum fill when even with max others, each edge must contribute at least something
            # Equivalent: if sum(max) == need then each unknown edge fixed to its max
            max_sum = sum(max(dom[ei]) for ei in unknown)
            min_sum = sum(min(dom[ei]) for ei in unknown)
            if need < min_sum or need > max_sum:
                return False
            if max_sum == need:
                for ei in unknown:
                    v = max(dom[ei])
                    if not set_edge(ei, v, trail):
                        return False
                    a, b = endpoints(ei)
                    push(a); push(b)
                continue
            if min_sum == need:
                for ei in unknown:
                    v = min(dom[ei])
                    if not set_edge(ei, v, trail):
                        return False
                    a, b = endpoints(ei)
                    push(a); push(b)
                continue

            # Rule: if need equals number of unknown edges and 0 is allowed, force each to at least 1 (if possible)
            # Implement as remove 0 when need == count and all edges can be >=1.
            if need == len(unknown):
                for ei in unknown:
                    if 0 in dom[ei]:
                        if 1 not in dom[ei] and 2 not in dom[ei]:
                            return False
                        old = dom[ei]
                        new = set(old)
                        new.discard(0)
                        if not new:
                            return False
                        if new != old:
                            dom[ei] = new
                            trail.append(("dom", ei, old))
                        if len(dom[ei]) == 1:
                            if not set_edge(ei, next(iter(dom[ei])), trail):
                                return False
                            a, b = endpoints(ei)
                            push(a); push(b)
                # no continue; other rules may apply

            # Rule: If need is large, cap 0/1
            # For each unknown edge, ensure feasibility by tightening its max/min based on remaining need.
            # Classic bound consistency on sum of variables (each in {0,1,2} subset).
            for ei in list(unknown):
                poss = dom[ei]
                if len(poss) == 1:
                    continue
                others = [ej for ej in unknown if ej != ei]
                min_others = sum(min(dom[ej]) for ej in others)
                max_others = sum(max(dom[ej]) for ej in others)
                # v must satisfy min_others + v <= need <= max_others + v
                new_poss = set()
                for v in poss:
                    if min_others + v <= need <= max_others + v:
                        new_poss.add(v)
                if not new_poss:
                    return False
                if new_poss != poss:
                    old = dom[ei]
                    dom[ei] = new_poss
                    trail.append(("dom", ei, old))
                    if len(new_poss) == 1:
                        if not set_edge(ei, next(iter(new_poss)), trail):
                            return False
                        a, b = endpoints(ei)
                        push(a); push(b)

        return True

    # ---- Connectivity handling (human-like: avoid premature separation) ----
    # We'll enforce:
    # 1) Final: all islands connected via edges with val>0.
    # 2) During search: no island can become impossible to connect (must have at least one possible positive incident edge unless already connected in a component with all demands satisfied?).
    # 3) Prevent creating a "closed" solved component disconnected from unsolved islands (bridge-cut heuristic).

    def possible_positive_incident(p: Coord) -> bool:
        for ei in incident_edges[p]:
            if vals[ei] == -1:
                if 1 in dom[ei] or 2 in dom[ei]:
                    return True
            elif vals[ei] > 0:
                return True
        return False

    def components_of_current_graph() -> List[Set[Coord]]:
        g = {p: [] for p in islands}
        for ei, (a, b) in enumerate(edges):
            v = vals[ei]
            if v and v > 0:
                g[a].append(b)
                g[b].append(a)
        seen = set()
        comps = []
        for p in islands:
            if p in seen:
                continue
            stack = [p]
            seen.add(p)
            comp = {p}
            while stack:
                x = stack.pop()
                for y in g[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
                        comp.add(y)
            comps.append(comp)
        return comps

    def connectivity_prune() -> bool:
        # If an island has remaining demand but no possible positive incident edge, fail.
        for p in islands:
            if deg[p] < demand[p] and not any(
                (vals[ei] == -1 and (1 in dom[ei] or 2 in dom[ei])) or (vals[ei] != -1 and vals[ei] > 0)
                for ei in incident_edges[p]
            ):
                return False

        comps = components_of_current_graph()
        if len(comps) <= 1:
            return True

        # If any component is "closed": all islands in it already meet demand, and there is no possible positive edge leaving it, then impossible.
        comp_index = {}
        for i, comp in enumerate(comps):
            for p in comp:
                comp_index[p] = i

        for comp in comps:
            all_satisfied = all(deg[p] == demand[p] for p in comp)
            if not all_satisfied:
                continue
            # is there any edge (assigned or possible) connecting comp to outside?
            has_exit = False
            for p in comp:
                for ei in incident_edges[p]:
                    a, b = endpoints(ei)
                    q = b if p == a else a
                    if q in comp:
                        continue
                    # If already positive, it's an exit (would merge comps)
                    if vals[ei] != -1:
                        if vals[ei] > 0:
                            has_exit = True
                            break
                    else:
                        if 1 in dom[ei] or 2 in dom[ei]:
                            has_exit = True
                            break
                if has_exit:
                    break
            if not has_exit:
                return False

        return True

    # ---- Branching heuristic ----
    def pick_var() -> Optional[int]:
        # Choose unassigned edge with smallest domain >1, break ties by higher impact (conflicts+incident demand pressure).
        best = None
        best_key = None
        for ei in range(len(edges)):
            if vals[ei] != -1:
                continue
            dsz = len(dom[ei])
            if dsz <= 1:
                continue
            a, b = endpoints(ei)
            pressure = (demand[a] - deg[a]) + (demand[b] - deg[b])
            impact = len(conflicts[ei]) + len(incident_edges[a]) + len(incident_edges[b])
            key = (dsz, -pressure, -impact)
            if best is None or key < best_key:
                best = ei
                best_key = key
        if best is not None:
            return best
        # If all remaining are singleton domains but unassigned, pick any
        for ei in range(len(edges)):
            if vals[ei] == -1:
                return ei
        return None

    def order_values(ei: int) -> List[int]:
        # Prefer values that satisfy endpoints (greedy): try larger if endpoints need many, else smaller.
        a, b = endpoints(ei)
        need_a = demand[a] - deg[a]
        need_b = demand[b] - deg[b]
        poss = sorted(dom[ei])
        # scoring
        def score(v):
            # encourage v close to average need but penalize overfilling risk
            return (abs((need_a + need_b) / 2 - v), 0 if v == 1 else 1, v)
        poss.sort(key=score)
        return poss

    # ---- Final check ----
    def is_complete() -> bool:
        return all(vals[ei] != -1 for ei in range(len(edges))) and all(deg[p] == demand[p] for p in islands)

    def final_connected() -> bool:
        comps = components_of_current_graph()
        return len(comps) == 1

    # ---- Search ----
    def dfs() -> bool:
        trail = []
        if not propagate(trail):
            undo(trail)
            return False
        if not connectivity_prune():
            undo(trail)
            return False
        if is_complete():
            ok = final_connected()
            undo(trail)  # will be re-applied by caller? We instead avoid undo by copying solution; easier store globally.
            return ok

        ei = pick_var()
        if ei is None:
            undo(trail)
            return False

        # If singleton domain, just set and continue
        if len(dom[ei]) == 1:
            v = next(iter(dom[ei]))
            if set_edge(ei, v, trail) and dfs():
                return True
            undo(trail)
            return False

        # Try values in heuristic order
        snapshot = list(trail)
        for v in order_values(ei):
            trail2 = []
            if set_edge(ei, v, trail2):
                if dfs():
                    # commit: keep assignments; but since recursion undoes, we need global capture
                    # We'll store in global 'solution_vals' at first success.
                    solution_vals[:] = vals[:]
                    solution_deg.update(deg)
                    # unwind current trails without undoing deeper committed? We'll just return True and let callers unwind without undo.
                    # To prevent undo by callers, they must not undo when returning True.
                    # So we must not call undo here.
                    return True
            undo(trail2)
        undo(trail)
        return False

    # Global solution capture
    solution_vals = [-1] * len(edges)
    solution_deg = {}

    # Before search, initial propagation
    trail0 = []
    if not propagate(trail0) or not connectivity_prune():
        undo(trail0)
        return "No Solution"
    # Keep initial assignments; undo not needed.
    solution_vals[:] = vals[:]

    if not dfs():
        return "No Solution"

    # Use captured solution if any, otherwise current.
    sol = solution_vals
    if any(v == -1 for v in sol):
        sol = vals

    # Build answer dict
    ans: Dict[EdgeKey, int] = {}
    for ei, v in enumerate(sol):
        if v and v > 0:
            a, b = edges[ei]
            k = (a, b) if a < b else (b, a)
            ans[k] = int(v)

    # Verify degrees and connectivity
    # (Lightweight; if fails, return No Solution)
    chk_deg = {p: 0 for p in islands}
    for (a, b), v in ans.items():
        chk_deg[a] += v
        chk_deg[b] += v
    if any(chk_deg[p] != demand[p] for p in islands):
        return "No Solution"
    # connectivity
    g = {p: [] for p in islands}
    for (a, b), v in ans.items():
        if v > 0:
            g[a].append(b); g[b].append(a)
    start = islands[0]
    seen = set([start])
    dq = deque([start])
    while dq:
        x = dq.popleft()
        for y in g[x]:
            if y not in seen:
                seen.add(y)
                dq.append(y)
    if len(seen) != len(islands):
        return "No Solution"

    return str(ans)


