from collections import deque

# Solver for "consecutive dots" Latin square:
# - Size N grid with digits 1..N in each row/col exactly once.
# - Dots specify orthogonally adjacent cells must be consecutive.
# - Absence of dot specifies they must NOT be consecutive.
#
# Approach:
# - Bitmask domains for each cell.
# - Aggressive propagation:
#   * Given numbers prune row/col peers.
#   * For each adjacency (with-dot / without-dot) apply arc-consistency (AC-3 style).
#   * "Hidden singles" in rows/cols.
#   * Strong pair constraint propagation for dotted edges:
#       if cell has value v then neighbor must be in {v-1, v+1} within 1..N
#     for non-dotted edges:
#       if cell has value v then neighbor cannot be {v-1, v+1}
# - Search with MRV + degree tie-break; forward-checking through propagation.
#
# Note: This is generalized and does not hardcode any instance-specific logic.

def solve(observation):
    grid = observation["data"]
    dots = observation["adjacent"]
    N = len(grid)
    if N == 0 or any(len(r) != N for r in grid):
        return "No Solution"

    ALL = (1 << N) - 1  # bit i means value i+1 allowed

    def bit(v):  # v is 1..N
        return 1 << (v - 1)

    def is_single(m):
        return m and (m & (m - 1)) == 0

    def single_val(m):
        return (m.bit_length())  # since single bit at k-1 -> bit_length=k

    # Build dot-set for quick lookup between orthogonally adjacent cells.
    # Midpoint coords: (r, c+0.5) horizontal, (r+0.5, c) vertical.
    dotset = set()
    for rc in dots:
        r, c = float(rc[0]), float(rc[1])
        dotset.add((r, c))

    def has_dot(a, b):
        (r1, c1), (r2, c2) = a, b
        if abs(r1 - r2) + abs(c1 - c2) != 1:
            return False
        if r1 == r2:
            r = float(r1)
            c = (c1 + c2) / 2.0
            return (r, c) in dotset
        else:
            r = (r1 + r2) / 2.0
            c = float(c1)
            return (r, c) in dotset

    # Precompute orthogonal neighbor pairs and whether dotted.
    neighbors = [[] for _ in range(N * N)]
    edges = []  # (i,j,is_dot) undirected stored both directions in neighbors
    for r in range(N):
        for c in range(N):
            i = r * N + c
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < N and 0 <= cc < N:
                    j = rr * N + cc
                    dotted = has_dot((r, c), (rr, cc))
                    neighbors[i].append((j, dotted))
            # no edges list needed; neighbors suffice

    # Row/col membership
    row_cells = [[r * N + c for c in range(N)] for r in range(N)]
    col_cells = [[r * N + c for r in range(N)] for c in range(N)]
    cell_row = [i // N for i in range(N * N)]
    cell_col = [i % N for i in range(N * N)]

    # Initialize domains
    dom = [ALL for _ in range(N * N)]
    givens = []
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                i = r * N + c
                dom[i] = bit(v)
                givens.append(i)

    # Helper: remove bits; record changes for backtracking
    def remove_bits(i, rem, trail):
        if rem == 0:
            return True
        before = dom[i]
        after = before & ~rem
        if after == before:
            return True
        if after == 0:
            return False
        dom[i] = after
        trail.append((i, before))
        return True

    def set_domain(i, newm, trail):
        before = dom[i]
        if before == newm:
            return True
        if newm == 0:
            return False
        dom[i] = newm
        trail.append((i, before))
        return True

    # Constraint support filtering for adjacency arcs
    def filter_neighbor(xm, dotted):
        # For a given domain mask of X, compute union of allowed values of Y.
        # dotted: Y must be consecutive to X
        # not dotted: Y must not be consecutive to X
        if xm == 0:
            return 0
        allowed = 0
        # Iterate bits in xm
        m = xm
        while m:
            lsb = m & -m
            v = (lsb.bit_length())  # 1..N
            if dotted:
                if v > 1:
                    allowed |= bit(v - 1)
                if v < N:
                    allowed |= bit(v + 1)
            else:
                # all except consecutive numbers to v
                ban = 0
                if v > 1:
                    ban |= bit(v - 1)
                if v < N:
                    ban |= bit(v + 1)
                allowed |= (ALL & ~ban)
            m -= lsb
        return allowed

    # AC-3 like propagation for adjacency constraints plus Latin row/col constraints
    def propagate(trail):
        q = deque()

        # enqueue all adjacency arcs
        for i in range(N * N):
            for j, dotted in neighbors[i]:
                q.append((i, j, dotted))

        # also enqueue latin constraints via singles queue
        singles = deque(i for i in range(N * N) if is_single(dom[i]))

        def enqueue_peers(i):
            r = cell_row[i]
            c = cell_col[i]
            for j in row_cells[r]:
                if j != i:
                    q.append((i, j, None))  # None marks latin-diff constraint
                    q.append((j, i, None))
            for j in col_cells[c]:
                if j != i:
                    q.append((i, j, None))
                    q.append((j, i, None))

        # seed peers from given singles
        seen_single = [False] * (N * N)
        for i in list(singles):
            seen_single[i] = True
            enqueue_peers(i)

        while q or singles:
            # process newly created singles to update latin constraints
            while singles:
                i = singles.popleft()
                if not is_single(dom[i]):
                    continue
                if seen_single[i]:
                    continue
                seen_single[i] = True
                enqueue_peers(i)

            if not q:
                continue
            xi, yi, kind = q.popleft()
            if kind is None:
                # Latin constraint: xi and yi in same row or col => different
                if not is_single(dom[xi]):
                    continue
                v = dom[xi]
                if dom[yi] & v:
                    if not remove_bits(yi, v, trail):
                        return False
                    if is_single(dom[yi]):
                        singles.append(yi)
                        # adjacency arcs from yi might tighten neighbors
                        for k, dotted in neighbors[yi]:
                            q.append((yi, k, dotted))
                            q.append((k, yi, dotted))
                    # peers of yi will be enqueued via singles mechanism
                continue

            dotted = kind
            # Revise yi using xi
            allowed_y = filter_neighbor(dom[xi], dotted)
            new_y = dom[yi] & allowed_y
            if new_y != dom[yi]:
                if not set_domain(yi, new_y, trail):
                    return False
                if is_single(new_y):
                    singles.append(yi)
                # If yi changed, propagate to its adjacency neighbors (including xi)
                for k, dotted2 in neighbors[yi]:
                    q.append((yi, k, dotted2))
                # Also xi might be revised based on yi (enqueue reverse)
                q.append((yi, xi, dotted))
                q.append((xi, yi, dotted))

            # Also revise xi using yi (helps convergence when processed in one direction)
            allowed_x = filter_neighbor(dom[yi], dotted)
            new_x = dom[xi] & allowed_x
            if new_x != dom[xi]:
                if not set_domain(xi, new_x, trail):
                    return False
                if is_single(new_x):
                    singles.append(xi)
                for k, dotted2 in neighbors[xi]:
                    q.append((xi, k, dotted2))
                q.append((xi, yi, dotted))
                q.append((yi, xi, dotted))

        # Hidden singles in each row/col
        # (do after arc consistency since it's cheaper and may create assignments)
        changed = True
        while changed:
            changed = False
            # rows
            for r in range(N):
                counts = [0] * (N + 1)
                lastpos = [-1] * (N + 1)
                for i in row_cells[r]:
                    m = dom[i]
                    mm = m
                    while mm:
                        lsb = mm & -mm
                        v = lsb.bit_length()
                        counts[v] += 1
                        lastpos[v] = i
                        mm -= lsb
                for v in range(1, N + 1):
                    if counts[v] == 0:
                        return False
                    if counts[v] == 1:
                        i = lastpos[v]
                        if not is_single(dom[i]):
                            if not set_domain(i, bit(v), trail):
                                return False
                            changed = True
            # cols
            for c in range(N):
                counts = [0] * (N + 1)
                lastpos = [-1] * (N + 1)
                for i in col_cells[c]:
                    m = dom[i]
                    mm = m
                    while mm:
                        lsb = mm & -mm
                        v = lsb.bit_length()
                        counts[v] += 1
                        lastpos[v] = i
                        mm -= lsb
                for v in range(1, N + 1):
                    if counts[v] == 0:
                        return False
                    if counts[v] == 1:
                        i = lastpos[v]
                        if not is_single(dom[i]):
                            if not set_domain(i, bit(v), trail):
                                return False
                            changed = True
            if changed:
                # after hidden singles, propagate quickly with latin+adj constraints
                if not propagate(trail):
                    return False
        return True

    # Initial consistency: check duplicates in givens quickly and propagate
    def check_givens_ok():
        for r in range(N):
            seen = 0
            for i in row_cells[r]:
                if is_single(dom[i]):
                    if seen & dom[i]:
                        return False
                    seen |= dom[i]
        for c in range(N):
            seen = 0
            for i in col_cells[c]:
                if is_single(dom[i]):
                    if seen & dom[i]:
                        return False
                    seen |= dom[i]
        return True

    if not check_givens_ok():
        return "No Solution"
    trail0 = []
    if not propagate(trail0):
        return "No Solution"

    def solved():
        return all(is_single(dom[i]) for i in range(N * N))

    def select_unassigned():
        # MRV with degree tie-break (more constraints)
        best = -1
        best_size = 10**9
        best_deg = -1
        for i in range(N * N):
            m = dom[i]
            if not is_single(m):
                sz = m.bit_count()
                if sz < best_size:
                    best = i
                    best_size = sz
                    # degree = number of unassigned peers + adjacency neighbors
                    r, c = cell_row[i], cell_col[i]
                    deg = 0
                    for j in row_cells[r]:
                        if j != i and not is_single(dom[j]):
                            deg += 1
                    for j in col_cells[c]:
                        if j != i and not is_single(dom[j]):
                            deg += 1
                    for j, _ in neighbors[i]:
                        if not is_single(dom[j]):
                            deg += 1
                    best_deg = deg
                elif sz == best_size:
                    r, c = cell_row[i], cell_col[i]
                    deg = 0
                    for j in row_cells[r]:
                        if j != i and not is_single(dom[j]):
                            deg += 1
                    for j in col_cells[c]:
                        if j != i and not is_single(dom[j]):
                            deg += 1
                    for j, _ in neighbors[i]:
                        if not is_single(dom[j]):
                            deg += 1
                    if deg > best_deg:
                        best = i
                        best_deg = deg
        return best

    def order_values(i):
        # Least-constraining value heuristic:
        # score values by how many options they leave in row/col peers and dotted neighbors
        m = dom[i]
        vals = []
        r, c = cell_row[i], cell_col[i]
        peers = set(row_cells[r] + col_cells[c])
        peers.discard(i)
        adjs = neighbors[i]
        mm = m
        while mm:
            lsb = mm & -mm
            v = lsb.bit_length()
            score = 0
            vb = bit(v)
            # latin impact: remove vb from peers
            for j in peers:
                if dom[j] & vb:
                    score += 1
            # adjacency impact: compute how much neighbor domains shrink
            for j, dotted in adjs:
                allowed = filter_neighbor(vb, dotted)
                score += (dom[j].bit_count() - (dom[j] & allowed).bit_count())
            vals.append((score, vb))
            mm -= lsb
        vals.sort(key=lambda x: x[0])
        return [vb for _, vb in vals]

    def dfs():
        if solved():
            return True
        i = select_unassigned()
        if i == -1:
            return False
        for vb in order_values(i):
            trail = []
            if not set_domain(i, vb, trail):
                # undo
                for k, before in reversed(trail):
                    dom[k] = before
                continue
            if propagate(trail):
                if dfs():
                    return True
            for k, before in reversed(trail):
                dom[k] = before
        return False

    if not dfs():
        return "No Solution"

    out = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            out[r][c] = single_val(dom[r * N + c])
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

