# Generalized solver for "consecutive Latin square" (a.k.a. Consecutive Sudoku without blocks):
# - N x N Latin constraints (rows/cols are permutations of 1..N)
# - Dots between orthogonally adjacent cells indicate consecutive values
# - Missing dot implies NOT consecutive
#
# Strategy (human-like):
# 1) Maintain candidate sets per cell (bitmasks).
# 2) Aggressive propagation:
#    - Row/col elimination, singles, hidden singles
#    - Consecutive edge constraints (dot => neighbor in {v-1,v+1}, no-dot => forbid those)
#    - Arc consistency-like pruning on adjacency edges (AC-3 style but lightweight)
#    - Pair/triple pruning in rows/cols (naked subsets up to size 3)
# 3) Search with strong heuristics:
#    - Choose cell with smallest domain (MRV)
#    - Value ordering: prefer values that satisfy most dotted edges (least-constraining-ish)
# 4) Backtracking with trail for fast undo.

from collections import deque

def solve(observation):
    data = observation["data"]
    N = len(data)
    if N == 0 or any(len(r) != N for r in data):
        return "No Solution"

    # Parse adjacency dots into constraints between cells
    # We'll store for each undirected neighbor pair a boolean: dot=True means consecutive, False means not consecutive.
    # Not all neighbor pairs appear in adjacent list; those imply "no dot".
    dot_midpoints = set()
    for a, b in observation.get("adjacent", []):
        dot_midpoints.add((float(a), float(b)))

    def in_bounds(r, c):
        return 0 <= r < N and 0 <= c < N

    # Build neighbor relations for all orthogonal adjacencies
    # constraint[(r1,c1,r2,c2)] = True if consecutive, False otherwise, directed for convenience
    cons = {}
    neighbors = [[] for _ in range(N * N)]
    def idx(r, c): return r * N + c

    for r in range(N):
        for c in range(N):
            for dr, dc, mid in ((0, 1, (r + 0.0, c + 0.5)),
                                (1, 0, (r + 0.5, c + 0.0))):
                r2, c2 = r + dr, c + dc
                if in_bounds(r2, c2):
                    is_dot = (float(mid[0]), float(mid[1])) in dot_midpoints
                    cons[(r, c, r2, c2)] = is_dot
                    cons[(r2, c2, r, c)] = is_dot
                    neighbors[idx(r, c)].append((r2, c2))
                    neighbors[idx(r2, c2)].append((r, c))

    # Bitmask utilities: values 1..N mapped to bits 0..N-1
    ALL = (1 << N) - 1

    def bit(v): return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def lowest_bit_index(x):
        # x != 0
        return (x & -x).bit_length() - 1

    def iter_bits(x):
        while x:
            lsb = x & -x
            i = lsb.bit_length() - 1
            yield i
            x ^= lsb

    # Precompute consecutive sets for each value
    consmask = [0] * (N + 1)
    for v in range(1, N + 1):
        m = 0
        if v > 1: m |= bit(v - 1)
        if v < N: m |= bit(v + 1)
        consmask[v] = m

    # Domain array as bitmask per cell
    dom = [ALL] * (N * N)

    # Row/col used masks for assigned values (bit=1 means value is already placed)
    row_used = [0] * N
    col_used = [0] * N

    # Initialize from givens
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= N):
                return "No Solution"
            m = bit(v)
            k = idx(r, c)
            dom[k] = m
            if row_used[r] & m:  # duplicate
                return "No Solution"
            if col_used[c] & m:
                return "No Solution"
            row_used[r] |= m
            col_used[c] |= m

    # Apply initial row/col elimination
    for r in range(N):
        used = row_used[r]
        if used:
            for c in range(N):
                k = idx(r, c)
                if popcount(dom[k]) != 1:
                    dom[k] &= ~used
    for c in range(N):
        used = col_used[c]
        if used:
            for r in range(N):
                k = idx(r, c)
                if popcount(dom[k]) != 1:
                    dom[k] &= ~used

    # Trail-based assignments
    trail = []
    def push_state():
        trail.append(None)

    def undo():
        while trail:
            item = trail.pop()
            if item is None:
                break
            typ = item[0]
            if typ == "dom":
                _, k, old = item
                dom[k] = old
            elif typ == "row":
                _, r, old = item
                row_used[r] = old
            elif typ == "col":
                _, c, old = item
                col_used[c] = old

    def set_dom(k, newm):
        old = dom[k]
        if old == newm:
            return True
        if newm == 0:
            return False
        trail.append(("dom", k, old))
        dom[k] = newm
        return True

    def assign(r, c, v):
        k = idx(r, c)
        m = bit(v)
        if dom[k] == m:
            return True
        if not (dom[k] & m):
            return False
        # update row/col used if becoming singleton from non-singleton
        if popcount(dom[k]) != 1:
            # record row/col used changes after actual assignment
            pass
        if not set_dom(k, m):
            return False
        # apply row/col used
        if not (row_used[r] & m):
            trail.append(("row", r, row_used[r]))
            row_used[r] |= m
        if not (col_used[c] & m):
            trail.append(("col", c, col_used[c]))
            col_used[c] |= m
        return True

    def is_single(k):
        return dom[k] != 0 and (dom[k] & (dom[k] - 1)) == 0

    def single_value(k):
        return lowest_bit_index(dom[k]) + 1

    # Constraint propagation
    def propagate_queue(initial_cells=None):
        # queue of cells whose domain changed or assigned; process implications
        q = deque()
        inq = [False] * (N * N)
        def enqueue(k):
            if not inq[k]:
                inq[k] = True
                q.append(k)

        if initial_cells is None:
            for k in range(N * N):
                if dom[k] == 0:
                    return False
                enqueue(k)
        else:
            for k in initial_cells:
                if dom[k] == 0:
                    return False
                enqueue(k)

        # For hidden singles scanning triggers
        dirty_rows = set()
        dirty_cols = set()
        for k in range(N * N):
            if inq[k]:
                r, c = divmod(k, N)
                dirty_rows.add(r)
                dirty_cols.add(c)

        while q:
            k = q.popleft()
            inq[k] = False
            r, c = divmod(k, N)
            dirty_rows.add(r)
            dirty_cols.add(c)

            # Row/col elimination based on used masks
            if popcount(dom[k]) != 1:
                newm = dom[k] & ~row_used[r] & ~col_used[c]
                if newm != dom[k]:
                    if not set_dom(k, newm):
                        return False
                    # domain changed, re-enqueue and continue
                    enqueue(k)
                    continue

            # If singleton, eliminate from peers
            if is_single(k):
                v = single_value(k)
                m = bit(v)
                # Ensure row/col used reflect it
                if not (row_used[r] & m):
                    trail.append(("row", r, row_used[r]))
                    row_used[r] |= m
                if not (col_used[c] & m):
                    trail.append(("col", c, col_used[c]))
                    col_used[c] |= m

                # Remove from row peers
                for cc in range(N):
                    if cc == c: continue
                    kk = idx(r, cc)
                    if dom[kk] & m:
                        if popcount(dom[kk]) == 1:
                            return False
                        if not set_dom(kk, dom[kk] & ~m):
                            return False
                        enqueue(kk)

                # Remove from col peers
                for rr in range(N):
                    if rr == r: continue
                    kk = idx(rr, c)
                    if dom[kk] & m:
                        if popcount(dom[kk]) == 1:
                            return False
                        if not set_dom(kk, dom[kk] & ~m):
                            return False
                        enqueue(kk)

            # Adjacency constraints with neighbors
            for (r2, c2) in neighbors[k]:
                k2 = idx(r2, c2)
                dotted = cons[(r, c, r2, c2)]
                d1 = dom[k]
                d2 = dom[k2]
                if d1 == 0 or d2 == 0:
                    return False

                if dotted:
                    # Enforce: for any value in cell, neighbor must have consecutive value
                    # Prune d2 to values that are consecutive to some value in d1
                    allowed2 = 0
                    # Iterate values in d1 and OR their consecutive masks
                    # Optimize by bit iteration
                    for bi in iter_bits(d1):
                        allowed2 |= consmask[bi + 1]
                    newd2 = d2 & allowed2
                    if newd2 != d2:
                        if not set_dom(k2, newd2):
                            return False
                        enqueue(k2)
                    # Symmetric prune d1 using d2
                    allowed1 = 0
                    for bi in iter_bits(dom[k2]):
                        allowed1 |= consmask[bi + 1]
                    newd1 = dom[k] & allowed1
                    if newd1 != dom[k]:
                        if not set_dom(k, newd1):
                            return False
                        enqueue(k)
                else:
                    # Enforce: values are NOT consecutive.
                    # If one side is singleton v, remove v-1,v+1 from other.
                    if is_single(k):
                        v = single_value(k)
                        forbid = consmask[v]
                        if dom[k2] & forbid:
                            newd2 = dom[k2] & ~forbid
                            if newd2 == 0:
                                return False
                            if newd2 != dom[k2]:
                                if not set_dom(k2, newd2):
                                    return False
                                enqueue(k2)
                    if is_single(k2):
                        v2 = single_value(k2)
                        forbid2 = consmask[v2]
                        if dom[k] & forbid2:
                            newd1 = dom[k] & ~forbid2
                            if newd1 == 0:
                                return False
                            if newd1 != dom[k]:
                                if not set_dom(k, newd1):
                                    return False
                                enqueue(k)

            # End processing cell

        # Hidden singles + naked subsets in dirty rows/cols
        def hidden_singles_row(r):
            # For each value, if appears in only one cell domain, assign it
            positions = [0] * N  # store cell index+1 if unique, -1 if multiple, 0 if none yet
            for c in range(N):
                k = idx(r, c)
                m = dom[k]
                for bi in iter_bits(m):
                    if positions[bi] == 0:
                        positions[bi] = k + 1
                    elif positions[bi] > 0:
                        positions[bi] = -1
            for bi, p in enumerate(positions):
                if p > 0:
                    k = p - 1
                    if not is_single(k):
                        if not set_dom(k, 1 << bi):
                            return False
            return True

        def hidden_singles_col(c):
            positions = [0] * N
            for r in range(N):
                k = idx(r, c)
                m = dom[k]
                for bi in iter_bits(m):
                    if positions[bi] == 0:
                        positions[bi] = k + 1
                    elif positions[bi] > 0:
                        positions[bi] = -1
            for bi, p in enumerate(positions):
                if p > 0:
                    k = p - 1
                    if not is_single(k):
                        if not set_dom(k, 1 << bi):
                            return False
            return True

        def naked_subsets_row(r, max_size=3):
            cells = [idx(r, c) for c in range(N) if popcount(dom[idx(r, c)]) > 1]
            # Map mask -> list of cells
            mp = {}
            for k in cells:
                mp.setdefault(dom[k], []).append(k)
            # Naked pairs/triples: if mask size==count and count<=max_size
            for m, ks in mp.items():
                sz = popcount(m)
                if 2 <= sz <= max_size and len(ks) == sz:
                    # eliminate m from other cells in row
                    for c in range(N):
                        kk = idx(r, c)
                        if kk in ks:
                            continue
                        if dom[kk] & m:
                            if popcount(dom[kk]) == 1:
                                return False
                            if not set_dom(kk, dom[kk] & ~m):
                                return False
            return True

        def naked_subsets_col(c, max_size=3):
            cells = [idx(r, c) for r in range(N) if popcount(dom[idx(r, c)]) > 1]
            mp = {}
            for k in cells:
                mp.setdefault(dom[k], []).append(k)
            for m, ks in mp.items():
                sz = popcount(m)
                if 2 <= sz <= max_size and len(ks) == sz:
                    for r in range(N):
                        kk = idx(r, c)
                        if kk in ks:
                            continue
                        if dom[kk] & m:
                            if popcount(dom[kk]) == 1:
                                return False
                            if not set_dom(kk, dom[kk] & ~m):
                                return False
            return True

        # Iterate a few times because hidden singles/naked subsets can cascade
        changed = True
        loop_guard = 0
        while changed and loop_guard < 10:
            loop_guard += 1
            changed = False
            before = None

            # Track whether any domain changed by checking trail length snapshots
            tlen0 = len(trail)
            for r in list(dirty_rows):
                if not hidden_singles_row(r): return False
                if not naked_subsets_row(r): return False
            for c in list(dirty_cols):
                if not hidden_singles_col(c): return False
                if not naked_subsets_col(c): return False
            if len(trail) != tlen0:
                changed = True
                # After bulk changes, need adjacency and row/col propagation again
                # enqueue all changed cells by scanning trail segment (dom changes)
                init = []
                for item in trail[tlen0:]:
                    if item is None:  # shouldn't happen here
                        continue
                    if item[0] == "dom":
                        init.append(item[1])
                if init:
                    if not propagate_queue(init):
                        return False
                # refresh dirty sets
                dirty_rows = set(range(N))
                dirty_cols = set(range(N))
        return True

    # Initial full propagation
    push_state()
    if not propagate_queue():
        undo()
        return "No Solution"
    # remove the initial marker to keep trail consistent for further pushes
    trail.pop()

    def solved():
        return all(is_single(k) for k in range(N * N))

    def select_cell():
        # MRV: smallest domain >1
        best_k = -1
        best_sz = 10**9
        for k in range(N * N):
            sz = popcount(dom[k])
            if sz > 1 and sz < best_sz:
                best_sz = sz
                best_k = k
                if sz == 2:
                    break
        return best_k

    def value_order(k):
        # Prefer values that better fit dotted edges: count of possible consecutive support
        r, c = divmod(k, N)
        vals = []
        for bi in iter_bits(dom[k]):
            v = bi + 1
            score = 0
            for (r2, c2) in neighbors[k]:
                dotted = cons[(r, c, r2, c2)]
                k2 = idx(r2, c2)
                if dotted:
                    score += popcount(dom[k2] & consmask[v])
                else:
                    # prefer values that don't overly restrict neighbor (i.e., forbid set intersects less)
                    score += (N - popcount(dom[k2] & consmask[v]))
            vals.append(( -score, v))
        vals.sort()
        return [v for _, v in vals]

    def dfs():
        if solved():
            return True
        k = select_cell()
        if k < 0:
            return True
        r, c = divmod(k, N)

        for v in value_order(k):
            push_state()
            ok = assign(r, c, v)
            if ok:
                ok = propagate_queue([k])
            if ok and dfs():
                trail.pop()  # remove marker for this level, keep assignments
                return True
            undo()
        return False

    push_state()
    if not dfs():
        undo()
        return "No Solution"
    # successful; remove marker
    trail.pop()

    # Build final grid
    out = []
    for r in range(N):
        row = []
        for c in range(N):
            k = idx(r, c)
            if not is_single(k):
                return "No Solution"
            row.append(single_value(k))
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

