# NOTE: The dot coordinates above are a best-effort parse from the provided image.
# This solver is fully generalized; replace OBSERVATION with a corrected parse if needed.

from collections import deque

def solve(observation):
    grid = observation["data"]
    N = len(grid)
    if N == 0 or any(len(r) != N for r in grid):
        return "No Solution"

    # Build dot adjacency set using integer cell pairs (u,v) undirected.
    # Dots are given at midpoints:
    #   horizontal between (r,c) and (r,c+1) -> (r, c+0.5)
    #   vertical   between (r,c) and (r+1,c) -> (r+0.5, c)
    dot_edges = set()
    for (x, y) in observation.get("adjacent", []):
        # tolerate floats encoded as ints too
        xf = float(x)
        yf = float(y)
        if abs(xf - round(xf)) < 1e-9 and abs((yf * 2) - round(yf * 2)) < 1e-9 and abs(yf - round(yf)) > 1e-9:
            # horizontal
            r = int(round(xf))
            c = int(round(yf - 0.5))
            if 0 <= r < N and 0 <= c < N - 1:
                a = r * N + c
                b = r * N + (c + 1)
                if a > b:
                    a, b = b, a
                dot_edges.add((a, b))
        elif abs(yf - round(yf)) < 1e-9 and abs((xf * 2) - round(xf * 2)) < 1e-9 and abs(xf - round(xf)) > 1e-9:
            # vertical
            r = int(round(xf - 0.5))
            c = int(round(yf))
            if 0 <= r < N - 1 and 0 <= c < N:
                a = r * N + c
                b = (r + 1) * N + c
                if a > b:
                    a, b = b, a
                dot_edges.add((a, b))
        else:
            # ignore malformed
            pass

    # Precompute non-dot orthogonal neighbors for each cell (as pairs for constraints)
    orth_neighbors = [[] for _ in range(N * N)]
    for r in range(N):
        for c in range(N):
            u = r * N + c
            if c + 1 < N:
                v = r * N + (c + 1)
                orth_neighbors[u].append(v)
                orth_neighbors[v].append(u)
            if r + 1 < N:
                v = (r + 1) * N + c
                orth_neighbors[u].append(v)
                orth_neighbors[v].append(u)

    def has_dot(u, v):
        if u > v:
            u, v = v, u
        return (u, v) in dot_edges

    # Domains as bitmasks 1..N => bits 0..N-1
    ALL = (1 << N) - 1

    row_cells = [[r * N + c for c in range(N)] for r in range(N)]
    col_cells = [[r * N + c for r in range(N)] for c in range(N)]

    # Initialize domains with givens
    dom = [ALL] * (N * N)
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                dom[r * N + c] = 1 << (v - 1)

    # Utility
    def bitcount(x):
        return x.bit_count()

    def lowbit_index(x):
        return (x & -x).bit_length() - 1

    def iter_bits(x):
        while x:
            b = x & -x
            yield b.bit_length() - 1
            x ^= b

    def consecutive_mask_for_value(val):
        # val in 1..N
        m = 0
        if val > 1:
            m |= 1 << (val - 2)
        if val < N:
            m |= 1 << (val)
        return m

    # Constraint propagation:
    # 1) Latin: row/col all-different via (a) naked singles elimination, (b) hidden singles,
    #    (c) subset (naked pairs/triples/quads) lightweight.
    # 2) Dot: if dot between u-v => values must be consecutive (abs diff 1).
    #         if no dot between u-v (orth adjacent) => values must not be consecutive.
    #
    # We implement propagation as queue of variables whose domain changed.
    # Additionally, we periodically run higher-level deductions (hidden singles, subsets).

    # Precompute dot constraints list
    dot_pairs = []
    nodot_pairs = []
    for u in range(N * N):
        for v in orth_neighbors[u]:
            if u < v:
                if has_dot(u, v):
                    dot_pairs.append((u, v))
                else:
                    nodot_pairs.append((u, v))

    # Build incident constraint maps
    inc_pairs = [[] for _ in range(N * N)]
    for u, v in dot_pairs:
        inc_pairs[u].append((u, v, True))
        inc_pairs[v].append((u, v, True))
    for u, v in nodot_pairs:
        inc_pairs[u].append((u, v, False))
        inc_pairs[v].append((u, v, False))

    def enforce_edge(u, v, is_dot):
        """Revise domains dom[u], dom[v] for (dot/nodot) constraint. Return True if changed, False if no change, None if contradiction."""
        du = dom[u]
        dv = dom[v]
        if du == 0 or dv == 0:
            return None

        if is_dot:
            # For each candidate in u, v must have adjacent candidate.
            new_du = 0
            for i in iter_bits(du):
                val = i + 1
                if dv & consecutive_mask_for_value(val):
                    new_du |= 1 << i
            new_dv = 0
            for j in iter_bits(dv):
                val = j + 1
                if du & consecutive_mask_for_value(val):
                    new_dv |= 1 << j
            if new_du == 0 or new_dv == 0:
                return None
            changed = (new_du != du) or (new_dv != dv)
            dom[u] = new_du
            dom[v] = new_dv
            return changed
        else:
            # Not consecutive: remove candidates that force consecutive with all possibilities of other.
            # Candidate x in u is invalid if every candidate in v is consecutive to x.
            # Equivalent: keep x if v has at least one candidate NOT consecutive to x.
            new_du = 0
            for i in iter_bits(du):
                val = i + 1
                consec = consecutive_mask_for_value(val)
                if dv & (ALL ^ consec):  # exists non-consecutive candidate
                    new_du |= 1 << i
            new_dv = 0
            for j in iter_bits(dv):
                val = j + 1
                consec = consecutive_mask_for_value(val)
                if du & (ALL ^ consec):
                    new_dv |= 1 << j
            if new_du == 0 or new_dv == 0:
                return None
            changed = (new_du != du) or (new_dv != dv)
            dom[u] = new_du
            dom[v] = new_dv
            return changed

    def apply_latin_basic(queue):
        # If a cell is single, remove from row/col peers.
        while queue:
            u = queue.popleft()
            du = dom[u]
            if du == 0:
                return None
            if bitcount(du) != 1:
                continue
            val_bit = du
            r = u // N
            c = u % N
            # Row peers
            for v in row_cells[r]:
                if v != u and (dom[v] & val_bit):
                    nd = dom[v] & ~val_bit
                    if nd == 0:
                        return None
                    if nd != dom[v]:
                        dom[v] = nd
                        queue.append(v)
            # Col peers
            for v in col_cells[c]:
                if v != u and (dom[v] & val_bit):
                    nd = dom[v] & ~val_bit
                    if nd == 0:
                        return None
                    if nd != dom[v]:
                        dom[v] = nd
                        queue.append(v)
        return True

    def hidden_singles():
        # For each unit (row/col), if a number appears in only one domain, set it.
        changed = False
        for unit in row_cells + col_cells:
            # count appearances
            counts = [0] * N
            lastpos = [-1] * N
            for u in unit:
                d = dom[u]
                for i in iter_bits(d):
                    counts[i] += 1
                    lastpos[i] = u
            for i, cnt in enumerate(counts):
                if cnt == 0:
                    return None
                if cnt == 1:
                    u = lastpos[i]
                    bit = 1 << i
                    if dom[u] != bit:
                        dom[u] = bit
                        changed = True
        return changed

    def naked_subsets_unit(unit, max_k=4):
        # Lightweight naked subsets: find sets of k cells whose union has size k, eliminate from others.
        # Use bucket by domain mask size <= max_k
        changed = False
        cells = [u for u in unit if 1 < bitcount(dom[u]) <= max_k]
        # group by exact mask
        masks = {}
        for u in cells:
            m = dom[u]
            masks.setdefault(m, []).append(u)
        for m, us in masks.items():
            k = bitcount(m)
            if 2 <= k <= max_k and len(us) == k:
                # remove m from all other cells in unit
                for v in unit:
                    if v not in us and (dom[v] & m):
                        nd = dom[v] & ~m
                        if nd == 0:
                            return None
                        if nd != dom[v]:
                            dom[v] = nd
                            changed = True
        return changed

    def enforce_all_edges(queue):
        # AC-3 style over dot/nodot edges using queue of endpoints.
        while queue:
            u = queue.popleft()
            for a, b, is_dot in inc_pairs[u]:
                before_a, before_b = dom[a], dom[b]
                res = enforce_edge(a, b, is_dot)
                if res is None:
                    return None
                if res:
                    if dom[a] != before_a:
                        queue.append(a)
                    if dom[b] != before_b:
                        queue.append(b)
        return True

    def initial_queue():
        q = deque()
        for u in range(N * N):
            q.append(u)
        return q

    def propagate():
        # Iterate: edge AC + latin singles + higher-level deductions until fixpoint.
        q = initial_queue()
        if enforce_all_edges(q) is None:
            return None
        q = initial_queue()
        if apply_latin_basic(q) is None:
            return None

        while True:
            any_change = False
            # Edge tightening from any changes
            q = initial_queue()
            if enforce_all_edges(q) is None:
                return None
            q = initial_queue()
            if apply_latin_basic(q) is None:
                return None

            hs = hidden_singles()
            if hs is None:
                return None
            if hs:
                any_change = True
                q = initial_queue()
                if apply_latin_basic(q) is None:
                    return None

            # Subsets
            for unit in row_cells + col_cells:
                ns = naked_subsets_unit(unit, max_k=4)
                if ns is None:
                    return None
                if ns:
                    any_change = True

            if not any_change:
                break
        return True

    def is_solved():
        return all(bitcount(d) == 1 for d in dom)

    def select_unassigned():
        # MRV with tie-break by degree (more incident edges)
        best = -1
        best_sz = 10**9
        best_deg = -1
        for u in range(N * N):
            sz = bitcount(dom[u])
            if sz > 1 and sz < best_sz:
                best = u
                best_sz = sz
                best_deg = len(inc_pairs[u]) + (2 * N - 2)  # approximate latin peers
            elif sz > 1 and sz == best_sz:
                deg = len(inc_pairs[u]) + (2 * N - 2)
                if deg > best_deg:
                    best = u
                    best_deg = deg
        return best

    def snapshot():
        return dom[:]

    def restore(snap):
        dom[:] = snap

    def dfs():
        if propagate() is None:
            return False
        if is_solved():
            return True
        u = select_unassigned()
        if u < 0:
            return False

        # Value ordering: try candidates that satisfy more dot constraints first (heuristic).
        cand = list(iter_bits(dom[u]))
        def score(i):
            val = i + 1
            s = 0
            for a, b, is_dot in inc_pairs[u]:
                v = b if a == u else a
                dv = dom[v]
                if is_dot:
                    s += bitcount(dv & consecutive_mask_for_value(val))
                else:
                    s += bitcount(dv & (ALL ^ consecutive_mask_for_value(val)))
            return -s
        cand.sort(key=score)

        snap0 = snapshot()
        for i in cand:
            restore(snap0)
            dom[u] = 1 << i
            if dfs():
                return True
        restore(snap0)
        return False

    if not dfs():
        return "No Solution"

    # Build solved grid
    out = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            u = r * N + c
            out[r][c] = lowbit_index(dom[u]) + 1

    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

