# Solver for weighted black-cell selection puzzle:
# - Each cell (r,c) is binary (black or not).
# - Row constraint: sum_{c black in row r} col_weight[c] == row_sum[r]
# - Col constraint: sum_{r black in col c} row_weight[r] == col_sum[c]
#
# Approach (human-like + efficient):
# 1) Precompute all feasible patterns for each row (subset of columns) meeting row target.
# 2) Precompute all feasible patterns for each column (subset of rows) meeting column target.
# 3) Run strong constraint propagation between row/col domains:
#    - For each cell, infer forced 1/0 when all remaining patterns agree.
#    - Remove patterns inconsistent with current cell assignments.
#    - Maintain and propagate column/row residual feasibility quickly.
# 4) If unresolved, perform guided search (branching on most constrained row/col),
#    using propagation at each node (not blind brute force).

from typing import List, Optional, Tuple, Dict

B = 'B'


def _all_subsets_meeting_sum(weights: List[int], target: int) -> List[int]:
    """
    Return list of bitmasks over len(weights) indicating subsets whose weighted sum == target.
    weights length expected small-moderate; uses DP by sum to be efficient.
    """
    n = len(weights)
    # DP: sum -> list of masks achieving sum
    dp: Dict[int, List[int]] = {0: [0]}
    for i, w in enumerate(weights):
        newdp = {s: lst[:] for s, lst in dp.items()}
        for s, masks in dp.items():
            ns = s + w
            if ns > target:
                continue
            nmasks = newdp.get(ns)
            if nmasks is None:
                newdp[ns] = [m | (1 << i) for m in masks]
            else:
                nmasks.extend(m | (1 << i) for m in masks)
        dp = newdp
    return dp.get(target, [])


def _bit_forced(domain_masks: List[int], bit_index: int) -> Optional[int]:
    """
    If all masks in domain have bit_index set => forced 1.
    If all masks have it clear => forced 0.
    Else None.
    """
    if not domain_masks:
        return None
    all_set = True
    all_clear = True
    bit = 1 << bit_index
    for m in domain_masks:
        if m & bit:
            all_clear = False
        else:
            all_set = False
        if not all_set and not all_clear:
            return None
    return 1 if all_set else 0


def _filter_domain_by_cell(domain_masks: List[int], cell_idx: int, val: int) -> List[int]:
    bit = 1 << cell_idx
    if val == 1:
        return [m for m in domain_masks if (m & bit) != 0]
    else:
        return [m for m in domain_masks if (m & bit) == 0]


def _propagate(nr: int, nc: int,
               row_dom: List[List[int]],
               col_dom: List[List[int]],
               grid: List[List[int]]) -> bool:
    """
    Arc-consistency style propagation between row and column domains.
    grid entries: -1 unknown, 0 white, 1 black.
    Returns False on contradiction.
    """
    changed = True
    # For speed, we loop until fixpoint; sizes are typically small.
    while changed:
        changed = False

        # 1) Enforce current grid assignments on domains
        for r in range(nr):
            dom = row_dom[r]
            if not dom:
                return False
            # Apply all known cells in row
            for c in range(nc):
                v = grid[r][c]
                if v == -1:
                    continue
                nd = _filter_domain_by_cell(dom, c, v)
                if len(nd) != len(dom):
                    dom = nd
                    row_dom[r] = dom
                    changed = True
                    if not dom:
                        return False

        for c in range(nc):
            dom = col_dom[c]
            if not dom:
                return False
            for r in range(nr):
                v = grid[r][c]
                if v == -1:
                    continue
                nd = _filter_domain_by_cell(dom, r, v)
                if len(nd) != len(dom):
                    dom = nd
                    col_dom[c] = dom
                    changed = True
                    if not dom:
                        return False

        # 2) Deduce forced cells from row domains
        for r in range(nr):
            dom = row_dom[r]
            if not dom:
                return False
            for c in range(nc):
                if grid[r][c] != -1:
                    continue
                f = _bit_forced(dom, c)
                if f is not None:
                    grid[r][c] = f
                    changed = True

        # 3) Deduce forced cells from column domains
        for c in range(nc):
            dom = col_dom[c]
            if not dom:
                return False
            for r in range(nr):
                if grid[r][c] != -1:
                    continue
                f = _bit_forced(dom, r)
                if f is not None:
                    grid[r][c] = f
                    changed = True

        # 4) Cross-prune: remove row patterns incompatible with column domains (and vice versa)
        #    This is stronger than just checking assigned cells, but still efficient for small boards.
        #    For each row pattern, it implies certain bits in each column domain must be possible.
        for r in range(nr):
            dom = row_dom[r]
            if not dom:
                return False
            new_dom = []
            for mask in dom:
                ok = True
                # Check each column c: if row chooses black at (r,c), then column must allow bit r = 1 somewhere.
                # If row chooses white, column must allow bit r = 0 somewhere.
                for c in range(nc):
                    bit = 1 << r
                    wants = 1 if (mask >> c) & 1 else 0
                    # see if any col pattern supports this bit choice
                    supports = False
                    for cm in col_dom[c]:
                        has = 1 if (cm & bit) else 0
                        if has == wants:
                            supports = True
                            break
                    if not supports:
                        ok = False
                        break
                if ok:
                    new_dom.append(mask)
            if len(new_dom) != len(dom):
                row_dom[r] = new_dom
                changed = True
                if not new_dom:
                    return False

        for c in range(nc):
            dom = col_dom[c]
            if not dom:
                return False
            new_dom = []
            for mask in dom:
                ok = True
                for r in range(nr):
                    bit = 1 << c
                    wants = 1 if (mask >> r) & 1 else 0
                    supports = False
                    for rm in row_dom[r]:
                        has = 1 if (rm & bit) else 0
                        if has == wants:
                            supports = True
                            break
                    if not supports:
                        ok = False
                        break
                if ok:
                    new_dom.append(mask)
            if len(new_dom) != len(dom):
                col_dom[c] = new_dom
                changed = True
                if not new_dom:
                    return False

    return True


def _is_solved(grid: List[List[int]]) -> bool:
    return all(v != -1 for row in grid for v in row)


def _choose_branch(row_dom: List[List[int]], col_dom: List[List[int]], grid: List[List[int]]) -> Tuple[str, int]:
    """
    Choose whether to branch on a row or column domain with smallest >1 size.
    Returns ('r', idx) or ('c', idx). Assumes not solved.
    """
    best_type = 'r'
    best_idx = -1
    best_size = 10**9

    for i, dom in enumerate(row_dom):
        s = len(dom)
        if s > 1 and s < best_size:
            best_size = s
            best_type = 'r'
            best_idx = i
    for j, dom in enumerate(col_dom):
        s = len(dom)
        if s > 1 and s < best_size:
            best_size = s
            best_type = 'c'
            best_idx = j
    return best_type, best_idx


def _deepcopy_state(row_dom, col_dom, grid):
    return [d[:] for d in row_dom], [d[:] for d in col_dom], [row[:] for row in grid]


def _search(nr: int, nc: int, row_dom: List[List[int]], col_dom: List[List[int]], grid: List[List[int]]) -> Optional[List[List[int]]]:
    if not _propagate(nr, nc, row_dom, col_dom, grid):
        return None
    if _is_solved(grid):
        return grid

    t, idx = _choose_branch(row_dom, col_dom, grid)
    if idx < 0:
        return None  # no branching point but not solved => contradiction

    if t == 'r':
        # Try each remaining row pattern, smallest-first heuristic by compatibility with current grid
        patterns = row_dom[idx][:]
        # Order patterns by number of newly decided cells (prefer more informative)
        unknown_cols = [c for c in range(nc) if grid[idx][c] == -1]
        def score(m):
            # higher decided blacks/whites in unknowns does not matter; all decide, but we can bias by rarity:
            return -sum(1 for c in unknown_cols if (m >> c) & 1)
        patterns.sort(key=score)
        for m in patterns:
            rd, cd, g = _deepcopy_state(row_dom, col_dom, grid)
            rd[idx] = [m]
            # Assign row cells from m
            for c in range(nc):
                g[idx][c] = 1 if (m >> c) & 1 else 0
            res = _search(nr, nc, rd, cd, g)
            if res is not None:
                return res
    else:
        patterns = col_dom[idx][:]
        unknown_rows = [r for r in range(nr) if grid[r][idx] == -1]
        def score(m):
            return -sum(1 for r in unknown_rows if (m >> r) & 1)
        patterns.sort(key=score)
        for m in patterns:
            rd, cd, g = _deepcopy_state(row_dom, col_dom, grid)
            cd[idx] = [m]
            for r in range(nr):
                g[r][idx] = 1 if (m >> r) & 1 else 0
            res = _search(nr, nc, rd, cd, g)
            if res is not None:
                return res

    return None


def solve(observation):
    row_w = observation["row_sum"]  # row weights for columns' constraints
    col_w = observation["col_sum"]  # column weights for rows' constraints
    nr = len(row_w)
    nc = len(col_w)

    # Domains:
    # row_dom[r]: bitmask over columns indicating black cells in row r, satisfying row target using column weights.
    # col_dom[c]: bitmask over rows indicating black cells in column c, satisfying col target using row weights.
    row_dom = [_all_subsets_meeting_sum(col_w, row_w[r]) for r in range(nr)]
    col_dom = [_all_subsets_meeting_sum(row_w, col_w[c]) for c in range(nc)]

    if any(len(d) == 0 for d in row_dom) or any(len(d) == 0 for d in col_dom):
        return "No Solution"

    grid = [[-1] * nc for _ in range(nr)]
    sol = _search(nr, nc, row_dom, col_dom, grid)
    if sol is None:
        return "No Solution"

    out = [[(B if sol[r][c] == 1 else None) for c in range(nc)] for r in range(nr)]
    return "\n".join(str(row) for row in out)


