# Masyu-like loop with length-sum clues on circles (white=straight, black=turn).
# Grid: (N+1)x(N+1) dots, clues live in cells between dots: observation['data'] is NxN cells.
# We model each cell with possible loop pattern among its 4 sides (N,E,S,W edges on dot grid).
# Use aggressive constraint propagation + limited backtracking with smallest-domain heuristic.

from collections import deque, defaultdict

DIRS = ['N', 'E', 'S', 'W']
dN = {'N': (-1, 0), 'E': (0, 1), 'S': (1, 0), 'W': (0, -1)}
OPP = {'N': 'S', 'S': 'N', 'E': 'W', 'W': 'E'}

# Pattern bits: which sides have loop edges in this cell.
# Valid local loop occupancy: exactly 0 (unused) or 2 sides (path passes through cell).
PATTERNS = []
for mask in range(16):
    bits = [d for i, d in enumerate(DIRS) if (mask >> i) & 1]
    if len(bits) in (0, 2):
        PATTERNS.append(mask)

def is_straight(mask):
    # exactly 2 opposite sides
    return mask in (0b0101, 0b1010)  # N+S or E+W

def is_turn(mask):
    # exactly 2 adjacent sides
    return mask in (0b0011, 0b0110, 0b1100, 0b1001)

def sides(mask):
    return [d for i, d in enumerate(DIRS) if (mask >> i) & 1]

def mask_has(mask, d):
    return (mask >> DIRS.index(d)) & 1

def set_edge_key(r, c, d):
    # Edge on dot grid: between dots.
    # Represent edge uniquely as (min_dot, max_dot) where dot=(R,C).
    if d == 'N':
        a, b = (r, c), (r, c+1)
    elif d == 'S':
        a, b = (r+1, c), (r+1, c+1)
    elif d == 'W':
        a, b = (r, c), (r+1, c)
    else:  # 'E'
        a, b = (r, c+1), (r+1, c+1)
    return (a, b) if a <= b else (b, a)

def iter_cell_edges(r, c, mask):
    for d in DIRS:
        if mask_has(mask, d):
            yield set_edge_key(r, c, d)

def parse_token(tok):
    if tok is None:
        return None
    t = tok[0]
    k = int(tok[1:])
    return (t, k)

def solve(observation):
    data = observation['data']
    N = len(data)
    M = len(data[0]) if N else 0
    if N == 0 or M == 0 or N != M:
        return "No Solution"
    n = N  # cells are n x n, dots are (n+1)x(n+1)

    # Domains for each cell: set of allowed masks from PATTERNS, plus clue restrictions.
    dom = [[set(PATTERNS) for _ in range(n)] for __ in range(n)]
    clues = [[parse_token(data[r][c]) for c in range(n)] for r in range(n)]

    # Precompute per cell: if clue, restrict to straight/turn and compute possible length pairs.
    # Lengths measured in number of consecutive cells from this circle along the two directions used.
    # For white: directions are opposite; for black: adjacent.
    def max_run_len(r, c, d):
        dr, dc = dN[d]
        rr, cc = r, c
        length = 0
        while True:
            rr += dr
            cc += dc
            if not (0 <= rr < n and 0 <= cc < n):
                break
            length += 1
        return length

    maxlen_dir = [[[max_run_len(r, c, d) for d in DIRS] for c in range(n)] for r in range(n)]

    # For each clue cell, compute allowed direction-pairs given k and type.
    clue_allowed_pairs = [[None]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            cl = clues[r][c]
            if not cl:
                continue
            t, k = cl
            pairs = []
            if t == 'W':
                # opposite pairs: (N,S) or (E,W)
                for a, b in [('N','S'), ('E','W')]:
                    la = maxlen_dir[r][c][DIRS.index(a)]
                    lb = maxlen_dir[r][c][DIRS.index(b)]
                    # actual length variables are >=1 because edge must leave cell along that side if used;
                    # but can be limited by boundary and by other turns/clues; we enforce sum by propagation later.
                    if 1 <= la and 1 <= lb:
                        # possible segment lengths (xa, xb) with xa+xb==k, 1..la and 1..lb
                        poss = []
                        for xa in range(1, la+1):
                            xb = k - xa
                            if 1 <= xb <= lb:
                                poss.append((xa, xb))
                        if poss:
                            pairs.append((a, b, poss))
            else:  # 'B'
                # adjacent pairs
                adj = [('N','E'), ('E','S'), ('S','W'), ('W','N')]
                for a, b in adj:
                    la = maxlen_dir[r][c][DIRS.index(a)]
                    lb = maxlen_dir[r][c][DIRS.index(b)]
                    if 1 <= la and 1 <= lb:
                        poss = []
                        for xa in range(1, la+1):
                            xb = k - xa
                            if 1 <= xb <= lb:
                                poss.append((xa, xb))
                        if poss:
                            pairs.append((a, b, poss))
            if not pairs:
                return "No Solution"
            clue_allowed_pairs[r][c] = pairs

    # Initial restriction per clue on local patterns
    for r in range(n):
        for c in range(n):
            cl = clues[r][c]
            if not cl:
                continue
            t, _ = cl
            if t == 'W':
                dom[r][c] = {m for m in dom[r][c] if is_straight(m)}
            else:
                dom[r][c] = {m for m in dom[r][c] if is_turn(m)}
            if not dom[r][c]:
                return "No Solution"

    # Edge assignments: each cell side implies an edge; neighboring cell shares it.
    # We will propagate via cell domains; explicit edge state optional, but we use it to enforce dot degrees and global loop.
    # Edge state: 0=absent, 1=present, None=unknown
    edges = {}
    # Build all edges keys for the grid
    for r in range(n):
        for c in range(n):
            for d in DIRS:
                edges.setdefault(set_edge_key(r, c, d), None)

    # Map each edge to the incident cell-sides (up to 2)
    edge_inc = defaultdict(list)
    for r in range(n):
        for c in range(n):
            for d in DIRS:
                ek = set_edge_key(r, c, d)
                edge_inc[ek].append((r, c, d))

    # Dot degree constraints: each dot has degree 0 or 2 in the loop.
    dot_inc_edges = defaultdict(list)
    for (a, b) in edges.keys():
        dot_inc_edges[a].append((a, b))
        dot_inc_edges[b].append((a, b))

    # Helper: compute implied edge states from a cell's domain.
    def cell_edge_possibilities(r, c):
        # returns dict d -> (can_be_1, can_be_0)
        res = {}
        for d in DIRS:
            can1 = any(mask_has(m, d) for m in dom[r][c])
            can0 = any(not mask_has(m, d) for m in dom[r][c])
            res[d] = (can1, can0)
        return res

    # Apply edge assignment and prune cell domains accordingly
    def assign_edge(ek, val, q):
        cur = edges[ek]
        if cur is not None:
            return cur == val
        edges[ek] = val
        q.append(('edge', ek))
        # prune incident cells
        for (r, c, d) in edge_inc[ek]:
            newdom = {m for m in dom[r][c] if (mask_has(m, d) == val)}
            if newdom != dom[r][c]:
                dom[r][c] = newdom
                if not newdom:
                    return False
                q.append(('cell', (r, c)))
        return True

    # Enforce from cell domains to edges when fixed
    def propagate_cell_to_edges(r, c, q):
        poss = cell_edge_possibilities(r, c)
        for d, (can1, can0) in poss.items():
            ek = set_edge_key(r, c, d)
            if can1 and not can0:
                if not assign_edge(ek, 1, q):
                    return False
            if can0 and not can1:
                if not assign_edge(ek, 0, q):
                    return False
        return True

    # Dot degree propagation
    def propagate_dot(dot, q):
        inc = dot_inc_edges[dot]
        present = [e for e in inc if edges[e] == 1]
        unknown = [e for e in inc if edges[e] is None]
        if len(present) > 2:
            return False
        if len(present) == 2:
            # others absent
            for e in unknown:
                if not assign_edge(e, 0, q):
                    return False
        # If to reach degree 2, but forced
        if len(present) + len(unknown) < 2:
            # can't ever reach 2; but degree can be 0 too. However if any present then must reach 2.
            if len(present) > 0:
                return False
        if len(present) == 1 and len(unknown) == 1:
            # must take it to make degree 2
            if not assign_edge(unknown[0], 1, q):
                return False
        # If degree cannot be 1 in final; if all edges decided and degree==1 => fail
        if not unknown and len(present) == 1:
            return False
        return True

    # Length-sum clue propagation (human-like): ensure there is a consistent way to place straight runs
    # respecting turns/straights at clue cell only, using current edge possibility information.
    # We implement a bounded "ray" analysis: for each direction from clue cell, compute possible run lengths
    # until first forced turn/boundary by analyzing cells along the line.
    #
    # For a given direction d from (r,c), the run proceeds through consecutive cells in that direction.
    # For a length L to be possible:
    #  - For i=0..L-1 cell along ray must allow passing straight in ray direction (i.e., include edge entering and exiting)
    #  - At step L, the path must not continue straight further in that direction (either boundary or forced not-straight / edge absent).
    # We'll compute min/max feasible lengths and possible lengths set (small) by scanning until blocked.
    def ray_possible_lengths(r, c, d):
        dr, dc = dN[d]
        # Entry/exit sides for a cell on ray:
        # moving in direction d means within each traversed cell, we need both sides along that axis:
        # if d is N or S -> need N and S; if E or W -> need E and W
        axis_sides = ('N', 'S') if d in ('N', 'S') else ('E', 'W')

        lengths = []
        rr, cc = r, c
        L = 0
        while True:
            rr += dr
            cc += dc
            if not (0 <= rr < n and 0 <= cc < n):
                break
            L += 1
            # must be possible to have straight-through along axis in this cell
            ok_through = False
            for m in dom[rr][cc]:
                if mask_has(m, axis_sides[0]) and mask_has(m, axis_sides[1]):
                    # also must not include the perpendicular sides? not necessary; but local patterns are 0 or 2,
                    # so having both axis sides means exactly straight.
                    ok_through = True
                    break
            if not ok_through:
                break
            # also need the connecting edge between previous and this cell along d to be possibly present
            # This is ensured by domain but add check via edge states along boundary between cells:
            # edge on border between cells depends on direction:
            if d == 'N':
                ek = set_edge_key(rr, cc, 'S')
            elif d == 'S':
                ek = set_edge_key(rr-1, cc, 'S')
            elif d == 'W':
                ek = set_edge_key(rr, cc, 'E')
            else:  # E
                ek = set_edge_key(rr, cc-1, 'E')
            if edges[ek] == 0:
                break
            lengths.append(L)
            # If edge ahead is forced absent or next cell cannot allow through, then L might be terminal;
            # terminal condition handled in clue pair feasibility by allowing stop at L even if could continue,
            # but we can prune using forced-continuation:
        return set(lengths)

    def propagate_clue(r, c, q):
        cl = clues[r][c]
        if not cl:
            return True
        t, k = cl
        pairs = clue_allowed_pairs[r][c]
        # Restrict based on which direction pair is still possible with current domains/edges.
        possible_masks = set()
        valid_any = False

        # Precompute ray lengths sets
        raylens = {d: ray_possible_lengths(r, c, d) for d in DIRS}

        for a, b, poss in pairs:
            # Check if local mask can realize using sides a and b (straight or turn already ensured)
            local_masks = {m for m in dom[r][c] if mask_has(m, a) and mask_has(m, b)}
            if not local_masks:
                continue
            # Now length feasibility:
            la_set = raylens[a]
            lb_set = raylens[b]
            feasible = False
            for xa, xb in poss:
                if xa in la_set and xb in lb_set:
                    feasible = True
                    break
            if feasible:
                valid_any = True
                possible_masks |= local_masks

        if not valid_any:
            return False
        if possible_masks != dom[r][c]:
            dom[r][c] = possible_masks
            q.append(('cell', (r, c)))
        return True

    # Queue-based propagation
    def propagate(q):
        while q:
            typ, obj = q.popleft()
            if typ == 'cell':
                r, c = obj
                if not propagate_cell_to_edges(r, c, q):
                    return False
                # clue propagation around this cell and itself
                if not propagate_clue(r, c, q):
                    return False
                # Neighbor clues along same row/col can be affected; push nearby in cross
                for rr in range(max(0, r-1), min(n, r+2)):
                    for cc in range(max(0, c-1), min(n, c+2)):
                        if clues[rr][cc]:
                            q.append(('clue', (rr, cc)))
            elif typ == 'edge':
                ek = obj
                # propagate dot degrees
                a, b = ek
                if not propagate_dot(a, q):
                    return False
                if not propagate_dot(b, q):
                    return False
                # also affect clue rays: push all clue cells in same row/col within distance because edge can block ray.
                # Lightweight: just enqueue all clues (still small)
                # We'll mark them via q as 'clue' to avoid full cell processing.
                pass
            elif typ == 'clue':
                r, c = obj
                if not propagate_clue(r, c, q):
                    return False
        return True

    # Initialize propagation
    q = deque()
    for r in range(n):
        for c in range(n):
            q.append(('cell', (r, c)))
    if not propagate(q):
        return "No Solution"

    # Backtracking with MRV on cell domains, plus early global-loop checks.
    def snapshot():
        return ([ [set(dom[r][c]) for c in range(n)] for r in range(n) ], dict(edges))

    def restore(snap):
        ddom, dedges = snap
        for r in range(n):
            for c in range(n):
                dom[r][c] = set(ddom[r][c])
        edges.clear()
        edges.update(dedges)

    # Check if fully decided and forms single cycle through all clue cells
    def build_graph_and_check():
        # all edges must be decided
        if any(v is None for v in edges.values()):
            return None
        used_edges = [e for e, v in edges.items() if v == 1]
        if not used_edges:
            return False
        # degree check already enforced, but verify and connectivity/single cycle
        adj = defaultdict(list)
        for a, b in used_edges:
            adj[a].append(b)
            adj[b].append(a)
        for dot, nbrs in adj.items():
            if len(nbrs) != 2:
                return False
        # single cycle: traverse from any node
        start = next(iter(adj))
        seen = set()
        cur, prev = start, None
        while True:
            seen.add(cur)
            nxts = adj[cur]
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            prev, cur = cur, nxt
            if cur == start:
                break
            if cur in seen:
                return False
        if len(seen) != len(adj):
            return False
        # ensure all clue cells are used (non-zero pattern)
        for r in range(n):
            for c in range(n):
                if clues[r][c]:
                    # in a decided solution, the cell must have 2 sides (since clue must be on loop)
                    if all(m == 0 for m in dom[r][c]):
                        return False
        return True

    def partial_no_small_cycles():
        # prevent formation of closed cycle before all forced edges determined (classic loop puzzle pruning).
        # If a cycle exists in current decided-present edges with all its vertices degree 2 (with unknowns absent),
        # and there exists any other present edge outside, fail. Hard to do perfectly; do a conservative check:
        # If there is a cycle component where every vertex currently has degree 2 using decided-present edges,
        # and there exists any clue cell not yet definitely on this component, we prune.
        used = [e for e, v in edges.items() if v == 1]
        if not used:
            return True
        adj = defaultdict(list)
        for a, b in used:
            adj[a].append(b)
            adj[b].append(a)
        seen = set()
        comps = []
        for v in adj:
            if v in seen:
                continue
            stack = [v]
            comp = set()
            while stack:
                x = stack.pop()
                if x in comp:
                    continue
                comp.add(x)
                for y in adj[x]:
                    if y not in comp:
                        stack.append(y)
            seen |= comp
            comps.append(comp)
        if len(comps) <= 1:
            return True
        # Multiple components with present edges can't happen in a single loop; but they might connect via unknown edges later.
        # We allow it, but if any component is already a closed cycle (all degrees 2 and no incident unknown edges),
        # then it can never connect, so fail unless it's the only component.
        for comp in comps:
            closed = True
            for v in comp:
                if len(adj[v]) != 2:
                    closed = False
                    break
                # any unknown edge incident would allow connection (degree would become >2, impossible), so actually unknown can't connect.
                # connection requires an edge between a vertex in comp and outside, but that would increase degree >2, impossible.
                # Therefore, if comp is a cycle, it is permanently closed.
            if closed:
                return False
        return True

    # Choose next cell to branch: smallest domain >1; prefer clue cells.
    def pick_cell():
        best = None
        best_sz = 10**9
        for r in range(n):
            for c in range(n):
                sz = len(dom[r][c])
                if sz > 1:
                    score = sz
                    if clues[r][c]:
                        score -= 0.5
                    if score < best_sz:
                        best_sz = score
                        best = (r, c)
        return best

    def dfs():
        chk = build_graph_and_check()
        if chk is True:
            return True
        if chk is False:
            return False
        if not partial_no_small_cycles():
            return False

        cell = pick_cell()
        if cell is None:
            return False
        r, c = cell
        # Value ordering: try patterns that include more forced edges around clues
        candidates = list(dom[r][c])
        candidates.sort(key=lambda m: (-len(sides(m)), m))
        snap = snapshot()
        for m in candidates:
            restore(snap)
            dom[r][c] = {m}
            q = deque([('cell', (r, c))])
            if propagate(q):
                if dfs():
                    return True
        restore(snap)
        return False

    if not dfs():
        return "No Solution"

    # Reconstruct loop as ordered dot path
    used_edges = [e for e, v in edges.items() if v == 1]
    adj = defaultdict(list)
    for a, b in used_edges:
        adj[a].append(b)
        adj[b].append(a)
    start = min(adj.keys())
    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = adj[cur]
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
    return str(path)

