from __future__ import annotations

from dataclasses import dataclass
from typing import List, Tuple, Optional, Dict, Set
import math


# Solver for "The Longest Path / Straight Line Sum loop" variant:
# - Single closed loop on dot grid (edges between adjacent dots).
# - Clues are in cells; loop passes through clue cells.
#   White: straight through cell, Black: turn in cell.
# - Number k: sum of lengths of the two straight segments extending from that cell along the loop.
#
# We model:
# - Dots: (r,c), r,c in [0..N]
# - Edges between adjacent dots (horizontal/vertical) are decision vars (0/1 in loop).
# - Each cell (r,c), 0<=r,c<N has four boundary edges. If loop passes through cell, it uses exactly 2 edges.
#   The 2 edges must be opposite (straight) for white, adjacent (turn) for black.
# - Additionally, the "ray lengths" for clue cell: if the loop uses, say, left+right (horizontal),
#   then from this cell the straight segment extends left through consecutive horizontally-straight cells until
#   a turning cell is encountered; similarly to the right. Sum of these segment lengths (in cells) equals k.
#
# Human-like deduction:
# - Maintain allowed local patterns per clue cell based on straight/turn.
# - Propagate to edges; enforce dot degrees 0 or 2, and global single-cycle via DSU with subtour prevention.
# - Use segment-length constraints via incremental "ray" reasoning: from a clue, rays must continue straight
#   until a turn cell stops it; we derive bounds and force continuations when k is tight.
# - Employ MRV branching only when needed; aggressively apply deterministic propagation between branches.


DIRS = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # E,S,W,N
E, S, W, N = 0, 1, 2, 3


def is_black(tok: str) -> bool:
    return tok and tok[0] == "B"


def is_white(tok: str) -> bool:
    return tok and tok[0] == "W"


def tok_num(tok: str) -> int:
    return int(tok[1:])


@dataclass(frozen=True)
class Edge:
    # undirected edge between two adjacent dots, canonical order
    a: Tuple[int, int]
    b: Tuple[int, int]

    @staticmethod
    def make(u: Tuple[int, int], v: Tuple[int, int]) -> "Edge":
        return Edge(u, v) if u <= v else Edge(v, u)


class DSU:
    __slots__ = ("p", "r", "sz")

    def __init__(self, n: int):
        self.p = list(range(n))
        self.r = [0] * n
        self.sz = [1] * n

    def find(self, x: int) -> int:
        p = self.p
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def union(self, a: int, b: int) -> int:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return ra
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        self.sz[ra] += self.sz[rb]
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1
        return ra

    def size(self, x: int) -> int:
        return self.sz[self.find(x)]


class Contradiction(Exception):
    pass


class State:
    __slots__ = (
        "N",
        "data",
        "edge_val",
        "dot_deg",
        "dot_inc_edges",
        "cell_edges",
        "cell_pat_allow",
        "dot_index",
        "index_dot",
        "dsu",
        "active_dots_count",
        "chosen_edges_count",
    )

    def __init__(self, data: List[List[Optional[str]]]):
        self.N = len(data)
        self.data = data

        # Map dots to indices for DSU
        self.dot_index: Dict[Tuple[int, int], int] = {}
        self.index_dot: List[Tuple[int, int]] = []
        idx = 0
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                self.dot_index[(r, c)] = idx
                self.index_dot.append((r, c))
                idx += 1

        self.dsu = DSU((self.N + 1) * (self.N + 1))

        # Edge variables
        self.edge_val: Dict[Edge, int] = {}  # -1 unknown, 0 off, 1 on
        self.dot_deg: List[int] = [0] * ((self.N + 1) * (self.N + 1))
        self.dot_inc_edges: Dict[Tuple[int, int], List[Edge]] = {}

        # Build all possible grid edges
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                u = (r, c)
                inc = []
                if c + 1 <= self.N:
                    inc.append(Edge.make(u, (r, c + 1)))
                if r + 1 <= self.N:
                    inc.append(Edge.make(u, (r + 1, c)))
                if c - 1 >= 0:
                    inc.append(Edge.make(u, (r, c - 1)))
                if r - 1 >= 0:
                    inc.append(Edge.make(u, (r - 1, c)))
                # Keep only unique by canonical Edge, but list can include duplicates due to both directions; filter
                uniq = []
                seen = set()
                for e in inc:
                    if e not in seen:
                        seen.add(e)
                        uniq.append(e)
                self.dot_inc_edges[u] = uniq

        # Initialize all edges unknown
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                u = (r, c)
                if c + 1 <= self.N:
                    self.edge_val[Edge.make(u, (r, c + 1))] = -1
                if r + 1 <= self.N:
                    self.edge_val[Edge.make(u, (r + 1, c))] = -1

        # Cell boundary edges: cell (r,c) has 4 boundary edges between its corner dots
        self.cell_edges: Dict[Tuple[int, int], Dict[str, Edge]] = {}
        for r in range(self.N):
            for c in range(self.N):
                tl = (r, c)
                tr = (r, c + 1)
                bl = (r + 1, c)
                br = (r + 1, c + 1)
                self.cell_edges[(r, c)] = {
                    "T": Edge.make(tl, tr),
                    "B": Edge.make(bl, br),
                    "L": Edge.make(tl, bl),
                    "R": Edge.make(tr, br),
                }

        # Allowed patterns per cell:
        # each pattern is a tuple of boundary labels used by the loop in that cell (exactly two edges)
        # Straight patterns: (L,R) or (T,B)
        # Turn patterns: four corners: (T,R),(R,B),(B,L),(L,T)
        self.cell_pat_allow: Dict[Tuple[int, int], Set[Tuple[str, str]]] = {}
        for r in range(self.N):
            for c in range(self.N):
                tok = data[r][c]
                if tok is None:
                    pats = {("L", "R"), ("T", "B"), ("T", "R"), ("R", "B"), ("B", "L"), ("L", "T")}
                elif is_white(tok):
                    pats = {("L", "R"), ("T", "B")}
                else:
                    pats = {("T", "R"), ("R", "B"), ("B", "L"), ("L", "T")}
                # normalize ordering within pattern
                norm = set()
                for a, b in pats:
                    norm.add((a, b) if a < b else (b, a))
                self.cell_pat_allow[(r, c)] = norm

        self.active_dots_count = 0
        self.chosen_edges_count = 0

    def clone(self) -> "State":
        s = State(self.data)
        s.edge_val = self.edge_val.copy()
        s.dot_deg = self.dot_deg[:]  # degrees due to chosen edges
        s.cell_pat_allow = {k: v.copy() for k, v in self.cell_pat_allow.items()}
        s.dsu.p = self.dsu.p[:]
        s.dsu.r = self.dsu.r[:]
        s.dsu.sz = self.dsu.sz[:]
        s.active_dots_count = self.active_dots_count
        s.chosen_edges_count = self.chosen_edges_count
        return s

    def edge_get(self, e: Edge) -> int:
        return self.edge_val[e]

    def edge_set(self, e: Edge, val: int):
        cur = self.edge_val[e]
        if cur == val:
            return
        if cur != -1 and cur != val:
            raise Contradiction("Edge conflict")
        self.edge_val[e] = val
        if val == 1:
            ia = self.dot_index[e.a]
            ib = self.dot_index[e.b]
            self.dot_deg[ia] += 1
            self.dot_deg[ib] += 1
            self.chosen_edges_count += 1
            # union for connectivity tracking
            self.dsu.union(ia, ib)

    def iter_cell_patterns(self, cell: Tuple[int, int]) -> List[Tuple[str, str]]:
        return list(self.cell_pat_allow[cell])

    def restrict_cell_patterns(self, cell: Tuple[int, int], allowed: Set[Tuple[str, str]]):
        cur = self.cell_pat_allow[cell]
        new = cur & allowed
        if not new:
            raise Contradiction("No patterns for cell")
        if new != cur:
            self.cell_pat_allow[cell] = new

    def cell_used_edges_must(self, cell: Tuple[int, int]) -> Tuple[Set[str], Set[str]]:
        # Returns (must_on_labels, must_off_labels) based on current patterns.
        pats = self.cell_pat_allow[cell]
        labels = {"T", "B", "L", "R"}
        must_on = set(labels)
        must_off = set(labels)
        for a, b in pats:
            used = {a, b}
            must_on &= used
            must_off &= (labels - used)
        return must_on, must_off


def solve(observation):
    data = observation["data"]
    N = len(data)

    # Quick sanity: require square data
    for row in data:
        if len(row) != N:
            return "No Solution"

    st = State(data)

    def propagate(st: State):
        changed = True
        while changed:
            changed = False

            # 1) Cell pattern -> edge constraints and edge constraints -> cell pattern filtering
            for r in range(N):
                for c in range(N):
                    cell = (r, c)
                    cedges = st.cell_edges[cell]

                    # Filter patterns based on fixed edges
                    if len(st.cell_pat_allow[cell]) > 1:
                        allowed = set()
                        for a, b in st.cell_pat_allow[cell]:
                            ok = True
                            for lab in ("T", "B", "L", "R"):
                                e = cedges[lab]
                                ev = st.edge_get(e)
                                if ev == 1 and lab not in (a, b):
                                    ok = False
                                    break
                                if ev == 0 and lab in (a, b):
                                    ok = False
                                    break
                            if ok:
                                allowed.add((a, b))
                        if not allowed:
                            raise Contradiction("Cell patterns wiped")
                        if allowed != st.cell_pat_allow[cell]:
                            st.cell_pat_allow[cell] = allowed
                            changed = True

                    must_on, must_off = st.cell_used_edges_must(cell)
                    for lab in must_on:
                        e = cedges[lab]
                        if st.edge_get(e) == -1:
                            st.edge_set(e, 1)
                            changed = True
                    for lab in must_off:
                        e = cedges[lab]
                        if st.edge_get(e) == -1:
                            st.edge_set(e, 0)
                            changed = True

            # 2) Dot degree constraints: degree is 0 or 2 in final loop; enforce via bounds
            for dot, inc in st.dot_inc_edges.items():
                idx = st.dot_index[dot]
                deg = st.dot_deg[idx]
                if deg > 2:
                    raise Contradiction("Dot degree >2")
                unknown = []
                on = deg
                off = 0
                for e in inc:
                    v = st.edge_get(e)
                    if v == -1:
                        unknown.append(e)
                    elif v == 0:
                        off += 1
                # If already degree 2, remaining incident edges must be 0
                if on == 2:
                    for e in unknown:
                        st.edge_set(e, 0)
                        changed = True
                # If degree 1 and only one unknown left, it must be 1 to reach degree 2
                # But note dot can be degree 0 as well; however if any incident edge is on, dot must become degree 2.
                # So if on==1, we must pick exactly one more.
                if on == 1:
                    if len(unknown) == 0:
                        raise Contradiction("Dangling degree 1")
                    if len(unknown) == 1:
                        st.edge_set(unknown[0], 1)
                        changed = True
                # If on==0 and only two possible edges can be on? can't force.

            # 3) Clue segment-length propagation (bounds and forced continuation)
            # Compute local orientation for a clue cell if determined, then apply k constraints as bounds on ray lengths.
            for r in range(N):
                for c in range(N):
                    tok = data[r][c]
                    if tok is None:
                        continue
                    cell = (r, c)
                    pats = st.cell_pat_allow[cell]
                    if len(pats) == 1:
                        (a, b) = next(iter(pats))
                        # Determine direction of straight-through at this cell:
                        # if a,b are opposite -> straight (white), else turn (black). Orientation for rays uses the two
                        # directions that the loop exits the cell along its path; regardless of turn/straight, each exit
                        # has a direction among L/R/T/B.
                        exits = [a, b]

                        # Each exit contributes a ray length: number of consecutive cells (including current cell)
                        # in that direction that remain straight along that axis until first turn occurs.
                        # For a turn cell, rays are along the two different axes; for straight cell, both rays same axis.
                        k = tok_num(tok)

                        def axis_of(lab: str) -> int:
                            return 0 if lab in ("L", "R") else 1  # 0 horiz, 1 vert

                        # For each exit, compute min/max possible ray length given current pattern domains.
                        # Ray length counts cells starting at current cell as 1 then extend while next cell continues straight along axis.
                        # Stop when:
                        # - boundary reached
                        # - next cell cannot support straight continuation from that side along same axis
                        # - or forced turn breaks.
                        def ray_bounds_from(cell_rc: Tuple[int, int], dir_lab: str) -> Tuple[int, int, List[Tuple[int, int]]]:
                            rr, cc = cell_rc
                            ax = axis_of(dir_lab)
                            step = {
                                "L": (0, -1),
                                "R": (0, 1),
                                "T": (-1, 0),
                                "B": (1, 0),
                            }[dir_lab]
                            # mapping: entering next cell from opposite side
                            opp = {"L": "R", "R": "L", "T": "B", "B": "T"}[dir_lab]

                            # collect cells along ray excluding start; for forcing decisions later
                            path_cells = []
                            # current cell counts as 1
                            minlen = 1
                            maxlen = 1
                            cur_r, cur_c = rr, cc
                            while True:
                                nr, nc = cur_r + step[0], cur_c + step[1]
                                if not (0 <= nr < N and 0 <= nc < N):
                                    break
                                ncell = (nr, nc)
                                path_cells.append(ncell)
                                # For continuation, in ncell the loop must use the incoming side 'opp'
                                # and also continue out the opposite side on same axis (straight through on that axis).
                                if ax == 0:
                                    needed = tuple(sorted((opp, "L" if opp == "R" else "R")))
                                else:
                                    needed = tuple(sorted((opp, "T" if opp == "B" else "B")))
                                patsn = st.cell_pat_allow[ncell]
                                can_continue = needed in patsn
                                # Determine if forced continue (only patterns that include opp must be needed)
                                can_have_in = any(opp in p for p in patsn)
                                if not can_have_in:
                                    # loop cannot enter next cell from this side => ray stops before it
                                    path_cells.pop()
                                    break
                                if can_continue:
                                    # min may increase only if all patterns that include opp also continue straight
                                    must_continue = True
                                    for p in patsn:
                                        if opp in p and p != needed:
                                            must_continue = False
                                            break
                                    maxlen += 1
                                    if must_continue:
                                        minlen += 1
                                        cur_r, cur_c = nr, nc
                                        continue
                                    else:
                                        # could stop here by turning in next cell
                                        cur_r, cur_c = nr, nc
                                        # but can't guarantee min beyond current
                                        break
                                else:
                                    # cannot continue straight in that cell; so ray length ends at current cell
                                    path_cells.pop()
                                    break
                            return minlen, maxlen, path_cells

                        bounds = []
                        for ex in exits:
                            mn, mx, cells_line = ray_bounds_from(cell, ex)
                            bounds.append((ex, mn, mx, cells_line))

                        # Apply sum constraint bounds
                        sum_min = bounds[0][1] + bounds[1][1]
                        sum_max = bounds[0][2] + bounds[1][2]
                        if k < sum_min or k > sum_max:
                            raise Contradiction("k out of bounds")

                        # Forced extensions when tight:
                        # If we need at least t cells on a ray, force straight continuation in the first (t-1) next cells.
                        # Compute required minimum for each ray given other ray max.
                        for i in range(2):
                            ex, mn, mx, cells_line = bounds[i]
                            other_max = bounds[1 - i][2]
                            req = max(mn, k - other_max)
                            # req is minimal length needed on this ray
                            # Force continuation through first (req-1) next cells.
                            need_steps = req - 1
                            if need_steps > 0:
                                # along this ray, each next cell must have straight-through pattern on same axis including incoming side
                                ax = axis_of(ex)
                                stepcells = cells_line[:need_steps]
                                # Determine required straight pattern in each stepcell based on direction
                                opp = {"L": "R", "R": "L", "T": "B", "B": "T"}[ex]
                                for sc in stepcells:
                                    patsn = st.cell_pat_allow[sc]
                                    if ax == 0:
                                        needed = tuple(sorted((opp, "L" if opp == "R" else "R")))
                                    else:
                                        needed = tuple(sorted((opp, "T" if opp == "B" else "B")))
                                    if needed not in patsn:
                                        raise Contradiction("Cannot force straight continuation")
                                    if len(patsn) != 1:
                                        st.restrict_cell_patterns(sc, {needed})
                                        changed = True

                        # Forced stopping when tight on max:
                        # If this ray cannot exceed req_max, constrain the first next cell (at position req_max) to NOT continue straight.
                        for i in range(2):
                            ex, mn, mx, cells_line = bounds[i]
                            other_min = bounds[1 - i][1]
                            allow_max = min(mx, k - other_min)  # this ray length must be <= allow_max
                            if allow_max < mx:
                                # We must prevent continuation beyond allow_max.
                                # If allow_max == 1, prevent entering next cell from this side at all (force edge off) is too strong;
                                # instead prevent the next cell from having the straight-continuation pattern, if it can be entered.
                                pos = allow_max  # number of cells along ray including start; next cell index is pos-1 in cells_line
                                if pos - 1 < len(cells_line) and pos >= 1:
                                    block_cell = cells_line[pos - 1]
                                    ax = axis_of(ex)
                                    opp = {"L": "R", "R": "L", "T": "B", "B": "T"}[ex]
                                    if ax == 0:
                                        needed = tuple(sorted((opp, "L" if opp == "R" else "R")))
                                    else:
                                        needed = tuple(sorted((opp, "T" if opp == "B" else "B")))
                                    patsn = st.cell_pat_allow[block_cell]
                                    if needed in patsn and len(patsn) > 1:
                                        st.restrict_cell_patterns(block_cell, set(patsn) - {needed})
                                        changed = True

            # 4) Subtour prevention (human-like): if an edge would close a cycle before all required dots are connected, forbid it.
            # Determine required dots: dots incident to any ON edge must be in same component; also loop must be single.
            # We'll implement simple: if setting an unknown edge ON would connect two dots in same component AND there exist
            # any other dot with degree>0 outside that component, then that edge must be OFF.
            # Additionally, if it would create a small cycle with all degrees 2 in that component but not all edges decided, off.
            # This is a heuristic but powerful.
            comps_with_activity = {}
            active_roots = set()
            for i, deg in enumerate(st.dot_deg):
                if deg > 0:
                    root = st.dsu.find(i)
                    active_roots.add(root)
                    comps_with_activity[root] = comps_with_activity.get(root, 0) + 1

            if len(active_roots) >= 2:
                for e, v in list(st.edge_val.items()):
                    if v != -1:
                        continue
                    ia = st.dot_index[e.a]
                    ib = st.dot_index[e.b]
                    ra = st.dsu.find(ia)
                    rb = st.dsu.find(ib)
                    if ra == rb and (ra in active_roots) and len(active_roots) > 1:
                        st.edge_set(e, 0)
                        changed = True

        return st

    def is_complete(st: State) -> bool:
        # all edges decided in cells? Actually loop can omit many edges; completion criteria:
        # - every dot degree is 0 or 2, and all clue cells have exactly one pattern remaining (thus exactly 2 edges used)
        # - all ON edges form a single cycle (one component) and no dangling.
        for d in st.dot_deg:
            if d not in (0, 2):
                return False
        for r in range(N):
            for c in range(N):
                tok = data[r][c]
                if tok is not None and len(st.cell_pat_allow[(r, c)]) != 1:
                    return False
        # ensure every clue cell is "passed through": guaranteed by pattern having 2 edges; but must ensure edges are ON.
        # since we force must_on based on singleton pattern, should be.
        # Single cycle check: gather dots with deg 2
        dots = [i for i, d in enumerate(st.dot_deg) if d == 2]
        if not dots:
            return False
        root = st.dsu.find(dots[0])
        if any(st.dsu.find(i) != root for i in dots):
            return False
        # edges count in cycle: E = V (for single cycle component with all deg2)
        # count edges ON within component
        on_edges = 0
        for e, v in st.edge_val.items():
            if v == 1:
                ia = st.dot_index[e.a]
                if st.dot_deg[ia] == 2 and st.dsu.find(ia) == root:
                    on_edges += 1
        if on_edges != len(dots):
            return False
        return True

    def pick_branch(st: State):
        # MRV: pick a cell with smallest >1 pattern domain, else pick an unknown edge incident to active area
        best_cell = None
        best_sz = 10**9
        for r in range(N):
            for c in range(N):
                sz = len(st.cell_pat_allow[(r, c)])
                if 1 < sz < best_sz and data[r][c] is not None:
                    best_sz = sz
                    best_cell = (r, c)
        if best_cell is not None:
            return ("cell", best_cell)
        for r in range(N):
            for c in range(N):
                sz = len(st.cell_pat_allow[(r, c)])
                if 1 < sz < best_sz:
                    best_sz = sz
                    best_cell = (r, c)
        if best_cell is not None and best_sz <= 3:
            return ("cell", best_cell)

        # Edge branching: prefer edges in boundary of clue cells
        best_edge = None
        for r in range(N):
            for c in range(N):
                if data[r][c] is None:
                    continue
                for e in st.cell_edges[(r, c)].values():
                    if st.edge_get(e) == -1:
                        best_edge = e
                        break
                if best_edge:
                    break
            if best_edge:
                break
        if best_edge:
            return ("edge", best_edge)

        for e, v in st.edge_val.items():
            if v == -1:
                return ("edge", e)
        return None

    def dfs(st: State, depth: int = 0) -> Optional[List[Tuple[int, int]]]:
        try:
            propagate(st)
        except Contradiction:
            return None

        if is_complete(st):
            return build_loop_path(st)

        choice = pick_branch(st)
        if choice is None:
            return None
        kind, obj = choice

        if kind == "cell":
            cell = obj
            pats = list(st.cell_pat_allow[cell])
            # Branch on patterns
            for p in pats:
                st2 = st.clone()
                try:
                    st2.restrict_cell_patterns(cell, {p})
                    res = dfs(st2, depth + 1)
                    if res is not None:
                        return res
                except Contradiction:
                    continue
            return None
        else:
            e = obj
            # try ON then OFF (ON often more constraining)
            for val in (1, 0):
                st2 = st.clone()
                try:
                    st2.edge_set(e, val)
                    res = dfs(st2, depth + 1)
                    if res is not None:
                        return res
                except Contradiction:
                    continue
            return None

    def build_loop_path(st: State) -> List[Tuple[int, int]]:
        # Reconstruct ordered cycle from ON edges.
        adj: Dict[Tuple[int, int], List[Tuple[int, int]]] = {}
        for e, v in st.edge_val.items():
            if v == 1:
                adj.setdefault(e.a, []).append(e.b)
                adj.setdefault(e.b, []).append(e.a)
        start = None
        for dot, nbrs in adj.items():
            if len(nbrs) == 2:
                start = dot
                break
        if start is None:
            raise Contradiction("No cycle")

        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > (N + 1) * (N + 1) * 2:
                raise Contradiction("Cycle too long")
        return path

    ans = dfs(st)
    if ans is None:
        return "No Solution"
    return str(ans)


