OBSERVATION = {'data': [['B3', None, None, 'B5', 'W2', None], [None, None, None, None, 'B3', None], ['B2', None, None, None, None, None], [None, None, None, None, None, None], [None, 'B2', None, 'B2', None, 'B2'], ['B3', None, None, None, None, None]]}
# Masyu-like loop with numbered circles:
# - Single closed loop on dot grid edges (orthogonal), no crossings/branches.
# - Must pass through all clue circles (located at dot positions in observation grid):
#   * Wk: loop goes straight at the circle; sum of lengths of the two straight rays from the circle equals k.
#   * Bk: loop turns at the circle; sum of lengths of the two straight rays from the circle (along the outgoing directions) equals k.
#
# This solver:
# - Models each undirected edge between adjacent dots as a boolean (in/out of loop).
# - Degree constraints at each dot: 0 or 2, and globally all used edges form exactly one cycle.
# - For each clue, enforces straight/turn locally, and numbered "ray length" constraints with aggressive propagation:
#   For each clue, for each of its two outgoing directions, defines a ray length = number of consecutive used edges
#   continuing straight until a turn or endpoint (degree!=2) is encountered.
#   Uses bounds reasoning and early pruning; exact lengths are resolved as edges get fixed.
#
# NOTE: No external SAT/ILP solvers are used. Search is guided by deduction + MRV branching.
from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass
from typing import Dict, List, Optional, Set, Tuple, Iterable

Coord = Tuple[int, int]
Edge = Tuple[Coord, Coord]


def _norm_edge(a: Coord, b: Coord) -> Edge:
    return (a, b) if a <= b else (b, a)


def _neighbors_dot(r: int, c: int, R: int, C: int) -> List[Coord]:
    out = []
    if r > 0:
        out.append((r - 1, c))
    if r < R:
        out.append((r + 1, c))
    if c > 0:
        out.append((r, c - 1))
    if c < C:
        out.append((r, c + 1))
    return out


def _dir(a: Coord, b: Coord) -> Tuple[int, int]:
    return (b[0] - a[0], b[1] - a[1])


def _is_straight(d1: Tuple[int, int], d2: Tuple[int, int]) -> bool:
    return (d1[0] == -d2[0] and d1[1] == -d2[1])


def _perp_dirs(d: Tuple[int, int]) -> List[Tuple[int, int]]:
    if d[0] != 0:
        return [(0, 1), (0, -1)]
    return [(1, 0), (-1, 0)]


def _add(a: Coord, d: Tuple[int, int]) -> Coord:
    return (a[0] + d[0], a[1] + d[1])


@dataclass
class Clue:
    pos: Coord
    color: str  # 'W' or 'B'
    k: int


class DSU:
    __slots__ = ("p", "r", "sz", "edges")

    def __init__(self, n: int):
        self.p = list(range(n))
        self.r = [0] * n
        self.sz = [1] * n
        self.edges = [0] * n

    def find(self, x: int) -> int:
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x

    def union_edge(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            self.edges[ra] += 1
            return
        if self.r[ra] < self.r[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        self.sz[ra] += self.sz[rb]
        self.edges[ra] += self.edges[rb] + 1
        if self.r[ra] == self.r[rb]:
            self.r[ra] += 1


class Solver:
    def __init__(self, observation: dict):
        data = observation["data"]
        self.H = len(data)  # dots grid size is H x W where H=W=N+1
        self.W = len(data[0]) if self.H else 0
        if self.H == 0 or self.W == 0:
            raise ValueError("Empty grid")
        # interpret as dot grid; edges between adjacent dots
        self.R = self.H - 1
        self.C = self.W - 1

        self.clues: List[Clue] = []
        for r in range(self.H):
            for c in range(self.W):
                tok = data[r][c]
                if tok:
                    color = tok[0].upper()
                    k = int(tok[1:])
                    if color not in ("W", "B"):
                        raise ValueError(f"Bad token {tok}")
                    self.clues.append(Clue((r, c), color, k))

        # enumerate all edges
        self.edges: List[Edge] = []
        self.edge_index: Dict[Edge, int] = {}
        for r in range(self.H):
            for c in range(self.W):
                a = (r, c)
                for b in _neighbors_dot(r, c, self.H - 1, self.W - 1):
                    e = _norm_edge(a, b)
                    if e not in self.edge_index:
                        self.edge_index[e] = len(self.edges)
                        self.edges.append(e)

        # edges incident to dot
        self.inc: Dict[Coord, List[int]] = defaultdict(list)
        for i, (a, b) in enumerate(self.edges):
            self.inc[a].append(i)
            self.inc[b].append(i)

        # For faster: map dot -> neighbor dot -> edge id
        self.edge_of: Dict[Tuple[Coord, Coord], int] = {}
        for i, (a, b) in enumerate(self.edges):
            self.edge_of[(a, b)] = i
            self.edge_of[(b, a)] = i

        # Variable states: -1 unknown, 0 off, 1 on
        self.state0 = [-1] * len(self.edges)

        # Precompute adjacency direction for each incident edge at each dot
        self.edge_dir: Dict[Tuple[Coord, int], Tuple[int, int]] = {}
        for dot, elist in self.inc.items():
            for ei in elist:
                a, b = self.edges[ei]
                other = b if dot == a else a
                self.edge_dir[(dot, ei)] = _dir(dot, other)

        # Precompute for each clue its incident edges by direction (N,S,W,E if present)
        self.clue_dir_edge: Dict[Coord, Dict[Tuple[int, int], int]] = {}
        for cl in self.clues:
            pos = cl.pos
            dmap = {}
            for nb in _neighbors_dot(pos[0], pos[1], self.H - 1, self.W - 1):
                d = _dir(pos, nb)
                dmap[d] = self.edge_of[(pos, nb)]
            self.clue_dir_edge[pos] = dmap

        # Max possible ray length from a dot in each direction (grid boundary)
        self.max_run: Dict[Tuple[Coord, Tuple[int, int]], int] = {}
        for r in range(self.H):
            for c in range(self.W):
                p = (r, c)
                for d in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    rr, cc = r, c
                    m = 0
                    while True:
                        rr2, cc2 = rr + d[0], cc + d[1]
                        if not (0 <= rr2 < self.H and 0 <= cc2 < self.W):
                            break
                        m += 1
                        rr, cc = rr2, cc2
                    self.max_run[(p, d)] = m

        # Dots ordering heuristic cache
        self.dot_list = [(r, c) for r in range(self.H) for c in range(self.W)]

    def solve(self) -> Optional[List[Coord]]:
        st = self.state0[:]
        ok, st = self._propagate(st)
        if not ok:
            return None
        res = self._search(st)
        return res

    def _search(self, st: List[int]) -> Optional[List[Coord]]:
        ok, st = self._propagate(st)
        if not ok:
            return None

        # If complete, validate single cycle + all clues satisfied fully, then extract loop
        if all(v != -1 for v in st):
            if not self._is_single_cycle(st):
                return None
            if not self._all_clues_satisfied(st):
                return None
            return self._extract_cycle(st)

        # Choose next branching variable: edge with strongest constraints (incident to clue or constrained dot)
        ei = self._select_edge_mrv(st)
        # Branch ON then OFF (often loop edges are fewer; but clue constraints push ON)
        for val in (1, 0):
            st2 = st[:]
            st2[ei] = val
            res = self._search(st2)
            if res is not None:
                return res
        return None

    def _select_edge_mrv(self, st: List[int]) -> int:
        # Score unknown edges: higher if touches clue dot, else if touches dot with degree pressure
        best = None
        best_score = -10**9
        clue_set = {cl.pos for cl in self.clues}
        for i, v in enumerate(st):
            if v != -1:
                continue
            a, b = self.edges[i]
            score = 0
            if a in clue_set:
                score += 50
            if b in clue_set:
                score += 50
            # degree pressure: dots with many fixed edges
            for p in (a, b):
                inc = self.inc[p]
                on = sum(1 for e in inc if st[e] == 1)
                unk = sum(1 for e in inc if st[e] == -1)
                if on == 1 and unk == 1:
                    score += 20
                if on == 2:
                    score += 10
            # prefer edges closer to being forced by contradictions: endpoints with low unk
            if score > best_score:
                best_score = score
                best = i
        return best if best is not None else next(i for i, v in enumerate(st) if v == -1)

    def _propagate(self, st: List[int]) -> Tuple[bool, List[int]]:
        q = deque()

        # initialize queue with all dots and clues
        for p in self.dot_list:
            q.append(("dot", p))
        for cl in self.clues:
            q.append(("clue", cl.pos))

        inq: Set[Tuple[str, Coord]] = set(q)

        def enqueue(kind: str, pos: Coord):
            key = (kind, pos)
            if key not in inq:
                inq.add(key)
                q.append(key)

        while q:
            kind, pos = q.popleft()
            inq.discard((kind, pos))
            if kind == "dot":
                ok, changed_edges = self._prop_dot(pos, st)
            else:
                ok, changed_edges = self._prop_clue(pos, st)
            if not ok:
                return False, st
            if changed_edges:
                for ei in changed_edges:
                    a, b = self.edges[ei]
                    enqueue("dot", a)
                    enqueue("dot", b)
                    # update nearby clues if at endpoints
                    if a in self.clue_dir_edge:
                        enqueue("clue", a)
                    if b in self.clue_dir_edge:
                        enqueue("clue", b)
        # global pruning: prevent small cycles before completion (subtour)
        if not self._no_premature_cycle(st):
            return False, st
        return True, st

    def _prop_dot(self, p: Coord, st: List[int]) -> Tuple[bool, List[int]]:
        inc = self.inc[p]
        on = [e for e in inc if st[e] == 1]
        off = [e for e in inc if st[e] == 0]
        unk = [e for e in inc if st[e] == -1]

        changed = []

        # Degree must be 0 or 2 (loop visits or not), but if any edge is on, degree must be 2.
        if len(on) > 2:
            return False, []
        if len(on) == 1 and len(unk) == 0:
            return False, []
        if len(on) == 2:
            # force rest off
            for e in unk:
                st[e] = 0
                changed.append(e)
        elif len(on) == 1:
            # if only one unknown remains, it must be on
            if len(unk) == 1:
                st[unk[0]] = 1
                changed.append(unk[0])
            # if clue requires straight/turn at this dot, handled in clue propagation
        else:  # len(on)==0
            # if all but 2 are off and dot is forced to be used (e.g., clue), clue propagation will force
            pass

        # Additional: if dot is clue, it must have degree 2 (always used)
        if p in self.clue_dir_edge:
            # if two edges already off leaving less than 2 possible -> fail
            possible = [e for e in inc if st[e] != 0]
            if len(possible) < 2:
                return False, []
            # ensure dot used: cannot have degree 0
            if len(on) == 0 and len(possible) == 2:
                for e in possible:
                    if st[e] != 1:
                        st[e] = 1
                        changed.append(e)
            # if one on, must pick another among possible
            if len(on) == 1 and len(possible) == 2:
                e = possible[0] if possible[1] == on[0] else possible[1]
                if st[e] != 1:
                    st[e] = 1
                    changed.append(e)

        return True, changed

    def _prop_clue(self, p: Coord, st: List[int]) -> Tuple[bool, List[int]]:
        # enforce local straight/turn + numbered ray sum bounds
        tok = None
        for cl in self.clues:
            if cl.pos == p:
                tok = cl
                break
        if tok is None:
            return True, []
        cl = tok
        inc = self.inc[p]
        changed = []

        # Clue must have exactly 2 incident ON edges eventually.
        # Use local pattern constraints:
        # Determine which pairs are allowed for W/B.
        dirs_edges = self.clue_dir_edge[p]  # direction->edge
        # list available incident edges with direction
        items = [(d, e) for d, e in dirs_edges.items()]
        # in-grid should be 2-4 edges (corners/edges/inside)
        # Evaluate possible pairs consistent with W/B and current st
        possible_pairs = []
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                d1, e1 = items[i]
                d2, e2 = items[j]
                if st[e1] == 0 or st[e2] == 0:
                    continue
                if cl.color == "W":
                    if not _is_straight(d1, d2):
                        continue
                else:
                    if _is_straight(d1, d2):
                        continue
                possible_pairs.append(((d1, e1), (d2, e2)))
        # Also must respect already-ON edges
        on_edges = [e for e in inc if st[e] == 1]
        if len(on_edges) > 2:
            return False, []
        if len(on_edges) == 2:
            # verify they match at least one possible pair
            okpair = False
            for (d1, e1), (d2, e2) in possible_pairs:
                if {e1, e2} == set(on_edges):
                    okpair = True
                    break
            if not okpair:
                return False, []
        elif len(on_edges) == 1:
            e_on = on_edges[0]
            possible_pairs = [pp for pp in possible_pairs if pp[0][1] == e_on or pp[1][1] == e_on]
            if not possible_pairs:
                return False, []
        else:
            if not possible_pairs:
                return False, []

        # If all possible pairs share a common edge, force it on; if an edge appears in no pair, force off
        edge_in_pairs = defaultdict(int)
        for (d1, e1), (d2, e2) in possible_pairs:
            edge_in_pairs[e1] += 1
            edge_in_pairs[e2] += 1
        total_pairs = len(possible_pairs)
        for e in inc:
            if st[e] == -1:
                if edge_in_pairs.get(e, 0) == 0:
                    st[e] = 0
                    changed.append(e)
                elif edge_in_pairs.get(e, 0) == total_pairs:
                    st[e] = 1
                    changed.append(e)

        # Number constraint (ray length sum = k) with bounds over all possible pairs.
        # For each candidate pair, compute min/max possible ray lengths for each direction given current st,
        # and check feasibility vs k.
        feasible_pairs = []
        for (d1, e1), (d2, e2) in possible_pairs:
            bounds1 = self._ray_bounds(p, d1, st)
            bounds2 = self._ray_bounds(p, d2, st)
            if bounds1 is None or bounds2 is None:
                continue
            (mn1, mx1) = bounds1
            (mn2, mx2) = bounds2
            k = cl.k
            if mn1 + mn2 <= k <= mx1 + mx2:
                feasible_pairs.append(((d1, e1, mn1, mx1), (d2, e2, mn2, mx2)))
        if not feasible_pairs:
            return False, []

        # Filter based on on-edges again (since bounds may remove pairs)
        if len(on_edges) == 2:
            if not any({pp[0][1], pp[1][1]} == set(on_edges) for pp in feasible_pairs):
                return False, []
        elif len(on_edges) == 1:
            e_on = on_edges[0]
            feasible_pairs = [pp for pp in feasible_pairs if pp[0][1] == e_on or pp[1][1] == e_on]
            if not feasible_pairs:
                return False, []
        # With updated feasible pairs, enforce same edge commonality
        edge_in_pairs2 = defaultdict(int)
        for a, b in feasible_pairs:
            edge_in_pairs2[a[1]] += 1
            edge_in_pairs2[b[1]] += 1
        total2 = len(feasible_pairs)
        for e in inc:
            if st[e] == -1:
                if edge_in_pairs2.get(e, 0) == 0:
                    st[e] = 0
                    changed.append(e)
                elif edge_in_pairs2.get(e, 0) == total2:
                    st[e] = 1
                    changed.append(e)

        # If a pair is forced uniquely, we can also try to force some straight continuation edges based on ray sum tightness.
        if total2 == 1:
            (d1, e1, mn1, mx1), (d2, e2, mn2, mx2) = feasible_pairs[0]
            # ensure these two edges are ON
            for e in (e1, e2):
                if st[e] == -1:
                    st[e] = 1
                    changed.append(e)
                elif st[e] == 0:
                    return False, []
            # If k forces an exact ray length and the current min==max not, we can sometimes force early edges on/off.
            k = cl.k
            # For each ray, if other ray fixed to min/max range leaves exact needed length, enforce.
            # We'll perform a limited "prefix forcing": if a ray must be at least L, force first L edges on.
            # If a ray must be at most U, and an edge at distance U+1 is on, contradiction caught by bounds.
            need1_min = max(mn1, k - mx2)
            need1_max = min(mx1, k - mn2)
            need2_min = max(mn2, k - mx1)
            need2_max = min(mx2, k - mn1)
            if need1_min > need1_max or need2_min > need2_max:
                return False, []
            # prefix forcing for required minimums
            ch = self._force_ray_min(p, d1, need1_min, st)
            if ch is None:
                return False, []
            changed.extend(ch)
            ch = self._force_ray_min(p, d2, need2_min, st)
            if ch is None:
                return False, []
            changed.extend(ch)

        return True, changed

    def _ray_bounds(self, start: Coord, d: Tuple[int, int], st: List[int]) -> Optional[Tuple[int, int]]:
        # Ray length counts consecutive ON edges starting from start in direction d,
        # until the path cannot continue straight (edge off), or must turn/end at some dot.
        # We compute lower bound (forced ON prefix) and upper bound (max possible without violating degree constraints).
        max_steps = self.max_run[(start, d)]
        if max_steps == 0:
            return None
        # If first edge is OFF -> length 0 impossible because clue must use that direction if chosen;
        # however ray_bounds called only for chosen direction; ensure first edge not off.
        nxt = _add(start, d)
        e0 = self.edge_of.get((start, nxt))
        if e0 is None or st[e0] == 0:
            return None

        # Determine forced prefix ON due to already ON edges in straight line
        mn = 0
        cur = start
        for step in range(1, max_steps + 1):
            nxt = _add(cur, d)
            e = self.edge_of.get((cur, nxt))
            if e is None:
                break
            if st[e] == 1:
                mn = step
                cur = nxt
                continue
            break

        # Compute upper bound by scanning until an OFF edge blocks or until a dot cannot accept straight-through
        # given existing ON edges would force a turn/end before continuing.
        mx = 0
        cur = start
        for step in range(1, max_steps + 1):
            nxt = _add(cur, d)
            e = self.edge_of.get((cur, nxt))
            if e is None or st[e] == 0:
                break
            # check feasibility of having edge cur->nxt ON and continuing straight through nxt (unless this is end)
            # We allow continuation as long as nxt can have degree 2 with one edge being this incoming
            # and the straight outgoing edge not forced off.
            mx = step
            cur = nxt
            # If at cur (which is nxt), if continuing further, need the straight edge available
            if step < max_steps:
                nxt2 = _add(cur, d)
                e2 = self.edge_of.get((cur, nxt2))
                if e2 is None or st[e2] == 0:
                    # cannot continue further
                    break
                # Also, if cur already has 2 ON edges and the straight one isn't among them, cannot continue
                inc = self.inc[cur]
                on = [x for x in inc if st[x] == 1]
                if len(on) == 2 and e2 not in on:
                    break
                # If cur has 1 ON edge and all other incident except e2 are off, then e2 is forced on -> ok
                # If cur has 0 ON edges, still possible
        return (mn, mx)

    def _force_ray_min(self, start: Coord, d: Tuple[int, int], L: int, st: List[int]) -> Optional[List[int]]:
        # Force first L edges along ray to be ON
        changed = []
        cur = start
        for _ in range(L):
            nxt = _add(cur, d)
            if not (0 <= nxt[0] < self.H and 0 <= nxt[1] < self.W):
                return None
            e = self.edge_of.get((cur, nxt))
            if e is None:
                return None
            if st[e] == 0:
                return None
            if st[e] == -1:
                st[e] = 1
                changed.append(e)
            cur = nxt
        return changed

    def _no_premature_cycle(self, st: List[int]) -> bool:
        # Disallow forming a closed cycle unless all clue dots that are forced-used are included and
        # no other ON edges remain outside. Use DSU on dots with ON edges.
        n = self.H * self.W

        def idx(p: Coord) -> int:
            return p[0] * self.W + p[1]

        dsu = DSU(n)
        used_nodes = set()
        on_edges = 0
        for i, v in enumerate(st):
            if v == 1:
                a, b = self.edges[i]
                used_nodes.add(idx(a))
                used_nodes.add(idx(b))
                dsu.union_edge(idx(a), idx(b))
                on_edges += 1
        if on_edges == 0:
            return True
        # find any component that is already a cycle: edges == nodes in component and all degrees in comp are 2 fixed
        comp_nodes = defaultdict(int)
        comp_edges = defaultdict(int)
        for node in used_nodes:
            r = dsu.find(node)
            comp_nodes[r] += 1
        for node in list(comp_nodes.keys()):
            comp_edges[node] = dsu.edges[node]
        # if any component forms a cycle but there exist unknown edges or other components -> premature
        cycle_comps = [r for r in comp_nodes if comp_edges[r] == comp_nodes[r] and comp_nodes[r] >= 4]
        if not cycle_comps:
            return True
        # If exactly one cycle component and all edges decided and all clue nodes are in it, allow (final check later)
        if any(v == -1 for v in st):
            # Could still be final cycle if all remaining unknowns are forced off and no other on edges;
            # but we can't know. Prevent any closed cycle if there is any clue not in that component.
            clue_nodes = {idx(cl.pos) for cl in self.clues}
            for r in cycle_comps:
                # if this cycle component already exists and not all clue nodes included -> invalid
                # also if there are ON edges outside this component -> invalid
                if not clue_nodes.issubset({node for node in used_nodes if dsu.find(node) == r}):
                    return False
                # ensure no used node outside
                if any(dsu.find(node) != r for node in used_nodes):
                    return False
        return True

    def _is_single_cycle(self, st: List[int]) -> bool:
        # All degrees are 0 or 2; clues must be degree 2; used edges must form one component and cycle.
        deg = defaultdict(int)
        on_edges = []
        for i, v in enumerate(st):
            if v == 1:
                a, b = self.edges[i]
                deg[a] += 1
                deg[b] += 1
                on_edges.append((a, b))
        # every used dot has degree 2
        used_dots = [p for p, d in deg.items() if d > 0]
        if not used_dots:
            return False
        for p in used_dots:
            if deg[p] != 2:
                return False
        # all clue dots used
        for cl in self.clues:
            if deg.get(cl.pos, 0) != 2:
                return False
        # connectivity: all used dots in one component
        stack = [used_dots[0]]
        seen = {used_dots[0]}
        adj = defaultdict(list)
        for a, b in on_edges:
            adj[a].append(b)
            adj[b].append(a)
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        return len(seen) == len(used_dots)

    def _all_clues_satisfied(self, st: List[int]) -> bool:
        # Verify local straight/turn and exact ray sum.
        for cl in self.clues:
            p = cl.pos
            inc = self.inc[p]
            on = [e for e in inc if st[e] == 1]
            if len(on) != 2:
                return False
            d1 = self.edge_dir[(p, on[0])]
            d2 = self.edge_dir[(p, on[1])]
            if cl.color == "W":
                if not _is_straight(d1, d2):
                    return False
            else:
                if _is_straight(d1, d2):
                    return False
            # compute exact ray lengths along outgoing directions
            L1 = self._ray_exact(p, d1, st)
            L2 = self._ray_exact(p, d2, st)
            if L1 is None or L2 is None or (L1 + L2) != cl.k:
                return False
        return True

    def _ray_exact(self, start: Coord, d: Tuple[int, int], st: List[int]) -> Optional[int]:
        # Starting from start, go in direction d while edges are ON and path continues straight through intermediate dots.
        # Since final solution is a single cycle, we can just count consecutive ON edges.
        max_steps = self.max_run[(start, d)]
        cur = start
        cnt = 0
        for _ in range(max_steps):
            nxt = _add(cur, d)
            if not (0 <= nxt[0] < self.H and 0 <= nxt[1] < self.W):
                break
            e = self.edge_of.get((cur, nxt))
            if e is None or st[e] != 1:
                break
            cnt += 1
            cur = nxt
            # stop if at cur the loop turns (i.e., the next edge straight is not ON)
            nxt2 = _add(cur, d)
            if not (0 <= nxt2[0] < self.H and 0 <= nxt2[1] < self.W):
                break
            e2 = self.edge_of.get((cur, nxt2))
            if e2 is None or st[e2] != 1:
                break
            # otherwise continue
        return cnt

    def _extract_cycle(self, st: List[int]) -> List[Coord]:
        # Build adjacency and follow cycle from lexicographically smallest used dot.
        adj = defaultdict(list)
        for i, v in enumerate(st):
            if v == 1:
                a, b = self.edges[i]
                adj[a].append(b)
                adj[b].append(a)
        start = min(adj.keys())
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            prev, cur = cur, nxt
            path.append(cur)
            if cur == start:
                break
        return path


def solve(observation):
    s = Solver(observation)
    path = s.solve()
    return "No Solution" if path is None else str(path)


if __name__ == "__main__":
    print(solve(OBSERVATION))

