from collections import deque, defaultdict
import itertools
import math

# Solver for Masyu "k" variant:
# - Grid is N x N cells with (N+1)x(N+1) dots.
# - Clues sit at cell centers (r,c), 0..N-1.
# - Loop runs on edges between dots, forming single cycle.
# - Each clue cell must be visited by the loop:
#   * Wk: loop goes straight through the cell (one of two straight orientations)
#   * Bk: loop turns in the cell (one of four corner orientations)
#   * k: sum of lengths of the two straight segments extending from that cell along the loop
#        (along the two directions used at the clue, for W: opposite, for B: orthogonal).
#
# Approach:
# - Represent each cell's local pattern choice (domain).
# - Represent each edge between dots as {0,1,unknown}.
# - Aggressive constraint propagation:
#   * Local incidence constraints per cell pattern
#   * Degree constraints per dot: degree is 0 or 2
#   * Connectivity (no premature small loops; single cycle at end)
#   * Segment-length constraints for each clue using forward reasoning:
#       - For a chosen pattern, the two rays from the clue must run straight until a turning clue (black) or a straight clue with perpendicular continuation causes turn;
#         In practice, we track "must-be-straight corridor" and compute feasible ranges for segment lengths from partial assignments.
# - Search:
#   * Choose most constrained variable: either a clue cell pattern with smallest domain, or an undecided edge with high impact.
#   * Depth-first with backtracking; propagation after each decision.

DIRS = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # E,S,W,N
E, S, W, N = 0, 1, 2, 3

def solve(observation):
    data = observation["data"]
    n = len(data)
    # Dots are (n+1)x(n+1)
    H = n + 1
    Wd = n + 1

    # Edge indexing:
    # horizontal edge between (r,c)-(r,c+1): h[r][c], r in [0..H-1], c in [0..Wd-2]
    # vertical edge between (r,c)-(r+1,c): v[r][c], r in [0..H-2], c in [0..Wd-1]
    h = [[-1]*(Wd-1) for _ in range(H)]
    v = [[-1]*Wd for _ in range(H-1)]

    # Helper mapping between cell patterns and required edges.
    # Each cell (r,c) is a square with corners:
    # tl=(r,c), tr=(r,c+1), bl=(r+1,c), br=(r+1,c+1)
    # A path through the cell uses two boundary edges adjacent to the cell center.
    # We'll express patterns in terms of entering/exiting sides: 0=top,1=right,2=bottom,3=left.
    # If pattern uses sides a and b:
    # - add the corresponding boundary edges as present
    # - all other boundary edges absent (but note: edges are shared between adjacent cells; absence here means the loop does not use that boundary segment adjacent to this cell,
    #   which is equivalent to edge absent overall).
    #
    # Boundary side to actual edge:
    # top side is h[r][c]
    # bottom side is h[r+1][c]
    # left side is v[r][c]
    # right side is v[r][c+1]
    def side_edge(cell_r, cell_c, side):
        if side == 0:
            return ('h', cell_r, cell_c)
        if side == 2:
            return ('h', cell_r+1, cell_c)
        if side == 3:
            return ('v', cell_r, cell_c)
        if side == 1:
            return ('v', cell_r, cell_c+1)
        raise ValueError

    # Patterns:
    # Straight: (top,bottom) or (left,right)
    STRAIGHTS = [(0,2), (3,1)]
    # Turns: (top,right),(right,bottom),(bottom,left),(left,top)
    TURNS = [(0,1),(1,2),(2,3),(3,0)]

    clues = {}
    for r in range(n):
        for c in range(n):
            tok = data[r][c]
            if tok:
                color = tok[0]
                k = int(tok[1:])
                clues[(r,c)] = (color, k)

    # Domains for each clue cell: list of allowed patterns (tuple of sides)
    domains = {}
    for (r,c),(color,k) in clues.items():
        if color == 'W':
            domains[(r,c)] = STRAIGHTS.copy()
        else:
            domains[(r,c)] = TURNS.copy()

    # Non-clue cells: can be unused or used (straight/turn). But the loop must pass through all clues, not necessarily all cells.
    # For non-clues, we do not explicitly model cell patterns; edges are sufficient with dot degree constraints.
    # However, to help propagation of segment lengths, we need to know whether the loop goes through a cell and how.
    # We'll infer local usage by edges as they are assigned.

    # Dot degrees tracking
    deg = [[0]*Wd for _ in range(H)]
    unk_inc = [[0]*Wd for _ in range(H)]

    # Initialize unk_inc counts (number of incident edges unknown per dot)
    # Each dot has up to 4 incident edges; we will update as edges assigned.
    def init_unknown_counts():
        for r in range(H):
            for c in range(Wd):
                cnt = 0
                if c>0: cnt += 1  # h[r][c-1]
                if c<Wd-1: cnt += 1  # h[r][c]
                if r>0: cnt += 1  # v[r-1][c]
                if r<H-1: cnt += 1  # v[r][c]
                unk_inc[r][c] = cnt
    init_unknown_counts()

    # Union-Find for preventing premature cycles among active dots.
    parent = {}
    comp_edges = {}
    comp_nodes = {}

    def uf_find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def uf_make(x):
        if x not in parent:
            parent[x] = x
            comp_edges[x] = 0
            comp_nodes[x] = 1

    def uf_union(a,b):
        ra, rb = uf_find(a), uf_find(b)
        if ra == rb:
            return ra
        # union by size
        if comp_nodes[ra] < comp_nodes[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        comp_edges[ra] += comp_edges[rb]
        comp_nodes[ra] += comp_nodes[rb]
        return ra

    # Stack for backtracking changes
    trail = []

    def trail_set(ref, idx, old):
        trail.append((ref, idx, old))

    def set_h(r,c,val):
        old = h[r][c]
        if old == val:
            return True
        if old != -1 and old != val:
            return False
        trail_set(h[r], c, old)
        h[r][c] = val
        # update dot degrees/unknown counts
        a = (r,c)
        b = (r,c+1)
        _edge_assigned(a,b,val)
        return True

    def set_v(r,c,val):
        old = v[r][c]
        if old == val:
            return True
        if old != -1 and old != val:
            return False
        trail_set(v[r], c, old)
        v[r][c] = val
        a = (r,c)
        b = (r+1,c)
        _edge_assigned(a,b,val)
        return True

    def _edge_assigned(a,b,val):
        ar,ac = a
        br,bc = b
        # decrement unknown incident for both dots
        trail_set(unk_inc[ar], ac, unk_inc[ar][ac])
        unk_inc[ar][ac] -= 1
        trail_set(unk_inc[br], bc, unk_inc[br][bc])
        unk_inc[br][bc] -= 1
        if val == 1:
            # increase degrees
            trail_set(deg[ar], ac, deg[ar][ac])
            deg[ar][ac] += 1
            trail_set(deg[br], bc, deg[br][bc])
            deg[br][bc] += 1
            # union-find update for cycle check
            uf_make(a); uf_make(b)
            ra, rb = uf_find(a), uf_find(b)
            if ra == rb:
                # added an edge within same component; this creates a cycle in that component
                # It's only allowed if it would be the final single loop and all active nodes have degree 2.
                # We'll mark by incrementing edge count; later feasibility check rejects premature.
                root = ra
                trail.append(("uf_edges", root, comp_edges[root]))
                comp_edges[root] += 1
            else:
                # merge components, edge count increments by 1
                new_root = uf_union(a,b)
                trail.append(("uf_edges", new_root, comp_edges[new_root]))
                comp_edges[new_root] += 1
        # val==0: nothing else

    def get_edge_between(p,q):
        pr,pc = p; qr,qc = q
        if pr == qr:
            r = pr
            c = min(pc,qc)
            return ('h', r, c, h[r][c])
        else:
            c = pc
            r = min(pr,qr)
            return ('v', r, c, v[r][c])

    def set_edge_between(p,q,val):
        pr,pc = p; qr,qc = q
        if pr == qr:
            r = pr; c = min(pc,qc)
            return set_h(r,c,val)
        else:
            r = min(pr,qr); c = pc
            return set_v(r,c,val)

    def rollback(to_len):
        while len(trail) > to_len:
            item = trail.pop()
            if item[0] == "uf_edges":
                _, root, old = item
                comp_edges[root] = old
            else:
                ref, idx, old = item
                ref[idx] = old
        # Note: parent/comp_nodes changes are not rolled back fully; to keep it simple and correct,
        # we avoid relying on persistent UF across backtracking by rebuilding UF when needed in checks.
        # We'll do that for cycle checks in feasibility, and not use UF for propagation decisions.

    # Degree feasibility propagation
    def propagate_degrees(queue):
        while queue:
            r,c = queue.popleft()
            d = deg[r][c]
            u = unk_inc[r][c]
            # impossible degrees
            if d > 2:
                return False
            if d == 1 and u == 0:
                return False
            if d == 0 and u == 0:
                # isolated dot is fine
                continue
            # if degree already 2, remaining unknown incident edges must be 0
            if d == 2 and u > 0:
                # set all unknown incident edges to 0
                for (p,q,kind,rr,cc) in incident_edges(r,c):
                    if kind == 'h':
                        if h[rr][cc] == -1 and not set_h(rr,cc,0): return False
                    else:
                        if v[rr][cc] == -1 and not set_v(rr,cc,0): return False
                    # neighbor dot degrees impacted; enqueue both ends
                    queue.append(p); queue.append(q)
            # if degree + unknown == 2, all unknown must be 1
            if d + u == 2 and u > 0:
                for (p,q,kind,rr,cc) in incident_edges(r,c):
                    if kind == 'h':
                        if h[rr][cc] == -1 and not set_h(rr,cc,1): return False
                    else:
                        if v[rr][cc] == -1 and not set_v(rr,cc,1): return False
                    queue.append(p); queue.append(q)
        return True

    def incident_edges(r,c):
        # yields (p,q,kind,rr,cc) where edge variable is h[rr][cc] or v[rr][cc]
        p = (r,c)
        if c>0:
            q=(r,c-1)
            yield (p,q,'h',r,c-1)
        if c<Wd-1:
            q=(r,c+1)
            yield (p,q,'h',r,c)
        if r>0:
            q=(r-1,c)
            yield (p,q,'v',r-1,c)
        if r<H-1:
            q=(r+1,c)
            yield (p,q,'v',r,c)

    # Enforce a clue cell pattern on edges
    def apply_cell_pattern(r,c,pat):
        # pat is tuple (sideA, sideB) among 0..3
        sides_on = set(pat)
        for side in [0,1,2,3]:
            kind, rr, cc = side_edge(r,c,side)
            want = 1 if side in sides_on else 0
            if kind == 'h':
                if not set_h(rr,cc,want): return False
            else:
                if not set_v(rr,cc,want): return False
        return True

    # For each clue, filter domains by edge consistency (partial)
    def filter_domains():
        changed = True
        while changed:
            changed = False
            for (r,c),(color,k) in clues.items():
                dom = domains[(r,c)]
                ok = []
                for pat in dom:
                    if pattern_compatible(r,c,pat):
                        ok.append(pat)
                if not ok:
                    return False
                if len(ok) != len(dom):
                    trail.append(("dom", (r,c), dom))
                    domains[(r,c)] = ok
                    changed = True
                if len(ok) == 1:
                    # enforce it
                    if not apply_cell_pattern(r,c,ok[0]):
                        return False
        return True

    def rollback_domains(to_len):
        while len(trail) > to_len:
            item = trail.pop()
            if item[0] == "dom":
                _, key, olddom = item
                domains[key] = olddom
            elif item[0] == "uf_edges":
                _, root, old = item
                comp_edges[root] = old
            else:
                ref, idx, old = item
                ref[idx] = old

    def pattern_compatible(r,c,pat):
        # check if any required edge contradicts current assignments
        sides_on = set(pat)
        for side in [0,1,2,3]:
            kind, rr, cc = side_edge(r,c,side)
            cur = h[rr][cc] if kind=='h' else v[rr][cc]
            want = 1 if side in sides_on else 0
            if cur != -1 and cur != want:
                return False
        return True

    # Segment-length feasibility (range reasoning).
    # For a clue with chosen (or candidate) pattern, compute min/max possible sum of the two ray lengths
    # given current edge assignments and degree constraints locally.
    def ray_length_range_from_cell(r,c,dir_side):
        # dir_side: 0 top,1 right,2 bottom,3 left; ray exits the cell via that side and goes along grid lines.
        # We measure length in cell units: number of consecutive cells traveled straight from the clue cell until a turn.
        # Here we compute bounds based on forced edges:
        # - If at any step the straight continuation edge is forced 0, max stops before.
        # - If forced 1, min extends.
        # Termination: when line is forced to turn by an edge configuration at a cell boundary (unknown allows both).
        # We approximate with conservative bounds to allow strong pruning without incorrect elimination:
        #   min_len: count of steps that are forced straight (edge=1) until first unknown/forced stop
        #   max_len: extend until a forced stop encountered or border reached
        dr, dc = {0:(-1,0), 1:(0,1), 2:(1,0), 3:(0,-1)}[dir_side]
        # Starting at the boundary between clue cell and adjacent cell in that direction.
        # We'll traverse cell-by-cell; each step requires the boundary edge between cells to be 1 and the line to remain straight.
        # For straightness, we need both entering and exiting edges in each traversed cell along same direction.
        # Modeling exact straightness requires cell patterns; we use edge-based straight corridor:
        # along vertical movement: require both top and bottom edges of each cell in the corridor to be 1, and left/right to be 0 at the turn point.
        # This is complex; to stay correct and still useful, we use only boundary-edge continuity:
        # The ray length is at least number of consecutive boundary edges forced to 1 outward;
        # at most number of consecutive boundary edges not forced 0 outward until border.
        minlen = 0
        maxlen = 0
        cr, cc = r, c
        while True:
            nr, nc = cr + dr, cc + dc
            if not (0 <= nr < n and 0 <= nc < n):
                break
            # boundary edge between (cr,cc) cell and (nr,nc) cell corresponds to one of cell sides for (cr,cc)
            side = dir_side
            kind, rr, ec = side_edge(cr,cc,side)
            cur = h[rr][ec] if kind=='h' else v[rr][ec]
            if cur == 0:
                break
            maxlen += 1
            if cur == 1:
                minlen += 1
                cr, cc = nr, nc
                continue
            # unknown: can stop here or continue
            cr, cc = nr, nc
        return minlen, maxlen

    def segment_sum_range_for_pat(r,c,pat):
        a,b = pat
        r1 = ray_length_range_from_cell(r,c,a)
        r2 = ray_length_range_from_cell(r,c,b)
        return (r1[0]+r2[0], r1[1]+r2[1])

    def filter_domains_by_k():
        changed = True
        while changed:
            changed = False
            for (r,c),(color,k) in clues.items():
                dom = domains[(r,c)]
                ok = []
                for pat in dom:
                    lo, hi = segment_sum_range_for_pat(r,c,pat)
                    if lo <= k <= hi:
                        ok.append(pat)
                if not ok:
                    return False
                if len(ok) != len(dom):
                    trail.append(("dom", (r,c), dom))
                    domains[(r,c)] = ok
                    changed = True
                if len(ok) == 1:
                    if not apply_cell_pattern(r,c,ok[0]):
                        return False
        return True

    def propagate_all():
        # repeated passes
        q = deque()
        # all dots might need consideration; but we seed with those with low unknown counts after assignments in practice
        for r in range(H):
            for c in range(Wd):
                if deg[r][c] or unk_inc[r][c] <= 2:
                    q.append((r,c))
        if not propagate_degrees(q):
            return False
        if not filter_domains():
            return False
        if not filter_domains_by_k():
            return False
        # degrees again after pattern enforcement
        q = deque()
        for r in range(H):
            for c in range(Wd):
                if deg[r][c] or unk_inc[r][c] <= 2:
                    q.append((r,c))
        if not propagate_degrees(q):
            return False
        return True

    def rebuild_components():
        # Build components of active edges=1 to detect premature cycles and ensure eventual single loop.
        par = {}
        size = {}
        edges_cnt = {}
        def find(x):
            while par[x]!=x:
                par[x]=par[par[x]]
                x=par[x]
            return x
        def make(x):
            if x not in par:
                par[x]=x; size[x]=1; edges_cnt[x]=0
        def union(a,b):
            ra,rb=find(a),find(b)
            if ra==rb:
                edges_cnt[ra]+=1
                return
            if size[ra]<size[rb]:
                ra,rb=rb,ra
            par[rb]=ra
            size[ra]+=size[rb]
            edges_cnt[ra]+=edges_cnt[rb]+1
        active_nodes=set()
        for r in range(H):
            for c in range(Wd-1):
                if h[r][c]==1:
                    a=(r,c); b=(r,c+1)
                    make(a); make(b)
                    active_nodes.add(a); active_nodes.add(b)
                    union(a,b)
        for r in range(H-1):
            for c in range(Wd):
                if v[r][c]==1:
                    a=(r,c); b=(r+1,c)
                    make(a); make(b)
                    active_nodes.add(a); active_nodes.add(b)
                    union(a,b)
        comps=defaultdict(lambda: {"nodes":0,"edges":0})
        for node in active_nodes:
            root=find(node)
            comps[root]["nodes"]=size[root]
            comps[root]["edges"]=edges_cnt[root]
        return comps, active_nodes

    def premature_cycle_exists():
        comps, active_nodes = rebuild_components()
        # If any component already forms a cycle (edges==nodes) while there remain undecided edges that could connect other parts
        # and not all clue constraints satisfied, reject. We approximate: reject any closed component unless it's the only component
        # and all degrees for its nodes are 2 and all clues are included (hard to check inclusion), so delay strictness:
        # We'll reject closed component if there exists at least one other active node outside it.
        if len(comps) <= 1:
            return False
        for comp in comps.values():
            if comp["edges"] == comp["nodes"] and comp["nodes"] > 0:
                return True
        return False

    def all_assigned():
        for r in range(H):
            for c in range(Wd-1):
                if h[r][c] == -1:
                    return False
        for r in range(H-1):
            for c in range(Wd):
                if v[r][c] == -1:
                    return False
        for key in domains:
            if len(domains[key]) != 1:
                return False
        return True

    def valid_final_loop():
        # All dots have degree 0 or 2, at least one edge exists, and all active edges form a single cycle.
        comps, active_nodes = rebuild_components()
        if not active_nodes:
            return False
        # degree check
        for (r,c) in active_nodes:
            if deg[r][c] != 2:
                return False
        if len(comps) != 1:
            return False
        comp = next(iter(comps.values()))
        if comp["edges"] != comp["nodes"]:
            return False
        # all clues must be satisfied with exact k:
        for (r,c),(color,k) in clues.items():
            if len(domains[(r,c)]) != 1:
                return False
            pat = domains[(r,c)][0]
            lo, hi = segment_sum_range_for_pat(r,c,pat)
            if not (lo == hi == k):
                return False
        return True

    def pick_variable():
        # Prefer clue with smallest domain >1
        best = None
        best_size = 10**9
        for key, dom in domains.items():
            if len(dom) > 1 and len(dom) < best_size:
                best = ("clue", key)
                best_size = len(dom)
        if best:
            return best
        # Else pick an undecided edge adjacent to clues or near high degree pressure
        best_edge = None
        best_score = -1
        for r in range(H):
            for c in range(Wd-1):
                if h[r][c] == -1:
                    score = (deg[r][c]+deg[r][c+1]) + (2-(unk_inc[r][c])) + (2-(unk_inc[r][c+1]))
                    if score > best_score:
                        best_score = score
                        best_edge = ('h', r, c)
        for r in range(H-1):
            for c in range(Wd):
                if v[r][c] == -1:
                    score = (deg[r][c]+deg[r+1][c]) + (2-(unk_inc[r][c])) + (2-(unk_inc[r+1][c]))
                    if score > best_score:
                        best_score = score
                        best_edge = ('v', r, c)
        if best_edge:
            return ("edge", best_edge)
        return None

    def search():
        if not propagate_all():
            return False
        if premature_cycle_exists():
            return False
        if all_assigned():
            return valid_final_loop()
        var = pick_variable()
        if var is None:
            return False
        if var[0] == "clue":
            key = var[1]
            dom = domains[key]
            r,c = key
            # try each pattern
            for pat in dom:
                tlen = len(trail)
                # assign domain to singleton and apply edges
                trail.append(("dom", key, dom))
                domains[key] = [pat]
                if apply_cell_pattern(r,c,pat) and search():
                    return True
                rollback_domains(tlen)
            return False
        else:
            kind, r, c = var[1]
            for val in (1,0):  # try include edge first
                tlen = len(trail)
                ok = set_h(r,c,val) if kind=='h' else set_v(r,c,val)
                if ok and search():
                    return True
                rollback_domains(tlen)
            return False

    # Initial propagation from clues (they must be on loop, so their 2 used sides are forced after domain reductions).
    if not search():
        return "No Solution"

    # Reconstruct a loop path from edges
    # Find a starting dot with degree 2
    start = None
    for r in range(H):
        for c in range(Wd):
            if deg[r][c] == 2:
                start = (r,c); break
        if start: break
    if not start:
        return "No Solution"

    def neighbors(dot):
        r,c = dot
        res=[]
        if c>0 and h[r][c-1]==1: res.append((r,c-1))
        if c<Wd-1 and h[r][c]==1: res.append((r,c+1))
        if r>0 and v[r-1][c]==1: res.append((r-1,c))
        if r<H-1 and v[r][c]==1: res.append((r+1,c))
        return res

    path=[start]
    prev=None
    cur=start
    while True:
        ns=neighbors(cur)
        if len(ns)!=2:
            return "No Solution"
        nxt = ns[0] if ns[0]!=prev else ns[1]
        if nxt==start:
            path.append(start)
            break
        path.append(nxt)
        prev,cur=cur,nxt
        if len(path) > (H*Wd*4):
            return "No Solution"
    return str(path)

if __name__ == "__main__":
    print(solve(OBSERVATION))

