import math
from collections import deque

# Consecutive Sudoku (a.k.a. Kropki-like consecutive dots only)
# Rules:
# - Latin square of size N: rows/cols are permutations of 1..N
# - Dot between orthogonally adjacent cells => values are consecutive (abs diff = 1)
# - No dot between orthogonally adjacent cells => values are NOT consecutive (abs diff != 1)

ALL_MASK_CACHE = {}

def bit(n):  # 1-indexed value -> bit
    return 1 << (n - 1)

def popcount(x):
    return x.bit_count()

def lowest_bit_index(x):
    # returns 0-based index of least significant set bit
    return (x & -x).bit_length() - 1

def iter_bits(mask):
    while mask:
        lb = mask & -mask
        yield lb
        mask ^= lb

def mask_to_values(mask):
    # 1..N
    vals = []
    i = 1
    while mask:
        lb = mask & -mask
        idx = lb.bit_length() - 1
        vals.append(idx + 1)
        mask ^= lb
    return vals

def consecutive_mask_for_values(mask, N):
    # Given a mask of allowed values, return mask of values that are consecutive (+/-1) to any value in mask.
    # Efficient via bit shifts on the bitmask:
    # values v consecutive to v±1 => shift left/right.
    # Example: bit(v) consecutive candidates include bit(v-1) and bit(v+1).
    # For a set S, consecutive set is (S<<1) | (S>>1) intersect 1..N.
    all_mask = (1 << N) - 1
    return ((mask << 1) | (mask >> 1)) & all_mask

def is_consecutive_possible(mask_a, mask_b, N):
    # true if there exists a in A, b in B with |a-b|=1
    # Equivalent: (consecutive_mask(A) & B) != 0
    return (consecutive_mask_for_values(mask_a, N) & mask_b) != 0

def remove_nonconsecutive_pairs(mask_a, mask_b, N):
    # For a dotted edge: enforce existence of consecutive pair across the edge by arc-consistency style filtering.
    # Return filtered (mask_a2, mask_b2)
    all_mask = (1 << N) - 1
    cons_a = consecutive_mask_for_values(mask_a, N)
    cons_b = consecutive_mask_for_values(mask_b, N)
    # a is supported if it has some b consecutive => bit(a) is supported if bit(a±1) in B.
    # Supported set for A: values a such that (bit(a-1)|bit(a+1)) intersects B.
    # Compute from B: supported A = consecutive_mask(B) intersect A
    sup_a = consecutive_mask_for_values(mask_b, N) & mask_a
    sup_b = consecutive_mask_for_values(mask_a, N) & mask_b
    return sup_a & all_mask, sup_b & all_mask

def remove_consecutive_pairs(mask_a, mask_b, N):
    # For a non-dotted edge: forbid consecutive differences.
    # Enforce: for each side, remove values that would force a consecutive match given the other side is singleton,
    # and do arc-consistency when one side becomes tight.
    # General AC for "not consecutive": keep a in A if there exists b in B with |a-b|!=1.
    # That's only impossible if B is subset of {a-1,a+1} (i.e. B has no nonconsecutive option).
    # Compute for each a: forbidden-support set in B = neighbors of a; if B \ neighbors == empty => a unsupported.
    all_mask = (1 << N) - 1
    # For a given a, neighbors mask is bit(a-1)|bit(a+1). We need to test quickly without iterating all a too much.
    # We'll do a selective filtering: if B is small, iterate B; else iterate A. N is usually small (<=9/10), acceptable.
    # But keep it efficient: if B has at least 3 distinct values, almost always supports everything.
    # Early exit: if B has value count >= 3 => for any a, there will exist some b nonconsecutive unless B happens to be exactly {a-1,a+1} plus maybe duplicates (not possible).
    # Still, B could be {x, y, z} where for some a, all three are neighbors? impossible since neighbors size <=2.
    if popcount(mask_b) >= 3:
        # Then every a has some b not in its neighbor set, hence all A supported.
        # Symmetrically for B if popcount(A)>=3.
        # But if A has <3, still need to filter B potentially.
        pass
    # Filter A
    if popcount(mask_b) <= 2:
        vals_b = mask_to_values(mask_b)
        # For each a in A, check existence of b in B with not consecutive
        new_a = 0
        for lb in iter_bits(mask_a):
            a = lb.bit_length()
            ok = False
            for b in vals_b:
                if abs(a - b) != 1:
                    ok = True
                    break
            if ok:
                new_a |= lb
        mask_a = new_a
    # Filter B
    if popcount(mask_a) <= 2:
        vals_a = mask_to_values(mask_a)
        new_b = 0
        for lb in iter_bits(mask_b):
            b = lb.bit_length()
            ok = False
            for a in vals_a:
                if abs(a - b) != 1:
                    ok = True
                    break
            if ok:
                new_b |= lb
        mask_b = new_b
    return mask_a & all_mask, mask_b & all_mask

def build_edges(observation):
    data = observation["data"]
    N = len(data)
    dot_midpoints = set(tuple(x) for x in observation.get("adjacent", []))

    def has_dot_between(r1, c1, r2, c2):
        if r1 == r2 and abs(c1 - c2) == 1:
            rr = float(r1)
            cc = min(c1, c2) + 0.5
            return (rr, cc) in dot_midpoints
        if c1 == c2 and abs(r1 - r2) == 1:
            rr = min(r1, r2) + 0.5
            cc = float(c1)
            return (rr, cc) in dot_midpoints
        return False

    edges = []
    # store edge constraints for all orthogonal adjacencies
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                dotted = has_dot_between(r, c, r, c + 1)
                edges.append(((r, c), (r, c + 1), dotted))
            if r + 1 < N:
                dotted = has_dot_between(r, c, r + 1, c)
                edges.append(((r, c), (r + 1, c), dotted))
    return N, edges

def solve(observation):
    data = observation["data"]
    N, edges = build_edges(observation)
    all_mask = (1 << N) - 1

    # Domains as bitmasks
    dom = [[all_mask for _ in range(N)] for __ in range(N)]
    row_used = [0] * N
    col_used = [0] * N

    # Apply givens
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                m = bit(v)
                if (row_used[r] & m) or (col_used[c] & m):
                    return "No Solution"
                dom[r][c] = m
                row_used[r] |= m
                col_used[c] |= m

    # Precompute neighbor list from edges for propagation
    neighbors = [[[] for _ in range(N)] for __ in range(N)]
    for (a, b, dotted) in edges:
        (r1, c1) = a
        (r2, c2) = b
        neighbors[r1][c1].append((r2, c2, dotted))
        neighbors[r2][c2].append((r1, c1, dotted))

    # Constraint propagation queue
    def enqueue_cell(q, r, c):
        q.append((r, c))

    def propagate(dom, row_used, col_used):
        q = deque()
        inq = [[False]*N for _ in range(N)]
        # Initialize with all cells (cheap at N<=9/10; still OK)
        for r in range(N):
            for c in range(N):
                q.append((r, c))
                inq[r][c] = True

        while q:
            r, c = q.popleft()
            inq[r][c] = False

            # Remove used numbers from domain
            used = row_used[r] | col_used[c]
            nd = dom[r][c] & ~used
            if nd != dom[r][c]:
                dom[r][c] = nd
                if nd == 0:
                    return False
                # if singleton, update used masks
                if nd & (nd - 1) == 0:
                    vbit = nd
                    if not (row_used[r] & vbit):
                        row_used[r] |= vbit
                        # row change affects all cells in row
                        for cc in range(N):
                            if cc != c and not inq[r][cc]:
                                q.append((r, cc)); inq[r][cc] = True
                    if not (col_used[c] & vbit):
                        col_used[c] |= vbit
                        for rr in range(N):
                            if rr != r and not inq[rr][c]:
                                q.append((rr, c)); inq[rr][c] = True

                # domain change affects neighbors for consecutive constraints
                for (rr, cc, _) in neighbors[r][c]:
                    if not inq[rr][cc]:
                        q.append((rr, cc)); inq[rr][cc] = True

            # If singleton, enforce dotted/non-dotted edges arc-consistency
            for (rr, cc, dotted) in neighbors[r][c]:
                a = dom[r][c]
                b = dom[rr][cc]
                if dotted:
                    na, nb = remove_nonconsecutive_pairs(a, b, N)
                    if na != a:
                        dom[r][c] = na
                        if na == 0:
                            return False
                        if not inq[r][c]:
                            q.append((r, c)); inq[r][c] = True
                    if nb != b:
                        dom[rr][cc] = nb
                        if nb == 0:
                            return False
                        if not inq[rr][cc]:
                            q.append((rr, cc)); inq[rr][cc] = True
                else:
                    na, nb = remove_consecutive_pairs(a, b, N)
                    if na != a:
                        dom[r][c] = na
                        if na == 0:
                            return False
                        if not inq[r][c]:
                            q.append((r, c)); inq[r][c] = True
                    if nb != b:
                        dom[rr][cc] = nb
                        if nb == 0:
                            return False
                        if not inq[rr][cc]:
                            q.append((rr, cc)); inq[rr][cc] = True

            # Hidden singles in row/col (human-like)
            # Only check when this cell updated; still okay to scan row/col each time due to small N.
            # Row hidden single
            miss = all_mask & ~row_used[r]
            if miss:
                # count occurrences
                counts = [0]*N
                last_pos = [-1]*N
                for cc in range(N):
                    m = dom[r][cc] & ~ (col_used[cc] | row_used[r])
                    # note: dom already should have removed used; but re-mask for safety
                    for lb in iter_bits(m):
                        idx = lb.bit_length() - 1
                        counts[idx] += 1
                        last_pos[idx] = cc
                for idx, cnt in enumerate(counts):
                    if cnt == 1:
                        cc = last_pos[idx]
                        vbit = 1 << idx
                        if dom[r][cc] != vbit:
                            dom[r][cc] = vbit
                            if not inq[r][cc]:
                                q.append((r, cc)); inq[r][cc] = True

            # Col hidden single
            miss = all_mask & ~col_used[c]
            if miss:
                counts = [0]*N
                last_pos = [-1]*N
                for rr in range(N):
                    m = dom[rr][c] & ~ (row_used[rr] | col_used[c])
                    for lb in iter_bits(m):
                        idx = lb.bit_length() - 1
                        counts[idx] += 1
                        last_pos[idx] = rr
                for idx, cnt in enumerate(counts):
                    if cnt == 1:
                        rr = last_pos[idx]
                        vbit = 1 << idx
                        if dom[rr][c] != vbit:
                            dom[rr][c] = vbit
                            if not inq[rr][c]:
                                q.append((rr, c)); inq[rr][c] = True

        return True

    def is_solved(dom):
        for r in range(N):
            for c in range(N):
                m = dom[r][c]
                if m == 0 or (m & (m - 1)) != 0:
                    return False
        return True

    def select_cell(dom, row_used, col_used):
        # MRV with tie-break on strongest dot connectivity (more dotted neighbors)
        best = None
        best_size = 999
        best_score = -1
        for r in range(N):
            for c in range(N):
                m = dom[r][c] & ~(row_used[r] | col_used[c])
                k = popcount(m)
                if k > 1 and k < best_size:
                    score = sum(1 for (_, _, d) in neighbors[r][c] if d)
                    best = (r, c, m)
                    best_size = k
                    best_score = score
                elif k > 1 and k == best_size:
                    score = sum(1 for (_, _, d) in neighbors[r][c] if d)
                    if score > best_score:
                        best = (r, c, m)
                        best_score = score
        return best

    def order_values(r, c, mask, dom):
        # Least-constraining value heuristic using consecutive constraints:
        # prefer values that keep dotted neighbors feasible and reduce conflicts.
        vals = mask_to_values(mask)
        scored = []
        for v in vals:
            vb = bit(v)
            penalty = 0
            # row/col impact: less relevant as Latin constraint uniform; still count how many cells lose this value
            for cc in range(N):
                if cc != c and (dom[r][cc] & vb):
                    penalty += 1
            for rr in range(N):
                if rr != r and (dom[rr][c] & vb):
                    penalty += 1
            # dotted neighbors: must be consecutive; measure how many options remain
            for (rr, cc, dotted) in neighbors[r][c]:
                m2 = dom[rr][cc]
                if dotted:
                    cons = consecutive_mask_for_values(vb, N)
                    penalty += 5 * (popcount(m2) - popcount(m2 & cons))
                else:
                    cons = consecutive_mask_for_values(vb, N)
                    penalty += 2 * popcount(m2 & cons)  # forbidden
            scored.append((penalty, v))
        scored.sort()
        return [v for _, v in scored]

    def clone_state(dom, row_used, col_used):
        return [row[:] for row in dom], row_used[:], col_used[:]

    def search(dom, row_used, col_used):
        if not propagate(dom, row_used, col_used):
            return None
        if is_solved(dom):
            return dom
        sel = select_cell(dom, row_used, col_used)
        if sel is None:
            return None
        r, c, mask = sel
        # try values
        for v in order_values(r, c, mask, dom):
            dom2, ru2, cu2 = clone_state(dom, row_used, col_used)
            vb = bit(v)
            dom2[r][c] = vb
            # immediate used update
            if (ru2[r] & vb) or (cu2[c] & vb):
                continue
            ru2[r] |= vb
            cu2[c] |= vb
            res = search(dom2, ru2, cu2)
            if res is not None:
                return res
        return None

    # Initial propagation and search
    dom0, ru0, cu0 = clone_state(dom, row_used, col_used)
    sol = search(dom0, ru0, cu0)
    if sol is None:
        return "No Solution"
    grid = [[(sol[r][c].bit_length()) for c in range(N)] for r in range(N)]
    return str(grid)

