from __future__ import annotations

# Generalized solver for "Consecutive Dots Latin Square" (a.k.a. Kropki-like consecutive constraints without ratio dots).
# Rules:
#  - N x N Latin square: numbers 1..N each row/col exactly once.
#  - Dot between orthogonally adjacent cells => values consecutive (abs diff == 1).
#  - No dot => values NOT consecutive.
#
# Strategy (human-like deduction + strong propagation, then limited search):
#  - Maintain domains per cell (bitmasks).
#  - Enforce givens.
#  - Repeatedly apply:
#     * Latin constraints: remove used values from peers; hidden singles in row/col.
#     * Consecutive-dot constraints: arc-consistency between adjacent cells.
#     * Non-dot constraints: forbid consecutive pairs between adjacent cells.
#     * Stronger local rules:
#         - If cell is 1 then dotted neighbors must be 2; if cell is N then dotted neighbors must be N-1.
#         - If cell is 1 then non-dotted neighbors cannot be 2; similarly N cannot have N-1 on non-dots.
#     * Optional: "row/col value placement" (hidden singles via union masks).
#  - Search:
#     * Choose cell with smallest domain (MRV) and branch.
#     * Value ordering: prefer values that satisfy most adjacency constraints quickly.
#
# Implementation notes:
#  - Use bit operations for speed.
#  - Represent values 1..N as bits 0..N-1.

def solve(observation):
    data = observation["data"]
    N = len(data)
    if N == 0 or any(len(r) != N for r in data):
        return "No Solution"

    # Build adjacency: for each cell index i=r*N+c, store dotted neighbors and non-dotted neighbors.
    dotted = [set() for _ in range(N*N)]
    # Determine dot midpoints set for O(1) membership
    dot_set = set()
    for rc in observation.get("adjacent", []):
        if not (isinstance(rc, (list, tuple)) and len(rc) == 2):
            continue
        dot_set.add((float(rc[0]), float(rc[1])))

    def idx(r, c): return r * N + c

    # For each orthogonal edge, classify as dotted or not
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                mid = (float(r), float(c) + 0.5)
                a = idx(r, c); b = idx(r, c+1)
                if mid in dot_set:
                    dotted[a].add(b); dotted[b].add(a)
            if r + 1 < N:
                mid = (float(r) + 0.5, float(c))
                a = idx(r, c); b = idx(r+1, c)
                if mid in dot_set:
                    dotted[a].add(b); dotted[b].add(a)

    # Non-dotted neighbors are simply all orthogonal neighbors minus dotted.
    nondotted = [set() for _ in range(N*N)]
    for r in range(N):
        for c in range(N):
            a = idx(r, c)
            if c > 0: nondotted[a].add(idx(r, c-1))
            if c + 1 < N: nondotted[a].add(idx(r, c+1))
            if r > 0: nondotted[a].add(idx(r-1, c))
            if r + 1 < N: nondotted[a].add(idx(r+1, c))
            nondotted[a] -= dotted[a]

    ALL = (1 << N) - 1

    # Precompute consecutive masks for each value (1..N) and for each domain bitmask.
    cons_of_val = [0] * (N + 1)  # 1..N
    for v in range(1, N + 1):
        m = 0
        if v > 1: m |= 1 << (v - 2)
        if v < N: m |= 1 << v
        cons_of_val[v] = m

    # For a domain bitmask, return mask of values consecutive to any value in domain.
    cons_of_mask = [0] * (1 << N)
    for m in range(1 << N):
        out = 0
        mm = m
        while mm:
            lsb = mm & -mm
            i = (lsb.bit_length() - 1)  # 0-based value index
            v = i + 1
            out |= cons_of_val[v]
            mm -= lsb
        cons_of_mask[m] = out

    # For a domain bitmask, return mask of values that have at least one consecutive partner in neighbor domain.
    # This is computed on the fly with cons_of_mask[neighbor_domain] intersect current_domain.
    def has_single_bit(m): return m and (m & (m - 1)) == 0

    def bit_to_val(bit):  # bit has single set
        return bit.bit_length()

    def iter_bits(m):
        while m:
            b = m & -m
            yield b
            m -= b

    # Initialize domains
    dom = [ALL] * (N * N)
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= int(v) <= N):
                    return "No Solution"
                dom[idx(r, c)] = 1 << (int(v) - 1)

    # Row/col peer lists
    row_cells = [[idx(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[idx(r, c) for r in range(N)] for c in range(N)]
    peers = [set() for _ in range(N*N)]
    for r in range(N):
        rc = row_cells[r]
        for a in rc:
            peers[a].update(rc)
    for c in range(N):
        cc = col_cells[c]
        for a in cc:
            peers[a].update(cc)
    for i in range(N*N):
        peers[i].discard(i)

    # Efficient row/col used masks (updated from dom when fixed)
    def compute_used():
        row_used = [0] * N
        col_used = [0] * N
        for r in range(N):
            for c in range(N):
                i = idx(r, c)
                if has_single_bit(dom[i]):
                    b = dom[i]
                    row_used[r] |= b
                    col_used[c] |= b
        return row_used, col_used

    # Propagation
    def propagate(dom):
        row_used, col_used = compute_used()

        # Queue of cells to process when domain changes
        # Use list as stack for speed.
        stack = [i for i in range(N*N)]

        in_stack = [True] * (N*N)

        def push(i):
            if not in_stack[i]:
                in_stack[i] = True
                stack.append(i)

        def remove_from_rowcol(i, old_mask, new_mask):
            # If fixed newly, update used masks.
            if has_single_bit(new_mask) and not has_single_bit(old_mask):
                r, c = divmod(i, N)
                row_used[r] |= new_mask
                col_used[c] |= new_mask

        while stack:
            i = stack.pop()
            in_stack[i] = False
            m = dom[i]
            if m == 0:
                return False

            r, c = divmod(i, N)

            # 1) Latin: remove already-used values in row/col
            used = row_used[r] | col_used[c]
            if not has_single_bit(m):
                nm = m & ~used
                if nm != m:
                    old = m
                    dom[i] = nm
                    m = nm
                    if m == 0:
                        return False
                    remove_from_rowcol(i, old, m)
                    # peers and neighbors affected
                    for p in peers[i]:
                        push(p)
                    for nb in dotted[i]:
                        push(nb)
                    for nb in nondotted[i]:
                        push(nb)

            # 2) If fixed, enforce removal to peers strongly
            if has_single_bit(m):
                b = m
                # Remove from peers
                for p in peers[i]:
                    pm = dom[p]
                    if pm & b:
                        old = pm
                        dom[p] = pm & ~b
                        if dom[p] == 0:
                            return False
                        remove_from_rowcol(p, old, dom[p])
                        push(p)
                        for nb in dotted[p]:
                            push(nb)
                        for nb in nondotted[p]:
                            push(nb)

            # 3) Dot constraints: arc consistency with dotted neighbors
            # For each dotted edge i-j: dom[i] ⊆ cons(dom[j]) and dom[j] ⊆ cons(dom[i])
            for j in dotted[i]:
                mi = dom[i]
                mj = dom[j]
                # Filter i based on j
                allow_i = cons_of_mask[mj]
                nmi = mi & allow_i
                if nmi != mi:
                    old = mi
                    dom[i] = nmi
                    if nmi == 0:
                        return False
                    remove_from_rowcol(i, old, nmi)
                    push(i)
                    for p in peers[i]:
                        push(p)
                    for nb in dotted[i]:
                        push(nb)
                    for nb in nondotted[i]:
                        push(nb)
                    break  # restart processing i after change

                # Filter j based on i
                allow_j = cons_of_mask[mi]
                nmj = mj & allow_j
                if nmj != mj:
                    old = mj
                    dom[j] = nmj
                    if nmj == 0:
                        return False
                    remove_from_rowcol(j, old, nmj)
                    push(j)
                    for p in peers[j]:
                        push(p)
                    for nb in dotted[j]:
                        push(nb)
                    for nb in nondotted[j]:
                        push(nb)

            # 4) Non-dot constraints: forbid consecutive across non-dotted neighbors
            # If i has value v, then neighbor cannot be v-1 or v+1.
            if has_single_bit(dom[i]):
                v = bit_to_val(dom[i])
                forbid = cons_of_val[v]
                for j in nondotted[i]:
                    mj = dom[j]
                    nmj = mj & ~forbid
                    if nmj != mj:
                        old = mj
                        dom[j] = nmj
                        if nmj == 0:
                            return False
                        remove_from_rowcol(j, old, nmj)
                        push(j)
                        for p in peers[j]:
                            push(p)
                        for nb in dotted[j]:
                            push(nb)
                        for nb in nondotted[j]:
                            push(nb)

            # 5) Endpoint rule: if i can only be {1} or {N} then dotted neighbors forced accordingly
            # Already covered by arc consistency, but adding direct pruning for speed on fixed endpoints.
            if has_single_bit(dom[i]):
                v = bit_to_val(dom[i])
                if v == 1:
                    req = 1 << 1  # 2
                    for j in dotted[i]:
                        mj = dom[j]
                        nmj = mj & req
                        if nmj != mj:
                            old = mj
                            dom[j] = nmj
                            if nmj == 0:
                                return False
                            remove_from_rowcol(j, old, nmj)
                            push(j)
                elif v == N:
                    req = 1 << (N - 2)  # N-1
                    for j in dotted[i]:
                        mj = dom[j]
                        nmj = mj & req
                        if nmj != mj:
                            old = mj
                            dom[j] = nmj
                            if nmj == 0:
                                return False
                            remove_from_rowcol(j, old, nmj)
                            push(j)

        # Hidden singles in each row/col
        for r in range(N):
            cells = row_cells[r]
            # For each value, count positions
            pos = [0] * N  # bitmask of cells? keep last seen idx and count via integer
            cnt = [0] * N
            for i in cells:
                m = dom[i]
                for b in iter_bits(m):
                    k = b.bit_length() - 1
                    cnt[k] += 1
                    pos[k] = i
            for k in range(N):
                if cnt[k] == 0:
                    return False
                if cnt[k] == 1:
                    i = pos[k]
                    need = 1 << k
                    if dom[i] != need:
                        old = dom[i]
                        dom[i] = need
                        if dom[i] == 0:
                            return False
                        # update used + push affected
                        row_used[r] |= need
                        col_used[i % N] |= need
                        for p in peers[i]:
                            push(p)
                        for nb in dotted[i]:
                            push(nb)
                        for nb in nondotted[i]:
                            push(nb)

        for c in range(N):
            cells = col_cells[c]
            pos = [0] * N
            cnt = [0] * N
            for i in cells:
                m = dom[i]
                for b in iter_bits(m):
                    k = b.bit_length() - 1
                    cnt[k] += 1
                    pos[k] = i
            for k in range(N):
                if cnt[k] == 0:
                    return False
                if cnt[k] == 1:
                    i = pos[k]
                    need = 1 << k
                    if dom[i] != need:
                        old = dom[i]
                        dom[i] = need
                        if dom[i] == 0:
                            return False
                        row_used[i // N] |= need
                        col_used[c] |= need
                        for p in peers[i]:
                            push(p)
                        for nb in dotted[i]:
                            push(nb)
                        for nb in nondotted[i]:
                            push(nb)

        return True

    def is_solved(dom):
        return all(has_single_bit(m) for m in dom)

    # Heuristic: select unfilled cell with MRV
    def select_cell(dom):
        best_i = -1
        best_sz = 10**9
        for i, m in enumerate(dom):
            if not has_single_bit(m):
                sz = m.bit_count()
                if sz < best_sz:
                    best_sz = sz
                    best_i = i
                    if sz == 2:
                        break
        return best_i

    # Value ordering: favor values that satisfy dotted neighbors (i.e., allow more in neighbors) and avoid creating conflicts
    def order_values(i, dom):
        m = dom[i]
        r, c = divmod(i, N)
        neigh_dot = dotted[i]
        neigh_nodot = nondotted[i]
        used = 0
        # used in row/col
        for j in row_cells[r]:
            if has_single_bit(dom[j]): used |= dom[j]
        for j in col_cells[c]:
            if has_single_bit(dom[j]): used |= dom[j]
        vals = []
        for b in iter_bits(m):
            v = b.bit_length()
            score = 0
            # penalize conflicts quickly (should already be avoided)
            if used & b:
                score -= 1000
            # dotted neighbors: prefer v that keeps their domains larger
            cm = cons_of_val[v]
            for j in neigh_dot:
                score += (dom[j] & cm).bit_count()
            # non-dotted neighbors: prefer v that eliminates fewer options (keep flexibility)
            forbid = cm
            for j in neigh_nodot:
                score += (dom[j] & ~forbid).bit_count()
            vals.append(( -score, b))
        vals.sort()
        return [b for _, b in vals]

    # DFS with propagation; not "blind brute force" due to heavy propagation and strong heuristics.
    def dfs(dom, depth=0):
        if not propagate(dom):
            return None
        if is_solved(dom):
            return dom
        i = select_cell(dom)
        if i < 0:
            return None
        for b in order_values(i, dom):
            nd = dom[:]  # shallow copy OK (ints)
            nd[i] = b
            res = dfs(nd, depth + 1)
            if res is not None:
                return res
        return None

    dom0 = dom[:]
    res = dfs(dom0)
    if res is None:
        return "No Solution"
    out = []
    for r in range(N):
        row = []
        for c in range(N):
            v = bit_to_val(res[idx(r, c)])
            row.append(v)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

