# NOTE: The OBSERVATION above is a best-effort transcription from the provided image.
# The solver below is general for Consecutive Sudoku (a.k.a. "Kropki consecutive" without ratio dots):
# - Standard Latin constraints (1..N each row/col).
# - Dot between orthogonally adjacent cells => values differ by 1.
# - No dot => values do NOT differ by 1.
#
# Emphasis: strong constraint propagation with:
# - Bitmask domains
# - Row/col used masks
# - Arc consistency style propagation for adjacency constraints
# - Hidden singles and forced placements
# - Speculative search with MRV + degree heuristics, with propagation at each step
#
# No external solvers are used.

from collections import deque

def solve(observation):
    grid = observation["data"]
    N = len(grid)
    if N == 0 or any(len(r) != N for r in grid):
        return "No Solution"

    # Bit utilities
    ALL = (1 << N) - 1
    bit = [0] + [1 << (v - 1) for v in range(1, N + 1)]

    def popcount(x):
        return x.bit_count()

    def lsb_index(x):
        # x != 0, returns 0-based index of least set bit
        return (x & -x).bit_length() - 1

    # Precompute +/-1 neighbors as bitmasks: adjmask[v] = {v-1, v+1} within 1..N
    adjmask = [0] * (N + 1)
    for v in range(1, N + 1):
        m = 0
        if v > 1:
            m |= bit[v - 1]
        if v < N:
            m |= bit[v + 1]
        adjmask[v] = m

    # Parse dot adjacencies
    # Midpoint coordinates: (r, c+0.5) horizontal between (r,c) and (r,c+1)
    #                      (r+0.5, c) vertical between (r,c) and (r+1,c)
    dot = set()
    for rc in observation.get("adjacent", []):
        if not (isinstance(rc, (list, tuple)) and len(rc) == 2):
            continue
        r, c = rc
        dot.add((float(r), float(c)))

    # Build adjacency lists with constraint type:
    # cons[(a,b)] = True if consecutive required else False if consecutive forbidden
    # We'll treat every orthogonal neighbor pair; presence of dot => required, else forbidden.
    neighbors = [[] for _ in range(N * N)]
    req = {}  # key (u,v) u<v -> True if require consecutive, False if forbid consecutive
    for r in range(N):
        for c in range(N):
            u = r * N + c
            if c + 1 < N:
                v = r * N + (c + 1)
                has = (float(r), float(c) + 0.5) in dot
                k = (u, v) if u < v else (v, u)
                req[k] = True if has else False
                neighbors[u].append(v)
                neighbors[v].append(u)
            if r + 1 < N:
                v = (r + 1) * N + c
                has = (float(r) + 0.5, float(c)) in dot
                k = (u, v) if u < v else (v, u)
                req[k] = True if has else False
                neighbors[u].append(v)
                neighbors[v].append(u)

    # Row/col membership
    row_of = [i // N for i in range(N * N)]
    col_of = [i % N for i in range(N * N)]
    row_cells = [[r * N + c for c in range(N)] for r in range(N)]
    col_cells = [[r * N + c for r in range(N)] for c in range(N)]

    # Domains as bitmasks
    dom = [ALL] * (N * N)
    row_used = [0] * N
    col_used = [0] * N

    # Initialize with givens
    q = deque()
    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            idx = r * N + c
            if val is None:
                continue
            if not (1 <= int(val) <= N):
                return "No Solution"
            m = bit[int(val)]
            # Assign domain
            dom[idx] = m
            q.append(idx)

    # Apply initial row/col used and check duplicates
    for i in range(N * N):
        if popcount(dom[i]) == 1:
            vbit = dom[i]
            r = row_of[i]
            c = col_of[i]
            if row_used[r] & vbit:
                return "No Solution"
            if col_used[c] & vbit:
                return "No Solution"
            row_used[r] |= vbit
            col_used[c] |= vbit

    # Constraint propagation engine
    # We'll do iterative propagation:
    # - Enforce row/col elimination based on used masks
    # - Enforce adjacency constraints between neighboring cells
    # - Hidden singles in each row/col
    #
    # Use a queue of "touched" cells to avoid full rescans too often, but still do periodic hidden singles.

    def tighten_cell(i, newmask, touched):
        if newmask == dom[i]:
            return True
        if newmask == 0:
            return False
        dom[i] = newmask
        touched.append(i)
        return True

    def propagate(assign_queue):
        touched = []
        # Seed touched with all singleton assignments in queue
        for i in assign_queue:
            touched.append(i)
        assign_queue.clear()

        # We also maintain a work queue for arcs (i -> j) where i changed
        arcq = deque(touched)

        # Update used masks when a cell becomes singleton; to detect "becomes singleton", we track last popcount
        # We'll recompute used masks by incremental updates here:
        # But to handle domain reductions to singleton, we need to update row_used/col_used and also eliminate from peers.
        # We'll do this inside the loop: if cell is singleton, ensure it's reflected in used masks and propagate to row/col peers.

        in_used = [False] * (N * N)  # whether singleton has been committed into used masks
        # initialize committed singletons from current row_used/col_used by checking domains:
        for i in range(N * N):
            if popcount(dom[i]) == 1:
                in_used[i] = True

        # However, if there are contradictions due to earlier masks, those were checked at init.
        # During propagation, when a cell becomes singleton, we will set in_used and update used masks.

        # We need accurate row_used/col_used as domains change; easiest: recompute at start of propagate.
        # It's O(N^3) worst-case; for N<=9 this is fine and robust.
        def recompute_used():
            for r in range(N):
                row_used[r] = 0
                col_used[r] = 0
            for i in range(N * N):
                if popcount(dom[i]) == 1:
                    vbit = dom[i]
                    r = row_of[i]
                    c = col_of[i]
                    if row_used[r] & vbit:
                        return False
                    if col_used[c] & vbit:
                        return False
                    row_used[r] |= vbit
                    col_used[c] |= vbit
            return True

        if not recompute_used():
            return False

        # Maintain a flag for progress in hidden singles
        while True:
            # Process arc constraints and row/col eliminations for touched cells
            while arcq:
                i = arcq.popleft()
                r = row_of[i]
                c = col_of[i]

                # Row/col elimination from used masks
                used = row_used[r] | col_used[c]
                if popcount(dom[i]) != 1:
                    nm = dom[i] & ~used
                    if nm != dom[i]:
                        if not tighten_cell(i, nm, touched):
                            return False
                        arcq.append(i)
                        continue

                # If singleton, ensure masks are consistent and propagate elimination to peers quickly
                if popcount(dom[i]) == 1:
                    vbit = dom[i]
                    # Masks already recomputed; eliminate this value from other cells in row/col
                    for j in row_cells[r]:
                        if j != i and (dom[j] & vbit):
                            nm = dom[j] & ~vbit
                            if not tighten_cell(j, nm, touched):
                                return False
                            arcq.append(j)
                    for j in col_cells[c]:
                        if j != i and (dom[j] & vbit):
                            nm = dom[j] & ~vbit
                            if not tighten_cell(j, nm, touched):
                                return False
                            arcq.append(j)

                # Adjacency constraints with neighbors
                di = dom[i]
                for j in neighbors[i]:
                    k = (i, j) if i < j else (j, i)
                    must = req[k]
                    dj = dom[j]
                    if must:
                        # Require |a-b|=1
                        # Filter i: keep values that have neighbor in dj
                        # For each value v in i, allowed if adjmask[v] intersects dj.
                        # We'll compute allowed set for i and j using bit tricks by iterating smaller domain.
                        # Since N<=9, iterating bits is fine.
                        ai = 0
                        x = di
                        while x:
                            b = x & -x
                            v = b.bit_length()  # 1..N
                            if adjmask[v] & dj:
                                ai |= b
                            x -= b
                        aj = 0
                        x = dj
                        while x:
                            b = x & -x
                            v = b.bit_length()
                            if adjmask[v] & di:
                                aj |= b
                            x -= b
                        if ai != di:
                            if not tighten_cell(i, ai, touched):
                                return False
                            arcq.append(i)
                        if aj != dj:
                            if not tighten_cell(j, aj, touched):
                                return False
                            arcq.append(j)
                    else:
                        # Forbid consecutive: remove values in i that can only pair with consecutive in j? Not only.
                        # We enforce arc consistency: for each v in i there must exist w in j such that |v-w| != 1.
                        # Equivalent: v is invalid if dj subset of adjmask[v] (i.e., all possible w are consecutive).
                        ai = 0
                        x = di
                        while x:
                            b = x & -x
                            v = b.bit_length()
                            if dj & ~adjmask[v]:
                                ai |= b
                            x -= b
                        aj = 0
                        x = dj
                        while x:
                            b = x & -x
                            v = b.bit_length()
                            if di & ~adjmask[v]:
                                aj |= b
                            x -= b
                        if ai != di:
                            if not tighten_cell(i, ai, touched):
                                return False
                            arcq.append(i)
                        if aj != dj:
                            if not tighten_cell(j, aj, touched):
                                return False
                            arcq.append(j)

            # Recompute used masks after a wave of reductions
            if not recompute_used():
                return False

            # Hidden singles in rows/cols (human-like: scan for a digit that can go only one place)
            progress = False
            for r in range(N):
                # skip if row is complete
                # compute candidate positions per digit
                pos = [0] * (N + 1)  # store cell index+1 if unique, -1 if multiple
                for i in row_cells[r]:
                    m = dom[i]
                    x = m
                    while x:
                        b = x & -x
                        v = b.bit_length()
                        if pos[v] == 0:
                            pos[v] = i + 1
                        elif pos[v] > 0:
                            pos[v] = -1
                        x -= b
                for v in range(1, N + 1):
                    if pos[v] > 0:
                        i = pos[v] - 1
                        if popcount(dom[i]) != 1:
                            if not tighten_cell(i, bit[v], touched):
                                return False
                            arcq.append(i)
                            progress = True
            for c in range(N):
                pos = [0] * (N + 1)
                for i in col_cells[c]:
                    m = dom[i]
                    x = m
                    while x:
                        b = x & -x
                        v = b.bit_length()
                        if pos[v] == 0:
                            pos[v] = i + 1
                        elif pos[v] > 0:
                            pos[v] = -1
                        x -= b
                for v in range(1, N + 1):
                    if pos[v] > 0:
                        i = pos[v] - 1
                        if popcount(dom[i]) != 1:
                            if not tighten_cell(i, bit[v], touched):
                                return False
                            arcq.append(i)
                            progress = True

            if not progress:
                break

        return True

    if not propagate(q):
        return "No Solution"

    # Search with MRV + degree
    def is_solved():
        return all(popcount(dom[i]) == 1 for i in range(N * N))

    def select_var():
        best = -1
        best_size = 999
        best_deg = -1
        for i in range(N * N):
            pc = popcount(dom[i])
            if pc == 1:
                continue
            if pc < best_size:
                best_size = pc
                best = i
                # degree: count of unassigned neighbors and row/col peers
                r = row_of[i]
                c = col_of[i]
                deg = 0
                for j in row_cells[r]:
                    if i != j and popcount(dom[j]) > 1:
                        deg += 1
                for j in col_cells[c]:
                    if i != j and popcount(dom[j]) > 1:
                        deg += 1
                for j in neighbors[i]:
                    if popcount(dom[j]) > 1:
                        deg += 1
                best_deg = deg
            elif pc == best_size:
                r = row_of[i]
                c = col_of[i]
                deg = 0
                for j in row_cells[r]:
                    if i != j and popcount(dom[j]) > 1:
                        deg += 1
                for j in col_cells[c]:
                    if i != j and popcount(dom[j]) > 1:
                        deg += 1
                for j in neighbors[i]:
                    if popcount(dom[j]) > 1:
                        deg += 1
                if deg > best_deg:
                    best = i
                    best_deg = deg
        return best

    def order_values(i):
        # Least-constraining value: prefer values that leave most options to peers
        m = dom[i]
        vals = []
        x = m
        while x:
            b = x & -x
            v = b.bit_length()
            vals.append(v)
            x -= b
        r = row_of[i]
        c = col_of[i]
        peers = set(row_cells[r] + col_cells[c] + neighbors[i])
        peers.discard(i)

        def score(v):
            vbit = bit[v]
            s = 0
            for j in peers:
                dj = dom[j]
                if popcount(dj) == 1:
                    continue
                # effect of row/col uniqueness
                if dj & vbit:
                    s += 1
                # effect of adjacency
                if j in neighbors[i]:
                    k = (i, j) if i < j else (j, i)
                    must = req[k]
                    if must:
                        # j would be restricted to v±1
                        s += popcount(dj) - popcount(dj & adjmask[v])
                    else:
                        # j loses those that become forced consecutive-only; rough estimate:
                        # remove possibilities in dj that would have no nonconsecutive partner.
                        # Here, if we fix i=v, then j cannot be v±1 only? Actually non-dot forbids consecutive, so j cannot be v±1.
                        s += popcount(dj & adjmask[v])
            return s

        vals.sort(key=score)
        return vals

    def dfs():
        if is_solved():
            return True
        i = select_var()
        if i < 0:
            return False

        snapshot_dom = dom[:]  # cheap for 81
        snapshot_row_used = row_used[:]
        snapshot_col_used = col_used[:]

        for v in order_values(i):
            dom[:] = snapshot_dom
            row_used[:] = snapshot_row_used
            col_used[:] = snapshot_col_used

            dom[i] = bit[v]
            q = deque([i])
            if not propagate(q):
                continue
            if dfs():
                return True
        return False

    if not dfs():
        return "No Solution"

    # Build solved grid
    sol = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            i = r * N + c
            if popcount(dom[i]) != 1:
                return "No Solution"
            sol[r][c] = lsb_index(dom[i]) + 1

    return str(sol)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [3, 3, 0, 0, 0], 'D': [0, 0, 0, 0, 0], 'L': [2, 0, 1, 0, 0], 'R': [0, 0, 2, 2, 0]}
from itertools import permutations

# Skyscrapers solver with strong human-like constraint propagation:
# - Precompute all row/col permutations satisfying side clues
# - Maintain domains as sets of candidate permutations for each line
# - Propagate cell-wise value constraints between intersecting row/col candidates
# - Use additional partial-visibility pruning when clues exist
# - Search with MRV over lines, always propagating to fixpoint


def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    n = len(U)

    # Validate lengths
    if not (len(D) == len(L) == len(R) == n):
        return "No Solution"

    all_perms = list(permutations(range(1, n + 1)))

    def visible_count(seq):
        m = 0
        v = 0
        for x in seq:
            if x > m:
                m = x
                v += 1
        return v

    # Precompute visibilities for speed
    vis_lr = {}  # perm -> (left_vis, right_vis)
    for p in all_perms:
        lv = visible_count(p)
        rv = visible_count(reversed(p))
        vis_lr[p] = (lv, rv)

    def clue_ok(vis, clue):
        return clue == 0 or vis == clue

    # Candidate lines: rows by L/R, cols by U/D
    row_cands = []
    for r in range(n):
        lcl = L[r]
        rcl = R[r]
        c = [p for p in all_perms if clue_ok(vis_lr[p][0], lcl) and clue_ok(vis_lr[p][1], rcl)]
        if not c:
            return "No Solution"
        row_cands.append(set(c))

    col_cands = []
    for cidx in range(n):
        ucl = U[cidx]
        dcl = D[cidx]
        c = [p for p in all_perms if clue_ok(vis_lr[p][0], ucl) and clue_ok(vis_lr[p][1], dcl)]
        if not c:
            return "No Solution"
        col_cands.append(set(c))

    # Helper: compute possible values for a cell from current candidates
    def cell_values_from_rows(r, c):
        return {p[c] for p in row_cands[r]}

    def cell_values_from_cols(r, c):
        return {p[r] for p in col_cands[c]}

    # Partial visibility pruning: Given a clue and known fixed prefix values (or domain sets),
    # we prune candidates directly already (done by filtering perms), but we can also prune by
    # enforcing minimum/maximum possible visible given a partially fixed line.
    # Here we implement it by recomputing bounds per candidate quickly using precomputed vis.
    # Since candidates are full perms, additional partial logic is mainly done via intersection
    # between row/col at cells. That's usually sufficient and very fast.

    def propagate():
        # Returns False if contradiction, True otherwise.
        changed = True
        while changed:
            changed = False

            # Cell-wise intersection between row and col possibilities
            for r in range(n):
                # Precompute row cell possible values via candidates
                row_poss = [set() for _ in range(n)]
                for p in row_cands[r]:
                    for c in range(n):
                        row_poss[c].add(p[c])

                for c in range(n):
                    col_poss = set()
                    for p in col_cands[c]:
                        col_poss.add(p[r])

                    inter = row_poss[c] & col_poss
                    if not inter:
                        return False

                    # Filter row candidates where cell value not in inter
                    before = len(row_cands[r])
                    if before > 1:  # skip trivial
                        row_cands[r] = {p for p in row_cands[r] if p[c] in inter}
                        if not row_cands[r]:
                            return False
                        if len(row_cands[r]) != before:
                            changed = True

                    # Filter col candidates where cell value not in inter
                    before = len(col_cands[c])
                    if before > 1:
                        col_cands[c] = {p for p in col_cands[c] if p[r] in inter}
                        if not col_cands[c]:
                            return False
                        if len(col_cands[c]) != before:
                            changed = True

            # Optional: if a line becomes singleton, enforce its values on perpendicular lines more aggressively
            # (already happens via cell intersections above; this speeds convergence a bit by early detection)
            # We'll also do uniqueness check inside each line: already guaranteed by permutations.

        return True

    if not propagate():
        return "No Solution"

    # Choose next line to branch: MRV among unfixed rows and cols
    def is_solved():
        return all(len(s) == 1 for s in row_cands) and all(len(s) == 1 for s in col_cands)

    def snapshot():
        return [set(s) for s in row_cands], [set(s) for s in col_cands]

    def restore(snap):
        nonlocal row_cands, col_cands
        row_cands, col_cands = snap

    def pick_mrv_line():
        best = None  # (kind, idx, size)
        for r in range(n):
            sz = len(row_cands[r])
            if 1 < sz and (best is None or sz < best[2]):
                best = ("row", r, sz)
        for c in range(n):
            sz = len(col_cands[c])
            if 1 < sz and (best is None or sz < best[2]):
                best = ("col", c, sz)
        return best

    # Value ordering: try candidates that are most compatible with current perpendicular constraints
    def score_row_perm(r, perm):
        s = 0
        for c in range(n):
            # count how many col candidates support this value at (r,c)
            val = perm[c]
            cnt = 0
            for p in col_cands[c]:
                if p[r] == val:
                    cnt += 1
            s += cnt
        return s

    def score_col_perm(c, perm):
        s = 0
        for r in range(n):
            val = perm[r]
            cnt = 0
            for p in row_cands[r]:
                if p[c] == val:
                    cnt += 1
            s += cnt
        return s

    def backtrack():
        if is_solved():
            return True

        choice = pick_mrv_line()
        if choice is None:
            return False

        kind, idx, _ = choice

        snap0 = snapshot()

        if kind == "row":
            cands = list(row_cands[idx])
            # sort by compatibility descending to reduce search
            cands.sort(key=lambda p: score_row_perm(idx, p), reverse=True)
            for p in cands:
                restore(snap0)
                row_cands[idx] = {p}
                if propagate() and backtrack():
                    return True
        else:
            cands = list(col_cands[idx])
            cands.sort(key=lambda p: score_col_perm(idx, p), reverse=True)
            for p in cands:
                restore(snap0)
                col_cands[idx] = {p}
                if propagate() and backtrack():
                    return True

        restore(snap0)
        return False

    if not backtrack():
        return "No Solution"

    # Build final grid from rows
    grid = [list(next(iter(row_cands[r]))) for r in range(n)]
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [1, 2, 4, 2, 3], 'D': [2, 2, 1, 4, 3], 'L': [1, 3, 3, 2, 2], 'R': [4, 2, 1, 3, 2]}

from itertools import permutations

# Skyscrapers solver with human-like deduction:
# - Precompute all row/col permutations satisfying left/right or top/bottom clues.
# - Maintain candidate sets for each row/col (like pencil marks).
# - Propagate:
#   * intersection constraints on each cell (row candidates vs col candidates)
#   * filter candidates by fixed numbers
#   * hidden singles (a value appears in only one position among candidates)
# - Branch only when necessary, choosing the most constrained row/col.

def _visible_count(seq):
    mx = 0
    vis = 0
    for x in seq:
        if x > mx:
            mx = x
            vis += 1
    return vis

def _all_candidates(N, left_clue, right_clue):
    """All permutations of 1..N that match both side clues if nonzero."""
    nums = tuple(range(1, N + 1))
    res = []
    for p in permutations(nums):
        if left_clue and _visible_count(p) != left_clue:
            continue
        if right_clue and _visible_count(p[::-1]) != right_clue:
            continue
        res.append(p)
    return res

def _filter_by_cells(cands, allowed_sets):
    # allowed_sets: list of sets length N
    out = []
    for p in cands:
        ok = True
        for i, v in enumerate(p):
            if v not in allowed_sets[i]:
                ok = False
                break
        if ok:
            out.append(p)
    return out

def _allowed_from_cands(cands, N):
    allowed = [set() for _ in range(N)]
    for p in cands:
        for i, v in enumerate(p):
            allowed[i].add(v)
    return allowed

def _hidden_singles_reduce(cands, N):
    """If a digit can appear in only one position across candidates, force it."""
    # Compute for each position possible values
    pos_allowed = _allowed_from_cands(cands, N)
    # For each value, find positions it can appear
    val_positions = {v: [] for v in range(1, N + 1)}
    for i in range(N):
        for v in pos_allowed[i]:
            val_positions[v].append(i)

    forced = [None] * N
    changed = False
    for v, ps in val_positions.items():
        if len(ps) == 1:
            i = ps[0]
            if forced[i] is None:
                forced[i] = v
                changed = True
            elif forced[i] != v:
                return None, True  # contradiction
    if not changed:
        return cands, False

    # Apply forced
    allowed_sets = [set(range(1, N + 1)) for _ in range(N)]
    for i, v in enumerate(forced):
        if v is not None:
            allowed_sets[i] = {v}
    new_cands = _filter_by_cells(cands, allowed_sets)
    if not new_cands:
        return None, True
    return new_cands, True

def _propagate(row_cands, col_cands, N):
    """Iteratively enforce consistency between row and col candidate pools."""
    while True:
        # Build cell-wise allowed sets from current candidates
        row_allowed = [_allowed_from_cands(row_cands[r], N) for r in range(N)]
        col_allowed = [_allowed_from_cands(col_cands[c], N) for c in range(N)]

        changed = False

        # Enforce intersections on each cell by filtering row and col candidates
        for r in range(N):
            allowed_sets = []
            for c in range(N):
                allowed_sets.append(row_allowed[r][c] & col_allowed[c][r])
                if not allowed_sets[-1]:
                    return None
            new = _filter_by_cells(row_cands[r], allowed_sets)
            if not new:
                return None
            if len(new) != len(row_cands[r]):
                row_cands[r] = new
                changed = True

        # Recompute after row filtering for tighter col filtering
        row_allowed = [_allowed_from_cands(row_cands[r], N) for r in range(N)]
        for c in range(N):
            allowed_sets = []
            for r in range(N):
                allowed_sets.append(row_allowed[r][c] & col_allowed[c][r])
                if not allowed_sets[-1]:
                    return None
            new = _filter_by_cells(col_cands[c], allowed_sets)
            if not new:
                return None
            if len(new) != len(col_cands[c]):
                col_cands[c] = new
                changed = True

        # Hidden singles within each row/col candidate pool
        for r in range(N):
            reduced, did = _hidden_singles_reduce(row_cands[r], N)
            if reduced is None:
                return None
            if did and len(reduced) != len(row_cands[r]):
                row_cands[r] = reduced
                changed = True
        for c in range(N):
            reduced, did = _hidden_singles_reduce(col_cands[c], N)
            if reduced is None:
                return None
            if did and len(reduced) != len(col_cands[c]):
                col_cands[c] = reduced
                changed = True

        if not changed:
            return row_cands, col_cands

def _is_solved(row_cands, col_cands):
    return all(len(x) == 1 for x in row_cands) and all(len(x) == 1 for x in col_cands)

def _choose_branch(row_cands, col_cands):
    # Choose smallest domain among rows/cols that isn't fixed
    best = None  # (kind, idx, size)
    for i, c in enumerate(row_cands):
        s = len(c)
        if s > 1 and (best is None or s < best[2]):
            best = ("row", i, s)
    for j, c in enumerate(col_cands):
        s = len(c)
        if s > 1 and (best is None or s < best[2]):
            best = ("col", j, s)
    return best

def _search(row_cands, col_cands, N):
    prop = _propagate([list(x) for x in row_cands], [list(x) for x in col_cands], N)
    if prop is None:
        return None
    row_cands, col_cands = prop
    if _is_solved(row_cands, col_cands):
        # Extract grid from rows
        return [list(row_cands[r][0]) for r in range(N)]

    choice = _choose_branch(row_cands, col_cands)
    if choice is None:
        return None
    kind, idx, _ = choice

    if kind == "row":
        # Try candidates in an order that tends to satisfy column constraints (already propagated)
        for cand in row_cands[idx]:
            new_row = [list(x) for x in row_cands]
            new_col = [list(x) for x in col_cands]
            new_row[idx] = [cand]
            sol = _search(new_row, new_col, N)
            if sol is not None:
                return sol
    else:
        for cand in col_cands[idx]:
            new_row = [list(x) for x in row_cands]
            new_col = [list(x) for x in col_cands]
            new_col[idx] = [cand]
            sol = _search(new_row, new_col, N)
            if sol is not None:
                return sol
    return None

def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    N = len(U)
    if not (len(D) == len(L) == len(R) == N):
        return "No Solution"

    # Candidate permutations for each row and column based on side clues only
    row_cands = []
    for r in range(N):
        row_cands.append(_all_candidates(N, L[r], R[r]))
        if not row_cands[-1]:
            return "No Solution"

    col_cands = []
    for c in range(N):
        col_cands.append(_all_candidates(N, U[c], D[c]))
        if not col_cands[-1]:
            return "No Solution"

    sol = _search(row_cands, col_cands, N)
    return sol if sol is not None else "No Solution"

