from itertools import permutations

# Skyscrapers solver with strong human-like constraint propagation:
# - Precompute all row/col permutations satisfying directional visibility clues.
# - Maintain domains (possible permutations) per row and per column.
# - Iteratively prune by arc-consistency (row<->col agreement), plus "forced cell" deductions.
# - If not solved, do MRV branching on the tightest row/col domain.

def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    N = len(U)
    if not (len(D) == len(L) == len(R) == N):
        return "No Solution"

    def vis_count(seq):
        m = 0
        c = 0
        for x in seq:
            if x > m:
                m = x
                c += 1
        return c

    def ok_with_clues(seq, left, right):
        if left and vis_count(seq) != left:
            return False
        if right and vis_count(seq[::-1]) != right:
            return False
        return True

    all_perms = list(permutations(range(1, N + 1)))

    # Candidate permutations for each row/col by their own side clues.
    row_cands = [None] * N
    col_cands = [None] * N

    for r in range(N):
        lc = L[r]
        rc = R[r]
        row_cands[r] = [p for p in all_perms if ok_with_clues(p, lc, rc)]
        if not row_cands[r]:
            return "No Solution"

    for c in range(N):
        uc = U[c]
        dc = D[c]
        col_cands[c] = [p for p in all_perms if ok_with_clues(p, uc, dc)]
        if not col_cands[c]:
            return "No Solution"

    # Helper: compute allowed values per cell from current domains.
    def compute_cell_allowed(row_domains, col_domains):
        # allowed[r][c] is a bitmask over values 1..N
        allowed = [[0] * N for _ in range(N)]
        row_masks = []
        col_masks = []

        # Precompute for speed: for each row r and position c, bitmask of values possible there.
        for r in range(N):
            masks = [0] * N
            for p in row_domains[r]:
                for c, v in enumerate(p):
                    masks[c] |= 1 << (v - 1)
            row_masks.append(masks)

        for c in range(N):
            masks = [0] * N
            for p in col_domains[c]:
                for r, v in enumerate(p):
                    masks[r] |= 1 << (v - 1)
            col_masks.append(masks)

        for r in range(N):
            for c in range(N):
                allowed[r][c] = row_masks[r][c] & col_masks[c][r]
                if allowed[r][c] == 0:
                    return None
        return allowed

    # Prune row/col domains by enforcing consistency at each cell.
    def prune_domains(row_domains, col_domains, allowed):
        changed = False

        # Prune rows
        for r in range(N):
            new_list = []
            for p in row_domains[r]:
                ok = True
                for c, v in enumerate(p):
                    if not (allowed[r][c] & (1 << (v - 1))):
                        ok = False
                        break
                if ok:
                    new_list.append(p)
            if len(new_list) != len(row_domains[r]):
                row_domains[r] = new_list
                changed = True
                if not new_list:
                    return None, None, None

        # Prune cols
        for c in range(N):
            new_list = []
            for p in col_domains[c]:
                ok = True
                for r, v in enumerate(p):
                    if not (allowed[r][c] & (1 << (v - 1))):
                        ok = False
                        break
                if ok:
                    new_list.append(p)
            if len(new_list) != len(col_domains[c]):
                col_domains[c] = new_list
                changed = True
                if not new_list:
                    return None, None, None

        if not changed:
            return row_domains, col_domains, allowed
        # Recompute allowed after pruning
        allowed2 = compute_cell_allowed(row_domains, col_domains)
        if allowed2 is None:
            return None, None, None
        return row_domains, col_domains, allowed2

    # More human-like deduction: if a cell's allowed bitmask is singleton, enforce it on row/col domains.
    def enforce_singletons(row_domains, col_domains, allowed):
        changed = False
        for r in range(N):
            for c in range(N):
                m = allowed[r][c]
                if m and (m & (m - 1)) == 0:
                    v = (m.bit_length())  # 1..N
                    # Filter row perms where position c is v
                    rd = row_domains[r]
                    if len(rd) > 1:
                        new_rd = [p for p in rd if p[c] == v]
                        if not new_rd:
                            return None, None, None
                        if len(new_rd) != len(rd):
                            row_domains[r] = new_rd
                            changed = True
                    # Filter col perms where position r is v
                    cd = col_domains[c]
                    if len(cd) > 1:
                        new_cd = [p for p in cd if p[r] == v]
                        if not new_cd:
                            return None, None, None
                        if len(new_cd) != len(cd):
                            col_domains[c] = new_cd
                            changed = True
        if not changed:
            return row_domains, col_domains, allowed
        allowed2 = compute_cell_allowed(row_domains, col_domains)
        if allowed2 is None:
            return None, None, None
        return row_domains, col_domains, allowed2

    # Full propagation loop: arc consistency + singleton enforcement until fixed point.
    def propagate(row_domains, col_domains):
        allowed = compute_cell_allowed(row_domains, col_domains)
        if allowed is None:
            return None, None, None
        while True:
            prev_sizes = (tuple(len(x) for x in row_domains), tuple(len(x) for x in col_domains))
            row_domains, col_domains, allowed = prune_domains(row_domains, col_domains, allowed)
            if row_domains is None:
                return None, None, None
            row_domains, col_domains, allowed = enforce_singletons(row_domains, col_domains, allowed)
            if row_domains is None:
                return None, None, None
            new_sizes = (tuple(len(x) for x in row_domains), tuple(len(x) for x in col_domains))
            if new_sizes == prev_sizes:
                return row_domains, col_domains, allowed

    def is_solved(row_domains, col_domains):
        return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

    def extract_grid(row_domains):
        return [list(row_domains[r][0]) for r in range(N)]

    # Choose a branching variable: smallest domain among rows/cols (MRV), but >1.
    def choose_mrv(row_domains, col_domains):
        best = None  # ('r', idx) or ('c', idx)
        best_len = 10**9
        for r, d in enumerate(row_domains):
            if 1 < len(d) < best_len:
                best_len = len(d)
                best = ('r', r)
        for c, d in enumerate(col_domains):
            if 1 < len(d) < best_len:
                best_len = len(d)
                best = ('c', c)
        return best

    # Order values (permutations) to try: heuristic by how restrictive it is for intersecting domains.
    def score_row_perm(p, col_domains, r):
        # lower score => try first (more compatible)
        s = 0
        for c, v in enumerate(p):
            # count how many column perms allow v at row r
            cnt = 0
            for q in col_domains[c]:
                if q[r] == v:
                    cnt += 1
            s += cnt
        return s

    def score_col_perm(p, row_domains, c):
        s = 0
        for r, v in enumerate(p):
            cnt = 0
            for q in row_domains[r]:
                if q[c] == v:
                    cnt += 1
            s += cnt
        return s

    def deep_copy_domains(domains):
        return [d[:] for d in domains]

    def dfs(row_domains, col_domains):
        row_domains, col_domains, allowed = propagate(row_domains, col_domains)
        if row_domains is None:
            return None
        if is_solved(row_domains, col_domains):
            # Consistency check: row assignments imply unique columns too, but domains already ensure it
            return extract_grid(row_domains)

        var = choose_mrv(row_domains, col_domains)
        if var is None:
            return None

        kind, idx = var
        if kind == 'r':
            perms = row_domains[idx]
            # Try most compatible first (higher sum of compat counts)
            perms_sorted = sorted(perms, key=lambda p: -score_row_perm(p, col_domains, idx))
            for p in perms_sorted:
                rd2 = deep_copy_domains(row_domains)
                cd2 = deep_copy_domains(col_domains)
                rd2[idx] = [p]
                res = dfs(rd2, cd2)
                if res is not None:
                    return res
        else:
            perms = col_domains[idx]
            perms_sorted = sorted(perms, key=lambda p: -score_col_perm(p, row_domains, idx))
            for p in perms_sorted:
                rd2 = deep_copy_domains(row_domains)
                cd2 = deep_copy_domains(col_domains)
                cd2[idx] = [p]
                res = dfs(rd2, cd2)
                if res is not None:
                    return res
        return None

    grid = dfs(row_cands, col_cands)
    return grid if grid is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [1, 5, 4, 3, 2, 2], 'D': [3, 1, 2, 3, 2, 4], 'L': [1, 3, 4, 2, 3, 2], 'R': [3, 1, 2, 3, 2, 4]}

from itertools import permutations

# Skyscrapers solver with aggressive human-like constraint propagation:
# - Precompute all row/col permutations matching side clues.
# - Maintain domains as sets of candidate permutations per row/col.
# - Propagate:
#   (1) Cell-wise intersection between row/col candidates
#   (2) Arc consistency between rows and columns via allowed value pairs per cell
#   (3) Hidden singles at cell level derived from candidate supports
# - Search only when propagation stalls; branch on most constrained row/col domain.

def _visible_count(seq):
    m = 0
    vis = 0
    for x in seq:
        if x > m:
            m = x
            vis += 1
    return vis

def _match_clues(seq, left, right):
    if left and _visible_count(seq) != left:
        return False
    if right and _visible_count(reversed(seq)) != right:
        return False
    return True

def _all_perms_n(n):
    return list(permutations(range(1, n + 1)))

def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    n = len(U)
    if not (len(D) == len(L) == len(R) == n):
        return "No Solution"

    allp = _all_perms_n(n)

    # Candidate permutations by row clues and by column clues
    row_cands = []
    for r in range(n):
        lc, rc = L[r], R[r]
        row_cands.append([p for p in allp if _match_clues(p, lc, rc)])

    col_cands = []
    for c in range(n):
        uc, dc = U[c], D[c]
        col_cands.append([p for p in allp if _match_clues(p, uc, dc)])

    # Quick fail
    if any(len(x) == 0 for x in row_cands) or any(len(x) == 0 for x in col_cands):
        return "No Solution"

    # Represent domains as lists and also as boolean masks for speed
    # We'll keep as lists of tuples; pruning rebuilds lists.
    rows = [list(c) for c in row_cands]
    cols = [list(c) for c in col_cands]

    # Cache: for a list of candidate perms, compute allowed values per position (bitmask)
    # Value v => bit (1<<(v-1))
    def allowed_masks(domain):
        masks = [0] * n
        for p in domain:
            for i, v in enumerate(p):
                masks[i] |= 1 << (v - 1)
        return masks

    def mask_to_values(m):
        # iterate 1..n where bit set
        while m:
            b = m & -m
            v = (b.bit_length())
            yield v
            m ^= b

    # Cell possible values (bitmask) maintained implicitly from row/col domains; computed on demand.
    def compute_cell_masks(rows_dom, cols_dom):
        row_masks = [allowed_masks(dom) for dom in rows_dom]
        col_masks = [allowed_masks(dom) for dom in cols_dom]
        cell = [[row_masks[r][c] & col_masks[c][r] for c in range(n)] for r in range(n)]
        return row_masks, col_masks, cell

    # Prune domain by requiring for each position i, value is in mask_i.
    def prune_domain_by_masks(domain, masks_pos):
        if not domain:
            return domain
        new_dom = [p for p in domain if all((masks_pos[i] >> (p[i] - 1)) & 1 for i in range(n))]
        return new_dom

    # Stronger pruning using cell masks: row perm must match each cell's mask; similarly for col perms.
    def prune_by_cell(rows_dom, cols_dom, cell_masks):
        changed = False
        for r in range(n):
            cm = cell_masks[r]
            new_dom = [p for p in rows_dom[r] if all((cm[c] >> (p[c] - 1)) & 1 for c in range(n))]
            if len(new_dom) != len(rows_dom[r]):
                rows_dom[r] = new_dom
                changed = True
                if not new_dom:
                    return False, changed
        for c in range(n):
            # cell_masks[r][c] -> for column c at row r, check position r in column perm
            new_dom = [p for p in cols_dom[c] if all((cell_masks[r][c] >> (p[r] - 1)) & 1 for r in range(n))]
            if len(new_dom) != len(cols_dom[c]):
                cols_dom[c] = new_dom
                changed = True
                if not new_dom:
                    return False, changed
        return True, changed

    # Arc consistency between row r and col c via allowed pair support at (r,c)
    # For each cell, remove row candidates whose value at c has no supporting col candidate at r, and vice versa.
    def arc_consistency(rows_dom, cols_dom):
        changed_any = False
        # Precompute support sets for each (r,c) based on current domains:
        # For each column c, possible values at row r: bitmask
        col_pos_masks = [allowed_masks(cols_dom[c]) for c in range(n)]  # index by c -> pos r
        row_pos_masks = [allowed_masks(rows_dom[r]) for r in range(n)]  # index by r -> pos c

        # Iterate cells; prune with fast bit tests
        for r in range(n):
            for c in range(n):
                # Values that can appear at cell from each side
                m_rc_from_row = row_pos_masks[r][c]
                m_rc_from_col = col_pos_masks[c][r]
                m = m_rc_from_row & m_rc_from_col
                if m == 0:
                    return False, changed_any

                # Prune rows[r]: value at c must be in m
                domr = rows_dom[r]
                if domr:
                    new_domr = [p for p in domr if ((m >> (p[c] - 1)) & 1)]
                    if len(new_domr) != len(domr):
                        rows_dom[r] = new_domr
                        changed_any = True
                        if not new_domr:
                            return False, changed_any

                # Prune cols[c]: value at r must be in m
                domc = cols_dom[c]
                if domc:
                    new_domc = [p for p in domc if ((m >> (p[r] - 1)) & 1)]
                    if len(new_domc) != len(domc):
                        cols_dom[c] = new_domc
                        changed_any = True
                        if not new_domc:
                            return False, changed_any
        return True, changed_any

    # Hidden singles: if at cell (r,c) only one value possible, enforce it by pruning.
    def enforce_singletons(rows_dom, cols_dom):
        row_masks, col_masks, cell = compute_cell_masks(rows_dom, cols_dom)
        changed = False
        for r in range(n):
            for c in range(n):
                m = cell[r][c]
                if m == 0:
                    return False, changed
                if m & (m - 1) == 0:
                    # singleton value
                    v = m.bit_length()
                    # prune row r to those with v at c
                    domr = rows_dom[r]
                    new_domr = [p for p in domr if p[c] == v]
                    if len(new_domr) != len(domr):
                        rows_dom[r] = new_domr
                        changed = True
                        if not new_domr:
                            return False, changed
                    # prune col c to those with v at r
                    domc = cols_dom[c]
                    new_domc = [p for p in domc if p[r] == v]
                    if len(new_domc) != len(domc):
                        cols_dom[c] = new_domc
                        changed = True
                        if not new_domc:
                            return False, changed
        return True, changed

    def propagate(rows_dom, cols_dom):
        # Fixed-point propagation loop
        while True:
            ok, ch1 = arc_consistency(rows_dom, cols_dom)
            if not ok:
                return False
            row_masks, col_masks, cell = compute_cell_masks(rows_dom, cols_dom)
            ok, ch2 = prune_by_cell(rows_dom, cols_dom, cell)
            if not ok:
                return False
            ok, ch3 = enforce_singletons(rows_dom, cols_dom)
            if not ok:
                return False
            if not (ch1 or ch2 or ch3):
                return True

    def is_solved(rows_dom, cols_dom):
        return all(len(d) == 1 for d in rows_dom) and all(len(d) == 1 for d in cols_dom)

    def extract_grid(rows_dom):
        return [list(rows_dom[r][0]) for r in range(n)]

    # Choose variable (row or col) with smallest domain > 1
    def select_branch(rows_dom, cols_dom):
        best = ("row", -1, 10**9)
        for r, d in enumerate(rows_dom):
            if 1 < len(d) < best[2]:
                best = ("row", r, len(d))
        for c, d in enumerate(cols_dom):
            if 1 < len(d) < best[2]:
                best = ("col", c, len(d))
        return best[0], best[1]

    def dfs(rows_dom, cols_dom):
        ok = propagate(rows_dom, cols_dom)
        if not ok:
            return None
        if is_solved(rows_dom, cols_dom):
            # Ensure consistency between unique rows and cols (should hold after propagation)
            return extract_grid(rows_dom)

        kind, idx = select_branch(rows_dom, cols_dom)
        if idx < 0:
            return None

        # Value ordering: try candidates that are most compatible with opposite domains (heuristic)
        if kind == "row":
            # Score by sum of supports in columns for each position
            col_pos_masks = [allowed_masks(cols_dom[c])[idx] for c in range(n)]  # at row idx in each column
            scored = []
            for p in rows_dom[idx]:
                score = 0
                for c in range(n):
                    score += 1 if ((col_pos_masks[c] >> (p[c] - 1)) & 1) else 0
                scored.append((score, p))
            scored.sort(reverse=True)
            candidates = [p for _, p in scored]
            for p in candidates:
                new_rows = [list(d) for d in rows_dom]
                new_cols = [list(d) for d in cols_dom]
                new_rows[idx] = [p]
                res = dfs(new_rows, new_cols)
                if res is not None:
                    return res
        else:
            row_pos_masks = [allowed_masks(rows_dom[r])[idx] for r in range(n)]  # at col idx in each row
            scored = []
            for p in cols_dom[idx]:
                score = 0
                for r in range(n):
                    score += 1 if ((row_pos_masks[r] >> (p[r] - 1)) & 1) else 0
                scored.append((score, p))
            scored.sort(reverse=True)
            candidates = [p for _, p in scored]
            for p in candidates:
                new_rows = [list(d) for d in rows_dom]
                new_cols = [list(d) for d in cols_dom]
                new_cols[idx] = [p]
                res = dfs(new_rows, new_cols)
                if res is not None:
                    return res

        return None

    result = dfs(rows, cols)
    return result if result is not None else "No Solution"


