    print(solve(OBSERVATION))

OBSERVATION = {'U': [2, 1, 2, 2], 'D': [3, 4, 1, 2], 'L': [2, 1, 2, 2], 'R': [3, 4, 1, 2]}

from itertools import permutations

# Skyscrapers solver with strong human-like constraint propagation:
# - Precompute all row/col permutations consistent with edge visibility clues.
# - Maintain candidate sets for each row and column (like pencil marks).
# - Repeatedly propagate:
#   * Intersect cell domains from row/col candidates
#   * Filter row candidates by column cell domains (and vice versa)
#   * Hidden singles / forced placements by position-frequency
# - Use MRV branching on the most constrained row/col candidate set, not on cells.
# This avoids naive brute-force over N^(N^2) and typically solves instantly for N<=7.

def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    N = len(U)
    if not (len(D) == len(L) == len(R) == N):
        return "No Solution"

    all_perms = list(permutations(range(1, N + 1)))

    def visible_count(seq):
        m = 0
        c = 0
        for x in seq:
            if x > m:
                m = x
                c += 1
        return c

    # Cache visibility for speed
    vis_fwd = {}
    vis_rev = {}
    for p in all_perms:
        vis_fwd[p] = visible_count(p)
        vis_rev[p] = visible_count(p[::-1])

    def clue_ok(clue, count):
        return clue == 0 or clue == count

    row_cands = []
    for r in range(N):
        lc = L[r]
        rc = R[r]
        c = [p for p in all_perms if clue_ok(lc, vis_fwd[p]) and clue_ok(rc, vis_rev[p])]
        if not c:
            return "No Solution"
        row_cands.append(c)

    col_cands = []
    for c in range(N):
        uc = U[c]
        dc = D[c]
        col = [p for p in all_perms if clue_ok(uc, vis_fwd[p]) and clue_ok(dc, vis_rev[p])]
        if not col:
            return "No Solution"
        col_cands.append(col)

    # Domains per cell represented as bitmasks over 1..N
    full_mask = (1 << N) - 1
    def val_to_bit(v): return 1 << (v - 1)

    def mask_from_vals(vals):
        m = 0
        for v in vals:
            m |= val_to_bit(v)
        return m

    def iter_bits(mask):
        # yields values 1..N
        while mask:
            lsb = mask & -mask
            idx = (lsb.bit_length() - 1)
            yield idx + 1
            mask ^= lsb

    def compute_cell_masks(row_cands_local, col_cands_local):
        # Union across candidates for each position
        row_pos_masks = [[0]*N for _ in range(N)]
        col_pos_masks = [[0]*N for _ in range(N)]
        for r in range(N):
            # union per position
            pm = [0]*N
            for p in row_cands_local[r]:
                for j, v in enumerate(p):
                    pm[j] |= val_to_bit(v)
            row_pos_masks[r] = pm
        for c in range(N):
            pm = [0]*N
            for p in col_cands_local[c]:
                for i, v in enumerate(p):
                    pm[i] |= val_to_bit(v)
            col_pos_masks[c] = pm

        cell_masks = [[0]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                cell_masks[r][c] = row_pos_masks[r][c] & col_pos_masks[c][r]
        return cell_masks

    def filter_candidates_by_cell_masks(row_cands_local, col_cands_local, cell_masks):
        changed = False

        # Filter row candidates: each cell must be compatible with cell_mask and column uniqueness is already in perm
        for r in range(N):
            before = len(row_cands_local[r])
            if before > 1:
                allowed_masks = cell_masks[r]
                row_cands_local[r] = [
                    p for p in row_cands_local[r]
                    if all((allowed_masks[c] & val_to_bit(p[c])) for c in range(N))
                ]
                if not row_cands_local[r]:
                    return None, None, True  # contradiction
                if len(row_cands_local[r]) != before:
                    changed = True

        # Filter column candidates similarly
        for c in range(N):
            before = len(col_cands_local[c])
            if before > 1:
                allowed_masks = [cell_masks[r][c] for r in range(N)]
                col_cands_local[c] = [
                    p for p in col_cands_local[c]
                    if all((allowed_masks[r] & val_to_bit(p[r])) for r in range(N))
                ]
                if not col_cands_local[c]:
                    return None, None, True
                if len(col_cands_local[c]) != before:
                    changed = True

        return row_cands_local, col_cands_local, changed

    def enforce_hidden_singles(row_cands_local, col_cands_local, cell_masks):
        # If in a row, a value can appear only in one position across candidates, restrict that position.
        changed = False

        # Cell masks will be refined in-place by forcing bits
        # Row-wise hidden singles
        for r in range(N):
            # frequency per value across positions considering candidates
            pos_freq = [0]*N  # for value v, bitmask of positions it can be in
            for p in row_cands_local[r]:
                for c, v in enumerate(p):
                    pos_freq[v-1] |= (1 << c)
            for v_idx, positions_mask in enumerate(pos_freq):
                if positions_mask and (positions_mask & (positions_mask - 1)) == 0:
                    c = positions_mask.bit_length() - 1
                    bit = 1 << v_idx
                    if cell_masks[r][c] & bit and cell_masks[r][c] != bit:
                        cell_masks[r][c] = bit
                        changed = True

        # Column-wise hidden singles
        for c in range(N):
            pos_freq = [0]*N  # bitmask of rows
            for p in col_cands_local[c]:
                for r, v in enumerate(p):
                    pos_freq[v-1] |= (1 << r)
            for v_idx, rows_mask in enumerate(pos_freq):
                if rows_mask and (rows_mask & (rows_mask - 1)) == 0:
                    r = rows_mask.bit_length() - 1
                    bit = 1 << v_idx
                    if cell_masks[r][c] & bit and cell_masks[r][c] != bit:
                        cell_masks[r][c] = bit
                        changed = True

        return changed

    def propagate(row_cands_local, col_cands_local):
        # Iterative fixpoint propagation
        while True:
            cell_masks = compute_cell_masks(row_cands_local, col_cands_local)

            # Immediate contradiction: any cell mask becomes 0
            for r in range(N):
                for c in range(N):
                    if cell_masks[r][c] == 0:
                        return None

            # Hidden singles can tighten cell masks, then refilter candidates
            hs_changed = enforce_hidden_singles(row_cands_local, col_cands_local, cell_masks)

            row_cands_local, col_cands_local, filtered_changed = filter_candidates_by_cell_masks(
                row_cands_local, col_cands_local, cell_masks
            )
            if row_cands_local is None:
                return None

            if not (hs_changed or filtered_changed):
                return (row_cands_local, col_cands_local)

    def is_solved(row_cands_local, col_cands_local):
        return all(len(x) == 1 for x in row_cands_local) and all(len(x) == 1 for x in col_cands_local)

    def build_grid_from_rows(row_cands_local):
        return [list(row_cands_local[r][0]) for r in range(N)]

    # Additional consistency check: row and column singletons must agree
    def singleton_agree(row_cands_local, col_cands_local):
        for r in range(N):
            if len(row_cands_local[r]) == 1:
                rowp = row_cands_local[r][0]
                for c in range(N):
                    if len(col_cands_local[c]) == 1:
                        colp = col_cands_local[c][0]
                        if rowp[c] != colp[r]:
                            return False
        return True

    def choose_branch_var(row_cands_local, col_cands_local):
        # Choose smallest candidate list > 1 among rows and cols (MRV)
        best = None
        best_is_row = True
        best_idx = -1
        best_len = 10**9
        for r in range(N):
            l = len(row_cands_local[r])
            if 1 < l < best_len:
                best_len = l
                best = row_cands_local[r]
                best_is_row = True
                best_idx = r
        for c in range(N):
            l = len(col_cands_local[c])
            if 1 < l < best_len:
                best_len = l
                best = col_cands_local[c]
                best_is_row = False
                best_idx = c
        return best_is_row, best_idx

    def dfs(row_cands_local, col_cands_local):
        propagated = propagate([list(x) for x in row_cands_local], [list(x) for x in col_cands_local])
        if propagated is None:
            return None
        row_cands_p, col_cands_p = propagated
        if not singleton_agree(row_cands_p, col_cands_p):
            return None
        if is_solved(row_cands_p, col_cands_p):
            return build_grid_from_rows(row_cands_p)

        is_row, idx = choose_branch_var(row_cands_p, col_cands_p)
        if idx < 0:
            return None

        # Value ordering heuristic: try candidates that best match the other dimension masks first
        cell_masks = compute_cell_masks(row_cands_p, col_cands_p)
        if is_row:
            candidates = row_cands_p[idx]
            # score by compatibility sum with column masks
            scored = []
            for p in candidates:
                score = 0
                for c in range(N):
                    score += 1 if (cell_masks[idx][c] & val_to_bit(p[c])) else 0
                scored.append((score, p))
            scored.sort(reverse=True)
            for _, p in scored:
                row2 = [list(x) for x in row_cands_p]
                col2 = [list(x) for x in col_cands_p]
                row2[idx] = [p]
                res = dfs(row2, col2)
                if res is not None:
                    return res
        else:
            candidates = col_cands_p[idx]
            scored = []
            for p in candidates:
                score = 0
                for r in range(N):
                    score += 1 if (cell_masks[r][idx] & val_to_bit(p[r])) else 0
                scored.append((score, p))
            scored.sort(reverse=True)
            for _, p in scored:
                row2 = [list(x) for x in row_cands_p]
                col2 = [list(x) for x in col_cands_p]
                col2[idx] = [p]
                res = dfs(row2, col2)
                if res is not None:
                    return res

        return None

    solution = dfs(row_cands, col_cands)
    return solution if solution is not None else "No Solution"


