OBSERVATION = {'data': [[1, 5, 3, 4, 1], [5, 3, 5, 3, 1], [3, 5, 4, 1, 5], [5, 1, 2, 3, 4], [2, 1, 1, 1, 3]]}

from collections import deque, defaultdict

# Solver for Hitori-like puzzle:
# - Shade some cells black such that:
#   1) In each row/col, each number appears at most once among white cells.
#   2) Black cells cannot touch orthogonally.
#   3) All white cells form one orthogonally connected component.

W, B = 0, 1  # internal states: white-forced, black-forced; unknown is -1


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if n == 0 or any(len(r) != n for r in grid):
        return "No Solution"

    # Precompute row/col groups by value (cells that share same number in same row/col)
    row_groups = [[[] for _ in range(n)] for _ in range(n)]  # unused placeholder for shape
    # We'll store: row_map[r][val] -> list of cols ; col_map[c][val] -> list of rows
    row_map = [defaultdict(list) for _ in range(n)]
    col_map = [defaultdict(list) for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            row_map[r][v].append(c)
            col_map[c][v].append(r)

    # Store only duplicates groups (size>=2) for fast constraint handling
    row_dups = [[] for _ in range(n)]  # list of (val, cols)
    col_dups = [[] for _ in range(n)]  # list of (val, rows)
    for r in range(n):
        for v, cols in row_map[r].items():
            if len(cols) >= 2:
                row_dups[r].append((v, tuple(cols)))
    for c in range(n):
        for v, rows in col_map[c].items():
            if len(rows) >= 2:
                col_dups[c].append((v, tuple(rows)))

    # Neighbors
    nbrs = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            idx = r * n + c
            if r > 0:
                nbrs[idx].append((r - 1) * n + c)
            if r + 1 < n:
                nbrs[idx].append((r + 1) * n + c)
            if c > 0:
                nbrs[idx].append(r * n + (c - 1))
            if c + 1 < n:
                nbrs[idx].append(r * n + (c + 1))

    def idx_of(r, c):
        return r * n + c

    def rc_of(idx):
        return divmod(idx, n)

    # Connectivity lower-bound pruning for whites:
    # - Black cells are removed. Whites must be one component.
    # - Unknown cells are treated as potentially white for pruning, but forced whites must be connectable.
    def connectivity_ok(state):
        # state: list length n*n with -1 unknown, 0 forced white, 1 forced black
        # Find any cell that is not forced black (potentially white). If none, invalid.
        start = -1
        for i, s in enumerate(state):
            if s != B:
                start = i
                break
        if start < 0:
            return False

        # BFS over cells not forced black
        dq = deque([start])
        seen = bytearray(n * n)
        seen[start] = 1
        while dq:
            u = dq.popleft()
            for v in nbrs[u]:
                if not seen[v] and state[v] != B:
                    seen[v] = 1
                    dq.append(v)

        # All forced-white cells must be in same reachable area
        for i, s in enumerate(state):
            if s == W and not seen[i]:
                return False

        # Additionally, if there are multiple "islands" of potentially-white cells, we can still connect
        # only if unknowns can serve as bridges. Our BFS already used all non-black, so islands would mean separated by black only.
        # That's impossible to fix later (black is immutable), so if any non-black is unseen -> disconnected and invalid.
        # However, some currently-black might be flipped? No, black-forced is final, but unknown may become black later (not white).
        # So connectivity can only worsen; thus require all non-black to be connected now.
        for i, s in enumerate(state):
            if s != B and not seen[i]:
                return False

        return True

    # Constraint propagation using a queue of newly assigned cells.
    # Returns (ok, new_state, changed_cells_list_for_undo) where changes are recorded to undo.
    def propagate(state, initial_queue):
        q = deque(initial_queue)
        changes = []

        def assign(cell, val):
            # val in {W,B}
            cur = state[cell]
            if cur == val:
                return True
            if cur != -1 and cur != val:
                return False
            state[cell] = val
            changes.append(cell)
            q.append(cell)
            return True

        # Helper: enforce non-adjacent blacks around a black cell
        def enforce_black_adjacency(cell):
            for nb in nbrs[cell]:
                if not assign(nb, W):
                    return False
            return True

        # Helper: enforce duplicates constraints for row/col groups
        # For each row/col and value group of size k:
        #   - cannot have >1 whites in group
        #   - cannot have all blacks
        #   - if already 1 white => others must be black
        #   - if k-1 blacks => remaining must be white
        def enforce_group(cells):
            whites = 0
            blacks = 0
            unk = []
            for cell in cells:
                s = state[cell]
                if s == W:
                    whites += 1
                elif s == B:
                    blacks += 1
                else:
                    unk.append(cell)
            if whites >= 2:
                return False
            if blacks == len(cells):
                return False
            if whites == 1:
                for u in unk:
                    if not assign(u, B):
                        return False
            elif blacks == len(cells) - 1:
                if len(unk) != 1:
                    return False
                if not assign(unk[0], W):
                    return False
            return True

        # Helper: pattern "sandwich" in row/col: a x a with one cell between must force middle white
        # because at least one of the equal a's must be black, but if middle were black it might isolate/adjacency?
        # In standard Hitori, "a b a" implies b must be white, because if b were black then both a's must be white (cannot both be black adjacent? not necessarily),
        # actually the correct reasoning: if b is black, then a's cannot be black (adjacent to b), so they would be white, creating duplicate a's in row/col.
        def enforce_sandwich():
            # This is a global scan but cheap for n<=~20; still do incremental by scanning affected lines when a cell assigned.
            # We'll implement incremental by just scanning full lines for simplicity; still efficient on typical sizes.
            for r in range(n):
                for c in range(n - 2):
                    if grid[r][c] == grid[r][c + 2]:
                        mid = idx_of(r, c + 1)
                        # if mid is black -> ends must be white, contradiction with duplicates => mid cannot be black => white
                        if state[mid] == B:
                            return False
                        if state[mid] == -1:
                            if not assign(mid, W):
                                return False
            for c in range(n):
                for r in range(n - 2):
                    if grid[r][c] == grid[r + 2][c]:
                        mid = idx_of(r + 1, c)
                        if state[mid] == B:
                            return False
                        if state[mid] == -1:
                            if not assign(mid, W):
                                return False
            return True

        # A slightly stronger local rule:
        # If a cell is forced black, its row/col duplicates companions (same number in same row/col) are more likely forced white?
        # Not necessarily. We'll keep core group constraints.

        # Initial pass: enforce groups and sandwich once to kickstart
        for r in range(n):
            for _, cols in row_dups[r]:
                if not enforce_group([idx_of(r, cc) for cc in cols]):
                    return False, changes
        for c in range(n):
            for _, rows in col_dups[c]:
                if not enforce_group([idx_of(rr, c) for rr in rows]):
                    return False, changes
        if not enforce_sandwich():
            return False, changes

        # Process queue for incremental constraints
        while q:
            cell = q.popleft()
            s = state[cell]
            r, c = rc_of(cell)

            if s == B:
                if not enforce_black_adjacency(cell):
                    return False, changes

            # Re-enforce duplicate groups only for affected row/col value
            v = grid[r][c]
            cols = row_map[r].get(v)
            if cols and len(cols) >= 2:
                if not enforce_group([idx_of(r, cc) for cc in cols]):
                    return False, changes
            rows = col_map[c].get(v)
            if rows and len(rows) >= 2:
                if not enforce_group([idx_of(rr, c) for rr in rows]):
                    return False, changes

            # Also adjacency rule can imply something if a cell is white? Not directly.

            # Optional: local sandwich around (r,c)
            # Check row windows involving c
            if c >= 2 and grid[r][c] == grid[r][c - 2]:
                mid = idx_of(r, c - 1)
                if state[mid] == B:
                    return False, changes
                if state[mid] == -1:
                    if not assign(mid, W):
                        return False, changes
            if c + 2 < n and grid[r][c] == grid[r][c + 2]:
                mid = idx_of(r, c + 1)
                if state[mid] == B:
                    return False, changes
                if state[mid] == -1:
                    if not assign(mid, W):
                        return False, changes

            # Check col windows involving r
            if r >= 2 and grid[r][c] == grid[r - 2][c]:
                mid = idx_of(r - 1, c)
                if state[mid] == B:
                    return False, changes
                if state[mid] == -1:
                    if not assign(mid, W):
                        return False, changes
            if r + 2 < n and grid[r][c] == grid[r + 2][c]:
                mid = idx_of(r + 1, c)
                if state[mid] == B:
                    return False, changes
                if state[mid] == -1:
                    if not assign(mid, W):
                        return False, changes

        # Connectivity pruning (monotone)
        if not connectivity_ok(state):
            return False, changes

        return True, changes

    def undo(state, changes):
        for cell in reversed(changes):
            state[cell] = -1

    # Heuristic choice: pick an unknown cell involved in most duplicate constraints and tightest situation
    dup_degree = [0] * (n * n)
    for r in range(n):
        for _, cols in row_dups[r]:
            for c in cols:
                dup_degree[idx_of(r, c)] += 1
    for c in range(n):
        for _, rows in col_dups[c]:
            for r in rows:
                dup_degree[idx_of(r, c)] += 1

    def select_cell(state):
        best = -1
        best_score = -1
        for i, s in enumerate(state):
            if s == -1:
                r, c = rc_of(i)
                v = grid[r][c]
                # Count undecided in its row/col duplicate groups of same value
                sc = dup_degree[i] * 10
                cols = row_map[r][v]
                if len(cols) >= 2:
                    unk = 0
                    whites = 0
                    for cc in cols:
                        t = state[idx_of(r, cc)]
                        if t == -1:
                            unk += 1
                        elif t == W:
                            whites += 1
                    sc += (5 - unk) + whites * 4
                rows = col_map[c][v]
                if len(rows) >= 2:
                    unk = 0
                    whites = 0
                    for rr in rows:
                        t = state[idx_of(rr, c)]
                        if t == -1:
                            unk += 1
                        elif t == W:
                            whites += 1
                    sc += (5 - unk) + whites * 4
                # Prefer cells adjacent to blacks (often forced white) or creating adjacency constraints
                adj_black = sum(1 for nb in nbrs[i] if state[nb] == B)
                sc += adj_black * 3
                if sc > best_score:
                    best_score = sc
                    best = i
        return best

    # Branch ordering: try black first if it helps resolve duplicates, otherwise white first.
    def branch_values(cell, state):
        r, c = rc_of(cell)
        v = grid[r][c]
        # If cell is in a duplicate group, making it black often helps remove duplicates; but black has adjacency cost.
        in_dup = (len(row_map[r][v]) >= 2) or (len(col_map[c][v]) >= 2)
        adj_unk = sum(1 for nb in nbrs[cell] if state[nb] == -1)
        # If many unknown neighbors, black causes many forced whites -> strong propagation.
        if in_dup and adj_unk >= 2:
            return (B, W)
        if in_dup:
            return (B, W)
        return (W, B)

    # DFS with heavy propagation (not naive brute force: every node enforces constraints + connectivity)
    def dfs(state):
        cell = select_cell(state)
        if cell == -1:
            # All decided; final connectivity already checked; ensure duplicates satisfied (should be).
            return True

        for val in branch_values(cell, state):
            changes = []
            # Assign and propagate
            state[cell] = val
            changes.append(cell)
            ok, more = propagate(state, [cell])
            changes.extend(more)
            if ok:
                if dfs(state):
                    return True
            undo(state, changes)
        return False

    state = [-1] * (n * n)

    # Initial propagation with no assignments still useful (sandwich & group constraints like "all but one black" won't fire yet).
    ok, changes = propagate(state, [])
    if not ok:
        return "No Solution"
    # no need to undo initial changes; keep them
    if not dfs(state):
        return "No Solution"

    # Build output mask with 'B' and None
    out = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if state[idx_of(r, c)] == B:
                out[r][c] = 'B'
    return str(out)


