from collections import deque

def solve(observation):
    data = observation["data"]
    N = len(data)
    horiz_raw = observation.get("horizontal", {})
    vert_raw = observation.get("vertical", {})

    # Parse inequalities into adjacency constraints between two cells:
    # each constraint is (a, b, rel) meaning value(a) < value(b) if rel=='<'
    constraints = []

    # Horizontal: key "(r, c+0.5)" between (r,c) and (r,c+1)
    for k, sym in horiz_raw.items():
        if sym not in ("<", ">"):
            continue
        try:
            ks = k.strip()
            if ks[0] == "(" and ks[-1] == ")":
                ks = ks[1:-1]
            r_s, c_s = [x.strip() for x in ks.split(",")]
            r = float(r_s); c = float(c_s)
        except Exception:
            continue
        rr = int(round(r))
        cc05 = c
        # cc05 should be col+0.5
        col = int(round(cc05 - 0.5))
        if 0 <= rr < N and 0 <= col < N - 1:
            a = (rr, col)
            b = (rr, col + 1)
            if sym == "<":
                constraints.append((a, b, "<"))
            else:
                constraints.append((a, b, "<"))  # invert
                constraints[-1] = (b, a, "<")

    # Vertical: key "(r+0.5, c)" between (r,c) and (r+1,c) with '^' meaning top < bottom? or top > bottom?
    # We'll adopt: '^' means top < bottom (arrow up indicates upper smaller), 'v' means top > bottom.
    # This matches typical futoshiki: symbol points to smaller; however puzzles vary. We'll implement both
    # by detecting contradictions during solve and, if needed, try flipped interpretation once.
    def build_vertical(interp_flip=False):
        cons = []
        for k, sym in vert_raw.items():
            if sym not in ("^", "v"):
                continue
            try:
                ks = k.strip()
                if ks[0] == "(" and ks[-1] == ")":
                    ks = ks[1:-1]
                r_s, c_s = [x.strip() for x in ks.split(",")]
                r = float(r_s); c = float(c_s)
            except Exception:
                continue
            row = int(round(r - 0.5))
            col = int(round(c))
            if 0 <= row < N - 1 and 0 <= col < N:
                top = (row, col)
                bot = (row + 1, col)
                s = sym
                if interp_flip:
                    s = "^" if sym == "v" else "v"
                if s == "^":
                    cons.append((top, bot, "<"))  # top < bottom
                else:
                    cons.append((bot, top, "<"))  # bottom < top (i.e., top > bottom)
        return cons

    # Domain representation: bitmask of possible values 1..N => bit i means value i+1
    ALL = (1 << N) - 1
    dom = [[ALL for _ in range(N)] for __ in range(N)]

    # Apply givens
