    # Precompute row/col peer lists
    row_cells = [[(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[(r, c) for r in range(N)] for c in range(N)]

    # Constraints adjacency for propagation
    def make_adj(cons):
        adj = {}
        for a, b, rel in cons:
            adj.setdefault(a, []).append((a, b, rel))
            adj.setdefault(b, []).append((a, b, rel))
        return adj

    def bit_count(x):
        return x.bit_count()

    def lowest_bit_index(x):
        return (x & -x).bit_length() - 1

    def iter_bits(x):
        while x:
            lb = x & -x
            i = lb.bit_length() - 1
            yield i
            x ^= lb

    def min_val(mask):
        return lowest_bit_index(mask) + 1

    def max_val(mask):
        return (mask.bit_length() - 1) + 1

    def enforce_ineq(a, b, domA, domB):
        # enforce value(a) < value(b)
        # Remove from A values that are >= max(B) possible? More precisely:
        # A must be <= maxB-1; B must be >= minA+1.
        if domA == 0 or domB == 0:
            return 0, 0, True
        minA = min_val(domA)
        maxA = max_val(domA)
        minB = min_val(domB)
        maxB = max_val(domB)

        changed = False

        # Prune A: values >= maxB are impossible
        if maxB <= 1:
            # then A < B impossible because B can't be >=2
            return 0, 0, True
        # mask of values 1..(maxB-1)
        allowedA = (1 << (maxB - 1)) - 1
        newA = domA & allowedA
        if newA != domA:
            domA = newA
            changed = True

        if domA == 0:
            return domA, domB, True

        # Recompute minA after prune
        minA = min_val(domA)
        # Prune B: values <= minA are impossible
        if minA >= N:
            return 0, 0, True
        allowedB = ALL & ~((1 << minA) - 1)
        newB = domB & allowedB
        if newB != domB:
            domB = newB
            changed = True

        if domB == 0:
            return domA, domB, True

        # Stronger bound pruning using min/max only; arc-consistency via bounds is sufficient for futoshiki.
        return domA, domB, False if changed else None  # None means no change

    def propagate(cons):
        # Human-like techniques:
        # 1) Basic elimination from row/col singles
        # 2) Hidden singles in rows/cols
        # 3) Inequality bound propagation (repeated to fixpoint)
        # 4) Pair/triple naked subsets in rows/cols (small k up to 3) to reduce search
        adj = make_adj(cons)

        q = deque()
        inq = set()

        def push_cell(r, c):
            key = (r, c)
            if key not in inq:
                inq.add(key)
                q.append(key)

        # Initialize all cells
        for r in range(N):
            for c in range(N):
                push_cell(r, c)

        def apply_rowcol_singles(r, c):
            # If cell is singleton, remove from peers in row/col
            m = dom[r][c]
            if bit_count(m) != 1:
                return False, False
            vbit = m
            changed_any = False
            # row
            for cc in range(N):
                if cc == c:
                    continue
                old = dom[r][cc]
                if old & vbit:
                    new = old & ~vbit
                    if new == 0:
                        return False, True
                    dom[r][cc] = new
                    changed_any = True
                    push_cell(r, cc)
            # col
            for rr in range(N):
                if rr == r:
                    continue
                old = dom[rr][c]
                if old & vbit:
                    new = old & ~vbit
                    if new == 0:
                        return False, True
                    dom[rr][c] = new
                    changed_any = True
                    push_cell(rr, c)
            return changed_any, False

        def hidden_singles_unit(cells):
            # For each value, if it appears in only one cell domain, assign it.
            loc = [-1] * (N + 1)
            count = [0] * (N + 1)
            for idx, (r, c) in enumerate(cells):
                m = dom[r][c]
                for i in iter_bits(m):
                    v = i + 1
                    count[v] += 1
                    loc[v] = idx
            changed_any = False
            for v in range(1, N + 1):
                if count[v] == 1:
                    r, c = cells[loc[v]]
                    mb = 1 << (v - 1)
                    if dom[r][c] != mb:
                        dom[r][c] = mb
                        push_cell(r, c)
                        changed_any = True
            return changed_any

        def naked_subsets_unit(cells, kmax=3):
            # Consider masks with small size; if same mask appears in exactly size(mask) cells => eliminate from others.
            buckets = {}
            for (r, c) in cells:
                m = dom[r][c]
                bc = bit_count(m)
                if 2 <= bc <= kmax:
                    buckets.setdefault(m, []).append((r, c))
            changed_any = False
            for m, places in buckets.items():
                sz = bit_count(m)
                if len(places) == sz and sz >= 2:
                    for (r, c) in cells:
                        if (r, c) in places:
                            continue
                        old = dom[r][c]
                        if old & m:
                            new = old & ~m
                            if new == 0:
                                return False, True
                            dom[r][c] = new
                            push_cell(r, c)
                            changed_any = True
            return changed_any, False

        def inequality_propagate(cell):
            r, c = cell
            if (r, c) not in adj:
                return False, False
            changed_any = False
            for a, b, rel in adj[(r, c)]:
                if rel != "<":
                    continue
                ar, ac = a
                br, bc = b
                dA, dB = dom[ar][ac], dom[br][bc]
                newA, newB, flag = enforce_ineq(a, b, dA, dB)
