                if newA != dA:
                    dom[ar][ac] = newA
                    push_cell(ar, ac)
                    changed_any = True
                if newB != dB:
                    dom[br][bc] = newB
                    push_cell(br, bc)
                    changed_any = True
            return changed_any, False

        # Main fixpoint loop
        while q:
            r, c = q.popleft()
            inq.discard((r, c))

            if dom[r][c] == 0:
                return False

            # 1) If singleton, eliminate from peers
            _, bad = apply_rowcol_singles(r, c)
            if bad:
                return False

            # 2) Inequality bounds
            _, bad = inequality_propagate((r, c))
            if bad:
                return False

            # 3) Periodically attempt unit-wide deductions for affected row/col (human scan)
            # Trigger when cell updated (we are here because it was pushed)
            if hidden_singles_unit(row_cells[r]):
                # newly assigned cells already queued
                pass
            if hidden_singles_unit(col_cells[c]):
                pass

            ok, bad = naked_subsets_unit(row_cells[r])
            if bad:
                return False
            ok, bad = naked_subsets_unit(col_cells[c])
            if bad:
                return False

        # final sanity: each unit must still be feasible
        for r in range(N):
            # quick check: union of domains must include all values, and no duplicates forced conflict
            forced = 0
            for c in range(N):
                m = dom[r][c]
                if bit_count(m) == 1:
                    if forced & m:
                        return False
                    forced |= m
            # same for columns
        for c in range(N):
            forced = 0
            for r in range(N):
                m = dom[r][c]
                if bit_count(m) == 1:
                    if forced & m:
                        return False
                    forced |= m
        return True

    def is_solved():
        for r in range(N):
            for c in range(N):
                if bit_count(dom[r][c]) != 1:
                    return False
        return True

    def select_cell():
        # MRV with tie-break on degree (inequality edges + peers)
        best = None
        best_key = (10**9, -1)
        # degree precompute lightly
        for r in range(N):
            for c in range(N):
                bc = bit_count(dom[r][c])
                if bc == 1:
                    continue
                deg = 2*(N-1)
                # approximate: inequalities around it from raw dict counts
                # (skip heavy computation)
                key = (bc, -deg)
                if key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def snapshot():
        return [row[:] for row in dom]

    def restore(snap):
        for r in range(N):
            dom[r] = snap[r][:]

    def search(cons):
        if not propagate(cons):
            return False
        if is_solved():
            return True
        cell = select_cell()
        if cell is None:
            return False
        r, c = cell
        m = dom[r][c]

        # Value ordering: try extremes first if inequalities likely; else ascending
        values = [i + 1 for i in iter_bits(m)]
        # heuristic: try middle-out? keep ascending for determinism
        for v in values:
            snap = snapshot()
            dom[r][c] = 1 << (v - 1)
            if search(cons):
                return True
            restore(snap)
        return False

    # Try with default vertical interpretation, else flip if unsat
    cons1 = constraints + build_vertical(interp_flip=False)
    if search(cons1):
        sol = [[min_val(dom[r][c]) for c in range(N)] for r in range(N)]
        return str(sol)

    # Reset domains for second attempt
    dom = [[ALL for _ in range(N)] for __ in range(N)]
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                dom[r][c] = 1 << (v - 1)

    cons2 = constraints + build_vertical(interp_flip=True)
    if search(cons2):
        sol = [[min_val(dom[r][c]) for c in range(N)] for r in range(N)]
        return str(sol)

    return "No Solution"


