        if old == newmask:
            return
        row_used[r] = newmask
        trail.append(("ru", r, old))

    def set_used_col(c, newmask):
        old = col_used[c]
        if old == newmask:
            return
        col_used[c] = newmask
        trail.append(("cu", c, old))

    def assign(k, v):
        m = bit(v)
        r, c = divmod(k, N)
        if dom[k] == m:
            return True
        if not (dom[k] & m):
            return False
        # update dom
        if not set_dom(k, m):
            return False
        # update row/col used and prune peers
        if row_used[r] & m or col_used[c] & m:
            return False
        set_used_row(r, row_used[r] | m)
        set_used_col(c, col_used[c] | m)
        # remove from row/col peers
        for cc in range(N):
            kk = idx(r, cc)
            if kk != k and (dom[kk] & m) and popcount(dom[kk]) > 1:
                if not set_dom(kk, dom[kk] & ~m):
