    # Inequality propagation for two variables A ? B.
    # If A < B:
    # - remove values in A that are >= max(B)
    # - remove values in B that are <= min(A)
    def propagate_ineq(a, b, rel):  # rel -1 means a<b, +1 means a>b
        ma = dom[a]; mb = dom[b]
        if rel == -1:
