                return False
            mb = dom[b]
            newa = ma & ~((1 << minb) - 1)       # a > minb
            if not set_dom(a, newa):
                return False
        return True

    # Hidden singles in rows/cols + inequality + forced singles loop.
    def propagate():
        q = [i for i in range(N * N)]
        inq = [True] * (N * N)
        # We do a worklist: whenever a domain changes, re-enqueue that cell and its row/col/ineq neighbors.
        while q:
            k = q.pop()
            inq[k] = False
            r, c = divmod(k, N)

            # If singleton, ensure assigned consistency with used masks and peers
            if popcount(dom[k]) == 1:
                v = dom[k].bit_length()
                m = dom[k]
                if not (row_used[r] & m):
                    if row_used[r] & m or col_used[c] & m:
                        return False
                    set_used_row(r, row_used[r] | m)
                    set_used_col(c, col_used[c] | m)
                    # prune peers
                    for cc in range(N):
                        kk = idx(r, cc)
                        if kk != k and (dom[kk] & m) and popcount(dom[kk]) > 1:
                            if not set_dom(kk, dom[kk] & ~m):
                                return False
                            if not inq[kk]:
                                q.append(kk); inq[kk] = True
                    for rr in range(N):
                        kk = idx(rr, c)
                        if kk != k and (dom[kk] & m) and popcount(dom[kk]) > 1:
                            if not set_dom(kk, dom[kk] & ~m):
                                return False
                            if not inq[kk]:
                                q.append(kk); inq[kk] = True

            # Row/col used elimination (in case used updated)
            ru = row_used[r]
            if ru and popcount(dom[k]) > 1:
                nm = dom[k] & ~ru
                if nm != dom[k]:
                    if not set_dom(k, nm):
                        return False
            cu = col_used[c]
            if cu and popcount(dom[k]) > 1:
                nm = dom[k] & ~cu
                if nm != dom[k]:
                    if not set_dom(k, nm):
                        return False

            # Inequalities
            for nb, rel in ineq[k]:
                if not propagate_ineq(k, nb, rel):
                    return False
                if dom[nb] != 0 and not inq[nb]:
                    q.append(nb); inq[nb] = True
                if not inq[k]:
                    q.append(k); inq[k] = True  # recheck after tightening

        # Hidden singles (only-choice) in each row and column
        for r in range(N):
            needed = FULL & ~row_used[r]
            # value -> last position
            positions = [None] * (N + 1)
            counts = [0] * (N + 1)
            for c in range(N):
                k = idx(r, c)
                m = dom[k] & needed
                while m:
                    lsb = m & -m
                    v = lsb.bit_length()
                    counts[v] += 1
                    positions[v] = k
                    m -= lsb
            for v in range(1, N + 1):
                if (needed & bit(v)) and counts[v] == 0:
                    return False
                if counts[v] == 1:
                    if not assign(positions[v], v):
                        return False

        for c in range(N):
            needed = FULL & ~col_used[c]
            positions = [None] * (N + 1)
            counts = [0] * (N + 1)
            for r in range(N):
                k = idx(r, c)
                m = dom[k] & needed
                while m:
                    lsb = m & -m
                    v = lsb.bit_length()
                    counts[v] += 1
                    positions[v] = k
                    m -= lsb
            for v in range(1, N + 1):
                if (needed & bit(v)) and counts[v] == 0:
                    return False
                if counts[v] == 1:
                    if not assign(positions[v], v):
                        return False

        return True

    # Initial propagation (also assigns any immediate singles)
    for k in range(N * N):
        if dom[k] == 0:
            return "No Solution"
        if popcount(dom[k]) == 1:
            r, c = divmod(k, N)
            m = dom[k]
            if (row_used[r] & m) == 0:
                if row_used[r] & m or col_used[c] & m:
                    return "No Solution"
                row_used[r] |= m
                col_used[c] |= m

    if not propagate():
        return "No Solution"

    def snapshot():
        return len(trail)

    def rollback(t):
        while len(trail) > t:
            typ, a, old = trail.pop()
            if typ == "dom":
                dom[a] = old
            elif typ == "ru":
                row_used[a] = old
            else:
                col_used[a] = old

    # Choose variable with smallest domain > 1 (MRV), tie-break by most ineq degree
    def select_var():
        best = -1
        best_sz = 999
        best_deg = -1
        for k in range(N * N):
            sz = popcount(dom[k])
            if sz > 1 and sz < best_sz:
                best = k
                best_sz = sz
                best_deg = len(ineq[k])
            elif sz > 1 and sz == best_sz:
                deg = len(ineq[k])
                if deg > best_deg:
                    best = k
                    best_deg = deg
        return best

    def iter_values(mask):
        # Try values in an order that respects inequalities loosely: middle-out
        vals = [v for v in range(1, N + 1) if mask & bit(v)]
        mid = (N + 1) / 2
        vals.sort(key=lambda x: abs(x - mid))
        return vals

    def solved():
        return all(popcount(dom[k]) == 1 for k in range(N * N))

    def dfs():
        if solved():
            return True
        k = select_var()
        if k < 0:
            return False
        m = dom[k]
        r, c = divmod(k, N)

        for v in iter_values(m):
            t = snapshot()
            if assign(k, v) and propagate():
                if dfs():
                    return True
            rollback(t)
        return False

    if not dfs():
        return "No Solution"

    grid = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            k = idx(r, c)
            grid[r][c] = dom[k].bit_length()

    return str(grid)

