from collections import defaultdict, deque

# Hitori solver: shade cells black to remove duplicates in rows/cols, avoid orth adjacency of blacks,
# and keep all whites orthogonally connected.

B = 1
W = 0
U = -1


def solve(observation):
    g = observation["data"]
    n = len(g)
    if n == 0 or any(len(r) != n for r in g):
        return "No Solution"

    N = n * n

    def idx(r, c): return r * n + c
    def rc(i): return divmod(i, n)

    nbrs = [[] for _ in range(N)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r: nbrs[i].append(idx(r - 1, c))
            if r + 1 < n: nbrs[i].append(idx(r + 1, c))
            if c: nbrs[i].append(idx(r, c - 1))
            if c + 1 < n: nbrs[i].append(idx(r, c + 1))

    # Duplicate groups per row/col for "at most one white" constraint: among equal-valued cells in a row/col.
    dup_groups = []  # list of list of cell indices
    cell_to_groups = [[] for _ in range(N)]
    for r in range(n):
        mp = defaultdict(list)
        for c in range(n):
            mp[g[r][c]].append(idx(r, c))
        for v, cells in mp.items():
            if len(cells) > 1:
                gid = len(dup_groups)
                dup_groups.append(cells)
                for i in cells:
                    cell_to_groups[i].append(gid)
    for c in range(n):
        mp = defaultdict(list)
        for r in range(n):
            mp[g[r][c]].append(idx(r, c))
        for v, cells in mp.items():
            if len(cells) > 1:
                gid = len(dup_groups)
                dup_groups.append(cells)
                for i in cells:
                    cell_to_groups[i].append(gid)

    # Initial states
    st = [U] * N

    # Counts per group for quick propagation
    group_size = [len(cells) for cells in dup_groups]
    g_white = [0] * len(dup_groups)
    g_black = [0] * len(dup_groups)
    g_unk = [sz for sz in group_size]

    # For connectivity: choose a canonical seed (first cell) to keep white; may be forced black by search, handle.
    # We'll enforce connectivity via bridge/articulation-like checks and "island" prevention.

    # Trail stack for backtracking
    trail = []
    level_mark = []

    def push_change(i, old):
        trail.append((i, old))

    def set_cell(i, val):
        """Assign st[i]=val with propagation for adjacency and duplicate groups. Returns False on contradiction."""
        old = st[i]
        if old == val:
            return True
        if old != U and old != val:
            return False
        push_change(i, old)
        st[i] = val
        # Update group counters
        for gid in cell_to_groups[i]:
            if val == W:
                g_white[gid] += 1
            else:
                g_black[gid] += 1
            g_unk[gid] -= 1
        return True

    def undo(to_mark):
        while len(trail) > to_mark:
            i, old = trail.pop()
            # rollback group counters
            new = st[i]
            if new != U:
                for gid in cell_to_groups[i]:
                    if new == W:
                        g_white[gid] -= 1
                    else:
                        g_black[gid] -= 1
                    g_unk[gid] += 1
            st[i] = old

    def contradiction():
        # Duplicate constraints: each group must have at most one white, and at least one white (can't all black)
        for gid in range(len(dup_groups)):
            if g_white[gid] > 1:
                return True
            if g_black[gid] == group_size[gid]:
                return True
        # Adjacent blacks
        for i in range(N):
            if st[i] == B:
                for j in nbrs[i]:
                    if st[j] == B:
                        return True
        return False

    # Propagation queue for assignments derived from rules
    q = deque()

    def enqueue(i, val):
        q.append((i, val))

    def propagate():
        """Apply deterministic human-like deductions repeatedly. Returns False if contradiction."""
        # Seed queue with nothing; we will add as we find consequences.
        while True:
            # Process queued assignments
            while q:
                i, val = q.popleft()
                if not set_cell(i, val):
                    return False

            if contradiction():
                return False

            progress = False

            # Rule A: No adjacent blacks -> if a cell is black, all orth neighbors are white.
            for i in range(N):
                if st[i] == B:
                    for j in nbrs[i]:
                        if st[j] == U:
                            enqueue(j, W)
                            progress = True

            # Rule B: Duplicate groups - if a group already has one white, all others black.
            # Also if all but one are black, remaining must be white.
            for gid, cells in enumerate(dup_groups):
                if g_white[gid] == 1:
                    for i in cells:
                        if st[i] == U:
                            enqueue(i, B)
                            progress = True
                else:
                    # g_white == 0
                    if g_black[gid] == group_size[gid] - 1:
                        for i in cells:
                            if st[i] == U:
                                enqueue(i, W)
                                progress = True
                                break

            # Rule C: If a cell is forced white due to being surrounded by black possibilities? (lightweight)
            # If cell has 4 neighbors and all are black, impossible (since blacks cannot touch but whites can). Not needed.

            # Rule D: Connectivity pruning (local): avoid creating isolated white islands.
            # We treat unknown as potentially white; only confirmed black blocks.
            # But a confirmed white must have at least one potential-white neighbor unless it's the only white.
            # Stronger: if a confirmed white has all neighbors confirmed black -> impossible unless N==1.
            if N > 1:
                for i in range(N):
                    if st[i] == W:
                        if all(st[j] == B for j in nbrs[i]):
                            return False

            # Rule E: Connectivity pruning (global): If multiple confirmed-white components exist that cannot be joined via unknowns -> contradiction.
            # Compute components in graph of non-black cells, but with mandatory whites as terminals.
            # If any mandatory white is unreachable from another through non-black -> impossible.
            # Also, if there exists a non-black region that contains no mandatory white and is cut off (all boundary blacks) -> it must be all black; we don't enforce fully to keep fast.
            whites = [i for i in range(N) if st[i] == W]
            if whites:
                start = whites[0]
                seen = set([start])
                dq = deque([start])
                while dq:
                    v = dq.popleft()
                    for u in nbrs[v]:
                        if st[u] != B and u not in seen:
                            seen.add(u)
                            dq.append(u)
                for w in whites[1:]:
                    if w not in seen:
                        return False

            if not progress:
                break
        return True

    # More advanced deduction: articulation/bridge forced-white (prevents disconnecting mandatory white connectivity).
    # Human-like: avoid painting a cell black if it would separate whites.
    def connectivity_forced_moves():
        """Return list of (i, W) assignments that are forced to keep white connectivity."""
        whites = [i for i in range(N) if st[i] == W]
        if len(whites) <= 1:
            return []
        # Consider graph of nodes that are not black. Unknown nodes are included.
        # Determine articulation points whose removal disconnects confirmed whites across components -> that node cannot be black (must be white).
        # We only test unknown nodes to potentially force them white.
        nodes = [i for i in range(N) if st[i] != B]
        in_graph = [False] * N
        for i in nodes:
            in_graph[i] = True

        # Map to consecutive ids for Tarjan
        id_map = [-1] * N
        for k, i in enumerate(nodes):
            id_map[i] = k
        adj = [[] for _ in range(len(nodes))]
        for i in nodes:
            a = id_map[i]
            for j in nbrs[i]:
                if in_graph[j]:
                    adj[a].append(id_map[j])

        must = [False] * len(nodes)
        for w in whites:
            must[id_map[w]] = True

        # Tarjan articulation
        m = len(nodes)
        disc = [-1] * m
        low = [0] * m
        parent = [-1] * m
        t = 0
        forced = []

        # To decide if articulation separates must-nodes, we compute subtree must counts.
        sub_must = [0] * m

        def dfs(u):
            nonlocal t
            disc[u] = low[u] = t
            t += 1
            sub_must[u] = 1 if must[u] else 0
            child = 0
            for v in adj[u]:
                if disc[v] == -1:
                    parent[v] = u
                    child += 1
                    dfs(v)
                    sub_must[u] += sub_must[v]
                    low[u] = min(low[u], low[v])
                elif v != parent[u]:
                    low[u] = min(low[u], disc[v])

        # Run DFS from first mandatory white node
        root = id_map[whites[0]]
        dfs(root)

        total_must = sum(1 for x in must if x)

        # If some mandatory white wasn't reached (should have been caught earlier), no forced moves.
        if sub_must[root] != total_must:
            return []

        # Second pass to determine separating articulations:
        # For an articulation u, if there exists a child v with low[v] >= disc[u] and the subtree contains some must,
        # and also there exists must outside that subtree, then u is required as non-black; if u is unknown, force white.
        for u in range(m):
            if not must[u] and st[nodes[u]] != U:
                continue
            # Evaluate articulation property
            if u == root:
                # root is articulation if it has >=2 child subtrees containing must; if yes, root cannot be black.
                # Count children of root in DFS tree with must in subtree
                cnt = 0
                for v in adj[u]:
                    if parent[v] == u and low[v] >= disc[u] and sub_must[v] > 0:
                        cnt += 1
                if cnt >= 2:
                    cell = nodes[u]
                    if st[cell] == U:
                        forced.append((cell, W))
                continue
            # non-root
            for v in adj[u]:
                if parent[v] == u and low[v] >= disc[u]:
                    inside = sub_must[v]
                    outside = total_must - inside
                    if inside > 0 and outside > 0:
                        cell = nodes[u]
                        if st[cell] == U:
                            forced.append((cell, W))
                        break
        return forced

    def deterministic_phase():
        """Run propagation plus connectivity forced moves to a fixpoint."""
        while True:
            mark = len(trail)
            if not propagate():
                return False
            forced = connectivity_forced_moves()
            if not forced:
                return True
            for i, val in forced:
                enqueue(i, val)
            if len(trail) == mark and not forced:
                return True

    def is_solved():
        if any(x == U for x in st):
            return False
        if contradiction():
            return False
        # All whites connected
        whites = [i for i in range(N) if st[i] == W]
        if not whites:
            return False
        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            v = dq.popleft()
            for u in nbrs[v]:
                if st[u] == W and u not in seen:
                    seen.add(u)
                    dq.append(u)
        return len(seen) == len(whites)

    def choose_var():
        # Pick an unknown with most constraint pressure: in many dup groups, and near other blacks/whites
        best = -1
        best_score = -1
        for i in range(N):
            if st[i] != U:
                continue
            score = 0
            for gid in cell_to_groups[i]:
                # prefer groups close to being decided
                if g_white[gid] == 1:
                    score += 5
                elif g_black[gid] == group_size[gid] - 1:
                    score += 4
                else:
                    score += 2
            # adjacency pressure
            for j in nbrs[i]:
                if st[j] == B:
                    score += 6  # can't be black adjacent; tends to force white
                elif st[j] == W:
                    score += 1
            if score > best_score:
                best_score = score
                best = i
        return best

    def order_values(i):
        # Try white first generally to preserve connectivity, but if duplicates press, maybe black.
        # Heuristic: if any group would get 2 whites by setting white? that's impossible; will be pruned.
        # If any group already has 1 white, then i must be black -> handled by propagation; so here g_white==0 for those groups.
        # If setting black would complete all-black in a group -> impossible.
        canW = True
        for gid in cell_to_groups[i]:
            if g_white[gid] >= 1:
                canW = False
                break
        canB = True
        for gid in cell_to_groups[i]:
            if g_black[gid] + 1 == group_size[gid]:
                canB = False
                break
        # adjacency: if any neighbor is black, cannot be black
        if any(st[j] == B for j in nbrs[i]):
            canB = False
        vals = []
        if canW:
            vals.append(W)
        if canB:
            vals.append(B)
        # If both possible, decide by pressure: if i is in large duplicate groups, black helps remove duplicates.
        if len(vals) == 2:
            pressure = sum(group_size[gid] for gid in cell_to_groups[i])
            if pressure >= 6:
                vals = [B, W]
        return vals

    def dfs():
        if not deterministic_phase():
            return False
        if is_solved():
            return True
        i = choose_var()
        if i == -1:
            return False
        vals = order_values(i)
        if not vals:
            return False
        mark = len(trail)
        for v in vals:
            level_mark.append(mark)
            enqueue(i, v)
            if dfs():
                return True
            undo(mark)
            # clear any pending queue items (should be empty due to deterministic_phase, but safe)
            q.clear()
        return False

    # Initial deterministic deductions
    if not deterministic_phase():
        return "No Solution"
    if not dfs():
        return "No Solution"

    # Build output mask
    mask = [[None] * n for _ in range(n)]
    for i in range(N):
        r, c = rc(i)
        if st[i] == B:
            mask[r][c] = 'B'
        else:
            mask[r][c] = None
    return str(mask)


