from collections import deque

# Futoshiki solver: Latin square (rows/cols 1..N all-different) + inequalities.
# Emphasizes human-like deduction:
# - Candidate elimination by row/col used numbers
# - Inequality arc consistency (bounds + direct support pruning)
# - Hidden singles in row/col
# - Strong propagation loop
# - MRV + LCV search as last resort (not naive brute force)

def solve(observation):
    grid = observation["data"]
    N = len(grid)
    nums_mask_all = (1 << N) - 1

    # Parse inequalities into directional adjacency:
    # For each cell a, store constraints with neighbor b: a < b or a > b.
    # Represent as (ra,ca, rb,cb, rel) where rel is -1 if a<b, +1 if a>b.
    edges = []
    # Horizontal keys: "(r,c+0.5)" symbol between (r,c) and (r,c+1)
    for k, sym in observation.get("horizontal", {}).items():
        r, cph = eval(k)  # input guaranteed from our literal
        c = int(cph - 0.5)
        a = (r, c)
        b = (r, c + 1)
        if sym == '<':
            edges.append((a, b, -1))  # a < b
        elif sym == '>':
            edges.append((a, b, +1))  # a > b
    # Vertical keys: "(r+0.5,c)" symbol between (r,c) and (r+1,c)
    # '^' means upper cell is smaller than lower cell (top < bottom)
    # 'v' means upper cell is greater than lower cell (top > bottom)
    for k, sym in observation.get("vertical", {}).items():
        rph, c = eval(k)
        r = int(rph - 0.5)
        top = (r, c)
        bot = (r + 1, c)
        if sym == '^':
            edges.append((top, bot, -1))  # top < bottom
        elif sym == 'v':
            edges.append((top, bot, +1))  # top > bottom

    # Build adjacency for faster propagation
    adj = [[[] for _ in range(N)] for __ in range(N)]
    for (ra, ca), (rb, cb), rel in edges:
        adj[ra][ca].append((rb, cb, rel))
        adj[rb][cb].append((ra, ca, -rel))  # invert relation for reverse view

    def bit_count(x):
        return x.bit_count()

    def lowbit_index(x):
        # x has single bit set
        return (x & -x).bit_length() - 1

    def mask_to_min(mask):
        return (mask & -mask).bit_length()  # 1..N

    def mask_to_max(mask):
        return mask.bit_length()  # 1..N

    def iter_vals(mask):
        while mask:
            b = mask & -mask
            v = b.bit_length()  # 1..N
            yield v
            mask ^= b

    def val_to_mask(v):
        return 1 << (v - 1)

    # Initialize domains
    dom = [[nums_mask_all for _ in range(N)] for __ in range(N)]
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v is not None:
                m = val_to_mask(v)
                dom[r][c] = m

    # Precompute row/col peers for quick used mask updates
    row_cells = [[(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[(r, c) for r in range(N)] for c in range(N)]

    def is_solved(dom):
        for r in range(N):
            for c in range(N):
                if dom[r][c] & (dom[r][c] - 1):
                    return False
        return True

    def apply_all_different(dom):
        # Eliminate used singles from row/col peers
        changed = False
        for r in range(N):
            used = 0
            for c in range(N):
                m = dom[r][c]
                if m and (m & (m - 1)) == 0:
                    used |= m
            for c in range(N):
                m = dom[r][c]
                if m & (m - 1):
                    nm = m & ~used
                    if nm != m:
                        dom[r][c] = nm
                        changed = True
                        if nm == 0:
                            return False, True
        for c in range(N):
            used = 0
            for r in range(N):
                m = dom[r][c]
                if m and (m & (m - 1)) == 0:
                    used |= m
            for r in range(N):
                m = dom[r][c]
                if m & (m - 1):
                    nm = m & ~used
                    if nm != m:
                        dom[r][c] = nm
                        changed = True
                        if nm == 0:
                            return False, True
        return True, changed

    def hidden_singles(dom):
        # If a number appears in only one domain in a row/col, assign it.
        changed = False
        for r in range(N):
            counts = [0] * (N + 1)
            lastpos = [None] * (N + 1)
            for c in range(N):
                m = dom[r][c]
                for v in iter_vals(m):
                    counts[v] += 1
                    lastpos[v] = (r, c)
            for v in range(1, N + 1):
                if counts[v] == 1:
                    rr, cc = lastpos[v]
                    m = dom[rr][cc]
                    vm = val_to_mask(v)
                    if m != vm:
                        dom[rr][cc] = vm
                        changed = True
        for c in range(N):
            counts = [0] * (N + 1)
            lastpos = [None] * (N + 1)
            for r in range(N):
                m = dom[r][c]
                for v in iter_vals(m):
                    counts[v] += 1
                    lastpos[v] = (r, c)
            for v in range(1, N + 1):
                if counts[v] == 1:
                    rr, cc = lastpos[v]
                    m = dom[rr][cc]
                    vm = val_to_mask(v)
                    if m != vm:
                        dom[rr][cc] = vm
                        changed = True
        return True, changed

    def prune_ineq_bounds(dom, ra, ca, rb, cb, rel):
        # rel = -1 means a<b, +1 means a>b
        ma = dom[ra][ca]
        mb = dom[rb][cb]
        if ma == 0 or mb == 0:
            return False, True
        changed = False
        mina, maxa = mask_to_min(ma), mask_to_max(ma)
        minb, maxb = mask_to_min(mb), mask_to_max(mb)

        if rel == -1:
            # a < b => a <= maxb-1, b >= mina+1
            if maxb <= 1:
                return False, True
            if mina >= N:
                return False, True
            # tighten a upper bound
            if maxa >= maxb:
                # remove values >= maxb
                cutoff = maxb - 1
                allowed = (1 << cutoff) - 1  # 1..cutoff
                na = ma & allowed
                if na != ma:
                    dom[ra][ca] = na
                    changed = True
                    if na == 0:
                        return False, True
                    ma = na
                    mina, maxa = mask_to_min(ma), mask_to_max(ma)
            # tighten b lower bound
            if minb <= mina:
                cutoff = mina + 1
                allowed = nums_mask_all & ~((1 << (cutoff - 1)) - 1)  # cutoff..N
                nb = mb & allowed
                if nb != mb:
                    dom[rb][cb] = nb
                    changed = True
                    if nb == 0:
                        return False, True
        else:
            # a > b
            if maxa <= 1:
                return False, True
            if minb >= N:
                return False, True
            # a >= minb+1
            if mina <= minb:
                cutoff = minb + 1
                allowed = nums_mask_all & ~((1 << (cutoff - 1)) - 1)
                na = ma & allowed
                if na != ma:
                    dom[ra][ca] = na
                    changed = True
                    if na == 0:
                        return False, True
                    ma = na
                    mina, maxa = mask_to_min(ma), mask_to_max(ma)
            # b <= maxa-1
            if maxb >= maxa:
                cutoff = maxa - 1
                allowed = (1 << cutoff) - 1 if cutoff >= 1 else 0
                nb = mb & allowed
                if nb != mb:
                    dom[rb][cb] = nb
                    changed = True
                    if nb == 0:
                        return False, True
        return True, changed

    def prune_ineq_support(dom, ra, ca, rb, cb, rel):
        # Arc-consistency-ish filtering: remove values in a that have no support in b and vice versa.
        ma = dom[ra][ca]
        mb = dom[rb][cb]
        if ma == 0 or mb == 0:
            return False, True
        changed = False

        if rel == -1:
            # a < b: for each a=v, need exists b>w with w>v
            # Supported a values are those with v < max(b)
            maxb = mask_to_max(mb)
            supported_a = ma & ((1 << (maxb - 1)) - 1) if maxb > 1 else 0
            if supported_a != ma:
                dom[ra][ca] = supported_a
                changed = True
                if supported_a == 0:
                    return False, True
                ma = supported_a
            # Supported b values are those with w > min(a)
            mina = mask_to_min(ma)
            supported_b = mb & (nums_mask_all & ~((1 << mina) - 1))  # (mina+1..N)
            if supported_b != mb:
                dom[rb][cb] = supported_b
                changed = True
                if supported_b == 0:
                    return False, True
        else:
            # a > b
            minb = mask_to_min(mb)
            supported_a = ma & (nums_mask_all & ~((1 << minb) - 1))  # minb+1..N
            if supported_a != ma:
                dom[ra][ca] = supported_a
                changed = True
                if supported_a == 0:
                    return False, True
                ma = supported_a
            maxa = mask_to_max(ma)
            supported_b = mb & ((1 << (maxa - 1)) - 1) if maxa > 1 else 0
            if supported_b != mb:
                dom[rb][cb] = supported_b
                changed = True
                if supported_b == 0:
                    return False, True
        return True, changed

    def propagate(dom):
        # Queue-based propagation over affected cells (all-different and inequalities).
        q = deque()
        inq = [[False]*N for _ in range(N)]
        def push(r,c):
            if not inq[r][c]:
                inq[r][c] = True
                q.append((r,c))

        # start with all cells
        for r in range(N):
            for c in range(N):
                push(r,c)

        while q:
            r,c = q.popleft()
            inq[r][c] = False

            # all-different elimination effect on row/col by re-running lightweight elimination for this row/col
            # (human-like: every new single removes from peers)
            m = dom[r][c]
            if m == 0:
                return False
            if (m & (m-1)) == 0:
                # eliminate from row peers
                for cc in range(N):
                    if cc == c: continue
                    mm = dom[r][cc]
                    if mm & m:
                        nm = mm & ~m
                        if nm != mm:
                            dom[r][cc] = nm
                            if nm == 0: return False
                            push(r,cc)
                # eliminate from col peers
                for rr in range(N):
                    if rr == r: continue
                    mm = dom[rr][c]
                    if mm & m:
                        nm = mm & ~m
                        if nm != mm:
                            dom[rr][c] = nm
                            if nm == 0: return False
                            push(rr,c)

            # inequality propagation to neighbors
            for (rb, cb, rel) in adj[r][c]:
                ok, ch = prune_ineq_bounds(dom, r, c, rb, cb, rel)
                if not ok:
                    return False
                if ch:
                    push(r,c); push(rb,cb)
                ok, ch2 = prune_ineq_support(dom, r, c, rb, cb, rel)
                if not ok:
                    return False
                if ch2:
                    push(r,c); push(rb,cb)

        # Global hidden singles sweep occasionally helps
        ok, ch = apply_all_different(dom)
        if not ok: return False
        ok2, ch2 = hidden_singles(dom)
        if not ok2: return False

        # If hidden singles created new singles, redo local propagation quickly
        if ch or ch2:
            return propagate(dom)
        return True

    def select_unassigned(dom):
        best = None
        best_sz = 10**9
        for r in range(N):
            for c in range(N):
                m = dom[r][c]
                if m == 0:
                    return None
                if m & (m-1):
                    sz = bit_count(m)
                    if sz < best_sz:
                        best_sz = sz
                        best = (r,c)
                        if sz == 2:
                            return best
        return best

    def lcv_order(dom, r, c):
        # Least-constraining value by counting eliminations in peers and inequality neighbors.
        m = dom[r][c]
        vals = list(iter_vals(m))
        scores = []
        row_peers = [(r, cc) for cc in range(N) if cc != c]
        col_peers = [(rr, c) for rr in range(N) if rr != r]
        neigh = adj[r][c]

        for v in vals:
            vm = val_to_mask(v)
            elim = 0
            for rr,cc in row_peers:
                if dom[rr][cc] & vm:
                    elim += 1
            for rr,cc in col_peers:
                if dom[rr][cc] & vm:
                    elim += 1
            # inequality neighbor feasibility quick check
            for rb,cb,rel in neigh:
                mb = dom[rb][cb]
                if rel == -1:
                    # v < b => b must have >v
                    allowedb = mb & (nums_mask_all & ~((1<<v)-1))
                    if allowedb == 0:
                        elim += 1000
                else:
                    # v > b => b must have <v
                    allowedb = mb & ((1<<(v-1))-1 if v>1 else 0)
                    if allowedb == 0:
                        elim += 1000
            scores.append((elim, v))
        scores.sort()
        return [v for _, v in scores]

    def deep_copy(dom):
        return [row[:] for row in dom]

    def search(dom):
        if not propagate(dom):
            return None
        if is_solved(dom):
            sol = [[None]*N for _ in range(N)]
            for r in range(N):
                for c in range(N):
                    sol[r][c] = lowbit_index(dom[r][c]) + 1
            return sol

        cell = select_unassigned(dom)
        if cell is None:
            return None
        r,c = cell
        for v in lcv_order(dom, r, c):
            nd = deep_copy(dom)
            nd[r][c] = val_to_mask(v)
            res = search(nd)
            if res is not None:
                return res
        return None

    # Validate givens (row/col duplicates)
    for r in range(N):
        seen = set()
        for c in range(N):
            v = grid[r][c]
            if v is not None:
                if v in seen:
                    return "No Solution"
                seen.add(v)
    for c in range(N):
        seen = set()
        for r in range(N):
            v = grid[r][c]
            if v is not None:
                if v in seen:
                    return "No Solution"
                seen.add(v)

    ans = search(dom)
    return ans if ans is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 2, 2], [0, 0, 1, 3, 2], [4, 4, 1, 3, 2], [4, 4, 5, 5, 5], [6, 6, 6, 6, 6]], 'data': [[None, 5, None, None, 1], [None, None, None, 4, None], [None, None, None, None, None], [None, 2, None, None, None], [1, None, None, 2, None]]}
from collections import defaultdict, deque

# Irregular Sudoku / Jigsaw Latin square solver for NxN with regions.
# Human-like deduction: singles, hidden singles, intersection claims, and strong propagation.
# Search: MRV + LCV with forward-checking; not brute-force due to heavy inference each node.

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    N = len(region)
    if N == 0 or any(len(r) != N for r in region) or any(len(r) != N for r in data):
        return "No Solution"

    digits = list(range(1, N + 1))
    allmask = (1 << N) - 1

    def bit(v):  # v in 1..N
        return 1 << (v - 1)

    # Build regions map
    reg_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            reg_cells[region[r][c]].append((r, c))

    # Validate each region size == N
    if any(len(cells) != N for cells in reg_cells.values()):
        return "No Solution"
    R = list(reg_cells.keys())

    # Precompute units
    rows = [[(r, c) for c in range(N)] for r in range(N)]
    cols = [[(r, c) for r in range(N)] for c in range(N)]
    regs = [reg_cells[rid] for rid in R]

    # Cell -> units indices (row, col, reg)
    cell_reg = [[region[r][c] for c in range(N)] for r in range(N)]
    reg_index = {rid: i for i, rid in enumerate(R)}

    # Neighbors for each cell
    neighbors = [[set() for _ in range(N)] for __ in range(N)]
    for r in range(N):
        for c in range(N):
            nbs = neighbors[r][c]
            for cc in range(N):
                if cc != c: nbs.add((r, cc))
            for rr in range(N):
                if rr != r: nbs.add((rr, c))
            for (rr, cc) in reg_cells[cell_reg[r][c]]:
                if (rr, cc) != (r, c): nbs.add((rr, cc))

    # Masks for used digits in each unit
    row_used = [0] * N
    col_used = [0] * N
    reg_used = [0] * len(R)

    # Domain masks per cell
    dom = [[allmask for _ in range(N)] for __ in range(N)]

    # Load givens, validate
    grid = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= N):
                return "No Solution"
            ridx = reg_index[cell_reg[r][c]]
            m = bit(v)
            if (row_used[r] & m) or (col_used[c] & m) or (reg_used[ridx] & m):
                return "No Solution"
            grid[r][c] = v
            row_used[r] |= m
            col_used[c] |= m
            reg_used[ridx] |= m

    # Initialize domains from used masks
    for r in range(N):
        for c in range(N):
            if grid[r][c]:
                dom[r][c] = bit(grid[r][c])
            else:
                ridx = reg_index[cell_reg[r][c]]
                forb = row_used[r] | col_used[c] | reg_used[ridx]
                dom[r][c] = allmask & ~forb
                if dom[r][c] == 0:
                    return "No Solution"

    # Helpers
    def popcount(x):
        return x.bit_count()

    def lowest_bit_index(x):
        # x != 0
        return (x & -x).bit_length() - 1

    def mask_to_vals(m):
        # iterate values from bitmask
        while m:
            lb = m & -m
            i = lb.bit_length() - 1
            yield i + 1
            m ^= lb

    # Assignment with trail for backtracking
    trail = []

    def push_state(r, c, old_dom, old_val=0):
        trail.append((r, c, old_dom, old_val))

    def undo(to_len):
        nonlocal row_used, col_used, reg_used
        while len(trail) > to_len:
            r, c, old_dom, old_val = trail.pop()
            # If old_val nonzero: it indicates we changed grid value and unit masks
            if old_val:
                v = grid[r][c]
                # remove current v from unit masks
                ridx = reg_index[cell_reg[r][c]]
                m = bit(v)
                row_used[r] ^= m
                col_used[c] ^= m
                reg_used[ridx] ^= m
                grid[r][c] = old_val  # old_val is previous grid val (usually 0)
            dom[r][c] = old_dom

    def assign(r, c, v, q):
        """Assign value v to cell (r,c), enqueue propagation. Returns False if contradiction."""
        if grid[r][c] == v:
            return True
        if grid[r][c] != 0 and grid[r][c] != v:
            return False
        m = bit(v)
        if not (dom[r][c] & m):
            return False
        # Save domain and previous value
        push_state(r, c, dom[r][c], grid[r][c])
        # Set grid and domain to singleton
        grid[r][c] = v
        dom[r][c] = m
        # Update used masks
        ridx = reg_index[cell_reg[r][c]]
        if (row_used[r] & m) or (col_used[c] & m) or (reg_used[ridx] & m):
            return False
        row_used[r] |= m
        col_used[c] |= m
        reg_used[ridx] |= m
        # Enqueue this assignment for neighbor elimination
        q.append((r, c))
        return True

    def eliminate(r, c, mask_remove, q):
        """Remove bits in mask_remove from dom[r][c]. Enqueue if becomes singleton. False if empty."""
        if grid[r][c]:
            return True
        cur = dom[r][c]
        new = cur & ~mask_remove
        if new == cur:
            return True
        if new == 0:
            return False
        push_state(r, c, cur, 0)
        dom[r][c] = new
        if popcount(new) == 1:
            v = lowest_bit_index(new) + 1
            if not assign(r, c, v, q):
                return False
        return True

    # Unit-based deductions: hidden singles + intersection claims
    def hidden_singles_and_claims(q):
        # Hidden singles in row/col/reg, and intersection "claiming" (pointing)
        # Return False if contradiction
        # Hidden singles: for each digit, if only one cell in unit can take it => assign.
        # Claiming:
        #   - In a region, for digit d, if all candidate cells lie in one row -> eliminate d from that row outside region.
        #   - Similarly for one col.
        # (Also reverse: in a row, if candidates for d all lie in one region -> eliminate in that region outside the row; same for col.)
        # Repeat until no progress.
        changed = True
        while changed:
            changed = False

            # Precompute candidates per unit quickly
            # Rows
            for r in range(N):
                used = row_used[r]
                missing = allmask & ~used
                if missing == 0:
                    continue
                # digit -> (count, last_c)
                counts = [0] * N
                lastpos = [None] * N
                for c in range(N):
                    if grid[r][c]:
                        continue
                    m = dom[r][c] & missing
                    mm = m
                    while mm:
                        lb = mm & -mm
                        i = lb.bit_length() - 1
                        counts[i] += 1
                        lastpos[i] = (r, c)
                        mm ^= lb
                for i in range(N):
                    if (missing >> i) & 1:
                        if counts[i] == 0:
                            return False
                        if counts[i] == 1:
                            rr, cc = lastpos[i]
                            if not assign(rr, cc, i + 1, q):
                                return False
                            changed = True

                # Row->Region claiming: if digit candidates all in one region, eliminate in region outside row
                for d in mask_to_vals(missing):
                    rid = None
                    ok = True
                    for c in range(N):
                        if grid[r][c] == 0 and (dom[r][c] & bit(d)):
                            crid = cell_reg[r][c]
                            if rid is None:
                                rid = crid
                            elif rid != crid:
                                ok = False
                                break
                    if ok and rid is not None:
                        for (rr, cc) in reg_cells[rid]:
                            if rr != r and grid[rr][cc] == 0 and (dom[rr][cc] & bit(d)):
                                if not eliminate(rr, cc, bit(d), q):
                                    return False
                                changed = True

            # Cols
            for c in range(N):
                used = col_used[c]
                missing = allmask & ~used
                if missing == 0:
                    continue
                counts = [0] * N
                lastpos = [None] * N
                for r in range(N):
                    if grid[r][c]:
                        continue
                    m = dom[r][c] & missing
                    mm = m
                    while mm:
                        lb = mm & -mm
                        i = lb.bit_length() - 1
                        counts[i] += 1
                        lastpos[i] = (r, c)
                        mm ^= lb
                for i in range(N):
                    if (missing >> i) & 1:
                        if counts[i] == 0:
                            return False
                        if counts[i] == 1:
                            rr, cc = lastpos[i]
                            if not assign(rr, cc, i + 1, q):
                                return False
                            changed = True

                # Col->Region claiming
                for d in mask_to_vals(missing):
                    rid = None
                    ok = True
                    for r in range(N):
                        if grid[r][c] == 0 and (dom[r][c] & bit(d)):
                            crid = cell_reg[r][c]
                            if rid is None:
                                rid = crid
                            elif rid != crid:
                                ok = False
                                break
                    if ok and rid is not None:
                        for (rr, cc) in reg_cells[rid]:
                            if cc != c and grid[rr][cc] == 0 and (dom[rr][cc] & bit(d)):
                                if not eliminate(rr, cc, bit(d), q):
                                    return False
                                changed = True

            # Regions
            for rid in R:
                cells = reg_cells[rid]
                used = reg_used[reg_index[rid]]
                missing = allmask & ~used
                if missing == 0:
                    continue
                counts = [0] * N
                lastpos = [None] * N
                # Also track rows/cols coverage for each digit for pointing
                rowset = [0] * N  # bitset of rows indices (N<=32 typical; we store as bitmask)
                colset = [0] * N
                for (r, c) in cells:
                    if grid[r][c]:
                        continue
                    m = dom[r][c] & missing
                    mm = m
                    while mm:
                        lb = mm & -mm
                        i = lb.bit_length() - 1
                        counts[i] += 1
                        lastpos[i] = (r, c)
                        rowset[i] |= 1 << r
                        colset[i] |= 1 << c
                        mm ^= lb
                for i in range(N):
                    if (missing >> i) & 1:
                        if counts[i] == 0:
                            return False
                        if counts[i] == 1:
                            rr, cc = lastpos[i]
                            if not assign(rr, cc, i + 1, q):
                                return False
                            changed = True
                        else:
                            # Pointing: all candidates in one row/col
                            rs = rowset[i]
                            cs = colset[i]
                            if rs and (rs & (rs - 1)) == 0:
                                r0 = (rs.bit_length() - 1)
                                dmask = bit(i + 1)
                                for cc in range(N):
                                    if cell_reg[r0][cc] != rid and grid[r0][cc] == 0 and (dom[r0][cc] & dmask):
                                        if not eliminate(r0, cc, dmask, q):
                                            return False
                                        changed = True
                            if cs and (cs & (cs - 1)) == 0:
                                c0 = (cs.bit_length() - 1)
                                dmask = bit(i + 1)
                                for rr in range(N):
                                    if cell_reg[rr][c0] != rid and grid[rr][c0] == 0 and (dom[rr][c0] & dmask):
                                        if not eliminate(rr, c0, dmask, q):
                                            return False
                                        changed = True
        return True

    def propagate(q):
        """Arc-consistency-ish propagation from assignments + unit deductions."""
        while True:
            # Process direct eliminations from assigned cells in queue
            while q:
                r, c = q.pop()
                v = grid[r][c]
                if v == 0:
                    continue
                rm = bit(v)
                for (rr, cc) in neighbors[r][c]:
                    if grid[rr][cc] == 0 and (dom[rr][cc] & rm):
                        if not eliminate(rr, cc, rm, q):
                            return False
            # Apply higher-order deductions; if it enqueues new singles, loop
            before = len(trail)
            if not hidden_singles_and_claims(q):
                return False
            # If no new assignments/dom changes occurred, stop.
            if len(trail) == before and not q:
                return True

    # Initial propagation from givens
    init_q = deque()
    for r in range(N):
        for c in range(N):
            if grid[r][c]:
                init_q.append((r, c))
    if not propagate(init_q):
        return "No Solution"

    def solved():
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    return False
        return True

    def select_unassigned_cell():
        # MRV with degree tie-break
        best = None
        best_cnt = 10**9
        best_deg = -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    cnt = popcount(dom[r][c])
                    if cnt < best_cnt:
                        best_cnt = cnt
                        best_deg = sum(1 for (rr, cc) in neighbors[r][c] if grid[rr][cc] == 0)
                        best = (r, c)
                    elif cnt == best_cnt:
                        deg = sum(1 for (rr, cc) in neighbors[r][c] if grid[rr][cc] == 0)
                        if deg > best_deg:
                            best_deg = deg
                            best = (r, c)
        return best, best_cnt

    def order_values_lcv(r, c):
        # Least-constraining value: count eliminations in neighbors
        vals = list(mask_to_vals(dom[r][c]))
        if len(vals) <= 1:
            return vals
        scores = []
        for v in vals:
            rm = bit(v)
            elim = 0
            for (rr, cc) in neighbors[r][c]:
                if grid[rr][cc] == 0 and (dom[rr][cc] & rm):
                    elim += 1
            scores.append((elim, v))
        scores.sort()
        return [v for _, v in scores]

    def dfs():
        if solved():
            return True

        (r, c), cnt = select_unassigned_cell()
        if (r, c) is None:
            return True
        if cnt == 0:
            return False

        snapshot = len(trail)
        for v in order_values_lcv(r, c):
            q = deque()
            if assign(r, c, v, q) and propagate(q):
                if dfs():
                    return True
            undo(snapshot)
        return False

    if not dfs():
        return "No Solution"

    return str([[grid[r][c] for c in range(N)] for r in range(N)])

