from __future__ import annotations

# Irregular Sudoku (a.k.a. Jigsaw Sudoku) solver with human-like propagation:
# - bitmask domains, peers
# - naked singles
# - hidden singles (row/col/region)
# - naked pairs / triples (row/col/region)
# - pointing pairs/triples (box->row/col) generalized for irregular regions
# - MRV + degree heuristic for branching when needed
# No external solvers.

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    N = len(region)
    if N == 0 or any(len(r) != N for r in region) or any(len(r) != N for r in data):
        return "No Solution"

    # Validate symbols 1..N
    full_mask = (1 << N) - 1

    def bit(v):  # v in 1..N
        return 1 << (v - 1)

    def popcount(x: int) -> int:
        return x.bit_count()

    def lowest_bit_index(x: int) -> int:
        return (x & -x).bit_length() - 1  # 0-based

    # Build region cells map
    reg_cells = {}
    for r in range(N):
        for c in range(N):
            rid = region[r][c]
            reg_cells.setdefault(rid, []).append((r, c))
    # Each region must have exactly N cells
    if any(len(cells) != N for cells in reg_cells.values()):
        return "No Solution"
    # Number of regions must be N
    if len(reg_cells) != N:
        # Still can be solvable if IDs not 0..N-1? But must be N distinct regions.
        # Accept if count is N; else fail.
        return "No Solution"

    # Precompute units
    rows = [[(r, c) for c in range(N)] for r in range(N)]
    cols = [[(r, c) for r in range(N)] for c in range(N)]
    regs = [reg_cells[rid] for rid in sorted(reg_cells.keys())]

    # Map cell -> region index in regs order
    rid_to_idx = {rid: i for i, rid in enumerate(sorted(reg_cells.keys()))}
    cell_reg = [[rid_to_idx[region[r][c]] for c in range(N)] for r in range(N)]

    # Peers
    peers = [[None] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            pr = set(rows[r]) | set(cols[c]) | set(regs[cell_reg[r][c]])
            pr.discard((r, c))
            peers[r][c] = tuple(pr)

    # Unit lists for each cell (indices)
    units = [[None] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            units[r][c] = (rows[r], cols[c], regs[cell_reg[r][c]])

    # Domains init
    dom = [[full_mask for _ in range(N)] for _ in range(N)]

    # Track used masks for each unit for quick elimination
    row_used = [0] * N
    col_used = [0] * N
    reg_used = [0] * N

    # Place givens with consistency check
    def assign(r, c, vmask, trail):
        """Assign cell (r,c) to exactly vmask (single-bit). Record changes in trail."""
        if dom[r][c] == vmask:
            return True
        if (dom[r][c] & vmask) == 0:
            return False
        trail.append((r, c, dom[r][c]))
        dom[r][c] = vmask
        return True

    # Remove candidates
    def eliminate(r, c, emask, trail):
        """Remove bits in emask from dom[r][c]."""
        cur = dom[r][c]
        nxt = cur & ~emask
        if nxt == cur:
            return True
        if nxt == 0:
            return False
        trail.append((r, c, cur))
        dom[r][c] = nxt
        return True

    # Initial constraint from givens
    trail = []
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                if not assign(r, c, bit(v), trail):
                    return "No Solution"

    # Build used masks based on fixed domains (singletons)
    def rebuild_used():
        for i in range(N):
            row_used[i] = 0
            col_used[i] = 0
            reg_used[i] = 0
        for r in range(N):
            for c in range(N):
                m = dom[r][c]
                if m & (m - 1) == 0:  # singleton
                    row_used[r] |= m
                    col_used[c] |= m
                    reg_used[cell_reg[r][c]] |= m

    rebuild_used()

    # Propagation engine
    def propagate(trail):
        """Apply iterative logical deductions until fixpoint. Return False if contradiction."""
        changed = True
        while changed:
            changed = False
            rebuild_used()

            # Basic elimination from used values
            for r in range(N):
                ru = row_used[r]
                for c in range(N):
                    if dom[r][c] & (dom[r][c] - 1):  # not singleton
                        em = ru | col_used[c] | reg_used[cell_reg[r][c]]
                        if em:
                            before = dom[r][c]
                            if not eliminate(r, c, em, trail):
                                return False
                            if dom[r][c] != before:
                                changed = True

            # If any cell becomes singleton, need to enforce peer eliminations quickly
            # (already done via rebuild + elimination loops, but do direct queue for speed)
            queue = []
            for r in range(N):
                for c in range(N):
                    m = dom[r][c]
                    if m & (m - 1) == 0:
                        queue.append((r, c, m))
            seen = set(queue)
            while queue:
                r, c, m = queue.pop()
                # eliminate this value from peers
                for pr, pc in peers[r][c]:
                    if dom[pr][pc] & m:
                        before = dom[pr][pc]
                        if not eliminate(pr, pc, m, trail):
                            return False
                        if dom[pr][pc] != before:
                            changed = True
                            nm = dom[pr][pc]
                            if nm & (nm - 1) == 0:
                                key = (pr, pc, nm)
                                if key not in seen:
                                    seen.add(key)
                                    queue.append(key)

            # Hidden singles in each unit
            # For each unit, compute candidate locations per digit using bit aggregation.
            def hidden_singles_in_unit(unit_cells):
                nonlocal changed
                # For each digit bit, track OR of positions? We'll count occurrences via arrays.
                counts = [0] * N
                lastpos = [None] * N
                for (r, c) in unit_cells:
                    m = dom[r][c]
                    x = m
                    while x:
                        b = x & -x
                        d = b.bit_length() - 1
                        counts[d] += 1
                        lastpos[d] = (r, c)
                        x -= b
                for d in range(N):
                    if counts[d] == 1:
                        r, c = lastpos[d]
                        vmask = 1 << d
                        if dom[r][c] != vmask:
                            if not assign(r, c, vmask, trail):
                                return False
                            changed = True
                return True

            for r in range(N):
                if not hidden_singles_in_unit(rows[r]):
                    return False
            for c in range(N):
                if not hidden_singles_in_unit(cols[c]):
                    return False
            for g in range(N):
                if not hidden_singles_in_unit(regs[g]):
                    return False

            # Naked pairs/triples (subset elimination) in units
            def naked_subsets_in_unit(unit_cells, max_k=3):
                nonlocal changed
                # Collect unsolved cells
                cells = [(r, c, dom[r][c]) for (r, c) in unit_cells if dom[r][c] & (dom[r][c]-1)]
                if len(cells) < 2:
                    return True
                # Group by mask for quick pairs
                bymask = {}
                for r, c, m in cells:
                    pc = popcount(m)
                    if 2 <= pc <= max_k:
                        bymask.setdefault(m, []).append((r, c))
                for m, poslist in bymask.items():
                    k = popcount(m)
                    if len(poslist) == k and 2 <= k <= max_k:
                        # eliminate m from other cells
                        for (r, c, cm) in cells:
                            if (r, c) not in poslist and (cm & m):
                                before = dom[r][c]
                                if not eliminate(r, c, m, trail):
                                    return False
                                if dom[r][c] != before:
                                    changed = True
                return True

            for r in range(N):
                if not naked_subsets_in_unit(rows[r], 3):
                    return False
            for c in range(N):
                if not naked_subsets_in_unit(cols[c], 3):
                    return False
            for g in range(N):
                if not naked_subsets_in_unit(regs[g], 3):
                    return False

            # Pointing pairs/triples generalized:
            # If in a region, all candidates for a digit are confined to one row (or col),
            # eliminate that digit from the rest of that row (or col) outside the region.
            for g in range(N):
                cells = regs[g]
                # For each digit, determine rows/cols that contain candidates
                rowmask_per_d = [0] * N  # bitmask of rows involved (N<=32 ok here)
                colmask_per_d = [0] * N
                for (r, c) in cells:
                    m = dom[r][c]
                    x = m
                    while x:
                        b = x & -x
                        d = b.bit_length() - 1
                        rowmask_per_d[d] |= (1 << r)
                        colmask_per_d[d] |= (1 << c)
                        x -= b
                for d in range(N):
                    vmask = 1 << d
                    rm = rowmask_per_d[d]
                    if rm and (rm & (rm - 1) == 0):
                        rr = lowest_bit_index(rm)
                        # eliminate from row rr outside region g
                        for cc in range(N):
                            if cell_reg[rr][cc] != g and (dom[rr][cc] & vmask):
                                before = dom[rr][cc]
                                if not eliminate(rr, cc, vmask, trail):
                                    return False
                                if dom[rr][cc] != before:
                                    changed = True
                    cm = colmask_per_d[d]
                    if cm and (cm & (cm - 1) == 0):
                        cc = lowest_bit_index(cm)
                        for rr in range(N):
                            if cell_reg[rr][cc] != g and (dom[rr][cc] & vmask):
                                before = dom[rr][cc]
                                if not eliminate(rr, cc, vmask, trail):
                                    return False
                                if dom[rr][cc] != before:
                                    changed = True

            # Contradiction check: each unit must have each digit possible somewhere
            # Fast check using OR of domains equals full_mask
            for r in range(N):
                acc = 0
                for c in range(N):
                    acc |= dom[r][c]
                if acc != full_mask:
                    return False
            for c in range(N):
                acc = 0
                for r in range(N):
                    acc |= dom[r][c]
                if acc != full_mask:
                    return False
            for g in range(N):
                acc = 0
                for (r, c) in regs[g]:
                    acc |= dom[r][c]
                if acc != full_mask:
                    return False

        return True

    # Initial propagation
    init_trail = []
    if not propagate(init_trail):
        return "No Solution"

    # Backtracking with MRV + degree, with propagation at each decision
    def is_solved():
        for r in range(N):
            for c in range(N):
                m = dom[r][c]
                if m & (m - 1):
                    return False
        return True

    def select_mrv_cell():
        best = None
        best_count = 10**9
        best_deg = -1
        for r in range(N):
            for c in range(N):
                m = dom[r][c]
                if m & (m - 1):
                    cnt = popcount(m)
                    if cnt < best_count:
                        # degree = number of unsolved peers
                        deg = 0
                        for pr, pc in peers[r][c]:
                            pm = dom[pr][pc]
                            if pm & (pm - 1):
                                deg += 1
                        best = (r, c)
                        best_count = cnt
                        best_deg = deg
                        if cnt == 2 and deg >= best_deg:
                            pass
                    elif cnt == best_count:
                        deg = 0
                        for pr, pc in peers[r][c]:
                            pm = dom[pr][pc]
                            if pm & (pm - 1):
                                deg += 1
                        if deg > best_deg:
                            best = (r, c)
                            best_deg = deg
        return best

    def order_values_lcv(r, c):
        # Least Constraining Value: count eliminations in peers
        m = dom[r][c]
        vals = []
        x = m
        while x:
            b = x & -x
            elim = 0
            for pr, pc in peers[r][c]:
                if dom[pr][pc] & b:
                    elim += 1
            vals.append((elim, b))
            x -= b
        vals.sort()
        return [b for _, b in vals]

    def backtrack():
        if is_solved():
            return True
        cell = select_mrv_cell()
        if cell is None:
            return False
        r, c = cell
        for vmask in order_values_lcv(r, c):
            trail = []
            if not assign(r, c, vmask, trail):
                continue
            if propagate(trail):
                if backtrack():
                    return True
            # undo
            for rr, cc, old in reversed(trail):
                dom[rr][cc] = old
        return False

    if not backtrack():
        return "No Solution"

    # Extract solution grid
    out = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            m = dom[r][c]
            if m == 0 or (m & (m - 1)):
                return "No Solution"
            out[r][c] = lowest_bit_index(m) + 1
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, 3, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None]], 'horizontal': {'(0, 0.5)': '>', '(0, 3.5)': '<', '(1, 0.5)': '<', '(1, 2.5)': '<', '(3, 1.5)': '<', '(3, 2.5)': '>'}, 'vertical': {'(1.5, 0)': 'v', '(2.5, 2)': 'v', '(4.5, 2)': '<'}}

from __future__ import annotations

def solve(observation):
    # Generalized Futoshiki solver with human-like propagation + MRV search.
    import re

    data = observation["data"]
    N = len(data)
    assert all(len(r) == N for r in data)

    # Parse inequalities
    horiz = {}
    vert = {}

    def parse_key(k):
        m = re.match(r'^\(\s*([0-9]+(?:\.[0-9]+)?)\s*,\s*([0-9]+(?:\.[0-9]+)?)\s*\)$', k)
        if not m:
            raise ValueError(f"Bad key: {k}")
        return float(m.group(1)), float(m.group(2))

    for k, sym in observation.get("horizontal", {}).items():
        r, c = parse_key(k)
        # stored at (row, col+0.5)
        rr = int(round(r))
        cc2 = int(round(c * 2))
        if abs(r - rr) > 1e-9 or abs(c * 2 - cc2) > 1e-9 or (cc2 % 2) != 1:
            raise ValueError(f"Bad horizontal coordinate: {k}")
        lc = (cc2 - 1) // 2
        if not (0 <= rr < N and 0 <= lc < N - 1):
            raise ValueError(f"Horizontal out of range: {k}")
        if sym not in ("<", ">"):
            raise ValueError(f"Bad horizontal symbol: {sym}")
        horiz[(rr, lc)] = sym  # between (rr,lc) and (rr,lc+1)

    for k, sym in observation.get("vertical", {}).items():
        r, c = parse_key(k)
        # stored at (row+0.5, col) with symbols '^' or 'v'
        cc = int(round(c))
        rr2 = int(round(r * 2))
        if abs(c - cc) > 1e-9 or abs(r * 2 - rr2) > 1e-9 or (rr2 % 2) != 1:
            raise ValueError(f"Bad vertical coordinate: {k}")
        tr = (rr2 - 1) // 2
        if not (0 <= tr < N - 1 and 0 <= cc < N):
            raise ValueError(f"Vertical out of range: {k}")
        if sym not in ("^", "v"):
            # Some sources use '<'/'>' mistakenly; keep strict but allow mapping if ever used.
            raise ValueError(f"Bad vertical symbol: {sym}")
        vert[(tr, cc)] = sym  # between (tr,cc) (top) and (tr+1,cc) (bottom)

    # Domain represented as bitmask of candidates 1..N (bit i => value i+1)
    ALL = (1 << N) - 1

    def bit(v):  # v in 1..N
        return 1 << (v - 1)

    def mask_to_list(m):
        res = []
        while m:
            lsb = m & -m
            i = (lsb.bit_length() - 1)
            res.append(i + 1)
            m ^= lsb
        return res

    def popcount(x):
        return x.bit_count()

    # Precompute row/col peers
    row_cells = [[(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[(r, c) for r in range(N)] for c in range(N)]

    # Inequality adjacency list: for each cell, list of (other_cell, relation)
    # relation: -1 means cell < other, +1 means cell > other
    ineq = [[[] for _ in range(N)] for __ in range(N)]

    # Horizontal constraints
    for (r, c), sym in horiz.items():
        a = (r, c)
        b = (r, c + 1)
        if sym == "<":
            ineq[r][c].append((b, -1))
            ineq[r][c + 1].append((a, +1))
        else:  # ">"
            ineq[r][c].append((b, +1))
            ineq[r][c + 1].append((a, -1))

    # Vertical constraints: symbol indicates top compared to bottom
    # '^' => top < bottom ; 'v' => top > bottom
    for (tr, c), sym in vert.items():
        top = (tr, c)
        bot = (tr + 1, c)
        if sym == "^":
            ineq[tr][c].append((bot, -1))
            ineq[tr + 1][c].append((top, +1))
        else:  # "v"
            ineq[tr][c].append((bot, +1))
            ineq[tr + 1][c].append((top, -1))

    # Initialize domains
    dom = [[ALL for _ in range(N)] for __ in range(N)]
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                dom[r][c] = bit(v)

    # Helper: compute used masks in row/col (singletons)
    def compute_used(dom_):
        row_used = [0] * N
        col_used = [0] * N
        for r in range(N):
            ru = 0
            for c in range(N):
                m = dom_[r][c]
                if m & (m - 1) == 0:
                    ru |= m
            row_used[r] = ru
        for c in range(N):
            cu = 0
            for r in range(N):
                m = dom_[r][c]
                if m & (m - 1) == 0:
                    cu |= m
            col_used[c] = cu
        return row_used, col_used

    # Tighten domain by inequality with neighbor using min/max bounds from domains
    def min_val(m):
        # smallest candidate in mask
        return (m & -m).bit_length()

    def max_val(m):
        # largest candidate in mask
        return m.bit_length()

    def prune_ineq(dom_, r, c):
        """Apply inequality constraints from (r,c) to neighbors; return True if any change, False otherwise.
           If contradiction, raise ValueError."""
        changed = False
        a = dom_[r][c]
        if a == 0:
            raise ValueError("Empty domain")
        a_min = min_val(a)
        a_max = max_val(a)
        for (rr, cc), rel in ineq[r][c]:
            b = dom_[rr][cc]
            if b == 0:
                raise ValueError("Empty domain")
            b_min = min_val(b)
            b_max = max_val(b)
            if rel == -1:
                # A < B => A <= b_max-1 and B >= a_min+1
                new_a = a
                if b_max <= 1:
                    raise ValueError("Ineq impossible")
                # cap A to <= b_max-1
                cap = b_max - 1
                if cap < N:
                    new_a &= (1 << cap) - 1
                if new_a == 0:
                    raise ValueError("Ineq pruned A empty")
                if new_a != a:
                    dom_[r][c] = new_a
                    a = new_a
                    a_min = min_val(a)
                    a_max = max_val(a)
                    changed = True

                new_b = b
                floorv = a_min + 1
                if floorv > 1:
                    new_b &= ~((1 << (floorv - 1)) - 1)
                if new_b == 0:
                    raise ValueError("Ineq pruned B empty")
                if new_b != b:
                    dom_[rr][cc] = new_b
                    changed = True
            else:
                # A > B => A >= b_min+1 and B <= a_max-1
                new_a = a
                floorv = b_min + 1
                if floorv > 1:
                    new_a &= ~((1 << (floorv - 1)) - 1)
                if new_a == 0:
                    raise ValueError("Ineq pruned A empty")
                if new_a != a:
                    dom_[r][c] = new_a
                    a = new_a
                    a_min = min_val(a)
                    a_max = max_val(a)
                    changed = True

                new_b = b
                cap = a_max - 1
                if cap < 1:
                    raise ValueError("Ineq impossible")
                if cap < N:
                    new_b &= (1 << cap) - 1
                if new_b == 0:
                    raise ValueError("Ineq pruned B empty")
                if new_b != b:
                    dom_[rr][cc] = new_b
                    changed = True
        return changed

    # Apply Latin rule: remove fixed values from peers; hidden singles
    def latin_propagate(dom_):
        changed = False
        row_used, col_used = compute_used(dom_)
        # Remove used numbers from non-singletons
        for r in range(N):
            ru = row_used[r]
            for c in range(N):
                m = dom_[r][c]
                if m & (m - 1) != 0:
                    nm = m & ~ru
                    if nm == 0:
                        raise ValueError("Row eliminated all")
                    if nm != m:
                        dom_[r][c] = nm
                        changed = True
        for c in range(N):
            cu = col_used[c]
            for r in range(N):
                m = dom_[r][c]
                if m & (m - 1) != 0:
                    nm = m & ~cu
                    if nm == 0:
                        raise ValueError("Col eliminated all")
                    if nm != m:
                        dom_[r][c] = nm
                        changed = True

        # Hidden singles in rows/cols
        for r in range(N):
            # count appearances of each value in row
            counts = [0] * N
            lastpos = [None] * N
            for c in range(N):
                m = dom_[r][c]
                mm = m
                while mm:
                    lsb = mm & -mm
                    i = lsb.bit_length() - 1
                    counts[i] += 1
                    lastpos[i] = (r, c)
                    mm ^= lsb
            for i, cnt in enumerate(counts):
                if cnt == 0:
                    raise ValueError("Row missing value")
                if cnt == 1:
                    rr, cc = lastpos[i]
                    b = 1 << i
                    if dom_[rr][cc] != b:
                        dom_[rr][cc] = b
                        changed = True

        for c in range(N):
            counts = [0] * N
            lastpos = [None] * N
            for r in range(N):
                m = dom_[r][c]
                mm = m
                while mm:
                    lsb = mm & -mm
                    i = lsb.bit_length() - 1
                    counts[i] += 1
                    lastpos[i] = (r, c)
                    mm ^= lsb
            for i, cnt in enumerate(counts):
                if cnt == 0:
                    raise ValueError("Col missing value")
                if cnt == 1:
                    rr, cc = lastpos[i]
                    b = 1 << i
                    if dom_[rr][cc] != b:
                        dom_[rr][cc] = b
                        changed = True

        return changed

    def propagate(dom_):
        # Aggressive fixpoint: Latin + inequality bounds
        # Queue-based inequality propagation for speed
        from collections import deque
        q = deque()
        inq = [[False] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                q.append((r, c))
                inq[r][c] = True

        # First run a few rounds alternating to quickly converge
        while True:
            any_change = False

            # Latin propagation (may set new singletons)
            if latin_propagate(dom_):
                any_change = True
                # enqueue all cells since row/col eliminations are broad
                for r in range(N):
                    for c in range(N):
                        if not inq[r][c]:
                            q.append((r, c))
                            inq[r][c] = True

            # Inequality propagation using queue
            while q:
                r, c = q.popleft()
                inq[r][c] = False
                before = dom_[r][c]
                if prune_ineq(dom_, r, c):
                    any_change = True
                    # if changed, neighbors and itself need reconsideration
                    for (rr, cc), _ in ineq[r][c]:
                        if not inq[rr][cc]:
                            q.append((rr, cc))
                            inq[rr][cc] = True
                    if dom_[r][c] != before:
                        # row/col effects handled next latin round
                        pass

            if not any_change:
                break

    def is_solved(dom_):
        for r in range(N):
            for c in range(N):
                m = dom_[r][c]
                if m & (m - 1):
                    return False
        return True

    def extract_grid(dom_):
        out = [[0] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                m = dom_[r][c]
                if m == 0 or (m & (m - 1)):
                    return None
                out[r][c] = (m.bit_length())  # since mask is power of two
        return out

    def select_mrv(dom_):
        best = None
        best_cnt = 10**9
        # MRV with degree tie-break (more inequalities)
        for r in range(N):
            for c in range(N):
                m = dom_[r][c]
                cnt = popcount(m)
                if cnt > 1 and cnt < best_cnt:
                    best_cnt = cnt
                    best = (r, c)
                elif cnt > 1 and cnt == best_cnt and best is not None:
                    br, bc = best
                    if len(ineq[r][c]) > len(ineq[br][bc]):
                        best = (r, c)
        return best

    def order_values_lcv(dom_, r, c):
        # Least-constraining value: estimate eliminations on row/col + inequality neighbor bounds
        m = dom_[r][c]
        vals = mask_to_list(m)
        if len(vals) <= 1:
            return vals

        # Precompute peer domains
        row_peer = [dom_[r][cc] for cc in range(N) if cc != c]
        col_peer = [dom_[rr][c] for rr in range(N) if rr != r]
        neigh = ineq[r][c]

        scored = []
        for v in vals:
            b = bit(v)
            elim = 0
            # row/col: count peers containing v
            for pm in row_peer:
                if pm & b:
                    elim += 1
            for pm in col_peer:
                if pm & b:
                    elim += 1
            # inequalities: approximate by resulting bounds effect
            for (rr, cc), rel in neigh:
                bm = dom_[rr][cc]
                if rel == -1:
                    # v < B => B must be >= v+1
                    if v < N:
                        # candidates <= v removed
                        elim += popcount(bm & ((1 << v) - 1))
                    else:
                        elim += 1000
                else:
                    # v > B => B must be <= v-1
                    if v > 1:
                        elim += popcount(bm & ~((1 << (v - 1)) - 1))
                    else:
                        elim += 1000
            scored.append((elim, v))
        scored.sort()
        return [v for _, v in scored]

    def clone_dom(dom_):
        return [row[:] for row in dom_]

    def dfs(dom_):
        try:
            propagate(dom_)
        except ValueError:
            return None
        if is_solved(dom_):
            return extract_grid(dom_)
        cell = select_mrv(dom_)
        if cell is None:
            return None
        r, c = cell
        for v in order_values_lcv(dom_, r, c):
            nd = clone_dom(dom_)
            nd[r][c] = bit(v)
            res = dfs(nd)
            if res is not None:
                return res
        return None

    # Solve
    try:
        propagate(dom)
    except ValueError:
        return "No Solution"
    if is_solved(dom):
        sol = extract_grid(dom)
        return str(sol) if sol is not None else "No Solution"

    sol = dfs(dom)
    return "No Solution" if sol is None else str(sol)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 9, None, None, None], [None, 5, None, None, None, None, 8], [None, None, None, 8, None, None, 10], [None, None, None, 9, None, None, None], [7, None, None, 9, None, None, None], [3, None, None, None, None, 3, None], [None, None, None, 4, None, None, None]]}

from collections import deque

# Solver for Kuromasu (a.k.a. Kurodoko) with numbered visibility clues.
# State encoding per cell:
#   -1: black
#    0: unknown
#    1: white (non-clue)
#   >1: clue number (always white)

DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def solve(observation):
    data = observation["data"]
    n = len(data)
    if any(len(row) != n for row in data):
        return "No Solution"

    grid = [[0] * n for _ in range(n)]
    clue_pos = []
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if isinstance(v, int):
                grid[r][c] = v
                clue_pos.append((r, c))

    # Quick sanity checks for clue bounds
    for r, c in clue_pos:
        v = grid[r][c]
        maxvis = 1 + r + (n - 1 - r) + c + (n - 1 - c)  # no blocks
        if v < 1 or v > maxvis:
            return "No Solution"

    # Precompute rays for each clue: lists outward from clue (excluding itself)
    rays = {}
    for r, c in clue_pos:
        up = [(rr, c) for rr in range(r - 1, -1, -1)]
        dn = [(rr, c) for rr in range(r + 1, n)]
        lf = [(r, cc) for cc in range(c - 1, -1, -1)]
        rt = [(r, cc) for cc in range(c + 1, n)]
        rays[(r, c)] = (up, dn, lf, rt)

    def inb(r, c):
        return 0 <= r < n and 0 <= c < n

    def is_black(v):
        return v == -1

    def is_white(v):
        return v == 1 or v > 1

    def is_clue(v):
        return v > 1

    # Trail for backtracking
    trail = []

    def set_cell(r, c, val):
        """Assign cell to -1 (black) or 1 (white). Clues are immutable."""
        cur = grid[r][c]
        if is_clue(cur):
            return cur != -1 and val != -1  # clue cannot be black, can be 'white' implicitly
        if cur == val:
            return True
        if cur != 0:
            return False
        grid[r][c] = val
        trail.append((r, c))
        return True

    def undo(to_len):
        while len(trail) > to_len:
            r, c = trail.pop()
            grid[r][c] = 0

    # --- Constraint helpers for a clue ---

    def compute_visibility_counts(rc):
        """Return (min_vis, max_vis, forced_white_set, forced_black_set) for clue at rc.
        min_vis: currently guaranteed visible white cells (including clue itself),
        max_vis: maximum possible visible cells if all unknown become white and no blocking blacks appear.
        Additionally returns sets of cells that must be WHITE/BLACK by tight visibility bounds.
        """
        r, c = rc
        target = grid[r][c]
        # min counts definite visible whites until blocked by known black; unknown do not contribute to min
        # max counts all cells until first known black (excluded), treating unknown as potentially white
        min_vis = 1
        max_vis = 1
        forced_white = set()
        forced_black = set()
        # For each direction, scan until border, stop at known black for both min/max.
        # For min, only count definite whites; unknown doesn't count but doesn't stop.
        # For max, count all non-black (white or unknown) until known black.
        for line in rays[(r, c)]:
            # max:
            for (rr, cc) in line:
                if grid[rr][cc] == -1:
                    break
                max_vis += 1
            # min:
            for (rr, cc) in line:
                v = grid[rr][cc]
                if v == -1:
                    break
                if is_white(v):
                    min_vis += 1
                else:
                    # unknown: doesn't add but doesn't stop
                    pass

        # Tighten by local implications:
        # If target == min_vis, then all further potentially visible unknowns in each direction must be black
        # until a known black (since any white would increase visibility).
        if target == min_vis:
            for line in rays[(r, c)]:
                for (rr, cc) in line:
                    if grid[rr][cc] == -1:
                        break
                    if grid[rr][cc] == 0:
                        forced_black.add((rr, cc))
                    # if white continues, still okay (already counted) but unknowns must be black
        # If target == max_vis, then all potentially visible unknowns must be white (can't block, and must be visible)
        if target == max_vis:
            for line in rays[(r, c)]:
                for (rr, cc) in line:
                    if grid[rr][cc] == -1:
                        break
                    if grid[rr][cc] == 0:
                        forced_white.add((rr, cc))

        return min_vis, max_vis, forced_white, forced_black

    def enforce_no_adjacent_blacks():
        """If a cell is black, its orthogonal neighbors must be white."""
        forced = []
        for r in range(n):
            for c in range(n):
                if grid[r][c] == -1:
                    for dr, dc in DIRS:
                        rr, cc = r + dr, c + dc
                        if inb(rr, cc) and grid[rr][cc] == 0:
                            forced.append((rr, cc, 1))
        return forced

    def enforce_clue_immediate_rules():
        """Apply immediate bounds-based rules around each clue."""
        forced = []
        for rc in clue_pos:
            target = grid[rc[0]][rc[1]]
            min_vis, max_vis, fw, fb = compute_visibility_counts(rc)
            if not (min_vis <= target <= max_vis):
                return None  # contradiction
            for (rr, cc) in fw:
                forced.append((rr, cc, 1))
            for (rr, cc) in fb:
                forced.append((rr, cc, -1))
        return forced

    def apply_forced(forced_list):
        """Apply a list of forced assignments; return False if contradiction."""
        for r, c, v in forced_list:
            if not set_cell(r, c, v):
                return False
        return True

    def propagate():
        """Aggressive logical propagation loop."""
        q = deque([("all", None)])
        seen_tag = set()
        while q:
            tag, payload = q.popleft()
            if (tag, payload) in seen_tag:
                continue
            seen_tag.add((tag, payload))

            # 1) No adjacent blacks
            forced = enforce_no_adjacent_blacks()
            if forced:
                if not apply_forced(forced):
                    return False
                q.append(("all", None))

            # 2) Clue visibility bounds / equalities
            forced = enforce_clue_immediate_rules()
            if forced is None:
                return False
            if forced:
                if not apply_forced(forced):
                    return False
                q.append(("all", None))

            # 3) Additional strong rule: if a clue needs k more visible cells, we can bound where blacks may appear.
            # Implement per-direction "must-include prefix" and "must-exclude beyond cutoff" reasoning.
            if not propagate_clue_prefix_suffix():
                return False

            # 4) Connectivity pruning (white must be connected): do early check on impossibility.
            if not connectivity_feasible():
                return False

        return True

    def line_until_black(line):
        """Return cells in line until first known black (excluded)."""
        out = []
        for rc in line:
            if grid[rc[0]][rc[1]] == -1:
                break
            out.append(rc)
        return out

    def propagate_clue_prefix_suffix():
        """
        Human-like deduction:
        For each clue, the visible cells form a cross with contiguous segments in each direction
        until the first black. That implies in each direction, the visible unknown/white must be a prefix
        of the ray (can't have a black after a white in the visible segment, because black stops).
        Use target to force some cells to white (must be within visible budget) or to black (beyond max cutoff).
        """
        forced = []
        for r, c in clue_pos:
            target = grid[r][c]

            segments = []
            fixed_visible = 1  # clue itself
            # For each direction, consider cells up to first known black (candidates for visibility)
            # But within that, if there is a known white, it must be visible, so it contributes and also means
            # any earlier cells (closer to clue) cannot be black (since it would block that known white).
            for line in rays[(r, c)]:
                cand = line_until_black(line)
                # Determine mandatory prefix length due to known whites in cand:
                mand_prefix = 0
                for idx, (rr, cc) in enumerate(cand):
                    v = grid[rr][cc]
                    if is_white(v):
                        mand_prefix = max(mand_prefix, idx + 1)
                # Also count currently guaranteed visible whites: all known whites in cand are visible
                for (rr, cc) in cand:
                    if is_white(grid[rr][cc]):
                        fixed_visible += 1
                segments.append((cand, mand_prefix))

            if fixed_visible > target:
                return False

            # Minimum visible includes mand_prefix cells in each direction as white (to not block known whites)
            # But those prefix cells might currently be unknown; force them to white.
            for cand, mand_prefix in segments:
                for idx in range(mand_prefix):
                    rr, cc = cand[idx]
                    if grid[rr][cc] == 0:
                        forced.append((rr, cc, 1))

            # Now compute maximum additional visible possible:
            # each direction contributes up to len(cand) cells (all could be white and visible)
            max_possible = 1 + sum(len(cand) for cand, _ in segments)
            if target > max_possible:
                return False

            # If target equals minimum possible after forcing prefixes? We can compute a stronger min:
            min_possible = 1
            # In each direction, at least mand_prefix cells must be visible and white.
            for cand, mand_prefix in segments:
                min_possible += mand_prefix
            if target < min_possible:
                return False

            # If we already know we need exactly X visible in total, then for any direction,
            # cells beyond a global cutoff might be forced black when the remaining budget is tight.
            # Use a simple bound:
            # remaining_visibility_budget = target - 1
            # For any cell at distance d in a direction to be visible, all closer cells must be non-black.
            # If the sum of minimum required in other directions already uses up budget, we can cap each direction.
            rem = target - 1
            # For each direction i, compute min in others:
            mins = [mand for _, mand in segments]
            lens = [len(cand) for cand, _ in segments]
            for i, (cand, mand) in enumerate(segments):
                min_others = sum(mins) - mand
                max_here = rem - min_others
                if max_here < mand:
                    return False
                # Cells beyond max_here in this direction can never be visible; to prevent them from becoming visible,
                # we can force a black at position max_here (the blocker) OR force those cells black if already unblocked.
                # Safe rule: if max_here == mand, then the (mand+1)th cell (index mand) must be black (if exists and not clue/white).
                if max_here == mand and mand < len(cand):
                    rr, cc = cand[mand]
                    if grid[rr][cc] == 0:
                        forced.append((rr, cc, -1))

            # If target equals max_possible, then all candidate cells must be visible => all candidates white.
            if target == max_possible:
                for cand, _ in segments:
                    for rr, cc in cand:
                        if grid[rr][cc] == 0:
                            forced.append((rr, cc, 1))

        if forced:
            if not apply_forced(forced):
                return False
        return True

    def connectivity_feasible():
        """
        White cells (including clues and forced whites) must be connected in final.
        Early pruning:
          - If there are 2+ white components already separated by black cells such that they cannot be connected
            because all possible connecting unknowns would require adjacent blacks? We'll do a simpler necessary check:
          - Unknowns are considered potentially white; blacks are walls. Ensure all current whites are in same
            connected component when traversing through non-black cells (white+unknown). If not, impossible.
        """
        # Collect all current definite whites (including clues)
        whites = [(r, c) for r in range(n) for c in range(n) if is_white(grid[r][c])]
        if not whites:
            return True
        start = whites[0]
        dq = deque([start])
        seen = {start}
        while dq:
            r, c = dq.popleft()
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if inb(rr, cc) and (rr, cc) not in seen and grid[rr][cc] != -1:
                    seen.add((rr, cc))
                    dq.append((rr, cc))
        for rc in whites[1:]:
            if rc not in seen:
                return False
        return True

    def final_check():
        # Check all clues exact visibility and all whites connected and no adjacent blacks.
        for r in range(n):
            for c in range(n):
                if grid[r][c] == -1:
                    for dr, dc in DIRS:
                        rr, cc = r + dr, c + dc
                        if inb(rr, cc) and grid[rr][cc] == -1:
                            return False

        # Clues exact
        for r, c in clue_pos:
            target = grid[r][c]
            count = 1
            for line in rays[(r, c)]:
                for rr, cc in line:
                    if grid[rr][cc] == -1:
                        break
                    if is_white(grid[rr][cc]):
                        count += 1
                    else:
                        # unknown shouldn't exist in final_check, but treat as not white
                        pass
            if count != target:
                return False

        # All non-black are white in final solution; ensure connected.
        # If any unknown remain, not final.
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        # connectivity among all white (non-black) cells
        whites = [(r, c) for r in range(n) for c in range(n) if grid[r][c] != -1]
        if not whites:
            return False
        start = whites[0]
        dq = deque([start])
        seen = {start}
        while dq:
            r, c = dq.popleft()
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if inb(rr, cc) and (rr, cc) not in seen and grid[rr][cc] != -1:
                    seen.add((rr, cc))
                    dq.append((rr, cc))
        return len(seen) == len(whites)

    def choose_branch_cell():
        """
        Heuristic:
        Pick an unknown cell that appears in the most clue rays (highest constraint impact),
        preferring those adjacent to a black possibility (near clues).
        """
        impact = [[0] * n for _ in range(n)]
        for r, c in clue_pos:
            for line in rays[(r, c)]:
                for rr, cc in line_until_black(line):
                    if grid[rr][cc] == 0:
                        impact[rr][cc] += 1
        best = None
        best_key = (-1, -1)
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    adj_black = 0
                    for dr, dc in DIRS:
                        rr, cc = r + dr, c + dc
                        if inb(rr, cc) and grid[rr][cc] == -1:
                            adj_black = 1
                            break
                    key = (impact[r][c], adj_black)
                    if key > best_key:
                        best_key = key
                        best = (r, c)
        return best

    def search():
        if not propagate():
            return False
        if final_check():
            return True
        cell = choose_branch_cell()
        if cell is None:
            return False
        r, c = cell

        # Try black first only if not violating clue immutability and adjacency constraints quickly
        for val in (-1, 1):
            tl = len(trail)
            if set_cell(r, c, val):
                if search():
                    return True
            undo(tl)
        return False

    # Seed: clues are white; no need to set.
    if not propagate():
        return "No Solution"
    if not search():
        return "No Solution"

    # Build answer grid
    ans = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if is_clue(grid[r][c]):
                ans[r][c] = grid[r][c]
            elif grid[r][c] == -1:
                ans[r][c] = "B"
            else:
                ans[r][c] = None
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[1, 2, 5, 7, 3, 2, 1, 9, 4, 7], [2, 1, 7, 3, 5, 9, 8, 10, 6, 4], [4, 3, 4, 2, 4, 7, 1, 5, 9, 1], [4, 5, 9, 5, 2, 5, 3, 5, 7, 5], [3, 9, 7, 6, 7, 10, 4, 2, 4, 1], [10, 6, 1, 7, 4, 9, 2, 7, 10, 5], [7, 3, 3, 9, 3, 8, 10, 1, 1, 2], [10, 8, 6, 5, 1, 4, 5, 3, 2, 10], [8, 7, 2, 4, 8, 2, 9, 2, 3, 10], [5, 2, 10, 2, 9, 6, 4, 8, 4, 2]]}
from collections import defaultdict, deque

# Hitori-like solver:
# - Decide cells black/white
# - For each number group in a row/col, at most one white among duplicates
# - No orthogonal adjacent blacks
# - All whites connected


def solve(observation):
    g = observation["data"]
    n = len(g)
    if n == 0 or any(len(r) != n for r in g):
        return "No Solution"

    # --- Indexing helpers ---
    def idx(r, c): return r * n + c
    def rc(i): return divmod(i, n)

    N = n * n
    neigh = [[] for _ in range(N)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r: neigh[i].append(idx(r - 1, c))
            if r + 1 < n: neigh[i].append(idx(r + 1, c))
            if c: neigh[i].append(idx(r, c - 1))
            if c + 1 < n: neigh[i].append(idx(r, c + 1))

    # --- Build duplicate groups (constraints) ---
    # For each row and value with k occurrences => among those cells, <=1 can be white => all pairs cannot both be white.
    # Same for columns.
    row_positions = [defaultdict(list) for _ in range(n)]
    col_positions = [defaultdict(list) for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = g[r][c]
            row_positions[r][v].append(idx(r, c))
            col_positions[c][v].append(idx(r, c))

    # Pairwise "not both white" edges for duplicates
    not_both_white = [set() for _ in range(N)]  # adjacency list of i: set of j such that (i white) implies (j black) if needed
    dup_groups = []  # store groups with size>=2 for stronger deductions
    for r in range(n):
        for v, cells in row_positions[r].items():
            if len(cells) >= 2:
                dup_groups.append(cells)
                for i in range(len(cells)):
                    a = cells[i]
                    for j in range(i + 1, len(cells)):
                        b = cells[j]
                        not_both_white[a].add(b)
                        not_both_white[b].add(a)
    for c in range(n):
        for v, cells in col_positions[c].items():
            if len(cells) >= 2:
                dup_groups.append(cells)
                for i in range(len(cells)):
                    a = cells[i]
                    for j in range(i + 1, len(cells)):
                        b = cells[j]
                        not_both_white[a].add(b)
                        not_both_white[b].add(a)

    # Domain: -1 unassigned, 0 white, 1 black
    state = [-1] * N

    # Quick unsat: if any cell forced both black and white
    # We'll maintain implications via propagation queue.

    # --- Connectivity checker for whites with pruning ---
    # Treat unassigned as potentially white for "can-still-connect" checks.
    # Must ensure:
    # 1) all decided whites are in one component considering (white or unassigned) passable
    # 2) no decided black adjacency rule broken
    # Final check: all whites connected.

    def connectivity_ok(relaxed=True):
        # relaxed=True: treat unassigned as passable
        # relaxed=False: only whites passable
        passable = [False] * N
        any_white = False
        start = -1
        for i in range(N):
            if state[i] == 1:
                passable[i] = False
            elif state[i] == 0:
                passable[i] = True
                any_white = True
                if start < 0:
                    start = i
            else:
                passable[i] = relaxed  # unassigned
                if relaxed and start < 0:
                    start = i

        if relaxed:
            # If everything is black (shouldn't happen because blacks can't touch everywhere maybe), still ok until final
            if start < 0:
                return True
            # All forced whites must be reachable within passable graph
            q = deque([start])
            seen = [False] * N
            seen[start] = True
            while q:
                x = q.popleft()
                for y in neigh[x]:
                    if passable[y] and not seen[y]:
                        seen[y] = True
                        q.append(y)
            for i in range(N):
                if state[i] == 0 and not seen[i]:
                    return False
            return True
        else:
            # final: all whites connected; if no white, invalid puzzle (typically at least one white)
            if not any_white:
                return False
            q = deque([start])
            seen = [False] * N
            seen[start] = True
            while q:
                x = q.popleft()
                for y in neigh[x]:
                    if state[y] == 0 and not seen[y]:
                        seen[y] = True
                        q.append(y)
            for i in range(N):
                if state[i] == 0 and not seen[i]:
                    return False
            return True

    # --- Propagation machinery with trail (for backtracking) ---
    # We'll implement deterministic deductions:
    # A) Adjacent black rule: if cell is black -> neighbors cannot be black => must be white
    # B) Duplicate rule pairwise: if i white, all j in not_both_white[i] must be black
    # C) Group rule: for each duplicate group, if k-1 are black => remaining must be white; if any white => all others black
    # D) Local cornering connectivity heuristic: if an unassigned cell is the only connector ("articulation-like") for forced whites in relaxed graph, force it white.
    #    We'll approximate via checking if setting it black disconnects forced whites (only for high-impact candidates).

    groups = [tuple(cells) for cells in dup_groups]

    # Precompute groups containing each cell
    groups_of = [[] for _ in range(N)]
    for gi, cells in enumerate(groups):
        for i in cells:
            groups_of[i].append(gi)

    def assign(i, val, q, trail):
        # val: 0 white, 1 black
        cur = state[i]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        state[i] = val
        trail.append(i)
        q.append(i)
        return True

    def propagate(trail):
        q = deque()
        # Seed q with all recently assigned cells in trail? caller will pass.
        # Here we assume caller already pushed into q via assign; but for convenience:
        q.extend(trail[-1:])  # harmless if empty or single; caller often adds one
        # We'll maintain a set of "touched groups" to reevaluate
        touched_groups = set()

        while q:
            i = q.popleft()
            v = state[i]
            if v == 1:
                # Black => all neighbors white
                for nb in neigh[i]:
                    if not assign(nb, 0, q, trail):
                        return False
            else:
                # White => all duplicates (pairwise) must be black
                for j in not_both_white[i]:
                    if not assign(j, 1, q, trail):
                        return False

            # No adjacent blacks violation immediate check when assign black later; but also check now quickly
            if v == 1:
                for nb in neigh[i]:
                    if state[nb] == 1:
                        return False

            # Track groups affected
            for gi in groups_of[i]:
                touched_groups.add(gi)

            # Evaluate group rules opportunistically
            while touched_groups:
                gi = touched_groups.pop()
                cells = groups[gi]
                whites = 0
                last_un = -1
                uncnt = 0
                blackcnt = 0
                for c in cells:
                    s = state[c]
                    if s == 0:
                        whites += 1
                    elif s == 1:
                        blackcnt += 1
                    else:
                        uncnt += 1
                        last_un = c
                # At most one white in group:
                if whites >= 2:
                    return False
                if whites == 1:
                    # all others must be black
                    for c in cells:
                        if state[c] == -1:
                            if not assign(c, 1, q, trail):
                                return False
                else:
                    # no white yet; if all but one are black, remaining must be white
                    if uncnt == 1 and blackcnt == len(cells) - 1:
                        if not assign(last_un, 0, q, trail):
                            return False

        # Connectivity relaxed must hold
        if not connectivity_ok(relaxed=True):
            return False

        return True

    def full_propagate(trail):
        # Run propagation starting from nothing new by scanning for immediate contradictions / strong deductions
        # We'll implement a loop:
        # 1) Apply group "k-1 black -> last white" and "has white -> others black" already covered in propagate when any cell assigned.
        # 2) Additional connectivity-critical forced whites:
        #    For a subset of unassigned cells, test if making it black would disconnect existing forced whites in relaxed graph; if so, force white.
        changed = True
        while changed:
            changed = False

            # Basic adjacency black checks already handled; also check current adjacency blacks quickly
            for i in range(N):
                if state[i] == 1:
                    for nb in neigh[i]:
                        if state[nb] == 1:
                            return False

            # Connectivity-forcing heuristic (cheap):
            # If there are forced whites, ensure they can reach each other through passable (not black).
            if not connectivity_ok(relaxed=True):
                return False

            # Find a few candidate unassigned cells near forced whites to test as connectors
            forced_whites = [i for i in range(N) if state[i] == 0]
            if len(forced_whites) >= 2:
                # Build reachability in current relaxed graph
                passable = [state[i] != 1 for i in range(N)]
                start = forced_whites[0]
                q = deque([start])
                seen = [False] * N
                seen[start] = True
                while q:
                    x = q.popleft()
                    for y in neigh[x]:
                        if passable[y] and not seen[y]:
                            seen[y] = True
                            q.append(y)
                if any(not seen[w] for w in forced_whites):
                    return False

                # Candidate connectors: unassigned cells that are on boundary between seen/unseen or adjacent to forced whites
                # (kept small for speed)
                cand = set()
                for w in forced_whites:
                    for nb in neigh[w]:
                        if state[nb] == -1:
                            cand.add(nb)
                # Also add unassigned cells adjacent to both a seen and another seen? Keep limited.
                if len(cand) < 25:
                    for i in range(N):
                        if state[i] == -1:
                            sc = 0
                            for nb in neigh[i]:
                                if seen[nb] and state[nb] != 1:
                                    sc += 1
                            if sc >= 2:
                                cand.add(i)
                                if len(cand) >= 25:
                                    break

                # Test each candidate: if setting black would break relaxed connectivity among forced whites, force it white
                for c in list(cand):
                    if state[c] != -1:
                        continue
                    # Temporarily mark black and test reachability of forced whites in relaxed graph
                    state[c] = 1
                    ok = connectivity_ok(relaxed=True)
                    state[c] = -1
                    if not ok:
                        # must be white
                        local_trail = []
                        if not assign(c, 0, deque(), local_trail):
                            # restore
                            for x in reversed(local_trail):
                                state[x] = -1
                            return False
                        # Now propagate those assignments properly
                        if not propagate(local_trail):
                            for x in reversed(local_trail):
                                state[x] = -1
                            return False
                        trail.extend(local_trail)
                        changed = True

        return True

    # --- Decision heuristic ---
    def score_cell(i):
        # Prefer cells in large duplicate constraints (more impact), and with many neighbors
        return (len(not_both_white[i]) * 4 + len(groups_of[i]) * 3 + len(neigh[i]))

    def choose_unassigned():
        best = -1
        best_sc = -1
        for i in range(N):
            if state[i] == -1:
                sc = score_cell(i)
                if sc > best_sc:
                    best_sc = sc
                    best = i
        return best

    def is_valid_final():
        # All assigned
        if any(s == -1 for s in state):
            return False
        # No adjacent blacks
        for i in range(N):
            if state[i] == 1:
                for nb in neigh[i]:
                    if state[nb] == 1:
                        return False
        # Duplicates: in each row/col, no repeated whites
        for r in range(n):
            seen = set()
            for c in range(n):
                i = idx(r, c)
                if state[i] == 0:
                    v = g[r][c]
                    if v in seen:
                        return False
                    seen.add(v)
        for c in range(n):
            seen = set()
            for r in range(n):
                i = idx(r, c)
                if state[i] == 0:
                    v = g[r][c]
                    if v in seen:
                        return False
                    seen.add(v)
        # White connectivity
        return connectivity_ok(relaxed=False)

    def backtrack():
        trail = []
        if not full_propagate(trail):
            for x in reversed(trail):
                state[x] = -1
            return False

        if all(s != -1 for s in state):
            ok = is_valid_final()
            for x in reversed(trail):
                state[x] = -1
            return ok

        i = choose_unassigned()
        if i < 0:
            ok = is_valid_final()
            for x in reversed(trail):
                state[x] = -1
            return ok

        # Branch order: try WHITE first if it kills many duplicates (forces blacks), else BLACK first.
        # Also if any neighbor is black, i cannot be black.
        can_black = all(state[nb] != 1 for nb in neigh[i])
        white_first = (len(not_both_white[i]) >= 2) or (not can_black)

        def try_val(val):
            local_trail = []
            q = deque()
            if not assign(i, val, q, local_trail):
                for x in reversed(local_trail):
                    state[x] = -1
                return False
            # propagate from this decision
            if not propagate(local_trail):
                for x in reversed(local_trail):
                    state[x] = -1
                return False
            if backtrack():
                return True
            for x in reversed(local_trail):
                state[x] = -1
            return False

        ok = False
        if white_first:
            ok = try_val(0) or (can_black and try_val(1))
        else:
            ok = (can_black and try_val(1)) or try_val(0)

        for x in reversed(trail):
            state[x] = -1
        return ok

    # Solve by searching, but keep found solution
    solution = None

    def search_capture():
        nonlocal solution
        trail = []
        if not full_propagate(trail):
            for x in reversed(trail):
                state[x] = -1
            return False
        if all(s != -1 for s in state):
            if is_valid_final():
                solution = state[:]
                for x in reversed(trail):
                    state[x] = -1
                return True
            for x in reversed(trail):
                state[x] = -1
            return False

        i = choose_unassigned()
        can_black = all(state[nb] != 1 for nb in neigh[i])
        white_first = (len(not_both_white[i]) >= 2) or (not can_black)

        def try_val(val):
            local_trail = []
            q = deque()
            if not assign(i, val, q, local_trail):
                for x in reversed(local_trail):
                    state[x] = -1
                return False
            if not propagate(local_trail):
                for x in reversed(local_trail):
                    state[x] = -1
                return False
            if search_capture():
                return True
            for x in reversed(local_trail):
                state[x] = -1
            return False

        found = False
        if white_first:
            found = try_val(0) or (can_black and try_val(1))
        else:
            found = (can_black and try_val(1)) or try_val(0)

        for x in reversed(trail):
            state[x] = -1
        return found

    if not search_capture() or solution is None:
        return "No Solution"

    mask = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if solution[idx(r, c)] == 1:
                mask[r][c] = 'B'
            else:
                mask[r][c] = None
    return str(mask)


