OBSERVATION = {'data': [[None, 'B', None, None, None, None, 'W', None], [None, 'B', None, None, None, None, 'W', None], [None, None, 'B', None, None, 'B', None, None], [None, None, None, None, None, None, None, None], [None, None, None, 'W', 'B', None, None, None], ['W', None, None, None, None, None, None, 'W'], [None, None, None, 'B', 'W', None, None, None], [None, 'W', None, None, None, None, 'B', None]], 'horizontal': {'(5.0,1.5)': '=', '(0.0,4.5)': '='}, 'vertical': {'(3.5,2.0)': '=', '(5.5,5.0)': '=', '(0.5,4.0)': 'x', '(2.5,6.0)': 'x'}}
from collections import deque

# Solver for Binary Puzzle with adjacency (= / x) constraints.
# Human-like deduction:
# 1) Local 3-in-a-row prevention (forces opposite in patterns XX_ / _XX / X_X).
# 2) Line balancing (max N/2 of each color; if reached then rest forced).
# 3) Adjacency constraints propagate equality/inequality.
# 4) Pair-completion: if two empties remain in a line, fill by balance.
# 5) Limited search with MRV + forward-checking, after exhaustive propagation.
# Note: Uniqueness of rows/cols is not specified in this variant; not enforced.

B, W = 1, 0  # internal bits
UNK = -1

def parse_observation(obs):
    data = obs["data"]
    n = len(data)
    m = len(data[0]) if n else 0
    if n != m:
        raise ValueError("Expected square grid in this puzzle family.")
    grid = [UNK] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                grid[r*n + c] = B
            elif v == 'W':
                grid[r*n + c] = W
            elif v is None:
                grid[r*n + c] = UNK
            else:
                raise ValueError("Cell must be 'B','W',or None.")

    # adjacency constraints: store for each cell list of (neighbor, relation) where relation = 0 means same, 1 means different
    adj = [[] for _ in range(n*n)]

    def add_edge(a, b, rel):
        adj[a].append((b, rel))
        adj[b].append((a, rel))

    # horizontal keys are "(row, col+0.5)"
    for k, sym in obs.get("horizontal", {}).items():
        t = k.strip()[1:-1]
        rs, cs = t.split(",")
        r = int(float(rs))
        cf = float(cs)
        c_left = int(cf - 0.5)
        c_right = c_left + 1
        if not (0 <= r < n and 0 <= c_left < n-1):
            raise ValueError("Bad horizontal constraint coordinate.")
        a = r*n + c_left
        b = r*n + c_right
        rel = 0 if sym == '=' else 1
        add_edge(a, b, rel)

    # vertical keys are "(row+0.5, col)"
    for k, sym in obs.get("vertical", {}).items():
        t = k.strip()[1:-1]
        rs, cs = t.split(",")
        rf = float(rs)
        c = int(float(cs))
        r_up = int(rf - 0.5)
        r_dn = r_up + 1
        if not (0 <= c < n and 0 <= r_up < n-1):
            raise ValueError("Bad vertical constraint coordinate.")
        a = r_up*n + c
        b = r_dn*n + c
        rel = 0 if sym == '=' else 1
        add_edge(a, b, rel)

    return n, grid, adj

def bit_to_char(x):
    return 'B' if x == B else 'W'

def idx(n, r, c):
    return r*n + c

def neighbors_in_line(n, r, c, is_row):
    if is_row:
        return [idx(n, r, j) for j in range(n)]
    return [idx(n, i, c) for i in range(n)]

def apply_assign(n, grid, adj, i, val, queue):
    """Assign grid[i]=val if consistent. Push affected indices to queue for propagation."""
    cur = grid[i]
    if cur == val:
        return True
    if cur != UNK and cur != val:
        return False
    grid[i] = val
    queue.append(i)
    # adjacency immediate implications can be queued as well by checking neighbors later
    return True

def check_line_basic(n, line_vals):
    """Return False if violates max counts or 3 consecutive rule."""
    half = n // 2
    cntB = sum(1 for v in line_vals if v == B)
    cntW = sum(1 for v in line_vals if v == W)
    if cntB > half or cntW > half:
        return False
    # 3 consecutive
    for i in range(n-2):
        a, b, c = line_vals[i], line_vals[i+1], line_vals[i+2]
        if a != UNK and a == b == c:
            return False
    return True

def propagate_local_patterns(n, grid, line_idxs, queue):
    """Apply XX_/_XX/X_X patterns in a line; return False if contradiction."""
    changed = False
    for i in range(n-2):
        a, b, c = line_idxs[i], line_idxs[i+1], line_idxs[i+2]
        va, vb, vc = grid[a], grid[b], grid[c]
        # XX_
        if va != UNK and va == vb and vc == UNK:
            if not apply_assign(n, grid, None, c, va ^ 1, queue):
                return False, changed
            changed = True
        # _XX
        if vb != UNK and vb == vc and va == UNK:
            if not apply_assign(n, grid, None, a, vb ^ 1, queue):
                return False, changed
            changed = True
        # X_X
        if va != UNK and vc != UNK and va == vc and vb == UNK:
            if not apply_assign(n, grid, None, b, va ^ 1, queue):
                return False, changed
            changed = True
    return True, changed

def propagate_balance(n, grid, line_idxs, queue):
    """If count of a color reached half, force remaining to opposite. Return False if contradiction."""
    half = n // 2
    vals = [grid[i] for i in line_idxs]
    cntB = sum(1 for v in vals if v == B)
    cntW = sum(1 for v in vals if v == W)
    if cntB > half or cntW > half:
        return False, False
    changed = False
    if cntB == half:
        for i in line_idxs:
            if grid[i] == UNK:
                if not apply_assign(n, grid, None, i, W, queue):
                    return False, changed
                changed = True
    if cntW == half:
        for i in line_idxs:
            if grid[i] == UNK:
                if not apply_assign(n, grid, None, i, B, queue):
                    return False, changed
                changed = True
    return True, changed

def propagate_two_empties(n, grid, line_idxs, queue):
    """If only two UNKs remain, fill by balance (forced)."""
    half = n // 2
    vals = [grid[i] for i in line_idxs]
    unks = [line_idxs[k] for k, v in enumerate(vals) if v == UNK]
    if len(unks) != 2:
        return True, False
    cntB = sum(1 for v in vals if v == B)
    cntW = sum(1 for v in vals if v == W)
    needB = half - cntB
    needW = half - cntW
    if needB < 0 or needW < 0 or needB + needW != 2:
        return False, False
    changed = False
    if needB == 0:
        for u in unks:
            if not apply_assign(n, grid, None, u, W, queue):
                return False, changed
            changed = True
    elif needW == 0:
        for u in unks:
            if not apply_assign(n, grid, None, u, B, queue):
                return False, changed
            changed = True
    # If needB==1 and needW==1, not forced.
    return True, changed

def propagate_adjacency(n, grid, adj, i, queue):
    """From assigned i, propagate to neighbors."""
    vi = grid[i]
    if vi == UNK:
        return True, False
    changed = False
    for j, rel in adj[i]:
        vj = grid[j]
        if vj == UNK:
            if not apply_assign(n, grid, None, j, vi ^ rel, queue):
                return False, changed
            changed = True
        else:
            if (vi ^ vj) != rel:
                return False, changed
    return True, changed

def full_propagate(n, grid, adj):
    """Exhaustive propagation until fixpoint. Return (ok, grid)."""
    queue = deque([i for i, v in enumerate(grid) if v != UNK])
    inq = [False]*(n*n)
    for i in queue:
        inq[i] = True

    def enqueue(x):
        if not inq[x]:
            inq[x] = True
            queue.append(x)

    # For convenience, wrap apply_assign to also enqueue dependencies
    def assign(i, val):
        cur = grid[i]
        if cur == val:
            return True
        if cur != UNK and cur != val:
            return False
        grid[i] = val
        enqueue(i)
        # also enqueue row/col for line checks by enqueuing representative cells:
        r, c = divmod(i, n)
        # enqueue all cells in row/col lightly by enqueueing just i; line scans are global below
        return True

    # Monkey-patch local helpers to use assign
    def apply_assign_local(i, val):
        return assign(i, val)

    changed_any = True
    while changed_any:
        changed_any = False

        # Process adjacency queue
        while queue:
            i = queue.popleft()
            inq[i] = False
            vi = grid[i]
            if vi == UNK:
                continue
            for j, rel in adj[i]:
                vj = grid[j]
                if vj == UNK:
                    if not apply_assign_local(j, vi ^ rel):
                        return False
                    changed_any = True
                else:
                    if (vi ^ vj) != rel:
                        return False

        # Line-based deductions: scan all rows and cols (n<=14 typical; still cheap)
        for r in range(n):
            line = [grid[idx(n, r, c)] for c in range(n)]
            if not check_line_basic(n, line):
                return False
            # patterns
            line_idxs = [idx(n, r, c) for c in range(n)]
            ok, ch = propagate_local_patterns_scan(n, grid, line_idxs, apply_assign_local)
            if not ok:
                return False
            if ch: changed_any = True
            ok, ch = propagate_balance_scan(n, grid, line_idxs, apply_assign_local)
            if not ok:
                return False
            if ch: changed_any = True
            ok, ch = propagate_two_empties_scan(n, grid, line_idxs, apply_assign_local)
            if not ok:
                return False
            if ch: changed_any = True

        for c in range(n):
            line = [grid[idx(n, r, c)] for r in range(n)]
            if not check_line_basic(n, line):
                return False
            line_idxs = [idx(n, r, c) for r in range(n)]
            ok, ch = propagate_local_patterns_scan(n, grid, line_idxs, apply_assign_local)
            if not ok:
                return False
            if ch: changed_any = True
            ok, ch = propagate_balance_scan(n, grid, line_idxs, apply_assign_local)
            if not ok:
                return False
            if ch: changed_any = True
            ok, ch = propagate_two_empties_scan(n, grid, line_idxs, apply_assign_local)
            if not ok:
                return False
            if ch: changed_any = True

        # If something changed, adjacency will be processed next loop via enqueue in assign.

    return True

def propagate_local_patterns_scan(n, grid, line_idxs, assign):
    changed = False
    for i in range(n-2):
        a, b, c = line_idxs[i], line_idxs[i+1], line_idxs[i+2]
        va, vb, vc = grid[a], grid[b], grid[c]
        if va != UNK and va == vb and vc == UNK:
            if not assign(c, va ^ 1): return False, changed
            changed = True
        if vb != UNK and vb == vc and va == UNK:
            if not assign(a, vb ^ 1): return False, changed
            changed = True
        if va != UNK and vc != UNK and va == vc and vb == UNK:
            if not assign(b, va ^ 1): return False, changed
            changed = True
    return True, changed

def propagate_balance_scan(n, grid, line_idxs, assign):
    half = n // 2
    vals = [grid[i] for i in line_idxs]
    cntB = sum(1 for v in vals if v == B)
    cntW = sum(1 for v in vals if v == W)
    if cntB > half or cntW > half:
        return False, False
    changed = False
    if cntB == half:
        for i in line_idxs:
            if grid[i] == UNK:
                if not assign(i, W): return False, changed
                changed = True
    if cntW == half:
        for i in line_idxs:
            if grid[i] == UNK:
                if not assign(i, B): return False, changed
                changed = True
    return True, changed

def propagate_two_empties_scan(n, grid, line_idxs, assign):
    half = n // 2
    vals = [grid[i] for i in line_idxs]
    unks = [line_idxs[k] for k, v in enumerate(vals) if v == UNK]
    if len(unks) != 2:
        return True, False
    cntB = sum(1 for v in vals if v == B)
    cntW = sum(1 for v in vals if v == W)
    needB = half - cntB
    needW = half - cntW
    if needB < 0 or needW < 0 or needB + needW != 2:
        return False, False
    changed = False
    if needB == 0:
        for u in unks:
            if not assign(u, W): return False, changed
            changed = True
    elif needW == 0:
        for u in unks:
            if not assign(u, B): return False, changed
            changed = True
    return True, changed

def is_solved(n, grid):
    return all(v != UNK for v in grid)

def line_valid_partial(n, grid, line_idxs):
    vals = [grid[i] for i in line_idxs]
    return check_line_basic(n, vals)

def choose_var_mrv(n, grid, adj):
    # Simple MRV: prefer cells constrained by many assigned neighbors and near completing row/col
    best = None
    best_score = -1
    for i, v in enumerate(grid):
        if v != UNK:
            continue
        r, c = divmod(i, n)
        row = [grid[idx(n, r, j)] for j in range(n)]
        col = [grid[idx(n, j, c)] for j in range(n)]
        score = 0
        score += sum(1 for (j, _) in adj[i] if grid[j] != UNK) * 3
        score += (n - row.count(UNK)) + (n - col.count(UNK))
        # prefer near balance limits
        half = n // 2
        score += max(0, (sum(1 for x in row if x == B) - (half-1))) * 2
        score += max(0, (sum(1 for x in row if x == W) - (half-1))) * 2
        score += max(0, (sum(1 for x in col if x == B) - (half-1))) * 2
        score += max(0, (sum(1 for x in col if x == W) - (half-1))) * 2
        if score > best_score:
            best_score = score
            best = i
    return best

def try_value_order(n, grid, i):
    # Value ordering: try value that best satisfies immediate patterns and balances
    r, c = divmod(i, n)
    row_idxs = [idx(n, r, j) for j in range(n)]
    col_idxs = [idx(n, j, c) for j in range(n)]
    half = n // 2
    row = [grid[k] for k in row_idxs]
    col = [grid[k] for k in col_idxs]
    cntB = sum(1 for v in row if v == B) + sum(1 for v in col if v == B)
    cntW = sum(1 for v in row if v == W) + sum(1 for v in col if v == W)
    # heuristic: choose rarer color among row+col combined
    if cntB > cntW:
        return (W, B)
    if cntW > cntB:
        return (B, W)
    return (B, W)

def dfs(n, grid, adj, depth=0, max_depth=10_000):
    if depth > max_depth:
        return None
    ok = full_propagate(n, grid, adj)
    if not ok:
        return None
    if is_solved(n, grid):
        return grid

    i = choose_var_mrv(n, grid, adj)
    if i is None:
        return None

    # quick domain pruning: ensure both values locally possible via line check
    r, c = divmod(i, n)
    row_idxs = [idx(n, r, j) for j in range(n)]
    col_idxs = [idx(n, j, c) for j in range(n)]

    for val in try_value_order(n, grid, i):
        g2 = grid[:]
        g2[i] = val

        # immediate adjacency consistency check
        consistent = True
        for j, rel in adj[i]:
            vj = g2[j]
            if vj != UNK and ((val ^ vj) != rel):
                consistent = False
                break
        if not consistent:
            continue

        # immediate line checks
        if not line_valid_partial(n, g2, row_idxs):
            continue
        if not line_valid_partial(n, g2, col_idxs):
            continue

        res = dfs(n, g2, adj, depth+1, max_depth)
        if res is not None:
            return res
    return None

def solve(observation):
    n, grid, adj = parse_observation(observation)
    if n % 2 != 0:
        return "No Solution"

    res = dfs(n, grid, adj)
    if res is None:
        return "No Solution"

    out = [[bit_to_char(res[idx(n, r, c)]) for c in range(n)] for r in range(n)]
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

