from collections import deque, defaultdict
import time

# Solver for the puzzle described:
# - Each region has a clue in exactly one cell (or none). Clue = number of black cells in the region.
# - Black cells cannot touch orthogonally.
# - Any uninterrupted straight white segment (row/col) cannot pass through more than 2 regions.
#   (i.e., for any maximal contiguous run of white cells along a row/col, the set of regions appearing in that run has size <= 2)
# - All white cells are orthogonally connected.
#
# Output: NxN 2D list using 'B' for black and None for white.

UNKNOWN = 0
BLACK = 1
WHITE = 2

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])
    if n != m:
        return "No Solution"

    N = n

    # Build region cells
    reg_cells = defaultdict(list)
    clue_of_reg = {}
    for r in range(N):
        for c in range(N):
            rid = region[r][c]
            reg_cells[rid].append(r * N + c)
            if data[r][c] is not None:
                # assume at most one clue per region; if multiple, they must agree
                v = int(data[r][c])
                if rid in clue_of_reg and clue_of_reg[rid] != v:
                    return "No Solution"
                clue_of_reg[rid] = v

    # If a region has no clue, treat it as unconstrained count? Usually all regions have clue in this puzzle,
    # but support None: unknown count -> any value 0..size
    reg_ids = sorted(reg_cells.keys())
    reg_sizes = {rid: len(reg_cells[rid]) for rid in reg_ids}

    # Precompute adjacency between cells (orthogonal)
    neighbors = [[] for _ in range(N * N)]
    for r in range(N):
        for c in range(N):
            i = r * N + c
            if r > 0: neighbors[i].append((r - 1) * N + c)
            if r < N - 1: neighbors[i].append((r + 1) * N + c)
            if c > 0: neighbors[i].append(r * N + (c - 1))
            if c < N - 1: neighbors[i].append(r * N + (c + 1))

    # Row/col segment constraints helper:
    # For each cell, row index and col index.
    row_of = [i // N for i in range(N * N)]
    col_of = [i % N for i in range(N * N)]
    reg_of = [region[i // N][i % N] for i in range(N * N)]

    # Prepare lists of cells per row/col
    row_cells = [[r * N + c for c in range(N)] for r in range(N)]
    col_cells = [[r * N + c for r in range(N)] for c in range(N)]

    # Domains: each cell is UNKNOWN/BLACK/WHITE
    grid = [UNKNOWN] * (N * N)

    # Region counts tracking
    reg_black = {rid: 0 for rid in reg_ids}
    reg_unk = {rid: reg_sizes[rid] for rid in reg_ids}

    # Frontier bookkeeping for propagation queue
    q = deque()

    def set_cell(i, val, reason=None):
        """Assign cell i to BLACK/WHITE. Return False on contradiction."""
        cur = grid[i]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        grid[i] = val
        rid = reg_of[i]
        if val == BLACK:
            reg_black[rid] += 1
        reg_unk[rid] -= 1
        q.append(i)
        return True

    # Initial: apply 0/size clues immediately if possible later via propagation

    # Propagation rules:
    # (A) Region quota: if clue known, enforce min/max and force remaining.
    # (B) Black adjacency: if cell black then all orthogonal neighbors white.
    # (C) Segment region-limit (<=2 regions per maximal white segment): detect violations and forced blacks.
    # (D) White connectivity: maintain that whites can still be connected (no isolated forced-white islands impossible).

    def region_propagate(rid):
        clue = clue_of_reg.get(rid, None)
        if clue is None:
            return True
        b = reg_black[rid]
        u = reg_unk[rid]
        # too many black or too few possible
        if b > clue:
            return False
        if b + u < clue:
            return False
        # force all remaining in region to WHITE if already met clue
        if b == clue:
            for i in reg_cells[rid]:
                if grid[i] == UNKNOWN:
                    if not set_cell(i, WHITE):
                        return False
        # force all remaining to BLACK if must fill
        if b + u == clue:
            for i in reg_cells[rid]:
                if grid[i] == UNKNOWN:
                    if not set_cell(i, BLACK):
                        return False
        return True

    def black_adjacency_propagate(i):
        if grid[i] != BLACK:
            return True
        for nb in neighbors[i]:
            if grid[nb] == BLACK:
                return False
            if grid[nb] == UNKNOWN:
                if not set_cell(nb, WHITE):
                    return False
        return True

    def analyze_line_for_segments(line_cells):
        """
        Enforce: any maximal contiguous WHITE segment uses <=2 distinct regions.
        We'll reason using partial assignment:
          - Consider any maximal segment of cells that are not BLACK (UNKNOWN or WHITE).
            This segment could become a white segment unless split by future BLACK.
          - If within a current confirmed-white segment (maximal run of WHITE cells), it must already satisfy <=2 regions.
          - For a not-black segment, if it currently contains >=3 distinct regions among cells that are forced WHITE,
            contradiction (because no splits possible inside forced whites).
          - Also, if within a not-black segment, there are already >=3 distinct regions present among all cells
            that are forced WHITE or could be WHITE (UNKNOWN), it's not immediately contradictory because we can place blacks
            to split. But if there exists a forced-white contiguous run (no UNKNOWN) spanning 3 regions => contradiction.
          - Forced move: If a maximal not-black segment contains 3+ distinct regions overall and there is exactly one boundary cell
            in the segment whose blackness can reduce region-count? This is complex. We'll implement a strong, cheap local rule:
              For any triple of consecutive region changes along the line, the middle border cell must be BLACK to prevent a white segment
              spanning 3 regions without a black split.
            Specifically, scan along line:
              Let seq of regions per position. A white segment spanning 3 regions exists if there is an index interval [a..b] with
              no blacks and containing >=3 distinct regions. To prevent that without knowing blacks, we can force a black at certain "cut"
              points when an interval of forced-WHITE already crosses 3 regions.
        """
        # First, check any maximal WHITE run (only WHITE, no UNKNOWN/BLACK) obeys <=2 regions
        k = len(line_cells)
        s = 0
        while s < k:
            if grid[line_cells[s]] != WHITE:
                s += 1
                continue
            e = s
            regs = set()
            while e < k and grid[line_cells[e]] == WHITE:
                regs.add(reg_of[line_cells[e]])
                e += 1
            if len(regs) > 2:
                return False
            s = e

        # Second, check forced-white with unknowns inside? Not needed.
        # Third, forced blacks at "mandatory cut" positions:
        # If there is a run of cells that are WHITE or UNKNOWN (no BLACK),
        # and within that run, there is a sub-run of consecutive cells that are forced WHITE spanning 3 regions,
        # then contradiction already caught. Otherwise, we can sometimes force a BLACK at a specific UNKNOWN cell that is the only possible cut.
        # Implement: For each maximal not-BLACK run, compute the sequence of region IDs across positions.
        # Consider minimal interval covering three distinct regions. If inside that interval all cells are forced WHITE except some UNKNOWN cut candidates,
        # and only one UNKNOWN position exists where placing BLACK would split into <=2 regions segments, force it.
        idx = 0
        while idx < k:
            if grid[line_cells[idx]] == BLACK:
                idx += 1
                continue
            j = idx
            while j < k and grid[line_cells[j]] != BLACK:
                j += 1
            # segment [idx, j)
            seg = line_cells[idx:j]
            # If length small skip
            if len(seg) >= 3:
                # Precompute region ids
                regs = [reg_of[x] for x in seg]
                # Identify positions where region changes
                # We attempt to find forced cut when there are >=3 distinct regions and there is only one UNKNOWN among "border" positions.
                distinct = set(regs)
                if len(distinct) >= 3:
                    # Find minimal window where 3 distinct regions appear, then see if there's exactly one UNKNOWN in that window at a region boundary.
                    # Sliding window
                    left = 0
                    counts = defaultdict(int)
                    have = 0
                    best_windows = []
                    for right in range(len(seg)):
                        rr = regs[right]
                        counts[rr] += 1
                        if counts[rr] == 1:
                            have += 1
                        while have >= 3 and left <= right:
                            best_windows.append((left, right))
                            rl = regs[left]
                            counts[rl] -= 1
                            if counts[rl] == 0:
                                have -= 1
                            left += 1
                    # For each best window, attempt force
                    for (a, b) in best_windows:
                        # If all are forced WHITE already, contradiction handled earlier (white run). But window may include UNKNOWNs.
                        # Determine candidate cut positions within [a,b] that if BLACK, would split the segment.
                        # A black in the interior splits; but we want to ensure each resulting white segment uses <=2 regions.
                        # We'll consider placing a single black somewhere; if only one position can fix for all possibilities, force.
                        # We will consider only UNKNOWN positions.
                        unk_pos = [t for t in range(a, b + 1) if grid[seg[t]] == UNKNOWN]
                        if not unk_pos:
                            # all WHITE but that would have been a WHITE run (no BLACK) -> already checked, but run might include UNKNOWN outside.
                            # Still, this is a forced WHITE interval across 3 regions: since no UNKNOWN, it's all WHITE => contradiction.
                            return False
                        # Evaluate each unknown as a cut candidate
                        feasible = []
                        for t in unk_pos:
                            # Suppose seg[t]=BLACK; check left part forced-white cannot exceed 2 regions if it becomes all WHITE.
                            # Conservative: ensure that in [a,t-1], forced WHITE already spans <=2 regions, and in [t+1,b], same.
                            # Also ensure adjacency (BLACK) doesn't conflict with immediate neighbors already BLACK.
                            cell = seg[t]
                            # neighbor conflicts in line handled by black adjacency elsewhere; still quick check
                            if (t > 0 and grid[seg[t - 1]] == BLACK) or (t + 1 < len(seg) and grid[seg[t + 1]] == BLACK):
                                continue
                            left_regs = set(reg_of[seg[x]] for x in range(a, t) if grid[seg[x]] == WHITE)
                            right_regs = set(reg_of[seg[x]] for x in range(t + 1, b + 1) if grid[seg[x]] == WHITE)
                            if len(left_regs) <= 2 and len(right_regs) <= 2:
                                feasible.append(t)
                        if len(feasible) == 0:
                            # No way to cut this 3-region window with a single black among unknowns.
                            # It might still be possible with multiple blacks elsewhere, so don't contradict.
                            continue
                        if len(feasible) == 1:
                            t = feasible[0]
                            cell = seg[t]
                            # Force black only if leaving it white would necessarily create a forced-white run across 3 regions.
                            # We'll trigger if all other cells in [a,b] are already WHITE (so window almost fixed).
                            all_other_white = True
                            for x in range(a, b + 1):
                                if x == t:
                                    continue
                                if grid[seg[x]] != WHITE:
                                    all_other_white = False
                                    break
                            if all_other_white:
                                if not set_cell(cell, BLACK):
                                    return False
            idx = j
        return True

    def segment_propagate():
        for r in range(N):
            if not analyze_line_for_segments(row_cells[r]):
                return False
        for c in range(N):
            if not analyze_line_for_segments(col_cells[c]):
                return False
        return True

    def connectivity_possible():
        # All cells not BLACK must be able to form a connected white component after assigning UNKNOWN to WHITE as needed.
        # Necessary condition: forced WHITE cells must lie in one connected component within graph of non-BLACK cells.
        forced = [i for i, v in enumerate(grid) if v == WHITE]
        if not forced:
            return True
        allowed = [v != BLACK for v in grid]
        start = forced[0]
        dq = deque([start])
        seen = {start}
        while dq:
            x = dq.popleft()
            for nb in neighbors[x]:
                if allowed[nb] and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        for i in forced:
            if i not in seen:
                return False
        return True

    def propagate():
        # Seed queue with all assigned cells
        while q:
            i = q.popleft()
            # black adjacency
            if not black_adjacency_propagate(i):
                return False
            # region quota for its region
            if not region_propagate(reg_of[i]):
                return False
        # global propagations
        # region propagate for all (handles 0-clue regions etc)
        for rid in reg_ids:
            if not region_propagate(rid):
                return False
        if not segment_propagate():
            return False
        if not connectivity_possible():
            return False
        return True

    # Initialize: apply any immediate region constraints by pushing nothing, then calling propagate handles.
    if not propagate():
        return "No Solution"

    # Decision heuristic:
    # - Prefer regions with known clue and tight remaining (few unknowns).
    # - Otherwise choose cell most constrained: unknown cell adjacent to black, etc.
    def pick_var():
        best = None
        best_key = None
        # region-based: pick an unknown cell in a region with known clue that is not yet fixed.
        for rid in reg_ids:
            clue = clue_of_reg.get(rid, None)
            if clue is None:
                continue
            u = reg_unk[rid]
            if u == 0:
                continue
            # score by u small and by "need" min(clue-b, b+u-clue)
            b = reg_black[rid]
            need = min(max(clue - b, 0), max(b + u - clue, 0))
            key = (u, need)
            if best_key is None or key < best_key:
                # choose an unknown cell in this region with additional constraints
                cand = None
                cand_key = None
                for i in reg_cells[rid]:
                    if grid[i] != UNKNOWN:
                        continue
                    # prefer cells that if black cause many forced whites
                    adj_unknown = sum(1 for nb in neighbors[i] if grid[nb] == UNKNOWN)
                    adj_black = sum(1 for nb in neighbors[i] if grid[nb] == BLACK)
                    # also consider line boundaries (segment rule)
                    lk = (adj_black, -adj_unknown)
                    if cand_key is None or lk > cand_key:
                        cand_key = lk
                        cand = i
                if cand is not None:
                    best = cand
                    best_key = key
        if best is not None:
            return best
        # fallback: any unknown with max adjacent blacks
        for i, v in enumerate(grid):
            if v != UNKNOWN:
                continue
            adj_black = sum(1 for nb in neighbors[i] if grid[nb] == BLACK)
            adj_unknown = sum(1 for nb in neighbors[i] if grid[nb] == UNKNOWN)
            key = (-adj_black, adj_unknown)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def snapshot():
        return (grid[:], dict(reg_black), dict(reg_unk), deque(q))

    def restore(snap):
        g, rb, ru, qq = snap
        grid[:] = g
        reg_black.clear(); reg_black.update(rb)
        reg_unk.clear(); reg_unk.update(ru)
        q.clear(); q.extend(qq)

    # Additional pruning: if a clue region is 0, forbid blacks in it early; if clue equals size, force all blacks.
    for rid, clue in clue_of_reg.items():
        if clue == 0:
            for i in reg_cells[rid]:
                if grid[i] == UNKNOWN and not set_cell(i, WHITE):
                    return "No Solution"
        elif clue == reg_sizes[rid]:
            for i in reg_cells[rid]:
                if grid[i] == UNKNOWN and not set_cell(i, BLACK):
                    return "No Solution"
    if not propagate():
        return "No Solution"

    t0 = time.time()
    TIME_LIMIT = 2.5  # keep conservative in generic environment

    def dfs():
        if time.time() - t0 > TIME_LIMIT:
            return False
        var = pick_var()
        if var is None:
            # all assigned; verify final segment constraints and connectivity with all unknown none (shouldn't happen)
            if not segment_propagate():
                return False
            if not connectivity_possible():
                return False
            # verify region exact
            for rid in reg_ids:
                clue = clue_of_reg.get(rid, None)
                if clue is not None and reg_black[rid] != clue:
                    return False
            return True

        # try WHITE then BLACK? Prefer WHITE to maintain connectivity and avoid adjacency
        # but use region clue preference: if region needs blacks, try BLACK first
        rid = reg_of[var]
        clue = clue_of_reg.get(rid, None)
        order = [WHITE, BLACK]
        if clue is not None:
            b = reg_black[rid]
            u = reg_unk[rid]
            need_black = clue - b
            if need_black > 0 and need_black == u:
                order = [BLACK, WHITE]
            elif need_black > 0:
                order = [BLACK, WHITE]  # generally try to satisfy quota earlier
            else:
                order = [WHITE, BLACK]

        for val in order:
            snap = snapshot()
            if set_cell(var, val) and propagate():
                if dfs():
                    return True
            restore(snap)
        return False

    ok = dfs()
    if not ok:
        return "No Solution"

    out = [[None for _ in range(N)] for __ in range(N)]
    for r in range(N):
        for c in range(N):
            v = grid[r * N + c]
            out[r][c] = 'B' if v == BLACK else None
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 0, None, 0, None], [2, None, None, None, None, None], [None, None, 2, None, None, 2], [2, 2, None, 2, 1, None], [0, None, None, None, None, 0], [None, None, 0, None, 1, None]]}
# Slant (a.k.a. "Gokigen Naname") solver:
# - Each cell must be '/' or '\'
# - Each numbered dot requires exactly that many incident segments
# - No closed loops allowed in the induced graph of dot-to-dot segments
#
# Approach:
# 1) Represent each cell as a boolean variable: 0 => '/', 1 => '\'.
# 2) For each dot, maintain remaining required degree with fast bounds checks.
# 3) Enforce "no loops" incrementally using a DSU (Union-Find) over dots:
#    Adding an edge between two dots that are already connected would form a loop => forbidden.
# 4) Aggressive propagation:
#    - Dot degree bounds pruning (min/max possible from unassigned incident cells)
#    - Forced assignments when a dot must take all or none of its remaining incident possibilities
#    - Unit-like reasoning on a cell when one orientation would immediately violate degree bounds or create a loop
# 5) DFS with MRV heuristic and propagation. This is not blind brute-force; it is propagation-driven.

from collections import deque

def solve(observation):
    data = observation["data"]
    H = len(data)
    W = len(data[0])
    if H != W:
        return "No Solution"
    N = H - 1  # cells N x N, dots (N+1)x(N+1)
    D = (N + 1) * (N + 1)
    C = N * N

    def dot_id(r, c):
        return r * (N + 1) + c

    def cell_id(r, c):
        return r * N + c

    # For each cell, endpoints for each orientation
    # '/' connects (r+1,c) - (r,c+1)
    # '\' connects (r,c) - (r+1,c+1)
    cell_endpoints = [None] * C
    for r in range(N):
        for c in range(N):
            a0 = dot_id(r + 1, c)
            b0 = dot_id(r, c + 1)
            a1 = dot_id(r, c)
            b1 = dot_id(r + 1, c + 1)
            cell_endpoints[cell_id(r, c)] = ((a0, b0), (a1, b1))

    # Incident cells for each dot: list of (cell, orient) where orient is 0 or 1 and that orient uses the dot
    dot_inc = [[] for _ in range(D)]
    for cid in range(C):
        for o in (0, 1):
            a, b = cell_endpoints[cid][o]
            dot_inc[a].append((cid, o))
            dot_inc[b].append((cid, o))

    # Precompute for each cell and orientation: which dots it increments (two endpoints)
    cell_dots = [None] * C
    for cid in range(C):
        cell_dots[cid] = (cell_endpoints[cid][0], cell_endpoints[cid][1])

    # Clues array
    clue = [None] * D
    for r in range(N + 1):
        for c in range(N + 1):
            v = data[r][c]
            if v is not None:
                if not (0 <= v <= 4):
                    return "No Solution"
                clue[dot_id(r, c)] = int(v)

    # Each cell variable: -1 unassigned, else 0 '/' or 1 '\'
    assign = [-1] * C

    # For each dot: current degree contributed by assigned cells
    deg = [0] * D

    # For each dot: count of still-possible incident contributions among unassigned cells (upper bound)
    # We'll compute dynamically when needed using dot_inc, but keep a cached value updated via delta.
    # To do that efficiently, track for each dot:
    #   unassigned_count: number of incident (cell,orient) pairs that are still "available" given cell unassigned
    # However for a cell, exactly one of its two orientations will be chosen, so a dot incident count isn't simply pair-based.
    # We'll instead track per dot:
    #   unassigned_cells_incident: list of incident cell ids (unique) and how dot participates in each cell (one of the two orientations)
    # But a dot may participate in a cell in 0, 1, or 2 orientations? In slant, a dot in a cell corner participates in exactly one orientation:
    # - Top-left and bottom-right => '\' only
    # - Top-right and bottom-left => '/' only
    # So exactly one orientation per incident cell. Great: dot incidence per cell is deterministic.
    dot_cells = [[] for _ in range(D)]  # list of (cid, required_orient) where that orient contributes to dot
    for d in range(D):
        # Each dot_inc entry is (cid, orient) but for a given cid, there should be only one orient for this dot
        # in this puzzle structure.
        seen = {}
        for cid, o in dot_inc[d]:
            if cid in seen and seen[cid] != o:
                # Should not happen in this puzzle type
                pass
            seen[cid] = o
        dot_cells[d] = [(cid, o) for cid, o in seen.items()]

    # Remaining possible contributions for each dot = number of incident unassigned cells whose dot-orient is still possible.
    # Since each cell will pick exactly one orient, for dot d and incident cell cid, contribution occurs iff assign[cid]==o.
    # If cell unassigned => could still contribute (1 possible). If assigned and equals o => contributes (already in deg).
    # If assigned and not equals o => cannot contribute.
    def dot_max_possible_add(d):
        cnt = 0
        for cid, o in dot_cells[d]:
            a = assign[cid]
            if a == -1:
                cnt += 1
            elif a == o:
                # already counted in deg, not "add"
                pass
        return cnt

    def dot_min_possible_add(d):
        # Minimum additional contribution from unassigned cells is 0 because each incident cell could choose the other orientation.
        return 0

    # Union-Find with rollback to enforce no loops.
    parent = list(range(D))
    size = [1] * D
    # track number of edges in each component for cycle detection:
    # cycle forms when adding edge connects nodes already connected.
    # We'll just forbid union if find(a)==find(b) at time of adding.
    uf_stack = []

    def uf_find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def uf_union(a, b):
        ra = uf_find(a)
        rb = uf_find(b)
        if ra == rb:
            return False  # would create loop
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        # rollback record: (rb, parent_rb, size_ra)
        uf_stack.append((rb, parent[rb], size[ra]))
        parent[rb] = ra
        size[ra] += size[rb]
        return True

    def uf_mark():
        return len(uf_stack)

    def uf_rollback(mark):
        while len(uf_stack) > mark:
            rb, old_parent_rb, old_size_ra = uf_stack.pop()
            ra = parent[rb]
            parent[rb] = old_parent_rb
            size[ra] = old_size_ra

    # Assignment stack for rollback of deg and assign
    stack = []

    def mark():
        return (len(stack), uf_mark())

    def rollback(m):
        st_len, uf_m = m
        uf_rollback(uf_m)
        while len(stack) > st_len:
            typ, idx, prev = stack.pop()
            if typ == "assign":
                assign[idx] = prev
            elif typ == "deg":
                deg[idx] = prev

    def set_deg(d, v):
        if deg[d] != v:
            stack.append(("deg", d, deg[d]))
            deg[d] = v

    def set_assign(cid, v):
        if assign[cid] != v:
            stack.append(("assign", cid, assign[cid]))
            assign[cid] = v

    def dot_feasible(d):
        c = clue[d]
        if c is None:
            return True
        if deg[d] > c:
            return False
        # maximum achievable = current deg + number of incident unassigned cells
        mx = deg[d] + dot_max_possible_add(d)
        if mx < c:
            return False
        return True

    def all_dots_feasible_for_cell(cid):
        # local check only for endpoints dots after assigning cell; used in propagation
        return True

    def apply_cell(cid, v):
        # returns False if contradiction (degree violation or loop)
        if assign[cid] != -1:
            return assign[cid] == v
        a, b = cell_endpoints[cid][v]
        # loop check
        if not uf_union(a, b):
            return False
        set_assign(cid, v)
        # increment degrees on endpoints
        set_deg(a, deg[a] + 1)
        set_deg(b, deg[b] + 1)
        # feasibility for endpoints and also their neighbors might be affected; caller propagation will handle.
        if not dot_feasible(a) or not dot_feasible(b):
            return False
        return True

    def cell_possible(cid, v):
        if assign[cid] != -1:
            return assign[cid] == v
        a, b = cell_endpoints[cid][v]
        if uf_find(a) == uf_find(b):
            return False
        # check degrees quickly
        for d in (a, b):
            c = clue[d]
            if c is not None:
                if deg[d] + 1 > c:
                    return False
        # also check that other dots won't become impossible due to reducing flexibility? hard globally; handled by propagation.
        return True

    # Propagation queue: dots whose feasibility/forced moves might change, and cells for unit checks
    def propagate():
        qd = deque()
        qc = deque()

        # seed with all dots with clues and all unassigned cells
        for d in range(D):
            if clue[d] is not None:
                qd.append(d)
        for cid in range(C):
            if assign[cid] == -1:
                qc.append(cid)

        in_qd = [False] * D
        in_qc = [False] * C
        for d in qd: in_qd[d] = True
        for cid in qc: in_qc[cid] = True

        def push_dot(d):
            if 0 <= d < D and not in_qd[d]:
                in_qd[d] = True
                qd.append(d)

        def push_cell(cid):
            if 0 <= cid < C and assign[cid] == -1 and not in_qc[cid]:
                in_qc[cid] = True
                qc.append(cid)

        while qd or qc:
            while qd:
                d = qd.popleft()
                in_qd[d] = False
                if not dot_feasible(d):
                    return False
                c = clue[d]
                if c is None:
                    continue
                # Let rem = c - deg[d]. Each incident unassigned cell can contribute at most 1.
                rem = c - deg[d]
                # Collect incident unassigned cells and whether they could contribute.
                undec = []
                for cid, o in dot_cells[d]:
                    if assign[cid] == -1:
                        undec.append((cid, o))
                if rem < 0 or rem > len(undec):
                    return False
                if not undec:
                    continue
                # If rem == 0, then all incident unassigned cells must choose the OTHER orientation (not o).
                if rem == 0:
                    for cid, o in undec:
                        other = 1 - o
                        if not cell_possible(cid, other):
                            return False
                        if assign[cid] == -1:
                            m = mark()
                            if not apply_cell(cid, other):
                                rollback(m)
                                return False
                            # affected: endpoints of assigned edge, plus dots adjacent to this cell via both orientations not needed; just endpoints
                            ea, eb = cell_endpoints[cid][other]
                            push_dot(ea); push_dot(eb)
                            # all 4 dots around that cell may have bounds tightened; push them
                            r = cid // N
                            ccol = cid % N
                            for dr in (0, 1):
                                for dc in (0, 1):
                                    push_dot(dot_id(r+dr, ccol+dc))
                            # neighboring cells around those dots could be forced
                            for cid2, _ in dot_cells[ea]:
                                push_cell(cid2)
                            for cid2, _ in dot_cells[eb]:
                                push_cell(cid2)
                # If rem == len(undec), then all those cells must contribute, i.e., choose orientation o.
                elif rem == len(undec):
                    for cid, o in undec:
                        if not cell_possible(cid, o):
                            return False
                        if assign[cid] == -1:
                            m = mark()
                            if not apply_cell(cid, o):
                                rollback(m)
                                return False
                            ea, eb = cell_endpoints[cid][o]
                            push_dot(ea); push_dot(eb)
                            r = cid // N
                            ccol = cid % N
                            for dr in (0, 1):
                                for dc in (0, 1):
                                    push_dot(dot_id(r+dr, ccol+dc))
                            for cid2, _ in dot_cells[ea]:
                                push_cell(cid2)
                            for cid2, _ in dot_cells[eb]:
                                push_cell(cid2)

            while qc:
                cid = qc.popleft()
                in_qc[cid] = False
                if assign[cid] != -1:
                    continue
                p0 = cell_possible(cid, 0)
                p1 = cell_possible(cid, 1)
                if not p0 and not p1:
                    return False
                if p0 and not p1:
                    m = mark()
                    if not apply_cell(cid, 0):
                        rollback(m)
                        return False
                    a, b = cell_endpoints[cid][0]
                    for d in (a, b):
                        push_dot(d)
                        for cid2, _ in dot_cells[d]:
                            push_cell(cid2)
                elif p1 and not p0:
                    m = mark()
                    if not apply_cell(cid, 1):
                        rollback(m)
                        return False
                    a, b = cell_endpoints[cid][1]
                    for d in (a, b):
                        push_dot(d)
                        for cid2, _ in dot_cells[d]:
                            push_cell(cid2)
                else:
                    # both possible; do a quick lookahead: if choosing one violates immediate dot feasibility bounds, eliminate it
                    # (cheap test: after adding edge, endpoints must still be feasible with remaining max)
                    # We'll test by temporary apply+rollback.
                    for v in (0, 1):
                        if not (p0 if v == 0 else p1):
                            continue
                        mm = mark()
                        ok = apply_cell(cid, v)
                        if ok:
                            # also ensure all dots with clues remain feasible (only endpoints and their neighboring dots are impacted)
                            # We'll check the four corner dots.
                            r = cid // N
                            ccol = cid % N
                            for dr in (0, 1):
                                for dc in (0, 1):
                                    d = dot_id(r+dr, ccol+dc)
                                    if not dot_feasible(d):
                                        ok = False
                                        break
                        rollback(mm)
                        if not ok:
                            # force the other
                            other = 1 - v
                            if not cell_possible(cid, other):
                                return False
                            mm2 = mark()
                            if not apply_cell(cid, other):
                                rollback(mm2)
                                return False
                            a, b = cell_endpoints[cid][other]
                            for d in (a, b):
                                push_dot(d)
                                for cid2, _ in dot_cells[d]:
                                    push_cell(cid2)
                            break
        return True

    # Initialize feasibility
    if not propagate():
        return "No Solution"

    # MRV selection: choose unassigned cell with smallest number of possible values, break ties by impact.
    def choose_cell():
        best = -1
        best_dom = 3
        best_score = -1
        for cid in range(C):
            if assign[cid] != -1:
                continue
            p0 = cell_possible(cid, 0)
            p1 = cell_possible(cid, 1)
            dom = (1 if p0 else 0) + (1 if p1 else 0)
            if dom == 0:
                return cid, []
            # impact score: endpoints have clues or tightness
            score = 0
            for v in (0, 1):
                if (p0 if v == 0 else p1):
                    a, b = cell_endpoints[cid][v]
                    for d in (a, b):
                        if clue[d] is not None:
                            score += 2
            if dom < best_dom or (dom == best_dom and score > best_score):
                best = cid
                best_dom = dom
                best_score = score
                if dom == 1 and score >= 4:
                    break
        if best == -1:
            return -1, []
        opts = []
        if cell_possible(best, 0): opts.append(0)
        if cell_possible(best, 1): opts.append(1)
        # value ordering: try the option that satisfies tighter dots first (least slack)
        def option_key(v):
            a, b = cell_endpoints[best][v]
            key = 0
            for d in (a, b):
                if clue[d] is not None:
                    slack = (clue[d] - deg[d])
                    key += slack
                else:
                    key += 10
            return key
        opts.sort(key=option_key)
        return best, opts

    def solved():
        # all cells assigned and all clues exactly met
        for cid in range(C):
            if assign[cid] == -1:
                return False
        for d in range(D):
            if clue[d] is not None and deg[d] != clue[d]:
                return False
        return True

    def dfs():
        if solved():
            return True
        cid, opts = choose_cell()
        if cid == -1:
            return False
        if not opts:
            return False
        for v in opts:
            m = mark()
            if apply_cell(cid, v) and propagate():
                if dfs():
                    return True
            rollback(m)
        return False

    if not dfs():
        return "No Solution"

    # Build output grid of '/' and '\'
    out = []
    for r in range(N):
        row = []
        for c in range(N):
            v = assign[cell_id(r, c)]
            row.append('/' if v == 0 else '\\')
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 5, None, None, None, 13, None, None, None], [None, None, None, None, None, None, None, None, None, 4], [None, 11, None, None, None, None, None, None, None, None], [None, None, 8, None, 11, None, 14, 6, None, None], [None, 11, None, None, None, None, None, None, 8, None], [None, 14, None, None, None, None, None, None, 17, None], [None, None, 8, 4, None, 12, None, 6, None, None], [None, None, None, None, None, None, None, None, 8, None], [11, None, None, None, None, None, None, None, None, None], [None, None, None, 2, None, None, None, 3, None, None]]}
from collections import deque
from functools import lru_cache

# Solver for "Sightline / Kuromasu-like with connectivity and no-adjacent-black" puzzle:
# - Some cells are clue numbers (always white).
# - Other cells are either white or black.
# - Each clue counts visible white cells orthogonally including itself until border/black.
# - All whites connected orthogonally.
# - Black cells cannot be orthogonally adjacent.

W, B, U = 1, 0, -1  # internal states: white, black, unknown


def solve(observation):
    data = observation["data"]
    n = len(data)
    if any(len(row) != n for row in data):
        return "No Solution"

    idx = lambda r, c: r * n + c
    rc = lambda k: (k // n, k % n)

    # Precompute clue positions and basic board masks.
    clue_idx = []
    clue_val = {}
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if isinstance(v, int):
                k = idx(r, c)
                clue_idx.append(k)
                clue_val[k] = v

    # Neighbors (orthogonal)
    NBR = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            k = idx(r, c)
            if r > 0:
                NBR[k].append(idx(r - 1, c))
            if r + 1 < n:
                NBR[k].append(idx(r + 1, c))
            if c > 0:
                NBR[k].append(idx(r, c - 1))
            if c + 1 < n:
                NBR[k].append(idx(r, c + 1))

    # Rays for each cell in 4 directions: list of indices outward (excluding self).
    RAYS = {}
    for r in range(n):
        for c in range(n):
            k = idx(r, c)
            up = [idx(rr, c) for rr in range(r - 1, -1, -1)]
            down = [idx(rr, c) for rr in range(r + 1, n)]
            left = [idx(r, cc) for cc in range(c - 1, -1, -1)]
            right = [idx(r, cc) for cc in range(c + 1, n)]
            RAYS[k] = (up, down, left, right)

    # Initial state: clues are forced white.
    st0 = [U] * (n * n)
    for k in clue_idx:
        st0[k] = W

    # Helpers
    def render(state):
        out = [[None] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                k = idx(r, c)
                if k in clue_val:
                    out[r][c] = clue_val[k]
                else:
                    out[r][c] = 'B' if state[k] == B else None
        return out

    def is_complete(state):
        return all(v != U for v in state)

    # --- Local constraint propagation for no-adjacent-black and clue sightlines ---

    def force_white(state, k, reason, trail):
        if state[k] == W:
            return True
        if state[k] == B:
            return False
        state[k] = W
        trail.append(k)
        return True

    def force_black(state, k, reason, trail):
        # clue cells cannot be black
        if k in clue_val:
            return False
        if state[k] == B:
            return True
        if state[k] == W:
            return False
        state[k] = B
        trail.append(k)
        return True

    def undo(state, trail, snap_len):
        for i in range(len(trail) - 1, snap_len - 1, -1):
            state[trail[i]] = U
        del trail[snap_len:]

    def visible_counts_bounds_for_clue(state, ck):
        # Returns (min_visible, max_visible) possible given partial assignment.
        # For each direction, visibility is a contiguous segment until first black or border,
        # but unknowns could be black to stop earlier. Min assumes stop as early as allowed,
        # max assumes extend through unknowns until forced black/border.
        min_vis = 1
        max_vis = 1
        for ray in RAYS[ck]:
            # max: count until first forced black, including forced white/unknown
            mx = 0
            for t in ray:
                if state[t] == B:
                    break
                mx += 1
            # min: if first cell is forced black => 0, else at least 1 until a forced black;
            # however we can choose to put a black at some unknown position (not necessarily first),
            # but black cannot be placed on clue cells and cannot violate adjacency.
            # For a safe lower bound, assume we can stop immediately at first step if that cell is not forced white.
            mn = 0
            if ray:
                first = ray[0]
                if state[first] == B:
                    mn = 0
                elif state[first] == W:
                    # must see at least first; continue while forced white and no forced black
                    mn = 1
                    for t in ray[1:]:
                        if state[t] == B:
                            break
                        if state[t] == W:
                            mn += 1
                        else:
                            # unknown could be black to stop here
                            break
                else:
                    # unknown first can be black to stop immediately
                    mn = 0
            min_vis += mn
            max_vis += mx
        return min_vis, max_vis

    def compute_mandatory_whites_for_clue(state, ck, target):
        # For each direction, compute the minimum number of cells that must be visible in that ray
        # based on global bounds in other rays.
        # Let per-ray max_i, min_i be bounds; to reach target, each ray i must contribute at least:
        # needed_i = max(0, target - 1 - sum(max_j for j!=i))
        # also cannot exceed max_i. Cells forced visible are first needed_i cells, thus must be white.
        rays = RAYS[ck]
        ray_max = []
        ray_min = []
        for ray in rays:
            mx = 0
            for t in ray:
                if state[t] == B:
                    break
                mx += 1
            # conservative min as in bounds function but return per-ray
            mn = 0
            if ray:
                first = ray[0]
                if state[first] == B:
                    mn = 0
                elif state[first] == W:
                    mn = 1
                    for t in ray[1:]:
                        if state[t] == B:
                            break
                        if state[t] == W:
                            mn += 1
                        else:
                            break
                else:
                    mn = 0
            ray_max.append(mx)
            ray_min.append(mn)

        total_max = sum(ray_max)
        total_min = sum(ray_min)
        # quick infeasibility check handled elsewhere
        needed = []
        for i in range(4):
            other_max = total_max - ray_max[i]
            need_i = max(0, target - 1 - other_max)
            # but at least current ray_min
            need_i = max(need_i, ray_min[i])
            need_i = min(need_i, ray_max[i])
            needed.append(need_i)
        return needed

    def enforce_clue_exactness(state, ck, target, trail):
        # Applies deterministic deductions:
        # 1) Check bounds.
        # 2) Force mandatory visible cells to white.
        # 3) If max equals target, then any cell beyond the target reach in a ray (given current forced
        #    whites) may be forced black at the first unknown after target visible segment to stop overshooting.
        mn, mx = visible_counts_bounds_for_clue(state, ck)
        if target < mn or target > mx:
            return False

        needed = compute_mandatory_whites_for_clue(state, ck, target)
        rays = RAYS[ck]
        # Force first needed[i] cells visible -> white (until blocked)
        for i, ray in enumerate(rays):
            cnt = 0
            for t in ray:
                if state[t] == B:
                    break
                if cnt < needed[i]:
                    if not force_white(state, t, ("clue_need", ck), trail):
                        return False
                    cnt += 1
                else:
                    break  # we only force prefix; not necessarily contiguous beyond unknowns
        # Additional pruning: if current minimum already equals target, we can place black immediately after
        # the forced visible segment *if* the next cell is unknown and would otherwise be seen for sure.
        # We implement a safe rule: if in a ray the first unknown is immediately after a prefix of forced whites,
        # and we already must not exceed remaining quota, force that unknown to black when necessary.
        # Compute per-ray forced-visible lower bounds after forcing.
        # Determine minimum contributions now (forced whites until first non-white/black).
        contrib_min = []
        contrib_max = []
        for ray in rays:
            # max as before
            mxr = 0
            for t in ray:
                if state[t] == B:
                    break
                mxr += 1
            # min: forced white prefix
            mnr = 0
            for t in ray:
                if state[t] == B:
                    break
                if state[t] == W:
                    mnr += 1
                else:
                    break
            contrib_min.append(mnr)
            contrib_max.append(mxr)
        total_min = 1 + sum(contrib_min)
        total_max = 1 + sum(contrib_max)

        if target < total_min or target > total_max:
            return False

        # If to avoid exceeding target, some ray must be cut at a specific point:
        # Let remaining allowance beyond forced prefix be A = target - total_min.
        # Each ray i can extend beyond prefix by at most ext_i = contrib_max[i]-contrib_min[i].
        # If sum(ext_i) == A, then all extra must be fully used; no cut.
        # If for a ray i, even if all other rays take maximum extension, ray i can take at most a cap.
        # This can force a black right after a certain position when the next cell is unknown.
        ext = [contrib_max[i] - contrib_min[i] for i in range(4)]
        A = target - total_min
        sum_ext = sum(ext)
        if A < 0 or A > sum_ext:
            return False

        # For each ray, compute maximum extension allowed given others could take min 0 but max ext.
        # We can force a cut if ray would otherwise be forced to extend past allowed due to forced whites.
        for i, ray in enumerate(rays):
            # allowed extra for this ray at most:
            other_ext_max = sum_ext - ext[i]
            max_extra_i = min(ext[i], A)  # trivial upper bound
            # tighter: ray i can be at most A - min_extra_other, but min extra other is 0 so same
            # However, if other rays cannot absorb enough (their max < A), then this ray must absorb some.
            other_ext_cap = other_ext_max
            min_extra_i = max(0, A - other_ext_cap)
            # So ray i extra must be within [min_extra_i, max_extra_i]
            # If max_extra_i == min_extra_i, then exact extra count is fixed.
            if min_extra_i == max_extra_i:
                fixed_extra = min_extra_i
                # Then the cell right after prefix+fixed_extra must be black (if exists and not already black)
                cut_pos = contrib_min[i] + fixed_extra
                # cut_pos is number of cells seen in this ray.
                # If ray has more cells beyond cut_pos and next cell is currently unknown or white (white would violate)
                if cut_pos < contrib_max[i]:
                    tnext = ray[cut_pos]
                    # Ensure it is black to stop, unless it is already black; if it is white, contradiction.
                    if not force_black(state, tnext, ("clue_cut", ck), trail):
                        return False
        return True

    def propagate_no_adjacent_black(state, trail):
        # If a cell is black, all orth neighbors must be white.
        # If a cell is unknown but has a black neighbor? nothing forced.
        q = deque([i for i, v in enumerate(state) if v == B])
        seen = set(q)
        while q:
            k = q.popleft()
            for nb in NBR[k]:
                if state[nb] == B:
                    return False
                if state[nb] == U:
                    if not force_white(state, nb, ("adj_black", k), trail):
                        return False
        return True

    def propagate_clues(state, trail):
        # Iterate clues until fixpoint.
        # Also apply immediate rule: cells adjacent to a clue being black can be allowed; no special.
        changed = True
        while changed:
            changed = False
            snap = len(trail)
            for ck in clue_idx:
                if not enforce_clue_exactness(state, ck, clue_val[ck], trail):
                    return False
            if len(trail) != snap:
                changed = True
            if not propagate_no_adjacent_black(state, trail):
                return False
        return True

    # --- Connectivity pruning: all whites must be one connected component.
    # Use a strong necessary condition: unknowns can be treated as white for possibility,
    # but black are walls. All forced whites must be connectable.

    def connectivity_feasible(state):
        # If no forced white, feasible.
        forced_whites = [i for i, v in enumerate(state) if v == W]
        if not forced_whites:
            return True
        # BFS in graph of non-black (white or unknown) to see if all forced whites lie in one component.
        start = forced_whites[0]
        q = deque([start])
        vis = {start}
        while q:
            k = q.popleft()
            for nb in NBR[k]:
                if nb not in vis and state[nb] != B:
                    vis.add(nb)
                    q.append(nb)
        return all(w in vis for w in forced_whites)

    def connectivity_final(state):
        # In complete assignment, all whites connected.
        whites = [i for i, v in enumerate(state) if v == W]
        if not whites:
            return False
        start = whites[0]
        q = deque([start])
        vis = {start}
        while q:
            k = q.popleft()
            for nb in NBR[k]:
                if nb not in vis and state[nb] == W:
                    vis.add(nb)
                    q.append(nb)
        return len(vis) == len(whites)

    # --- Branching heuristic: choose most constrained unknown cell.
    # Score by: adjacency to black (forces white), in sightlines of clues with tight remaining slack, etc.

    # Map each cell to which clues "see" it in their row/col ignoring blacks (dynamic). We'll approximate statically
    # by same row/col; still helpful.
    row_clues = [[] for _ in range(n)]
    col_clues = [[] for _ in range(n)]
    for ck in clue_idx:
        r, c = rc(ck)
        row_clues[r].append(ck)
        col_clues[c].append(ck)

    def estimate_cell_score(state, k):
        if state[k] != U:
            return -1
        r, c = rc(k)
        score = 0
        # Adjacent black makes it forced white eventually; prioritize.
        for nb in NBR[k]:
            if state[nb] == B:
                score += 50
        # Near clues in same row/col
        for ck in row_clues[r]:
            score += 3
        for ck in col_clues[c]:
            score += 3
        # Degree: corners/edges slightly more constrained.
        score += (4 - len(NBR[k]))
        return score

    def choose_branch_cell(state):
        best_k, best_s = None, -1
        for k, v in enumerate(state):
            if v == U:
                s = estimate_cell_score(state, k)
                if s > best_s:
                    best_s, best_k = s, k
        return best_k

    # --- Consistency checks for completed clue satisfaction
    def clue_exact_satisfied(state, ck, target):
        # compute visible whites exactly
        vis = 1
        for ray in RAYS[ck]:
            for t in ray:
                if state[t] == B:
                    break
                vis += 1
        # But if any visible cell is black, it would have broken; all visible are non-black.
        # Need count of white cells (non-black) since unknowns not in complete.
        # Here state is complete.
        return vis == target

    def all_clues_satisfied(state):
        return all(clue_exact_satisfied(state, ck, clue_val[ck]) for ck in clue_idx)

    # --- Search with strong propagation
    def dfs(state):
        trail = []
        # initial propagation
        if not propagate_no_adjacent_black(state, trail):
            undo(state, trail, 0)
            return None
        if not propagate_clues(state, trail):
            undo(state, trail, 0)
            return None
        if not connectivity_feasible(state):
            undo(state, trail, 0)
            return None

        if is_complete(state):
            if all_clues_satisfied(state) and connectivity_final(state):
                return state[:]
            undo(state, trail, 0)
            return None

        k = choose_branch_cell(state)
        if k is None:
            undo(state, trail, 0)
            return None

        # Try black first only if not adjacent to black and not clue.
        # Often Kuromasu-like puzzles have fewer blacks, but black introduces strong constraints; try black then white.
        for val in (B, W):
            snap = len(trail)
            ok = True
            if val == B:
                # black cannot touch black
                for nb in NBR[k]:
                    if state[nb] == B:
                        ok = False
                        break
                if ok:
                    ok = force_black(state, k, ("guess", k), trail)
            else:
                ok = force_white(state, k, ("guess", k), trail)
            if ok:
                res = dfs(state)
                if res is not None:
                    return res
            undo(state, trail, snap)

        undo(state, trail, 0)
        return None

    sol = dfs(st0[:])
    if sol is None:
        return "No Solution"
    return str(render(sol))


