from collections import defaultdict, deque
import itertools
import sys

# Solver for the described puzzle (Sashigane / "Disconnected" variant-like constraints):
# Variables: each cell is Black (B) or White (W).
# Constraints:
# (1) For each region, exactly clue number of black cells if a clue exists in that region. (If multiple clues appear, they must be consistent.)
# (2) Blacks cannot touch orthogonally.
# (3) Any uninterrupted straight white segment (row/col) cannot pass through more than 2 regions.
#     Interpreted as: for any maximal contiguous run of white cells along a row/col, the number of distinct region IDs in that run <= 2.
# (4) All white cells orthogonally connected.

# Approach:
# - Aggressive propagation:
#   * Region black-count bounds (min/max) and forced assignments.
#   * No-adjacent-black forces whites around a black.
#   * "White segment region-count" constraints enforced locally using window scanning with unknowns:
#       For each row/col, for any contiguous interval, if it could become an uninterrupted white segment
#       (i.e., no forced black within), then it must be possible for distinct region count <= 2.
#       We enforce this via examining maximal "not-forced-black" stretches and deriving forced blacks
#       to break stretches that would necessarily exceed 2 regions if all became white.
#   * White connectivity maintained using union-find over guaranteed whites + reachability check with unknowns for pruning.
# - Search with strong branching:
#   * Choose cell with highest constraint impact (in constrained regions / in critical row/col transitions / adjacent to blacks).
#   * Try assigning Black first only if consistent with region remaining quota; otherwise White.

W, B, U = 0, 1, -1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])
    assert n == m, "Expected NxN grid"

    # Map region -> cells
    reg_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            reg_cells[region[r][c]].append((r, c))

    # Gather region clues (may appear multiple times; must agree)
    reg_clue = {}
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            rid = region[r][c]
            if rid in reg_clue and reg_clue[rid] != v:
                return "No Solution"
            reg_clue[rid] = v

    # Precompute region transitions along each row/col for heuristics and segment checks
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]

    # Neighbors
    def neigh4(rc):
        r, c = rc
        if r > 0: yield (r-1, c)
        if r+1 < n: yield (r+1, c)
        if c > 0: yield (r, c-1)
        if c+1 < n: yield (r, c+1)

    # State arrays
    grid = [[U]*n for _ in range(n)]  # U/W/B as -1/0/1

    # Region count trackers
    reg_black = defaultdict(int)
    reg_unknown = defaultdict(int)
    for rid, cells in reg_cells.items():
        reg_unknown[rid] = len(cells)

    # Domain operations
    def set_cell(r, c, val, trail):
        cur = grid[r][c]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        # apply
        grid[r][c] = val
        trail.append((r, c, cur))
        rid = region[r][c]
        # update region trackers
        if cur == U:
            reg_unknown[rid] -= 1
            if val == B:
                reg_black[rid] += 1
        elif cur == W:
            if val == B:
                reg_black[rid] += 1
        elif cur == B:
            if val == W:
                reg_black[rid] -= 1
        return True

    def undo(trail, mark):
        while len(trail) > mark:
            r, c, prev = trail.pop()
            cur = grid[r][c]
            rid = region[r][c]
            # revert trackers
            if prev == U:
                reg_unknown[rid] += 1
                if cur == B:
                    reg_black[rid] -= 1
            elif prev == W:
                if cur == B:
                    reg_black[rid] -= 1
            elif prev == B:
                if cur == W:
                    reg_black[rid] += 1
            grid[r][c] = prev

    # Constraint propagation queue
    def propagate(trail):
        q = deque()
        inq = [[False]*n for _ in range(n)]

        def push(rc):
            r, c = rc
            if not inq[r][c]:
                inq[r][c] = True
                q.append(rc)

        # Initialize with all cells (could be optimized by seeding with recently changed, but ok)
        for r in range(n):
            for c in range(n):
                push((r, c))

        # region-level worklist
        regq = deque(reg_cells.keys())

        # helper: enforce region quota on a region id
        def enforce_region(rid):
            if rid not in reg_clue:
                return True
            clue = reg_clue[rid]
            bcnt = reg_black[rid]
            ucnt = reg_unknown[rid]
            if bcnt > clue:
                return False
            if bcnt + ucnt < clue:
                return False
            # If must fill remaining with all unknown -> set all unknown to black
            if bcnt + ucnt == clue:
                for (r, c) in reg_cells[rid]:
                    if grid[r][c] == U:
                        if not set_cell(r, c, B, trail):
                            return False
                        push((r, c))
            # If already met clue -> remaining unknown must be white
            if bcnt == clue:
                for (r, c) in reg_cells[rid]:
                    if grid[r][c] == U:
                        if not set_cell(r, c, W, trail):
                            return False
                        push((r, c))
            return True

        # helper: enforce black adjacency rule around a cell
        def enforce_adj(r, c):
            if grid[r][c] != B:
                return True
            for nr, nc in neigh4((r, c)):
                if grid[nr][nc] == B:
                    return False
                if grid[nr][nc] == U:
                    if not set_cell(nr, nc, W, trail):
                        return False
                    push((nr, nc))
            return True

        # Rule (3): segment cannot cross >2 regions.
        # We enforce on each row/col by scanning maximal stretches without forced black,
        # and if within a stretch, there exists a subsequence that would inevitably contain >2 regions
        # even after choosing some cells to black? But the segment is uninterrupted white, so black breaks it.
        # For deduction: if a maximal "not forced black" stretch contains >=3 distinct regions in order,
        # then to prevent an all-white segment that spans 3 regions, we must force at least one black at
        # some boundary between region changes where all cells at that boundary are not forced white.
        #
        # We implement conservative but powerful rule:
        # For any row/col, consider contiguous indices [i..j] where no cell is forced black.
        # If the sequence of region IDs over forced-white and unknown cells in [i..j] contains
        # three or more distinct regions, then at least one cell in that interval must be black.
        # Additionally, if only one cell can be black (by region quota / adjacency already implied),
        # force it. We approximate "only one candidate breaker" by identifying candidate cells whose
        # black would break all 3+region spans: any cell at a region-transition position.
        #
        # This is not complete but prunes heavily and mirrors human logic.
        def enforce_segments_line(cells):
            # cells: list of (r,c) along a line
            k = len(cells)
            i = 0
            while i < k:
                # skip forced black
                while i < k and grid[cells[i][0]][cells[i][1]] == B:
                    i += 1
                if i >= k:
                    break
                j = i
                while j < k and grid[cells[j][0]][cells[j][1]] != B:
                    j += 1
                # Now interval [i, j-1] contains U/W only
                # Determine distinct regions present (in order)
                regs = []
                last = None
                for t in range(i, j):
                    r, c = cells[t]
                    rid = region[r][c]
                    if rid != last:
                        regs.append(rid)
                        last = rid
                if len(regs) >= 3:
                    # Need at least one black somewhere in [i, j-1] OR ensure segment can't become all-white
                    # Identify candidate cells that are not forced white (unknown only) since W can't break.
                    candidates = []
                    for t in range(i, j):
                        r, c = cells[t]
                        if grid[r][c] == U:
                            candidates.append((r, c))
                    if not candidates:
                        # All forced white => would create illegal segment
                        return False
                    # Stronger: candidates that sit on any boundary between 3rd region inclusion.
                    # Find boundary indices where region changes; placing black anywhere breaks, but
                    # choose boundary candidates to reduce.
                    boundary_cands = set()
                    for t in range(i+1, j):
                        r0, c0 = cells[t-1]
                        r1, c1 = cells[t]
                        if region[r0][c0] != region[r1][c1]:
                            # Either side could be black to break
                            if grid[r0][c0] == U: boundary_cands.add((r0, c0))
                            if grid[r1][c1] == U: boundary_cands.add((r1, c1))
                    use = list(boundary_cands) if boundary_cands else candidates

                    # If any candidate is impossible to be black (due to adjacency immediate B neighbors or region quota),
                    # we'll filter.
                    feas = []
                    for (r, c) in use:
                        if grid[r][c] != U:
                            continue
                        # quick feasibility
                        ok = True
                        for nr, nc in neigh4((r, c)):
                            if grid[nr][nc] == B:
                                ok = False
                                break
                        if not ok:
                            continue
                        rid = region[r][c]
                        if rid in reg_clue and reg_black[rid] >= reg_clue[rid]:
                            continue
                        feas.append((r, c))
                    if not feas:
                        return False
                    if len(feas) == 1:
                        r, c = feas[0]
                        if not set_cell(r, c, B, trail):
                            return False
                        push((r, c))
                i = j
            return True

        # Connectivity pruning: all whites connected.
        # We do a necessary check:
        # - Let "definitely white" = cells assigned W.
        # - Let "possible white" = W or U.
        # If there are no whites, ok.
        # Otherwise, all definitely white cells must lie in the same connected component within possible-white graph.
        def enforce_connectivity_necessary():
            whites = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == W]
            if not whites:
                return True
            start = whites[0]
            seen = set([start])
            dq = deque([start])
            while dq:
                r, c = dq.popleft()
                for nr, nc in neigh4((r, c)):
                    if (nr, nc) in seen:
                        continue
                    if grid[nr][nc] == B:
                        continue
                    seen.add((nr, nc))
                    dq.append((nr, nc))
            for rc in whites[1:]:
                if rc not in seen:
                    return False
            return True

        # Initial region enforcement
        while regq:
            rid = regq.popleft()
            if not enforce_region(rid):
                return False

        # Main loop
        steps = 0
        while q:
            r, c = q.popleft()
            inq[r][c] = False
            steps += 1
            if steps > 200000:
                # safeguard
                pass

            # Enforce adjacency if black
            if not enforce_adj(r, c):
                return False

            # Region constraints might be affected
            rid = region[r][c]
            if not enforce_region(rid):
                return False

            # Segment constraints for the row/col of this cell
            if not enforce_segments_line(rows[r]):
                return False
            if not enforce_segments_line(cols[c]):
                return False

            # Connectivity necessary check periodically; cheap enough for 8x8
            if (steps & 31) == 0:
                if not enforce_connectivity_necessary():
                    return False

        # Final connectivity check
        if not enforce_connectivity_necessary():
            return False
        return True

    def is_complete():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == U:
                    return False
        # Validate region exact counts
        for rid, clue in reg_clue.items():
            if reg_black[rid] != clue:
                return False
        # Validate segments: any maximal white segment must be <=2 regions
        def check_line(cells):
            k = len(cells)
            i = 0
            while i < k:
                while i < k and grid[cells[i][0]][cells[i][1]] == B:
                    i += 1
                if i >= k:
                    break
                j = i
                while j < k and grid[cells[j][0]][cells[j][1]] != B:
                    j += 1
                # this segment is all white (since complete)
                regs = []
                last = None
                for t in range(i, j):
                    r, c = cells[t]
                    rid = region[r][c]
                    if rid != last:
                        regs.append(rid)
                        last = rid
                if len(regs) > 2:
                    return False
                i = j
            return True
        for r in range(n):
            if not check_line(rows[r]):
                return False
        for c in range(n):
            if not check_line(cols[c]):
                return False

        # Validate all whites connected
        whites = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == W]
        if not whites:
            return True
        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            r, c = dq.popleft()
            for nr, nc in neigh4((r, c)):
                if (nr, nc) in seen:
                    continue
                if grid[nr][nc] == B:
                    continue
                seen.add((nr, nc))
                dq.append((nr, nc))
        return len(seen) == len(whites)

    # Heuristic: pick most constrained unknown cell
    def pick_cell():
        best = None
        best_score = -1
        for r in range(n):
            for c in range(n):
                if grid[r][c] != U:
                    continue
                rid = region[r][c]
                score = 0
                # region pressure
                if rid in reg_clue:
                    clue = reg_clue[rid]
                    bcnt = reg_black[rid]
                    ucnt = reg_unknown[rid]
                    rem = clue - bcnt
                    # close to forcing
                    score += 10 * (1 if rem in (0, ucnt) else 0)
                    score += 5 * (1 if rem <= 1 else 0)
                # adjacency to black
                for nr, nc in neigh4((r, c)):
                    if grid[nr][nc] == B:
                        score += 20
                # region transitions in row/col (segment constraint sensitivity)
                if c > 0 and region[r][c-1] != region[r][c]:
                    score += 3
                if c+1 < n and region[r][c+1] != region[r][c]:
                    score += 3
                if r > 0 and region[r-1][c] != region[r][c]:
                    score += 3
                if r+1 < n and region[r+1][c] != region[r][c]:
                    score += 3
                if score > best_score:
                    best_score = score
                    best = (r, c)
        return best

    # Initial forced moves from clues: clue=0 => all white; clue=size => all black (then adjacency)
    trail = []
    for rid, cells in reg_cells.items():
        if rid in reg_clue:
            clue = reg_clue[rid]
            if clue == 0:
                for r, c in cells:
                    if not set_cell(r, c, W, trail):
                        return "No Solution"
            elif clue == len(cells):
                for r, c in cells:
                    if not set_cell(r, c, B, trail):
                        return "No Solution"
    if not propagate(trail):
        return "No Solution"

    sys.setrecursionlimit(10000)

    def dfs():
        if is_complete():
            return True
        rc = pick_cell()
        if rc is None:
            return False
        r, c = rc
        rid = region[r][c]

        # Decide ordering
        try_black_first = True
        if rid in reg_clue:
            clue = reg_clue[rid]
            if reg_black[rid] >= clue:
                try_black_first = False

        for val in ([B, W] if try_black_first else [W, B]):
            mark = len(trail)
            if set_cell(r, c, val, trail) and propagate(trail):
                if dfs():
                    return True
            undo(trail, mark)
        return False

    if not dfs():
        return "No Solution"

    # Return NxN 2D list with 'B' or None (white)
    ans = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if grid[r][c] == B else None)
        ans.append(row)
    return str(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2, 3, 3, 4], [0, 0, 1, 1, 2, 2, 3, 3, 4], [0, 0, 5, 5, 6, 6, 6, 3, 4], [0, 0, 5, 5, 6, 6, 6, 3, 4], [0, 0, 7, 7, 6, 6, 6, 3, 4], [8, 8, 8, 9, 9, 9, 10, 10, 4], [8, 8, 8, 9, 9, 9, 10, 10, 11], [12, 12, 12, 9, 9, 9, 13, 10, 11], [14, 14, 14, 15, 15, 16, 13, 17, 11], [14, 14, 14, 15, 15, 16, 13, 17, 11]], 'data': [[None, None, None, None, 2, None, None, 3, 1], [None, None, None, None, None, None, None, None, None], [None, None, 2, None, 1, None, None, None, None], [None, None, None, None, None, None, None, None, None], [None, None, None, None, 1, None, None, None, None], [None, 2, None, 2, None, None, 1, None, None], [None, None, None, None, None, None, None, None, 0], [None, None, None, None, None, None, None, None, None], [None, None, None, None, 1, None, None, 0, None], [None, None, None, None, None, None, None, 1, None]]}
from collections import deque, defaultdict
from dataclasses import dataclass

# Solver for: region black counts, no orth-adjacent blacks, "white straight segment spans <=2 regions",
# and all whites connected orthogonally.

B, W, U = 1, 0, -1  # black, white, unknown


def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])
    if n != m:
        # problem statement says N x N; still handle rectangles defensively
        pass

    # ---- Build region structures ----
    rid_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            rid_cells[region[r][c]].append(r * m + c)
    rids = sorted(rid_cells.keys())

    # region clues: allow None (unclued); if multiple numbers in region, they must match
    rid_clue = {}
    for rid in rids:
        clue = None
        for idx in rid_cells[rid]:
            r, c = divmod(idx, m)
            v = data[r][c]
            if v is None:
                continue
            if clue is None:
                clue = int(v)
            elif clue != int(v):
                return "No Solution"
        rid_clue[rid] = clue

    # ---- Precompute neighbors ----
    N = n * m
    nbrs = [[] for _ in range(N)]
    for r in range(n):
        for c in range(m):
            i = r * m + c
            if r > 0:
                nbrs[i].append((r - 1) * m + c)
            if r + 1 < n:
                nbrs[i].append((r + 1) * m + c)
            if c > 0:
                nbrs[i].append(r * m + (c - 1))
            if c + 1 < m:
                nbrs[i].append(r * m + (c + 1))

    # ---- Straight white-segment constraint helpers ----
    # For each cell, compute its maximal row-run and col-run (indexes) (entire line).
    # We'll enforce: in any contiguous run of non-black cells (white/unknown) in a row/col,
    # the number of distinct regions appearing in that run must be <= 2 once fully white,
    # and during propagation we ensure it can still be made <=2 by potentially placing blacks.
    row_cells = [[r * m + c for c in range(m)] for r in range(n)]
    col_cells = [[r * m + c for r in range(n)] for c in range(m)]
    cell_row = [i // m for i in range(N)]
    cell_col = [i % m for i in range(N)]

    # For each row/col, build segments separated by forced blacks; dynamic, so we will check on the fly.
    # Optimization: precompute region-id for each cell.
    cell_rid = [0] * N
    for r in range(n):
        for c in range(m):
            cell_rid[r * m + c] = region[r][c]

    # ---- State structure ----
    @dataclass
    class State:
        grid: list  # length N, values in {B,W,U}
        rid_black: dict
        rid_unknown: dict
        # DSU for whites connectivity (only for assigned whites). We'll rebuild incrementally with path compression.
        parent: list
        size: list
        white_count: int
        # track if contradiction found quickly
        ok: bool = True

    # DSU helpers
    def dsu_make(n_):
        return list(range(n_)), [1] * n_

    def dsu_find(par, x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x

    def dsu_union(par, sz, a, b):
        ra, rb = dsu_find(par, a), dsu_find(par, b)
        if ra == rb:
            return
        if sz[ra] < sz[rb]:
            ra, rb = rb, ra
        par[rb] = ra
        sz[ra] += sz[rb]

    # Initialize counts
    init_grid = [U] * N
    rid_black = {rid: 0 for rid in rids}
    rid_unknown = {rid: len(rid_cells[rid]) for rid in rids}
    parent, size = dsu_make(N)
    st = State(init_grid, rid_black, rid_unknown, parent, size, 0, True)

    # ---- Assignment with propagation ----
    def assign_cell(state: State, i: int, val: int, trail):
        cur = state.grid[i]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        # record for backtrack
        trail.append(("cell", i, cur))
        state.grid[i] = val
        rid = cell_rid[i]
        # update region counts
        if cur == U:
            # unknown -> val
            trail.append(("rid_unknown", rid, state.rid_unknown[rid]))
            state.rid_unknown[rid] -= 1
            if val == B:
                trail.append(("rid_black", rid, state.rid_black[rid]))
                state.rid_black[rid] += 1
            else:  # white
                trail.append(("white_count", None, state.white_count))
                state.white_count += 1
                # DSU union with white neighbors
                for j in nbrs[i]:
                    if state.grid[j] == W:
                        # union; record DSU changes by snapshotting roots info
                        ra = dsu_find(state.parent, i)
                        rb = dsu_find(state.parent, j)
                        if ra != rb:
                            # record parent and size for rollback
                            if state.size[ra] < state.size[rb]:
                                ra, rb = rb, ra
                            trail.append(("dsu", rb, state.parent[rb], ra, state.size[ra]))
                            state.parent[rb] = ra
                            state.size[ra] += state.size[rb]
        else:
            # shouldn't happen due to checks
            return False

        return True

    def rollback(state: State, trail, mark):
        while len(trail) > mark:
            typ, a, b, *rest = trail.pop()
            if typ == "cell":
                state.grid[a] = b
            elif typ == "rid_unknown":
                state.rid_unknown[a] = b
            elif typ == "rid_black":
                state.rid_black[a] = b
            elif typ == "white_count":
                state.white_count = b
            elif typ == "dsu":
                rb, old_parent, ra, old_size_ra = a, b, rest[0], rest[1]
                state.parent[rb] = old_parent
                state.size[ra] = old_size_ra

    # ---- Constraint checks & deductions ----
    def region_feasible(state: State, rid):
        clue = rid_clue[rid]
        if clue is None:
            # still must be feasible with current black count <= size
            return 0 <= state.rid_black[rid] <= len(rid_cells[rid])
        bcnt = state.rid_black[rid]
        unk = state.rid_unknown[rid]
        return (bcnt <= clue) and (bcnt + unk >= clue)

    def enforce_region_counts(state: State, trail, queue_rids):
        # For rid in queue, if clue forces all remaining unknowns to B or W, assign.
        while queue_rids:
            rid = queue_rids.popleft()
            if not region_feasible(state, rid):
                return False
            clue = rid_clue[rid]
            if clue is None:
                continue
            bcnt = state.rid_black[rid]
            unk = state.rid_unknown[rid]
            need = clue - bcnt
            if need == 0 and unk > 0:
                # all remaining unknown in region must be white
                for i in rid_cells[rid]:
                    if state.grid[i] == U:
                        if not assign_cell(state, i, W, trail):
                            return False
                        # neighbor constraints after assignment will be handled elsewhere
                # counts updated automatically
            elif need == unk and unk > 0:
                # all unknowns must be black
                for i in rid_cells[rid]:
                    if state.grid[i] == U:
                        if not assign_cell(state, i, B, trail):
                            return False
        return True

    def enforce_no_adjacent_blacks(state: State, trail, newly_black):
        # when a cell is black, all orth neighbors must be white
        while newly_black:
            i = newly_black.pop()
            for j in nbrs[i]:
                if state.grid[j] == B:
                    return False
                if state.grid[j] == U:
                    if not assign_cell(state, j, W, trail):
                        return False
        return True

    def check_straight_constraint_line(state: State, line):
        # line is list of indices in row/col order.
        # Consider segments separated by confirmed blacks.
        # For each segment, consider regions present among cells that are not black (W/U).
        # Must be possible to end with <=2 regions by inserting blacks among unknowns.
        # Necessary condition:
        # Let region sequence of cells excluding blacks. If there are >=3 distinct regions forced white
        # without any place to separate by black (i.e., contiguous whites spanning 3 regions), contradiction.
        # We'll do a safe pruning:
        # For each maximal segment between blacks, compute region blocks in order. Unknown cells may become black,
        # allowing splitting the segment. The only "forced" whites are W.
        # If there exists a contiguous run of W cells (no U and no B) whose region-set size > 2 => contradiction.
        # Also, if a segment has three different regions that each contain at least one forced white,
        # and these forced whites appear in order without unknown positions between region transitions to cut,
        # contradiction. We'll implement the simple strong check on forced-white runs and a mild check on whole segment.
        # Simple forced-white run check:
        k = 0
        L = len(line)
        while k < L:
            # skip blacks
            while k < L and state.grid[line[k]] == B:
                k += 1
            if k >= L:
                break
            # within segment until black
            seg_start = k
            while k < L and state.grid[line[k]] != B:
                k += 1
            seg = line[seg_start:k]
            # check runs of consecutive forced whites
            t = 0
            while t < len(seg):
                while t < len(seg) and state.grid[seg[t]] != W:
                    t += 1
                if t >= len(seg):
                    break
                u = t
                regset = set()
                while u < len(seg) and state.grid[seg[u]] == W:
                    regset.add(cell_rid[seg[u]])
                    u += 1
                if len(regset) > 2:
                    return False
                t = u
            # mild whole-segment pruning: if segment currently has >2 regions and there is no unknown at any boundary
            # between region changes to allow placing black, it may be impossible.
            # We'll compute region transitions positions that are "cuttable" (a cell that is U can become B).
            regs = [cell_rid[x] for x in seg]
            # compress consecutive equal
            comp = []
            pos = []
            for idx, rr in enumerate(regs):
                if not comp or comp[-1] != rr:
                    comp.append(rr)
                    pos.append(idx)
            if len(set(comp)) <= 2:
                continue
            # Determine if we can potentially reduce distinct regions to <=2 by cutting out some parts with blacks.
            # Necessary condition for possibility: there exist at least (len(set(comp))-2) unknown cells in seg
            # that could be black to split; very weak but helps.
            ucount = sum(1 for x in seg if state.grid[x] == U)
            if ucount == 0:
                return False
        return True

    def check_straight_constraint(state: State):
        for r in range(n):
            if not check_straight_constraint_line(state, row_cells[r]):
                return False
        for c in range(m):
            if not check_straight_constraint_line(state, col_cells[c]):
                return False
        return True

    def white_connectivity_possible(state: State):
        # If no whites assigned yet, always possible.
        if state.white_count <= 1:
            return True
        # Check all current whites are connected through non-black cells potentially (treat unknown as white for reachability).
        # Also ensure there exists at least one component of current whites that can connect via unknowns.
        # We'll run BFS from first white over cells != B and see if all current whites reached.
        start = None
        for i, v in enumerate(state.grid):
            if v == W:
                start = i
                break
        if start is None:
            return True
        q = deque([start])
        seen = [False] * N
        seen[start] = True
        reached_whites = 1
        while q:
            i = q.popleft()
            for j in nbrs[i]:
                if seen[j]:
                    continue
                if state.grid[j] == B:
                    continue
                seen[j] = True
                q.append(j)
        # verify all whites are in seen
        for i, v in enumerate(state.grid):
            if v == W and not seen[i]:
                return False
        return True

    def propagate(state: State, trail, seeds):
        # seeds: list of indices newly assigned, to drive local propagation
        q_rids = deque()
        newly_black = []
        for i in seeds:
            if state.grid[i] == B:
                newly_black.append(i)
            q_rids.append(cell_rid[i])

        # Also initial enforcement across all rids once
        # We'll include all rids in q on first call by passing seeds from whole set if needed.
        if not enforce_region_counts(state, trail, q_rids):
            return False
        if not enforce_no_adjacent_blacks(state, trail, newly_black):
            return False

        # Region counts might have changed after forcing whites; re-enforce iteratively until stable.
        # We'll do a bounded loop by scanning affected regions when changes occur.
        # Simple approach: keep re-queue all regions touched by any assignment in this propagation via trail diff.
        # Here we conservatively scan all regions if any change happened, but cap iterations.
        for _ in range(3):
            any_forced = False
            for rid in rids:
                clue = rid_clue[rid]
                if clue is None:
                    continue
                bcnt = state.rid_black[rid]
                unk = state.rid_unknown[rid]
                need = clue - bcnt
                if need == 0 and unk > 0:
                    any_forced = True
                    for i in rid_cells[rid]:
                        if state.grid[i] == U:
                            if not assign_cell(state, i, W, trail):
                                return False
                elif need == unk and unk > 0:
                    any_forced = True
                    for i in rid_cells[rid]:
                        if state.grid[i] == U:
                            if not assign_cell(state, i, B, trail):
                                return False
                            newly_black.append(i)
            if newly_black:
                if not enforce_no_adjacent_blacks(state, trail, newly_black):
                    return False
            if not any_forced:
                break

        # Global checks
        if not check_straight_constraint(state):
            return False
        if not white_connectivity_possible(state):
            return False
        # Region feasibility
        for rid in rids:
            if not region_feasible(state, rid):
                return False
        return True

    # ---- Heuristics ----
    def choose_cell(state: State):
        # Prefer cells in constrained regions (clued, near completion), then by adjacency to blacks/edges.
        best = None
        best_score = -10**9
        for i, v in enumerate(state.grid):
            if v != U:
                continue
            rid = cell_rid[i]
            clue = rid_clue[rid]
            bcnt = state.rid_black[rid]
            unk = state.rid_unknown[rid]
            score = 0
            if clue is not None:
                need = clue - bcnt
                # tighter regions higher score
                score += 1000 - 50 * unk - 30 * abs(need)
                # if need close to 0 or unk, strong
                if need == 0 or need == unk:
                    score += 500
            # adjacency to black increases likely forced white; decide sooner
            for j in nbrs[i]:
                if state.grid[j] == B:
                    score += 80
            # region boundary (encourages splitting straight segments)
            r = cell_row[i]
            c = cell_col[i]
            if r > 0 and cell_rid[i - m] != rid:
                score += 10
            if r + 1 < n and cell_rid[i + m] != rid:
                score += 10
            if c > 0 and cell_rid[i - 1] != rid:
                score += 10
            if c + 1 < m and cell_rid[i + 1] != rid:
                score += 10
            if score > best_score:
                best_score = score
                best = i
        return best

    def value_order(state: State, i: int):
        # Try value that is more constrained first
        rid = cell_rid[i]
        clue = rid_clue[rid]
        # If adjacent black, must be white
        for j in nbrs[i]:
            if state.grid[j] == B:
                return [W]
        if clue is None:
            # default: try white first (helps connectivity)
            return [W, B]
        need = clue - state.rid_black[rid]
        unk = state.rid_unknown[rid]
        # if need small, prefer white; if need large, prefer black
        if need <= 0:
            return [W]
        if need >= unk:
            return [B]
        if need * 2 > unk:
            return [B, W]
        return [W, B]

    # ---- DFS with strong propagation ----
    def dfs(state: State):
        # If all assigned, validate final constraints incl. exact region counts and full white connectivity.
        i = choose_cell(state)
        if i is None:
            # final checks: exact clued counts, no adj blacks, straight constraint, white connectivity of whites (all non-black are white now)
            for rid in rids:
                clue = rid_clue[rid]
                if clue is not None and state.rid_black[rid] != clue:
                    return None
            if not check_straight_constraint(state):
                return None
            # all unknowns none; ensure all whites connected:
            # BFS from a white across whites only
            whites = [k for k, v in enumerate(state.grid) if v == W]
            if whites:
                start = whites[0]
                q = deque([start])
                seen = set([start])
                while q:
                    x = q.popleft()
                    for y in nbrs[x]:
                        if state.grid[y] == W and y not in seen:
                            seen.add(y)
                            q.append(y)
                if len(seen) != len(whites):
                    return None
            return state.grid

        for val in value_order(state, i):
            trail = []
            mark = 0
            if not assign_cell(state, i, val, trail):
                rollback(state, trail, mark)
                continue
            if propagate(state, trail, [i]):
                res = dfs(state)
                if res is not None:
                    return res
            rollback(state, trail, mark)
        return None

    # Initial propagation: apply region forced moves from initial empty assignment (none), but we can still force regions with clue 0 or full.
    init_trail = []
    if not propagate(st, init_trail, []):
        return "No Solution"

    sol = dfs(st)
    if sol is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            v = sol[r * m + c]
            row.append("B" if v == B else None)
        out.append(row)
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 4, 3, 1, 5], [4, 3, 5, 3, 1], [5, 2, 5, 4, 3], [3, 3, 4, 1, 2], [4, 5, 2, 3, 4]]}
from collections import defaultdict, deque

# Hitori-like solver:
# - Decide for each cell: White(kept) or Black(shaded)
# Constraints:
#   (A) No duplicate numbers among Whites in any row/col.
#   (B) Blacks not orthogonally adjacent.
#   (C) All Whites connected orthogonally.
#
# Approach:
#   Aggressive propagation:
#     1) Unique-in-row/col constraints -> if a value appears k times in a line, at least k-1 must be black OR separated by blacking others.
#        We encode as: for each pair of same-valued cells in same line, not(both White).
#     2) Black adjacency: if cell Black => neighbors forced White.
#     3) Connectivity: maintain dynamic "must-connect" pruning:
#        - For partial assignments, check feasibility by ensuring remaining possible Whites can still be connected:
#          a) No already-White cells split into multiple components that cannot be connected through possible-White cells.
#          b) No forced-White cell becomes isolated (surrounded by forced-Black/out-of-bounds).
#   Search:
#     - Use smallest-domain heuristic on unassigned.
#     - Value ordering prefers White, but if that violates duplicates, try Black.
#
# Representation:
#   state[i] in {-1 unassigned, 0 white, 1 black}

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    N = n * n

    def idx(r, c): return r * n + c
    def rc(i): return divmod(i, n)

    # Precompute neighbors
    neigh = [[] for _ in range(N)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0: neigh[i].append(idx(r - 1, c))
            if r + 1 < n: neigh[i].append(idx(r + 1, c))
            if c > 0: neigh[i].append(idx(r, c - 1))
            if c + 1 < n: neigh[i].append(idx(r, c + 1))

    # Precompute duplicate-pairs constraints: for each pair with same number in a row/col => not(both white)
    # Store as adjacency list for quick checks.
    not_both_white = [[] for _ in range(N)]  # list of other indices that cannot both be white
    # Row groups
    for r in range(n):
        pos = defaultdict(list)
        for c in range(n):
            pos[grid[r][c]].append(idx(r, c))
        for _, cells in pos.items():
            if len(cells) > 1:
                for i in range(len(cells)):
                    a = cells[i]
                    for j in range(i + 1, len(cells)):
                        b = cells[j]
                        not_both_white[a].append(b)
                        not_both_white[b].append(a)
    # Col groups
    for c in range(n):
        pos = defaultdict(list)
        for r in range(n):
            pos[grid[r][c]].append(idx(r, c))
        for _, cells in pos.items():
            if len(cells) > 1:
                for i in range(len(cells)):
                    a = cells[i]
                    for j in range(i + 1, len(cells)):
                        b = cells[j]
                        not_both_white[a].append(b)
                        not_both_white[b].append(a)

    # Quick degree / potential isolation detection for forced white
    def white_has_possible_neighbor(i, state):
        # At least one neighbor is not forced black
        for j in neigh[i]:
            if state[j] != 1:
                return True
        return False

    # Connectivity feasibility check on partial assignment
    def connectivity_ok(state):
        # If no whites forced yet, always feasible unless all cells forced black (invalid)
        forced_white = [i for i, v in enumerate(state) if v == 0]
        if not forced_white:
            # Feasible if at least one cell can be white
            return any(v != 1 for v in state)

        # If any forced white has all neighbors forced black/out -> impossible (unless n==1)
        for i in forced_white:
            if not white_has_possible_neighbor(i, state) and N > 1:
                # It could still be valid if it's the only white in final, but puzzle requires connectivity of all whites.
                # Single white is connected; allow if all others can be black without violating adjacency.
                # However, in Hitori typically not all black allowed; here not prohibited. We'll allow.
                pass

        # Build graph of possible white cells (state != black)
        possible = [i for i, v in enumerate(state) if v != 1]
        poss_set = set(possible)

        # BFS from one forced white over possible cells
        start = forced_white[0]
        q = deque([start])
        seen = {start}
        while q:
            u = q.popleft()
            for v in neigh[u]:
                if v in poss_set and v not in seen:
                    seen.add(v)
                    q.append(v)

        # All forced whites must be in same possible component
        for i in forced_white[1:]:
            if i not in seen:
                return False

        # Additional pruning: if there exist multiple forced-white components already separated by forced blacks (covered by above)
        return True

    # Propagation engine
    def propagate(state, queue):
        # queue contains indices whose assignment changed; process implications.
        while queue:
            i = queue.pop()

            vi = state[i]
            if vi == 1:
                # Black => neighbors must be White (cannot be Black)
                for j in neigh[i]:
                    if state[j] == 1:
                        return False
                    if state[j] == -1:
                        state[j] = 0
                        queue.append(j)

            if vi == 0:
                # White => cannot have other same-number cell in row/col also White
                for j in not_both_white[i]:
                    if state[j] == 0:
                        return False
                    if state[j] == -1:
                        state[j] = 1
                        queue.append(j)

                # White cell must have at least one neighbor not black if more than one cell exists,
                # but single isolated white could be valid if it's the only white; can't decide yet.
                # Still, if all neighbors forced black and there is another forced white elsewhere => impossible via connectivity.
                # Connectivity check handles that.

            # Local adjacency check for unassigned not needed; handled when setting black.

        # Global connectivity feasibility check
        return connectivity_ok(state)

    def initial_propagation(state):
        # Some immediate deductions:
        # - If a number is unique in its row and col, it can be safely white (not strictly necessary),
        #   but forcing it white is sound: shading it provides no benefit for duplicates, but could help adjacency constraints.
        #   This is NOT always sound. So we won't force.
        #
        # - If a cell is the only possible white left in a region? too heavy. Skip.
        return True

    # Heuristic choose variable:
    # domain size 1 if implied; else choose most constrained:
    # prefer cells involved in many duplicate constraints.
    dup_degree = [len(not_both_white[i]) for i in range(N)]

    def pick_var(state):
        best = -1
        best_key = None
        for i, v in enumerate(state):
            if v != -1:
                continue
            # compute if forced by current constraints quickly:
            # if any neighbor is black? doesn't force.
            # if any conflicting same-number already white => this must be black.
            must_black = False
            for j in not_both_white[i]:
                if state[j] == 0:
                    must_black = True
                    break
            # if any neighbor black? doesn't restrict.
            # if any neighbor black and we set black -> would violate, but that's decision.
            domain = 1 if must_black else 2
            # higher dup_degree, and smaller domain
            key = (domain, -dup_degree[i])
            if best_key is None or key < best_key:
                best_key = key
                best = i
                if domain == 1 and dup_degree[i] > 0:
                    # pretty good
                    pass
        return best

    def is_complete(state):
        return all(v != -1 for v in state)

    def final_checks(state):
        # Check duplicates satisfied by construction (pairwise)
        # Check no adjacent blacks
        for i, v in enumerate(state):
            if v == 1:
                for j in neigh[i]:
                    if state[j] == 1:
                        return False
        # Check all whites connected
        whites = [i for i, v in enumerate(state) if v == 0]
        if whites:
            q = deque([whites[0]])
            seen = {whites[0]}
            white_set = set(whites)
            while q:
                u = q.popleft()
                for v in neigh[u]:
                    if v in white_set and v not in seen:
                        seen.add(v)
                        q.append(v)
            if len(seen) != len(whites):
                return False
        # If no whites, treat as invalid (usually); but rule says unshaded cells must form one connected group.
        # Empty set is not a group.
        else:
            return False
        return True

    # Backtracking with propagation
    def dfs(state):
        if is_complete(state):
            return state if final_checks(state) else None

        i = pick_var(state)
        if i == -1:
            return None

        # Determine domain ordering with some logic:
        # Prefer White unless it immediately forces contradiction or creates black adjacency necessity.
        candidates = []

        # If any conflicting same-number is white, must be black
        must_black = any(state[j] == 0 for j in not_both_white[i])
        if must_black:
            candidates = [1]
        else:
            # If any neighbor already black, setting this black would violate; so white first
            if any(state[j] == 1 for j in neigh[i]):
                candidates = [0]
            else:
                # Try white then black
                candidates = [0, 1]

        for val in candidates:
            # Quick check: setting black adjacent to black invalid
            if val == 1 and any(state[j] == 1 for j in neigh[i]):
                continue

            new_state = state[:]  # small grid; copy is fine
            new_state[i] = val
            q = [i]
            if propagate(new_state, q):
                res = dfs(new_state)
                if res is not None:
                    return res
        return None

    state0 = [-1] * N
    if not initial_propagation(state0):
        return "No Solution"

    # Also run propagate with empty queue to enforce initial connectivity feasibility
    if not connectivity_ok(state0):
        return "No Solution"

    solved = dfs(state0)
    if solved is None:
        return "No Solution"

    # Build mask: 'B' for black else None
    out = [[None] * n for _ in range(n)]
    for i, v in enumerate(solved):
        r, c = rc(i)
        if v == 1:
            out[r][c] = "B"
    return str(out)

