# Slant / "Gokigen Naname" solver:
# - Place one diagonal in each N x N cell: '/' or '\'
# - Each clue dot (r,c) requires exactly that many incident diagonals.
# - No closed loops allowed in the segment graph.
#
# Human-like logic:
# 1) Degree constraints at each dot: incident count must match clue (tight bounds propagate).
# 2) Forced moves when a dot reaches required degree or cannot possibly reach it with remaining cells.
# 3) "No-loop" constraint enforced with Union-Find on dots using incremental cycle prevention.
# 4) Search uses MRV (minimum remaining values) with aggressive propagation; no naive brute force.

from collections import deque

def solve(observation):
    data = observation["data"]
    H = len(data)
    W = len(data[0]) if H else 0
    if H != W:
        return "No Solution"
    N = H - 1
    if N <= 0:
        return "No Solution"

    # Map each cell to its two possible edges between dots
    # '\' connects (r,c) - (r+1,c+1)
    # '/' connects (r,c+1) - (r+1,c)
    # We'll treat each cell as variable with domain {0:'\\', 1:'/'}.
    # Precompute for speed.
    def edge_for_cell(r, c, val):
        if val == 0:  # '\'
            a = (r, c)
            b = (r + 1, c + 1)
        else:         # '/'
            a = (r, c + 1)
            b = (r + 1, c)
        return a, b

    # For each dot, list incident (cell, val) possibilities that would touch it.
    inc = [[[] for _ in range(N + 1)] for __ in range(N + 1)]
    for r in range(N):
        for c in range(N):
            for val in (0, 1):
                a, b = edge_for_cell(r, c, val)
                inc[a[0]][a[1]].append((r, c, val))
                inc[b[0]][b[1]].append((r, c, val))

    # Variables and domains: -1 unassigned; else 0 or 1
    assign = [[-1] * N for _ in range(N)]
    # Domain masks: bit0 for '\' allowed, bit1 for '/' allowed; start with 0b11
    dom = [[3] * N for _ in range(N)]

    # Degree bookkeeping at dots
    req = data
    deg = [[0] * (N + 1) for _ in range(N + 1)]
    # Remaining possible incidents count for dot based on variable domains
    # We'll recompute locally when needed; maintain count for speed.
    rem = [[0] * (N + 1) for _ in range(N + 1)]

    # Union-Find for dots for no-loop constraint among selected edges.
    size = (N + 1) * (N + 1)
    parent = list(range(size))
    rank = [0] * size

    def idx(dot):
        return dot[0] * (N + 1) + dot[1]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # would make cycle
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    # We need rollback for backtracking: assignments, domain reductions, degrees, UF changes.
    # Implement UF with rollback stack.
    uf_stack = []

    def union_rb(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        # union by rank with rollback
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        # now rank[ra] >= rank[rb]
        uf_stack.append((rb, parent[rb], ra, rank[ra]))
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    def uf_mark():
        return len(uf_stack)

    def uf_rollback(mark):
        while len(uf_stack) > mark:
            rb, old_parent_rb, ra, old_rank_ra = uf_stack.pop()
            parent[rb] = old_parent_rb
            rank[ra] = old_rank_ra

    # Trail for other mutable structures
    trail = []

    def mark():
        return len(trail), uf_mark()

    def rollback(m):
        tmark, umark = m
        while len(trail) > tmark:
            op = trail.pop()
            typ = op[0]
            if typ == "A":
                r, c, old = op[1:]
                assign[r][c] = old
            elif typ == "D":
                r, c, old = op[1:]
                dom[r][c] = old
            elif typ == "G":
                r, c, old = op[1:]
                deg[r][c] = old
            else:
                raise RuntimeError("bad trail op")
        uf_rollback(umark)

    # Initialize rem counts
    def recompute_rem_at(r, c):
        cnt = 0
        for (cr, cc, val) in inc[r][c]:
            if assign[cr][cc] == -1:
                if dom[cr][cc] & (1 << val):
                    cnt += 1
            else:
                if assign[cr][cc] == val:
                    cnt += 0  # already accounted in deg; rem should count only unassigned potentials
        rem[r][c] = cnt

    def recompute_all_rem():
        for r in range(N + 1):
            for c in range(N + 1):
                recompute_rem_at(r, c)

    recompute_all_rem()

    # Queue-based propagation
    q = deque()

    def enqueue_dot(r, c):
        q.append(("dot", r, c))

    def enqueue_cell(r, c):
        q.append(("cell", r, c))

    for r in range(N + 1):
        for c in range(N + 1):
            if req[r][c] is not None:
                enqueue_dot(r, c)
    for r in range(N):
        for c in range(N):
            enqueue_cell(r, c)

    def set_domain(r, c, newmask):
        old = dom[r][c]
        if old == newmask:
            return True
        if newmask == 0:
            return False
        trail.append(("D", r, c, old))
        dom[r][c] = newmask
        enqueue_cell(r, c)
        # A domain change affects rem for the four dots around potentially (actually two per val),
        # easiest: enqueue the 4 corner dots; propagation will recompute rem via local check.
        for dr in (0, 1):
            for dc in (0, 1):
                enqueue_dot(r + dr, c + dc)
        return True

    def assign_cell(r, c, val):
        if assign[r][c] == val:
            return True
        if assign[r][c] != -1 and assign[r][c] != val:
            return False
        # ensure val allowed
        if not (dom[r][c] & (1 << val)):
            return False
        # set assignment
        trail.append(("A", r, c, assign[r][c]))
        assign[r][c] = val
        # fix domain to singleton
        if not set_domain(r, c, 1 << val):
            return False

        # Update degrees and UF with the chosen edge
        a, b = edge_for_cell(r, c, val)
        ar, ac = a
        br, bc = b

        # no-loop: union endpoints must not already be connected
        if not union_rb(idx(a), idx(b)):
            return False

        # degree increments
        trail.append(("G", ar, ac, deg[ar][ac]))
        deg[ar][ac] += 1
        trail.append(("G", br, bc, deg[br][bc]))
        deg[br][bc] += 1

        # Dot constraints affected
        enqueue_dot(ar, ac)
        enqueue_dot(br, bc)
        return True

    def dot_bounds_ok(r, c):
        clue = req[r][c]
        if clue is None:
            return True
        # recompute remaining potential incidents for this dot precisely
        recompute_rem_at(r, c)
        d = deg[r][c]
        # d <= clue <= d + rem
        if d > clue:
            return False
        if d + rem[r][c] < clue:
            return False
        return True

    def propagate():
        while q:
            typ, r, c = q.popleft()
            if typ == "dot":
                if req[r][c] is None:
                    continue
                if not dot_bounds_ok(r, c):
                    return False
                clue = req[r][c]
                d = deg[r][c]
                # compute candidate incidents among unassigned cells with domain allowing a val that hits this dot
                cand = []
                for (cr, cc, val) in inc[r][c]:
                    if assign[cr][cc] == -1 and (dom[cr][cc] & (1 << val)):
                        cand.append((cr, cc, val))
                need = clue - d
                if need == 0:
                    # forbid all remaining candidates (they must not connect to this dot)
                    for (cr, cc, val) in cand:
                        if not set_domain(cr, cc, dom[cr][cc] & ~(1 << val)):
                            return False
                elif need == len(cand):
                    # force all candidates to be chosen, meaning each involved cell must take that val
                    for (cr, cc, val) in cand:
                        if not assign_cell(cr, cc, val):
                            return False
                else:
                    # Additional local forcing:
                    # If a cell has only one value left, it will be handled by cell processing.
                    pass
            else:  # cell
                if assign[r][c] != -1:
                    continue
                m = dom[r][c]
                if m == 0:
                    return False
                # singleton domain -> assign
                if m == 1:
                    if not assign_cell(r, c, 0):
                        return False
                elif m == 2:
                    if not assign_cell(r, c, 1):
                        return False
                else:
                    # optional pruning: check if either choice would instantly violate dot max/min or create a cycle
                    allowed = 0
                    for val in (0, 1):
                        if not (m & (1 << val)):
                            continue
                        a, b = edge_for_cell(r, c, val)
                        ar, ac = a
                        br, bc = b
                        # cycle quick check
                        if find(idx(a)) == find(idx(b)):
                            continue
                        ok = True
                        # degree upper bound quick check
                        for (dr, dc) in ((ar, ac), (br, bc)):
                            clue = req[dr][dc]
                            if clue is not None and deg[dr][dc] + 1 > clue:
                                ok = False
                                break
                        if not ok:
                            continue
                        allowed |= (1 << val)
                    if allowed != m:
                        if not set_domain(r, c, allowed):
                            return False
        # Final global check on all dots bounds (cheap for typical sizes, but keep it light)
        for rr in range(N + 1):
            for cc in range(N + 1):
                if req[rr][cc] is not None:
                    if not dot_bounds_ok(rr, cc):
                        return False
        return True

    # Initial propagation
    if not propagate():
        return "No Solution"

    def is_complete():
        for r in range(N):
            for c in range(N):
                if assign[r][c] == -1:
                    return False
        return True

    def select_unassigned_cell():
        # MRV + degree heuristic
        best = None
        best_sz = 3
        best_score = -1
        for r in range(N):
            for c in range(N):
                if assign[r][c] != -1:
                    continue
                m = dom[r][c]
                sz = (m & 1) + ((m >> 1) & 1)
                if sz < best_sz:
                    best_sz = sz
                    best = (r, c)
                if sz == 2 and best_sz == 2:
                    # score by how constrained its corner dots are (with clues)
                    score = 0
                    for dr in (0, 1):
                        for dc in (0, 1):
                            clue = req[r + dr][c + dc]
                            if clue is not None:
                                score += 3
                    if score > best_score:
                        best_score = score
                        best = (r, c)
        return best

    def backtrack():
        if is_complete():
            # verify all dot exactness
            for r in range(N + 1):
                for c in range(N + 1):
                    clue = req[r][c]
                    if clue is not None and deg[r][c] != clue:
                        return False
            return True

        cell = select_unassigned_cell()
        if cell is None:
            return False
        r, c = cell
        m = dom[r][c]
        # Try values in an order guided by clue satisfaction: prefer adding edges to dots needing more degree.
        options = []
        for val in (0, 1):
            if m & (1 << val):
                a, b = edge_for_cell(r, c, val)
                score = 0
                for (dr, dc) in (a, b):
                    clue = req[dr][dc]
                    if clue is not None:
                        score += max(0, clue - deg[dr][dc])
                options.append((score, val))
        options.sort(reverse=True)

        for _, val in options:
            M = mark()
            if assign_cell(r, c, val) and propagate():
                if backtrack():
                    return True
            rollback(M)
        return False

    if not backtrack():
        return "No Solution"

    # Build answer grid
    out = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append("\\" if assign[r][c] == 0 else "/")
        out.append(row)
    return out


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [1, None, None, None, None], [5, None, None, None, None]], 'horizontal': {'(0, 0.5)': '<', '(0, 1.5)': '<', '(2, 1.5)': '<', '(2, 3.5)': '>' , '(4, 3.5)': '>'}, 'vertical': {'(0.5, 1)': '^', '(1.5, 0)': '^', '(1.5, 4)': '^', '(2.5, 2)': '^', '(3.5, 3)': '^'}}

from collections import deque

# Futoshiki solver with strong constraint propagation + MRV search.
# Human-like techniques implemented:
#  - Domain initialization from givens
#  - Latin constraints (row/col all-different) via elimination
#  - Inequality constraints as arc-consistency (AC-3 style) plus bounds tightening
#  - Hidden singles in rows/cols
#  - MRV + degree heuristic branching (minimal remaining values; pick most constrained cell)
#  - Forward-checking with incremental propagation

def solve(observation):
    data = observation["data"]
    N = len(data)
    H = observation.get("horizontal", {})
    V = observation.get("vertical", {})

    # Parse inequality constraints into directed edges: (a -> b) meaning a < b
    lt_edges = []

    # Horizontal: key "(r, c+0.5)" between (r,c) and (r,c+1)
    for k, sym in H.items():
        r, c = _parse_key(k)
        # c is x.5 => between left col=int(c-0.5) and right col=int(c+0.5)
        left = int(c - 0.5)
        right = left + 1
        a = (int(r), left)
        b = (int(r), right)
        if sym == "<":
            lt_edges.append((a, b))
        elif sym == ">":
            lt_edges.append((b, a))
        else:
            return "No Solution"

    # Vertical: key "(r+0.5, c)" between (r,c) and (r+1,c)
    # Symbols: '^' or 'v'. Here interpret '^' as top < bottom (arrow points to smaller on top visually),
    # and 'v' as top > bottom. This matches common futoshiki notation.
    for k, sym in V.items():
        r, c = _parse_key(k)
        top = int(r - 0.5)
        bot = top + 1
        a = (top, int(c))
        b = (bot, int(c))
        if sym == "^":
            lt_edges.append((a, b))  # top < bottom
        elif sym.lower() == "v":
            lt_edges.append((b, a))  # bottom < top
        else:
            return "No Solution"

    # Domains: bitmask over 1..N
    FULL = (1 << N) - 1
    dom = [[FULL for _ in range(N)] for _ in range(N)]

    # Apply givens
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                dom[r][c] = 1 << (v - 1)

    # Precompute neighbors for inequalities
    lt_out = [[] for _ in range(N * N)]  # idx -> list of idx that must be greater
    lt_in = [[] for _ in range(N * N)]   # idx -> list of idx that must be smaller
    for a, b in lt_edges:
        ia = a[0] * N + a[1]
        ib = b[0] * N + b[1]
        lt_out[ia].append(ib)
        lt_in[ib].append(ia)

    # Row/col membership lists
    rows = [[r * N + c for c in range(N)] for r in range(N)]
    cols = [[r * N + c for r in range(N)] for c in range(N)]

    # Initial propagation
    state = _State(N, dom, lt_out, lt_in, rows, cols)
    if not state.propagate_all():
        return "No Solution"

    # Search
    sol = _search(state)
    if sol is None:
        return "No Solution"
    grid = sol.to_grid()
    return str(grid)

def _parse_key(s):
    # s like "(0, 0.5)"
    s = s.strip()
    if s[0] == "(" and s[-1] == ")":
        s = s[1:-1]
    a, b = s.split(",")
    return float(a.strip()), float(b.strip())

def _lsb_index(x):
    return (x & -x).bit_length() - 1

def _popcount(x):
    return x.bit_count()

def _mask_min(mask):
    # minimum value in domain
    return _lsb_index(mask) + 1

def _mask_max(mask):
    # maximum value in domain
    return (mask.bit_length() - 1) + 1

def _mask_to_values(mask):
    while mask:
        b = mask & -mask
        yield (b.bit_length() - 1) + 1
        mask ^= b

class _State:
    __slots__ = ("N", "dom", "lt_out", "lt_in", "rows", "cols")

    def __init__(self, N, dom, lt_out, lt_in, rows, cols):
        self.N = N
        # deep copy domains for safety
        self.dom = [row[:] for row in dom]
        self.lt_out = lt_out
        self.lt_in = lt_in
        self.rows = rows
        self.cols = cols

    def clone(self):
        return _State(self.N, self.dom, self.lt_out, self.lt_in, self.rows, self.cols)

    def to_grid(self):
        N = self.N
        out = [[None] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                m = self.dom[r][c]
                if m and (m & (m - 1)) == 0:
                    out[r][c] = _lsb_index(m) + 1
                else:
                    out[r][c] = None
        return out

    def is_solved(self):
        for r in range(self.N):
            for c in range(self.N):
                m = self.dom[r][c]
                if m == 0 or (m & (m - 1)) != 0:
                    return False
        return True

    def propagate_all(self):
        # Repeat until fixpoint using queue of affected cells and unit/hidden rules
        N = self.N
        q = deque()
        inq = [[False]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                q.append((r, c))
                inq[r][c] = True

        while q:
            r, c = q.popleft()
            inq[r][c] = False
            if not self._prune_cell(r, c, q, inq):
                return False

        # Hidden singles pass (may trigger new singles leading to more propagation)
        changed = True
        while changed:
            changed = False
            if not self._hidden_singles_all(q, inq):
                return False
            while q:
                r, c = q.popleft()
                inq[r][c] = False
                if not self._prune_cell(r, c, q, inq):
                    return False
                changed = True
        return True

    def _enqueue_related(self, r, c, q, inq):
        N = self.N
        # row/col peers
        for cc in range(N):
            if cc != c and not inq[r][cc]:
                q.append((r, cc)); inq[r][cc] = True
        for rr in range(N):
            if rr != r and not inq[rr][c]:
                q.append((rr, c)); inq[rr][c] = True
        # inequality neighbors
        idx = r * N + c
        for j in self.lt_out[idx]:
            rr, cc = divmod(j, N)
            if not inq[rr][cc]:
                q.append((rr, cc)); inq[rr][cc] = True
        for j in self.lt_in[idx]:
            rr, cc = divmod(j, N)
            if not inq[rr][cc]:
                q.append((rr, cc)); inq[rr][cc] = True

    def _prune_cell(self, r, c, q, inq):
        N = self.N
        m = self.dom[r][c]
        if m == 0:
            return False

        # Latin elimination from fixed peers
        # Remove values already fixed in row/col
        row_forbidden = 0
        for cc in range(N):
            if cc == c: 
                continue
            mm = self.dom[r][cc]
            if mm and (mm & (mm - 1)) == 0:
                row_forbidden |= mm
        col_forbidden = 0
        for rr in range(N):
            if rr == r:
                continue
            mm = self.dom[rr][c]
            if mm and (mm & (mm - 1)) == 0:
                col_forbidden |= mm

        nm = m & ~(row_forbidden | col_forbidden)
        if nm == 0:
            return False

        # Inequality pruning: enforce arc consistency with neighbors
        idx = r * N + c

        # For each constraint cell < nb: remove values that have no support in nb
        # Support condition: for value x in cell, exists y in nb domain s.t. x < y
        # Equivalent: x < max(nb)
        for j in self.lt_out[idx]:
            rr, cc = divmod(j, N)
            nb = self.dom[rr][cc]
            if nb == 0:
                return False
            nb_max = _mask_max(nb)
            # remove values >= nb_max
            if nb_max <= N:
                cutoff = nb_max  # keep values 1..cutoff-1
                keep = (1 << (cutoff - 1)) - 1 if cutoff > 1 else 0
                nm2 = nm & keep
                if nm2 == 0:
                    return False
                nm = nm2

        # For each constraint nb < cell: remove values that have no support in nb
        # Support: exists y in nb s.t. y < x => x > min(nb)
        for j in self.lt_in[idx]:
            rr, cc = divmod(j, N)
            nb = self.dom[rr][cc]
            if nb == 0:
                return False
            nb_min = _mask_min(nb)
            # remove values <= nb_min
            if nb_min >= 1:
                # keep values nb_min+1..N
                keep = FULL_MASK(N) ^ ((1 << nb_min) - 1)
                nm2 = nm & keep
                if nm2 == 0:
                    return False
                nm = nm2

        if nm != m:
            self.dom[r][c] = nm
            self._enqueue_related(r, c, q, inq)

            # If newly fixed, also remove from peers immediately (enqueue peers already done)
            if (nm & (nm - 1)) == 0:
                pass

        # Additionally, try to tighten neighbors based on this cell's bounds (bidirectional bounds tightening)
        # If cell < nb then nb_min >= cell_min+1; if nb < cell then nb_max <= cell_max-1
        # We apply this as queue-based propagation by enqueuing neighbors, which _prune_cell will use.
        return True

    def _hidden_singles_all(self, q, inq):
        # If a value appears in only one domain in a row/col, fix it.
        N = self.N
        changed = False

        # Rows
        for r in range(N):
            # count occurrences of each value via bitmasks
            pos = [0] * N  # bitmask of columns where value is possible
            for c in range(N):
                m = self.dom[r][c]
                if m == 0:
                    return False
                for v in _mask_to_values(m):
                    pos[v-1] |= (1 << c)
            for v in range(N):
                cols_mask = pos[v]
                if cols_mask == 0:
                    return False
                if cols_mask & (cols_mask - 1) == 0:
                    c = _lsb_index(cols_mask)
                    target = 1 << v
                    if self.dom[r][c] != target:
                        if (self.dom[r][c] & target) == 0:
                            return False
                        self.dom[r][c] = target
                        self._enqueue_related(r, c, q, inq)
                        changed = True

        # Cols
        for c in range(N):
            pos = [0] * N  # bitmask of rows where value is possible
            for r in range(N):
                m = self.dom[r][c]
                if m == 0:
                    return False
                for v in _mask_to_values(m):
                    pos[v-1] |= (1 << r)
            for v in range(N):
                rows_mask = pos[v]
                if rows_mask == 0:
                    return False
                if rows_mask & (rows_mask - 1) == 0:
                    r = _lsb_index(rows_mask)
                    target = 1 << v
                    if self.dom[r][c] != target:
                        if (self.dom[r][c] & target) == 0:
                            return False
                        self.dom[r][c] = target
                        self._enqueue_related(r, c, q, inq)
                        changed = True

        return True

def FULL_MASK(N):
    return (1 << N) - 1

def _pick_mrv_cell(state: _State):
    N = state.N
    best = None
    best_size = 10**9
    best_degree = -1
    for r in range(N):
        for c in range(N):
            m = state.dom[r][c]
            if m == 0:
                return None
            if (m & (m - 1)) == 0:
                continue
            sz = _popcount(m)
            if sz < best_size:
                best_size = sz
                best = (r, c)
                best_degree = _degree(state, r, c)
            elif sz == best_size:
                deg = _degree(state, r, c)
                if deg > best_degree:
                    best_degree = deg
                    best = (r, c)
    return best

def _degree(state, r, c):
    # Approx degree: number of unsolved peers plus inequality neighbors
    N = state.N
    d = 0
    for cc in range(N):
        if cc != c:
            m = state.dom[r][cc]
            if m and (m & (m - 1)) != 0:
                d += 1
    for rr in range(N):
        if rr != r:
            m = state.dom[rr][c]
            if m and (m & (m - 1)) != 0:
                d += 1
    idx = r * N + c
    for j in state.lt_out[idx]:
        rr, cc = divmod(j, N)
        m = state.dom[rr][cc]
        if m and (m & (m - 1)) != 0:
            d += 1
    for j in state.lt_in[idx]:
        rr, cc = divmod(j, N)
        m = state.dom[rr][cc]
        if m and (m & (m - 1)) != 0:
            d += 1
    return d

def _order_values_lcv(state: _State, r, c):
    # Least constraining value: estimate eliminations in row/col and inequality neighbors.
    N = state.N
    m = state.dom[r][c]
    vals = list(_mask_to_values(m))
    if len(vals) <= 1:
        return vals

    peers = []
    for cc in range(N):
        if cc != c:
            peers.append((r, cc))
    for rr in range(N):
        if rr != r:
            peers.append((rr, c))
    idx = r * N + c
    for j in state.lt_out[idx]:
        peers.append(divmod(j, N))
    for j in state.lt_in[idx]:
        peers.append(divmod(j, N))

    # Unique peers
    peers = list({p for p in peers if (state.dom[p[0]][p[1]] & (state.dom[p[0]][p[1]] - 1)) != 0})

    def cost(v):
        bit = 1 << (v - 1)
        eliminated = 0
        # Latin: peers can't take v if same row/col
        for (rr, cc) in peers:
            if rr == r or cc == c:
                if state.dom[rr][cc] & bit:
                    eliminated += 1
        # Inequalities: rough bound impacts
        # If cell < nb then nb cannot be <= v ; if nb < cell then nb cannot be >= v
        idx0 = r * N + c
        for j in state.lt_out[idx0]:
            rr, cc = divmod(j, N)
            nb = state.dom[rr][cc]
            # eliminate values <= v
            eliminated += _popcount(nb & ((1 << v) - 1))
        for j in state.lt_in[idx0]:
            rr, cc = divmod(j, N)
            nb = state.dom[rr][cc]
            # eliminate values >= v
            eliminated += _popcount(nb & (FULL_MASK(N) ^ ((1 << (v - 1)) - 1)))
        return eliminated

    vals.sort(key=cost)
    return vals

def _search(state: _State):
    if state.is_solved():
        return state

    cell = _pick_mrv_cell(state)
    if cell is None:
        return None
    r, c = cell

    for v in _order_values_lcv(state, r, c):
        ns = state.clone()
        bit = 1 << (v - 1)
        if (ns.dom[r][c] & bit) == 0:
            continue
        ns.dom[r][c] = bit
        if ns.propagate_all():
            res = _search(ns)
            if res is not None:
                return res
    return None

if __name__ == "__main__":
    print(solve(OBSERVATION))

