from __future__ import annotations

def solve(observation):
    data = observation["data"]
    N = len(data)
    Hraw = observation.get("horizontal", {}) or {}
    Vraw = observation.get("vertical", {}) or {}

    # Parse constraints into directed edges: a < b constraints
    lt_edges = [[] for _ in range(N * N)]  # u -> v means u < v
    gt_edges = [[] for _ in range(N * N)]  # u -> v means u > v (reverse)
    neigh = [[] for _ in range(N * N)]     # adjacency (both directions) for propagation

    def idx(r, c): return r * N + c

    # Horizontal constraints at (r, c+0.5): between (r,c) and (r,c+1)
    for k, sym in Hraw.items():
        try:
            r, x = eval(k, {}, {})
        except Exception:
            continue
        if not (isinstance(r, (int, float)) and isinstance(x, (int, float))):
            continue
        if abs(x - (int(x) + 0.5)) > 1e-9:
            continue
        r = int(r)
        c = int(x - 0.5)
        if not (0 <= r < N and 0 <= c < N - 1):
            continue
        a = idx(r, c)
        b = idx(r, c + 1)
        if sym == "<":
            lt_edges[a].append(b)
            gt_edges[b].append(a)
        elif sym == ">":
            lt_edges[b].append(a)
            gt_edges[a].append(b)
        else:
            continue
        neigh[a].append(b)
        neigh[b].append(a)

    # Vertical constraints at (r+0.5, c): between (r,c) and (r+1,c)
    # Convention: '^' means top < bottom; 'v' means top > bottom (as in typical Futoshiki)
    for k, sym in Vraw.items():
        if sym not in ("^", "v"):
            continue
        try:
            y, c = eval(k, {}, {})
        except Exception:
            continue
        if not (isinstance(y, (int, float)) and isinstance(c, (int, float))):
            continue
        if abs(y - (int(y) + 0.5)) > 1e-9:
            continue
        c = int(c)
        r = int(y - 0.5)
        if not (0 <= r < N - 1 and 0 <= c < N):
            continue
        top = idx(r, c)
        bot = idx(r + 1, c)
        if sym == "^":
            lt_edges[top].append(bot)
            gt_edges[bot].append(top)
        else:  # 'v'
            lt_edges[bot].append(top)
            gt_edges[top].append(bot)
        neigh[top].append(bot)
        neigh[bot].append(top)

    ALL = (1 << N) - 1
    fullmask = [ALL] * (N * N)

    # Row/col peer lists
    row_peers = [[] for _ in range(N * N)]
    col_peers = [[] for _ in range(N * N)]
    for r in range(N):
        for c in range(N):
            i = idx(r, c)
            row = [idx(r, cc) for cc in range(N) if cc != c]
            col = [idx(rr, c) for rr in range(N) if rr != r]
            row_peers[i] = row
            col_peers[i] = col

    # Bit helpers
    def bit(v): return 1 << (v - 1)

    def is_single(m): return m and (m & (m - 1)) == 0

    def lowbit_index(m):
        # return 1..N for singleton
        return (m.bit_length() - 1) + 1

    def popcount(x): return x.bit_count()

    # Initialize domains with givens
    dom = fullmask[:]
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                dom[idx(r, c)] = bit(v)

    # Precompute transitive bounds (cheap) per node based on chain lengths:
    # We'll iteratively propagate inequality-induced min/max bounds during solving instead of heavy precompute.

    # Constraint propagation engine
    from collections import deque

    def revise_ineq(u, v, dom_u, dom_v):
        # Enforce u < v
        # Remove values from u that are >= max(v) ; remove values from v that are <= min(u)
        if dom_u == 0 or dom_v == 0:
            return 0, 0, True
        min_u = (dom_u & -dom_u).bit_length()  # 1..N
        max_u = dom_u.bit_length()
        min_v = (dom_v & -dom_v).bit_length()
        max_v = dom_v.bit_length()

        # u must be <= max_v-1
        if max_v <= 1:
            return 0, 0, True
        allowed_u = dom_u & ((1 << (max_v - 1)) - 1)
        # v must be >= min_u+1
        if min_u >= N:
            return 0, 0, True
        allowed_v = dom_v & (~((1 << min_u) - 1) & ALL)
        return allowed_u, allowed_v, (allowed_u == 0 or allowed_v == 0)

    def propagate(dom):
        q = deque()
        inq = [False] * (N * N)
        # seed with all variables that are fixed or have constraints
        for i in range(N * N):
            if is_single(dom[i]) or lt_edges[i] or gt_edges[i]:
                q.append(i)
                inq[i] = True

        # For hidden singles in rows/cols, we need fast availability tracking; do incremental recomputation
        while q:
            i = q.popleft()
            inq[i] = False
            di = dom[i]
            if di == 0:
                return False

            # 1) Row/col all-different forward-checking for fixed values
            if is_single(di):
                vbit = di
                # remove from row peers
                for p in row_peers[i]:
                    dp = dom[p]
                    if dp & vbit:
                        ndp = dp & ~vbit
                        if ndp == 0:
                            return False
                        if ndp != dp:
                            dom[p] = ndp
                            if not inq[p]:
                                q.append(p); inq[p] = True
                # remove from col peers
                for p in col_peers[i]:
                    dp = dom[p]
                    if dp & vbit:
                        ndp = dp & ~vbit
                        if ndp == 0:
                            return False
                        if ndp != dp:
                            dom[p] = ndp
                            if not inq[p]:
                                q.append(p); inq[p] = True

            # 2) Inequality propagation with bounds tightening
            # i < j
            for j in lt_edges[i]:
                dj = dom[j]
                ni, nj, bad = revise_ineq(i, j, dom[i], dj)
                if bad:
                    return False
                if ni != dom[i]:
                    dom[i] = ni
                    if not inq[i]:
                        q.append(i); inq[i] = True
                if nj != dj:
                    dom[j] = nj
                    if not inq[j]:
                        q.append(j); inq[j] = True

            # k < i  (i is greater)
            for k in gt_edges[i]:
                dk = dom[k]
                nk, ni, bad = revise_ineq(k, i, dk, dom[i])
                if bad:
                    return False
                if nk != dk:
                    dom[k] = nk
                    if not inq[k]:
                        q.append(k); inq[k] = True
                if ni != dom[i]:
                    dom[i] = ni
                    if not inq[i]:
                        q.append(i); inq[i] = True

            # 3) Hidden singles in row and column (human-like scanning)
            r = i // N
            c = i % N
            # Row scan
            row_idxs = [idx(r, cc) for cc in range(N)]
            # Compute value -> location count
            # Do cheap scan: for each value bit, count occurrences.
            avail = [0] * N
            loc = [-1] * N
            for pos in row_idxs:
                m = dom[pos]
                while m:
                    b = m & -m
                    v = b.bit_length()  # 1..N
                    vi = v - 1
                    avail[vi] += 1
                    loc[vi] = pos if avail[vi] == 1 else loc[vi]
                    m -= b
            for vi, cnt in enumerate(avail):
                if cnt == 0:
                    return False
                if cnt == 1:
                    p = loc[vi]
                    target = 1 << vi
                    if dom[p] != target:
                        dom[p] = target
                        if not inq[p]:
                            q.append(p); inq[p] = True

            # Column scan
            col_idxs = [idx(rr, c) for rr in range(N)]
            avail = [0] * N
            loc = [-1] * N
            for pos in col_idxs:
                m = dom[pos]
                while m:
                    b = m & -m
                    v = b.bit_length()
                    vi = v - 1
                    avail[vi] += 1
                    loc[vi] = pos if avail[vi] == 1 else loc[vi]
                    m -= b
            for vi, cnt in enumerate(avail):
                if cnt == 0:
                    return False
                if cnt == 1:
                    p = loc[vi]
                    target = 1 << vi
                    if dom[p] != target:
                        dom[p] = target
                        if not inq[p]:
                            q.append(p); inq[p] = True

        return True

    # Additional inequality "extreme" rule: if u < v and u can take N then impossible, etc.
    # This is naturally covered by revise_ineq, but we'll strengthen by iterative local arc consistency through propagate.

    # Heuristic variable selection: smallest domain, tie-breaker highest constraint degree
    degrees = [len(row_peers[i]) + len(col_peers[i]) + len(neigh[i]) for i in range(N * N)]

    def select_var(dom):
        best = -1
        best_sz = 10**9
        best_deg = -1
        for i in range(N * N):
            if not is_single(dom[i]):
                sz = popcount(dom[i])
                if sz < best_sz or (sz == best_sz and degrees[i] > best_deg):
                    best = i
                    best_sz = sz
                    best_deg = degrees[i]
                    if best_sz == 2 and best_deg > 0:
                        # can't do better than 2 in most cases; keep scanning lightly
                        pass
        return best

    def order_values(i, dom):
        # Least-constraining value: simulate removal effect on peers via row/col and inequalities quickly
        m = dom[i]
        vals = []
        while m:
            b = m & -m
            v = b.bit_length()
            m -= b
            score = 0
            # count how many peers currently allow v
            vb = 1 << (v - 1)
            for p in row_peers[i]:
                score += 1 if (dom[p] & vb) else 0
            for p in col_peers[i]:
                score += 1 if (dom[p] & vb) else 0
            # inequality rough: prefer values that don't violate bounds quickly
            # (lower value for "less-than" source, higher value for "greater-than" source)
            score += 0
            vals.append((score, v))
        vals.sort(reverse=True)  # keep more flexible first
        return [v for _, v in vals]

    def dfs(dom):
        if not propagate(dom):
            return None
        i = select_var(dom)
        if i == -1:
            return dom  # solved

        for v in order_values(i, dom):
            ndom = dom[:]
            ndom[i] = bit(v)
            res = dfs(ndom)
            if res is not None:
                return res
        return None

    dom0 = dom[:]
    res = dfs(dom0)
    if res is None:
        return "No Solution"

    grid = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            m = res[idx(r, c)]
            if not is_single(m):
                return "No Solution"
            grid[r][c] = lowbit_index(m)
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [0, 0, 0, 0], 'D': [0, 0, 0, 0], 'L': [0, 2, 0, 0], 'R': [1, 0, 3, 0]}
# Generalized Skyscrapers solver (NxN).
# Human-like mechanics implemented:
# - Precompute all row/col permutations (Latin constraint) and their visibility counts.
# - Domain filtering per line by side clues.
# - Constraint propagation by:
#   - Intersecting cell candidates from remaining line options
#   - Eliminating line options inconsistent with per-cell candidates
# - Search with MRV heuristic on the most constrained line (row/col), not on individual cells.
# - Fast incremental checking of opposite-direction clue compatibility.

from itertools import permutations

def _visible_count(seq):
    m = 0
    c = 0
    for v in seq:
        if v > m:
            m = v
            c += 1
    return c

def _prepare(N):
    perms = list(permutations(range(1, N + 1)))
    visL = [_visible_count(p) for p in perms]
    visR = [_visible_count(p[::-1]) for p in perms]
    # buckets: (left_clue, right_clue) with 0 meaning "no clue"
    buckets = {}
    for idx, p in enumerate(perms):
        l = visL[idx]
        r = visR[idx]
        # Insert into all compatible clue buckets including 0 wildcards
        for cl in (0, l):
            for cr in (0, r):
                buckets.setdefault((cl, cr), []).append(idx)
    return perms, visL, visR, buckets

def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    N = len(U)
    if not (len(D) == len(L) == len(R) == N):
        return "No Solution"

    perms, visL, visR, buckets = _prepare(N)

    # Options for each row and column are indices into perms
    row_opts = [set(buckets.get((L[r], R[r]), [])) for r in range(N)]
    col_opts = [set(buckets.get((U[c], D[c]), [])) for c in range(N)]

    if any(len(s) == 0 for s in row_opts) or any(len(s) == 0 for s in col_opts):
        return "No Solution"

    # Cell candidates as bitmask over values 1..N (bit i means value i possible)
    FULL_MASK = (1 << (N + 1)) - 2  # bits 1..N set
    cell_mask = [[FULL_MASK for _ in range(N)] for _ in range(N)]

    # Precompute for each line option list, per-position possible value mask union
    # For speed, cache masks per (is_row, index) recomputed when options shrink.
    def recompute_line_pos_masks(is_row, idx, opts_set):
        # returns list of masks length N where mask has bits of possible values at pos
        pos_masks = [0] * N
        for pid in opts_set:
            p = perms[pid]
            for j, v in enumerate(p):
                pos_masks[j] |= 1 << v
        return pos_masks

    # Constraint propagation loop
    def propagate(row_opts, col_opts, cell_mask):
        changed = True
        # For caching positional masks, store alongside a version via size
        row_cache = [(None, -1) for _ in range(N)]  # (pos_masks, size)
        col_cache = [(None, -1) for _ in range(N)]

        def get_row_pos_masks(r):
            pm, sz = row_cache[r]
            if sz != len(row_opts[r]):
                pm = recompute_line_pos_masks(True, r, row_opts[r])
                row_cache[r] = (pm, len(row_opts[r]))
            return pm

        def get_col_pos_masks(c):
            pm, sz = col_cache[c]
            if sz != len(col_opts[c]):
                pm = recompute_line_pos_masks(False, c, col_opts[c])
                col_cache[c] = (pm, len(col_opts[c]))
            return pm

        while changed:
            changed = False

            # 1) Update cell masks from row/col option unions (intersection)
            for r in range(N):
                rpm = get_row_pos_masks(r)
                for c in range(N):
                    cm = cell_mask[r][c]
                    nm = cm & rpm[c]
                    if nm != cm:
                        if nm == 0:
                            return False
                        cell_mask[r][c] = nm
                        changed = True
            for c in range(N):
                cpm = get_col_pos_masks(c)
                for r in range(N):
                    cm = cell_mask[r][c]
                    nm = cm & cpm[r]
                    if nm != cm:
                        if nm == 0:
                            return False
                        cell_mask[r][c] = nm
                        changed = True

            # 2) Filter row options by cell masks and column compatibility (value uniqueness implied by permutations)
            for r in range(N):
                if len(row_opts[r]) == 1:
                    continue
                newset = None
                for pid in row_opts[r]:
                    p = perms[pid]
                    ok = True
                    for c, v in enumerate(p):
                        if not (cell_mask[r][c] >> v) & 1:
                            ok = False
                            break
                    if ok:
                        if newset is None:
                            newset = {pid}
                        else:
                            newset.add(pid)
                if newset is None or len(newset) == 0:
                    return False
                if len(newset) != len(row_opts[r]):
                    row_opts[r] = newset
                    row_cache[r] = (None, -1)
                    changed = True

            # 3) Filter column options by cell masks
            for c in range(N):
                if len(col_opts[c]) == 1:
                    continue
                newset = None
                for pid in col_opts[c]:
                    p = perms[pid]
                    ok = True
                    for r, v in enumerate(p):
                        if not (cell_mask[r][c] >> v) & 1:
                            ok = False
                            break
                    if ok:
                        if newset is None:
                            newset = {pid}
                        else:
                            newset.add(pid)
                if newset is None or len(newset) == 0:
                    return False
                if len(newset) != len(col_opts[c]):
                    col_opts[c] = newset
                    col_cache[c] = (None, -1)
                    changed = True

            # 4) Cross-prune: enforce row/col agreement on each cell by removing line options
            # This is stronger than mask intersection because it removes options that no longer have support in perpendicular line options.
            # For each cell (r,c), build allowed values from col options at that row and vice versa.
            for r in range(N):
                for c in range(N):
                    allowed_from_col = 0
                    for pid in col_opts[c]:
                        allowed_from_col |= 1 << perms[pid][r]
                    allowed_from_row = 0
                    for pid in row_opts[r]:
                        allowed_from_row |= 1 << perms[pid][c]
                    nm = cell_mask[r][c] & allowed_from_col & allowed_from_row
                    if nm != cell_mask[r][c]:
                        if nm == 0:
                            return False
                        cell_mask[r][c] = nm
                        changed = True

        return True

    # Helper: check completion and build grid if solved
    def is_solved(row_opts, col_opts):
        return all(len(s) == 1 for s in row_opts) and all(len(s) == 1 for s in col_opts)

    def build_grid_from_rows(row_opts):
        grid = [[0]*N for _ in range(N)]
        for r in range(N):
            pid = next(iter(row_opts[r]))
            p = perms[pid]
            grid[r] = list(p)
        return grid

    # Search on lines (rows/cols) with MRV
    def dfs(row_opts, col_opts, cell_mask):
        if not propagate(row_opts, col_opts, cell_mask):
            return None
        if is_solved(row_opts, col_opts):
            # Validate columns match their single option too
            grid = build_grid_from_rows(row_opts)
            # Ensure column options are consistent
            for c in range(N):
                col = tuple(grid[r][c] for r in range(N))
                pid = next(iter(col_opts[c]))
                if perms[pid] != col:
                    return None
            return grid

        # Choose most constrained unsolved line among rows and cols
        best_is_row = True
        best_idx = -1
        best_size = 10**9
        for r in range(N):
            sz = len(row_opts[r])
            if 1 < sz < best_size:
                best_size = sz
                best_is_row = True
                best_idx = r
        for c in range(N):
            sz = len(col_opts[c])
            if 1 < sz < best_size:
                best_size = sz
                best_is_row = False
                best_idx = c

        if best_idx == -1:
            return None

        # Value-ordering: try options that best fit current perpendicular constraints (least conflicts)
        if best_is_row:
            r = best_idx
            opts = list(row_opts[r])
            def score(pid):
                p = perms[pid]
                sc = 0
                for c, v in enumerate(p):
                    sc += 0 if (cell_mask[r][c] >> v) & 1 else 1000
                    # prefer values that appear in many column options at that row position
                    cnt = 0
                    for cpid in col_opts[c]:
                        if perms[cpid][r] == v:
                            cnt += 1
                    sc -= cnt
                return sc
            opts.sort(key=score)
            for pid in opts:
                new_row_opts = [s.copy() for s in row_opts]
                new_col_opts = [s.copy() for s in col_opts]
                new_cell = [row[:] for row in cell_mask]
                new_row_opts[r] = {pid}
                # tighten cell masks of that row to exact values
                p = perms[pid]
                for c, v in enumerate(p):
                    new_cell[r][c] = 1 << v
                res = dfs(new_row_opts, new_col_opts, new_cell)
                if res is not None:
                    return res
        else:
            c = best_idx
            opts = list(col_opts[c])
            def score(pid):
                p = perms[pid]
                sc = 0
                for r, v in enumerate(p):
                    sc += 0 if (cell_mask[r][c] >> v) & 1 else 1000
                    cnt = 0
                    for rpid in row_opts[r]:
                        if perms[rpid][c] == v:
                            cnt += 1
                    sc -= cnt
                return sc
            opts.sort(key=score)
            for pid in opts:
                new_row_opts = [s.copy() for s in row_opts]
                new_col_opts = [s.copy() for s in col_opts]
                new_cell = [row[:] for row in cell_mask]
                new_col_opts[c] = {pid}
                p = perms[pid]
                for r, v in enumerate(p):
                    new_cell[r][c] = 1 << v
                res = dfs(new_row_opts, new_col_opts, new_cell)
                if res is not None:
                    return res

        return None

    sol = dfs(row_opts, col_opts, cell_mask)
    return sol if sol is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [0, 1, 2, 3], 'D': [0, 0, 0, 0], 'L': [0, 0, 0, 0], 'R': [3, 3, 0, 2]}
from itertools import permutations

# Skyscrapers solver with strong human-like propagation:
# - Precompute all row/col permutations (Latin constraint) and filter by side clues.
# - Maintain candidate sets for each row and column (domain filtering).
# - Iteratively propagate:
#   * Intersection (cell-wise) constraints between row/col candidate sets
#   * Remove inconsistent row/col candidates using allowed values per cell
# - If not solved, branch on the most constrained row/col (fewest candidates).

def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c

def clue_ok(seq, left_clue, right_clue):
    if left_clue and visible_count(seq) != left_clue:
        return False
    if right_clue and visible_count(reversed(seq)) != right_clue:
        return False
    return True

def transpose(grid):
    return [list(col) for col in zip(*grid)]

def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    N = len(U)

    all_perms = list(permutations(range(1, N + 1)))

    # Precompute row candidates per row index by L/R clue
    row_cands = []
    for r in range(N):
        lc, rc = L[r], R[r]
        row_cands.append([p for p in all_perms if clue_ok(p, lc, rc)])

    # Precompute col candidates per col index by U/D clue
    col_cands = []
    for c in range(N):
        uc, dc = U[c], D[c]
        col_cands.append([p for p in all_perms if clue_ok(p, uc, dc)])

    # For speed: represent candidates as lists; derive allowed values per cell on the fly.
    def propagate(row_cands, col_cands):
        # Returns (row_cands, col_cands) pruned or (None, None) if contradiction.
        N = len(row_cands)
        changed = True
        while changed:
            changed = False

            # Compute allowed values per cell based on current row/col candidates
            row_allowed = [[set() for _ in range(N)] for _ in range(N)]
            col_allowed = [[set() for _ in range(N)] for _ in range(N)]

            for r in range(N):
                if not row_cands[r]:
                    return None, None
                for p in row_cands[r]:
                    for c, v in enumerate(p):
                        row_allowed[r][c].add(v)

            for c in range(N):
                if not col_cands[c]:
                    return None, None
                for p in col_cands[c]:
                    for r, v in enumerate(p):
                        col_allowed[r][c].add(v)

            # Cell intersection: allowed[r][c] must be in both
            cell_allowed = [[row_allowed[r][c] & col_allowed[r][c] for c in range(N)] for r in range(N)]
            for r in range(N):
                for c in range(N):
                    if not cell_allowed[r][c]:
                        return None, None

            # Prune row candidates inconsistent with cell_allowed
            for r in range(N):
                before = len(row_cands[r])
                if before > 1:
                    allowed_row = cell_allowed[r]
                    new_list = [p for p in row_cands[r] if all(p[c] in allowed_row[c] for c in range(N))]
                    if not new_list:
                        return None, None
                    if len(new_list) != before:
                        row_cands[r] = new_list
                        changed = True

            # Prune col candidates inconsistent with cell_allowed
            for c in range(N):
                before = len(col_cands[c])
                if before > 1:
                    new_list = []
                    for p in col_cands[c]:
                        ok = True
                        for r in range(N):
                            if p[r] not in cell_allowed[r][c]:
                                ok = False
                                break
                        if ok:
                            new_list.append(p)
                    if not new_list:
                        return None, None
                    if len(new_list) != before:
                        col_cands[c] = new_list
                        changed = True

            # Additional Latin constraint pruning via bipartite feasibility per row/col:
            # If a number cannot appear in a column position across all candidates, prune earlier.
            # (Already largely handled by cell_allowed, but this tightens in some cases.)
            for r in range(N):
                # ensure each value 1..N is possible somewhere in this row candidates (it always is, but check)
                # also enforce per-column position: if any position has singleton allowed, propagate implicitly by pruning
                pass

        return row_cands, col_cands

    def is_solved(row_cands, col_cands):
        return all(len(rc) == 1 for rc in row_cands) and all(len(cc) == 1 for cc in col_cands)

    def extract_grid(row_cands):
        return [list(row_cands[r][0]) for r in range(len(row_cands))]

    # Check consistency between fully assigned rows and columns (Latin constraint)
    def latin_ok_partial(row_assignment):
        # row_assignment may include None entries or full tuples
        N = len(row_assignment)
        # Column uniqueness check on fixed entries
        for c in range(N):
            seen = set()
            for r in range(N):
                p = row_assignment[r]
                if p is None:
                    continue
                v = p[c]
                if v in seen:
                    return False
                seen.add(v)
        return True

    def search(row_cands, col_cands):
        row_cands, col_cands = propagate([list(x) for x in row_cands], [list(x) for x in col_cands])
        if row_cands is None:
            return None

        if is_solved(row_cands, col_cands):
            grid = extract_grid(row_cands)
            # Final sanity: columns should match their unique candidates
            cols = transpose(grid)
            for c in range(N):
                if tuple(cols[c]) not in set(col_cands[c]):
                    return None
            return grid

        # Choose most constrained entity (row or column) to branch on
        best_is_row = True
        best_idx = -1
        best_len = 10**9
        for r in range(N):
            l = len(row_cands[r])
            if 1 < l < best_len:
                best_len = l
                best_idx = r
                best_is_row = True
        for c in range(N):
            l = len(col_cands[c])
            if 1 < l < best_len:
                best_len = l
                best_idx = c
                best_is_row = False

        if best_idx == -1:
            return None

        if best_is_row:
            r = best_idx
            # Heuristic: try candidates that best fit current column domains (least conflict)
            # Score by sum of occurrences in column candidates for each position
            col_pos_counts = []
            for c in range(N):
                cnt = {}
                for p in col_cands[c]:
                    cnt[p[r]] = cnt.get(p[r], 0) + 1
                col_pos_counts.append(cnt)

            def score(p):
                s = 0
                for c in range(N):
                    s += col_pos_counts[c].get(p[c], 0)
                return -s  # higher support first

            for cand in sorted(row_cands[r], key=score):
                new_row = [list(x) for x in row_cands]
                new_col = [list(x) for x in col_cands]
                new_row[r] = [cand]

                # Quick partial Latin check with fixed rows (cheap pruning)
                fixed = [None] * N
                for rr in range(N):
                    if len(new_row[rr]) == 1:
                        fixed[rr] = new_row[rr][0]
                if not latin_ok_partial(fixed):
                    continue

                res = search(new_row, new_col)
                if res is not None:
                    return res
        else:
            c = best_idx
            # Similar heuristic for columns based on row candidates
            row_pos_counts = []
            for r in range(N):
                cnt = {}
                for p in row_cands[r]:
                    cnt[p[c]] = cnt.get(p[c], 0) + 1
                row_pos_counts.append(cnt)

            def score(p):
                s = 0
                for r in range(N):
                    s += row_pos_counts[r].get(p[r], 0)
                return -s

            for cand in sorted(col_cands[c], key=score):
                new_row = [list(x) for x in row_cands]
                new_col = [list(x) for x in col_cands]
                new_col[c] = [cand]

                # Quick partial Latin check with fixed columns (convert to fixed rows where possible)
                # Build fixed row tuples if all columns fixed at that row
                fixed_rows = [None] * N
                for r in range(N):
                    vals = []
                    complete = True
                    for cc in range(N):
                        if len(new_col[cc]) != 1:
                            complete = False
                            break
                        vals.append(new_col[cc][0][r])
                    if complete:
                        fixed_rows[r] = tuple(vals)
                if not latin_ok_partial(fixed_rows):
                    continue

                res = search(new_row, new_col)
                if res is not None:
                    return res

        return None

    grid = search(row_cands, col_cands)
    return grid if grid is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 1, 1, 1, 2], [0, 0, 1, 1, 2], [0, 3, 3, 1, 2], [4, 4, 3, 3, 2], [4, 3, 3, 3, 2]], 'data': [[None, 5, None, None, None], [None, None, None, None, 3], [None, 4, None, 2, None], [5, None, None, None, None], [None, None, None, 5, None]]}

from collections import defaultdict, deque

# Solver for Latin-square + irregular regions (Jigsaw Sudoku / Suguru-like without cages):
# - Numbers 1..N each appear exactly once per row, column, and region.
# Implements human-like deduction:
#   * Candidate computation by exclusion
#   * Hidden singles in row/col/region
#   * Naked singles
#   * Locked candidates (pointing) between region and row/col
#   * Subset elimination (naked pairs/triples) in row/col/region (small N => cheap)
# Uses search only after saturation with strong propagation (MRV + fail-fast).

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    N = len(region)
    if N == 0 or any(len(r) != N for r in region) or any(len(r) != N for r in data):
        return "No Solution"

    # Validate region IDs and build region cells
    rid_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            rid_cells[region[r][c]].append((r, c))
    if any(len(cells) != N for cells in rid_cells.values()):
        return "No Solution"

    # Precompute peers for each cell (row+col+region)
    row_cells = [[(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[(r, c) for r in range(N)] for c in range(N)]
    reg_cells = {rid: cells[:] for rid, cells in rid_cells.items()}

    peers = {}
    for r in range(N):
        for c in range(N):
            rid = region[r][c]
            s = set(row_cells[r]) | set(col_cells[c]) | set(reg_cells[rid])
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    ALL = (1 << N) - 1
    bit = [0] + [1 << (v - 1) for v in range(1, N + 1)]

    def popcount(x):
        return x.bit_count()

    def lsb_value(mask):
        # mask has exactly one bit set
        return (mask.bit_length() - 1) + 1

    def mask_to_list(mask):
        out = []
        while mask:
            b = mask & -mask
            v = (b.bit_length() - 1) + 1
            out.append(v)
            mask ^= b
        return out

    # Initialize grid and candidates
    grid = [[None] * N for _ in range(N)]
    cand = [[ALL] * N for _ in range(N)]

    # Helpers for used masks
    row_used = [0] * N
    col_used = [0] * N
    reg_used = {rid: 0 for rid in reg_cells}

    # Place givens with validation
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= N):
                return "No Solution"
            rid = region[r][c]
            m = bit[v]
            if (row_used[r] & m) or (col_used[c] & m) or (reg_used[rid] & m):
                return "No Solution"
            grid[r][c] = v
            row_used[r] |= m
            col_used[c] |= m
            reg_used[rid] |= m

    # Set initial candidates by exclusion
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                cand[r][c] = bit[grid[r][c]]
            else:
                rid = region[r][c]
                forbidden = row_used[r] | col_used[c] | reg_used[rid]
                cand[r][c] = ALL & ~forbidden
                if cand[r][c] == 0:
                    return "No Solution"

    def units():
        # Return list of unit lists (cells)
        out = []
        out.extend(row_cells)
        out.extend(col_cells)
        out.extend(reg_cells.values())
        return out

    U = units()

    def assign(state, r, c, val):
        # Assign value at (r,c) and update used masks; state is mutable in-place but we record trail for undo.
        # Returns False on contradiction.
        grid, cand, row_used, col_used, reg_used, trail = state

        if grid[r][c] == val:
            return True
        if grid[r][c] is not None and grid[r][c] != val:
            return False

        m = bit[val]
        # Candidate must allow it
        if not (cand[r][c] & m):
            return False

        # Record previous for undo
        trail.append(("cell", r, c, grid[r][c], cand[r][c]))
        grid[r][c] = val
        cand[r][c] = m

        rid = region[r][c]
        # Update used masks (record)
        if not (row_used[r] & m):
            trail.append(("row_used", r, row_used[r]))
            row_used[r] |= m
        if not (col_used[c] & m):
            trail.append(("col_used", c, col_used[c]))
            col_used[c] |= m
        if not (reg_used[rid] & m):
            trail.append(("reg_used", rid, reg_used[rid]))
            reg_used[rid] |= m

        # Eliminate from peers
        for pr, pc in peers[(r, c)]:
            if grid[pr][pc] is None:
                if cand[pr][pc] & m:
                    trail.append(("cand", pr, pc, cand[pr][pc]))
                    cand[pr][pc] &= ~m
                    if cand[pr][pc] == 0:
                        return False
        return True

    def eliminate_to_used_masks(state):
        # Ensure all candidates respect row/col/reg used masks
        grid, cand, row_used, col_used, reg_used, trail = state
        for r in range(N):
            ru = row_used[r]
            for c in range(N):
                if grid[r][c] is not None:
                    continue
                rid = region[r][c]
                forbidden = ru | col_used[c] | reg_used[rid]
                newm = cand[r][c] & ~forbidden
                if newm != cand[r][c]:
                    trail.append(("cand", r, c, cand[r][c]))
                    cand[r][c] = newm
                    if newm == 0:
                        return False
        return True

    def naked_singles(state, queue):
        grid, cand, *_ = state
        while queue:
            r, c = queue.popleft()
            if grid[r][c] is not None:
                continue
            m = cand[r][c]
            if m == 0:
                return False
            if popcount(m) == 1:
                v = lsb_value(m)
                if not assign(state, r, c, v):
                    return False
                # after assignment, peers changed -> enqueue affected empties
                for pr, pc in peers[(r, c)]:
                    if grid[pr][pc] is None:
                        queue.append((pr, pc))
        return True

    def hidden_singles_in_unit(state, unit):
        grid, cand, *_ = state
        # For each digit, if it appears in exactly one candidate cell, assign it
        count = [0] * (N + 1)
        last_pos = [None] * (N + 1)
        for r, c in unit:
            if grid[r][c] is not None:
                continue
            m = cand[r][c]
            while m:
                b = m & -m
                v = (b.bit_length() - 1) + 1
                count[v] += 1
                last_pos[v] = (r, c)
                m ^= b
        for v in range(1, N + 1):
            if count[v] == 1:
                r, c = last_pos[v]
                if not assign(state, r, c, v):
                    return False
        return True

    def pointing_locked_candidates(state):
        # Region->row/col pointing: if in a region a digit only appears in one row, eliminate from that row outside region.
        # Similarly for one col.
        grid, cand, *_ = state
        trail = state[-1]

        for rid, cells in reg_cells.items():
            # Build positions per digit
            rows_for = [set() for _ in range(N + 1)]
            cols_for = [set() for _ in range(N + 1)]
            poss_cells_for = [0] * (N + 1)  # bitmask over cell index within region (<=N<=16 typically small)
            for idx, (r, c) in enumerate(cells):
                if grid[r][c] is not None:
                    continue
                m = cand[r][c]
                while m:
                    b = m & -m
                    v = (b.bit_length() - 1) + 1
                    rows_for[v].add(r)
                    cols_for[v].add(c)
                    poss_cells_for[v] |= (1 << idx)
                    m ^= b
            for v in range(1, N + 1):
                if poss_cells_for[v] == 0:
                    continue
                if len(rows_for[v]) == 1:
                    row = next(iter(rows_for[v]))
                    mbit = bit[v]
                    for (r, c) in row_cells[row]:
                        if region[r][c] != rid and grid[r][c] is None and (cand[r][c] & mbit):
                            trail.append(("cand", r, c, cand[r][c]))
                            cand[r][c] &= ~mbit
                            if cand[r][c] == 0:
                                return False
                if len(cols_for[v]) == 1:
                    col = next(iter(cols_for[v]))
                    mbit = bit[v]
                    for (r, c) in col_cells[col]:
                        if region[r][c] != rid and grid[r][c] is None and (cand[r][c] & mbit):
                            trail.append(("cand", r, c, cand[r][c]))
                            cand[r][c] &= ~mbit
                            if cand[r][c] == 0:
                                return False
        return True

    def naked_subsets_unit(state, unit, max_k=3):
        # Naked pairs/triples: if k cells have union of candidates size k, remove those from other cells.
        grid, cand, *_ = state
        trail = state[-1]

        cells = [(r, c) for (r, c) in unit if grid[r][c] is None]
        if len(cells) < 2:
            return True

        # Map mask->list of cells
        mask_to_cells = defaultdict(list)
        for r, c in cells:
            m = cand[r][c]
            pc = popcount(m)
            if 1 <= pc <= max_k:
                mask_to_cells[m].append((r, c))

        # Handle exact k identical masks first (fast)
        for m, clist in mask_to_cells.items():
            k = popcount(m)
            if 2 <= k <= max_k and len(clist) == k:
                # eliminate m from other cells
                for r, c in cells:
                    if (r, c) in clist:
                        continue
                    if cand[r][c] & m:
                        trail.append(("cand", r, c, cand[r][c]))
                        cand[r][c] &= ~m
                        if cand[r][c] == 0:
                            return False

        # Limited additional combinations for triples where masks differ but union size==k
        if max_k >= 3 and len(cells) <= 9:
            # For small N, this is cheap.
            # Build list of candidate masks with small size
            small = [(r, c, cand[r][c]) for (r, c) in cells if 2 <= popcount(cand[r][c]) <= 3]
            L = len(small)
            for i in range(L):
                for j in range(i + 1, L):
                    for k in range(j + 1, L):
                        union = small[i][2] | small[j][2] | small[k][2]
                        if popcount(union) == 3:
                            trio = {(small[i][0], small[i][1]), (small[j][0], small[j][1]), (small[k][0], small[k][1])}
                            for r, c in cells:
                                if (r, c) in trio:
                                    continue
                                if cand[r][c] & union:
                                    trail.append(("cand", r, c, cand[r][c]))
                                    cand[r][c] &= ~union
                                    if cand[r][c] == 0:
                                        return False
        return True

    def propagate(state):
        grid, cand, *_ = state
        trail = state[-1]
        # Initialize queue with all empties for single detection
        q = deque()
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    q.append((r, c))

        changed = True
        while changed:
            start_trail_len = len(trail)

            if not eliminate_to_used_masks(state):
                return False
            if not naked_singles(state, q):
                return False

            # Hidden singles across all units
            for unit in U:
                if not hidden_singles_in_unit(state, unit):
                    return False

            if not pointing_locked_candidates(state):
                return False

            # Subset elimination
            for unit in U:
                if not naked_subsets_unit(state, unit, max_k=3):
                    return False

            # After eliminations, enqueue all cells that might now be singles
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None and popcount(cand[r][c]) == 1:
                        q.append((r, c))

            changed = len(trail) != start_trail_len
        return True

    def is_solved(grid):
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    return False
        return True

    def choose_cell(state):
        grid, cand, *_ = state
        best = None
        best_count = 10**9
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    pc = popcount(cand[r][c])
                    if pc < best_count:
                        best_count = pc
                        best = (r, c)
                        if pc == 2:
                            return best
        return best

    def undo(state, trail_len):
        grid, cand, row_used, col_used, reg_used, trail = state
        while len(trail) > trail_len:
            item = trail.pop()
            t = item[0]
            if t == "cell":
                _, r, c, prev_v, prev_c = item
                grid[r][c] = prev_v
                cand[r][c] = prev_c
            elif t == "cand":
                _, r, c, prev = item
                cand[r][c] = prev
            elif t == "row_used":
                _, r, prev = item
                row_used[r] = prev
            elif t == "col_used":
                _, c, prev = item
                col_used[c] = prev
            elif t == "reg_used":
                _, rid, prev = item
                reg_used[rid] = prev

    def dfs(state):
        if not propagate(state):
            return False
        if is_solved(state[0]):
            return True

        r, c = choose_cell(state)
        if r is None:
            return False

        m = state[1][r][c]
        # Value ordering: try least constraining (min peer hits)
        vals = mask_to_list(m)

        def peer_hits(v):
            mv = bit[v]
            hits = 0
            for pr, pc in peers[(r, c)]:
                if state[0][pr][pc] is None and (state[1][pr][pc] & mv):
                    hits += 1
            return hits

        vals.sort(key=peer_hits)

        for v in vals:
            trail_len = len(state[-1])
            if assign(state, r, c, v):
                if dfs(state):
                    return True
            undo(state, trail_len)
        return False

    trail = []
    state = (grid, cand, row_used, col_used, reg_used, trail)
    if not dfs(state):
        return "No Solution"
    return "\n".join(" ".join(str(grid[r][c]) for c in range(N)) for r in range(N))


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, None, None, None, None, 'B'], [None, 'B', None, None, 'W', None], [None, 'W', None, None, 'W', None], [None, None, None, None, None, None], [None, None, None, None, None, None]], 'horizontal': {'(0, 4.5)': '=', '(2, 0.5)': '=', '(3, 2.5)': '='}, 'vertical': {'(0.5, 0)': 'x', '(2.5, 5)': 'x', '(3.5, 2)': 'x'}}
from __future__ import annotations

# General solver for "Binary puzzle with = / x adjacency constraints":
# - Grid cells are B/W.
# - Each row/col has equal B and W.
# - No three consecutive identical in any row/col.
# - '=' constraint: adjacent same; 'x' constraint: adjacent different.
# - Uses aggressive human-like propagation (local pattern rules, balance, pair/line completion),
#   plus backtracking only when needed (MRV + forward-check).

from collections import deque
from itertools import product

B, W = 1, 0  # internal
INV = {B: W, W: B}
CHR = {B: "B", W: "W"}

def solve(observation):
    grid0 = observation["data"]
    n = len(grid0)
    if n == 0 or any(len(r) != n for r in grid0):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"

    # Parse constraints
    hcon = {}  # (r,c) between (r,c) and (r,c+1)
    vcon = {}  # (r,c) between (r,c) and (r+1,c)

    def parse_key(k):
        s = k.strip()
        if s[0] == "(" and s[-1] == ")":
            s = s[1:-1]
        a, b = s.split(",")
        a = a.strip()
        b = b.strip()
        # stored keys could be like "2.0" or "2"
        return float(a), float(b)

    for k, t in observation.get("horizontal", {}).items():
        r, cc = parse_key(k)
        r = int(round(r))
        # cc is c + 0.5
        c = int(round(cc - 0.5))
        if not (0 <= r < n and 0 <= c < n - 1):
            return "No Solution"
        if t not in ("=", "x"):
            return "No Solution"
        hcon[(r, c)] = t

    for k, t in observation.get("vertical", {}).items():
        rr, c = parse_key(k)
        c = int(round(c))
        r = int(round(rr - 0.5))
        if not (0 <= r < n - 1 and 0 <= c < n):
            return "No Solution"
        if t not in ("=", "x"):
            return "No Solution"
        vcon[(r, c)] = t

    # State: domains bitmask 1<<0 for W, 1<<1 for B
    ALL = 0b11
    dom = [[ALL for _ in range(n)] for __ in range(n)]
    for r in range(n):
        for c in range(n):
            v = grid0[r][c]
            if v is None:
                continue
            if v == "B":
                dom[r][c] = 0b10
            elif v == "W":
                dom[r][c] = 0b01
            else:
                return "No Solution"

    # Helpers
    def is_single(mask):
        return mask == 0b01 or mask == 0b10

    def mask_to_val(mask):
        return B if mask == 0b10 else W

    def val_to_mask(v):
        return 0b10 if v == B else 0b01

    def popcount2(mask):
        # mask is 0..3
        return (mask & 1) + ((mask >> 1) & 1)

    # Adjacency constraints list for propagation
    # Each edge: (r1,c1,r2,c2, type)
    edges = []
    for (r, c), t in hcon.items():
        edges.append((r, c, r, c + 1, t))
    for (r, c), t in vcon.items():
        edges.append((r, c, r + 1, c, t))

    # For fast access, incident edges per cell
    inc = [[[] for _ in range(n)] for __ in range(n)]
    for i, (r1, c1, r2, c2, t) in enumerate(edges):
        inc[r1][c1].append(i)
        inc[r2][c2].append(i)

    # Row/col indexing utilities
    def row_cells(r):
        return [(r, c) for c in range(n)]

    def col_cells(c):
        return [(r, c) for r in range(n)]

    # Constraint checks and propagation rules
    def restrict_cell(r, c, newmask, q):
        nonlocal dom
        old = dom[r][c]
        nm = old & newmask
        if nm == 0:
            return False
        if nm != old:
            dom[r][c] = nm
            q.append((r, c))
        return True

    def propagate_from_queue(q):
        # q contains cells that changed
        while q:
            r, c = q.popleft()
            m = dom[r][c]
            if m == 0:
                return False

            # 1) Apply adjacency constraints along incident edges (arc consistency)
            for ei in inc[r][c]:
                r1, c1, r2, c2, t = edges[ei]
                if (r, c) == (r1, c1):
                    a = (r1, c1); b = (r2, c2)
                else:
                    a = (r2, c2); b = (r1, c1)
                ar, ac = a
                br, bc = b
                ma = dom[ar][ac]
                mb = dom[br][bc]
                if t == "=":
                    # domains must intersect in same value
                    inter = ma & mb
                    if inter == 0:
                        return False
                    if not restrict_cell(ar, ac, inter, q): return False
                    if not restrict_cell(br, bc, inter, q): return False
                else:  # 'x' different
                    # For each value in a, b cannot be same.
                    # AC: remove v from b if a fixed to v, etc.
                    if is_single(ma):
                        va = mask_to_val(ma)
                        if not restrict_cell(br, bc, val_to_mask(INV[va]), q): return False
                    if is_single(mb):
                        vb = mask_to_val(mb)
                        if not restrict_cell(ar, ac, val_to_mask(INV[vb]), q): return False
                    # If both not single, no direct reduction.

            # 2) No-three-in-a-row/col local pattern rules (human-like)
            # For each line (row and col), enforce:
            # - If two consecutive are same, neighbors must be opposite.
            # - If separated by one and endpoints same, middle must be opposite.
            for is_row in (True, False):
                if is_row:
                    line = [(r, j) for j in range(n)]
                else:
                    line = [(i, c) for i in range(n)]
                # We'll scan triples for forced moves using domains
                for k in range(n - 2):
                    a = line[k]; b = line[k + 1]; d = line[k + 2]
                    ma, mb, md = dom[a[0]][a[1]], dom[b[0]][b[1]], dom[d[0]][d[1]]

                    # Pattern: A B C
                    # If A and B fixed same => C cannot be that value
                    if is_single(ma) and is_single(mb) and ma == mb:
                        v = mask_to_val(ma)
                        if not restrict_cell(d[0], d[1], val_to_mask(INV[v]), q): return False
                    # If B and C fixed same => A cannot be that value
                    if is_single(mb) and is_single(md) and mb == md:
                        v = mask_to_val(mb)
                        if not restrict_cell(a[0], a[1], val_to_mask(INV[v]), q): return False
                    # If A and C fixed same => B must be opposite
                    if is_single(ma) and is_single(md) and ma == md:
                        v = mask_to_val(ma)
                        if not restrict_cell(b[0], b[1], val_to_mask(INV[v]), q): return False

            # 3) Balance rule per row/col (equal counts):
            # If count of B reaches n/2 -> remaining must be W; same for W.
            for is_row in (True, False):
                if is_row:
                    cells = row_cells(r)
                else:
                    cells = col_cells(c)
                fixedB = fixedW = 0
                unknown = []
                for (i, j) in cells:
                    m2 = dom[i][j]
                    if is_single(m2):
                        if mask_to_val(m2) == B:
                            fixedB += 1
                        else:
                            fixedW += 1
                    else:
                        unknown.append((i, j))
                if fixedB > n // 2 or fixedW > n // 2:
                    return False
                if fixedB == n // 2:
                    for (i, j) in unknown:
                        if not restrict_cell(i, j, 0b01, q): return False
                if fixedW == n // 2:
                    for (i, j) in unknown:
                        if not restrict_cell(i, j, 0b10, q): return False

            # 4) "Only place" in a row/col for a color count using domain counting:
            # If a row needs k Bs and only k cells can be B, force them to B (similarly W).
            for is_row in (True, False):
                if is_row:
                    cells = row_cells(r)
                else:
                    cells = col_cells(c)
                fixedB = fixedW = 0
                canB = []
                canW = []
                for (i, j) in cells:
                    m2 = dom[i][j]
                    if is_single(m2):
                        if mask_to_val(m2) == B:
                            fixedB += 1
                        else:
                            fixedW += 1
                    else:
                        if m2 & 0b10: canB.append((i, j))
                        if m2 & 0b01: canW.append((i, j))
                needB = n // 2 - fixedB
                needW = n // 2 - fixedW
                if needB < 0 or needW < 0:
                    return False
                if needB == 0:
                    for (i, j) in canB:
                        if not restrict_cell(i, j, dom[i][j] & 0b01, q): return False
                elif len(canB) == needB:
                    for (i, j) in canB:
                        if not restrict_cell(i, j, 0b10, q): return False
                if needW == 0:
                    for (i, j) in canW:
                        if not restrict_cell(i, j, dom[i][j] & 0b10, q): return False
                elif len(canW) == needW:
                    for (i, j) in canW:
                        if not restrict_cell(i, j, 0b01, q): return False

        return True

    def initial_propagate():
        q = deque()
        # seed queue with all fixed cells
        for r in range(n):
            for c in range(n):
                if is_single(dom[r][c]):
                    q.append((r, c))
        # also seed with all cells for a strong first pass (balance may trigger without fixed seeds)
        for r in range(n):
            for c in range(n):
                q.append((r, c))
        return propagate_from_queue(q)

    def is_solved():
        return all(is_single(dom[r][c]) for r in range(n) for c in range(n))

    def choose_cell():
        # MRV: smallest domain >1
        best = None
        bestsz = 3
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                if not is_single(m):
                    sz = popcount2(m)
                    if sz < bestsz:
                        bestsz = sz
                        best = (r, c)
                        if sz == 2:
                            # cannot be 1 here, so early break only if 2 is minimal
                            pass
        return best

    def snapshot():
        return [row[:] for row in dom]

    def restore(snap):
        nonlocal dom
        dom = [row[:] for row in snap]

    def dfs():
        if is_solved():
            return True
        cell = choose_cell()
        if cell is None:
            return False
        r, c = cell
        m = dom[r][c]
        # Value ordering: try value that helps balance (heuristic)
        # Compute row/col current fixed counts to prefer completing quotas.
        def score(val):
            rb = rw = cb = cw = 0
            for j in range(n):
                mm = dom[r][j]
                if is_single(mm):
                    (rb if mask_to_val(mm) == B else rw)  # no-op
            # quick counts
            for j in range(n):
                mm = dom[r][j]
                if is_single(mm):
                    if mask_to_val(mm) == B: rb += 1
                    else: rw += 1
            for i in range(n):
                mm = dom[i][c]
                if is_single(mm):
                    if mask_to_val(mm) == B: cb += 1
                    else: cw += 1
            # prefer value that doesn't exceed half
            if val == B:
                return (rb + 1 <= n // 2) + (cb + 1 <= n // 2)
            else:
                return (rw + 1 <= n // 2) + (cw + 1 <= n // 2)

        candidates = []
        if m & 0b10: candidates.append(B)
        if m & 0b01: candidates.append(W)
        candidates.sort(key=score, reverse=True)

        for v in candidates:
            snap = snapshot()
            q = deque()
            if not restrict_cell(r, c, val_to_mask(v), q):
                restore(snap)
                continue
            if propagate_from_queue(q):
                if dfs():
                    return True
            restore(snap)
        return False

    if not initial_propagate():
        return "No Solution"
    if not dfs():
        return "No Solution"

    solved = [[CHR[mask_to_val(dom[r][c])] for c in range(n)] for r in range(n)]
    return str(solved)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [2, 0, 0, 1, 0, 6], 'D': [0, 0, 2, 2, 3, 0], 'L': [4, 0, 3, 0, 2, 0], 'R': [0, 0, 0, 0, 0, 0]}
from itertools import permutations

# Skyscrapers solver (Latin square + visibility constraints) with aggressive constraint propagation.
# Generalized for NxN based on clue list lengths; 0 means "no clue".

def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    n = len(U)
    if not (len(D) == len(L) == len(R) == n):
        return "No Solution"

    vals = tuple(range(1, n + 1))

    def visible_count(seq):
        m = 0
        seen = 0
        for x in seq:
            if x > m:
                m = x
                seen += 1
        return seen

    # Precompute row patterns matching side clues (left/right).
    all_rows = list(permutations(vals))
    row_cands = []
    for r in range(n):
        lc = L[r]
        rc = R[r]
        cands = []
        for p in all_rows:
            if lc and visible_count(p) != lc:
                continue
            if rc and visible_count(p[::-1]) != rc:
                continue
            cands.append(p)
        if not cands:
            return "No Solution"
        row_cands.append(cands)

    # Precompute allowed full columns per (top,bottom) clue for fast final validation and incremental pruning.
    col_allowed = {}
    for t in range(0, n + 1):
        for b in range(0, n + 1):
            allowed = []
            for p in all_rows:
                if t and visible_count(p) != t:
                    continue
                if b and visible_count(p[::-1]) != b:
                    continue
                allowed.append(p)
            col_allowed[(t, b)] = allowed

    # Fast checks for partial columns against (top,bottom) using bounds:
    # - top clue: visible count so far cannot exceed clue; and must be possible to reach clue.
    # - bottom clue analogous using suffix info.
    # For possibility bounds, we use greedy best-case upper bound given remaining heights.
    def top_partial_ok(prefix, clue):
        if clue == 0:
            return True
        m = 0
        seen = 0
        for x in prefix:
            if x > m:
                m = x
                seen += 1
        if seen > clue:
            return False
        # Maximum additional visibles possible with remaining cells is limited by remaining distinct heights > current max.
        # Upper bound: seen + number of remaining heights that are greater than current max (at most remaining length).
        rem_len = n - len(prefix)
        # There exist some unused heights; compute optimistic max as min(rem_len, n - m) added to seen
        max_add = min(rem_len, n - m)
        return seen + max_add >= clue

    def bottom_partial_ok(suffix, clue):
        if clue == 0:
            return True
        m = 0
        seen = 0
        for x in suffix:
            if x > m:
                m = x
                seen += 1
        if seen > clue:
            return False
        rem_len = n - len(suffix)
        max_add = min(rem_len, n - m)
        return seen + max_add >= clue

    # Domain as bitmasks per (row,col) derived from row candidates; maintained via propagation.
    full_mask = (1 << n) - 1
    bit_of = [1 << (v - 1) for v in vals]

    def mask_from_values(vs):
        m = 0
        for v in vs:
            m |= bit_of[v - 1]
        return m

    def values_from_mask(m):
        out = []
        i = 1
        while m:
            lb = m & -m
            idx = (lb.bit_length() - 1)
            out.append(idx + 1)
            m ^= lb
            i += 1
        return out

    # Initialize cell masks from row candidates.
    cell = [[full_mask for _ in range(n)] for __ in range(n)]
    for r in range(n):
        # intersection-of-union for each position from candidates
        unions = [0] * n
        for p in row_cands[r]:
            for c, v in enumerate(p):
                unions[c] |= bit_of[v - 1]
        for c in range(n):
            cell[r][c] &= unions[c]
            if cell[r][c] == 0:
                return "No Solution"

    # Helper: reduce row candidates using current cell masks and (optionally) column uniqueness info
    def filter_row_candidates(r, col_used_masks):
        cands = row_cands[r]
        new = []
        # Additional pruning: for each col, value cannot already be used in that column (above fixed rows).
        for p in cands:
            ok = True
            for c, v in enumerate(p):
                if not (cell[r][c] & bit_of[v - 1]):
                    ok = False
                    break
                if col_used_masks[c] & bit_of[v - 1]:
                    ok = False
                    break
            if ok:
                new.append(p)
        return new

    # Propagate constraints until fixpoint; returns False on contradiction.
    def propagate(row_assigned, grid_rows, col_used_masks):
        changed = True
        while changed:
            changed = False

            # Update cell masks from row candidates (for unassigned rows)
            for r in range(n):
                if row_assigned[r]:
                    # Tighten cell masks to exact assigned values
                    row = grid_rows[r]
                    for c, v in enumerate(row):
                        m = bit_of[v - 1]
                        if cell[r][c] != m:
                            cell[r][c] = m
                            changed = True
                    continue

                # Filter row candidates based on current cell masks and column used masks
                newc = filter_row_candidates(r, col_used_masks)
                if not newc:
                    return False
                if len(newc) != len(row_cands[r]):
                    row_cands[r] = newc
                    changed = True

                # Recompute unions and also intersections for singleton deductions
                unions = [0] * n
                for p in row_cands[r]:
                    for c, v in enumerate(p):
                        unions[c] |= bit_of[v - 1]
                for c in range(n):
                    nm = cell[r][c] & unions[c]
                    if nm == 0:
                        return False
                    if nm != cell[r][c]:
                        cell[r][c] = nm
                        changed = True

                # Hidden single in row: for each value, if appears in only one position among candidates => fix that position mask
                # Compute possible positions per value
                pos_mask_per_val = [0] * n  # bitset over columns
                for p in row_cands[r]:
                    for c, v in enumerate(p):
                        pos_mask_per_val[v - 1] |= (1 << c)
                for vi in range(n):
                    pm = pos_mask_per_val[vi]
                    if pm and (pm & (pm - 1)) == 0:
                        c = (pm.bit_length() - 1)
                        nm = cell[r][c] & bit_of[vi]
                        if nm == 0:
                            return False
                        if cell[r][c] != nm:
                            cell[r][c] = nm
                            changed = True

            # Column-based pruning from current cell masks + used masks:
            for c in range(n):
                # Values already used in assigned rows for this column:
                used = col_used_masks[c]
                # If a value is used, remove from other unassigned cells
                for r in range(n):
                    if row_assigned[r]:
                        continue
                    nm = cell[r][c] & ~used
                    if nm == 0:
                        return False
                    if nm != cell[r][c]:
                        cell[r][c] = nm
                        changed = True

                # Hidden single in column (based on masks)
                avail_positions = [0] * n  # per value: bitset over rows
                for r in range(n):
                    if row_assigned[r]:
                        continue
                    m = cell[r][c]
                    mm = m
                    while mm:
                        lb = mm & -mm
                        vi = lb.bit_length() - 1
                        avail_positions[vi] |= (1 << r)
                        mm ^= lb
                for vi in range(n):
                    if used & (1 << vi):
                        continue
                    pm = avail_positions[vi]
                    if pm and (pm & (pm - 1)) == 0:
                        r = pm.bit_length() - 1
                        nm = cell[r][c] & (1 << vi)
                        if nm == 0:
                            return False
                        if cell[r][c] != nm:
                            cell[r][c] = nm
                            changed = True

            # Visibility partial checks for columns based on assigned prefixes/suffixes and also possible completion existence.
            # Quick prefix/suffix feasibility:
            for c in range(n):
                # Build assigned prefix from top until first unassigned row; but also consider gaps (we assign whole rows, so may be scattered)
                # We'll check every possible prefix length k from top of assigned rows contiguous.
                # Since assignments occur by row, contiguity may not hold; use current known singletons for each cell to form a "fixed" value or 0.
                col_vals = []
                for r in range(n):
                    m = cell[r][c]
                    if (m & (m - 1)) == 0:
                        col_vals.append((m.bit_length() - 1) + 1)
                    else:
                        col_vals.append(0)

                # Top check on known prefix until first 0
                k = 0
                prefix = []
                while k < n and col_vals[k] != 0:
                    prefix.append(col_vals[k])
                    k += 1
                if not top_partial_ok(prefix, U[c]):
                    return False

                # Bottom check on known suffix until first 0
                k = n - 1
                suffix = []
                while k >= 0 and col_vals[k] != 0:
                    suffix.append(col_vals[k])
                    k -= 1
                # suffix is bottom-up; for visibility from bottom we need bottom->top, so this order is fine.
                if not bottom_partial_ok(suffix, D[c]):
                    return False

        return True

    # Choose next row to assign using MRV (fewest candidates) plus impact heuristic.
    def select_row(row_assigned):
        best = -1
        best_len = 10**9
        for r in range(n):
            if row_assigned[r]:
                continue
            l = len(row_cands[r])
            if l < best_len:
                best_len = l
                best = r
        return best

    def dfs(row_assigned, grid_rows, col_used_masks):
        if not propagate(row_assigned, grid_rows, col_used_masks):
            return None

        if all(row_assigned):
            # Validate columns exactly match visibility clues (and are permutations).
            grid = [list(grid_rows[r]) for r in range(n)]
            for c in range(n):
                col = [grid[r][c] for r in range(n)]
                if len(set(col)) != n:
                    return None
                tc = U[c]
                bc = D[c]
                if tc and visible_count(col) != tc:
                    return None
                if bc and visible_count(col[::-1]) != bc:
                    return None
            return grid

        r = select_row(row_assigned)

        # Order candidates: try those that fit best with current column possibilities (least conflicts).
        cands = row_cands[r]

        def score(p):
            s = 0
            for c, v in enumerate(p):
                if col_used_masks[c] & bit_of[v - 1]:
                    s += 1000
                # prefer values that are rarer in the column masks
                cnt = 0
                for rr in range(n):
                    if row_assigned[rr]:
                        continue
                    if cell[rr][c] & bit_of[v - 1]:
                        cnt += 1
                s += cnt
            return s

        cands_sorted = sorted(cands, key=score)

        # Snapshot structures for backtracking: row_cands and cell mutate; do lightweight copies.
        row_cands_snapshot = None
        cell_snapshot = None

        for p in cands_sorted:
            # Quick check against used values in columns
            bad = False
            for c, v in enumerate(p):
                if col_used_masks[c] & bit_of[v - 1]:
                    bad = True
                    break
            if bad:
                continue

            # Save snapshots lazily
            if row_cands_snapshot is None:
                row_cands_snapshot = [lst[:] for lst in row_cands]
                cell_snapshot = [row[:] for row in cell]

            # Apply assignment
            row_assigned2 = row_assigned[:]
            grid_rows2 = list(grid_rows)
            col_used2 = col_used_masks[:]

            row_assigned2[r] = True
            grid_rows2[r] = p
            for c, v in enumerate(p):
                col_used2[c] |= bit_of[v - 1]

            # Force row candidates for this row and cell masks
            row_cands[r] = [p]
            for c, v in enumerate(p):
                cell[r][c] = bit_of[v - 1]

            res = dfs(row_assigned2, grid_rows2, col_used2)
            if res is not None:
                return res

            # Restore
            row_cands[:] = [lst[:] for lst in row_cands_snapshot]
            for rr in range(n):
                cell[rr][:] = cell_snapshot[rr][:]

        return None

    row_assigned0 = [False] * n
    grid_rows0 = [None] * n
    col_used0 = [0] * n

    sol = dfs(row_assigned0, grid_rows0, col_used0)
    return sol if sol is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 4, 3, 2, 3], [4, 3, 2, 3, 5], [1, 2, 3, 1, 4], [5, 3, 1, 4, 2], [2, 4, 4, 3, 3]]}

from collections import deque, defaultdict

# Solver for Hitori-like puzzles:
# - Shade some cells black.
# - No duplicate numbers remain unshaded in any row/column.
# - Black cells cannot touch orthogonally.
# - All unshaded cells must be orthogonally connected.
#
# Approach:
# Aggressive propagation using:
#   1) Duplicate constraints (row/col): for each value group, at least (k-1) must be black among k occurrences.
#      Implemented with fast infeasibility checks and forced moves for small k (k=2,3) via local reasoning.
#   2) No-adjacent-blacks constraints (pairwise).
#   3) Connectivity constraints:
#        - White cells must remain connectable: reject states where some forced-white component is separated by forced-black wall.
#        - Avoid making any white cell isolated (all 4-neighbors black/out).
#        - Prevent creation of disconnected forced-white components when separators are fixed.
# Search:
#   - Choose a branching cell from a "most constrained" duplicate group or a cell whose state strongly impacts constraints.
#   - Branch on setting cell black/white with propagation each side.
#
# This is not naive brute-force: propagation is heavy and branching is guided.

B = 1  # black
W = 2  # white
U = 0  # unknown

def solve(observation):
    g = observation["data"]
    n = len(g)
    m = len(g[0])
    if n != m:
        return "No Solution"
    N = n

    # Precompute coordinates, neighbors
    idx = lambda r, c: r * N + c
    rc = lambda k: (k // N, k % N)

    neigh = [[] for _ in range(N * N)]
    for r in range(N):
        for c in range(N):
            k = idx(r, c)
            if r > 0: neigh[k].append(idx(r - 1, c))
            if r + 1 < N: neigh[k].append(idx(r + 1, c))
            if c > 0: neigh[k].append(idx(r, c - 1))
            if c + 1 < N: neigh[k].append(idx(r, c + 1))

    # Groups of equal numbers per row/col
    row_groups = []
    col_groups = []

    for r in range(N):
        mp = defaultdict(list)
        for c in range(N):
            mp[g[r][c]].append(idx(r, c))
        for val, cells in mp.items():
            if len(cells) >= 2:
                row_groups.append((r, val, cells))

    for c in range(N):
        mp = defaultdict(list)
        for r in range(N):
            mp[g[r][c]].append(idx(r, c))
        for val, cells in mp.items():
            if len(cells) >= 2:
                col_groups.append((c, val, cells))

    groups = row_groups + col_groups

    # For quick access: for each cell, which groups (indices) it belongs to
    cell_groups = [[] for _ in range(N * N)]
    for gi, (_, _, cells) in enumerate(groups):
        for k in cells:
            cell_groups[k].append(gi)

    group_cells = [cells for (_, _, cells) in groups]

    def connectivity_ok(state):
        # If any cell is forced white, ensure all forced whites are in same component within non-black cells.
        # Also ensure there exists a possible spanning connectivity among all non-black cells not yet fixed black,
        # i.e., the graph induced by (not black) has at most one component containing all forced whites.
        forced_whites = [i for i, s in enumerate(state) if s == W]
        # Early: no white cell should be isolated by forced blacks/outside
        for i, s in enumerate(state):
            if s == W:
                ok = False
                for j in neigh[i]:
                    if state[j] != B:
                        ok = True
                        break
                if not ok and len(neigh[i]) > 0:
                    return False

        # Determine components in graph of allowed cells (not black)
        allowed = [s != B for s in state]
        # If no forced whites yet: still need whole final whites connected; we can enforce "allowed" is not split
        # into multiple components that are already separated by forced blacks with no chance to connect.
        # We'll use a permissive check: if there are forced whites, they must all lie in one allowed component.
        # Additionally, if there are multiple allowed components and more than one contains at least one forced white -> fail.
        # If no forced whites, we don't strictly require allowed to be connected (unknowns can be black later), but:
        # we disallow creation of an allowed component consisting solely of forced whites separated from all unknowns by blacks.
        seen = [False] * (N * N)
        comp_id = [-1] * (N * N)
        comps = []
        cid = 0
        for i in range(N * N):
            if allowed[i] and not seen[i]:
                q = deque([i])
                seen[i] = True
                nodes = []
                while q:
                    x = q.popleft()
                    comp_id[x] = cid
                    nodes.append(x)
                    for y in neigh[x]:
                        if allowed[y] and not seen[y]:
                            seen[y] = True
                            q.append(y)
                comps.append(nodes)
                cid += 1

        if not forced_whites:
            # light pruning: avoid two disjoint regions both containing forced-white? none.
            return True

        fid = comp_id[forced_whites[0]]
        if fid == -1:
            return False
        for w in forced_whites[1:]:
            if comp_id[w] != fid:
                return False
        return True

    def group_feasible(state, cells):
        # In a group of equal numbers (same row or col):
        # Among k cells, at most 1 can be white in final, so at least k-1 must be black.
        k = len(cells)
        black = 0
        white = 0
        unk = 0
        for x in cells:
            s = state[x]
            if s == B: black += 1
            elif s == W: white += 1
            else: unk += 1
        # If already more than 1 white -> impossible
        if white > 1:
            return False
        # Need black >= k-1 eventually => with remaining unknown, maximum black is black+unk
        if black + unk < k - 1:
            return False
        # Also if black > k-1? allowed (extra blacks) yes, but could cause 0 whites in group which is allowed.
        return True

    def propagate(state, queue):
        # queue contains indices of cells whose assignment changed; propagate constraints.
        # Returns False if contradiction.
        inq = [False] * (N * N)
        for x in queue:
            inq[x] = True

        def set_cell(i, val):
            if state[i] == val:
                return True
            if state[i] != U and state[i] != val:
                return False
            state[i] = val
            if not inq[i]:
                queue.append(i)
                inq[i] = True
            return True

        # Initial global checks of groups may force assignments even without queue; we'll handle via scanning occasionally.
        scans_remaining = 4  # bounded rescans for strong propagation

        while queue or scans_remaining:
            if queue:
                i = queue.popleft()
                inq[i] = False
                s = state[i]
                if s == B:
                    # No adjacent blacks => neighbors cannot be black => must be white or unknown -> force white.
                    for j in neigh[i]:
                        if not set_cell(j, W):
                            return False
                else:
                    # If cell is white, it does not directly force neighbors.
                    pass

                # For each group the cell belongs to, enforce feasibility and do local forcing for k=2,3.
                for gi in cell_groups[i]:
                    cells = group_cells[gi]
                    if not group_feasible(state, cells):
                        return False
                    k = len(cells)
                    # Count
                    blacks = [x for x in cells if state[x] == B]
                    whites = [x for x in cells if state[x] == W]
                    unks = [x for x in cells if state[x] == U]
                    # If already one white, all others must be black (to remove duplicates)
                    if len(whites) == 1:
                        for x in unks:
                            if not set_cell(x, B):
                                return False
                    # If black count reached k-1, remaining must be white (can't black all if it would isolate? Actually can.)
                    # Hitori allows all duplicates black (leaving none of that number), so no need to force white.
                    # Special patterns for k=2:
                    if k == 2:
                        a, b = cells
                        # If a is white -> b black, already handled
                        # If a is black -> b must be white? Not required; could black both? allowed but may violate adjacency.
                        # We don't force.
                        # If a and b are orthogonally adjacent, they cannot both be black, thus at least one must be white.
                        if b in neigh[a]:
                            if state[a] == B and state[b] == B:
                                return False
                            if state[a] == B and state[b] == U:
                                if not set_cell(b, W):
                                    return False
                            if state[b] == B and state[a] == U:
                                if not set_cell(a, W):
                                    return False
                    # Special for k=3: if two are forced white -> impossible already caught.
                    # If two are forced black and remaining unknown, could remain unknown; no forcing.

            else:
                scans_remaining -= 1
                # Global scan: groups forcing due to white presence and adjacency constraints due to implied patterns.
                # Also perform "corner isolation" avoidance: unknown cell surrounded by blacks becomes white impossible; etc.
                # Group scan (cheap on 5x5, still fine generalized)
                for cells in group_cells:
                    if not group_feasible(state, cells):
                        return False
                    whites = [x for x in cells if state[x] == W]
                    if len(whites) == 1:
                        for x in cells:
                            if state[x] == U:
                                state[x] = B
                                if not inq[x]:
                                    queue.append(x); inq[x] = True

                    # Adjacent duplicate pair inside this group: if two cells with same number adjacent,
                    # they cannot both be black if group size==2, but if group size>2 it's still true (adjacency rule),
                    # and to satisfy duplicate constraint, at least all but one must be black; for adjacent pair, at least one white.
                    # We'll enforce: if in a group, all but two are already black, and the remaining two are adjacent unknowns,
                    # then exactly one must be white (so they can't both be black); weak forcing not implemented here beyond k=2.

                # Check adjacency black violations quickly
                for i2, s2 in enumerate(state):
                    if s2 == B:
                        for j in neigh[i2]:
                            if state[j] == B:
                                return False

                # Connectivity pruning
                if not connectivity_ok(state):
                    return False

        return True

    def is_complete(state):
        return all(s != U for s in state)

    def all_constraints_ok(state):
        # Groups
        for cells in group_cells:
            if not group_feasible(state, cells):
                return False
        # Adjacent blacks
        for i in range(N * N):
            if state[i] == B:
                for j in neigh[i]:
                    if state[j] == B:
                        return False
        # Connectivity final: all whites connected
        # If complete, enforce all non-black (=white) connected
        if is_complete(state):
            whites = [i for i, s in enumerate(state) if s != B]
            if not whites:
                return False
            seen = set([whites[0]])
            q = deque([whites[0]])
            while q:
                x = q.popleft()
                for y in neigh[x]:
                    if state[y] != B and y not in seen:
                        seen.add(y); q.append(y)
            if len(seen) != len(whites):
                return False
        else:
            if not connectivity_ok(state):
                return False
        return True

    def choose_branch_cell(state):
        # Pick cell that is in the "tightest" duplicate group with many requirements.
        best = None
        best_score = -1

        # Prefer cells in groups where already one white exists (then others forced black already via propagation)
        # Otherwise pick from groups with size k and low unknown count.
        for cells in group_cells:
            unk = [x for x in cells if state[x] == U]
            if not unk:
                continue
            whites = sum(1 for x in cells if state[x] == W)
            blacks = sum(1 for x in cells if state[x] == B)
            k = len(cells)
            # need at least k-1 blacks; deficit:
            deficit = max(0, (k - 1) - blacks)
            # unknown tightness:
            tight = (deficit, len(unk), -k, whites)
            # Convert to score: smaller unk and higher deficit is more constrained
            score = (deficit * 1000) - (len(unk) * 10) + (k * 2) + (whites * 50)
            # Additionally, adjacency: if a cell has a black neighbor, it can't be black -> must be white (prop should do), so not here.
            if score > best_score:
                # choose a representative unknown cell, but prefer one adjacent to unknowns for connectivity impact
                cand = None
                cand_score = -1
                for x in unk:
                    local = sum(1 for y in neigh[x] if state[y] == U) + sum(1 for y in neigh[x] if state[y] == W)
                    if local > cand_score:
                        cand_score = local
                        cand = x
                best = cand
                best_score = score

        if best is not None:
            return best

        # Fallback: any unknown cell with most constraints (neighbors + groups)
        for i in range(N * N):
            if state[i] == U:
                score = len(cell_groups[i]) * 10 + len(neigh[i])
                if score > best_score:
                    best_score = score
                    best = i
        return best

    def dfs(state):
        if not all_constraints_ok(state):
            return None
        if is_complete(state):
            return state

        v = choose_branch_cell(state)
        if v is None:
            return None

        # Branch order heuristic:
        # Try black first if it helps satisfy duplicate groups (most cells in duplicate groups tend to be black).
        # But if any neighbor is black, black is impossible (should have been forced to white).
        can_black = all(state[j] != B for j in neigh[v])
        # Also black might disconnect forced whites; propagate will test.
        branches = []
        if can_black:
            branches.append(B)
        branches.append(W)  # always can try white

        for val in branches:
            st2 = state[:]  # copy
            q = deque()
            st2[v] = val
            q.append(v)
            if propagate(st2, q):
                res = dfs(st2)
                if res is not None:
                    return res
        return None

    init = [U] * (N * N)
    if not propagate(init, deque()):
        return "No Solution"
    sol = dfs(init)
    if sol is None:
        return "No Solution"

    # Build required mask: 'B' for black else None
    out = []
    for r in range(N):
        row = []
        for c in range(N):
            s = sol[idx(r, c)]
            row.append('B' if s == B else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[5, 1, 2, 8, 7, 1, 4, 9, 8, 9], [8, 2, 10, 4, 9, 3, 6, 9, 1, 8], [1, 7, 7, 8, 4, 4, 9, 2, 9, 5], [4, 6, 9, 4, 8, 2, 9, 3, 6, 8], [6, 9, 1, 7, 9, 8, 2, 2, 5, 3], [1, 6, 3, 9, 1, 3, 8, 7, 8, 4], [9, 5, 7, 10, 5, 1, 4, 10, 4, 1], [8, 3, 1, 6, 2, 9, 5, 1, 5, 9], [9, 4, 5, 10, 8, 9, 10, 8, 3, 1], [3, 5, 10, 1, 4, 7, 10, 1, 9, 3]]}
from collections import deque, defaultdict

# Hitori solver (blacken cells) with strong, human-like deduction:
# - "No duplicates in white" => for each equal pair in row/col, at least one must be black.
# - Black cells cannot be orthogonally adjacent.
# - All whites connected.
# Deductions used:
#   1) Forced by adjacency: if a cell is black => its orthogonal neighbors are white.
#   2) Duplicate elimination:
#        - If in a row/col a value has all but one occurrences forced white, remaining must be black.
#        - If in a row/col a value has one occurrence forced black, remaining occurrences must be white if only one left? (handled by constraints)
#   3) Pair/triple reasoning via "hitting set" within row/col value-groups: maintain for each group (row,value) and (col,value)
#        constraint that at most one member is white, i.e., among k occurrences, at least k-1 are black.
#        Implemented as: if x is white -> all others in group must be black.
#   4) Connectivity pruning:
#        - Whites must be connected; we enforce during search with fast checks:
#            a) No white cell can be isolated (all neighbors black/outside) unless it's the only white.
#            b) Articulation-style cut is expensive; instead we maintain reachability lower bound:
#               if current white cells form >1 components separated by forced blacks AND cannot be connected by undecided cells => fail.
#            c) Also ensure black cells do not create 2x2 all-black? (not a rule) => not used.
#   5) Branching heuristic:
#        - Prefer cells involved in duplicate groups with highest pressure (largest group size / most constraints).
#        - Try setting BLACK first when group requires many blacks.

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    if n == 0 or m == 0 or n != m:
        return "No Solution"
    N = n

    # Indexing helpers
    def idx(r, c): return r * N + c
    def rc(i): return divmod(i, N)

    # Precompute neighbors
    neigh = [[] for _ in range(N*N)]
    for r in range(N):
        for c in range(N):
            i = idx(r, c)
            if r > 0: neigh[i].append(idx(r-1, c))
            if r+1 < N: neigh[i].append(idx(r+1, c))
            if c > 0: neigh[i].append(idx(r, c-1))
            if c+1 < N: neigh[i].append(idx(r, c+1))

    # Build duplicate groups: list of cell indices for each (row,val) with count>1 and (col,val) with count>1
    row_groups = defaultdict(list)
    col_groups = defaultdict(list)
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            row_groups[(r, v)].append(idx(r, c))
            col_groups[(c, v)].append(idx(r, c))

    groups = []
    for k, cells in row_groups.items():
        if len(cells) > 1:
            groups.append(cells)
    for k, cells in col_groups.items():
        if len(cells) > 1:
            groups.append(cells)

    cell_groups = [[] for _ in range(N*N)]
    for gi, cells in enumerate(groups):
        for i in cells:
            cell_groups[i].append(gi)

    # State values: -1 unknown, 0 white, 1 black
    UNKNOWN, WHITE, BLACK = -1, 0, 1

    # For each group, we need at most one WHITE. Equivalent:
    # - If one member is WHITE => all others BLACK.
    # Track chosen white (index) or -1 if none forced.
    # Track count of forced black in group to allow deductions.
    group_size = [len(cells) for cells in groups]

    # Fast group lookup arrays
    groups_arr = [tuple(cells) for cells in groups]

    # Propagation engine using a queue of assignments
    def propagate(state, gw, gblackcnt, queue):
        # queue items: (cell_index, value)
        while queue:
            i, val = queue.pop()
            cur = state[i]
            if cur == val:
                continue
            if cur != UNKNOWN and cur != val:
                return False

            state[i] = val

            if val == BLACK:
                # No adjacent blacks: neighbors must be WHITE
                for j in neigh[i]:
                    if state[j] == BLACK:
                        return False
                    if state[j] == UNKNOWN:
                        queue.append((j, WHITE))
            else:
                # If WHITE, enforce group: all other duplicates in each group become BLACK
                for gi in cell_groups[i]:
                    if gw[gi] == -1:
                        gw[gi] = i
                        for j in groups_arr[gi]:
                            if j != i:
                                if state[j] == WHITE:
                                    return False
                                if state[j] == UNKNOWN:
                                    queue.append((j, BLACK))
                    else:
                        if gw[gi] != i:
                            # another white already chosen -> conflict
                            return False

            # Update group black counts and possibly force remaining
            if val == BLACK:
                for gi in cell_groups[i]:
                    gblackcnt[gi] += 1
                    # In a group of size k, we need at least k-1 black, i.e., at most one white.
                    # If blacks reach k-1, remaining unknowns must be WHITE (and also there can be no chosen white among them conflict).
                    k = group_size[gi]
                    if gblackcnt[gi] == k:
                        # all black => then no white remains, but is it allowed? Yes (duplicates all removed), no rule forbids.
                        pass
                    if gblackcnt[gi] == k - 1:
                        # remaining non-black cells (unknown or possibly white) must be WHITE if not already black
                        for j in groups_arr[gi]:
                            if state[j] == UNKNOWN:
                                queue.append((j, WHITE))
                        # If gw already points to a black cell (shouldn't happen), ignore; gw is only set on white.
            # If WHITE, group black counts will increase via enqueued blacks; handled later.

        return True

    def connectivity_possible(state):
        # Determine if all current WHITE cells are connected in the graph of non-BLACK cells,
        # and whether remaining UNKNOWN cells could connect components.
        # We perform BFS over cells that are not BLACK (WHITE or UNKNOWN) but treat BLACK as walls.
        # Condition for failure: WHITE cells exist and belong to >1 component in this "possible" graph.
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return True
        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            i = dq.popleft()
            for j in neigh[i]:
                if state[j] != BLACK and j not in seen:
                    seen.add(j)
                    dq.append(j)
        # all whites must be in the same possible component
        for w in whites:
            if w not in seen:
                return False

        # Additional pruning: no forced WHITE can be isolated (unless it's the only white)
        if len(whites) > 1:
            for w in whites:
                if all(state[j] == BLACK for j in neigh[w]):
                    return False
        return True

    def finalize_connected_whites(state):
        # Once fully assigned, check all WHITE connected and no duplicates among whites guaranteed by constraints.
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return False
        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            i = dq.popleft()
            for j in neigh[i]:
                if state[j] == WHITE and j not in seen:
                    seen.add(j)
                    dq.append(j)
        return len(seen) == len(whites)

    def choose_branch_cell(state, gw, gblackcnt):
        # Pick an UNKNOWN cell with highest constraint pressure:
        # score by sum over groups: (size-1 - blackcnt) remaining blacks needed, plus group size.
        best = -1
        best_score = -1
        for i, v in enumerate(state):
            if v != UNKNOWN:
                continue
            score = 0
            for gi in cell_groups[i]:
                k = group_size[gi]
                need = max(0, (k - 1) - gblackcnt[gi])
                score += (need * 10 + k)
                if gw[gi] != -1:
                    # if a white already chosen in this group, this cell is effectively forced black; strong
                    score += 50
            # Also consider adjacency to BLACK: if adjacent to black, cannot be black -> reduces branching
            adj_black = sum(1 for j in neigh[i] if state[j] == BLACK)
            score += adj_black * 5
            if score > best_score:
                best_score = score
                best = i
        return best

    def clone_state(state, gw, gblackcnt):
        return state[:], gw[:], gblackcnt[:]

    # Initial state
    state0 = [UNKNOWN] * (N*N)
    gw0 = [-1] * len(groups_arr)
    gblackcnt0 = [0] * len(groups_arr)

    # Early deterministic propagation:
    # If a duplicate group has size 2 and the two cells are orthogonally adjacent,
    # they cannot both be black (adjacency rule) and cannot both be white (duplicate rule),
    # so exactly one is black and one is white. We don't know which, but we can derive:
    # if one is forced black elsewhere, the other must be white, etc. Handled by propagation.
    # No unconditional assignment possible here.

    # Search with propagation
    def dfs(state, gw, gblackcnt):
        # Connectivity feasibility check
        if not connectivity_possible(state):
            return None

        # If complete assignment, validate final connectivity
        if all(v != UNKNOWN for v in state):
            if finalize_connected_whites(state):
                return state
            return None

        i = choose_branch_cell(state, gw, gblackcnt)
        if i == -1:
            return None

        # Decide branching order: prefer BLACK if it helps satisfy duplicate groups (i in any group w/o chosen white),
        # unless adjacent to BLACK (then BLACK impossible).
        can_black = all(state[j] != BLACK for j in neigh[i])
        can_white = True  # always possible unless group already has other white (prop will detect)

        # Heuristic: if any group already has a chosen white and i is in it -> i forced black.
        forced_black = any(gw[gi] != -1 and gw[gi] != i for gi in cell_groups[i])
        if forced_black:
            can_white = False

        branches = []
        if can_black and (forced_black or True):
            branches.append(BLACK)
        if can_white:
            branches.append(WHITE)

        # Better order: if cell participates in large groups needing blacks, try BLACK first.
        # If adjacent to BLACK, must be WHITE.
        if not can_black and can_white:
            branches = [WHITE]
        elif can_black and not can_white:
            branches = [BLACK]
        else:
            black_pressure = 0
            white_pressure = 0
            for gi in cell_groups[i]:
                k = group_size[gi]
                need = max(0, (k - 1) - gblackcnt[gi])
                black_pressure += need * 2 + k
                if gw[gi] != -1:
                    white_pressure += 100
            adjb = sum(1 for j in neigh[i] if state[j] == BLACK)
            # if near black, less likely to be black
            if adjb:
                white_pressure += 20 * adjb
            if white_pressure > black_pressure:
                branches = [WHITE, BLACK] if can_black else [WHITE]

        for val in branches:
            st, gww, gbc = clone_state(state, gw, gblackcnt)
            q = [(i, val)]
            if propagate(st, gww, gbc, q):
                res = dfs(st, gww, gbc)
                if res is not None:
                    return res
        return None

    result_state = dfs(state0, gw0, gblackcnt0)
    if result_state is None:
        return "No Solution"

    # Convert to mask 'B'/None
    mask = [[None for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            v = result_state[idx(r, c)]
            if v == BLACK:
                mask[r][c] = 'B'
            else:
                mask[r][c] = None
    return str(mask)

if __name__ == "__main__":
    print(solve(OBSERVATION))

