from __future__ import annotations

# Futoshiki / Inequality Latin Square solver
# - Strong constraint propagation (arc consistency + inequality bounds pruning)
# - Human-like deductions: singles, hidden singles, inequality min/max tightening, AC-3
# - Search only when necessary using MRV + degree heuristic + value ordering

from collections import deque
from typing import Dict, List, Optional, Set, Tuple

Coord = Tuple[int, int]


def solve(observation):
    data = observation["data"]
    N = len(data)
    horiz_raw = observation.get("horizontal", {})
    vert_raw = observation.get("vertical", {})

    # Parse constraint dictionaries with keys like "(r, c+0.5)" / "(r+0.5, c)"
    def parse_key(k: str) -> Tuple[float, float]:
        k = k.strip()
        if k[0] == "(" and k[-1] == ")":
            k = k[1:-1]
        a, b = k.split(",")
        return float(a.strip()), float(b.strip())

    horiz = {}
    for k, v in horiz_raw.items():
        r, c = parse_key(k)
        # r is integer, c is x.5
        rr = int(round(r))
        cc2 = int(round(c * 2))
        # col between cc2/2 - but we store left cell col as integer
        # For c = col + 0.5 => 2c = 2col+1 => col = (2c-1)//2
        left_c = (cc2 - 1) // 2
        horiz[(rr, left_c)] = v  # between (rr,left_c) and (rr,left_c+1)

    vert = {}
    for k, v in vert_raw.items():
        r, c = parse_key(k)
        cc = int(round(c))
        rr2 = int(round(r * 2))
        top_r = (rr2 - 1) // 2
        vert[(top_r, cc)] = v  # between (top_r,cc) and (top_r+1,cc)

    # Domains
    full = set(range(1, N + 1))
    dom: List[List[Set[int]]] = [[set(full) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                v = int(data[r][c])
                dom[r][c] = {v}

    # Build neighbors for row/col all-different (binary not-equal constraints)
    row_cells = [[(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[(r, c) for r in range(N)] for c in range(N)]

    # Inequality constraints list as directed arcs with relation type
    # For horizontal at (r, c): between (r,c) and (r,c+1)
    #   '<' means left < right
    #   '>' means left > right
    # For vertical at (r, c): between (r,c) and (r+1,c)
    #   '^' means top < bottom (arrow up indicates smaller on top? We'll interpret as top < bottom when '^')
    #   'v' means top > bottom when 'v'
    # This is consistent with many futoshiki conventions where '^' placed between means upper is smaller.
    ineq_arcs: List[Tuple[Coord, Coord, str]] = []
    for (r, c), sym in horiz.items():
        a = (r, c)
        b = (r, c + 1)
        if sym == "<":
            ineq_arcs.append((a, b, "<"))
        elif sym == ">":
            ineq_arcs.append((a, b, ">"))
    for (r, c), sym in vert.items():
        a = (r, c)
        b = (r + 1, c)
        if sym == "^":
            ineq_arcs.append((a, b, "<"))  # top < bottom
        elif sym == "v":
            ineq_arcs.append((a, b, ">"))  # top > bottom

    # Helper: apply row/col elimination from singles (fast)
    def propagate_singles(queue: deque[Coord]) -> bool:
        while queue:
            r, c = queue.popleft()
            if len(dom[r][c]) != 1:
                continue
            v = next(iter(dom[r][c]))
            # Row
            for cc in range(N):
                if cc == c:
                    continue
                if v in dom[r][cc]:
                    dom[r][cc].discard(v)
                    if not dom[r][cc]:
                        return False
                    if len(dom[r][cc]) == 1:
                        queue.append((r, cc))
            # Col
            for rr in range(N):
                if rr == r:
                    continue
                if v in dom[rr][c]:
                    dom[rr][c].discard(v)
                    if not dom[rr][c]:
                        return False
                    if len(dom[rr][c]) == 1:
                        queue.append((rr, c))
        return True

    # Hidden singles in a unit (row/col)
    def hidden_singles() -> bool:
        changed = False
        # Rows
        for r in range(N):
            positions: Dict[int, List[int]] = {v: [] for v in range(1, N + 1)}
            for c in range(N):
                for v in dom[r][c]:
                    positions[v].append(c)
            for v, cols in positions.items():
                if len(cols) == 1:
                    c = cols[0]
                    if dom[r][c] != {v}:
                        dom[r][c] = {v}
                        changed = True
        # Cols
        for c in range(N):
            positions: Dict[int, List[int]] = {v: [] for v in range(1, N + 1)}
            for r in range(N):
                for v in dom[r][c]:
                    positions[v].append(r)
            for v, rows in positions.items():
                if len(rows) == 1:
                    r = rows[0]
                    if dom[r][c] != {v}:
                        dom[r][c] = {v}
                        changed = True
        return changed

    # Inequality bounds tightening: for a < b:
    #   remove values from A that are >= max(B)
    #   remove values from B that are <= min(A)
    def tighten_inequalities() -> bool:
        changed = False
        for (ar, ac), (br, bc), rel in ineq_arcs:
            A = dom[ar][ac]
            B = dom[br][bc]
            if not A or not B:
                return False  # contradiction already
            if rel == "<":
                maxB = max(B)
                minA = min(A)
                # A must be <= maxB-1
                newA = {x for x in A if x < maxB}
                if newA != A:
                    dom[ar][ac] = newA
                    if not newA:
                        return False
                    changed = True
                    A = newA
                    minA = min(A)
                # B must be >= minA+1
                newB = {y for y in B if y > minA}
                if newB != B:
                    dom[br][bc] = newB
                    if not newB:
                        return False
                    changed = True
            else:  # ">"
                maxA = max(A)
                minB = min(B)
                # A must be >= minB+1
                newA = {x for x in A if x > minB}
                if newA != A:
                    dom[ar][ac] = newA
                    if not newA:
                        return False
                    changed = True
                    A = newA
                    maxA = max(A)
                # B must be <= maxA-1
                newB = {y for y in B if y < maxA}
                if newB != B:
                    dom[br][bc] = newB
                    if not newB:
                        return False
                    changed = True
        return changed

    # AC-3 for binary constraints (not-equal in row/col, plus inequalities)
    # We model all arcs explicitly for stronger pruning.
    def ac3() -> bool:
        q = deque()

        # not-equal arcs for rows and cols (dense but manageable for N<=9-ish)
        for r in range(N):
            for c1 in range(N):
                for c2 in range(N):
                    if c1 != c2:
                        q.append(((r, c1), (r, c2), "!="))
        for c in range(N):
            for r1 in range(N):
                for r2 in range(N):
                    if r1 != r2:
                        q.append(((r1, c), (r2, c), "!="))

        # inequality arcs both directions
        for a, b, rel in ineq_arcs:
            q.append((a, b, rel))
            q.append((b, a, ">" if rel == "<" else "<"))

        def revise(x: Coord, y: Coord, rel: str) -> bool:
            xr, xc = x
            yr, yc = y
            Dx = dom[xr][xc]
            Dy = dom[yr][yc]
            removed = False
            if rel == "!=":
                if len(Dy) == 1:
                    v = next(iter(Dy))
                    if v in Dx:
                        Dx = set(Dx)
                        Dx.discard(v)
                        removed = True
            elif rel == "<":
                # keep x values that have some y > x
                maxy = max(Dy)
                newDx = {vx for vx in Dx if vx < maxy}
                if newDx != Dx:
                    Dx = newDx
                    removed = True
            else:  # ">"
                miny = min(Dy)
                newDx = {vx for vx in Dx if vx > miny}
                if newDx != Dx:
                    Dx = newDx
                    removed = True

            if removed:
                dom[xr][xc] = Dx
                if not Dx:
                    return False
            return True

        # adjacency list to re-enqueue neighbors efficiently
        neighbors: Dict[Coord, Set[Coord]] = {(r, c): set() for r in range(N) for c in range(N)}
        for r in range(N):
            for c1 in range(N):
                for c2 in range(N):
                    if c1 != c2:
                        neighbors[(r, c1)].add((r, c2))
        for c in range(N):
            for r1 in range(N):
                for r2 in range(N):
                    if r1 != r2:
                        neighbors[(r1, c)].add((r2, c))
        ineq_map: Dict[Tuple[Coord, Coord], str] = {}
        for a, b, rel in ineq_arcs:
            ineq_map[(a, b)] = rel
            ineq_map[(b, a)] = ">" if rel == "<" else "<"
            neighbors[a].add(b)
            neighbors[b].add(a)

        while q:
            x, y, rel = q.popleft()
            before = dom[x[0]][x[1]]
            ok = revise(x, y, rel)
            if not ok:
                return False
            after = dom[x[0]][x[1]]
            if after is not before and after != before:
                # re-enqueue all z->x arcs
                for z in neighbors[x]:
                    if z == y:
                        continue
                    # determine relation z->x
                    if z[0] == x[0] and z[1] != x[1]:
                        q.append((z, x, "!="))
                    elif z[1] == x[1] and z[0] != x[0]:
                        q.append((z, x, "!="))
                    else:
                        relzx = ineq_map.get((z, x))
                        if relzx:
                            q.append((z, x, relzx))
        return True

    def is_solved() -> bool:
        for r in range(N):
            for c in range(N):
                if len(dom[r][c]) != 1:
                    return False
        return True

    def snapshot():
        return [[set(dom[r][c]) for c in range(N)] for r in range(N)]

    def restore(snap):
        for r in range(N):
            for c in range(N):
                dom[r][c] = snap[r][c]

    def deterministic_propagation() -> bool:
        # Iterate until fixpoint using several human-like rules
        q = deque()
        for r in range(N):
            for c in range(N):
                if len(dom[r][c]) == 1:
                    q.append((r, c))
        if not propagate_singles(q):
            return False

        while True:
            changed = False
            # inequality min/max tightening
            t = tighten_inequalities()
            if t is False:
                return False
            if t:
                changed = True
            # run singles again after tightening
            q2 = deque()
            for r in range(N):
                for c in range(N):
                    if len(dom[r][c]) == 1:
                        q2.append((r, c))
            if not propagate_singles(q2):
                return False
            # hidden singles
            if hidden_singles():
                changed = True
                q3 = deque()
                for r in range(N):
                    for c in range(N):
                        if len(dom[r][c]) == 1:
                            q3.append((r, c))
                if not propagate_singles(q3):
                    return False
            # AC-3 occasionally for stronger pruning
            if changed:
                if not ac3():
                    return False
                # after AC3, enforce singles quickly
                q4 = deque()
                for r in range(N):
                    for c in range(N):
                        if len(dom[r][c]) == 1:
                            q4.append((r, c))
                if not propagate_singles(q4):
                    return False
                continue
            break
        return True

    def select_unassigned() -> Optional[Coord]:
        best = None
        best_key = None
        for r in range(N):
            for c in range(N):
                k = len(dom[r][c])
                if k > 1:
                    # degree heuristic: count constraints with other unassigned in row/col + inequalities
                    deg = 0
                    for cc in range(N):
                        if cc != c and len(dom[r][cc]) > 1:
                            deg += 1
                    for rr in range(N):
                        if rr != r and len(dom[rr][c]) > 1:
                            deg += 1
                    # inequalities
                    for a, b, _ in ineq_arcs:
                        if a == (r, c) and len(dom[b[0]][b[1]]) > 1:
                            deg += 1
                        elif b == (r, c) and len(dom[a[0]][a[1]]) > 1:
                            deg += 1
                    key = (k, -deg)
                    if best is None or key < best_key:
                        best = (r, c)
                        best_key = key
        return best

    def order_values(cell: Coord) -> List[int]:
        r, c = cell
        # Least-constraining value: prefer values that appear less in peers
        peers = set((r, cc) for cc in range(N) if cc != c) | set((rr, c) for rr in range(N) if rr != r)
        freq = {}
        for v in dom[r][c]:
            cnt = 0
            for pr, pc in peers:
                if v in dom[pr][pc]:
                    cnt += 1
            freq[v] = cnt
        return sorted(dom[r][c], key=lambda v: (freq[v], v))

    def dfs() -> bool:
        if not deterministic_propagation():
            return False
        if is_solved():
            return True
        cell = select_unassigned()
        if cell is None:
            return False
        r, c = cell
        values = order_values(cell)
        snap = snapshot()
        for v in values:
            restore(snap)
            dom[r][c] = {v}
            if dfs():
                return True
        restore(snap)
        return False

    if not dfs():
        return "No Solution"

    solved = [[next(iter(dom[r][c])) for c in range(N)] for r in range(N)]
    return str(solved)


if __name__ == "__main__":
    print(solve(OBSERVATION))

