from collections import deque

# Solver for Binary Puzzle / Takuzu with extra adjacency constraints (=, x).
# Uses aggressive propagation: adjacency constraints, no-3-in-a-row, row/col balance,
# and line pattern forcing (human-like deductions), plus low-branching search with MRV.

B, W = 1, 0

def solve(observation):
    grid0 = observation["data"]
    n = len(grid0)
    if n == 0 or any(len(r) != n for r in grid0):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"

    # Parse constraints into fast lookup
    hcon = {}  # between (r,c) and (r,c+1): key (r,c) -> 1 for "=", -1 for "x"
    vcon = {}  # between (r,c) and (r+1,c): key (r,c) -> 1 for "=", -1 for "x"

    def parse_key(s):
        s = s.strip()
        if s[0] == "(" and s[-1] == ")":
            s = s[1:-1]
        a, b = s.split(",")
        return float(a.strip()), float(b.strip())

    for k, val in observation.get("horizontal", {}).items():
        r, c = parse_key(k)
        # r integer, c .5
        rr = int(round(r))
        cc = int(round(c - 0.5))
        hcon[(rr, cc)] = 1 if val == "=" else -1

    for k, val in observation.get("vertical", {}).items():
        r, c = parse_key(k)
        # r .5, c integer
        rr = int(round(r - 0.5))
        cc = int(round(c))
        vcon[(rr, cc)] = 1 if val == "=" else -1

    # Build domains: bitmask 1<<0 for W, 1<<1 for B
    ALL = 0b11
    dom = [[ALL] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = grid0[r][c]
            if v == "B":
                dom[r][c] = 0b10
            elif v == "W":
                dom[r][c] = 0b01
            elif v is None:
                dom[r][c] = ALL
            else:
                return "No Solution"

    # Utility
    def popcount(x):
        return (x & 1) + ((x >> 1) & 1)

    def is_single(x):
        return x == 1 or x == 2

    def mask_to_val(x):
        return W if x == 1 else B

    def val_to_mask(v):
        return 1 if v == W else 2

    def other(v):
        return B if v == W else W

    def iter_line_cells(is_row, idx):
        if is_row:
            return [(idx, c) for c in range(n)]
        else:
            return [(r, idx) for r in range(n)]

    # Queue-based propagation on assignments and line updates
    q = deque()

    def enqueue_cell(r, c):
        q.append(("cell", r, c))
        q.append(("line", 1, r))  # row
        q.append(("line", 0, c))  # col

    # Initialize queue with all fixed cells
    for r in range(n):
        for c in range(n):
            if is_single(dom[r][c]):
                enqueue_cell(r, c)

    def intersect(r, c, newmask):
        m = dom[r][c] & newmask
        if m == 0:
            return False
        if m != dom[r][c]:
            dom[r][c] = m
            if is_single(m):
                enqueue_cell(r, c)
            else:
                q.append(("line", 1, r))
                q.append(("line", 0, c))
                q.append(("cell", r, c))
        return True

    def apply_adj_constraints(r, c):
        # Apply "=" / "x" constraints to neighbors based on current domain (binary)
        m = dom[r][c]

        # Horizontal left constraint between (r,c-1)-(r,c) stored at (r,c-1)
        if c - 1 >= 0 and (r, c - 1) in hcon:
            rel = hcon[(r, c - 1)]
            m2 = dom[r][c - 1]
            # enforce relation between m2 and m
            if rel == 1:  # equal
                # both must be same; restrict each to intersection with other
                if not intersect(r, c, m2):
                    return False
                if not intersect(r, c - 1, m):
                    return False
            else:  # different
                # If one is single, force opposite on other. In general prune inconsistent pairs:
                # Since only two values, "different" means mask must be complement.
                if is_single(m):
                    v = mask_to_val(m)
                    if not intersect(r, c - 1, val_to_mask(other(v))):
                        return False
                if is_single(m2):
                    v = mask_to_val(m2)
                    if not intersect(r, c, val_to_mask(other(v))):
                        return False
                # If both are not single, no pruning beyond that (already binary).
        # Horizontal right
        if c + 1 < n and (r, c) in hcon:
            rel = hcon[(r, c)]
            m2 = dom[r][c + 1]
            if rel == 1:
                if not intersect(r, c, m2):
                    return False
                if not intersect(r, c + 1, m):
                    return False
            else:
                if is_single(m):
                    v = mask_to_val(m)
                    if not intersect(r, c + 1, val_to_mask(other(v))):
                        return False
                if is_single(m2):
                    v = mask_to_val(m2)
                    if not intersect(r, c, val_to_mask(other(v))):
                        return False
        # Vertical up constraint between (r-1,c)-(r,c) stored at (r-1,c)
        if r - 1 >= 0 and (r - 1, c) in vcon:
            rel = vcon[(r - 1, c)]
            m2 = dom[r - 1][c]
            if rel == 1:
                if not intersect(r, c, m2):
                    return False
                if not intersect(r - 1, c, m):
                    return False
            else:
                if is_single(m):
                    v = mask_to_val(m)
                    if not intersect(r - 1, c, val_to_mask(other(v))):
                        return False
                if is_single(m2):
                    v = mask_to_val(m2)
                    if not intersect(r, c, val_to_mask(other(v))):
                        return False
        # Vertical down
        if r + 1 < n and (r, c) in vcon:
            rel = vcon[(r, c)]
            m2 = dom[r + 1][c]
            if rel == 1:
                if not intersect(r, c, m2):
                    return False
                if not intersect(r + 1, c, m):
                    return False
            else:
                if is_single(m):
                    v = mask_to_val(m)
                    if not intersect(r + 1, c, val_to_mask(other(v))):
                        return False
                if is_single(m2):
                    v = mask_to_val(m2)
                    if not intersect(r, c, val_to_mask(other(v))):
                        return False
        return True

    def enforce_no_three_line(is_row, idx):
        # For each triple window, enforce that not all three same.
        cells = iter_line_cells(is_row, idx)
        # access by index
        for i in range(n - 2):
            (r1, c1), (r2, c2), (r3, c3) = cells[i], cells[i + 1], cells[i + 2]
            m1, m2, m3 = dom[r1][c1], dom[r2][c2], dom[r3][c3]
            # If two are fixed same, third cannot be that
            if is_single(m1) and is_single(m2) and m1 == m2:
                if not intersect(r3, c3, ALL ^ m1):
                    return False
            if is_single(m2) and is_single(m3) and m2 == m3:
                if not intersect(r1, c1, ALL ^ m2):
                    return False
            if is_single(m1) and is_single(m3) and m1 == m3:
                # pattern X ? X => middle must be opposite
                if not intersect(r2, c2, ALL ^ m1):
                    return False
        return True

    def enforce_balance_line(is_row, idx):
        # Each line must have exactly n/2 of each color.
        cells = iter_line_cells(is_row, idx)
        fixed_b = fixed_w = 0
        unknown = []
        for (r, c) in cells:
            m = dom[r][c]
            if m == 2:
                fixed_b += 1
            elif m == 1:
                fixed_w += 1
            else:
                unknown.append((r, c))
        half = n // 2
        if fixed_b > half or fixed_w > half:
            return False
        # If one color reached half, rest must be the other
        if fixed_b == half:
            for (r, c) in unknown:
                if not intersect(r, c, 1):
                    return False
        if fixed_w == half:
            for (r, c) in unknown:
                if not intersect(r, c, 2):
                    return False
        # If number of unknown equals remaining needed of one color => force all unknown accordingly?
        # Actually remaining_B = half - fixed_b, remaining_W = half - fixed_w, and unknown_count = remaining_B + remaining_W
        # No direct unless remaining_B==0 or remaining_W==0 handled above.
        return True

    def enforce_constraint_pair_logic():
        # Human-like: If "=" edge and one side fixed -> other fixed; for "x" similar.
        # Already handled by apply_adj_constraints when cell processed; this is a cheap sweep for non-triggered.
        for r in range(n):
            for c in range(n - 1):
                if (r, c) in hcon:
                    rel = hcon[(r, c)]
                    m1, m2 = dom[r][c], dom[r][c + 1]
                    if rel == 1:
                        # both same -> intersect
                        if not intersect(r, c, m2): return False
                        if not intersect(r, c + 1, m1): return False
                    else:
                        if is_single(m1):
                            if not intersect(r, c + 1, ALL ^ m1): return False
                        if is_single(m2):
                            if not intersect(r, c, ALL ^ m2): return False
        for r in range(n - 1):
            for c in range(n):
                if (r, c) in vcon:
                    rel = vcon[(r, c)]
                    m1, m2 = dom[r][c], dom[r + 1][c]
                    if rel == 1:
                        if not intersect(r, c, m2): return False
                        if not intersect(r + 1, c, m1): return False
                    else:
                        if is_single(m1):
                            if not intersect(r + 1, c, ALL ^ m1): return False
                        if is_single(m2):
                            if not intersect(r, c, ALL ^ m2): return False
        return True

    def propagate():
        # Seed sweep constraints once
        if not enforce_constraint_pair_logic():
            return False
        for i in range(n):
            if not enforce_balance_line(True, i): return False
            if not enforce_balance_line(False, i): return False
            if not enforce_no_three_line(True, i): return False
            if not enforce_no_three_line(False, i): return False

        while q:
            typ, a, b = q.popleft()
            if typ == "cell":
                r, c = a, b
                if dom[r][c] == 0:
                    return False
                if not apply_adj_constraints(r, c):
                    return False
                # no-3 local via line checks is handled by line events, but cheap local check:
                if not enforce_no_three_line(True, r): return False
                if not enforce_no_three_line(False, c): return False
                if not enforce_balance_line(True, r): return False
                if not enforce_balance_line(False, c): return False
            else:  # line
                is_row = bool(a)
                idx = b
                if not enforce_balance_line(is_row, idx): return False
                if not enforce_no_three_line(is_row, idx): return False
        return True

    def is_solved():
        for r in range(n):
            for c in range(n):
                if not is_single(dom[r][c]):
                    return False
        return True

    def choose_cell():
        # MRV: pick smallest domain >1
        best = None
        best_sz = 3
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                if m == 3:
                    if best_sz > 2:
                        best = (r, c)
                        best_sz = 2
        return best

    def snapshot():
        return [row[:] for row in dom], deque(q)

    def restore(snap):
        nonlocal dom, q
        dom, q = snap[0], snap[1]

    def dfs():
        if not propagate():
            return False
        if is_solved():
            return True
        rc = choose_cell()
        if rc is None:
            return False
        r, c = rc
        m = dom[r][c]
        # Value ordering heuristic: try to satisfy balance: pick value that is currently less in row/col
        def line_counts(is_row, idx):
            cells = iter_line_cells(is_row, idx)
            cb = cw = 0
            for (rr, cc) in cells:
                if dom[rr][cc] == 2: cb += 1
                elif dom[rr][cc] == 1: cw += 1
            return cb, cw

        rb, rw = line_counts(True, r)
        cb, cw = line_counts(False, c)
        # score B lower if already many Bs
        order = []
        if m & 2:
            scoreB = (rb + cb)
            order.append((scoreB, 2))
        if m & 1:
            scoreW = (rw + cw)
            order.append((scoreW, 1))
        order.sort(key=lambda x: x[0])

        for _, mv in order:
            snap = snapshot()
            if intersect(r, c, mv):
                if dfs():
                    return True
            restore(snap)
        return False

    if not dfs():
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append("B" if dom[r][c] == 2 else "W")
        out.append(row)
    return out


