# Slant / "Gokigen Naname" solver:
# - Each cell has one diagonal: '/' or '\'
# - Each clue dot specifies number of incident diagonals
# - No closed loops in the resulting segment graph (forest constraint)
#
# Approach:
# - Model each cell choice as creating exactly one edge between two of the four corner dots.
#   '\' connects (r,c)-(r+1,c+1), '/' connects (r,c+1)-(r+1,c)
# - Clues become degree constraints on dots.
# - No-loops enforced dynamically via DSU with cycle detection for forced edges.
# - Human-like propagation:
#   * For each dot: maintain remaining required degree and remaining available incident cells.
#     - If required == 0 => all adjacent undecided cells must choose orientation not incident to dot.
#     - If required == available => all adjacent undecided cells must choose orientation incident to dot.
#   * Also bound check: required < 0 or required > available => contradiction.
# - Search:
#   * Pick next variable by MRV-like heuristic derived from tight dots:
#     choose an undecided cell adjacent to any dot with smallest slack (available-required) or required/available extremes.
#   * Try forced-first ordering when one orientation would immediately violate constraints or create cycle.
#
# This is a generalized solver (no hardcoded instance steps).

from collections import deque

def solve(observation):
    data = observation["data"]
    H = len(data)         # dots rows = N+1
    W = len(data[0])      # dots cols = N+1
    N = H - 1
    if W != N + 1:
        return "No Solution"

    # Map dot (r,c) -> id
    def did(r, c):
        return r * (N + 1) + c

    D = (N + 1) * (N + 1)

    # For each cell (r,c), define the two possible edges:
    # 0 for '\' : (r,c) -- (r+1,c+1)
    # 1 for '/' : (r,c+1) -- (r+1,c)
    cell_edges = []
    incident_cells = [[] for _ in range(D)]  # for each dot, list of (cell_index, orientation_that_is_incident(0/1))
    for r in range(N):
        for c in range(N):
            a0 = did(r, c)
            b0 = did(r + 1, c + 1)
            a1 = did(r, c + 1)
            b1 = did(r + 1, c)
            idx = r * N + c
            cell_edges.append(((a0, b0), (a1, b1)))
            # For each dot, register which orientation causes incidence
            incident_cells[a0].append((idx, 0))
            incident_cells[b0].append((idx, 0))
            incident_cells[a1].append((idx, 1))
            incident_cells[b1].append((idx, 1))

    # Clues degrees: None means no constraint (free)
    clue = [None] * D
    for r in range(N + 1):
        for c in range(N + 1):
            v = data[r][c]
            if v is not None:
                clue[did(r, c)] = int(v)

    # State arrays
    # cell_val: -1 undecided, 0 '\' , 1 '/'
    cell_val = [-1] * (N * N)

    # Degree accounting
    deg = [0] * D  # current number of incident chosen edges (only for dots with clue, but maintained for all)
    # remaining undecided incident "opportunities" per dot depends on choices forced away; we compute on fly with counters
    # We will maintain per dot counts of undecided incident possibilities (cells where at least one orientation would touch)
    # but since each incident record is specific to an orientation, a cell contributes at most once per dot.
    # We'll maintain:
    #   undec_inc[d] = number of incident (cell,ori) pairs still possible (cell undecided or decided matching ori)
    #   but we need "available incident edges still possible to satisfy degree": number of incident pairs whose orientation is still allowed.
    #
    # We'll maintain per cell an allowed mask: bit0 for '\' allowed, bit1 for '/' allowed.
    allowed = [3] * (N * N)

    # DSU for no-cycle constraint on chosen edges
    parent = list(range(D))
    rank = [0] * D

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    # Trail for backtracking
    trail = []

    def mark(var, old):
        trail.append((var, old))

    # Variables stored in trail:
    # ('cell_val', idx, old)
    # ('allowed', idx, oldmask)
    # ('deg', dot, olddeg)
    # ('dsu', changes) where changes = list of (child, oldparent, oldrank_of_root_changed or None)
    # We'll implement DSU undo by recording parent/rank changes for each union.
    def dsu_union_undoable(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return None  # indicates cycle would form
        # union by rank with undo
        changes = []
        if rank[ra] < rank[rb]:
            # parent[ra] becomes rb
            changes.append((ra, parent[ra], None))
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            changes.append((rb, parent[rb], None))
            parent[rb] = ra
        else:
            changes.append((rb, parent[rb], None))
            parent[rb] = ra
            changes.append((ra, None, rank[ra]))  # rank change marker
            rank[ra] += 1
        return changes

    def dsu_undo(changes):
        # reverse apply
        for node, oldp, oldrank in reversed(changes):
            if oldp is not None:
                parent[node] = oldp
            else:
                rank[node] = oldrank

    def dot_required_remaining(d):
        if clue[d] is None:
            return None
        return clue[d] - deg[d]

    def available_for_dot(d):
        # count incident orientations still possible that would add degree if chosen
        cnt = 0
        for ci, ori in incident_cells[d]:
            v = cell_val[ci]
            if v == -1:
                if allowed[ci] & (1 << ori):
                    cnt += 1
            else:
                if v == ori:
                    # already contributing; not "available"
                    pass
                else:
                    pass
        return cnt

    def undecided_incident_cells_for_dot(d):
        # list of (ci,ori) that are still possible and undecided
        res = []
        for ci, ori in incident_cells[d]:
            if cell_val[ci] == -1 and (allowed[ci] & (1 << ori)):
                res.append((ci, ori))
        return res

    def other_ori(ori):
        return 1 - ori

    def forbid_orientation(ci, ori):
        m = allowed[ci]
        if not (m & (1 << ori)):
            return True
        newm = m & ~(1 << ori)
        if newm == 0:
            return False
        mark(('allowed', ci), m)
        allowed[ci] = newm
        return True

    def set_cell(ci, ori):
        # set cell to specific ori, must be allowed
        if cell_val[ci] != -1:
            return cell_val[ci] == ori
        if not (allowed[ci] & (1 << ori)):
            return False

        # before setting, forbid the other orientation (for consistency in propagation)
        if allowed[ci] != (1 << ori):
            mark(('allowed', ci), allowed[ci])
            allowed[ci] = (1 << ori)

        mark(('cell_val', ci), -1)
        cell_val[ci] = ori

        # apply degree increments for the two dots incident to that diagonal
        (u, v) = cell_edges[ci][ori]
        # loop prevention: this edge must not create a cycle
        changes = dsu_union_undoable(u, v)
        if changes is None:
            return False
        mark(('dsu', None), changes)

        # degree updates (only matter if clue exists, but keep for all)
        mark(('deg', u), deg[u])
        deg[u] += 1
        mark(('deg', v), deg[v])
        deg[v] += 1
        return True

    def check_dot_bounds(d):
        if clue[d] is None:
            return True
        rem = clue[d] - deg[d]
        if rem < 0:
            return False
        avail = 0
        for ci, ori in incident_cells[d]:
            v = cell_val[ci]
            if v == -1:
                if allowed[ci] & (1 << ori):
                    avail += 1
            else:
                # decided: contributes only if matches ori, already counted in deg
                pass
        if rem > avail:
            return False
        return True

    def propagate(queue):
        # queue contains dots to re-evaluate
        inq = [False] * D
        for d in queue:
            inq[d] = True
        dq = deque(queue)

        while dq:
            d = dq.popleft()
            inq[d] = False
            if clue[d] is None:
                continue
            if not check_dot_bounds(d):
                return False
            rem = clue[d] - deg[d]
            # gather possible undecided incident orientation assignments
            poss = undecided_incident_cells_for_dot(d)
            avail = len(poss)
            if rem == 0:
                # forbid all incident orientations at this dot in undecided cells
                for ci, ori in poss:
                    if not forbid_orientation(ci, ori):
                        return False
                    # if a cell becomes forced, set it
                    m = allowed[ci]
                    if cell_val[ci] == -1 and (m == 1 or m == 2):
                        forced_ori = 0 if m == 1 else 1
                        if not set_cell(ci, forced_ori):
                            return False
                        # enqueue affected dots
                        u, v = cell_edges[ci][forced_ori]
                        if clue[u] is not None and not inq[u]:
                            dq.append(u); inq[u] = True
                        if clue[v] is not None and not inq[v]:
                            dq.append(v); inq[v] = True
            elif rem == avail:
                # all possible incident orientations must be taken => each involved cell must choose that ori
                for ci, ori in poss:
                    if not set_cell(ci, ori):
                        return False
                    u, v = cell_edges[ci][ori]
                    if clue[u] is not None and not inq[u]:
                        dq.append(u); inq[u] = True
                    if clue[v] is not None and not inq[v]:
                        dq.append(v); inq[v] = True
            # else no direct forced moves
        return True

    # Initial propagation from all clue dots
    init_q = [d for d in range(D) if clue[d] is not None]
    if not propagate(init_q):
        return "No Solution"

    def snapshot():
        return len(trail)

    def rollback(t):
        while len(trail) > t:
            var, old = trail.pop()
            kind = var[0]
            if kind == 'cell_val':
                _, ci = var
                cell_val[ci] = old
            elif kind == 'allowed':
                _, ci = var
                allowed[ci] = old
            elif kind == 'deg':
                _, d = var
                deg[d] = old
            elif kind == 'dsu':
                # old is changes
                dsu_undo(old)
            else:
                raise RuntimeError("bad trail kind")

    def pick_cell():
        # Choose undecided cell with best heuristic:
        # - Prefer cells with allowed mask of size 1 (shouldn't happen without being set, but safe)
        # - Prefer cells adjacent to most constrained dots (min slack)
        best = None
        best_key = None
        for ci in range(N * N):
            if cell_val[ci] != -1:
                continue
            m = allowed[ci]
            if m == 0:
                return None
            # compute constraint score from its 4 corner dots, but only those with clues
            r, c = divmod(ci, N)
            corners = [did(r, c), did(r, c+1), did(r+1, c), did(r+1, c+1)]
            min_slack = 10**9
            sum_tight = 0
            for d in corners:
                if clue[d] is None:
                    continue
                rem = clue[d] - deg[d]
                avail = 0
                for cii, ori in incident_cells[d]:
                    v = cell_val[cii]
                    if v == -1:
                        if allowed[cii] & (1 << ori):
                            avail += 1
                slack = avail - rem
                if slack < min_slack:
                    min_slack = slack
                sum_tight += (100 - slack) if slack < 100 else 0
            domain = 1 if (m == 1 or m == 2) else 2
            key = (domain, min_slack, -sum_tight)
            if best is None or key < best_key:
                best = ci
                best_key = key
        return best

    def orientation_order(ci):
        # Try orientation that is more forced by local degree needs and avoids cycle
        m = allowed[ci]
        opts = []
        for ori in (0, 1):
            if not (m & (1 << ori)):
                continue
            u, v = cell_edges[ci][ori]
            # cycle risk
            cycle = (find(u) == find(v))
            penalty = 0
            if cycle:
                penalty += 1000000
            # dot pressure: if choosing ori satisfies higher rem fraction, prioritize
            pressure = 0
            for d in (u, v):
                if clue[d] is None:
                    continue
                rem = clue[d] - deg[d]
                pressure -= rem  # more remaining => more need => earlier
            opts.append((penalty, pressure, ori))
        opts.sort()
        return [o[2] for o in opts]

    def all_assigned():
        return all(v != -1 for v in cell_val)

    def final_check():
        # All clues satisfied and no cycles already enforced.
        for d in range(D):
            if clue[d] is not None:
                if deg[d] != clue[d]:
                    return False
        return True

    def dfs():
        if all_assigned():
            return final_check()

        ci = pick_cell()
        if ci is None:
            return False

        for ori in orientation_order(ci):
            t = snapshot()
            if set_cell(ci, ori):
                u, v = cell_edges[ci][ori]
                q = []
                if clue[u] is not None:
                    q.append(u)
                if clue[v] is not None and v != u:
                    q.append(v)
                # also neighboring dots impacted via forbidding other orientation already set in allowed
                if propagate(q):
                    if dfs():
                        return True
            rollback(t)
        return False

    ok = dfs()
    if not ok:
        return "No Solution"

    # Build answer grid
    ans = []
    for r in range(N):
        row = []
        for c in range(N):
            v = cell_val[r * N + c]
            row.append('\\' if v == 0 else '/')
        ans.append(row)
    return ans


if __name__ == "__main__":
    print(solve(OBSERVATION))

