from collections import deque

# Efficient generalized Futoshiki solver (Latin square + inequalities)
# Human-like deductions implemented:
# - Candidate elimination by row/col (hidden singles, naked singles)
# - Inequality arc-consistency propagation (AC-style)
# - Strong bound tightening from inequality chains (min/max pruning)
# - Early contradiction checks
# - Backtracking with MRV + degree heuristic + forward checking


def solve(observation):
    grid = observation["data"]
    N = len(grid)
    if N == 0 or any(len(r) != N for r in grid):
        return "No Solution"

    # Parse inequalities into directed edges: A < B
    # Horizontal keys: (r, c+0.5) with '<' or '>' comparing (r,c) and (r,c+1)
    # Vertical keys: (r+0.5, c) with '^' or 'v' comparing (r,c) and (r+1,c)
    lt_edges = [[] for _ in range(N * N)]  # u -> v means u < v
    gt_edges = [[] for _ in range(N * N)]  # u -> v means u > v (reverse adjacency)

    def vid(r, c):
        return r * N + c

    def add_lt(u, v):
        lt_edges[u].append(v)
        gt_edges[v].append(u)

    # Horizontal
    for k, sym in observation.get("horizontal", {}).items():
        # k like "(0,0.5)"
        t = k.strip()[1:-1].split(",")
        r = int(float(t[0]))
        cf = float(t[1])
        c = int(cf - 0.5)
        if not (0 <= r < N and 0 <= c < N - 1):
            continue
        left = vid(r, c)
        right = vid(r, c + 1)
        if sym == "<":
            add_lt(left, right)
        elif sym == ">":
            add_lt(right, left)

    # Vertical
    for k, sym in observation.get("vertical", {}).items():
        t = k.strip()[1:-1].split(",")
        rf = float(t[0])
        c = int(float(t[1]))
        r = int(rf - 0.5)
        if not (0 <= r < N - 1 and 0 <= c < N):
            continue
        top = vid(r, c)
        bot = vid(r + 1, c)
        # In many futoshiki conventions:
        # '^' means top > bottom (arrow points up), 'v' means top < bottom.
        if sym == "v":
            add_lt(top, bot)
        elif sym == "^":
            add_lt(bot, top)

    # Domains: bitmask 1..N
    ALL = (1 << N) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def lowest_bit(x):
        return (x & -x)

    def bit_to_val(b):
        return (b.bit_length())

    # Precompute row/col peers
    row_cells = [[vid(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[vid(r, c) for r in range(N)] for c in range(N)]
    peers = [[] for _ in range(N * N)]
    for r in range(N):
        for c in range(N):
            u = vid(r, c)
            ps = set(row_cells[r] + col_cells[c])
            ps.discard(u)
            peers[u] = list(ps)

    # Initialize domains from givens
    dom = [ALL] * (N * N)
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                dom[vid(r, c)] = bit(v)

    # Helper: get min/max possible value from domain
    def dmin(mask):
        # smallest value present
        return (mask & -mask).bit_length()

    def dmax(mask):
        return mask.bit_length()

    # Propagation queue mechanisms
    inq = [False] * (N * N)
    q = deque()

    def enqueue(u):
        if not inq[u]:
            inq[u] = True
            q.append(u)

    # Enqueue all variables initially
    for u in range(N * N):
        enqueue(u)

    # Constraint propagation:
    # 1) Latin constraint (row/col): remove assigned values from peers; hidden singles
    # 2) Inequality constraint: enforce arc consistency on pairs u < v
    # 3) Bound tightening along inequalities: min(u) <= max(v)-1 and max(u) <= max(v)-1 etc.
    #    Implemented through repeated arc pruning (works as human reasoning).
    def remove_value(mask, valbit):
        nm = mask & ~valbit
        return nm

    # Track row/col used bits for faster elimination
    def compute_used():
        row_used = [0] * N
        col_used = [0] * N
        for r in range(N):
            for c in range(N):
                u = vid(r, c)
                if popcount(dom[u]) == 1:
                    row_used[r] |= dom[u]
                    col_used[c] |= dom[u]
        return row_used, col_used

    def apply_latin_basic():
        changed = False
        row_used, col_used = compute_used()
        for r in range(N):
            for c in range(N):
                u = vid(r, c)
                if popcount(dom[u]) == 1:
                    continue
                used = row_used[r] | col_used[c]
                nm = dom[u] & ~used
                if nm != dom[u]:
                    dom[u] = nm
                    changed = True
                    enqueue(u)
                    if nm == 0:
                        return False, True
        return True, changed

    def hidden_singles_unit(unit):
        # unit is list of variable ids
        # For each value, if only one place can take it -> assign
        changed = False
        # Build occurrence counts with bitwise accumulation
        # For each value i, track last position and count
        last_pos = [None] * (N + 1)
        cnt = [0] * (N + 1)
        for u in unit:
            m = dom[u]
            x = m
            while x:
                b = x & -x
                v = b.bit_length()
                cnt[v] += 1
                last_pos[v] = u
                x -= b
        for v in range(1, N + 1):
            if cnt[v] == 1:
                u = last_pos[v]
                if popcount(dom[u]) != 1:
                    dom[u] = bit(v)
                    changed = True
                    enqueue(u)
        return changed

    def apply_hidden_singles():
        changed = False
        for r in range(N):
            if hidden_singles_unit(row_cells[r]):
                changed = True
        for c in range(N):
            if hidden_singles_unit(col_cells[c]):
                changed = True
        return changed

    def prune_lt(u, v):
        # Enforce u < v by pruning domains:
        # u cannot take values >= max(v)
        # v cannot take values <= min(u)
        mu = dom[u]
        mv = dom[v]
        if mu == 0 or mv == 0:
            return False, False
        min_u = dmin(mu)
        max_u = dmax(mu)
        min_v = dmin(mv)
        max_v = dmax(mv)

        # u must be <= max_v-1
        if max_v <= 1:
            return False, True  # v can't be 1 or less to allow u < v
        allowed_u_max = max_v - 1
        # v must be >= min_u+1
        if min_u >= N:
            return False, True
        allowed_v_min = min_u + 1

        # Build masks quickly by trimming ranges using precomputed prefix masks
        # prefix_mask[k] = bits 1..k
        # We'll compute once outside
        return True, False

    # Precompute prefix masks
    prefix = [0] * (N + 1)
    for k in range(1, N + 1):
        prefix[k] = prefix[k - 1] | bit(k)

    def mask_le(k):
        if k <= 0:
            return 0
        if k >= N:
            return ALL
        return prefix[k]

    def mask_ge(k):
        if k <= 1:
            return ALL
        if k > N:
            return 0
        return ALL & ~prefix[k - 1]

    def enforce_lt(u, v):
        changed = False
        mu = dom[u]
        mv = dom[v]
        if mu == 0 or mv == 0:
            return False, False
        min_u = dmin(mu)
        max_u = dmax(mu)
        min_v = dmin(mv)
        max_v = dmax(mv)

        # quick infeasibility check
        if min_u >= max_v:
            return False, True

        # prune u: must be <= max_v-1
        nu = mu & mask_le(max_v - 1)
        if nu != mu:
            dom[u] = nu
            changed = True
            enqueue(u)
            if nu == 0:
                return False, True

        # prune v: must be >= min_u+1
        nv = mv & mask_ge(min_u + 1)
        if nv != mv:
            dom[v] = nv
            changed = True
            enqueue(v)
            if nv == 0:
                return False, True

        # Additional arc-consistency style pruning:
        # remove any value a in u that has no supporting b in v with b > a
        # and similarly for v.
        mu = dom[u]
        mv = dom[v]
        # Support check using cumulative masks:
        # For u value a: need v in {a+1..N} => mv & ge(a+1) nonzero
        x = mu
        bad = 0
        while x:
            b = x & -x
            a = b.bit_length()
            if (mv & mask_ge(a + 1)) == 0:
                bad |= b
            x -= b
        if bad:
            nu = mu & ~bad
            if nu != mu:
                dom[u] = nu
                changed = True
                enqueue(u)
                if nu == 0:
                    return False, True

        mu = dom[u]
        mv = dom[v]
        # For v value b: need u in {1..b-1} => mu & le(b-1) nonzero
        x = mv
        bad = 0
        while x:
            bb = x & -x
            bval = bb.bit_length()
            if (mu & mask_le(bval - 1)) == 0:
                bad |= bb
            x -= bb
        if bad:
            nv = mv & ~bad
            if nv != mv:
                dom[v] = nv
                changed = True
                enqueue(v)
                if nv == 0:
                    return False, True

        return True, changed

    def propagate():
        # Multi-pass until fixpoint:
        # - process queue variables: apply local row/col elimination from assignments, inequality propagation
        # - then run hidden singles occasionally
        # This simulates human iterative deductions and keeps it fast.
        # Start with basic latin elimination
        ok, _ = apply_latin_basic()
        if not ok:
            return False
        progress = True
        hs_counter = 0
        while q:
            u = q.popleft()
            inq[u] = False
            if dom[u] == 0:
                return False

            # If assigned, eliminate from peers quickly
            if popcount(dom[u]) == 1:
                valbit = dom[u]
                for p in peers[u]:
                    if dom[p] & valbit:
                        dom[p] &= ~valbit
                        enqueue(p)
                        if dom[p] == 0:
                            return False

            # Inequality propagation for all incident edges
            for v in lt_edges[u]:
                ok, _ = enforce_lt(u, v)
                if not ok:
                    return False
            for v in gt_edges[u]:
                ok, _ = enforce_lt(v, u)
                if not ok:
                    return False

            hs_counter += 1
            if hs_counter % (N * N // 2 + 1) == 0:
                if apply_hidden_singles():
                    # after hidden singles, basic elimination helps
                    ok, _ = apply_latin_basic()
                    if not ok:
                        return False

        # Final hidden singles sweep and latin pruning to closure
        changed = True
        while changed:
            changed = False
            ok, ch = apply_latin_basic()
            if not ok:
                return False
            changed |= ch
            if apply_hidden_singles():
                changed = True
        return True

    def is_solved():
        return all(popcount(dom[u]) == 1 for u in range(N * N))

    def pick_var():
        # MRV with degree tie-breaker (more constraints)
        best = -1
        best_sz = 10**9
        best_deg = -1
        for u in range(N * N):
            sz = popcount(dom[u])
            if sz > 1 and sz < best_sz:
                best_sz = sz
                best = u
                # degree: number of unassigned peers + inequality neighbors
                deg = sum(1 for p in peers[u] if popcount(dom[p]) > 1)
                deg += sum(1 for v in lt_edges[u] if popcount(dom[v]) > 1)
                deg += sum(1 for v in gt_edges[u] if popcount(dom[v]) > 1)
                best_deg = deg
            elif sz > 1 and sz == best_sz:
                deg = sum(1 for p in peers[u] if popcount(dom[p]) > 1)
                deg += sum(1 for v in lt_edges[u] if popcount(dom[v]) > 1)
                deg += sum(1 for v in gt_edges[u] if popcount(dom[v]) > 1)
                if deg > best_deg:
                    best = u
                    best_deg = deg
        return best

    def order_values(u):
        # Least-constraining value: try values that eliminate fewer options in peers/ineq
        m = dom[u]
        vals = []
        x = m
        while x:
            b = x & -x
            v = b.bit_length()
            x -= b
            cost = 0
            # peers
            for p in peers[u]:
                if dom[p] & b:
                    cost += 1
            # inequalities: rough cost by feasibility
            for w in lt_edges[u]:  # u < w; choosing v forces w >= v+1
                cost += popcount(dom[w] & ~mask_ge(v + 1))
            for w in gt_edges[u]:  # w < u; choosing v forces w <= v-1
                cost += popcount(dom[w] & ~mask_le(v - 1))
            vals.append((cost, v))
        vals.sort()
        return [v for _, v in vals]

    def snapshot():
        return dom[:], list(inq), deque(q)

    def restore(snap):
        nonlocal dom, inq, q
        dom, inq, q = snap

    def dfs():
        if not propagate():
            return False
        if is_solved():
            return True
        u = pick_var()
        if u == -1:
            return False
        for v in order_values(u):
            snap = snapshot()
            dom[u] = bit(v)
            enqueue(u)
            if dfs():
                return True
            restore(snap)
        return False

    if not dfs():
        return "No Solution"

    sol = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            sol[r][c] = bit_to_val(dom[vid(r, c)])
    return str(sol)


if __name__ == "__main__":
    print(solve(OBSERVATION))

