from collections import defaultdict, deque

# --------- Core solver (Jigsaw Sudoku / Irregular regions) ----------
# Human-like logic emphasis:
# 1) Candidate elimination by row/col/region constraints
# 2) Naked singles + Hidden singles (row/col/region)
# 3) Locked candidates (pointing) between region <-> row/col
# 4) Naked pairs/triples (row/col/region)
# 5) X-Wing (rows/cols) for stronger pruning
# 6) Only then: MRV + forward checking + propagation (limited guessing)

def solve(observation):
    region = observation["region"]
    givens = observation["data"]
    N = len(region)
    if N == 0 or any(len(r) != N for r in region) or any(len(r) != N for r in givens):
        return "No Solution"
    # Validate region ids
    rids = set()
    for r in range(N):
        for c in range(N):
            rids.add(region[r][c])
    # Regions should each have size N in valid puzzles; still solve if not, but enforce "each number once" within region size N
    # If region sizes differ, it's not a standard Latin constraint; treat as standard jigsaw: each region must contain 1..N exactly once
    # Hence require each region has exactly N cells; else unsat.
    cells_by_region = defaultdict(list)
    for r in range(N):
        for c in range(N):
            cells_by_region[region[r][c]].append((r, c))
    if any(len(cells) != N for cells in cells_by_region.values()):
        return "No Solution"

    ALL = (1 << N) - 1
    def bit(v): return 1 << (v - 1)

    # Precompute row/col/unit cell lists
    rows = [[(r, c) for c in range(N)] for r in range(N)]
    cols = [[(r, c) for r in range(N)] for c in range(N)]
    regs = [cells_by_region[rid] for rid in sorted(cells_by_region.keys())]
    # Map region id to index in regs list
    rid_to_idx = {rid: i for i, rid in enumerate(sorted(cells_by_region.keys()))}
    reg_index = [[rid_to_idx[region[r][c]] for c in range(N)] for r in range(N)]

    units = []
    units.extend(rows)
    units.extend(cols)
    units.extend(regs)

    # Peers for each cell
    peers = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            # Row + Col + Region
            pr = set(rows[r]) | set(cols[c]) | set(regs[reg_index[r][c]])
            pr.discard((r, c))
            peers[r][c] = pr

    # State: grid values and candidate masks
    grid = [[0]*N for _ in range(N)]
    cand = [[ALL]*N for _ in range(N)]

    row_used = [0]*N
    col_used = [0]*N
    reg_used = [0]*N

    def popcount(x):
        return x.bit_count()

    def lowbit_index(x):
        # x has exactly one bit set; return index 0..N-1
        return (x & -x).bit_length() - 1

    def mask_to_values(m):
        while m:
            lb = m & -m
            yield lb.bit_length()
            m ^= lb

    def assign(r, c, v, trail):
        """Assign value v to cell (r,c), update constraints; return False if contradiction."""
        if grid[r][c] == v:
            return True
        if grid[r][c] != 0 and grid[r][c] != v:
            return False
        m = bit(v)
        if not (cand[r][c] & m):
            return False

        # Record changes for backtracking
        trail.append(("cell", r, c, grid[r][c], cand[r][c]))
        grid[r][c] = v
        cand[r][c] = m

        # Update used masks
        ri = reg_index[r][c]
        # If already marked used by someone else -> contradiction
        if (row_used[r] & m) or (col_used[c] & m) or (reg_used[ri] & m):
            return False
        trail.append(("used", r, c, row_used[r], col_used[c], reg_used[ri]))
        row_used[r] |= m
        col_used[c] |= m
        reg_used[ri] |= m

        # Eliminate v from peers
        for (rr, cc) in peers[r][c]:
            if grid[rr][cc] == 0 and (cand[rr][cc] & m):
                trail.append(("cand", rr, cc, cand[rr][cc]))
                cand[rr][cc] &= ~m
                if cand[rr][cc] == 0:
                    return False
        return True

    def untrail(trail):
        while trail:
            t = trail.pop()
            if t[0] == "cand":
                _, r, c, old = t
                cand[r][c] = old
            elif t[0] == "used":
                _, r, c, oldr, oldc, oldg = t
                ri = reg_index[r][c]
                row_used[r] = oldr
                col_used[c] = oldc
                reg_used[ri] = oldg
            elif t[0] == "cell":
                _, r, c, oldv, oldm = t
                grid[r][c] = oldv
                cand[r][c] = oldm

    # Initialize candidates based on givens
    # First, set all to ALL, then remove used in row/col/reg incrementally via assign to maintain consistency.
    for r in range(N):
        for c in range(N):
            v = givens[r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"

    trail0 = []
    for r in range(N):
        for c in range(N):
            v = givens[r][c]
            if v is not None:
                if not assign(r, c, v, trail0):
                    return "No Solution"

    # ---------- Deduction techniques ----------

    def naked_singles(trail):
        progress = False
        q = deque()
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0 and popcount(cand[r][c]) == 1:
                    q.append((r, c))
        while q:
            r, c = q.popleft()
            if grid[r][c] != 0:
                continue
            m = cand[r][c]
            if popcount(m) != 1:
                continue
            v = lowbit_index(m) + 1
            if not assign(r, c, v, trail):
                return False, progress
            progress = True
            # new singles might appear among peers
            for (rr, cc) in peers[r][c]:
                if grid[rr][cc] == 0 and popcount(cand[rr][cc]) == 1:
                    q.append((rr, cc))
        return True, progress

    def hidden_singles_in_unit(unit, trail):
        # For each digit, see if it appears in exactly one cell in unit
        loc = [None]*N
        count = [0]*N
        for (r, c) in unit:
            if grid[r][c] != 0:
                continue
            m = cand[r][c]
            mm = m
            while mm:
                lb = mm & -mm
                d = lb.bit_length() - 1
                count[d] += 1
                loc[d] = (r, c) if count[d] == 1 else loc[d]
                mm ^= lb
        for d in range(N):
            if count[d] == 1:
                r, c = loc[d]
                if grid[r][c] == 0:
                    if not assign(r, c, d+1, trail):
                        return False, True
                    return True, True
        return True, False

    def hidden_singles(trail):
        progress = False
        # iterate until no unit creates a single in one pass
        any_change = True
        while any_change:
            any_change = False
            for unit in units:
                ok, ch = hidden_singles_in_unit(unit, trail)
                if not ok:
                    return False, progress
                if ch:
                    progress = True
                    any_change = True
        return True, progress

    def locked_candidates(trail):
        # Pointing: within a region, if candidate digit confined to one row/col, eliminate from that row/col outside region
        progress = False
        for ridx, reg in enumerate(regs):
            # For each digit, collect rows and cols where it appears in region
            rows_set = [set() for _ in range(N)]
            cols_set = [set() for _ in range(N)]
            positions = [[] for _ in range(N)]
            for (r, c) in reg:
                if grid[r][c] != 0:
                    continue
                m = cand[r][c]
                mm = m
                while mm:
                    lb = mm & -mm
                    d = lb.bit_length() - 1
                    rows_set[d].add(r)
                    cols_set[d].add(c)
                    positions[d].append((r, c))
                    mm ^= lb
            for d in range(N):
                if not positions[d]:
                    continue
                mbit = 1 << d
                if len(rows_set[d]) == 1:
                    row = next(iter(rows_set[d]))
                    for (rr, cc) in rows[row]:
                        if reg_index[rr][cc] != ridx and grid[rr][cc] == 0 and (cand[rr][cc] & mbit):
                            trail.append(("cand", rr, cc, cand[rr][cc]))
                            cand[rr][cc] &= ~mbit
                            if cand[rr][cc] == 0:
                                return False, progress
                            progress = True
                if len(cols_set[d]) == 1:
                    col = next(iter(cols_set[d]))
                    for (rr, cc) in cols[col]:
                        if reg_index[rr][cc] != ridx and grid[rr][cc] == 0 and (cand[rr][cc] & mbit):
                            trail.append(("cand", rr, cc, cand[rr][cc]))
                            cand[rr][cc] &= ~mbit
                            if cand[rr][cc] == 0:
                                return False, progress
                            progress = True
        return True, progress

    def naked_subsets_in_unit(unit, k, trail):
        # Naked pairs/triples/quads via mask frequency
        progress = False
        masks = {}
        cells = []
        for (r, c) in unit:
            if grid[r][c] == 0:
                m = cand[r][c]
                pc = popcount(m)
                if 2 <= pc <= k:
                    masks.setdefault(m, []).append((r, c))
                    cells.append((r, c, m))
        # Direct identical masks of size k
        for m, lst in masks.items():
            if popcount(m) == k and len(lst) == k:
                # remove these digits from other cells in unit
                for (r, c) in unit:
                    if grid[r][c] == 0 and (r, c) not in lst:
                        if cand[r][c] & m:
                            trail.append(("cand", r, c, cand[r][c]))
                            cand[r][c] &= ~m
                            if cand[r][c] == 0:
                                return False, progress
                            progress = True
        return True, progress

    def naked_pairs_triples(trail):
        progress = False
        for unit in units:
            for k in (2, 3, 4):
                ok, ch = naked_subsets_in_unit(unit, k, trail)
                if not ok:
                    return False, progress
                if ch:
                    progress = True
        return True, progress

    def x_wing(trail):
        # For each digit, check rows: two rows with same two columns positions -> eliminate from those columns in other rows
        progress = False
        for d in range(N):
            mbit = 1 << d
            row_pos = []
            for r in range(N):
                cols_list = []
                for c in range(N):
                    if grid[r][c] == 0 and (cand[r][c] & mbit):
                        cols_list.append(c)
                if len(cols_list) == 2:
                    row_pos.append((r, tuple(cols_list)))
            # find pairs with same columns
            by_cols = defaultdict(list)
            for r, cc in row_pos:
                by_cols[cc].append(r)
            for cc, rs in by_cols.items():
                if len(rs) >= 2:
                    # choose all pairs; elimination works for any two, but applying once for all involved rows is safe
                    c1, c2 = cc
                    rows_in = set(rs)
                    for rr in range(N):
                        if rr in rows_in:
                            continue
                        for c in (c1, c2):
                            if grid[rr][c] == 0 and (cand[rr][c] & mbit):
                                trail.append(("cand", rr, c, cand[rr][c]))
                                cand[rr][c] &= ~mbit
                                if cand[rr][c] == 0:
                                    return False, progress
                                progress = True
        # Column-based
        for d in range(N):
            mbit = 1 << d
            col_pos = []
            for c in range(N):
                rows_list = []
                for r in range(N):
                    if grid[r][c] == 0 and (cand[r][c] & mbit):
                        rows_list.append(r)
                if len(rows_list) == 2:
                    col_pos.append((c, tuple(rows_list)))
            by_rows = defaultdict(list)
            for c, rr in col_pos:
                by_rows[rr].append(c)
            for rr, cs in by_rows.items():
                if len(cs) >= 2:
                    r1, r2 = rr
                    cols_in = set(cs)
                    for cc in range(N):
                        if cc in cols_in:
                            continue
                        for r in (r1, r2):
                            if grid[r][cc] == 0 and (cand[r][cc] & mbit):
                                trail.append(("cand", r, cc, cand[r][cc]))
                                cand[r][cc] &= ~mbit
                                if cand[r][cc] == 0:
                                    return False, progress
                                progress = True
        return True, progress

    def propagate(trail):
        # Loop applying techniques until fixed point
        while True:
            any_prog = False
            for fn in (naked_singles, hidden_singles, locked_candidates, naked_pairs_triples, x_wing, naked_singles, hidden_singles):
                ok, prog = fn(trail)
                if not ok:
                    return False
                if prog:
                    any_prog = True
            if not any_prog:
                return True

    def is_solved():
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    return False
        return True

    def select_mrv_cell():
        best = None
        bestc = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    pc = popcount(cand[r][c])
                    if pc == 0:
                        return None
                    if best is None or pc < best:
                        best = pc
                        bestc = (r, c)
                        if pc == 2:
                            # can't be 1 here if propagate done; 2 is strong enough early break
                            pass
        return bestc

    def order_values_lcv(r, c):
        # Least-constraining value: count eliminations in peers
        m = cand[r][c]
        vals = list(mask_to_values(m))
        if len(vals) <= 1:
            return vals
        scores = []
        for v in vals:
            vb = bit(v)
            score = 0
            for (rr, cc) in peers[r][c]:
                if grid[rr][cc] == 0 and (cand[rr][cc] & vb):
                    score += 1
            scores.append((score, v))
        scores.sort()
        return [v for _, v in scores]

    def dfs():
        trail = []
        if not propagate(trail):
            untrail(trail)
            return False
        if is_solved():
            untrail(trail)
            return True

        cell = select_mrv_cell()
        if cell is None:
            untrail(trail)
            return False
        r, c = cell
        snapshot = len(trail)

        for v in order_values_lcv(r, c):
            trail2 = []
            if assign(r, c, v, trail2):
                if dfs():
                    # keep solution in current global grid by redoing moves? easier: don't untrail successful path.
                    # Since we untrail(trail2) below, we must not on success. We'll return with grid holding solution.
                    return True
            untrail(trail2)
            # restore to snapshot (though trail2 already reverted, nothing else changed)
        # revert deductions at this level
        untrail(trail)
        return False

    # Run search with strong propagation
    if not dfs():
        return "No Solution"
    # If dfs returned True, grid contains solution
    return str([[grid[r][c] for c in range(N)] for r in range(N)])

