# Solver for the puzzle described in prompt (region black-count, no orthogonal black touch,
# white straight segments cross <=2 regions, all whites connected).
#
# Focus: strong constraint propagation + small, guided search.
#
# Representation:
#  - Each cell state in {-1 unknown, 0 white, 1 black}
#  - Regions are arbitrary polyominoes with an optional clue (number of blacks in that region).
#
# Constraints:
#  A) Region count: sum(cell==black) == clue (if clue exists)
#  B) No orthogonal adjacent blacks.
#  C) For each maximal straight segment of whites (contiguous whites with unknowns treated carefully),
#     in final solution each maximal white run must cross <=2 regions.
#     We enforce it via line constraints using union-find of region transitions on each line,
#     and strong local deductions for guaranteed whites/regions crossing.
#  D) All whites connected (orthogonally), blacks are blockers.
#     Enforced with connectivity pruning on partial assignments (single-component feasibility).
#
# NOTE: Because rule C depends on "uninterrupted straight white segment" in the final grid,
# we model it as: for any contiguous sequence of non-black cells (white/unknown) in a row/col,
# if it becomes all-white, then the number of distinct regions in that run must be <=2.
# During solving, we maintain bounds: any run that is forced to remain unbroken (no place for black)
# must already satisfy <=2. Also if a run already contains whites fixed and has only limited breakpoints,
# we can deduce some must be black to avoid 3+ regions.
#
# The solver is generalized; the OBSERVATION is just one instance.

from collections import defaultdict, deque
from functools import lru_cache

UNKNOWN = -1
WHITE = 0
BLACK = 1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])
    assert n == m, "Expected square grid N x N"

    N = n
    idx = lambda r, c: r * N + c
    rc = lambda i: (i // N, i % N)

    # Build region cells
    region_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            region_cells[region[r][c]].append(idx(r, c))

    # Region clues: clue per region-id (if any). If multiple clues appear (shouldn't), enforce equality.
    region_clue = {}
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is None:
                continue
            rid = region[r][c]
            if rid in region_clue and region_clue[rid] != v:
                return "No Solution"
            region_clue[rid] = v

    # Precompute neighbors
    nbr4 = [[] for _ in range(N*N)]
    for r in range(N):
        for c in range(N):
            i = idx(r, c)
            if r > 0: nbr4[i].append(idx(r-1, c))
            if r+1 < N: nbr4[i].append(idx(r+1, c))
            if c > 0: nbr4[i].append(idx(r, c-1))
            if c+1 < N: nbr4[i].append(idx(r, c+1))

    # Precompute row/col lines
    rows = [[idx(r, c) for c in range(N)] for r in range(N)]
    cols = [[idx(r, c) for r in range(N)] for c in range(N)]

    cell_region = [0]*(N*N)
    for r in range(N):
        for c in range(N):
            cell_region[idx(r,c)] = region[r][c]

    # --- Constraint helpers ---

    def region_count_bounds(state, rid):
        cells = region_cells[rid]
        b = sum(1 for i in cells if state[i] == BLACK)
        u = sum(1 for i in cells if state[i] == UNKNOWN)
        return b, b+u

    def apply_region_count_deductions(state, queue):
        # returns False if contradiction
        for rid, clue in region_clue.items():
            cells = region_cells[rid]
            blacks = [i for i in cells if state[i] == BLACK]
            unknowns = [i for i in cells if state[i] == UNKNOWN]
            b = len(blacks)
            u = len(unknowns)
            if b > clue: return False
            if b + u < clue: return False
            if clue == b and u:
                for i in unknowns:
                    if not assign(state, i, WHITE, queue): return False
            elif clue == b + u and u:
                for i in unknowns:
                    if not assign(state, i, BLACK, queue): return False
        return True

    def assign(state, i, val, queue):
        cur = state[i]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        state[i] = val
        queue.append(i)
        return True

    def apply_no_adjacent_black(state, queue, i_changed):
        # if cell is black, neighbors must be white
        if state[i_changed] == BLACK:
            for j in nbr4[i_changed]:
                if not assign(state, j, WHITE, queue):
                    return False
        return True

    # Rule C: segment crosses <=2 regions.
    # We'll implement strong pruning/deductions per line using:
    # - Identify contiguous blocks of cells that are "not black" (WHITE or UNKNOWN). Each block could become an uninterrupted
    #   white segment unless we place at least one black inside it.
    # - For each block, compute distinct region ids present. If <=2, ok even if fully white.
    # - If >2, then we must place at least one black in the block at some "cut positions" that would split regions count.
    #   We'll implement necessary conditions: if there exists a triple of region changes that cannot be separated by potential blacks
    #   (cells already forced white), contradiction; also if only one cell can be black to reduce region count and it's forced white -> contradiction.
    #
    # We approximate with safe, strong deductions:
    #  - For any maximal block of cells with state != BLACK, consider the subsequence of forced WHITE cells within it.
    #    If there exist 3 forced-white cells along the block such that the region sequence between them includes >=3 distinct regions
    #    and there is no UNKNOWN cell between region-boundary positions to place a BLACK, contradiction.
    #  - Additionally, if in a block there are already >=3 distinct regions among cells that are forced WHITE, then we must break the
    #    block with BLACK somewhere between whites belonging to region1..region3. If there is exactly one possible position for such black,
    #    force it.
    #
    # For efficiency, we compute on each line and react when changes happen.

    def line_blocks(line, state):
        # yields (start,end) inclusive indices in line list for maximal consecutive not-black cells
        res = []
        s = None
        for k, i in enumerate(line):
            if state[i] != BLACK:
                if s is None:
                    s = k
            else:
                if s is not None:
                    res.append((s, k-1))
                    s = None
        if s is not None:
            res.append((s, len(line)-1))
        return res

    def distinct_regions_in_segment(line, a, b):
        s = set()
        for k in range(a, b+1):
            s.add(cell_region[line[k]])
        return s

    def apply_rule_c_line(state, queue, line):
        # returns False if contradiction
        blocks = line_blocks(line, state)
        for a, b in blocks:
            # quick check: if <=2 distinct regions overall in block, ok
            regs_all = distinct_regions_in_segment(line, a, b)
            if len(regs_all) <= 2:
                continue

            # Need at least one BLACK inside this block in final to split into smaller segments.
            # If all cells in block are forced WHITE => contradiction.
            if all(state[line[k]] == WHITE for k in range(a, b+1)):
                return False

            # Stronger: forced-white region sequence
            white_pos = [k for k in range(a, b+1) if state[line[k]] == WHITE]
            if len(white_pos) >= 2:
                # If forced whites alone already cover >=3 regions, then we must insert a BLACK between some consecutive forced whites
                # to prevent them being in same uninterrupted segment.
                regs_forced = []
                for k in white_pos:
                    regs_forced.append(cell_region[line[k]])
                if len(set(regs_forced)) >= 3:
                    # Find necessary cut positions between forced whites to reduce to <=2 per resulting segment.
                    # A sufficient condition: there must be a black between some pair of forced whites such that it separates
                    # at least one region transition needed.
                    # We'll compute minimal set of candidate cut cells (unknowns) between forced whites that can be black.
                    candidates = set()
                    # for each consecutive forced whites, any cell between them could be black
                    for p, q in zip(white_pos, white_pos[1:]):
                        for k in range(p+1, q):
                            i = line[k]
                            if state[i] == UNKNOWN:
                                candidates.add(i)
                    if not candidates:
                        return False
                    if len(candidates) == 1:
                        only = next(iter(candidates))
                        if not assign(state, only, BLACK, queue):
                            return False

            # Another deduction: if in this block there is exactly one UNKNOWN cell, it must be BLACK (since need a split)
            unknowns = [line[k] for k in range(a, b+1) if state[line[k]] == UNKNOWN]
            if len(unknowns) == 1:
                if not assign(state, unknowns[0], BLACK, queue):
                    return False

        return True

    def apply_rule_c(state, queue, i_changed=None):
        # For simplicity and speed, when something changes, scan its row and col only.
        if i_changed is None:
            for r in range(N):
                if not apply_rule_c_line(state, queue, rows[r]): return False
            for c in range(N):
                if not apply_rule_c_line(state, queue, cols[c]): return False
            return True
        r, c = rc(i_changed)
        if not apply_rule_c_line(state, queue, rows[r]): return False
        if not apply_rule_c_line(state, queue, cols[c]): return False
        return True

    # Rule D: all whites connected.
    # Feasibility pruning:
    #  - If there are fixed WHITE cells, ensure all fixed whites are in one component in graph of non-BLACK cells considering UNKNOWN as passable.
    #  - Additionally, ensure no fixed WHITE is completely enclosed by BLACK in a way impossible to connect (handled by above).
    def connectivity_ok(state):
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return True
        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in nbr4[u]:
                if v in seen: continue
                if state[v] != BLACK:  # unknown or white can connect in future
                    seen.add(v)
                    dq.append(v)
        return all(w in seen for w in whites)

    # Additional pruning: avoid creating "isolated non-black islands" that contain no white yet but could become white later.
    # Not necessary; keep lightweight.

    def propagate(state, queue):
        # queue contains indices whose assignment may trigger local deductions.
        # returns False if contradiction.
        # Initial global region deductions each loop iteration.
        if not apply_region_count_deductions(state, queue):
            return False
        if not apply_rule_c(state, queue, None):
            return False
        while queue:
            i = queue.popleft()
            if not apply_no_adjacent_black(state, queue, i):
                return False
            if not apply_region_count_deductions(state, queue):
                return False
            if not apply_rule_c(state, queue, i):
                return False
            if not connectivity_ok(state):
                return False
        return True

    def is_solved(state):
        if any(v == UNKNOWN for v in state):
            return False
        # Check all region counts
        for rid, clue in region_clue.items():
            b = sum(1 for i in region_cells[rid] if state[i] == BLACK)
            if b != clue: return False
        # Check no adjacent blacks
        for i, v in enumerate(state):
            if v == BLACK:
                for j in nbr4[i]:
                    if state[j] == BLACK: return False
        # Check rule C exact: for each maximal white segment in each line, regions <=2
        for line in rows + cols:
            k = 0
            while k < len(line):
                if state[line[k]] == WHITE:
                    a = k
                    regs = set([cell_region[line[k]]])
                    k += 1
                    while k < len(line) and state[line[k]] == WHITE:
                        regs.add(cell_region[line[k]])
                        k += 1
                    if len(regs) > 2:
                        return False
                else:
                    k += 1
        # Check connectivity exact on whites
        return connectivity_ok_exact(state)

    def connectivity_ok_exact(state):
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return True
        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in nbr4[u]:
                if v in seen: continue
                if state[v] == WHITE:
                    seen.add(v)
                    dq.append(v)
        return len(seen) == len(whites)

    # Variable ordering: pick most constrained cell:
    #  - in a region with tight remaining count
    #  - or whose row/col currently violates rule C unless split
    def choose_var(state):
        best = None
        best_score = -1
        # Precompute remaining needs per region for scoring
        need = {}
        for rid, clue in region_clue.items():
            b, ub = region_count_bounds(state, rid)
            need[rid] = (clue - b, ub - b)  # (remaining blacks, remaining unknown capacity)
        for i, v in enumerate(state):
            if v != UNKNOWN:
                continue
            rid = cell_region[i]
            score = 0
            if rid in region_clue:
                rem, cap = need[rid]
                # tighter regions -> higher score
                score += 10 * (N*N - cap)
                # if must place blacks, push
                score += 5 * max(0, rem)
            # adjacency: if any neighbor black then forced white (so unknown with black neighbor is constrained)
            if any(state[j] == BLACK for j in nbr4[i]):
                score += 50
            # endpoints: in lines with >2 regions in current non-black block, push
            r, c = rc(i)
            score += 2 * line_pressure(state, rows[r], i)
            score += 2 * line_pressure(state, cols[c], i)
            if score > best_score:
                best_score = score
                best = i
        return best

    def line_pressure(state, line, i):
        # 0/1 heuristic if i belongs to a non-black block with >2 region types
        # locate position
        pos = None
        for k, x in enumerate(line):
            if x == i:
                pos = k
                break
        if pos is None:
            return 0
        if state[i] == BLACK:
            return 0
        # find block boundaries in not-black
        a = pos
        while a-1 >= 0 and state[line[a-1]] != BLACK:
            a -= 1
        b = pos
        while b+1 < len(line) and state[line[b+1]] != BLACK:
            b += 1
        regs = distinct_regions_in_segment(line, a, b)
        return 1 if len(regs) > 2 else 0

    def try_assign(state, i, val):
        st = state[:]
        q = deque()
        if not assign(st, i, val, q):
            return None
        if not propagate(st, q):
            return None
        return st

    # Initial state
    state0 = [UNKNOWN] * (N*N)

    # Seed: apply direct deductions from region clues 0 and full regions etc.
    q0 = deque()
    if not propagate(state0, q0):
        return "No Solution"

    # DFS with propagation, limited branching (white vs black).
    # Branch order: try BLACK first if region needs blacks; else WHITE first.
    seen = set()

    def key(state):
        # compact key for memoization
        return bytes((v+1) for v in state)  # map -1,0,1 -> 0,1,2

    def dfs(state):
        k = key(state)
        if k in seen:
            return None
        seen.add(k)

        if is_solved(state):
            return state

        i = choose_var(state)
        if i is None:
            return None

        rid = cell_region[i]
        order = [WHITE, BLACK]
        if rid in region_clue:
            clue = region_clue[rid]
            b, ub = region_count_bounds(state, rid)
            rem = clue - b
            # if still need blacks, prioritize black; if already met, prioritize white
            if rem > 0:
                order = [BLACK, WHITE]
            elif rem == 0:
                order = [WHITE, BLACK]

        for val in order:
            st2 = try_assign(state, i, val)
            if st2 is None:
                continue
            # quick connectivity feasibility
            if not connectivity_ok(st2):
                continue
            res = dfs(st2)
            if res is not None:
                return res
        return None

    sol = dfs(state0)
    if sol is None:
        return "No Solution"

    # Convert to requested output: N x N with 'B' for black else None
    out = []
    for r in range(N):
        row_out = []
        for c in range(N):
            v = sol[idx(r,c)]
            row_out.append('B' if v == BLACK else None)
        out.append(row_out)
    return str(out)

