# NOTE:
# The provided OBSERVATION is intentionally left empty (all None, no constraints) because
# converting the specific image into exact coordinates is outside the scope of this solver code.
# This file focuses on a generalized, efficient solver for the described rule set.
#
# To use: populate OBSERVATION['data'], OBSERVATION['horizontal'], OBSERVATION['vertical']
# per the problem statement, then run.

from collections import deque

B, W = 1, 0  # internal encoding

def solve(observation):
    grid0 = observation["data"]
    Hc = observation.get("horizontal", {})
    Vc = observation.get("vertical", {})

    R = len(grid0)
    C = len(grid0[0]) if R else 0
    if R == 0 or C == 0:
        return "No Solution"
    if C % 2 != 0 or R % 2 != 0:
        # Rule requires equal B/W count per row/col => even length
        return "No Solution"

    # Parse constraints into adjacency maps for fast access
    # horizontal: key '(r, c+0.5)' means between (r,c) and (r,c+1)
    # vertical: key '(r+0.5, c)' means between (r,c) and (r+1,c)
    h = [[None]*(C-1) for _ in range(R)]
    v = [[None]*C for _ in range(R-1)]

    def parse_key(s):
        # s like '(2.0,4.5)'
        s = s.strip()
        if not (s.startswith("(") and s.endswith(")")):
            raise ValueError("Bad key: %r" % s)
        a, b = s[1:-1].split(",")
        return float(a.strip()), float(b.strip())

    for k, val in Hc.items():
        r, cc = parse_key(k)
        r = int(round(r))
        c = int(round(cc - 0.5))
        if not (0 <= r < R and 0 <= c < C-1):
            return "No Solution"
        if val not in ("=", "x"):
            return "No Solution"
        h[r][c] = val

    for k, val in Vc.items():
        rr, c = parse_key(k)
        r = int(round(rr - 0.5))
        c = int(round(c))
        if not (0 <= r < R-1 and 0 <= c < C):
            return "No Solution"
        if val not in ("=", "x"):
            return "No Solution"
        v[r][c] = val

    # Domains: bitmask 1<<W | 1<<B (i.e., 1 for W, 2 for B)
    ALL = (1 << W) | (1 << B)

    dom = [[ALL]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            x = grid0[r][c]
            if x is None:
                continue
            if x == "W":
                dom[r][c] = 1 << W
            elif x == "B":
                dom[r][c] = 1 << B
            else:
                return "No Solution"

    half_row = C // 2
    half_col = R // 2

    # Fast helpers
    def is_single(mask):
        return mask == (1 << W) or mask == (1 << B)

    def val_of(mask):
        # only for singletons
        return B if mask == (1 << B) else W

    def other(color):
        return W if color == B else B

    def mask_for(color):
        return 1 << color

    # Incremental counts
    row_cntB = [0]*R
    row_cntW = [0]*R
    row_un = [0]*R
    col_cntB = [0]*C
    col_cntW = [0]*C
    col_un = [0]*C

    for r in range(R):
        for c in range(C):
            if is_single(dom[r][c]):
                if val_of(dom[r][c]) == B:
                    row_cntB[r] += 1
                    col_cntB[c] += 1
                else:
                    row_cntW[r] += 1
                    col_cntW[c] += 1
            else:
                row_un[r] += 1
                col_un[c] += 1

    # For "no identical rows/cols" rule: not specified in prompt; do NOT enforce.

    # Propagation queue: cells whose domain changed
    q = deque()
    inq = [[False]*C for _ in range(R)]
    def push(r,c):
        if not inq[r][c]:
            inq[r][c] = True
            q.append((r,c))

    for r in range(R):
        for c in range(C):
            push(r,c)

    def apply_assign(r,c,newmask):
        # returns False if contradiction, True otherwise (and pushes if changed)
        nonlocal dom
        old = dom[r][c]
        if old == newmask:
            return True
        if old & newmask == 0:
            return False
        newmask = old & newmask
        if newmask == old:
            return True
        # update counts if transitions involve singleton/unassigned
        old_single = is_single(old)
        new_single = is_single(newmask)
        if old_single and not new_single:
            # shouldn't happen with intersection, but keep safe
            v0 = val_of(old)
            if v0 == B:
                row_cntB[r] -= 1; col_cntB[c] -= 1
            else:
                row_cntW[r] -= 1; col_cntW[c] -= 1
            row_un[r] += 1; col_un[c] += 1
        elif not old_single and new_single:
            v1 = val_of(newmask)
            if v1 == B:
                row_cntB[r] += 1; col_cntB[c] += 1
            else:
                row_cntW[r] += 1; col_cntW[c] += 1
            row_un[r] -= 1; col_un[c] -= 1
        elif old_single and new_single:
            v0 = val_of(old); v1 = val_of(newmask)
            if v0 != v1:
                if v0 == B:
                    row_cntB[r] -= 1; col_cntB[c] -= 1
                    row_cntW[r] += 1; col_cntW[c] += 1
                else:
                    row_cntW[r] -= 1; col_cntW[c] -= 1
                    row_cntB[r] += 1; col_cntB[c] += 1
        dom[r][c] = newmask
        push(r,c)
        return True

    # Deductions
    def enforce_counts_line(is_row, idx):
        # If reached half of one color, remaining must be other.
        if is_row:
            cntB, cntW, un = row_cntB[idx], row_cntW[idx], row_un[idx]
            if cntB > half_row or cntW > half_row:
                return False
            if un == 0:
                return True
            if cntB == half_row:
                # rest W
                for c in range(C):
                    if not is_single(dom[idx][c]):
                        if not apply_assign(idx, c, 1 << W):
                            return False
            if cntW == half_row:
                for c in range(C):
                    if not is_single(dom[idx][c]):
                        if not apply_assign(idx, c, 1 << B):
                            return False
        else:
            cntB, cntW, un = col_cntB[idx], col_cntW[idx], col_un[idx]
            if cntB > half_col or cntW > half_col:
                return False
            if un == 0:
                return True
            if cntB == half_col:
                for r in range(R):
                    if not is_single(dom[r][idx]):
                        if not apply_assign(r, idx, 1 << W):
                            return False
            if cntW == half_col:
                for r in range(R):
                    if not is_single(dom[r][idx]):
                        if not apply_assign(r, idx, 1 << B):
                            return False
        return True

    def enforce_no_triples_at(r,c):
        # Apply local pattern constraints in row/col around (r,c) for "no three consecutive same"
        # This is strong when neighbors are fixed.
        def process_line(get_mask, set_mask, length):
            for i in range(length):
                pass

        # Row patterns affecting positions c-2..c+2
        rr = r
        for start in (c-2, c-1, c):
            if 0 <= start and start+2 < C:
                m0, m1, m2 = dom[rr][start], dom[rr][start+1], dom[rr][start+2]
                # If two fixed equal => third must be opposite to avoid triple when adjacent
                if is_single(m0) and is_single(m1) and val_of(m0) == val_of(m1):
                    if not apply_assign(rr, start+2, mask_for(other(val_of(m0)))):
                        return False
                if is_single(m1) and is_single(m2) and val_of(m1) == val_of(m2):
                    if not apply_assign(rr, start, mask_for(other(val_of(m1)))):
                        return False
                # If ends fixed equal => middle must be opposite (to avoid ABA? Actually A ? A would force middle opposite; otherwise AAA possible with middle A)
                if is_single(m0) and is_single(m2) and val_of(m0) == val_of(m2):
                    if not apply_assign(rr, start+1, mask_for(other(val_of(m0)))):
                        return False
        # Col patterns
        cc = c
        for start in (r-2, r-1, r):
            if 0 <= start and start+2 < R:
                m0, m1, m2 = dom[start][cc], dom[start+1][cc], dom[start+2][cc]
                if is_single(m0) and is_single(m1) and val_of(m0) == val_of(m1):
                    if not apply_assign(start+2, cc, mask_for(other(val_of(m0)))):
                        return False
                if is_single(m1) and is_single(m2) and val_of(m1) == val_of(m2):
                    if not apply_assign(start, cc, mask_for(other(val_of(m1)))):
                        return False
                if is_single(m0) and is_single(m2) and val_of(m0) == val_of(m2):
                    if not apply_assign(start+1, cc, mask_for(other(val_of(m0)))):
                        return False
        return True

    def enforce_edge_constraints_at(r,c):
        # Apply '=' and 'x' constraints for edges adjacent to (r,c)
        m = dom[r][c]
        # left
        if c-1 >= 0 and h[r][c-1] is not None:
            rel = h[r][c-1]
            m2 = dom[r][c-1]
            if rel == "=":
                # intersect both with each other
                if not apply_assign(r, c, m2): return False
                if not apply_assign(r, c-1, dom[r][c]): return False
            else:
                # x: if one fixed, other cannot be same
                if is_single(dom[r][c-1]):
                    if not apply_assign(r, c, ALL ^ dom[r][c-1]): return False
                if is_single(dom[r][c]):
                    if not apply_assign(r, c-1, ALL ^ dom[r][c]): return False
                # if both two-valued, nothing more
        # right
        if c < C-1 and h[r][c] is not None:
            rel = h[r][c]
            m2 = dom[r][c+1]
            if rel == "=":
                if not apply_assign(r, c, m2): return False
                if not apply_assign(r, c+1, dom[r][c]): return False
            else:
                if is_single(dom[r][c+1]):
                    if not apply_assign(r, c, ALL ^ dom[r][c+1]): return False
                if is_single(dom[r][c]):
                    if not apply_assign(r, c+1, ALL ^ dom[r][c]): return False
        # up
        if r-1 >= 0 and v[r-1][c] is not None:
            rel = v[r-1][c]
            m2 = dom[r-1][c]
            if rel == "=":
                if not apply_assign(r, c, m2): return False
                if not apply_assign(r-1, c, dom[r][c]): return False
            else:
                if is_single(dom[r-1][c]):
                    if not apply_assign(r, c, ALL ^ dom[r-1][c]): return False
                if is_single(dom[r][c]):
                    if not apply_assign(r-1, c, ALL ^ dom[r][c]): return False
        # down
        if r < R-1 and v[r][c] is not None:
            rel = v[r][c]
            m2 = dom[r+1][c]
            if rel == "=":
                if not apply_assign(r, c, m2): return False
                if not apply_assign(r+1, c, dom[r][c]): return False
            else:
                if is_single(dom[r+1][c]):
                    if not apply_assign(r, c, ALL ^ dom[r+1][c]): return False
                if is_single(dom[r][c]):
                    if not apply_assign(r+1, c, ALL ^ dom[r][c]): return False
        return True

    def propagate():
        # AC-style propagation with targeted deductions
        # Additionally, re-check row/col counts when any cell in them changes.
        touched_rows = set()
        touched_cols = set()
        while q:
            r,c = q.popleft()
            inq[r][c] = False
            if dom[r][c] == 0:
                return False
            # Always enforce adjacency constraints & no-triples locally
            if not enforce_edge_constraints_at(r,c):
                return False
            if not enforce_no_triples_at(r,c):
                return False
            touched_rows.add(r)
            touched_cols.add(c)
        # Count-based fill
        for r in touched_rows:
            if not enforce_counts_line(True, r):
                return False
        for c in touched_cols:
            if not enforce_counts_line(False, c):
                return False
        return True

    def is_solved():
        for r in range(R):
            if row_un[r] != 0:
                return False
            if row_cntB[r] != half_row or row_cntW[r] != half_row:
                return False
        for c in range(C):
            if col_un[c] != 0:
                return False
            if col_cntB[c] != half_col or col_cntW[c] != half_col:
                return False
        return True

    def select_cell():
        # MRV + degree heuristic
        best = None
        best_score = None
        for r in range(R):
            for c in range(C):
                m = dom[r][c]
                if not is_single(m):
                    # domain size 2 always here, but still use degree: constraints + near triples impact
                    deg = 0
                    if c-1 >= 0 and h[r][c-1] is not None: deg += 1
                    if c < C-1 and h[r][c] is not None: deg += 1
                    if r-1 >= 0 and v[r-1][c] is not None: deg += 1
                    if r < R-1 and v[r][c] is not None: deg += 1
                    # also prefer cells in rows/cols close to half limit
                    slack = (half_row - max(row_cntB[r], row_cntW[r])) + (half_col - max(col_cntB[c], col_cntW[c]))
                    score = (-deg, slack)
                    if best is None or score < best_score:
                        best = (r,c)
                        best_score = score
        return best

    def snapshot():
        return (
            [row[:] for row in dom],
            row_cntB[:], row_cntW[:], row_un[:],
            col_cntB[:], col_cntW[:], col_un[:],
            deque(q), [row[:] for row in inq]
        )

    def restore(snap):
        nonlocal dom, row_cntB, row_cntW, row_un, col_cntB, col_cntW, col_un, q, inq
        dom, row_cntB, row_cntW, row_un, col_cntB, col_cntW, col_un, q, inq = snap

    if not propagate():
        return "No Solution"

    # DFS with propagation; not naive because propagation is strong and branching is minimal
    def dfs():
        if is_solved():
            return True
        cell = select_cell()
        if cell is None:
            return False
        r,c = cell
        m = dom[r][c]
        # value ordering: try value that helps balance row/col (heuristic)
        opts = []
        for color in (W, B):
            if m & (1<<color):
                # compute imbalance cost
                rb = row_cntB[r] + (1 if color==B else 0)
                rw = row_cntW[r] + (1 if color==W else 0)
                cb = col_cntB[c] + (1 if color==B else 0)
                cw = col_cntW[c] + (1 if color==W else 0)
                cost = abs(rb - rw) + abs(cb - cw)
                opts.append((cost, color))
        opts.sort()
        for _, color in opts:
            snap = snapshot()
            if apply_assign(r,c,1<<color) and propagate() and dfs():
                return True
            restore(snap)
        return False

    if not dfs():
        return "No Solution"

    # Build output grid in 'B'/'W'
    out = []
    for r in range(R):
        row = []
        for c in range(C):
            if not is_single(dom[r][c]):
                return "No Solution"
            row.append("B" if val_of(dom[r][c]) == B else "W")
        out.append(row)
    return str(out)

