# Generalized Irregular Sudoku (Jigsaw) solver for N x N, symbols 1..N
# Human-like techniques implemented:
# - Constraint propagation with bitmasks
# - Naked singles (cell with one candidate)
# - Hidden singles (only place for a digit in row/col/region)
# - Locked candidates (pointing/claiming between region and row/col)
# - MRV + degree heuristic branching with forward checking
# - Iterative propagation stack to avoid full rescans

from collections import defaultdict, deque

def solve(observation):
    region = observation["region"]
    givens = observation["data"]
    N = len(region)
    if N == 0 or any(len(r) != N for r in region) or any(len(r) != N for r in givens):
        return "No Solution"

    ALL = (1 << N) - 1  # bits 0..N-1 correspond to digits 1..N

    def bit(d):  # d in 1..N
        return 1 << (d - 1)

    def popcount(x):
        return x.bit_count()

    def lowbit(x):
        return x & -x

    def bit_to_digit(b):
        return (b.bit_length() - 1) + 1

    # Build region groups and validate region sizes
    reg_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            reg_cells[region[r][c]].append((r, c))
    # Each region must contain exactly N cells for a proper Latin constraint
    if any(len(cells) != N for cells in reg_cells.values()):
        return "No Solution"
    reg_ids = sorted(reg_cells.keys())
    R = len(reg_ids)
    # Map region id to compact index
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}

    # Units: rows, cols, regs
    row_cells = [[(r, c) for c in range(N)] for r in range(N)]
    col_cells = [[(r, c) for r in range(N)] for c in range(N)]
    reg_cells_list = [reg_cells[rid] for rid in reg_ids]

    # Precompute peers (cells sharing row/col/region)
    peers = [[set() for _ in range(N)] for __ in range(N)]
    for r in range(N):
        for c in range(N):
            ridx = reg_index[region[r][c]]
            for cc in range(N):
                if cc != c:
                    peers[r][c].add((r, cc))
            for rr in range(N):
                if rr != r:
                    peers[r][c].add((rr, c))
            for (rr, cc) in reg_cells_list[ridx]:
                if rr != r or cc != c:
                    peers[r][c].add((rr, cc))

    # Candidate masks per cell
    cand = [[ALL for _ in range(N)] for __ in range(N)]

    # Used masks per unit
    row_used = [0] * N
    col_used = [0] * N
    reg_used = [0] * R

    # Initialize from givens
    fixed = [[0] * N for _ in range(N)]  # 0 if unset else digit
    for r in range(N):
        for c in range(N):
            v = givens[r][c]
            if v is None:
                continue
            if not (1 <= v <= N):
                return "No Solution"
            ridx = reg_index[region[r][c]]
            b = bit(v)
            if (row_used[r] & b) or (col_used[c] & b) or (reg_used[ridx] & b):
                return "No Solution"
            fixed[r][c] = v
            row_used[r] |= b
            col_used[c] |= b
            reg_used[ridx] |= b

    # Set initial candidates: remove used in row/col/reg
    for r in range(N):
        for c in range(N):
            ridx = reg_index[region[r][c]]
            if fixed[r][c]:
                cand[r][c] = bit(fixed[r][c])
            else:
                cand[r][c] = ALL & ~(row_used[r] | col_used[c] | reg_used[ridx])
                if cand[r][c] == 0:
                    return "No Solution"

    # Propagation engine: assign + eliminate, with a stack of events
    # We'll use a queue of assigned cells for peer eliminations.
    assign_q = deque()

    def enqueue_if_single(r, c):
        if fixed[r][c] == 0 and popcount(cand[r][c]) == 1:
            assign_q.append((r, c))

    # Seed singles from initial candidates
    for r in range(N):
        for c in range(N):
            enqueue_if_single(r, c)

    def do_assign(r, c, v):
        """Assign digit v to cell (r,c). Return False on contradiction."""
        if fixed[r][c]:
            return fixed[r][c] == v
        b = bit(v)
        if not (cand[r][c] & b):
            return False

        # Update used masks
        ridx = reg_index[region[r][c]]
        if (row_used[r] & b) or (col_used[c] & b) or (reg_used[ridx] & b):
            return False
        fixed[r][c] = v
        cand[r][c] = b
        row_used[r] |= b
        col_used[c] |= b
        reg_used[ridx] |= b

        # Remove this value from peers
        for (rr, cc) in peers[r][c]:
            if fixed[rr][cc]:
                if fixed[rr][cc] == v:
                    return False
                continue
            if cand[rr][cc] & b:
                cand[rr][cc] &= ~b
                if cand[rr][cc] == 0:
                    return False
                if popcount(cand[rr][cc]) == 1:
                    assign_q.append((rr, cc))
        return True

    def hidden_singles_unit(cells):
        """Find hidden singles in a unit; assign them."""
        # Count occurrences of each digit bit among candidates in unit
        pos = [None] * N  # store last cell where digit appears
        cnt = [0] * N
        for (r, c) in cells:
            m = cand[r][c]
            # if already fixed, treat as only candidate
            # (m already equals its bit)
            x = m
            while x:
                lb = lowbit(x)
                d = lb.bit_length() - 1
                cnt[d] += 1
                pos[d] = (r, c)
                x -= lb
        progressed = False
        for d in range(N):
            if cnt[d] == 1:
                r, c = pos[d]
                if fixed[r][c] == 0:
                    if not do_assign(r, c, d + 1):
                        return None  # contradiction
                    progressed = True
        return progressed

    def locked_candidates():
        """
        Pointing/Claiming:
        - If in a region, all candidates for a digit lie in one row (or col),
          eliminate that digit from the rest of that row (or col) outside region.
        - If in a row (or col), all candidates for a digit lie in one region,
          eliminate from the rest of that region outside the row (or col).
        """
        progressed = False

        # Region -> row/col (pointing)
        for ridx, cells in enumerate(reg_cells_list):
            # For each digit, collect rows/cols positions within the region
            rows_for = [set() for _ in range(N)]
            cols_for = [set() for _ in range(N)]
            anypos = [False] * N
            for (r, c) in cells:
                x = cand[r][c]
                while x:
                    lb = lowbit(x)
                    d = lb.bit_length() - 1
                    anypos[d] = True
                    rows_for[d].add(r)
                    cols_for[d].add(c)
                    x -= lb
            for d in range(N):
                if not anypos[d]:
                    continue
                b = 1 << d
                if len(rows_for[d]) == 1:
                    rr = next(iter(rows_for[d]))
                    # eliminate from row rr outside this region
                    for cc in range(N):
                        if reg_index[region[rr][cc]] != ridx and fixed[rr][cc] == 0 and (cand[rr][cc] & b):
                            cand[rr][cc] &= ~b
                            if cand[rr][cc] == 0:
                                return None
                            progressed = True
                            if popcount(cand[rr][cc]) == 1:
                                assign_q.append((rr, cc))
                if len(cols_for[d]) == 1:
                    cc = next(iter(cols_for[d]))
                    for rr in range(N):
                        if reg_index[region[rr][cc]] != ridx and fixed[rr][cc] == 0 and (cand[rr][cc] & b):
                            cand[rr][cc] &= ~b
                            if cand[rr][cc] == 0:
                                return None
                            progressed = True
                            if popcount(cand[rr][cc]) == 1:
                                assign_q.append((rr, cc))

        # Row -> region (claiming)
        for r in range(N):
            # digit -> set of regions
            regs_for = [set() for _ in range(N)]
            anypos = [False] * N
            for c in range(N):
                x = cand[r][c]
                ridx = reg_index[region[r][c]]
                while x:
                    lb = lowbit(x)
                    d = lb.bit_length() - 1
                    anypos[d] = True
                    regs_for[d].add(ridx)
                    x -= lb
            for d in range(N):
                if not anypos[d] or len(regs_for[d]) != 1:
                    continue
                target = next(iter(regs_for[d]))
                b = 1 << d
                # eliminate from region target outside row r
                for (rr, cc) in reg_cells_list[target]:
                    if rr != r and fixed[rr][cc] == 0 and (cand[rr][cc] & b):
                        cand[rr][cc] &= ~b
                        if cand[rr][cc] == 0:
                            return None
                        progressed = True
                        if popcount(cand[rr][cc]) == 1:
                            assign_q.append((rr, cc))

        # Col -> region (claiming)
        for c in range(N):
            regs_for = [set() for _ in range(N)]
            anypos = [False] * N
            for r in range(N):
                x = cand[r][c]
                ridx = reg_index[region[r][c]]
                while x:
                    lb = lowbit(x)
                    d = lb.bit_length() - 1
                    anypos[d] = True
                    regs_for[d].add(ridx)
                    x -= lb
            for d in range(N):
                if not anypos[d] or len(regs_for[d]) != 1:
                    continue
                target = next(iter(regs_for[d]))
                b = 1 << d
                for (rr, cc) in reg_cells_list[target]:
                    if cc != c and fixed[rr][cc] == 0 and (cand[rr][cc] & b):
                        cand[rr][cc] &= ~b
                        if cand[rr][cc] == 0:
                            return None
                        progressed = True
                        if popcount(cand[rr][cc]) == 1:
                            assign_q.append((rr, cc))

        return progressed

    def propagate():
        """Run propagation until fixpoint; return False on contradiction."""
        # First assign queued singles
        while True:
            while assign_q:
                r, c = assign_q.popleft()
                if fixed[r][c]:
                    continue
                m = cand[r][c]
                if m == 0:
                    return False
                v = bit_to_digit(m)
                if not do_assign(r, c, v):
                    return False

            progress = False

            # Hidden singles (rows, cols, regs)
            for r in range(N):
                res = hidden_singles_unit(row_cells[r])
                if res is None:
                    return False
                progress |= res
            for c in range(N):
                res = hidden_singles_unit(col_cells[c])
                if res is None:
                    return False
                progress |= res
            for ridx in range(R):
                res = hidden_singles_unit(reg_cells_list[ridx])
                if res is None:
                    return False
                progress |= res

            # Locked candidates
            res = locked_candidates()
            if res is None:
                return False
            progress |= res

            # Any new singles queued?
            if not progress and not assign_q:
                break
        return True

    def is_solved():
        for r in range(N):
            for c in range(N):
                if fixed[r][c] == 0:
                    return False
        return True

    # Snapshot/restore for DFS (lightweight copying of arrays)
    def snapshot():
        return (
            [row[:] for row in cand],
            [row[:] for row in fixed],
            row_used[:],
            col_used[:],
            reg_used[:],
            deque(assign_q),
        )

    def restore(snap):
        nonlocal cand, fixed, row_used, col_used, reg_used, assign_q
        cand, fixed, row_used, col_used, reg_used, assign_q = snap

    # Choose next cell: MRV with tie-break by degree (more peers unresolved)
    def select_unassigned():
        best = None
        best_pc = 10**9
        best_deg = -1
        for r in range(N):
            for c in range(N):
                if fixed[r][c]:
                    continue
                pc = popcount(cand[r][c])
                if pc < best_pc:
                    best_pc = pc
                    # degree: count unresolved peers
                    deg = 0
                    for (rr, cc) in peers[r][c]:
                        if fixed[rr][cc] == 0:
                            deg += 1
                    best_deg = deg
                    best = (r, c)
                    if pc == 2 and best_deg > 0:
                        # good enough, but continue to possibly find pc==1 (shouldn't happen here)
                        pass
                elif pc == best_pc:
                    deg = 0
                    for (rr, cc) in peers[r][c]:
                        if fixed[rr][cc] == 0:
                            deg += 1
                    if deg > best_deg:
                        best_deg = deg
                        best = (r, c)
        return best

    # Value ordering: least constraining value (LCV) based on peer eliminations
    def ordered_values(r, c):
        m = cand[r][c]
        vals = []
        x = m
        while x:
            lb = lowbit(x)
            d = bit_to_digit(lb)
            vals.append(d)
            x -= lb

        def score(v):
            b = bit(v)
            s = 0
            for (rr, cc) in peers[r][c]:
                if fixed[rr][cc] == 0 and (cand[rr][cc] & b):
                    s += 1
            return s

        vals.sort(key=score)  # fewer eliminations first
        return vals

    def dfs():
        if not propagate():
            return False
        if is_solved():
            return True

        rc = select_unassigned()
        if rc is None:
            return False
        r, c = rc

        for v in ordered_values(r, c):
            snap = snapshot()
            if do_assign(r, c, v):
                if dfs():
                    return True
            restore(snap)
        return False

    if not dfs():
        return "No Solution"

    return [[fixed[r][c] for c in range(N)] for r in range(N)]


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 2, 2], [3, 3, 3, 4, 2], [3, 5, 5, 5, 6], [3, 7, 7, 7, 7], [8, 8, 8, 8, 8]], 'data': [[None, None, None, 2, None], [None, None, None, None, None], [None, 5, None, 1, None], [None, None, None, None, None], [None, 4, None, None, None]]}
from __future__ import annotations

# Irregular Latin-square / Jigsaw Sudoku (size N x N with symbols 1..N)
# Human-like techniques implemented:
# - Candidate tracking via bitmasks
# - Naked singles / Hidden singles (row/col/region)
# - Intersection elimination (pointing/claiming between region and row/col)
# - Naked subsets up to size 4 in row/col/region
# - MRV + degree heuristic for branching; forward-checking with strong propagation
# This is not a pure brute force; search is used only when logic stalls.

from typing import List, Optional, Tuple, Dict

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    if n == 0 or any(len(r) != n for r in region) or any(len(r) != n for r in data):
        return "No Solution"

    # Validate symbols range
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None and not (1 <= v <= n):
                return "No Solution"

    # Map regions to cells
    reg_ids = set()
    for r in range(n):
        for c in range(n):
            reg_ids.add(region[r][c])
    reg_ids = sorted(reg_ids)
    rid_to_idx = {rid: i for i, rid in enumerate(reg_ids)}
    R = len(reg_ids)
    if R != n:
        # In a standard Latin jigsaw, number of regions must be N and each region size N.
        # If not, still attempt but enforce region uniqueness with available regions.
        pass

    reg_cells: List[List[int]] = [[] for _ in range(R)]
    for r in range(n):
        for c in range(n):
            reg_cells[rid_to_idx[region[r][c]]].append(r * n + c)

    # Precompute units
    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    regs = reg_cells

    # Check region sizes match N (strong assumption of puzzle type)
    if any(len(u) != n for u in regs):
        # Still try; but solver assumes each unit wants all digits 1..N exactly once.
        pass

    units = rows + cols + regs
    cell_units: List[List[int]] = [[] for _ in range(n * n)]
    for ui, u in enumerate(units):
        for cell in u:
            cell_units[cell].append(ui)

    # Peer sets per cell
    peers: List[List[int]] = [[] for _ in range(n * n)]
    for cell in range(n * n):
        pset = set()
        for ui in cell_units[cell]:
            for other in units[ui]:
                if other != cell:
                    pset.add(other)
        peers[cell] = list(pset)

    ALL = (1 << n) - 1
    def bit(d): return 1 << (d - 1)

    # State: candidates per cell bitmask; row/col/reg used masks
    cand = [ALL] * (n * n)
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * R

    def reg_index(cell: int) -> int:
        r, c = divmod(cell, n)
        return rid_to_idx[region[r][c]]

    # Initialize with givens
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            cell = r * n + c
            m = bit(v)
            ri = reg_index(cell)
            if (row_used[r] & m) or (col_used[c] & m) or (reg_used[ri] & m):
                return "No Solution"
            row_used[r] |= m
            col_used[c] |= m
            reg_used[ri] |= m
            cand[cell] = m

    # Apply initial elimination
    for cell in range(n * n):
        if cand[cell] & (cand[cell] - 1) == 0:  # single
            continue
        r, c = divmod(cell, n)
        ri = reg_index(cell)
        used = row_used[r] | col_used[c] | reg_used[ri]
        cand[cell] &= ~used
        if cand[cell] == 0:
            return "No Solution"

    # Utility
    def popcount(x: int) -> int:
        return x.bit_count()

    def lowest_bit_index(x: int) -> int:
        # x != 0
        return (x & -x).bit_length() - 1

    def mask_to_vals(m: int) -> List[int]:
        out = []
        while m:
            lsb = m & -m
            out.append(lsb.bit_length())
            m -= lsb
        return out

    # Propagation with trail for undo
    TrailEntry = Tuple[int, int]  # (cell, previous_mask) for candidate changes; also special markers
    AssignEntry = Tuple[int, int, int, int, int]  # (cell, oldmask, r, c, ri) for assignment changes to used masks
    # We'll keep separate trails for cand and used masks changes.
    cand_trail: List[TrailEntry] = []
    used_trail: List[Tuple[int, int, int]] = []  # (kind, index, previous_mask); kind:0 row,1 col,2 reg

    def save_cand(cell: int, newmask: int) -> bool:
        old = cand[cell]
        if old == newmask:
            return True
        if newmask == 0:
            return False
        cand_trail.append((cell, old))
        cand[cell] = newmask
        return True

    def save_used(kind: int, idx: int, newmask: int):
        if kind == 0:
            old = row_used[idx]
            if old != newmask:
                used_trail.append((kind, idx, old))
                row_used[idx] = newmask
        elif kind == 1:
            old = col_used[idx]
            if old != newmask:
                used_trail.append((kind, idx, old))
                col_used[idx] = newmask
        else:
            old = reg_used[idx]
            if old != newmask:
                used_trail.append((kind, idx, old))
                reg_used[idx] = newmask

    def undo(cand_mark: int, used_mark: int):
        while len(cand_trail) > cand_mark:
            cell, old = cand_trail.pop()
            cand[cell] = old
        while len(used_trail) > used_mark:
            kind, idx, old = used_trail.pop()
            if kind == 0:
                row_used[idx] = old
            elif kind == 1:
                col_used[idx] = old
            else:
                reg_used[idx] = old

    # Queue-based propagate
    from collections import deque

    def assign(cell: int, vmask: int, q: deque) -> bool:
        # set cell to vmask (single) and update used masks, eliminate from peers
        if cand[cell] == vmask:
            return True
        if cand[cell] & vmask == 0:
            return False
        if not save_cand(cell, vmask):
            return False
        q.append(cell)
        return True

    def propagate() -> bool:
        q = deque([i for i in range(n * n) if cand[i] & (cand[i] - 1) == 0])
        inq = [False] * (n * n)
        for i in q:
            inq[i] = True

        while q:
            cell = q.popleft()
            inq[cell] = False
            m = cand[cell]
            if m == 0:
                return False
            if m & (m - 1):
                continue  # not single anymore
            r, c = divmod(cell, n)
            ri = reg_index(cell)

            # If used masks not updated for this single, update (idempotently)
            if row_used[r] & m == 0:
                save_used(0, r, row_used[r] | m)
            if col_used[c] & m == 0:
                save_used(1, c, col_used[c] | m)
            if reg_used[ri] & m == 0:
                save_used(2, ri, reg_used[ri] | m)

            # Eliminate from peers
            for p in peers[cell]:
                pm = cand[p]
                if pm & m:
                    nm = pm & ~m
                    if nm == 0:
                        return False
                    if nm != pm:
                        if not save_cand(p, nm):
                            return False
                        if nm & (nm - 1) == 0 and not inq[p]:
                            q.append(p); inq[p] = True

        return True

    # Deductive techniques over units
    def hidden_singles() -> bool:
        # For each unit, if a digit appears in candidates of only one cell, assign it.
        q = deque()
        for u in units:
            # fast per-digit count via accumulation
            loc = [None] * n
            count = [0] * n
            for cell in u:
                m = cand[cell]
                while m:
                    lsb = m & -m
                    d = lsb.bit_length() - 1
                    count[d] += 1
                    loc[d] = cell if count[d] == 1 else loc[d]
                    m -= lsb
            for d in range(n):
                if count[d] == 1:
                    cell = loc[d]
                    if cell is None:
                        continue
                    vm = 1 << d
                    if cand[cell] != vm:
                        if not assign(cell, vm, q):
                            return False
        # propagate assignments
        while q:
            cell = q.popleft()
            # ensure propagation effects
            if not propagate():
                return False
        return True

    def intersection_elimination() -> bool:
        # Pointing/claiming: within a region, if all candidates of digit d lie in one row/col, remove d from that row/col outside region.
        for ridx, u in enumerate(regs):
            # Build digit-> rows/cols mask and cells list
            rows_mask = [0] * n
            cols_mask = [0] * n
            cells_for_d: List[List[int]] = [[] for _ in range(n)]
            for cell in u:
                r, c = divmod(cell, n)
                m = cand[cell]
                while m:
                    lsb = m & -m
                    d = lsb.bit_length() - 1
                    rows_mask[d] |= 1 << r
                    cols_mask[d] |= 1 << c
                    cells_for_d[d].append(cell)
                    m -= lsb

            for d in range(n):
                if not cells_for_d[d]:
                    continue
                dm = 1 << d
                rm = rows_mask[d]
                cm = cols_mask[d]
                # If restricted to single row
                if rm and (rm & (rm - 1)) == 0:
                    r = lowest_bit_index(rm)
                    # remove dm from row r cells not in this region
                    for cell in rows[r]:
                        if reg_index(cell) != ridx and (cand[cell] & dm):
                            if not save_cand(cell, cand[cell] & ~dm):
                                return False
                # If restricted to single col
                if cm and (cm & (cm - 1)) == 0:
                    c = lowest_bit_index(cm)
                    for cell in cols[c]:
                        if reg_index(cell) != ridx and (cand[cell] & dm):
                            if not save_cand(cell, cand[cell] & ~dm):
                                return False

        # Claiming: in a row/col, if all candidates of digit d lie in one region, remove from other cells in that region.
        # Rows
        for r in range(n):
            u = rows[r]
            regs_mask = [0] * n
            cells_for_d: List[List[int]] = [[] for _ in range(n)]
            for cell in u:
                ri = reg_index(cell)
                m = cand[cell]
                while m:
                    lsb = m & -m
                    d = lsb.bit_length() - 1
                    regs_mask[d] |= 1 << ri
                    cells_for_d[d].append(cell)
                    m -= lsb
            for d in range(n):
                if not cells_for_d[d]:
                    continue
                rm = regs_mask[d]
                if rm and (rm & (rm - 1)) == 0:
                    ri = lowest_bit_index(rm)
                    dm = 1 << d
                    for cell in regs[ri]:
                        if cell not in u and (cand[cell] & dm):
                            if not save_cand(cell, cand[cell] & ~dm):
                                return False
        # Cols
        for c in range(n):
            u = cols[c]
            regs_mask = [0] * n
            cells_for_d: List[List[int]] = [[] for _ in range(n)]
            for cell in u:
                ri = reg_index(cell)
                m = cand[cell]
                while m:
                    lsb = m & -m
                    d = lsb.bit_length() - 1
                    regs_mask[d] |= 1 << ri
                    cells_for_d[d].append(cell)
                    m -= lsb
            for d in range(n):
                if not cells_for_d[d]:
                    continue
                rm = regs_mask[d]
                if rm and (rm & (rm - 1)) == 0:
                    ri = lowest_bit_index(rm)
                    dm = 1 << d
                    for cell in regs[ri]:
                        if cell not in u and (cand[cell] & dm):
                            if not save_cand(cell, cand[cell] & ~dm):
                                return False

        return propagate()

    def naked_subsets_in_unit(u: List[int], max_k: int = 4) -> bool:
        # Find k cells whose candidates union size == k; eliminate those digits from others.
        # Use pattern grouping by candidate mask.
        # Only consider cells with 2..max_k candidates.
        masks: Dict[int, List[int]] = {}
        for cell in u:
            m = cand[cell]
            pc = popcount(m)
            if 2 <= pc <= max_k:
                masks.setdefault(m, []).append(cell)

        # First: direct same-mask groups (e.g., naked pairs/triples)
        for m, cells in list(masks.items()):
            k = popcount(m)
            if k <= max_k and len(cells) == k:
                # eliminate m from other cells
                for cell in u:
                    if cell not in cells and (cand[cell] & m):
                        if not save_cand(cell, cand[cell] & ~m):
                            return False

        # Second: combinations across different masks (limited)
        # collect unique masks list
        uniq = [(m, masks[m]) for m in masks]
        umasks = [m for m, _ in uniq]
        L = len(umasks)
        # Try combinations size 2..max_k
        # small N (typically <= 9), so manageable; we restrict by popcount union pruning.
        def rec(start: int, choose: int, union: int, chosen_cells: set) -> bool:
            if choose == 0:
                k = popcount(union)
                if k < 2 or k > max_k:
                    return True
                # Verify exactly k cells involved
                if len(chosen_cells) != k:
                    return True
                # eliminate union from other cells
                for cell in u:
                    if cell not in chosen_cells and (cand[cell] & union):
                        if not save_cand(cell, cand[cell] & ~union):
                            return False
                return True
            for i in range(start, L - choose + 1):
                m = umasks[i]
                new_union = union | m
                if popcount(new_union) > max_k:
                    continue
                # add all cells that have this mask; but for mixed subsets, we need a specific selection of cells.
                # Approximation: use at most one representative cell per mask group; however classic naked subset can involve
                # different masks across different cells. We'll build chosen cells by taking all cells of these masks but cap.
                # More accurate: enumerate cells directly. Given N small, implement cell-based recursion instead.
            return True

        # Accurate cell-based search limited to max_k
        candidates_cells = [cell for cell in u if 2 <= popcount(cand[cell]) <= max_k]
        M = len(candidates_cells)
        # early exit
        if M < 2:
            return True

        # Enumerate combinations of cells size 2..max_k with pruning by union size
        def comb_rec(idx: int, target: int, chosen: List[int], union: int) -> bool:
            if len(chosen) == target:
                if popcount(union) == target:
                    chosen_set = set(chosen)
                    for cell in u:
                        if cell not in chosen_set and (cand[cell] & union):
                            if not save_cand(cell, cand[cell] & ~union):
                                return False
                return True
            if idx >= M:
                return True
            # pruning: even if we take all remaining, can't reach target
            if len(chosen) + (M - idx) < target:
                return True
            cell = candidates_cells[idx]
            m = cand[cell]
            # choose
            new_union = union | m
            if popcount(new_union) <= target:
                chosen.append(cell)
                if not comb_rec(idx + 1, target, chosen, new_union):
                    return False
                chosen.pop()
            # skip
            return comb_rec(idx + 1, target, chosen, union)

        for k in range(2, max_k + 1):
            if M >= k:
                if not comb_rec(0, k, [], 0):
                    return False
        return True

    def naked_subsets() -> bool:
        for u in units:
            if not naked_subsets_in_unit(u, 4):
                return False
        return propagate()

    def reduce_loop() -> bool:
        # Repeat deductions until stable
        while True:
            cand_mark = len(cand_trail)
            used_mark = len(used_trail)
            if not propagate():
                return False
            if not hidden_singles():
                return False
            if not intersection_elimination():
                return False
            if not naked_subsets():
                return False
            if len(cand_trail) == cand_mark and len(used_trail) == used_mark:
                return True

    def is_solved() -> bool:
        return all((m & (m - 1)) == 0 for m in cand)

    def pick_cell() -> int:
        # MRV with degree tie-break
        best = -1
        best_pc = 10**9
        best_deg = -1
        for cell in range(n * n):
            m = cand[cell]
            pc = popcount(m)
            if pc == 1:
                continue
            if pc < best_pc:
                best_pc = pc
                best = cell
                best_deg = len(peers[cell])
                if pc == 2:
                    # can't do better than 2 for meaningful branch
                    pass
            elif pc == best_pc and pc > 1:
                deg = len(peers[cell])
                if deg > best_deg:
                    best = cell
                    best_deg = deg
        return best

    def dfs() -> bool:
        if not reduce_loop():
            return False
        if is_solved():
            return True
        cell = pick_cell()
        if cell == -1:
            return False
        m = cand[cell]
        # Least-constraining value: try values that eliminate least in peers
        vals = []
        mm = m
        while mm:
            lsb = mm & -mm
            dmask = lsb
            impact = 0
            for p in peers[cell]:
                if cand[p] & dmask:
                    impact += 1
            vals.append((impact, dmask))
            mm -= lsb
        vals.sort(key=lambda x: x[0])

        for _, vmask in vals:
            cand_mark = len(cand_trail)
            used_mark = len(used_trail)
            q = deque()
            if assign(cell, vmask, q) and propagate():
                if dfs():
                    return True
            undo(cand_mark, used_mark)
        return False

    if not dfs():
        return "No Solution"

    # Build solution grid
    sol = [[0] * n for _ in range(n)]
    for cell in range(n * n):
        r, c = divmod(cell, n)
        m = cand[cell]
        if m == 0 or (m & (m - 1)):
            return "No Solution"
        sol[r][c] = m.bit_length()
    return sol


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 1, 2, 2], [3, 0, 4, 1, 2, 2], [3, 0, 4, 5, 2, 2], [3, 0, 6, 6, 2, 2], [3, 0, 6, 6, 7, 7], [3, 0, 6, 6, 6, 6]], 'data': [[None, None, None, None, 1, None], [3, None, 0, None, 1, None], [None, None, None, 1, None, None], [None, None, 1, None, None, None], [None, None, None, None, 1, None], [None, None, 1, None, None, None]]}
from collections import defaultdict, deque
from itertools import combinations

# Solver for "Heyawake" variant:
# 1) Each region has exactly clue black cells if clue exists.
# 2) Black cells cannot touch orthogonally.
# 3) In any row/col, a contiguous white run may not span >2 regions
#    (equivalently: along any row/col, no sequence of consecutive cells all white can contain >=3 region transitions).
# 4) All white cells are orthogonally connected.
#
# Output: NxN list with 'B' for black, None for white.

B, W, U = 1, 0, -1  # black, white, unknown


def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    if n == 0 or any(len(row) != n for row in region):
        return "No Solution"
    if any(len(row) != n for row in data):
        return "No Solution"

    # Map regions
    reg_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            reg_cells[region[r][c]].append((r, c))
    reg_ids = sorted(reg_cells.keys())
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}
    R = len(reg_ids)

    # Region clues (None if absent)
    reg_clue = [None] * R
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            rid = region[r][c]
            idx = reg_index[rid]
            if reg_clue[idx] is None:
                reg_clue[idx] = int(v)
            else:
                # Multiple clues in same region should match
                if reg_clue[idx] != int(v):
                    return "No Solution"

    # Neighbors for orth adjacency
    nbrs = {}
    for r in range(n):
        for c in range(n):
            ns = []
            if r > 0:
                ns.append((r - 1, c))
            if r + 1 < n:
                ns.append((r + 1, c))
            if c > 0:
                ns.append((r, c - 1))
            if c + 1 < n:
                ns.append((r, c + 1))
            nbrs[(r, c)] = ns

    # Precompute row and col region sequences
    row_reg = [[region[r][c] for c in range(n)] for r in range(n)]
    col_reg = [[region[r][c] for r in range(n)] for c in range(n)]

    # Precompute blocks (maximal same-region segments) along rows/cols; used for Heyawake rule pruning
    # But we implement rule as "no all-white segment spanning >=3 regions".
    # We can enforce by checking any window of cells that spans 3 regions must contain at least one black.
    row_windows = [[] for _ in range(n)]
    col_windows = [[] for _ in range(n)]

    def build_windows(line_regions):
        # returns list of (i,j, involved_region_count, cells_indices) for all minimal intervals spanning >=3 regions
        # We'll store all intervals that contain at least 3 distinct region segments (in order), but only "minimal"
        # intervals where removing either end would reduce region-segment count below 3.
        segs = []
        start = 0
        L = len(line_regions)
        while start < L:
            rid = line_regions[start]
            end = start + 1
            while end < L and line_regions[end] == rid:
                end += 1
            segs.append((start, end, rid))  # [start,end)
            start = end

        # For any triple of consecutive segments (k,k+1,k+2), minimal interval spans from seg[k].start to seg[k+2].end-1.
        intervals = []
        for k in range(len(segs) - 2):
            i = segs[k][0]
            j = segs[k + 2][1] - 1
            cells = list(range(i, j + 1))
            intervals.append((i, j, cells))
        # For 4+ segments, any interval spanning >=3 segments will contain some triple-minimal interval;
        # thus it suffices to enforce constraints for each consecutive triple.
        return intervals

    for r in range(n):
        row_windows[r] = build_windows(row_reg[r])
    for c in range(n):
        col_windows[c] = build_windows(col_reg[c])

    # Initial domains/state
    state = [[U] * n for _ in range(n)]

    # Region counts trackers
    reg_total = [len(reg_cells[rid]) for rid in reg_ids]
    reg_black = [0] * R
    reg_unknown = [reg_total[i] for i in range(R)]

    # Utility
    def assign(cell, val, queue):
        rr, cc = cell
        cur = state[rr][cc]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        state[rr][cc] = val
        idx = reg_index[region[rr][cc]]
        if val == B:
            reg_black[idx] += 1
        reg_unknown[idx] -= 1
        queue.append(cell)
        return True

    # Initialize forced from clue=0 or clue=size
    q = deque()
    for rid, idx in reg_index.items():
        clue = reg_clue[idx]
        if clue is None:
            continue
        if clue < 0 or clue > reg_total[idx]:
            return "No Solution"
        if clue == 0:
            for cell in reg_cells[rid]:
                if not assign(cell, W, q):
                    return "No Solution"
        elif clue == reg_total[idx]:
            for cell in reg_cells[rid]:
                if not assign(cell, B, q):
                    return "No Solution"

    # Propagation rules
    def propagate(queue):
        while queue:
            r, c = queue.popleft()
            val = state[r][c]

            # Rule 2: no orth-adjacent blacks
            if val == B:
                for (nr, nc) in nbrs[(r, c)]:
                    if state[nr][nc] == B:
                        return False
                    if state[nr][nc] == U:
                        if not assign((nr, nc), W, queue):
                            return False

            # Region quota checks and deductions
            rid = region[r][c]
            idx = reg_index[rid]
            clue = reg_clue[idx]
            if clue is not None:
                bcnt = reg_black[idx]
                ucnt = reg_unknown[idx]
                # Too many blacks
                if bcnt > clue:
                    return False
                # Not enough capacity for blacks
                if bcnt + ucnt < clue:
                    return False
                # If reached clue, rest must be white
                if bcnt == clue and ucnt > 0:
                    for cell in reg_cells[rid]:
                        rr, cc = cell
                        if state[rr][cc] == U:
                            if not assign(cell, W, queue):
                                return False
                # If need all remaining unknowns black
                if ucnt > 0 and bcnt + ucnt == clue:
                    for cell in reg_cells[rid]:
                        rr, cc = cell
                        if state[rr][cc] == U:
                            if not assign(cell, B, queue):
                                return False

            # Heyawake Rule 3 (local): any 3-region-spanning interval in this row/col cannot be all-white.
            # Enforce: for each such interval, if all cells are decided and all are white => contradiction;
            # if all decided white except one unknown => that unknown must be black.
            # Apply only for affected row/col to keep fast.
            if not enforce_line_rule_row(r, queue):
                return False
            if not enforce_line_rule_col(c, queue):
                return False

        # Global checks/deductions after queue drains
        # 1) connectivity feasibility and forced whites
        if not enforce_connectivity(queue):
            return False
        # 2) after any new assignments, continue propagation
        while queue:
            if not propagate(queue):
                return False
        return True

    def enforce_line_rule_row(r, queue):
        wins = row_windows[r]
        if not wins:
            return True
        for i, j, cells in wins:
            unknown_pos = None
            all_white_so_far = True
            for cc in cells:
                v = state[r][cc]
                if v == B:
                    all_white_so_far = False
                    break
                if v == U:
                    if unknown_pos is None:
                        unknown_pos = cc
                    else:
                        # more than one unknown => can't force
                        unknown_pos = -2
            if not all_white_so_far:
                continue
            if unknown_pos is None:
                # all white => violates (spans 3 regions)
                return False
            if unknown_pos != -2:
                if not assign((r, unknown_pos), B, queue):
                    return False
        return True

    def enforce_line_rule_col(c, queue):
        wins = col_windows[c]
        if not wins:
            return True
        for i, j, cells in wins:
            unknown_pos = None
            all_white_so_far = True
            for rr in cells:
                v = state[rr][c]
                if v == B:
                    all_white_so_far = False
                    break
                if v == U:
                    if unknown_pos is None:
                        unknown_pos = rr
                    else:
                        unknown_pos = -2
            if not all_white_so_far:
                continue
            if unknown_pos is None:
                return False
            if unknown_pos != -2:
                if not assign((unknown_pos, c), B, queue):
                    return False
        return True

    # Connectivity: all white cells must be connected.
    # We use two mechanisms:
    # A) feasibility check: unknowns can be white; blacks are blocked. If all non-black cells split into >1 components -> fail.
    # B) forced-white bridges: if a cell (unknown) is an articulation point for connectivity in the graph of non-black cells
    #    between currently-fixed white cells, we can force it white (common human technique).
    def enforce_connectivity(queue):
        # Collect fixed whites, and graph nodes as cells not black.
        nonblack = []
        fixed_whites = []
        for r in range(n):
            for c in range(n):
                if state[r][c] != B:
                    nonblack.append((r, c))
                if state[r][c] == W:
                    fixed_whites.append((r, c))

        if not nonblack:
            return True  # all black allowed? but region clues may prevent; connectivity vacuously ok

        # Build component labels on-the-fly via BFS over non-black
        seen = set()
        comps = []
        for cell in nonblack:
            if cell in seen:
                continue
            dq = deque([cell])
            seen.add(cell)
            comp = []
            while dq:
                x = dq.popleft()
                comp.append(x)
                for y in nbrs[x]:
                    if state[y[0]][y[1]] != B and y not in seen:
                        seen.add(y)
                        dq.append(y)
            comps.append(comp)
            if len(comps) > 1:
                # If multiple components already even allowing unknowns to be white, impossible
                return False

        # If no fixed whites or only one, no articulation forcing needed
        if len(fixed_whites) <= 1:
            return True

        # Compute articulation points in the graph of non-black cells, but only to force unknowns that are mandatory
        # for connecting fixed whites: remove candidate unknown, see if fixed whites split.
        # We'll do a cheaper test: compute BFS tree from one fixed white; if all fixed whites reachable (they are, by comps==1).
        # For each unknown cell, check if it dominates reachability of some fixed white by testing reachability avoiding it.
        # We'll limit to unknowns adjacent to two+ non-black neighbors (possible cut), and near fixed whites.
        all_nodes = set(nonblack)
        start = fixed_whites[0]

        # Precompute neighbor lists within non-black
        nb_nb = {}
        for cell in all_nodes:
            nb_nb[cell] = [y for y in nbrs[cell] if y in all_nodes]

        # Candidate unknowns: unknown with degree>=2
        candidates = [(r, c) for (r, c) in all_nodes if state[r][c] == U and len(nb_nb[(r, c)]) >= 2]
        if not candidates:
            return True

        fixed_set = set(fixed_whites)

        def reachable_without(block):
            if block == start:
                return set()
            vis = set()
            dq = deque([start])
            vis.add(start)
            while dq:
                x = dq.popleft()
                for y in nb_nb[x]:
                    if y == block or y in vis:
                        continue
                    vis.add(y)
                    dq.append(y)
            return vis

        # Only test a small subset first: candidates that lie on shortest paths between fixed whites are more likely.
        # Heuristic: candidates adjacent to any fixed white or adjacent to any black (corridors).
        cand2 = []
        for cell in candidates:
            r, c = cell
            adj_fw = any(state[nr][nc] == W for (nr, nc) in nbrs[cell])
            adj_black = any(state[nr][nc] == B for (nr, nc) in nbrs[cell])
            if adj_fw or adj_black:
                cand2.append(cell)
        if cand2:
            candidates = cand2

        for cell in candidates:
            vis = reachable_without(cell)
            if not fixed_set.issubset(vis):
                # then this unknown must be white (cannot be black; if black, would block too)
                if not assign(cell, W, queue):
                    return False
        return True

    # Initial propagation
    if not propagate(q):
        return "No Solution"

    # Search with strong branching on region constraints first, then line-rule critical cells.
    def snapshot():
        return (
            [row[:] for row in state],
            reg_black[:],
            reg_unknown[:],
        )

    def restore(snap):
        s_state, s_rb, s_ru = snap
        for r in range(n):
            state[r] = s_state[r][:]
        for i in range(R):
            reg_black[i] = s_rb[i]
            reg_unknown[i] = s_ru[i]

    def is_solved():
        for r in range(n):
            for c in range(n):
                if state[r][c] == U:
                    return False
        # Validate all region clues
        for i in range(R):
            clue = reg_clue[i]
            if clue is not None and reg_black[i] != clue:
                return False
        # Validate connectivity of whites
        whites = [(r, c) for r in range(n) for c in range(n) if state[r][c] == W]
        if whites:
            vis = set([whites[0]])
            dq = deque([whites[0]])
            while dq:
                x = dq.popleft()
                for y in nbrs[x]:
                    if state[y[0]][y[1]] == W and y not in vis:
                        vis.add(y)
                        dq.append(y)
            if len(vis) != len(whites):
                return False
        # Validate Heyawake triple rule fully
        for r in range(n):
            for i, j, cells in row_windows[r]:
                if all(state[r][cc] == W for cc in cells):
                    return False
        for c in range(n):
            for i, j, cells in col_windows[c]:
                if all(state[rr][c] == W for rr in cells):
                    return False
        return True

    def choose_var():
        # Prefer regions with clues and tight remaining
        best = None
        best_score = None

        # 1) choose a region cell if region has remaining blacks to place and small unknown set
        for i, rid in enumerate(reg_ids):
            clue = reg_clue[i]
            if clue is None:
                continue
            need = clue - reg_black[i]
            if need <= 0:
                continue
            # collect unknown cells
            u = []
            for (r, c) in reg_cells[rid]:
                if state[r][c] == U:
                    u.append((r, c))
            if not u:
                continue
            # score: smaller choose(n,k) proxy: (len(u), need) with len small and need close to 0/len helpful
            score = (len(u), min(need, len(u) - need))
            if best_score is None or score < best_score:
                # pick a cell among u with most constraints (adjacent unknown/black, in many windows)
                def cell_score(cell):
                    r, c = cell
                    deg = sum(1 for nb in nbrs[cell] if state[nb[0]][nb[1]] == U)
                    adj_black = sum(1 for nb in nbrs[cell] if state[nb[0]][nb[1]] == B)
                    return -(deg + 2 * adj_black)
                u.sort(key=cell_score)
                best = u[0]
                best_score = score

        if best is not None:
            return best

        # 2) otherwise pick unknown cell that appears in most critical (almost-violated) windows
        best = None
        best_score = -1
        for r in range(n):
            for c in range(n):
                if state[r][c] != U:
                    continue
                crit = 0
                # row windows containing (r,c)
                for _, _, cells in row_windows[r]:
                    if c in cells:
                        # count unknowns in that window
                        unk = 0
                        has_black = False
                        for cc in cells:
                            v = state[r][cc]
                            if v == B:
                                has_black = True
                                break
                            if v == U:
                                unk += 1
                        if (not has_black) and unk <= 2:
                            crit += (3 - unk)  # higher if closer to forcing
                # col windows containing (r,c)
                for _, _, cells in col_windows[c]:
                    if r in cells:
                        unk = 0
                        has_black = False
                        for rr in cells:
                            v = state[rr][c]
                            if v == B:
                                has_black = True
                                break
                            if v == U:
                                unk += 1
                        if (not has_black) and unk <= 2:
                            crit += (3 - unk)
                if crit > best_score:
                    best_score = crit
                    best = (r, c)
        if best is not None and best_score > 0:
            return best

        # 3) fallback: first unknown
        for r in range(n):
            for c in range(n):
                if state[r][c] == U:
                    return (r, c)
        return None

    def search():
        if is_solved():
            return True
        cell = choose_var()
        if cell is None:
            return False

        # Branch order heuristic: try white first usually helps connectivity; but if region needs blacks, black first.
        rid = region[cell[0]][cell[1]]
        idx = reg_index[rid]
        clue = reg_clue[idx]
        order = [W, B]
        if clue is not None:
            need = clue - reg_black[idx]
            if need > 0:
                # if many blacks needed relative to unknowns, try black first
                ucnt = sum(1 for (r, c) in reg_cells[rid] if state[r][c] == U)
                if ucnt > 0 and need / ucnt >= 0.5:
                    order = [B, W]

        for val in order:
            snap = snapshot()
            q = deque()
            if assign(cell, val, q) and propagate(q):
                if search():
                    return True
            restore(snap)
        return False

    if not search():
        return "No Solution"

    # Build required output format
    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if state[r][c] == B else None)
        out.append(row)
    return out


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 1, 2, 2, 2, 3, 3, 3], [0, 1, 4, 5, 5, 3, 3, 3], [0, 6, 6, 5, 5, 7, 7, 8], [0, 6, 6, 9, 9, 7, 7, 8], [10, 6, 6, 9, 9, 11, 11, 8], [10, 12, 13, 9, 9, 11, 11, 8], [14, 12, 13, 9, 9, 11, 11, 15], [14, 12, 13, 9, 9, 11, 11, 15]], 'data': [[0, None, None, None, None, 1, None, None], [None, None, 1, 0, None, None, None, None], [None, 1, None, None, None, None, None, 2], [None, None, None, 3, None, 0, None, None], [None, None, None, None, None, None, None, None], [None, None, 1, None, None, None, None, None], [1, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None]]}
# Solver for: cell coloring with regions and constraints:
# 1) Each region r: exactly clue[r] black cells (clue is stored per-cell but at most one number per region); missing clue => unconstrained count.
# 2) Black cells cannot touch orthogonally.
# 3) Any uninterrupted straight white segment (row/col) cannot pass through more than 2 regions.
#    (Segment = maximal contiguous run of white cells in a row/col.)
# 4) All white cells are orthogonally connected.
#
# Approach:
# - Preprocess regions, clues, adjacency, and line structures.
# - Maintain tri-state grid: -1 unknown, 0 white, 1 black.
# - Aggressive propagation:
#   A) Region quota bounds (forced black/white when remaining equals).
#   B) No-adjacent-black constraint.
#   C) Segment<=2-regions constraint using local reasoning at region boundaries along each row/col.
#      For each boundary between two adjacent cells with different regions, if both are white then they connect regions in that line segment.
#      Enforce that for any maximal run of whites, unique region IDs count <=2.
#      We propagate by forbidding patterns that would make a run span 3 regions: at the moment it becomes inevitable, force a boundary cell black (or split with black).
#   D) White connectivity via union-find with "must-be-connected" pruning using articulation/bridge-like reasoning on unknowns:
#      - If some cells are decided black, they are walls.
#      - Ensure that all decided-white cells are in one component; if they become disconnected, fail.
#      - Additionally, for each unknown cell, if setting it black would disconnect decided-white components with no possible alternative path through unknowns, force it white.
#        Implemented via checking connectivity in the graph of non-black cells under two scenarios (cell forced black).
# - Search:
#   - Choose variable with strongest heuristic: region with tight quota, then cell with high constraint (boundary cell in line, near blacks).
#   - Branch white/black with immediate propagation.
#
# Note: This is a generalized solver; OBSERVATION is just one instance.

from collections import defaultdict, deque

UNKNOWN, WHITE, BLACK = -1, 0, 1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])
    assert n == m, "Expected NxN grid"
    N = n

    # Build regions
    cells_in_region = defaultdict(list)
    for r in range(N):
        for c in range(N):
            cells_in_region[region[r][c]].append((r, c))
    region_ids = sorted(cells_in_region.keys())
    R = len(region_ids)

    # Region clue: take the first number found within region (assume 0..)
    region_clue = {rid: None for rid in region_ids}
    for r in range(N):
        for c in range(N):
            v = data[r][c]
            if v is not None:
                rid = region[r][c]
                if region_clue[rid] is None:
                    region_clue[rid] = int(v)
                else:
                    # If multiple clues appear in a region, keep consistent if possible
                    if region_clue[rid] != int(v):
                        return "No Solution"

    # Neighbors
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    def inb(r,c): return 0 <= r < N and 0 <= c < N

    # Line boundary pairs where region changes (potentially causing 3-region segment issue)
    row_boundaries = [[] for _ in range(N)]  # list of (c, (r,c),(r,c+1)) where regions differ
    col_boundaries = [[] for _ in range(N)]  # list of (r, (r,c),(r+1,c))
    for r in range(N):
        for c in range(N-1):
            if region[r][c] != region[r][c+1]:
                row_boundaries[r].append((c, (r,c), (r,c+1)))
    for c in range(N):
        for r in range(N-1):
            if region[r][c] != region[r+1][c]:
                col_boundaries[c].append((r, (r,c), (r+1,c)))

    # Precompute "region sequence" along each row/col for quick segment region counting
    row_regions = [region[r][:] for r in range(N)]
    col_regions = [[region[r][c] for r in range(N)] for c in range(N)]

    # State
    grid = [[UNKNOWN]*N for _ in range(N)]

    # Apply immediate forced by clue 0 (all cells white) or clue == size (all black, subject to constraints)
    initial_assigns = []
    for rid, clue in region_clue.items():
        if clue is None:
            continue
        cells = cells_in_region[rid]
        if clue < 0 or clue > len(cells):
            return "No Solution"
        if clue == 0:
            for (r,c) in cells:
                initial_assigns.append((r,c,WHITE))
        elif clue == len(cells):
            for (r,c) in cells:
                initial_assigns.append((r,c,BLACK))

    # Utility: region counts
    def region_counts(g):
        b = {rid: 0 for rid in region_ids}
        u = {rid: 0 for rid in region_ids}
        for rid in region_ids:
            for (r,c) in cells_in_region[rid]:
                if g[r][c] == BLACK:
                    b[rid] += 1
                elif g[r][c] == UNKNOWN:
                    u[rid] += 1
        return b, u

    # Check and propagate region quota and adjacency
    def assign(g, r, c, val, queue):
        cur = g[r][c]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        g[r][c] = val
        queue.append((r,c))
        return True

    def propagate(g):
        queue = deque()

        # seed queue with all decided cells
        for r in range(N):
            for c in range(N):
                if g[r][c] != UNKNOWN:
                    queue.append((r,c))

        # Fast region tracking
        bcount, ucount = region_counts(g)

        def update_region(rid):
            clue = region_clue[rid]
            if clue is None:
                return True
            b = bcount[rid]
            u = ucount[rid]
            if b > clue:
                return False
            if b + u < clue:
                return False
            # Force all remaining unknown to white if already met
            if b == clue and u > 0:
                for (rr,cc) in cells_in_region[rid]:
                    if g[rr][cc] == UNKNOWN:
                        if not assign(g, rr, cc, WHITE, queue):
                            return False
                        ucount[rid] -= 1
            # Force all remaining unknown to black if must fill
            if b + u == clue and u > 0:
                for (rr,cc) in cells_in_region[rid]:
                    if g[rr][cc] == UNKNOWN:
                        if not assign(g, rr, cc, BLACK, queue):
                            return False
                        ucount[rid] -= 1
                        bcount[rid] += 1
            return True

        # Initially update all regions
        for rid in region_ids:
            if not update_region(rid):
                return False

        # Helper: enforce segment rule in one row
        def enforce_line_segment_rule_row(r):
            # For each maximal run of known-white and unknown (non-black) cells, only becomes a "white segment"
            # when all cells in that run are WHITE. However, we can still deduce when a third region becomes forced
            # to be within a potential all-white run between blacks/edges with already-white "bridges".
            #
            # We implement a conservative but effective propagation:
            # Whenever we have two boundaries (between different regions) both "open" by having both cells WHITE,
            # and they lie in the same current non-black interval (no BLACK between), then the regions spanned by
            # the whites in that interval would be >=3 unless we place a BLACK somewhere to split.
            #
            # We compute current non-black intervals between blacks and edges; within each, look at region changes
            # positions where both sides are WHITE. If within an interval there are >=2 such open boundaries that
            # imply spanning >=3 regions, we must block at least one boundary by setting one of its cells BLACK.
            #
            # This gives strong deductions when interval has no UNKNOWN flexibility at boundary cells.
            row = g[r]
            # Find black separators
            blacks = [-1] + [i for i,v in enumerate(row) if v == BLACK] + [N]
            for bi in range(len(blacks)-1):
                L = blacks[bi] + 1
                R = blacks[bi+1] - 1
                if L > R:
                    continue
                # Determine region sequence across interval and count distinct regions that could be connected by forced whites.
                # Identify "open boundaries": c where (c,c+1) in interval and regions differ and both cells WHITE.
                open_bounds = []
                for c in range(L, R):
                    if row_regions[r][c] != row_regions[r][c+1] and g[r][c] == WHITE and g[r][c+1] == WHITE:
                        open_bounds.append(c)
                if len(open_bounds) < 2:
                    continue
                # If there are at least two open boundaries, then there exists a contiguous white segment that would cross
                # at least 3 regions if the cells between are all WHITE. But could BLACK/UNKNOWN block it?
                # Since open bounds already connect across region changes, the only way to avoid >2 regions in a final
                # white segment within this non-black interval is to ensure there is at least one BLACK somewhere between
                # the first and last connected region-change. The most local action: block one of the open boundaries by
                # making one of its two cells BLACK (but they are already WHITE -> impossible), so instead the segment must
                # be broken by inserting a BLACK in some cell within the interval (currently UNKNOWN).
                # If there is no UNKNOWN in interval, contradiction.
                any_unknown = any(g[r][c] == UNKNOWN for c in range(L, R+1))
                if not any_unknown:
                    return False
                # If only a single position can be BLACK due to region quotas/adjacency, force it. We do a focused check:
                candidates = []
                for c in range(L, R+1):
                    if g[r][c] == UNKNOWN:
                        candidates.append((r,c))
                if len(candidates) == 1:
                    rr,cc = candidates[0]
                    if not assign(g, rr, cc, BLACK, queue):
                        return False
            return True

        def enforce_line_segment_rule_col(c):
            blacks = [-1] + [i for i in range(N) if g[i][c] == BLACK] + [N]
            for bi in range(len(blacks)-1):
                L = blacks[bi] + 1
                R = blacks[bi+1] - 1
                if L > R:
                    continue
                open_bounds = []
                for r0 in range(L, R):
                    if col_regions[c][r0] != col_regions[c][r0+1] and g[r0][c] == WHITE and g[r0+1][c] == WHITE:
                        open_bounds.append(r0)
                if len(open_bounds) < 2:
                    continue
                any_unknown = any(g[r0][c] == UNKNOWN for r0 in range(L, R+1))
                if not any_unknown:
                    return False
                candidates = []
                for r0 in range(L, R+1):
                    if g[r0][c] == UNKNOWN:
                        candidates.append((r0,c))
                if len(candidates) == 1:
                    rr,cc = candidates[0]
                    if not assign(g, rr, cc, BLACK, queue):
                        return False
            return True

        # White connectivity check among decided whites; plus detect impossible isolation for decided whites
        def check_white_connectivity():
            whites = [(r,c) for r in range(N) for c in range(N) if g[r][c] == WHITE]
            if not whites:
                return True
            start = whites[0]
            seen = set([start])
            dq = deque([start])
            while dq:
                r,c = dq.popleft()
                for dr,dc in dirs:
                    rr,cc = r+dr, c+dc
                    if inb(rr,cc) and g[rr][cc] != BLACK and (rr,cc) not in seen:
                        # traverse through WHITE and UNKNOWN because they could connect in final
                        seen.add((rr,cc))
                        dq.append((rr,cc))
            # all decided white must be reachable through non-black cells
            for w in whites:
                if w not in seen:
                    return False
            return True

        # Main propagation loop
        touched_rows = set()
        touched_cols = set()

        while queue:
            r,c = queue.popleft()
            # Maintain region counts updates and adjacency enforcement
            rid = region[r][c]
            if g[r][c] == BLACK:
                # black adjacency: neighbors cannot be black
                for dr,dc in dirs:
                    rr,cc = r+dr, c+dc
                    if inb(rr,cc):
                        if g[rr][cc] == BLACK:
                            return False
                        if g[rr][cc] == UNKNOWN:
                            if not assign(g, rr, cc, WHITE, queue):
                                return False
                # Update region counts
                # Recompute delta safely
            # Update counts precisely for this cell by recomputing region counts for that region (small)
            # This is efficient since regions are small relative to grid; keeps code simple and correct.
            b = 0
            u = 0
            for (rr,cc) in cells_in_region[rid]:
                if g[rr][cc] == BLACK:
                    b += 1
                elif g[rr][cc] == UNKNOWN:
                    u += 1
            bcount[rid] = b
            ucount[rid] = u
            if not update_region(rid):
                return False

            touched_rows.add(r)
            touched_cols.add(c)

            # If a cell is WHITE, no immediate effect except segment/connectivity handled later

        # Enforce segment rule on touched lines (iterate to fixpoint with region constraints)
        # Iterate a small bounded number of times because enforcing can enqueue new assignments.
        for _ in range(3):
            changed = False
            # rows
            for r in list(touched_rows) if touched_rows else range(N):
                before = None
                if not enforce_line_segment_rule_row(r):
                    return False
            for c in list(touched_cols) if touched_cols else range(N):
                if not enforce_line_segment_rule_col(c):
                    return False
            # apply any newly queued effects
            if queue:
                while queue:
                    r,c = queue.popleft()
                    rid = region[r][c]
                    if g[r][c] == BLACK:
                        for dr,dc in dirs:
                            rr,cc = r+dr, c+dc
                            if inb(rr,cc):
                                if g[rr][cc] == BLACK:
                                    return False
                                if g[rr][cc] == UNKNOWN:
                                    if not assign(g, rr, cc, WHITE, queue):
                                        return False
                    b = 0
                    u = 0
                    for (rr,cc) in cells_in_region[rid]:
                        if g[rr][cc] == BLACK:
                            b += 1
                        elif g[rr][cc] == UNKNOWN:
                            u += 1
                    bcount[rid] = b
                    ucount[rid] = u
                    if not update_region(rid):
                        return False
                changed = True
            if not changed:
                break

        if not check_white_connectivity():
            return False

        return True

    # Seed initial assigns
    seed = deque()
    for r,c,v in initial_assigns:
        if not assign(grid, r, c, v, seed):
            return "No Solution"
    # Apply seeding effects
    while seed:
        r,c = seed.popleft()
        # just keep them; propagation will scan decided cells anyway

    if not propagate(grid):
        return "No Solution"

    # Heuristic variable selection
    def pick_cell(g):
        # Prefer regions with clue and tight remaining
        bcount, ucount = region_counts(g)
        best = None
        best_score = -1
        for rid in region_ids:
            clue = region_clue[rid]
            if clue is None:
                continue
            b = bcount[rid]
            u = ucount[rid]
            if u == 0:
                continue
            rem = clue - b
            # tighter when rem is 0..u
            tight = min(rem, u - rem)
            score = 1000 - tight*10 - u
            # choose a cell in region with additional boundary degree
            for (r,c) in cells_in_region[rid]:
                if g[r][c] == UNKNOWN:
                    deg = 0
                    for dr,dc in dirs:
                        rr,cc = r+dr, c+dc
                        if inb(rr,cc) and g[rr][cc] != UNKNOWN:
                            deg += 1
                    # boundary in row/col between regions
                    bd = 0
                    if c>0 and region[r][c-1] != region[r][c]: bd += 1
                    if c<N-1 and region[r][c+1] != region[r][c]: bd += 1
                    if r>0 and region[r-1][c] != region[r][c]: bd += 1
                    if r<N-1 and region[r+1][c] != region[r][c]: bd += 1
                    sc = score + deg*3 + bd*2
                    if sc > best_score:
                        best_score = sc
                        best = (r,c)
        if best is not None:
            return best
        # Otherwise pick most constrained unknown by adjacency/boundary
        for r in range(N):
            for c in range(N):
                if g[r][c] == UNKNOWN:
                    deg = 0
                    for dr,dc in dirs:
                        rr,cc = r+dr, c+dc
                        if inb(rr,cc) and g[rr][cc] != UNKNOWN:
                            deg += 1
                    bd = 0
                    if c>0 and region[r][c-1] != region[r][c]: bd += 1
                    if c<N-1 and region[r][c+1] != region[r][c]: bd += 1
                    if r>0 and region[r-1][c] != region[r][c]: bd += 1
                    if r<N-1 and region[r+1][c] != region[r][c]: bd += 1
                    sc = deg*3 + bd*2
                    if sc > best_score:
                        best_score = sc
                        best = (r,c)
        return best

    def is_complete(g):
        for r in range(N):
            for c in range(N):
                if g[r][c] == UNKNOWN:
                    return False
        # final checks: region exact, no touching black, segment rule, white connectivity (strict on whites)
        # region exact
        for rid in region_ids:
            clue = region_clue[rid]
            if clue is None:
                continue
            cnt = 0
            for (r,c) in cells_in_region[rid]:
                if g[r][c] == BLACK:
                    cnt += 1
            if cnt != clue:
                return False
        # segment rule strict: for each maximal contiguous white run, regions<=2
        for r in range(N):
            c = 0
            while c < N:
                if g[r][c] == BLACK:
                    c += 1
                    continue
                # run of white (since complete, non-black means white)
                start = c
                regs = set()
                while c < N and g[r][c] != BLACK:
                    regs.add(region[r][c])
                    c += 1
                if len(regs) > 2:
                    return False
        for c in range(N):
            r = 0
            while r < N:
                if g[r][c] == BLACK:
                    r += 1
                    continue
                regs = set()
                while r < N and g[r][c] != BLACK:
                    regs.add(region[r][c])
                    r += 1
                if len(regs) > 2:
                    return False
        # white connectivity strict
        whites = [(r,c) for r in range(N) for c in range(N) if g[r][c] == WHITE]
        if whites:
            start = whites[0]
            seen = set([start])
            dq = deque([start])
            while dq:
                r,c = dq.popleft()
                for dr,dc in dirs:
                    rr,cc = r+dr, c+dc
                    if inb(rr,cc) and g[rr][cc] == WHITE and (rr,cc) not in seen:
                        seen.add((rr,cc))
                        dq.append((rr,cc))
            if len(seen) != len(whites):
                return False
        return True

    def clone(g):
        return [row[:] for row in g]

    def dfs(g, depth=0):
        if is_complete(g):
            return g
        cell = pick_cell(g)
        if cell is None:
            return None
        r,c = cell

        # Order branching: try BLACK if region still needs blacks, else WHITE first
        bcount, ucount = region_counts(g)
        rid = region[r][c]
        clue = region_clue[rid]
        order = [WHITE, BLACK]
        if clue is not None:
            rem = clue - bcount[rid]
            if rem > 0:
                order = [BLACK, WHITE]
            else:
                order = [WHITE, BLACK]

        for val in order:
            g2 = clone(g)
            q = deque()
            if not assign(g2, r, c, val, q):
                continue
            # integrate queue seeds quickly (propagate scans all decided anyway)
            if not propagate(g2):
                continue
            res = dfs(g2, depth+1)
            if res is not None:
                return res
        return None

    sol = dfs(grid)
    if sol is None:
        return "No Solution"
    # Convert to required format: 'B' for black, None for white
    out = [[('B' if sol[r][c] == BLACK else None) for c in range(N)] for r in range(N)]
    return str(out)

