# Irregular Sudoku (Jigsaw Sudoku) solver with human-like deduction + fast backtracking.
# Generalized for N x N where symbols are 1..N and regions partition the grid.

from collections import defaultdict, deque

def solve(observation):
    region = observation["region"]
    grid = observation["data"]
    N = len(grid)
    if N == 0 or any(len(r) != N for r in grid) or any(len(r) != N for r in region):
        return "No Solution"

    # Validate symbols
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v is not None and not (1 <= v <= N):
                return "No Solution"

    # Map regions to cells
    reg_cells = defaultdict(list)
    for r in range(N):
        for c in range(N):
            reg_cells[region[r][c]].append((r, c))
    # Basic region validity: each region must have size N
    if any(len(cells) != N for cells in reg_cells.values()) or len(reg_cells) != N:
        return "No Solution"

    # Precompute peers (row/col/region) for each cell
    rows = [set((r, c) for c in range(N)) for r in range(N)]
    cols = [set((r, c) for r in range(N)) for c in range(N)]
    regs = {}
    for reg_id, cells in reg_cells.items():
        regs[reg_id] = set(cells)

    peers = {}
    for r in range(N):
        for c in range(N):
            reg_id = region[r][c]
            ps = (rows[r] | cols[c] | regs[reg_id]) - {(r, c)}
            peers[(r, c)] = tuple(ps)

    ALL = (1 << N) - 1  # bitmask for digits 1..N (bit i for digit i+1)

    def bit(d):  # d in 1..N
        return 1 << (d - 1)

    def bits_count(x):
        return x.bit_count()

    def bits_iter(x):
        # yields digits (1..N) in x
        while x:
            lsb = x & -x
            d = (lsb.bit_length() - 1) + 1
            yield d
            x ^= lsb

    def singleton_digit(m):
        # assumes m has exactly one bit
        return (m.bit_length() - 1) + 1

    # Unit lists for iteration (rows, cols, regs)
    units = []
    for r in range(N):
        units.append(tuple((r, c) for c in range(N)))
    for c in range(N):
        units.append(tuple((r, c) for r in range(N)))
    for reg_id in sorted(reg_cells.keys()):
        units.append(tuple(reg_cells[reg_id]))

    # Constraints: used masks per row/col/reg
    row_used = [0] * N
    col_used = [0] * N
    reg_used = {rid: 0 for rid in reg_cells}

    # Candidate masks per cell
    cand = [[ALL for _ in range(N)] for _ in range(N)]

    # Initialize with givens
    def place_value(r, c, v, trail):
        """Assign value v to (r,c), push changes to trail for rollback. Return False if contradiction."""
        m = bit(v)
        reg_id = region[r][c]
        if grid[r][c] is not None:
            return grid[r][c] == v

        # Check conflict with used masks
        if (row_used[r] & m) or (col_used[c] & m) or (reg_used[reg_id] & m):
            return False

        # Record state changes
        trail.append(("cell", r, c, grid[r][c]))
        grid[r][c] = v

        trail.append(("row_used", r, row_used[r]))
        row_used[r] |= m
        trail.append(("col_used", c, col_used[c]))
        col_used[c] |= m
        trail.append(("reg_used", reg_id, reg_used[reg_id]))
        reg_used[reg_id] |= m

        # Set candidates for this cell to singleton, and remove from peers
        old = cand[r][c]
        trail.append(("cand", r, c, old))
        cand[r][c] = m

        # Propagate elimination to peers
        for (pr, pc) in peers[(r, c)]:
            if grid[pr][pc] is None and (cand[pr][pc] & m):
                oldp = cand[pr][pc]
                newp = oldp & ~m
                trail.append(("cand", pr, pc, oldp))
                cand[pr][pc] = newp
                if newp == 0:
                    return False
        return True

    def rollback(trail):
        while trail:
            kind, a, b, old = trail.pop()
            if kind == "cell":
                grid[a][b] = old
            elif kind == "row_used":
                row_used[a] = old
            elif kind == "col_used":
                col_used[a] = old
            elif kind == "reg_used":
                reg_used[a] = old
            elif kind == "cand":
                cand[a][b] = old
            else:
                raise RuntimeError("Unknown trail entry")

    # Build initial masks and candidates from givens
    init_trail = []
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v is not None:
                if not place_value(r, c, v, init_trail):
                    return "No Solution"
    # After placing givens, set remaining candidates as allowed by unit used masks
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                reg_id = region[r][c]
                m = ALL & ~(row_used[r] | col_used[c] | reg_used[reg_id])
                if m == 0:
                    rollback(init_trail)
                    return "No Solution"
                cand[r][c] = m

    # Deduction engine
    def deduce(trail):
        """Repeatedly apply human-like deductions until fixed point. Return False if contradiction."""
        q = deque()

        # Seed queue with all unfilled cells and all units
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    q.append(("cell", r, c))
        for ui in range(len(units)):
            q.append(("unit", ui))

        inq_cell = [[True if grid[r][c] is None else False for c in range(N)] for r in range(N)]
        inq_unit = [True] * len(units)

        def push_cell(r, c):
            if grid[r][c] is None and not inq_cell[r][c]:
                inq_cell[r][c] = True
                q.append(("cell", r, c))

        def push_unit(ui):
            if not inq_unit[ui]:
                inq_unit[ui] = True
                q.append(("unit", ui))

        # Whenever a cell changes, its row/col/reg units should be revisited.
        def affected_units_of_cell(r, c):
            # row unit index r, col unit index N+c, reg unit index 2N + reg_index_in_sorted
            yield r
            yield N + c
            # reg index
            rid = region[r][c]
            # Map rid to unit index in region units
            # regions appended in sorted(reg_cells.keys()) order
            regpos = reg_order_index[rid]
            yield 2 * N + regpos

        # Precompute region order index
        reg_ids_sorted = sorted(reg_cells.keys())
        reg_order_index = {rid: i for i, rid in enumerate(reg_ids_sorted)}

        # Hidden singles in a unit: if a digit can go in only one place -> place it.
        def hidden_single_in_unit(ui):
            unit = units[ui]
            # count positions for each digit
            pos_for_digit = [None] * (N + 1)
            count = [0] * (N + 1)
            for (r, c) in unit:
                if grid[r][c] is None:
                    m = cand[r][c]
                    # iterate bits
                    mm = m
                    while mm:
                        lsb = mm & -mm
                        d = (lsb.bit_length() - 1) + 1
                        count[d] += 1
                        pos_for_digit[d] = (r, c) if count[d] == 1 else pos_for_digit[d]
                        mm ^= lsb
            for d in range(1, N + 1):
                if count[d] == 1:
                    r, c = pos_for_digit[d]
                    if not place_value(r, c, d, trail):
                        return False
                    # enqueue affected
                    push_cell(r, c)
                    for aui in affected_units_of_cell(r, c):
                        push_unit(aui)
            return True

        # Naked singles: candidate mask with one bit.
        def naked_single_cell(r, c):
            m = cand[r][c]
            if m == 0:
                return False
            if bits_count(m) == 1:
                d = singleton_digit(m)
                if not place_value(r, c, d, trail):
                    return False
                # enqueue affected
                push_cell(r, c)
                for aui in affected_units_of_cell(r, c):
                    push_unit(aui)
            return True

        # Locked candidates (pointing/claiming) generalized for irregular regions:
        # If in a region, all candidates for digit d lie in one row (or col), remove d from that row (or col) outside the region.
        # Also if in a row, all candidates for digit d lie in one region, remove d from that region outside the row.
        def locked_candidates(ui):
            unit = units[ui]
            # Determine unit type by index range
            if ui < N:
                utype = "row"
            elif ui < 2 * N:
                utype = "col"
            else:
                utype = "reg"

            # Build candidate locations per digit in this unit
            locs = [[] for _ in range(N + 1)]
            for (r, c) in unit:
                if grid[r][c] is None:
                    m = cand[r][c]
                    mm = m
                    while mm:
                        lsb = mm & -mm
                        d = (lsb.bit_length() - 1) + 1
                        locs[d].append((r, c))
                        mm ^= lsb

            changed = False
            for d in range(1, N + 1):
                L = locs[d]
                if len(L) <= 1:
                    continue
                if utype == "reg":
                    # pointing: all in one row or one col
                    rows_set = {r for r, _ in L}
                    cols_set = {c for _, c in L}
                    rid = region[L[0][0]][L[0][1]]
                    if len(rows_set) == 1:
                        rr = next(iter(rows_set))
                        # eliminate from row rr outside this region
                        for cc in range(N):
                            if region[rr][cc] != rid and grid[rr][cc] is None and (cand[rr][cc] & bit(d)):
                                old = cand[rr][cc]
                                new = old & ~bit(d)
                                trail.append(("cand", rr, cc, old))
                                cand[rr][cc] = new
                                if new == 0:
                                    return False
                                push_cell(rr, cc)
                                push_unit(rr)  # row
                                changed = True
                    if len(cols_set) == 1:
                        cc = next(iter(cols_set))
                        for rr in range(N):
                            if region[rr][cc] != rid and grid[rr][cc] is None and (cand[rr][cc] & bit(d)):
                                old = cand[rr][cc]
                                new = old & ~bit(d)
                                trail.append(("cand", rr, cc, old))
                                cand[rr][cc] = new
                                if new == 0:
                                    return False
                                push_cell(rr, cc)
                                push_unit(N + cc)  # col
                                changed = True
                elif utype == "row":
                    # claiming: candidates in row all in one region
                    regset = {region[r][c] for (r, c) in L}
                    if len(regset) == 1:
                        rid = next(iter(regset))
                        r = unit[0][0]
                        # eliminate from region rid outside this row
                        for (rr, cc) in regs[rid]:
                            if rr != r and grid[rr][cc] is None and (cand[rr][cc] & bit(d)):
                                old = cand[rr][cc]
                                new = old & ~bit(d)
                                trail.append(("cand", rr, cc, old))
                                cand[rr][cc] = new
                                if new == 0:
                                    return False
                                push_cell(rr, cc)
                                push_unit(2 * N + reg_order_index[rid])
                                changed = True
                else:  # col
                    regset = {region[r][c] for (r, c) in L}
                    if len(regset) == 1:
                        rid = next(iter(regset))
                        c = unit[0][1]
                        for (rr, cc) in regs[rid]:
                            if cc != c and grid[rr][cc] is None and (cand[rr][cc] & bit(d)):
                                old = cand[rr][cc]
                                new = old & ~bit(d)
                                trail.append(("cand", rr, cc, old))
                                cand[rr][cc] = new
                                if new == 0:
                                    return False
                                push_cell(rr, cc)
                                push_unit(2 * N + reg_order_index[rid])
                                changed = True
            return True

        # Naked subsets (pairs/triples/quads) in a unit: if k cells' candidates union has size k, remove those digits from others.
        def naked_subsets_in_unit(ui, max_k=4):
            unit = units[ui]
            # Collect candidate masks for unsolved cells
            cells = [(r, c) for (r, c) in unit if grid[r][c] is None]
            if len(cells) < 2:
                return True
            # Bucket by candidate mask (ignore large masks)
            buckets = defaultdict(list)
            for r, c in cells:
                m = cand[r][c]
                bc = bits_count(m)
                if 2 <= bc <= max_k:
                    buckets[m].append((r, c))

            # Consider masks and combinations using mask union logic:
            # Start with direct same-mask groups (fast), then limited combination search over small set.
            changed = False

            # Same-mask naked subsets (e.g., two cells both {1,3} in unit => remove 1,3 from others)
            for m, loc in buckets.items():
                k = bits_count(m)
                if len(loc) == k and 2 <= k <= max_k:
                    for r, c in cells:
                        if (r, c) not in loc and (cand[r][c] & m):
                            old = cand[r][c]
                            new = old & ~m
                            trail.append(("cand", r, c, old))
                            cand[r][c] = new
                            if new == 0:
                                return False
                            push_cell(r, c)
                            changed = True

            # Limited combination among distinct masks (only if needed)
            small_masks = [m for m in buckets.keys()]
            if len(small_masks) > 0 and len(small_masks) <= 24:  # cap for speed
                # For k=2..max_k
                for k in range(2, max_k + 1):
                    # iterative combine with pruning by union size
                    # represent each element as (mask, list of locations) but locations not needed for union
                    # We'll use indices; combinations are bounded by cap.
                    def rec(start, choose, unionm, picked):
                        nonlocal changed
                        if choose == 0:
                            if bits_count(unionm) == k:
                                # collect all cells whose cand is subset of unionm AND whose mask among picked masks
                                picked_cells = []
                                for mi in picked:
                                    msk = small_masks[mi]
                                    picked_cells.extend(buckets[msk])
                                # Unique cells
                                picked_set = set(picked_cells)
                                if len(picked_set) != k:
                                    return
                                # eliminate unionm from other cells
                                for r, c in cells:
                                    if (r, c) not in picked_set and (cand[r][c] & unionm):
                                        old = cand[r][c]
                                        new = old & ~unionm
                                        trail.append(("cand", r, c, old))
                                        cand[r][c] = new
                                        if new == 0:
                                            raise ValueError("contradiction")
                                        push_cell(r, c)
                                        changed = True
                            return
                        for i in range(start, len(small_masks) - choose + 1):
                            msk = small_masks[i]
                            newu = unionm | msk
                            if bits_count(newu) > k:
                                continue
                            picked.append(i)
                            rec(i + 1, choose - 1, newu, picked)
                            picked.pop()

                    try:
                        rec(0, k, 0, [])
                    except ValueError:
                        return False

            return True

        # Main queue processing
        while q:
            typ, x, y = q.popleft()
            if typ == "cell":
                r, c = x, y
                inq_cell[r][c] = False
                if grid[r][c] is None:
                    if not naked_single_cell(r, c):
                        return False
            else:
                ui = x
                inq_unit[ui] = False
                # Apply unit-based deductions
                if not hidden_single_in_unit(ui):
                    return False
                if not locked_candidates(ui):
                    return False
                if not naked_subsets_in_unit(ui, max_k=4):
                    return False

        # Final consistency quick check
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None and cand[r][c] == 0:
                    return False
        return True

    # Initial deduction
    trail0 = []
    if not deduce(trail0):
        rollback(trail0)
        rollback(init_trail)
        return "No Solution"

    # Search with MRV + least constraining value (LCV), with deduction after each guess
    def select_unassigned_cell():
        best = None
        best_count = 10**9
        best_deg = -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    m = cand[r][c]
                    bc = bits_count(m)
                    if bc < best_count:
                        best_count = bc
                        # degree heuristic: number of unfilled peers
                        deg = 0
                        for pr, pc in peers[(r, c)]:
                            if grid[pr][pc] is None:
                                deg += 1
                        best_deg = deg
                        best = (r, c)
                        if bc == 2 and deg >= best_deg:
                            pass
                    elif bc == best_count:
                        deg = 0
                        for pr, pc in peers[(r, c)]:
                            if grid[pr][pc] is None:
                                deg += 1
                        if deg > best_deg:
                            best_deg = deg
                            best = (r, c)
        return best

    def order_values_lcv(r, c):
        # value ordering by counting eliminations in peers
        m = cand[r][c]
        vals = list(bits_iter(m))
        if len(vals) <= 1:
            return vals
        scores = []
        for v in vals:
            bm = bit(v)
            elim = 0
            for pr, pc in peers[(r, c)]:
                if grid[pr][pc] is None and (cand[pr][pc] & bm):
                    elim += 1
            scores.append((elim, v))
        scores.sort()
        return [v for _, v in scores]

    def is_solved():
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    return False
        return True

    def search():
        if is_solved():
            return True
        rc = select_unassigned_cell()
        if rc is None:
            return True
        r, c = rc
        m = cand[r][c]
        if m == 0:
            return False
        for v in order_values_lcv(r, c):
            trail = []
            if not place_value(r, c, v, trail):
                rollback(trail)
                continue
            if deduce(trail):
                if search():
                    return True
            rollback(trail)
        return False

    if not search():
        rollback(trail0)
        rollback(init_trail)
        return "No Solution"

    # Return solved grid as Python literal 2D list
    return str([[grid[r][c] for c in range(N)] for r in range(N)])


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 3, None], [4, None, None, None, None], [None, 9, None, 6, None], [None, None, None, None, 5], [None, 7, None, None, None]]}

from collections import deque
from functools import lru_cache

# Solver for "Kuromasu"-like puzzle:
# - Some cells are black, clues are fixed white.
# - For each clue, the count equals number of visible white cells in its row/col (orthogonal), incl. itself,
#   stopping at black or border.
# - Black cells not orthogonally adjacent.
# - All white cells form one orthogonally connected component.

B, W, U = 1, 0, -1  # black, white, unknown


def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Precompute
    clues = {}
    clue_cells = set()
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not isinstance(v, int) or v <= 0:
                    return "No Solution"
                clues[(r, c)] = v
                clue_cells.add((r, c))

    # Initial assignment grid
    grid = [[U] * n for _ in range(n)]
    for (r, c) in clue_cells:
        grid[r][c] = W  # clues are always white

    # Helpers
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def inb(r, c):
        return 0 <= r < n and 0 <= c < n

    def iter_line_cells(r, c, dr, dc):
        rr, cc = r + dr, c + dc
        while inb(rr, cc):
            yield rr, cc
            rr += dr
            cc += dc

    # For each clue, the "maximum line" cells (until border), for faster access
    line_cache = {}
    for (r, c) in clues:
        line_cache[(r, c)] = {
            "up": list(iter_line_cells(r, c, -1, 0)),
            "down": list(iter_line_cells(r, c, 1, 0)),
            "left": list(iter_line_cells(r, c, 0, -1)),
            "right": list(iter_line_cells(r, c, 0, 1)),
        }

    # Fast neighbor list
    neigh = [[[] for _ in range(n)] for __ in range(n)]
    for r in range(n):
        for c in range(n):
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                if inb(rr, cc):
                    neigh[r][c].append((rr, cc))

    def clone_grid(g):
        return [row[:] for row in g]

    def set_cell(g, r, c, val, reasons, queue):
        cur = g[r][c]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        if (r, c) in clue_cells and val == B:
            return False
        g[r][c] = val
        reasons.append((r, c))
        queue.append((r, c))
        return True

    def enforce_black_adjacency(g, r, c, reasons, queue):
        # If (r,c) is black, orthogonal neighbors must be white
        if g[r][c] != B:
            return True
        for rr, cc in neigh[r][c]:
            if not set_cell(g, rr, cc, W, reasons, queue):
                return False
        return True

    def visible_count_and_unknowns(g, r, c):
        # Return (count_white_guaranteed, count_unknown_visible, list_unknown_cells, blocked_info)
        # For each direction, visibility proceeds until a black cell; unknowns and whites count,
        # blacks stop (not counted). Guaranteed includes the clue itself (white).
        assert g[r][c] == W
        guaranteed = 1
        unknowns = 0
        unknown_cells = []
        for key, cells in line_cache[(r, c)].items():
            for rr, cc in cells:
                if g[rr][cc] == B:
                    break
                if g[rr][cc] == W:
                    guaranteed += 1
                else:
                    unknowns += 1
                    unknown_cells.append((rr, cc))
        return guaranteed, unknowns, unknown_cells

    def min_max_visible(g, r, c):
        # min = guaranteed whites seen before black/border, treating unknown as black (stop? no, unknown not stop)
        # Actually unknown doesn't stop; it could be black or white.
        # For min, set unknown to black as early as possible: but any unknown could be black and stop, reducing count.
        # Yet black might not be allowed (adjacent etc.), but here compute loose bounds:
        # min_visible: if immediately next cell in a direction is black, that direction contributes 0.
        # With unknowns, the min is 1 + sum over directions of minimal possible visible in that ray.
        # The minimal possible for a ray is:
        # - 0 if first cell is unknown or black
        # - k if first k are forced white until a forced black; if none forced black, could place black at first unknown after forced whites.
        # This is a useful (safe) bound.
        minv = 1
        maxv = 1
        for key, cells in line_cache[(r, c)].items():
            # max: all non-black are white until first black; unknowns treated white
            for rr, cc in cells:
                if g[rr][cc] == B:
                    break
                maxv += 1
            # min:
            add = 0
            for rr, cc in cells:
                if g[rr][cc] == B:
                    break
                if g[rr][cc] == W:
                    add += 1
                    continue
                # unknown: could be black, so stop before counting it
                break
            minv += add
        return minv, maxv

    def clue_quick_impossible(g):
        # Check all clues against bounds
        for (r, c), v in clues.items():
            if g[r][c] == B:
                return True
            if g[r][c] == U:
                # should not happen (clue forced white), but just in case
                return True
            mn, mx = min_max_visible(g, r, c)
            if v < mn or v > mx:
                return True
        return False

    def apply_clue_local_forcing(g, r, c, reasons, queue):
        # Apply forcing rules for a single clue:
        # 1) If current guaranteed whites already exceed clue -> contradiction.
        # 2) If guaranteed + unknowns < clue -> contradiction.
        # 3) If guaranteed == clue -> all unknown visible cells must be black OR blocked by earlier blacks? Actually if visible,
        #    and no black currently stops them, then to keep count, each visible unknown must become black (as earliest blockers).
        #    But turning a visible cell black will stop further cells behind it from being visible; those behind might be unknown too.
        #    Our unknown_visible list includes all unknowns until first existing black; making one black reduces visibility of behind cells.
        #    Human-like rule:
        #      - If guaranteed == clue: the first unknown cell in each ray (if any) must be black (to block further visibility),
        #        and any unknowns before that (none) are irrelevant.
        #      - Also any unknown visible before the first unknown? not possible.
        # 4) If max == clue -> all cells visible up to current first black/border must be white (unknowns in that region become white).
        v = clues[(r, c)]
        mn, mx = min_max_visible(g, r, c)
        if v < mn or v > mx:
            return False

        # Rule: if mx == v then all cells currently visible (until first black) are white
        if mx == v:
            for key, cells in line_cache[(r, c)].items():
                for rr, cc in cells:
                    if g[rr][cc] == B:
                        break
                    if not set_cell(g, rr, cc, W, reasons, queue):
                        return False

        # Rule: if mn == v then we must block at the first unknown in each direction (if exists),
        # because all forced whites are already needed, and any extra visibility would exceed v.
        if mn == v:
            for key, cells in line_cache[(r, c)].items():
                for rr, cc in cells:
                    if g[rr][cc] == B:
                        break
                    if g[rr][cc] == W:
                        continue
                    # first unknown on this ray must be black to stop further visibility
                    if not set_cell(g, rr, cc, B, reasons, queue):
                        return False
                    break

        # Additional rule: if v == 1 then all adjacent (orthogonally) cells must be black (immediately blocks all rays).
        if v == 1:
            for rr, cc in neigh[r][c]:
                if not set_cell(g, rr, cc, B, reasons, queue):
                    return False

        return True

    def propagate(g):
        # Queue-based propagation using:
        # - black adjacency rule
        # - clue local forcing for affected clues (same row/col)
        # - early impossibility checks
        reasons = []
        queue = deque()

        # Seed: all clue cells and any already assigned black for adjacency
        for (r, c) in clue_cells:
            queue.append((r, c))
        for r in range(n):
            for c in range(n):
                if g[r][c] == B:
                    queue.append((r, c))

        # To avoid reprocessing clues too much, we still process dynamically by dependency:
        # when a cell changes, it affects clues in its row and column.
        while queue:
            r, c = queue.popleft()

            if g[r][c] == B:
                if not enforce_black_adjacency(g, r, c, reasons, queue):
                    return None

            # Process any clue in same row/col that could have visibility changed by (r,c)
            # This is O(n) per event; grid sizes are moderate; strong pruning minimizes events.
            for cc in range(n):
                if (r, cc) in clues:
                    if not apply_clue_local_forcing(g, r, cc, reasons, queue):
                        return None
            for rr in range(n):
                if (rr, c) in clues:
                    if not apply_clue_local_forcing(g, rr, c, reasons, queue):
                        return None

            # Global quick check occasionally
            # (cheap enough due to small n)
            if clue_quick_impossible(g):
                return None

        return g

    def compute_final_visibility(g, r, c):
        cnt = 1
        for key, cells in line_cache[(r, c)].items():
            for rr, cc in cells:
                if g[rr][cc] == B:
                    break
                cnt += 1  # must be white if solved
        return cnt

    def whites_connected(g):
        # All white cells must be connected; unknown treated as white? For partial, we need feasibility:
        # - if there are multiple forced-white components disconnected by forced-black, still could be connected via unknowns.
        # We'll check a necessary condition:
        #   All forced-white cells must be connected in graph where non-black cells (white or unknown) are passable.
        forced = [(r, c) for r in range(n) for c in range(n) if g[r][c] == W]
        if not forced:
            return True
        start = forced[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            r, c = dq.popleft()
            for rr, cc in neigh[r][c]:
                if (rr, cc) in seen:
                    continue
                if g[rr][cc] != B:  # passable if not forced black
                    seen.add((rr, cc))
                    dq.append((rr, cc))
        return all(cell in seen for cell in forced)

    def whites_connected_final(g):
        whites = [(r, c) for r in range(n) for c in range(n) if g[r][c] == W]
        if not whites:
            return False
        start = whites[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            r, c = dq.popleft()
            for rr, cc in neigh[r][c]:
                if (rr, cc) in seen:
                    continue
                if g[rr][cc] == W:
                    seen.add((rr, cc))
                    dq.append((rr, cc))
        return len(seen) == len(whites)

    def no_black_adjacent(g):
        for r in range(n):
            for c in range(n):
                if g[r][c] == B:
                    for rr, cc in neigh[r][c]:
                        if g[rr][cc] == B:
                            return False
        return True

    def solved(g):
        # No unknowns
        for r in range(n):
            for c in range(n):
                if g[r][c] == U:
                    return False
        if not no_black_adjacent(g):
            return False
        if not whites_connected_final(g):
            return False
        # Check all clues exact
        for (r, c), v in clues.items():
            if compute_final_visibility(g, r, c) != v:
                return False
        return True

    def pick_branch_cell(g):
        # Choose a highly constrained unknown:
        # Prefer cells adjacent to black constraints or lying on clue sightlines, especially first unknown in a ray.
        best = None
        best_score = -1

        # Precompute for each unknown: how many clues see it (until forced black)
        # Also adjacency to black.
        for r in range(n):
            for c in range(n):
                if g[r][c] != U:
                    continue
                score = 0
                # adjacency to black increases constraint
                for rr, cc in neigh[r][c]:
                    if g[rr][cc] == B:
                        score += 5
                # clue visibility involvement
                # scan row and col for clues with no forced black between (coarse but ok)
                for cc in range(n):
                    if (r, cc) in clues and cc != c:
                        # if in same row, check if c is between with no forced black blocking
                        step = 1 if cc < c else -1
                        blocked = False
                        for x in range(cc + step, c, step):
                            if g[r][x] == B:
                                blocked = True
                                break
                        if not blocked:
                            score += 2
                for rr in range(n):
                    if (rr, c) in clues and rr != r:
                        step = 1 if rr < r else -1
                        blocked = False
                        for x in range(rr + step, r, step):
                            if g[x][c] == B:
                                blocked = True
                                break
                        if not blocked:
                            score += 2

                if score > best_score:
                    best_score = score
                    best = (r, c)

        return best

    def state_key(g):
        return tuple(tuple(row) for row in g)

    @lru_cache(maxsize=None)
    def dfs_cached(key):
        g = [list(row) for row in key]
        # Basic feasibility
        if clue_quick_impossible(g):
            return None
        if not whites_connected(g):
            return None

        g2 = propagate(clone_grid(g))
        if g2 is None:
            return None
        if not whites_connected(g2):
            return None
        if solved(g2):
            return g2

        cell = pick_branch_cell(g2)
        if cell is None:
            return None
        r, c = cell

        # Branch ordering: try white first to keep connectivity, unless black strongly suggested by adjacency/clue.
        # If any neighbor is black, this cell cannot be black-adjacent? It can be white; black would violate.
        # So prefer white in that case.
        prefer = [W, B]
        if any(g2[rr][cc] == B for rr, cc in neigh[r][c]):
            prefer = [W, B]

        for val in prefer:
            g3 = clone_grid(g2)
            reasons = []
            q = deque()
            if not set_cell(g3, r, c, val, reasons, q):
                continue
            # Immediate enforce if black
            ok = True
            while q and ok:
                rr, cc = q.popleft()
                if g3[rr][cc] == B:
                    ok = enforce_black_adjacency(g3, rr, cc, reasons, q)
            if not ok:
                continue
            if clue_quick_impossible(g3):
                continue
            if not whites_connected(g3):
                continue
            res = dfs_cached(state_key(g3))
            if res is not None:
                return res
        return None

    # Initial propagation
    g0 = propagate(clone_grid(grid))
    if g0 is None:
        return "No Solution"

    res = dfs_cached(state_key(g0))
    if res is None:
        return "No Solution"

    # Build answer grid: keep clue ints, mark blacks 'B', other whites as None
    out = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if (r, c) in clues:
                out[r][c] = clues[(r, c)]
            else:
                out[r][c] = 'B' if res[r][c] == B else None

    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 0, 1, 1], [2, 2, 2, 2, 1, 1], [2, 3, 3, 2, 1, 1], [2, 3, 3, 2, 4, 4], [5, 5, 6, 6, 6, 7], [5, 5, 6, 6, 7, 7]], 'data': [[1, None, None, None, 2, None], [None, None, None, None, None, None], [None, 0, None, None, None, None], [None, None, None, None, 0, None], [1, None, 1, None, None, 1], [None, None, None, None, None, None]]}
from collections import defaultdict, deque
from itertools import combinations

# Solver for the puzzle defined by:
# 1) Each region with a clue k has exactly k black cells.
# 2) Black cells cannot touch orthogonally.
# 3) Any maximal straight white segment in a row/col cannot pass through >2 regions.
# 4) All white cells are orthogonally connected.
#
# Representation:
# grid state values: -1 unknown, 0 white, 1 black


def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0]) if n else 0
    if n == 0 or m == 0:
        return []

    # --- Precompute regions and clues ---
    reg_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            reg_cells[region[r][c]].append((r, c))

    reg_clue = {}
    for r in range(n):
        for c in range(m):
            v = data[r][c]
            if v is not None:
                rid = region[r][c]
                if rid in reg_clue and reg_clue[rid] != v:
                    return "No Solution"
                reg_clue[rid] = v

    # Neighbors
    def neigh4(rc):
        r, c = rc
        if r > 0:
            yield (r - 1, c)
        if r + 1 < n:
            yield (r + 1, c)
        if c > 0:
            yield (r, c - 1)
        if c + 1 < m:
            yield (r, c + 1)

    # --- Precompute row/col region-runs segments (maximal contiguous cells with same region in a row/col) ---
    # Constraint 3: any maximal straight white segment cannot pass through >2 regions.
    # For a given row, any contiguous block of white cells: count distinct region runs intersected in that block <= 2.
    # We enforce locally by detecting forced blacks that must break potential 3-run stretches, and globally by checking violations.
    #
    # We'll create row_runs[r]: list of runs in that row as (c0,c1,rid) with c1 exclusive
    # and col_runs[c]: list of runs in that col as (r0,r1,rid) with r1 exclusive
    row_runs = []
    for r in range(n):
        runs = []
        c = 0
        while c < m:
            rid = region[r][c]
            c0 = c
            while c < m and region[r][c] == rid:
                c += 1
            runs.append((c0, c, rid))
        row_runs.append(runs)

    col_runs = []
    for c in range(m):
        runs = []
        r = 0
        while r < n:
            rid = region[r][c]
            r0 = r
            while r < n and region[r][c] == rid:
                r += 1
            runs.append((r0, r, rid))
        col_runs.append(runs)

    # --- Helper: map each cell to its run index for row/col ---
    row_run_idx = [[None] * m for _ in range(n)]
    for r in range(n):
        for idx, (c0, c1, _) in enumerate(row_runs[r]):
            for c in range(c0, c1):
                row_run_idx[r][c] = idx
    col_run_idx = [[None] * m for _ in range(n)]
    for c in range(m):
        for idx, (r0, r1, _) in enumerate(col_runs[c]):
            for r in range(r0, r1):
                col_run_idx[r][c] = idx

    # --- Region pattern precomputation for faster propagation ---
    # For each region, list all placements of black cells of size k (k from clue) that satisfy:
    # - no orthogonal adjacency inside region (since black adjacency forbidden globally)
    # We'll use it as a domain in a CSP-style propagation.
    reg_patterns = {}
    for rid, cells in reg_cells.items():
        if rid not in reg_clue:
            continue
        k = reg_clue[rid]
        if k < 0 or k > len(cells):
            return "No Solution"
        # Quick adjacency list inside region
        cell_set = set(cells)
        adj = {cell: [] for cell in cells}
        for cell in cells:
            for nb in neigh4(cell):
                if nb in cell_set:
                    adj[cell].append(nb)

        # Generate all k-subsets with no internal adjacency.
        # Use incremental build with pruning.
        patterns = []
        if k == 0:
            patterns = [frozenset()]
        else:
            # order cells by degree for pruning
            ordered = sorted(cells, key=lambda x: len(adj[x]), reverse=True)

            def backtrack(start, chosen, forbidden):
                if len(chosen) == k:
                    patterns.append(frozenset(chosen))
                    return
                # Remaining capacity
                remaining_needed = k - len(chosen)
                if start >= len(ordered):
                    return
                # Upper bound pruning
                available = 0
                for i in range(start, len(ordered)):
                    if ordered[i] not in forbidden:
                        available += 1
                if available < remaining_needed:
                    return
                for i in range(start, len(ordered)):
                    cell = ordered[i]
                    if cell in forbidden:
                        continue
                    chosen.append(cell)
                    new_forb = set(forbidden)
                    new_forb.add(cell)
                    for nb in adj[cell]:
                        new_forb.add(nb)
                    backtrack(i + 1, chosen, new_forb)
                    chosen.pop()

            backtrack(0, [], set())

        reg_patterns[rid] = patterns
        if not patterns:
            return "No Solution"

    # --- State and bookkeeping ---
    UNKNOWN, WHITE, BLACK = -1, 0, 1
    state = [[UNKNOWN] * m for _ in range(n)]

    # Fast counts per region
    reg_black = defaultdict(int)
    reg_unknown = defaultdict(int)
    for rid, cells in reg_cells.items():
        reg_unknown[rid] = len(cells)

    # Track pattern domains dynamically: allowed pattern indices for each constrained region
    reg_dom = {}
    for rid, patterns in reg_patterns.items():
        reg_dom[rid] = list(range(len(patterns)))

    # --- Assignment with trail (for backtracking) ---
    trail = []  # entries: (r,c,prev), plus special markers for other structures
    dom_trail = []  # (rid, prev_dom_list)

    def assign_cell(r, c, val):
        """Assign a cell; return False if conflict."""
        cur = state[r][c]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        # record
        trail.append((r, c, cur))
        state[r][c] = val
        rid = region[r][c]
        # update counts
        if cur == UNKNOWN:
            reg_unknown[rid] -= 1
        if val == BLACK:
            reg_black[rid] += 1
        # adjacency rule: if black, neighbors must be white
        if val == BLACK:
            for nr, nc in neigh4((r, c)):
                if not assign_cell(nr, nc, WHITE):
                    return False
        return True

    def undo(to_len, dom_to_len):
        while len(trail) > to_len:
            r, c, prev = trail.pop()
            cur = state[r][c]
            if cur == prev:
                continue
            rid = region[r][c]
            # revert counts
            if prev == UNKNOWN:
                reg_unknown[rid] += 1
            if cur == BLACK:
                reg_black[rid] -= 1
            state[r][c] = prev
        while len(dom_trail) > dom_to_len:
            rid, prev_dom = dom_trail.pop()
            reg_dom[rid] = prev_dom

    # --- Region clue propagation (human-like): exact counts + pattern-domain filtering ---
    def filter_region_domain(rid):
        """Filter domain patterns against current assignments. Return False if empty."""
        if rid not in reg_dom:
            return True
        patterns = reg_patterns[rid]
        dom = reg_dom[rid]
        if not dom:
            return False

        # Save previous
        prev = dom
        new_dom = []
        cells = reg_cells[rid]
        # Convert current assignment constraints
        must_black = set()
        must_white = set()
        for (r, c) in cells:
            if state[r][c] == BLACK:
                must_black.add((r, c))
            elif state[r][c] == WHITE:
                must_white.add((r, c))

        for idx in dom:
            p = patterns[idx]
            if not must_black.issubset(p):
                continue
            if p.intersection(must_white):
                continue
            new_dom.append(idx)

        if not new_dom:
            return False
        if len(new_dom) != len(prev):
            dom_trail.append((rid, prev))
            reg_dom[rid] = new_dom
        return True

    def propagate_region_forced(rid):
        """From region domain, force cells that are always black/always white."""
        if rid not in reg_dom:
            return True
        dom = reg_dom[rid]
        patterns = reg_patterns[rid]
        cells = reg_cells[rid]
        if not dom:
            return False
        # Determine intersection/union of black positions across all patterns
        # Efficient: count occurrences
        occ = defaultdict(int)
        for idx in dom:
            for cell in patterns[idx]:
                occ[cell] += 1
        total = len(dom)
        for cell in cells:
            r, c = cell
            if state[r][c] != UNKNOWN:
                continue
            cnt = occ.get(cell, 0)
            if cnt == total:
                if not assign_cell(r, c, BLACK):
                    return False
            elif cnt == 0:
                if not assign_cell(r, c, WHITE):
                    return False
        return True

    def propagate_region_counts_simple(rid):
        """Classic count propagation without patterns."""
        if rid not in reg_clue:
            return True
        k = reg_clue[rid]
        b = reg_black[rid]
        u = reg_unknown[rid]
        if b > k or b + u < k:
            return False
        if u == 0:
            return True
        if b == k:
            for r, c in reg_cells[rid]:
                if state[r][c] == UNKNOWN:
                    if not assign_cell(r, c, WHITE):
                        return False
        elif b + u == k:
            for r, c in reg_cells[rid]:
                if state[r][c] == UNKNOWN:
                    if not assign_cell(r, c, BLACK):
                        return False
        return True

    # --- Rule 3 propagation: prevent 3-region white segments ---
    def check_line_violation_row(r):
        """Check if any existing maximal white segment spans >2 region-runs."""
        c = 0
        while c < m:
            # find next non-black (white or unknown doesn't break white segment yet)
            # But actual white segment considers only definite WHITE.
            while c < m and state[r][c] != WHITE:
                c += 1
            if c >= m:
                break
            c0 = c
            run_ids = []
            last_run = None
            while c < m and state[r][c] == WHITE:
                idx = row_run_idx[r][c]
                if idx != last_run:
                    run_ids.append(idx)
                    last_run = idx
                    if len(run_ids) > 2:
                        return False
                c += 1
            # segment [c0,c)
        return True

    def check_line_violation_col(c):
        r = 0
        while r < n:
            while r < n and state[r][c] != WHITE:
                r += 1
            if r >= n:
                break
            run_ids = []
            last_run = None
            while r < n and state[r][c] == WHITE:
                idx = col_run_idx[r][c]
                if idx != last_run:
                    run_ids.append(idx)
                    last_run = idx
                    if len(run_ids) > 2:
                        return False
                r += 1
        return True

    def rule3_local_breaks():
        """
        Human-like deduction:
        If in a row/col there is a stretch of cells that, if all became white, would span 3 distinct region-runs,
        then at least one cell in the middle run(s) must be black to break it.
        We apply a safe, forced version:
          - If two boundary cells are already WHITE and they belong to three runs with the only possible break cell set
            constrained to a single cell -> force it BLACK.
        We'll implement for windows of three consecutive runs: A|B|C in the same row/col.
        If there is a contiguous interval covering end of A, all of B, start of C which is all forced WHITE except one unknown,
        force that unknown BLACK.
        """
        # Rows
        for r in range(n):
            runs = row_runs[r]
            for i in range(len(runs) - 2):
                a0, a1, _ = runs[i]
                b0, b1, _ = runs[i + 1]
                c0, c1, _ = runs[i + 2]
                # consider interval from some cell in A to some cell in C; forced only if edges are white contiguous through B.
                # We can only assert violation if there exists a fully WHITE path from A into C across B.
                # Strong forced case: if all cells in B are WHITE, and there is at least one WHITE in A adjacent to B
                # and one WHITE in C adjacent to B, then impossible unless a BLACK exists in B (contradiction). But B all WHITE means already bad.
                # Forced BLACK: if within [b0,b1) all but one are WHITE and the remaining is UNKNOWN, and there is WHITE at b0-1 and b1 (edges),
                # then that UNKNOWN must be BLACK.
                left_edge = b0 - 1
                right_edge = b1
                if left_edge < 0 or right_edge >= m:
                    continue
                if state[r][left_edge] != WHITE or state[r][right_edge] != WHITE:
                    continue
                # ensure the white segment can connect across B if B cells are non-black
                unknowns = []
                all_nonblack = True
                for c in range(b0, b1):
                    if state[r][c] == BLACK:
                        all_nonblack = False
                        break
                    if state[r][c] == UNKNOWN:
                        unknowns.append((r, c))
                if not all_nonblack:
                    continue
                if len(unknowns) == 0:
                    # would create a white segment spanning A,B,C already; contradiction check elsewhere
                    continue
                if len(unknowns) == 1:
                    rr, cc = unknowns[0]
                    if not assign_cell(rr, cc, BLACK):
                        return False
        # Cols
        for c in range(m):
            runs = col_runs[c]
            for i in range(len(runs) - 2):
                a0, a1, _ = runs[i]
                b0, b1, _ = runs[i + 1]
                c0, c1, _ = runs[i + 2]
                top_edge = b0 - 1
                bot_edge = b1
                if top_edge < 0 or bot_edge >= n:
                    continue
                if state[top_edge][c] != WHITE or state[bot_edge][c] != WHITE:
                    continue
                unknowns = []
                all_nonblack = True
                for r in range(b0, b1):
                    if state[r][c] == BLACK:
                        all_nonblack = False
                        break
                    if state[r][c] == UNKNOWN:
                        unknowns.append((r, c))
                if not all_nonblack:
                    continue
                if len(unknowns) == 1:
                    rr, cc = unknowns[0]
                    if not assign_cell(rr, cc, BLACK):
                        return False
        return True

    # --- White connectivity (rule 4) with pruning ---
    def connectivity_ok():
        # If no confirmed white yet, it's ok (can be connected later)
        whites = [(r, c) for r in range(n) for c in range(m) if state[r][c] == WHITE]
        if not whites:
            return True
        # BFS through cells that are not BLACK (WHITE or UNKNOWN) to ensure whites can still connect
        start = whites[0]
        q = deque([start])
        seen = {start}
        while q:
            cur = q.popleft()
            for nb in neigh4(cur):
                r, c = nb
                if state[r][c] != BLACK and nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        for w in whites:
            if w not in seen:
                return False
        return True

    # --- Global propagation loop ---
    def propagate():
        changed = True
        while changed:
            before_trail = len(trail)
            before_dom = len(dom_trail)

            # Region constraints
            for rid in reg_cells.keys():
                if not propagate_region_counts_simple(rid):
                    return False
                if rid in reg_dom:
                    if not filter_region_domain(rid):
                        return False
                    if not propagate_region_forced(rid):
                        return False
                    # After forcing, refilter once for consistency
                    if not filter_region_domain(rid):
                        return False

            # Rule 3 forced breaks
            if not rule3_local_breaks():
                return False

            # Quick violation checks for definite WHITE segments
            for r in range(n):
                if not check_line_violation_row(r):
                    return False
            for c in range(m):
                if not check_line_violation_col(c):
                    return False

            if not connectivity_ok():
                return False

            changed = (len(trail) != before_trail) or (len(dom_trail) != before_dom)
        return True

    # --- Heuristic choice: pick region with smallest domain / or cell with strong constraints ---
    def select_branch():
        # Prefer constrained regions with patterns remaining >1
        best = None
        best_size = 10**9
        for rid, dom in reg_dom.items():
            if len(dom) > 1 and len(dom) < best_size:
                best_size = len(dom)
                best = ("region", rid)
        if best is not None:
            return best
        # Else pick a cell in a clued region still unknown that has tight count
        best_cell = None
        best_score = -1
        for rid in reg_clue.keys():
            k = reg_clue[rid]
            b = reg_black[rid]
            u = reg_unknown[rid]
            if u == 0:
                continue
            # score higher if close to fixed
            score = (k - b == 0) + (b + u == k)
            if score > best_score:
                # find an unknown cell
                for (r, c) in reg_cells[rid]:
                    if state[r][c] == UNKNOWN:
                        best_cell = (r, c)
                        best_score = score
                        break
        if best_cell is not None:
            return ("cell", best_cell)
        # fallback: any unknown cell
        for r in range(n):
            for c in range(m):
                if state[r][c] == UNKNOWN:
                    return ("cell", (r, c))
        return None

    def is_complete():
        for r in range(n):
            for c in range(m):
                if state[r][c] == UNKNOWN:
                    return False
        # Final checks:
        for rid in reg_clue:
            if reg_black[rid] != reg_clue[rid]:
                return False
        for r in range(n):
            if not check_line_violation_row(r):
                return False
        for c in range(m):
            if not check_line_violation_col(c):
                return False
        # White must be connected through WHITE only (not unknown, but none unknown)
        whites = [(r, c) for r in range(n) for c in range(m) if state[r][c] == WHITE]
        if not whites:
            return False
        q = deque([whites[0]])
        seen = {whites[0]}
        while q:
            cur = q.popleft()
            for nb in neigh4(cur):
                r, c = nb
                if state[r][c] == WHITE and nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        return len(seen) == len(whites)

    # --- Search with propagation ---
    def dfs():
        if not propagate():
            return False
        if is_complete():
            return True

        choice = select_branch()
        if choice is None:
            return False

        tlen = len(trail)
        dlen = len(dom_trail)

        kind, payload = choice
        if kind == "region":
            rid = payload
            dom = reg_dom[rid]
            patterns = reg_patterns[rid]
            # Try patterns one by one with forward assignment on region cells
            # Heuristic: try pattern that sets more blacks first (they induce more whites via adjacency)
            order = sorted(dom, key=lambda idx: -len(patterns[idx]))
            for idx in order:
                undo(tlen, dlen)
                # Restrict domain to this pattern
                dom_trail.append((rid, reg_dom[rid]))
                reg_dom[rid] = [idx]
                pat = patterns[idx]
                ok = True
                # Assign cells in region accordingly
                for (r, c) in reg_cells[rid]:
                    desired = BLACK if (r, c) in pat else WHITE
                    if not assign_cell(r, c, desired):
                        ok = False
                        break
                if ok and dfs():
                    return True
            undo(tlen, dlen)
            return False
        else:
            (r, c) = payload
            # Value ordering: try BLACK first if allowed by region clue slack
            rid = region[r][c]
            tries = [BLACK, WHITE]
            # quick prune: if region clue is 0 -> WHITE first
            if rid in reg_clue and reg_clue[rid] == 0:
                tries = [WHITE, BLACK]
            for val in tries:
                undo(tlen, dlen)
                if assign_cell(r, c, val) and dfs():
                    return True
            undo(tlen, dlen)
            return False

    if not dfs():
        return "No Solution"

    # Build answer grid: 'B' for black, None for white
    ans = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('B' if state[r][c] == BLACK else None)
        ans.append(row)
    return ans


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, 'B', None, None, 'W', None, None], [None, None, None, 'W', 'B', None, None, None], [None, 'W', None, None, None, None, 'B', None], [None, 'B', None, None, None, None, 'B', None], ['W', 'W', None, None, None, None, 'W', 'B'], [None, 'B', None, None, None, None, 'W', None]], 'horizontal': {'(2, 1.5)': '=', '(4, 2.5)': '=', '(4, 5.5)': '=', '(6, 2.5)': '=', '(6, 3.5)': '='}, 'vertical': {'(2.5, 1)': 'x', '(1.5, 6)': 'x', '(4.5, 3)': 'x', '(4.5, 4)': 'x'}}

# Solver for Binary puzzle with extra adjacency constraints (=, x)
# Techniques:
# - Constraint propagation using:
#   (a) No-three-in-a-row rules (local)
#   (b) Row/col balance (global counts)
#   (c) Row/col uniqueness (classic Binairo rule)
#   (d) Equality/inequality edge constraints (graph propagation)
# - Backtracking with strong heuristics:
#   MRV cell choice + forward checking + incremental propagation
# No external libraries.

from collections import deque

B, W = 1, 0  # internal
CH = {B: "B", W: "W"}
INV = {B: W, W: B}

def solve(observation):
    grid0 = observation["data"]
    n = len(grid0)
    if n == 0 or any(len(r) != n for r in grid0):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"
    half = n // 2

    # Parse constraints
    heq = {}  # (r,c)-(r,c+1) : 0 same, 1 diff
    veq = {}  # (r,c)-(r+1,c)
    for k, v in observation.get("horizontal", {}).items():
        # key "(row, col+0.5)" with col+0.5 between adjacent columns
        s = k.strip()
        if not (s.startswith("(") and s.endswith(")")):
            return "No Solution"
        a, b = s[1:-1].split(",")
        r = int(float(a.strip()))
        mid = float(b.strip())
        c = int(mid - 0.5)
        if not (0 <= r < n and 0 <= c < n - 1):
            return "No Solution"
        heq[(r, c)] = 0 if v == "=" else 1
    for k, v in observation.get("vertical", {}).items():
        s = k.strip()
        if not (s.startswith("(") and s.endswith(")")):
            return "No Solution"
        a, b = s[1:-1].split(",")
        mid = float(a.strip())
        c = int(float(b.strip()))
        r = int(mid - 0.5)
        if not (0 <= r < n - 1 and 0 <= c < n):
            return "No Solution"
        veq[(r, c)] = 0 if v == "=" else 1

    # Domains: bitmask 1<<0 for W, 1<<1 for B
    FULL = 0b11
    dom = [[FULL for _ in range(n)] for __ in range(n)]
    grid = [[None for _ in range(n)] for __ in range(n)]
    for r in range(n):
        for c in range(n):
            v = grid0[r][c]
            if v is None:
                continue
            if v not in ("B", "W"):
                return "No Solution"
            val = B if v == "B" else W
            grid[r][c] = val
            dom[r][c] = 1 << val

    # Helpers
    def mask_vals(m):
        if m == 1:
            return (W,)
        if m == 2:
            return (B,)
        if m == 3:
            return (W, B)
        return ()

    def is_assigned(r, c):
        return dom[r][c] in (1, 2)

    def get_val(r, c):
        m = dom[r][c]
        if m == 1:
            return W
        if m == 2:
            return B
        return None

    def set_dom(r, c, m, q):
        # return False if contradiction
        if dom[r][c] == m:
            return True
        if dom[r][c] & m == 0:
            return False
        dom[r][c] = dom[r][c] & m
        if dom[r][c] == 0:
            return False
        q.append((r, c))
        return True

    # Precompute adjacency edges
    # Represent constraints as list of (r1,c1,r2,c2, parity) parity=0 same,1 diff
    edges = [[] for _ in range(n * n)]
    def idx(r, c): return r * n + c
    for (r, c), parity in heq.items():
        a = idx(r, c); b = idx(r, c + 1)
        edges[a].append((r, c + 1, parity))
        edges[b].append((r, c, parity))
    for (r, c), parity in veq.items():
        a = idx(r, c); b = idx(r + 1, c)
        edges[a].append((r + 1, c, parity))
        edges[b].append((r, c, parity))

    # Row/col tracking
    def row_counts(r):
        w = b = u = 0
        for c in range(n):
            v = get_val(r, c)
            if v is None:
                u += 1
            elif v == W:
                w += 1
            else:
                b += 1
        return w, b, u

    def col_counts(c):
        w = b = u = 0
        for r in range(n):
            v = get_val(r, c)
            if v is None:
                u += 1
            elif v == W:
                w += 1
            else:
                b += 1
        return w, b, u

    def row_signature(r):
        # tuple of 0/1 for assigned, None for unassigned
        return tuple(get_val(r, c) for c in range(n))

    def col_signature(c):
        return tuple(get_val(r, c) for r in range(n))

    # Uniqueness propagation:
    # If a row is complete, no other row can be identical.
    # If two rows have all assigned positions equal and differ only in two unassigned positions,
    # then those positions must be opposite (classic Binairo rule generalization).
    def propagate_uniqueness(q):
        # rows
        sigs = [row_signature(r) for r in range(n)]
        for r1 in range(n):
            s1 = sigs[r1]
            if None not in s1:
                for r2 in range(n):
                    if r2 == r1:
                        continue
                    s2 = sigs[r2]
                    if None not in s2 and s2 == s1:
                        return False
                    # if s2 has Nones, avoid becoming identical to complete row
                    if None in s2:
                        # if all assigned in r2 match s1, then remaining must not all match
                        mismatch = False
                        unknowns = []
                        for c in range(n):
                            v2 = s2[c]
                            if v2 is None:
                                unknowns.append(c)
                            elif v2 != s1[c]:
                                mismatch = True
                                break
                        if not mismatch and len(unknowns) == 2:
                            cA, cB = unknowns
                            # Force r2 at cA and cB to be opposite of s1 at least one position differs.
                            # With balance constraints this implies they must be opposite to s1 respectively:
                            # For binairo, when only 2 spots left and row must avoid equality with s1, they must be swapped,
                            # i.e., (s1[cA], s1[cB]) cannot both be matched -> only possibilities are the opposite pair.
                            # So enforce r2[cA]=INV[s1[cA]] and r2[cB]=INV[s1[cB]]
                            if not set_dom(r2, cA, 1 << INV[s1[cA]], q):
                                return False
                            if not set_dom(r2, cB, 1 << INV[s1[cB]], q):
                                return False

        # cols
        sigs = [col_signature(c) for c in range(n)]
        for c1 in range(n):
            s1 = sigs[c1]
            if None not in s1:
                for c2 in range(n):
                    if c2 == c1:
                        continue
                    s2 = sigs[c2]
                    if None not in s2 and s2 == s1:
                        return False
                    if None in s2:
                        mismatch = False
                        unknowns = []
                        for r in range(n):
                            v2 = s2[r]
                            if v2 is None:
                                unknowns.append(r)
                            elif v2 != s1[r]:
                                mismatch = True
                                break
                        if not mismatch and len(unknowns) == 2:
                            rA, rB = unknowns
                            if not set_dom(rA, c2, 1 << INV[s1[rA]], q):
                                return False
                            if not set_dom(rB, c2, 1 << INV[s1[rB]], q):
                                return False
        return True

    # No-three local propagation for a line (row or col)
    def apply_no_three_line(getcell, setcell, q):
        # pattern based
        for i in range(n):
            pass
        # We run scans for i=0..n-3: [a,b,c]
        for i in range(n - 2):
            a = getcell(i)
            b = getcell(i + 1)
            c = getcell(i + 2)
            # If a and b same assigned => c must be opposite
            if a is not None and b is not None and a == b:
                if not setcell(i + 2, 1 << INV[a], q):
                    return False
            # If b and c same assigned => a must be opposite
            if b is not None and c is not None and b == c:
                if not setcell(i, 1 << INV[b], q):
                    return False
            # If a and c same assigned => b must be opposite
            if a is not None and c is not None and a == c:
                if not setcell(i + 1, 1 << INV[a], q):
                    return False
        return True

    def apply_balance_row(r, q):
        w, b, u = row_counts(r)
        if w > half or b > half:
            return False
        if u == 0:
            return True
        if w == half:
            # rest must be B
            for c in range(n):
                if get_val(r, c) is None:
                    if not set_dom(r, c, 1 << B, q):
                        return False
        if b == half:
            for c in range(n):
                if get_val(r, c) is None:
                    if not set_dom(r, c, 1 << W, q):
                        return False
        return True

    def apply_balance_col(c, q):
        w, b, u = col_counts(c)
        if w > half or b > half:
            return False
        if u == 0:
            return True
        if w == half:
            for r in range(n):
                if get_val(r, c) is None:
                    if not set_dom(r, c, 1 << B, q):
                        return False
        if b == half:
            for r in range(n):
                if get_val(r, c) is None:
                    if not set_dom(r, c, 1 << W, q):
                        return False
        return True

    def apply_edge_constraints(r, c, q):
        v = get_val(r, c)
        m = dom[r][c]
        # For each edge, restrict neighbor
        for (nr, nc, parity) in edges[idx(r, c)]:
            nm = dom[nr][nc]
            # allowed pairs based on parity
            if parity == 0:
                # same: neighbor values must intersect with this domain
                if m != FULL:
                    if not set_dom(nr, nc, m, q):
                        return False
            else:
                # diff
                if m != FULL:
                    # if m is singleton, neighbor must be opposite
                    if m in (1, 2):
                        val = 0 if m == 1 else 1
                        if not set_dom(nr, nc, 1 << INV[val], q):
                            return False
                    else:
                        # if this cell could be both, cannot constrain neighbor
                        pass
            # Also when neighbor singleton can restrict current
            if nm in (1, 2) and m == FULL:
                nval = 0 if nm == 1 else 1
                if parity == 0:
                    if not set_dom(r, c, 1 << nval, q):
                        return False
                else:
                    if not set_dom(r, c, 1 << INV[nval], q):
                        return False
        return True

    def propagate(q):
        # queue holds changed cells for local propagation; but we also do periodic global checks
        while q:
            r, c = q.popleft()
            if dom[r][c] == 0:
                return False
            # edge constraints
            if not apply_edge_constraints(r, c, q):
                return False
            # row/col balance
            if not apply_balance_row(r, q):
                return False
            if not apply_balance_col(c, q):
                return False
            # no-three on row r and col c
            def r_get(i): return get_val(r, i)
            def r_set(i, m, q=q): return set_dom(r, i, m, q)
            def c_get(i): return get_val(i, c)
            def c_set(i, m, q=q): return set_dom(i, c, m, q)
            if not apply_no_three_line(r_get, r_set, q):
                return False
            if not apply_no_three_line(c_get, c_set, q):
                return False

        # After local exhaustion, run uniqueness + another balance/no-three sweep for all lines
        qq = deque()
        if not propagate_uniqueness(qq):
            return False
        if qq:
            if not propagate(qq):
                return False

        # Final sanity: no complete duplicate rows/cols; counts okay; no-three check fully
        # (cheap scan)
        seen_rows = set()
        for r in range(n):
            w, b, _ = row_counts(r)
            if w > half or b > half:
                return False
            sig = row_signature(r)
            if None not in sig:
                if sig in seen_rows:
                    return False
                seen_rows.add(sig)
                # verify no-three
                for i in range(n - 2):
                    a, b2, c2 = sig[i], sig[i + 1], sig[i + 2]
                    if a == b2 == c2:
                        return False
        seen_cols = set()
        for c in range(n):
            w, b, _ = col_counts(c)
            if w > half or b > half:
                return False
            sig = col_signature(c)
            if None not in sig:
                if sig in seen_cols:
                    return False
                seen_cols.add(sig)
                for i in range(n - 2):
                    a, b2, c2 = sig[i], sig[i + 1], sig[i + 2]
                    if a == b2 == c2:
                        return False
        return True

    # Initial propagation from givens
    initq = deque()
    for r in range(n):
        for c in range(n):
            if dom[r][c] in (1, 2):
                initq.append((r, c))
    if not propagate(initq):
        return "No Solution"

    def is_solved():
        for r in range(n):
            for c in range(n):
                if dom[r][c] == FULL:
                    return False
        # all assigned; ensure balance equals half
        for r in range(n):
            w, b, u = row_counts(r)
            if u != 0 or w != half or b != half:
                return False
        for c in range(n):
            w, b, u = col_counts(c)
            if u != 0 or w != half or b != half:
                return False
        return True

    def choose_cell():
        best = None
        best_deg = -1
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                if m == FULL:
                    # degree heuristic: number of constraints involved + line pressure
                    deg = len(edges[idx(r, c)])
                    rw, rb, ru = row_counts(r)
                    cw, cb, cu = col_counts(c)
                    deg += (half - abs(rw - rb)) + (half - abs(cw - cb))
                    # adjacency to assigned helps
                    for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                        rr, cc = r+dr, c+dc
                        if 0 <= rr < n and 0 <= cc < n and is_assigned(rr, cc):
                            deg += 2
                    if deg > best_deg:
                        best_deg = deg
                        best = (r, c)
        return best

    # Snapshot/restore via stack of changed cells for speed
    def dfs():
        if is_solved():
            return True
        cell = choose_cell()
        if cell is None:
            return False
        r, c = cell

        # try value ordering: prefer value that helps balance (fill missing)
        rw, rb, _ = row_counts(r)
        cw, cb, _ = col_counts(c)
        prefer = []
        # If row needs more W, try W first; same for col
        scoreW = (half - rw) + (half - cw)
        scoreB = (half - rb) + (half - cb)
        if scoreB > scoreW:
            prefer = [B, W]
        else:
            prefer = [W, B]

        original = dom[r][c]
        for val in prefer:
            # Save changes
            stack = []
            def set_dom_track(rr, cc, mm, q):
                old = dom[rr][cc]
                if old == mm:
                    return True
                if old & mm == 0:
                    return False
                newm = old & mm
                if newm == old:
                    return True
                dom[rr][cc] = newm
                stack.append((rr, cc, old))
                q.append((rr, cc))
                return True

            # Temporarily override set_dom within this branch by manual operations
            # We'll implement branch propagation using local queue and manual application of same rules
            # by copying code with set_dom_track.
            q = deque()
            ok = set_dom_track(r, c, 1 << val, q)
            if ok:
                # branch propagate
                while ok and q:
                    rr, cc = q.popleft()
                    # edge constraints
                    m = dom[rr][cc]
                    for (nr, nc, parity) in edges[idx(rr, cc)]:
                        nm = dom[nr][nc]
                        if parity == 0:
                            if m != FULL:
                                if not set_dom_track(nr, nc, m, q):
                                    ok = False
                                    break
                        else:
                            if m in (1, 2):
                                v0 = 0 if m == 1 else 1
                                if not set_dom_track(nr, nc, 1 << INV[v0], q):
                                    ok = False
                                    break
                        if nm in (1, 2) and m == FULL:
                            nval = 0 if nm == 1 else 1
                            if parity == 0:
                                if not set_dom_track(rr, cc, 1 << nval, q):
                                    ok = False
                                    break
                            else:
                                if not set_dom_track(rr, cc, 1 << INV[nval], q):
                                    ok = False
                                    break
                    if not ok:
                        break

                    # balance row/col
                    def bal_row(r0):
                        w, b, u = row_counts(r0)
                        if w > half or b > half:
                            return False
                        if w == half:
                            for c0 in range(n):
                                if get_val(r0, c0) is None:
                                    if not set_dom_track(r0, c0, 1 << B, q):
                                        return False
                        if b == half:
                            for c0 in range(n):
                                if get_val(r0, c0) is None:
                                    if not set_dom_track(r0, c0, 1 << W, q):
                                        return False
                        return True
                    def bal_col(c0):
                        w, b, u = col_counts(c0)
                        if w > half or b > half:
                            return False
                        if w == half:
                            for r0 in range(n):
                                if get_val(r0, c0) is None:
                                    if not set_dom_track(r0, c0, 1 << B, q):
                                        return False
                        if b == half:
                            for r0 in range(n):
                                if get_val(r0, c0) is None:
                                    if not set_dom_track(r0, c0, 1 << W, q):
                                        return False
                        return True
                    if not bal_row(rr) or not bal_col(cc):
                        ok = False
                        break

                    # no-three in row rr and col cc
                    def apply_no_three_row(r0):
                        for i in range(n - 2):
                            a = get_val(r0, i); b2 = get_val(r0, i+1); c2 = get_val(r0, i+2)
                            if a is not None and b2 is not None and a == b2:
                                if not set_dom_track(r0, i+2, 1 << INV[a], q):
                                    return False
                            if b2 is not None and c2 is not None and b2 == c2:
                                if not set_dom_track(r0, i, 1 << INV[b2], q):
                                    return False
                            if a is not None and c2 is not None and a == c2:
                                if not set_dom_track(r0, i+1, 1 << INV[a], q):
                                    return False
                        return True
                    def apply_no_three_col(c0):
                        for i in range(n - 2):
                            a = get_val(i, c0); b2 = get_val(i+1, c0); c2 = get_val(i+2, c0)
                            if a is not None and b2 is not None and a == b2:
                                if not set_dom_track(i+2, c0, 1 << INV[a], q):
                                    return False
                            if b2 is not None and c2 is not None and b2 == c2:
                                if not set_dom_track(i, c0, 1 << INV[b2], q):
                                    return False
                            if a is not None and c2 is not None and a == c2:
                                if not set_dom_track(i+1, c0, 1 << INV[a], q):
                                    return False
                        return True
                    if not apply_no_three_row(rr) or not apply_no_three_col(cc):
                        ok = False
                        break

                if ok:
                    qq = deque()
                    # uniqueness
                    # reuse global uniqueness but with set_dom_track
                    # implement compactly here
                    sigs = [row_signature(r0) for r0 in range(n)]
                    for r1 in range(n):
                        s1 = sigs[r1]
                        if None not in s1:
                            for r2 in range(n):
                                if r2 == r1:
                                    continue
                                s2 = sigs[r2]
                                if None not in s2 and s2 == s1:
                                    ok = False
                                    break
                                if None in s2:
                                    mismatch = False
                                    unknowns = []
                                    for c0 in range(n):
                                        v2 = s2[c0]
                                        if v2 is None:
                                            unknowns.append(c0)
                                        elif v2 != s1[c0]:
                                            mismatch = True
                                            break
                                    if not mismatch and len(unknowns) == 2:
                                        cA, cB = unknowns
                                        if not set_dom_track(r2, cA, 1 << INV[s1[cA]], qq):
                                            ok = False
                                            break
                                        if not set_dom_track(r2, cB, 1 << INV[s1[cB]], qq):
                                            ok = False
                                            break
                            if not ok:
                                break
                    if ok:
                        sigs = [col_signature(c0) for c0 in range(n)]
                        for c1 in range(n):
                            s1 = sigs[c1]
                            if None not in s1:
                                for c2 in range(n):
                                    if c2 == c1:
                                        continue
                                    s2 = sigs[c2]
                                    if None not in s2 and s2 == s1:
                                        ok = False
                                        break
                                    if None in s2:
                                        mismatch = False
                                        unknowns = []
                                        for r0 in range(n):
                                            v2 = s2[r0]
                                            if v2 is None:
                                                unknowns.append(r0)
                                            elif v2 != s1[r0]:
                                                mismatch = True
                                                break
                                        if not mismatch and len(unknowns) == 2:
                                            rA, rB = unknowns
                                            if not set_dom_track(rA, c2, 1 << INV[s1[rA]], qq):
                                                ok = False
                                                break
                                            if not set_dom_track(rB, c2, 1 << INV[s1[rB]], qq):
                                                ok = False
                                                break
                                if not ok:
                                    break
                    if ok and qq:
                        # propagate effects from uniqueness using the same branch propagation loop by pushing into q
                        q2 = deque(qq)
                        while ok and q2:
                            rr, cc = q2.popleft()
                            # edge constraints
                            m = dom[rr][cc]
                            for (nr, nc, parity) in edges[idx(rr, cc)]:
                                nm = dom[nr][nc]
                                if parity == 0:
                                    if m != FULL:
                                        if not set_dom_track(nr, nc, m, q2):
                                            ok = False
                                            break
                                else:
                                    if m in (1, 2):
                                        v0 = 0 if m == 1 else 1
                                        if not set_dom_track(nr, nc, 1 << INV[v0], q2):
                                            ok = False
                                            break
                                if nm in (1, 2) and m == FULL:
                                    nval = 0 if nm == 1 else 1
                                    if parity == 0:
                                        if not set_dom_track(rr, cc, 1 << nval, q2):
                                            ok = False
                                            break
                                    else:
                                        if not set_dom_track(rr, cc, 1 << INV[nval], q2):
                                            ok = False
                                            break
                            if not ok:
                                break
                            # balance
                            if not bal_row(rr) or not bal_col(cc):
                                ok = False
                                break
                            # no-three
                            if not apply_no_three_row(rr) or not apply_no_three_col(cc):
                                ok = False
                                break

                # final check via global propagate sanity quickly
                if ok:
                    # lightweight check duplicates/3 and count bounds
                    if not propagate(deque()):  # uses global sanity, no changes
                        ok = False

            if ok and dfs():
                return True

            # restore
            for rr, cc, old in reversed(stack):
                dom[rr][cc] = old

        dom[r][c] = original
        return False

    if not dfs():
        return "No Solution"

    out = [[CH[get_val(r, c)] for c in range(n)] for r in range(n)]
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, None, None, 'B3', 'B3', 'B2'], [None, None, 'W2', None, None, None], [None, 'W2', None, None, None, None], [None, None, None, None, None, 'W2'], ['B7', None, None, None, 'B2', None]]}
from collections import deque, defaultdict
import math
import sys

# Slitherlink-like loop on grid edges with "Masyu-length" clues:
# - Each clue is at a grid vertex (dot).
# - Loop is a single simple cycle along unit edges.
# - For Wk: must go straight through the vertex (degree=2 with opposite edges).
# - For Bk: must turn at the vertex (degree=2 with perpendicular edges).
# - For token ?k: k = sum of straight-run lengths in the two directions from the vertex.
#   At a straight vertex, the two directions are opposite; at a turn, they are perpendicular.
#   Straight-run length in a direction = number of consecutive unit edges in that direction
#   until the loop turns (or ends, but ends forbidden in cycle). On a cycle, it always turns
#   somewhere; thus lengths are well-defined.

DIRS = [(-1,0),(1,0),(0,-1),(0,1)]
DIR_IDX = {(-1,0):0,(1,0):1,(0,-1):2,(0,1):3}
OPP = {0:1,1:0,2:3,3:2}

def solve(observation):
    data = observation["data"]
    R = len(data)
    C = len(data[0]) if R else 0
    if R == 0 or C == 0:
        return "No Solution"

    # Edges between adjacent dots: horizontal (r,c)-(r,c+1) for c in [0..C-2], vertical (r,c)-(r+1,c) for r in [0..R-2]
    # We'll map each undirected unit edge to an index; state: 1=in loop, 0=out, -1=unknown.
    edge_index = {}
    edges = []  # (a,b) endpoints as (r,c)
    adj_edges = [[[] for _ in range(C)] for __ in range(R)]

    def add_edge(a, b):
        idx = len(edges)
        edges.append((a, b))
        edge_index[(a, b)] = idx
        edge_index[(b, a)] = idx
        ar, ac = a
        br, bc = b
        adj_edges[ar][ac].append(idx)
        adj_edges[br][bc].append(idx)

    for r in range(R):
        for c in range(C):
            if c + 1 < C:
                add_edge((r, c), (r, c + 1))
            if r + 1 < R:
                add_edge((r, c), (r + 1, c))

    E = len(edges)
    # Precompute per edge: endpoints, direction from each endpoint
    edge_end = edges
    edge_dir_from = [dict() for _ in range(E)]
    for i, (a, b) in enumerate(edges):
        ar, ac = a
        br, bc = b
        dr, dc = br - ar, bc - ac
        di = DIR_IDX[(dr, dc)]
        edge_dir_from[i][a] = di
        edge_dir_from[i][b] = OPP[di]

    # Parse clues
    clues = {}
    for r in range(R):
        for c in range(C):
            tok = data[r][c]
            if tok:
                t = tok[0].upper()
                k = int(tok[1:])
                clues[(r, c)] = (t, k)

    # Helper: degree constraints at each vertex: deg in {0,2} overall for a single cycle on subset vertices.
    # We'll enforce locally: deg <= 2 always; and if any incident edge in loop, deg must become 2 (no dangling).
    # Additionally, if a vertex is a clue, it must be visited: deg==2 and shape constrained.
    is_clue = [[False]*C for _ in range(R)]
    for (r,c) in clues:
        is_clue[r][c] = True

    # State arrays
    st = [-1] * E  # -1 unknown, 0 out, 1 in

    # For each vertex, track counts quickly
    inc = [[0]*C for _ in range(R)]
    out = [[0]*C for _ in range(R)]
    unk = [[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            unk[r][c] = len(adj_edges[r][c])

    # Union-Find for "in" edges to prevent premature small cycles; with incremental rebuild when needed.
    # We'll use a dynamic connectivity check only during branching via light-weight union rebuild from st.
    def uf_build():
        parent = {}
        rank = {}
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a,b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
            return True
        # init only vertices that have any in-edge
        active = set()
        for ei, val in enumerate(st):
            if val == 1:
                a,b = edge_end[ei]
                active.add(a); active.add(b)
        for v in active:
            parent[v] = v
            rank[v] = 0
        # union all in-edges
        for ei, val in enumerate(st):
            if val == 1:
                a,b = edge_end[ei]
                if a not in parent:
                    parent[a]=a; rank[a]=0
                if b not in parent:
                    parent[b]=b; rank[b]=0
                union(a,b)
        return parent, rank, find

    # Propagation queue of vertices and edges
    vq = deque()
    eq = deque()

    # Assignment with trail for backtracking
    trail = []

    def set_edge(ei, val):
        nonlocal st
        cur = st[ei]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        st[ei] = val
        trail.append(ei)
        a,b = edge_end[ei]
        for (r,c), endpoint in [(a,a),(b,b)]:
            if val == 1:
                inc[r][c] += 1
            else:
                out[r][c] += 1
            unk[r][c] -= 1
            vq.append((r,c))
        eq.append(ei)
        return True

    def undo(to_len):
        while len(trail) > to_len:
            ei = trail.pop()
            val = st[ei]
            a,b = edge_end[ei]
            for (r,c) in [a,b]:
                if val == 1:
                    inc[r][c] -= 1
                else:
                    out[r][c] -= 1
                unk[r][c] += 1
            st[ei] = -1

    # Vertex local constraints:
    # - deg_in <= 2
    # - if deg_in == 1 then must eventually become 2 => at least one unknown must be set to 1
    # - if deg_in == 2 then all other incident edges are 0
    # - if deg_in == 0 then either all 0 or can remain 0; if clue, must be 2 -> force.
    # - if deg_in + unk < 2 and clue or deg_in>0 => fail
    #
    # Additionally, clue shape:
    # W: must use opposite pair; B: must use perpendicular pair.
    #
    # We'll use pattern forcing for each clue vertex by enumerating feasible edge-pair patterns consistent with partial st.

    def incident_edges(r,c):
        return adj_edges[r][c]

    def edge_to_dir_at(ei, v):
        return edge_dir_from[ei][v]

    # Precompute for each vertex possible pairs of incident dirs (for deg==2)
    v_pairs = {}
    for r in range(R):
        for c in range(C):
            v = (r,c)
            dirs = []
            for ei in adj_edges[r][c]:
                a,b = edge_end[ei]
                dirs.append(edge_dir_from[ei][v])
            # build pairs by dir index (but need map dir->edge idx)
            dir_to_edge = {}
            for ei in adj_edges[r][c]:
                dir_to_edge[edge_dir_from[ei][v]] = ei
            pairs = []
            for d1 in dir_to_edge:
                for d2 in dir_to_edge:
                    if d1 < d2:
                        pairs.append((d1,d2, dir_to_edge[d1], dir_to_edge[d2]))
            v_pairs[v] = (dir_to_edge, pairs)

    def clue_allowed_pairs(v, typ):
        dir_to_edge, pairs = v_pairs[v]
        allowed = []
        for d1,d2,e1,e2 in pairs:
            if typ == 'W':
                # opposite
                if OPP[d1] == d2:
                    allowed.append((e1,e2,d1,d2))
            else:
                # turn
                if OPP[d1] != d2:
                    allowed.append((e1,e2,d1,d2))
        return allowed

    clue_allowed_cache = {}
    for v,(t,k) in clues.items():
        clue_allowed_cache[(v,t)] = clue_allowed_pairs(v,t)

    # Length constraint checking for a clue vertex given a chosen pair:
    # For direction d at vertex v, straight-run length is number of consecutive in-edges along d until a turn vertex is encountered.
    # This depends on unknown edges; we'll do bounds propagation:
    # - Compute min_len, max_len possible for a run along direction d given current partial st and degree/shape possibilities.
    # - Use these to filter clue pair options with k.
    #
    # We'll approximate runs using forced-straight implications:
    # The run continues through intermediate vertices only if those vertices are (or can be) straight in that path direction.
    # We'll compute conservative bounds:
    #   min_len: assume earliest possible turn consistent with constraints
    #   max_len: assume we keep going straight as long as not impossible
    #
    # This yields strong pruning yet safe.

    def vertex_must_be_straight_in_dir(v, incoming_dir):
        # If vertex already has 2 in-edges fixed, determine if straight and what dirs.
        r,c = v
        if inc[r][c] == 2:
            ins = []
            for ei in adj_edges[r][c]:
                if st[ei] == 1:
                    ins.append(edge_dir_from[ei][v])
            if len(ins) != 2:
                return False
            return OPP[ins[0]] == ins[1] and (ins[0] == incoming_dir or ins[1] == incoming_dir)
        # If vertex is a clue:
        if v in clues:
            t,_ = clues[v]
            if t == 'W':
                # must be straight, so it can be straight in any axis that exists
                return True
            else:
                return False
        # Otherwise could be straight or turn; not forced.
        return False

    def run_bounds_from(v, d):
        # returns (min_len, max_len) along direction d starting with the edge leaving v in dir d
        r,c = v
        dir_to_edge, _ = v_pairs[v]
        if d not in dir_to_edge:
            return (math.inf, -math.inf)
        first_e = dir_to_edge[d]
        if st[first_e] == 0:
            return (math.inf, -math.inf)  # impossible
        # Minimum length: if first edge unknown, could be out unless required by pair; we compute conditional assuming edge is in.
        # We'll treat bounds conditioned on that edge being in; caller ensures membership.
        min_len = 1
        max_len = 1

        # Step along grid vertices
        def step(pos, dd):
            pr, pc = pos
            dr, dc = DIRS[dd]
            return (pr + dr, pc + dc)

        cur = step(v, d)
        prev_dir = OPP[d]  # direction from cur back to v
        # For min: turn as early as possible; for max: go as long as possible
        # We'll walk until blocked.
        # For each intermediate vertex cur, continuing straight requires having (or being able to have) two in-edges on opposite dirs along prev_dir axis.
        # Turning means cur has in-edge coming from prev and some perpendicular out.
        while True:
            cr, cc = cur
            # if out of bounds: should not happen due to edge existence
            # Determine if continuation is possible at all:
            # If vertex already has deg constraints making it impossible to have in-edge from prev, then stop.
            dir_to_edge2, pairs2 = v_pairs[cur]
            if prev_dir not in dir_to_edge2:
                break
            in_e = dir_to_edge2[prev_dir]
            if st[in_e] == 0:
                break
            # For max: need possibility of being straight at cur along prev axis:
            straight_ok = False
            cont_dir = OPP[prev_dir]
            if cont_dir in dir_to_edge2:
                out_e = dir_to_edge2[cont_dir]
                if st[out_e] != 0:
                    # also degree feasibility:
                    if inc[cr][cc] <= 2 and inc[cr][cc] + unk[cr][cc] >= 2:
                        # if clue is black, can't be straight
                        if cur in clues and clues[cur][0] == 'B':
                            straight_ok = False
                        else:
                            straight_ok = True
            # For min: can we turn here? turning requires some perpendicular edge can be in (unknown or in) and not violating clue white.
            turn_ok = False
            if cur in clues and clues[cur][0] == 'W':
                turn_ok = False
            else:
                for pd in [0,1,2,3]:
                    if pd in (prev_dir, OPP[prev_dir]):
                        continue
                    if pd in dir_to_edge2 and st[dir_to_edge2[pd]] != 0:
                        turn_ok = True
                        break

            # If neither straight nor turn possible, this path is impossible.
            if not straight_ok and not turn_ok:
                return (math.inf, -math.inf)

            # Update min: if turn possible, can stop; else must go straight.
            if not turn_ok:
                min_len += 1
            # Update max: if straight possible, can extend; else must stop.
            if straight_ok:
                max_len += 1
            else:
                break

            # If we reached boundary where cont edge doesn't exist, stop.
            if not straight_ok:
                break
            # Advance
            cur = step(cur, OPP[prev_dir])
            prev_dir = prev_dir  # still coming from same axis but at new vertex it's from opposite
            # Actually when moving forward, the direction from new cur back is still prev_dir
            # Example: moving east: d=3, at next vertex prev_dir=2 (west) constant each step.
            # So prev_dir remains unchanged.

        return (min_len, max_len)

    def apply_vertex_basic(r,c):
        # degree feasibility
        if inc[r][c] > 2:
            return False
        # If clue or touched, must be able to reach degree 2
        if (is_clue[r][c] or inc[r][c] > 0) and inc[r][c] + unk[r][c] < 2:
            return False
        # If clue, must be degree 2 eventually
        if is_clue[r][c]:
            # If already 2, ok; else if only 2 possible => force remaining unknowns to in
            if inc[r][c] == 2:
                # force others out
                for ei in adj_edges[r][c]:
                    if st[ei] == -1:
                        if not set_edge(ei, 0):
                            return False
            elif inc[r][c] + unk[r][c] == 2:
                for ei in adj_edges[r][c]:
                    if st[ei] == -1:
                        if not set_edge(ei, 1):
                            return False
        else:
            # Non-clue: if degree 2 fixed, close it
            if inc[r][c] == 2:
                for ei in adj_edges[r][c]:
                    if st[ei] == -1:
                        if not set_edge(ei, 0):
                            return False
            # If one in and only one unknown left, must set it in
            if inc[r][c] == 1 and unk[r][c] == 1:
                for ei in adj_edges[r][c]:
                    if st[ei] == -1:
                        if not set_edge(ei, 1):
                            return False
            # If zero in and unk == 1, must set that edge out (avoid dangling single edge later impossible)
            if inc[r][c] == 0 and unk[r][c] == 1:
                for ei in adj_edges[r][c]:
                    if st[ei] == -1:
                        if not set_edge(ei, 0):
                            return False
        return True

    def apply_clue_constraints(v):
        if v not in clues:
            return True
        t,k = clues[v]
        r,c = v
        # Vertex must be degree 2; enforce via allowed pair options.
        options = []
        for e1,e2,d1,d2 in clue_allowed_cache[(v,t)]:
            # both edges must exist
            if st[e1] == 0 or st[e2] == 0:
                continue
            # if any other incident edge already in, must be one of these
            ok = True
            for ei in adj_edges[r][c]:
                if st[ei] == 1 and ei not in (e1,e2):
                    ok = False
                    break
            if not ok:
                continue
            # degree feasibility with current counts:
            # ensure we can set e1,e2 to 1 and others to 0
            need_in = 0
            if st[e1] == -1: need_in += 1
            if st[e2] == -1: need_in += 1
            if inc[r][c] + need_in > 2:
                continue
            if inc[r][c] + unk[r][c] < 2:
                continue
            # length bounds
            # compute bounds for each direction (d1,d2) but ensure each edge is considered "in"
            b1 = run_bounds_from(v, d1)
            b2 = run_bounds_from(v, d2)
            if b1[0] == math.inf or b2[0] == math.inf:
                continue
            if b1[0] + b2[0] > k:
                continue
            if b1[1] + b2[1] < k:
                continue
            options.append((e1,e2,d1,d2,b1,b2))
        if not options:
            return False

        # If only one option, force it.
        if len(options) == 1:
            e1,e2,_,_,_,_ = options[0]
            if not set_edge(e1, 1): return False
            if not set_edge(e2, 1): return False
            for ei in adj_edges[r][c]:
                if ei != e1 and ei != e2:
                    if not set_edge(ei, 0): return False
            return True

        # If all options share an edge-inclusion, enforce it; and if an edge never appears, forbid it.
        appear = {ei:0 for ei in adj_edges[r][c]}
        for e1,e2,_,_,_,_ in options:
            appear[e1] += 1
            appear[e2] += 1
        total = len(options)
        for ei in adj_edges[r][c]:
            if appear[ei] == 0:
                if st[ei] == -1:
                    if not set_edge(ei, 0): return False
            elif appear[ei] == total:
                if st[ei] == -1:
                    if not set_edge(ei, 1): return False

        # If currently two in-edges already fixed, validate shape and length exactness if possible
        if inc[r][c] == 2:
            ins = [ei for ei in adj_edges[r][c] if st[ei] == 1]
            if len(ins) != 2:
                return False
            # check that this pair is among options; if so, and if runs are fully determined, ensure sum==k
            found = False
            for e1,e2,_,_,b1,b2 in options:
                if set(ins) == set((e1,e2)):
                    found = True
                    # If both bounds collapsed to exact, enforce.
                    # We can also prune if exact sum cannot be k already (handled above).
                    if b1[0] == b1[1] and b2[0] == b2[1]:
                        if b1[0] + b2[0] != k:
                            return False
                    break
            if not found:
                return False
        return True

    def propagate():
        # seed all clue vertices once
        for v in clues:
            vq.append(v)
        while vq or eq:
            while vq:
                r,c = vq.popleft()
                if not apply_vertex_basic(r,c):
                    return False
                if (r,c) in clues:
                    if not apply_clue_constraints((r,c)):
                        return False
            # Edge-based propagation: prevent premature small cycles when all degrees 2 in a component and it doesn't include all clues.
            # We'll do a cheap check only when an edge is set in.
            changed = False
            while eq:
                ei = eq.popleft()
                if st[ei] != 1:
                    continue
                changed = True
            if changed:
                # If any closed cycle formed while there are still required clue vertices not connected -> fail.
                # Detect cycles by finding connected components and counting edges/vertices degrees.
                parent, rank, find = uf_build()
                comp_verts = defaultdict(set)
                comp_edges = defaultdict(int)
                comp_deg_ok = defaultdict(bool)
                # collect vertices involved in in-edges
                for ei2, val in enumerate(st):
                    if val == 1:
                        a,b = edge_end[ei2]
                        ra = find(a)
                        comp_edges[ra] += 1
                        comp_verts[ra].add(a); comp_verts[ra].add(b)
                # identify if a component is a closed cycle: all vertices in it have degree 2
                for root, verts in comp_verts.items():
                    all2 = True
                    for (vr,vc) in verts:
                        if inc[vr][vc] != 2:
                            all2 = False
                            break
                    if all2:
                        # if there exist any clue vertex not in this component but still potentially needs to be connected, then premature.
                        # since final must be single loop through all clues, any closed cycle not containing all clues is invalid.
                        # If there are no other in-edges elsewhere yet, still invalid if not all clues in it and some clue unresolved.
                        contains_all_clues = True
                        for cv in clues:
                            if cv not in verts:
                                contains_all_clues = False
                                break
                        if not contains_all_clues:
                            return False
        return True

    # Choose branching edge: prefer edges adjacent to clues or vertices with tight degree.
    def pick_edge():
        best = None
        best_score = -1
        for ei, val in enumerate(st):
            if val != -1:
                continue
            a,b = edge_end[ei]
            score = 0
            for v in (a,b):
                r,c = v
                if is_clue[r][c]:
                    score += 50
                # tighter degrees
                score += (2-inc[r][c]) * 2
                score += (3-unk[r][c])
            if score > best_score:
                best_score = score
                best = ei
        return best

    def all_clues_satisfied_and_single_loop():
        # all clues deg==2 and constraints satisfied by propagation already.
        for (r,c) in clues:
            if inc[r][c] != 2:
                return False
        # all used vertices have degree 2
        used = []
        for r in range(R):
            for c in range(C):
                if inc[r][c] > 0:
                    if inc[r][c] != 2:
                        return False
                    used.append((r,c))
        if not used:
            return False
        # single component
        parent, rank, find = uf_build()
        roots = set()
        for v in used:
            if v in parent:
                roots.add(find(v))
        if len(roots) != 1:
            return False
        return True

    def extract_loop():
        # build adjacency of in-edges to traverse
        nbrs = defaultdict(list)
        for ei, val in enumerate(st):
            if val == 1:
                a,b = edge_end[ei]
                nbrs[a].append(b)
                nbrs[b].append(a)
        # start at any vertex with degree 2
        start = next(iter(nbrs))
        path = [start]
        prev = None
        cur = start
        while True:
            nxts = nbrs[cur]
            if len(nxts) != 2:
                return None
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            prev, cur = cur, nxt
            path.append(cur)
            if cur == start:
                break
            if len(path) > (E+5):
                return None
        return path

    sys.setrecursionlimit(10000)

    def dfs():
        if not propagate():
            return None
        if all(val != -1 for val in st):
            if all_clues_satisfied_and_single_loop():
                return extract_loop()
            return None
        # If already forms valid single loop that includes all clues, remaining unknown edges must be 0; force quickly
        if all_clues_satisfied_and_single_loop():
            tl = len(trail)
            ok = True
            for ei, val in enumerate(st):
                if val == -1:
                    if not set_edge(ei, 0):
                        ok = False
                        break
            if ok and propagate() and all_clues_satisfied_and_single_loop():
                res = extract_loop()
                if res:
                    return res
            undo(tl)
        ei = pick_edge()
        if ei is None:
            return None
        tl = len(trail)
        # Branch order: try IN then OUT, but avoid violating immediate degree >2 etc.
        for val in (1, 0):
            undo(tl)
            if set_edge(ei, val):
                res = dfs()
                if res is not None:
                    return res
        undo(tl)
        return None

    loop = dfs()
    if not loop:
        return "No Solution"
    return str(loop)

if __name__ == "__main__":
    print(solve(OBSERVATION))
